import numpy as np
import cv2
import math

# ---------------------------------------------------------------
#  ACES TRANSFORM HELPERS
# ---------------------------------------------------------------


class ACESHelpers:
    """
    Mathematical helpers for the ACES color pipeline.
    No LUTs, no external dependencies — pure formulas.
    """

    def __init__(self):
        # Standard coefficients for sRGB → Linear
        self.gamma = 2.4
        self.alpha = 0.055
        self.linear_threshold = 0.04045

    def srgb_to_linear(self, img):
        """
        Converts 8-bit sRGB to linear light representation.
        """
        img_f = img.astype(np.float32) / 255.0
        low = img_f <= self.linear_threshold
        high = ~low

        out = np.zeros_like(img_f)
        out[low] = img_f[low] / 12.92
        out[high] = ((img_f[high] + self.alpha) / (1 + self.alpha)) ** self.gamma
        return out

    def linear_to_srgb(self, img_linear):
        """
        Converts linear to display-space sRGB.
        """
        img = np.zeros_like(img_linear)
        low = img_linear <= 0.0031308
        high = ~low

        img[low] = img_linear[low] * 12.92
        img[high] = (1 + self.alpha) * (img_linear[high] ** (1 / self.gamma)) - self.alpha

        return np.clip(img * 255, 0, 255).astype(np.uint8)

# ---------------------------------------------------------------
#  ACES RRT + ODT FILMIC TONE MAPPER
# ---------------------------------------------------------------

class ACESToneCurve:
    """
    Implements an approximation of the ACES RRT+ODT filmic curve.
    Based on the Narkowicz rational polynomial.
    """

    def __init__(self):
        # Filmic constants defined by ACES approximation
        self.a = 2.51
        self.b = 0.03
        self.c = 2.43
        self.d = 0.59
        self.e = 0.14

    def filmic(self, x):
        """
        Applies ACES filmic curve to a linear light buffer.
        x must be in 0–1 linear range.
        """
        return (x * (self.a * x + self.b)) / (x * (self.c * x + self.d) + self.e)

# ---------------------------------------------------------------
#  ROLLING SHOULDER + TOE (Highlight Rolloff + Shadows)
# ---------------------------------------------------------------

class HighlightShadowRolloff:
    """
    Applies soft-knee highlight compression AND soft toe expansion.
    """

    def __init__(self, highlight_knee=0.8, toe_strength=0.15):
        self.knee = highlight_knee
        self.toe_s = toe_strength

    def apply_highlight_rolloff(self, x):
        """
        Soft-knee highlight rolloff.
        """
        mask = x > self.knee
        out = np.copy(x)
        out[mask] = self.knee + (np.log((x[mask] - self.knee) + 1) * 0.25)
        return np.clip(out, 0, 1)

    def apply_shadow_toe(self, x):
        """
        Softens shadows → prevents crushed blacks.
        """
        out = x + (x ** 2) * self.toe_s
        return np.clip(out, 0, 1)

# ---------------------------------------------------------------
#  MODE SWITCHER (ACES / REC709 / TEAL ORANGE)
# ---------------------------------------------------------------

class GlobalToneCurveEngine:
    """
    Unified switchable tone curve engine.
    MODES:
       • "ACES"          → True cinema
       • "REC709"        → Standard video curve
       • "TEAL_ORANGE"   → Stylized
    """

    def __init__(self, mode="ACES"):
        self.mode = mode
        self.ac = ACESHelpers()
        self.film = ACESToneCurve()
        self.roll = HighlightShadowRolloff()

        # Placeholder for expansion in next chunks
        self.curve_lut = None  # Future LUT export

# ---------------------------------------------------------------
#  MAIN APPLY FUNCTION
# ---------------------------------------------------------------

    def apply(self, frame):
        """
        MAIN ENTRY:
        Converts frame → linear → tone curve → output mode.
        """
        if frame is None:
            return None

        # 1. Convert to linear light
        lin = self.ac.srgb_to_linear(frame)

          # 2. Apply Rolloff + Toe before main curve
        lin = self.roll.apply_shadow_toe(lin)
        lin = self.roll.apply_highlight_rolloff(lin)

        # 3. Apply Selected Tone Curve
        if self.mode == "ACES":
            mapped = self.film.filmic(lin)

        elif self.mode == "REC709":
            # Simple gamma + contrast boost
            mapped = np.power(lin, 1/2.2)

        elif self.mode == "TEAL_ORANGE":
            mapped = self.film.filmic(lin)
            mapped = self._apply_teal_orange(mapped)

        else:
            mapped = lin

        # 4. Convert back to sRGB
        out = self.ac.linear_to_srgb(mapped)
        return out

# ---------------------------------------------------------------
#  TEAL-ORANGE OPERATOR (Stylized)
# ---------------------------------------------------------------

    def _apply_teal_orange(self, x):
        """
        Pushes shadows → teal, highlights → orange.
        """
        b, g, r = cv2.split(x)

        # luminance
        lum = 0.2126*r + 0.7152*g + 0.0722*b

        # Shadows → teal
        shadow_mask = 1.0 - lum
        b += shadow_mask * 0.05
        g += shadow_mask * 0.02

        # Highlights → orange
        r += lum * 0.05
        g += lum * 0.02

        out = cv2.merge((b, g, r))
        return np.clip(out, 0, 1)
# ---------------------------------------------------------------
#  3D LUT + 1D LUT EXPORT SYSTEM
# ---------------------------------------------------------------

class LUTExporter:
    """
    Exports the tone curve into:
        • 1D LUT  (for DaVinci Resolve curves)
        • 3D LUT  (33×33×33 Cube LUT for Premiere / Resolve / FCPX)
    This allows your pipeline to match commercial-grade color software.
    """

    def __init__(self, resolution_1d=1024, resolution_3d=33):
        self.res_1d = resolution_1d
        self.res_3d = resolution_3d

    # -----------------------------------------------------------
    #  Generate 1D LUT (Good for Contrast / Tone Curves Only)
    # -----------------------------------------------------------
    def generate_1d_lut(self, tone_engine):
        """
        Creates a 1D LUT using the selected tone curve engine.
        Input: tone_engine.apply() must accept a grayscale image
        Output: numpy array shape (res_1d, 3)
        """
        lut = np.zeros((self.res_1d, 3), dtype=np.uint16)

        for i in range(self.res_1d):
            # Input normalized sample
            x = i / (self.res_1d - 1)

            # Build grayscale input image (dummy frame)
            sample = np.array([[x * 255]], dtype=np.uint8)
            sample_bgr = cv2.cvtColor(sample, cv2.COLOR_GRAY2BGR)

            # Apply tone curve to this sample
            out = tone_engine.apply(sample_bgr)

            # Store result (Resolve expects 0–65535)
            lut[i] = (out[0,0] / 255.0 * 65535).astype(np.uint16)

        return lut

    # -----------------------------------------------------------
    #  Generate 3D LUT (Full Color Transform)
    # -----------------------------------------------------------
    def generate_3d_lut(self, tone_engine):
        """
        Generates a standard 33×33×33 .cube-format LUT.
        Commercial color grading workflows use this.

        WARNING:
            This computation is heavy: 33^3 = 35,937 samples.
            But it's necessary for true cinema quality.
        """

        N = self.res_3d
        lut = np.zeros((N, N, N, 3), dtype=np.float32)

        for r in range(N):
            for g in range(N):
                for b in range(N):

                    # Normalize sample
                    rn = r / (N - 1)
                    gn = g / (N - 1)
                    bn = b / (N - 1)

                    sample = np.array(
        [[[bn * 255, gn * 255, rn * 255]]],
        dtype=np.uint8
                    )

                    # Pass through tone curve pipeline
                    out = tone_engine.apply(sample)

                    # Normalize back to 0–1
                    lut[r, g, b] = out[0,0] / 255.0

        return lut

    # -----------------------------------------------------------
    #  Export LUT to .cube file (DaVinci Resolve / Premiere)
    # -----------------------------------------------------------
    def save_cube(self, path, lut):
        """
        Saves 3D LUT in CUBE format.
        """
        N = lut.shape[0]
        with open(path, "w") as f:
            f.write("# Generated by AI ToneCurveEngine\n")
            f.write("LUT_3D_SIZE {}\n".format(N))
            f.write("DOMAIN_MIN 0.0 0.0 0.0\n")
            f.write("DOMAIN_MAX 1.0 1.0 1.0\n")

            # Write LUT data
            for r in range(N):
                for g in range(N):
                    for b in range(N):
                        R, G, B = lut[r, g, b]
                        f.write(f"{R:.6f} {G:.6f} {B:.6f}\n")

        return True

    # -----------------------------------------------------------
    #  Export 1D LUT as .csv (Resolve Curve Import)
    # -----------------------------------------------------------
    def save_1d_csv(self, path, lut1d):
        """
        Saves 1D LUT as CSV for debugging / tools / external apps.
        """
        with open(path, "w") as f:
            f.write("R,G,B\n")
            for i in range(lut1d.shape[0]):
                R, G, B = lut1d[i]
                f.write(f"{R},{G},{B}\n")

        return True

# ---------------------------------------------------------------
#  LUT INTEGRATION WITH ToneCurveEngine
# ---------------------------------------------------------------

class ToneCurveWithLUT(GlobalToneCurveEngine):
    """
    Extends tone curve engine with LUT export abilities.
    """
    def __init__(self, mode="ACES"):
        super().__init__(mode)
        self.lut_exporter = LUTExporter()

    def export_luts(self, base_path):
        """
        Generates:
          • base_path + ".cube"   (3D LUT)
          • base_path + "_1d.csv" (1D LUT)
        """
        print("Generating 1D LUT…")
        lut1d = self.lut_exporter.generate_1d_lut(self)
        self.lut_exporter.save_1d_csv(base_path + "_1d.csv", lut1d)

        print("Generating 3D LUT…")
        lut3d = self.lut_exporter.generate_3d_lut(self)
        self.lut_exporter.save_cube(base_path + ".cube", lut3d)

        return {
            "1d_lut": base_path + "_1d.csv",
            "3d_lut": base_path + ".cube",
            "status": "OK"
        }
# ---------------------------------------------------------------
#  CHUNK 3 — SCENE-ADAPTIVE TONE CURVE BUILDER
#  Creates a dynamic tone curve based on the scene analysis.
#  This is “cinema-level” tone mapping: not static, fully adaptive.
# ---------------------------------------------------------------

class SceneAdaptiveCurveBuilder:
    """
    Builds a real-time adaptive tone curve based on scene metrics.
    Inputs:
        - shadow_ratio
        - highlight_ratio
        - scene_key (from SceneAnalyzerUltra)
    Output:
        - full 256-value tone curve LUT
    """

    def __init__(self):
        # Smooth the tone curve to prevent flickering
        self.prev_curve = None
        self.alpha = 0.10  # temporal smoothing factor

    # -----------------------------------------------------------
    def _build_shadow_toe(self, x, shadow_ratio):
        """
        More shadows = softer toe.
        Less shadows = stronger contrast.
        """
        toe_strength = 1.5 + shadow_ratio * 2.0
        return np.power(x, toe_strength)

    # -----------------------------------------------------------
    def _build_highlight_shoulder(self, x, highlight_ratio):
        """
        High highlight ratio → more compression.
        Scenes like snow/sun require aggressive shoulder.
        """
        shoulder_strength = 1.0 + (highlight_ratio * 3.0)
        compressed = 1.0 - np.exp(-(x * shoulder_strength))
        return compressed

    # -----------------------------------------------------------
    def _apply_scene_key_shift(self, curve, scene_key):
        """
        Adjusts curve based on scene key:
            dark scenes → lift entire curve
            bright scenes → push curve down
        """
        # scene_key: 0→dark, 1→bright
        offset = (scene_key - 0.5) * 0.20
        return np.clip(curve + offset, 0.0, 1.0)

    # -----------------------------------------------------------
    def build_curve(self, scene_data):
        """
        Main function to build the dynamic adaptive curve.
        scene_data contains:
            - total_clipping
            - scene_key
            - r_clip / g_clip / b_clip
        """
        scene_key = scene_data["scene_key"]
        highlight_ratio = scene_data["total_clipping"]
        shadow_ratio = min(1.0 - scene_key, 1.0)  # approx inverse of scene key

        # Step 1: X input samples
        x = np.linspace(0, 1, 256)

        # Step 2: Build toe + shoulder structure
        toe = self._build_shadow_toe(x, shadow_ratio)
        shoulder = self._build_highlight_shoulder(toe, highlight_ratio)

        # Step 3: Apply scene-key shift
        adaptive = self._apply_scene_key_shift(shoulder, scene_key)

        # Step 4: Apply smoothing
        if self.prev_curve is None:
            smoothed = adaptive
        else:
            smoothed = (self.prev_curve * (1 - self.alpha)) + (adaptive * self.alpha)

        self.prev_curve = smoothed

        # Step 5: Convert to LUT (0–255)
        lut = (smoothed * 255).astype(np.uint8)
        return lut

# ---------------------------------------------------------------
#  INTEGRATION WRAPPER
# ---------------------------------------------------------------

class ToneCurveAdaptiveEngine(GlobalToneCurveEngine):
    """
    Extends tone curve engine with real-time adaptive behavior.
    """
    def __init__(self, mode="ACES"):
        super().__init__(mode)
        self.curve_builder = SceneAdaptiveCurveBuilder()

    def apply_adaptive(self, frame, scene_data):
        """
        Builds a dynamic curve and applies it to the frame.
        """
        lut = self.curve_builder.build_curve(scene_data)
        return cv2.LUT(frame, lut)

    def export_current_curve(self):
        """
        Exports last curve for debugging/UI plot.
        """
        if self.curve_builder.prev_curve is None:
            return None
        curve = (self.curve_builder.prev_curve * 255).astype(np.uint8)
        return curve.tolist()

