import cv2
import numpy as np

class MultiResTonePyramid:
    """
    Performs advanced HDR multi-band tone mapping:
        • Gaussian Pyramid Downsampling
        • Laplacian Pyramid Difference Layers
        • Adaptive curve shaping on global band (L0)
        • Controlled reconstruction with frequency weighting
    """
    def __init__(self):
        # Blend weights (tuned for cinematic balance)
        self.weight_L0 = 0.65   # global exposure + HDR rolloff
        self.weight_L1 = 0.25   # midtone separation
        self.weight_L2 = 0.10   # high-frequency detail pop

        # Temporal smoothing for global tone (prevents flicker)
        self.prev_L0 = None
        self.alpha_L0 = 0.08

    # ---------------------------------------------------------------
    def _downsample(self, frame):
        """Returns Gaussian pyramid levels."""
        L0 = cv2.pyrDown(frame)
        L1 = cv2.pyrDown(L0)
        return L0, L1

    # ---------------------------------------------------------------
    def _upsample_to(self, level, target_shape):
        """Resizes pyramid level to match given shape."""
        return cv2.resize(level, (target_shape[1], target_shape[0]),
        interpolation=cv2.INTER_LINEAR)

    # ---------------------------------------------------------------
    def _laplacian(self, frame, lower_level):
        """Computes Laplacian band (detail layer)."""
        up = self._upsample_to(lower_level, frame.shape)
        lap = frame.astype(np.float32) - up.astype(np.float32)
        return lap

    # ---------------------------------------------------------------
    def decompose(self, frame):
        """
        Produces:
            L0 — global tone level
            L1 — midtone pyramid level
            L1_detail — mid-frequency details
            L2_detail — high-frequency Laplacian details
        """
        h, w = frame.shape[:2]

        # 1. Downsample
        L0, L1 = self._downsample(frame)

        # 2. Laplacians
        L0_up = self._upsample_to(L0, (h, w))
        L1_up = self._upsample_to(L1, L0.shape[:2])

        L2_detail = frame.astype(np.float32) - L0_up.astype(np.float32)
        L1_detail = L0.astype(np.float32) - L1_up.astype(np.float32)

        return {
            "L0": L0,
            "L1": L1,
            "L1_detail": L1_detail,
            "L2_detail": L2_detail
        }

    # ---------------------------------------------------------------
    def apply_global_curve(self, L0, curve_engine, scene_data):
        """
        Applies tone curve ONLY on L0 (global exposure & rolloff).
        This prevents noise amplification & flicker.
        """
        toned = curve_engine.apply_adaptive(L0, scene_data)

        # Temporal smoothing prevents flicker between frames
        if self.prev_L0 is None:
            out = toned
        else:
            out = (self.prev_L0 * (1 - self.alpha_L0) +
                   toned.astype(np.float32) * self.alpha_L0).astype(np.uint8)

        self.prev_L0 = out
        return out

    # ---------------------------------------------------------------
    def reconstruct(self, L0_proc, L1, L1_detail, L2_detail):
        """Reconstructs final HDR frame from all pyramid bands."""
        h1, w1 = L1.shape[:2]

        # Upsample processed L0 → L1 size
        L0_up1 = cv2.resize(L0_proc, (w1, h1), interpolation=cv2.INTER_LINEAR)

        # Combine L1 and processed L0
        mid = (L1.astype(np.float32) * 0.7 +
               L0_up1.astype(np.float32) * 0.3)

        # Upsample to original resolution
        h2, w2 = L1_detail.shape[:2]
        mid_up = cv2.resize(mid, (w2, h2), interpolation=cv2.INTER_LINEAR)

        # Weighted reconstruction
        final = (
            mid_up * self.weight_L1 +
            L2_detail * self.weight_L2 +
            cv2.resize(L0_proc, (w2, h2), interpolation=cv2.INTER_LINEAR) * self.weight_L0
        )

        final = np.clip(final, 0, 255).astype(np.uint8)
        return final

    # ---------------------------------------------------------------
    def process(self, frame, curve_engine, scene_data):
        """
        1) Multi-resolution decomposition  
        2) Tone-mapping on L0  
        3) Frequency reconstruction  
        """
        pyr = self.decompose(frame)

        L0_proc = self.apply_global_curve(
            pyr["L0"],
            curve_engine,
            scene_data
        )

        final = self.reconstruct(
            L0_proc,
            pyr["L1"],
            pyr["L1_detail"],
            pyr["L2_detail"]
        )

        return final

# ---------------------------------------------------------------
#  EXTRA UTILITY: PRECISE LUMINANCE MAP (for debugging)
# ---------------------------------------------------------------
def compute_luminance_map(frame):
    """Returns normalized luminance used to visualize tone decisions."""
    y = (0.2126 * frame[...,2] +
         0.7152 * frame[...,1] +
         0.0722 * frame[...,0])
    y_norm = y / 255.0
    return np.clip(y_norm, 0, 1)

# ---------------------------------------------------------------
#  EXTRA UTILITY: PYRAMID VISUALIZER
# ---------------------------------------------------------------
def visualize_pyramid(pyr_dict):
    """Debug helper: displays each pyramid band in one composite image."""
    L0 = cv2.resize(pyr_dict["L0"], (320, 180))
    L1 = cv2.resize(pyr_dict["L1"], (320, 180))
    L1d = cv2.resize(np.abs(pyr_dict["L1_detail"]).astype(np.uint8), (320,180))
    L2d = cv2.resize(np.abs(pyr_dict["L2_detail"]).astype(np.uint8), (320,180))
    
    top = np.hstack([L0, L1])
    bottom = np.hstack([L1d, L2d])
    return np.vstack([top, bottom])

