import numpy as np
import cv2
import math
from collections import deque
from typing import Optional, Tuple

# ---------------------------------------------------------------
# ROLLING SHUTTER CORRECTOR (IMU-assisted per-row warp)
# ---------------------------------------------------------------
class RollingShutterCorrector:
    """
    Simple per-row corrective warp using IMU gyroscope yaw/roll rates.
    NOTE: This is a lightweight approximation (suitable for preview/soft realtime).
    For production you must replace with sensor-timed exposures & exact timestamps.
    """
    def __init__(self, max_correction_pixels=60):
        self.max_pixels = max_correction_pixels

    def correct(self, frame: np.ndarray, gyro_rates: Tuple[float,float,float], exposure_time_s: float):
        """
        Args:
            frame: HxWx3 uint8 or float image (0..1)
            gyro_rates: (gx, gy, gz) in rad/s (device frame)
            exposure_time_s: total frame exposure duration (s)
        Returns:
            corrected_frame (same dtype as input)
        """
        if frame is None:
            return None
        h, w = frame.shape[:2]

        # if float range 0..1 convert to float image for remap
        float_input = (frame.astype(np.float32) / 255.0) if frame.dtype == np.uint8 else frame.astype(np.float32)

        # Estimate per-row angular displacement assuming readout from top->bottom
        # row_time = exposure_time_s / h
        row_time = exposure_time_s / max(1.0, float(h))
        # We use yaw (gz) primarily for horizontal smear and roll for vertical tilt
        gx, gy, gz = gyro_rates
        # per-row pixel shift (approx)
        px_per_rad = max(1.0, w / (2.0 * math.pi))  # rough mapping
        row_shifts = (gz * np.arange(h) * row_time) * px_per_rad
        # clamp
        row_shifts = np.clip(row_shifts, -self.max_pixels, self.max_pixels).astype(np.float32)

        # Build remap arrays
        grid_x, grid_y = np.meshgrid(np.arange(w, dtype=np.float32), np.arange(h, dtype=np.float32))
        map_x = grid_x - row_shifts[:, None]  # shift each row horizontally
        map_y = grid_y

        corrected = cv2.remap(float_input, map_x, map_y, interpolation=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REFLECT)
        if frame.dtype == np.uint8:
            return np.clip(corrected * 255.0, 0, 255).astype(np.uint8)
        return corrected

# ---------------------------------------------------------------
# LENS CORRECTION ENGINE (distortion + vignette + chromatic aberration)
# ---------------------------------------------------------------
class LensCorrectionEngine:
    """
    Uses precomputed calibration parameters to undistort + correct vignetting.
    Accepts per-camera calibration dicts: { 'K': ..., 'D': ..., 'vignette_map': ... }
    """
    def __init__(self, calib: Optional[dict] = None):
        # calib: { 'K': numpy(3,3), 'D': (k1,k2,p1,p2,k3), 'vmap': numpy(H,W) float(0..1) }
        self.calib = calib or {}
    def undistort(self, frame):
        if frame is None:
            return None
        if not self.calib or 'K' not in self.calib:
            return frame
        h, w = frame.shape[:2]
        K = self.calib['K']
        D = np.array(self.calib.get('D', [0,0,0,0,0]))
        # OpenCV fisheye or standard distortion depending on values
        try:
            newK, _ = cv2.getOptimalNewCameraMatrix(K, D, (w, h), 0)
            und = cv2.undistort(frame, K, D, None, newK)
            return und
        except Exception:
            # fallback minimal radial undistortion
            return frame

    def apply_vignette(self, frame):
        if frame is None:
            return None
        if 'vmap' not in self.calib:
            return frame
        vmap = cv2.resize(self.calib['vmap'], (frame.shape[1], frame.shape[0]))
        vmap = vmap.astype(np.float32)
        out = frame.astype(np.float32) * (1.0 / (vmap + 1e-6))  # invert falloff
        return np.clip(out, 0, 255).astype(frame.dtype)

    def chromatic_aberration_fix(self, frame):
        """
        Simple chromatic aberration correction by per-channel radial scaling.
        Calibration should provide r_scale per channel.
        """
        if frame is None:
            return None
        params = self.calib.get('ca', None)
        if not params:
            return frame
        h, w = frame.shape[:2]
        cx, cy = w/2, h/2
        # per-channel scale
        rscale = params.get('r', 1.0)
        gscale = params.get('g', 1.0)
        bscale = params.get('b', 1.0)
        # warp channels slightly outward/inward
        def remap_channel(ch, scale):
            grid_x, grid_y = np.meshgrid(np.arange(w,dtype=np.float32), np.arange(h,dtype=np.float32))
            dx = (grid_x - cx) * (scale - 1.0)
            dy = (grid_y - cy) * (scale - 1.0)
            map_x = grid_x + dx
            map_y = grid_y + dy
            return cv2.remap(ch, map_x, map_y, interpolation=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REFLECT)
        b, g, r = cv2.split(frame)
        b2 = remap_channel(b, bscale)
        g2 = remap_channel(g, gscale)
        r2 = remap_channel(r, rscale)
        return cv2.merge([b2, g2, r2]).astype(frame.dtype)

# ---------------------------------------------------------------
# TEMPORAL NOISE MODEL + MOTION-AWARE DENOISER
# ---------------------------------------------------------------
class TemporalNoiseModel:
    """
    Builds a simple noise profile as function of ISO and temperature,
    and performs motion-aware temporal denoising using accumulation when motion is low.
    """
    def __init__(self, max_history=5):
        self.history = deque(maxlen=max_history)
        self.motion_history = deque(maxlen=max_history)
    def predict_noise_strength(self, iso):
        # simplified noise model: noise ~ a*log2(iso/100) + b
        iso = max(100.0, float(iso))
        return 0.02 * math.log2(iso / 100.0 + 1.0) + 0.005
    def register_frame(self, frame, motion_mag):
        # store recent frames for temporal filtering
        self.history.append(frame.astype(np.float32) / 255.0)
        self.motion_history.append(motion_mag)
    def motion_weight(self):
        # if avg motion low -> higher temporal blend
        mavg = float(np.mean(self.motion_history)) if self.motion_history else 0.0
        # map motion 0..20 px -> weight 0.9..0.1
        w = np.clip(1.0 - (mavg / 20.0), 0.1, 0.9)
        return w
    def denoise(self, current_frame, iso=100):
        """
        Blend previous frames into current_frame based on motion weight and predicted noise.
        """
        if current_frame is None:
            return None
        if len(self.history) < 2:
            return current_frame
        curr = current_frame.astype(np.float32) / 255.0
        noise_strength = self.predict_noise_strength(iso)
        w = self.motion_weight()
        # Weighted temporal accumulation with exposure-aware soft clamp
        accum = curr * 0.0
        total_w = 0.0
        decay = 0.8
        for i, f in enumerate(reversed(self.history)):
            weight = (decay ** i) * (w * (1.0 - noise_strength) + (noise_strength * 0.2))
            accum += f * weight
            total_w += weight

        accum = accum / max(1e-6, total_w)
        # spatial refine using bilateral filter to protect edges
        accum_sp = cv2.bilateralFilter((accum*255.0).astype(np.uint8), d=5, sigmaColor=25, sigmaSpace=7)
        out = cv2.addWeighted((curr*255.0).astype(np.uint8), 0.4, accum_sp, 0.6, 0)
        return out

# ---------------------------------------------------------------
# TEMPORAL COLOR CONSISTENCY (flicker suppression)
# ---------------------------------------------------------------
class TemporalColorConsistency:
    """
    Tracks per-channel histograms across frames and constrains
    per-frame color corrections to avoid temporal jumps.
    """
    def __init__(self, hist_bins=64):
        self.prev_mean = None
        self.alpha = 0.1
    def measure_stats(self, frame):
        if frame is None:
            return None
        # compute per-channel mean in linear space
        f = frame.astype(np.float32) / 255.0
        mean = f.reshape(-1,3).mean(axis=0)
        return mean

    def stabilize(self, frame):
        if frame is None:
            return None
        mean = self.measure_stats(frame)
        if self.prev_mean is None:
            self.prev_mean = mean
            return frame
        # Smooth means
        smoothed = (self.prev_mean * (1 - self.alpha)) + (mean * self.alpha)
        # Compute per-channel gain to nudge means toward smoothed
        gain = (smoothed + 1e-6) / (mean + 1e-6)
        out = frame.astype(np.float32) * gain.reshape(1,1,3)
        self.prev_mean = smoothed
        return np.clip(out, 0, 255).astype(frame.dtype)

# ---------------------------------------------------------------
# MULTI-RES EXPOSURE FUSION HELPER
# ---------------------------------------------------------------
class MultiResExposureFusion:
    """
    Simple HDR fusion across exposure brackets using multi-res weighting.
    Expects bracketed images aligned (or minimal parallax).
    """
    def __init__(self):
        pass
    def fuse_brackets(self, images: list):
        """
        images: list of np.ndarray (same size)
        Returns: fused image
        """
        if not images:
            return None
        # convert to float
        imgs_f = [ (im.astype(np.float32) / 255.0) for im in images ]
        # compute per-pixel weights: well-exposedness + saturation + contrast
        weights = []
        for im in imgs_f:
            gray = cv2.cvtColor((im*255).astype(np.uint8), cv2.COLOR_BGR2GRAY).astype(np.float32)/255.0
            # well exposedness (peak near 0.5)
            we = np.exp(-4.0 * (gray - 0.5)**2)
            sat = np.mean(np.std(im, axis=2), keepdims=False) + 1e-6
            weights.append(we + 0.001)
        weight_sum = np.sum(weights, axis=0) + 1e-9
        fused = np.zeros_like(imgs_f[0])
        for im, w in zip(imgs_f, weights):
            fused += im * (w[...,None] / weight_sum[...,None])
        return np.clip((fused*255.0).astype(np.uint8), 0, 255)
# ---------------------------------------------------------------
# INTEGRATION HOOKS: Add helpers to UltraACES via monkey-patch functions
# (so we avoid breaking earlier definitions while extending)
# ---------------------------------------------------------------
def extend_ultra_aces_with_advanced(ultra_obj):
    """Attach instances for the advanced modules to an UltraACES object."""
    ultra_obj.rolling_shutter = RollingShutterCorrector()
    ultra_obj.lens = LensCorrectionEngine()
    ultra_obj.temp_noise = TemporalNoiseModel()
    ultra_obj.temp_color = TemporalColorConsistency()
    ultra_obj.multi_fuse = MultiResExposureFusion()
    return ultra_obj

