import numpy as np
import cv2
import math
from collections import deque

# ---------------------------------------------------------------
# GPU HELPER (OpenCV CUDA auto-detection)
# ---------------------------------------------------------------
class GPUAccelerator:
    """
    Provides fallback-safe CUDA acceleration for:
        - Gaussian blur
        - Resize
        - Bilateral filtering
        - Optical flow
    """
    def __init__(self):
        self.enabled = cv2.cuda.getCudaEnabledDeviceCount() > 0

    def to_gpu(self, frame):
        if not self.enabled:
            return None
        return cv2.cuda_GpuMat().upload(frame)

    def gaussian(self, frame, sigma):
        if not self.enabled:
            return cv2.GaussianBlur(frame, (0,0), sigma)
        gpu = self.to_gpu(frame)
        if gpu is None:
            return frame
        gpu_blur = cv2.cuda.createGaussianFilter(
            gpu.type(), gpu.type(), (0,0), sigma
        )
        out = gpu_blur.apply(gpu)
        return out.download()

    def bilateral(self, frame, d=5, sc=35, ss=10):
        if not self.enabled:
            return cv2.bilateralFilter(frame, d, sc, ss)
        gpu = self.to_gpu(frame)
        bf = cv2.cuda.createBilateralFilter(gpu.type(), d, sc, ss)
        out = bf.apply(gpu)
        return out.download()

    def resize(self, frame, shape):
        if not self.enabled:
            return cv2.resize(frame, shape, interpolation=cv2.INTER_LINEAR)
        gpu = self.to_gpu(frame)
        out = cv2.cuda.resize(gpu, shape)
        return out.download()

    def optic_flow(self, prev_gray, curr_gray):
        """
        Computes motion vectors using Farneback (CPU fallback).
        """
        if not self.enabled:
            return cv2.calcOpticalFlowFarneback(
                prev_gray, curr_gray, None,
                0.5, 3, 15, 3, 5, 1.2, 0
            )
        # GPU Farneback
        gpu_prev = self.to_gpu(prev_gray)
        gpu_curr = self.to_gpu(curr_gray)
        f = cv2.cuda_FarnebackOpticalFlow.create(
            5, 0.5, False, 15, 5, 1.1, 10, 1, 0
        )
        gpu_flow = f.calc(gpu_prev, gpu_curr)
        return gpu_flow.download()

# ---------------------------------------------------------------
# TEMPORAL STABILIZER 2.0 (ACES-style exposure impulse damper)
# ---------------------------------------------------------------
class ACESExposureStabilizer:
    """
    Prevents exposure flicker caused by:
        - auto-exposure
        - inconsistent camera logs
        - HDR merge instability
    Works by analyzing per-frame mid-gray response.
    """
    def __init__(self):
        self.prev_ev = None
        self.alpha = 0.15  # smoothing

    def measure_ev(self, frame):
        """
        Computes log-average luminance (standard ACES metric).
        """
        f = frame.astype(np.float32) / 255.0
        y = (0.2126*f[...,2] + 0.7152*f[...,1] + 0.0722*f[...,0]) + 1e-6
        log_avg = np.exp(np.mean(np.log(y)))
        return math.log2(max(1e-6, log_avg))

    def stabilize(self, frame):
        curr = self.measure_ev(frame)
        if self.prev_ev is None:
            self.prev_ev = curr
            return frame
        smoothed = (self.prev_ev * (1 - self.alpha)) + (curr * self.alpha)
        delta = smoothed - curr
        gain = 2.0 ** delta
        out = np.clip(frame.astype(np.float32) * gain, 0, 255).astype(np.uint8)
        self.prev_ev = smoothed
        return out

# ---------------------------------------------------------------
# FILMIC HALATION ENGINE (physically-inspired diffusion)
# ---------------------------------------------------------------
class HalationEngine:
    """
    Adds cinematic halation:
        • highlight bleed
        • red-channel diffusion
        • physically-motivated scattering falloff
    """
    def __init__(self, radius=22, strength=0.18):
        self.radius = radius
        self.strength = strength

    def compute_mask(self, frame):
        """
        Extract highlight mask for halation:
        uses HSV V channel.
        """
        hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
        v = hsv[...,2].astype(np.float32) / 255.0
        mask = np.clip((v - 0.75) * 4.0, 0, 1)  # threshold around bright areas
        return mask

    def apply(self, frame):
        mask = self.compute_mask(frame)
        blur = cv2.GaussianBlur(frame, (0,0), self.radius)
        hal = frame.astype(np.float32) + (blur.astype(np.float32) - frame.astype(np.float32)) * (mask[...,None] * self.strength)
        return np.clip(hal, 0, 255).astype(np.uint8)

# ---------------------------------------------------------------
# BLOOM ENGINE (cinematic highlight glow)
# ---------------------------------------------------------------
class BloomEngine:
    """
    Multi-stage bloom:
        1. threshold
        2. multi-scale Gaussian
        3. weighted addition
    """
    def __init__(self, threshold=0.85, strength=0.25):
        self.thr = threshold
        self.strength = strength

    def extract(self, frame):
        f = frame.astype(np.float32) / 255.0
        lum = (0.2126*f[...,2] + 0.7152*f[...,1] + 0.0722*f[...,0])
        mask = np.clip((lum - self.thr) * 8.0, 0, 1)
        return (f * mask[...,None]) * 255.0

    def apply(self, frame):
        highlights = self.extract(frame).astype(np.uint8)
        blur1 = cv2.GaussianBlur(highlights, (0,0), 4)
        blur2 = cv2.GaussianBlur(highlights, (0,0), 12)
        blur3 = cv2.GaussianBlur(highlights, (0,0), 24)
        out = frame.astype(np.float32) + (
            blur1 * 0.6 + blur2 * 0.3 + blur3 * 0.1
        ) * self.strength
        return np.clip(out, 0, 255).astype(np.uint8)

# ---------------------------------------------------------------
# FILM GRAIN ENGINE (motion-aware grain injection)
# ---------------------------------------------------------------
class FilmGrainEngine:
    """
    Adds filmic grain that:
        • scales with luminance
        • reduces in high-motion regions
    """
    def __init__(self, strength=0.04):
        self.strength = strength

    def apply(self, frame, motion_mag=0.0):
        f = frame.astype(np.float32) / 255.0
        h, w = frame.shape[:2]
        grain = np.random.normal(0, 1, (h,w))
        # motion reduces grain
        mot_scale = max(0.2, 1.0 - motion_mag / 20.0)
        lum = (0.2126*f[...,2] + 0.7152*f[...,1] + 0.0722*f[...,0])
        lum = np.clip(lum, 0, 1)
        g = grain * (lum * self.strength * mot_scale)
        g3 = np.stack([g,g,g], axis=2)
        out = f + g3
        return np.clip(out * 255.0, 0, 255).astype(np.uint8)

# ---------------------------------------------------------------
# EXR-SAFE HDR I/O HELPERS (float32 read/write)
# ---------------------------------------------------------------
class HDRIO:
    """
    Handles float HDR read/write using OpenEXR compatibility paths.
    """
    @staticmethod
    def load(path):
        img = cv2.imread(path, cv2.IMREAD_UNCHANGED)
        if img is None:
            return None
        return img.astype(np.float32)

    @staticmethod
    def save(path, img):
        if img.dtype != np.float32:
            img = img.astype(np.float32)
        cv2.imwrite(path, img)
        return True

# ---------------------------------------------------------------
