import numpy as np
import cv2
import math
import json
from typing import Optional, Dict, Any
# ---------------------------------------------------------------
# HDR / PQ Transfer Utilities (SMPTE ST 2084 approximation)
# ---------------------------------------------------------------
class PQTransfer:
    """
    Implementation of ST2084 (PQ) EOTF / inverse EOTF approximations.
    Supports mapping scene-linear light -> PQ-coded values and back.
    """
    def __init__(self, peak_nits: float = 1000.0):
        self.peak = float(peak_nits)
        # PQ constants
        self.m1 = 2610.0 / 4096.0 / 4.0
        self.m2 = 2523.0 / 4096.0 * 128.0
        self.c1 = 3424.0 / 4096.0
        self.c2 = 2413.0 / 4096.0 * 32.0
        self.c3 = 2392.0 / 4096.0 * 32.0
    def linear_to_pq(self, lin: np.ndarray) -> np.ndarray:
        """
        lin: linear scene light scaled such that 1.0 corresponds to `peak_nits` nits.
        returns: PQ-coded values 0..1
        """
        # Ensure numeric stability
        x = np.clip(lin, 0.0, None)
        xp = np.power(x, self.m1)
        num = self.c1 + self.c2 * xp
        den = 1.0 + self.c3 * xp
        pq = np.power(num / den, self.m2)
        return np.clip(pq, 0.0, 1.0)
    def pq_to_linear(self, pq: np.ndarray) -> np.ndarray:
        """
        Inverse PQ EOTF: PQ 0..1 -> linear light (1.0 == peak_nits).
        """
        y = np.clip(pq, 0.0, 1.0)
        y_m = np.power(y, 1.0 / self.m2)
        num = np.maximum(y_m - self.c1, 0.0)
        den = self.c2 - self.c3 * y_m
        lin = np.power(num / den, 1.0 / self.m1)
        return np.clip(lin, 0.0, None)
# ---------------------------------------------------------------
# Dolby-like Tone Mapper (approximate guidance — non-proprietary)
# ---------------------------------------------------------------
class DolbyishToneMapper:
    """
    High-level cinematic mapping that prepares ACES-scene-linear images
    for PQ playback: soft rolloff, highlight lift, color-preserving.
    """
    def __init__(self, peak_nits=1000.0):
        self.peak = peak_nits
        self.pq = PQTransfer(peak_nits=self.peak)
    def soft_rolloff(self, linear: np.ndarray, shoulder=0.95, toe=0.02) -> np.ndarray:
        """
        Smoothly compress highlights via a soft shoulder curve.
        """
        x = np.clip(linear, 0.0, None)
        # Normalize to 0..1 by relative peak
        x_rel = x / (self.peak if self.peak > 0 else 1.0)
        # Soft knee using smoothstep-like function
        knee = shoulder
        below = x_rel <= knee
        out = np.zeros_like(x_rel)
        out[below] = x_rel[below]
        above = ~below
        out[above] = knee + (1.0 - knee) * (1.0 - np.exp(-(x_rel[above] - knee) * 3.0))
        # Re-scale back to linear-nits domain
        return out * self.peak
    def apply(self, acescg_linear: np.ndarray) -> np.ndarray:
        """
        Input: ACEScg linear scene-referred RGB floats (0..inf)
        Output: PQ-coded RGB (0..1) ready to be ODT'd.
        """
        # 1) Luminance-preserving soft rolloff applied per-channel
        rolled = self.soft_rolloff(acescg_linear, shoulder=0.92)
        # 2) Slight highlight desaturation (preserve skin)
        luma = 0.2126 * rolled[..., 0] + 0.7152 * rolled[..., 1] + 0.0722 * rolled[..., 2]
        sat_drop = np.clip((luma - 0.7) * 1.5, 0.0, 1.0)[..., None]
        desat = rolled * (1.0 - (0.12 * sat_drop))
        # 3) Convert to PQ domain (per-channel)
        # Map linear scene light normalized by peak
        normalized = desat / max(self.peak, 1.0)
        pq_r = self.pq.linear_to_pq(normalized[..., 0])
        pq_g = self.pq.linear_to_pq(normalized[..., 1])
        pq_b = self.pq.linear_to_pq(normalized[..., 2])
        return np.stack([pq_r, pq_g, pq_b], axis=-1)
# ---------------------------------------------------------------
# Gamut Mapping & Clipping Utilities (Perceptual-safe)
# ---------------------------------------------------------------
class GamutMapper:
    """
    Implements simple but robust gamut compression with preserve-saturation option.
    """
    def __init__(self):
        # small epsilon to avoid divide by zero
        self.eps = 1e-6
    def clip_gamut_simple(self, img: np.ndarray) -> np.ndarray:
        """
        Simple clipping to [0,1] per channel.
        """
        return np.clip(img, 0.0, 1.0)
    def compress_saturation(self, img: np.ndarray, amount: float = 0.2) -> np.ndarray:
        """
        Reduces saturation non-linearly on bright pixels to avoid hue shifts.
        """
        luma = 0.2126 * img[..., 0] + 0.7152 * img[..., 1] + 0.0722 * img[..., 2]
        s = np.linalg.norm(img, axis=2)
        # compute scale per-pixel
        scale = 1.0 / (1.0 + (luma[..., None] * amount))
        return img * scale
# ---------------------------------------------------------------
# Surround Compensation (room lighting perception)
# ---------------------------------------------------------------
class SurroundCompensator:
    """
    Slightly tweaks tone mapping based on surround conditions:
    - 'Dark'  => cinema projector (boost shadows slightly)
    - 'Dim'   => living room (neutral)
    - 'Bright'=> showroom (pull down contrast)
    """
    def __init__(self, mode: str = "Dim"):
        self.mode = mode
    def apply(self, display_linear: np.ndarray) -> np.ndarray:
        if self.mode == "Dark":
            # gentle lift shadows
            lift = 1.02
            return np.clip(np.power(display_linear, 0.99) * lift, 0.0, 1.0)
        elif self.mode == "Bright":
            return np.clip(np.power(display_linear, 1.02), 0.0, 1.0)
        else:
            return display_linear
# ---------------------------------------------------------------
# Metadata Embedding Helper (XMP-like JSON sidecar)
# ---------------------------------------------------------------
class MetadataEmitter:
    """
    Writes a small JSON sidecar describing color pipeline settings
    suitable for later grading or forensic uses.
    """
    def __init__(self):
        self.data: Dict[str, Any] = {}
    def stamp(self, path: str, info: Dict[str, Any]):
        """
        Writes a .json file next to the output image.
        """
        try:
            meta_path = path + ".json"
            with open(meta_path, "w") as f:
                json.dump(info, f, indent=2)
            return meta_path
        except Exception as e:
            return None
# ---------------------------------------------------------------
# ULTRA OUTPUT ENGINE - integrates ODT + PQ + Gamut + Surround
# ---------------------------------------------------------------
class UltraOutputEngine:
    """
    High-level wrapper that finalizes ACES scene-linear content into display
    outputs (Rec709, P3, PQ/HDR10) and emits metadata.
    """
    def __init__(self, peak_nits: float = 1000.0, surround: str = "Dim"):
        self.peak = peak_nits
        self.dolby = DolbyishToneMapper(peak_nits=self.peak)
        self.gamut = GamutMapper()
        self.surround = SurroundCompensator(mode=surround)
        self.meta = MetadataEmitter()
    def to_rec709(self, acescg_linear: np.ndarray, out_path: Optional[str] = None) -> np.ndarray:
        """
        Convert ACEScg linear -> Rec709 8-bit output.
        """
        # 1. Tone-map with SSTS-like curve (reuse simple filmic curve)
        # A production deployment would call a full RRT+ODT; this is a pragmatic wrapper.
        tone = np.clip(acescg_linear, 0.0, None)
# ---------------------------------------------------------------
        # Convert to display-referred midtones (gamma 2.4)
        disp = np.power(tone, 1/2.4)
        # Clip out-of-gamut values
        disp = self.gamut.clip_gamut_simple(disp)
        # Surround compensation
        disp = self.surround.apply(disp)
        # Convert to 8-bit output
        out = (np.clip(disp, 0.0, 1.0) * 255).astype(np.uint8)
        # Save metadata if output path is given
        if out_path is not None:
            meta = {
                "odt": "Rec709",
                "peak_nits": None,
                "surround": self.surround.mode,
                "notes": "ACEScg → Rec709 tone-mapped output"
            }
            self.meta.stamp(out_path, meta)
        return out
    # ---------------------------------------------------------------
    # Output to P3-D65 (Cinema monitors)
    # ---------------------------------------------------------------
    def to_p3(self, acescg_linear: np.ndarray, out_path: Optional[str] = None) -> np.ndarray:
        """
        Converts ACEScg linear → P3-D65 (gamma 2.6 cinema standard).
        """
        tone = np.clip(acescg_linear, 0.0, None)
        # Mild desaturation for cinema projector simulation
        tone = self.gamut.compress_saturation(tone, amount=0.12)
        # Gamma encode for cinema (2.6)
        disp = np.power(tone, 1/2.6)
        disp = self.gamut.clip_gamut_simple(disp)
        disp = self.surround.apply(disp)
        out = (disp * 255).astype(np.uint8)
        if out_path is not None:
            meta = {
                "odt": "P3-D65",
                "gamma": 2.6,
                "surround": self.surround.mode,
                "description": "Cinema-style P3 output"
            }
            self.meta.stamp(out_path, meta)
        return out
    # ---------------------------------------------------------------
    # HDR10 Output Path (PQ, Rec2020 container)
    # ---------------------------------------------------------------
    def to_hdr10(self, acescg_linear: np.ndarray, out_path: Optional[str] = None) -> np.ndarray:
        """
        FULL HDR10 OUTPUT:
            1) Dolby-style tone shaping
            2) PQ encoding
            3) Clip & pack into 10/12-bit container
        """
        # Step 1: Dolby-style rolloff + desat
        pq_ready = self.dolby.apply(acescg_linear)
        # Step 2: Clip
        pq_ready = self.gamut.clip_gamut_simple(pq_ready)
        # Step 3: Encode into 10-bit HDR format
        hdr10 = (pq_ready * 1023).astype(np.uint16)  # 10-bit container
        if out_path is not None:
            meta = {
                "odt": "HDR10",
                "peak_nits": self.peak,
                "transfer": "PQ (ST2084)",
                "gamut": "Rec2020",
                "surround": self.surround.mode,
                "notes": "ACEScg → PQ HDR10 tone-map output"
            }
            self.meta.stamp(out_path, meta)
        return hdr10
    # ---------------------------------------------------------------
    # Unified Output Function
    # ---------------------------------------------------------------
    def export(self, acescg_linear: np.ndarray, mode: str, out_path: Optional[str] = None):
        """
        Unified wrapper:
            mode = "Rec709" | "P3" | "HDR10"
        """
        mode = mode.upper()
        if mode == "REC709":
            return self.to_rec709(acescg_linear, out_path)
        elif mode == "P3":
            return self.to_p3(acescg_linear, out_path)
        elif mode == "HDR10":
            return self.to_hdr10(acescg_linear, out_path)
        else:
            raise ValueError(f"Unknown output mode: {mode}")
    # ---------------------------------------------------------------
    # Utility Helpers
    # ---------------------------------------------------------------
    def preview(self, img: np.ndarray, title="Preview"):
        """
        Used during debugging — displays result and auto-resizes.
        """
        disp = cv2.resize(img, (960, 540))
        cv2.imshow(title, disp)
        cv2.waitKey(1)
    def normalize(self, img: np.ndarray) -> np.ndarray:
        """
        Normalizes arbitrary float image → 0..1 range.
        """
        mn = img.min()
        mx = img.max()
        if mx - mn < 1e-8:
            return np.zeros_like(img)
        return (img - mn) / (mx - mn)
