import os
import time
from typing import List, Dict, Any
class AIFusionPipeline:
    """
    High-level wrapper that composes:
       - UltraACES (IDT -> RRT -> ODT)
       - Advanced chunk modules (rolling shutter, lens, denoise)
       - Film grain V2 (motion-aware)
       - Vintage/emulation stack (optional)
    Designed to be drop-in for your ai_fusion_pipeline.py usage.
    """
    def __init__(self,
                 ultra: Optional[UltraACES] = None,
                 extend_advanced: bool = True,
                 enable_gpu: bool = False):
        # core engine (create if not provided)
        self.ultra = ultra if ultra is not None else UltraACES("sRGB", "Rec709")
        # attach advanced modules (if available)
        if extend_advanced:
            try:
                extend_ultra_aces_with_advanced(self.ultra)
            except Exception:
                # silent fail: non-critical
                pass
            try:
                extend_ultra_aces_with_chunk7(self.ultra)
            except Exception:
                pass
        # Build film grainv2 and vintage if not present
        self.film_grain_v2 = FilmGrainV2()
        self.vintage = VintageFilmEmulator()
        # Basic state buffers for temporal modules
        self.prev_frame = None
        self.prev_gray = None
        self.frame_id = 0
        # performance flags
        self.enable_gpu = enable_gpu and hasattr(cv2, "cuda") and cv2.cuda.getCudaEnabledDeviceCount() > 0
    def process_frame(self,
        frame_bgr_uint8: np.ndarray,
        iso: int = 100,
        ev_offset: float = 0.0,
        apply_vintage: bool = False,
        apply_grain_v2: bool = True,
        do_lens_correct: bool = False,
        camera_calib: Optional[dict] = None,
        do_rolling_shutter: bool = False,
        gyro_rates: Optional[tuple] = None,
        exposure_data: Optional[Dict[str,Any]] = None,
        lut_1d: Optional[np.ndarray] = None,
        lut_3d: Optional[np.ndarray] = None
        ) -> Dict[str, Any]:
        """
        Main high-level process function.
        Returns dict: { "out": uint8 frame, "debug": {...} }
        """
        debug: Dict[str, Any] = {"frame_id": self.frame_id}
        if frame_bgr_uint8 is None:
            return {"out": None, "debug": {"error": "no_input"}}
        # Rolling shutter correction (optional)
        img = frame_bgr_uint8
        if do_rolling_shutter and gyro_rates is not None and getattr(self.ultra, "rolling_shutter", None) is not None:
            try:
                img = self.ultra.rolling_shutter.correct(img, gyro_rates, exposure_time_s=exposure_data.get("exposure_time", 1/30.0) if exposure_data else 1/30.0)
                debug['rolling_shutter'] = "applied"
            except Exception as e:
                debug['rolling_shutter'] = f"failed:{e}"
        # Lens corrections (optional)
        if do_lens_correct and getattr(self.ultra, "lens", None) is not None:
            try:
                if camera_calib:
                    self.ultra.lens.calib = camera_calib
                img = self.ultra.lens.undistort(img)
                img = self.ultra.lens.apply_vignette(img)
                debug['lens'] = "applied"
            except Exception as e:
                debug['lens'] = f"failed:{e}"
        # Compute a scene analysis stub (simple stats) to drive adaptive curve
        h, w = img.shape[:2]
        gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
        mean_luma = float(np.mean(gray) / 255.0)
        clipping = float(np.sum(gray > 250) / (h*w))
        scene_data = {
            "scene_key": np.clip(mean_luma, 0.0, 1.0),
            "total_clipping": clipping,
            "r_clip": 0.0, "g_clip": 0.0, "b_clip": 0.0
        }
        debug['scene_data'] = scene_data
        # Pass through UltraACES core pipeline (IDT -> RRT -> ODT)
        try:
            out_core = self.ultra.process(img, iso=iso, ev_offset=ev_offset, apply_grain=False, lut_1d=None, lut_3d=None)
            debug['ultra_core'] = "ok"
        except Exception as e:
            debug['ultra_core'] = f"fail:{e}"
            out_core = img
        # Convert out_core to float 0..1 for further operations
        out_f = to_float01(out_core)
        # Film grain v2 (motion-aware) using optical flow between prev_gray and gray
        try:
            if apply_grain_v2 and self.film_grain_v2 is not None:
                prev_g = self.prev_gray
                curr_g = gray
                out_f = self.film_grain_v2.apply(out_f, iso=iso, prev_gray=prev_g, curr_gray=curr_g, frame_id=self.frame_id)
                debug['grain_v2'] = "applied"
        except Exception as e:
            debug['grain_v2'] = f"failed:{e}"
        # Optional vintage emulation
        if apply_vintage:
            try:
                out_f = self.vintage.render(out_f, frame_id=self.frame_id)
                debug['vintage'] = "applied"
            except Exception as e:
                debug['vintage'] = f"failed:{e}"
        # Optional LUT application (1D/3D) - expects float 0..1
        try:
            if lut_1d is not None:
                out_f = LUTTools.apply_1d_lut(out_f, lut_1d)
                debug['lut_1d'] = "applied"
            if lut_3d is not None:
                out_f = LUTTools.apply_3d_lut(out_f, lut_3d)
                debug['lut_3d'] = "applied"
        except Exception as e:
            debug['lut'] = f"failed:{e}"
        # Final output uint8
        out_uint8 = to_uint8(out_f)
        # Update temporal buffers
        self.prev_frame = out_uint8.copy()
        self.prev_gray = gray.copy()
        self.frame_id += 1
        return {"out": out_uint8, "debug": debug}
