import torch
import torch.nn.functional as F

class TorchGPU:
    """
    GPU accelerator for the ACES pipeline.
    All operations preserve numerical behavior of CPU version.
    """
    def __init__(self, device=None):
        self.device = device or ("cuda" if torch.cuda.is_available() else "cpu")

    # -----------------------------------------------------------
    # Utility: Convert uint8 BGR → float32 RGB 0–1 on GPU
    # -----------------------------------------------------------
    def to_tensor(self, frame):
        t = torch.from_numpy(frame).float().to(self.device) / 255.0
        # convert BGR → RGB
        t = t[..., [2,1,0]]
        return t.permute(2,0,1).unsqueeze(0)  # [1,3,H,W]

    def to_uint8(self, t):
        t = t.squeeze(0).permute(1,2,0)
        # RGB → BGR
        t = t[..., [2,1,0]]
        return (t.clamp(0,1).cpu().numpy() * 255).astype(np.uint8)

    # -----------------------------------------------------------
    # Linearization (sRGB → Linear)
    # -----------------------------------------------------------
    def srgb_to_linear(self, t):
        low = t <= 0.04045
        high = ~low
        out = torch.zeros_like(t)
        out[low] = t[low] / 12.92
        out[high] = ((t[high] + 0.055) / 1.055) ** 2.4
        return out

    # -----------------------------------------------------------
    # Filmic Curve (ACES approximation)
    # -----------------------------------------------------------
    def aces_filmic(self, t):
        a = 2.51
        b = 0.03
        c = 2.43
        d = 0.59
        e = 0.14
        return (t * (a*t + b)) / (t*(c*t + d) + e)

    # -----------------------------------------------------------
    # Glow blur (Gaussian via conv2d)
    # -----------------------------------------------------------
    def gaussian_blur(self, t, sigma=15):
        # build gaussian kernel dynamically
        k = int(2 * round(3*sigma) + 1)
        coords = torch.arange(k) - k//2
        g = torch.exp(-(coords**2) / (2*sigma*sigma))
        g = (g / g.sum()).to(self.device)
        kernel = (g[:,None] * g[None,:]).unsqueeze(0).unsqueeze(0)
        kernel = kernel.repeat(3,1,1,1)  # depthwise (3 channels)
        t_pad = F.pad(t, (k//2,k//2,k//2,k//2), mode="reflect")
        return F.conv2d(t_pad, kernel, groups=3)

    # -----------------------------------------------------------
    # Motion-aware Grain (GPU)
    # -----------------------------------------------------------
    def grain_v2(self, t, iso=800, flow=None):
        h = t.shape[-2]
        w = t.shape[-1]
        # base grain intensity
        strength = min(1.0, iso / 3200.0)
        # random noise
        noise = torch.randn_like(t) * (0.03 * strength)
        # optionally warp grain by flow (optical flow not GPU-implemented here)
        if flow is not None:
            # Flow: [1,2,H,W], noise: [1,3,H,W]
            # NOT implementing full flow warp in this chunk for simplicity
            pass
        # add & clamp
        return (t + noise).clamp(0, 1)

    # -----------------------------------------------------------
    # 1D LUT (GPU)
    # -----------------------------------------------------------
    def apply_lut_1d(self, t, lut):
        # lut: numpy array 1D, 256 values or similar
        lut_gpu = torch.from_numpy(lut).float().to(self.device) / 255.0
        t_idx = (t * (len(lut)-1)).long().clamp(0, len(lut)-1)
        return torch.gather(lut_gpu, 0, t_idx)

    # -----------------------------------------------------------
    # 3D LUT (GPU)
    # -----------------------------------------------------------
    def apply_lut_3d(self, t, lut3d):
        # t: [1,3,H,W], values 0–1
        N = lut3d.shape[0]
        lut_gpu = torch.from_numpy(lut3d).float().to(self.device)
        coords = (t * (N-1)).clamp(0, N-1)
        r = coords[:,0]
        g = coords[:,1]
        b = coords[:,2]
        r0 = r.long(); r1 = (r0+1).clamp(max=N-1)
        g0 = g.long(); g1 = (g0+1).clamp(max=N-1)
        b0 = b.long(); b1 = (b0+1).clamp(max=N-1)
        # trilinear weights
        wr = r - r0
        wg = g - g0
        wb = b - b0
        c000 = lut_gpu[r0, g0, b0]
        c100 = lut_gpu[r1, g0, b0]
        c010 = lut_gpu[r0, g1, b0]
        c001 = lut_gpu[r0, g0, b1]
        c110 = lut_gpu[r1, g1, b0]
        c101 = lut_gpu[r1, g0, b1]
        c011 = lut_gpu[r0, g1, b1]
        c111 = lut_gpu[r1, g1, b1]
        # trilinear formula
        out = (
            c000*(1-wr)*(1-wg)*(1-wb) +
            c100*(wr)*(1-wg)*(1-wb) +
            c010*(1-wr)*(wg)*(1-wb) +
            c001*(1-wr)*(1-wg)*(wb) +
            c110*(wr)*(wg)*(1-wb) +
            c101*(wr)*(1-wg)*(wb) +
            c011*(1-wr)*(wg)*(wb) +
            c111*(wr)*(wg)*(wb)
        )
        return out

# ================================================================
# GPU-ENABLED WRAPPER FOR AIFusionPipeline
# ================================================================
class AIFusionPipelineGPU(AIFusionPipeline):
    """
    Drop-in replacement that forces GPU mode.
    """
    def __init__(self):
        super().__init__(enable_gpu=True)
        self.gpu = TorchGPU()

    def process_frame(self, frame, **kwargs):
        # Convert input frame → tensor
        t = self.gpu.to_tensor(frame)
        # Convert to linear
        t = self.gpu.srgb_to_linear(t)
        # Apply ACES filmic
        t = self.gpu.aces_filmic(t)
        # Glow
        t_glow = self.gpu.gaussian_blur(t, sigma=12)
        t = (t + 0.10 * t_glow).clamp(0,1)
        # Grain
        t = self.gpu.grain_v2(t, iso=kwargs.get("iso", 800))
        # Convert to uint8
        out = self.gpu.to_uint8(t)
        return {"out": out, "debug": {"gpu": True}}
