# ================================================================
# CHUNK 14 — ULTRA-PRO-MAX HALATION ENGINE (H3 HYBRID MODEL)
# Provides:
#    • Photochemical halation (Vision3-style red halo bloom)
#    • Digital spectral scattering (ACES-hue-weighted)
#    • Lens-dependent kernel shaping
#    • Motion-aware halation suppression (using RAFT flow mask)
#    • Temporal stabilization (no flicker)
#    • Multi-resolution halation pyramid
# ================================================================

import numpy as np
import cv2
from typing import Optional, Dict, Any

# ---------------------------------------------------------------
# Utility: ensure float 0–1
# ---------------------------------------------------------------
def _f01(img):
    if img.dtype == np.uint8:
        return img.astype(np.float32) / 255.0
    out = img.astype(np.float32)
    if out.max() > 1.5:
        out = out / 255.0
    return np.clip(out, 0.0, 1.0)

# ---------------------------------------------------------------
# H3: Spectral Response Curves (film-like halation strength)
# ---------------------------------------------------------------
class H3SpectralResponse:
    """
    Defines per-wavelength scattering weights.
    These emulate the red-dye layer glow in Kodak Vision3.
    """
    def __init__(self):
        # Strongest halo in long wavelengths → red
        self.red_weight = 1.00
        # Medium halo in green channel
        self.green_weight = 0.45
        # Weak halo in blue channel
        self.blue_weight = 0.18

    def apply(self, img):
        r = img[..., 2] * self.red_weight
        g = img[..., 1] * self.green_weight
        b = img[..., 0] * self.blue_weight
        return np.stack([b, g, r], axis=2)

# ---------------------------------------------------------------
# H3: Lens-dependent kernel (anamorphic, spherical, vintage)
# ---------------------------------------------------------------
class H3LensKernel:
    """
    Produces anisotropic halation kernels:
      mode="spherical" → uniform gaussian
      mode="anamorphic" → stretched horizontal bloom
      mode="vintage" → slight tilt & chromatic offset
    """
    def __init__(self, radius=18, mode="spherical", stretch=2.5):
        self.radius = int(max(3, radius))
        self.mode = mode
        self.stretch = stretch

    def build(self):
        r = self.radius
        xs = np.arange(-r, r+1)
        ys = np.arange(-r, r+1)
        xv, yv = np.meshgrid(xs, ys)

        if self.mode == "spherical":
            d = (xv**2 + yv**2) / (r*r)
        elif self.mode == "anamorphic":
            d = (xv**2 / (self.stretch*r)**2) + (yv**2 / (r*r))
        else:  # vintage
            tilt = xv * 0.12
            d = ((xv+tilt)**2 + (yv**2)) / (r*r)

        k = np.exp(-d * 3.2)
        k = k / np.sum(k)
        return k.astype(np.float32)

# ---------------------------------------------------------------
# Temporal stabilizer (prevents flicker across frames)
# ---------------------------------------------------------------
class H3TemporalHalation:
    def __init__(self, blend=0.82):
        self.blend = float(np.clip(blend, 0.0, 0.99))
        self.prev = None

    def apply(self, curr):
        if self.prev is None:
            self.prev = curr.copy()
            return curr
        out = self.prev * self.blend + curr * (1.0 - self.blend)
        self.prev = out
        return out

# ---------------------------------------------------------------
# H3 Halation Engine
# ---------------------------------------------------------------
class HalationH3:
    """
    Master halation engine:
      1. Detect highlights
      2. Apply spectral halo intensity per channel
      3. Convolve with lens kernel
      4. Multi-res pyramid (soft atmosphere halos)
      5. Motion-aware mask (suppresses halo in fast objects)
      6. Temporal stability
    """
    def __init__(self,
                 threshold=0.75,
                 intensity=1.20,
                 radius=18,
                 mode="spherical",
                 use_motion_mask=True,
                 spectral=True):

        self.threshold = float(threshold)
        self.intensity = float(intensity)
        self.use_motion_mask = bool(use_motion_mask)

        # Build kernel and spectral model
        self.kernel = H3LensKernel(radius=radius, mode=mode).build()
        self.spectral = H3SpectralResponse() if spectral else None

        # Temporal stabilizer
        self.temporal = H3TemporalHalation(blend=0.80)

    # -----------------------------------------------------------
    def _extract_highlights(self, img):
        """
        Produces mask of highlights where halation occurs.
        """
        luma = 0.2126 * img[...,2] + 0.7152 * img[...,1] + 0.0722 * img[...,0]
        mask = np.clip((luma - self.threshold) / (1.0 - self.threshold), 0.0, 1.0)
        return mask[..., None]

    # -----------------------------------------------------------
    def _apply_kernel(self, src):
        """
        Convolve with lens kernel using separable filtering.
        """
        k = self.kernel
        # First blur horizontally
        blur = cv2.filter2D(src, -1, k, borderType=cv2.BORDER_REFLECT)
        return blur

    # -----------------------------------------------------------
    def _pyramid_glow(self, img, strength=0.35):
        """
        Multi-resolution halo pyramid:
          • High freq: small halo (sharp glow)
          • Mid  freq: medium halo
          • Low  freq: large atmospheric halo
        """
        g1 = cv2.GaussianBlur(img, (0,0), 3)
        g2 = cv2.GaussianBlur(img, (0,0), 9)
        g3 = cv2.GaussianBlur(img, (0,0), 21)
        return (g1 * 0.6 + g2 * 0.3 + g3 * 0.1) * strength

    # -----------------------------------------------------------
    def apply(self, img, motion_mask: Optional[np.ndarray] = None):
        """
        img: float32 RGB 0–1
        motion_mask: optional mask (0–1) → reduces halation in motion
        """
        f = _f01(img)

        # 1. Highlight mask
        mask = self._extract_highlights(f)

        # 2. Spectral response
        if self.spectral is not None:
            spec = self.spectral.apply(f)
        else:
            spec = f

        # 3. Kernel convolution of highlight-weighted spectral channels
        weighted = spec * mask
        halo_conv = self._apply_kernel(weighted)

        # 4. Multi-resolution atmospheric halo
        halo_pyr = self._pyramid_glow(weighted)

        halo = halo_conv + halo_pyr
        halo = halo * self.intensity

        # 5. Motion mask suppression
        if self.use_motion_mask and motion_mask is not None:
            mm = np.clip(1.0 - motion_mask[...,None], 0.0, 1.0)
            halo = halo * mm

        # 6. Temporal stabilization
        halo = self.temporal.apply(halo)

        # 7. Composite over image
        out = f + halo
        return np.clip(out, 0.0, 1.0)

# ---------------------------------------------------------------
# H3 Halation Wrapper for VintageFilmEmulator & Pipeline
# ---------------------------------------------------------------
class HalationEngineH3:
    """
    Drop-in replacement for HalationEngine.
    """
    def __init__(self, **kwargs):
        self.engine = HalationH3(**kwargs)

    def apply(self, frame, motion_mask=None):
        return self.engine.apply(frame, motion_mask=motion_mask)

# ---------------------------------------------------------------
# Integration Hook for AIFusionPipeline
# ---------------------------------------------------------------
def integrate_h3_halation(pipeline, **params):
    """
    Adds Ultra H3 halation to AIFusionPipeline instance.
    """
    pipeline.halation_h3 = HalationEngineH3(**params)
    return pipeline

# ---------------------------------------------------------------
# Example extension of AIFusionPipeline
# ---------------------------------------------------------------
class AIFusionPipeline_H3(AIFusionPipeline):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.h3 = HalationH3()

    def process_frame(self, frame, **kw):
        base = super().process_frame(frame, **kw)

        out_f = _f01(base["out"])

        # If motion mask available (from RAFT-Lite)
        motion_mask = base["debug"].get("motion_mask")

        # apply H3 halation
        halated = self.h3.apply(out_f, motion_mask=motion_mask)

        base["out"] = (np.clip(halated, 0, 1) * 255).astype(np.uint8)
        base["debug"]["halation_h3"] = "applied"
        return base

