# ================================================================
# ================================================================
# CHUNK 15 — BLOOM ENGINE V3 ULTRA (Spectral, Multi-Pass, Motion-Aware)
# Provides:
#   • Spectral bloom (film-correct warm scattering)
#   • Multi-pass gaussian bloom (3-layer)
#   • ACES highlight extraction
#   • Motion-aware suppression (uses optical-flow mask)
#   • Temporal stabilization (prevents flicker)
# ================================================================

import cv2
import numpy as np

class BloomEngineV3:
    """
    Ultra-Pro-Max Bloom System:
       - 3-band bloom pyramid
       - ACES-based highlight selection
       - Spectral (R/G/B) scattering differences
       - Motion-aware suppression (optional RAFT mask)
       - Temporal stabilization for video
    """
    def __init__(
            self,
            strength: float = 1.25,
            radius: float = 24.0,
            threshold: float = 0.80,
            color_temp: str = "warm",
            temporal_smooth: float = 0.75
    ):
        self.strength = float(strength)
        self.radius = float(radius)
        self.threshold = float(np.clip(threshold, 0.0, 1.0))
        self.color_temp = str(color_temp).lower()
        self.temporal_smooth = float(np.clip(temporal_smooth, 0.0, 0.99))
        self.prev_bloom = None  # temporal state
    # ---------------------------------------------------------------
    def _highlight_mask(self, f):
        """ACES luminance + soft threshold masking."""
        lum = 0.2126 * f[...,2] + 0.7152 * f[...,1] + 0.0722 * f[...,0]
        # soft knee mask
        m = (lum - self.threshold) / (1.0 - self.threshold)
        m = np.clip(m, 0.0, 1.0)
        # 3-band smoothed mask
        m_small = cv2.GaussianBlur(m, (0,0), sigmaX=1.5)
        m_mid   = cv2.GaussianBlur(m, (0,0), sigmaX=4.0)
        m_large = cv2.GaussianBlur(m, (0,0), sigmaX=12.0)
        mask = (m_small * 0.50 +
                m_mid   * 0.30 +
                m_large * 0.20)
        return np.clip(mask, 0.0, 1.0)
    # ---------------------------------------------------------------
    def _spectral_weight(self, f):
        """
        Film-accurate spectral bloom:
           R blooms strongest, B weakest.
        """
        b = f[...,0] * 0.40
        g = f[...,1] * 0.70
        r = f[...,2] * 1.00
        return np.stack([b, g, r], axis=2)
    # ---------------------------------------------------------------
    def _color_temperature(self, bloom):
        """
        Warms/cools bloom color cast.
        """
        if self.color_temp == "warm":
            bloom[...,2] *= 1.10
            bloom[...,0] *= 0.92
        elif self.color_temp == "cool":
            bloom[...,2] *= 0.95
            bloom[...,0] *= 1.05
        return bloom
    # ---------------------------------------------------------------
    def _multi_pass_blur(self, img):
        """Three-layer gaussian bloom pyramid."""
        r = self.radius
        b1 = cv2.GaussianBlur(img, (0,0), sigmaX=r * 0.50)
        b2 = cv2.GaussianBlur(img, (0,0), sigmaX=r * 1.00)
        b3 = cv2.GaussianBlur(img, (0,0), sigmaX=r * 2.00)
        out = b1 * 0.60 + b2 * 0.30 + b3 * 0.10
        return out
    # ---------------------------------------------------------------
    def _motion_suppress(self, bloom, motion_mask):
        """
        motion_mask: 0..1 (high motion = suppress bloom)
        """
        if motion_mask is None:
            return bloom
        mask = 1.0 - motion_mask[...,None] * 0.75
        return bloom * np.clip(mask, 0.25, 1.0)
    # ---------------------------------------------------------------
    def apply(self, frame, motion_mask=None):
        """
        Main bloom function.
        frame: float32 0..1
        motion_mask: optional from RAFTLite
        """
        f = frame.astype(np.float32)
        # 1. ACES-style highlight mask
        mask = self._highlight_mask(f)
        # 2. Extract highlight colors → spectral weighting
        extract = self._spectral_weight(f) * mask[...,None]
        # 3. Multi-pass gaussian pyramid bloom
        bloom = self._multi_pass_blur(extract)
        # 4. Color temperature adjustment
        bloom = self._color_temperature(bloom)
        # 5. Motion-aware suppression
        bloom = self._motion_suppress(bloom, motion_mask)
        # 6. Temporal stabilization
        if self.prev_bloom is not None:
            bloom = (
                self.prev_bloom * self.temporal_smooth +
                bloom * (1.0 - self.temporal_smooth)
            )
        self.prev_bloom = bloom
        # 7. Composite with base frame
        out = f + bloom * self.strength
        return np.clip(out, 0.0, 1.0)
