# PIPELINE INTEGRATION WRAPPER (for AIFusionPipeline)
# ================================================================
class BloomModuleV3:
    """
    Wrapper used by AIFusionPipeline to integrate BloomEngineV3.
    """
    def __init__(self):
        self.engine = BloomEngineV3()
    def apply(self, frame_float01, motion_mask=None):
        return self.engine.apply(frame_float01, motion_mask=motion_mask)
