# OPTIONAL EXTENSION: AUTO-TUNING BLOOM BASED ON SCENE KEY
# ================================================================
class AutoBloomTuner:
    """
    Automatically adjusts bloom strength based on:
       – scene_key (brightness)
       – highlight_clipping
       – motion_mask (avoid overbloom on fast motion)
    """
    def __init__(self, min_strength=0.4, max_strength=1.8):
        self.min_s = float(min_strength)
        self.max_s = float(max_strength)
    def tune(self, bloom_engine: BloomEngineV3, scene_data, motion_mask=None):
        key = float(scene_data.get("scene_key", 0.5))
        clip = float(scene_data.get("total_clipping", 0.0))
        # base strength based on brightness
        s = np.interp(key, [0.0, 1.0], [self.max_s, self.min_s])
        # add highlight clipping compensation
        s += clip * 0.25
        # suppress bloom heavily in motion
        if motion_mask is not None:
            fast = np.mean(motion_mask)
            s *= (1.0 - fast * 0.65)
        bloom_engine.strength = float(np.clip(s, self.min_s, self.max_s))
        return bloom_engine.strength
