# WRAPPER MODULE FOR PIPELINE
# ================================================================
class ColorSeparationModuleV4:
    def __init__(self):
        self.engine = CinematicColorSeparationV4()

    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

