class FilmDensityEngineV4_Extended(FilmDensityEngineV4):
    """
    Wraps FilmDensityEngineV4 with:
       - Preset loading
       - Dynamic parameter injection
       - ACES-safe normalization of incoming preset ranges
    """

    def load_preset(self, name: str):
        """
        Loads preset and updates engine parameters.
        """
        p = FilmDensityPresetsV4.get(name)

        self.toe_strength       = float(p["toe_strength"])
        self.mid_contrast       = float(p["mid_contrast"])
        self.shoulder_strength  = float(p["shoulder_strength"])
        self.density_tint       = float(p["density_tint"])
        self.highlight_limit    = float(p["highlight_limit"])

    # ------------------------------------------------------------
    def inject_params(self, **kwargs):
        """
        External modules (AI style selector, LUT adapters)
        can modify film density model.
        """
        for k, v in kwargs.items():
            if hasattr(self, k):
                setattr(self, k, float(v))

    # ------------------------------------------------------------
    def normalize_for_aces(self):
        """
        Guarantee safe ranges when working under ACEScg.
        """
        self.toe_strength      = np.clip(self.toe_strength, 0.0, 1.0)
        self.mid_contrast      = np.clip(self.mid_contrast, 1.0, 1.6)
        self.shoulder_strength = np.clip(self.shoulder_strength, 0.0, 1.0)
        self.density_tint      = np.clip(self.density_tint, 0.0, 0.20)
        self.highlight_limit   = np.clip(self.highlight_limit, 0.80, 0.98)

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Extended apply:
          – Validate ranges
          – Run base FilmDensityEngineV4
        """
        self.normalize_for_aces()
        return super().apply(img)


