# ================================================================
# CHUNK 74E — LUT Adapter Layer V4 (ACES-Safe, Exportable .cube)
# Provides:
#   • Real 3D LUT generation (17, 33, 65 res)
#   • ACES-compliant mapping
#   • Converts FilmDensityEngineV4 response → LUT
#   • Enables external editor compatibility (DaVinci, Premiere, GoPro)
# ================================================================

import numpy as np

class LUTAdapterV4:
    """
    Converts FilmDensityEngineV4 transformations into a
    fully exportable 3D LUT (.cube format).

    This allows:
       • exporting cinematic looks
       • applying looks to external NLE systems
       • using the same film look on GoPro/DJI/RAW video
    """

    # ------------------------------------------------------------
    def __init__(self, lut_size: int = 33):
        self.size = int(np.clip(lut_size, 17, 65))

    # ------------------------------------------------------------
    def _generate_grid(self):
        """
        Generates a normalized RGB 3D LUT grid of shape:
           (size, size, size, 3)
        """
        n = self.size
        vals = np.linspace(0.0, 1.0, n)

        grid = np.stack(np.meshgrid(vals, vals, vals, indexing="ij"), axis=-1)

        return grid.reshape(-1, 3)

    # ------------------------------------------------------------
    def create_lut(self, density_engine):
        """
        Runs each LUT sample through FilmDensityEngineV4.
        Returns the LUT as float32 array.
        """
        grid = self._generate_grid()

        lut_out = []
        for rgb in grid:
            rgb_img = rgb.reshape(1, 1, 3).astype(np.float32)
            processed = density_engine.apply(rgb_img)
            lut_out.append(processed.flatten())

        return np.array(lut_out, dtype=np.float32)

    # ------------------------------------------------------------
    def export_cube(self, lut_data, path="cinematic_v4.cube"):
        """
        Saves LUT in standard .cube file format.
        Compatible with all major editors.
        """
        n = self.size

        with open(path, "w") as f:
            f.write("# Generated by AIFusionPipeline — LUT Adapter V4\n")
            f.write("TITLE \"FilmDensityV4\"\n")
            f.write(f"LUT_3D_SIZE {n}\n")

            for rgb in lut_data:
                r, g, b = rgb
                f.write(f"{r:.6f} {g:.6f} {b:.6f}\n")

        return path

    # ------------------------------------------------------------
    def generate_and_export(self, density_engine, path, size=None):
        """
        Convenience wrapper:
           density engine → LUT → exported .cube file
        """
        if size is not None:
            self.size = int(np.clip(size, 17, 65))

        lut = self.create_lut(density_engine)
        return self.export_cube(lut, path)


# ================================================================
# PIPELINE WRAPPER — Allows AIFusionPipeline to call LUT export
# ================================================================
class LUTExportModuleV4:
    """
    High-level interface used by AIFusionPipeline:
       • Exports current film look as LUT
       • Automatically names LUT files based on date/style
    """

    def __init__(self, density_engine):
        self.engine = density_engine
        self.adapter = LUTAdapterV4(lut_size=33)

    # ------------------------------------------------------------
    def export_current_lut(self, style_name="default"):
        filename = f"lut_{style_name}_v4.cube"
        path = self.adapter.generate_and_export(
            density_engine=self.engine,
            path=filename
        )
        return path


