# PIPELINE WRAPPER — VintageImperfectionModuleV4
# ================================================================
class VintageImperfectionModuleV4:
    """Integration wrapper for AIFusionPipeline."""
    def __init__(self):
        self.engine = VintageImperfectionV4()

    def apply(self, frame_float01, frame_index=0):
        return self.engine.apply(frame_float01, frame_index=frame_index)

