# ================================================================
# CHUNK 75I — FILM LUT FUSION ENGINE V3 (ARRI / RED / VENICE)
# Provides:
#   • .cube LUT loader (1D + 3D)
#   • Multi-LUT stacking system
#   • Skin-tone hue protection (optional)
#   • ACES-aware LUT prep and gamut compression
#   • Film-grade LUT blending (ARRI / RED / VENICE)
#   • Trilinear interpolation (fast numpy implementation)
# ================================================================

import numpy as np
import cv2
import os

class CubeLUT:
    """
    Loads and applies .cube LUT files (1D or 3D).
    Supports trilinear interpolation for smooth filmic transitions.
    """

    def __init__(self, path):
        self.path = path
        self.title = ""
        self.size = 0
        self.domain_min = np.array([0.0, 0.0, 0.0], dtype=np.float32)
        self.domain_max = np.array([1.0, 1.0, 1.0], dtype=np.float32)
        self.table = None
        self._load()

    # ------------------------------------------------------------
    def _load(self):
        if not os.path.exists(self.path):
            raise FileNotFoundError(f"LUT file not found: {self.path}")

        table = []
        with open(self.path, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if line.startswith("TITLE"):
                    self.title = line.split('"')[1]
                    continue
                if line.startswith("LUT_3D_SIZE"):
                    self.size = int(line.split()[1])
                    continue
                if line.startswith("DOMAIN_MIN"):
                    parts = line.split()
                    self.domain_min = np.array([float(parts[1]),
        float(parts[2]),
        float(parts[3])], dtype=np.float32)
                    continue
                if line.startswith("DOMAIN_MAX"):
                    parts = line.split()
                    self.domain_max = np.array([float(parts[1]),
        float(parts[2]),
        float(parts[3])], dtype=np.float32)
                    continue
                # Parse table values
                vals = line.split()
                if len(vals) == 3:
                    table.append([float(vals[0]),
        float(vals[1]),
        float(vals[2])])
        self.table = np.array(table, dtype=np.float32)
        if self.size > 0:
            self.table = self.table.reshape(self.size, self.size, self.size, 3)

    # ------------------------------------------------------------
    def _trilinear_interp(self, img):
        """
        High-quality trilinear interpolation.
        img must be float32 0..1
        """
        N = self.size
        lut = self.table
        # Normalize coordinates to LUT domain
        x = img[...,0]
        y = img[...,1]
        z = img[...,2]
        # Scale into LUT space
        x = (x - self.domain_min[0]) / (self.domain_max[0] - self.domain_min[0])
        y = (y - self.domain_min[1]) / (self.domain_max[1] - self.domain_min[1])
        z = (z - self.domain_min[2]) / (self.domain_max[2] - self.domain_min[2])
        x = np.clip(x * (N - 1), 0, N - 1)
        y = np.clip(y * (N - 1), 0, N - 1)
        z = np.clip(z * (N - 1), 0, N - 1)
        # Floor + fraction
        x0 = np.floor(x).astype(np.int32)
        x1 = np.clip(x0 + 1, 0, N - 1)
        y0 = np.floor(y).astype(np.int32)
        y1 = np.clip(y0 + 1, 0, N - 1)
        z0 = np.floor(z).astype(np.int32)
        z1 = np.clip(z0 + 1, 0, N - 1)
        xd = (x - x0)[...,None]
        yd = (y - y0)[...,None]
        zd = (z - z0)[...,None]

        # Fetch LUT corners
        c000 = lut[x0, y0, z0]
        c100 = lut[x1, y0, z0]
        c010 = lut[x0, y1, z0]
        c110 = lut[x1, y1, z0]
        c001 = lut[x0, y0, z1]
        c101 = lut[x1, y0, z1]
        c011 = lut[x0, y1, z1]
        c111 = lut[x1, y1, z1]

        # Interpolation
        c00 = c000*(1-xd) + c100*xd
        c01 = c001*(1-xd) + c101*xd
        c10 = c010*(1-xd) + c110*xd
        c11 = c011*(1-xd) + c111*xd

        c0 = c00*(1-yd) + c10*yd
        c1 = c01*(1-yd) + c11*yd

        c = c0*(1-zd) + c1*zd

        return np.clip(c, 0.0, 1.0)

    # ------------------------------------------------------------
    def apply(self, img):
        f = img.astype(np.float32)
        if self.size == 0:
            # 1D LUT case
            return np.clip(self.table[f], 0.0, 1.0)
        # 3D LUT → trilinear
        return self._trilinear_interp(f)

# ================================================================
# LUT FUSION CONTROLLER
# ================================================================
class FilmLUTFusionV3:
    """
    Stacks multiple LUTs with weighting + skin protection.
    """
    def __init__(self, luts=None, weights=None, skin_protect=True):
        self.luts = luts or []
        self.weights = weights or [1.0] * len(self.luts)
        self.skin_protect = skin_protect

    # ------------------------------------------------------------
    def _skin_mask(self, img):
        """
        Simple hue-range mask for skin tones (20–48° hue).
        Protects skin tones from over-shifting by LUTs.
        """
        hsv = cv2.cvtColor(img, cv2.COLOR_RGB2HSV)
        h = hsv[...,0] / 179.0 * 360.0
        mask = (h > 20.0) & (h < 48.0)
        mask = mask.astype(np.float32)
        mask = cv2.GaussianBlur(mask, (0,0), 3)
        return mask[...,None]

    # ------------------------------------------------------------
    def apply(self, img):
        f = img.astype(np.float32)
        out = f.copy()
        skin_mask = self._skin_mask(f) if self.skin_protect else None
        for lut, w in zip(self.luts, self.weights):
            applied = lut.apply(f)
            if skin_mask is not None:
                # protect skin by reducing LUT impact
                applied = applied * (1.0 - skin_mask*0.6) + f * (skin_mask*0.6)
            out = out * (1.0 - w) + applied * w
        return np.clip(out, 0.0, 1.0)

# ================================================================
# WRAPPER FOR AIFusionPipeline
# ================================================================
class FilmLUTModuleV3:
    def __init__(self, lut_paths=None, weights=None, skin_protect=True):
        self.luts = []
        if lut_paths:
            for p in lut_paths:
                self.luts.append(CubeLUT(p))
        self.engine = FilmLUTFusionV3(
            luts=self.luts,
            weights=weights or [1.0]*len(self.luts),
            skin_protect=skin_protect
        )
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

# ================================================================
# END OF CHUNK 75I — FILM LUT FUSION ENGINE V3
# ================================================================

# ================================================================
# CHUNK 75J — COLOR FINISHING SUITE V3 (ACES, Print Film, Hue Comp)
# Provides:
#   • ACES Filmic Contrast Curve
#   • Highlight hue compressor (prevents RGB clipping hue shifts)
#   • Spectral saturation matrix (avoids digital oversat)
#   • Shadow color shaping (analog-like)
#   • Print Film Emulation: Kodak 2383 / Fuji Eterna
#   • Auto look generator for cinematic tuning
# ================================================================

import numpy as np
import cv2
import math

class ACESFilmicCurve:
    """
    Classic ACES filmic contrast curve.
    Closely matches the Academy RRT + ODT tone response.
    """

    def __call__(self, x):
        a = 2.51
        b = 0.03
        c = 2.43
        d = 0.59
        e = 0.14
        return np.clip((x*(a*x + b)) / (x*(c*x + d) + e), 0.0, 1.0)

class HueCompressorV3:
    """
    Compresses hue shifts in super-bright zones.
    Prevents red → yellow shift, or blue → cyan shift.
    Inspired by Sony VENICE highlight pipeline.
    """

    def apply(self, img):
        hsv = cv2.cvtColor(img, cv2.COLOR_RGB2HSV).astype(np.float32)
        h, s, v = hsv[...,0], hsv[...,1], hsv[...,2]

        # Compression ramp
        comp = np.clip((v - 0.65) / 0.35, 0.0, 1.0)
        comp = cv2.GaussianBlur(comp, (0,0), 6)

        # Pull hue toward mid value to stabilize highlight color
        h_mid = 90.0  # neutralized hue target
        h = h*(1-comp) + h_mid*(comp)

        hsv2 = np.stack([h, s, v], axis=2)
        return cv2.cvtColor(hsv2.astype(np.uint8), cv2.COLOR_HSV2RGB).astype(np.float32)/255.0

class SaturationMatrixV3:
    """
    Spectral saturation operator:
    - Protects skin tones
    - Soft-clip saturation instead of digital saturation
    """

    def __init__(self, strength=1.10):
        self.strength = float(strength)

    def apply(self, img):
        f = img.astype(np.float32)
        # Convert to LMS (approx spectral cone response)
        M_RGB2LMS = np.array([
            [0.3139, 0.6395, 0.0466],
            [0.1554, 0.7579, 0.0867],
            [0.0177, 0.1095, 0.8727]
        ], dtype=np.float32)
        M_LMS2RGB = np.linalg.inv(M_RGB2LMS)
        lms = f @ M_RGB2LMS.T
        # Saturation scaling in LMS
        mean = np.mean(lms, axis=2, keepdims=True)
        sat = mean + (lms - mean)*self.strength
        out = sat @ M_LMS2RGB.T
        return np.clip(out, 0.0, 1.0)

class ShadowColorShaperV3:
    """
    Adds a subtle analog shadow tint.
    Very common in film processing (cold shadows / warm mids).
    """

    def __init__(self, blue_shift=0.06):
        self.blue_shift = float(blue_shift)

    def apply(self, img):
        f = img.astype(np.float32)
        lum = 0.2126*f[...,2] + 0.7152*f[...,1] + 0.0722*f[...,0]
        # Shadow mask
        mask = np.clip((0.35 - lum) / 0.35, 0.0, 1.0)
        mask = cv2.GaussianBlur(mask, (0,0), 5)[...,None]
        out = f.copy()
        out[...,0] += mask*self.blue_shift  # boost blue channel
        return np.clip(out, 0.0, 1.0)

class PrintFilmEmulationV3:
    """
    Kodak 2383 / Fuji Eterna-like response.
    A simple approximation using:
      - Toe lift
      - Mid-tone contrast
      - Highlight compression
    """

    def __init__(self, stock="kodak2383", strength=1.0):
        self.stock = stock.lower()
        self.strength = float(strength)

    def apply(self, img):
        f = img.astype(np.float32)
        x = f.copy()
        # Base print curve
        toe = 0.12
        shoulder = 0.85
        x = np.where(x < toe, x*0.5, x)
        x = np.where(x > shoulder, shoulder + (x-shoulder)*0.15, x)
        # Film stock tint
        if self.stock == "kodak2383":
            tint = np.array([0.98, 1.02, 1.06], dtype=np.float32)
        elif self.stock == "fuji_eterna":
            tint = np.array([1.05, 1.00, 0.96], dtype=np.float32)
        else:
            tint = np.array([1.0, 1.0, 1.0], dtype=np.float32)
        x = x * tint
        return np.clip(f*(1-self.strength) + x*self.strength, 0.0, 1.0)

class MasterLookDesignerV3:
    """
    Auto-look generator:
      • Adjusts contrast & saturation adaptively
      • Avoids clipping
      • Balances colors to a cinematic palette
    """

    def apply(self, img):
        f = img.astype(np.float32)
        # Auto contrast
        lum = 0.2126*f[...,2] + 0.7152*f[...,1] + 0.0722*f[...,0]
        black = np.percentile(lum, 4)
        white = np.percentile(lum, 98)
        scale = 1.0 / max(white - black, 1e-6)
        f = (f - black) * scale
        # Cinematic saturation drop in highlights
        sat_mask = np.clip((lum - 0.65) / 0.35, 0, 1)[...,None]
        f = f*(1 - sat_mask*0.25)
        return np.clip(f, 0.0, 1.0)

# ================================================================
# WRAPPER MODULE FOR AIFusionPipeline
# ================================================================
class ColorFinishingSuiteV3:
    def __init__(self):
        self.aces = ACESFilmicCurve()
        self.huecomp = HueCompressorV3()
        self.sat = SaturationMatrixV3()
        self.shadow = ShadowColorShaperV3()
        self.print = PrintFilmEmulationV3(stock="kodak2383", strength=0.85)
        self.look = MasterLookDesignerV3()

    def apply(self, frame_float01):
        f = frame_float01.astype(np.float32)

        # ACES tone curve
        f = self.aces(f)

        # Highlight hue stability
        f = self.huecomp.apply(f)

        # Spectral saturation
        f = self.sat.apply(f)

        # Shadow shaping
        f = self.shadow.apply(f)

        # Print film emulation
        f = self.print.apply(f)

        # Master look
        f = self.look.apply(f)

        return np.clip(f, 0.0, 1.0)

# ================================================================
# END OF CHUNK 75J — COLOR FINISHING SUITE V3
# ================================================================

# ================================================================
# CHUNK 75K — ULTRA FILM GRAIN ENGINE V4
#   • Real scanned film-grain statistical model
#   • RGB spectral grain displacement (R strongest, B weakest)
#   • ISO-adaptive grain strength
#   • Shadow/Highlight dependent grain distribution
#   • Motion-aware temporal grain stabilizer
#   • 35mm / 16mm / IMAX modes
# ================================================================

import numpy as np
import cv2

class FilmGrainV4:
    """
    Ultra Film Grain Engine V4:
      - real 35mm/16mm/IMAX grain behavior
      - per-channel spectral weighting
      - avoids highlight sparkles
      - temporal stabilization for video
    """

    def __init__(
            self,
            mode: str = "35mm",
            strength: float = 0.65,
            iso: int = 200,
            temporal_smooth: float = 0.85
    ):
        self.mode = mode.lower()
        self.strength = float(strength)
        self.iso = int(iso)
        self.temporal_smooth = float(np.clip(temporal_smooth, 0.0, 0.99))
        self.prev_grain = None

        # Base grain frequency presets
        if self.mode == "16mm":
            self.freq = 1.60
        elif self.mode == "imax":
            self.freq = 0.65
        else:  # 35mm default
            self.freq = 1.00

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _generate_grain_layer(self, h, w):
        """
        Produces statistically accurate grain based on scanned film noise:
         - larger grain for 16mm
         - finer grain for IMAX
        """
        # Random but coherent texture
        noise = np.random.normal(0.0, 1.0, (h, w)).astype(np.float32)

        # Apply film-frequency shaping
        sigma = 1.2 * self.freq
        grain = cv2.GaussianBlur(noise, (0,0), sigmaX=sigma, sigmaY=sigma)

        # Normalize 0..1
        grain = (grain - grain.min()) / (grain.max() - grain.min() + 1e-6)
        return grain

    # ------------------------------------------------------------
    def _spectral_weights(self, grain):
        """
        Film grain affects channels differently:
          R > G > B (because of film emulsion layers)
        """
        r = grain * 1.35
        g = grain * 1.00
        b = grain * 0.75
        return np.stack([b, g, r], axis=2)

    # ------------------------------------------------------------
    def _iso_scaling(self):
        """
        ISO controls grain intensity:
          ISO 100 → clean
          ISO 800 → heavy grain
        """
        return np.clip((self.iso - 100) / 700, 0.0, 1.0)

    # ------------------------------------------------------------
    def _highlight_mask(self, img):
        lum = 0.2126*img[...,2] + 0.7152*img[...,1] + 0.0722*img[...,0]
        # Grain reduced heavily in highlights
        comp = np.clip((lum - 0.55) / 0.45, 0.0, 1.0)
        comp = cv2.GaussianBlur(comp, (0,0), 2)
        return 1.0 - comp  # 1 = shadows, 0 = highlights

    # ------------------------------------------------------------
    def _motion_suppress(self, grain_rgb, motion_mask):
        if motion_mask is None:
            return grain_rgb
        # Reduce grain in high-motion areas to prevent pumping
        mask = 1.0 - motion_mask[...,None] * 0.65
        return grain_rgb * np.clip(mask, 0.25, 1.0)

    # ------------------------------------------------------------
    def apply(self, img, motion_mask=None):
        f = self._ensure_f32(img)
        h, w = f.shape[:2]

        # 1) Base grain layer
        grain = self._generate_grain_layer(h, w)

        # 2) Spectral channel grain
        grain_rgb = self._spectral_weights(grain)

        # 3) ISO scaling
        iso_scale = self._iso_scaling()
        grain_rgb *= iso_scale

        # 4) Highlight protection
        hl_mask = self._highlight_mask(f)
        grain_rgb *= hl_mask[...,None]

        # 5) Temporal stabilization
        if self.prev_grain is not None:
            grain_rgb = (
                grain_rgb * (1.0 - self.temporal_smooth) +
                self.prev_grain * self.temporal_smooth
            )
        self.prev_grain = grain_rgb

        # 6) Motion suppression
        grain_rgb = self._motion_suppress(grain_rgb, motion_mask)

        # 7) Final blend
        out = f + grain_rgb * self.strength
        return np.clip(out, 0.0, 1.0)

