# ================================================================
# CHUNK 75M — ADVANCED LIGHT-LEAK ENGINE V4
#   • Procedural gradient leaks (warm/cool)
#   • Edge burn illumination
#   • Chromatic dispersion (R/G/B misalignment)
#   • Directional streak leaks (horizontal / vertical)
#   • Roll-movement based on frame index
#   • Hybrid blend modes: screen, add, softlight
# ================================================================

import numpy as np
import cv2
import math
import random

class LightLeakV4:
    """
    Ultra Pro Max Light-Leak Generator:
      - Combines procedural leaks with film-scan-style dispersion
      - Directionally biased streaks (top/bottom/left/right)
      - Soft film burn + vignette inversion
      - Realistic flicker + rolling movement
    """

    def __init__(self,
                 leak_strength: float = 0.35,
                 color_shift: float = 0.25,
                 movement_speed: float = 0.35,
                 streak_strength: float = 0.25,
                 edge_burn_strength: float = 0.45,
                 seed: int = 2024):
        
        self.leak_strength = float(leak_strength)
        self.color_shift = float(color_shift)
        self.movement_speed = float(movement_speed)
        self.streak_strength = float(streak_strength)
        self.edge_burn_strength = float(edge_burn_strength)
        self.frame_index = 0
        self.rng = np.random.default_rng(seed)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _procedural_gradient(self, h, w, direction="left"):
        """
        Generates a smooth light-leak gradient from a chosen side.
        """
        if direction == "left":
            ramp = np.linspace(1, 0, w)[None, :]
        elif direction == "right":
            ramp = np.linspace(0, 1, w)[None, :]
        elif direction == "top":
            ramp = np.linspace(1, 0, h)[:, None]
        else:  # bottom
            ramp = np.linspace(0, 1, h)[:, None]
        grad = cv2.GaussianBlur(ramp.astype(np.float32), (0,0), 60)
        return grad

    # ------------------------------------------------------------
    def _chromatic_dispersion(self, leak):
        """
        Creates R/G/B offset leakage like real film overexposure.
        """
        h, w = leak.shape
        shift = int(6 * self.color_shift)
        r = np.roll(leak, shift, axis=1)
        g = leak
        b = np.roll(leak, -shift, axis=1)
        rgb = np.stack([b, g, r], axis=2)
        return rgb

    # ------------------------------------------------------------
    def _directional_streak(self, h, w):
        """
        Exaggerated horizontal streak leaks (lens flare-like).
        """
        streak = np.zeros((h, w), np.float32)
        y = random.randint(0, h-1)
        for _ in range(3):
            width = random.randint(15, 50)
            y0 = np.clip(y + random.randint(-20, 20), 0, h-1)
            streak[y0:y0+3, :] += np.linspace(0.7, 0.0, w)
        streak = cv2.GaussianBlur(streak, (0,0), 22)
        return streak * self.streak_strength

    # ------------------------------------------------------------
    def _edge_burn(self, h, w):
        """
        Burned film edges — inverted vignette glow.
        """
        xs = np.linspace(-1, 1, w)
        ys = np.linspace(-1, 1, h)
        xv, yv = np.meshgrid(xs, ys)
        dist = np.sqrt(xv**2 + yv**2)
        burn = np.clip(1.4 - dist*1.2, 0.0, 1.0)
        burn = cv2.GaussianBlur(burn.astype(np.float32), (0,0), 35)
        return burn * self.edge_burn_strength

    # ------------------------------------------------------------
    def _blend_screen(self, base, leak):
        return 1 - (1-base) * (1-leak)

    # ------------------------------------------------------------
    def _blend_softlight(self, base, leak):
        return (1 - 2*leak) * base**2 + 2*leak * base

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Combines:
          - procedural leak
          - chromatic dispersion
          - streaks
          - burn edges
          - flicker + motion
        """
        f = self._ensure_f32(img)
        h, w = f.shape[:2]

        # rolling animation movement
        shift = int(self.frame_index * self.movement_speed)
        self.frame_index += 1

        # 1) base procedural leak
        direction = random.choice(["left","right","top","bottom"])
        grad = self._procedural_gradient(h, w, direction)
        grad = np.roll(grad, shift, axis=1)

        # 2) chromatic dispersion
        leak_rgb = self._chromatic_dispersion(grad)

        # 3) streak enhancement
        streak = self._directional_streak(h, w)
        leak_rgb += streak[...,None]

        # 4) edge burn
        burn = self._edge_burn(h, w)
        leak_rgb += burn[...,None]

        # 5) normalize leak strength
        leak_rgb *= self.leak_strength

        # 6) flicker pulse
        flicker = 1.0 + self.rng.normal() * 0.05
        leak_rgb *= flicker

        # 7) blend (screen + softlight)
        screen = self._blend_screen(f, leak_rgb)
        soft = self._blend_softlight(f, leak_rgb * 0.5)
        out = (screen * 0.7 + soft * 0.3)
        return np.clip(out, 0.0, 1.0)

