# ================================================================
# CHUNK 75Q-A — FILM DAMAGE ENGINE V5 (Emulsion, Scratches, Dust)
#   • Physical emulsion lift simulation (perlin-style warping)
#   • Chemical stain map (red/orange film bleed)
#   • Vertical micro-scratches with random interruption
#   • Gate dust occlusion (randomized, blurred, additive)
#   • Film density aging curve
#   • ACES-safe blend logic
# ================================================================

import numpy as np
import cv2

class FilmDamageV5:
    """
    Ultra-Pro-Max Film Damage Engine:
      - Organic, non-destructive damage simulation
      - Layers: emulsion warp, stains, scratches, dust, density loss
      - Fully ACES compatible
    """

    def __init__(self,
                 damage_strength: float = 0.35,
                 scratch_density: float = 0.12,
                 dust_amount: float = 0.08,
                 stain_intensity: float = 0.25,
                 emulsion_warp: float = 0.012,
                 seed: int = 777):
        
        self.damage_strength = float(damage_strength)
        self.scratch_density = float(scratch_density)
        self.dust_amount = float(dust_amount)
        self.stain_intensity = float(stain_intensity)
        self.emulsion_warp = float(emulsion_warp)
        self.rng = np.random.default_rng(seed)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _emulsion_lift(self, img):
        """
        Small coordinate warp → simulates emulsion tearing/stretch.
        """
        h, w = img.shape[:2]
        # Coarse Perlin-like noise
        noise = self.rng.normal(0, 1, (h//8, w//8)).astype(np.float32)
        noise = cv2.resize(noise, (w, h), interpolation=cv2.INTER_CUBIC)
        noise = cv2.GaussianBlur(noise, (0,0), 12)
        dx = noise * self.emulsion_warp * w
        dy = noise * self.emulsion_warp * h
        xs, ys = np.meshgrid(np.arange(w), np.arange(h))
        map_x = (xs + dx).astype(np.float32)
        map_y = (ys + dy).astype(np.float32)
        warped = cv2.remap(img, map_x, map_y,
        interpolation=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_REFLECT)
        return warped

    # ------------------------------------------------------------
    def _stain_layer(self, img):
        """
        Warm red/orange chemical bleed, localized variation.
        """
        h, w = img.shape[:2]
        base = self.rng.normal(0, 1, (h//12, w//12)).astype(np.float32)
        base = cv2.resize(base, (w, h), interpolation=cv2.INTER_CUBIC)
        base = cv2.GaussianBlur(base, (0,0), 22)
        stain = np.clip(base, 0, 1)**1.5
        # warm hue
                 # B, G, R
        stain_rgb = np.stack([
            stain * 0.10,  # blue
            stain * 0.25,  # green
            stain * 1.00   # red
        ], axis=2)
        return stain_rgb * self.stain_intensity

    # ------------------------------------------------------------
    def _scratch_layer(self, img):
        """
        Vertical micro-scratches.
        """
        h, w = img.shape[:2]
        scratch_map = np.zeros((h, w), np.float32)
        count = int(w * self.scratch_density)
        for _ in range(count):
            x = self.rng.integers(0, w)
            # random scratch intensity
            col = self.rng.uniform(0.15, 0.45)
            # random discontinuity
            discontinuity = self.rng.uniform(0.2, 0.65)
            for y in range(h):
                if self.rng.random() > discontinuity:
                    scratch_map[y, x] = col
        scratch_map = cv2.GaussianBlur(scratch_map, (0,0), 1.2)
        return np.repeat(scratch_map[...,None], 3, axis=2)

    # ------------------------------------------------------------
    def _dust_layer(self, img):
        """
        Circular dust, softened edges.
        """
        h, w = img.shape[:2]
        dust = np.zeros((h, w), np.float32)
        count = int((h*w) * self.dust_amount * 0.00015)
        for _ in range(count):
            cx = self.rng.integers(0, w)
            cy = self.rng.integers(0, h)
            r = self.rng.uniform(2, 11)
            yy, xx = np.ogrid[:h, :w]
            mask = ((xx - cx)**2 + (yy - cy)**2) <= r*r
            dust[mask] += self.rng.uniform(0.25, 1.0)
        dust = cv2.GaussianBlur(dust, (0,0), 3.0)
        return np.repeat(np.clip(dust, 0, 1)[...,None], 3, axis=2)

    # ------------------------------------------------------------
    def _density_fade(self, img):
        """
        Subtle loss of film density (aging).
        """
        fade = np.clip(1.0 - self.damage_strength * 0.18, 0.75, 1.0)
        return img * fade

    # ------------------------------------------------------------
    def apply(self, img):
        f = self._ensure_f32(img)
        # 1) Emulsion warp
        warped = self._emulsion_lift(f)
        # 2) Layers
        stains = self._stain_layer(f)
        scratches = self._scratch_layer(f)
        dust = self._dust_layer(f)
        # 3) Film density fade
        faded = self._density_fade(warped)
        # 4) Composite (ACES-safe)
        out = faded + stains + scratches + dust
        return np.clip(out, 0.0, 1.0)

# ================================================================
# WRAPPER FOR AIFusionPipeline
# ================================================================
class FilmDamageModuleV5:
    def __init__(self):
        self.engine = FilmDamageV5()

    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

