# ================================================================
# CHUNK 75Q-B — GATE-WEAVE ENGINE V5 (Mechanical Film Jitter)
#   • Sub-pixel jitter based on smooth noise
#   • Slow rotational drift (projector instability)
#   • Variable frequency weave (per-reel simulation)
#   • ACES-safe warp remapping
# ================================================================

import numpy as np
import cv2
import math

class GateWeaveV5:
    """
    Ultra-Pro-Max Gate Weave Engine:
      - Simulates film jitter and instability from mechanical transport
      - Includes: translation jitter + rotational drift + per-frame noise
      - Designed to be subtle, realistic, and ACES-safe
    """

    def __init__(self,
                 jitter_amplitude: float = 0.65,
                 rotation_amplitude: float = 0.12,
                 frequency: float = 0.42,
                 seed: int = 991):
        
        self.jitter_amp = float(jitter_amplitude)
        self.rot_amp = float(rotation_amplitude)
        self.freq = float(frequency)

        self.frame_index = 0
        self.rng = np.random.default_rng(seed)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _compute_offsets(self):
        """
        Uses smooth sinusoid + noise to generate physical gate motion.
        """
        t = self.frame_index * self.freq * 0.05

        # Smooth sinusoidal drift
        dx_sin = math.sin(t * 2.1) * self.jitter_amp
        dy_sin = math.cos(t * 1.7) * self.jitter_amp

        # Low-frequency Perlin-like jitter
        dx_noise = self.rng.normal(0, 0.25) * self.jitter_amp
        dy_noise = self.rng.normal(0, 0.25) * self.jitter_amp

        # Rotation drift
        rot = math.sin(t * 1.3) * self.rot_amp

        self.frame_index += 1
        return dx_sin + dx_noise, dy_sin + dy_noise, rot

    # ------------------------------------------------------------
    def _warp(self, img, dx, dy, rot):
        h, w = img.shape[:2]

        cx, cy = w/2, h/2

        # Build affine transform
        M_rot = cv2.getRotationMatrix2D((cx, cy), rot, 1.0)
        M_rot[0,2] += dx
        M_rot[1,2] += dy

        warped = cv2.warpAffine(
            img, M_rot, (w, h),
            flags=cv2.INTER_LINEAR,
            borderMode=cv2.BORDER_REFLECT
        )

        return warped

    # ------------------------------------------------------------
    def apply(self, img):
        f = self._ensure_f32(img)

        # 1) Compute offsets for this frame
        dx, dy, rot = self._compute_offsets()

        # 2) Apply warp
        out = self._warp(f, dx, dy, rot)

        return np.clip(out, 0.0, 1.0)

# ================================================================
# WRAPPER FOR AIFusionPipeline
# ================================================================
class GateWeaveModuleV5:
    def __init__(self):
        self.engine = GateWeaveV5()

    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

