# ================================================================
# CHUNK 75K — ULTRA FILM LUT EMULATION ENGINE V5
# Film Stock Emulation (Mathematical, ACES-Safe)
# Provides:
#   • Kodak 2383 Print Film Emulation
#   • Kodak Vision3 (250D, 500T) Color Science Model
#   • Fuji Eterna (250D / 3513) Film Response Model
#   • Density → Contrast shaping
#   • Film saturation curve (logarithmic, not linear)
#   • Per-channel spectral rolloff
#   • Halation-aware highlight shaping (works with HalationV3)
# ================================================================

import numpy as np
import cv2

class FilmEmulationV5:
    """
    Ultra-level Film Emulation:
      - Mathematical reconstruction of film density curves
      - Channel-dependent spectral rolloff
      - Built-in 2383/ Vision3 / Eterna models
    """

    # ------------------------------------------------------------------
    # MAIN FILM STOCK PRESETS (CURVES TUNED TO FILM CHARACTERISTICS)
    # ------------------------------------------------------------------
    PRESET_KODAK_2383 = {
        "contrast": 1.32,
        "toe": 0.12,
        "shoulder": 0.82,
        "sat": 1.18,
        "red_shift": 0.015,
        "green_shift": -0.005,
        "blue_shift": -0.012
    }

    PRESET_VISION3_250D = {
        "contrast": 1.18,
        "toe": 0.16,
        "shoulder": 0.78,
        "sat": 1.22,
        "red_shift": 0.020,
        "green_shift": -0.003,
        "blue_shift": -0.008
    }

    PRESET_VISION3_500T = {
        "contrast": 1.10,
        "toe": 0.20,
        "shoulder": 0.75,
        "sat": 1.28,
        "red_shift": 0.038,
        "green_shift": -0.012,
        "blue_shift": -0.003
    }

    PRESET_FUJI_ETERNA = {
        "contrast": 1.15,
        "toe": 0.17,
        "shoulder": 0.79,
        "sat": 1.10,
        "red_shift": -0.008,
        "green_shift": 0.005,
        "blue_shift": 0.012
    }

    # ------------------------------------------------------------------
    def __init__(self, preset="kodak_2383", strength=1.0):
        self.preset_name = preset.lower()
        self.strength = float(np.clip(strength, 0.0, 1.0))

        if self.preset_name == "kodak_2383":
            self.preset = FilmEmulationV5.PRESET_KODAK_2383
        elif self.preset_name == "vision3_250d":
            self.preset = FilmEmulationV5.PRESET_VISION3_250D
        elif self.preset_name == "vision3_500t":
            self.preset = FilmEmulationV5.PRESET_VISION3_500T
        elif self.preset_name == "fuji_eterna":
            self.preset = FilmEmulationV5.PRESET_FUJI_ETERNA
        else:
            self.preset = FilmEmulationV5.PRESET_KODAK_2383

    # ------------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------------
    def _filmic_curve(self, x, toe, shoulder, contrast):
        """
        Combined toe + linear + shoulder curve.
        Pure math version of print-film density curve.
        """
        # Toe curve
        t = np.power(np.clip(x, 0, 1), toe)

        # Shoulder curve
        s = 1.0 - np.power(np.clip(1.0 - x, 0, 1), shoulder)

        # Mix both with contrast
        out = (t * (1 - contrast)) + (s * contrast)
        return np.clip(out, 0.0, 1.0)

    # ------------------------------------------------------------------
    def _apply_channel_shifts(self, img):
        r, g, b = img[...,2], img[...,1], img[...,0]

        r2 = np.clip(r + self.preset["red_shift"], 0, 1)
        g2 = np.clip(g + self.preset["green_shift"], 0, 1)
        b2 = np.clip(b + self.preset["blue_shift"], 0, 1)

        return np.stack([b2, g2, r2], axis=2)

    # ------------------------------------------------------------------
    def _sat_curve(self, img):
        """
        Film saturation model:
          - saturates midtones more
          - protects highlights from neon blowout
        """
        hsv = cv2.cvtColor(img, cv2.COLOR_RGB2HSV)
        h, s, v = cv2.split(hsv)

        s = s.astype(np.float32) / 255.0

        # Midtone saturation boost
        s = np.power(s, 0.85) * self.preset["sat"]

        # Highlight compression
        v_norm = v.astype(np.float32) / 255.0
        compress = np.clip((v_norm - 0.65)/0.35, 0.0, 1.0)
        s *= (1.0 - compress * 0.4)

        s = np.clip(s, 0.0, 1.0)
        s = (s * 255).astype(np.uint8)

        hsv_new = cv2.merge([h, s, v])
        return cv2.cvtColor(hsv_new, cv2.COLOR_HSV2RGB)

    # ------------------------------------------------------------------
    def apply(self, img):
        """
        Full Ultra Film Emulation:
          1. Apply filmic contrast curve
          2. Apply channel spectral shifts
          3. Apply saturation model
          4. Blend with original based on strength
        """
        f = self._ensure_f32(img)

        # 1 — Film contrast curve
        toe = self.preset["toe"]
        shoulder = self.preset["shoulder"]
        contrast = self.preset["contrast"]

        film_curve = self._filmic_curve(f, toe, shoulder, contrast)

        # 2 — Channel spectral shifts
        film_shift = self._apply_channel_shifts(film_curve)

        # 3 — Film saturation
        film_sat = self._sat_curve(film_shift)

        # 4 — Strength blend
        out = f * (1.0 - self.strength) + film_sat * self.strength
        return np.clip(out, 0.0, 1.0)

# ================================================================
# WRAPPER FOR AIFusionPipeline
# ================================================================
class FilmEmulationModuleV5:
    def __init__(self, preset="kodak_2383", strength=1.0):
        self.engine = FilmEmulationV5(preset=preset, strength=strength)
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

