# ================================================================
# CHUNK 75R — FILM GATE WEAVE / MICRO-JITTER ENGINE V3
# Provides:
#   • Analog film gate drift (sub-pixel x/y shifts)
#   • Slow oscillation “breathing” movement
#   • Micro jitter randomness (Gaussian; film-like)
#   • Exposure flutter simulation
#   • Zero-shake stabilization safe (post-process only)
# ================================================================

import numpy as np
import cv2
import math
import random

class FilmGateWeaveV3:
    """
    Ultra Film Gate Weave Engine:
      - Emulates analog film jitter using subpixel remaps
      - Adds breathing oscillation (0.1–0.4 Hz)
      - Exposure flutter (0.5–1% intensity variance)
      - Smooth time-continuous movement (not digital shaking)
    """
      
    def __init__(self,
                 max_jitter_px: float = 0.85,
                 breathing_strength: float = 0.35,
                 jitter_sigma: float = 0.25,
                 flutter_strength: float = 0.012):
        # Sub-pixel drift
        self.max_jitter = float(max_jitter_px)
        self.jitter_sigma = float(jitter_sigma)

        # Slow oscillation movement
        self.breathing_strength = float(breathing_strength)
          # random breathing frequency between 0.12–0.36 Hz
        self.breath_freq = random.uniform(0.12, 0.36)

        # Exposure flutter strength
        self.flutter_strength = float(flutter_strength)

        # internal frame counter
        self.t = 0.0

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _compute_offsets(self):
        """
        Computes analog jitter offsets for current frame.
        """
        # soft random jitter
        jx = np.random.normal(0, self.jitter_sigma)
        jy = np.random.normal(0, self.jitter_sigma)

        jx = np.clip(jx, -self.max_jitter, self.max_jitter)
        jy = np.clip(jy, -self.max_jitter, self.max_jitter)

        # breathing oscillation
        breath = math.sin(self.t * self.breath_freq * 2 * math.pi)
        breath *= self.breathing_strength

        self.t += 1.0  # increment time

        return jx + breath, jy + breath * 0.85

    # ------------------------------------------------------------
    def _apply_subpixel_shift(self, img, dx, dy):
        """
        Subpixel shift using remap (film-correct and smooth).
        """
        h, w = img.shape[:2]

        xs = (np.arange(w) + dx).astype(np.float32)
        ys = (np.arange(h) + dy).astype(np.float32)

        xv, yv = np.meshgrid(xs, ys)

        shifted = cv2.remap(
            img,
            xv, yv,
            interpolation=cv2.INTER_LINEAR,
            borderMode=cv2.BORDER_REFLECT
        )

        return shifted

    # ------------------------------------------------------------
    def _flutter(self, img):
        """
        Micro exposure flutter (≈ 0.5–1% variation)
        """
        f = 1.0 + np.random.uniform(
            -self.flutter_strength,
            self.flutter_strength
        )
        return np.clip(img * f, 0.0, 1.0)

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Full jitter + breathing + flutter application.
        """
        f = self._ensure_f32(img)

        # 1 — compute jitter & breathing
        dx, dy = self._compute_offsets()

        # 2 — apply subpixel remap
        shifted = self._apply_subpixel_shift(f, dx, dy)

        # 3 — exposure flutter
        out = self._flutter(shifted)

        return out

# ================================================================
# WRAPPER MODULE — Film Gate Weave V3
# ================================================================
class FilmGateWeaveModuleV3:
    def __init__(self):
        self.engine = FilmGateWeaveV3()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

