# ================================================================
# CHUNK 75V — ANALOG FILM INSTABILITY ENGINE V4
# Provides:
#   • Gate weave simulation (X/Y jitter, film perforation wobble)
#   • Film breathing (scale micro-oscillation 0.1–0.4%)
#   • Shutter flicker / exposure flutter (±1–3% brightness)
#   • Registration jitter (randomized sub-pixel offsets)
#   • Temporal coherence (smooth analog mechanical feel)
#   • Fully ACES-compatible post-FX module
# ================================================================

import numpy as np
import cv2
import math
import random

class FilmInstabilityV4:
    """
    Ultra-Pro-Max analog instability simulator.
    Designed to emulate:
       - 35mm projector gate weave
       - film scanner mechanical drift
       - slight transport misalignment
       - shutter exposure flutter
    """
    def __init__(self,
                 weave_strength: float = 0.65,     # subpixel jitter amplitude
                 breathing_strength: float = 0.002, # 0.2% default
                 flutter_strength: float = 0.015,  # brightness flicker (1.5%)
                 temporal_smooth: float = 0.92):   # smooth drift
        self.weave_strength = float(weave_strength)
        self.breathing_strength = float(breathing_strength)
        self.flutter_strength = float(flutter_strength)
        self.temporal_smooth = float(temporal_smooth)
        # temporal state
        self.weave_x_prev = 0.0
        self.weave_y_prev = 0.0
        self.scale_prev = 1.0
        self.flutter_prev = 1.0

    # ------------------------------------------------------------
    def _smooth_rand(self, prev, amp):
        """
        Generates analog-feeling drift using smooth random walk.
        """
        target = (random.random() - 0.5) * 2.0 * amp
        out = prev * self.temporal_smooth + target * (1 - self.temporal_smooth)
        return out

    # ------------------------------------------------------------
    def _compute_gate_weave(self):
        x = self._smooth_rand(self.weave_x_prev, self.weave_strength)
        y = self._smooth_rand(self.weave_y_prev, self.weave_strength)
        self.weave_x_prev = x
        self.weave_y_prev = y
        return x, y

    # ------------------------------------------------------------
    def _compute_breathing(self):
        """
        Micro-scale oscillation, film scanning breathing.
        """
        s = self._smooth_rand(self.scale_prev - 1.0, self.breathing_strength) + 1.0
        self.scale_prev = s
        return s

    # ------------------------------------------------------------
    def _compute_flutter(self):
        """
        ± flutter_strength brightness jitter.
        """
        f = self._smooth_rand(self.flutter_prev - 1.0, self.flutter_strength) + 1.0
        self.flutter_prev = f
        return f

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def apply(self, img):
        """
        FULL instability pipeline:
          1. compute weave offsets
          2. compute breathing scale
          3. compute exposure flutter
          4. warp transform image
        """
        f = self._ensure_f32(img)
        h, w = f.shape[:2]

        # --- 1) Gate Weave ---
        dx, dy = self._compute_gate_weave()
        # --- 2) Breathing Scale ---
        s = self._compute_breathing()
        # --- 3) Flutter ---
        fl = self._compute_flutter()
        # --- 4) Build Warp Matrix ---
        cx, cy = w / 2, h / 2
        M = cv2.getRotationMatrix2D((cx, cy), 0, s)
        # apply jitter
        M[0,2] += dx
        M[1,2] += dy

        warped = cv2.warpAffine(f, M, (w, h), flags=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_REFLECT)

        # --- 5) Apply brightness flutter ---
        warped *= fl

        return np.clip(warped, 0.0, 1.0)

# ================================================================
# WRAPPER MODULE
# ================================================================
class FilmInstabilityModuleV4:
    def __init__(self):
        self.engine = FilmInstabilityV4()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

