# ================================================================
# CHUNK 75W — FILM DAMAGE & VINTAGE ARTIFACT ENGINE V5
# Provides:
#   • Vertical & horizontal scratches (persistent + random)
#   • Dust particles (1–2 frame flickers)
#   • Gate hairs on reel edges
#   • Emulsion burn spots (soft glowing artifacts)
#   • Sprocket-edge halation + film edge fog
#   • Temporal persistence engine (scratches last multiple frames)
#   • Fully ACES-compatible, integrated post module
# ================================================================

import numpy as np
import cv2
import random

class FilmDamageV5:
    """
    Ultra film-damage simulator:
      - multi-type scratches
      - dust flicker
      - gate hairs
      - burn marks
      - edge halation
    """
    def __init__(self,
                 scratch_density: float = 0.004,
                 dust_density: float = 0.002,
                 burn_chance: float = 0.0003,
                 edge_fog_strength: float = 0.12,
                 persistence: int = 24):  # frames scratches persist
        self.scratch_density = scratch_density
        self.dust_density = dust_density
        self.burn_chance = burn_chance
        self.edge_fog_strength = edge_fog_strength
        self.persistence = persistence
        # persistent scratches
        self.active_scratches = []  # list of dict {x, width, opacity, ttl}
    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _add_scratches(self, h, w):
        """Spawn vertical scratches randomly."""
        new_scratches = []
        count = int(w * self.scratch_density)
        for _ in range(count):
            x = random.randint(0, w - 1)
            width = random.uniform(1.0, 3.0)
            opacity = random.uniform(0.15, 0.4)
            new_scratches.append({
                "x": x,
                "width": width,
                "opacity": opacity,
                "ttl": self.persistence
            })
        self.active_scratches.extend(new_scratches)

    # ------------------------------------------------------------
    def _render_scratches(self, frame):
        h, w = frame.shape[:2]
        scratch_map = np.zeros((h, w), np.float32)
        for s in list(self.active_scratches):
            x = int(s["x"])
            wth = int(max(1, s["width"]))
            scratch_map[:, x:x+wth] += s["opacity"]
            s["ttl"] -= 1
            if s["ttl"] <= 0:
                self.active_scratches.remove(s)
        scratch_map = cv2.GaussianBlur(scratch_map, (0,0), sigmaX=1.2)
        return np.clip(scratch_map, 0.0, 1.0)

    # ------------------------------------------------------------
    def _render_dust(self, h, w):
        """Short-lived dust specs."""
        dust_map = np.zeros((h, w), np.float32)
        count = int((h*w) * self.dust_density)
        for _ in range(count):
            x = random.randint(0, w-1)
            y = random.randint(0, h-1)
            dust_map[y, x] = random.uniform(0.3, 0.8)
        dust_map = cv2.GaussianBlur(dust_map, (0,0), sigmaX=0.8)
        return np.clip(dust_map, 0.0, 1.0)

    # ------------------------------------------------------------
    def _render_gate_hair(self, h, w):
        """Classic 35mm hair on left edge."""
        width = random.randint(3, 7)
        opacity = random.uniform(0.05, 0.15)
        hair = np.zeros((h, w), np.float32)
        hair[:, :width] = opacity
        hair = cv2.GaussianBlur(hair, (0,0), sigmaX=2)
        return hair

    # ------------------------------------------------------------
    def _render_burn_mark(self, h, w):
        """Occasional glowing emulsion burn spot."""
        if random.random() > self.burn_chance:
            return np.zeros((h, w), np.float32)
        mask = np.zeros((h, w), np.float32)
        cx = random.randint(0, w-1)
        cy = random.randint(0, h-1)
        rad = random.randint(30, 90)
        cv2.circle(mask, (cx, cy), rad, random.uniform(0.3, 0.6), -1)
        mask = cv2.GaussianBlur(mask, (0,0), sigmaX=20)
        return np.clip(mask, 0.0, 1.0)

    # ------------------------------------------------------------
    def _render_edge_fog(self, h, w):
        """Foggy film-edge halation."""
        fog = np.zeros((h, w), np.float32)
        border = int(w * 0.04)
        fog[:, :border] = 1.0
        fog[:, w-border:] = 1.0
        fog = cv2.GaussianBlur(fog, (0,0), sigmaX=25)
        return fog * self.edge_fog_strength

    # ------------------------------------------------------------
    def apply(self, img):
        f = self._ensure_f32(img)
        h, w = f.shape[:2]
        # 1) Spawn scratches
        self._add_scratches(h, w)
        # 2) Render maps
        scratches = self._render_scratches(f)
        dust = self._render_dust(h, w)
        hair = self._render_gate_hair(h, w)
        burn = self._render_burn_mark(h, w)
        fog = self._render_edge_fog(h, w)
        # 3) Composite all
        dmg = np.clip(scratches + dust + hair + burn + fog, 0.0, 1.0)
        dmg_rgb = np.repeat(dmg[...,None], 3, axis=2)
        out = f * (1.0 - dmg_rgb) + (f * 0.7) * dmg_rgb
        return np.clip(out, 0.0, 1.0)

# ================================================================
# WRAPPER MODULE
# ================================================================
class FilmDamageModuleV5:
    def __init__(self):
        self.engine = FilmDamageV5()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

