# ================================================================
# CHUNK 75X — ANALOG GATE WARP ENGINE V5
# Provides:
#   • Heat-warp shimmer (like old film passing hot projector)
#   • Gate-pressure warp (wavy deformation near edges)
#   • Reel transport wobble (oscillating offset patterns)
#   • Luminance-influenced deformation (brighter areas warp more)
#   • Temporal coherence (warp evolves smoothly, not jumpy)
#   • Motion-aware suppression (avoid warping faces)
#   • ACES-safe output
# ================================================================

import numpy as np
import cv2
import random
import math

class GateWarpV5:
    """
    Ultra-level analog gate warp simulator.
    Includes heat shimmer, projector gate deformation, and reel jitter.
    """
    def __init__(
        self,
        heat_intensity: float = 0.004,
        gate_curve: float = 0.012,
        wobble_frequency: float = 0.7,
        warp_scale: float = 3.5,
        motion_protect: float = 0.65,
        temporal_smooth: float = 0.90
    ):
        self.heat_intensity = heat_intensity
        self.gate_curve = gate_curve
        self.wobble_frequency = wobble_frequency
        self.warp_scale = warp_scale
        self.motion_protect = motion_protect
        self.temporal_smooth = temporal_smooth
        # temporal noise fields
        self.prev_dx = None
        self.prev_dy = None
        self.t = 0.0
    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _generate_heat_noise(self, h, w):
        """Base perlin-like random noise for heat shimmer."""
        noise = np.random.randn(h, w).astype(np.float32)
        noise = cv2.GaussianBlur(noise, (0,0), sigmaX=18)
        noise = cv2.GaussianBlur(noise, (0,0), sigmaX=12)
        return noise

    # ------------------------------------------------------------
    def _generate_gate_curve(self, h, w):
        """Simulate curvature from projector gate pressure."""
        xs = (np.linspace(-1, 1, w)) ** 2
        ys = (np.linspace(-1, 1, h)) ** 2
        xv, yv = np.meshgrid(xs, ys)
        return (xv + yv).astype(np.float32)

    # ------------------------------------------------------------
    def _motion_mask_protect(self, motion_mask, h, w):
        """
        motion_mask: None or 0..1 motion
        Return suppression map: 1 = full warp, 0 = protect area.
        """
        if motion_mask is None:
            return np.ones((h, w), np.float32)
        # blur mask so it's not harsh
        m = cv2.GaussianBlur(motion_mask, (0,0), sigmaX=6)
        # invert → high motion = protect
        return 1.0 - (m * self.motion_protect)

    # ------------------------------------------------------------
    def apply(self, img, motion_mask=None):
        """Apply analog gate/heat warp."""
        f = self._ensure_f32(img)
        h, w = f.shape[:2]
        # --------------------------------------------------------
        # 1) Generate noise & base fields
        heat_noise = self._generate_heat_noise(h, w)
        gate_field = self._generate_gate_curve(h, w)
        # reel wobble (slow oscillation)
        self.t += 0.015
        wobble = math.sin(self.t * self.wobble_frequency) * 0.6
        # --------------------------------------------------------
        # 2) Combine displacement fields
        dx = (
            heat_noise * self.heat_intensity * self.warp_scale +
            gate_field * self.gate_curve * self.warp_scale +
            wobble
        )
        dy = (
            heat_noise * self.heat_intensity * 0.5 +
            gate_field * self.gate_curve * 0.4
        )
        # --------------------------------------------------------
        # 3) Temporal smoothing
        if self.prev_dx is not None:
            dx = dx * (1 - self.temporal_smooth) + self.prev_dx * self.temporal_smooth
        if self.prev_dy is not None:
            dy = dy * (1 - self.temporal_smooth) + self.prev_dy * self.temporal_smooth
        self.prev_dx = dx
        self.prev_dy = dy
        # --------------------------------------------------------
        # 4) Motion-aware protection
        protect = self._motion_mask_protect(motion_mask, h, w)
        dx *= protect
        dy *= protect
        # --------------------------------------------------------
        # 5) Build remap grids
        xs = np.arange(w).astype(np.float32)
        ys = np.arange(h).astype(np.float32)
        xv, yv = np.meshgrid(xs, ys)
        map_x = xv + dx
        map_y = yv + dy
        # --------------------------------------------------------
        # 6) Remap (warp)
        warped = cv2.remap(f, map_x, map_y,
        interpolation=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_REFLECT)
        return np.clip(warped, 0.0, 1.0)

# ================================================================
# WRAPPER MODULE FOR AIFusionPipeline
# ================================================================
class GateWarpModuleV5:
    def __init__(self):
        self.engine = GateWarpV5()
    def apply(self, frame_float01, motion_mask=None):
        return self.engine.apply(frame_float01, motion_mask)

