# ================================================================
# CHUNK 75Y — ANALOG FRAME TRANSPORT JITTER ENGINE V4
# Provides:
#   • Horizontal frame jitter (mechanical reel wobble)
#   • Vertical micro-judder (transport lift vibration)
#   • Gate-slip drift (slow sliding offset)
#   • Random frame acceleration/deceleration artifacts
#   • Temporal misregistration (analog frame offset memory)
#   • Jitter protection for faces / subjects (motion-aware)
# ================================================================

import numpy as np
import cv2
import math
import random

class TransportJitterV4:
    """
    Ultra-grade analog frame jitter engine.
    Simulates:
      - Reel wobble
      - Gate jitter
      - Misaligned transport
      - Temporal drift memory
    """
    def __init__(
        self,
        jitter_strength: float = 1.8,
        micro_judder_strength: float = 0.55,
        slip_strength: float = 0.35,
        accel_prob: float = 0.12,
        protect_strength: float = 0.70,
        temporal_decay: float = 0.87
    ):
        self.jitter_strength = jitter_strength
        self.micro_judder_strength = micro_judder_strength
        self.slip_strength = slip_strength
        self.accel_prob = accel_prob
        self.protect_strength = protect_strength
        self.temporal_decay = temporal_decay
        self.prev_jx = 0.0
        self.prev_jy = 0.0
        self.drift_x = 0.0
        self.drift_y = 0.0
        self.frame_index = 0

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _motion_protect(self, motion_mask, h, w):
        """
        Suppresses jitter on faces / subjects.
        """
        if motion_mask is None:
            return np.ones((h, w), np.float32)
        m = cv2.GaussianBlur(motion_mask, (0,0), sigmaX=6)
        return 1.0 - m * self.protect_strength

    # ------------------------------------------------------------
    def _compute_jitter_offsets(self):
        """
        Main analog jitter model.
        Combines:
          • random wobble
          • micro-judder
          • gate slip drift
          • occasional transport acceleration
          • temporal smoothing
        """
        self.frame_index += 1
        # 1) Base random jitter (per-frame)
        jx = (random.random() - 0.5) * self.jitter_strength
        jy = (random.random() - 0.5) * self.jitter_strength * 0.6
        # 2) Micro-judder (vertical oscillation)
        jy += math.sin(self.frame_index * 0.32) * self.micro_judder_strength
        # 3) Gate slip (slow drifting offset)
        self.drift_x += (random.random() - 0.5) * self.slip_strength * 0.02
        self.drift_y += (random.random() - 0.5) * self.slip_strength * 0.01
        # 4) Random acceleration / deceleration events
        if random.random() < self.accel_prob:
            jx *= 3.5
            jy *= 3.5
        # 5) Temporal smoothing
        jx = jx * (1 - self.temporal_decay) + self.prev_jx * self.temporal_decay
        jy = jy * (1 - self.temporal_decay) + self.prev_jy * self.temporal_decay
        self.prev_jx = jx
        self.prev_jy = jy
        return jx + self.drift_x, jy + self.drift_y

    # ------------------------------------------------------------
    def apply(self, img, motion_mask=None):
        """
        Apply analog film jitter & slippage.
        """
        f = self._ensure_f32(img)
        h, w = f.shape[:2]
        # motion protect map
        protect = self._motion_protect(motion_mask, h, w)
        # compute jitter
        jx, jy = self._compute_jitter_offsets()
        # attenuate jitter in protected areas
        jx_map = protect * jx
        jy_map = protect * jy
        # build remap grid
        xs = np.arange(w).astype(np.float32)
        ys = np.arange(h).astype(np.float32)
        xv, yv = np.meshgrid(xs, ys)
        map_x = xv + jx_map
        map_y = yv + jy_map
        warped = cv2.remap(f, map_x, map_y,
        interpolation=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_REFLECT)
        return np.clip(warped, 0.0, 1.0)

# ================================================================
# WRAPPER MODULE FOR AIFusionPipeline
# ================================================================
class TransportJitterModuleV4:
    def __init__(self):
        self.engine = TransportJitterV4()
    def apply(self, frame_float01, motion_mask=None):
        return self.engine.apply(frame_float01, motion_mask)

