# WRAPPER FOR FUSION PIPELINE (FilmGrainModuleV5)
# ================================================================
class FilmGrainModuleV5:
    def __init__(self):
        self.engine = FilmGrainV5()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

