# ================================================================
# CHUNK 76B — FILM GATE WEAVE + TRANSPORT JITTER ENGINE V4 (Ultra)
# Adds:
#   • X/Y gate weave based on analog sprocket drift
#   • Micro-rotation from film misalignment inside gate
#   • Low-frequency breathing drift (slow analog oscillation)
#   • Temporal coherence (no digital randomness)
#   • ACES-safe resampling (no color shifts)
#   • Works together with Grain V5 + Halation V3
# ================================================================

import numpy as np
import cv2
import math
import random

class FilmGateWeaveV4:
    """
    Ultra-grade film gate weave system.
    Emulates:
       - Film transport instability
       - Gate pressure plate jitter
       - Sprocket hole drift
       - Long-term mechanical drift (ARRICAM ST / LT style)
    """
    def __init__(
            self,
            jitter_strength: float = 0.65,
            rotation_strength: float = 0.12,
            breathing_strength: float = 0.08,
            temporal_smooth: float = 0.92,
            freq_low: float = 0.12,     # slow breathing freq
            freq_high: float = 2.75):   # sprocket jitter freq
        self.jitter_strength = jitter_strength
        self.rotation_strength = rotation_strength
        self.breathing_strength = breathing_strength
        self.temporal_smooth = temporal_smooth
        self.freq_low = freq_low
        self.freq_high = freq_high
        self.frame_idx = 0
        self.prev_offset = (0.0, 0.0)

    # ------------------------------------------------------------
    def _smooth_noise(self, t):
        """
        Generates 1D smooth evolving noise using sin layers.
        """
        n = (
            math.sin(t * self.freq_low) * 0.55 +
            math.sin(t * self.freq_high) * 0.35 +
            math.sin(t * (self.freq_high * 1.7)) * 0.10
        )
        return n

    # ------------------------------------------------------------
    def _compute_offsets(self):
        """
        Computes:
         - jitter_offset_x/y
         - rotation_offset
        """
        t = self.frame_idx * 0.016  # ~60 fps timing
        base = self._smooth_noise(t)
        jitter_x = base * self.jitter_strength * 0.8
        jitter_y = math.sin(t * 1.3) * self.jitter_strength * 0.6
        rot = base * self.rotation_strength * 0.02
        # temporal smoothing
        px, py = self.prev_offset
        jitter_x = jitter_x * (1 - self.temporal_smooth) + px * self.temporal_smooth
        jitter_y = jitter_y * (1 - self.temporal_smooth) + py * self.temporal_smooth
        self.prev_offset = (jitter_x, jitter_y)
        return jitter_x, jitter_y, rot

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Applies gate weave distortion.
        """
        f = img.astype(np.float32)
        h, w = f.shape[:2]
        # compute jitter + rotation
        jx, jy, rot = self._compute_offsets()
        # 1 — Translation matrix
        M_trans = np.float32([[1, 0, jx], [0, 1, jy]])
        warped = cv2.warpAffine(
            f, M_trans, (w, h),
            flags=cv2.INTER_LINEAR,
            borderMode=cv2.BORDER_REFLECT
        )
        # 2 — Rotation around center
        cx, cy = w / 2, h / 2
        M_rot = cv2.getRotationMatrix2D((cx, cy), rot, 1.0)
        warped = cv2.warpAffine(
            warped, M_rot, (w, h),
            flags=cv2.INTER_LINEAR,
            borderMode=cv2.BORDER_REFLECT
        )
        # update frame index
        self.frame_idx += 1
        return warped

# ================================================================
# WRAPPER FOR PIPELINE (FilmGateWeaveModuleV4)
# ================================================================
class FilmGateWeaveModuleV4:
    def __init__(self):
        self.engine = FilmGateWeaveV4()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

