# ================================================================
# CHUNK 76G — OPTICAL PRINTER GLOW ENGINE V4 (Photochemical Duplication Glow)
# Provides:
#   • Low-frequency diffusion glow (film printer characteristic)
#   • Soft density-lift based on luminance
#   • Subtle chroma compression (print film effect)
#   • Spectral diffusion (R > G > B)
#   • ACES-safe additive fusion
# ================================================================

import numpy as np
import cv2

class OpticalPrinterGlowV4:
    """
    Emulates glow introduced by photochemical optical printers.
    Distinct from bloom/halation:
      - much lower frequency
      - softer highlight lift
      - chroma compresses slightly (print film behavior)
    """

    def __init__(self,
                 glow_strength: float = 0.35,
                 diffusion_radius: float = 38.0,
                 chroma_compress: float = 0.12,
                 spectral_weight: tuple = (1.20, 1.05, 0.90)):  # R, G, B
        self.glow_strength = float(glow_strength)
        self.diffusion_radius = float(diffusion_radius)
        self.chroma_compress = float(chroma_compress)
        self.spectral_weight = spectral_weight

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _luminance(self, img):
        return 0.2126*img[...,2] + 0.7152*img[...,1] + 0.0722*img[...,0]

    # ------------------------------------------------------------
    def _diffuse(self, img):
        """Large-radius diffusion (film printer optical scatter)."""
        radius = max(1.0, self.diffusion_radius)
        blur = cv2.GaussianBlur(img, (0,0), sigmaX=radius, sigmaY=radius)
        return blur

    # ------------------------------------------------------------
    def _apply_spectral_weights(self, diff):
        """R diffuses strongest, B weakest (film spectral response)."""
        b = diff[...,0] * self.spectral_weight[2]
        g = diff[...,1] * self.spectral_weight[1]
        r = diff[...,2] * self.spectral_weight[0]
        return np.stack([b, g, r], axis=2)

    # ------------------------------------------------------------
    def _chroma_compression(self, img):
        """
        Mimics Kodak print-film chroma density compression.
        High saturation areas get very slightly pulled inward.
        """
        hsv = cv2.cvtColor(img, cv2.COLOR_RGB2HSV)
        h, s, v = cv2.split(hsv)

        # reduce saturation slightly near highlights
        lum = v.astype(np.float32) / 255.0
        reduce = np.clip((lum - 0.65) / 0.35, 0.0, 1.0)
        s2 = s * (1.0 - reduce * self.chroma_compress)

        hsv2 = cv2.merge([h, s2, v])
        out = cv2.cvtColor(hsv2, cv2.COLOR_HSV2RGB)
        return out.astype(np.float32) / 255.0

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Full optical printer glow simulation.
        """
        f = self._ensure_f32(img)

        # 1 — large diffusion
        diff = self._diffuse(f)

        # 2 — spectral bias
        diff_spectral = self._apply_spectral_weights(diff)

        # 3 — low-frequency glow extraction
        glow = diff_spectral - f
        glow = np.clip(glow, 0.0, 1.0)

        # 4 — chroma compression for print simulation
        f_chroma = self._chroma_compression(f)

        # 5 — final ACES-safe blend
        out = f_chroma + glow * self.glow_strength
        out = np.clip(out, 0.0, 1.0)

        return out

# ================================================================
# WRAPPER MODULE — OpticalPrinterGlowModuleV4
# ================================================================
class OpticalPrinterGlowModuleV4:
    def __init__(self):
        self.engine = OpticalPrinterGlowV4()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

