# ================================================================
# CHUNK 76N — Chemical Development Variance Engine V4
# Simulates:
#   • Push/Pull processing (±3 stops)
#   • Halide density drift (fine-grain vs coarse-grain)
#   • Developer exhaustion (magenta/green bias)
#   • Temperature-driven contrast expansion/compression
#   • Dye-cloud diffusion randomness
#   • ACES-safe film-science mapping for digital sources
# ================================================================

import numpy as np
import cv2
import random
import math

class ChemicalVarianceV4:
    """
    Ultra Film Chemistry Simulator:
      - Models Kodak Vision3-like chemical variations
      - Mimics real lab inconsistencies (temp, agitation, time)
      - Push/Pull shifts dynamic range + saturation + granularity
    """

    def __init__(self,
                 push_pull: float = 0.0,          # -3..+3 stops
                 halide_variance: float = 0.12,   # 0..1 (grain tightness)
                 developer_bias: float = 0.10,    # magenta-green drift
                 diffusion_strength: float = 0.18,# dye-cloud smear
                 contrast_variance: float = 0.10, # ±10% curve expansion
                 temp_variance: float = 0.05):    # film bath temperature drift
        self.push_pull = float(np.clip(push_pull, -3.0, 3.0))
        self.halide_variance = float(halide_variance)
        self.developer_bias = float(developer_bias)
        self.diffusion_strength = float(diffusion_strength)
        self.contrast_variance = float(contrast_variance)
        self.temp_variance = float(temp_variance)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _apply_push_pull(self, img):
        """
        Push (+) increases contrast + saturation.
        Pull (-) softens contrast + lowers saturation.
        Modeled as log-space contrast expansion.
        """
        pp = self.push_pull
        if abs(pp) < 1e-4:
            return img
        # logarithmic push/pull expansion factor
        factor = 1.0 + (pp * 0.22)
        # apply in log domain for film realism
        safe = np.clip(img, 1e-6, 1.0)
        logv = np.log(safe)
        adj = np.exp(logv * factor)
        return np.clip(adj, 0.0, 1.0)

    # ------------------------------------------------------------
    def _developer_exhaustion_bias(self, img):
        """
        Simulates chemical bath exhaustion:
          - magenta shift (R+B increase)
          - green weakness
        """
        bias = self.developer_bias
        if abs(bias) < 1e-4:
            return img
        r = img[...,2]
        g = img[...,1]
        b = img[...,0]
        r2 = r * (1.0 + bias)
        g2 = g * (1.0 - bias * 0.5)
        b2 = b * (1.0 + bias)
        return np.stack([b2, g2, r2], axis=2)

    # ------------------------------------------------------------
    def _halide_density_shift(self, img):
        """
        Adds local contrast variation like uneven film development.
        """
        strength = self.halide_variance
        noise = np.random.normal(0, strength*0.25, img.shape[:2]).astype(np.float32)
        noise = cv2.GaussianBlur(noise, (0,0), sigmaX=8)
        # convert noise into luminance multiplier
        mult = 1.0 + noise[...,None] * 0.65
        return np.clip(img * mult, 0.0, 1.0)

    # ------------------------------------------------------------
    def _temperature_contrast_shift(self, img):
        """
        Higher temp => higher contrast, lower temp => flatter.
        """
        t = self.temp_variance
        if abs(t) < 1e-5:
            return img
        factor = 1.0 + t * random.uniform(-1, 1)
        # simple power curve expansion
        return np.clip(img ** (1.0 / factor), 0.0, 1.0)

    # ------------------------------------------------------------
    def _dye_cloud_diffusion(self, img):
        """
        Blur R more than G more than B, matching real dye diffusion.
        """
        d = self.diffusion_strength
        if d <= 0:
            return img
        r = cv2.GaussianBlur(img[...,2], (0,0), sigmaX=10*d)
        g = cv2.GaussianBlur(img[...,1], (0,0), sigmaX=7*d)
        b = cv2.GaussianBlur(img[...,0], (0,0), sigmaX=4*d)
        return np.stack([b, g, r], axis=2)

    # ------------------------------------------------------------
    def _contrast_variation(self, img):
        """
        Random ±contrast changes in linear space.
        """
        c = self.contrast_variance
        factor = 1.0 + c * random.uniform(-1, 1)
        mean = 0.5
        out = (img - mean) * factor + mean
        return np.clip(out, 0.0, 1.0)

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Full chemical variance pipeline:
          1. Push/pull contrast simulation
          2. Developer exhaustion biasing
          3. Halide density variation
          4. Temperature contrast shift
          5. Dye cloud diffusion
          6. Randomized contrast modulation
        """
        f = self._ensure_f32(img)
        f = self._apply_push_pull(f)
        f = self._developer_exhaustion_bias(f)
        f = self._halide_density_shift(f)
        f = self._temperature_contrast_shift(f)
        f = self._dye_cloud_diffusion(f)
        f = self._contrast_variation(f)
        return np.clip(f, 0.0, 1.0)

# ================================================================
# WRAPPER MODULE – ChemicalVarianceModuleV4
# ================================================================
class ChemicalVarianceModuleV4:
    def __init__(self):
        self.engine = ChemicalVarianceV4()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

