# ================================================================
# CHUNK 76O — Negative Density Curve Engine V4
# Purpose:
#   • Simulate true film negative density response (Vision3 style)
#   • Includes:
#        – Toe curve (shadow lift & softening)
#        – Mid-tone contrast shaping (gamma slope)
#        – Shoulder compression (highlight preservation)
#        – Dye-coupler spectral density ratios (R/G/B non-linear)
#        – Log + linear hybrid mapping for ACES compatibility
#   • Required for realistic film negative pipelines
# ================================================================

import numpy as np
import cv2
import math

class NegativeDensityCurveV4:
    """
    Ultra-Pro-Max Negative Engine:
      - Reconstructs film density curve behavior from scanned negatives
      - Models Vision3 toe/shoulder/gamma using hybrid log-contrast curves
      - Per-channel spectral density shaping to mimic dye-coupler behaviors
    """

    def __init__(self,
                 toe_strength: float = 0.22,       # Shadow lift strength
                 shoulder_strength: float = 0.35,  # Highlight compression
                 gamma_mid: float = 1.32,          # Mid-tone contrast shaping
                 density_scale: float = 1.15,      # Film density amplitude
                 spectral_ratio=(1.00, 0.90, 0.78) # R,G,B density differences
    ):
        self.toe_strength = float(toe_strength)
        self.shoulder_strength = float(shoulder_strength)
        self.gamma_mid = float(gamma_mid)
        self.density_scale = float(density_scale)
        self.spectral_ratio = tuple(float(x) for x in spectral_ratio)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _toe_curve(self, x):
        """
        Vision3 style toe lift:
          - Lifts deepest shadows
          - Softens black roll-off
        """
        t = self.toe_strength
        return x ** (1.0 - t)

    # ------------------------------------------------------------
    def _shoulder_curve(self, x):
        """
        Shoulder compression:
          - Compresses extreme highlights gradually
          - Protects white detail
        """
        s = self.shoulder_strength
        return 1.0 - (1.0 - x)**(1.0 + s)

    # ------------------------------------------------------------
    def _mid_contrast(self, x):
        """
        Film gamma curve approximation.
        """
        return np.clip(x ** self.gamma_mid, 0.0, 1.0)

    # ------------------------------------------------------------
    def _apply_spectral_density(self, img):
        """
        Applies real-world negative density ratios:
          R absorbs the most → highest density
          G is medium
          B is lowest
        """
        b = img[...,0] * self.spectral_ratio[2]
        g = img[...,1] * self.spectral_ratio[1]
        r = img[...,2] * self.spectral_ratio[0]
        return np.stack([b, g, r], axis=2)

    # ------------------------------------------------------------
    def _log_density(self, img):
        """
        Converts linear light → log film density.
        """
        safe = np.clip(img, 1e-6, 1.0)
        logd = np.log10(safe * 9.0 + 1.0) / np.log10(10.0)
        return logd * self.density_scale

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Full negative density transformation:
          1) Apply spectral density multipliers
          2) Convert to log-density space
          3) Apply toe, gamma, shoulder curves
          4) Convert back to normalized light domain
        """
        f = self._ensure_f32(img)

        # Step 1 — spectral density weighting (R strongest)
        spec = self._apply_spectral_density(f)

        # Step 2 — convert to negative density (log space)
        d = self._log_density(spec)

        # Step 3 — apply film curve shaping
        toe = self._toe_curve(d)
        mid = self._mid_contrast(toe)
        out = self._shoulder_curve(mid)

        # Step 4 — normalize final output
        return np.clip(out, 0.0, 1.0)

# ================================================================
# WRAPPER MODULE — NegativeDensityModuleV4
# ================================================================
class NegativeDensityModuleV4:
    def __init__(self):
        self.engine = NegativeDensityCurveV4()

    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

