# ================================================================
# CHUNK 76Q-Q — CINEMATIC COLOR MOTION ENGINE V5 (CCME-V5)
# Adds:
#   • Motion-aware chroma shaping
#   • Direction-based saturation compression
#   • Highlight motion stabilizer (ACES safe)
#   • Avoids “motion neon” artifacts in bloom-heavy scenes
#   • Preserves skin tone stability during fast pans
#   • Temporal coherence filtering for smooth color motion
# Designed to run after ColorSeparationV6 → before FilmPrint LUT
# ================================================================

import numpy as np
import cv2

class CinematicColorMotionV5:
    """
    Motion-color coupling engine:
      - Computes optical flow magnitude + direction
      - Adjusts saturation & hue stability based on motion
      - Ideal for handheld / drone movements for film look
    """

    def __init__(self,
                 sat_reduce_motion=0.45,   # how much saturation drops on fast motion
                 hue_stability=0.85,       # 0–1, higher = preserves hue during motion
                 flow_blur=12.0,           # smoothing of motion field
                 temporal_blend=0.88):     # overall temporal stabilizer
        self.sat_reduce_motion = float(sat_reduce_motion)
        self.hue_stability = float(hue_stability)
        self.flow_blur = float(flow_blur)
        self.temp = float(temporal_blend)
        self.prev = None
        self.prev_gray = None

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32)/255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _compute_flow(self, img):
        """
        Computes dense optical flow (Farneback derivative).
        Returns magnitude + angle maps.
        """
        gray = cv2.cvtColor((img*255).astype(np.uint8), cv2.COLOR_BGR2GRAY)
        if self.prev_gray is None:
            self.prev_gray = gray
            h, w = gray.shape
            return np.zeros((h, w), np.float32), np.zeros((h, w), np.float32)
        flow = cv2.calcOpticalFlowFarneback(
            self.prev_gray, gray,
            None,
            0.5, 3, 21, 5, 5, 1.2, 0
        )
        self.prev_gray = gray
        mag, ang = cv2.cartToPolar(flow[...,0], flow[...,1])
        # smooth the motion field
        mag_blur = cv2.GaussianBlur(mag, (0,0), self.flow_blur)
        ang_blur = cv2.GaussianBlur(ang, (0,0), self.flow_blur)
        # normalize magnitude for 0–1 range
        mag_n = np.clip(mag_blur / (mag_blur.max() + 1e-6), 0.0, 1.0)
        return mag_n, ang_blur

    # ------------------------------------------------------------
    def _apply_motion_saturation(self, img, mag):
        """
        Reduce saturation proportionally to motion magnitude.
        Prevents neon-oversaturated edges during camera movement.
        """
        hsv = cv2.cvtColor((img*255).astype(np.uint8), cv2.COLOR_BGR2HSV).astype(np.float32)
        s = hsv[...,1] / 255.0
        reduce = mag * self.sat_reduce_motion
        s2 = s * (1.0 - reduce)
        hsv[...,1] = (s2 * 255.0)
        out = cv2.cvtColor(hsv.astype(np.uint8), cv2.COLOR_HSV2BGR)
        return out.astype(np.float32)/255.0

    # ------------------------------------------------------------
    def _apply_hue_stability(self, img, mag):
        """
        Hue stabilization → prevents hue wobble during motion.
        """
        hsv = cv2.cvtColor((img*255).astype(np.uint8), cv2.COLOR_BGR2HSV).astype(np.float32)
        h = hsv[...,0] / 180.0
        # blend hue toward previous hue based on speed
        if self.prev is not None:
            prev_h = cv2.cvtColor((self.prev*255).astype(np.uint8), cv2.COLOR_BGR2HSV).astype(np.float32)[...,0] / 180.0
            h = h * (1.0 - mag * (1.0 - self.hue_stability)) + prev_h * (mag * (1.0 - self.hue_stability))
        hsv[...,0] = h * 180.0
        out = cv2.cvtColor(hsv.astype(np.uint8), cv2.COLOR_HSV2BGR)
        return out.astype(np.float32)/255.0

    # ------------------------------------------------------------
    def _temporal(self, img):
        if self.prev is None:
            self.prev = img
            return img
        out = self.prev * self.temp + img * (1.0 - self.temp)
        self.prev = out
        return out

    # ------------------------------------------------------------
    def apply(self, img):
        f = self._ensure_f32(img)
        # 1) compute motion field
        mag, ang = self._compute_flow(f)
        # 2) saturation compression based on motion
        sat_fixed = self._apply_motion_saturation(f, mag)
        # 3) hue stabilization
        hue_fixed = self._apply_hue_stability(sat_fixed, mag)
        # 4) temporal smoothing
        out = self._temporal(hue_fixed)
        return np.clip(out, 0.0, 1.0)

# ================================================================
# WRAPPER MODULE
# ================================================================
class CinematicColorMotionModuleV5:
    def __init__(self):
        self.engine = CinematicColorMotionV5()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

