# ================================================================
# CHUNK 77A — ANALOG GATE WEAVE SIMULATOR V3 (Film Stability Engine)
# Adds:
#   • Subpixel jitter drift (horizontal + vertical)
#   • Sprocket-based oscillatory weave (6–8 Hz)
#   • Micro-bounce randomness per frame
#   • Vertical breathing (0.1–0.2%)
#   • Temporal smoothing for realistic analog feel
#   • ACES-safe spatial warp
# ================================================================

import numpy as np
import cv2
import math
import time

class GateWeaveV3:
    """
    Ultra-level 35mm-style film weave:
      - Simulates sprocket drift + projector jitter
      - Uses sinusoidal offset + noise jitter
      - Temporal smoothing prevents digital harsh motion
    """

    def __init__(self,
                 jitter_px=0.65,
                 oscillation_px=1.25,
                 breathing_strength=0.0018,
                 temporal_smooth=0.80):
        # max random jitter per frame
        self.jitter_px = float(jitter_px)
        # periodic sprocket oscillation amplitude
        self.osc_px = float(oscillation_px)
        # vertical scale modulation
        self.breathing = float(breathing_strength)
        # smoothing for transitions
        self.temporal_smooth = float(temporal_smooth)
        # state memory
        self.prev_dx = 0.0
        self.prev_dy = 0.0
        self.prev_scale = 1.0

        self.start_time = time.time()

    # ------------------------------------------------------------
    def _compute_offsets(self, h, w):
        """
        Compute drift + oscillation + breathing.
        """
        t = time.time() - self.start_time

        # 1) Sprocket oscillation (6–8 Hz)
        osc_freq = 6.8
        osc_dx = math.sin(2 * math.pi * osc_freq * t) * self.osc_px
        osc_dy = math.sin(2 * math.pi * osc_freq * t * 0.5) * (self.osc_px * 0.6)

        # 2) Random jitter (film gate instability)
        jitter_dx = np.random.uniform(-self.jitter_px, self.jitter_px)
        jitter_dy = np.random.uniform(-self.jitter_px, self.jitter_px)

        # 3) Combine
        dx = osc_dx + jitter_dx
        dy = osc_dy + jitter_dy

        # 4) Vertical breathing (scale modulation)
        breathe = 1.0 + math.sin(t * 2.2) * self.breathing

        # 5) Temporal smoothing
        dx = self.prev_dx * self.temporal_smooth + dx * (1 - self.temporal_smooth)
        dy = self.prev_dy * self.temporal_smooth + dy * (1 - self.temporal_smooth)
        scale = self.prev_scale * self.temporal_smooth + breathe * (1 - self.temporal_smooth)

        # update memory
        self.prev_dx = dx
        self.prev_dy = dy
        self.prev_scale = scale

        return dx, dy, scale

    # ------------------------------------------------------------
    def _apply_warp(self, img, dx, dy, scale):
        """
        ACES-safe affine warp.
        """
        h, w = img.shape[:2]

        # scaling matrix around frame center
        cx, cy = w / 2, h / 2
        M_scale = np.array([
            [scale, 0,      cx - scale*cx],
            [0,     scale,  cy - scale*cy]
        ], dtype=np.float32)
        # translation offsets
        M_trans = np.array([
            [1, 0, dx],
            [0, 1, dy]
        ], dtype=np.float32)

        # combined transform
        M = M_trans @ M_scale

        warped = cv2.warpAffine(
            img, M, (w, h),
            flags=cv2.INTER_LINEAR,
            borderMode=cv2.BORDER_REFLECT
        )
        return warped

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Apply gate weave to frame.
        """
        f = img.astype(np.float32) if img.dtype != np.float32 else img
        h, w = f.shape[:2]
        # compute analog offsets
        dx, dy, scale = self._compute_offsets(h, w)

        # apply warp transform
        out = self._apply_warp(f, dx, dy, scale)
        return np.clip(out, 0.0, 1.0)

# ================================================================
# WRAPPER: GateWeaveModuleV3
# ================================================================
class GateWeaveModuleV3:
    def __init__(self):
        self.engine = GateWeaveV3()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

