# END OF CHUNK 77G — FILM STOCK GRAIN COHESION ENGINE V4
# ================================================================

# ================================================================
# CHUNK 77H — FILMIC FRINGE EXPANSION ENGINE V4
# Adds:
#   • True optical chromatic aberration (CA) dispersion
#   • Edge-energy-driven fringing
#   • Lens-breathing aware aberration scaling
#   • Sub-pixel spectral shift simulation (micro-dispersion)
#   • ACES-safe composite
# ================================================================

import numpy as np
import cv2

class FilmicFringeV4:
    """
    Ultra-level optical aberration:
      - micro-dispersion per pixel (simulates wavelength separation)
      - CA increases toward corners (lens geometry)
      - edge-driven color fringing (only high-contrast edges)
      - breathing-adaptive: exposure fluctuation increases CA
    """

    def __init__(
        self,
        strength=0.0045,
        edge_boost=1.85,
        breathing_sensitivity=0.30,
        dispersion_scale=1.0,
        vignette_factor=0.75
    ):
        self.strength = float(strength)
        self.edge_boost = float(edge_boost)
        self.breathing_sensitivity = float(breathing_sensitivity)
        self.dispersion_scale = float(dispersion_scale)
        self.vignette_factor = float(vignette_factor)

        self.prev_lum = None

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _lum(self, img):
        return 0.2126*img[...,2] + 0.7152*img[...,1] + 0.0722*img[...,0]

    # ------------------------------------------------------------
    def _breathing_factor(self, lum):
        """
        Lens breathing simulation:
          CA increases when rapid exposure shifts occur.
        """
        if self.prev_lum is None:
            self.prev_lum = lum
            return 1.0

        diff = np.abs(lum - self.prev_lum)
        exp_change = np.mean(diff)

        # scale based on sensitivity
        factor = 1.0 + exp_change * self.breathing_sensitivity
        self.prev_lum = lum
        return factor

    # ------------------------------------------------------------
    def _edge_energy(self, img):
        """
        High frequency edges → more fringing.
        Very smooth areas → minimal CA.
        """
        gray = cv2.cvtColor((img*255).astype(np.uint8), cv2.COLOR_BGR2GRAY)
        gx = cv2.Sobel(gray, cv2.CV_32F, 1, 0, ksize=3)
        gy = cv2.Sobel(gray, cv2.CV_32F, 0, 1, ksize=3)
        mag = np.sqrt(gx*gx + gy*gy)
        mag_norm = mag / (np.max(mag) + 1e-6)
        mag_norm = np.clip(mag_norm, 0.0, 1.0)
        mag_norm = np.power(mag_norm, 0.65)  # soften
        mag_norm = cv2.GaussianBlur(mag_norm, (0,0), 0.85)
        return mag_norm

    # ------------------------------------------------------------
    def _radial_map(self, img):
        """
        Aberration grows toward corners.
        Creates normalized radial distance map.
        """
        h, w = img.shape[:2]
        cx, cy = w/2, h/2
        xs = (np.arange(w) - cx) / cx
        ys = (np.arange(h) - cy) / cy
        xv, yv = np.meshgrid(xs, ys)
        radial = np.sqrt(xv**2 + yv**2)
        radial = radial**self.vignette_factor
        radial = cv2.GaussianBlur(radial.astype(np.float32), (0,0), 1.5)
        return np.clip(radial, 0.0, 1.0)

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Full optical fringe simulation:
          1. Edge energy → where to apply fringing
          2. Radial map → how strong dispersions get
          3. Breathing factor → dynamic CA change
          4. Per-channel subpixel wavelength shift
          5. ACES-safe blending
        """
        f = self._ensure_f32(img)
        h, w = f.shape[:2]

        lum = self._lum(f)

        # step 1: texture-driven edge map
        edges = self._edge_energy(f)

        # step 2: radial intensity (corner dispersion)
        radial = self._radial_map(f)

        # step 3: breathing scale factor
        breathe = self._breathing_factor(lum)

        # combined aberration map
        aberr = edges * radial
        aberr = cv2.GaussianBlur(aberr, (0,0), 0.9)
        strength = self.strength * breathe * self.dispersion_scale

        # --------------------------------------------------------
        # Step 4 — wavelength-dependent subpixel shifts
        # --------------------------------------------------------
        # red shifts outward the MOST
        shift_r = strength * 2.2
        # green moderate shift
        shift_g = strength * 1.3
        # blue smallest shift
        shift_b = strength * 0.8

        # coordinate grid
        xs = np.arange(w).astype(np.float32)
        ys = np.arange(h).astype(np.float32)
        xv, yv = np.meshgrid(xs, ys)

        # apply radial displacement per channel
        dx = (xv - w/2) / (w/2 + 1e-6)
        dy = (yv - h/2) / (h/2 + 1e-6)

        # normalization for mapping
        disp = aberr[...,None]

        # compute remap coordinates
        def remap_channel(channel, sx):
            mx = xv + dx * sx * disp[...,0] * w
            my = yv + dy * sx * disp[...,0] * h
            mx = mx.astype(np.float32)
            my = my.astype(np.float32)
            return cv2.remap(channel, mx, my,
        interpolation=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_REFLECT)

        b = remap_channel(f[...,0], shift_b)
        g = remap_channel(f[...,1], shift_g)
        r = remap_channel(f[...,2], shift_r)

        # stacked dispersed image
        shifted = np.stack([b, g, r], axis=2)

        # step 5 — ACES-safe fringe blend
        out = f * (1.0 - aberr[...,None]) + shifted * aberr[...,None]
        out = np.clip(out, 0.0, 1.0)
        return out

# ================================================================
# WRAPPER MODULE — FilmicFringeModuleV4
# ================================================================
class FilmicFringeModuleV4:
    def __init__(self):
        self.engine = FilmicFringeV4()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

