# ================================================================
# CHUNK 77J — Filmic Halation Recovery + Glow Energy Normalizer V4
# Adds:
#   • Halation-corrected spectral balance recovery
#   • Glow energy redistribution (post-bloom, post-halation)
#   • Highlight-preserving compression (ACES-compliant)
#   • Skin-tone protection mask
#   • Adaptive glow limiter (prevents over-softening)
# ================================================================

import numpy as np
import cv2

class HalationGlowNormalizerV4:
    """
    Stabilizes halation + bloom interactions.
    Prevents:
      - red-channel blowout
      - glow halos stacking and washing out contrast
      - highlight chroma drift (yellow/pink hue shift)
    """
    def __init__(
        self,
        hal_reduction: float = 0.35,
        glow_limit: float = 0.55,
        chroma_protect: float = 0.72,
        skin_protect: float = 0.65,
        rolloff_start: float = 0.70,
        rolloff_end: float = 0.96
    ):
        self.hal_reduction = float(hal_reduction)
        self.glow_limit = float(glow_limit)
        self.chroma_protect = float(chroma_protect)
        self.skin_protect = float(skin_protect)
        self.rolloff_start = float(rolloff_start)
        self.rolloff_end = float(rolloff_end)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _lum(self, img):
        return 0.2126*img[...,2] + 0.7152*img[...,1] + 0.0722*img[...,0]

    # ------------------------------------------------------------
    def _skin_mask(self, img):
        """
        Protective mask for skin tones (prevents halation desaturation).
        Works in YCrCb.
        """
        ycrcb = cv2.cvtColor((img*255).astype(np.uint8), cv2.COLOR_BGR2YCrCb)
        y, cr, cb = cv2.split(ycrcb)
        # Skin region ranges
        mask = (cr > 135) & (cr < 180) & (cb > 85) & (cb < 135)
        mask = mask.astype(np.float32)
        mask = cv2.GaussianBlur(mask, (0,0), sigmaX=4)
        return np.clip(mask, 0.0, 1.0)

    # ------------------------------------------------------------
    def _glow_energy(self, img, ref):
        """
        Measures glow intensity (difference from original frame).
        Used to redistribute bloom/halation.
        """
        diff = np.clip(img - ref, 0.0, 1.0)
        glow = np.max(diff, axis=2)
        glow = cv2.GaussianBlur(glow, (0,0), sigmaX=3)
        return glow

    # ------------------------------------------------------------
    def _compress_glow(self, glow):
        """
        Adaptive glow limiting.
        """
        limit = self.glow_limit
        return glow * (limit / (np.max(glow) + 1e-6))

    # ------------------------------------------------------------
    def _apply_glow_suppression(self, img, glow_map):
        """
        Glow suppression is applied more near highlights,
        leaving midtones mostly untouched.
        """
        lum = self._lum(img)
        # compression ramp
        t = (lum - self.rolloff_start) / (self.rolloff_end - self.rolloff_start)
        t = np.clip(t, 0.0, 1.0)
        t = t * t * (3 - 2*t)  # smoothstep
        # suppress glow proportionally to t
        suppression = glow_map[...,None] * t[...,None]
        out = img - suppression * self.hal_reduction
        return np.clip(out, 0.0, 1.0)

    # ------------------------------------------------------------
    def _restore_chroma(self, img, skin_mask):
        """
        Restore chroma after halation/glow compression.
        """
        eps = 1e-6
        r = img[...,2]
        g = img[...,1]
        b = img[...,0]
        maxc = np.maximum(np.maximum(r, g), b)
        minc = np.minimum(np.minimum(r, g), b)
        spread = (maxc - minc) / (maxc + eps)
        # chroma fade in high highlights
        fade = np.clip((maxc - 0.65) / 0.35, 0.0, 1.0)
        fade *= (1.0 - self.chroma_protect)
        # skin tones resist chroma loss strongly
        fade *= (1.0 - skin_mask * self.skin_protect)
        chroma_keep = 1.0 - fade
        # restore channels to preserve hue
        avg = (r + g + b) / 3.0
        r2 = avg * (1-chroma_keep) + r * chroma_keep
        g2 = avg * (1-chroma_keep) + g * chroma_keep
        b2 = avg * (1-chroma_keep) + b * chroma_keep
        out = np.stack([b2, g2, r2], axis=2)
        return np.clip(out, 0.0, 1.0)

    # ------------------------------------------------------------
    def apply(self, img, original_frame):
        """
        img: frame processed with bloom + halation
        original_frame: unprocessed frame reference
        """
        f = self._ensure_f32(img)
        o = self._ensure_f32(original_frame)

        # 1) compute glow map
        glow = self._glow_energy(f, o)
        glow_c = self._compress_glow(glow)

        # 2) suppress excess bloom/halation
        suppressed = self._apply_glow_suppression(f, glow_c)

        # 3) skin-tone mask
        sk = self._skin_mask(o)

        # 4) restore chroma + correct color drift
        restored = self._restore_chroma(suppressed, sk)

        return np.clip(restored, 0.0, 1.0)

# ================================================================
# WRAPPER — HalationGlowNormalizerModuleV4
# ================================================================
class HalationGlowNormalizerModuleV4:
    def __init__(self):
        self.engine = HalationGlowNormalizerV4()
    def apply(self, frame_after_fx, original_frame):
        return self.engine.apply(frame_after_fx, original_frame)

# ================================================================
# END OF CHUNK 77J — Filmic Halation Recovery + Glow Normalizer V4
# ================================================================

# ================================================================
# CHUNK 77K — TEMPORAL FLICKER REMOVAL V5 (MOTION-AWARE, ACES-SAFE)
# Provides:
#   • Motion-compensated temporal smoothing (no ghosting)
#   • Luma flicker removal (LED/auto-exposure flicker)
#   • Highlight flicker stabilization (post-bloom/post-halation)
#   • Grain-aware blending (protects fine detail)
#   • Scene-cut detector (auto resets memory)
# ================================================================

import numpy as np
import cv2

class TemporalFlickerRemovalV5:
    """
    Ultra-grade temporal stabilizer for halation/bloom/HDR pipeline.
    Ensures cinematic stability under:
      - auto-exposure jitter
      - drone vibrations
      - rapid luminance shifts
      - rolling shutter patterns
    Motion-aware to avoid ghost trails.
    """

    def __init__(
            self,
            strength: float = 0.65,       # temporal smoothing amount
            motion_protect: float = 0.55, # reduces smoothing on strong motion
            highlight_protect: float = 0.70,
            grain_protect: float = 0.65,
            cut_threshold: float = 0.32   # scene-cut detector sensitivity
    ):
        self.strength = float(strength)
        self.motion_protect = float(motion_protect)
        self.highlight_protect = float(highlight_protect)
        self.grain_protect = float(grain_protect)
        self.cut_threshold = float(cut_threshold)

        self.prev_frame = None
        self.prev_luma = None

    # ------------------------------------------------------------
    def _ensure_f32(self, f):
        if f.dtype == np.uint8:
            return f.astype(np.float32) / 255.0
        return f.astype(np.float32)

    # ------------------------------------------------------------
    def _luma(self, img):
        return 0.2126*img[...,2] + 0.7152*img[...,1] + 0.0722*img[...,0]

    # ------------------------------------------------------------
    def _detect_cut(self, curr_luma, prev_luma):
        """
        Hard cut detector based on histogram difference.
        """
        if prev_luma is None:
            return False
        # compare histograms
        h1 = np.histogram(curr_luma, bins=32, range=(0,1))[0]
        h2 = np.histogram(prev_luma, bins=32, range=(0,1))[0]
        diff = np.mean(np.abs(h1 - h2)) / (np.mean(h1 + h2 + 1e-6))
        return diff > self.cut_threshold

    # ------------------------------------------------------------
    def _motion_mask(self, curr, prev):
        """
        Lightweight motion estimation using abs-diff + gaussian blur.
        """
        diff = np.abs(curr - prev)
        m = np.max(diff, axis=2)
        m = cv2.GaussianBlur(m, (0,0), sigmaX=5)
        return np.clip(m, 0.0, 1.0)

    # ------------------------------------------------------------
    def _grain_mask(self, curr_luma):
        """
        Grain lives in high-frequency zones.
        Preserve grain by reducing temporal blending there.
        """
        lap = cv2.Laplacian(curr_luma, cv2.CV_32F)
        hi = np.abs(lap)
        hi = cv2.GaussianBlur(hi, (0,0), sigmaX=1.5)
        # normalize 0..1
        hi = hi / (np.max(hi) + 1e-6)
        return np.clip(hi, 0.0, 1.0)

    # ------------------------------------------------------------
    def _highlight_mask(self, img):
        lum = self._luma(img)
        m = np.clip((lum - 0.75) / 0.25, 0.0, 1.0)
        return cv2.GaussianBlur(m, (0,0), sigmaX=3)

    # ------------------------------------------------------------
    def apply(self, img):
        f = self._ensure_f32(img)
        l = self._luma(f)
        # 1) first frame → no smoothing
        if self.prev_frame is None:
            self.prev_frame = f.copy()
            self.prev_luma = l.copy()
            return f
        # 2) scene cut detector
        if self._detect_cut(l, self.prev_luma):
            # reset temporal memory
            self.prev_frame = f.copy()
            self.prev_luma = l.copy()
            return f
        # 3) motion mask
        mot = self._motion_mask(f, self.prev_frame)
        # 4) grain preservation mask
        grain = self._grain_mask(l)
        # 5) highlight stability mask
        hl = self._highlight_mask(f)
        # ---------------------------------------------
        # 6) compute effective blend weight per pixel
        # ---------------------------------------------
        # high motion → less smoothing
        w_motion = 1.0 - mot * self.motion_protect
        # high grain → less smoothing
        w_grain = 1.0 - grain * self.grain_protect
        # highlights → protect from smearing
        w_highlight = 1.0 - hl * self.highlight_protect
        # base smoothing
        w_base = self.strength
        # combine all weights
        w = w_base * w_motion * w_grain * w_highlight
        w = np.clip(w, 0.0, 1.0)[...,None]

        # ---------------------------------------------
        # 7) apply temporal smoothing (no ghosting)
        # ---------------------------------------------
        out = f * (1.0 - w) + self.prev_frame * w

        # update memory
        self.prev_frame = out.copy()
        self.prev_luma = l.copy()
        return np.clip(out, 0.0, 1.0)

# ================================================================
# WRAPPER — TemporalFlickerModuleV5
# ================================================================
class TemporalFlickerModuleV5:
    def __init__(self):
        self.engine = TemporalFlickerRemovalV5()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

