# ================================================================
# CHUNK 77M — VINTAGE FILM EMULATION ENGINE V6
# Kodak 2383 • Fuji Eterna 3513 • Agfa Ultra 50 • Bleach Bypass
# Provides:
#   • True film-print style colorimetry
#   • Density-based saturation compression
#   • Toe/shoulder shaping (chemically inspired)
#   • Channel cross-talk (film spectral overlap)
#   • Highlight rolloff (smooth, non-digital)
#   • Stock-based contrast profiles
#   • ACES-safe integration into the entire pipeline
# ================================================================

import numpy as np
import cv2
import math

class FilmStockV6:
    """
    A modern, high-quality simulation of real film stocks.
    Each preset defines:
      - spectral matrix (3x3)
      - density curve coefficients
      - saturation-to-density shift
      - toe/shoulder shape
    """

    PRESETS = {
        "kodak_2383": {
            "matrix": np.array([
                [1.15, -0.05, -0.04],
                [-0.02, 1.10, -0.03],
                [0.00, -0.05, 1.20]
            ]),
            "toe": 0.055,
            "shoulder": 0.82,
            "sat_comp": 0.82,
            "contrast": 1.18
        },

        "fuji_eterna": {
            "matrix": np.array([
                [1.05, -0.03, -0.02],
                [-0.01, 1.08, -0.02],
                [0.00, -0.02, 1.10]
            ]),
            "toe": 0.065,
            "shoulder": 0.78,
            "sat_comp": 0.88,
            "contrast": 1.10
        },

        "agfa_ultra": {
            "matrix": np.array([
                [1.22, -0.08, -0.08],
                [-0.04, 1.18, -0.06],
                [0.00, -0.05, 1.30]
            ]),
            "toe": 0.040,
            "shoulder": 0.90,
            "sat_comp": 0.72,
            "contrast": 1.30
        },

        "bleach_bypass": {
            "matrix": np.eye(3),
            "toe": 0.02,
            "shoulder": 0.95,
            "sat_comp": 0.25,
            "contrast": 1.55
        }
    }

    # ------------------------------------------------------------
    def __init__(self, preset="kodak_2383"):
        self.set_preset(preset)

    def set_preset(self, preset):
        if preset not in self.PRESETS:
            preset = "kodak_2383"
        self.params = self.PRESETS[preset]

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _apply_matrix(self, img):
        h, w, _ = img.shape
        flat = img.reshape(-1, 3)
        out = flat @ self.params["matrix"].T
        return out.reshape(h, w, 3)

    # ------------------------------------------------------------
    def _toe_shoulder(self, x, toe, shoulder):
        """
        A film-style soft toe + rolloff shoulder curve.
        """
        # toe region (shadows)
        t = x / (x + toe)
        # shoulder region (highlights)
        s = 1.0 - np.exp(-((x - shoulder) * 3.0).clip(0, 1))
        # blend toe → linear → shoulder
        out = t * (1.0 - s) + s
        return np.clip(out, 0.0, 1.0)

    # ------------------------------------------------------------
    def _saturation_density(self, img):
        """
        Simulates how real film compresses saturation as density increases.
        """
        r = img[...,2]
        g = img[...,1]
        b = img[...,0]

        sat = np.sqrt(
            (r - g)**2 +
            (g - b)**2 +
            (b - r)**2
        )

        comp = self.params["sat_comp"]
        # saturation compression (higher density = lower saturation)
        sat_factor = 1.0 - sat * (1.0 - comp)
        r2 = r * sat_factor
        g2 = g * sat_factor
        b2 = b * sat_factor
        return np.stack([b2, g2, r2], axis=2)

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Full ultra film emulation:
          1. Apply spectral matrix
          2. Density-driven saturation model
          3. Film toe/shoulder curve
          4. Contrast scaling
          5. ACES-safe output clamp
        """
        f = self._ensure_f32(img)

        # 1) apply spectral overlap matrix
        m = self._apply_matrix(f)

        # 2) compress saturation based on density
        sat = self._saturation_density(m)

        # 3) apply toe/shoulder
        toe = self.params["toe"]
        shd = self.params["shoulder"]
        curved = self._toe_shoulder(sat, toe, shd)

        # 4) apply contrast
        c = self.params["contrast"]
        out = np.power(curved, 1.0 / c)

        return np.clip(out, 0.0, 1.0)

# ---------------------------------------------------------------
# WRAPPER for AIFusionPipeline
# ---------------------------------------------------------------
class FilmStockModuleV6:
    def __init__(self, preset="kodak_2383"):
        self.engine = FilmStockV6(preset)

    def apply(self, frame_float01, preset=None):
        if preset is not None:
            self.engine.set_preset(preset)
        return self.engine.apply(frame_float01)

