# ================================================================
# CHUNK 77 — SUBJECT-DRIVEN COLOR GRADING SUITE V7 ULTRA
# SECTION Q — Y) Adaptive Skin Exposure Balancer V9.1
# ---------------------------------------------------------------
# Purpose:
#   • Fix uneven brightness across skin (natural exposure matching)
#   • Adaptive correction using local luminance field
#   • Prevent hot hotspots on nose, cheeks, forehead
#   • Bring up under-eye shadows without flattening texture
#   • Maintains ACES highlight shape
#   • Stabilizes indoor/outdoor mixed lighting fluctuations
#
# Inputs:
#   - frame_float01 (BGR float32)
#   - skin_matte: 0..1 mask for skin regions
#
# Outputs:
#   - frame with stabilized skin exposure + preserved detail
# ================================================================

import numpy as np
import cv2

class SkinExposureBalancerV91:
    """
    Adaptive Skin Exposure Balancer V9.1
    - Prevents highlight blowout
    - Recovers dark zones
    - Maintains texture & hue
    - Uses luminance-guided local exposure shaping
    """

    def __init__(self,
                 lift_strength=0.22,        # brightens dark areas
                 rolloff_strength=0.35,     # compresses over-bright areas
                 gamma_balance=0.18,        # midtone shaping
                 texture_keep=0.82,         # blend detail back
                 smoothing_radius=18.0):    # local exposure field smoothness
        self.lift_strength = float(lift_strength)
        self.rolloff_strength = float(rolloff_strength)
        self.gamma_balance = float(gamma_balance)
        self.texture_keep = float(texture_keep)
        self.smoothing_radius = float(smoothing_radius)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _luminance(self, f):
        return 0.2126*f[...,2] + 0.7152*f[...,1] + 0.0722*f[...,0]

    # ------------------------------------------------------------
    def _compute_exposure_field(self, lum, skin_matte):
        """
        Build exposure compensation map:
          - darker areas lifted
          - too bright areas compressed
          - smoothly interpolated across face
        """
        matte = skin_matte.astype(np.float32)

        # 1. Lift low luminance
        lift = np.clip((0.45 - lum) * self.lift_strength, 0.0, 1.0)

        # 2. Compress over-bright luminance
        roll = np.clip((lum - 0.60) * self.rolloff_strength, 0.0, 1.0)

        # 3. Combine into final exposure field
        field = lift - roll

        # 4. Smooth field to avoid harsh transitions
        field = cv2.GaussianBlur(field, (0,0), self.smoothing_radius)

        return field * matte

    # ------------------------------------------------------------
    def _apply_exposure(self, f, field):
        """
        gamma-shifted exposure normalization:
          - positive field = brightening
          - negative field = compression
        """
        gamma = 1.0 - self.gamma_balance * field
        gamma = np.clip(gamma, 0.35, 2.5)

        out = np.power(f, gamma)
        return np.clip(out, 0.0, 1.0)

    # ------------------------------------------------------------
    def _restore_texture(self, original, processed, matte):
        """
        Prevent plastic-smooth skin by adding microtexture back.
        """
        detail = original - cv2.GaussianBlur(original, (0,0), 2.0)
        matte3 = matte[...,None].astype(np.float32)
        restored = processed + detail * self.texture_keep * matte3
        return np.clip(restored, 0.0, 1.0)

    # ------------------------------------------------------------
    def apply(self, frame, skin_matte):
        f = self._ensure_f32(frame)
        matte = np.clip(skin_matte.astype(np.float32), 0.0, 1.0)

        lum = self._luminance(f)

        # 1) Build exposure field
        field = self._compute_exposure_field(lum, matte)

        # 2) Apply exposure shaping
        exposed = self._apply_exposure(f, field)

        # 3) Restore texture
        out = self._restore_texture(f, exposed, matte)

        return np.clip(out, 0.0, 1.0)

# ================================================================
# END OF CHUNK 77 Q Y — Adaptive Skin Exposure Balancer V9.1
# ================================================================

