# CHUNK 77 — SUBJECT-DRIVEN COLOR GRADING SUITE V7 ULTRA
# SECTION Q — Z) Cinematic Skin Glow Shaping V6.5
# ---------------------------------------------------------------
# Purpose:
#   • Add subtle cinematic glow ONLY to skin
#   • Zero-smoothing beauty glow (keeps all texture)
#   • Warm film-style color bloom (Venice/Alexa style)
#   • Adaptive radius: highlights → more glow, shadows → less
#   • Works after SkinExposureBalancer to unify skin presence
#
# Inputs:
#   - frame_float01 (float32, BGR, 0..1)
#   - skin_matte (0..1 mask)
#
# Outputs:
#   - frame with warm filmic skin glow applied
# ================================================================

import numpy as np
import cv2

class SkinGlowV65:
    """
    Cinematic Skin Glow Shaping V6.5
      - Film-like warmth diffusion
      - No face distortion or smoothing
      - Glow intensity follows highlight regions
      - Minimal color shift / no orange cast artifact
    """

    def __init__(self,
                 glow_strength=0.22,       # global glow intensity
                 warm_tint=0.12,           # how warm the glow becomes
                 base_radius=14.0,          # glow blur radius
                 adaptive_radius_boost=18.0,# stronger glow in bright areas
                 highlight_threshold=0.65,  # where glow begins
                 matte_soften=6.0):         # soften matte edges
        self.glow_strength = float(glow_strength)
        self.warm_tint = float(warm_tint)
        self.base_radius = float(base_radius)
        self.adaptive_radius_boost = float(adaptive_radius_boost)
        self.highlight_threshold = float(highlight_threshold)
        self.matte_soften = float(matte_soften)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _luminance(self, f):
        return 0.2126*f[...,2] + 0.7152*f[...,1] + 0.0722*f[...,0]

    # ------------------------------------------------------------
    def _soft_matte(self, matte):
        """
        Feather skin matte edges before applying glow.
        """
        return cv2.GaussianBlur(matte, (0,0), self.matte_soften)

    # ------------------------------------------------------------
    def _build_glow(self, f, lum, matte):
        """
        Glow = (blur * warm_tint) masked by skin + highlight
        """
        # 1. Highlight-based radius scaling
        hl = np.clip((lum - self.highlight_threshold) /
        max(1e-6, (1.0 - self.highlight_threshold)),
        0.0, 1.0)
        # radius grows in bright regions
        radius_map = self.base_radius + hl * self.adaptive_radius_boost
        # 2. Apply variable blur using multi-pass approximation
        #    (true per-pixel radius convolution is too expensive)
        r_small = cv2.GaussianBlur(f, (0,0), self.base_radius * 0.5)
        r_medium = cv2.GaussianBlur(f, (0,0), self.base_radius)
        r_large = cv2.GaussianBlur(f, (0,0), self.base_radius * 2.0)
        # blend blur levels using highlight weight
        glow = (
            r_small * (1.0 - hl)[...,None] +
            r_medium * (0.6 * hl[...,None]) +
            r_large * (0.4 * hl[...,None])
        )

        # 3. Warm tint film coating (subtle)
        glow_r = glow[...,2] * (1.0 + self.warm_tint)
        glow_g = glow[...,1] * (1.0 + self.warm_tint * 0.5)
        glow_b = glow[...,0] * (1.0 - self.warm_tint * 0.15)
        glow = np.stack([glow_b, glow_g, glow_r], axis=2)

        # 4. Mask glow to skin regions
        return glow * matte[...,None]

    # ------------------------------------------------------------
    def apply(self, frame, skin_matte):
        f = self._ensure_f32(frame)
        matte = np.clip(self._soft_matte(skin_matte), 0.0, 1.0)
        lum = self._luminance(f)
        # 1. Build warm diffuse glow
        glow = self._build_glow(f, lum, matte)
        # 2. Strength scaling
        glow *= self.glow_strength
        # 3. Add back to frame
        out = f + glow
        out = np.clip(out, 0.0, 1.0)
        return out

