# CHUNK 78 — FILMIC DEPTH + DENSITY SUITE V7
# SECTION A — Ultra Film Shadow Sculptor V4
# ---------------------------------------------------------------
# Purpose:
#   • Sculpt shadows with cinematic density (Kodak-style)
#   • Maintain texture — no crushing / no banding
#   • Adaptive warm/cool shadow tinting based on environment
#   • ACES-compatible low-end rolloff
#   • Zero-impact on highlights/midtones
#
# Inputs:
#   - frame_float01 (float32, BGR, 0..1)
#   - env_profile: "outdoor", "indoor", "neutral"
#
# Outputs:
#   - frame with shaped cinematic shadow density
# ================================================================

import numpy as np
import cv2

class FilmShadowSculptorV4:
    """
    Ultra-level shadow density engine:
      - ACES-friendly shadow rolloff
      - Mild color separation in deep tones
      - Adaptive tint (blue outdoor / amber indoor)
      - Avoids crushed blacks or clipped channels
    """

    def __init__(self,
                 density_strength=0.28,    # how strong shadows deepen
                 chroma_separation=0.12,   # subtle R/G/B split in deep zones
                 rolloff_start=0.12,       # ACES-like toe start
                 rolloff_end=0.35,         # ACES-like toe end
                 tint_strength=0.10):      # environmental tint
        self.density_strength = float(density_strength)
        self.chroma_separation = float(chroma_separation)
        self.rolloff_start = float(rolloff_start)
        self.rolloff_end = float(rolloff_end)
        self.tint_strength = float(tint_strength)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _luminance(self, f):
        return 0.2126*f[...,2] + 0.7152*f[...,1] + 0.0722*f[...,0]

    # ------------------------------------------------------------
    def _shadow_mask(self, lum):
        """
        Smooth mask 0..1 across deep shadows.
        """
        t = (self.rolloff_end - self.rolloff_start)
        m = (lum - self.rolloff_start) / (t + 1e-6)
        m = 1.0 - np.clip(m, 0.0, 1.0)
        m = cv2.GaussianBlur(m, (0,0), 5.0)
        return m

    # ------------------------------------------------------------
    def _environment_tint(self, f, env_profile):
        """
        Film-like tint:
          outdoor → very subtle blue/cyan
          indoor  → very subtle amber/red
        Tint only applied inside shadows.
        """
        if env_profile == "outdoor":
            # +Blue, -Red
            tint = np.array([0.03, -0.01, -0.02], np.float32)
        elif env_profile == "indoor":
            # +Red, +Amber, -Blue
            tint = np.array([-0.02, +0.01, +0.04], np.float32)
        else:
            tint = np.zeros(3, np.float32)
        return tint * self.tint_strength

    # ------------------------------------------------------------
    def apply(self, frame, env_profile="neutral"):
        f = self._ensure_f32(frame)
        lum = self._luminance(f)
        # 1. Build shadow mask
        m = self._shadow_mask(lum)  # 0 (not shadow) → 1 (deep shadow)
        # 2. Density deepening (film-like toe curve)
        deep = f * (1.0 - self.density_strength * m[...,None])
        # 3. Chroma separation in shadows (subtle RGB shaping)
        r = deep[...,2]
        g = deep[...,1]
        b = deep[...,0]
        # small controlled hue shift
        r2 = r * (1.0 - self.chroma_separation * m)
        g2 = g * (1.0 - self.chroma_separation * 0.5 * m)
        b2 = b * (1.0 + self.chroma_separation * 0.3 * m)
        chroma = np.stack([b2, g2, r2], axis=2)
        # 4. Add subtle environmental tint inside shadows
        tint = self._environment_tint(f, env_profile)
        tinted = chroma + (tint * m[...,None])
        # 5. Composite with highlights unchanged
        out = tinted
        out = np.clip(out, 0.0, 1.0)
        return out

