# ================================================================
# CHUNK 78 C — HIGHLIGHT & SHADOW DUAL-ORBIT COLOR SEPARATION V5
# ---------------------------------------------------------------
# Purpose:
#   Modern cinema cameras shift hue differently in highlights vs shadows:
#     • Highlights drift slightly warm-yellow (Alexa, Vision3)
#     • Deep shadows cool slightly toward cyan/blue
#
# This module creates:
#   • 2 orbit centers (highlight + shadow)
#   • Smooth transition band with ACES-safe luminance blending
#   • Hue-preserving chroma re-projection (no spectral clipping)
#
# Input:
#   frame_float01 — ACES/linear float32 0..1
#
# Output:
#   Film-like hue drift depending on exposure zone.
# ================================================================

import numpy as np
import cv2

class DualOrbitColorV5:
    """
    Ultra-grade film color separation:
      - Highlight orbit (warm shift)
      - Shadow orbit (cool shift)
      - Midtone preserve region
      - Fully hue-safe (no weird neon artifacts)
    """

    def __init__(
            self,
            shadow_orbit_strength=0.08,     # 0..0.25
            highlight_orbit_strength=0.12,  # 0..0.35
            shadow_pivot=0.22,
            highlight_pivot=0.68,
            softness=0.18                   # Blend softness
    ):
        self.shadow_orbit_strength = float(shadow_orbit_strength)
        self.highlight_orbit_strength = float(highlight_orbit_strength)
        self.shadow_pivot = float(shadow_pivot)
        self.highlight_pivot = float(highlight_pivot)
        self.softness = float(softness)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _orbit(self, img, angle, strength):
        """
        Applies a chromatic orbit:
          - Convert to YUV
          - Rotate U/V plane by 'angle' scaled by strength
          - Re-project back to RGB
        """
        # RGB → YUV
        m = np.array([[0.299, 0.587, 0.114],
        [-0.14713, -0.28886, 0.436],
        [0.615, -0.51499, -0.10001]], np.float32)
        flat = img.reshape(-1, 3)
        yuv = flat @ m.T

        Y = yuv[:, 0]
        U = yuv[:, 1]
        V = yuv[:, 2]

        # orbit rotation
        ang = angle * strength
        cos_a = np.cos(ang)
        sin_a = np.sin(ang)

        U2 = U * cos_a - V * sin_a
        V2 = U * sin_a + V * cos_a

        yuv2 = np.stack([Y, U2, V2], axis=1)

        # YUV → RGB
        m2 = np.array([[1.0, 0.0, 1.13983],
        [1.0, -0.39465, -0.58060],
        [1.0, 2.03211, 0.0]], np.float32)

        rgb = yuv2 @ m2.T
        rgb = rgb.reshape(img.shape)
        return np.clip(rgb, 0.0, 1.0)

    # ------------------------------------------------------------
    def apply(self, img):
        f = self._ensure_f32(img)

        # luminance (ACES coefficients)
        lum = (
            0.2126*f[...,2] +
            0.7152*f[...,1] +
            0.0722*f[...,0]
        )

        # masks for zones
        shadow_mask = 1.0 - np.clip((lum - self.shadow_pivot) /
        (self.softness + 1e-6), 0.0, 1.0)

        highlight_mask = np.clip((lum - self.highlight_pivot) /
        (self.softness + 1e-6), 0.0, 1.0)

        midtone_mask = 1.0 - shadow_mask - highlight_mask
        midtone_mask = np.clip(midtone_mask, 0.0, 1.0)

        # 1) Shadow orbit = cool drift (slight blue/cyan rotation)
        shadow_orbit = self._orbit(
            f,
            angle=-0.45,  # cool direction
            strength=self.shadow_orbit_strength
        )

        # 2) Highlight orbit = warm drift (golden tint)
        highlight_orbit = self._orbit(
            f,
            angle=0.32,  # warm direction
            strength=self.highlight_orbit_strength
        )

        # 3) Blend based on masks
        out = (
            shadow_orbit * shadow_mask[...,None] +
            f            * midtone_mask[...,None] +
            highlight_orbit * highlight_mask[...,None]
        )

        return np.clip(out, 0.0, 1.0)

