# Say “78I” to continue.
# ================================================================
# CHUNK 78 I — Ultra Film Print LUT Engine V3
#
# Film Print Stage (AFTER Negative):
#   • ACEScg → Cineon linearization
#   • Print Density Curves (Kodak 2383, Fuji 3510)
#   • Saturation Compression in Highlights
#   • Shadow Density Lift (film toe)
#   • Highlight Shoulder Rolloff
#   • Film contrast shaping
#
# This module simulates the *print* stock stage, complementing
# CHUNK 78 H (negative simulation).
#
# ================================================================

import numpy as np
import cv2

class FilmPrintLUTV3:
    """
    Ultra Film Print Stage Simulator.
    This is the final color shaping applied after negative processing.
    Includes:
      • Cineon log transforms
      • Kodak 2383 tone curves
      • Fuji Eterna print curves
      • Highlight shoulder compression
      • Adaptive saturation mapping
    """

    def __init__(self,
                 stock="kodak_2383",
                 contrast=1.12,
                 saturation=1.08,
                 highlight_rolloff=0.28,
                 toe_strength=0.18):
        
        self.stock = stock.lower()
        self.contrast = float(contrast)
        self.saturation = float(saturation)
        self.highlight_rolloff = float(highlight_rolloff)
        self.toe_strength = float(toe_strength)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _to_cineon(self, f):
        """
        ACEScg/linear → Cineon Log transform.
        Approximation with safe clamp.
        """
        f = np.clip(f, 1e-6, 1.0)
        return (np.log(f * 685.0 + 1.0) / np.log(685.0 + 1.0))

    # ------------------------------------------------------------
    def _from_cineon(self, log_img):
        """
        Cineon Log → linear.
        """
        base = np.exp(log_img * np.log(686.0))
        return np.clip((base - 1.0) / 685.0, 0.0, 1.0)

    # ------------------------------------------------------------
    def _kodak_curve(self, x):
        """
        Kodak 2383 Density Curve (approx film print contrast)
        """
        # Has a deep toe and strong shoulder
        toe = np.power(x, 0.80)
        shoulder = 1.0 - np.exp(-3.4 * x)
        blend = toe * 0.55 + shoulder * 0.45
        return blend

    # ------------------------------------------------------------
    def _fuji_curve(self, x):
        """
        Fuji 3510 print density curve.
        Slightly softer contrast, more saturation friendly.
        """
        toe = np.power(x, 0.92)
        shoulder = 1.0 - np.exp(-2.6 * x)
        return toe * 0.65 + shoulder * 0.35

    # ------------------------------------------------------------
    def _apply_curve(self, lin):
        """
        Apply selected print stock density curve.
        """
        if self.stock == "kodak_2383":
            return self._kodak_curve(lin)
        elif self.stock == "fuji_3510":
            return self._fuji_curve(lin)
        else:
            return self._kodak_curve(lin)

    # ------------------------------------------------------------
    def _apply_saturation(self, f):
        """
        Film saturation rolloff:
          - Highlights: desaturate (like real print stocks)
          - Mids/Shadows: enrich
        """
        hsv = cv2.cvtColor(f, cv2.COLOR_BGR2HSV)
        h, s, v = cv2.split(hsv)
        # Saturation curve
        sat_gain = (
            self.saturation * (1.0 - v * 0.35)  # highlight rolloff
        )
        s2 = np.clip(s * sat_gain, 0.0, 1.0)
        hsv2 = cv2.merge([h, s2, v])
        return cv2.cvtColor(hsv2, cv2.COLOR_HSV2BGR)

    # ------------------------------------------------------------
    def _apply_toe(self, f):
        """
        Film toe: gentle lift of darkest shadows.
        """
        return np.power(f, 1.0 - self.toe_strength)

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Full film print emulation pipeline.
        """
        f = self._ensure_f32(img)
        # 1) linear → cineon log
        cine = self._to_cineon(f)
        # 2) apply density curve in log domain
        curved = self._apply_curve(cine)
        # 3) convert back to linear
        lin = self._from_cineon(curved)
        # 4) apply film toe
        toe_applied = self._apply_toe(lin)
        # 5) apply saturation shaping
        saturated = self._apply_saturation(toe_applied)
        # 6) final contrast shaping
        final = np.power(saturated, 1.0 / self.contrast)
        return np.clip(final, 0.0, 1.0)

# ================================================================
# PIPELINE WRAPPER
# ================================================================

class FilmPrintModuleV3:
    def __init__(self, stock="kodak_2383"):
        self.engine = FilmPrintLUTV3(stock=stock)
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

