# CHUNK 78 Z — Film Curve Stabilizer V3
#
# Makes tone curve output consistent across frames:
#   • Eliminates exposure flicker
#   • Stabilizes highlight rolloff frame-to-frame
#   • Prevents color pulsation during motion or brightness change
#   • Maintains continuity after bloom / halation / HDR modules
#
# This is critical for drone footage where:
#   – lighting changes as drone rotates
#   – shadows pass over scene
#   – auto-exposure would otherwise wobble
#
# ================================================================

import numpy as np
import cv2

class FilmCurveStabilizerV3:
    """
    Stabilizes final ACES → Film curve output.
    Uses:
      • Rolling temporal luminance reference
      • Local contrast inertia
      • Chromatic deviation smoothing
      • Adaptive curve compensation (dynamic knee correction)
    """

    def __init__(self,
                 lum_smooth=0.85,
                 chroma_smooth=0.80,
                 contrast_stability=0.65,
                 knee_lock=0.40):
        # 0..1 smoothing values
        self.lum_smooth = float(lum_smooth)
        self.chroma_smooth = float(chroma_smooth)
        self.contrast_stability = float(contrast_stability)
        self.knee_lock = float(knee_lock)
        # persistent buffers
        self.prev_lum = None
        self.prev_img = None
        self.prev_curve_map = None

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _compute_luma(self, img):
        return 0.2126*img[...,2] + 0.7152*img[...,1] + 0.0722*img[...,0]

    # ------------------------------------------------------------
    def _smooth_luma(self, lum):
        """Temporal smoothing of luminance."""
        if self.prev_lum is None:
            self.prev_lum = lum
            return lum
        sm = (
            self.prev_lum * self.lum_smooth +
            lum * (1.0 - self.lum_smooth)
        )
        self.prev_lum = sm
        return sm

    # ------------------------------------------------------------
    def _smooth_chroma(self, img):
        """
        Prevent color wobble during exposure/bloom shifts.
        """
        if self.prev_img is None:
            self.prev_img = img
            return img
        out = (
            self.prev_img * self.chroma_smooth +
            img * (1.0 - self.chroma_smooth)
        )
        self.prev_img = out
        return out

    # ------------------------------------------------------------
    def _curve_lock(self, img, lum):
        """
        Locks knee region of tone curve (0.6–0.9).
        Prevents highlight flicker and uneven rolloff.
        """
        knee_mask = np.clip((lum - 0.55) / 0.35, 0.0, 1.0)
        if self.prev_curve_map is None:
            self.prev_curve_map = img
            return img
        locked = (
            self.prev_curve_map * self.knee_lock +
            img * (1.0 - self.knee_lock)
        )
        out = img * (1-knee_mask[...,None]) + locked * knee_mask[...,None]
        self.prev_curve_map = out
        return out

    # ------------------------------------------------------------
    def _stabilize_contrast(self, img):
        """
        Prevents micro-contrast bouncing after:
          - bloom pulses
          - highlight changes
          - scene brightness transitions
        """
        blur = cv2.GaussianBlur(img, (0,0), sigmaX=3.5)
        return (
            img * (1.0 - self.contrast_stability) +
            blur * self.contrast_stability
        )

    # ------------------------------------------------------------
    def apply(self, img):
        f = self._ensure_f32(img)
        # Step 1: Compute luminance
        lum = self._compute_luma(f)
        # Step 2: Temporal Luminance Stabilization
        lum_s = self._smooth_luma(lum)
        # Step 3: Exposure rebalance
        exp_factor = (lum_s + 1e-6) / (lum + 1e-6)
        exp_factor = np.clip(exp_factor, 0.85, 1.15)
        f2 = f * exp_factor[...,None]
        # Step 4: Smooth Chroma Over Time
        f3 = self._smooth_chroma(f2)
        # Step 5: Lock Tone-Curve Knee Region
        f4 = self._curve_lock(f3, lum_s)
        # Step 6: Contrast Stabilization
        out = self._stabilize_contrast(f4)
        return np.clip(out, 0.0, 1.0)

# ------------------------------------------------------------
class FilmCurveStabilizerModuleV3:
    def __init__(self):
        self.engine = FilmCurveStabilizerV3()

    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

