# CHUNK 79 Q C — Highlight Grain Fusion V3
# Adds:
#   • Highlight-only micro-grain
#   • ACES-compliant blending
#   • Energy-preserving texture reconstruction
#   • Grain frequency modulation based on luminance
# ================================================================

import numpy as np
import cv2

class HighlightGrainFusionV3:
    """
    Creates ultra-fine highlight-only grain to prevent overly smooth
    HDR rolloff + bloom + halation from destroying natural texture.
    
    Workflow:
      1. Build luminance mask (only bright regions)
      2. Generate micro-grain (0.5–2px)
      3. Modulate grain intensity with luminance
      4. ACES-preserving blend
    """

    def __init__(self,
                 base_intensity: float = 0.06,
                 luminance_boost: float = 0.45,
                 threshold: float = 0.72):
        
        self.base_intensity = float(base_intensity)
        self.luminance_boost = float(luminance_boost)
        self.threshold = float(threshold)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _highlight_mask(self, img):
        lum = 0.2126*img[...,2] + 0.7152*img[...,1] + 0.0722*img[...,0]
        mask = np.clip((lum - self.threshold) / (1.0 - self.threshold), 0.0, 1.0)
        return cv2.GaussianBlur(mask, (0,0), 2)[...,None]

    # ------------------------------------------------------------
    def _grain(self, h, w):
        # micro-grain: extremely fine
        noise = np.random.normal(0.0, 1.0, (h, w, 1)).astype(np.float32)
        noise = cv2.GaussianBlur(noise, (0,0), 0.4)
        return noise

    # ------------------------------------------------------------
    def apply(self, img):
        f = self._ensure_f32(img)
        h, w = f.shape[:2]

        # 1. highlight mask
        mask = self._highlight_mask(f)

        # 2. generate micro grain
        noise = self._grain(h, w)

        # 3. modulate intensity by luminance
        lum = 0.2126*f[...,2] + 0.7152*f[...,1] + 0.0722*f[...,0]
        lum_boost = np.clip(lum[...,None] * self.luminance_boost, 0.0, 1.0)

        intensity = self.base_intensity * mask * lum_boost

        # 4. blend grain with image
        out = f + noise * intensity
        return np.clip(out, 0.0, 1.0)

# ------------------------------------------------------------
class HighlightGrainFusionModuleV3:
    def __init__(self):
        self.engine = HighlightGrainFusionV3()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

