# ================================================================
# CHUNK 79 Q P — Film Gate Weave + Mechanical Vibration Simulator V4
# Provides:
#   • Sub-pixel analog gate weave (X/Y drifting like film projector)
#   • Micro-vibration blur (emulates sensor/gimbal imperfections)
#   • Rolling-shutter wobble (GoPro & IMX sensors)
#   • Motion-aware stabilization blending
#   • Temporal coherence using low-frequency noise
# ================================================================

import numpy as np
import cv2
import math

class GateWeaveV4:
    """
    Ultra-level film motion instability simulator.
    This NEVER affects drone control — only the final video aesthetic.
    """

    def __init__(self,
                 weave_intensity: float = 0.65,
                 micro_vibration: float = 0.25,
                 rolling_shutter: float = 0.12,
                 temporal_speed: float = 0.015,
                 motion_protect: float = 0.85,
                 temporal_seed: int = 99123):

        self.weave_intensity = float(weave_intensity)
        self.micro_vibration = float(micro_vibration)
        self.rolling = float(rolling_shutter)
        self.tspeed = float(temporal_speed)
        self.mprotect = float(np.clip(motion_protect, 0.0, 1.0))

        self.frame_idx = 0
        self.rng = np.random.default_rng(temporal_seed)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _low_freq_noise(self):
        """
        Smooth temporal drift → gives analog film gate wobble look.
        """
        t = self.frame_idx * self.tspeed
        # Low-frequency sin/noise blend
        drift_x = (
            math.sin(t * 1.3) * 0.5 +
            math.sin(t * 0.27) * 0.35 +
            self.rng.normal(0, 0.02)
        )
        drift_y = (
            math.sin(t * 1.7) * 0.4 +
            math.sin(t * 0.12) * 0.25 +
            self.rng.normal(0, 0.02)
        )
        return drift_x, drift_y

    # ------------------------------------------------------------
    def _apply_gate_weave(self, img, dx, dy):
        """
        Apply 2D sub-pixel translation.
        """
        h, w = img.shape[:2]
        M = np.float32([[1, 0, dx], [0, 1, dy]])
        return cv2.warpAffine(
            img, M, (w, h),
            flags=cv2.INTER_LINEAR,
            borderMode=cv2.BORDER_REFLECT
        )

    # ------------------------------------------------------------
    def _apply_micro_vibration(self, img):
        """
        Adds very subtle blur to emulate real camera vibration.
        """
        sigma = self.micro_vibration * 0.65
        return cv2.GaussianBlur(img, (0,0), sigma)

    # ------------------------------------------------------------
    def _rolling_shutter_warp(self, img):
        """
        Slight sinusoidal vertical displacement per scanline.
        """
        if self.rolling <= 0:
            return img
        h, w = img.shape[:2]
        out = np.zeros_like(img)
        # Compute horizontal phase drift
        t = self.frame_idx * 0.03
        for y in range(h):
            warp = int(math.sin((y * 0.012) + t) * self.rolling * 12)
            out[y] = np.roll(img[y], warp, axis=0)
        return out

    # ------------------------------------------------------------
    def apply(self, img, motion_mask=None):
        """
        Applies everything:
          1. Low-frequency analog drift (gate weave)
          2. Micro-vibration blur
          3. Rolling shutter warp
          4. Motion aware suppression
        """
        f = self._ensure_f32(img)

        # 1) Compute analog drift
        dx, dy = self._low_freq_noise()
        dx *= self.weave_intensity
        dy *= self.weave_intensity

        # Apply sub-pixel weave
        out = self._apply_gate_weave(f, dx, dy)

        # 2) Apply vibration
        out = self._apply_micro_vibration(out)

        # 3) Rolling shutter warp
        out = self._rolling_shutter_warp(out)

        # 4) Motion-based suppression
        if motion_mask is not None:
            sup = 1.0 - motion_mask[...,None] * self.mprotect
            out = f * (1-sup) + out * sup

        # Increment frame counter
        self.frame_idx += 1
        return np.clip(out, 0.0, 1.0)

# ------------------------------------------------------------
class GateWeaveModuleV4:
    def __init__(self):
        self.engine = GateWeaveV4()
    def apply(self, frame_float01, motion_mask=None):
        return self.engine.apply(frame_float01, motion_mask=motion_mask)

