# ================================================================
# CHUNK 79 Q Q — OPTICAL BREATHING EMULATOR + AI ZOOM STABILIZER V2
#
# Features:
#   • Lens breathing simulation (film/photography lens realism)
#   • AI subject-distance estimation → adaptive breathing scaling
#   • Highlight-driven breathing suppression
#   • Depth-change-based zoom smoothing (AI-stabilized)
#   • Target-size lock zoom controller (matches cinematic framing rules)
#   • Temporal zoom smoothing (prevents zoom jitter)
# ================================================================

import numpy as np
import cv2
import math

class OpticalBreathingV2:
    """
    Ultra Pro Max Lens Breathing Emulator.
    Emulates lens FOV changes based on focus distance.
    This affects only video aesthetic, NOT drone control.
    """

    def __init__(self,
                 breathing_strength: float = 0.035,
                 highlight_protect: float = 0.6,
                 temporal_smooth: float = 0.9,
                 min_zoom: float = 1.00,
                 max_zoom: float = 1.25):

        self.strength = float(breathing_strength)
        self.hl_protect = float(np.clip(highlight_protect, 0.0, 1.0))
        self.smooth = float(np.clip(temporal_smooth, 0.0, 0.99))

        self.min_zoom = float(min_zoom)
        self.max_zoom = float(max_zoom)

        self.prev_zoom = 1.0

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _highlight_mask(self, img):
        lum = 0.2126*img[...,2] + 0.7152*img[...,1] + 0.0722*img[...,0]
        mask = np.clip((lum - 0.85) / 0.15, 0.0, 1.0)
        return cv2.GaussianBlur(mask, (0,0), 8)

    # ------------------------------------------------------------
    def compute_zoom_factor(self, depth_val, highlight_mask=None):
        """
        AI Depth → Zoom breathing mapping.
        depth_val = estimated target normalized depth (0=far, 1=near)
        """
        # Base breathing curve
        base = 1.0 + depth_val * self.strength

        # Highlight protection (to avoid zoom on bright scenes)
        if highlight_mask is not None:
            hl = float(np.mean(highlight_mask))
            base *= (1.0 - hl * self.hl_protect)

        # Clamp zoom
        base = np.clip(base, self.min_zoom, self.max_zoom)

        # Temporal smooth
        out = self.prev_zoom * self.smooth + base * (1 - self.smooth)
        self.prev_zoom = out

        return float(out)

    # ------------------------------------------------------------
    def _apply_zoom(self, img, z):
        """
        Zooms using center crop + upscale (lossless-like at small ranges).
        """
        if abs(z - 1.0) < 1e-6:
            return img

        h, w = img.shape[:2]

        new_w = int(w / z)
        new_h = int(h / z)

        x0 = (w - new_w) // 2
        y0 = (h - new_h) // 2

        crop = img[y0:y0+new_h, x0:x0+new_w]
        resized = cv2.resize(crop, (w, h), interpolation=cv2.INTER_LINEAR)
        return resized

    # ------------------------------------------------------------
    def apply(self, img, depth_norm=0.0):
        """
        Full breathing pipeline:
          1. Compute highlight mask
          2. Compute zoom from depth + highlights
          3. Apply center crop zoom
        """
        f = self._ensure_f32(img)

        hl_mask = self._highlight_mask(f)
        zoom = self.compute_zoom_factor(depth_norm, hl_mask)

        out = self._apply_zoom(f, zoom)
        return np.clip(out, 0.0, 1.0), zoom


# ================================================================
# AI SUBJECT ZOOM STABILIZER MODULE V2
# ================================================================

class AIZoomStabilizerV2:
    """
    Uses AI tracking box size to stabilize zoom while keeping
    subject cinematic size (FILM RULE: 15%–30% screen area).
    """

    def __init__(self,
                 target_area: float = 0.22,   # ideal subject fill
                 tol: float = 0.10,           # tolerance band
                 zoom_speed: float = 0.08,
                 temporal_smooth: float = 0.88):

        self.target_area = float(target_area)
        self.tol = float(tol)
        self.zoom_speed = float(zoom_speed)
        self.smooth = float(temporal_smooth)

        self.prev_zoom = 1.0

    # ------------------------------------------------------------
    def compute_from_box(self, box, frame_shape):
        """
        box: [cx, cy, w, h] from YOLO tracker
        Output: zoom factor (1.0–1.4)
        """
        if box is None:
            return self.prev_zoom

        h, w, _ = frame_shape
        _, _, bw, bh = box

        area = (bw * bh) / (w * h)

        # Determine zoom delta
        if area < self.target_area - self.tol:
            dz = 1 + self.zoom_speed  # zoom in
        elif area > self.target_area + self.tol:
            dz = 1 - self.zoom_speed  # zoom out
        else:
            dz = 1.0  # hold

        # Combine with temporal smoothing
        out = self.prev_zoom * self.smooth + dz * (1 - self.smooth)
        self.prev_zoom = out

        return float(out)


# ================================================================
# PIPELINE WRAPPER — Optical Breathing + AI Zoom
# ================================================================

class ZoomModuleV2:
    def __init__(self):
        self.breath = OpticalBreathingV2()
        self.ai_zoom = AIZoomStabilizerV2()

    def apply(self, frame_float01, yolo_box=None, depth_norm=0.0):
        """
        yolo_box → from VisionPipeline detection/tracking
        depth_norm → AI-estimated subject proximity
        """

        # AI zoom based on subject size
        z_subject = self.ai_zoom.compute_from_box(yolo_box, frame_float01.shape)

        # Breathing zoom based on depth
        _breath_out, z_breath = self.breath.apply(frame_float01, depth_norm)

        # Combine zooms multiplicatively
        z_final = z_subject * z_breath
        z_final = float(np.clip(z_final, 1.0, 1.35))

        # Apply final zoom
        out = self.breath._apply_zoom(frame_float01, z_final)

        return out, {
            "zoom_subject": float(z_subject),
            "zoom_breath": float(z_breath),
            "zoom_final": float(z_final),
        }


