# PIPELINE WRAPPER — Motion Deblur V5
# ================================================================

class MotionDeblurModuleV5:
    def __init__(self):
        self.engine = MotionDeblurV5()

    def apply(self, frame_float01, optical_flow=None):
        return self.engine.apply(frame_float01, flow=optical_flow)


