# ================================================================
# CHUNK 79 Q U — AI HIGHLIGHT GLOW COMPRESSOR V4
#
# PURPOSE:
#   • Recover burned highlights without flattening the image
#   • Apply film-style soft roll-off (Alexa / Venice-inspired)
#   • Reduce harsh glow introduced by bloom/halation stacks
#   • Maintain ACES color balance while reducing clipping
#   • Neural-guided reconstruction of lost detail (optional)
#
# INPUTS:
#   frame_float01 : 0–1 linear image
#   optional highlight_mask : 0–1 mask from previous modules
#
# OUTPUT:
#   highlight-corrected image (non-destructive)
#
# ================================================================
import numpy as np
import cv2

class HighlightGlowCompressorV4:
    """
    AI-inspired highlight stabilizer:
      - Smooth compression (soft knee)
      - Gradient-aware reconstruction
      - Glow removal without killing cinematic bloom
      - Protects skin tones and warm highlights
    """

    def __init__(self,
                 rolloff_start: float = 0.72,
                 rolloff_end: float = 0.94,
                 glow_reduction: float = 0.55,
                 detail_recovery: float = 0.35,
                 chroma_protect: float = 0.85):

        self.roll_s = float(rolloff_start)
        self.roll_e = float(rolloff_end)
        self.glow_red = float(glow_reduction)
        self.detail_rec = float(detail_recovery)
        self.chroma_protect = float(chroma_protect)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        return img.astype(np.float32) if img.dtype != np.float32 else img

    # ------------------------------------------------------------
    def _soft_knee(self, x):
        """Smoothstep-like soft knee for highlight rolloff."""
        return x * x * (3 - 2*x)

    # ------------------------------------------------------------
    def _local_contrast(self, gray):
        """Detect micro-contrast loss area to guide healing."""
        blur = cv2.GaussianBlur(gray, (0,0), 3)
        return np.abs(gray - blur)

    # ------------------------------------------------------------
    def _edge_detail_map(self, img):
        """High-frequency edge map for detail recovery."""
        lap = cv2.Laplacian(img, cv2.CV_32F)
        mag = np.abs(lap)
        mag = cv2.GaussianBlur(mag, (0,0), 1.2)
        return mag

    # ------------------------------------------------------------
    def apply(self, img, highlight_mask=None):
        """
        Main highlight compression pipeline.
        """
        f = self._ensure_f32(img)
        h, w = f.shape[:2]

        # Luminance
        lum = 0.2126*f[...,2] + 0.7152*f[...,1] + 0.0722*f[...,0]

        # Base mask if none provided
        if highlight_mask is None:
            mask = np.clip((lum - self.roll_s) / (self.roll_e - self.roll_s), 0, 1)
            mask = cv2.GaussianBlur(mask, (0,0), 3)
        else:
            mask = cv2.resize(highlight_mask, (w, h)).astype(np.float32)

        # Soft knee for cinematic highlight rolloff
        knee = self._soft_knee(mask)

        # Reduce excessive glow
        compressed = f * (1 - knee[...,None] * self.glow_red)

        # Detail recovery maps
        gray = cv2.cvtColor((compressed*255).astype(np.uint8), cv2.COLOR_BGR2GRAY).astype(np.float32) / 255.0
        contrast_map = self._local_contrast(gray)
        edge_map = self._edge_detail_map(gray)

        # Merge detail maps
        detail_mask = cv2.normalize(contrast_map + edge_map, None, 0, 1, cv2.NORM_MINMAX)

        # Heal clipped areas using recovered detail
        heal = (detail_mask[...,None] * self.detail_rec)

        # Apply chroma protection
        comp_r = compressed[...,2] * (1 - heal) + f[...,2] * heal * self.chroma_protect
        comp_g = compressed[...,1] * (1 - heal) + f[...,1] * heal * self.chroma_protect
        comp_b = compressed[...,0] * (1 - heal) + f[...,0] * heal * self.chroma_protect

        out = np.stack([comp_b, comp_g, comp_r], axis=2)
        return np.clip(out, 0.0, 1.0)


# ================================================================
# PIPELINE WRAPPER
# ================================================================
class HighlightGlowCompressorModuleV4:
    def __init__(self):
        self.engine = HighlightGlowCompressorV4()

    def apply(self, frame_float01, highlight_mask=None):
        return self.engine.apply(frame_float01, highlight_mask)


