# CHUNK 79 Q Y — AI SUBJECT ISOLATION MASK REFINEMENT V4
#
# PURPOSE:
#   Create ultra-clean subject masks for cinematic pipelines:
#     - bloom shaping
#     - halation suppression
#     - rim-light enhancement
#     - depth-aware glow falloff
#
#   Uses:
#     • segmentation logits
#     • optical flow boundaries
#     • Laplacian edges
#     • depth-hint smoothing (if available)
#     • temporal stabilization (EMA)
#
# OUTPUT:
#     refined_mask: float32 mask 0..1, stable, smooth, edge-accurate
# ================================================================
import numpy as np
import cv2
class SubjectMaskRefinerV4:
    """
    Ultra-refinement engine for subject masks:
      - combines segmentation, edges, flow, depth
      - fixes flicker via temporal smoothing
      - guarantees clean silhouette boundaries
    """
    def __init__(self, temporal_smooth=0.82):
        self.prev_mask = None
        self.temporal_smooth = float(np.clip(temporal_smooth, 0.0, 0.99))
    # ------------------------------------------------------------
    def _ensure_f32(self, x):
        return x.astype(np.float32) if x.dtype != np.float32 else x
    # ------------------------------------------------------------
    def _edge_refine(self, mask, frame):
        """
        Sharpens mask near real edges of subject.
        """
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        edges = cv2.Laplacian(gray, cv2.CV_32F, ksize=3)
        edges = np.abs(edges)
        edges = cv2.GaussianBlur(edges, (0,0), 1.4)
        # Normalize edges to range 0..1
        e = edges / (np.max(edges) + 1e-6)
        # Strengthen mask where edges indicate boundary
        sharpen = mask + (e * 0.35)
        return np.clip(sharpen, 0.0, 1.0)
    # ------------------------------------------------------------
    def _flow_refine(self, mask, flow):
        """
        Motion edges refine foreground outline.
        flow: optical flow magnitude or full flow map
        """
        if flow is None:
            return mask
        if flow.ndim == 3:
            fx, fy = flow[...,0], flow[...,1]
            mag = np.sqrt(fx*fx + fy*fy)
        else:
            mag = flow
        mag = cv2.GaussianBlur(mag, (0,0), 1.5)
        m = mag / (np.max(mag) + 1e-6)
        refine = mask + m * 0.25
        return np.clip(refine, 0.0, 1.0)
    # ------------------------------------------------------------
    def _depth_smooth(self, mask, depth):
        """
        Depth-guided smoothing:
        - foreground usually closer
        - smooths uneven segmentation noise
        """
        if depth is None:
            return mask
        d = depth.astype(np.float32)
        d = cv2.GaussianBlur(d, (0,0), 3.0)
        # Normalize depth
        dn = (d - np.min(d)) / (np.max(d) - np.min(d) + 1e-6)
        # Foreground boost for near-depth
        depth_boost = (1.0 - dn) * 0.30
        smoothed = mask + depth_boost
        return np.clip(smoothed, 0.0, 1.0)
    # ------------------------------------------------------------
    def _temporal_stable(self, mask):
        if self.prev_mask is None:
            self.prev_mask = mask
            return mask
        stabilized = (
            self.prev_mask * self.temporal_smooth +
            mask * (1.0 - self.temporal_smooth)
        )
        self.prev_mask = stabilized
        return stabilized
    # ------------------------------------------------------------
    def refine(self, base_mask, frame, flow=None, depth=None):
        """
        Main refinement function.
        """
        m = self._ensure_f32(base_mask)
        # 1) Edge guided refinement
        m = self._edge_refine(m, frame)
        # 2) Flow-guided motion boundary refinement
        m = self._flow_refine(m, flow)
        # 3) Depth smoothing
        m = self._depth_smooth(m, depth)
        # 4) Final blur for natural mask rolloff
        m = cv2.GaussianBlur(m, (0,0), 2.0)
        # 5) Temporal stabilization
        m = self._temporal_stable(m)
        # 6) Final clip
        return np.clip(m, 0.0, 1.0)
# ================================================================
# WRAPPER
# ================================================================
class SubjectMaskModuleV4:
    def __init__(self):
        self.engine = SubjectMaskRefinerV4()
    def apply(self, base_mask, frame_float01, flow=None, depth=None):
        return self.engine.refine(base_mask, frame_float01, flow, depth)
