# ================================================================
# CHUNK 80 E — AI-DRIVEN SCENE EMOTION ENHANCER V1
#
# PURPOSE:
#   • Detect emotional tone from image statistics
#   • Apply micro-contrast, micro-saturation and tone biases
#   • Compliments Color Narrative Engine (Chunk 80D)
#   • Mimics Hollywood “Emotional Node Stack” grading practice
# ================================================================

import numpy as np
import cv2

class EmotionEnhancerV1:
    """
    Emotion-based micro-grading engine.
    Inputs:
      - Frame (float32, 0..1)
    Outputs:
      - Emotion-biased frame (float32, 0..1)
    """

    def __init__(self, smooth=0.92):
        self.prev_vec = None
        self.smooth = float(smooth)

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _analyze_emotion(self, img):
        """
        Compute emotional indicators from the frame.
        """
        hsv = cv2.cvtColor(img, cv2.COLOR_BGR2HSV)
        lum = 0.2126*img[...,2] + 0.7152*img[...,1] + 0.0722*img[...,0]

        brightness = float(np.mean(lum))
        contrast   = float(np.std(lum))
        sat        = float(np.mean(hsv[...,1]) / 255.0)
        r_mean = float(np.mean(img[...,2]))
        b_mean = float(np.mean(img[...,0]))
        temp_bias = r_mean - b_mean

        fast_edges = cv2.Canny((lum*255).astype(np.uint8), 40, 90)
        motion_energy = np.mean(fast_edges) / 255.0
        return {
            "brightness": brightness,
            "contrast": contrast,
            "saturation": sat,
            "temp_bias": temp_bias,
            "motion_energy": motion_energy
        }

    # ------------------------------------------------------------
    def _emotion_vector(self, f):
        """
        Map features into emotional distributions:
            calm
warm_romantic
energetic_fast
tension
danger_highcontrast
isolation_cold
dreamy_soft
        """
        b = f["brightness"]
        c = f["contrast"]
        s = f["saturation"]
        t = f["temp_bias"]
        m = f["motion_energy"]
        calm           = max(0.0, (1-m)*0.6 + (1-c)*0.4)
        warm_romantic  = max(0.0,  t*0.8 + b*0.3)
        energetic_fast = max(0.0,  m*0.9 + s*0.5)
        tension        = max(0.0,  c*0.8 + (1-b)*0.3)
        danger_contrast= max(0.0,  c*1.2 + m*0.4)
        isolation_cold = max(0.0, -t*0.9 + (1-s)*0.3)
        dreamy_soft    = max(0.0, (1-c)*0.5 + (b*0.3))
        vec = np.array([
            calm,
            warm_romantic,
            energetic_fast,
            tension,
            danger_contrast,
            isolation_cold,
            dreamy_soft
        ], dtype=np.float32)
        if np.sum(vec) < 1e-5:
            vec = np.ones_like(vec)
        vec /= np.sum(vec)
        return vec

    # ------------------------------------------------------------
    def _smooth_vec(self, new):
        if self.prev_vec is None:
            self.prev_vec = new
            return new
        sm = self.prev_vec*self.smooth + new*(1-self.smooth)
        self.prev_vec = sm
        return sm

    # ------------------------------------------------------------
    def _apply_emotion(self, img, w):
        """
        Apply each emotional modulation:
          calm -> soften contrast
          warm romantic -> warm shadows/mids
          energetic -> boost local contrast + sat
          tension -> cool tint + contrast slope
          danger -> darken shadows, push red
          isolation -> heavy desat + cold shadow bias
          dreamy -> reduced clarity + pastel rolloff
        """
        (wc, ww, we, wt, wd, wi, ws) = w
        f = img.copy()

        # --- Calm ---
        if wc > 0:
            f = f*(1 - 0.10*wc) + cv2.GaussianBlur(f, (0,0), 6)*(0.10*wc)

        # --- Warm Romantic ---
        if ww > 0:
            f[...,2] *= (1 + ww*0.10)
            f[...,0] *= (1 - ww*0.06)

        # --- Energetic ---
        if we > 0:
            hsv = cv2.cvtColor(f, cv2.COLOR_BGR2HSV)
            hsv[...,1] = np.clip(hsv[...,1]*(1 + we*0.22), 0, 255)
            f = cv2.cvtColor(hsv, cv2.COLOR_HSV2BGR)

        # --- Tension ---
        if wt > 0:
            f[...,0] *= (1 + wt*0.12)
            f = np.clip(f, 0.0, 1.0)

        # --- Danger ---
        if wd > 0:
            f[...,2] *= (1 + wd*0.18)
            f[...,1] *= (1 - wd*0.10)
            f = np.clip(f, 0.0, 1.0)

        # --- Isolation Cold ---
        if wi > 0:
            f[...,1] *= (1 - wi*0.25)
            f[...,2] *= (1 - wi*0.15)
            f[...,0] *= (1 + wi*0.20)

        # --- Dreamy Soft ---
        if ws > 0:
            soft = cv2.GaussianBlur(f, (0,0), 12)
            f = f*(1 - ws*0.18) + soft*(ws*0.18)

        return np.clip(f, 0.0, 1.0)

    # ------------------------------------------------------------
    def apply(self, frame):
        f = self._ensure_f32(frame)
        feat = self._analyze_emotion(f)
        vec = self._emotion_vector(feat)
        vec = self._smooth_vec(vec)
        out = self._apply_emotion(f, vec)
        return out

# ---------------------------------------------------------------
class EmotionEnhancerModuleV1:
    def __init__(self):
        self.engine = EmotionEnhancerV1()
    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

