# =============================================================
class LensEmulatorV5:
    """
    Extremely advanced cinematic lens emulator.
    Applies:
      - MTF-based softness
      - Field curvature
      - Cat-eye bokeh deformation
      - CA dispersion
      - Swirl DOF distortion
      - Breathing (FOV modulation)
    """
    def __init__(self, profile_name="cooke_s4"):
        if profile_name not in LENS_PROFILES:
            raise ValueError(f"Unknown lens: {profile_name}")
        self.profile = LENS_PROFILES[profile_name]

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _apply_breathing(self, img):
        """
        FOV shift proportional to focus distance.
        Simulated by slight scaling.
        """
        ratio = 1.0 + self.profile.breathing_ratio
        h, w = img.shape[:2]
        scaled = cv2.resize(img, (int(w*ratio), int(h*ratio)))
        # Crop back to original
        sh, sw = scaled.shape[:2]
        x0 = (sw - w) // 2
        y0 = (sh - h) // 2
        return scaled[y0:y0+h, x0:x0+w]

    # ------------------------------------------------------------
    def _apply_mtf_softness(self, img):
        """
        Softens edges based on MTF curve.
        """
        h, w = img.shape[:2]
        cx, cy = w/2, h/2
        xs = (np.arange(w) - cx) / cx
        ys = (np.arange(h) - cy) / cy
        xv, yv = np.meshgrid(xs, ys)
        r = np.sqrt(xv**2 + yv**2)
        mtf = self.profile.mtf_center + (self.profile.mtf_edge - self.profile.mtf_center) * r
        mtf = np.clip(mtf, 0.0, 1.0)
        # Blur image
        blurred = cv2.GaussianBlur(img, (0,0), 5)
        out = img * mtf[...,None] + blurred * (1.0 - mtf[...,None])
        return out

    # ------------------------------------------------------------
    def _apply_field_curvature(self, img):
        """
        Moves focus plane into a gentle curve.
        """
        h, w = img.shape[:2]
        cx, cy = w/2, h/2
        xs = (np.arange(w) - cx) / cx
        ys = (np.arange(h) - cy) / cy
        xv, yv = np.meshgrid(xs, ys)
        curvature = self.profile.field_curvature
        defocus_mask = (xv**2 + yv**2) * curvature
        blur = cv2.GaussianBlur(img, (0,0), 7)
        out = img * (1.0 - defocus_mask[...,None]) + blur * defocus_mask[...,None]
        return np.clip(out, 0.0, 1.0)

    # ------------------------------------------------------------
    def _apply_cat_eye_bokeh(self, img):
        """
        Compress edges → creates oval bokeh near corners.
        """
        h, w = img.shape[:2]
        strength = self.profile.cat_eye_strength
        M = np.float32([
            [1, strength*0.12, 0],
            [strength*0.06, 1, 0]
        ])
        warped = cv2.warpAffine(img, M, (w, h),
        flags=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_REFLECT)
        return warped

    # ------------------------------------------------------------
    def _apply_swirl(self, img):
        """
        Radial DOF swirl like vintage Petzval lenses.
        """
        h, w = img.shape[:2]
        cx, cy = w/2, h/2
        swirl_s = self.profile.swirl_strength
        xs = (np.arange(w) - cx) / cx
        ys = (np.arange(h) - cy) / cy
        xv, yv = np.meshgrid(xs, ys)
        angle = swirl_s * (xv**2 + yv**2)
        sin_a = np.sin(angle)
        cos_a = np.cos(angle)
        x_new = xv*cos_a - yv*sin_a
        y_new = xv*sin_a + yv*cos_a
        x_new = (x_new * cx + cx).astype(np.float32)
        y_new = (y_new * cy + cy).astype(np.float32)
        swirled = cv2.remap(img, x_new, y_new,
        interpolation=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_REFLECT)
        return swirled

    # ------------------------------------------------------------
    def _apply_chromatic_aberration(self, img):
        """
        Radial CA separation.
        """
        h, w = img.shape[:2]
        cx, cy = w/2, h/2
        ca = self.profile.chroma_amount
        xs = (np.arange(w) - cx) / cx
        ys = (np.arange(h) - cy) / cy
        xv, yv = np.meshgrid(xs, ys)
        r = np.sqrt(xv**2 + yv**2)
        shift = (r * ca * w).astype(np.float32)
        # Shift channels differently
        def shift_channel(img_ch, dx):
            map_x = (xv*cx + cx + dx).astype(np.float32)
            map_y = (yv*cy + cy).astype(np.float32)
            return cv2.remap(img_ch, map_x, map_y,
        interpolation=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_REFLECT)
        b = shift_channel(img[...,0], -shift)
        g = shift_channel(img[...,1], 0)
        r = shift_channel(img[...,2], +shift)
        return np.stack([b, g, r], axis=2)

    # ------------------------------------------------------------
    def apply(self, img):
        """
        Full Lens Simulation Pipeline.
        """
        f = self._ensure_f32(img)
        # 1. Breathing
        f = self._apply_breathing(f)
        # 2. MTF softening
        f = self._apply_mtf_softness(f)
        # 3. Field curvature
        f = self._apply_field_curvature(f)
        # 4. Cat-eye oval bokeh deformation
        f = self._apply_cat_eye_bokeh(f)
        # 5. Swirl distortion
        f = self._apply_swirl(f)
        # 6. Chromatic Aberration
        f = self._apply_chromatic_aberration(f)
        return np.clip(f, 0.0, 1.0)

# ------------------------------------------------------------
