# =============================================================
class FilmEmulationV6:
    """
    Ultra cinematic film emulation using:
      – Spectral remapping
      – Film density S-curve
      – Saturation compression
      – Highlight chroma preservation
      – Halation boost hook (merged with halation engine)
    """
    def __init__(self, stock="kodak_250d"):
        if stock not in FILM_STOCKS:
            raise ValueError(f"Unknown film stock: {stock}")
        self.stock = FILM_STOCKS[stock]

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _apply_spectral_tint(self, img):
        """
        Applies film spectral shadow/mid/highlight coloration.
        """
        hls = cv2.cvtColor(img, cv2.COLOR_BGR2HLS)
        L = hls[...,1]
        # Blend between shadow/mid/high coefficients
        w_sh = np.clip((0.5 - L) * 2.0, 0.0, 1.0)
        w_hi = np.clip((L - 0.5) * 2.0, 0.0, 1.0)
        w_md = 1.0 - w_sh - w_hi
        r = img[...,2]
        g = img[...,1]
        b = img[...,0]
        r_new = (r * (w_sh*self.stock.rgb_shadows[2] +
        w_md*self.stock.rgb_mids[2] +
        w_hi*self.stock.rgb_highs[2]))
        g_new = (g * (w_sh*self.stock.rgb_shadows[1] +
        w_md*self.stock.rgb_mids[1] +
        w_hi*self.stock.rgb_highs[1]))
        b_new = (b * (w_sh*self.stock.rgb_shadows[0] +
        w_md*self.stock.rgb_mids[0] +
        w_hi*self.stock.rgb_highs[0]))
        return np.stack([b_new, g_new, r_new], axis=2)

    # ------------------------------------------------------------
    def _apply_density_curve(self, img):
        """
        Film "toe" and "shoulder" density compression.
        """
        x = np.clip(img, 0.0, 1.0)
        # Toe: shadow lift
        toe = 0.10
        x = x + toe * (1.0 - np.exp(-x*8.0))
        # Shoulder: highlight compression
        shoulder = self.stock.contrast
        x = 1.0 - (1.0 - x)**shoulder
        return np.clip(x, 0.0, 1.0)

    # ------------------------------------------------------------
    def _apply_saturation(self, img):
        """
        Saturation adjustment with chroma protection in highlights.
        """
        hsv = cv2.cvtColor(img, cv2.COLOR_BGR2HSV)
        H, S, V = cv2.split(hsv)
        # Highlight chroma falloff
        protect = np.clip(1.0 - (V - 0.65) * 2.0, 0.0, 1.0)
        boost = 1.0 + (self.stock.sat - 1.0) * protect
        S = np.clip(S * boost, 0, 1)
        hsv_new = cv2.merge([H, S, V])
        return cv2.cvtColor(hsv_new, cv2.COLOR_HSV2BGR)

    # ------------------------------------------------------------
    def _apply_halation_boost(self, img):
        """
        Boosts halation channels before halation module.
        (This does NOT produce halation here — it modifies the feed.)
        """
        h = self.stock.hal_boost
        img[...,2] *= (1.0 + h * 0.8)
        img[...,1] *= (1.0 + h * 0.3)
        img[...,0] *= (1.0 + h * 0.1)
        return np.clip(img, 0.0, 1.0)

    # ------------------------------------------------------------
    def apply(self, frame):
        """
        Full Film Emulation Pipeline.
        """
        f = self._ensure_f32(frame)

        # 1. Spectral tint shaping
        f = self._apply_spectral_tint(f)

        # 2. Film density curve
        f = self._apply_density_curve(f)

        # 3. Saturation model (highlight protected)
        f = self._apply_saturation(f)

        # 4. Halation boost (pre-feed to halation module)
        f = self._apply_halation_boost(f)

        return np.clip(f, 0.0, 1.0)

# ------------------------------------------------------------
class FilmEmulationModuleV6:
    def __init__(self, stock="kodak_250d"):
        self.engine = FilmEmulationV6(stock)

    def apply(self, frame_float01):
        return self.engine.apply(frame_float01)

