# ==============================================================================
# CHUNK 80Z-A — ULTRA FILM GATE-WEAVE + ANALOG JITTER ENGINE V1 (Refined)
# ==============================================================================
# Physically-plausible analog camera jitter simulator:
#   • Gaussian micro-jitter (per-frame seating error)
#   • Dual-octave Perlin drift (low-frequency film wandering)
#   • Multi-band telecine vibration (8/14/22 Hz projector hum)
#   • Rotational gate-roll (±0.05° typical)
#   • Anisotropic heat-expansion breathing (projector lamp heat)
# Produces subpixel-accurate motion for ultimate realism.
# ==============================================================================

import numpy as np
import cv2
import math

class GateWeaveEngineV1:
    """
    Refined analog film gate-weave simulator.
    Internal state includes:
      • frame_index      : driving temporal signal
      • improved Perlin  : gradient + permutation table
      • dual-octave drift: prevents repetition patterns
    """

    def __init__(self, intensity=1.0, fps=24.0):
        self.intensity = float(intensity)
        self.fps = float(fps)
        # Frame Index (clamped to avoid float overflow)
        self.frame_index = 0
        # Build high-resolution gradient & permutation tables
        self._grad_size = 1024
        self._grad = np.random.uniform(-1, 1, self._grad_size).astype(np.float32)
        self._perm = np.arange(self._grad_size, dtype=np.int32)
        np.random.shuffle(self._perm)
    # --------------------------------------------------------------------------
    # HIGH-FIDELITY 1D PERLIN NOISE
    # --------------------------------------------------------------------------
    def _perlin_1d(self, x):
        xi = int(x) % self._grad_size
        xf = x - int(x)
        # smootherstep (more film-like than standard fade)
        u = xf * xf * xf * (xf * (xf * 6 - 15) + 10)
        g0 = self._grad[self._perm[xi]]
        g1 = self._grad[self._perm[(xi + 1) % self._grad_size]]
        n0 = g0 * xf
        n1 = g1 * (xf - 1)
        return (1 - u) * n0 + u * n1

    # --------------------------------------------------------------------------
    # COMPUTE ADVANCED MOTION PARAMETERS
    # --------------------------------------------------------------------------
    def compute_motion_params(self):
        t = float(self.frame_index)
        I = self.intensity
        # 1. Gaussian micro-jitter (core gate weave)
        jitter_x = np.random.normal(0, 0.15 * I)
        jitter_y = np.random.normal(0, 0.15 * I)
        # 2. Dual-octave Perlin drift — MUCH more cinematic
        drift_x = (
            self._perlin_1d(t * 0.020) * 0.25 +
            self._perlin_1d(t * 0.005) * 0.10
        ) * I
        drift_y = (
            self._perlin_1d(t * 0.018 + 123) * 0.25 +
            self._perlin_1d(t * 0.004 + 321) * 0.10
        ) * I
        # 3. Multi-band telecine vibration (synced to projector hum)
        phase = (2.0 * math.pi * t) / self.fps
        vib = (
            math.sin(phase * 8.0 ) * 0.050 +
            math.sin(phase * 14.0) * 0.030 +
            math.sin(phase * 22.0) * 0.020
        ) * I
        # 4. Rotational jitter (gate roll)
        rot = np.random.normal(0, 0.05 * I)
        return {
            "dx": jitter_x + drift_x + vib,
            "dy": jitter_y + drift_y + vib * 0.6,
            "rot": rot
        }

    # --------------------------------------------------------------------------
    # APPLY TRANSFORM
    # --------------------------------------------------------------------------
    def apply(self, frame):
        if frame is None:
            return None
        h, w = frame.shape[:2]
        params = self.compute_motion_params()
        dx = float(params["dx"])
        dy = float(params["dy"])
        angle = float(params["rot"])
        # Rotation matrix
        M = cv2.getRotationMatrix2D((w / 2, h / 2), angle, 1.0)
        M[0, 2] += dx
        M[1, 2] += dy
        warped = cv2.warpAffine(
            frame, M, (w, h),
            flags=cv2.INTER_LINEAR,
            borderMode=cv2.BORDER_REFLECT_101
        )
        # Optional anisotropic heat breathing (improved realism)
        breath = 1.0 + (math.sin(self.frame_index * 0.011) * 0.00065 * self.intensity)
        if abs(breath - 1.0) > 1e-5:
            M2 = cv2.getRotationMatrix2D((w / 2, h / 2), 0, breath)
            warped = cv2.warpAffine(
                warped, M2, (w, h),
                flags=cv2.INTER_LINEAR,
                borderMode=cv2.BORDER_REFLECT_101
            )
        # Advance frame counter safely
        self.frame_index = (self.frame_index + 1) % 10_000_000
        return warped

