# WRAPPER FOR AI FUSION PIPELINE
# ==============================================================================
class UltraFilmGrainModuleV5:
    def __init__(self, strength=0.5, iso=400):
        self.engine = UltraFilmGrainV5(strength=strength, iso=iso)
    def apply(self, frame, stock_profile=None):
        return self.engine.apply(frame)
