# WRAPPER FOR AIFusionPipeline
# ==============================================================================
class AnamorphicOpticsModuleV4:
    def __init__(self):
        self.engine = AnamorphicOpticsV4()
    def apply(self, frame, coc=None):
        return self.engine.apply(frame, coc)
