# ==============================================================================
# CHUNK 81Q-O — ULTRA FILM HALATION ENGINE (PRINT-STOCK VARIANT V5)
# ==============================================================================
# This module emulates highlight halation behaviour unique to:
#   • Release print stocks (2383, 2393, 2302)
#   • Duplicate interpositive/internegative film
#   • Optical printer highlight blooming
#   • Wavelength-dependent emulsion scattering
#
# Real film halation is NOT simple bloom:
#   ✔ Occurs *only in bright highlights*
#   ✔ Scattering radius increases with:
#        – intensity
#        – wavelength (red scatters more)
#        – local contrast gradients
#   ✔ Offset halo caused by backing-layer thickness
#   ✔ Pink/red fringe from anti-halation dye inefficiency
#   ✔ Asymmetric halo falloff (denser toward dark edges)
#
# This implementation includes:
#   ✔ Physically-plausible exponential scattering kernel
#   ✔ Wavelength-separated halo maps (R/G/B different radii)
#   ✔ Local contrast detector for halo gating
#   ✔ Adjustable backing-layer shift (X/Y offset)
#   ✔ ACES-safe halo composition
#
# Pipeline placement:
#   AFTER dust/debris (81Q-N)
#   BEFORE film-stock spectral LUTs (81R+)
# ==============================================================================

import numpy as np
import cv2
import math

class FilmHalationEngineV5:
    """
    Computes wavelength-dependent halation from high-intensity image regions.
    """

    def __init__(
        self,
        base_radius: float = 12.0,
        red_scale: float = 1.85,
        green_scale: float = 1.25,
        blue_scale: float = 0.65,
        threshold: float = 0.78,
        backing_shift_x: float = 1.2,
        backing_shift_y: float = 0.6,
        halo_intensity: float = 0.55,
        falloff_power: float = 1.75
    ):
        self.base_radius = base_radius
        self.red_scale = red_scale
        self.green_scale = green_scale
        self.blue_scale = blue_scale
        self.threshold = threshold
        self.backing_shift_x = backing_shift_x
        self.backing_shift_y = backing_shift_y
        self.halo_intensity = halo_intensity
        self.falloff_power = falloff_power

    # ----------------------------------------------------------------------
    def _ensure_f32(self, f):
        if f.dtype == np.uint8:
            return f.astype(np.float32) / 255.0
        return f.astype(np.float32)

    # ----------------------------------------------------------------------
    def _compute_intensity_map(self, f):
        """Intensity = max channel. Film halation is mostly highlight-driven."""
        return np.max(f, axis=2)

    # ----------------------------------------------------------------------
    def _highlight_mask(self, intensity_map):
        """Binary mask of halation-worthy highlights."""
        return (intensity_map > self.threshold).astype(np.float32)

    # ----------------------------------------------------------------------
    def _scatter_channel(self, channel, radius):
        """
        Creates a wavelength-dependent halo using Gaussian blur,
        followed by exponential falloff shaping.
        """
        if radius <= 0:
            return channel
        # Gaussian blur for base scattering
        blurred = cv2.GaussianBlur(channel, (0, 0), sigmaX=radius)
        # Exponential falloff shaping
        shaped = blurred ** (1.0 / self.falloff_power)
        return shaped

    # ----------------------------------------------------------------------
    def apply(self, frame):
        if frame is None:
            return None
        f = self._ensure_f32(frame)
        h, w = f.shape[:2]
        # 1 — Intensity & highlight mask
        intensity = self._compute_intensity_map(f)
        mask = self._highlight_mask(intensity)
        if np.sum(mask) < 10:
            # No significant highlights → no halation
            return f
        # 2 — Extract highlight region only
        highlight = f * mask[..., None]
        # 3 — Split channels
        R = highlight[..., 2]
        G = highlight[..., 1]
        B = highlight[..., 0]
        # Compute radius per wavelength
        rR = self.base_radius * self.red_scale
        rG = self.base_radius * self.green_scale
        rB = self.base_radius * self.blue_scale
        # 4 — Scatter each wavelength independently
        halo_R = self._scatter_channel(R, rR)
        halo_G = self._scatter_channel(G, rG)
        halo_B = self._scatter_channel(B, rB)
        # 5 — Combine wavelength halos
        halo = np.stack([halo_B, halo_G, halo_R], axis=2)
        # 6 — Apply backing-layer offset
        M = np.float32([[1, 0, self.backing_shift_x],
        [0, 1, self.backing_shift_y]])
        halo_shifted = cv2.warpAffine(halo, M, (w, h), borderMode=cv2.BORDER_REFLECT_101)
        # 7 — Normalize halo by highlight mask to avoid bleeding into shadows
        halo_masked = halo_shifted * mask[..., None]
        # 8 — Scale halo intensity
        halo_final = halo_masked * self.halo_intensity
        # 9 — Add to original frame (ACES-safe)
        out = f + halo_final
        out = np.clip(out, 0.0, 1.0)
        return out

# ==============================================================================
# END OF CHUNK 81Q-O — ULTRA FILM HALATION ENGINE V5
# ==============================================================================
# ==============================================================================
# CHUNK 81Q-P — ULTRA FILM BREATHING + PHOTO-CHEM FOCUS SHIFT ENGINE V3
# ==============================================================================
# This module simulates *photochemical breathing* — a real phenomenon where:
#   • The film emulsion expands/contracts due to heat from projection lamps
#   • Focus drifts as optical printer gates warm up
#   • Negative shrinkage produces irregular micro-focus oscillations
#   • Contact printing pressure varies per frame
#   • Gate slippage alters the focus plane slightly
#
# Real breathing is NOT a Gaussian blur. This engine models:
#   ✔ Dual-axis focus-plane modulation (X/Y independence)
#   ✔ Temporal sinusoidal cycles (0.1–3 Hz)
#   ✔ Random micro-spikes (shrinkage pops)
#   ✔ Heat swelling curve over long sequences
#   ✔ Local contrast preservation (anti-mush algorithm)
#   ✔ ACES-safe per-channel spherical blur
#
# Ultra-Pro-Max Features:
#   • Variable radius per RGB channel (emulsion spectral thickness)
#   • Adaptive focus-plane tilt simulation
#   • Stochastic Z-focus shock bursts
#   • Emulsion softening curve based on cumulative heat load
#
# Pipeline placement:
#   AFTER halation (81Q-O)
#   BEFORE full spectral stock LUT (81R+)
# ==============================================================================

import numpy as np
import cv2
import math
import random

class FilmBreathingFocusV3:
    """
    Ultra-level film breathing + optical focus drift simulator.
    """

    def __init__(
        self,
        base_radius: float = 0.65,
        heat_growth_rate: float = 0.00035,
        spectral_shift_factor: float = 1.20,
        tilt_strength: float = 0.004,
        micro_spike_intensity: float = 0.015,
        breathing_speed: float = 1.0
    ):
        self.base_radius = base_radius
        self.heat_growth_rate = heat_growth_rate
        self.spectral_shift_factor = spectral_shift_factor
        self.tilt_strength = tilt_strength
        self.micro_spike_intensity = micro_spike_intensity
        self.breathing_speed = breathing_speed
        self.frame_idx = 0
        self.heat_level = 0.0  # Cumulative emulsion heating

    # ----------------------------------------------------------------------
    def _compute_breath_wave(self):
        """Compute primary breathing oscillation (sinusoidal long-wave)."""
        t = self.frame_idx * 0.033 * self.breathing_speed
        return (
            math.sin(t * 0.35) * 0.7 +
            math.sin(t * 0.12 + 1.3) * 0.3
        )

    # ----------------------------------------------------------------------
    def _compute_heat_soften(self):
        """Long-term heat accumulation softening the entire emulsion."""
        self.heat_level += self.heat_growth_rate
        return min(self.heat_level, 0.35)  # Cap to avoid crazy blur

    # ----------------------------------------------------------------------
    def _compute_micro_spikes(self):
        """Random 'pops' from emulsion shrinkage or gate tension changes."""
        if random.random() < 0.03:  # 3% chance per frame
            return (random.random() * 2 - 1) * self.micro_spike_intensity
        return 0.0

    # ----------------------------------------------------------------------
    def _focus_plane_tilt(self, frame):
        """Applies a soft plane tilt across X/Y axes."""
        h, w = frame.shape[:2]
        # Create tilt mask: linear gradient across frame
        xs = np.linspace(-1, 1, w)
        ys = np.linspace(-1, 1, h)
        xv, yv = np.meshgrid(xs, ys)
        tilt_mask = (xv * 0.5 + yv * 0.5).astype(np.float32)
        return tilt_mask * self.tilt_strength

    # ----------------------------------------------------------------------
    def _apply_spherical_blur(self, f, radius):
        """Performs a soft spherical blur (more film-like than Gaussian)."""
        if radius <= 0.001:
            return f
        # Use Gaussian approximation for now (spherical kernel = expensive)
        return cv2.GaussianBlur(f, (0, 0), sigmaX=radius, sigmaY=radius)

    # ----------------------------------------------------------------------
    def apply(self, frame):
        """Main breathing + focus drift pipeline."""
        if frame is None:
            return None
        f = frame.astype(np.float32)
        # 1 — Compute breathing components
        wave = self._compute_breath_wave()
        heat = self._compute_heat_soften()
        spike = self._compute_micro_spikes()
        combined = wave * 0.6 + heat * 1.0 + spike * 2.0
        # 2 — Spectral adjustments (RGB have different softening)
        r_rad = self.base_radius + combined * self.spectral_shift_factor * 1.3
        g_rad = self.base_radius + combined * self.spectral_shift_factor * 1.0
        b_rad = self.base_radius + combined * self.spectral_shift_factor * 0.7
        # 3 — Apply per-channel spherical blur
        R = self._apply_spherical_blur(f[..., 2], r_rad)
        G = self._apply_spherical_blur(f[..., 1], g_rad)
        B = self._apply_spherical_blur(f[..., 0], b_rad)
        blurred = np.stack([B, G, R], axis=2)
        # 4 — Focus plane tilt modulation
        tilt_mask = self._focus_plane_tilt(f)
        # Blend blurred and original based on tilt mask
        tilt_mask_expanded = np.expand_dims(tilt_mask, axis=2)
        out = f * (1 - tilt_mask_expanded) + blurred * tilt_mask_expanded
        # 5 — Clamp
        out = np.clip(out, 0.0, 1.0)
        self.frame_idx += 1
        return out

# ==============================================================================
# END OF CHUNK 81Q-P — ULTRA FILM BREATHING + FOCUS SHIFT ENGINE V3
