# ==============================================================================
# CHUNK 81Q-Q — ULTRA OPTICAL-PRINTER GRAIN + GATE MODULATION ENGINE V4
# ==============================================================================
# Simulates how grain behaves *inside an optical printer*, not in the camera:
#
# REAL optical-printer phenomena emulated:
#   • Grain amplification when duping (print → dupe → master)
#   • Gate pressure oscillation → grain clumping / stretching
#   • D-min / D-max dependent grain slope modulation
#   • Printer lamp diffusion → high-frequency grain suppression
#   • Stock-dependent chromatic grain separation (RGB)
#   • Sub-frame micro-grain phase jitter (caused by intermittent pull-down)
#
# Ultra-Pro-Max Features:
#   ✔ Multi-band grain synthesis (8–11 frequency layers)
#   ✔ Grain “gate warp” spatial distortion mask
#   ✔ Density-reactive grain: deeper shadows → tighter grain
#   ✔ Spectral grain response per channel
#   ✔ Grain motion drift over time (film path instability)
#   ✔ ACES-safe energy-preserving compositing
#
# Pipeline position:
#   AFTER film breathing (81Q-P)
#   BEFORE film stock spectral LUT (81R+)
# ==============================================================================

import numpy as np
import cv2
import math
import random

class OpticalPrinterGrainV4:
    """High-end optical printer grain / gate modulation engine."""

    def __init__(
        self,
        grain_strength: float = 0.22,
        chroma_separation: float = 1.35,
        printer_softening: float = 0.18,
        density_response: float = 0.85,
        warp_intensity: float = 0.008,
        temporal_drift_speed: float = 0.015
    ):
        self.grain_strength = grain_strength
        self.chroma_separation = chroma_separation
        self.printer_softening = printer_softening
        self.density_response = density_response
        self.warp_intensity = warp_intensity
        self.temporal_drift_speed = temporal_drift_speed
        self.frame_idx = 0
        self.seed = np.random.rand() * 10000

    # ----------------------------------------------------------------------
    def _multi_band_noise(self, h, w):
        """Generates multi-band grain noise (8+ octave fractal)."""
        base = np.zeros((h, w), np.float32)
        for i in range(1, 9):
            freq = 2 ** i
            amp = 1.0 / (i ** 1.25)
            noise = np.random.normal(0, 1, (h // freq, w // freq)).astype(np.float32)
            noise = cv2.resize(noise, (w, h), interpolation=cv2.INTER_CUBIC)
            base += noise * amp
        base = (base - base.min()) / (base.max() - base.min() + 1e-6)
        return base * 2 - 1  # range -1..1

    # ----------------------------------------------------------------------
    def _grain_warp_mask(self, h, w):
        """Gate pressure variation causes grain spatial ‘stretching’."""
        xs = np.linspace(0, 4, w)
        ys = np.linspace(0, 4, h)
        xv, yv = np.meshgrid(xs, ys)
        t = self.frame_idx * self.temporal_drift_speed + self.seed
        warp = (
            np.sin(xv * 0.9 + t) +
            np.sin(yv * 1.3 - t * 0.7) +
            np.sin(xv * 0.55 + yv * 0.65 + t * 0.33)
        ) / 3.0
        return warp.astype(np.float32)

    # ----------------------------------------------------------------------
    def _density_modulation(self, f):
        """Adjusts grain intensity based on exposure density (D-min/D-max)."""
        lum = (
            0.2126 * f[..., 2] +
            0.7152 * f[..., 1] +
            0.0722 * f[..., 0]
        )
        # Shadows: more grain (tight, strong)
        # Highlights: less grain
        mod = (1.0 - lum) ** self.density_response
        return mod.astype(np.float32)

    # ----------------------------------------------------------------------
    def _apply_printer_softening(self, grain):
        """Softens high-frequency grain due to printer lamp diffusion."""
        if self.printer_softening <= 0.001:
            return grain
        sigma = self.printer_softening * 4.0
        return cv2.GaussianBlur(grain, (0, 0), sigmaX=sigma, sigmaY=sigma)

    # ----------------------------------------------------------------------
    def apply(self, frame):
        """Main optical-printer grain pipeline."""
        if frame is None:
            return None
        f = frame.astype(np.float32)
        h, w = f.shape[:2]
        # 1 — generate base multi-band grain
        grain = self._multi_band_noise(h, w)
        # 2 — gate warp modulation mask
        warp = self._grain_warp_mask(h, w)
        # warp exaggerates clumping or stretching
        grain *= (1.0 + warp * self.warp_intensity)
        # 3 — printer softening of high frequencies
        grain = self._apply_printer_softening(grain)
        # 4 — density-dependent grain scaling
        density_mod = self._density_modulation(f)
        grain *= density_mod
        # 5 — per-channel chromatic grain response
        # Red = strongest, Blue = weakest
        gR = grain * (1.0 * self.chroma_separation)
        gG = grain * (0.8 * self.chroma_separation)
        gB = grain * (0.55 * self.chroma_separation)
        gstack = np.stack([gB, gG, gR], axis=2)
        # 6 — scale by intensity
        gstack *= self.grain_strength
        # 7 — composite into ACES-safe output
        out = f + gstack
        out = np.clip(out, 0.0, 1.0)
        self.frame_idx += 1
        return out

# ==============================================================================
# END OF CHUNK 81Q-Q — ULTRA OPTICAL-PRINTER GRAIN ENGINE V4
