# ==============================================================================
# CHUNK 81Q-R — ULTRA CHEMICAL FOG + SILVER HALIDE OXIDATION ENGINE V5
# ==============================================================================
# Simulates advanced archival & lab-aging chemical processes:
#
# REAL PHOTOCHEMICAL PHENOMENA MODELLED:
#   • Base fog increase (developer fog + age fog)
#   • Silver halide oxidation → magenta/green crossover
#   • Halide blooming → soft haze halos in highlights
#   • Acetate “vinegar syndrome” yellowing drift
#   • Uneven chemical aging → spatial fog turbulence
#   • Micro-contrast collapse in over-processed prints
#
# Ultra-Pro-Max Features:
#   ✔ Multi-band fog generator (3 temporal layers)
#   ✔ Chromatic oxidation maps (silver → magenta shift)
#   ✔ Archival chemical drift (decades of simulated decay)
#   ✔ Highlight halide bloom with ACES-safe blending
#   ✔ Fog density tied to image luminance
#   ✔ Per-frame temporal chemical breathing
#
# Pipeline placement:
#   AFTER 81Q-Q (optical printer grain)
#   BEFORE 81R (film stock spectral LUT + print density mapping)
# ==============================================================================

import numpy as np
import cv2
import math

class ChemicalFogOxidationV5:
    """Advanced archival-style chemical fog + halide oxidation simulator."""

    def __init__(
        self,
        fog_intensity: float = 0.035,
        oxidation_strength: float = 0.028,
        yellowing_strength: float = 0.020,
        halide_bloom_intensity: float = 0.055,
        temporal_speed: float = 0.010,
        spatial_complexity: float = 2.5
    ):
        self.fog_intensity = fog_intensity
        self.oxidation_strength = oxidation_strength
        self.yellowing_strength = yellowing_strength
        self.halide_bloom_intensity = halide_bloom_intensity
        self.temporal_speed = temporal_speed
        self.spatial_complexity = spatial_complexity

        self.frame_idx = 0
        self.seed = np.random.rand() * 10000

    # ----------------------------------------------------------------------
    def _fog_field(self, h, w):
        """Generates a multi-band chemical fog turbulence map."""
        xs = np.linspace(0, self.spatial_complexity, w)
        ys = np.linspace(0, self.spatial_complexity, h)
        xv, yv = np.meshgrid(xs, ys)

        t = self.seed + self.frame_idx * self.temporal_speed

        layer1 = np.sin(xv * 1.1 + t) * 0.33
        layer2 = np.sin(yv * 1.7 - t * 0.7) * 0.33
        layer3 = np.sin(xv * 0.6 + yv * 0.9 + t * 0.4) * 0.34

        fog = (layer1 + layer2 + layer3) * 0.5 + 0.5
        return fog.astype(np.float32)

    # ----------------------------------------------------------------------
    def _oxidation_color_shift(self, h, w):
        """Simulates magenta/green shifts due to silver halide oxidation."""
        t = self.frame_idx * self.temporal_speed

        m = math.sin(t * 1.3 + 0.7)  # magenta bias
        g = math.sin(t * 0.9 + 1.6)  # green counter-shift

        # Oxidation creates magenta shadows & green highlight tinge
        shift = np.array([
            -0.5 * g * self.oxidation_strength,   # blue channel decreases with green rise
            0.4 * g * self.oxidation_strength,    # green increases mildly
            0.6 * m * self.oxidation_strength     # red boosts under magenta fog
        ], dtype=np.float32)

        return shift

    # ----------------------------------------------------------------------
    def _yellowing_mask(self, h, w):
        """Simulates acetate 'vinegar syndrome' yellow cast over time."""
        xs = np.linspace(0, 2.2, w)
        ys = np.linspace(0, 2.2, h)
        xv, yv = np.meshgrid(xs, ys)

        t = self.seed + self.frame_idx * self.temporal_speed * 0.5

        ymask = (
            np.sin(xv * 1.3 + t) +
            np.sin(yv * 1.1 - t * 0.6)
        ) * 0.5 + 0.5

        return ymask.astype(np.float32)

    # ----------------------------------------------------------------------
    def _halide_bloom(self, lum):
        """Soft highlight bloom caused by silver halide halo expansion."""
        blur = cv2.GaussianBlur(lum, (0, 0), sigmaX=12.0)
        bloom = (blur - lum) * self.halide_bloom_intensity
        return np.clip(bloom, 0.0, 1.0)

    # ----------------------------------------------------------------------
    def apply(self, frame):
        if frame is None:
            return None

        f = frame.astype(np.float32)
        h, w = f.shape[:2]

        # 1 — luminance for density-based fog
        lum = (
            0.2126 * f[..., 2] +
            0.7152 * f[..., 1] +
            0.0722 * f[..., 0]
        )

        # Darker areas get more fog
        fog_density = (1.0 - lum) ** 1.25

        # 2 — spatial fog turbulence
        fog_field = self._fog_field(h, w)
        fog = fog_field * fog_density[..., None] * self.fog_intensity

        # 3 — oxidation color shift
        ox_shift = self._oxidation_color_shift(h, w)
        ox_applied = ox_shift[None, None, :]

        # 4 — acetate yellowing overlay
        yellow_mask = self._yellowing_mask(h, w)
        yellow_tint = yellow_mask[..., None] * np.array(
            [0.015, 0.020, -0.005], dtype=np.float32
        ) * self.yellowing_strength

        # 5 — halide bloom in highlights
        hal_bloom = self._halide_bloom(lum)
        hal_rgb = np.repeat(hal_bloom[..., None], 3, axis=2)

        # 6 — assemble all effects
        out = f + fog + ox_applied + yellow_tint + hal_rgb
        out = np.clip(out, 0.0, 1.0)

        self.frame_idx += 1
        return out

# ==============================================================================
# END OF CHUNK 81Q-R — CHEMICAL FOG + HALIDE OXIDATION ENGINE V5
