# ==============================================================================
# CHUNK 81Q-S — ULTRA ACETATE SHRINKAGE + CURL WARP ENGINE V4
# ==============================================================================
# Simulates real-world physical deformation of aging film stock:
#
#   • Acetate base shrinkage (0.2–1.2%) causing geometric distortion
#   • Curl warp along X/Y axes (barrel-like bending of the frame)
#   • Edge-wave deformation from humidity cycling
#   • Binder contraction → uneven density stretch
#   • Temporal curling oscillation (film breathing effect)
#
# Ultra-Pro-Max Technical Features:
#   ✔ Bi-directional curl with adjustable frequency
#   ✔ Spatial shrinkage field (non-uniform shrink regions)
#   ✔ Edge-attenuated warp (strongest at edges, weakest at center)
#   ✔ Per-pixel warp field via mesh-grid distortion
#   ✔ ACES-safe deformation blending
#
# Placement:
#   AFTER 81Q-R (Chemical Fog + Halide Oxidation V5)
#   BEFORE 81Q-T (Ultra Archival Perforation Shadow Engine)
# ==============================================================================

import numpy as np
import cv2
import math

class AcetateCurlWarpV4:
    """Simulates physical shrinkage + curl deformation of archival film."""

    def __init__(
        self,
        shrink_amount: float = 0.006,       # 0.6% typical archival shrinkage
        curl_strength: float = 0.018,       # curl warp amplitude
        curl_frequency: float = 1.5,        # temporal oscillation
        edge_wave_intensity: float = 0.012, # humidity wave deformation
        edge_wave_freq: float = 3.0,
        temporal_speed: float = 0.015
    ):
        self.shrink_amount = shrink_amount
        self.curl_strength = curl_strength
        self.curl_frequency = curl_frequency
        self.edge_wave_intensity = edge_wave_intensity
        self.edge_wave_freq = edge_wave_freq
        self.temporal_speed = temporal_speed

        self.frame_idx = 0

    # ----------------------------------------------------------------------
    def _shrink_field(self, h, w):
        """
        Creates a non-uniform shrinkage field:
          • stronger at edges
          • weaker in the center
        """
        ys = np.linspace(-1, 1, h)
        xs = np.linspace(-1, 1, w)
        xv, yv = np.meshgrid(xs, ys)

        # Radial distance from center
        r = np.sqrt(xv**2 + yv**2)

        # Edge shrinkage → center preserved
        shrink = r * self.shrink_amount

        return shrink.astype(np.float32)

    # ----------------------------------------------------------------------
    def _curl_field(self, h, w):
        """
        Curl warp simulating film curling upward/downward.
        """
        ys = np.linspace(-1, 1, h)
        xs = np.linspace(-1, 1, w)
        xv, yv = np.meshgrid(xs, ys)

        t = self.frame_idx * self.temporal_speed

        # Temporal oscillation (film breathing)
        curl_phase = math.sin(t * self.curl_frequency)

        # Curl field — bending along both axes
        curl = (
            (xv**2 - yv**2) * curl_phase * self.curl_strength
        )

        return curl.astype(np.float32)

    # ----------------------------------------------------------------------
    def _edge_wave_field(self, h, w):
        """
        Humidity edge-wave deformation: wavy bending near edges only.
        """
        ys = np.linspace(0, 1, h)
        xs = np.linspace(0, 1, w)
        xv, yv = np.meshgrid(xs, ys)

        t = self.frame_idx * self.temporal_speed

        # Waves strongest near the edges
        edge_mask_x = np.minimum(xv, 1 - xv)
        edge_mask_y = np.minimum(yv, 1 - yv)
        edge_mask = np.minimum(edge_mask_x, edge_mask_y) * 4.0
        edge_mask = np.clip(edge_mask, 0.0, 1.0)

        wave = (
            np.sin(xv * self.edge_wave_freq * 2 * np.pi + t) +
            np.sin(yv * self.edge_wave_freq * 2 * np.pi + t * 0.7)
        ) * self.edge_wave_intensity

        # Only affect edges
        wave *= (1.0 - edge_mask)

        return wave.astype(np.float32)

    # ----------------------------------------------------------------------
    def apply(self, frame):
        if frame is None:
            return None

        f = frame.astype(np.float32)
        h, w = f.shape[:2]

        # Coordinate grid
        xs = np.linspace(0, w - 1, w)
        ys = np.linspace(0, h - 1, h)
        xv, yv = np.meshgrid(xs, ys)

        # Normalize grid to -1..1 space
        nx = (xv / (w - 1)) * 2 - 1
        ny = (yv / (h - 1)) * 2 - 1

        # 1 — shrinkage field
        shrink = self._shrink_field(h, w)

        # 2 — curl deformation
        curl = self._curl_field(h, w)

        # 3 — edge wave deformation
        edge_wave = self._edge_wave_field(h, w)

        # Combine fields
        warp_x = nx + shrink * nx + curl + edge_wave
        warp_y = ny + shrink * ny - curl + edge_wave * 0.5

        # Convert back to pixel space
        map_x = ((warp_x + 1) * 0.5 * (w - 1)).astype(np.float32)
        map_y = ((warp_y + 1) * 0.5 * (h - 1)).astype(np.float32)

        # Warp frame
        warped = cv2.remap(
            f, map_x, map_y,
            interpolation=cv2.INTER_LINEAR,
            borderMode=cv2.BORDER_REFLECT_101
        )

        self.frame_idx += 1
        return warped

