# ==============================================================================
# CHUNK 81Q-V — ULTRA HALATION LAYER V6 (SPECTRAL SCATTERING ENGINE)
# ==============================================================================
# Next-generation halation engine:
#
#   • True spectral scattering simulation (R → G → B wavelength falloff)
#   • Multi-radius convolution stack (6–12 radii blended)
#   • Density-dependent edge scatter (bright edges emit more)
#   • Long-range red channel diffusion (film-like bleed)
#   • Short-range green scatter (midtone spill)
#   • Blue-channel high-frequency haze (minimal bleed)
#   • Chromatic fringing control (bidirectional offsets)
#   • Physical halation thresholding (luma-driven energy mask)
#   • ACES-safe clamp with energy conservation
#
# Placement:
#   AFTER 81Q-U (Gate Flare Engine V5)
#   BEFORE 81Q-W (Advanced Spectral Grain)
#
# Notes:
#   This is the *main* halation model used for:
#      • Kodak Vision3 style red halo
#      • Highlight-edge glow on bright points
#      • Organic analog depth around emissive objects
#
# ==============================================================================

import numpy as np
import cv2
import math

class UltraHalationV6:
    """Full-spectrum halation simulator."""

    def __init__(
            self,
            strength_red: float = 0.42,
            strength_green: float = 0.18,
            strength_blue: float = 0.06,
            threshold: float = 0.78,
            radii: list = None,
            chroma_offset: float = 1.0,
            energy_preserve: float = 0.85
    ):
        """
        strength_red:     Red-channel diffusion intensity
        strength_green:   Green-channel diffusion intensity
        strength_blue:    Blue-channel short-range scatter
        threshold:        Luma threshold for halation onset
        radii:            List of blur radii (6–12 recommended)
        chroma_offset:    Offsets RGB layers radially for chromatic halo
        energy_preserve:  1.0 = strict energy conservation
        """
        self.str_r = strength_red
        self.str_g = strength_green
        self.str_b = strength_blue
        self.thresh = threshold
        self.energy_preserve = energy_preserve
        self.chroma_offset = chroma_offset
        if radii is None:
            # Default cinematic multi-radius stack
            self.radii = [3, 6, 12, 18, 28, 42]
        else:
            self.radii = radii

        self.frame_idx = 0

    # ----------------------------------------------------------------------
    def _luma(self, f):
        return (
            0.2126 * f[..., 2] +
            0.7152 * f[..., 1] +
            0.0722 * f[..., 0]
        ).astype(np.float32)

    # ----------------------------------------------------------------------
    def _threshold_mask(self, luma):
        """Soft onset mask for halation threshold."""
        m = (luma - self.thresh) / (1.0 - self.thresh)
        m = np.clip(m, 0.0, 1.0)
        return cv2.GaussianBlur(m, (0, 0), sigmaX=2.5)

    # ----------------------------------------------------------------------
    def _apply_blur_stack(self, src_single_channel):
        """
        Apply multiple gaussian blurs and accumulate weighted output.
        Produces physically-plausible scattering profile.
        """
        h, w = src_single_channel.shape
        accum = np.zeros((h, w), np.float32)
        for i, r in enumerate(self.radii):
            weight = (1.0 / ((i + 1))) ** 0.55  # power-law falloff
            blurred = cv2.GaussianBlur(src_single_channel, (0, 0), sigmaX=r)
            accum += blurred * weight
        # Normalize: ensures large-radius layers don't overflow
        accum /= (accum.max() + 1e-6)
        return accum

    # ----------------------------------------------------------------------
    def apply(self, frame):
        if frame is None:
            return None
        f = frame.astype(np.float32)
        h, w = f.shape[:2]

        # 1 — Compute luma & threshold mask
        luma = self._luma(f)
        mask = self._threshold_mask(luma)  # 0–1 activation

        # 2 — Extract weighted emission signal from RGB channels
        #     brighter objects emit more halation
        emit_r = f[..., 2] * mask
        emit_g = f[..., 1] * mask
        emit_b = f[..., 0] * mask

        # 3 — Multi-radius blur stacks for each channel
        blur_r = self._apply_blur_stack(emit_r)
        blur_g = self._apply_blur_stack(emit_g)
        blur_b = self._apply_blur_stack(emit_b)

        # 4 — Chromatic fringing offset (sub-pixel remap)
        if self.chroma_offset != 0:
            # radial outward shift for dispersion
            xs = np.linspace(-1, 1, w)
            ys = np.linspace(-1, 1, h)
            xv, yv = np.meshgrid(xs, ys)
            radius = np.sqrt(xv**2 + yv**2)
            # Apply radial scale (tiny outward push)
            shift_map = (radius * self.chroma_offset * 0.75).astype(np.float32)
            # Remap red outward strongest
            blur_r = cv2.GaussianBlur(blur_r + shift_map * 0.10, (0, 0), sigmaX=1.0)
            blur_g = cv2.GaussianBlur(blur_g + shift_map * 0.04, (0, 0), sigmaX=1.0)
            blur_b = cv2.GaussianBlur(blur_b + shift_map * 0.02, (0, 0), sigmaX=1.0)

        # 5 — Scale by spectral strengths
        hal_r = blur_r * self.str_r
        hal_g = blur_g * self.str_g
        hal_b = blur_b * self.str_b

        # 6 — Stack halation channels
        hal = np.stack([hal_b, hal_g, hal_r], axis=2)

        # 7 — Composite with energy-preserving blend
        out = f + hal * self.energy_preserve
        # 8 — Clamp
        out = np.clip(out, 0.0, 1.0)
        self.frame_idx += 1
        return out

