# ==============================================================================
# CHUNK 81Q-W — ADVANCED SPECTRAL FILM GRAIN ENGINE V7
# ==============================================================================
# Ultra-level grain simulator:
#   • True spectral (R/G/B separate grain) modeling
#   • ISO-dependent grain amplitude + chroma noise ratio
#   • Multi-frequency grain stack (fine/medium/coarse)
#   • Soft-threshold film response curve (grain increases in mids)
#   • Per-pixel contrast-reactive grain modulation
#   • Micro dithering (blue-noise diffusion)
#   • Stock presets (Vision3, Fuji Eterna, Tri-X, 5219)
#   • Highlight washout suppression
#   • ACES-safe blend using density-based weighting
#
# Placement in pipeline:
#   AFTER 81Q-V (Halation V6)
#   BEFORE 81R-A (Spectral Diffusion / Film Bloom Core)
#
# ==============================================================================

import numpy as np
import cv2
import math

class SpectralFilmGrainV7:
    """
    Ultra-level spectral grain system.
    Grain model includes:
      - Sensor shot noise mapping
      - Optical granularity
      - Film emulsion pattern variation
      - Dither diffusion for anti-band noise
    """

    # ----------------------------
    # Preset configurations
    # ----------------------------
    STOCKS = {
        "vision3_500t":  {"iso": 500, "chroma_ratio": 0.75, "grain_size": 1.35},
        "vision3_250d":  {"iso": 250, "chroma_ratio": 0.55, "grain_size": 1.10},
        "fuji_eterna":   {"iso": 250, "chroma_ratio": 0.60, "grain_size": 1.20},
        "kodak_5219":    {"iso": 500, "chroma_ratio": 0.70, "grain_size": 1.40},
        "tri_x_400":     {"iso": 400, "chroma_ratio": 0.20, "grain_size": 1.65},
    }

    def __init__(
            self,
            stock="vision3_500t",
            strength=1.0,
            highlight_protect=0.35,
            midtone_bias=1.15,
            dither_strength=0.15
    ):
        self.stock_name = stock
        self.strength = float(strength)
        self.highlight_protect = highlight_protect
        self.midtone_bias = midtone_bias
        self.dither_strength = dither_strength
        self.frame_idx = 0
        # Load preset
        cfg = self.STOCKS.get(stock, self.STOCKS["vision3_500t"])
        self.iso = cfg["iso"]
        self.chroma_ratio = cfg["chroma_ratio"]
        self.grain_size = cfg["grain_size"]

    # ----------------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ----------------------------------------------------------------------
    def _generate_base_grain(self, h, w):
        """
        Generates three independent Gaussian noise layers for RGB.
        """
        # ISO → noise power mapping
        base_amp = (self.iso / 500.0) ** 0.65
        # Fine grain (sensor noise)
        noise_f = np.random.normal(0, 1, (h, w)).astype(np.float32)
        # Medium grain (emulsion granularity)
        noise_m = cv2.GaussianBlur(noise_f, (0, 0), sigmaX=1.0 * self.grain_size)
        # Coarse grain (large clumps)
        noise_c = cv2.GaussianBlur(noise_f, (0, 0), sigmaX=2.5 * self.grain_size)
        # Weighted grain stack
        stacked = (
            noise_f * 0.55 +
            noise_m * 0.33 +
            noise_c * 0.12
        )
        # Normalize to -1..1
        stacked /= (np.max(np.abs(stacked)) + 1e-6)
        return stacked * base_amp

    # ----------------------------------------------------------------------
    def _apply_blue_noise_dither(self, grain):
        """
        Applies blue-noise micro dithering to break banding and
        add fine stochastic structure.
        """
        # Pre-generate a small high-frequency blue-noise tile
        tile = np.random.rand(64, 64).astype(np.float32)
        tile = cv2.GaussianBlur(tile, (0, 0), sigmaX=0.4)
        h, w = grain.shape
        reps_x = w // 64 + 1
        reps_y = h // 64 + 1
        bn = np.tile(tile, (reps_y, reps_x))[:h, :w]
        return grain + bn * self.dither_strength

    # ----------------------------------------------------------------------
    def _midtone_response(self, f):
        """
        Film grain is strongest in midtones, weaker in shadows/highlights.
        """
        lum = (
            0.2126 * f[..., 2] +
            0.7152 * f[..., 1] +
            0.0722 * f[..., 0]
        )
        # Midtone shaping curve
        curve = np.exp(-((lum - 0.5) ** 2) * self.midtone_bias * 6.0)
        return curve.astype(np.float32)

    # ----------------------------------------------------------------------
    def apply(self, frame):
        if frame is None:
            return None
        f = self._ensure_f32(frame)
        h, w = f.shape[:2]
        # 1 — Base grain (monochrome, then spectrally expanded)
        grain = self._generate_base_grain(h, w)
        # 2 — Dither for micro-texture
        grain = self._apply_blue_noise_dither(grain)
        # 3 — Per-channel spectral scaling
        #     R strongest, B weakest (depending on stock)
        g_r = grain * (1.0 * self.chroma_ratio + 0.35)
        g_g = grain * (1.0 * self.chroma_ratio)
        g_b = grain * (1.0 * self.chroma_ratio * 0.65)
        grain_rgb = np.stack([g_b, g_g, g_r], axis=2)
        # 4 — Apply midtone mask (grain visible mostly in mids)
        midmask = self._midtone_response(f)
        grain_rgb *= midmask[..., None]

        # 5 — Highlight protection (grain fades in bright areas)
        lum = (
            0.2126 * f[..., 2] +
            0.7152 * f[..., 1] +
            0.0722 * f[..., 0]
        )
        hl_mask = np.clip(1.0 - (lum - 0.75) * (1.0 / (1.0 - 0.75)), 0.0, 1.0)
        grain_rgb *= hl_mask[..., None]

        # 6 — Composite grain
        out = f + grain_rgb * self.strength * 0.65
        # 7 — ACES-safe clamp
        out = np.clip(out, 0.0, 1.0)
        self.frame_idx += 1
        return out

# ==============================================================================
# END OF CHUNK 81Q-W — ADVANCED SPECTRAL FILM GRAIN ENGINE V7
