# ==============================================================================
# CHUNK 81Q-X — ULTRA PHOTON SHOT-NOISE + SENSOR BLOOM FUSION ENGINE V5
# ==============================================================================
# This module simulates the physical electronic noise and micro-blooming
# characteristics of real digital cinema sensors (ALEXA, Venice, FX3, BMPCC6K).
#
# Features:
#   • True photon shot-noise (Poisson-distributed luminance noise)
#   • Read-noise model (Gaussian baseline noise)
#   • Sensor micro-bloom halos around high-contrast edges
#   • Pixel-well overflow softness (bloom-on-clipping)
#   • Wavelength-dependent sensor scatter (R→ strongest, B→ weakest)
#   • Highlight-lift bloom + chromatic bleed
#   • Iso-dependent noise scaling
#   • ACES-safe composite
#
# Placement:
#   AFTER 81Q-W (Spectral Film Grain V7)
#   BEFORE 81Q-Y (Optical Aberration / Lens Breathing Sim)
#
# ==============================================================================

import numpy as np
import cv2
import math

class SensorBloomNoiseV5:
    """
    Ultra-level simulation of digital sensor photon-noise + micro-bloom.
    """

    def __init__(
            self,
            iso_value=800,
            bloom_strength=0.22,
            chromatic_bleed=0.12,
            read_noise_level=0.004,
            edge_bloom_radius=2.2,
            clip_soft_knee=0.02
    ):
        self.iso = float(iso_value)
        self.bloom_strength = float(bloom_strength)
        self.chromatic_bleed = float(chromatic_bleed)
        self.read_noise_level = float(read_noise_level)
        self.edge_bloom_radius = float(edge_bloom_radius)
        self.clip_soft_knee = float(clip_soft_knee)
        self.frame_idx = 0

    # ------------------------------------------------------------
    def _ensure_f32(self, img):
        if img.dtype == np.uint8:
            return img.astype(np.float32) / 255.0
        return img.astype(np.float32)

    # ------------------------------------------------------------
    def _photon_shot_noise(self, img):
        """
        True photon shot noise = Poisson noise.
        Variance increases with brightness.
        """
        # Scale to a large integer domain for Poisson precision
        scaled = np.clip(img * 5000.0, 0.0, None)
        # Poisson process
        noisy = np.random.poisson(scaled).astype(np.float32)
        # Normalize back to 0..1
        noisy = noisy / 5000.0
        # ISO amplification model: ISO↑ → larger noise deviation
        iso_amp = (self.iso / 800.0) ** 0.85
        out = img + (noisy - img) * iso_amp
        return out

    # ------------------------------------------------------------
    def _read_noise(self, img):
        """
        Gaussian baseline read noise (sensor electronics).
        """
        noise = np.random.normal(0, self.read_noise_level, img.shape).astype(np.float32)
        return img + noise

    # ------------------------------------------------------------
    def _micro_bloom(self, img):
        """
        Sensor micro-bloom: small halos around highlight edges.
        """
        lum = (
            0.2126 * img[..., 2] +
            0.7152 * img[..., 1] +
            0.0722 * img[..., 0]
        )
        # Detect edges with Sobel
        gx = cv2.Sobel(lum, cv2.CV_32F, 1, 0, ksize=3)
        gy = cv2.Sobel(lum, cv2.CV_32F, 0, 1, ksize=3)
        edges = np.sqrt(gx * gx + gy * gy)
        # Normalize edges → 0..1
        if edges.max() > 1e-6:
            edges /= edges.max()
        # Blur edges to form bloom halo
        halo = cv2.GaussianBlur(edges, (0, 0), self.edge_bloom_radius)
        # Chromatic bloom weighting
        b = halo * (self.bloom_strength * (1.0 - self.chromatic_bleed))
        g = halo * (self.bloom_strength)
        r = halo * (self.bloom_strength * (1.0 + self.chromatic_bleed))
        bloom = np.stack([b, g, r], axis=2)
        return img + bloom

    # ------------------------------------------------------------
    def _soft_clip(self, img):
        """
        Pixel well overflow soft-knee:
        Highlights bloom instead of hard clipping.
        """
        knee = self.clip_soft_knee
        # For values above 1-knee: soft compression curve
        mask = img > (1.0 - knee)
        out = img.copy()
        out[mask] = 1.0 - (1.0 - out[mask]) * 0.35
        return out

    # ------------------------------------------------------------
    def apply(self, frame):
        if frame is None:
            return None
        f = self._ensure_f32(frame)
        # 1) Photon shot noise
        f = self._photon_shot_noise(f)
        # 2) Read noise
        f = self._read_noise(f)
        # 3) Micro-bloom edges
        f = self._micro_bloom(f)
        # 4) Soft highlight clipping
        f = self._soft_clip(f)
        # 5) Clamp
        f = np.clip(f, 0.0, 1.0)
        self.frame_idx += 1
        return f

