import numpy as np
import cv2
import time
# Import all prior modules
# (These imports assume the modules already exist in your project.)
from aces_input_transform import ACESInputTransform
from halation_engine import UltraHalationV7
from bloom_engine import UltraBloomV6
from grain_engine import GrainEngineSuiteV12
from gate_weave_engine_v1 import GateWeaveEngineV1
from lab_flicker_engine_v4 import LabChemicalFlickerV4
from film_stock_spectral_v3 import FilmStockSpectralV3
from display_legalizer_v5 import DisplayLegalizerV5
from master_output_encoder_v3 import MasterOutputEncoderV3
class AIFusionPipelineV5:
    """
    Main orchestrator that routes a frame through the entire
    Ultra-Pro-Max cinematographic pipeline.
    Subsystems:
       • input_xfm   — Camera Log → ACEScg
       • stock       — Film spectral simulation
       • halation    — Optical highlight bleed
       • bloom       — Diffusion + highlight glow
       • weave       — Gate jitter (80Z-A)
       • chem        — Lab flicker (80Z-Z)
       • grain       — Organic multi-model grain
       • legalizer   — Display legal-range handler
       • encoder     — Final output writer
    Each block can be toggled for debugging purposes.
    """
    def __init__(self,
                 enable_halation=True,
                 enable_bloom=True,
                 enable_grain=True,
                 enable_gate_weave=True,
                 enable_chem_flicker=True,
                 enable_stock=True,
                 odt_profile="Rec709",
                 metadata=None):
        # Core transforms
        self.input_xfm = ACESInputTransform()
        self.stock = FilmStockSpectralV3()
        self.halation = UltraHalationV7()
        self.bloom = UltraBloomV6()
        self.grain = GrainEngineSuiteV12()
        self.weave = GateWeaveEngineV1()
        self.chem = LabChemicalFlickerV4()
        self.legalizer = DisplayLegalizerV5(profile=odt_profile)
        self.encoder = MasterOutputEncoderV3(
            color_space="ACES2065-1",
            metadata=metadata,
            container="exr"
        )
        # Feature toggles
        self.enable_halation = enable_halation
        self.enable_bloom = enable_bloom
        self.enable_grain = enable_grain
        self.enable_gate_weave = enable_gate_weave
        self.enable_chem_flicker = enable_chem_flicker
        self.enable_stock = enable_stock
        # Internal state
        self.frame_index = 0
        self.time_start = time.time()
    # ----------------------------------------------------------------------
    def _apply_stage(self, label, func, frame):
        """
        Helper: Safely applies a stage and logs execution time.
        """
        if frame is None:
            return None
        t0 = time.time()
        out = func(frame)
        dt = (time.time() - t0) * 1000
        # (Logging omitted to avoid spam, but can be added)
        return out
    # ----------------------------------------------------------------------
    def process_frame(self, frame, camera_profile="ARRI_LogC3"):
        """
        Main entry point for per-frame processing.
        Processes a single frame through the entire cinematic chain.
        """
        if frame is None:
            return None
        # 1. INPUT: Camera Log → ACEScg
        aces = self.input_xfm.process(frame, profile=camera_profile)
        # ----------------------------------------------------------
        # 2. OPTIONAL: Film stock spectral simulation
        if self.enable_stock:
            aces = self._apply_stage("stock", self.stock.apply, aces)
        # ----------------------------------------------------------
        # 3. OPTIONAL: Halation (optical bleed)
        if self.enable_halation:
            aces = self._apply_stage("halation", self.halation.apply, aces)
        # ----------------------------------------------------------
        # 4. OPTIONAL: Bloom
        if self.enable_bloom:
            aces = self._apply_stage("bloom", self.bloom.apply, aces)
        # ----------------------------------------------------------
        # 5. OPTIONAL: Gate-Weave (applies to display-linear)
        if self.enable_gate_weave:
            aces_img = (aces * 1.0).astype(np.float32)
            aces = self.weave.apply(aces_img)
        # ----------------------------------------------------------
        # 6. OPTIONAL: Chemical Flicker
        if self.enable_chem_flicker:
            aces = self._apply_stage("chem", self.chem.apply, aces)
        # ----------------------------------------------------------
        # 7. OPTIONAL: Grain (final image texture)
        if self.enable_grain:
            aces = self._apply_stage("grain", self.grain.apply, aces)
        # ----------------------------------------------------------
        # 8. Output Legalization (Rec709 / HDR10 / P3)
        legal = self.legalizer.apply(aces)
        self.frame_index += 1
        return legal
    # ----------------------------------------------------------------------
    def export_image(self, frame, out_path):
        """Single-frame export helper."""
        return self.encoder.export_image(frame, out_path)
    # ----------------------------------------------------------------------
    def export_video(self, frames, out_path, codec="h264"):
        """Video export helper."""
        return self.encoder.export_video(frames, out_path, codec=codec)
