# ==============================================================================
# GPU Device Object
# ==============================================================================
class GPUDevice:
    """
    Represents a selected GPU backend (CUDA / Vulkan / Metal / CPU).
    Handles:
        - Memory allocation
        - Buffer management
        - Kernel dispatch
        - Fallback logic
    """
    def __init__(self):
        # Determine active backend:
        if _HAS_CUDA:
            self.backend = "cuda"
        elif _HAS_VULKAN:
            self.backend = "vulkan"
        elif _HAS_METAL:
            self.backend = "metal"
        else:
            self.backend = "cpu"
        self.initialized = False
        self.context = None
    # ----------------------------------------------------------------------
    def initialize(self):
        """Set up GPU backend."""
        if self.initialized:
            return
        if self.backend == "cuda":
            # Cupy takes care of CUDA context creation automatically.
            self.context = cp
            self.initialized = True
        elif self.backend == "vulkan":
            # Placeholder: Vulkan compute setup
            self.context = vk
            self.initialized = True
        elif self.backend == "metal":
            # Placeholder: Metal compute pipeline
            self.context = mtl
            self.initialized = True
        else:
            # CPU: No initialization needed
            self.context = np
            self.initialized = True
    # ----------------------------------------------------------------------
    def array(self, x):
        """Creates a GPU-backed array if backend supports it."""
        if self.backend == "cuda":
            return cp.asarray(x)
        return np.asarray(x)
    # ----------------------------------------------------------------------
    def to_cpu(self, x):
        """Converts GPU array → CPU numpy."""
        if self.backend == "cuda":
            return cp.asnumpy(x)
        return x
    # ----------------------------------------------------------------------
    def supports_compute(self):
        return self.backend in ("cuda", "vulkan", "metal")
# ==============================================================================
# Triple Buffer System (Ping-Pong + Reserve Buffer)
# ==============================================================================
class TripleBuffer:
    """
    Triple-buffered GPU frame system:
        • buf_a — current
        • buf_b — next
        • buf_c — spare (pre-alloc)
    Prevents blocking on GPU scheduling. Used in real-time pipelines.
    """
    def __init__(self, device: GPUDevice):
        self.device = device
        self.buf_a = None
        self.buf_b = None
        self.buf_c = None
    def allocate(self, shape, dtype=np.float32):
        """Preallocates all buffers."""
        xp = self.device.context
        self.buf_a = xp.zeros(shape, dtype=dtype)
        self.buf_b = xp.zeros(shape, dtype=dtype)
        self.buf_c = xp.zeros(shape, dtype=dtype)
    def swap(self):
        """
        buf_a ← buf_b
        buf_b ← buf_c
        buf_c ← OLD buf_a
        """
        old_a = self.buf_a
        self.buf_a = self.buf_b
        self.buf_b = self.buf_c
        self.buf_c = old_a
    def load_frame(self, frame):
        """Loads a CPU numpy frame → GPU buf_a."""
        self.buf_a = self.device.array(frame)
    def current(self):
        return self.buf_a
# ==============================================================================
# GPU-Accelerated Kernel Container
# ==============================================================================
class GPUKernelsV4:
    """
    Holds GPU accelerated versions of:
        • Bloom downsample/upsample
        • Halation blur
        • Grain generator
        • Gate-weave warp (affine)
        • Flicker modulation
    If GPU unsupported, CPU fallback is used.
    """
    def __init__(self, device: GPUDevice):
        self.device = device
        xp = device.context
        # Precompiled CUDA kernels (pseudo — placeholder)
        # In your real system these become actual fused kernels.
        self.has_gpu = device.supports_compute()
    # ----------------------------------------------------------------------
    def gaussian_blur(self, img, sigma):
        xp = self.device.context
        if not self.has_gpu:
            # CPU fallback
            return cv2.GaussianBlur(img.astype(np.float32), (0,0), sigma)
        # GPU blur using separable Gaussians (pseudo fused kernel)
        # Here we approximate using cupy's convolve for demonstration.
        ksize = int(max(3, sigma * 6)) | 1
        kernel_1d = xp.exp(-0.5 * (xp.arange(ksize) - ksize//2)**2 / (sigma*sigma))
        kernel_1d /= kernel_1d.sum()
        tmp = xp.apply_along_axis(lambda m: xp.convolve(m, kernel_1d, mode='same'), 1, img)
        out = xp.apply_along_axis(lambda m: xp.convolve(m, kernel_1d, mode='same'), 0, tmp)
        return out
    # ----------------------------------------------------------------------
    def apply_affine(self, img, matrix):
        xp = self.device.context
        if not self.has_gpu:
            return cv2.warpAffine(img, matrix, (img.shape[1], img.shape[0]),
        flags=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_REFLECT_101)
        # GPU fallback pseudo-affine warp (fast, approximated)
        # Real implementation: custom CUDA kernel for warp affine.
        return xp.asarray(
            cv2.warpAffine(
                self.device.to_cpu(img),
                matrix,
                (img.shape[1], img.shape[0]),
                flags=cv2.INTER_LINEAR,
                borderMode=cv2.BORDER_REFLECT_101
            )
        )
    # ----------------------------------------------------------------------
    def grain_noise(self, shape, strength=1.0):
        xp = self.device.context
        if not self.has_gpu:
            return (np.random.normal(0, strength, shape).astype(np.float32))
        return xp.random.normal(0, strength, shape).astype(xp.float32)
# ==============================================================================
# GPU FRAME EXECUTION ENGINE V4
# ==============================================================================
class GPUExecutionEngineV4:
    """
    The orchestrator for GPU-based acceleration.
    Responsibilities:
        • Initialize device
        • Allocate triple buffers
        • Manage GPU kernels
        • Dispatch operations for:
              - halation
              - bloom
              - grain
              - warp (gate weave)
              - flicker modulation
        • CPU fallback path
    """
    def __init__(self):
        self.device = GPUDevice()
        self.device.initialize()
        self.triple = TripleBuffer(self.device)
        self.kernels = GPUKernelsV4(self.device)
        self.ready = False
    # ----------------------------------------------------------------------
    def prepare(self, frame_shape):
        """Allocates buffers."""
        self.triple.allocate(frame_shape, dtype=np.float32)
        self.ready = True
    # ----------------------------------------------------------------------
    def run_gaussian(self, frame, sigma):
        """GPU-powered Gaussian blur wrapper."""
        if not self.ready:
            self.prepare(frame.shape)
        self.triple.load_frame(frame)
        img = self.triple.current()
        out = self.kernels.gaussian_blur(img, sigma)
        # Swap buffers so next ops get fresh buffer
        self.triple.buf_b = out
        self.triple.swap()
        return self.device.to_cpu(out)
    # ----------------------------------------------------------------------
    def run_affine(self, frame, matrix):
        """GPU-powered affine warp."""
        if not self.ready:
            self.prepare(frame.shape)
        self.triple.load_frame(frame)
        img = self.triple.current()
        out = self.kernels.apply_affine(img, matrix)
        self.triple.buf_b = out
        self.triple.swap()
        return self.device.to_cpu(out)
    # ----------------------------------------------------------------------
    def run_grain(self, shape, strength):
        """GPU grain generator."""
        noise = self.kernels.grain_noise(shape, strength)
        return self.device.to_cpu(noise)
