import numpy as np
import cv2
import math
class GPUComputeGraphV6:
    """
    Platform-agnostic adaptive GPU compute graph for real-time film processing.
    Works with FusedKernelsV7 for all heavy operations.
    """
    def __init__(self, device, fused_kernels):
        self.device = device
        self.fused = fused_kernels
        self.use_cuda = device.device_type == "cuda"
        self.use_vulkan = device.device_type == "vulkan"
        self.use_metal = device.device_type == "metal"
        # Graph caches
        self.cuda_graph = None
        self.cuda_instance = None
        self.vk_pipeline = None
        self.mps_graph = None
        # Motion-aware adaptive flags
        self.motion_trigger = 0.0
        self.prev_frame = None
    # ---------------------------------------------------------------------------
    def _compute_motion_mag(self, frame):
        """
        Computes a motion magnitude score to determine dynamic routing:
          - Low motion → add grain, halation, microflicker
          - High motion → disable heavy halation, reduce bloom passes
        """
        if self.prev_frame is None:
            self.prev_frame = frame.copy()
            return 0.0
    # Simple absolute difference (GPU accelerated if available)
        diff = np.mean(np.abs(frame.astype(np.float32) - self.prev_frame.astype(np.float32)))
        self.prev_frame = frame.copy()
        return float(diff)
    # ---------------------------------------------------------------------------
    def _prepare_cuda_graph(self):
        """
        Pre-captures the CUDA graph if not already built.
        """
        if not self.use_cuda or self.cuda_graph is not None:
            return
        # Pseudo graph building (conceptual representation)
        # Real CUDA graph capture occurs inside GPUExecutionEngineV4
        self.cuda_graph = "CUDA_GRAPH_CAPTURED"
        self.cuda_instance = "CUDA_GRAPH_INSTANCE"
        print("[GPU Graph] CUDA graph captured.")
        return
    # ---------------------------------------------------------------------------
    def _prepare_vulkan_pipeline(self):
        """
        Builds a Vulkan compute pipeline (shader modules generated elsewhere).
        """
        if not self.use_vulkan or self.vk_pipeline is not None:
            return
        self.vk_pipeline = "VULKAN_COMPUTE_PIPELINE_READY"
        print("[GPU Graph] Vulkan compute pipeline created.")
    # ---------------------------------------------------------------------------
    def _prepare_mps_graph(self):
        """
        Sets up a Metal MPSGraph for Apple Silicon acceleration.
        """
        if not self.use_metal or self.mps_graph is not None:
            return
        self.mps_graph = "MPS_GRAPH_READY"
        print("[GPU Graph] Metal MPSGraph initialized.")
    # ---------------------------------------------------------------------------
    def _execute_cuda(self, frame, params):
        """
        Executes the fused pipeline via CUDA graph replay (V7 kernels).
        """
        if self.cuda_graph is None:
            self._prepare_cuda_graph()
    # Simplified conceptual execution
        f = frame
        f = self.fused.fused_bloom(f, passes=params["bloom_passes"], base_sigma=params["bloom_sigma"])
        f = self.fused.fused_halation(f, radius=params["hal_radius"], strength=params["hal_strength"])
        f = self.fused.fused_flicker(f, params["frame_idx"])
        g = self.fused.fused_grain(f.shape, params["grain_intensity"])
        out = np.clip(f + g, 0.0, 1.0)
        return out
    # ---------------------------------------------------------------------------
    def _execute_vulkan(self, frame, params):
        """
        Executes the fused pipeline using Vulkan compute dispatch.
        """
        if self.vk_pipeline is None:
            self._prepare_vulkan_pipeline()
    # Vulkan compute simulated behavior
        f = frame
        f = self.fused.fused_bloom(f, passes=params["bloom_passes"], base_sigma=params["bloom_sigma"])
        f = self.fused.fused_halation(f, radius=params["hal_radius"], strength=params["hal_strength"])
        f = self.fused.fused_flicker(f, params["frame_idx"])
        g = self.fused.fused_grain(f.shape, params["grain_intensity"])
        out = np.clip(f + g, 0.0, 1.0)
        return out
    # ---------------------------------------------------------------------------
    def _execute_metal(self, frame, params):
        """
        Executes via MPSGraph (conceptual).
        """
        if self.mps_graph is None:
            self._prepare_mps_graph()
    # Same fused logic
        f = frame
        f = self.fused.fused_bloom(f, passes=params["bloom_passes"], base_sigma=params["bloom_sigma"])
        f = self.fused.fused_halation(f, radius=params["hal_radius"], strength=params["hal_strength"])
        f = self.fused.fused_flicker(f, params["frame_idx"])
        g = self.fused.fused_grain(f.shape, params["grain_intensity"])
        out = np.clip(f + g, 0.0, 1.0)
        return out
    # ---------------------------------------------------------------------------
    def apply(self, frame, frame_idx):
        """
        Adaptive selector:
        - Compute motion → adjust parameters → execute on best backend.
        """
        motion = self._compute_motion_mag(frame)
    # Dynamic parameter map
        params = {
            "frame_idx": frame_idx,
            "bloom_passes": 3 if motion > 0.10 else 5,
        "bloom_sigma": 6.0 if motion > 0.10 else 10.0,
            "hal_radius": 8.0 if motion > 0.10 else 18.0,
        "hal_strength": 0.25 if motion > 0.10 else 0.55,
            "grain_intensity": 0.35 if motion > 0.10 else 0.65
        }
        if self.use_cuda:
            return self._execute_cuda(frame, params)
        if self.use_vulkan:
            return self._execute_vulkan(frame, params)
        if self.use_metal:
            return self._execute_metal(frame, params)
        # CPU fallback
        f = frame
        f = self.fused.fused_bloom(f, passes=params["bloom_passes"], base_sigma=params["bloom_sigma"])
        f = self.fused.fused_halation(f, radius=params["hal_radius"], strength=params["hal_strength"])
        f = self.fused.fused_flicker(f, frame_idx)
        g = self.fused.fused_grain(f.shape, params["grain_intensity"])
        return np.clip(f + g, 0.0, 1.0)
