# ==============================================================================
# CHUNK 81QZ-C59 — SPECTRAL FILM LUT FUSION ENGINE (ACES FILM MATRIX V4)
# ==============================================================================
# Purpose:
#   Apply spectral LUT-based film color transforms using:
#       • Triple-zone LUT blending (shadow/mid/highlight)
#       • Film spectral weighting (Vision3-like)
#       • ACES IDT → Film Matrix → ACES ODT safe workflow
#       • Density-compensated LUT fusion
#       • Skin-protection hue band (20°–45°)
#       • Highlight rolloff stabilizer
#
# Why this matters:
#   This is the heart of FILM COLOR SCIENCE.
#   Digital → Film conversion needs spectral LUT fusion with density-aware
#   blending, otherwise it looks cheap or synthetic.
#
# Pipeline placement:
#   AFTER 81QZ-C58 (Micro-Contrast Engine)
#   BEFORE 81QZ-C60 (Analog Halation Integration Layer)
# ==============================================================================

import numpy as np
import cv2
import math

class FilmLUTFusionV4:
    """
    ACES-compliant spectral LUT fusion engine.
    Performs multi-band LUT blending with density compensation and
    skin-tone protection.
    """

    def __init__(self,
                 lut_shadow=None,
                 lut_mid=None,
                 lut_high=None,
                 blend_softness=0.15,
                 skin_protect_strength=0.18,
                 highlight_protect=0.25):
        # LUTs must be loaded externally (user provides 3x 33³ or 65³ LUTs)
        self.lut_shadow = lut_shadow
        self.lut_mid = lut_mid
        self.lut_high = lut_high
        self.blend_softness = blend_softness
        self.skin_protect_strength = skin_protect_strength
        self.highlight_protect = highlight_protect

    # ----------------------------------------------------------------------
    def _ensure_f32(self, frame):
        if frame.dtype == np.uint8:
            return frame.astype(np.float32) / 255.0
        return frame.astype(np.float32)

    # ----------------------------------------------------------------------
    def _apply_lut(self, img, lut):
        """
        Apply a 3D LUT to an image.
        LUT format expected: (N,N,N,3)
        """
        if lut is None:
            return img
        N = lut.shape[0]
        img_clipped = np.clip(img, 0, 1)
        coords = (img_clipped * (N - 1)).astype(np.int32)
        r = coords[...,2]
        g = coords[...,1]
        b = coords[...,0]
        return lut[r, g, b]

    # ----------------------------------------------------------------------
    def _density_zones(self, frame):
        """
        Computes three masks:
           shadow_mask, mid_mask, highlight_mask
        Uses soft boundaries so zones blend seamlessly.
        """
        lum = 0.2126*frame[...,2] + 0.7152*frame[...,1] + 0.0722*frame[...,0]
        # Soft region transitions
        sh = np.clip((0.35 - lum) / 0.35, 0, 1)
        hi = np.clip((lum - 0.65) / 0.35, 0, 1)
        md = 1 - np.maximum(sh, hi)
        # Blend softness controls zone bleed
        s = self.blend_softness
        sh = cv2.GaussianBlur(sh, (0,0), s*8)
        md = cv2.GaussianBlur(md, (0,0), s*8)
        hi = cv2.GaussianBlur(hi, (0,0), s*8)
        return sh, md, hi

    # ----------------------------------------------------------------------
    def _skin_protect(self, img, transformed):
        """
        Protect skin tones from LUT-induced hue shifts.
        Works in hue-angle domain (HSV).
        """
        hsv_in  = cv2.cvtColor(img, cv2.COLOR_BGR2HSV)
        hsv_out = cv2.cvtColor(transformed, cv2.COLOR_BGR2HSV)
        hue = hsv_in[...,0].astype(np.float32)
        sat = hsv_in[...,1].astype(np.float32) / 255.0
        # Skin hue between 20° and 45° (scaled to OpenCV 0–180 range)
        mask = np.logical_and(hue > 20, hue < 45).astype(np.float32)
        mask = mask * sat
        mask = cv2.GaussianBlur(mask, (0,0), 4)
        mask = (mask * self.skin_protect_strength)[...,None]
        return img * mask + transformed * (1 - mask)

    # ----------------------------------------------------------------------
    def _highlight_rolloff(self, img):
        """
        Protects speculars from LUT clipping artifacts.
        """
        lum = 0.2126*img[...,2] + 0.7152*img[...,1] + 0.0722*img[...,0]
        mask = np.clip((lum - 0.80) / 0.20, 0, 1)
        mask = cv2.GaussianBlur(mask, (0,0), 3)
        rolloff = mask[...,None] * (-self.highlight_protect)
        return np.clip(img + rolloff, 0, 1)

    # ----------------------------------------------------------------------
    def apply(self, frame):
        """
        Full pipeline:
          1. Compute density zones
          2. Apply 3D LUTs
          3. Fuse via zone masks
          4. Skin protection
          5. Highlight rolloff
        """
        if frame is None:
            return None
        f = self._ensure_f32(frame)
        # ---- 1. Zone compute -------------------------------------------------
        sh_mask, md_mask, hi_mask = self._density_zones(f)
        sh_mask3 = sh_mask[...,None]
        md_mask3 = md_mask[...,None]
        hi_mask3 = hi_mask[...,None]
        # ---- 2. Apply LUTs ---------------------------------------------------
        lut_sh = self._apply_lut(f, self.lut_shadow)
        lut_md = self._apply_lut(f, self.lut_mid)
        lut_hi = self._apply_lut(f, self.lut_high)
        # ---- 3. Fuse ---------------------------------------------------------
        fused = (
            lut_sh * sh_mask3 +
            lut_md * md_mask3 +
            lut_hi * hi_mask3
        )
        fused = np.clip(fused, 0, 1)

        # ---- 4. Skin protection ----------------------------------------------
        fused = self._skin_protect(f, fused)

        # ---- 5. Highlight rolloff --------------------------------------------
        fused = self._highlight_rolloff(fused)

        return np.clip(fused, 0, 1)

