import numpy as np
import math

class HarmonicLuminanceBreathingV1:
    """
    Generates subtle exposure breathing over time using a multi-harmonic model.
    Implemented in log-luminance space to mimic real photochemical behavior.
    """

    def __init__(self,
                 base_strength: float = 0.015,      # overall breathing amplitude
                 contrast_link: float = 0.35,       # how much contrast affects breathing
                 harmonic_weight: float = 0.6,      # blend of harmonics vs base
                 speed: float = 1.0):               # playback speed scaling
        
        self.base_strength = base_strength
        self.contrast_link = contrast_link
        self.harmonic_weight = harmonic_weight
        self.speed = speed
        
        self.frame_idx = 0
        self.seed = np.random.rand() * 10000

    # --------------------------------------------------------------------------
    def _compute_breathing_factor(self):
        """
        Multi-band harmonic luminance modulation.
        """
        t = self.frame_idx * 0.033 * self.speed
        # Primary breathing (0.2 Hz)
        b1 = math.sin(t * 0.2 + self.seed) * 0.7
        # Secondary film-tension harmonic (0.47 Hz)
        b2 = math.sin(t * 0.47 + 1.1) * 0.4
        # Third harmonic (1.9 Hz)
        b3 = math.sin(t * 1.9 + 2.5) * 0.25
        harmonic = (b1 + b2 + b3) / 3.0
        return (
            harmonic * self.harmonic_weight +
            np.random.normal(0, 0.02) * (1 - self.harmonic_weight)
        ) * self.base_strength

    # --------------------------------------------------------------------------
    def _estimate_contrast(self, frame):
        """
        Computes global contrast based on simple luminance statistics.
        Contrast influences breathing intensity.
        """
        if frame.ndim == 3:
            lum = (
                0.2126 * frame[..., 2] +
                0.7152 * frame[..., 1] +
                0.0722 * frame[..., 0]
            )
        else:
            lum = frame
        return np.std(lum) / (np.mean(lum) + 1e-6)

    # --------------------------------------------------------------------------
    def apply(self, frame):
        """
        Main breathing application in log luminance domain.
        """
        if frame is None:
            return None
        f = frame.astype(np.float32)
        # 1 — Compute breathing component
        breathing = self._compute_breathing_factor()
        # 2 — Contrast-linked enhancement
        contrast = self._estimate_contrast(f)
        breathing *= (1.0 + contrast * self.contrast_link)
        # 3 — Convert to log space (mimics film exposure)
        log_img = np.log(f + 1e-6)
        # 4 — Apply breathing as additive offset in log space
        log_img += breathing
        # 5 — Convert back to linear domain
        out = np.exp(log_img)
        # 6 — Clamp
        out = np.clip(out, 0.0, 1.0)
        self.frame_idx += 1
        return out

