# ==============================================================================
# CHUNK 81 Q Z C50 — ULTRA ANALOG NEGATIVE STOCK
#                      “GRAIN-TO-LUMINANCE CROSS-MODULATION ENGINE V3”
# ==============================================================================
# Purpose:
#   Real 35mm/65mm/IMAX negative stock does NOT apply grain uniformly.
#   Grain density, intensity, and sharpness change based on:
#       • local exposure (brighter → finer grain)
#       • development temperature
#       • silver-halide crystal saturation
#       • layer stacking (cyan/magenta/yellow)
#
#   This engine simulates:
#       ✓ exposure-weighted grain intensity
#       ✓ shadow-chunk grain clumping
#       ✓ highlight-grain thinning
#       ✓ chroma-dependent grain spectral shifts
#       ✓ time-evolving chemical grain drift
#
# Placement in pipeline:
#    AFTER: Harmonic Luminance Breathing (C49)
#    BEFORE: Film Stock Spectral Emulation (81A)
# ==============================================================================

import numpy as np
import cv2
import math

class GrainLuminanceCrossModV3:
    """
    High-end grain engine that modulates grain by luminance & color channels.
    Time-varying chemical drift adds realism.
    """

    def __init__(self,
                 base_strength: float = 0.22,      # baseline grain
                 shadow_boost: float = 1.4,        # grain increases in dark areas
                 highlight_cut: float = 0.55,      # grain reduced in highlights
                 chroma_link: float = 0.35,        # grain depends on color density
                 drift_speed: float = 0.03):       # time evolution of grain pattern
        self.base_strength = base_strength
        self.shadow_boost = shadow_boost
        self.highlight_cut = highlight_cut
        self.chroma_link = chroma_link
        self.drift_speed = drift_speed
        self.frame_idx = 0
        self.seed = np.random.rand() * 9999

    # --------------------------------------------------------------------------
    def _compute_luminance(self, frame):
        """Extract luminance for grain weighting."""
        return (
            0.2126 * frame[..., 2] +
            0.7152 * frame[..., 1] +
            0.0722 * frame[..., 0]
        )

    # --------------------------------------------------------------------------
    def _generate_base_grain(self, h, w):
        """
        Generates procedural grain with fine → coarse spatial components.
        """
        # Start with white noise
        grain = np.random.normal(0, 1, (h, w)).astype(np.float32)
        # Multi-scale smoothing (simulates crystal cluster structure)
        g_small = cv2.GaussianBlur(grain, (0, 0), sigmaX=0.7)
        g_mid   = cv2.GaussianBlur(grain, (0, 0), sigmaX=1.6)
        g_large = cv2.GaussianBlur(grain, (0, 0), sigmaX=3.8)
        out = (g_small * 0.55 + g_mid * 0.35 + g_large * 0.10)
        return out

    # --------------------------------------------------------------------------
    def _grain_drift(self, grain):
        """
        Slow temporal drift of grain pattern (developer movement).
        """
        t = self.frame_idx * self.drift_speed
        shift_x = int(math.sin(t * 0.7 + self.seed) * 2)
        shift_y = int(math.sin(t * 1.3 + self.seed * 1.2) * 2)
        shifted = np.roll(grain, shift=(shift_y, shift_x), axis=(0, 1))
        return shifted

    # --------------------------------------------------------------------------
    def apply(self, frame):
        """Main cross-modulated grain injection."""
        if frame is None:
            return None
        f = frame.astype(np.float32)
        h, w = f.shape[:2]
        # 1 — Luminance map for exposure-weighted grain
        lum = self._compute_luminance(f)
        # Normalize to 0–1 for mapping
        lum_n = np.clip(lum, 1e-6, 1.0)
        # 2 — Create base grain
        grain = self._generate_base_grain(h, w)
        # 3 — Apply temporal drift
        grain = self._grain_drift(grain)
        # 4 — Exposure-dependent weighting
        shadow_w = (1.0 - lum_n) ** self.shadow_boost
        highlight_w = lum_n ** self.highlight_cut
        # Final intensity map
        intensity_map = (
            shadow_w * 1.2 + 
            (1 - highlight_w) * 0.8
        )
        # 5 — Chroma modulation
        chroma = np.abs(f[..., 2] - f[..., 1]) + np.abs(f[..., 1] - f[..., 0])
        chroma_n = chroma / (np.max(chroma) + 1e-6)
        chroma_boost = 1.0 + chroma_n * self.chroma_link
        intensity_map *= chroma_boost
        # 6 — Apply grain
        grain_rgb = np.stack([grain, grain, grain], axis=2)
        out = f + grain_rgb * intensity_map[..., None] * self.base_strength
        # 7 — Clamp
        out = np.clip(out, 0.0, 1.0)
        self.frame_idx += 1
        return out

