import numpy as np
import cv2
import math

class HalideChargeDiffusionV3:
    """
    Pre-development crystal charge diffusion simulation.
    Produces wavelength-sensitive micro-bloom textures.
    """

    def __init__(self,
                 base_radius: float = 0.65,
                 anisotropy_strength: float = 0.18,
                 temp_drift_strength: float = 0.04,
                 wavelength_scale: tuple = (1.0, 0.85, 0.65)):
        # Root diffusion size for neutral film stock
        self.base_radius = base_radius
        # How directionally biased the grain layer is
        self.aniso = anisotropy_strength
        # Temperature drift → slow large-radius softening
        self.temp_drift = temp_drift_strength
        # Spread radius multipliers for (B, G, R)
        # R diffuses least → higher resolution in red channel
        self.wavelength_scale = wavelength_scale
        # Random long-term drift field seed
        self.seed = np.random.rand() * 40000

    # ----------------------------------------------------------------------
    def _temperature_drift_field(self, h, w, frame_idx):
        """
        Generates a soft field representing film temperature expansion.
        Very low frequency — changes slowly over time.
        """
        xs = np.linspace(0, 2.2, w)
        ys = np.linspace(0, 2.2, h)
        xv, yv = np.meshgrid(xs, ys)
        t = self.seed + frame_idx * 0.002
        drift = (
            np.sin(xv * 0.6 + t) * 0.5 +
            np.sin(yv * 0.7 - t * 0.8) * 0.5
        )
        drift = (drift * 0.5 + 0.5).astype(np.float32)
        return drift * self.temp_drift

    # ----------------------------------------------------------------------
    def _anisotropic_kernel(self, radius, orientation):
        """
        Creates directional Gaussian kernel.
        Orientation rotates the anisotropy (in radians).
        """
        # Kernel size
        k = int(radius * 6)
        if k % 2 == 0:
            k += 1
        ax = np.linspace(-(k//2), k//2, k)
        ay = np.linspace(-(k//2), k//2, k)
        xx, yy = np.meshgrid(ax, ay)
        # Rotate coordinate system
        xr = xx * math.cos(orientation) + yy * math.sin(orientation)
        yr = -xx * math.sin(orientation) + yy * math.cos(orientation)
        sigma_x = radius * (1 + self.aniso)
        sigma_y = radius * (1 - self.aniso)
        kernel = np.exp(-(xr**2 / (2*sigma_x**2) + yr**2 / (2*sigma_y**2)))
        kernel /= np.sum(kernel)
        return kernel.astype(np.float32)

    # ----------------------------------------------------------------------
    def apply(self, frame, frame_idx=0):
        if frame is None:
            return None
        f = frame.astype(np.float32)
        h, w = f.shape[:2]
        # Temperature drift map
        drift = self._temperature_drift_field(h, w, frame_idx)
        # Orientation varies slowly over time
        orientation = math.sin(frame_idx * 0.005 + self.seed) * math.pi
        out = np.zeros_like(f)
        # Diffuse each channel using anisotropic, wavelength-scaled kernels
        for ci in range(3):
            scale = self.wavelength_scale[ci]
            radius = self.base_radius * scale + drift * 2.0
            # Channel-specific kernel
            # We create a new kernel for the *mean* radius per frame.
            mean_r = float(np.mean(radius))
            kernel = self._anisotropic_kernel(mean_r, orientation)
            # Apply convolution
            out[..., ci] = cv2.filter2D(f[..., ci], -1, kernel)
        # Blend original and diffused image
        # 0.85 keeps detail; 0.15 adds pre-softening
        out = f * 0.85 + out * 0.15
        out = np.clip(out, 0.0, 1.0)
        return out

