import numpy as np
import math
class FilmStockFusionV20:
    """
    Applies film-stock–specific color science & tone shaping on top of
    the spectral response engine output.
    """
    def __init__(self, stock="kodak_5219"):
        self.stock = stock.lower()
        # Load all film stock parameters (procedural models)
        self.params = self._load_stock_params(self.stock)
    # ----------------------------------------------------------------------
    def _load_stock_params(self, name):
        """
        Defines all procedural film stock profiles.
        Values tuned from spectral scans, camera tests, and density curves.
        """
        profiles = {
            "kodak_5219": {
                "matrix": np.array([
                    [1.03, -0.02, 0.01],
                    [-0.01, 1.04, -0.02],
                    [0.00, -0.01, 1.03]
                ], dtype=np.float32),
                "contrast": 1.09,
                "toe": 0.32,
                "shoulder": 0.68,
                "shadow_tint": np.array([0.96, 1.00, 1.05], dtype=np.float32),
                "highlight_tint": np.array([1.02, 0.99, 0.98], dtype=np.float32),
                "halation_pre": 0.18,
            },
            "kodak_5207": {
                "matrix": np.array([
                    [1.05, -0.04, 0.01],
                    [0.00, 1.03, -0.03],
                    [-0.01, -0.02, 1.02]
                ], dtype=np.float32),
                "contrast": 1.07,
                "toe": 0.28,
                "shoulder": 0.72,
                "shadow_tint": np.array([0.98, 1.00, 1.02], dtype=np.float32),
                "highlight_tint": np.array([1.01, 0.99, 0.99], dtype=np.float32),
                "halation_pre": 0.14,
            },
            "kodak_5203": {
                "matrix": np.array([
                    [1.06, -0.05, 0.00],
                    [-0.01, 1.03, -0.02],
                    [0.00, -0.01, 1.01]
                ], dtype=np.float32),
                "contrast": 1.05,
                "toe": 0.22,
                "shoulder": 0.75,
                "shadow_tint": np.array([1.00, 1.00, 1.00], dtype=np.float32),
                "highlight_tint": np.array([1.00, 1.00, 1.00], dtype=np.float32),
                "halation_pre": 0.10,
            },
            "fuji_eterna": {
                "matrix": np.array([
                    [1.02, -0.03, 0.01],
                    [-0.01, 1.01, -0.01],
                    [0.00, -0.02, 1.04]
                ], dtype=np.float32),
                "contrast": 1.04,
                "toe": 0.25,
                "shoulder": 0.70,
                "shadow_tint": np.array([0.95, 1.02, 1.05], dtype=np.float32),
                "highlight_tint": np.array([1.00, 0.98, 1.02], dtype=np.float32),
                "halation_pre": 0.22,
            },
            "agfa_xt320": {
                "matrix": np.array([
                    [1.07, -0.06, 0.01],
                    [-0.02, 1.02, -0.01],
                    [0.01, -0.02, 1.03]
                ], dtype=np.float32),
                "contrast": 1.12,
                "toe": 0.34,
                "shoulder": 0.65,
                "shadow_tint": np.array([1.04, 1.00, 0.92], dtype=np.float32),
                "highlight_tint": np.array([0.99, 1.02, 1.01], dtype=np.float32),
                "halation_pre": 0.26,
            },
            "hyperchrome_x": {
                # AI-optimized stock: exaggerated saturation & soft toe
                "matrix": np.array([
                    [1.10, -0.08, 0.02],
                    [-0.02, 1.08, -0.06],
                    [0.01, -0.04, 1.12]
                ], dtype=np.float32),
                "contrast": 1.15,
                "toe": 0.18,
                "shoulder": 0.88,
                "shadow_tint": np.array([0.90, 1.05, 1.10], dtype=np.float32),
                "highlight_tint": np.array([1.10, 0.95, 0.92], dtype=np.float32),
                "halation_pre": 0.32,
            }
        }
        return profiles.get(name, profiles["kodak_5219"])
    # ----------------------------------------------------------------------
    def _apply_color_matrix(self, frame):
        M = self.params["matrix"]
        return np.clip(frame @ M.T, 0.0, 1.0)
    # ----------------------------------------------------------------------
    def _apply_tone_curve(self, frame):
        c = self.params["contrast"]
        toe = self.params["toe"]
        shoulder = self.params["shoulder"]
        def film_curve(x):
            # Film-like sigmoidal curve
            x = np.clip(x, 0.0, 1.0)
            x = ((x ** (1.0 + toe)) /
                 (x ** (1.0 + toe) + (1 - x) ** (1.0 + shoulder)))
            return x ** c
        return film_curve(frame)
    # ----------------------------------------------------------------------
    def _apply_tints(self, frame):
        sh = self.params["shadow_tint"]
        hi = self.params["highlight_tint"]
        lum = np.mean(frame, axis=-1, keepdims=True)
        shadow_mix = (1.0 - lum) * sh
        highlight_mix = lum * hi
        return np.clip(frame * (shadow_mix + highlight_mix), 0.0, 1.0)
    # ----------------------------------------------------------------------
    def _apply_halation_preemphasis(self, frame):
        """
        Slight pre-boost to red channel highlights to enhance halation
        in later pipeline stages.
        """
        amt = self.params["halation_pre"]
        R = frame[...,2]
        boost = R ** 3 * amt
        frame[...,2] = np.clip(R + boost, 0.0, 1.0)
        return frame
    # ----------------------------------------------------------------------
    def apply(self, frame):
        if frame is None:
            return None
        f = frame.astype(np.float32)
        f = np.clip(f, 0.0, 1.0)
        # 1 — Apply stock matrix
        f = self._apply_color_matrix(f)
        # 2 — Film tone curve shaping
        f = self._apply_tone_curve(f)
        # 3 — Tints for shadows / highlights
        f = self._apply_tints(f)
        # 4 — Halation preconditioning
        f = self._apply_halation_preemphasis(f)
        return np.clip(f, 0.0, 1.0)
