# ==============================================================================
import numpy as np
import cv2
import math
class BloomHalationMergeV6:
    """
    Physically interpretable fusion of Bloom + Halation.
    
    Real optical principles:
      - Bloom = lens diffusion (optics)
      - Halation = emulsion backscatter (film layer)
    Interaction model:
      A) If Bloom is strong → Halation fades (already diffused)
      B) If Halation is strong → Bloom rim softens
      C) Highlights choose dominant effect automatically
    """
    def __init__(self,
                 hal_soften=0.55,
                 bloom_supress=0.40,
                 crossover=0.62,
                 spectral_mix=0.35,
                 energy_preserve=True):
        # Halation blends into bloom edges
        self.hal_soften = hal_soften
        # Bloom suppresses over-halation
        self.bloom_supress = bloom_supress
        # Exposure point where bloom ↔ halation dominance swaps
        self.crossover = crossover
        # Cross-spectral mixing helps unify red/green bloom edges
        self.spectral_mix = spectral_mix
        # ACES-style energy compensation
        self.energy_preserve = energy_preserve
    # ----------------------------------------------------------------------
    def _compute_highlight_density(self, frame):
        """Normalized highlight density map used for weighting interplay."""
        lum = (
            frame[...,2] * 0.2126 +
            frame[...,1] * 0.7152 +
            frame[...,0] * 0.0722
        )
        # Normalize into 0-1 range emphasizing bright zones
        d = np.clip((lum - 0.55) / 0.45, 0.0, 1.0)
        d = cv2.GaussianBlur(d.astype(np.float32), (0,0), 2.5)
        return d
    # ----------------------------------------------------------------------
    def _spectral_unify(self, bloom, hal):
        """
        Ensures bloom & halation edges do not show color mismatch.
        Applies spectral cross-mixing to unify hue response.
        """
        b_b = bloom[...,0] * (1.0 - self.spectral_mix) + hal[...,0] * self.spectral_mix
        b_g = bloom[...,1] * (1.0 - self.spectral_mix) + hal[...,1] * self.spectral_mix
        b_r = bloom[...,2] * (1.0 - self.spectral_mix) + hal[...,2] * self.spectral_mix
        h_b = hal[...,0] * (1.0 - self.spectral_mix) + bloom[...,0] * self.spectral_mix
        h_g = hal[...,1] * (1.0 - self.spectral_mix) + bloom[...,1] * self.spectral_mix
        h_r = hal[...,2] * (1.0 - self.spectral_mix) + bloom[...,2] * self.spectral_mix
        bloom_u = np.stack([b_b, b_g, b_r], axis=2)
        hal_u   = np.stack([h_b, h_g, h_r], axis=2)
        return bloom_u, hal_u
    # ----------------------------------------------------------------------
    def apply(self, frame, bloom, hal):
        """
        Main merge algorithm combining bloom + halation.
        """
        if frame is None or bloom is None or hal is None:
            return frame
        f = frame.astype(np.float32)
        b = bloom.astype(np.float32)
        h = hal.astype(np.float32)
        # Highlight intensity map
        density = self._compute_highlight_density(f)
        # Unify spectra before weighting
        b_u, h_u = self._spectral_unify(b, h)
        # bloom = lens-level light bleed
        # hal   = film-layer backscatter
        #
        # weight_bloom_high = highlight regions where bloom dominates
        weight_b = np.clip((density - self.crossover) * 4.0, 0.0, 1.0)
        # weight_halation_high = low-light highlight borders
        weight_h = 1.0 - weight_b
        # halation softening effect from bloom
        h_soft = h_u * (1.0 - self.bloom_supress * weight_b[...,None])
        # bloom smoothing effect from halation
        b_soft = b_u * (1.0 - self.hal_soften * weight_h[...,None])
        # Combine interactively
        merged = (b_soft * weight_b[...,None]) + (h_soft * weight_h[...,None])
        # Add to base frame
        out = f + merged
        # Energy preservation correction
        if self.energy_preserve:
            out = np.clip(out, 0.0, 1.0)
        return out
# ==============================================================================
# END OF CHUNK 81 Q Z C70
