# 3. Sharp Cutoff: ~600nm. Unlike Cyan, Magenta drops to zero quickly in the Red
#    spectrum. This is intentional to prevent muddy skin tones.
#
# ALGORITHM:
# We model the main absorption as a Skewed Gaussian and the secondary absorption
# as a broad Lorentzian. We then sum them to get the total extinction coefficient.
#
# --------------------------------------------------------------------------------------------
import numpy as np
class Vision3_MagentaDye_Physics:
   """
   The Molecular Definition of the Green-Layer Dye (Pyrazolotriazole).
   """
   def __init__(self, wavelengths=None):
       # Wavelength range (380-780nm)
       if wavelengths is None:
           self.wavelengths = np.linspace(380, 780, 401)
       else:
           self.wavelengths = wavelengths
           
       # ----------------------------------------------------------------------
       # MOLECULAR ABSORPTION CONSTANTS (Epsilon)
       # ----------------------------------------------------------------------
       
       # PRIMARY PEAK (Green Absorption)
       self.primary_peak_nm = 550.0
       self.primary_width_nm = 45.0
       self.primary_skew = 0.04 # Positive skew leans towards Red (sharp cutoff)
       
       # SECONDARY PEAK (Unwanted Blue Absorption)
       # This creates the "muddy blue" look if not corrected.
       self.secondary_peak_nm = 430.0
       self.secondary_width_nm = 60.0
       self.secondary_strength = 0.22 # High! 22% of the main peak.
       
       # ----------------------------------------------------------------------
       # DENSITY-DEPENDENT PHYSICS
       # ----------------------------------------------------------------------
       # As density builds, the "Unwanted Blue" peak grows faster than the main peak.
       # This is due to the formation of specific dye aggregates that absorb blue.
       self.secondary_gain_factor = 1.15 # Blue error grows 15% faster than Green signal
       
       # Peak Shift (Solvatochromism during drying)
       self.peak_shift_factor = 2.0 # Shifts redder as density increases
       
       # Cache base profile
       self.base_profile = self._calculate_extinction_coefficient(1.0)
   def _skewed_gaussian(self, x, x0, sigma, skew):
       """
       Standard Gaussian multiplied by a Sigmoid to create asymmetry.
       Used to model the sharp "Red-Side" cutoff of Magenta dye.
       """
       # Normal Gaussian
       g = np.exp(-0.5 * ((x - x0) / sigma) ** 2)
       
       # Sigmoid Skew Function (erf approximation)
       # If skew > 0, it suppresses the left side and boosts the right?
       # No, we want a hard cutoff on the right (Red side).
       # So we use a complementary sigmoid.
       
       s = 1.0 / (1.0 + np.exp(skew * (x - (x0 + 30)))) # Cutoff starts 30nm after peak
       
       return g * s
   def _lorentzian(self, x, x0, gamma):
       """
       Broad resonance curve for the secondary blue absorption.
       """
       return 1.0 / (1.0 + ((x - x0) / gamma)**2)
   def _calculate_extinction_coefficient(self, density_scalar):
       """
       Generates the spectral absorption curve D(lambda) for Magenta.
       """
       # 1. Apply Peak Shift
       # Higher density -> slightly redder peak (Aggregation)
       current_peak = self.primary_peak_nm + (density_scalar * self.peak_shift_factor)
       
       # 2. Construct Primary Peak (Green)
       # Use skewed gaussian to ensure sharp drop-off at 600nm
       absorption_g = self._skewed_gaussian(
           self.wavelengths,
           current_peak,
           self.primary_width_nm,
           0.15 # Sharpness of the red-side cut
       )
       
       # 3. Construct Secondary Peak (Unwanted Blue)
       # Scale strength based on density non-linearity
       # (High density = disproportionately more blue absorption)
       blue_strength = self.secondary_strength * (1.0 + (density_scalar - 1.0) * 0.1)
       
       absorption_b = self._lorentzian(
           self.wavelengths,
           self.secondary_peak_nm,
           self.secondary_width_nm
       ) * blue_strength
       
       # 4. Construct Tertiary Red Leak (Very small)
       # Real Magenta is transparent to Red, but has a tiny "tail"
       absorption_r = np.where(self.wavelengths > 600, 0.01, 0.0)
       
       # 5. Combine
       total_extinction = absorption_g + absorption_b + absorption_r
       
       # Normalize to Peak = 1.0
       max_val = np.max(total_extinction)
       if max_val > 0:
           total_extinction /= max_val
           
       return total_extinction
   def get_spectral_density(self, target_density):
       """
       Returns the array of Optical Density values.
       D(lambda) = Density_Scalar * Epsilon(lambda)
       """
       if target_density > 0.5:
           # Recalculate for shift physics
           profile = self._calculate_extinction_coefficient(target_density)
       else:
           # Use cached linear profile
           profile = self.base_profile
           
       return profile * target_density
   def get_transmission(self, target_density):
       """
       Beer-Lambert Transmission.
       T = 10 ^ (-D)
       """
       d_lambda = self.get_spectral_density(target_density)
       return np.power(10.0, -d_lambda)
   def get_cross_talk_matrix_row(self, target_density=1.0):
       """
       Returns the 'M' row of the color mixing matrix [M_b, M_g, M_r].
       Used for fast-path approximation in real-time pipelines.
       """
       spectrum = self.get_spectral_density(target_density)
       
       # Integrate over ideal sensor bands
       # Blue (400-480), Green (520-580), Red (620-700)
       
       idx_b = (self.wavelengths >= 400) & (self.wavelengths <= 480)
       idx_g = (self.wavelengths >= 520) & (self.wavelengths <= 580)
       idx_r = (self.wavelengths >= 620) & (self.wavelengths <= 700)
       
       # Mean density in each band
       d_b = np.mean(spectrum[idx_b])
       d_g = np.mean(spectrum[idx_g])
       d_r = np.mean(spectrum[idx_r])
       
       # Normalized to Green (Primary)
       if d_g > 0:
           return np.array([d_b/d_g, 1.0, d_r/d_g])
       else:
           return np.array([0.0, 1.0, 0.0])
   def analyze_purity(self, target_density=1.0):
       """
       Debug tool to verify the "Dirty Magenta" hypothesis.
       """
       matrix_row = self.get_cross_talk_matrix_row(target_density)
       print(f"[DYE PHYSICS] Magenta Purity Analysis (Density {target_density}):")
       print(f"  Primary Absorption (Green): 100%")
       print(f"  Parasitic Absorption (Blue): {matrix_row[0]*100:.1f}% (Should be ~20-25%)")
       print(f"  Parasitic Absorption (Red):  {matrix_row[2]*100:.1f}% (Should be < 2%)")
       
       if matrix_row[0] < 0.15:
           print("  [WARNING] Magenta is too pure! Digital look detected.")
       elif matrix_row[0] > 0.30:
           print("  [WARNING] Magenta is too dirty! Muddy blue look detected.")
       else:
           print("  [OK] Magenta profile matches Kodak Vision3 specification.")
   def simulate_projection_illuminant_shift(self, illuminant_spectrum):
       """
       Advanced Feature: 
       How does this dye behave under Xenon Projection vs Tungsten?
       Calculates the effective visual density given a light source.
       """
       # T(lambda)
       transmission = self.get_transmission(1.0)
       
       # Transmitted Light = Source * Transmission
       transmitted_light = illuminant_spectrum * transmission
       
       # Integrate (Total Energy)
       total_energy_in = np.sum(illuminant_spectrum)
       total_energy_out = np.sum(transmitted_light)
       
       if total_energy_in == 0: return 0.0
       
       # Visual Density = -log10(Energy_Out / Energy_In)
       return -np.log10(total_energy_out / total_energy_in)
