import numpy as np
class Vision3_Archival_Aging:
   """
   The Time Machine.
   Ages the virtual negative by N years.
   """
   def __init__(self):
       # ----------------------------------------------------------------------
       # DECAY RATES (% Density Loss per Year at Room Temp)
       # ----------------------------------------------------------------------
       # Based on Kodak Image Stability Data (dark storage).
       
       self.fade_rate_cyan = 0.002    # 0.2% per year (Very Stable)
       self.fade_rate_magenta = 0.008 # 0.8% per year (Unstable)
       self.fade_rate_yellow = 0.005  # 0.5% per year
       
       # ----------------------------------------------------------------------
       # FOG ACCUMULATION
       # ----------------------------------------------------------------------
       # Background radiation (Cosmic Rays) affects all layers equally?
       # No, fast layers (Blue) are more sensitive.
       
       self.fog_rate_per_year = 0.0015 # Density units per year
       
       # ----------------------------------------------------------------------
       # COUPLER STAIN
       # ----------------------------------------------------------------------
       # Unreacted couplers turn yellow. Adds Blue Density.
       self.stain_rate = 0.001
   def age_film_stock(self, density_rgb, years_elapsed=0):
       """
       Applies chemical degradation to the density map.
       """
       if years_elapsed <= 0:
           return density_rgb
           
       r = density_rgb[..., 0] # Cyan Dye
       g = density_rgb[..., 1] # Magenta Dye
       b = density_rgb[..., 2] # Yellow Dye
       
       # 1. Apply Dye Fading (Multiplicative Loss)
       # Density(t) = Density(0) * exp(-k * t)
       
       factor_r = np.exp(-self.fade_rate_cyan * years_elapsed)
       factor_g = np.exp(-self.fade_rate_magenta * years_elapsed)
       factor_b = np.exp(-self.fade_rate_yellow * years_elapsed)
       
       # Note: Fading mainly affects D-Max and Midtones. D-Min is usually stain/mask.
       # We assume the entire image density fades.
       r_aged = r * factor_r
       g_aged = g * factor_g
       b_aged = b * factor_b
       
       # 2. Apply Fog Rise (Additive Gain)
       # Increases D-Min, lifting shadows.
       fog_gain = self.fog_rate_per_year * years_elapsed
       
       r_aged += fog_gain
       g_aged += fog_gain
       b_aged += fog_gain * 1.2 # Blue layer accumulates more fog (faster speed)
       
       # 3. Apply Coupler Stain (Yellowing)
       # Adds uniform Blue Density (Yellow Stain)
       stain = self.stain_rate * years_elapsed
       b_aged += stain
       
       return np.stack([r_aged, g_aged, b_aged], axis=-1)
