# --------------------------------------------------------------------------------------------
import numpy as np
class Vision3_CrossProcess_Physics:
   """
   The 'Lomo' Effect Generator.
   Distorts the H&D curves to mimic chemical incompatibility.
   """
   def __init__(self):
       # ----------------------------------------------------------------------
       # XPRO GAMMA DISTORTION
       # ----------------------------------------------------------------------
       # Slide film developed as negative is very steep.
       self.xpro_gamma_r = 1.10
       self.xpro_gamma_g = 1.35 # Green gets super steep (Green Highlights)
       self.xpro_gamma_b = 1.20
       
       # ----------------------------------------------------------------------
       # OFFSET SHIFTS (The "Cross")
       # ----------------------------------------------------------------------
       # Shifts the midpoints of the curves to create color casts.
       # Values in Density (LogE equivalent).
       
       self.shift_r = -0.10 # Red shadows crush
       self.shift_g = 0.20  # Green midtones lift
       self.shift_b = 0.05  # Blue stays neutral-ish
       
       # ----------------------------------------------------------------------
       # SHOULDER DISTORTION
       # ----------------------------------------------------------------------
