# Output feeds:
#   → AI Stabilization Engine
#   → Motion-Aware Tone & Grain
#   → Cloud Reinforcement Optimizer
#   → Unreal / AirSim simulation
#
# NO FLIGHT CONTROL — METADATA ONLY
# ==============================================================================
import struct
import numpy as np
import subprocess
from collections import deque
class GoProGPMFGyroExtractorUltra:
    """
    Ultra-grade GPMF gyro extractor for GoPro Hero 12.
    Produces:
      - Angular velocity (rad/s)
      - Integrated orientation deltas
      - Confidence score per frame
      - Latency estimation (sensor → frame)
    """
    def __init__(self, gpmf_parser_path="gpmf-parser"):
        self.parser = gpmf_parser_path
        # Ring buffers
        self.gyro_buffer = deque(maxlen=512)
        self.time_buffer = deque(maxlen=512)
        # Calibration offsets (learned online)
        self.bias = np.zeros(3, dtype=np.float32)
        self.scale = np.ones(3, dtype=np.float32)
        # Confidence tracking
        self.confidence_window = deque(maxlen=60)
    # --------------------------------------------------------------------------
    def extract_from_video(self, video_path):
        """
        Uses gpmf-parser to extract raw gyro packets.
        """
        cmd = [self.parser, video_path]
        proc = subprocess.Popen(cmd, stdout=subprocess.PIPE)
        for line in proc.stdout:
            if b"GYRO" in line:
                self._parse_gyro_line(line.decode("utf-8"))
    # --------------------------------------------------------------------------
    def _parse_gyro_line(self, line):
        """
        Parses a single GPMF GYRO packet.
        Expected format:
          GYRO t=123.456 x y z
        """
        try:
            parts = line.strip().split()
            t = float(parts[1].split("=")[1])
            gx = float(parts[2])
            gy = float(parts[3])
            gz = float(parts[4])
            raw = np.array([gx, gy, gz], dtype=np.float32)
            # Bias + scale correction
            corrected = (raw - self.bias) * self.scale
            self.gyro_buffer.append(corrected)
            self.time_buffer.append(t)
            self._update_bias(corrected)
        except Exception:
            pass
    # --------------------------------------------------------------------------
    def _update_bias(self, gyro):
        """
        Slowly learns bias when motion is minimal.
        """
        mag = np.linalg.norm(gyro)
        if mag < 0.02:
            self.bias = self.bias * 0.999 + gyro * 0.001
    # --------------------------------------------------------------------------
    def compute_frame_motion(self, frame_dt):
        """
        Integrates gyro into per-frame rotation deltas.
        """
        if len(self.gyro_buffer) < 2:
            return None
        gyro = np.mean(self.gyro_buffer, axis=0)
        # Integrate angular velocity
        delta = gyro * frame_dt
        confidence = self._compute_confidence(gyro)
        return {
            "d_pitch": float(delta[0]),
            "d_yaw":   float(delta[1]),
            "d_roll":  float(delta[2]),
            "confidence": confidence,
            "latency_ms": self._estimate_latency()
        }
    # --------------------------------------------------------------------------
    def _compute_confidence(self, gyro):
        """
        Confidence based on signal consistency & noise.
        """
        mag = np.linalg.norm(gyro)
        self.confidence_window.append(mag)
        if len(self.confidence_window) < 10:
            return 0.5
        std = np.std(self.confidence_window)
        conf = np.clip(1.0 - (std * 5.0), 0.0, 1.0)
        return float(conf)
    # --------------------------------------------------------------------------
    def _estimate_latency(self):
        """
        Estimates sensor → frame latency.
        """
        if len(self.time_buffer) < 2:
            return 0.0
        dt = self.time_buffer[-1] - self.time_buffer[-2]
        return float(dt * 1000.0)
