class GPMFSample:
    """
    Represents a single GPMF gyro sample aligned to video time.
    """
    __slots__ = (
        "timestamp_us",
        "gyro_xyz",
        "accel_xyz",
        "confidence",
        "latency_us"
    )
    def __init__(
        self,
        timestamp_us: int,
        gyro_xyz: np.ndarray,
        accel_xyz: np.ndarray,
        confidence: float,
        latency_us: int
    ):
        self.timestamp_us = timestamp_us
        self.gyro_xyz = gyro_xyz.astype(np.float32)
        self.accel_xyz = accel_xyz.astype(np.float32)
        self.confidence = float(confidence)
        self.latency_us = int(latency_us)

# ------------------------------------------------------------------------------
# GPMF PARSER (SIMPLIFIED, HERO 12 COMPATIBLE)
# ------------------------------------------------------------------------------

class GoProGPMFParser:
    """
    Extracts gyro + accel from GoPro Hero 12 MP4 GPMF track.
    Assumes prior demux of GPMF binary payload per frame.
    """
    def __init__(self, gyro_scale=1.0, accel_scale=1.0):
        self.gyro_scale = gyro_scale
        self.accel_scale = accel_scale
    def parse_packet(self, raw_bytes: bytes) -> Dict[str, List]:
        """
        Parses a single GPMF payload block.
        Returns dict with gyro, accel, timestamps.
        NOTE:
        - Real implementation uses full GPMF fourCC tree
        - This layer assumes upstream demux already filtered relevant keys
        """
        # Placeholder format:
        # [t_us][gx][gy][gz][ax][ay][az] repeated
        stride = 28  # bytes
        out = {
            "t": [],
            "gyro": [],
            "accel": []
        }
        for i in range(0, len(raw_bytes), stride):
            chunk = raw_bytes[i:i+stride]
            if len(chunk) != stride:
                continue
            t, gx, gy, gz, ax, ay, az = struct.unpack("<Iffffff", chunk)
            out["t"].append(t)
            out["gyro"].append([gx, gy, gz])
            out["accel"].append([ax, ay, az])
        return out

# ------------------------------------------------------------------------------
# CONFIDENCE + LATENCY MODEL
# ------------------------------------------------------------------------------

class GPMFQualityModel:
    """
    Scores reliability of each GPMF sample.
    """
    def __init__(self):
        pass
    def compute_confidence(
        self,
        gyro_xyz: np.ndarray,
        accel_xyz: np.ndarray
    ) -> float:
        """
        Confidence factors:
          • gyro magnitude sanity
          • accel near gravity envelope
        """
        gyro_mag = np.linalg.norm(gyro_xyz)
        accel_mag = np.linalg.norm(accel_xyz)
        gyro_ok = 0.0 <= gyro_mag <= 35.0
        accel_ok = 7.0 <= accel_mag <= 13.0
        score = 1.0
        if not gyro_ok:
            score *= 0.6
        if not accel_ok:
            score *= 0.7
        return float(np.clip(score, 0.0, 1.0))

    def estimate_latency_us(self) -> int:
        """
        GoPro Hero 12 typical sensor → mux latency.
        """
        return 1800  # ~1.8 ms empirical

# ------------------------------------------------------------------------------
# ULTRA GPMF → MOTION STREAM
# ------------------------------------------------------------------------------

class GoProMotionStream:
    """
    Produces time-aligned motion samples usable by:
      • Stabilization
      • Rolling shutter correction
      • AI reframing
      • Cloud reinforcement loop
    """
    def __init__(self):
        self.parser = GoProGPMFParser()
        self.quality = GPMFQualityModel()
    def process_packet(self, raw_bytes: bytes) -> List[GPMFSample]:
        parsed = self.parser.parse_packet(raw_bytes)
        samples = []
        for t, g, a in zip(parsed["t"], parsed["gyro"], parsed["accel"]):
            gyro = np.array(g, dtype=np.float32)
            accel = np.array(a, dtype=np.float32)
            conf = self.quality.compute_confidence(gyro, accel)
            latency = self.quality.estimate_latency_us()
            samples.append(
                GPMFSample(
                    timestamp_us=t,
                    gyro_xyz=gyro,
                    accel_xyz=accel,
                    confidence=conf,
                    latency_us=latency
                )
            )
        return samples

# ------------------------------------------------------------------------------
# OUTPUT INTERFACE (FOR PIPELINE + CLOUD)
# ------------------------------------------------------------------------------

def export_motion_frame(samples: List[GPMFSample]) -> Dict:
    """
    Produces a compact motion packet for downstream AI modules.
    """
    return {
        "timestamps_us": [s.timestamp_us for s in samples],
        "gyro": [s.gyro_xyz.tolist() for s in samples],
        "accel": [s.accel_xyz.tolist() for s in samples],
        "confidence": [s.confidence for s in samples],
        "latency_us": [s.latency_us for s in samples]
    }
