# ==============================================================================
# CHUNK 81 H 06 — VISION3 PRIMARY COLOR SATURATION BIAS
# ==============================================================================
# Purpose:
#   Models Vision3-style primary color saturation bias where
#   Red, Green, and Blue saturate at different perceptual and
#   exposure-dependent rates. This is NOT a simple saturation boost.
#   It preserves skin, prevents neon clipping, and respects film density.
import numpy as _np
def _81h06_rgb_to_hsv_linear(rgb):
    # Linear-light safe RGB→HSV (avoids gamma artifacts)
    r, g, b = rgb[..., 0], rgb[..., 1], rgb[..., 2]
    maxc = _np.maximum(_np.maximum(r, g), b)
    minc = _np.minimum(_np.minimum(r, g), b)
    v = maxc
    delta = maxc - minc + 1e-6
    s = delta / (maxc + 1e-6)
    h = _np.zeros_like(v)
    mask = delta > 1e-6
    rc = (((maxc - r) / delta) % 6)
    gc = (((maxc - g) / delta) + 2)
    bc = (((maxc - b) / delta) + 4)
    h = _np.where((maxc == r) & mask, rc, h)
    h = _np.where((maxc == g) & mask, gc, h)
    h = _np.where((maxc == b) & mask, bc, h)
    h = h / 6.0
    return h, s, v
def _81h06_hsv_to_rgb_linear(h, s, v):
    # Inverse HSV→RGB in linear domain
    h6 = h * 6.0
    i = _np.floor(h6).astype(_np.int32)
    f = h6 - i
    p = v * (1.0 - s)
    q = v * (1.0 - s * f)
    t = v * (1.0 - s * (1.0 - f))
    i_mod = i % 6
    r = _np.select(
        [i_mod == 0, i_mod == 1, i_mod == 2, i_mod == 3, i_mod == 4, i_mod == 5],
        [v, q, p, p, t, v], default=v
    )
    g = _np.select(
        [i_mod == 0, i_mod == 1, i_mod == 2, i_mod == 3, i_mod == 4, i_mod == 5],
        [t, v, v, q, p, p], default=p
    )
    b = _np.select(
        [i_mod == 0, i_mod == 1, i_mod == 2, i_mod == 3, i_mod == 4, i_mod == 5],
        [p, p, t, v, v, q], default=q
    )
    return _np.stack([r, g, b], axis=-1)
def _81h06_primary_bias_weights(h):
    """
    Returns per-pixel bias weights for R, G, B primaries
    based on hue angle.
    Vision3 characteristics:
      - Red saturates earliest (skin protection)
      - Green is most stable (luminance anchor)
      - Blue saturates slowest (sky retention)
    """
    # Hue centers (normalized)
    red_c   = 0.0
    green_c = 1.0 / 3.0
    blue_c  = 2.0 / 3.0
    def gauss(h, c, w):
        d = _np.minimum(_np.abs(h - c), 1.0 - _np.abs(h - c))
        return _np.exp(-(d * d) / (2.0 * w * w))
    w_r = gauss(h, red_c,   0.08)
    w_g = gauss(h, green_c, 0.10)
    w_b = gauss(h, blue_c,  0.12)
    norm = w_r + w_g + w_b + 1e-6
    return w_r / norm, w_g / norm, w_b / norm
def apply_81h06_primary_saturation_bias(
    rgb_linear,
    exposure_ev=0.0,
    strength=1.0
):
    """
    Applies film-accurate primary color saturation bias.
    Args:
        rgb_linear: linear-light RGB (ACEScg or scene-linear)
        exposure_ev: current exposure offset in stops
        strength: global blend factor (0–1)
    """
    h, s, v = _81h06_rgb_to_hsv_linear(rgb_linear)
    # Exposure-aware saturation compression
    # Overexposure → saturation collapses (film behavior)
    exp_factor = _np.clip(1.0 - 0.18 * exposure_ev, 0.65, 1.05)
    # Primary weights
    w_r, w_g, w_b = _81h06_primary_bias_weights(h)
    # Vision3 bias coefficients
    # Red compresses earlier, blue later
    sat_scale = (
        (1.0 - 0.22 * w_r) *
        (1.0 - 0.08 * w_g) *
        (1.0 - 0.04 * w_b)
    )
    sat_scale *= exp_factor
    # Apply bias
    s_biased = _np.clip(s * sat_scale, 0.0, 1.0)
    rgb_biased = _81h06_hsv_to_rgb_linear(h, s_biased, v)
    # Blend with original (safety)
    out = rgb_linear * (1.0 - strength) + rgb_biased * strength
    return _np.clip(out, 0.0, None)
# ==============================================================================
# END OF CHUNK 81 H 06 — PRIMARY COLOR SATURATION BIAS
# ==============================================================================
# ==============================================================================
# CHUNK 81 H 07 — SECONDARY COLOR SATURATION BIAS (VISION3)
# ==============================================================================
# Purpose:
#   Models non-linear saturation behavior of secondary hues (C/M/Y)
#   as observed in Kodak Vision3 film stocks.
#   Prevents digital oversaturation while preserving filmic color density.
#
# Applies to:
#   Cyan, Magenta, Yellow hue sectors only
# ==============================================================================
import numpy as _np
class Vision3SecondarySaturationBias:
    """
    Film-accurate secondary color saturation behavior.
    Characteristics:
        • Cyan saturates early, then compresses
        • Yellow saturates densely but softly
        • Magenta saturates late with gentle roll-off
    This is one of the key differences between film and digital color.
    """
    def __init__(self):
        # Hue centers in normalized HSV hue space [0–1]
        self.hue_cyan = 0.50
        self.hue_magenta = 0.83
        self.hue_yellow = 0.17
        # Hue widths (how wide the influence band is)
        self.width_cyan = 0.08
        self.width_magenta = 0.07
        self.width_yellow = 0.10
        # Saturation bias strengths (film-tuned)
        self.cyan_compress = 0.65
        self.magenta_soft = 0.85
        self.yellow_density = 0.90
    def _hue_distance(self, h, center):
        """
        Circular hue distance.
        """
        d = _np.abs(h - center)
        return _np.minimum(d, 1.0 - d)
    def _sector_mask(self, h, center, width):
        """
        Smooth Gaussian-like mask for hue sector.
        """
        d = self._hue_distance(h, center)
        m = _np.exp(-(d ** 2) / (2.0 * width ** 2))
        return _np.clip(m, 0.0, 1.0)
    def _cyan_bias(self, s, mask):
        """
        Cyan saturates quickly but compresses early.
        Prevents electric-blue water/sky artifacts.
        """
        compressed = s / (1.0 + (s ** 1.3))
        return s * (1.0 - mask) + compressed * mask * self.cyan_compress
    def _magenta_bias(self, s, mask):
        """
        Magenta saturates late and softly.
        Preserves neon/signage without clipping.
        """
        soft = s ** 0.85
        return s * (1.0 - mask) + soft * mask * self.magenta_soft
    def _yellow_bias(self, s, mask):
        """
        Yellow builds density without harsh saturation.
        Critical for skin tones and sunlight.
        """
        dense = s ** 0.92
        return s * (1.0 - mask) + dense * mask * self.yellow_density
    def apply(self, hsv):
        """
        Args:
            hsv: float HSV image, H in [0–1], S,V in [0–1]
        Returns:
            HSV image with film-style secondary saturation behavior
        """
        h = hsv[..., 0]
        s = hsv[..., 1]
        # Build hue masks
        m_c = self._sector_mask(h, self.hue_cyan, self.width_cyan)
        m_m = self._sector_mask(h, self.hue_magenta, self.width_magenta)
        m_y = self._sector_mask(h, self.hue_yellow, self.width_yellow)
        # Apply sector-specific bias
        s2 = self._cyan_bias(s, m_c)
        s2 = self._magenta_bias(s2, m_m)
        s2 = self._yellow_bias(s2, m_y)
        hsv_out = hsv.copy()
        hsv_out[..., 1] = _np.clip(s2, 0.0, 1.0)
        return hsv_out
# ==============================================================================
# END OF CHUNK 81 H 07
# ==============================================================================
# ==============================================================================
