    master_w = _np.clip(master_w, 0.0, 1.0)
    # Merge aging stack (expects pre-aligned RGB arrays)
    aged = rgb.copy()
    for key, layer in aging_stack.items():
        if layer is None:
            continue
        aged = aged * (1.0 - master_w) + layer * master_w
    # Energy preservation
    e_in = _np.mean(rgb, axis=-1, keepdims=True) + 1e-6
    e_out = _np.mean(aged, axis=-1, keepdims=True) + 1e-6
    aged *= e_in / e_out
    # Soft perceptual clipping
