    density = density[..., None]
    rgb = rgb * density
    # Midtone contrast
    rgb = _81l01_apply_contrast(rgb, profile.midtone_contrast)
    # Color separation (film dye behavior)
    rgb = _81l01_color_separation(rgb, profile.color_separation)
