    if gyro_metadata is not None:
        conf = gyro_metadata.get('confidence', 0.0)
        if conf > 0.5:
            # Reduce chroma stress during fast motion
            motion_scale = _np.clip(1.0 - conf * 0.15, 0.85, 1.0)
            rgb = rgb * motion_scale
    return _np.clip(rgb, 0.0, None)
