    # Scale chroma while preserving luminance
    out = rgb * ratio + (1.0 - ratio) * luma[..., None]
    # Energy normalization (avoid dimming)
    e_in = _np.mean(rgb, axis=-1, keepdims=True) + 1e-6
    e_out = _np.mean(out, axis=-1, keepdims=True) + 1e-6
    out *= e_in / e_out
    return _np.clip(out, 0.0, None)
