#   AI-induced color aggression while retaining cinematic contrast intent.
#
import numpy as _np
def _81m04_compute_luma(rgb):
    # WHY: ACES-consistent luma for perceptual decisions
    return (
        0.2722287 * rgb[..., 0] +
        0.6740818 * rgb[..., 1] +
        0.0536895 * rgb[..., 2]
    )
def _81m04_skin_mask(rgb):
    # WHY: Protect human skin from AI over-grading
    r, g, b = rgb[..., 0], rgb[..., 1], rgb[..., 2]
    sum_rgb = r + g + b + 1e-6
