    # Confidence weighting
    confidence = _81n05_temporal_confidence(
        motion_confidence,
        gyro_confidence
    )
    # Arbitration bias:
    # Trust GoPro more when motion & gyro are confident
    primary_weight = _np.clip(
        0.55 + 0.35 * confidence - 0.25 * delta_norm,
        0.15,
        0.85
    )
    primary_weight = primary_weight[..., None]
    blended = _81n05_blend(gopro, ref, primary_weight)
    # Temporal stabilization
    if prev_rgb is not None:
        blended = (
            temporal_strength * blended +
            (1.0 - temporal_strength) * prev_rgb
        )
    # Energy preservation (avoid brightness drift)
    e_in = _81n05_luma(gopro)[..., None] + 1e-6
    e_out = _81n05_luma(blended)[..., None] + 1e-6
    blended *= e_in / e_out
    return _np.clip(blended, 0.0, None)
