    if rgb_prev is None:
        return rgb_curr
    w = _81n07_motion_weight(gyro_mag, gpmf_conf, gpmf_latency_ms)
    # Luma/chroma split
    l_curr = _81n07_luma(rgb_curr)
    l_prev = _81n07_luma(rgb_prev)
    c_curr = _81n07_chroma(rgb_curr, l_curr)
    c_prev = _81n07_chroma(rgb_prev, l_prev)
