    meta = {
        "confidence_gopro": float(g_conf),
        "confidence_internal": float(i_conf),
        "weight_gopro": float(g_w),
        "weight_internal": float(i_w),
        "latency_class": "LOW" if g_conf > i_conf else "MEDIUM",
    }
    return fused, meta
