    out = _81p01_opponent_to_rgb(opp)
    # Energy normalization to prevent density loss
    ein = _np.mean(rgb, axis=-1, keepdims=True) + 1e-6
    eout = _np.mean(out, axis=-1, keepdims=True) + 1e-6
    out *= ein / eout
    return _np.clip(out, 0.0, None)
