    mag_in = _np.linalg.norm(chroma, axis=-1, keepdims=True) + 1e-6
    mag_out = _np.linalg.norm(chroma_stable, axis=-1, keepdims=True) + 1e-6
    chroma_stable *= (mag_in / mag_out)
    # --- Reconstruct RGB ---
    out = chroma_stable * lum[..., None]
    # --- Energy consistency correction ---
    lum_out = _81p03_luminance(out)
    gain = lum / (lum_out + 1e-6)
    gain = _np.clip(gain, 0.9, 1.1)
    out *= gain[..., None]
    return _np.clip(out, 0.0, None)
