    rgb_new = lum[..., None] + chroma_unit * sat_new[..., None]
    # --- Energy preservation ---
    lum_out = _81p05_luminance(rgb_new)
    gain = lum / (lum_out + 1e-6)
    gain = np.clip(gain, 0.9, 1.1)
