# ==============================================================================
# CHUNK 81P-08 — METAL & WATER HIGHLIGHT BEHAVIOR
# ==============================================================================
# Purpose:
#   Model physically distinct highlight responses for:
#     • Conductive surfaces (metal, chrome, vehicles)
#     • Dielectric surfaces (water, glass, wet materials)
#
# This affects:
#   • Highlight spectral balance
#   • Local contrast retention
#   • Energy spread vs concentration
#
# Visible impact:
#   • Water highlights feel "alive", layered, non-flat
#   • Metal highlights feel sharp, dense, specular
#
# Placement:
#   AFTER highlight density redistribution (81P-02)
#   BEFORE highlight edge soft transitions (81P-09)
# ==============================================================================
import numpy as _np
class MetalWaterHighlightModel:
    """
    Physically-inspired highlight behavior separation for metals vs water.
    Operates entirely in linear RGB (ACEScg).
    """
    def __init__(self):
        # Energy shaping coefficients
        self.metal_concentration = 1.25   # metals hold energy tightly
        self.water_dispersion = 0.85      # water disperses energy
        # Spectral bias
        self.metal_spectral_bias = _np.array([1.05, 1.00, 0.95], dtype=_np.float32)
        self.water_spectral_bias = _np.array([0.95, 1.00, 1.08], dtype=_np.float32)
        # Thresholds
        self.highlight_threshold = 0.78
        self.water_luminance_softness = 0.18
        # Temporal memory
        self._prev_energy = None
        self.temporal_alpha = 0.65
    def _luminance(self, rgb):
        return (
            0.2126 * rgb[..., 0] +
            0.7152 * rgb[..., 1] +
            0.0722 * rgb[..., 2]
        )
    def _highlight_mask(self, lum):
        return _np.clip(
            (lum - self.highlight_threshold) /
            (1.0 - self.highlight_threshold),
            0.0, 1.0
        )
    def _estimate_surface_type(self, rgb, lum):
        """
        Heuristic separation:
          • Metals → high luminance, low chroma
          • Water  → high luminance, higher blue energy, smoother gradients
        """
        chroma = _np.std(rgb, axis=-1)
        metal_score = _np.clip(
            (lum * (1.0 - chroma)) * 1.4,
            0.0, 1.0
        )
        water_score = _np.clip(
            (lum * (rgb[..., 2])) * 1.2,
            0.0, 1.0
        )
        return metal_score, water_score
    def _temporal_smooth(self, energy):
        if self._prev_energy is None:
            self._prev_energy = energy
            return energy
        smoothed = (
            self._prev_energy * (1.0 - self.temporal_alpha) +
            energy * self.temporal_alpha
        )
        self._prev_energy = smoothed
        return smoothed
    def apply(self, rgb_linear):
        """
        Input:
          rgb_linear : float32 linear RGB
        Output:
          rgb_linear with surface-aware highlight behavior
        """
        lum = self._luminance(rgb_linear)
        mask = self._highlight_mask(lum)
        if _np.max(mask) < 0.01:
            return rgb_linear
        metal_score, water_score = self._estimate_surface_type(rgb_linear, lum)
        # Normalize contributions
        total = metal_score + water_score + 1e-6
        metal_w = metal_score / total
        water_w = water_score / total
        # Base highlight energy
        energy = rgb_linear * mask[..., None]
        # Metal behavior: tighter, spectrally dense
        metal_energy = (
            energy *
            self.metal_concentration *
            self.metal_spectral_bias
        )
        # Water behavior: softer, spectrally dispersed
        water_energy = (
            energy *
            self.water_dispersion *
            self.water_spectral_bias
        )
        # Blend by surface probability
        combined = (
            metal_energy * metal_w[..., None] +
            water_energy * water_w[..., None]
        )
        # Temporal stabilization (critical for water shimmer realism)
        combined = self._temporal_smooth(combined)
        # Energy conservation
        max_energy = _np.maximum(rgb_linear, combined)
        out = rgb_linear + (max_energy - rgb_linear) * mask[..., None]
        return out
