    hue_weight = _81p09_hue_sensitivity(rgb, lum)
    # Soft saturation knee
    excess = _np.clip(ratio - max_ratio, 0.0, None)
    knee = excess / (excess + knee_strength)
    # Perceptual compression factor
    compress = 1.0 - knee * (1.0 - hue_weight)
