    chroma *= compress[..., None]
    out = chroma + lum[..., None]
    # Energy consistency safeguard
    lum_out = _81p09_luminance(out)
    gain = lum_safe / (_np.clip(lum_out, 1e-6, None))
    gain = _np.clip(gain, 0.92, 1.08)
    out *= gain[..., None]
    return _np.clip(out, 0.0, None)
