# ==============================================================================
# CHUNK 81 Q 02 — PERCEPTUAL SPECTRAL STABILITY & QUANTIZATION CONTROL
# ==============================================================================
#
# Purpose:
#   Suppress perceptually-visible spectral instability introduced by
#   quantization, temporal resampling, and aggressive grading operations.
#   Operates in scene-linear space and preserves chromatic intent while
#   preventing subtle color crawling and banding artifacts.
#
import numpy as _np
def _81q02_perceptual_luma(rgb):
    # WHY: Human vision anchors spectral instability to luma transitions
    return (
        0.2126 * rgb[..., 0] +
        0.7152 * rgb[..., 1] +
        0.0722 * rgb[..., 2]
    )
def _81q02_spectral_variance(rgb):
    # WHY: Spectral variance reveals quantization-induced chroma jitter
    mean = _np.mean(rgb, axis=-1, keepdims=True)
    return _np.mean((rgb - mean) ** 2, axis=-1)
def _81q02_stability_weight(luma, variance):
    # WHY: Stabilize midtones first; highlights/shadows are perceptually tolerant
    luma_w = _np.clip(1.0 - _np.abs(luma - 0.45) * 2.4, 0.0, 1.0)
    var_w = _np.clip(variance * 6.0, 0.0, 1.0)
    return luma_w * var_w
def apply_81q02_spectral_stability(
    rgb_linear,
    strength=0.55,
    floor=1e-5
):
    """
    Reduce perceptually-visible spectral instability without flattening color.
    Parameters:
        rgb_linear : ndarray
            Scene-linear RGB (ACEScg or equivalent).
        strength : float
            Stabilization strength [0–1]. Cinematic sweet spot ~0.4–0.6.
        floor : float
            Numerical stability floor.
    """
    rgb = _np.asarray(rgb_linear, dtype=_np.float32)
    # --- Compute perceptual anchors ---
    luma = _81q02_perceptual_luma(rgb)
    variance = _81q02_spectral_variance(rgb)
    w = _81q02_stability_weight(luma, variance)[..., None]
    w *= strength
    # --- Local spectral mean (per-pixel) ---
    mean_rgb = _np.mean(rgb, axis=-1, keepdims=True)
    # --- Stabilized reconstruction ---
    stabilized = mean_rgb + (rgb - mean_rgb) * (1.0 - w)
    # --- Energy preservation ---
    e_in = _np.mean(rgb, axis=-1, keepdims=True) + floor
    e_out = _np.mean(stabilized, axis=-1, keepdims=True) + floor
    stabilized *= e_in / e_out
    return _np.clip(stabilized, 0.0, None)
# ==============================================================================
# END OF CHUNK 81 Q 02
