# ==============================================================================
# CHUNK 81 Q 05 — MICRO-SPECTRAL HUE DENSITY COMPENSATION ENGINE
# ==============================================================================
#
# Purpose:
#   Correct non-linear hue density drift introduced by film-like spectral
#   cross-coupling and aggressive grading. This module preserves hue identity
#   under high density, especially in saturated regions, without flattening.
#
# Cinematic Intent:
#   - Prevent hue “bending” in deep colors
#   - Maintain perceptual hue stability under density changes
#   - Emulate photochemical dye density behavior (Kodak / Fuji lineage)
#   - ACES-linear compatible
#
import numpy as _np
def _81q05_rgb_to_hue(rgb):
    # WHY: Hue extraction without polar instability
    r, g, b = rgb[..., 0], rgb[..., 1], rgb[..., 2]
    num = _np.sqrt(3.0) * (g - b)
    den = 2.0 * r - g - b
    return _np.arctan2(num, den)
def _81q05_density(rgb):
    # WHY: Film density correlates with log exposure, not linear value
    return _np.log1p(_np.mean(rgb, axis=-1))
def _81q05_hue_preservation_weight(density):
    # WHY: Hue instability increases with density
    return _np.clip(density * 1.4, 0.0, 1.0)
def _81q05_compensate(rgb, strength):
    # Extract hue and density
    hue = _81q05_rgb_to_hue(rgb)
    dens = _81q05_density(rgb)
    # Compute preservation weight
    w = _81q05_hue_preservation_weight(dens) * strength
    # Reference hue from desaturated signal
    gray = _np.mean(rgb, axis=-1, keepdims=True)
    rgb_ref = _np.repeat(gray, 3, axis=-1)
    hue_ref = _81q05_rgb_to_hue(rgb_ref)
    # Hue delta
    dh = hue - hue_ref
    # Apply correction
    hue_corr = hue - dh * w
    # Reconstruct RGB direction from corrected hue
    cos_h = _np.cos(hue_corr)
    sin_h = _np.sin(hue_corr)
    # Direction vectors in RGB space (normalized)
    dir_r = (1.0 / 3.0) * (1.0 + 2.0 * cos_h)
    dir_g = (1.0 / 3.0) * (1.0 - cos_h + _np.sqrt(3.0) * sin_h)
    dir_b = (1.0 / 3.0) * (1.0 - cos_h - _np.sqrt(3.0) * sin_h)
    dirs = _np.stack([dir_r, dir_g, dir_b], axis=-1)
    # Preserve original luminance
    lum = _np.mean(rgb, axis=-1, keepdims=True) + 1e-6
    dirs /= (_np.mean(dirs, axis=-1, keepdims=True) + 1e-6)
    return dirs * lum
def apply_81q05_micro_spectral_hue_density_compensation(
    rgb_linear,
    strength=0.55
):
    """
    Parameters:
        rgb_linear : ndarray
            Scene-linear RGB (ACEScg preferred).
        strength : float
            Compensation intensity [0–1]. Cinematic sweet spot ~0.4–0.6.
    """
    rgb = _np.asarray(rgb_linear, dtype=_np.float32)
    # Fast exit if no saturation present
    sat = _np.max(rgb, axis=-1) - _np.min(rgb, axis=-1)
    if _np.max(sat) < 1e-4:
        return rgb
    out = _81q05_compensate(rgb, strength)
    # Energy normalization
    e_in = _np.mean(rgb, axis=-1, keepdims=True) + 1e-6
    e_out = _np.mean(out, axis=-1, keepdims=True) + 1e-6
    out *= e_in / e_out
    return _np.clip(out, 0.0, None)
