    if motion_magnitude is None:
        motion_gate = 1.0
    else:
        motion_gate = _81u02_motion_gate(motion_magnitude)
    # --- Perceptual midtone weighting ---
    mid_w = _np.clip(1.0 - _np.abs(luma - 0.45) * 2.0, 0.0, 1.0)
    # --- Temporal blend factor ---
    alpha = strength * motion_gate * mid_w
    alpha = _np.clip(alpha, 0.0, 1.0)[..., None]
    # --- Stabilize chroma only ---
    chroma_stable = chroma * (1.0 - alpha) + chroma_prev * alpha
    # --- Recombine ---
    out = _81u02_recombine(chroma_stable, luma)
    # --- Energy correction to avoid exposure drift ---
    e_in = _np.mean(rgb, axis=-1, keepdims=True) + 1e-6
    e_out = _np.mean(out, axis=-1, keepdims=True) + 1e-6
    out *= e_in / e_out
    return _np.clip(out, 0.0, None)
