# ==============================================================================
# CHUNK 81 W 09 — TEMPORAL CHROMATIC MEMORY STABILIZATION
# ==============================================================================
# Purpose:
#   Enforce perceptual chromatic continuity across time by introducing a
#   controlled color-memory decay model. This prevents subtle hue flicker,
#   chroma breathing, and inter-frame color instability that can arise from
#   AI-driven exposure, tone arbitration, and spectral reshaping.
#
# Scope:
#   - Operates in scene-linear color space
#   - Frame-to-frame temporal domain only
#   - NO spatial blur
#   - NO grain interaction
#   - NO motion vector dependency (handled elsewhere)
#
import numpy as np
class TemporalChromaticMemory:
    """
    Maintains a perceptual chromatic anchor across frames with adaptive decay.
    Inspired by human visual color memory and photochemical print stability.
    """
    def __init__(
        self,
        decay_rate=0.92,
        max_influence=0.35,
        luma_bias=0.6
    ):
        self.decay_rate = np.clip(decay_rate, 0.85, 0.99)
        self.max_influence = np.clip(max_influence, 0.0, 0.5)
        self.luma_bias = np.clip(luma_bias, 0.0, 1.0)
        self._memory = None
    # --------------------------------------------------------------------------
    def _compute_luminance(self, rgb):
        return (
            0.2126 * rgb[..., 0] +
            0.7152 * rgb[..., 1] +
            0.0722 * rgb[..., 2]
        )
    # --------------------------------------------------------------------------
    def _extract_chroma(self, rgb):
        lum = self._compute_luminance(rgb) + 1e-6
        return rgb / lum[..., None]
    # --------------------------------------------------------------------------
    def apply(self, rgb_linear):
        """
        Apply temporal chromatic stabilization.
        Args:
            rgb_linear : ndarray
                Scene-linear RGB frame.
        Returns:
            Stabilized RGB frame.
        """
        img = rgb_linear.astype(np.float32)
        chroma = self._extract_chroma(img)
        lum = self._compute_luminance(img)
        if self._memory is None:
            self._memory = chroma.copy()
            return img
        # --- Update memory with exponential decay ---
        self._memory = (
            self._memory * self.decay_rate +
            chroma * (1.0 - self.decay_rate)
        )
        # --- Compute influence mask (midtone-biased) ---
        luma_mask = 1.0 - np.abs(lum - 0.45) * 2.0
        luma_mask = np.clip(luma_mask, 0.0, 1.0)
        influence = luma_mask * self.max_influence * self.luma_bias
        # --- Blend chroma toward memory ---
        chroma_stable = (
            chroma * (1.0 - influence[..., None]) +
            self._memory * influence[..., None]
        )
        # --- Reconstruct RGB ---
        out = chroma_stable * lum[..., None]
        # --- Energy safety clamp ---
        out = np.clip(out, 0.0, None)
        return out
# --------------------------------------------------------------------------
# PIPELINE HOOK
# --------------------------------------------------------------------------
_81W09_temporal_chroma_memory = TemporalChromaticMemory()
def apply_81W09_temporal_chromatic_memory(rgb_linear):
    """
    Global entry point for temporal chromatic stabilization.
    """
    return _81W09_temporal_chroma_memory.apply(rgb_linear)
