# ==============================================================================
# CHUNK 81 X 01 — SCENE TYPE CLASSIFICATION INFLUENCE
# ==============================================================================
#
# Purpose:
#   Introduce high-level scene awareness into the film stock pipeline.
#   This module converts AI scene classification signals into subtle,
#   physically-grounded color and contrast biases that mirror how
#   cinematographers choose film stocks based on environment.
#
#   IMPORTANT:
#   • This does NOT hard-switch looks.
#   • It softly biases downstream film response.
#   • It preserves ACES-linear energy.
#
# Scene categories are assumed to come from an upstream vision model:
#   { indoor, outdoor, nature, urban, night, high_contrast, low_light }
#
import numpy as _np
def _81x01_luma(rgb):
    # WHY: ACES AP1 luminance for perceptual classification weighting
    return (
        0.2722287 * rgb[..., 0] +
        0.6740818 * rgb[..., 1] +
        0.0536895 * rgb[..., 2]
    )
def _81x01_softstep(x, softness=1.5):
    # WHY: Prevent abrupt scene influence changes
    x = _np.clip(x, 0.0, 1.0)
    return x ** softness / (x ** softness + (1.0 - x) ** softness + 1e-6)
class SceneTypeInfluence81X01:
    """
    Converts scene classification probabilities into
    film-stock-aware color and contrast bias weights.
    """
    def __init__(self):
        # Global influence ceiling (never overpower film stock)
        self.max_bias = 0.18
        # Scene-specific perceptual tendencies
        self.scene_bias = {
            "indoor":   {"warmth": 0.10, "contrast": -0.05},
            "outdoor":  {"warmth": -0.03, "contrast": 0.04},
            "nature":   {"warmth": 0.06, "contrast": -0.02},
            "urban":    {"warmth": -0.04, "contrast": 0.06},
            "night":    {"warmth": 0.02, "contrast": -0.08},
            "high_contrast": {"warmth": -0.02, "contrast": -0.10},
            "low_light": {"warmth": 0.04, "contrast": -0.12},
        }
        # Temporal smoothing
        self.temporal_alpha = 0.85
        self._prev_bias = None
    def compute_bias(self, scene_probs: dict):
        """
        Parameters:
            scene_probs : dict
                Scene classification probabilities from AI.
                Example:
                {
                  "indoor": 0.1,
                  "outdoor": 0.6,
                  "nature": 0.3
                }
        Returns:
            dict with keys {warmth, contrast}
        """
        warmth = 0.0
        contrast = 0.0
        for k, p in scene_probs.items():
            if k not in self.scene_bias:
                continue
            w = _81x01_softstep(p)
            warmth += self.scene_bias[k]["warmth"] * w
            contrast += self.scene_bias[k]["contrast"] * w
        # Clamp to perceptual ceiling
        warmth = _np.clip(warmth, -self.max_bias, self.max_bias)
        contrast = _np.clip(contrast, -self.max_bias, self.max_bias)
        bias = {"warmth": warmth, "contrast": contrast}
        # Temporal stabilization
        if self._prev_bias is not None:
            bias["warmth"] = (
                self.temporal_alpha * self._prev_bias["warmth"] +
                (1.0 - self.temporal_alpha) * bias["warmth"]
            )
            bias["contrast"] = (
                self.temporal_alpha * self._prev_bias["contrast"] +
                (1.0 - self.temporal_alpha) * bias["contrast"]
            )
        self._prev_bias = bias
        return bias
def apply_81x01_scene_bias(rgb_linear, scene_bias):
    """
    Apply scene-aware film bias to ACES-linear RGB.
    This intentionally operates BEFORE emotional bias (81W)
    and BEFORE stability enforcement (81Y).
    """
    rgb = _np.asarray(rgb_linear, dtype=_np.float32)
    luma = _81x01_luma(rgb)[..., None]
    # Warmth bias: tilt red/blue energy around luminance
    warmth = scene_bias.get("warmth", 0.0)
    rgb_warm = rgb.copy()
    rgb_warm[..., 0] += warmth * (luma[..., 0] - rgb[..., 0])
    rgb_warm[..., 2] -= warmth * (luma[..., 0] - rgb[..., 2])
    # Contrast bias: soft S-curve around mid-gray
    contrast = scene_bias.get("contrast", 0.0)
    pivot = 0.18
    rgb_contrast = pivot + (rgb_warm - pivot) * (1.0 + contrast)
    # Energy preservation
    e_in = _np.mean(rgb, axis=-1, keepdims=True) + 1e-6
    e_out = _np.mean(rgb_contrast, axis=-1, keepdims=True) + 1e-6
    rgb_contrast *= e_in / e_out
    return _np.clip(rgb_contrast, 0.0, None)
# ==============================================================================
# END OF CHUNK 81 X 01
# ==============================================================================
# ==============================================================================
# CHUNK 81 X 02 — INDOOR VS OUTDOOR BIAS
# ==============================================================================
#
# Purpose:
#   Apply physically and perceptually grounded color, contrast, and density
#   biases based on indoor vs outdoor scene classification.
#
#   This is NOT a LUT switch.
#   This module models real photographic differences between:
#     • Artificial illumination environments (indoor)
#     • Solar / sky-dominated illumination environments (outdoor)
#
#   Designed to:
#     • Preserve ACES linear integrity
#     • Influence later film / print behavior subtly
#     • Avoid obvious "look jumps"
#
# Placement:
#   AFTER: 81W (Emotional Bias Layer)
#   BEFORE: 81X-03 (Nature Scene Color Logic)
#
# Reference:
#   Kodak Vision3 indoor tungsten response
#   ARRI Alexa indoor vs daylight separation
#   ASC CDL indoor scene handling notes
#
# ==============================================================================
import numpy as _np
# ------------------------------------------------------------------------------
# Helper: ACES AP1 luminance
# ------------------------------------------------------------------------------
def _81x02_luminance_ap1(rgb):
    return (
        rgb[..., 0] * 0.2722287168 +
        rgb[..., 1] * 0.6740817658 +
        rgb[..., 2] * 0.0536895174
    )
# ------------------------------------------------------------------------------
# Helper: Soft bias curve
# ------------------------------------------------------------------------------
def _81x02_soft_bias(x, strength):
    """
    Smooth, energy-preserving bias curve.
    """
    return x + strength * (x - x * x)
# ------------------------------------------------------------------------------
# Core Logic
# ------------------------------------------------------------------------------
def apply_81x02_indoor_outdoor_bias(
    rgb_linear_ap1,
    scene_probabilities,
    strength=0.65
):
    """
    Parameters:
        rgb_linear_ap1 : ndarray
            Linear-light ACES AP1 RGB.
        scene_probabilities : dict
            Expected keys:
                {
                    "indoor": float,
                    "outdoor": float
                }
        strength : float
            Global influence scaler [0–1].
    """
    indoor_w = float(scene_probabilities.get("indoor", 0.0))
    outdoor_w = float(scene_probabilities.get("outdoor", 0.0))
    # Normalize defensively
    s = indoor_w + outdoor_w + 1e-6
    indoor_w /= s
    outdoor_w /= s
    if indoor_w < 0.05 and outdoor_w < 0.05:
        return rgb_linear_ap1
    # --------------------------------------------------------------------------
    # 1. Luminance extraction
    # --------------------------------------------------------------------------
    lum = _81x02_luminance_ap1(rgb_linear_ap1)
    # --------------------------------------------------------------------------
    # 2. Indoor bias model
    #
    # Physics:
    #   • Artificial light → reduced blue energy
    #   • Higher contrast in midtones
    #   • Slight warmth accumulation
    # --------------------------------------------------------------------------
    indoor_bias = _np.zeros_like(rgb_linear_ap1)
    # Channel weighting (AP1)
    indoor_bias[..., 0] += 0.015  # Red lift
    indoor_bias[..., 1] += 0.005  # Mild green
    indoor_bias[..., 2] -= 0.020  # Blue suppression
    # Contrast shaping (midtone emphasis)
    mid_mask = _np.clip((lum - 0.25) / 0.5, 0.0, 1.0)
    mid_mask = mid_mask * (1.0 - mid_mask)
    mid_mask = mid_mask[..., None]
    indoor_contrast = (
        rgb_linear_ap1 +
        (rgb_linear_ap1 - lum[..., None]) * mid_mask * 0.25
    )
    # --------------------------------------------------------------------------
    # 3. Outdoor bias model
    #
    # Physics:
    #   • Solar illumination → strong blue component
    #   • Lower perceived contrast
    #   • Cleaner highlight separation
    # --------------------------------------------------------------------------
    outdoor_bias = _np.zeros_like(rgb_linear_ap1)
    outdoor_bias[..., 0] -= 0.010
    outdoor_bias[..., 1] += 0.000
    outdoor_bias[..., 2] += 0.020
    # Contrast relaxation
    outdoor_contrast = (
        rgb_linear_ap1 -
        (rgb_linear_ap1 - lum[..., None]) * 0.18
    )
    # --------------------------------------------------------------------------
    # 4. Weighted blend
    # --------------------------------------------------------------------------
    indoor_rgb = indoor_contrast + indoor_bias
    outdoor_rgb = outdoor_contrast + outdoor_bias
    blended = (
        rgb_linear_ap1 * (1.0 - strength) +
        strength * (
            indoor_rgb * indoor_w +
            outdoor_rgb * outdoor_w
        )
    )
    # --------------------------------------------------------------------------
    # 5. Energy normalization (critical for ACES pipeline)
    # --------------------------------------------------------------------------
    e_in = _np.mean(rgb_linear_ap1, axis=-1, keepdims=True) + 1e-6
    e_out = _np.mean(blended, axis=-1, keepdims=True) + 1e-6
    blended *= e_in / e_out
    return _np.clip(blended, 0.0, None)
# ==============================================================================
# END OF CHUNK 81 X 02 — INDOOR VS OUTDOOR BIAS
# ==============================================================================
# ==============================================================================
# CHUNK 81X-03 — NATURE SCENE COLOR LOGIC
# ==============================================================================
#
# SUBCHUNK ID: 81X-03
# PARENT SYSTEM: 81X (Film Stock Scene Awareness)
#
# OBJECTIVE:
#   Apply scene-aware color logic optimized for natural environments
#   (foliage, sky, earth, water) that mimics high-end film stock behavior.
#
# CORE PRINCIPLES:
#   • Preserve chlorophyll greens (no digital neon shift)
#   • Maintain sky spectral purity without cyan clipping
#   • Slight warmth bias in highlights (sun energy)
#   • Film-like saturation compression in high-energy colors
#   • ACES-linear safe operations only
#
# ------------------------------------------------------------------------------
import numpy as np
class NatureSceneColorLogic:
   """
   Scene-aware color shaping for outdoor natural environments.
   Designed to sit AFTER base film response but BEFORE emotional bias layers.
   """
   def __init__(self):
       # ------------------------------------------------------------------
       # GREEN (FOLIAGE) BEHAVIOR
       # ------------------------------------------------------------------
       # Film greens compress saturation early to avoid "video grass".
       self.green_sat_compress = 0.18
       self.green_luma_anchor = 0.55
       # Slight yellow bias in highlights (sunlit leaves)
       self.green_warm_shift = 0.04
       # ------------------------------------------------------------------
       # SKY / ATMOSPHERIC BLUES
       # ------------------------------------------------------------------
       # Prevent cyan over-rotation in skies
       self.sky_cyan_suppression = 0.22
       # Maintain deep blue density without crushing
       self.sky_density_preserve = 0.85
       # ------------------------------------------------------------------
       # EARTH / SOIL / ROCK TONES
       # ------------------------------------------------------------------
       # Earth tones lean warm but low saturation
       self.earth_warm_bias = 0.06
       self.earth_sat_limit = 0.65
       # ------------------------------------------------------------------
       # GLOBAL NATURE CONTRAST SHAPING
       # ------------------------------------------------------------------
       # Natural scenes prefer softer contrast than urban scenes
       self.contrast_softening = 0.92
   # --------------------------------------------------------------------------
   def _luminance(self, f):
       return (
           f[..., 0] * 0.2126 +
           f[..., 1] * 0.7152 +
           f[..., 2] * 0.0722
       )
   # --------------------------------------------------------------------------
   def _saturation(self, f):
       maxc = np.max(f, axis=-1)
       minc = np.min(f, axis=-1)
       return (maxc - minc) / (maxc + 1e-6)
   # --------------------------------------------------------------------------
   def _green_logic(self, f, lum, sat):
       """
       Controls foliage greens:
       - Saturation compression
       - Highlight warmth
       """
       r, g, b = f[..., 0], f[..., 1], f[..., 2]
       # Identify green-dominant pixels
       green_mask = (g > r) & (g > b)
       # Saturation compression
       sat_comp = 1.0 - (sat * self.green_sat_compress)
       # Highlight warmth (only above anchor luminance)
       warm_mask = lum > self.green_luma_anchor
       warm_factor = (lum - self.green_luma_anchor) * self.green_warm_shift
       r = r + warm_factor * warm_mask * green_mask
       g = g
       b = b - warm_factor * warm_mask * green_mask
       # Apply saturation compression
       avg = (r + g + b) / 3.0
       r = avg + (r - avg) * sat_comp
       g = avg + (g - avg) * sat_comp
       b = avg + (b - avg) * sat_comp
       return np.stack([r, g, b], axis=-1)
   # --------------------------------------------------------------------------
   def _sky_logic(self, f, lum):
       """
       Controls sky blues:
       - Prevent cyan shift
       - Preserve density
       """
       r, g, b = f[..., 0], f[..., 1], f[..., 2]
       # Blue dominant detection
       sky_mask = (b > g) & (b > r)
       # Cyan suppression (reduce green leakage into blue)
       g = g * (1.0 - self.sky_cyan_suppression * sky_mask)
       # Density preservation
       b = b * self.sky_density_preserve + b * (1.0 - self.sky_density_preserve)
       return np.stack([r, g, b], axis=-1)
   # --------------------------------------------------------------------------
   def _earth_logic(self, f):
       """
       Controls soil, rock, sand tones:
       - Warm bias
       - Saturation limiting
       """
       r, g, b = f[..., 0], f[..., 1], f[..., 2]
       # Earth tones often have R >= G >= B
       earth_mask = (r >= g) & (g >= b)
       # Warm bias
       r = r + self.earth_warm_bias * earth_mask
       b = b - self.earth_warm_bias * earth_mask
       # Saturation clamp
       avg = (r + g + b) / 3.0
       r = avg + (r - avg) * self.earth_sat_limit
       g = avg + (g - avg) * self.earth_sat_limit
       b = avg + (b - avg) * self.earth_sat_limit
       return np.stack([r, g, b], axis=-1)
   # --------------------------------------------------------------------------
   def apply(self, frame):
       """
       Applies nature scene color logic.
       """
       if frame is None:
           return None
       f = frame.astype(np.float32)
       lum = self._luminance(f)
       sat = self._saturation(f)
       # Apply foliage logic
       f = self._green_logic(f, lum, sat)
       # Apply sky logic
       f = self._sky_logic(f, lum)
       # Apply earth logic
       f = self._earth_logic(f)
       # Global contrast softening for nature
       avg = np.mean(f, axis=-1, keepdims=True)
       f = avg + (f - avg) * self.contrast_softening
       # ACES-safe clamp
       f = np.clip(f, 0.0, 1.0)
       return f
# ==============================================================================
# END OF CHUNK 81X-03 — NATURE SCENE COLOR LOGIC
