# ==============================================================================
# CHUNK 81 X 04 — HYBRID GYRO–OPTICAL MOTION FUSION (ULTRA)
# ==============================================================================
# Purpose:
#   Fuse GoPro GPMF gyro data with optical flow motion vectors to produce
#   a physically coherent, confidence-weighted motion field.
#
#   Design goals:
#     • Prefer real gyro when reliable (low latency, high confidence)
#     • Fall back to optical motion when gyro confidence degrades
#     • Preserve cinematic inertia (no robotic correction)
#     • ACES-linear safe (no perceptual-domain math)
#
#   Outputs:
#     • stabilized_motion_field (dx, dy, rotation)
#     • per-frame confidence scalar
#
#   NOTE:
#     This module DOES NOT control motors or flight.
#     It produces motion intent for stabilization, framing, and grading.
#
import numpy as _np
import cv2 as _cv2
class HybridMotionFusion81X04:
    """
    Ultra-grade hybrid motion fusion engine.
    Inputs:
      - GPMF gyro packets (angular velocity + confidence)
      - Optical flow vectors (dense or sparse)
    Output:
      - Stabilized motion field with physical plausibility
    """
    def __init__(self):
        # ------------------------------------------------------------------
        # Trust model
        # ------------------------------------------------------------------
        self.gyro_latency_ms = 3.5
        self.optical_latency_ms = 18.0
        self.gyro_base_weight = 0.75
        self.optical_base_weight = 0.25
        # ------------------------------------------------------------------
        # Temporal inertia (cinematic smoothness)
        # ------------------------------------------------------------------
        self.temporal_inertia = 0.88
        # ------------------------------------------------------------------
        # Safety clamps (prevent digital snap)
        # ------------------------------------------------------------------
        self.max_translation_px = 42.0
        self.max_rotation_deg = 2.8
        # ------------------------------------------------------------------
        # State memory
        # ------------------------------------------------------------------
        self._prev_motion = None
        self._prev_confidence = None
    # ----------------------------------------------------------------------
    def _normalize_flow(self, flow):
        """
        Normalize optical flow to pixel displacement per frame.
        """
        mag = _np.linalg.norm(flow, axis=-1)
        scale = _np.clip(mag / (mag.mean() + 1e-6), 0.0, 2.0)
        return flow * scale[..., None]
    # ----------------------------------------------------------------------
    def _extract_optical_motion(self, flow):
        """
        Reduce dense flow to global translation + rotation estimate.
        """
        h, w, _ = flow.shape
        cx, cy = w * 0.5, h * 0.5
        ys, xs = _np.mgrid[0:h, 0:w]
        dx = flow[..., 0]
        dy = flow[..., 1]
        # Translation (median is robust)
        tx = _np.median(dx)
        ty = _np.median(dy)
        # Rotation estimate around center
        rx = xs - cx
        ry = ys - cy
        rot = _np.median((rx * dy - ry * dx) / (rx**2 + ry**2 + 1e-6))
        return _np.array([tx, ty, rot], dtype=_np.float32)
    # ----------------------------------------------------------------------
    def _extract_gyro_motion(self, gpmf_packet):
        """
        Convert GPMF angular velocity to frame-relative motion.
        """
        wx = gpmf_packet.get("gyro_x", 0.0)
        wy = gpmf_packet.get("gyro_y", 0.0)
        wz = gpmf_packet.get("gyro_z", 0.0)
        # Convert rad/s to degrees/frame (GoPro timestamps assumed)
        rot_deg = _np.degrees(wz) * gpmf_packet.get("dt", 0.0083)
        # Translation from angular tilt (small-angle approx)
        tx = _np.degrees(wx) * 0.12
        ty = _np.degrees(wy) * 0.12
        return _np.array([tx, ty, rot_deg], dtype=_np.float32)
    # ----------------------------------------------------------------------
    def _confidence_from_gpmf(self, gpmf_packet):
        """
        Extract gyro confidence from GPMF metadata.
        """
        base = gpmf_packet.get("confidence", 0.6)
        latency_penalty = _np.clip(self.gyro_latency_ms / 10.0, 0.0, 0.3)
        return _np.clip(base - latency_penalty, 0.0, 1.0)
    # ----------------------------------------------------------------------
    def _confidence_from_flow(self, flow):
        """
        Confidence from optical flow coherence.
        """
        mag = _np.linalg.norm(flow, axis=-1)
        coherence = 1.0 - (_np.std(mag) / (_np.mean(mag) + 1e-6))
        latency_penalty = _np.clip(self.optical_latency_ms / 25.0, 0.0, 0.4)
        return _np.clip(coherence - latency_penalty, 0.0, 1.0)
    # ----------------------------------------------------------------------
    def fuse(self, flow, gpmf_packet):
        """
        Main fusion entry point.
        """
        flow = self._normalize_flow(flow)
        opt_motion = self._extract_optical_motion(flow)
        gyro_motion = self._extract_gyro_motion(gpmf_packet)
        opt_conf = self._confidence_from_flow(flow)
        gyro_conf = self._confidence_from_gpmf(gpmf_packet)
        # Normalize weights
        w_gyro = gyro_conf * self.gyro_base_weight
        w_opt = opt_conf * self.optical_base_weight
        w_sum = w_gyro + w_opt + 1e-6
        fused = (
            gyro_motion * (w_gyro / w_sum) +
            opt_motion * (w_opt / w_sum)
        )
        # Clamp to cinematic-safe bounds
        fused[0] = _np.clip(fused[0], -self.max_translation_px, self.max_translation_px)
        fused[1] = _np.clip(fused[1], -self.max_translation_px, self.max_translation_px)
        fused[2] = _np.clip(fused[2], -self.max_rotation_deg, self.max_rotation_deg)
        # Temporal inertia
        if self._prev_motion is not None:
            fused = (
                self._prev_motion * self.temporal_inertia +
                fused * (1.0 - self.temporal_inertia)
            )
        confidence = _np.clip((gyro_conf + opt_conf) * 0.5, 0.0, 1.0)
        self._prev_motion = fused
        self._prev_confidence = confidence
        return fused, confidence
# ==============================================================================
# END OF CHUNK 81 X 04
