def _soft_rolloff(x, knee, strength):
   """
   Film-like roll-off curve: linear below knee, smooth compression above.
   """
   t = np.clip((x - knee) / max(1.0 - knee, 1e-6), 0.0, 1.0)
   compressed = knee + (1.0 - knee) * (1.0 - np.exp(-strength * t))
   return np.where(x <= knee, x, compressed)
