       img = img_display_rgb.astype(np.float32)
       # --------------------------------------------------------------
       # Apply channel-specific spectral roll-off
       # --------------------------------------------------------------
       r = _soft_rolloff(img[..., 0], self.knee_r, self.strength_r)
       g = _soft_rolloff(img[..., 1], self.knee_g, self.strength_g)
       b = _soft_rolloff(img[..., 2], self.knee_b, self.strength_b)
       img = np.stack([r, g, b], axis=-1)
       return np.clip(img, 0.0, 1.0)
