       # --------------------------------------------------------------
       luma = np.mean(img, axis=-1)
       chroma = img - luma[..., None]
       # --------------------------------------------------------------
       # 2. Secondary dye temporal memory
       # --------------------------------------------------------------
       mean_chroma = np.mean(chroma, axis=(0, 1))
       if self._dye_mem is None:
           self._dye_mem = mean_chroma
       else:
           delta = mean_chroma - self._dye_mem
           delta = np.clip(delta,
        -self.max_delta,
        self.max_delta)
           self._dye_mem = (
               self.dye_alpha * self._dye_mem +
               (1.0 - self.dye_alpha) *
               (self._dye_mem + delta)
           )
       # --------------------------------------------------------------
       # 3. Inject secondary dye contribution
       # --------------------------------------------------------------
       dye_contribution = self._dye_mem * self.dye_strength
       img[..., 0] += dye_contribution[0]
       img[..., 1] += dye_contribution[1]
       img[..., 2] += dye_contribution[2]
