        if self._retained_chroma is None:
            self._retained_chroma = frame_chroma
        else:
            self._retained_chroma = (
                self.retention_alpha * self._retained_chroma +
                (1.0 - self.retention_alpha) * frame_chroma
            )
        # --------------------------------------------------------------
        # 3. Inject retained chroma
        # --------------------------------------------------------------
        chroma += self._retained_chroma * self.retention_strength
        # --------------------------------------------------------------
