        # 1. Compute luminance
        # --------------------------------------------------------------
        luma = np.mean(img, axis=-1)
        # --------------------------------------------------------------
        # 2. Extract chroma
        # --------------------------------------------------------------
        chroma = img - luma[..., None]
        # --------------------------------------------------------------
        # 3. Compute shadow reinforcement mask
