        # Optional mid-gray normalization
        # --------------------------------------------------------------
        if self.preserve_midgray:
            img = self._normalize_midgray(img)
        # --------------------------------------------------------------
        # Numerical cleanup
        # --------------------------------------------------------------
        img[np.abs(img) < self.epsilon] = 0.0
        # --------------------------------------------------------------
        # Final clamp
        # --------------------------------------------------------------
        img = np.clip(img, self.clamp_min, self.clamp_max)
        return img
