import numpy as np
class BackwardCompatibilityShim:
    """
    Adapts legacy metadata and parameter ranges to current expectations.
    """
    def __init__(self):
        # Version-specific normalization rules
        self._version_rules = {
            "v1": {
                "sceneMean_scale": 1.2,
                "peak_bias": 0.9
            },
            "v2": {
                "sceneMean_scale": 1.0,
                "peak_bias": 1.0
            }
        }
    # ------------------------------------------------------------------
    def adapt(self, metadata: dict, source_version: str):
        if metadata is None:
            return None
        rules = self._version_rules.get(source_version)
        if rules is None:
            return metadata
        adapted = dict(metadata)
        # Normalize scene mean luminance
        if "sceneMean" in adapted:
            adapted["sceneMean"] = (
                adapted["sceneMean"] * rules["sceneMean_scale"]
            )
        # Bias peak luminance for legacy encodes
        if "maxCLL" in adapted:
            adapted["maxCLL"] = (
                adapted["maxCLL"] * rules["peak_bias"]
            )
        return adapted
