import numpy as np
class DistributionIntegrityCheck:
    """
    Validates assembled delivery package integrity.
    """
    def __init__(self, require_checksum=True, epsilon=1e-6):
        """
        require_checksum:
            Enforce checksum presence and validity
        epsilon:
            Numerical tolerance
        """
        self.require_checksum = bool(require_checksum)
        self.epsilon = float(epsilon)
    # ------------------------------------------------------------------
    def _validate_checksum(self, frame, checksum):
        computed = int(np.sum(np.abs(frame)) * 1e6) & 0xFFFFFFFF
        return computed == checksum
    # ------------------------------------------------------------------
    def validate(self, package: dict):
        if package is None:
            return False
        frame = package.get("frame")
        if frame is None:
            return False
        if not np.isfinite(frame).all():
            return False
        if self.require_checksum:
            checksum = package.get("checksum")
            if checksum is None:
                return False
            if not self._validate_checksum(frame, checksum):
                return False
        return True
