# ==============================================================================
# SUBCHUNK 84 A 03 — DISPLAY-REFERRED BLACK MAPPING
# ==============================================================================
# Purpose:
#   Establish a perceptually correct mapping between scene-referred blacks
#   and display-referred black levels, accounting for display minimum luminance,
#   surround conditions, and ACES-compliant viewing assumptions.
#
# Cinematic relevance:
#   - Prevents crushed blacks on HDR / SDR displays
#   - Preserves shadow detail without lifting true black
#   - Matches high-end cinema projector behavior
#
# Runs AFTER:
#   - 84 A 02 (Backward Compatibility Shim)
# ==============================================================================
import numpy as np
def map_display_black_level(
    linear_rgb: np.ndarray,
    display_min_nits: float,
    reference_white_nits: float,
    surround_gamma: float = 1.0
) -> np.ndarray:
    """
    Maps scene-referred linear RGB values into a display-referred black floor.
    Parameters:
        linear_rgb:
            Scene-linear RGB (ACEScg / linear-light)
        display_min_nits:
            Physical minimum luminance of the target display
        reference_white_nits:
            Reference diffuse white luminance
        surround_gamma:
            Perceptual surround compensation factor
    Returns:
        Black-mapped linear RGB suitable for display encoding
    """
    # Safety clamps
    display_min_nits = max(display_min_nits, 0.0)
    reference_white_nits = max(reference_white_nits, 1e-6)
    # Normalize display black relative to reference white
    black_norm = display_min_nits / reference_white_nits
    # Prevent pathological cases
    black_norm = np.clip(black_norm, 0.0, 0.05)
    # Apply surround compensation (cinema vs dim surround)
    if surround_gamma != 1.0:
        black_norm = black_norm ** surround_gamma
    # Compute soft black lift curve
    # This preserves near-black detail without raising true zero
    epsilon = 1e-6
    lifted = np.maximum(linear_rgb, 0.0)
    # Smooth transition using a low-order power curve
    shadow_mask = lifted < black_norm
    if np.any(shadow_mask):
        t = lifted[shadow_mask] / (black_norm + epsilon)
        lifted[shadow_mask] = black_norm * (t ** 1.8)
    return lifted
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_display_black_mapping(
    linear_rgb: np.ndarray,
    display_profile: dict
) -> np.ndarray:
    """
    Wrapper applying display-referred black mapping using a display profile.
    """
    return map_display_black_level(
        linear_rgb=linear_rgb,
        display_min_nits=display_profile.get("min_nits", 0.0),
        reference_white_nits=display_profile.get("white_nits", 100.0),
        surround_gamma=display_profile.get("surround_gamma", 1.0)
    )
# ==============================================================================
# END OF SUBCHUNK 84 A 03 — DISPLAY-REFERRED BLACK MAPPING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 A 04 — SCENE-REFERRED BLACK PRESERVATION
# ==============================================================================
# Purpose:
#   Preserve true scene-referred blacks through the display mapping pipeline
#   without introducing artificial lift, while protecting low-frequency
#   shadow texture and avoiding banding or posterization.
#
# Cinematic relevance:
#   - Maintains “true black” intent from capture through grading
#   - Prevents unintended shadow haze
#   - Matches high-end DI pipelines (ARRI/ACES)
#
# Runs AFTER:
#   - 84 A 03 (Display-Referred Black Mapping)
# ==============================================================================
import numpy as np
def preserve_scene_black(
    linear_rgb: np.ndarray,
    scene_black_threshold: float = 1e-4,
    preservation_strength: float = 0.85,
    temporal_hint: np.ndarray | None = None
) -> np.ndarray:
    """
    Preserves scene-referred black regions while allowing perceptual shadow detail.
    Parameters:
        linear_rgb:
            Scene-linear RGB after display black mapping
        scene_black_threshold:
            Linear-light threshold considered as true scene black
        preservation_strength:
            Weight of preservation vs perceptual lift (0–1)
        temporal_hint:
            Optional temporal luminance reference for stability
    Returns:
        Linear RGB with preserved scene blacks
    """
    preservation_strength = np.clip(preservation_strength, 0.0, 1.0)
    scene_black_threshold = max(scene_black_threshold, 0.0)
    rgb = np.maximum(linear_rgb, 0.0)
    # Luminance proxy (ACEScg coefficients)
    luma = (
        0.272229 * rgb[..., 0] +
        0.674082 * rgb[..., 1] +
        0.053689 * rgb[..., 2]
    )
    # Optional temporal stabilization to prevent flicker in near-black
    if temporal_hint is not None:
        temporal_luma = np.clip(temporal_hint, 0.0, None)
        luma = 0.7 * luma + 0.3 * temporal_luma
    # Identify true scene-black region
    black_mask = luma <= scene_black_threshold
    if not np.any(black_mask):
        return rgb
    # Compute gentle preservation curve
    eps = 1e-6
    t = luma[black_mask] / (scene_black_threshold + eps)
    # Smoothstep-style curve for natural roll-in
    preserved_factor = (
        t * t * (3.0 - 2.0 * t)
    )
    preserved_factor = (
        preservation_strength * preserved_factor +
        (1.0 - preservation_strength)
    )
    # Apply per-channel preservation
    rgb_preserved = rgb.copy()
    rgb_preserved[black_mask] = (
        rgb[black_mask] * preserved_factor[..., None]
    )
    return rgb_preserved
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_scene_black_preservation(
    linear_rgb: np.ndarray,
    config: dict,
    temporal_hint: np.ndarray | None = None
) -> np.ndarray:
    """
    Applies scene-black preservation using configuration parameters.
    """
    return preserve_scene_black(
        linear_rgb=linear_rgb,
        scene_black_threshold=config.get("scene_black_threshold", 1e-4),
        preservation_strength=config.get("preserve_strength", 0.85),
        temporal_hint=temporal_hint
    )
# ==============================================================================
# END OF SUBCHUNK 84 A 04 — SCENE-REFERRED BLACK PRESERVATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 A 05 — BLACK FLOOR VS NOISE ARBITRATION
# ==============================================================================
# Purpose:
#   Resolve conflicts between preserving deep blacks and retaining perceptually
#   meaningful shadow noise/texture. Prevents over-denoised “plastic” blacks while
#   avoiding noisy lifted shadows.
#
# Cinematic relevance:
#   - Maintains organic shadow texture (film-like)
#   - Avoids crushed blacks or noisy haze
#   - Critical for HDR and low-light drone footage
#
# Runs AFTER:
#   - 84 A 04 (Scene-Referred Black Preservation)
# ==============================================================================
import numpy as np
def arbitrate_black_vs_noise(
    linear_rgb: np.ndarray,
    noise_luma: np.ndarray,
    black_floor: float = 1e-4,
    noise_visibility_floor: float = 2e-4,
    arbitration_strength: float = 0.9
) -> np.ndarray:
    """
    Balances black preservation against perceptible noise presence.
    Parameters:
        linear_rgb:
            Linear RGB after black preservation
        noise_luma:
            Estimated noise luminance (same spatial shape)
        black_floor:
            Scene black threshold
        noise_visibility_floor:
            Minimum noise level considered perceptible
        arbitration_strength:
            Strength of arbitration (0–1)
    Returns:
        Linear RGB with balanced black/noise behavior
    """
    arbitration_strength = np.clip(arbitration_strength, 0.0, 1.0)
    rgb = np.maximum(linear_rgb, 0.0)
    # Luminance proxy
    luma = (
        0.272229 * rgb[..., 0] +
        0.674082 * rgb[..., 1] +
        0.053689 * rgb[..., 2]
    )
    noise_luma = np.maximum(noise_luma, 0.0)
    # Identify arbitration zone: near-black but with visible noise
    near_black = luma <= (black_floor * 2.5)
    noise_visible = noise_luma >= noise_visibility_floor
    mask = near_black & noise_visible
    if not np.any(mask):
        return rgb
    # Arbitration factor: preserve some noise texture without lifting base black
    eps = 1e-6
    noise_ratio = noise_luma[mask] / (luma[mask] + eps)
    noise_ratio = np.clip(noise_ratio, 0.0, 1.0)
    # Smooth weighting curve
    w = noise_ratio ** 0.6
    w = arbitration_strength * w
    # Apply selective lift proportional to noise presence
    rgb_adj = rgb.copy()
    rgb_adj[mask] = rgb[mask] * (1.0 + w[..., None] * 0.25)
    # Hard clamp to prevent black floor violation
    rgb_adj = np.maximum(rgb_adj, black_floor)
    return rgb_adj
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_black_noise_arbitration(
    linear_rgb: np.ndarray,
    noise_metrics: dict,
    config: dict
) -> np.ndarray:
    """
    Applies black-vs-noise arbitration using estimated noise metrics.
    """
    return arbitrate_black_vs_noise(
        linear_rgb=linear_rgb,
        noise_luma=noise_metrics.get("noise_luma"),
        black_floor=config.get("black_floor", 1e-4),
        noise_visibility_floor=config.get("noise_visibility_floor", 2e-4),
        arbitration_strength=config.get("arbitration_strength", 0.9)
    )
# ==============================================================================
# END OF SUBCHUNK 84 A 05 — BLACK FLOOR VS NOISE ARBITRATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 A 06 — BLACK FLOOR STABILITY OVER TIME
# ==============================================================================
# Purpose:
#   Enforce temporal stability of the black floor to prevent flicker, pumping,
#   or crawling artifacts in near-black regions across consecutive frames.
#
# Cinematic relevance:
#   - Eliminates shadow flicker during slow exposure changes
#   - Preserves film-like temporal coherence
#   - Essential for stabilized drone footage and HDR sequences
#
# Runs AFTER:
#   - 84 A 05 (Black Floor vs Noise Arbitration)
# ==============================================================================
import numpy as np
def stabilize_black_floor_temporal(
    linear_rgb: np.ndarray,
    prev_black_floor_map: np.ndarray | None,
    stability_strength: float = 0.92,
    max_delta: float = 5e-5
) -> tuple[np.ndarray, np.ndarray]:
    """
    Applies temporal smoothing to black floor behavior.
    Parameters:
        linear_rgb:
            Current-frame linear RGB
        prev_black_floor_map:
            Previous frame's black floor luminance map
        stability_strength:
            Temporal inertia (0–1), higher = more stable
        max_delta:
            Maximum allowed frame-to-frame black floor change
    Returns:
        Tuple of:
          - stabilized RGB
          - updated black floor map for next frame
    """
    stability_strength = np.clip(stability_strength, 0.0, 1.0)
    rgb = np.maximum(linear_rgb, 0.0)
    # Luminance proxy
    luma = (
        0.272229 * rgb[..., 0] +
        0.674082 * rgb[..., 1] +
        0.053689 * rgb[..., 2]
    )
    # Estimate current black floor map as low-percentile luminance
    current_black_map = np.minimum(luma, np.percentile(luma, 5))
    if prev_black_floor_map is None:
        return rgb, current_black_map
    # Temporal blend
    blended_black = (
        stability_strength * prev_black_floor_map +
        (1.0 - stability_strength) * current_black_map
    )
    # Clamp frame-to-frame variation
    delta = blended_black - prev_black_floor_map
    delta = np.clip(delta, -max_delta, max_delta)
    stabilized_black = prev_black_floor_map + delta
    # Apply correction only where luma is near black
    mask = luma <= (stabilized_black * 2.0)
    rgb_stable = rgb.copy()
    rgb_stable[mask] = np.maximum(
        rgb[mask],
        stabilized_black[mask][..., None]
    )
    return rgb_stable, stabilized_black
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_temporal_black_stability(
    linear_rgb: np.ndarray,
    state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies temporal black floor stabilization and updates state.
    """
    stabilized, black_map = stabilize_black_floor_temporal(
        linear_rgb=linear_rgb,
        prev_black_floor_map=state.get("prev_black_floor_map"),
        stability_strength=config.get("stability_strength", 0.92),
        max_delta=config.get("max_delta", 5e-5)
    )
    state["prev_black_floor_map"] = black_map
    return stabilized
# ==============================================================================
# END OF SUBCHUNK 84 A 06 — BLACK FLOOR STABILITY OVER TIME
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 A 07 — HDR BLACK FLOOR ADAPTATION
# ==============================================================================
# Purpose:
#   Adapt the black floor dynamically for HDR mastering targets (PQ / HLG)
#   while preserving scene-referred intent and avoiding HDR shadow washout.
#
# Cinematic relevance:
#   - Prevents milky blacks on HDR displays
#   - Maintains deep contrast without clipping
#   - Matches professional HDR grading behavior (Dolby Vision / HDR10)
#
# Runs AFTER:
#   - 84 A 06 (Black Floor Stability Over Time)
# ==============================================================================
import numpy as np
def adapt_black_floor_hdr(
    linear_rgb: np.ndarray,
    mastering_nits: float,
    content_peak_nits: float,
    hdr_mode: str = "PQ",
    adaptation_strength: float = 0.85
) -> np.ndarray:
    """
    Adapts black floor behavior for HDR mastering environments.
    Parameters:
        linear_rgb:
            Linear RGB after temporal black stabilization
        mastering_nits:
            Target mastering display peak luminance
        content_peak_nits:
            Estimated content peak luminance
        hdr_mode:
            'PQ' or 'HLG'
        adaptation_strength:
            Strength of HDR black adaptation (0–1)
    Returns:
        Linear RGB adapted for HDR black behavior
    """
    adaptation_strength = np.clip(adaptation_strength, 0.0, 1.0)
    mastering_nits = max(mastering_nits, 100.0)
    content_peak_nits = max(content_peak_nits, 1.0)
    rgb = np.maximum(linear_rgb, 0.0)
    # Luminance proxy (ACEScg)
    luma = (
        0.272229 * rgb[..., 0] +
        0.674082 * rgb[..., 1] +
        0.053689 * rgb[..., 2]
    )
    # Normalize luminance to mastering space
    peak_ratio = np.clip(content_peak_nits / mastering_nits, 0.1, 1.0)
    # HDR mode shaping
    if hdr_mode.upper() == "PQ":
        # PQ has deeper blacks; protect near-zero aggressively
        black_scale = (1.0 - peak_ratio) ** 1.4
    else:
        # HLG has a softer toe
        black_scale = (1.0 - peak_ratio) ** 0.9
    black_scale = adaptation_strength * black_scale
    # Identify near-black region
    near_black = luma <= np.percentile(luma, 6)
    if not np.any(near_black):
        return rgb
    # Apply HDR-aware compression toward true black
    eps = 1e-6
    t = luma[near_black] / (np.max(luma[near_black]) + eps)
    compression = (t ** (1.0 + black_scale))
    rgb_hdr = rgb.copy()
    rgb_hdr[near_black] = (
        rgb[near_black] * compression[..., None]
    )
    return rgb_hdr
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_hdr_black_adaptation(
    linear_rgb: np.ndarray,
    hdr_metadata: dict,
    config: dict
) -> np.ndarray:
    """
    Applies HDR black floor adaptation using mastering metadata.
    """
    return adapt_black_floor_hdr(
        linear_rgb=linear_rgb,
        mastering_nits=hdr_metadata.get("mastering_nits", 1000.0),
        content_peak_nits=hdr_metadata.get("content_peak_nits", 400.0),
        hdr_mode=hdr_metadata.get("mode", "PQ"),
        adaptation_strength=config.get("adaptation_strength", 0.85)
    )
# ==============================================================================
# END OF SUBCHUNK 84 A 07 — HDR BLACK FLOOR ADAPTATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 A 08 — BLACK FLOOR SAFETY CLAMP
# ==============================================================================
# Purpose:
#   Enforce absolute safety bounds on black floor handling to prevent negative
#   values, NaNs, or underflow artifacts during extreme grading, HDR mapping,
#   or temporal accumulation.
#
# Cinematic relevance:
#   - Guarantees stable blacks across all delivery paths
#   - Prevents banding, NaN propagation, and display instability
#   - Required for long-form renders and cloud batch processing
#
# Runs AFTER:
#   - 84 A 07 (HDR Black Floor Adaptation)
# ==============================================================================
import numpy as np
def clamp_black_floor(
    linear_rgb: np.ndarray,
    min_black: float = 0.0,
    max_black: float = 2e-3,
    nan_replacement: float = 0.0
) -> np.ndarray:
    """
    Applies hard safety clamps to black floor behavior.
    Parameters:
        linear_rgb:
            Linear RGB after all black adaptations
        min_black:
            Absolute minimum allowed black value
        max_black:
            Absolute maximum allowed near-black lift
        nan_replacement:
            Replacement value for NaN or Inf
    Returns:
        Clamped, numerically safe linear RGB
    """
    rgb = linear_rgb.copy()
    # Replace NaN / Inf early
    invalid_mask = ~np.isfinite(rgb)
    if np.any(invalid_mask):
        rgb[invalid_mask] = nan_replacement
    # Hard clamp to legal bounds
    rgb = np.clip(rgb, min_black, max_black)
    return rgb
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_black_floor_safety(
    linear_rgb: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies final black floor safety constraints.
    """
    return clamp_black_floor(
        linear_rgb=linear_rgb,
        min_black=config.get("min_black", 0.0),
        max_black=config.get("max_black", 2e-3),
        nan_replacement=config.get("nan_replacement", 0.0)
    )
# ==============================================================================
# END OF SUBCHUNK 84 A 08 — BLACK FLOOR SAFETY CLAMP
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 B 01 — SHADOW NOISE PERCEPTUAL WEIGHTING
# ==============================================================================
# Purpose:
#   Weight shadow-region noise according to human visual sensitivity so that
#   noise is neither over-suppressed (plastic blacks) nor over-exposed (grainy haze).
#
# Cinematic relevance:
#   - Film-like shadow texture retention
#   - Prevents low-light drone footage from looking synthetic
#   - Aligns with perceptual contrast sensitivity in dark surrounds
#
# Runs AFTER:
#   - 84 A 08 (Black Floor Safety Clamp)
# ==============================================================================
import numpy as np
def perceptual_shadow_noise_weight(
    linear_rgb: np.ndarray,
    noise_luma: np.ndarray,
    csf_gamma: float = 0.65,
    shadow_knee: float = 0.02,
    max_weight: float = 1.25
) -> np.ndarray:
    """
    Computes a perceptual weight for shadow noise based on luminance and
    contrast sensitivity characteristics.
    Parameters:
        linear_rgb:
            Linear RGB (post black-floor handling)
        noise_luma:
            Estimated noise luminance map
        csf_gamma:
            Contrast sensitivity exponent (lower = more sensitive in shadows)
        shadow_knee:
            Luminance knee defining deep-shadow region
        max_weight:
            Upper bound on noise weighting
    Returns:
        Per-pixel perceptual noise weight (scalar map)
    """
    rgb = np.maximum(linear_rgb, 0.0)
    # Luminance proxy (ACEScg)
    luma = (
        0.272229 * rgb[..., 0] +
        0.674082 * rgb[..., 1] +
        0.053689 * rgb[..., 2]
    )
    noise_luma = np.maximum(noise_luma, 0.0)
    # Normalize luminance into [0,1] shadow domain
    eps = 1e-6
    shadow_norm = np.clip(luma / (shadow_knee + eps), 0.0, 1.0)
    # Contrast sensitivity weighting (more sensitive near black)
    cs_weight = (1.0 - shadow_norm) ** csf_gamma
    # Noise visibility modulation
    noise_norm = noise_luma / (luma + eps)
    noise_norm = np.clip(noise_norm, 0.0, 1.0)
    weight = cs_weight * noise_norm
    weight = np.clip(weight, 0.0, max_weight)
    return weight
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_shadow_noise_weighting(
    linear_rgb: np.ndarray,
    noise_metrics: dict,
    config: dict
) -> np.ndarray:
    """
    Applies perceptual weighting to shadow noise by modulating RGB values
    in near-black regions only.
    """
    weight = perceptual_shadow_noise_weight(
        linear_rgb=linear_rgb,
        noise_luma=noise_metrics.get("noise_luma"),
        csf_gamma=config.get("csf_gamma", 0.65),
        shadow_knee=config.get("shadow_knee", 0.02),
        max_weight=config.get("max_weight", 1.25)
    )
    # Apply selectively in shadows
    rgb = linear_rgb.copy()
    rgb *= (1.0 + weight[..., None] * 0.15)
    return rgb
# ==============================================================================
# END OF SUBCHUNK 84 B 01 — SHADOW NOISE PERCEPTUAL WEIGHTING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 B 02 — NOISE FREQUENCY SEPARATION
# ==============================================================================
# Purpose:
#   Separate noise into low-, mid-, and high-frequency components so that
#   each band can be treated perceptually correctly (film-like grain texture
#   without smearing structure or edges).
#
# Cinematic relevance:
#   - Preserves fine film grain while protecting edges and detail
#   - Avoids waxy denoising artifacts
#   - Matches professional DI frequency-domain noise handling
#
# Runs AFTER:
#   - 84 B 01 (Shadow Noise Perceptual Weighting)
# ==============================================================================
import numpy as np
import cv2
def separate_noise_frequencies(
    linear_rgb: np.ndarray,
    low_sigma: float = 1.5,
    mid_sigma: float = 0.7,
    high_gain: float = 1.0
) -> dict:
    """
    Separates noise into frequency bands using Gaussian pyramids.
    Parameters:
        linear_rgb:
            Linear RGB image (post shadow noise weighting)
        low_sigma:
            Sigma for low-frequency separation (structure)
        mid_sigma:
            Sigma for mid-frequency separation (texture)
        high_gain:
            Gain applied to extracted high-frequency noise
    Returns:
        Dictionary with keys:
            'low_freq', 'mid_freq', 'high_freq'
    """
    rgb = np.maximum(linear_rgb, 0.0)
    # Convert to luminance for frequency analysis
    luma = (
        0.272229 * rgb[..., 0] +
        0.674082 * rgb[..., 1] +
        0.053689 * rgb[..., 2]
    ).astype(np.float32)
    # Low-frequency component (broad structure)
    low_freq = cv2.GaussianBlur(
        luma,
        ksize=(0, 0),
        sigmaX=low_sigma,
        sigmaY=low_sigma
    )
    # Mid-frequency component (texture / film grain body)
    mid_base = cv2.GaussianBlur(
        luma,
        ksize=(0, 0),
        sigmaX=mid_sigma,
        sigmaY=mid_sigma
    )
    mid_freq = mid_base - low_freq
    # High-frequency component (fine grain + sensor noise)
    high_freq = (luma - mid_base) * high_gain
    return {
        "low_freq": low_freq,
        "mid_freq": mid_freq,
        "high_freq": high_freq
    }
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_noise_frequency_separation(
    linear_rgb: np.ndarray,
    config: dict
) -> dict:
    """
    Applies frequency separation to noise using configuration parameters.
    """
    return separate_noise_frequencies(
        linear_rgb=linear_rgb,
        low_sigma=config.get("low_sigma", 1.5),
        mid_sigma=config.get("mid_sigma", 0.7),
        high_gain=config.get("high_gain", 1.0)
    )
# ==============================================================================
# END OF SUBCHUNK 84 B 02 — NOISE FREQUENCY SEPARATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 B 03 — NOISE TEMPORAL COHERENCE
# ==============================================================================
# Purpose:
#   Enforce temporal coherence of noise/grain so that it evolves naturally
#   across frames (film-like), avoiding shimmer, crawl, or frozen noise.
#
# Cinematic relevance:
#   - Prevents temporal “boiling” in shadows
#   - Matches analog film grain evolution
#   - Essential for stabilized aerial footage and long takes
#
# Runs AFTER:
#   - 84 B 02 (Noise Frequency Separation)
# ==============================================================================
import numpy as np
def enforce_noise_temporal_coherence(
    freq_bands: dict,
    prev_state: dict | None,
    coherence_strength: float = 0.85,
    drift_limit: float = 0.35
) -> tuple[dict, dict]:
    """
    Enforces temporal coherence on noise frequency bands.
    Parameters:
        freq_bands:
            Dictionary containing 'low_freq', 'mid_freq', 'high_freq'
        prev_state:
            Previous frame noise state (or None on first frame)
        coherence_strength:
            Temporal inertia (0–1), higher = more stable noise
        drift_limit:
            Maximum allowed per-frame noise drift
    Returns:
        Tuple of:
            - Updated frequency bands (temporally coherent)
            - Updated state for next frame
    """
    coherence_strength = np.clip(coherence_strength, 0.0, 1.0)
    drift_limit = max(drift_limit, 0.0)
    updated = {}
    state_out = {}
    for key in ("low_freq", "mid_freq", "high_freq"):
        current = freq_bands.get(key)
        if current is None:
            continue
        if prev_state is None or key not in prev_state:
            updated[key] = current
            state_out[key] = current
            continue
        prev = prev_state[key]
        # Temporal blend
        blended = (
            coherence_strength * prev +
            (1.0 - coherence_strength) * current
        )
        # Limit drift to avoid ghosting or lag
        delta = blended - prev
        delta = np.clip(delta, -drift_limit, drift_limit)
        coherent = prev + delta
        updated[key] = coherent
        state_out[key] = coherent
    return updated, state_out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_noise_temporal_coherence(
    freq_bands: dict,
    state: dict,
    config: dict
) -> dict:
    """
    Applies temporal coherence to noise frequency bands and updates state.
    """
    updated, next_state = enforce_noise_temporal_coherence(
        freq_bands=freq_bands,
        prev_state=state.get("noise_state"),
        coherence_strength=config.get("coherence_strength", 0.85),
        drift_limit=config.get("drift_limit", 0.35)
    )
    state["noise_state"] = next_state
    return updated
# ==============================================================================
# END OF SUBCHUNK 84 B 03 — NOISE TEMPORAL COHERENCE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 B 04 — NOISE COLOR DECORRELATION
# ==============================================================================
# Purpose:
#   Reduce unnatural RGB channel correlation in noise so that grain/noise
#   behaves chromatically like film emulsion rather than digital sensor noise.
#
# Cinematic relevance:
#   - Eliminates “color speckle” artifacts
#   - Produces neutral, film-like grain
#   - Preserves chroma integrity in shadows
#
# Runs AFTER:
#   - 84 B 03 (Noise Temporal Coherence)
# ==============================================================================
import numpy as np
def decorrelate_noise_color(
    linear_rgb: np.ndarray,
    noise_luma: np.ndarray,
    decorrelation_strength: float = 0.75,
    chroma_bias: float = 0.15
) -> np.ndarray:
    """
    Applies chromatic decorrelation to noise while preserving luminance structure.
    Parameters:
        linear_rgb:
            Linear RGB image (post noise temporal coherence)
        noise_luma:
            Estimated noise luminance map
        decorrelation_strength:
            Strength of RGB decorrelation (0–1)
        chroma_bias:
            Residual chroma noise allowance (film-like)
    Returns:
        Linear RGB with decorrelated chromatic noise
    """
    decorrelation_strength = np.clip(decorrelation_strength, 0.0, 1.0)
    chroma_bias = np.clip(chroma_bias, 0.0, 0.5)
    rgb = np.maximum(linear_rgb, 0.0)
    # Compute luminance
    luma = (
        0.272229 * rgb[..., 0] +
        0.674082 * rgb[..., 1] +
        0.053689 * rgb[..., 2]
    )
    # Extract chroma components
    eps = 1e-6
    chroma = rgb / (luma[..., None] + eps)
    # Compute channel-wise noise influence
    noise_norm = np.clip(noise_luma / (luma + eps), 0.0, 1.0)
    # Target chroma moves slightly toward neutral (1,1,1)
    neutral = np.ones_like(chroma)
    blend = (
        decorrelation_strength * noise_norm[..., None]
    )
    chroma_decor = (
        chroma * (1.0 - blend) +
        neutral * blend * (1.0 - chroma_bias)
    )
    # Reconstruct RGB with preserved luminance
    rgb_out = chroma_decor * luma[..., None]
    return rgb_out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_noise_color_decorrelation(
    linear_rgb: np.ndarray,
    noise_metrics: dict,
    config: dict
) -> np.ndarray:
    """
    Applies chromatic decorrelation to noise using configuration parameters.
    """
    return decorrelate_noise_color(
        linear_rgb=linear_rgb,
        noise_luma=noise_metrics.get("noise_luma"),
        decorrelation_strength=config.get("decorrelation_strength", 0.75),
        chroma_bias=config.get("chroma_bias", 0.15)
    )
# ==============================================================================
# END OF SUBCHUNK 84 B 04 — NOISE COLOR DECORRELATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 B 05 — NOISE EXPOSURE INTERACTION
# ==============================================================================
# Purpose:
#   Model how noise visibility and character change with exposure, ISO gain,
#   and scene brightness so that noise behaves consistently across exposure
#   ramps, auto-exposure transitions, and HDR tone operations.
#
# Cinematic relevance:
#   - Prevents noise “popping” during exposure changes
#   - Preserves film-like grain growth with gain
#   - Essential for aerial shots with dynamic lighting
#
# Runs AFTER:
#   - 84 B 04 (Noise Color Decorrelation)
# ==============================================================================
import numpy as np
def modulate_noise_by_exposure(
    linear_rgb: np.ndarray,
    noise_luma: np.ndarray,
    exposure_ev: float,
    iso_gain: float = 1.0,
    mid_gray: float = 0.18,
    growth_gamma: float = 0.85,
    clamp_gain: float = 3.0
) -> np.ndarray:
    """
    Modulates noise contribution based on exposure and ISO gain.
    Parameters:
        linear_rgb:
            Linear RGB after noise color decorrelation
        noise_luma:
            Estimated noise luminance map
        exposure_ev:
            Exposure value offset (stops)
        iso_gain:
            Effective ISO gain multiplier
        mid_gray:
            Scene mid-gray reference
        growth_gamma:
            Controls how quickly noise grows with exposure
        clamp_gain:
            Upper bound on noise amplification
    Returns:
        Linear RGB with exposure-aware noise modulation
    """
    rgb = np.maximum(linear_rgb, 0.0)
    noise_luma = np.maximum(noise_luma, 0.0)
    # Luminance proxy
    luma = (
        0.272229 * rgb[..., 0] +
        0.674082 * rgb[..., 1] +
        0.053689 * rgb[..., 2]
    )
    # Exposure scaling (stops to linear)
    exposure_scale = 2.0 ** exposure_ev
    # Normalize luminance around mid-gray
    eps = 1e-6
    luma_norm = luma / (mid_gray + eps)
    # Noise growth model: increases in shadows and with gain
    gain = np.clip(iso_gain * exposure_scale, 0.0, clamp_gain)
    growth = (1.0 / (luma_norm + eps)) ** growth_gamma
    growth = np.clip(growth, 0.0, clamp_gain)
    # Final noise modulation factor
    noise_factor = gain * growth
    # Apply noise modulation proportionally
    rgb_out = rgb.copy()
    rgb_out += (noise_luma * noise_factor)[..., None] * 0.15
    return np.maximum(rgb_out, 0.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_noise_exposure_interaction(
    linear_rgb: np.ndarray,
    noise_metrics: dict,
    exposure_metadata: dict,
    config: dict
) -> np.ndarray:
    """
    Applies exposure-aware noise modulation using exposure and ISO metadata.
    """
    return modulate_noise_by_exposure(
        linear_rgb=linear_rgb,
        noise_luma=noise_metrics.get("noise_luma"),
        exposure_ev=exposure_metadata.get("exposure_ev", 0.0),
        iso_gain=exposure_metadata.get("iso_gain", 1.0),
        mid_gray=config.get("mid_gray", 0.18),
        growth_gamma=config.get("growth_gamma", 0.85),
        clamp_gain=config.get("clamp_gain", 3.0)
    )
# ==============================================================================
# END OF SUBCHUNK 84 B 05 — NOISE EXPOSURE INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 B 06 — NOISE RESPONSE STABILITY CLAMP
# ==============================================================================
# Purpose:
#   Enforce bounded, stable noise behavior under extreme grading, exposure ramps,
#   and temporal accumulation. Prevents runaway amplification, ringing, or
#   oscillation that becomes perceptible in shadows.
#
# Cinematic relevance:
#   - Prevents shadow “boiling” and pulsation
#   - Guarantees consistency across long takes
#   - Required for cloud batch renders and HDR pipelines
#
# Runs AFTER:
#   - 84 B 05 (Noise Exposure Interaction)
# ==============================================================================
import numpy as np
def clamp_noise_response(
    linear_rgb: np.ndarray,
    noise_luma: np.ndarray,
    max_noise_ratio: float = 0.35,
    min_luma_guard: float = 1e-4,
    temporal_guard: float = 0.9
) -> np.ndarray:
    """
    Clamps noise contribution to a stable, perceptually safe envelope.
    Parameters:
        linear_rgb:
            Linear RGB after exposure-aware noise modulation
        noise_luma:
            Estimated noise luminance map
        max_noise_ratio:
            Maximum allowed noise-to-signal ratio
        min_luma_guard:
            Minimum luminance guard to avoid division instability
        temporal_guard:
            Soft temporal damping factor (0–1)
    Returns:
        Linear RGB with clamped, stable noise response
    """
    rgb = np.maximum(linear_rgb, 0.0)
    noise_luma = np.maximum(noise_luma, 0.0)
    # Luminance proxy
    luma = (
        0.272229 * rgb[..., 0] +
        0.674082 * rgb[..., 1] +
        0.053689 * rgb[..., 2]
    )
    eps = 1e-6
    safe_luma = np.maximum(luma, min_luma_guard)
    # Compute noise-to-signal ratio
    ratio = noise_luma / (safe_luma + eps)
    # Soft clamp using smooth knee
    excess = np.maximum(ratio - max_noise_ratio, 0.0)
    knee = excess / (excess + max_noise_ratio + eps)
    # Apply damping
    damping = 1.0 - temporal_guard * knee
    damping = np.clip(damping, 0.0, 1.0)
    rgb_out = rgb.copy()
    rgb_out *= damping[..., None]
    return np.maximum(rgb_out, 0.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_noise_response_clamp(
    linear_rgb: np.ndarray,
    noise_metrics: dict,
    config: dict
) -> np.ndarray:
    """
    Applies final stability clamp to noise response.
    """
    return clamp_noise_response(
        linear_rgb=linear_rgb,
        noise_luma=noise_metrics.get("noise_luma"),
        max_noise_ratio=config.get("max_noise_ratio", 0.35),
        min_luma_guard=config.get("min_luma_guard", 1e-4),
        temporal_guard=config.get("temporal_guard", 0.9)
    )
# ==============================================================================
# END OF SUBCHUNK 84 B 06 — NOISE RESPONSE STABILITY CLAMP
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 C 01 — PERCEPTUAL GRAIN REINTEGRATION
# ==============================================================================
# Purpose:
#   Reintegrate perceptually-shaped grain back into the image after noise
#   conditioning, ensuring film-like texture without masking detail or edges.
#
# Cinematic relevance:
#   - Restores organic texture after noise control
#   - Prevents “over-clean” digital appearance
#   - Matches analog film grain perception
#
# Runs AFTER:
#   - 84 B 06 (Noise Response Stability Clamp)
# ==============================================================================
import numpy as np
def reintegrate_perceptual_grain(
    linear_rgb: np.ndarray,
    grain_bands: dict,
    grain_strength: float = 0.8,
    edge_protect: float = 0.65
) -> np.ndarray:
    """
    Reintegrates perceptually weighted grain into linear RGB.
    Parameters:
        linear_rgb:
            Linear RGB after noise stabilization
        grain_bands:
            Dictionary containing grain frequency bands
        grain_strength:
            Global grain reintegration strength (0–1)
        edge_protect:
            Edge protection factor (0–1)
    Returns:
        Linear RGB with film-like grain reintegrated
    """
    grain_strength = np.clip(grain_strength, 0.0, 1.0)
    edge_protect = np.clip(edge_protect, 0.0, 1.0)
    rgb = np.maximum(linear_rgb, 0.0)
    # Luminance proxy
    luma = (
        0.272229 * rgb[..., 0] +
        0.674082 * rgb[..., 1] +
        0.053689 * rgb[..., 2]
    )
    # Simple edge estimate via luminance gradient
    gy, gx = np.gradient(luma)
    edge_mag = np.sqrt(gx * gx + gy * gy)
    edge_mag = edge_mag / (np.max(edge_mag) + 1e-6)
    # Combine grain bands
    grain = (
        grain_bands.get("mid_freq", 0.0) * 0.6 +
        grain_bands.get("high_freq", 0.0) * 0.4
    )
    # Suppress grain near strong edges
    edge_mask = 1.0 - edge_protect * edge_mag
    edge_mask = np.clip(edge_mask, 0.0, 1.0)
    grain_mod = grain * edge_mask * grain_strength
    rgb_out = rgb + grain_mod[..., None]
    return np.maximum(rgb_out, 0.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_grain_reintegration(
    linear_rgb: np.ndarray,
    grain_bands: dict,
    config: dict
) -> np.ndarray:
    """
    Applies perceptual grain reintegration using configuration parameters.
    """
    return reintegrate_perceptual_grain(
        linear_rgb=linear_rgb,
        grain_bands=grain_bands,
        grain_strength=config.get("grain_strength", 0.8),
        edge_protect=config.get("edge_protect", 0.65)
    )
# ==============================================================================
# END OF SUBCHUNK 84 C 01 — PERCEPTUAL GRAIN REINTEGRATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 C 02 — GRAIN ENERGY CONSERVATION
# ==============================================================================
# Purpose:
#   Ensure that reintegrated grain does NOT change perceived exposure,
#   contrast, or scene energy. Grain must redistribute energy, not add it.
#
# Cinematic relevance:
#   - Prevents exposure drift across grain strength changes
#   - Maintains ACES energy consistency
#   - Required for long sequences and intercut shots
#
# Runs AFTER:
#   - 84 C 01 (Perceptual Grain Reintegration)
# ==============================================================================
import numpy as np
def conserve_grain_energy(
    linear_rgb: np.ndarray,
    reference_rgb: np.ndarray,
    preserve_luma: bool = True,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Rebalances grain so that overall scene energy is conserved.
    Parameters:
        linear_rgb:
            Linear RGB after grain reintegration
        reference_rgb:
            Linear RGB before grain reintegration
        preserve_luma:
            Preserve luminance energy instead of RGB sum
        eps:
            Numerical stability epsilon
    Returns:
        Energy-conserved linear RGB
    """
    rgb = np.maximum(linear_rgb, 0.0)
    ref = np.maximum(reference_rgb, 0.0)
    if preserve_luma:
        # Compute luminance
        luma = (
            0.272229 * rgb[..., 0] +
            0.674082 * rgb[..., 1] +
            0.053689 * rgb[..., 2]
        )
        luma_ref = (
            0.272229 * ref[..., 0] +
            0.674082 * ref[..., 1] +
            0.053689 * ref[..., 2]
        )
        scale = luma_ref / (luma + eps)
    else:
        energy = np.sum(rgb, axis=-1)
        energy_ref = np.sum(ref, axis=-1)
        scale = energy_ref / (energy + eps)
    scale = np.clip(scale, 0.5, 2.0)
    rgb_out = rgb * scale[..., None]
    return np.maximum(rgb_out, 0.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_grain_energy_conservation(
    linear_rgb: np.ndarray,
    pre_grain_rgb: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies grain energy conservation.
    """
    return conserve_grain_energy(
        linear_rgb=linear_rgb,
        reference_rgb=pre_grain_rgb,
        preserve_luma=config.get("preserve_luma", True),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 C 02 — GRAIN ENERGY CONSERVATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 C 03 — GRAIN CHROMATIC BALANCE
# ==============================================================================
# Purpose:
#   Maintain perceptually neutral grain chroma so grain does not bias color
#   reproduction, skin tones, or ACES chromatic integrity.
#
# Cinematic relevance:
#   - Prevents color shifts caused by grain
#   - Preserves skin tone neutrality
#   - Required for high-end grading and intercut consistency
#
# Runs AFTER:
#   - 84 C 02 (Grain Energy Conservation)
# ==============================================================================
import numpy as np
def balance_grain_chroma(
    linear_rgb: np.ndarray,
    grain_rgb: np.ndarray,
    neutral_axis: np.ndarray = np.array([1.0, 1.0, 1.0]),
    chroma_suppression: float = 0.7,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Suppresses chromatic bias in grain while preserving luminance texture.
    Parameters:
        linear_rgb:
            Linear RGB with grain applied
        grain_rgb:
            RGB grain contribution (same shape as linear_rgb)
        neutral_axis:
            Neutral chroma axis (typically [1,1,1])
        chroma_suppression:
            Strength of chroma suppression (0–1)
        eps:
            Numerical stability epsilon
    Returns:
        Linear RGB with chromatically balanced grain
    """
    rgb = np.maximum(linear_rgb, 0.0)
    grain = grain_rgb
    # Normalize neutral axis
    n = neutral_axis / (np.linalg.norm(neutral_axis) + eps)
    # Project grain onto neutral axis (luma component)
    grain_luma = np.dot(grain, n)
    grain_luma_rgb = grain_luma[..., None] * n
    # Chromatic component of grain
    grain_chroma = grain - grain_luma_rgb
    # Suppress chromatic grain
    grain_balanced = grain_luma_rgb + grain_chroma * (1.0 - chroma_suppression)
    rgb_out = rgb - grain + grain_balanced
    return np.maximum(rgb_out, 0.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_grain_chromatic_balance(
    linear_rgb: np.ndarray,
    grain_rgb: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies chromatic balancing to grain contribution.
    """
    return balance_grain_chroma(
        linear_rgb=linear_rgb,
        grain_rgb=grain_rgb,
        neutral_axis=config.get("neutral_axis", np.array([1.0, 1.0, 1.0])),
        chroma_suppression=config.get("chroma_suppression", 0.7),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 C 03 — GRAIN CHROMATIC BALANCE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 C 04 — GRAIN TEMPORAL PHASE DRIFT
# ==============================================================================
# Purpose:
#   Introduce controlled temporal phase drift to grain so it evolves naturally
#   over time, avoiding frozen or looping noise patterns while preserving
#   temporal coherence across frames.
#
# Cinematic relevance:
#   - Prevents static or tiled grain artifacts
#   - Mimics photochemical grain evolution frame-to-frame
#   - Critical for long takes, slow motion, and stabilized aerial shots
#
# Runs AFTER:
#   - 84 C 03 (Grain Chromatic Balance)
# ==============================================================================
import numpy as np
def apply_grain_temporal_phase_drift(
    grain_field: np.ndarray,
    frame_index: int,
    drift_rate: float = 0.015,
    phase_jitter: float = 0.002,
    temporal_lock: float = 0.85,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Applies controlled temporal phase drift to grain.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        frame_index:
            Current frame index in sequence
        drift_rate:
            Base phase drift speed (cycles per frame)
        phase_jitter:
            Small stochastic phase offset
        temporal_lock:
            How strongly grain correlates with previous frame (0–1)
        eps:
            Numerical stability epsilon
    Returns:
        Temporally evolved grain field
    """
    grain = grain_field.astype(np.float32, copy=True)
    # Generate deterministic temporal phase
    phase = (frame_index * drift_rate) % 1.0
    # Add subtle stochastic jitter
    jitter = (np.random.rand(*grain.shape[:2]) - 0.5) * phase_jitter
    total_phase = phase + jitter
    # Sinusoidal phase modulation (energy-preserving)
    phase_mod = np.sin(2.0 * np.pi * total_phase)
    if grain.ndim == 3:
        phase_mod = phase_mod[..., None]
    drifted = grain * (1.0 + phase_mod * 0.5)
    # Temporal coherence clamp
    if temporal_lock > 0.0:
        drifted = (
            temporal_lock * grain +
            (1.0 - temporal_lock) * drifted
        )
    # Normalize energy to avoid temporal pumping
    energy_in = np.mean(grain * grain) + eps
    energy_out = np.mean(drifted * drifted) + eps
    drifted *= np.sqrt(energy_in / energy_out)
    return drifted
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_temporal_phase(
    grain_field: np.ndarray,
    frame_metadata: dict,
    config: dict
) -> np.ndarray:
    """
    Applies temporal phase drift to grain using frame metadata.
    """
    return apply_grain_temporal_phase_drift(
        grain_field=grain_field,
        frame_index=frame_metadata.get("frame_index", 0),
        drift_rate=config.get("drift_rate", 0.015),
        phase_jitter=config.get("phase_jitter", 0.002),
        temporal_lock=config.get("temporal_lock", 0.85),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 C 04 — GRAIN TEMPORAL PHASE DRIFT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 C 05 — GRAIN DENSITY VS EXPOSURE COUPLING
# ==============================================================================
# Purpose:
#   Couple grain density to exposure level so darker regions exhibit higher
#   apparent grain density while highlights remain cleaner, matching
#   photochemical film behavior.
#
# Cinematic relevance:
#   - Prevents uniform digital grain appearance
#   - Matches real film’s shadow-heavy grain structure
#   - Crucial for night flights, silhouettes, HDR scenes
#
# Runs AFTER:
#   - 84 C 04 (Grain Temporal Phase Drift)
# ==============================================================================
import numpy as np
def couple_grain_density_to_exposure(
    grain_field: np.ndarray,
    linear_rgb: np.ndarray,
    mid_gray: float = 0.18,
    density_strength: float = 0.9,
    shadow_bias: float = 1.25,
    highlight_rolloff: float = 0.6,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Modulates grain density as a function of exposure and luminance.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        linear_rgb:
            Linear RGB image
        mid_gray:
            Reference mid-gray
        density_strength:
            Overall coupling strength
        shadow_bias:
            Exponent to bias shadows
        highlight_rolloff:
            Compression factor for highlights
        eps:
            Numerical stability epsilon
    Returns:
        Exposure-coupled grain field
    """
    grain = grain_field.astype(np.float32, copy=True)
    # Compute luminance
    luma = (
        0.272229 * linear_rgb[..., 0] +
        0.674082 * linear_rgb[..., 1] +
        0.053689 * linear_rgb[..., 2]
    )
    # Normalize around mid-gray
    luma_norm = luma / (mid_gray + eps)
    # Shadow emphasis curve
    shadow_term = (1.0 / (luma_norm + eps)) ** shadow_bias
    # Highlight rolloff
    highlight_term = 1.0 / (1.0 + highlight_rolloff * luma_norm)
    density_map = shadow_term * highlight_term
    density_map = np.clip(density_map, 0.25, 3.0)
    density_map *= density_strength
    if grain.ndim == 3:
        density_map = density_map[..., None]
    grain_out = grain * density_map
    # Energy normalization
    energy_in = np.mean(grain * grain) + eps
    energy_out = np.mean(grain_out * grain_out) + eps
    grain_out *= np.sqrt(energy_in / energy_out)
    return grain_out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_grain_density_exposure_coupling(
    grain_field: np.ndarray,
    linear_rgb: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies exposure-coupled grain density shaping.
    """
    return couple_grain_density_to_exposure(
        grain_field=grain_field,
        linear_rgb=linear_rgb,
        mid_gray=config.get("mid_gray", 0.18),
        density_strength=config.get("density_strength", 0.9),
        shadow_bias=config.get("shadow_bias", 1.25),
        highlight_rolloff=config.get("highlight_rolloff", 0.6),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 C 05 — GRAIN DENSITY VS EXPOSURE COUPLING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 C 06 — GRAIN STABILITY CLAMP
# ==============================================================================
# Purpose:
#   Enforce hard stability bounds on grain amplitude and temporal variation,
#   preventing flicker, pumping, or runaway amplification during aggressive
#   grading, stabilization, or temporal processing.
#
# Cinematic relevance:
#   - Eliminates grain flicker artifacts
#   - Guarantees consistent texture across long shots
#   - Required for HDR delivery and cloud batch rendering
#
# Runs AFTER:
#   - 84 C 05 (Grain Density vs Exposure Coupling)
# ==============================================================================
import numpy as np
def clamp_grain_stability(
    grain_field: np.ndarray,
    max_rms: float = 0.12,
    min_rms: float = 0.015,
    soft_knee: float = 0.4,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Clamps grain RMS energy into a perceptually stable envelope.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        max_rms:
            Maximum allowed RMS grain amplitude
        min_rms:
            Minimum allowed RMS grain amplitude
        soft_knee:
            Soft compression knee for smooth limiting
        eps:
            Numerical stability epsilon
    Returns:
        Stabilized grain field
    """
    grain = grain_field.astype(np.float32, copy=True)
    # Compute RMS energy
    rms = np.sqrt(np.mean(grain * grain) + eps)
    # Soft knee compression
    if rms > max_rms:
        excess = rms - max_rms
        compression = excess / (excess + soft_knee + eps)
        gain = max_rms / (rms * (1.0 - compression) + eps)
    elif rms < min_rms:
        gain = min_rms / (rms + eps)
    else:
        gain = 1.0
    grain_out = grain * gain
    return grain_out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_grain_stability_clamp(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies final grain stability constraints.
    """
    return clamp_grain_stability(
        grain_field=grain_field,
        max_rms=config.get("max_rms", 0.12),
        min_rms=config.get("min_rms", 0.015),
        soft_knee=config.get("soft_knee", 0.4),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 C 06 — GRAIN STABILITY CLAMP
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 D 01 — TEMPORAL GRAIN MEMORY
# ==============================================================================
# Purpose:
#   Maintain temporal memory of grain so texture evolves coherently across
#   frames instead of regenerating independently each frame.
#
# Cinematic relevance:
#   - Prevents "boiling" grain artifacts
#   - Preserves analog continuity in long shots
#   - Essential for stabilized drone footage
#
# Runs AFTER:
#   - 84 C 06 (Grain Stability Clamp)
# ==============================================================================
import numpy as np
def apply_temporal_grain_memory(
    current_grain: np.ndarray,
    previous_grain: np.ndarray,
    memory_strength: float = 0.75,
    decay_floor: float = 0.05,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Blends current grain with previous frame grain to preserve temporal memory.
    Parameters:
        current_grain:
            Newly generated grain field
        previous_grain:
            Grain field from previous frame
        memory_strength:
            Temporal blending strength (0–1)
        decay_floor:
            Minimum contribution of new grain
        eps:
            Numerical stability epsilon
    Returns:
        Temporally coherent grain field
    """
    memory_strength = np.clip(memory_strength, 0.0, 1.0)
    decay_floor = np.clip(decay_floor, 0.0, 1.0)
    if previous_grain is None:
        return current_grain
    # Blend with temporal memory
    blended = (
        memory_strength * previous_grain +
        (1.0 - memory_strength) * current_grain
    )
    # Ensure new information is never fully suppressed
    blended = (
        (1.0 - decay_floor) * blended +
        decay_floor * current_grain
    )
    # Energy normalization
    energy_in = np.mean(current_grain * current_grain) + eps
    energy_out = np.mean(blended * blended) + eps
    blended *= np.sqrt(energy_in / energy_out)
    return blended
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_temporal_grain_memory(
    grain_field: np.ndarray,
    temporal_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies temporal grain memory using stored state.
    """
    previous = temporal_state.get("previous_grain")
    updated = apply_temporal_grain_memory(
        current_grain=grain_field,
        previous_grain=previous,
        memory_strength=config.get("memory_strength", 0.75),
        decay_floor=config.get("decay_floor", 0.05),
        eps=config.get("eps", 1e-6)
    )
    temporal_state["previous_grain"] = updated
    return updated
# ==============================================================================
# END OF SUBCHUNK 84 D 01 — TEMPORAL GRAIN MEMORY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 D 02 — GRAIN PERSISTENCE DECAY
# ==============================================================================
# Purpose:
#   Model controlled decay of grain memory over time so texture persists
#   naturally but does not become static or ghosted across long durations.
#
# Cinematic relevance:
#   - Prevents frozen grain artifacts
#   - Maintains analog-like temporal evolution
#   - Critical for long aerial shots and slow camera motion
#
# Runs AFTER:
#   - 84 D 01 (Temporal Grain Memory)
# ==============================================================================
import numpy as np
def apply_grain_persistence_decay(
    grain_field: np.ndarray,
    frame_delta: int,
    decay_rate: float = 0.02,
    min_persistence: float = 0.25,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Applies exponential decay to grain persistence over time.
    Parameters:
        grain_field:
            Grain field with temporal memory
        frame_delta:
            Number of frames since last strong grain refresh
        decay_rate:
            Per-frame decay coefficient
        min_persistence:
            Lower bound for grain persistence
        eps:
            Numerical stability epsilon
    Returns:
        Grain field with persistence decay applied
    """
    grain = grain_field.astype(np.float32, copy=True)
    # Compute decay factor
    decay = np.exp(-decay_rate * max(frame_delta, 0))
    decay = np.clip(decay, min_persistence, 1.0)
    grain_out = grain * decay
    # Energy normalization to avoid dimming
    energy_in = np.mean(grain * grain) + eps
    energy_out = np.mean(grain_out * grain_out) + eps
    grain_out *= np.sqrt(energy_in / energy_out)
    return grain_out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_persistence_decay(
    grain_field: np.ndarray,
    temporal_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies grain persistence decay using temporal state.
    """
    frame_delta = temporal_state.get("frames_since_refresh", 0)
    decayed = apply_grain_persistence_decay(
        grain_field=grain_field,
        frame_delta=frame_delta,
        decay_rate=config.get("decay_rate", 0.02),
        min_persistence=config.get("min_persistence", 0.25),
        eps=config.get("eps", 1e-6)
    )
    temporal_state["frames_since_refresh"] = frame_delta + 1
    return decayed
# ==============================================================================
# END OF SUBCHUNK 84 D 02 — GRAIN PERSISTENCE DECAY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 D 03 — GRAIN SCENE-CHANGE RESET LOGIC
# ==============================================================================
# Purpose:
#   Detect hard scene changes or abrupt exposure/grade discontinuities and
#   reset grain memory safely so texture does not smear, ghost, or mismatch
#   across cuts.
#
# Cinematic relevance:
#   - Prevents grain carryover across edits
#   - Preserves editorial intent at hard cuts
#   - Essential for multi-shot drone sequences and montages
#
# Runs AFTER:
#   - 84 D 02 (Grain Persistence Decay)
# ==============================================================================
import numpy as np
def detect_scene_change(
    prev_luma_hist: np.ndarray,
    curr_luma_hist: np.ndarray,
    hist_threshold: float = 0.35,
    eps: float = 1e-6
) -> bool:
    """
    Detects scene changes using luminance histogram divergence.
    Parameters:
        prev_luma_hist:
            Histogram of previous frame luminance
        curr_luma_hist:
            Histogram of current frame luminance
        hist_threshold:
            Divergence threshold for scene cut detection
        eps:
            Numerical stability epsilon
    Returns:
        True if scene change detected
    """
    # Normalize histograms
    p = prev_luma_hist / (np.sum(prev_luma_hist) + eps)
    q = curr_luma_hist / (np.sum(curr_luma_hist) + eps)
    # Jensen-Shannon divergence (symmetric, bounded)
    m = 0.5 * (p + q)
    jsd = 0.5 * (
        np.sum(p * np.log((p + eps) / (m + eps))) +
        np.sum(q * np.log((q + eps) / (m + eps)))
    )
    return jsd > hist_threshold
def apply_grain_scene_reset(
    grain_field: np.ndarray,
    temporal_state: dict,
    scene_changed: bool,
    reset_strength: float = 1.0
) -> np.ndarray:
    """
    Resets or attenuates grain memory on detected scene changes.
    Parameters:
        grain_field:
            Current grain field
        temporal_state:
            Temporal grain state dictionary
        scene_changed:
            Scene change flag
        reset_strength:
            Strength of reset (1.0 = full reset)
    Returns:
        Grain field after scene-change handling
    """
    if not scene_changed:
        return grain_field
    reset_strength = np.clip(reset_strength, 0.0, 1.0)
    # Clear temporal memory
    temporal_state["previous_grain"] = None
    temporal_state["frames_since_refresh"] = 0
    # Attenuate current grain slightly to avoid pop
    return grain_field * (1.0 - 0.15 * reset_strength)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_scene_change(
    grain_field: np.ndarray,
    prev_luma_hist: np.ndarray,
    curr_luma_hist: np.ndarray,
    temporal_state: dict,
    config: dict
) -> np.ndarray:
    """
    Detects scene changes and resets grain memory when required.
    """
    scene_changed = detect_scene_change(
        prev_luma_hist=prev_luma_hist,
        curr_luma_hist=curr_luma_hist,
        hist_threshold=config.get("hist_threshold", 0.35)
    )
    return apply_grain_scene_reset(
        grain_field=grain_field,
        temporal_state=temporal_state,
        scene_changed=scene_changed,
        reset_strength=config.get("reset_strength", 1.0)
    )
# ==============================================================================
# END OF SUBCHUNK 84 D 03 — GRAIN SCENE-CHANGE RESET LOGIC
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 D 04 — GRAIN MOTION COMPENSATION
# ==============================================================================
# Purpose:
#   Compensate grain motion using optical-flow-derived motion vectors so grain
#   adheres to scene motion rather than screen space, preventing “sliding grain”
#   artifacts during camera movement and stabilization.
#
# Cinematic relevance:
#   - Eliminates grain drifting during pans, tilts, and drone translation
#   - Essential for EIS / gyro-stabilized aerial footage
#   - Matches photochemical grain behavior locked to the image plane
#
# Runs AFTER:
#   - 84 D 03 (Grain Scene-Change Reset Logic)
# ==============================================================================
import numpy as np
def warp_grain_with_motion(
    grain_field: np.ndarray,
    flow_uv: np.ndarray,
    motion_strength: float = 1.0,
    border_mode: str = "reflect"
) -> np.ndarray:
    """
    Warps grain field using optical flow vectors.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        flow_uv:
            Optical flow field (H, W, 2) in pixel units
        motion_strength:
            Scaling factor for motion compensation
        border_mode:
            Border handling mode ('reflect', 'wrap', 'constant')
    Returns:
        Motion-compensated grain field
    """
    h, w = grain_field.shape[:2]
    # Coordinate grid
    y, x = np.mgrid[0:h, 0:w].astype(np.float32)
    # Apply motion vectors
    dx = flow_uv[..., 0] * motion_strength
    dy = flow_uv[..., 1] * motion_strength
    x_warp = x + dx
    y_warp = y + dy
    # Clip coordinates
    x0 = np.floor(x_warp).astype(int)
    y0 = np.floor(y_warp).astype(int)
    x0 = np.clip(x0, 0, w - 1)
    y0 = np.clip(y0, 0, h - 1)
    if grain_field.ndim == 2:
        warped = grain_field[y0, x0]
    else:
        warped = grain_field[y0, x0, :]
    return warped
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_grain_motion_compensation(
    grain_field: np.ndarray,
    motion_vectors: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies motion-compensated warping to grain field.
    """
    if motion_vectors is None:
        return grain_field
    return warp_grain_with_motion(
        grain_field=grain_field,
        flow_uv=motion_vectors,
        motion_strength=config.get("motion_strength", 1.0),
        border_mode=config.get("border_mode", "reflect")
    )
# ==============================================================================
# END OF SUBCHUNK 84 D 04 — GRAIN MOTION COMPENSATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 D 05 — GRAIN CAMERA-MOVEMENT COUPLING
# ==============================================================================
# Purpose:
#   Couple grain behavior to camera motion magnitude so texture subtly tightens
#   during fast moves and relaxes during slow or locked-off shots, matching
#   real photochemical perception.
#
# Cinematic relevance:
#   - Prevents grain from overpowering motion blur
#   - Maintains perceived sharpness during fast drone passes
#   - Aligns grain energy with camera dynamics
#
# Runs AFTER:
#   - 84 D 04 (Grain Motion Compensation)
# ==============================================================================
import numpy as np
def couple_grain_to_camera_motion(
    grain_field: np.ndarray,
    motion_vectors: np.ndarray,
    base_strength: float = 1.0,
    motion_softness: float = 0.6,
    max_attenuation: float = 0.5,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Modulates grain amplitude based on camera motion magnitude.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        motion_vectors:
            Optical flow field (H, W, 2)
        base_strength:
            Baseline grain strength
        motion_softness:
            Controls how gently grain attenuates with motion
        max_attenuation:
            Maximum allowed grain reduction at high motion
        eps:
            Numerical stability epsilon
    Returns:
        Motion-coupled grain field
    """
    grain = grain_field.astype(np.float32, copy=True)
    if motion_vectors is None:
        return grain * base_strength
    # Compute motion magnitude
    mag = np.sqrt(
        motion_vectors[..., 0] ** 2 +
        motion_vectors[..., 1] ** 2
    )
    # Normalize motion magnitude
    mag_norm = mag / (np.mean(mag) + eps)
    # Smooth attenuation curve
    attenuation = 1.0 / (1.0 + motion_softness * mag_norm)
    attenuation = np.clip(attenuation, max_attenuation, 1.0)
    if grain.ndim == 3:
        attenuation = attenuation[..., None]
    grain_out = grain * attenuation * base_strength
    # Energy normalization to avoid pumping
    energy_in = np.mean(grain * grain) + eps
    energy_out = np.mean(grain_out * grain_out) + eps
    grain_out *= np.sqrt(energy_in / energy_out)
    return grain_out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_grain_camera_movement_coupling(
    grain_field: np.ndarray,
    motion_vectors: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies camera-motion-coupled grain modulation.
    """
    return couple_grain_to_camera_motion(
        grain_field=grain_field,
        motion_vectors=motion_vectors,
        base_strength=config.get("base_strength", 1.0),
        motion_softness=config.get("motion_softness", 0.6),
        max_attenuation=config.get("max_attenuation", 0.5),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 D 05 — GRAIN CAMERA-MOVEMENT COUPLING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 D 06 — GRAIN VELOCITY-ADAPTIVE SCALING
# ==============================================================================
# Purpose:
#   Adapt grain amplitude and frequency response based on instantaneous
#   motion velocity so texture remains perceptually consistent across
#   slow, medium, and fast camera movement.
#
# Cinematic relevance:
#   - Prevents grain washout during fast drone flybys
#   - Avoids over-emphasized grain in locked-off shots
#   - Preserves perceived sharpness and motion clarity
#
# Runs AFTER:
#   - 84 D 05 (Grain Camera-Movement Coupling)
# ==============================================================================
import numpy as np
def scale_grain_by_velocity(
    grain_field: np.ndarray,
    motion_vectors: np.ndarray,
    low_vel_gain: float = 1.05,
    mid_vel_gain: float = 1.0,
    high_vel_gain: float = 0.85,
    vel_low: float = 0.5,
    vel_high: float = 3.0,
    smoothness: float = 0.35,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Scales grain amplitude smoothly as a function of motion velocity.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        motion_vectors:
            Optical flow field (H, W, 2)
        low_vel_gain:
            Gain applied in near-static scenes
        mid_vel_gain:
            Gain applied at moderate motion
        high_vel_gain:
            Gain applied at high velocity
        vel_low:
            Lower velocity breakpoint (pixels/frame)
        vel_high:
            Upper velocity breakpoint (pixels/frame)
        smoothness:
            Transition smoothness between regimes
        eps:
            Numerical stability epsilon
    Returns:
        Velocity-adapted grain field
    """
    grain = grain_field.astype(np.float32, copy=True)
    if motion_vectors is None:
        return grain * mid_vel_gain
    # Velocity magnitude
    vel = np.sqrt(
        motion_vectors[..., 0] ** 2 +
        motion_vectors[..., 1] ** 2
    )
    # Normalize velocity to [0,1] range between breakpoints
    t = (vel - vel_low) / (vel_high - vel_low + eps)
    t = np.clip(t, 0.0, 1.0)
    # Smoothstep interpolation
    t_s = t * t * (3.0 - 2.0 * t)
    # Interpolate gain curve
    gain_low_mid = low_vel_gain + (mid_vel_gain - low_vel_gain) * t_s
    gain_mid_high = mid_vel_gain + (high_vel_gain - mid_vel_gain) * t_s
    gain = (1.0 - t_s) * gain_low_mid + t_s * gain_mid_high
    if grain.ndim == 3:
        gain = gain[..., None]
    grain_out = grain * gain
    # Energy normalization to prevent pumping
    energy_in = np.mean(grain * grain) + eps
    energy_out = np.mean(grain_out * grain_out) + eps
    grain_out *= np.sqrt(energy_in / energy_out)
    return grain_out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def apply_grain_velocity_scaling(
    grain_field: np.ndarray,
    motion_vectors: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies velocity-adaptive scaling to grain.
    """
    return scale_grain_by_velocity(
        grain_field=grain_field,
        motion_vectors=motion_vectors,
        low_vel_gain=config.get("low_vel_gain", 1.05),
        mid_vel_gain=config.get("mid_vel_gain", 1.0),
        high_vel_gain=config.get("high_vel_gain", 0.85),
        vel_low=config.get("vel_low", 0.5),
        vel_high=config.get("vel_high", 3.0),
        smoothness=config.get("smoothness", 0.35),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 D 06 — GRAIN VELOCITY-ADAPTIVE SCALING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 E 01 — GRAIN VS DETAIL PRESERVATION MASK
# ==============================================================================
# Purpose:
#   Generate a detail-aware mask that suppresses grain in high-detail regions
#   (edges, textures, fine structure) while allowing grain to remain present
#   in low-detail areas, matching real film perception.
#
# Cinematic relevance:
#   - Preserves sharpness and micro-detail
#   - Prevents grain from eating texture (faces, buildings, foliage)
#   - Required for IMAX-scale and 5.3K drone footage
#
# Runs AFTER:
#   - 84 D 06 (Grain Velocity-Adaptive Scaling)
# ==============================================================================
import numpy as np
def compute_detail_mask(
    linear_rgb: np.ndarray,
    edge_weight: float = 0.7,
    texture_weight: float = 0.3,
    softness: float = 0.4,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Computes a normalized detail mask based on edges and local texture energy.
    Parameters:
        linear_rgb:
            Linear RGB image
        edge_weight:
            Weight of edge contribution
        texture_weight:
            Weight of texture contribution
        softness:
            Controls mask softness / rolloff
        eps:
            Numerical stability epsilon
    Returns:
        Detail mask in range [0,1] (1 = high detail)
    """
    # Luminance proxy
    luma = (
        0.272229 * linear_rgb[..., 0] +
        0.674082 * linear_rgb[..., 1] +
        0.053689 * linear_rgb[..., 2]
    )
    # Edge energy via gradients
    gy, gx = np.gradient(luma)
    edge_energy = np.sqrt(gx * gx + gy * gy)
    # Texture energy via local variance
    mean = np.mean(luma)
    texture_energy = (luma - mean) ** 2
    # Normalize energies
    edge_energy /= (np.max(edge_energy) + eps)
    texture_energy /= (np.max(texture_energy) + eps)
    # Combine edge + texture
    detail = (
        edge_weight * edge_energy +
        texture_weight * texture_energy
    )
    # Soft rolloff
    detail = detail / (detail + softness + eps)
    return np.clip(detail, 0.0, 1.0)
def apply_detail_preservation_mask(
    grain_field: np.ndarray,
    detail_mask: np.ndarray,
    protect_strength: float = 0.85
) -> np.ndarray:
    """
    Suppresses grain in high-detail regions using detail mask.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        detail_mask:
            Detail mask (H, W), 1 = high detail
        protect_strength:
            How strongly to suppress grain in detailed areas
    Returns:
        Detail-aware grain field
    """
    protect_strength = np.clip(protect_strength, 0.0, 1.0)
    suppression = 1.0 - protect_strength * detail_mask
    if grain_field.ndim == 3:
        suppression = suppression[..., None]
    return grain_field * suppression
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_detail_preservation(
    grain_field: np.ndarray,
    linear_rgb: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies detail-aware grain suppression.
    """
    detail_mask = compute_detail_mask(
        linear_rgb=linear_rgb,
        edge_weight=config.get("edge_weight", 0.7),
        texture_weight=config.get("texture_weight", 0.3),
        softness=config.get("softness", 0.4),
        eps=config.get("eps", 1e-6)
    )
    return apply_detail_preservation_mask(
        grain_field=grain_field,
        detail_mask=detail_mask,
        protect_strength=config.get("protect_strength", 0.85)
    )
# ==============================================================================
# END OF SUBCHUNK 84 E 01 — GRAIN VS DETAIL PRESERVATION MASK
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 E 02 — GRAIN LOCAL CONTRAST PROTECTION
# ==============================================================================
# Purpose:
#   Protect local contrast by attenuating grain in regions where contrast
#   carries important visual information (faces, clouds, gradients, skin).
#
# Cinematic relevance:
#   - Prevents muddy midtones
#   - Preserves facial modeling and volumetric depth
#   - Essential for high-end filmic smoothness
#
# Runs AFTER:
#   - 84 E 01 (Grain vs Detail Preservation Mask)
# ==============================================================================
import numpy as np
def compute_local_contrast_map(
    linear_rgb: np.ndarray,
    radius: int = 5,
    contrast_softness: float = 0.5,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Computes a local contrast importance map.
    Parameters:
        linear_rgb:
            Linear RGB image
        radius:
            Neighborhood radius for local contrast
        contrast_softness:
            Softness of contrast importance rolloff
        eps:
            Numerical stability epsilon
    Returns:
        Contrast importance map in [0,1]
    """
    # Luminance proxy (ACES-like)
    luma = (
        0.272229 * linear_rgb[..., 0] +
        0.674082 * linear_rgb[..., 1] +
        0.053689 * linear_rgb[..., 2]
    )
    h, w = luma.shape
    padded = np.pad(luma, radius, mode="reflect")
    local_min = np.empty_like(luma)
    local_max = np.empty_like(luma)
    for y in range(h):
        for x in range(w):
            patch = padded[
                y:y + 2 * radius + 1,
                x:x + 2 * radius + 1
            ]
            local_min[y, x] = np.min(patch)
            local_max[y, x] = np.max(patch)
    local_contrast = local_max - local_min
    local_contrast /= (np.max(local_contrast) + eps)
    # Soft rolloff to avoid harsh transitions
    contrast_map = local_contrast / (local_contrast + contrast_softness + eps)
    return np.clip(contrast_map, 0.0, 1.0)
def apply_local_contrast_protection(
    grain_field: np.ndarray,
    contrast_map: np.ndarray,
    protection_strength: float = 0.75
) -> np.ndarray:
    """
    Attenuates grain where local contrast is important.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        contrast_map:
            Contrast importance map (H, W)
        protection_strength:
            Strength of grain suppression in contrast-rich areas
    Returns:
        Contrast-protected grain field
    """
    protection_strength = np.clip(protection_strength, 0.0, 1.0)
    attenuation = 1.0 - protection_strength * contrast_map
    if grain_field.ndim == 3:
        attenuation = attenuation[..., None]
    return grain_field * attenuation
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_local_contrast_protection(
    grain_field: np.ndarray,
    linear_rgb: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies local contrast-aware grain protection.
    """
    contrast_map = compute_local_contrast_map(
        linear_rgb=linear_rgb,
        radius=config.get("radius", 5),
        contrast_softness=config.get("contrast_softness", 0.5),
        eps=config.get("eps", 1e-6)
    )
    return apply_local_contrast_protection(
        grain_field=grain_field,
        contrast_map=contrast_map,
        protection_strength=config.get("protection_strength", 0.75)
    )
# ==============================================================================
# END OF SUBCHUNK 84 E 02 — GRAIN LOCAL CONTRAST PROTECTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 E 03 — GRAIN HIGHLIGHT ROLL-OFF PROTECTION
# ==============================================================================
# Purpose:
#   Attenuate grain progressively in highlights following a filmic roll-off
#   curve, preventing sparkle artifacts while preserving highlight texture.
#
# Cinematic relevance:
#   - Prevents buzzing grain in skies and specular highlights
#   - Preserves smooth highlight gradients
#   - Essential for daylight drone shots and HDR scenes
#
# Runs AFTER:
#   - 84 E 02 (Grain Local Contrast Protection)
# ==============================================================================
import numpy as np
def compute_highlight_mask(
    linear_rgb: np.ndarray,
    knee_start: float = 0.65,
    knee_softness: float = 0.15,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Computes a smooth highlight roll-off mask.
    Parameters:
        linear_rgb:
            Linear RGB image
        knee_start:
            Luminance level where highlight roll-off begins
        knee_softness:
            Smoothness of the knee transition
        eps:
            Numerical stability epsilon
    Returns:
        Highlight mask in [0,1] (1 = strong highlight)
    """
    # ACES-like luminance
    luma = (
        0.272229 * linear_rgb[..., 0] +
        0.674082 * linear_rgb[..., 1] +
        0.053689 * linear_rgb[..., 2]
    )
    # Normalize luminance
    luma_n = luma / (np.max(luma) + eps)
    # Smooth knee function
    t = (luma_n - knee_start) / (knee_softness + eps)
    t = np.clip(t, 0.0, 1.0)
    highlight = t * t * (3.0 - 2.0 * t)
    return np.clip(highlight, 0.0, 1.0)
def apply_highlight_grain_protection(
    grain_field: np.ndarray,
    highlight_mask: np.ndarray,
    protection_strength: float = 0.9
) -> np.ndarray:
    """
    Suppresses grain in highlight regions.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        highlight_mask:
            Highlight mask (H, W)
        protection_strength:
            Strength of grain suppression in highlights
    Returns:
        Highlight-protected grain field
    """
    protection_strength = np.clip(protection_strength, 0.0, 1.0)
    attenuation = 1.0 - protection_strength * highlight_mask
    if grain_field.ndim == 3:
        attenuation = attenuation[..., None]
    return grain_field * attenuation
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_highlight_protection(
    grain_field: np.ndarray,
    linear_rgb: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies highlight roll-off grain protection.
    """
    highlight_mask = compute_highlight_mask(
        linear_rgb=linear_rgb,
        knee_start=config.get("knee_start", 0.65),
        knee_softness=config.get("knee_softness", 0.15),
        eps=config.get("eps", 1e-6)
    )
    return apply_highlight_grain_protection(
        grain_field=grain_field,
        highlight_mask=highlight_mask,
        protection_strength=config.get("protection_strength", 0.9)
    )
# ==============================================================================
# END OF SUBCHUNK 84 E 03 — GRAIN HIGHLIGHT ROLL-OFF PROTECTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 E 04 — GRAIN SHADOW DETAIL SAFEGUARD
# ==============================================================================
# Purpose:
#   Protect shadow detail by attenuating grain in low-luminance regions using
#   a perceptually-linear shadow lift curve, preserving texture without mud.
#
# Cinematic relevance:
#   - Prevents crawling grain in dark areas
#   - Preserves night-scene texture and depth
#   - Essential for dusk/night drone shots and interiors
#
# Runs AFTER:
#   - 84 E 03 (Grain Highlight Roll-Off Protection)
# ==============================================================================
import numpy as np
def compute_shadow_mask(
    linear_rgb: np.ndarray,
    toe_start: float = 0.08,
    toe_softness: float = 0.12,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Computes a smooth shadow protection mask.
    Parameters:
        linear_rgb:
            Linear RGB image
        toe_start:
            Luminance below which shadow protection increases
        toe_softness:
            Softness of the toe transition
        eps:
            Numerical stability epsilon
    Returns:
        Shadow mask in [0,1] (1 = deep shadow)
    """
    # ACES-like luminance
    luma = (
        0.272229 * linear_rgb[..., 0] +
        0.674082 * linear_rgb[..., 1] +
        0.053689 * linear_rgb[..., 2]
    )
    # Normalize luminance
    luma_n = luma / (np.max(luma) + eps)
    # Inverted smooth toe
    t = (toe_start - luma_n) / (toe_softness + eps)
    t = np.clip(t, 0.0, 1.0)
    shadow = t * t * (3.0 - 2.0 * t)
    return np.clip(shadow, 0.0, 1.0)
def apply_shadow_grain_safeguard(
    grain_field: np.ndarray,
    shadow_mask: np.ndarray,
    safeguard_strength: float = 0.8
) -> np.ndarray:
    """
    Attenuates grain in shadow regions to preserve detail.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        shadow_mask:
            Shadow mask (H, W)
        safeguard_strength:
            Strength of grain suppression in shadows
    Returns:
        Shadow-protected grain field
    """
    safeguard_strength = np.clip(safeguard_strength, 0.0, 1.0)
    attenuation = 1.0 - safeguard_strength * shadow_mask
    if grain_field.ndim == 3:
        attenuation = attenuation[..., None]
    return grain_field * attenuation
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_shadow_safeguard(
    grain_field: np.ndarray,
    linear_rgb: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies shadow-aware grain protection.
    """
    shadow_mask = compute_shadow_mask(
        linear_rgb=linear_rgb,
        toe_start=config.get("toe_start", 0.08),
        toe_softness=config.get("toe_softness", 0.12),
        eps=config.get("eps", 1e-6)
    )
    return apply_shadow_grain_safeguard(
        grain_field=grain_field,
        shadow_mask=shadow_mask,
        safeguard_strength=config.get("safeguard_strength", 0.8)
    )
# ==============================================================================
# END OF SUBCHUNK 84 E 04 — GRAIN SHADOW DETAIL SAFEGUARD
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 E 05 — GRAIN MICRO-CONTRAST INTERACTION
# ==============================================================================
# Purpose:
#   Modulate grain intensity based on local micro-contrast so grain reinforces
#   texture instead of flattening or obscuring it.
#
# Cinematic relevance:
#   - Prevents grain from killing skin texture
#   - Enhances perceived sharpness without halos
#   - Critical for “film density” feel on faces and architecture
#
# Runs AFTER:
#   - 84 E 04 (Grain Shadow Detail Safeguard)
# ==============================================================================
import numpy as np
def compute_micro_contrast(
    linear_rgb: np.ndarray,
    radius: int = 2,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Computes a micro-contrast map using local high-frequency energy.
    Parameters:
        linear_rgb:
            Linear RGB image
        radius:
            Neighborhood radius for micro-contrast
        eps:
            Numerical stability epsilon
    Returns:
        Micro-contrast map in [0,1]
    """
    # Luminance (ACES-like)
    luma = (
        0.272229 * linear_rgb[..., 0] +
        0.674082 * linear_rgb[..., 1] +
        0.053689 * linear_rgb[..., 2]
    )
    h, w = luma.shape
    padded = np.pad(luma, radius, mode="reflect")
    local_mean = np.empty_like(luma)
    for y in range(h):
        for x in range(w):
            patch = padded[
                y:y + 2 * radius + 1,
                x:x + 2 * radius + 1
            ]
            local_mean[y, x] = np.mean(patch)
    micro = np.abs(luma - local_mean)
    micro /= (np.max(micro) + eps)
    return np.clip(micro, 0.0, 1.0)
def apply_micro_contrast_grain_interaction(
    grain_field: np.ndarray,
    micro_contrast: np.ndarray,
    enhancement_strength: float = 0.35
) -> np.ndarray:
    """
    Enhances or attenuates grain based on micro-contrast.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        micro_contrast:
            Micro-contrast map (H, W)
        enhancement_strength:
            Strength of grain reinforcement in textured areas
    Returns:
        Micro-contrast-aware grain field
    """
    enhancement_strength = np.clip(enhancement_strength, 0.0, 1.0)
    gain = 1.0 + enhancement_strength * (micro_contrast - 0.5)
    if grain_field.ndim == 3:
        gain = gain[..., None]
    return grain_field * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_micro_contrast_interaction(
    grain_field: np.ndarray,
    linear_rgb: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies micro-contrast-aware grain interaction.
    """
    micro_contrast = compute_micro_contrast(
        linear_rgb=linear_rgb,
        radius=config.get("radius", 2),
        eps=config.get("eps", 1e-6)
    )
    return apply_micro_contrast_grain_interaction(
        grain_field=grain_field,
        micro_contrast=micro_contrast,
        enhancement_strength=config.get("enhancement_strength", 0.35)
    )
# ==============================================================================
# END OF SUBCHUNK 84 E 05 — GRAIN MICRO-CONTRAST INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 E 06 — GRAIN FINAL SAFETY CLAMP
# ==============================================================================
# Purpose:
#   Apply a final perceptual and numerical safety clamp to the grain field,
#   ensuring no out-of-range values, no energy spikes, and no perceptual
#   instability before compositing into the image.
#
# Cinematic relevance:
#   - Prevents illegal pixel excursions (HDR / SDR)
#   - Guarantees stable grain energy across frames
#   - Required for professional mastering pipelines
#
# Runs AFTER:
#   - 84 E 05 (Grain Micro-Contrast Interaction)
# ==============================================================================
import numpy as np
def grain_final_safety_clamp(
    grain_field: np.ndarray,
    max_abs_value: float = 0.15,
    soft_knee: float = 0.05,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Applies a soft-knee clamp to grain values to avoid harsh clipping.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        max_abs_value:
            Maximum allowed absolute grain deviation
        soft_knee:
            Softness of clamp transition
        eps:
            Numerical stability epsilon
    Returns:
        Safely clamped grain field
    """
    g = grain_field.astype(np.float32, copy=True)
    abs_g = np.abs(g)
    # Soft-knee compression curve
    over = np.maximum(abs_g - max_abs_value, 0.0)
    compressed = over / (over + soft_knee + eps)
    g = np.sign(g) * (abs_g - compressed * over)
    return g
def normalize_grain_energy(
    grain_field: np.ndarray,
    target_rms: float = 0.035,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Normalizes grain RMS energy to a target perceptual level.
    """
    rms = np.sqrt(np.mean(grain_field ** 2) + eps)
    gain = target_rms / (rms + eps)
    return grain_field * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_final_safety(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies final safety clamp and energy normalization to grain.
    """
    g = grain_final_safety_clamp(
        grain_field=grain_field,
        max_abs_value=config.get("max_abs_value", 0.15),
        soft_knee=config.get("soft_knee", 0.05),
        eps=config.get("eps", 1e-6)
    )
    return normalize_grain_energy(
        grain_field=g,
        target_rms=config.get("target_rms", 0.035),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 E 06 — GRAIN FINAL SAFETY CLAMP
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 F 01 — GRAIN TEMPORAL STABILITY REFINEMENT
# ==============================================================================
# Purpose:
#   Enforce temporal coherence in grain evolution across frames so grain
#   appears organically stable, not jittery or digitally regenerated.
#
# Cinematic relevance:
#   - Eliminates frame-to-frame grain popping
#   - Preserves filmic continuity during motion
#   - Absolutely required for professional cinema perception
#
# Runs AFTER:
#   - 84 E 06 (Grain Final Safety Clamp)
# ==============================================================================
import numpy as np
def temporal_stabilize_grain(
    current_grain: np.ndarray,
    previous_grain: np.ndarray,
    stability_factor: float = 0.85,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Blends current grain with previous frame grain to ensure temporal stability.
    Parameters:
        current_grain:
            Grain field for current frame
        previous_grain:
            Grain field from previous frame
        stability_factor:
            Weight of previous grain (higher = more stable)
        eps:
            Numerical stability epsilon
    Returns:
        Temporally stabilized grain field
    """
    if previous_grain is None:
        return current_grain
    stability_factor = np.clip(stability_factor, 0.0, 1.0)
    g = (
        stability_factor * previous_grain +
        (1.0 - stability_factor) * current_grain
    )
    # Energy correction to avoid drift
    energy_curr = np.mean(current_grain ** 2) + eps
    energy_new = np.mean(g ** 2) + eps
    g *= np.sqrt(energy_curr / energy_new)
    return g
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_temporal_stability(
    current_grain: np.ndarray,
    previous_grain: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies temporal stabilization to grain.
    """
    return temporal_stabilize_grain(
        current_grain=current_grain,
        previous_grain=previous_grain,
        stability_factor=config.get("stability_factor", 0.85),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 F 01 — GRAIN TEMPORAL STABILITY REFINEMENT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 F 02 — GRAIN TEMPORAL VARIANCE CONTROL
# ==============================================================================
# Purpose:
#   Control frame-to-frame variance of grain energy so it evolves smoothly
#   over time, preventing perceptual pumping or breathing artifacts.
#
# Cinematic relevance:
#   - Prevents subtle but very noticeable brightness fluctuations
#   - Maintains stable “film density” perception
#   - Required for long continuous drone shots
#
# Runs AFTER:
#   - 84 F 01 (Grain Temporal Stability Refinement)
# ==============================================================================
import numpy as np
def control_grain_temporal_variance(
    stabilized_grain: np.ndarray,
    prev_variance: float,
    variance_smoothness: float = 0.9,
    max_variance_delta: float = 0.15,
    eps: float = 1e-6
) -> tuple[np.ndarray, float]:
    """
    Limits temporal variance changes in grain energy.
    Parameters:
        stabilized_grain:
            Temporally stabilized grain field
        prev_variance:
            Grain variance from previous frame
        variance_smoothness:
            Smoothing factor for variance evolution
        max_variance_delta:
            Maximum allowed relative variance change per frame
        eps:
            Numerical stability epsilon
    Returns:
        (Variance-controlled grain field, updated variance)
    """
    current_variance = np.var(stabilized_grain)
    if prev_variance <= eps:
        return stabilized_grain, current_variance
    # Smooth variance trajectory
    target_variance = (
        variance_smoothness * prev_variance +
        (1.0 - variance_smoothness) * current_variance
    )
    # Clamp variance delta
    max_allowed = prev_variance * (1.0 + max_variance_delta)
    min_allowed = prev_variance * (1.0 - max_variance_delta)
    target_variance = np.clip(target_variance, min_allowed, max_allowed)
    scale = np.sqrt(target_variance / (current_variance + eps))
    grain_out = stabilized_grain * scale
    return grain_out, target_variance
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_temporal_variance(
    stabilized_grain: np.ndarray,
    prev_variance: float,
    config: dict
) -> tuple[np.ndarray, float]:
    """
    Applies temporal variance control to grain.
    """
    return control_grain_temporal_variance(
        stabilized_grain=stabilized_grain,
        prev_variance=prev_variance,
        variance_smoothness=config.get("variance_smoothness", 0.9),
        max_variance_delta=config.get("max_variance_delta", 0.15),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 F 02 — GRAIN TEMPORAL VARIANCE CONTROL
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 F 03 — GRAIN MOTION COHERENCE FILTER
# ==============================================================================
# Purpose:
#   Enforce coherence between grain evolution and scene motion so grain
#   appears physically attached to the photographed world rather than
#   floating independently over moving content.
#
# Cinematic relevance:
#   - Eliminates grain swimming during camera moves
#   - Maintains physical believability of film texture
#   - Absolutely essential for drone shots with parallax
#
# Runs AFTER:
#   - 84 F 02 (Grain Temporal Variance Control)
# ==============================================================================
import numpy as np
def motion_coherent_grain_filter(
    grain_field: np.ndarray,
    motion_vectors: np.ndarray,
    coherence_strength: float = 0.8,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Aligns grain evolution with motion vectors to prevent sliding artifacts.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        motion_vectors:
            Optical flow vectors (H, W, 2)
        coherence_strength:
            Degree of motion locking (0 = none, 1 = full)
        eps:
            Numerical stability epsilon
    Returns:
        Motion-coherent grain field
    """
    if motion_vectors is None:
        return grain_field
    coherence_strength = np.clip(coherence_strength, 0.0, 1.0)
    h, w = grain_field.shape[:2]
    # Create sampling grid
    y, x = np.meshgrid(
        np.arange(h),
        np.arange(w),
        indexing="ij"
    )
    # Backward-warp grain using motion vectors
    src_x = x - motion_vectors[..., 0] * coherence_strength
    src_y = y - motion_vectors[..., 1] * coherence_strength
    src_x = np.clip(src_x, 0, w - 1)
    src_y = np.clip(src_y, 0, h - 1)
    x0 = np.floor(src_x).astype(int)
    y0 = np.floor(src_y).astype(int)
    x1 = np.clip(x0 + 1, 0, w - 1)
    y1 = np.clip(y0 + 1, 0, h - 1)
    wx = src_x - x0
    wy = src_y - y0
    def bilinear(g):
        return (
            (1 - wx) * (1 - wy) * g[y0, x0] +
            wx * (1 - wy) * g[y0, x1] +
            (1 - wx) * wy * g[y1, x0] +
            wx * wy * g[y1, x1]
        )
    if grain_field.ndim == 3:
        warped = np.stack(
            [bilinear(grain_field[..., c]) for c in range(grain_field.shape[2])],
            axis=-1
        )
    else:
        warped = bilinear(grain_field)
    # Blend warped grain with original to avoid over-locking
    grain_out = (
        coherence_strength * warped +
        (1.0 - coherence_strength) * grain_field
    )
    # Energy normalization
    energy_in = np.mean(grain_field ** 2) + eps
    energy_out = np.mean(grain_out ** 2) + eps
    grain_out *= np.sqrt(energy_in / energy_out)
    return grain_out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_motion_coherence(
    grain_field: np.ndarray,
    motion_vectors: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies motion coherence filtering to grain.
    """
    return motion_coherent_grain_filter(
        grain_field=grain_field,
        motion_vectors=motion_vectors,
        coherence_strength=config.get("coherence_strength", 0.8),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 F 03 — GRAIN MOTION COHERENCE FILTER
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 F 04 — GRAIN TEMPORAL PHASE LOCK
# ==============================================================================
# Purpose:
#   Lock grain phase evolution across frames so stochastic texture evolves
#   coherently over time without phase wandering or long-term drift.
#
# Cinematic relevance:
#   - Prevents slow “boiling” of grain in static shots
#   - Maintains filmic continuity in long drone passes
#   - Critical for professional-grade temporal realism
#
# Runs AFTER:
#   - 84 F 03 (Grain Motion Coherence Filter)
# ==============================================================================
import numpy as np
def lock_grain_temporal_phase(
    current_grain: np.ndarray,
    phase_reference: np.ndarray,
    lock_strength: float = 0.7,
    eps: float = 1e-6
) -> tuple[np.ndarray, np.ndarray]:
    """
    Locks the stochastic phase of grain to a running reference.
    Parameters:
        current_grain:
            Grain field for current frame
        phase_reference:
            Persistent phase reference from previous frames
        lock_strength:
            Degree of phase locking (0 = free, 1 = locked)
        eps:
            Numerical stability epsilon
    Returns:
        (Phase-locked grain field, updated phase reference)
    """
    if phase_reference is None:
        return current_grain, current_grain.copy()
    lock_strength = np.clip(lock_strength, 0.0, 1.0)
    # Blend phase reference with current grain
    locked = (
        lock_strength * phase_reference +
        (1.0 - lock_strength) * current_grain
    )
    # Energy normalization
    energy_in = np.mean(current_grain ** 2) + eps
    energy_out = np.mean(locked ** 2) + eps
    locked *= np.sqrt(energy_in / energy_out)
    # Update phase reference slowly to avoid freezing
    new_phase_ref = (
        0.95 * phase_reference +
        0.05 * locked
    )
    return locked, new_phase_ref
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_temporal_phase_lock(
    current_grain: np.ndarray,
    phase_reference: np.ndarray,
    config: dict
) -> tuple[np.ndarray, np.ndarray]:
    """
    Applies temporal phase locking to grain.
    """
    return lock_grain_temporal_phase(
        current_grain=current_grain,
        phase_reference=phase_reference,
        lock_strength=config.get("lock_strength", 0.7),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 F 04 — GRAIN TEMPORAL PHASE LOCK
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 F 05 — GRAIN TEMPORAL DRIFT SUPPRESSION
# ==============================================================================
# Purpose:
#   Suppress long-term low-frequency drift in grain evolution so stochastic
#   texture remains centered and neutral over extended shot durations.
#
# Cinematic relevance:
#   - Prevents slow grain “tilting” or bias over minutes-long shots
#   - Maintains neutral film density baseline
#   - Essential for continuous drone or gimbal passes
#
# Runs AFTER:
#   - 84 F 04 (Grain Temporal Phase Lock)
# ==============================================================================
import numpy as np
def suppress_grain_temporal_drift(
    grain_field: np.ndarray,
    running_mean: np.ndarray,
    drift_suppression: float = 0.95,
    eps: float = 1e-6
) -> tuple[np.ndarray, np.ndarray]:
    """
    Removes accumulated low-frequency drift from grain over time.
    Parameters:
        grain_field:
            Current grain field
        running_mean:
            Running mean of grain over time
        drift_suppression:
            How aggressively drift is suppressed
        eps:
            Numerical stability epsilon
    Returns:
        (Drift-suppressed grain field, updated running mean)
    """
    if running_mean is None:
        return grain_field, grain_field.copy()
    drift_suppression = np.clip(drift_suppression, 0.0, 1.0)
    # Update running mean slowly
    new_running_mean = (
        drift_suppression * running_mean +
        (1.0 - drift_suppression) * grain_field
    )
    # Remove low-frequency drift component
    corrected = grain_field - new_running_mean
    # Energy normalization
    energy_in = np.mean(grain_field ** 2) + eps
    energy_out = np.mean(corrected ** 2) + eps
    corrected *= np.sqrt(energy_in / energy_out)
    return corrected, new_running_mean
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_temporal_drift_suppression(
    grain_field: np.ndarray,
    running_mean: np.ndarray,
    config: dict
) -> tuple[np.ndarray, np.ndarray]:
    """
    Applies temporal drift suppression to grain.
    """
    return suppress_grain_temporal_drift(
        grain_field=grain_field,
        running_mean=running_mean,
        drift_suppression=config.get("drift_suppression", 0.95),
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 F 05 — GRAIN TEMPORAL DRIFT SUPPRESSION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 F 06 — GRAIN SHOT BOUNDARY RESET LOGIC
# ==============================================================================
# Purpose:
#   Detect shot boundaries and safely reset or re-seed grain state so temporal
#   history does NOT leak across cuts, fades, or hard transitions.
#
# Cinematic relevance:
#   - Prevents grain “ghost memory” across edits
#   - Ensures each shot has its own organic grain evolution
#   - Mandatory for professional editing and mastering pipelines
#
# Runs AFTER:
#   - 84 F 05 (Grain Temporal Drift Suppression)
# ==============================================================================
import numpy as np
def detect_shot_boundary(
    prev_frame_luma: np.ndarray,
    curr_frame_luma: np.ndarray,
    threshold: float = 0.25,
    eps: float = 1e-6
) -> bool:
    """
    Detects a shot boundary based on luminance histogram divergence.
    Parameters:
        prev_frame_luma:
            Luminance of previous frame
        curr_frame_luma:
            Luminance of current frame
        threshold:
            Divergence threshold indicating a cut
        eps:
            Numerical stability epsilon
    Returns:
        True if shot boundary detected
    """
    if prev_frame_luma is None:
        return False
    # Normalize luminance
    a = prev_frame_luma.flatten()
    b = curr_frame_luma.flatten()
    a /= (np.mean(a) + eps)
    b /= (np.mean(b) + eps)
    # Histogram-based divergence (simple but robust)
    hist_a, _ = np.histogram(a, bins=64, range=(0.0, 1.0), density=True)
    hist_b, _ = np.histogram(b, bins=64, range=(0.0, 1.0), density=True)
    divergence = np.mean(np.abs(hist_a - hist_b))
    return divergence > threshold
def reset_grain_state_on_cut(
    grain_field: np.ndarray,
    shot_boundary_detected: bool,
    reseed_strength: float = 1.0
) -> np.ndarray:
    """
    Resets or re-seeds grain state when a shot boundary is detected.
    Parameters:
        grain_field:
            Current grain field
        shot_boundary_detected:
            Boolean indicating cut
        reseed_strength:
            Degree of reseeding (1.0 = full reset)
    Returns:
        Updated grain field
    """
    if not shot_boundary_detected:
        return grain_field
    reseed_strength = np.clip(reseed_strength, 0.0, 1.0)
    # Fresh stochastic seed
    noise = np.random.normal(
        loc=0.0,
        scale=1.0,
        size=grain_field.shape
    ).astype(np.float32)
    grain_out = (
        reseed_strength * noise +
        (1.0 - reseed_strength) * grain_field
    )
    return grain_out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_shot_boundary(
    grain_field: np.ndarray,
    prev_luma: np.ndarray,
    curr_luma: np.ndarray,
    config: dict
) -> tuple[np.ndarray, bool]:
    """
    Detects shot boundaries and resets grain state if needed.
    """
    cut = detect_shot_boundary(
        prev_frame_luma=prev_luma,
        curr_frame_luma=curr_luma,
        threshold=config.get("threshold", 0.25),
        eps=config.get("eps", 1e-6)
    )
    grain_out = reset_grain_state_on_cut(
        grain_field=grain_field,
        shot_boundary_detected=cut,
        reseed_strength=config.get("reseed_strength", 1.0)
    )
    return grain_out, cut
# ==============================================================================
# END OF SUBCHUNK 84 F 06 — GRAIN SHOT BOUNDARY RESET LOGIC
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 G 01 — GRAIN & MOTION BLUR INTERACTION
# ==============================================================================
# Purpose:
#   Modulate grain strength and frequency response based on motion blur amount
#   so grain integrates physically with exposure-induced blur rather than
#   floating independently.
#
# Cinematic relevance:
#   - Prevents grain from overpowering motion blur
#   - Preserves exposure realism during fast fly-throughs
#   - Essential for high-speed drone passes and low-shutter shots
#
# Runs AFTER:
#   - 84 F 06 (Grain Shot Boundary Reset Logic)
# ==============================================================================
import numpy as np
def compute_motion_blur_strength(
    motion_vectors: np.ndarray,
    shutter_scale: float = 1.0,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Estimates motion blur strength from optical flow magnitude and shutter scale.
    Parameters:
        motion_vectors:
            Optical flow vectors (H, W, 2)
        shutter_scale:
            Exposure/shutter influence scale
        eps:
            Numerical stability epsilon
    Returns:
        Motion blur strength map in [0,1]
    """
    if motion_vectors is None:
        return None
    mag = np.sqrt(
        motion_vectors[..., 0] ** 2 +
        motion_vectors[..., 1] ** 2
    )
    mag = mag * shutter_scale
    mag /= (np.max(mag) + eps)
    return np.clip(mag, 0.0, 1.0)
def apply_grain_motion_blur_coupling(
    grain_field: np.ndarray,
    blur_strength: np.ndarray,
    attenuation_strength: float = 0.7
) -> np.ndarray:
    """
    Attenuates grain proportionally to motion blur strength.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        blur_strength:
            Motion blur strength map (H, W)
        attenuation_strength:
            How strongly blur suppresses grain
    Returns:
        Motion-blur-aware grain field
    """
    if blur_strength is None:
        return grain_field
    attenuation_strength = np.clip(attenuation_strength, 0.0, 1.0)
    attenuation = 1.0 - attenuation_strength * blur_strength
    if grain_field.ndim == 3:
        attenuation = attenuation[..., None]
    return grain_field * attenuation
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_motion_blur_interaction(
    grain_field: np.ndarray,
    motion_vectors: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies motion-blur-aware grain interaction.
    """
    blur_strength = compute_motion_blur_strength(
        motion_vectors=motion_vectors,
        shutter_scale=config.get("shutter_scale", 1.0),
        eps=config.get("eps", 1e-6)
    )
    return apply_grain_motion_blur_coupling(
        grain_field=grain_field,
        blur_strength=blur_strength,
        attenuation_strength=config.get("attenuation_strength", 0.7)
    )
# ==============================================================================
# END OF SUBCHUNK 84 G 01 — GRAIN & MOTION BLUR INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 G 02 — GRAIN VS OPTICAL FLOW OCCLUSION MASK
# ==============================================================================
# Purpose:
#   Suppress or decorrelate grain in regions undergoing occlusion or
#   disocclusion as detected by optical flow divergence.
#
# Cinematic relevance:
#   - Prevents grain “tearing” at motion edges
#   - Eliminates ghost-grain in parallax transitions
#   - Critical for low-altitude flybys and fast lateral motion
#
# Runs AFTER:
#   - 84 G 01 (Grain & Motion Blur Interaction)
# ==============================================================================
import numpy as np
def compute_flow_divergence(
    flow: np.ndarray,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Computes divergence of optical flow to detect occlusion regions.
    Parameters:
        flow:
            Optical flow field (H, W, 2)
        eps:
            Numerical stability epsilon
    Returns:
        Divergence map (H, W)
    """
    if flow is None:
        return None
    fx = flow[..., 0]
    fy = flow[..., 1]
    dfx_dx = np.gradient(fx, axis=1)
    dfy_dy = np.gradient(fy, axis=0)
    divergence = dfx_dx + dfy_dy
    return np.abs(divergence)
def generate_occlusion_mask(
    divergence: np.ndarray,
    threshold: float = 0.15
) -> np.ndarray:
    """
    Generates an occlusion mask from flow divergence.
    Parameters:
        divergence:
            Divergence magnitude map
        threshold:
            Occlusion sensitivity threshold
    Returns:
        Occlusion mask in [0,1]
    """
    if divergence is None:
        return None
    mask = divergence / (np.max(divergence) + 1e-6)
    mask = np.clip(mask, 0.0, 1.0)
    return np.clip(mask / threshold, 0.0, 1.0)
def apply_grain_occlusion_mask(
    grain_field: np.ndarray,
    occlusion_mask: np.ndarray,
    suppression_strength: float = 0.8
) -> np.ndarray:
    """
    Suppresses grain in occluded or disoccluded regions.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        occlusion_mask:
            Occlusion strength map
        suppression_strength:
            Grain suppression strength in occlusions
    Returns:
        Occlusion-aware grain field
    """
    if occlusion_mask is None:
        return grain_field
    suppression_strength = np.clip(suppression_strength, 0.0, 1.0)
    attenuation = 1.0 - suppression_strength * occlusion_mask
    if grain_field.ndim == 3:
        attenuation = attenuation[..., None]
    return grain_field * attenuation
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_occlusion_interaction(
    grain_field: np.ndarray,
    optical_flow: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies occlusion-aware grain suppression.
    """
    divergence = compute_flow_divergence(
        flow=optical_flow,
        eps=config.get("eps", 1e-6)
    )
    mask = generate_occlusion_mask(
        divergence=divergence,
        threshold=config.get("threshold", 0.15)
    )
    return apply_grain_occlusion_mask(
        grain_field=grain_field,
        occlusion_mask=mask,
        suppression_strength=config.get("suppression_strength", 0.8)
    )
# ==============================================================================
# END OF SUBCHUNK 84 G 02 — GRAIN VS OPTICAL FLOW OCCLUSION MASK
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 G 03 — GRAIN DEPTH-OF-FIELD INTERACTION
# ==============================================================================
# Purpose:
#   Modulate grain amplitude and spatial frequency based on depth-of-field
#   characteristics so grain behaves as an optical property of the image
#   formation process, not a flat overlay.
#
# Cinematic relevance:
#   - Prevents sharp grain in defocused regions
#   - Preserves lens realism during rack focus
#   - Critical for large-sensor cinematic look emulation
#
# Runs AFTER:
#   - 84 G 02 (Grain vs Optical Flow Occlusion Mask)
# ==============================================================================
import numpy as np
def compute_dof_blur_map(
    depth_map: np.ndarray,
    focus_distance: float,
    aperture: float,
    max_blur: float = 1.0,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Estimates per-pixel defocus strength based on depth difference.
    Parameters:
        depth_map:
            Scene depth map (normalized or metric)
        focus_distance:
            Focus plane distance
        aperture:
            Effective aperture (f-number proxy)
        max_blur:
            Maximum normalized blur strength
        eps:
            Numerical stability epsilon
    Returns:
        Depth-of-field blur strength map in [0,1]
    """
    if depth_map is None:
        return None
    # Defocus proportional to distance from focus plane
    defocus = np.abs(depth_map - focus_distance)
    # Aperture increases blur non-linearly
    blur = defocus * (aperture + eps)
    blur /= (np.max(blur) + eps)
    return np.clip(blur * max_blur, 0.0, 1.0)
def attenuate_grain_for_dof(
    grain_field: np.ndarray,
    dof_blur: np.ndarray,
    suppression_strength: float = 0.85
) -> np.ndarray:
    """
    Suppresses high-frequency grain in defocused regions.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        dof_blur:
            Defocus strength map
        suppression_strength:
            How strongly defocus suppresses grain
    Returns:
        DoF-aware grain field
    """
    if dof_blur is None:
        return grain_field
    suppression_strength = np.clip(suppression_strength, 0.0, 1.0)
    attenuation = 1.0 - suppression_strength * dof_blur
    if grain_field.ndim == 3:
        attenuation = attenuation[..., None]
    return grain_field * attenuation
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_depth_of_field_interaction(
    grain_field: np.ndarray,
    depth_map: np.ndarray,
    focus_distance: float,
    aperture: float,
    config: dict
) -> np.ndarray:
    """
    Applies depth-of-field-aware grain modulation.
    """
    dof_blur = compute_dof_blur_map(
        depth_map=depth_map,
        focus_distance=focus_distance,
        aperture=aperture,
        max_blur=config.get("max_blur", 1.0),
        eps=config.get("eps", 1e-6)
    )
    return attenuate_grain_for_dof(
        grain_field=grain_field,
        dof_blur=dof_blur,
        suppression_strength=config.get("suppression_strength", 0.85)
    )
# ==============================================================================
# END OF SUBCHUNK 84 G 03 — GRAIN DEPTH-OF-FIELD INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 G 04 — GRAIN BOKEH RESPONSE COUPLING
# ==============================================================================
# Purpose:
#   Couple grain response to bokeh (out-of-focus highlights) so grain does not
#   contaminate blur discs and instead respects optical energy distribution.
#
# Cinematic relevance:
#   - Prevents noisy bokeh balls in defocused highlights
#   - Preserves clean, creamy cinematic bokeh
#   - Critical for night scenes, specular highlights, and cityscapes
#
# Runs AFTER:
#   - 84 G 03 (Grain Depth-of-Field Interaction)
# ==============================================================================
import numpy as np
def detect_bokeh_regions(
    luminance: np.ndarray,
    dof_blur: np.ndarray,
    highlight_threshold: float = 0.85,
    blur_threshold: float = 0.4
) -> np.ndarray:
    """
    Detects bokeh-prone regions based on highlight intensity and defocus.
    Parameters:
        luminance:
            Luminance channel (H, W)
        dof_blur:
            Defocus strength map (H, W)
        highlight_threshold:
            Luminance threshold for specular highlights
        blur_threshold:
            Minimum defocus required for bokeh formation
    Returns:
        Bokeh mask in [0,1]
    """
    if luminance is None or dof_blur is None:
        return None
    lum_norm = luminance / (np.max(luminance) + 1e-6)
    highlight_mask = np.clip(
        (lum_norm - highlight_threshold) / (1.0 - highlight_threshold),
        0.0,
        1.0
    )
    blur_mask = np.clip(
        (dof_blur - blur_threshold) / (1.0 - blur_threshold),
        0.0,
        1.0
    )
    return highlight_mask * blur_mask
def suppress_grain_in_bokeh(
    grain_field: np.ndarray,
    bokeh_mask: np.ndarray,
    suppression_strength: float = 0.9
) -> np.ndarray:
    """
    Suppresses grain contribution inside bokeh regions.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        bokeh_mask:
            Bokeh region mask
        suppression_strength:
            Degree of grain suppression in bokeh
    Returns:
        Bokeh-aware grain field
    """
    if bokeh_mask is None:
        return grain_field
    suppression_strength = np.clip(suppression_strength, 0.0, 1.0)
    attenuation = 1.0 - suppression_strength * bokeh_mask
    if grain_field.ndim == 3:
        attenuation = attenuation[..., None]
    return grain_field * attenuation
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_bokeh_response(
    grain_field: np.ndarray,
    luminance: np.ndarray,
    dof_blur: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies bokeh-aware grain suppression.
    """
    bokeh_mask = detect_bokeh_regions(
        luminance=luminance,
        dof_blur=dof_blur,
        highlight_threshold=config.get("highlight_threshold", 0.85),
        blur_threshold=config.get("blur_threshold", 0.4)
    )
    return suppress_grain_in_bokeh(
        grain_field=grain_field,
        bokeh_mask=bokeh_mask,
        suppression_strength=config.get("suppression_strength", 0.9)
    )
# ==============================================================================
# END OF SUBCHUNK 84 G 04 — GRAIN BOKEH RESPONSE COUPLING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 G 05 — GRAIN FOCUS PULL ADAPTATION
# ==============================================================================
# Purpose:
#   Adapt grain temporal and spatial behavior during dynamic focus pulls so
#   grain evolves smoothly with shifting focus planes rather than popping.
#
# Cinematic relevance:
#   - Prevents grain popping during rack focus
#   - Maintains optical continuity in cinematic focus transitions
#   - Critical for shallow-DoF drone cinematography
#
# Runs AFTER:
#   - 84 G 04 (Grain Bokeh Response Coupling)
# ==============================================================================
import numpy as np
def compute_focus_pull_velocity(
    prev_focus_distance: float,
    curr_focus_distance: float,
    eps: float = 1e-6
) -> float:
    """
    Computes normalized focus pull velocity.
    Parameters:
        prev_focus_distance:
            Previous frame focus distance
        curr_focus_distance:
            Current frame focus distance
    Returns:
        Normalized focus pull velocity
    """
    delta = np.abs(curr_focus_distance - prev_focus_distance)
    return delta / (np.abs(prev_focus_distance) + eps)
def adapt_grain_for_focus_pull(
    grain_field: np.ndarray,
    focus_velocity: float,
    max_smoothing: float = 0.6
) -> np.ndarray:
    """
    Smooths grain evolution during rapid focus pulls.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        focus_velocity:
            Normalized focus pull velocity
        max_smoothing:
            Maximum temporal smoothing applied
    Returns:
        Focus-pull-adapted grain field
    """
    smoothing = np.clip(focus_velocity, 0.0, 1.0) * max_smoothing
    # Low-pass filter grain spatially during rapid focus change
    kernel_size = int(1 + 4 * smoothing)
    if kernel_size % 2 == 0:
        kernel_size += 1
    if kernel_size <= 1:
        return grain_field
    pad = kernel_size // 2
    padded = np.pad(grain_field, ((pad, pad), (pad, pad)), mode="reflect")
    out = np.zeros_like(grain_field)
    for y in range(grain_field.shape[0]):
        for x in range(grain_field.shape[1]):
            region = padded[y:y + kernel_size, x:x + kernel_size]
            out[y, x] = np.mean(region)
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_focus_pull_adaptation(
    grain_field: np.ndarray,
    prev_focus_distance: float,
    curr_focus_distance: float,
    config: dict
) -> np.ndarray:
    """
    Applies focus-pull-aware grain adaptation.
    """
    velocity = compute_focus_pull_velocity(
        prev_focus_distance=prev_focus_distance,
        curr_focus_distance=curr_focus_distance,
        eps=config.get("eps", 1e-6)
    )
    return adapt_grain_for_focus_pull(
        grain_field=grain_field,
        focus_velocity=velocity,
        max_smoothing=config.get("max_smoothing", 0.6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 G 05 — GRAIN FOCUS PULL ADAPTATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 G 06 — GRAIN APERTURE DYNAMICS RESPONSE
# ==============================================================================
# Purpose:
#   Adapt grain behavior dynamically to aperture (f-stop) changes so grain
#   density, contrast, and spatial coherence track real optical exposure shifts.
#
# Cinematic relevance:
#   - Prevents grain pumping during iris ramps
#   - Preserves exposure-to-texture consistency
#   - Critical for auto-exposure and AI-driven aperture control
#
# Runs AFTER:
#   - 84 G 05 (Grain Focus Pull Adaptation)
# ==============================================================================
import numpy as np
def compute_aperture_exposure_factor(
    prev_aperture: float,
    curr_aperture: float,
    eps: float = 1e-6
) -> float:
    """
    Computes exposure factor induced by aperture change.
    Parameters:
        prev_aperture:
            Previous f-number
        curr_aperture:
            Current f-number
    Returns:
        Normalized exposure change factor
    """
    prev_energy = 1.0 / (prev_aperture ** 2 + eps)
    curr_energy = 1.0 / (curr_aperture ** 2 + eps)
    return curr_energy / (prev_energy + eps)
def adapt_grain_for_aperture(
    grain_field: np.ndarray,
    exposure_factor: float,
    contrast_compensation: float = 0.5
) -> np.ndarray:
    """
    Adjusts grain amplitude based on aperture-induced exposure changes.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        exposure_factor:
            Relative exposure change from aperture shift
        contrast_compensation:
            Degree to counteract exposure amplification
    Returns:
        Aperture-aware grain field
    """
    exposure_factor = np.clip(exposure_factor, 0.25, 4.0)
    # Grain scales sub-linearly with exposure
    gain = exposure_factor ** 0.5
    compensated = grain_field * gain
    # Contrast compensation to prevent harsh grain
    mean = np.mean(compensated)
    compensated = (
        mean +
        (compensated - mean) * (1.0 - contrast_compensation)
    )
    return compensated
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_aperture_dynamics(
    grain_field: np.ndarray,
    prev_aperture: float,
    curr_aperture: float,
    config: dict
) -> np.ndarray:
    """
    Applies aperture-dynamics-aware grain modulation.
    """
    exposure_factor = compute_aperture_exposure_factor(
        prev_aperture=prev_aperture,
        curr_aperture=curr_aperture,
        eps=config.get("eps", 1e-6)
    )
    return adapt_grain_for_aperture(
        grain_field=grain_field,
        exposure_factor=exposure_factor,
        contrast_compensation=config.get("contrast_compensation", 0.5)
    )
# ==============================================================================
# END OF SUBCHUNK 84 G 06 — GRAIN APERTURE DYNAMICS RESPONSE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 G 07 — GRAIN ZOOM BREATHING INTERACTION
# ==============================================================================
# Purpose:
#   Adjust grain spatial frequency and amplitude in response to zoom breathing
#   so grain remains optically locked to image scale during focal length changes.
#
# Cinematic relevance:
#   - Prevents grain “swimming” during zooms
#   - Maintains perceived film plane consistency
#   - Critical for dolly-zoom, push-ins, and cinematic zoom transitions
#
# Runs AFTER:
#   - 84 G 06 (Grain Aperture Dynamics Response)
# ==============================================================================
import numpy as np
def compute_zoom_breathing_factor(
    prev_focal_length: float,
    curr_focal_length: float,
    eps: float = 1e-6
) -> float:
    """
    Computes normalized zoom breathing factor.
    Parameters:
        prev_focal_length:
            Previous focal length (mm or normalized)
        curr_focal_length:
            Current focal length
    Returns:
        Zoom scale factor
    """
    return curr_focal_length / (prev_focal_length + eps)
def adapt_grain_for_zoom(
    grain_field: np.ndarray,
    zoom_factor: float,
    frequency_compensation: float = 0.75
) -> np.ndarray:
    """
    Adjusts grain spatial scale for zoom breathing.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        zoom_factor:
            Relative zoom change
        frequency_compensation:
            Degree of spatial frequency compensation
    Returns:
        Zoom-aware grain field
    """
    zoom_factor = np.clip(zoom_factor, 0.5, 2.0)
    # Effective grain frequency adjustment
    freq_scale = zoom_factor ** frequency_compensation
    h, w = grain_field.shape[:2]
    new_h = max(1, int(h / freq_scale))
    new_w = max(1, int(w / freq_scale))
    # Simple resample to adjust spatial frequency
    scaled = grain_field[
        ::max(1, int(freq_scale)),
        ::max(1, int(freq_scale))
    ]
    # Pad or crop back to original size
    out = np.zeros_like(grain_field)
    out[:scaled.shape[0], :scaled.shape[1]] = scaled
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_zoom_breathing(
    grain_field: np.ndarray,
    prev_focal_length: float,
    curr_focal_length: float,
    config: dict
) -> np.ndarray:
    """
    Applies zoom-breathing-aware grain adaptation.
    """
    zoom_factor = compute_zoom_breathing_factor(
        prev_focal_length=prev_focal_length,
        curr_focal_length=curr_focal_length,
        eps=config.get("eps", 1e-6)
    )
    return adapt_grain_for_zoom(
        grain_field=grain_field,
        zoom_factor=zoom_factor,
        frequency_compensation=config.get("frequency_compensation", 0.75)
    )
# ==============================================================================
# END OF SUBCHUNK 84 G 07 — GRAIN ZOOM BREATHING INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 G 08 — GRAIN LENS ABERRATION COUPLING
# ==============================================================================
# Purpose:
#   Couple grain behavior to lens aberrations (chromatic, spherical, coma)
#   so grain follows optical energy redistribution instead of remaining uniform.
#
# Cinematic relevance:
#   - Prevents edge grain mismatch in wide lenses
#   - Preserves organic falloff toward frame edges
#   - Essential for anamorphic and fast spherical lens emulation
#
# Runs AFTER:
#   - 84 G 07 (Grain Zoom Breathing Interaction)
# ==============================================================================
import numpy as np
def compute_aberration_energy_map(
    radial_distance: np.ndarray,
    chroma_aberration: float,
    spherical_aberration: float
) -> np.ndarray:
    """
    Computes optical energy redistribution caused by lens aberrations.
    Parameters:
        radial_distance:
            Normalized distance from optical center (0–1)
        chroma_aberration:
            Chromatic aberration strength
        spherical_aberration:
            Spherical aberration strength
    Returns:
        Aberration energy modulation map
    """
    chroma_term = 1.0 - chroma_aberration * radial_distance
    spherical_term = 1.0 - spherical_aberration * (radial_distance ** 2)
    energy = chroma_term * spherical_term
    return np.clip(energy, 0.5, 1.2)
def adapt_grain_for_aberration(
    grain_field: np.ndarray,
    energy_map: np.ndarray
) -> np.ndarray:
    """
    Modulates grain amplitude according to aberration-induced energy changes.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        energy_map:
            Aberration energy modulation map
    Returns:
        Aberration-aware grain field
    """
    if grain_field.ndim == 3:
        energy_map = energy_map[..., None]
    return grain_field * energy_map
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_lens_aberration_coupling(
    grain_field: np.ndarray,
    radial_distance: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies lens-aberration-aware grain modulation.
    """
    energy_map = compute_aberration_energy_map(
        radial_distance=radial_distance,
        chroma_aberration=config.get("chroma_aberration", 0.08),
        spherical_aberration=config.get("spherical_aberration", 0.12)
    )
    return adapt_grain_for_aberration(
        grain_field=grain_field,
        energy_map=energy_map
    )
# ==============================================================================
# END OF SUBCHUNK 84 G 08 — GRAIN LENS ABERRATION COUPLING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 G 09 — GRAIN SENSOR MICROLENS INTERACTION
# ==============================================================================
# Purpose:
#   Modulate grain response based on sensor microlens angular efficiency and
#   off-axis light falloff so grain reflects real sensor photon behavior.
#
# Cinematic relevance:
#   - Prevents flat digital grain appearance
#   - Mimics cinema sensor angular response (ARRI/RED-like)
#   - Critical for wide lenses and off-axis highlights
#
# Runs AFTER:
#   - 84 G 08 (Grain Lens Aberration Coupling)
# ==============================================================================
import numpy as np
def compute_microlens_efficiency(
    incident_angle: np.ndarray,
    acceptance_angle: float = 25.0
) -> np.ndarray:
    """
    Computes microlens photon efficiency based on incident angle.
    Parameters:
        incident_angle:
            Per-pixel incident light angle (degrees)
        acceptance_angle:
            Microlens acceptance half-angle (degrees)
    Returns:
        Efficiency map in [0,1]
    """
    angle_norm = np.abs(incident_angle) / max(acceptance_angle, 1e-6)
    efficiency = np.cos(np.clip(angle_norm, 0.0, 1.0) * np.pi * 0.5)
    return np.clip(efficiency, 0.0, 1.0)
def apply_microlens_grain_modulation(
    grain_field: np.ndarray,
    efficiency_map: np.ndarray,
    strength: float = 0.6
) -> np.ndarray:
    """
    Modulates grain amplitude based on microlens efficiency.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        efficiency_map:
            Microlens efficiency map
        strength:
            Modulation strength
    Returns:
        Microlens-aware grain field
    """
    strength = np.clip(strength, 0.0, 1.0)
    modulation = 1.0 - strength * (1.0 - efficiency_map)
    if grain_field.ndim == 3:
        modulation = modulation[..., None]
    return grain_field * modulation
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_sensor_microlens(
    grain_field: np.ndarray,
    incident_angle: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies sensor microlens-aware grain modulation.
    """
    efficiency = compute_microlens_efficiency(
        incident_angle=incident_angle,
        acceptance_angle=config.get("acceptance_angle", 25.0)
    )
    return apply_microlens_grain_modulation(
        grain_field=grain_field,
        efficiency_map=efficiency,
        strength=config.get("strength", 0.6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 G 09 — GRAIN SENSOR MICROLENS INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 G 10 — GRAIN FINAL OPTICAL ENERGY NORMALIZATION
# ==============================================================================
# Purpose:
#   Re-normalize grain energy after all optical, temporal, and sensor-domain
#   interactions so perceived grain density remains stable and filmic.
#
# Cinematic relevance:
#   - Prevents grain “gain creep” across complex shots
#   - Ensures consistent texture density shot-to-shot
#   - Mandatory for mastering-level image stability
#
# Runs AFTER:
#   - 84 G 09 (Grain Sensor Microlens Interaction)
# ==============================================================================
import numpy as np
def normalize_grain_energy(
    grain_field: np.ndarray,
    reference_energy: float,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Normalizes grain RMS energy to a reference level.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        reference_energy:
            Target RMS energy
        eps:
            Numerical stability epsilon
    Returns:
        Energy-normalized grain field
    """
    if reference_energy is None:
        return grain_field
    current_energy = np.sqrt(np.mean(grain_field ** 2) + eps)
    scale = reference_energy / (current_energy + eps)
    return grain_field * scale
def compute_reference_grain_energy(
    grain_field: np.ndarray
) -> float:
    """
    Computes reference grain energy from an initial stable state.
    Parameters:
        grain_field:
            Grain field
    Returns:
        RMS grain energy
    """
    return float(np.sqrt(np.mean(grain_field ** 2)))
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_final_energy_normalization(
    grain_field: np.ndarray,
    reference_energy: float,
    config: dict
) -> np.ndarray:
    """
    Applies final grain energy normalization.
    """
    return normalize_grain_energy(
        grain_field=grain_field,
        reference_energy=reference_energy,
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 G 10 — GRAIN FINAL OPTICAL ENERGY NORMALIZATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 H 01 — GRAIN VS ROLLING SHUTTER INTERACTION
# ==============================================================================
# Purpose:
#   Couple grain temporal phase and amplitude to rolling shutter readout so
#   grain follows scanline-wise exposure timing instead of appearing globally
#   synchronized.
#
# Cinematic relevance:
#   - Prevents grain shear during fast yaw/pan
#   - Preserves sensor-authentic motion texture
#   - Critical for CMOS-based drone cameras
#
# Runs AFTER:
#   - 84 G 10 (Grain Final Optical Energy Normalization)
# ==============================================================================
import numpy as np
def compute_scanline_time_offsets(
    height: int,
    readout_time_ms: float,
    direction: str = "top_to_bottom"
) -> np.ndarray:
    """
    Computes per-scanline temporal offsets caused by rolling shutter.
    Parameters:
        height:
            Frame height in pixels
        readout_time_ms:
            Total sensor readout time in milliseconds
        direction:
            Readout direction ('top_to_bottom' or 'bottom_to_top')
    Returns:
        Time offset per scanline (ms)
    """
    offsets = np.linspace(0.0, readout_time_ms, height, dtype=np.float32)
    if direction == "bottom_to_top":
        offsets = offsets[::-1]
    return offsets
def apply_rolling_shutter_grain_phase(
    grain_field: np.ndarray,
    scanline_offsets: np.ndarray,
    phase_strength: float = 0.6
) -> np.ndarray:
    """
    Applies scanline-wise phase shifts to grain based on rolling shutter timing.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        scanline_offsets:
            Per-scanline temporal offsets
        phase_strength:
            Strength of phase modulation
    Returns:
        Rolling-shutter-aware grain field
    """
    h = grain_field.shape[0]
    phase_strength = np.clip(phase_strength, 0.0, 1.0)
    out = grain_field.copy()
    for y in range(h):
        phase = np.sin(scanline_offsets[y] * 2.0 * np.pi * 0.001)
        gain = 1.0 + phase_strength * phase
        out[y] *= gain
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_rolling_shutter(
    grain_field: np.ndarray,
    readout_time_ms: float,
    config: dict
) -> np.ndarray:
    """
    Applies rolling-shutter-aware grain modulation.
    """
    scanline_offsets = compute_scanline_time_offsets(
        height=grain_field.shape[0],
        readout_time_ms=readout_time_ms,
        direction=config.get("direction", "top_to_bottom")
    )
    return apply_rolling_shutter_grain_phase(
        grain_field=grain_field,
        scanline_offsets=scanline_offsets,
        phase_strength=config.get("phase_strength", 0.6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 H 01 — GRAIN VS ROLLING SHUTTER INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 H 02 — GRAIN VS CMOS READOUT TIMING
# ==============================================================================
# Purpose:
#   Model non-uniform CMOS readout timing jitter and modulate grain amplitude
#   and phase so grain reflects real sensor temporal sampling behavior.
#
# Cinematic relevance:
#   - Prevents subtle horizontal banding in skies
#   - Eliminates temporal grain phase snapping
#   - Critical for CMOS drone sensors under fast motion
#
# Runs AFTER:
#   - 84 H 01 (Grain vs Rolling Shutter Interaction)
# ==============================================================================
import numpy as np
def generate_cmos_readout_jitter(
    height: int,
    jitter_strength: float = 0.15,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates per-scanline readout timing jitter.
    Parameters:
        height:
            Frame height in pixels
        jitter_strength:
            Relative magnitude of readout timing variation
        seed:
            Optional random seed
    Returns:
        Jitter offsets per scanline
    """
    rng = np.random.default_rng(seed)
    jitter = rng.normal(
        loc=0.0,
        scale=jitter_strength,
        size=height
    ).astype(np.float32)
    # Low-pass filter jitter to match real CMOS behavior
    kernel = np.ones(5, dtype=np.float32) / 5.0
    jitter = np.convolve(jitter, kernel, mode="same")
    return jitter
def apply_cmos_readout_grain_modulation(
    grain_field: np.ndarray,
    jitter: np.ndarray,
    modulation_strength: float = 0.4
) -> np.ndarray:
    """
    Modulates grain amplitude based on CMOS readout timing jitter.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        jitter:
            Per-scanline jitter offsets
        modulation_strength:
            Strength of jitter-induced modulation
    Returns:
        CMOS-readout-aware grain field
    """
    h = grain_field.shape[0]
    modulation_strength = np.clip(modulation_strength, 0.0, 1.0)
    out = grain_field.copy()
    for y in range(h):
        gain = 1.0 + modulation_strength * jitter[y]
        out[y] *= gain
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_cmos_readout_timing(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies CMOS readout timing jitter to grain.
    """
    jitter = generate_cmos_readout_jitter(
        height=grain_field.shape[0],
        jitter_strength=config.get("jitter_strength", 0.15),
        seed=config.get("seed", None)
    )
    return apply_cmos_readout_grain_modulation(
        grain_field=grain_field,
        jitter=jitter,
        modulation_strength=config.get("modulation_strength", 0.4)
    )
# ==============================================================================
# END OF SUBCHUNK 84 H 02 — GRAIN VS CMOS READOUT TIMING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 H 03 — GRAIN SCANLINE PHASE COUPLING
# ==============================================================================
# Purpose:
#   Phase-lock grain evolution along scanlines to CMOS readout timing so
#   grain advances temporally in a physically consistent scanline sequence.
#
# Cinematic relevance:
#   - Eliminates scanline zippering during fast motion
#   - Preserves continuous grain motion during pans and yaw
#   - Essential for rolling-shutter CMOS realism
#
# Runs AFTER:
#   - 84 H 02 (Grain vs CMOS Readout Timing)
# ==============================================================================
import numpy as np
def compute_scanline_phase_offsets(
    scanline_offsets_ms: np.ndarray,
    temporal_frequency: float = 0.75
) -> np.ndarray:
    """
    Converts scanline time offsets into phase offsets.
    Parameters:
        scanline_offsets_ms:
            Per-scanline readout offsets (ms)
        temporal_frequency:
            Grain temporal evolution frequency (Hz)
    Returns:
        Phase offsets per scanline (radians)
    """
    return 2.0 * np.pi * temporal_frequency * (scanline_offsets_ms * 0.001)
def apply_scanline_phase_coupling(
    grain_field: np.ndarray,
    phase_offsets: np.ndarray,
    phase_strength: float = 0.8
) -> np.ndarray:
    """
    Applies scanline-wise phase coupling to grain.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        phase_offsets:
            Phase offsets per scanline
        phase_strength:
            Strength of phase modulation
    Returns:
        Phase-coupled grain field
    """
    h = grain_field.shape[0]
    phase_strength = np.clip(phase_strength, 0.0, 1.0)
    out = grain_field.copy()
    for y in range(h):
        phase = np.sin(phase_offsets[y])
        gain = 1.0 + phase_strength * phase
        out[y] *= gain
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_scanline_phase_coupling(
    grain_field: np.ndarray,
    scanline_offsets_ms: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies scanline phase coupling based on readout timing.
    """
    phase_offsets = compute_scanline_phase_offsets(
        scanline_offsets_ms=scanline_offsets_ms,
        temporal_frequency=config.get("temporal_frequency", 0.75)
    )
    return apply_scanline_phase_coupling(
        grain_field=grain_field,
        phase_offsets=phase_offsets,
        phase_strength=config.get("phase_strength", 0.8)
    )
# ==============================================================================
# END OF SUBCHUNK 84 H 03 — GRAIN SCANLINE PHASE COUPLING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 H 04 — GRAIN READOUT NOISE CORRELATION
# ==============================================================================
# Purpose:
#   Introduce physically plausible correlation between grain and CMOS readout
#   noise so grain appears organically continuous instead of pixel-independent.
#
# Cinematic relevance:
#   - Eliminates digital sparkle in flat gradients
#   - Restores analog-like noise coherence
#   - Critical for skies, walls, fog, and bokeh regions
#
# Runs AFTER:
#   - 84 H 03 (Grain Scanline Phase Coupling)
# ==============================================================================
import numpy as np
def generate_readout_noise_field(
    shape: tuple,
    noise_level: float = 0.03,
    correlation_radius: int = 3,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates correlated readout noise.
    Parameters:
        shape:
            Grain field shape (H, W) or (H, W, C)
        noise_level:
            Base noise amplitude
        correlation_radius:
            Spatial correlation radius (pixels)
        seed:
            Optional RNG seed
    Returns:
        Correlated readout noise field
    """
    rng = np.random.default_rng(seed)
    noise = rng.normal(0.0, noise_level, size=shape).astype(np.float32)
    # Simple separable box blur for correlation
    if correlation_radius > 1:
        kernel = np.ones(correlation_radius, dtype=np.float32)
        kernel /= kernel.sum()
        if noise.ndim == 2:
            noise = np.apply_along_axis(
                lambda m: np.convolve(m, kernel, mode="same"),
                axis=0,
                arr=noise
            )
            noise = np.apply_along_axis(
                lambda m: np.convolve(m, kernel, mode="same"),
                axis=1,
                arr=noise
            )
        else:
            for c in range(noise.shape[2]):
                noise[:, :, c] = np.apply_along_axis(
                    lambda m: np.convolve(m, kernel, mode="same"),
                    axis=0,
                    arr=noise[:, :, c]
                )
                noise[:, :, c] = np.apply_along_axis(
                    lambda m: np.convolve(m, kernel, mode="same"),
                    axis=1,
                    arr=noise[:, :, c]
                )
    return noise
def apply_readout_noise_correlation(
    grain_field: np.ndarray,
    readout_noise: np.ndarray,
    mix_strength: float = 0.5
) -> np.ndarray:
    """
    Mixes correlated readout noise into grain field.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        readout_noise:
            Correlated noise field
        mix_strength:
            Noise-to-grain mix ratio
    Returns:
        Grain field with correlated readout noise
    """
    mix_strength = np.clip(mix_strength, 0.0, 1.0)
    return grain_field + mix_strength * readout_noise
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_readout_noise_correlation(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies correlated readout noise to grain.
    """
    noise = generate_readout_noise_field(
        shape=grain_field.shape,
        noise_level=config.get("noise_level", 0.03),
        correlation_radius=config.get("correlation_radius", 3),
        seed=config.get("seed", None)
    )
    return apply_readout_noise_correlation(
        grain_field=grain_field,
        readout_noise=noise,
        mix_strength=config.get("mix_strength", 0.5)
    )
# ==============================================================================
# END OF SUBCHUNK 84 H 04 — GRAIN READOUT NOISE CORRELATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 H 05 — GRAIN DIRECTIONAL SKEW FROM READOUT
# ==============================================================================
# Purpose:
#   Introduce directionally biased grain skew driven by CMOS readout order
#   and camera motion so grain aligns with real sensor sampling geometry.
#
# Cinematic relevance:
#   - Prevents diagonal “grain drag” artifacts
#   - Preserves organic texture during fast pans/yaw
#   - Critical for drone motion with rolling shutter
#
# Runs AFTER:
#   - 84 H 04 (Grain Readout Noise Correlation)
# ==============================================================================
import numpy as np
def compute_directional_skew_field(
    height: int,
    width: int,
    readout_direction: str = "top_to_bottom",
    motion_vector: tuple = (0.0, 0.0),
    skew_strength: float = 0.35
) -> np.ndarray:
    """
    Computes a directional skew field based on readout direction and motion.
    Parameters:
        height, width:
            Frame dimensions
        readout_direction:
            'top_to_bottom' or 'bottom_to_top'
        motion_vector:
            (dx, dy) normalized camera motion
        skew_strength:
            Overall skew influence
    Returns:
        2D skew gain field (H, W)
    """
    y = np.linspace(-1.0, 1.0, height, dtype=np.float32)
    x = np.linspace(-1.0, 1.0, width, dtype=np.float32)
    yy, xx = np.meshgrid(y, x, indexing="ij")
    dx, dy = motion_vector
    readout_sign = 1.0 if readout_direction == "top_to_bottom" else -1.0
    skew = readout_sign * (yy * dy + xx * dx)
    skew *= skew_strength
    return 1.0 + skew
def apply_directional_skew_to_grain(
    grain_field: np.ndarray,
    skew_field: np.ndarray
) -> np.ndarray:
    """
    Applies directional skew gain to grain field.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        skew_field:
            Directional gain field (H, W)
    Returns:
        Skew-adjusted grain field
    """
    if grain_field.ndim == 2:
        return grain_field * skew_field
    out = grain_field.copy()
    for c in range(out.shape[2]):
        out[:, :, c] *= skew_field
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_directional_skew(
    grain_field: np.ndarray,
    motion_vector: tuple,
    config: dict
) -> np.ndarray:
    """
    Applies readout-driven directional skew to grain.
    """
    skew_field = compute_directional_skew_field(
        height=grain_field.shape[0],
        width=grain_field.shape[1],
        readout_direction=config.get("readout_direction", "top_to_bottom"),
        motion_vector=motion_vector,
        skew_strength=config.get("skew_strength", 0.35)
    )
    return apply_directional_skew_to_grain(
        grain_field=grain_field,
        skew_field=skew_field
    )
# ==============================================================================
# END OF SUBCHUNK 84 H 05 — GRAIN DIRECTIONAL SKEW FROM READOUT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 H 06 — GRAIN EXPOSURE RAMP INTERACTION
# ==============================================================================
# Purpose:
#   Couple grain amplitude and contrast to temporal exposure ramps so grain
#   responds naturally to auto-exposure, shutter, and lighting transitions.
#
# Cinematic relevance:
#   - Prevents grain pumping during exposure shifts
#   - Maintains filmic continuity across lighting changes
#   - Critical for drone shots with dynamic AE / ND
#
# Runs AFTER:
#   - 84 H 05 (Grain Directional Skew from Readout)
# ==============================================================================
import numpy as np
def compute_exposure_ramp_gain(
    exposure_ratio: float,
    response_curve: float = 0.85
) -> float:
    """
    Computes grain gain from exposure change ratio.
    Parameters:
        exposure_ratio:
            Current exposure / reference exposure
        response_curve:
            Nonlinear response shaping (film-like)
    Returns:
        Scalar gain factor
    """
    exposure_ratio = max(exposure_ratio, 1e-6)
    # Film grain grows sublinearly with exposure
    return exposure_ratio ** response_curve
def apply_exposure_ramp_to_grain(
    grain_field: np.ndarray,
    exposure_ratio: float,
    contrast_compensation: float = 0.25
) -> np.ndarray:
    """
    Applies exposure-driven gain and contrast compensation to grain.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        exposure_ratio:
            Exposure ratio vs reference
        contrast_compensation:
            Reduces excessive contrast during ramps
    Returns:
        Exposure-aware grain field
    """
    gain = compute_exposure_ramp_gain(exposure_ratio)
    out = grain_field * gain
    # Contrast compression to avoid harsh pumping
    mean = np.mean(out)
    out = mean + (out - mean) * (1.0 - contrast_compensation)
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_exposure_ramp(
    grain_field: np.ndarray,
    exposure_ratio: float,
    config: dict
) -> np.ndarray:
    """
    Applies exposure ramp interaction to grain.
    """
    return apply_exposure_ramp_to_grain(
        grain_field=grain_field,
        exposure_ratio=exposure_ratio,
        contrast_compensation=config.get("contrast_compensation", 0.25)
    )
# ==============================================================================
# END OF SUBCHUNK 84 H 06 — GRAIN EXPOSURE RAMP INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 H 07 — GRAIN LINE-PAIR TEMPORAL CROSSTALK
# ==============================================================================
# Purpose:
#   Model temporal crosstalk between adjacent scanlines caused by finite
#   charge settling time and shared readout paths in CMOS sensors.
#
# Cinematic relevance:
#   - Eliminates shimmering in fine repeating textures
#   - Preserves organic grain continuity on architectural detail
#   - Essential for drone footage over cities, grids, forests
#
# Runs AFTER:
#   - 84 H 06 (Grain Exposure Ramp Interaction)
# ==============================================================================
import numpy as np
def apply_line_pair_temporal_crosstalk(
    grain_field: np.ndarray,
    crosstalk_strength: float = 0.18
) -> np.ndarray:
    """
    Introduces temporal coupling between adjacent scanlines.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        crosstalk_strength:
            Degree of temporal bleed between neighboring lines
    Returns:
        Crosstalk-aware grain field
    """
    crosstalk_strength = np.clip(crosstalk_strength, 0.0, 0.5)
    out = grain_field.copy()
    if grain_field.ndim == 2:
        out[1:] += crosstalk_strength * grain_field[:-1]
        out[:-1] += crosstalk_strength * grain_field[1:]
    else:
        out[1:, :, :] += crosstalk_strength * grain_field[:-1, :, :]
        out[:-1, :, :] += crosstalk_strength * grain_field[1:, :, :]
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_line_pair_crosstalk(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies scanline line-pair temporal crosstalk to grain.
    """
    return apply_line_pair_temporal_crosstalk(
        grain_field=grain_field,
        crosstalk_strength=config.get("crosstalk_strength", 0.18)
    )
# ==============================================================================
# END OF SUBCHUNK 84 H 07 — GRAIN LINE-PAIR TEMPORAL CROSSTALK
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 H 08 — GRAIN SCANLINE FREQUENCY FOLDING
# ==============================================================================
# Purpose:
#   Suppress and redistribute aliased grain frequencies caused by interaction
#   between grain temporal frequency and scanline readout cadence.
#
# Cinematic relevance:
#   - Prevents high-frequency grain buzzing in skies
#   - Restores analog-continuous texture during motion
#   - Critical for CMOS sensors with fast readout
#
# Runs AFTER:
#   - 84 H 07 (Grain Line-Pair Temporal Crosstalk)
# ==============================================================================
import numpy as np
def compute_frequency_folding_mask(
    height: int,
    fold_strength: float = 0.45
) -> np.ndarray:
    """
    Computes a vertical frequency folding attenuation mask.
    Parameters:
        height:
            Frame height
        fold_strength:
            Strength of frequency attenuation
    Returns:
        Per-scanline attenuation mask
    """
    y = np.linspace(0.0, np.pi, height, dtype=np.float32)
    # Attenuate Nyquist-adjacent components
    mask = 1.0 - fold_strength * np.sin(y) ** 2
    return np.clip(mask, 0.5, 1.0)
def apply_frequency_folding_suppression(
    grain_field: np.ndarray,
    mask: np.ndarray
) -> np.ndarray:
    """
    Applies scanline frequency folding suppression.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        mask:
            Per-scanline attenuation mask
    Returns:
        Frequency-balanced grain field
    """
    out = grain_field.copy()
    if out.ndim == 2:
        out *= mask[:, None]
    else:
        for c in range(out.shape[2]):
            out[:, :, c] *= mask[:, None]
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_frequency_folding(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies scanline frequency folding suppression to grain.
    """
    mask = compute_frequency_folding_mask(
        height=grain_field.shape[0],
        fold_strength=config.get("fold_strength", 0.45)
    )
    return apply_frequency_folding_suppression(
        grain_field=grain_field,
        mask=mask
    )
# ==============================================================================
# END OF SUBCHUNK 84 H 08 — GRAIN SCANLINE FREQUENCY FOLDING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 H 09 — GRAIN READOUT HARMONIC SUPPRESSION
# ==============================================================================
# Purpose:
#   Detect and suppress harmonic resonances between grain temporal evolution
#   and CMOS readout clock to prevent periodic beating artifacts.
#
# Cinematic relevance:
#   - Eliminates faint rhythmic grain pulsing
#   - Stabilizes texture in long takes and slow pans
#   - Essential for skies, fog, dusk, and night scenes
#
# Runs AFTER:
#   - 84 H 08 (Grain Scanline Frequency Folding)
# ==============================================================================
import numpy as np
def compute_harmonic_suppression_curve(
    height: int,
    harmonic_strength: float = 0.55
) -> np.ndarray:
    """
    Builds a per-scanline harmonic suppression curve.
    Parameters:
        height:
            Frame height
        harmonic_strength:
            Suppression intensity
    Returns:
        Suppression curve (H,)
    """
    y = np.linspace(0.0, 2.0 * np.pi, height, dtype=np.float32)
    # Target dominant harmonic lobes
    suppression = 1.0 - harmonic_strength * (
        0.5 * np.sin(y) ** 2 +
        0.5 * np.sin(2.0 * y) ** 2
    )
    return np.clip(suppression, 0.6, 1.0)
def apply_harmonic_suppression(
    grain_field: np.ndarray,
    suppression_curve: np.ndarray
) -> np.ndarray:
    """
    Applies harmonic suppression to grain field.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        suppression_curve:
            Per-scanline suppression factors
    Returns:
        Harmonic-balanced grain field
    """
    out = grain_field.copy()
    if out.ndim == 2:
        out *= suppression_curve[:, None]
    else:
        for c in range(out.shape[2]):
            out[:, :, c] *= suppression_curve[:, None]
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_harmonic_suppression(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies readout harmonic suppression to grain.
    """
    curve = compute_harmonic_suppression_curve(
        height=grain_field.shape[0],
        harmonic_strength=config.get("harmonic_strength", 0.55)
    )
    return apply_harmonic_suppression(
        grain_field=grain_field,
        suppression_curve=curve
    )
# ==============================================================================
# END OF SUBCHUNK 84 H 09 — GRAIN READOUT HARMONIC SUPPRESSION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 H 10 — GRAIN ROLLING-SHUTTER ENERGY REBALANCE
# ==============================================================================
# Purpose:
#   Rebalance grain energy after all rolling-shutter-induced distortions so
#   cumulative scanline, phase, harmonic, and exposure effects do not bias
#   perceived grain density over time.
#
# Cinematic relevance:
#   - Prevents slow grain thickening/thinning in long takes
#   - Maintains exposure-consistent texture across pans and yaw
#   - Required for mastering-grade stability
#
# Runs AFTER:
#   - 84 H 09 (Grain Readout Harmonic Suppression)
# ==============================================================================
import numpy as np
def compute_grain_energy(grain_field: np.ndarray, eps: float = 1e-6) -> float:
    """
    Computes RMS energy of grain field.
    """
    return float(np.sqrt(np.mean(grain_field ** 2) + eps))
def rebalance_rolling_shutter_grain_energy(
    grain_field: np.ndarray,
    reference_energy: float,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Scales grain to restore reference energy after rolling-shutter processing.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        reference_energy:
            Baseline grain RMS energy
    Returns:
        Energy-rebalanced grain field
    """
    current_energy = compute_grain_energy(grain_field, eps)
    if current_energy < eps:
        return grain_field
    scale = reference_energy / current_energy
    return grain_field * scale
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_rolling_shutter_rebalance(
    grain_field: np.ndarray,
    reference_energy: float,
    config: dict
) -> np.ndarray:
    """
    Applies final rolling-shutter energy rebalance to grain.
    """
    return rebalance_rolling_shutter_grain_energy(
        grain_field=grain_field,
        reference_energy=reference_energy,
        eps=config.get("eps", 1e-6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 H 10 — GRAIN ROLLING-SHUTTER ENERGY REBALANCE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 I 01 — GRAIN VS MOTION BLUR PHASE COUPLING
# ==============================================================================
# Purpose:
#   Phase-lock grain evolution to motion blur integration so grain smears
#   coherently with optical and motion-induced blur instead of floating.
#
# Cinematic relevance:
#   - Eliminates floating grain during fast motion
#   - Restores analog film blur–grain coherence
#   - Critical for drone pans, yaw, fast fly-throughs
#
# Runs AFTER:
#   - 84 H 10 (Grain Rolling-Shutter Energy Rebalance)
# ==============================================================================
import numpy as np
def compute_motion_blur_phase(
    motion_vector: tuple,
    blur_length_px: float
) -> float:
    """
    Computes phase offset induced by motion blur direction and magnitude.
    Parameters:
        motion_vector:
            Normalized motion vector (dx, dy)
        blur_length_px:
            Effective blur length in pixels
    Returns:
        Phase offset (radians)
    """
    dx, dy = motion_vector
    magnitude = np.sqrt(dx * dx + dy * dy)
    return 2.0 * np.pi * magnitude * blur_length_px * 0.01
def apply_motion_blur_phase_to_grain(
    grain_field: np.ndarray,
    phase_offset: float,
    phase_strength: float = 0.75
) -> np.ndarray:
    """
    Applies motion-blur-driven phase modulation to grain.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        phase_offset:
            Phase offset in radians
        phase_strength:
            Strength of phase coupling
    Returns:
        Motion-blur-coupled grain field
    """
    phase_strength = np.clip(phase_strength, 0.0, 1.0)
    phase = np.sin(phase_offset)
    gain = 1.0 + phase_strength * phase
    return grain_field * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_motion_blur_phase(
    grain_field: np.ndarray,
    motion_vector: tuple,
    blur_length_px: float,
    config: dict
) -> np.ndarray:
    """
    Applies motion-blur phase coupling to grain.
    """
    phase_offset = compute_motion_blur_phase(
        motion_vector=motion_vector,
        blur_length_px=blur_length_px
    )
    return apply_motion_blur_phase_to_grain(
        grain_field=grain_field,
        phase_offset=phase_offset,
        phase_strength=config.get("phase_strength", 0.75)
    )
# ==============================================================================
# END OF SUBCHUNK 84 I 01 — GRAIN VS MOTION BLUR PHASE COUPLING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 I 02 — GRAIN DIRECTIONAL SMEAR COMPENSATION
# ==============================================================================
# Purpose:
#   Compensate grain shape and intensity along motion direction so grain
#   smears coherently with motion blur instead of stretching unnaturally.
#
# Cinematic relevance:
#   - Prevents directional grain dragging
#   - Preserves natural texture flow in fast fly-throughs
#   - Essential for cinematic drone strafes and orbits
#
# Runs AFTER:
#   - 84 I 01 (Grain vs Motion Blur Phase Coupling)
# ==============================================================================
import numpy as np
def compute_directional_smear_gain(
    motion_vector: tuple,
    smear_strength: float = 0.6
) -> tuple:
    """
    Computes directional smear gains along and across motion.
    Parameters:
        motion_vector:
            Normalized motion vector (dx, dy)
        smear_strength:
            Strength of smear compensation
    Returns:
        (parallel_gain, perpendicular_gain)
    """
    dx, dy = motion_vector
    magnitude = np.sqrt(dx * dx + dy * dy) + 1e-6
    parallel_gain = 1.0 - smear_strength * magnitude
    perpendicular_gain = 1.0 + smear_strength * magnitude * 0.5
    return parallel_gain, perpendicular_gain
def apply_directional_smear_compensation(
    grain_field: np.ndarray,
    motion_vector: tuple,
    smear_strength: float = 0.6
) -> np.ndarray:
    """
    Applies directional smear compensation to grain field.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        motion_vector:
            Normalized motion vector
        smear_strength:
            Compensation strength
    Returns:
        Smear-compensated grain field
    """
    dx, dy = motion_vector
    h, w = grain_field.shape[:2]
    yy, xx = np.meshgrid(
        np.linspace(-1.0, 1.0, h, dtype=np.float32),
        np.linspace(-1.0, 1.0, w, dtype=np.float32),
        indexing="ij"
    )
    parallel, perpendicular = compute_directional_smear_gain(
        motion_vector=motion_vector,
        smear_strength=smear_strength
    )
    # Project pixel directions
    dot = xx * dx + yy * dy
    gain_field = np.where(dot >= 0.0, parallel, perpendicular)
    if grain_field.ndim == 2:
        return grain_field * gain_field
    out = grain_field.copy()
    for c in range(out.shape[2]):
        out[:, :, c] *= gain_field
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_directional_smear(
    grain_field: np.ndarray,
    motion_vector: tuple,
    config: dict
) -> np.ndarray:
    """
    Applies directional smear compensation to grain.
    """
    return apply_directional_smear_compensation(
        grain_field=grain_field,
        motion_vector=motion_vector,
        smear_strength=config.get("smear_strength", 0.6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 I 02 — GRAIN DIRECTIONAL SMEAR COMPENSATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 I 03 — GRAIN VELOCITY-WEIGHTED PERSISTENCE
# ==============================================================================
# Purpose:
#   Modulate temporal persistence of grain based on local motion magnitude so
#   grain evolves more slowly in static regions and more rapidly in fast motion.
#
# Cinematic relevance:
#   - Prevents frozen grain in static shots
#   - Prevents grain wash-out during fast motion
#   - Matches real film emulsion temporal behavior
#
# Runs AFTER:
#   - 84 I 02 (Grain Directional Smear Compensation)
# ==============================================================================
import numpy as np
def compute_velocity_weight(
    motion_vector: tuple,
    min_weight: float = 0.35,
    max_weight: float = 1.0
) -> float:
    """
    Computes persistence weight based on motion magnitude.
    Parameters:
        motion_vector:
            Normalized motion vector (dx, dy)
        min_weight:
            Persistence at zero motion
        max_weight:
            Persistence at high motion
    Returns:
        Velocity-weighted persistence factor
    """
    dx, dy = motion_vector
    magnitude = np.sqrt(dx * dx + dy * dy)
    return min_weight + (max_weight - min_weight) * np.clip(magnitude, 0.0, 1.0)
def apply_velocity_weighted_persistence(
    grain_field: np.ndarray,
    previous_grain: np.ndarray,
    motion_vector: tuple,
    persistence_curve: float = 0.85
) -> np.ndarray:
    """
    Blends current grain with previous grain using velocity-dependent persistence.
    Parameters:
        grain_field:
            Current grain field
        previous_grain:
            Grain field from previous frame
        motion_vector:
            Normalized motion vector
        persistence_curve:
            Temporal response curve shaping
    Returns:
        Velocity-aware persistent grain field
    """
    weight = compute_velocity_weight(motion_vector)
    alpha = weight ** persistence_curve
    return alpha * previous_grain + (1.0 - alpha) * grain_field
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_velocity_persistence(
    grain_field: np.ndarray,
    previous_grain: np.ndarray,
    motion_vector: tuple,
    config: dict
) -> np.ndarray:
    """
    Applies velocity-weighted temporal persistence to grain.
    """
    return apply_velocity_weighted_persistence(
        grain_field=grain_field,
        previous_grain=previous_grain,
        motion_vector=motion_vector,
        persistence_curve=config.get("persistence_curve", 0.85)
    )
# ==============================================================================
# END OF SUBCHUNK 84 I 03 — GRAIN VELOCITY-WEIGHTED PERSISTENCE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 I 04 — GRAIN MOTION VECTOR ALIGNMENT
# ==============================================================================
# Purpose:
#   Align grain transport direction with optical motion vectors so grain
#   advects coherently with scene motion instead of drifting independently.
#
# Cinematic relevance:
#   - Eliminates sliding grain on moving subjects
#   - Preserves object-locked texture during tracking shots
#   - Essential for subject-following drone cinematography
#
# Runs AFTER:
#   - 84 I 03 (Grain Velocity-Weighted Persistence)
# ==============================================================================
import numpy as np
def warp_grain_along_motion(
    grain_field: np.ndarray,
    motion_vector: tuple,
    strength: float = 1.0
) -> np.ndarray:
    """
    Warps grain field along motion vector direction.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        motion_vector:
            Normalized motion vector (dx, dy)
        strength:
            Amount of grain advection
    Returns:
        Motion-aligned grain field
    """
    dx, dy = motion_vector
    h, w = grain_field.shape[:2]
    # Pixel displacement scaled to frame size
    shift_x = int(np.round(dx * strength))
    shift_y = int(np.round(dy * strength))
    out = np.roll(grain_field, shift=(shift_y, shift_x), axis=(0, 1))
    return out
def apply_motion_vector_alignment(
    grain_field: np.ndarray,
    motion_vector: tuple,
    alignment_strength: float = 0.8
) -> np.ndarray:
    """
    Blends original grain with motion-aligned grain.
    Parameters:
        grain_field:
            Original grain field
        motion_vector:
            Normalized motion vector
        alignment_strength:
            Alignment blend factor
    Returns:
        Motion-aligned grain field
    """
    alignment_strength = np.clip(alignment_strength, 0.0, 1.0)
    warped = warp_grain_along_motion(
        grain_field=grain_field,
        motion_vector=motion_vector,
        strength=alignment_strength
    )
    return (
        (1.0 - alignment_strength) * grain_field +
        alignment_strength * warped
    )
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_motion_alignment(
    grain_field: np.ndarray,
    motion_vector: tuple,
    config: dict
) -> np.ndarray:
    """
    Applies motion vector alignment to grain.
    """
    return apply_motion_vector_alignment(
        grain_field=grain_field,
        motion_vector=motion_vector,
        alignment_strength=config.get("alignment_strength", 0.8)
    )
# ==============================================================================
# END OF SUBCHUNK 84 I 04 — GRAIN MOTION VECTOR ALIGNMENT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 I 05 — GRAIN BLUR-KERNEL INTERACTION
# ==============================================================================
# Purpose:
#   Integrate grain response with the spatial structure of the motion blur
#   kernel so grain density, contrast, and orientation follow blur physics.
#
# Cinematic relevance:
#   - Prevents grain overlay artifacts on blurred edges
#   - Preserves filmic texture inside motion blur streaks
#   - Essential for shutter-angle-driven blur realism
#
# Runs AFTER:
#   - 84 I 04 (Grain Motion Vector Alignment)
# ==============================================================================
import numpy as np
def compute_blur_kernel_response(
    blur_kernel: np.ndarray,
    energy_preserve: bool = True
) -> np.ndarray:
    """
    Computes grain response weighting from a motion blur kernel.
    Parameters:
        blur_kernel:
            2D motion blur kernel (normalized or unnormalized)
        energy_preserve:
            Normalize response to preserve grain energy
    Returns:
        Grain response kernel
    """
    kernel = blur_kernel.astype(np.float32)
    # Absolute kernel influence (grain responds to magnitude, not sign)
    response = np.abs(kernel)
    if energy_preserve:
        s = np.sum(response)
        if s > 1e-6:
            response /= s
    return response
def apply_blur_kernel_interaction(
    grain_field: np.ndarray,
    response_kernel: np.ndarray,
    interaction_strength: float = 0.7
) -> np.ndarray:
    """
    Modulates grain using blur-kernel-shaped response.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        response_kernel:
            Grain response kernel derived from blur
        interaction_strength:
            Strength of kernel interaction
    Returns:
        Blur-integrated grain field
    """
    interaction_strength = np.clip(interaction_strength, 0.0, 1.0)
    # Convolution-like interaction (lightweight, kernel already small)
    if grain_field.ndim == 2:
        blurred = np.convolve(
            grain_field.flatten(),
            response_kernel.flatten(),
            mode="same"
        ).reshape(grain_field.shape)
    else:
        blurred = grain_field.copy()
        for c in range(grain_field.shape[2]):
            blurred[:, :, c] = np.convolve(
                grain_field[:, :, c].flatten(),
                response_kernel.flatten(),
                mode="same"
            ).reshape(grain_field.shape[:2])
    return (
        (1.0 - interaction_strength) * grain_field +
        interaction_strength * blurred
    )
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_blur_kernel_interaction(
    grain_field: np.ndarray,
    blur_kernel: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies blur-kernel-driven grain interaction.
    """
    response_kernel = compute_blur_kernel_response(
        blur_kernel=blur_kernel,
        energy_preserve=True
    )
    return apply_blur_kernel_interaction(
        grain_field=grain_field,
        response_kernel=response_kernel,
        interaction_strength=config.get("interaction_strength", 0.7)
    )
# ==============================================================================
# END OF SUBCHUNK 84 I 05 — GRAIN BLUR-KERNEL INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 I 06 — GRAIN SHUTTER-ANGLE DEPENDENCE
# ==============================================================================
# Purpose:
#   Modulate grain amplitude, elongation, and temporal integration based on
#   effective shutter angle (exposure time relative to frame duration).
#
# Cinematic relevance:
#   - Matches real film grain accumulation during longer exposures
#   - Prevents grain popping when shutter angle changes
#   - Critical for high-speed vs cinematic shutter differences
#
# Runs AFTER:
#   - 84 I 05 (Grain Blur-Kernel Interaction)
# ==============================================================================
import numpy as np
def compute_shutter_exposure_factor(
    shutter_angle_deg: float,
    reference_angle: float = 180.0
) -> float:
    """
    Computes exposure integration factor based on shutter angle.
    Parameters:
        shutter_angle_deg:
            Shutter angle in degrees (0–360)
        reference_angle:
            Reference cinematic shutter (usually 180°)
    Returns:
        Exposure integration factor
    """
    shutter_angle_deg = np.clip(shutter_angle_deg, 1.0, 360.0)
    return shutter_angle_deg / reference_angle
def apply_shutter_angle_grain_response(
    grain_field: np.ndarray,
    shutter_angle_deg: float,
    amplitude_curve: float = 0.6,
    elongation_curve: float = 0.4
) -> np.ndarray:
    """
    Adjusts grain intensity and elongation based on shutter angle.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
        shutter_angle_deg:
            Shutter angle in degrees
        amplitude_curve:
            Controls grain energy scaling
        elongation_curve:
            Controls grain elongation bias
    Returns:
        Shutter-angle-adjusted grain field
    """
    exposure_factor = compute_shutter_exposure_factor(shutter_angle_deg)
    # Grain amplitude grows sub-linearly with exposure time
    amplitude_scale = exposure_factor ** amplitude_curve
    # Elongation bias (longer exposure smears grain slightly)
    elongation_scale = exposure_factor ** elongation_curve
    adjusted = grain_field * amplitude_scale
    # Mild anisotropic smoothing to simulate exposure smear
    if elongation_scale > 1.0:
        kernel_size = int(np.clip(np.round(elongation_scale), 1, 5))
        kernel = np.ones((1, kernel_size), dtype=np.float32)
        kernel /= kernel.sum()
        if adjusted.ndim == 2:
            adjusted = np.apply_along_axis(
                lambda m: np.convolve(m, kernel.flatten(), mode="same"),
                axis=1,
                arr=adjusted
            )
        else:
            for c in range(adjusted.shape[2]):
                adjusted[:, :, c] = np.apply_along_axis(
                    lambda m: np.convolve(m, kernel.flatten(), mode="same"),
                    axis=1,
                    arr=adjusted[:, :, c]
                )
    return adjusted
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_shutter_dependence(
    grain_field: np.ndarray,
    shutter_angle_deg: float,
    config: dict
) -> np.ndarray:
    """
    Applies shutter-angle-dependent grain modulation.
    """
    return apply_shutter_angle_grain_response(
        grain_field=grain_field,
        shutter_angle_deg=shutter_angle_deg,
        amplitude_curve=config.get("amplitude_curve", 0.6),
        elongation_curve=config.get("elongation_curve", 0.4)
    )
# ==============================================================================
# END OF SUBCHUNK 84 I 06 — GRAIN SHUTTER-ANGLE DEPENDENCE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 I 07 — GRAIN TEMPORAL DECAY MODELING
# ==============================================================================
# Purpose:
#   Model non-linear temporal decay of film grain based on exposure history,
#   motion energy, and emulsion memory, producing realistic grain evolution
#   across frames without popping or freezing.
#
# Cinematic relevance:
#   - Prevents linear fade artifacts in static shots
#   - Preserves organic grain evolution over long takes
#   - Matches emulsion memory behavior seen in real film stocks
#
# Runs AFTER:
#   - 84 I 06 (Grain Shutter-Angle Dependence)
# ==============================================================================
import numpy as np
def compute_emulsion_memory_factor(
    exposure_energy: float,
    memory_half_life: float = 12.0
) -> float:
    """
    Computes emulsion memory retention based on accumulated exposure energy.
    Parameters:
        exposure_energy:
            Normalized exposure accumulation (0–1+)
        memory_half_life:
            Frames for memory to halve
    Returns:
        Memory retention factor (0–1)
    """
    exposure_energy = max(exposure_energy, 0.0)
    decay = np.exp(-exposure_energy / max(memory_half_life, 1e-3))
    return np.clip(decay, 0.0, 1.0)
def compute_motion_decay_bias(
    motion_energy: float,
    bias_curve: float = 0.7
) -> float:
    """
    Computes decay bias driven by motion energy.
    Parameters:
        motion_energy:
            Normalized motion magnitude (0–1)
        bias_curve:
            Curve shaping factor
    Returns:
        Motion-driven decay multiplier
    """
    motion_energy = np.clip(motion_energy, 0.0, 1.0)
    return 1.0 - (motion_energy ** bias_curve)
def apply_temporal_decay(
    current_grain: np.ndarray,
    previous_grain: np.ndarray,
    exposure_energy: float,
    motion_energy: float,
    base_decay: float = 0.92
) -> np.ndarray:
    """
    Applies non-linear temporal decay to grain.
    Parameters:
        current_grain:
            Grain field for current frame
        previous_grain:
            Grain field from previous frame
        exposure_energy:
            Exposure accumulation proxy
        motion_energy:
            Motion magnitude proxy
        base_decay:
            Base decay coefficient
    Returns:
        Temporally-decayed grain field
    """
    memory_factor = compute_emulsion_memory_factor(exposure_energy)
    motion_bias = compute_motion_decay_bias(motion_energy)
    decay_coeff = base_decay * memory_factor * motion_bias
    decay_coeff = np.clip(decay_coeff, 0.0, 0.999)
    return (
        decay_coeff * previous_grain +
        (1.0 - decay_coeff) * current_grain
    )
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_temporal_decay(
    current_grain: np.ndarray,
    previous_grain: np.ndarray,
    exposure_energy: float,
    motion_energy: float,
    config: dict
) -> np.ndarray:
    """
    Applies emulsion-inspired temporal decay to grain evolution.
    """
    return apply_temporal_decay(
        current_grain=current_grain,
        previous_grain=previous_grain,
        exposure_energy=exposure_energy,
        motion_energy=motion_energy,
        base_decay=config.get("base_decay", 0.92)
    )
# ==============================================================================
# END OF SUBCHUNK 84 I 07 — GRAIN TEMPORAL DECAY MODELING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 I 08 — GRAIN MOTION COHERENCE PRESERVATION
# ==============================================================================
# Purpose:
#   Preserve spatial and temporal coherence of grain across moving objects
#   and backgrounds by constraining grain evolution using motion-consistent
#   neighborhood agreement.
#
# Cinematic relevance:
#   - Prevents grain tearing at subject boundaries
#   - Eliminates shimmering on silhouettes during pans
#   - Maintains filmic continuity in complex motion scenes
#
# Runs AFTER:
#   - 84 I 07 (Grain Temporal Decay Modeling)
# ==============================================================================
import numpy as np
def compute_coherence_mask(
    motion_field: np.ndarray,
    threshold: float = 0.15
) -> np.ndarray:
    """
    Computes a coherence mask based on local motion consistency.
    Parameters:
        motion_field:
            Per-pixel motion magnitude field (H, W)
        threshold:
            Allowed local motion variance
    Returns:
        Coherence mask (H, W) in range 0–1
    """
    # Compute local variance via simple neighborhood differences
    gx = np.abs(np.gradient(motion_field, axis=1))
    gy = np.abs(np.gradient(motion_field, axis=0))
    variance = np.sqrt(gx * gx + gy * gy)
    mask = 1.0 - np.clip(variance / max(threshold, 1e-6), 0.0, 1.0)
    return mask
def apply_coherence_preservation(
    grain_field: np.ndarray,
    reference_grain: np.ndarray,
    coherence_mask: np.ndarray,
    coherence_strength: float = 0.85
) -> np.ndarray:
    """
    Preserves grain coherence using motion-consistent blending.
    Parameters:
        grain_field:
            Current grain field
        reference_grain:
            Motion-aligned reference grain
        coherence_mask:
            Spatial coherence weighting mask
        coherence_strength:
            Strength of coherence enforcement
    Returns:
        Coherence-preserved grain field
    """
    coherence_strength = np.clip(coherence_strength, 0.0, 1.0)
    if grain_field.ndim == 2:
        mask = coherence_mask
    else:
        mask = coherence_mask[:, :, None]
    blended = (
        (1.0 - coherence_strength * mask) * grain_field +
        (coherence_strength * mask) * reference_grain
    )
    return blended
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_motion_coherence(
    grain_field: np.ndarray,
    reference_grain: np.ndarray,
    motion_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies motion-coherent grain preservation.
    """
    coherence_mask = compute_coherence_mask(
        motion_field=motion_field,
        threshold=config.get("coherence_threshold", 0.15)
    )
    return apply_coherence_preservation(
        grain_field=grain_field,
        reference_grain=reference_grain,
        coherence_mask=coherence_mask,
        coherence_strength=config.get("coherence_strength", 0.85)
    )
# ==============================================================================
# END OF SUBCHUNK 84 I 08 — GRAIN MOTION COHERENCE PRESERVATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 I 09 — GRAIN MOTION BOUNDARY STABILIZATION
# ==============================================================================
# Purpose:
#   Stabilize grain behavior at motion boundaries (foreground/background edges)
#   by damping grain discontinuities caused by sharp motion vector gradients.
#
# Cinematic relevance:
#   - Prevents grain tearing at subject edges
#   - Eliminates edge shimmer during parallax motion
#   - Essential for drone shots with depth separation
#
# Runs AFTER:
#   - 84 I 08 (Grain Motion Coherence Preservation)
# ==============================================================================
import numpy as np
def compute_motion_boundary_mask(
    motion_field: np.ndarray,
    edge_threshold: float = 0.25
) -> np.ndarray:
    """
    Detects motion boundaries using motion gradient magnitude.
    Parameters:
        motion_field:
            Per-pixel motion magnitude (H, W)
        edge_threshold:
            Threshold for motion discontinuity
    Returns:
        Boundary mask (H, W), where 1.0 = stable, 0.0 = boundary
    """
    gx = np.abs(np.gradient(motion_field, axis=1))
    gy = np.abs(np.gradient(motion_field, axis=0))
    gradient_mag = np.sqrt(gx * gx + gy * gy)
    boundary = np.clip(gradient_mag / max(edge_threshold, 1e-6), 0.0, 1.0)
    # Invert so stable regions are 1.0
    return 1.0 - boundary
def stabilize_grain_at_boundaries(
    grain_field: np.ndarray,
    stabilized_grain: np.ndarray,
    boundary_mask: np.ndarray,
    stabilization_strength: float = 0.9
) -> np.ndarray:
    """
    Blends stabilized grain into boundary regions.
    Parameters:
        grain_field:
            Current grain field
        stabilized_grain:
            Motion-coherent reference grain
        boundary_mask:
            Motion boundary stability mask
        stabilization_strength:
            Strength of stabilization near edges
    Returns:
        Boundary-stabilized grain field
    """
    stabilization_strength = np.clip(stabilization_strength, 0.0, 1.0)
    if grain_field.ndim == 2:
        mask = boundary_mask
    else:
        mask = boundary_mask[:, :, None]
    blend = stabilization_strength * (1.0 - mask)
    return (
        (1.0 - blend) * grain_field +
        blend * stabilized_grain
    )
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_motion_boundary_stabilization(
    grain_field: np.ndarray,
    reference_grain: np.ndarray,
    motion_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies motion-boundary grain stabilization.
    """
    boundary_mask = compute_motion_boundary_mask(
        motion_field=motion_field,
        edge_threshold=config.get("edge_threshold", 0.25)
    )
    return stabilize_grain_at_boundaries(
        grain_field=grain_field,
        stabilized_grain=reference_grain,
        boundary_mask=boundary_mask,
        stabilization_strength=config.get("stabilization_strength", 0.9)
    )
# ==============================================================================
# END OF SUBCHUNK 84 I 09 — GRAIN MOTION BOUNDARY STABILIZATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 I 10 — GRAIN FINAL MOTION ENERGY NORMALIZATION
# ==============================================================================
# Purpose:
#   Perform final energy normalization of grain after all motion-dependent
#   operations to guarantee perceptually stable grain density across frames.
#
# Cinematic relevance:
#   - Prevents grain brightness pumping over long takes
#   - Maintains consistent perceived ISO across motion states
#   - Critical for professional-grade film stability
#
# Runs AFTER:
#   - 84 I 09 (Grain Motion Boundary Stabilization)
# ==============================================================================
import numpy as np
def compute_grain_energy(
    grain_field: np.ndarray
) -> float:
    """
    Computes RMS energy of a grain field.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, C)
    Returns:
        RMS grain energy
    """
    if grain_field.ndim == 3:
        energy = np.sqrt(np.mean(grain_field ** 2, axis=(0, 1)))
        return float(np.mean(energy))
    return float(np.sqrt(np.mean(grain_field ** 2)))
def normalize_grain_energy(
    grain_field: np.ndarray,
    target_energy: float,
    max_gain: float = 2.0
) -> np.ndarray:
    """
    Normalizes grain energy to a target RMS level.
    Parameters:
        grain_field:
            Grain field to normalize
        target_energy:
            Desired RMS energy
        max_gain:
            Maximum allowed normalization gain
    Returns:
        Energy-normalized grain field
    """
    current_energy = compute_grain_energy(grain_field)
    if current_energy < 1e-6:
        return grain_field
    gain = target_energy / current_energy
    gain = np.clip(gain, 1.0 / max_gain, max_gain)
    return grain_field * gain
def apply_motion_energy_normalization(
    grain_field: np.ndarray,
    reference_energy: float,
    smoothing_factor: float = 0.8
) -> np.ndarray:
    """
    Smoothly normalizes grain energy toward a reference level.
    Parameters:
        grain_field:
            Grain field after motion processing
        reference_energy:
            Reference grain RMS energy
        smoothing_factor:
            Temporal smoothing (0–1)
    Returns:
        Motion-energy-normalized grain field
    """
    current_energy = compute_grain_energy(grain_field)
    target_energy = (
        smoothing_factor * reference_energy +
        (1.0 - smoothing_factor) * current_energy
    )
    return normalize_grain_energy(
        grain_field=grain_field,
        target_energy=target_energy
    )
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_final_energy_normalization(
    grain_field: np.ndarray,
    reference_energy: float,
    config: dict
) -> np.ndarray:
    """
    Applies final motion-aware grain energy normalization.
    """
    return apply_motion_energy_normalization(
        grain_field=grain_field,
        reference_energy=reference_energy,
        smoothing_factor=config.get("smoothing_factor", 0.8)
    )
# ==============================================================================
# END OF SUBCHUNK 84 I 10 — GRAIN FINAL MOTION ENERGY NORMALIZATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 J 01 — ADVANCED GRAIN SPECTRAL RESPONSE MAPPING
# ==============================================================================
# Purpose:
#   Model wavelength-dependent grain response so grain amplitude and structure
#   vary across spectral bands (blue/green/red), matching real film emulsion
#   silver-halide sensitivity curves.
#
# Cinematic relevance:
#   - Prevents monochromatic grain appearance
#   - Improves highlight texture realism
#   - Essential for color separation in ACES pipelines
#
# Runs AFTER:
#   - 84 I 10 (Grain Final Motion Energy Normalization)
# ==============================================================================
import numpy as np
def default_emulsion_spectral_curve() -> dict:
    """
    Returns a physically-plausible spectral sensitivity curve
    approximating modern color negative film.
    Returns:
        Dict with per-channel sensitivity weights
    """
    return {
        "R": 0.85,   # Red layer slightly lower granularity
        "G": 1.00,   # Green reference layer
        "B": 1.20    # Blue layer highest apparent grain
    }
def apply_spectral_response(
    grain_field: np.ndarray,
    spectral_curve: dict
) -> np.ndarray:
    """
    Applies spectral weighting to grain field.
    Parameters:
        grain_field:
            Grain field (H, W) or (H, W, 3)
        spectral_curve:
            Dict with 'R','G','B' sensitivity multipliers
    Returns:
        Spectrally-shaped grain field
    """
    if grain_field.ndim == 2:
        # Luma-only grain: use green channel response
        return grain_field * spectral_curve.get("G", 1.0)
    out = grain_field.copy()
    out[:, :, 0] *= spectral_curve.get("R", 1.0)
    out[:, :, 1] *= spectral_curve.get("G", 1.0)
    out[:, :, 2] *= spectral_curve.get("B", 1.0)
    return out
def normalize_spectral_energy(
    grain_field: np.ndarray
) -> np.ndarray:
    """
    Renormalizes energy after spectral shaping to preserve global grain level.
    """
    rms_before = np.sqrt(np.mean(grain_field ** 2))
    if rms_before < 1e-6:
        return grain_field
    rms_after = np.sqrt(np.mean(grain_field ** 2))
    gain = rms_before / max(rms_after, 1e-6)
    return grain_field * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_spectral_response(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies advanced spectral response mapping to grain.
    """
    spectral_curve = config.get(
        "spectral_curve",
        default_emulsion_spectral_curve()
    )
    shaped = apply_spectral_response(
        grain_field=grain_field,
        spectral_curve=spectral_curve
    )
    return normalize_spectral_energy(shaped)
# ==============================================================================
# END OF SUBCHUNK 84 J 01 — ADVANCED GRAIN SPECTRAL RESPONSE MAPPING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 J 02 — GRAIN CHROMATIC PHASE INTERACTION
# ==============================================================================
# Purpose:
#   Introduce controlled phase offsets between color-channel grain layers
#   to replicate the stochastic misalignment of dye clouds in real color film.
#
# Cinematic relevance:
#   - Eliminates synthetic RGB-locked grain
#   - Restores organic chromatic texture
#   - Essential for high-end color-negative realism
#
# Runs AFTER:
#   - 84 J 01 (Advanced Grain Spectral Response Mapping)
# ==============================================================================
import numpy as np
def generate_phase_offset(
    shape: tuple,
    max_shift: int = 1
) -> tuple:
    """
    Generates random spatial phase offsets for grain channels.
    Parameters:
        shape:
            Grain field shape (H, W)
        max_shift:
            Maximum pixel offset per axis
    Returns:
        (shift_y, shift_x)
    """
    shift_y = np.random.randint(-max_shift, max_shift + 1)
    shift_x = np.random.randint(-max_shift, max_shift + 1)
    return shift_y, shift_x
def apply_chromatic_phase_interaction(
    grain_field: np.ndarray,
    max_phase_shift: int = 1,
    interaction_strength: float = 0.75
) -> np.ndarray:
    """
    Applies chromatic phase offsets to grain channels.
    Parameters:
        grain_field:
            Grain field (H, W, 3)
        max_phase_shift:
            Maximum pixel phase shift
        interaction_strength:
            Blend strength of phase interaction
    Returns:
        Chromatically decorrelated grain field
    """
    if grain_field.ndim != 3 or grain_field.shape[2] != 3:
        return grain_field
    out = grain_field.copy()
    for c in range(3):
        shift_y, shift_x = generate_phase_offset(
            shape=grain_field.shape[:2],
            max_shift=max_phase_shift
        )
        shifted = np.roll(
            grain_field[:, :, c],
            shift=(shift_y, shift_x),
            axis=(0, 1)
        )
        out[:, :, c] = (
            (1.0 - interaction_strength) * grain_field[:, :, c] +
            interaction_strength * shifted
        )
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_chromatic_phase(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies chromatic phase interaction to grain.
    """
    return apply_chromatic_phase_interaction(
        grain_field=grain_field,
        max_phase_shift=config.get("max_phase_shift", 1),
        interaction_strength=config.get("interaction_strength", 0.75)
    )
# ==============================================================================
# END OF SUBCHUNK 84 J 02 — GRAIN CHROMATIC PHASE INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 J 03 — GRAIN LUMINANCE-CHROMA DECOUPLING
# ==============================================================================
# Purpose:
#   Decouple grain behavior between luminance and chroma channels so grain
#   energy follows perceptual brightness while chroma grain remains subtler,
#   matching real color-negative film behavior.
#
# Cinematic relevance:
#   - Prevents rainbow crawl in shadows and skies
#   - Preserves clean color edges while retaining texture
#   - Essential for skin tones and large gradients
#
# Runs AFTER:
#   - 84 J 02 (Grain Chromatic Phase Interaction)
# ==============================================================================
import numpy as np
def split_luma_chroma(
    grain_rgb: np.ndarray
) -> tuple:
    """
    Splits grain into luminance and chroma components.
    Parameters:
        grain_rgb:
            Grain field (H, W, 3)
    Returns:
        (luma, chroma) where chroma is residual color grain
    """
    # ITU-R BT.709 luma coefficients (ACES-compatible)
    luma = (
        0.2126 * grain_rgb[:, :, 0] +
        0.7152 * grain_rgb[:, :, 1] +
        0.0722 * grain_rgb[:, :, 2]
    )
    chroma = grain_rgb - luma[:, :, None]
    return luma, chroma
def apply_luma_chroma_scaling(
    luma: np.ndarray,
    chroma: np.ndarray,
    chroma_strength: float = 0.45
) -> np.ndarray:
    """
    Scales chroma grain independently from luma grain.
    Parameters:
        luma:
            Luminance grain field
        chroma:
            Chrominance grain residual
        chroma_strength:
            Relative strength of chroma grain
    Returns:
        Recombined grain field
    """
    chroma_strength = np.clip(chroma_strength, 0.0, 1.0)
    return luma[:, :, None] + chroma * chroma_strength
def suppress_chroma_in_high_luma(
    luma: np.ndarray,
    chroma: np.ndarray,
    knee: float = 0.6
) -> np.ndarray:
    """
    Suppresses chroma grain in highlights where film dye clouds overlap densely.
    """
    weight = 1.0 - np.clip((luma - knee) / max(1.0 - knee, 1e-6), 0.0, 1.0)
    return chroma * weight[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_luma_chroma_decoupling(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies luminance–chroma grain decoupling and recomposition.
    """
    if grain_field.ndim != 3 or grain_field.shape[2] != 3:
        return grain_field
    luma, chroma = split_luma_chroma(grain_field)
    chroma = suppress_chroma_in_high_luma(
        luma=luma,
        chroma=chroma,
        knee=config.get("highlight_knee", 0.6)
    )
    return apply_luma_chroma_scaling(
        luma=luma,
        chroma=chroma,
        chroma_strength=config.get("chroma_strength", 0.45)
    )
# ==============================================================================
# END OF SUBCHUNK 84 J 03 — GRAIN LUMINANCE-CHROMA DECOUPLING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 J 04 — GRAIN CROSS-CHANNEL ENERGY CONSERVATION
# ==============================================================================
# Purpose:
#   Enforce conservation of grain energy across RGB channels after spectral,
#   phase, and luma–chroma operations, ensuring no unintended color bias or
#   brightness drift is introduced by multi-stage grain processing.
#
# Cinematic relevance:
#   - Prevents long-term color tint drift caused by grain
#   - Maintains neutral gray balance in static shots
#   - Essential for ACES-compliant color stability
#
# Runs AFTER:
#   - 84 J 03 (Grain Luminance-Chroma Decoupling)
# ==============================================================================
import numpy as np
def compute_channel_energy(
    grain_rgb: np.ndarray
) -> np.ndarray:
    """
    Computes RMS energy per color channel.
    Parameters:
        grain_rgb:
            Grain field (H, W, 3)
    Returns:
        np.ndarray of shape (3,) with per-channel RMS energy
    """
    energies = []
    for c in range(3):
        energies.append(np.sqrt(np.mean(grain_rgb[:, :, c] ** 2)))
    return np.array(energies, dtype=np.float32)
def apply_energy_conservation(
    grain_rgb: np.ndarray,
    target_energy: float,
    channel_balance: tuple = (1.0, 1.0, 1.0),
    max_gain: float = 1.8
) -> np.ndarray:
    """
    Scales RGB channels to conserve total grain energy.
    Parameters:
        grain_rgb:
            Grain field (H, W, 3)
        target_energy:
            Desired average RMS energy across channels
        channel_balance:
            Relative balance weights for (R, G, B)
        max_gain:
            Maximum allowed per-channel gain
    Returns:
        Energy-conserved grain field
    """
    energies = compute_channel_energy(grain_rgb)
    balance = np.array(channel_balance, dtype=np.float32)
    balance /= np.mean(balance)
    corrected = grain_rgb.copy()
    for c in range(3):
        if energies[c] < 1e-6:
            continue
        gain = (target_energy * balance[c]) / energies[c]
        gain = np.clip(gain, 1.0 / max_gain, max_gain)
        corrected[:, :, c] *= gain
    return corrected
def compute_global_target_energy(
    grain_rgb: np.ndarray
) -> float:
    """
    Computes global target RMS energy across all channels.
    """
    return float(np.sqrt(np.mean(grain_rgb ** 2)))
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_cross_channel_energy(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies cross-channel grain energy conservation.
    """
    if grain_field.ndim != 3 or grain_field.shape[2] != 3:
        return grain_field
    target_energy = config.get(
        "target_energy",
        compute_global_target_energy(grain_field)
    )
    return apply_energy_conservation(
        grain_rgb=grain_field,
        target_energy=target_energy,
        channel_balance=config.get("channel_balance", (1.0, 1.0, 1.0)),
        max_gain=config.get("max_gain", 1.8)
    )
# ==============================================================================
# END OF SUBCHUNK 84 J 04 — GRAIN CROSS-CHANNEL ENERGY CONSERVATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 J 05 — GRAIN SPECTRAL AGING DRIFT
# ==============================================================================
# Purpose:
#   Introduce slow, controlled spectral drift in grain response over time to
#   emulate emulsion aging, development variance, and reel-to-reel instability.
#
# Cinematic relevance:
#   - Prevents static grain coloration across long sequences
#   - Adds subtle organic evolution between shots
#   - Matches real-world film stock aging and lab variance
#
# Runs AFTER:
#   - 84 J 04 (Grain Cross-Channel Energy Conservation)
# ==============================================================================
import numpy as np
def compute_aging_drift_curve(
    frame_index: int,
    drift_strength: float = 0.015,
    drift_period: int = 2400
) -> np.ndarray:
    """
    Computes a slow spectral drift curve for grain aging.
    Parameters:
        frame_index:
            Absolute frame index in sequence
        drift_strength:
            Maximum fractional drift per channel
        drift_period:
            Frames per full drift cycle
    Returns:
        np.ndarray (3,) spectral drift multipliers for RGB
    """
    phase = 2.0 * np.pi * (frame_index % drift_period) / float(drift_period)
    # Slightly different phase offsets per channel
    drift_r = 1.0 + drift_strength * np.sin(phase + 0.3)
    drift_g = 1.0 + drift_strength * np.sin(phase + 1.1)
    drift_b = 1.0 + drift_strength * np.sin(phase + 2.2)
    return np.array([drift_r, drift_g, drift_b], dtype=np.float32)
def apply_spectral_aging_drift(
    grain_rgb: np.ndarray,
    drift_curve: np.ndarray,
    max_deviation: float = 0.04
) -> np.ndarray:
    """
    Applies spectral aging drift to grain field.
    Parameters:
        grain_rgb:
            Grain field (H, W, 3)
        drift_curve:
            Per-channel drift multipliers
        max_deviation:
            Safety clamp for drift deviation
    Returns:
        Spectrally aged grain field
    """
    drift = np.clip(
        drift_curve,
        1.0 - max_deviation,
        1.0 + max_deviation
    )
    aged = grain_rgb.copy()
    for c in range(3):
        aged[:, :, c] *= drift[c]
    return aged
def renormalize_after_aging(
    grain_rgb: np.ndarray
) -> np.ndarray:
    """
    Renormalizes grain energy after spectral aging to avoid brightness drift.
    """
    rms_before = np.sqrt(np.mean(grain_rgb ** 2))
    if rms_before < 1e-6:
        return grain_rgb
    rms_after = np.sqrt(np.mean(grain_rgb ** 2))
    gain = rms_before / max(rms_after, 1e-6)
    return grain_rgb * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_spectral_aging_drift(
    grain_field: np.ndarray,
    frame_index: int,
    config: dict
) -> np.ndarray:
    """
    Applies slow spectral aging drift to grain over time.
    """
    if grain_field.ndim != 3 or grain_field.shape[2] != 3:
        return grain_field
    drift_curve = compute_aging_drift_curve(
        frame_index=frame_index,
        drift_strength=config.get("drift_strength", 0.015),
        drift_period=config.get("drift_period", 2400)
    )
    aged = apply_spectral_aging_drift(
        grain_rgb=grain_field,
        drift_curve=drift_curve,
        max_deviation=config.get("max_deviation", 0.04)
    )
    return renormalize_after_aging(aged)
# ==============================================================================
# END OF SUBCHUNK 84 J 05 — GRAIN SPECTRAL AGING DRIFT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 J 06 — GRAIN DYE-LAYER INTERACTION MODELING
# ==============================================================================
# Purpose:
#   Model interaction between grain and overlapping dye layers in color film,
#   where cyan, magenta, and yellow dye clouds partially occlude and reinforce
#   each other depending on exposure density.
#
# Cinematic relevance:
#   - Produces correct grain behavior in saturated colors
#   - Prevents flat RGB grain in dense dye regions
#   - Essential for highlights, skin tones, and skies
#
# Runs AFTER:
#   - 84 J 05 (Grain Spectral Aging Drift)
# ==============================================================================
import numpy as np
def compute_dye_density_weights(
    rgb_image: np.ndarray
) -> np.ndarray:
    """
    Computes dye density interaction weights from image color density.
    Parameters:
        rgb_image:
            Linear RGB image (H, W, 3)
    Returns:
        Dye interaction weights (H, W, 3)
    """
    # Convert RGB density to approximate CMY dye density
    # Higher RGB value => lower dye density
    dye_density = 1.0 - np.clip(rgb_image, 0.0, 1.0)
    # Normalize interaction influence
    density_sum = np.sum(dye_density, axis=2, keepdims=True)
    density_sum = np.maximum(density_sum, 1e-6)
    return dye_density / density_sum
def apply_dye_layer_interaction(
    grain_rgb: np.ndarray,
    dye_weights: np.ndarray,
    interaction_strength: float = 0.65
) -> np.ndarray:
    """
    Applies dye-layer interaction to grain.
    Parameters:
        grain_rgb:
            Grain field (H, W, 3)
        dye_weights:
            Dye interaction weights (H, W, 3)
        interaction_strength:
            Strength of dye interaction coupling
    Returns:
        Dye-interacted grain field
    """
    interaction_strength = np.clip(interaction_strength, 0.0, 1.0)
    # Compute cross-channel influence
    cross = (
        grain_rgb[:, :, [1, 2, 0]] * dye_weights[:, :, [0, 1, 2]] +
        grain_rgb[:, :, [2, 0, 1]] * dye_weights[:, :, [1, 2, 0]]
    )
    return (
        (1.0 - interaction_strength) * grain_rgb +
        interaction_strength * cross
    )
def renormalize_dye_interaction_energy(
    grain_rgb: np.ndarray,
    max_gain: float = 1.6
) -> np.ndarray:
    """
    Renormalizes energy after dye-layer interaction.
    """
    rms_before = np.sqrt(np.mean(grain_rgb ** 2))
    if rms_before < 1e-6:
        return grain_rgb
    rms_after = np.sqrt(np.mean(grain_rgb ** 2))
    gain = rms_before / max(rms_after, 1e-6)
    gain = np.clip(gain, 1.0 / max_gain, max_gain)
    return grain_rgb * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_dye_layer_interaction(
    grain_field: np.ndarray,
    rgb_image: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies dye-layer interaction modeling to grain.
    """
    if grain_field.ndim != 3 or grain_field.shape[2] != 3:
        return grain_field
    dye_weights = compute_dye_density_weights(rgb_image)
    interacted = apply_dye_layer_interaction(
        grain_rgb=grain_field,
        dye_weights=dye_weights,
        interaction_strength=config.get("interaction_strength", 0.65)
    )
    return renormalize_dye_interaction_energy(
        interacted,
        max_gain=config.get("max_gain", 1.6)
    )
# ==============================================================================
# END OF SUBCHUNK 84 J 06 — GRAIN DYE-LAYER INTERACTION MODELING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 J 06 — GRAIN DYE-LAYER INTERACTION MODELING
# ==============================================================================
# Purpose:
#   Model interaction between grain and overlapping dye layers in color film,
