# ==============================================================================
# SUBCHUNK 84 J 07 — GRAIN COLOR CROSS-TALK SUPPRESSION
# ==============================================================================
# Purpose:
#   Suppress excessive inter-channel correlation introduced by dye-layer
#   interaction and spectral drift, restoring film-accurate partial independence
#   between color grain layers while preserving organic coupling.
#
# Cinematic relevance:
#   - Prevents neon speckling in saturated regions
#   - Maintains natural color separation in highlights
#   - Critical for skin tones and skies after dye interaction
#
# Runs AFTER:
#   - 84 J 06 (Grain Dye-Layer Interaction Modeling)
# ==============================================================================
import numpy as np
def compute_channel_correlation(grain_rgb: np.ndarray) -> np.ndarray:
    """
    Computes per-pixel inter-channel correlation strength.
    Returns scalar correlation map (H, W).
    """
    r, g, b = grain_rgb[:, :, 0], grain_rgb[:, :, 1], grain_rgb[:, :, 2]
    mean = (r + g + b) / 3.0
    var = ((r - mean)**2 + (g - mean)**2 + (b - mean)**2) / 3.0
    # Low variance => high correlation
    return 1.0 - np.clip(var / (var + mean**2 + 1e-6), 0.0, 1.0)
def suppress_color_crosstalk(
    grain_rgb: np.ndarray,
    correlation_map: np.ndarray,
    suppression_strength: float = 0.55
) -> np.ndarray:
    """
    Reduces correlated color grain components while preserving luminance grain.
    """
    suppression_strength = np.clip(suppression_strength, 0.0, 1.0)
    # Extract luminance grain
    lum = (
        0.2126 * grain_rgb[:, :, 0] +
        0.7152 * grain_rgb[:, :, 1] +
        0.0722 * grain_rgb[:, :, 2]
    )
    lum = lum[:, :, None]
    # Compute color residual
    color_residual = grain_rgb - lum
    # Suppress correlated color components
    suppression = (1.0 - suppression_strength * correlation_map)[:, :, None]
    return lum + color_residual * suppression
def energy_safe_renormalization(
    grain_rgb: np.ndarray,
    max_gain: float = 1.5
) -> np.ndarray:
    """
    Ensures total grain energy consistency after cross-talk suppression.
    """
    rms = np.sqrt(np.mean(grain_rgb ** 2))
    if rms < 1e-6:
        return grain_rgb
    gain = np.clip(1.0 / rms, 1.0 / max_gain, max_gain)
    return grain_rgb * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_color_crosstalk_suppression(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies color cross-talk suppression to grain field.
    """
    if grain_field.ndim != 3 or grain_field.shape[2] != 3:
        return grain_field
    corr_map = compute_channel_correlation(grain_field)
    suppressed = suppress_color_crosstalk(
        grain_rgb=grain_field,
        correlation_map=corr_map,
        suppression_strength=config.get("suppression_strength", 0.55)
    )
    return energy_safe_renormalization(
        suppressed,
        max_gain=config.get("max_gain", 1.5)
    )
# ==============================================================================
# END OF SUBCHUNK 84 J 07 — GRAIN COLOR CROSS-TALK SUPPRESSION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 J 08 — GRAIN HIGHLIGHT COLOR STABILITY CONTROL
# ==============================================================================
# Purpose:
#   Stabilize chromatic grain behavior in high-luminance regions where film
#   emulsion approaches dye saturation and digital systems tend to introduce
#   color flutter or chroma popping.
#
# Cinematic relevance:
#   - Prevents colored grain shimmer in skies and specular highlights
#   - Preserves neutral highlight roll-off
#   - Essential for daylight aerial shots and clouds
#
# Runs AFTER:
#   - 84 J 07 (Grain Color Cross-Talk Suppression)
# ==============================================================================
import numpy as np
def compute_highlight_mask(
    rgb_image: np.ndarray,
    threshold: float = 0.78,
    softness: float = 0.12
) -> np.ndarray:
    """
    Computes a smooth highlight mask based on luminance.
    """
    lum = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    t0 = threshold - softness
    t1 = threshold + softness
    mask = (lum - t0) / max(t1 - t0, 1e-6)
    return np.clip(mask, 0.0, 1.0)
def stabilize_highlight_chroma(
    grain_rgb: np.ndarray,
    highlight_mask: np.ndarray,
    stability_strength: float = 0.7
) -> np.ndarray:
    """
    Reduces chromatic grain variance in highlights while preserving luminance grain.
    """
    stability_strength = np.clip(stability_strength, 0.0, 1.0)
    # Compute luminance grain
    lum = (
        0.2126 * grain_rgb[:, :, 0] +
        0.7152 * grain_rgb[:, :, 1] +
        0.0722 * grain_rgb[:, :, 2]
    )
    lum = lum[:, :, None]
    # Isolate chroma grain
    chroma = grain_rgb - lum
    # Attenuate chroma grain in highlights
    attenuation = 1.0 - stability_strength * highlight_mask
    attenuation = attenuation[:, :, None]
    return lum + chroma * attenuation
def energy_compensate_highlights(
    original: np.ndarray,
    stabilized: np.ndarray,
    max_gain: float = 1.4
) -> np.ndarray:
    """
    Compensates grain energy loss after highlight stabilization.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_s = np.sqrt(np.mean(stabilized ** 2))
    if rms_s < 1e-6:
        return stabilized
    gain = np.clip(rms_o / rms_s, 1.0 / max_gain, max_gain)
    return stabilized * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_highlight_color_stability(
    grain_field: np.ndarray,
    rgb_image: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies highlight-specific color grain stabilization.
    """
    if grain_field.ndim != 3 or grain_field.shape[2] != 3:
        return grain_field
    mask = compute_highlight_mask(
        rgb_image,
        threshold=config.get("threshold", 0.78),
        softness=config.get("softness", 0.12)
    )
    stabilized = stabilize_highlight_chroma(
        grain_rgb=grain_field,
        highlight_mask=mask,
        stability_strength=config.get("stability_strength", 0.7)
    )
    return energy_compensate_highlights(
        original=grain_field,
        stabilized=stabilized,
        max_gain=config.get("max_gain", 1.4)
    )
# ==============================================================================
# END OF SUBCHUNK 84 J 08 — GRAIN HIGHLIGHT COLOR STABILITY CONTROL
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 J 09 — GRAIN LONG-EXPOSURE COLOR INTEGRATION
# ==============================================================================
# Purpose:
#   Integrate grain chroma over time to emulate long-exposure film behavior,
#   where dye clouds accumulate energy across frames rather than resetting
#   independently per exposure.
#
# Cinematic relevance:
#   - Essential for dusk, night, and golden-hour aerials
#   - Prevents digital “sparkle” in low-light gradients
#   - Preserves film-like temporal chroma continuity
#
# Runs AFTER:
#   - 84 J 08 (Grain Highlight Color Stability Control)
# ==============================================================================
import numpy as np
def compute_exposure_time_weight(
    shutter_time: float,
    reference_shutter: float = 1.0 / 48.0,
    max_weight: float = 2.5
) -> float:
    """
    Computes integration weight based on shutter duration.
    Longer shutter => stronger temporal integration.
    """
    if shutter_time <= 0.0:
        return 1.0
    weight = shutter_time / reference_shutter
    return float(np.clip(weight, 1.0, max_weight))
def integrate_grain_over_time(
    current_grain: np.ndarray,
    previous_grain: np.ndarray,
    integration_weight: float,
    chroma_only: bool = True
) -> np.ndarray:
    """
    Integrates grain temporally to simulate long exposure accumulation.
    Parameters:
        current_grain:
            Current frame grain (H, W, 3)
        previous_grain:
            Previous integrated grain (H, W, 3)
        integration_weight:
            Temporal accumulation strength
        chroma_only:
            Apply integration only to chroma channels
    """
    alpha = 1.0 / integration_weight
    if chroma_only:
        # Extract luminance
        lum_c = (
            0.2126 * current_grain[:, :, 0] +
            0.7152 * current_grain[:, :, 1] +
            0.0722 * current_grain[:, :, 2]
        )[:, :, None]
        lum_p = (
            0.2126 * previous_grain[:, :, 0] +
            0.7152 * previous_grain[:, :, 1] +
            0.0722 * previous_grain[:, :, 2]
        )[:, :, None]
        chroma_c = current_grain - lum_c
        chroma_p = previous_grain - lum_p
        chroma_integrated = (
            alpha * chroma_c +
            (1.0 - alpha) * chroma_p
        )
        return lum_c + chroma_integrated
    else:
        return (
            alpha * current_grain +
            (1.0 - alpha) * previous_grain
        )
def temporal_energy_correction(
    original: np.ndarray,
    integrated: np.ndarray,
    max_gain: float = 1.35
) -> np.ndarray:
    """
    Corrects energy drift introduced by temporal integration.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_i = np.sqrt(np.mean(integrated ** 2))
    if rms_i < 1e-6:
        return integrated
    gain = np.clip(rms_o / rms_i, 1.0 / max_gain, max_gain)
    return integrated * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_long_exposure_integration(
    grain_field: np.ndarray,
    previous_grain: np.ndarray,
    shutter_time: float,
    config: dict
) -> np.ndarray:
    """
    Applies long-exposure temporal integration to grain color.
    """
    if (
        grain_field is None or
        previous_grain is None or
        grain_field.shape != previous_grain.shape or
        grain_field.ndim != 3
    ):
        return grain_field
    weight = compute_exposure_time_weight(
        shutter_time=shutter_time,
        reference_shutter=config.get("reference_shutter", 1.0 / 48.0),
        max_weight=config.get("max_weight", 2.5)
    )
    integrated = integrate_grain_over_time(
        current_grain=grain_field,
        previous_grain=previous_grain,
        integration_weight=weight,
        chroma_only=config.get("chroma_only", True)
    )
    return temporal_energy_correction(
        original=grain_field,
        integrated=integrated,
        max_gain=config.get("max_gain", 1.35)
    )
# ==============================================================================
# END OF SUBCHUNK 84 J 09 — GRAIN LONG-EXPOSURE COLOR INTEGRATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 J 10 — GRAIN FINAL SPECTRAL HARMONIZATION
# ==============================================================================
# Purpose:
#   Perform final harmonization of grain spectral content after all temporal,
#   dye-layer, highlight, long-exposure, and cross-talk processes. This step
#   ensures perceptual neutrality, reel-to-reel consistency, and mastering-grade
#   stability without erasing organic variance.
#
# Cinematic relevance:
#   - Locks grain color balance across scenes
#   - Prevents cumulative chroma bias over long sequences
#   - Ensures filmic neutrality before aging/storage simulation
#
# Runs AFTER:
#   - 84 J 09 (Grain Long-Exposure Color Integration)
# ==============================================================================
import numpy as np
def compute_channel_energy(grain_rgb: np.ndarray) -> np.ndarray:
    """
    Computes RMS energy per color channel.
    Returns:
        np.ndarray (3,) RMS energy for R, G, B
    """
    energies = []
    for c in range(3):
        energies.append(np.sqrt(np.mean(grain_rgb[:, :, c] ** 2)))
    return np.array(energies, dtype=np.float32)
def compute_target_spectral_balance(
    energies: np.ndarray,
    neutrality_bias: float = 0.85
) -> np.ndarray:
    """
    Computes target spectral balance that gently pulls grain toward
    perceptual neutrality without flattening character.
    neutrality_bias:
        0.0 = preserve current balance
        1.0 = force perfect neutrality
    """
    neutrality_bias = np.clip(neutrality_bias, 0.0, 1.0)
    mean_energy = np.mean(energies)
    target = (
        (1.0 - neutrality_bias) * energies +
        neutrality_bias * mean_energy
    )
    return np.maximum(target, 1e-6)
def apply_spectral_harmonization(
    grain_rgb: np.ndarray,
    target_energy: np.ndarray,
    max_gain: float = 1.25
) -> np.ndarray:
    """
    Scales each color channel to match target spectral energy.
    """
    harmonized = grain_rgb.copy()
    current_energy = compute_channel_energy(grain_rgb)
    for c in range(3):
        if current_energy[c] < 1e-6:
            continue
        gain = target_energy[c] / current_energy[c]
        gain = np.clip(gain, 1.0 / max_gain, max_gain)
        harmonized[:, :, c] *= gain
    return harmonized
def perceptual_luminance_guard(
    original: np.ndarray,
    harmonized: np.ndarray,
    max_luma_error: float = 0.015
) -> np.ndarray:
    """
    Ensures spectral harmonization does not alter perceived luminance grain.
    """
    lum_o = (
        0.2126 * original[:, :, 0] +
        0.7152 * original[:, :, 1] +
        0.0722 * original[:, :, 2]
    )
    lum_h = (
        0.2126 * harmonized[:, :, 0] +
        0.7152 * harmonized[:, :, 1] +
        0.0722 * harmonized[:, :, 2]
    )
    delta = lum_o - lum_h
    delta = np.clip(delta, -max_luma_error, max_luma_error)
    correction = delta[:, :, None]
    return harmonized + correction
def global_energy_lock(
    original: np.ndarray,
    harmonized: np.ndarray,
    max_gain: float = 1.2
) -> np.ndarray:
    """
    Locks final grain energy to original reference.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_h = np.sqrt(np.mean(harmonized ** 2))
    if rms_h < 1e-6:
        return harmonized
    gain = np.clip(rms_o / rms_h, 1.0 / max_gain, max_gain)
    return harmonized * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_final_spectral_harmonization(
    grain_field: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies final spectral harmonization to grain field.
    """
    if grain_field.ndim != 3 or grain_field.shape[2] != 3:
        return grain_field
    energies = compute_channel_energy(grain_field)
    target = compute_target_spectral_balance(
        energies,
        neutrality_bias=config.get("neutrality_bias", 0.85)
    )
    harmonized = apply_spectral_harmonization(
        grain_rgb=grain_field,
        target_energy=target,
        max_gain=config.get("max_gain", 1.25)
    )
    harmonized = perceptual_luminance_guard(
        original=grain_field,
        harmonized=harmonized,
        max_luma_error=config.get("max_luma_error", 0.015)
    )
    return global_energy_lock(
        original=grain_field,
        harmonized=harmonized,
        max_gain=config.get("global_max_gain", 1.2)
    )
# ==============================================================================
# END OF SUBCHUNK 84 J 10 — GRAIN FINAL SPECTRAL HARMONIZATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 K 01 — FILM AGING & STORAGE EFFECTS (MASTER ONSET)
# ==============================================================================
# Purpose:
#   Establish master aging state variables and time-domain controls used by all
#   subsequent film aging and storage simulation modules. This defines how
#   "film age" accumulates across frames, shots, reels, and environmental context.
#
# Cinematic relevance:
#   - Enables coherent aging behavior across an entire project
#   - Prevents per-shot reset artifacts
#   - Matches real lab / storage temporal characteristics
#
# Runs BEFORE:
#   - 84 K 02+ (all storage temperature, humidity, density, saturation effects)
# ==============================================================================
import numpy as np
class FilmAgingState:
    """
    Container for film aging state across time.
    """
    def __init__(
        self,
        base_age_days: float = 0.0,
        exposure_days_per_hour: float = 0.15,
        reel_variance: float = 0.08
    ):
        """
        Parameters:
            base_age_days:
                Initial simulated film age in days
            exposure_days_per_hour:
                How much aging accumulates per hour of footage
            reel_variance:
                Per-reel random aging offset (organic variance)
        """
        self.base_age_days = float(base_age_days)
        self.exposure_days_per_hour = float(exposure_days_per_hour)
        # Reel-specific offset (fixed per session)
        self.reel_offset = np.random.normal(0.0, reel_variance)
        # Internal counters
        self.total_frames = 0
        self.current_age_days = self.base_age_days + self.reel_offset
    def update(
        self,
        frames_advanced: int,
        fps: float
    ) -> float:
        """
        Advances aging state based on frames processed.
        Returns:
            Updated film age in days
        """
        self.total_frames += frames_advanced
        hours = (frames_advanced / max(fps, 1e-6)) / 3600.0
        self.current_age_days += hours * self.exposure_days_per_hour
        return self.current_age_days
def compute_aging_intensity(
    age_days: float,
    knee_days: float = 180.0,
    max_intensity: float = 1.0
) -> float:
    """
    Converts film age (days) into normalized aging intensity.
    Uses a soft knee to prevent aggressive early aging.
    """
    age_days = max(age_days, 0.0)
    # Smooth knee curve
    intensity = age_days / (age_days + knee_days)
    return float(np.clip(intensity * max_intensity, 0.0, max_intensity))
def compute_environmental_bias(
    temperature_c: float,
    humidity_pct: float,
    temp_ref: float = 20.0,
    humidity_ref: float = 50.0
) -> float:
    """
    Computes environmental aging bias from storage conditions.
    Higher temperature and humidity accelerate aging.
    """
    temp_bias = (temperature_c - temp_ref) * 0.015
    humidity_bias = (humidity_pct - humidity_ref) * 0.01
    return float(np.clip(temp_bias + humidity_bias, -0.25, 0.75))
def compute_effective_aging_factor(
    aging_intensity: float,
    env_bias: float,
    stability_guard: float = 0.85
) -> float:
    """
    Combines intrinsic aging and environmental bias into final factor.
    """
    combined = aging_intensity * (1.0 + env_bias)
    # Stability guard prevents runaway degradation
    combined *= stability_guard
    return float(np.clip(combined, 0.0, 1.25))
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_film_aging_master_state(
    state: FilmAgingState,
    frames_advanced: int,
    fps: float,
    temperature_c: float,
    humidity_pct: float,
    config: dict
) -> dict:
    """
    Updates and returns master aging parameters for downstream modules.
    Returns:
        dict with keys:
            - age_days
            - aging_intensity
            - env_bias
            - effective_factor
    """
    age_days = state.update(frames_advanced, fps)
    aging_intensity = compute_aging_intensity(
        age_days=age_days,
        knee_days=config.get("knee_days", 180.0),
        max_intensity=config.get("max_intensity", 1.0)
    )
    env_bias = compute_environmental_bias(
        temperature_c=temperature_c,
        humidity_pct=humidity_pct,
        temp_ref=config.get("temp_ref", 20.0),
        humidity_ref=config.get("humidity_ref", 50.0)
    )
    effective = compute_effective_aging_factor(
        aging_intensity=aging_intensity,
        env_bias=env_bias,
        stability_guard=config.get("stability_guard", 0.85)
    )
    return {
        "age_days": age_days,
        "aging_intensity": aging_intensity,
        "environment_bias": env_bias,
        "effective_factor": effective
    }
# ==============================================================================
# END OF SUBCHUNK 84 K 01 — FILM AGING & STORAGE EFFECTS (MASTER ONSET)
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 K 02 — STORAGE TEMPERATURE BIAS MODELING
# ==============================================================================
# Purpose:
#   Model temperature-driven chemical acceleration or retardation in film stock
#   during storage and handling, affecting dye stability, contrast, and color
#   balance in a physically plausible, temporally coherent way.
#
# Cinematic relevance:
#   - Explains warm/cool bias differences between reels
#   - Prevents uniform aging across environments
#   - Critical for archival vs on-set footage mixing
#
# Runs AFTER:
#   - 84 K 01 (Film Aging & Storage Effects — Master Onset)
# ==============================================================================
import numpy as np
def compute_temperature_acceleration(
    temperature_c: float,
    ref_temperature_c: float = 20.0,
    q10: float = 2.0
) -> float:
    """
    Computes Arrhenius-like temperature acceleration factor using Q10 model.
    Every +10°C roughly doubles chemical reaction rates in film dyes.
    """
    delta = temperature_c - ref_temperature_c
    return float(q10 ** (delta / 10.0))
def compute_temperature_color_bias(
    temperature_c: float,
    warm_bias_scale: float = 0.035,
    cool_bias_scale: float = 0.025
) -> np.ndarray:
    """
    Computes RGB color bias induced by storage temperature.
    Higher temperatures tend to warm highlights and midtones due to dye fogging.
    Lower temperatures preserve blue/cyan dyes more strongly.
    """
    if temperature_c >= 20.0:
        warm_strength = (temperature_c - 20.0) * warm_bias_scale
        return np.array(
            [1.0 + warm_strength,
             1.0,
             1.0 - warm_strength * 0.85],
            dtype=np.float32
        )
    else:
        cool_strength = (20.0 - temperature_c) * cool_bias_scale
        return np.array(
            [1.0 - cool_strength * 0.65,
             1.0,
             1.0 + cool_strength],
            dtype=np.float32
        )
def apply_temperature_bias_to_rgb(
    rgb_image: np.ndarray,
    bias_curve: np.ndarray,
    intensity: float
) -> np.ndarray:
    """
    Applies temperature-induced color bias to image.
    """
    intensity = np.clip(intensity, 0.0, 1.0)
    biased = rgb_image.copy()
    for c in range(3):
        biased[:, :, c] *= (
            (1.0 - intensity) + intensity * bias_curve[c]
        )
    return biased
def apply_temperature_contrast_shift(
    rgb_image: np.ndarray,
    temperature_c: float,
    max_contrast_loss: float = 0.08
) -> np.ndarray:
    """
    Applies contrast softening or preservation based on storage temperature.
    Higher temps reduce micro-contrast via chemical fogging.
    """
    if temperature_c <= 20.0:
        return rgb_image
    loss = np.clip(
        (temperature_c - 20.0) * 0.01,
        0.0,
        max_contrast_loss
    )
    mean = np.mean(rgb_image, axis=2, keepdims=True)
    return mean + (rgb_image - mean) * (1.0 - loss)
def temperature_energy_guard(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.2
) -> np.ndarray:
    """
    Prevents brightness drift from temperature bias operations.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_storage_temperature_bias(
    rgb_image: np.ndarray,
    aging_state: dict,
    temperature_c: float,
    config: dict
) -> np.ndarray:
    """
    Applies storage temperature bias using master aging state.
    """
    effective_factor = aging_state.get("effective_factor", 0.0)
    accel = compute_temperature_acceleration(
        temperature_c=temperature_c,
        ref_temperature_c=config.get("ref_temperature_c", 20.0),
        q10=config.get("q10", 2.0)
    )
    bias_curve = compute_temperature_color_bias(
        temperature_c=temperature_c,
        warm_bias_scale=config.get("warm_bias_scale", 0.035),
        cool_bias_scale=config.get("cool_bias_scale", 0.025)
    )
    intensity = np.clip(
        effective_factor * np.log1p(accel),
        0.0,
        1.0
    )
    biased = apply_temperature_bias_to_rgb(
        rgb_image=rgb_image,
        bias_curve=bias_curve,
        intensity=intensity
    )
    biased = apply_temperature_contrast_shift(
        rgb_image=biased,
        temperature_c=temperature_c,
        max_contrast_loss=config.get("max_contrast_loss", 0.08)
    )
    return temperature_energy_guard(
        original=rgb_image,
        processed=biased,
        max_gain=config.get("max_gain", 1.2)
    )
# ==============================================================================
# END OF SUBCHUNK 84 K 02 — STORAGE TEMPERATURE BIAS MODELING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 K 03 — HUMIDITY-DRIVEN EMULSION SHIFT
# ==============================================================================
# Purpose:
#   Simulate humidity-induced emulsion swelling, dye diffusion, and selective
#   spectral instability caused by moisture absorption in film layers during
#   storage and handling.
#
# Cinematic relevance:
#   - Explains cyan/magenta drift in humid environments
#   - Adds realistic shadow softness in tropical storage conditions
#   - Essential for long-term archival realism
#
# Runs AFTER:
#   - 84 K 02 (Storage Temperature Bias Modeling)
# ==============================================================================
import numpy as np
def compute_humidity_diffusion_factor(
    humidity_pct: float,
    ref_humidity: float = 50.0,
    max_factor: float = 1.6
) -> float:
    """
    Computes dye diffusion acceleration due to humidity.
    Higher humidity increases emulsion swelling and dye mobility.
    """
    delta = max(humidity_pct - ref_humidity, 0.0)
    factor = 1.0 + (delta / 50.0)
    return float(np.clip(factor, 1.0, max_factor))
def compute_humidity_color_shift(
    humidity_pct: float,
    cyan_sensitivity: float = 0.045,
    magenta_sensitivity: float = 0.025
) -> np.ndarray:
    """
    Computes RGB bias from humidity-driven dye instability.
    Cyan dyes are most humidity-sensitive, magenta moderately so.
    """
    excess = max(humidity_pct - 50.0, 0.0)
    cyan_loss = excess * cyan_sensitivity * 0.01
    magenta_loss = excess * magenta_sensitivity * 0.01
    return np.array(
        [
            1.0 - magenta_loss,
            1.0,
            1.0 - cyan_loss
        ],
        dtype=np.float32
    )
def apply_emulsion_softening(
    rgb_image: np.ndarray,
    humidity_pct: float,
    max_softening: float = 0.06
) -> np.ndarray:
    """
    Applies micro-contrast softening due to emulsion swelling.
    """
    if humidity_pct <= 55.0:
        return rgb_image
    softness = np.clip(
        (humidity_pct - 55.0) * 0.004,
        0.0,
        max_softening
    )
    mean = np.mean(rgb_image, axis=2, keepdims=True)
    return mean + (rgb_image - mean) * (1.0 - softness)
def humidity_energy_guard(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.15
) -> np.ndarray:
    """
    Prevents luminance drift from humidity-induced operations.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_humidity_emulsion_shift(
    rgb_image: np.ndarray,
    aging_state: dict,
    humidity_pct: float,
    config: dict
) -> np.ndarray:
    """
    Applies humidity-driven emulsion shift using master aging state.
    """
    effective_factor = aging_state.get("effective_factor", 0.0)
    diffusion = compute_humidity_diffusion_factor(
        humidity_pct=humidity_pct,
        ref_humidity=config.get("ref_humidity", 50.0),
        max_factor=config.get("max_factor", 1.6)
    )
    color_bias = compute_humidity_color_shift(
        humidity_pct=humidity_pct,
        cyan_sensitivity=config.get("cyan_sensitivity", 0.045),
        magenta_sensitivity=config.get("magenta_sensitivity", 0.025)
    )
    intensity = np.clip(
        effective_factor * np.log1p(diffusion),
        0.0,
        1.0
    )
    biased = rgb_image.copy()
    for c in range(3):
        biased[:, :, c] *= (1.0 - intensity) + intensity * color_bias[c]
    softened = apply_emulsion_softening(
        rgb_image=biased,
        humidity_pct=humidity_pct,
        max_softening=config.get("max_softening", 0.06)
    )
    return humidity_energy_guard(
        original=rgb_image,
        processed=softened,
        max_gain=config.get("max_gain", 1.15)
    )
# ==============================================================================
# END OF SUBCHUNK 84 K 03 — HUMIDITY-DRIVEN EMULSION SHIFT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 K 04 — LONG-TERM DENSITY COMPRESSION
# ==============================================================================
# Purpose:
#   Simulate gradual density compression in aged film where silver halide
#   exhaustion, dye fogging, and base contamination reduce contrast range over
#   long storage periods.
#
# Cinematic relevance:
#   - Prevents "too clean" contrast in aged footage
#   - Matches archival and stored-film response curves
#   - Especially visible in shadows and upper midtones
#
# Runs AFTER:
#   - 84 K 03 (Humidity-Driven Emulsion Shift)
# ==============================================================================
import numpy as np
def compute_density_compression_curve(
    aging_factor: float,
    max_compression: float = 0.22
) -> float:
    """
    Computes density compression factor from effective aging.
    """
    aging_factor = np.clip(aging_factor, 0.0, 1.25)
    return float(np.clip(aging_factor * max_compression, 0.0, max_compression))
def apply_density_compression(
    rgb_image: np.ndarray,
    compression: float
) -> np.ndarray:
    """
    Compresses tonal density symmetrically toward mid-gray.
    """
    if compression <= 0.0:
        return rgb_image
    # Film mid-density anchor (~18% gray)
    mid = 0.18
    return mid + (rgb_image - mid) * (1.0 - compression)
def adaptive_shadow_guard(
    original: np.ndarray,
    compressed: np.ndarray,
    shadow_floor: float = 0.02
) -> np.ndarray:
    """
    Prevents total shadow collapse after density compression.
    """
    shadow_mask = original < shadow_floor
    compressed[shadow_mask] = original[shadow_mask]
    return compressed
def density_energy_guard(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.25
) -> np.ndarray:
    """
    Maintains overall exposure energy consistency.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_long_term_density_compression(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies long-term density compression driven by film aging.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    compression = compute_density_compression_curve(
        aging_factor=aging_factor,
        max_compression=config.get("max_compression", 0.22)
    )
    compressed = apply_density_compression(
        rgb_image=rgb_image,
        compression=compression
    )
    compressed = adaptive_shadow_guard(
        original=rgb_image,
        compressed=compressed,
        shadow_floor=config.get("shadow_floor", 0.02)
    )
    return density_energy_guard(
        original=rgb_image,
        processed=compressed,
        max_gain=config.get("max_gain", 1.25)
    )
# ==============================================================================
# END OF SUBCHUNK 84 K 04 — LONG-TERM DENSITY COMPRESSION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 K 05 — AGING SATURATION ROLL-OFF
# ==============================================================================
# Purpose:
#   Simulate gradual saturation loss in aged film caused by dye fading,
#   chemical instability, and base fog accumulation over long storage periods.
#
# Cinematic relevance:
#   - Prevents unrealistically vibrant colors in aged footage
#   - Matches archival film behavior
#   - Strongly affects skin tones, foliage, and skies
#
# Runs AFTER:
#   - 84 K 04 (Long-Term Density Compression)
# ==============================================================================
import numpy as np
def compute_saturation_rolloff(
    aging_factor: float,
    max_rolloff: float = 0.28
) -> float:
    """
    Computes saturation roll-off factor from effective aging.
    """
    aging_factor = np.clip(aging_factor, 0.0, 1.25)
    return float(np.clip(aging_factor * max_rolloff, 0.0, max_rolloff))
def apply_saturation_rolloff(
    rgb_image: np.ndarray,
    rolloff: float
) -> np.ndarray:
    """
    Reduces chroma while preserving luminance.
    """
    if rolloff <= 0.0:
        return rgb_image
    # Compute luminance
    lum = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    lum = lum[:, :, None]
    # Separate chroma
    chroma = rgb_image - lum
    # Apply roll-off
    chroma *= (1.0 - rolloff)
    return lum + chroma
def hue_preservation_guard(
    original: np.ndarray,
    desaturated: np.ndarray,
    max_hue_shift: float = 0.015
) -> np.ndarray:
    """
    Prevents excessive hue drift during saturation loss.
    """
    delta = desaturated - original
    delta = np.clip(delta, -max_hue_shift, max_hue_shift)
    return original + delta
def saturation_energy_guard(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.2
) -> np.ndarray:
    """
    Maintains exposure consistency after saturation changes.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_aging_saturation_rolloff(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies saturation roll-off driven by film aging.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    rolloff = compute_saturation_rolloff(
        aging_factor=aging_factor,
        max_rolloff=config.get("max_rolloff", 0.28)
    )
    desaturated = apply_saturation_rolloff(
        rgb_image=rgb_image,
        rolloff=rolloff
    )
    desaturated = hue_preservation_guard(
        original=rgb_image,
        desaturated=desaturated,
        max_hue_shift=config.get("max_hue_shift", 0.015)
    )
    return saturation_energy_guard(
        original=rgb_image,
        processed=desaturated,
        max_gain=config.get("max_gain", 1.2)
    )
# ==============================================================================
# END OF SUBCHUNK 84 K 05 — AGING SATURATION ROLL-OFF
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 K 06 — DYE STABILITY LOSS OVER TIME
# ==============================================================================
# Purpose:
#   Model differential fading and instability of color dye layers (C/M/Y)
#   caused by chemical decay, oxygen exposure, and storage conditions.
#
# Cinematic relevance:
#   - Produces authentic archival color bias (cyan loss, magenta drift)
#   - Prevents uniform desaturation artifacts
#   - Highly visible in skies, skin tones, and shadows
#
# Runs AFTER:
#   - 84 K 05 (Aging Saturation Roll-Off)
# ==============================================================================
import numpy as np
def compute_dye_decay_factors(
    aging_factor: float,
    stability_profile: dict
) -> np.ndarray:
    """
    Computes per-channel dye decay multipliers.
    stability_profile keys:
        'cyan', 'magenta', 'yellow' : relative decay sensitivities
    """
    aging_factor = np.clip(aging_factor, 0.0, 1.25)
    # Empirical ordering: Cyan decays fastest, Yellow slowest
    c = 1.0 - aging_factor * stability_profile.get("cyan", 0.32)
    m = 1.0 - aging_factor * stability_profile.get("magenta", 0.24)
    y = 1.0 - aging_factor * stability_profile.get("yellow", 0.18)
    return np.clip(np.array([c, m, y]), 0.55, 1.0)
def apply_dye_stability_loss(
    rgb_image: np.ndarray,
    dye_factors: np.ndarray
) -> np.ndarray:
    """
    Applies dye decay factors in subtractive color approximation.
    """
    # Convert RGB to approximate CMY density space
    cmy = 1.0 - np.clip(rgb_image, 0.0, 1.0)
    # Apply decay
    cmy[:, :, 0] *= dye_factors[0]  # Cyan
    cmy[:, :, 1] *= dye_factors[1]  # Magenta
    cmy[:, :, 2] *= dye_factors[2]  # Yellow
    # Convert back to RGB
    return np.clip(1.0 - cmy, 0.0, 1.0)
def chroma_balance_guard(
    original: np.ndarray,
    processed: np.ndarray,
    max_bias: float = 0.06
) -> np.ndarray:
    """
    Prevents extreme color bias collapse.
    """
    delta = processed - original
    delta = np.clip(delta, -max_bias, max_bias)
    return original + delta
def dye_energy_compensation(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.15
) -> np.ndarray:
    """
    Maintains luminance energy after dye decay.
    """
    lum_o = np.mean(original, axis=2)
    lum_p = np.mean(processed, axis=2)
    ratio = np.ones_like(lum_o)
    mask = lum_p > 1e-6
    ratio[mask] = lum_o[mask] / lum_p[mask]
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_dye_stability_loss(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies dye-layer stability loss driven by film aging.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    dye_factors = compute_dye_decay_factors(
        aging_factor=aging_factor,
        stability_profile=config.get(
            "stability_profile",
            {"cyan": 0.32, "magenta": 0.24, "yellow": 0.18}
        )
    )
    processed = apply_dye_stability_loss(
        rgb_image=rgb_image,
        dye_factors=dye_factors
    )
    processed = chroma_balance_guard(
        original=rgb_image,
        processed=processed,
        max_bias=config.get("max_bias", 0.06)
    )
    return dye_energy_compensation(
        original=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.15)
    )
# ==============================================================================
# END OF SUBCHUNK 84 K 06 — DYE STABILITY LOSS OVER TIME
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 K 07 — AGING SHADOW LIFT
# ==============================================================================
# Purpose:
#   Simulate shadow toe lift caused by base fog, chemical contamination,
#   and silver halide residue accumulation over long-term storage.
#
# Cinematic relevance:
#   - Removes digitally-crushed blacks in aged footage
#   - Produces authentic milky toe and reduced Dmax
#   - Highly visible in night scenes and low-key interiors
#
# Runs AFTER:
#   - 84 K 06 (Dye Stability Loss Over Time)
# ==============================================================================
import numpy as np
def compute_shadow_lift(
    aging_factor: float,
    max_lift: float = 0.06
) -> float:
    """
    Computes shadow lift amount from effective aging.
    """
    aging_factor = np.clip(aging_factor, 0.0, 1.25)
    return float(np.clip(aging_factor * max_lift, 0.0, max_lift))
def apply_shadow_lift_curve(
    rgb_image: np.ndarray,
    lift: float,
    pivot: float = 0.18
) -> np.ndarray:
    """
    Lifts shadows with a smooth toe curve while preserving midtones.
    """
    if lift <= 0.0:
        return rgb_image
    # Luminance proxy for toe shaping
    lum = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    # Toe mask: stronger in shadows, zero near pivot
    toe_mask = np.clip((pivot - lum) / max(pivot, 1e-6), 0.0, 1.0)
    # Apply lift proportionally
    lifted = rgb_image + toe_mask[:, :, None] * lift
    return np.clip(lifted, 0.0, 1.0)
def black_floor_guard(
    original: np.ndarray,
    processed: np.ndarray,
    min_black: float = 0.004
) -> np.ndarray:
    """
    Ensures a realistic minimum black floor (no absolute zero).
    """
    return np.maximum(processed, min_black)
def shadow_energy_compensation(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.12
) -> np.ndarray:
    """
    Preserves overall exposure energy after shadow lift.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_aging_shadow_lift(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies aging-driven shadow lift (film toe fog).
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    lift = compute_shadow_lift(
        aging_factor=aging_factor,
        max_lift=config.get("max_lift", 0.06)
    )
    lifted = apply_shadow_lift_curve(
        rgb_image=rgb_image,
        lift=lift,
        pivot=config.get("pivot", 0.18)
    )
    lifted = black_floor_guard(
        original=rgb_image,
        processed=lifted,
        min_black=config.get("min_black", 0.004)
    )
    return shadow_energy_compensation(
        original=rgb_image,
        processed=lifted,
        max_gain=config.get("max_gain", 1.12)
    )
# ==============================================================================
# END OF SUBCHUNK 84 K 07 — AGING SHADOW LIFT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 K 08 — AGING HIGHLIGHT BLEACH
# ==============================================================================
# Purpose:
#   Simulate progressive highlight density loss due to dye exhaustion and
#   emulsion fatigue, causing airy, washed highlights in aged film.
#
# Cinematic relevance:
#   - Prevents digitally-hard highlights in archival looks
#   - Produces authentic highlight thinning and veil
#   - Highly visible in skies, speculars, and bright fabrics
#
# Runs AFTER:
#   - 84 K 07 (Aging Shadow Lift)
# ==============================================================================
import numpy as np
def compute_highlight_bleach(
    aging_factor: float,
    max_bleach: float = 0.18
) -> float:
    """
    Computes highlight bleach amount from effective aging.
    """
    aging_factor = np.clip(aging_factor, 0.0, 1.25)
    return float(np.clip(aging_factor * max_bleach, 0.0, max_bleach))
def apply_highlight_bleach_curve(
    rgb_image: np.ndarray,
    bleach: float,
    pivot: float = 0.65
) -> np.ndarray:
    """
    Applies a soft shoulder flattening to highlights.
    """
    if bleach <= 0.0:
        return rgb_image
    lum = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    # Shoulder mask increases above pivot
    shoulder = np.clip((lum - pivot) / max(1.0 - pivot, 1e-6), 0.0, 1.0)
    # Pull highlights toward pivot (density loss)
    compressed = rgb_image - shoulder[:, :, None] * bleach * (rgb_image - pivot)
    return np.clip(compressed, 0.0, 1.0)
def specular_preservation_guard(
    original: np.ndarray,
    processed: np.ndarray,
    max_delta: float = 0.08
) -> np.ndarray:
    """
    Preserves specular integrity while allowing bleach.
    """
    delta = processed - original
    delta = np.clip(delta, -max_delta, max_delta)
    return original + delta
def highlight_energy_compensation(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.10
) -> np.ndarray:
    """
    Maintains global exposure energy after highlight bleaching.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_aging_highlight_bleach(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies aging-driven highlight bleach (shoulder thinning).
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    bleach = compute_highlight_bleach(
        aging_factor=aging_factor,
        max_bleach=config.get("max_bleach", 0.18)
    )
    bleached = apply_highlight_bleach_curve(
        rgb_image=rgb_image,
        bleach=bleach,
        pivot=config.get("pivot", 0.65)
    )
    bleached = specular_preservation_guard(
        original=rgb_image,
        processed=bleached,
        max_delta=config.get("max_delta", 0.08)
    )
    return highlight_energy_compensation(
        original=rgb_image,
        processed=bleached,
        max_gain=config.get("max_gain", 1.10)
    )
# ==============================================================================
# END OF SUBCHUNK 84 K 08 — AGING HIGHLIGHT BLEACH
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 K 09 — TEMPORAL AGING COLOR DRIFT
# ==============================================================================
# Purpose:
#   Simulate slow, stochastic chromatic drift over time caused by
#   chemical instability, uneven dye decay, and base fog evolution.
#
# Cinematic relevance:
#   - Prevents "static grade" look in aged sequences
#   - Adds living, breathing archival instability
#   - Extremely visible in long takes and slow camera moves
#
# Runs AFTER:
#   - 84 K 08 (Aging Highlight Bleach)
# ==============================================================================
import numpy as np
def generate_temporal_drift_vector(
    frame_index: int,
    drift_scale: float = 0.004,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates a slow-varying RGB drift vector.
    """
    if seed is not None:
        np.random.seed(seed + frame_index)
    # Low-frequency random walk
    base = np.random.normal(0.0, drift_scale, size=3)
    # Bias toward known film aging tendencies
    # Cyan loss → warm drift
    bias = np.array([+0.6, -0.2, -0.4])
    drift = base * bias
    return np.clip(drift, -0.01, 0.01)
def apply_temporal_color_drift(
    rgb_image: np.ndarray,
    drift_vector: np.ndarray,
    strength: float = 1.0
) -> np.ndarray:
    """
    Applies chromatic drift uniformly to the frame.
    """
    drift = drift_vector[None, None, :] * strength
    return np.clip(rgb_image + drift, 0.0, 1.0)
def temporal_coherence_guard(
    previous_rgb: np.ndarray | None,
    current_rgb: np.ndarray,
    max_delta: float = 0.015
) -> np.ndarray:
    """
    Prevents visible flicker by limiting inter-frame chroma jumps.
    """
    if previous_rgb is None:
        return current_rgb
    delta = current_rgb - previous_rgb
    delta = np.clip(delta, -max_delta, max_delta)
    return previous_rgb + delta
def chroma_energy_balance(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.08
) -> np.ndarray:
    """
    Preserves overall exposure and color energy.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_temporal_aging_color_drift(
    rgb_image: np.ndarray,
    frame_index: int,
    previous_rgb: np.ndarray | None,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies slow temporal chromatic drift driven by aging chemistry.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    drift_vec = generate_temporal_drift_vector(
        frame_index=frame_index,
        drift_scale=config.get("drift_scale", 0.004) * aging_factor,
        seed=config.get("seed", None)
    )
    drifted = apply_temporal_color_drift(
        rgb_image=rgb_image,
        drift_vector=drift_vec,
        strength=config.get("strength", 1.0)
    )
    drifted = temporal_coherence_guard(
        previous_rgb=previous_rgb,
        current_rgb=drifted,
        max_delta=config.get("max_delta", 0.015)
    )
    return chroma_energy_balance(
        original=rgb_image,
        processed=drifted,
        max_gain=config.get("max_gain", 1.08)
    )
# ==============================================================================
# END OF SUBCHUNK 84 K 09 — TEMPORAL AGING COLOR DRIFT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 K 10 — AGING INTENSITY MASTER CONTROL
# ==============================================================================
# Purpose:
#   Provide a unified, physically-plausible master control that modulates
#   ALL aging-related effects (density, saturation, dye decay, shadow lift,
#   highlight bleach, temporal drift) in a coherent and art-directable way.
#
# Cinematic relevance:
#   - Enables precise matching of aging look across shots and sequences
#   - Prevents over-stacking or runaway degradation
#   - Allows dynamic aging ramps (flashbacks, archival transitions, etc.)
#
# Runs AFTER:
#   - 84 K 09 (Temporal Aging Color Drift)
# ==============================================================================
import numpy as np
def compute_global_aging_scalar(
    user_intensity: float,
    time_years: float,
    storage_quality: float = 1.0
) -> float:
    """
    Computes a physically-grounded global aging scalar.
    Parameters:
        user_intensity:
            Artistic control [0..1]
        time_years:
            Simulated storage time in years
        storage_quality:
            1.0 = archival, <1.0 = poor storage
    """
    user_intensity = np.clip(user_intensity, 0.0, 1.0)
    storage_quality = np.clip(storage_quality, 0.25, 1.25)
    # Film aging roughly follows a logarithmic response over time
    time_factor = np.log1p(time_years) / np.log1p(50.0)
    time_factor = np.clip(time_factor, 0.0, 1.25)
    return float(np.clip(user_intensity * time_factor / storage_quality, 0.0, 1.25))
def apply_aging_intensity_scaling(
    aging_state: dict,
    global_scalar: float
) -> dict:
    """
    Scales all aging sub-components coherently.
    """
    scaled = {}
    for key, value in aging_state.items():
        if isinstance(value, (int, float)):
            scaled[key] = value * global_scalar
        else:
            scaled[key] = value
    return scaled
def temporal_ramp_guard(
    previous_scalar: float | None,
    current_scalar: float,
    max_step: float = 0.02
) -> float:
    """
    Prevents visible jumps in aging intensity across frames.
    """
    if previous_scalar is None:
        return current_scalar
    delta = current_scalar - previous_scalar
    delta = np.clip(delta, -max_step, max_step)
    return previous_scalar + delta
def aging_energy_normalization(
    rgb_image: np.ndarray,
    reference_rgb: np.ndarray,
    max_gain: float = 1.05
) -> np.ndarray:
    """
    Final guard to ensure aging does not unintentionally alter exposure.
    """
    rms_r = np.sqrt(np.mean(reference_rgb ** 2))
    rms_o = np.sqrt(np.mean(rgb_image ** 2))
    if rms_o < 1e-6:
        return rgb_image
    gain = np.clip(rms_r / rms_o, 1.0 / max_gain, max_gain)
    return rgb_image * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_aging_master_control(
    rgb_image: np.ndarray,
    aging_state: dict,
    user_controls: dict,
    previous_scalar: float | None,
    reference_rgb: np.ndarray,
    frame_index: int
) -> tuple[np.ndarray, dict, float]:
    """
    Applies master aging control and returns updated aging state.
    """
    global_scalar = compute_global_aging_scalar(
        user_intensity=user_controls.get("intensity", 1.0),
        time_years=user_controls.get("years", 0.0),
        storage_quality=user_controls.get("storage_quality", 1.0)
    )
    global_scalar = temporal_ramp_guard(
        previous_scalar=previous_scalar,
        current_scalar=global_scalar,
        max_step=user_controls.get("max_step", 0.02)
    )
    scaled_aging_state = apply_aging_intensity_scaling(
        aging_state=aging_state,
        global_scalar=global_scalar
    )
    rgb_image = aging_energy_normalization(
        rgb_image=rgb_image,
        reference_rgb=reference_rgb,
        max_gain=user_controls.get("max_gain", 1.05)
    )
    return rgb_image, scaled_aging_state, global_scalar
# ==============================================================================
# END OF SUBCHUNK 84 K 10 — AGING INTENSITY MASTER CONTROL
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 L 01 — ARCHIVAL FILM BASE FOG ACCUMULATION
# ==============================================================================
# Purpose:
#   Simulate gradual accumulation of base fog caused by chemical residue,
#   radiation exposure, oxidation, and emulsion contamination over time.
#
# Cinematic relevance:
#   - Creates lifted black floor typical of archival negatives
#   - Removes “perfect transparency” of modern sensors
#   - Highly visible in shadows, night scenes, and fades
#
# Runs AFTER:
#   - 84 K 10 (Aging Intensity Master Control)
# ==============================================================================
import numpy as np
def compute_base_fog_level(
    aging_factor: float,
    max_fog: float = 0.045
) -> float:
    """
    Computes base fog density from effective aging.
    """
    aging_factor = np.clip(aging_factor, 0.0, 1.25)
    return float(np.clip(aging_factor * max_fog, 0.0, max_fog))
def apply_base_fog(
    rgb_image: np.ndarray,
    fog_level: float
) -> np.ndarray:
    """
    Adds uniform base fog density across the frame.
    """
    if fog_level <= 0.0:
        return rgb_image
    fog = np.full_like(rgb_image, fog_level)
    return np.clip(rgb_image + fog, 0.0, 1.0)
def fog_luminance_weighting(
    original: np.ndarray,
    fogged: np.ndarray,
    bias: float = 0.7
) -> np.ndarray:
    """
    Applies stronger fog influence in shadows than highlights.
    """
    lum = (
        0.2126 * original[:, :, 0] +
        0.7152 * original[:, :, 1] +
        0.0722 * original[:, :, 2]
    )
    shadow_mask = np.clip(1.0 - lum, 0.0, 1.0) ** bias
    return np.clip(
        original + (fogged - original) * shadow_mask[:, :, None],
        0.0,
        1.0
    )
def base_fog_energy_guard(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.08
) -> np.ndarray:
    """
    Prevents unintended exposure inflation due to fog.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_archival_base_fog(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies archival film base fog accumulation.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    fog_level = compute_base_fog_level(
        aging_factor=aging_factor,
        max_fog=config.get("max_fog", 0.045)
    )
    fogged = apply_base_fog(
        rgb_image=rgb_image,
        fog_level=fog_level
    )
    fogged = fog_luminance_weighting(
        original=rgb_image,
        fogged=fogged,
        bias=config.get("shadow_bias", 0.7)
    )
    return base_fog_energy_guard(
        original=rgb_image,
        processed=fogged,
        max_gain=config.get("max_gain", 1.08)
    )
