# ==============================================================================
# SUBCHUNK 84 L 02 — BASE TINT SHIFT OVER TIME
# ==============================================================================
# Purpose:
#   Simulate chromatic tint shifts in the film base caused by aging polyester/
#   acetate substrates, chemical leaching, and long-term storage conditions.
#
# Cinematic relevance:
#   - Produces authentic warm/yellow or cool/cyan archival bias
#   - Prevents neutral-gray base fog artifacts
#   - Strongly visible in highlights, skies, and fades
#
# Runs AFTER:
#   - 84 L 01 (Archival Film Base Fog Accumulation)
# ==============================================================================
import numpy as np
def compute_base_tint_vector(
    aging_factor: float,
    tint_profile: dict
) -> np.ndarray:
    """
    Computes RGB tint vector for film base aging.
    tint_profile keys:
        'warm' : strength of yellow/red bias
        'cool' : strength of cyan/blue bias
    """
    aging_factor = np.clip(aging_factor, 0.0, 1.25)
    warm = tint_profile.get("warm", 0.015)
    cool = tint_profile.get("cool", 0.010)
    # Typical archival tendency: slight warm/yellow drift
    tint = np.array([
        warm * aging_factor,           # Red
        warm * 0.8 * aging_factor,     # Green
       -cool * aging_factor            # Blue
    ])
    return np.clip(tint, -0.05, 0.05)
def apply_base_tint(
    rgb_image: np.ndarray,
    tint_vector: np.ndarray
) -> np.ndarray:
    """
    Applies base tint uniformly to the image.
    """
    tinted = rgb_image + tint_vector[None, None, :]
    return np.clip(tinted, 0.0, 1.0)
def luminance_weighted_tint(
    original: np.ndarray,
    tinted: np.ndarray,
    highlight_bias: float = 0.6
) -> np.ndarray:
    """
    Biases base tint toward highlights where base is more visible.
    """
    lum = (
        0.2126 * original[:, :, 0] +
        0.7152 * original[:, :, 1] +
        0.0722 * original[:, :, 2]
    )
    weight = np.clip(lum ** highlight_bias, 0.0, 1.0)
    return np.clip(
        original + (tinted - original) * weight[:, :, None],
        0.0,
        1.0
    )
def base_tint_energy_guard(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.06
) -> np.ndarray:
    """
    Ensures base tint does not unintentionally alter exposure energy.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_base_tint_shift(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies film base tint shift driven by aging chemistry.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    tint_vector = compute_base_tint_vector(
        aging_factor=aging_factor,
        tint_profile=config.get(
            "tint_profile",
            {"warm": 0.015, "cool": 0.010}
        )
    )
    tinted = apply_base_tint(
        rgb_image=rgb_image,
        tint_vector=tint_vector
    )
    tinted = luminance_weighted_tint(
        original=rgb_image,
        tinted=tinted,
        highlight_bias=config.get("highlight_bias", 0.6)
    )
    return base_tint_energy_guard(
        original=rgb_image,
        processed=tinted,
        max_gain=config.get("max_gain", 1.06)
    )
# ==============================================================================
# END OF SUBCHUNK 84 L 02 — BASE TINT SHIFT OVER TIME
