# ==============================================================================
# SUBCHUNK 84 L 03 — BASE DENSITY NON-UNIFORMITY
# ==============================================================================
# Purpose:
#   Simulate spatial non-uniformity in film base density caused by
#   manufacturing tolerances, aging stress, chemical diffusion,
#   and uneven base fog accumulation.
#
# Cinematic relevance:
#   - Breaks digital flat-field perfection
#   - Introduces organic large-scale density breathing
#   - Extremely visible in skies, walls, fades, and long takes
#
# Runs AFTER:
#   - 84 L 02 (Base Tint Shift Over Time)
# ==============================================================================
import numpy as np
def generate_base_density_field(
    shape: tuple,
    scale: float = 0.015,
    octaves: int = 3,
    persistence: float = 0.55,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates a low-frequency base density variation field.
    """
    if seed is not None:
        np.random.seed(seed)
    h, w = shape
    field = np.zeros((h, w), dtype=np.float32)
    freq = 1.0
    amp = scale
    for _ in range(octaves):
        noise = np.random.normal(0.0, 1.0, size=(h, w))
        noise = np.fft.ifft2(np.fft.fft2(noise) * _low_pass_mask(h, w, freq)).real
        field += noise * amp
        freq *= 2.0
        amp *= persistence
    return np.clip(field, -0.05, 0.05)
def _low_pass_mask(h: int, w: int, freq: float) -> np.ndarray:
    """
    Generates a radial low-pass frequency mask.
    """
    y = np.linspace(-1, 1, h)[:, None]
    x = np.linspace(-1, 1, w)[None, :]
    r = np.sqrt(x * x + y * y)
    return np.exp(-(r * freq) ** 2)
def apply_base_density_field(
    rgb_image: np.ndarray,
    density_field: np.ndarray,
    strength: float = 1.0
) -> np.ndarray:
    """
    Applies base density non-uniformity to RGB image.
    """
    return np.clip(
        rgb_image + density_field[:, :, None] * strength,
        0.0,
        1.0
    )
def luminance_weighted_density(
    original: np.ndarray,
    processed: np.ndarray,
    shadow_bias: float = 0.8
) -> np.ndarray:
    """
    Biases density variation toward shadows and midtones.
    """
    lum = (
        0.2126 * original[:, :, 0] +
        0.7152 * original[:, :, 1] +
        0.0722 * original[:, :, 2]
    )
    weight = np.clip((1.0 - lum) ** shadow_bias, 0.0, 1.0)
    return np.clip(
        original + (processed - original) * weight[:, :, None],
        0.0,
        1.0
    )
def base_density_energy_guard(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.07
) -> np.ndarray:
    """
    Prevents exposure drift from density non-uniformity.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_base_density_nonuniformity(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies spatial base density non-uniformity.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    field = generate_base_density_field(
        shape=rgb_image.shape[:2],
        scale=config.get("scale", 0.015) * aging_factor,
        octaves=config.get("octaves", 3),
        persistence=config.get("persistence", 0.55),
        seed=config.get("seed", None)
    )
    processed = apply_base_density_field(
        rgb_image=rgb_image,
        density_field=field,
        strength=config.get("strength", 1.0)
    )
    processed = luminance_weighted_density(
        original=rgb_image,
        processed=processed,
        shadow_bias=config.get("shadow_bias", 0.8)
    )
    return base_density_energy_guard(
        original=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.07)
    )
# ==============================================================================
# END OF SUBCHUNK 84 L 03 — BASE DENSITY NON-UNIFORMITY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 L 04 — BASE CHEMICAL CONTAMINATION MODELING
# ==============================================================================
# Purpose:
#   Simulate chemical contamination in the film base caused by residual
#   fixer, developer carryover, oxidation, mold, and storage pollutants.
#
# Cinematic relevance:
#   - Introduces subtle chroma–density coupling artifacts
#   - Breaks mathematically clean base fog behavior
#   - Visible in archival prints, scanned negatives, and damaged reels
#
# Runs AFTER:
#   - 84 L 03 (Base Density Non-Uniformity)
# ==============================================================================
import numpy as np
def generate_contamination_field(
    shape: tuple,
    intensity: float,
    chroma_bias: tuple = (0.6, 0.3, 0.1),
    spatial_scale: float = 0.002,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates a low-energy chromatic contamination field.
    """
    if seed is not None:
        np.random.seed(seed)
    h, w = shape
    base = np.random.normal(0.0, 1.0, size=(h, w))
    # Low-pass filter contamination structure
    freq_mask = _contamination_low_pass(h, w, spatial_scale)
    base = np.fft.ifft2(np.fft.fft2(base) * freq_mask).real
    field = np.zeros((h, w, 3), dtype=np.float32)
    for c in range(3):
        field[:, :, c] = base * chroma_bias[c] * intensity
    return np.clip(field, -0.03, 0.03)
def _contamination_low_pass(h: int, w: int, scale: float) -> np.ndarray:
    """
    Radial low-pass mask for contamination diffusion.
    """
    y = np.linspace(-1, 1, h)[:, None]
    x = np.linspace(-1, 1, w)[None, :]
    r = np.sqrt(x * x + y * y)
    return np.exp(-(r / max(scale, 1e-6)) ** 2)
def apply_contamination(
    rgb_image: np.ndarray,
    contamination_field: np.ndarray,
    strength: float = 1.0
) -> np.ndarray:
    """
    Applies chemical contamination to RGB image.
    """
    return np.clip(
        rgb_image + contamination_field * strength,
        0.0,
        1.0
    )
def luminance_sensitive_contamination(
    original: np.ndarray,
    contaminated: np.ndarray,
    shadow_bias: float = 0.9
) -> np.ndarray:
    """
    Contamination is more visible in darker densities.
    """
    lum = (
        0.2126 * original[:, :, 0] +
        0.7152 * original[:, :, 1] +
        0.0722 * original[:, :, 2]
    )
    weight = np.clip((1.0 - lum) ** shadow_bias, 0.0, 1.0)
    return np.clip(
        original + (contaminated - original) * weight[:, :, None],
        0.0,
        1.0
    )
def contamination_energy_guard(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.06
) -> np.ndarray:
    """
    Prevents contamination from altering exposure energy.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_base_chemical_contamination(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies chemical contamination artifacts to film base.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    contamination = generate_contamination_field(
        shape=rgb_image.shape[:2],
        intensity=config.get("intensity", 0.015) * aging_factor,
        chroma_bias=config.get("chroma_bias", (0.6, 0.3, 0.1)),
        spatial_scale=config.get("spatial_scale", 0.002),
        seed=config.get("seed", None)
    )
    processed = apply_contamination(
        rgb_image=rgb_image,
        contamination_field=contamination,
        strength=config.get("strength", 1.0)
    )
    processed = luminance_sensitive_contamination(
        original=rgb_image,
        contaminated=processed,
        shadow_bias=config.get("shadow_bias", 0.9)
    )
    return contamination_energy_guard(
        original=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.06)
    )
# ==============================================================================
# END OF SUBCHUNK 84 L 04 — BASE CHEMICAL CONTAMINATION MODELING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 L 05 — BASE FOG TEMPORAL EVOLUTION
# ==============================================================================
# Purpose:
#   Simulate slow temporal evolution of film base fog caused by
#   chemical diffusion, environmental fluctuation, and latent image decay.
#
# Cinematic relevance:
#   - Prevents static “fog layer” artifacts
#   - Introduces organic, living archival instability
#   - Highly perceptible in long takes and fades
#
# Runs AFTER:
#   - 84 L 04 (Base Chemical Contamination Modeling)
# ==============================================================================
import numpy as np
def generate_temporal_fog_offset(
    frame_index: int,
    evolution_rate: float = 0.0015,
    seed: int | None = None
) -> float:
    """
    Generates a slow-varying scalar fog offset over time.
    """
    if seed is not None:
        np.random.seed(seed + frame_index // 8)
    # Very low-frequency random walk
    offset = np.random.normal(0.0, evolution_rate)
    return float(np.clip(offset, -0.01, 0.01))
def apply_temporal_fog_evolution(
    rgb_image: np.ndarray,
    fog_offset: float
) -> np.ndarray:
    """
    Applies temporal fog offset uniformly.
    """
    if abs(fog_offset) < 1e-6:
        return rgb_image
    fog = np.full_like(rgb_image, fog_offset)
    return np.clip(rgb_image + fog, 0.0, 1.0)
def temporal_fog_coherence_guard(
    previous_rgb: np.ndarray | None,
    current_rgb: np.ndarray,
    max_step: float = 0.006
) -> np.ndarray:
    """
    Prevents visible temporal stepping in fog evolution.
    """
    if previous_rgb is None:
        return current_rgb
    delta = current_rgb - previous_rgb
    delta = np.clip(delta, -max_step, max_step)
    return previous_rgb + delta
def fog_energy_stabilization(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.05
) -> np.ndarray:
    """
    Maintains exposure consistency during fog evolution.
    """
    rms_r = np.sqrt(np.mean(reference ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_r / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_base_fog_temporal_evolution(
    rgb_image: np.ndarray,
    frame_index: int,
    previous_rgb: np.ndarray | None,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies slow temporal evolution to film base fog.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    fog_offset = generate_temporal_fog_offset(
        frame_index=frame_index,
        evolution_rate=config.get("evolution_rate", 0.0015) * aging_factor,
        seed=config.get("seed", None)
    )
    evolved = apply_temporal_fog_evolution(
        rgb_image=rgb_image,
        fog_offset=fog_offset
    )
    evolved = temporal_fog_coherence_guard(
        previous_rgb=previous_rgb,
        current_rgb=evolved,
        max_step=config.get("max_step", 0.006)
    )
    return fog_energy_stabilization(
        reference=rgb_image,
        processed=evolved,
        max_gain=config.get("max_gain", 1.05)
    )
# ==============================================================================
# END OF SUBCHUNK 84 L 05 — BASE FOG TEMPORAL EVOLUTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 L 06 — BASE FOG SPATIAL INHOMOGENEITY
# ==============================================================================
# Purpose:
#   Introduce low-frequency spatial variation into film base fog caused by
#   uneven storage pressure, humidity gradients, and base-emulsion interactions.
#
# Cinematic relevance:
#   - Breaks spatial uniformity of base fog
#   - Adds authentic archival unevenness
#   - Visible in skies, walls, fades, and static frames
#
# Runs AFTER:
#   - 84 L 05 (Base Fog Temporal Evolution)
# ==============================================================================
import numpy as np
def generate_spatial_fog_field(
    shape: tuple,
    intensity: float = 0.01,
    spatial_scale: float = 0.003,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates a low-frequency spatial fog inhomogeneity field.
    """
    if seed is not None:
        np.random.seed(seed)
    h, w = shape
    noise = np.random.normal(0.0, 1.0, size=(h, w))
    mask = _fog_spatial_low_pass(h, w, spatial_scale)
    field = np.fft.ifft2(np.fft.fft2(noise) * mask).real
    field = field / (np.max(np.abs(field)) + 1e-6)
    return np.clip(field * intensity, -0.03, 0.03)
def _fog_spatial_low_pass(h: int, w: int, scale: float) -> np.ndarray:
    """
    Low-pass frequency mask tuned for film-base scale variation.
    """
    y = np.linspace(-1.0, 1.0, h)[:, None]
    x = np.linspace(-1.0, 1.0, w)[None, :]
    r = np.sqrt(x * x + y * y)
    return np.exp(-(r / max(scale, 1e-6)) ** 2)
def apply_spatial_fog(
    rgb_image: np.ndarray,
    fog_field: np.ndarray
) -> np.ndarray:
    """
    Applies spatial fog field uniformly across RGB channels.
    """
    fog_rgb = fog_field[:, :, None]
    return np.clip(rgb_image + fog_rgb, 0.0, 1.0)
def spatial_fog_density_weighting(
    original: np.ndarray,
    fogged: np.ndarray,
    shadow_bias: float = 0.85
) -> np.ndarray:
    """
    Spatial fog is more visible in dense/shadow regions.
    """
    lum = (
        0.2126 * original[:, :, 0] +
        0.7152 * original[:, :, 1] +
        0.0722 * original[:, :, 2]
    )
    weight = np.clip((1.0 - lum) ** shadow_bias, 0.0, 1.0)
    return np.clip(
        original + (fogged - original) * weight[:, :, None],
        0.0,
        1.0
    )
def spatial_fog_energy_guard(
    original: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.05
) -> np.ndarray:
    """
    Prevents spatial fog from altering overall exposure.
    """
    rms_o = np.sqrt(np.mean(original ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_o / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_base_fog_spatial_inhomogeneity(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies spatially varying base fog inhomogeneity.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    fog_field = generate_spatial_fog_field(
        shape=rgb_image.shape[:2],
        intensity=config.get("intensity", 0.01) * aging_factor,
        spatial_scale=config.get("spatial_scale", 0.003),
        seed=config.get("seed", None)
    )
    fogged = apply_spatial_fog(
        rgb_image=rgb_image,
        fog_field=fog_field
    )
    fogged = spatial_fog_density_weighting(
        original=rgb_image,
        fogged=fogged,
        shadow_bias=config.get("shadow_bias", 0.85)
    )
    return spatial_fog_energy_guard(
        original=rgb_image,
        processed=fogged,
        max_gain=config.get("max_gain", 1.05)
    )
# ==============================================================================
# END OF SUBCHUNK 84 L 06 — BASE FOG SPATIAL INHOMOGENEITY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 L 07 — BASE MICRO-DENSITY DRIFT
# ==============================================================================
# Purpose:
#   Simulate ultra-low-amplitude micro-density drift in the film base caused by
#   polymer relaxation, silver ion migration, and long-term chemical instability.
#
# Cinematic relevance:
#   - Removes digitally smooth gradients
#   - Adds organic, barely-visible density breathing
#   - Noticeable in large flat areas (skies, walls, fades)
#
# Runs AFTER:
#   - 84 L 06 (Base Fog Spatial Inhomogeneity)
# ==============================================================================
import numpy as np
def generate_micro_density_drift(
    shape: tuple,
    amplitude: float = 0.004,
    spatial_scale: float = 0.015,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates micro-scale density drift field.
    """
    if seed is not None:
        np.random.seed(seed)
    h, w = shape
    noise = np.random.normal(0.0, 1.0, size=(h, w))
    mask = _micro_drift_low_pass(h, w, spatial_scale)
    drift = np.fft.ifft2(np.fft.fft2(noise) * mask).real
    drift /= (np.max(np.abs(drift)) + 1e-6)
    return np.clip(drift * amplitude, -0.01, 0.01)
def _micro_drift_low_pass(h: int, w: int, scale: float) -> np.ndarray:
    """
    Higher-frequency passband than base fog; still non-grain.
    """
    y = np.linspace(-1.0, 1.0, h)[:, None]
    x = np.linspace(-1.0, 1.0, w)[None, :]
    r = np.sqrt(x * x + y * y)
    return np.exp(-(r / max(scale, 1e-6)) ** 4)
def apply_micro_density_drift(
    rgb_image: np.ndarray,
    drift_field: np.ndarray
) -> np.ndarray:
    """
    Applies micro-density drift uniformly across channels.
    """
    drift_rgb = drift_field[:, :, None]
    return np.clip(rgb_image + drift_rgb, 0.0, 1.0)
def density_luminance_modulation(
    original: np.ndarray,
    drifted: np.ndarray,
    midtone_bias: float = 0.55
) -> np.ndarray:
    """
    Micro-density drift most visible in mid-density regions.
    """
    lum = (
        0.2126 * original[:, :, 0] +
        0.7152 * original[:, :, 1] +
        0.0722 * original[:, :, 2]
    )
    weight = np.exp(-((lum - 0.5) ** 2) / max(midtone_bias ** 2, 1e-6))
    weight = np.clip(weight, 0.0, 1.0)
    return np.clip(
        original + (drifted - original) * weight[:, :, None],
        0.0,
        1.0
    )
def micro_density_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.03
) -> np.ndarray:
    """
    Ensures micro-density drift does not alter global exposure.
    """
    rms_r = np.sqrt(np.mean(reference ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_r / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_base_micro_density_drift(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies micro-density drift to film base.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    drift = generate_micro_density_drift(
        shape=rgb_image.shape[:2],
        amplitude=config.get("amplitude", 0.004) * aging_factor,
        spatial_scale=config.get("spatial_scale", 0.015),
        seed=config.get("seed", None)
    )
    drifted = apply_micro_density_drift(
        rgb_image=rgb_image,
        drift_field=drift
    )
    drifted = density_luminance_modulation(
        original=rgb_image,
        drifted=drifted,
        midtone_bias=config.get("midtone_bias", 0.55)
    )
    return micro_density_energy_guard(
        reference=rgb_image,
        processed=drifted,
        max_gain=config.get("max_gain", 1.03)
    )
# ==============================================================================
# END OF SUBCHUNK 84 L 07 — BASE MICRO-DENSITY DRIFT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 L 08 — BASE AGING INTENSITY COUPLING
# ==============================================================================
# Purpose:
#   Couple film base aging intensity to local exposure density and accumulated
#   chemical stress, producing non-linear, exposure-aware aging behavior.
#
# Cinematic relevance:
#   - Prevents uniform aging overlays
#   - Makes bright regions age differently from shadows
#   - Essential for believable archival progression
#
# Runs AFTER:
#   - 84 L 07 (Base Micro-Density Drift)
# ==============================================================================
import numpy as np
def compute_exposure_density(
    rgb_image: np.ndarray,
    gamma: float = 1.0
) -> np.ndarray:
    """
    Computes exposure density proxy from RGB luminance.
    """
    lum = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    lum = np.clip(lum, 0.0, 1.0)
    return np.clip(lum ** gamma, 0.0, 1.0)
def compute_aging_coupling_field(
    exposure_density: np.ndarray,
    aging_factor: float,
    coupling_curve: tuple = (0.6, 1.4)
) -> np.ndarray:
    """
    Produces a non-linear coupling field linking exposure to aging strength.
    """
    low, high = coupling_curve
    # Shadows and highlights age differently
    curve = low + (high - low) * exposure_density
    coupled = curve * aging_factor
    return np.clip(coupled, 0.0, aging_factor * 1.6)
def apply_aging_coupling(
    rgb_image: np.ndarray,
    coupling_field: np.ndarray,
    strength: float = 1.0
) -> np.ndarray:
    """
    Applies aging coupling by modulating base density.
    """
    mod = coupling_field[:, :, None] * strength
    return np.clip(rgb_image + mod, 0.0, 1.0)
def coupling_temporal_smoothing(
    previous: np.ndarray | None,
    current: np.ndarray,
    alpha: float = 0.15
) -> np.ndarray:
    """
    Smooths coupling evolution across frames.
    """
    if previous is None:
        return current
    return np.clip(
        previous * (1.0 - alpha) + current * alpha,
        0.0,
        1.0
    )
def coupling_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.04
) -> np.ndarray:
    """
    Ensures coupling does not drift exposure energy.
    """
    rms_r = np.sqrt(np.mean(reference ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_r / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_base_aging_intensity_coupling(
    rgb_image: np.ndarray,
    previous_rgb: np.ndarray | None,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies exposure-coupled aging intensity modulation.
    """
    aging_factor = aging_state.get("effective_factor", 0.0)
    exposure_density = compute_exposure_density(
        rgb_image=rgb_image,
        gamma=config.get("density_gamma", 1.0)
    )
    coupling_field = compute_aging_coupling_field(
        exposure_density=exposure_density,
        aging_factor=aging_factor,
        coupling_curve=config.get("coupling_curve", (0.6, 1.4))
    )
    coupled = apply_aging_coupling(
        rgb_image=rgb_image,
        coupling_field=coupling_field,
        strength=config.get("strength", 1.0)
    )
    coupled = coupling_temporal_smoothing(
        previous=previous_rgb,
        current=coupled,
        alpha=config.get("temporal_alpha", 0.15)
    )
    return coupling_energy_guard(
        reference=rgb_image,
        processed=coupled,
        max_gain=config.get("max_gain", 1.04)
    )
# ==============================================================================
# END OF SUBCHUNK 84 L 08 — BASE AGING INTENSITY COUPLING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 M 01 — EMULSION LAYER STRESS RESPONSE
# ==============================================================================
# Purpose:
#   Simulate mechanical and chemical stress responses in the emulsion layer
#   caused by aging, temperature cycling, humidity, and base-emulsion mismatch.
#
# Cinematic relevance:
#   - Subtle softening and tension-related sharpness variation
#   - Highlight edge instability (pre-halation behavior)
#   - Non-digital micro-deformation of fine detail
#
# Runs AFTER:
#   - 84 L 08 (Base Aging Intensity Coupling)
# ==============================================================================
import numpy as np
def compute_emulsion_stress_field(
    shape: tuple,
    stress_level: float,
    spatial_scale: float = 0.01,
    anisotropy: float = 0.35,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates emulsion stress field representing micro-tension patterns.
    """
    if seed is not None:
        np.random.seed(seed)
    h, w = shape
    base = np.random.normal(0.0, 1.0, size=(h, w))
    mask = _emulsion_stress_low_pass(h, w, spatial_scale)
    field = np.fft.ifft2(np.fft.fft2(base) * mask).real
    field /= (np.max(np.abs(field)) + 1e-6)
    # Directional bias (emulsion coating direction)
    y_grad = np.linspace(-1.0, 1.0, h)[:, None]
    directional = (1.0 - anisotropy) * field + anisotropy * y_grad
    return np.clip(directional * stress_level, -0.02, 0.02)
def _emulsion_stress_low_pass(h: int, w: int, scale: float) -> np.ndarray:
    """
    Stress diffusion frequency mask.
    """
    y = np.linspace(-1.0, 1.0, h)[:, None]
    x = np.linspace(-1.0, 1.0, w)[None, :]
    r = np.sqrt(x * x + y * y)
    return np.exp(-(r / max(scale, 1e-6)) ** 3)
def apply_emulsion_stress(
    rgb_image: np.ndarray,
    stress_field: np.ndarray
) -> np.ndarray:
    """
    Applies stress-induced micro-density deformation.
    """
    stress_rgb = stress_field[:, :, None]
    return np.clip(rgb_image + stress_rgb, 0.0, 1.0)
def stress_edge_weighting(
    original: np.ndarray,
    stressed: np.ndarray,
    edge_bias: float = 0.75
) -> np.ndarray:
    """
    Stress more visible near luminance transitions.
    """
    gx = np.gradient(original, axis=1)
    gy = np.gradient(original, axis=0)
    grad = np.sqrt(
        np.mean(gx ** 2 + gy ** 2, axis=2)
    )
    weight = np.clip(grad ** edge_bias, 0.0, 1.0)
    return np.clip(
        original + (stressed - original) * weight[:, :, None],
        0.0,
        1.0
    )
def emulsion_stress_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.04
) -> np.ndarray:
    """
    Maintains exposure stability under stress deformation.
    """
    rms_r = np.sqrt(np.mean(reference ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_r / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_emulsion_layer_stress_response(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies emulsion layer stress response.
    """
    stress_level = aging_state.get("emulsion_stress", 0.0)
    stress_field = compute_emulsion_stress_field(
        shape=rgb_image.shape[:2],
        stress_level=stress_level * config.get("strength", 1.0),
        spatial_scale=config.get("spatial_scale", 0.01),
        anisotropy=config.get("anisotropy", 0.35),
        seed=config.get("seed", None)
    )
    stressed = apply_emulsion_stress(
        rgb_image=rgb_image,
        stress_field=stress_field
    )
    stressed = stress_edge_weighting(
        original=rgb_image,
        stressed=stressed,
        edge_bias=config.get("edge_bias", 0.75)
    )
    return emulsion_stress_energy_guard(
        reference=rgb_image,
        processed=stressed,
        max_gain=config.get("max_gain", 1.04)
    )
# ==============================================================================
# END OF SUBCHUNK 84 M 01 — EMULSION LAYER STRESS RESPONSE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 M 02 — EMULSION MICRO-CRACKING SIMULATION
# ==============================================================================
# Purpose:
#   Simulate sub-pixel emulsion micro-cracking caused by aging, humidity cycling,
#   and mechanical stress, affecting local contrast coherence and edge integrity.
#
# Cinematic relevance:
#   - Breaks perfect edge continuity (key film vs digital tell)
#   - Adds organic highlight fragmentation without visible cracks
#   - Influences perceived sharpness and halation boundaries
#
# Runs AFTER:
#   - 84 M 01 (Emulsion Layer Stress Response)
# ==============================================================================
import numpy as np
def generate_micro_crack_field(
    shape: tuple,
    crack_intensity: float,
    spatial_scale: float = 0.004,
    directional_bias: float = 0.25,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates a micro-crack influence field (NOT visible cracks).
    """
    if seed is not None:
        np.random.seed(seed)
    h, w = shape
    base = np.random.normal(0.0, 1.0, size=(h, w))
    mask = _micro_crack_low_pass(h, w, spatial_scale)
    field = np.fft.ifft2(np.fft.fft2(base) * mask).real
    field /= (np.max(np.abs(field)) + 1e-6)
    # Introduce subtle directional stress memory
    x_grad = np.linspace(-1.0, 1.0, w)[None, :]
    directional = (1.0 - directional_bias) * field + directional_bias * x_grad
    return np.clip(directional * crack_intensity, -0.015, 0.015)
def _micro_crack_low_pass(h: int, w: int, scale: float) -> np.ndarray:
    """
    Higher-frequency mask than fog, lower than grain.
    """
    y = np.linspace(-1.0, 1.0, h)[:, None]
    x = np.linspace(-1.0, 1.0, w)[None, :]
    r = np.sqrt(x * x + y * y)
    return np.exp(-(r / max(scale, 1e-6)) ** 6)
def apply_micro_cracking(
    rgb_image: np.ndarray,
    crack_field: np.ndarray
) -> np.ndarray:
    """
    Applies micro-crack influence as density perturbation.
    """
    crack_rgb = crack_field[:, :, None]
    return np.clip(rgb_image + crack_rgb, 0.0, 1.0)
def crack_edge_modulation(
    original: np.ndarray,
    cracked: np.ndarray,
    edge_sensitivity: float = 0.85
) -> np.ndarray:
    """
    Micro-cracking more visible along fine edges and highlights.
    """
    gx = np.gradient(original, axis=1)
    gy = np.gradient(original, axis=0)
    grad = np.sqrt(np.mean(gx ** 2 + gy ** 2, axis=2))
    weight = np.clip(grad ** edge_sensitivity, 0.0, 1.0)
    return np.clip(
        original + (cracked - original) * weight[:, :, None],
        0.0,
        1.0
    )
def micro_crack_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.03
) -> np.ndarray:
    """
    Preserves exposure energy under micro-cracking.
    """
    rms_r = np.sqrt(np.mean(reference ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_r / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_emulsion_micro_cracking(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies emulsion micro-cracking simulation.
    """
    crack_intensity = aging_state.get("micro_crack_level", 0.0)
    crack_field = generate_micro_crack_field(
        shape=rgb_image.shape[:2],
        crack_intensity=crack_intensity * config.get("strength", 1.0),
        spatial_scale=config.get("spatial_scale", 0.004),
        directional_bias=config.get("directional_bias", 0.25),
        seed=config.get("seed", None)
    )
    cracked = apply_micro_cracking(
        rgb_image=rgb_image,
        crack_field=crack_field
    )
    cracked = crack_edge_modulation(
        original=rgb_image,
        cracked=cracked,
        edge_sensitivity=config.get("edge_sensitivity", 0.85)
    )
    return micro_crack_energy_guard(
        reference=rgb_image,
        processed=cracked,
        max_gain=config.get("max_gain", 1.03)
    )
# ==============================================================================
# END OF SUBCHUNK 84 M 02 — EMULSION MICRO-CRACKING SIMULATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 M 03 — EMULSION THICKNESS VARIANCE
# ==============================================================================
# Purpose:
#   Simulate microscopic emulsion thickness variation caused by coating
#   irregularities, aging shrinkage, and base-emulsion interaction.
#
# Cinematic relevance:
#   - Modulates local sharpness and contrast organically
#   - Affects halation spread radius and highlight bloom
#   - Critical for film-like depth rendering
#
# Runs AFTER:
#   - 84 M 02 (Emulsion Micro-Cracking Simulation)
# ==============================================================================
import numpy as np
def generate_emulsion_thickness_field(
    shape: tuple,
    variance: float,
    spatial_scale: float = 0.006,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates emulsion thickness variance field.
    """
    if seed is not None:
        np.random.seed(seed)
    h, w = shape
    noise = np.random.normal(0.0, 1.0, size=(h, w))
    mask = _thickness_low_pass(h, w, spatial_scale)
    field = np.fft.ifft2(np.fft.fft2(noise) * mask).real
    field /= (np.max(np.abs(field)) + 1e-6)
    return np.clip(field * variance, -0.02, 0.02)
def _thickness_low_pass(h: int, w: int, scale: float) -> np.ndarray:
    """
    Frequency mask for coating-scale thickness variation.
    """
    y = np.linspace(-1.0, 1.0, h)[:, None]
    x = np.linspace(-1.0, 1.0, w)[None, :]
    r = np.sqrt(x * x + y * y)
    return np.exp(-(r / max(scale, 1e-6)) ** 4)
def apply_thickness_variance(
    rgb_image: np.ndarray,
    thickness_field: np.ndarray
) -> np.ndarray:
    """
    Applies emulsion thickness variance as local density modulation.
    """
    mod = thickness_field[:, :, None]
    return np.clip(rgb_image + mod, 0.0, 1.0)
def thickness_luminance_weighting(
    original: np.ndarray,
    modulated: np.ndarray,
    bias: float = 0.65
) -> np.ndarray:
    """
    Thickness variance most visible in mid-to-high densities.
    """
    lum = (
        0.2126 * original[:, :, 0] +
        0.7152 * original[:, :, 1] +
        0.0722 * original[:, :, 2]
    )
    weight = np.clip(lum ** bias, 0.0, 1.0)
    return np.clip(
        original + (modulated - original) * weight[:, :, None],
        0.0,
        1.0
    )
def thickness_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.04
) -> np.ndarray:
    """
    Prevents thickness variance from altering global exposure.
    """
    rms_r = np.sqrt(np.mean(reference ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_r / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_emulsion_thickness_variance(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies emulsion thickness variance modulation.
    """
    variance = aging_state.get("emulsion_thickness_variance", 0.0)
    thickness_field = generate_emulsion_thickness_field(
        shape=rgb_image.shape[:2],
        variance=variance * config.get("strength", 1.0),
        spatial_scale=config.get("spatial_scale", 0.006),
        seed=config.get("seed", None)
    )
    modulated = apply_thickness_variance(
        rgb_image=rgb_image,
        thickness_field=thickness_field
    )
    modulated = thickness_luminance_weighting(
        original=rgb_image,
        modulated=modulated,
        bias=config.get("luminance_bias", 0.65)
    )
    return thickness_energy_guard(
        reference=rgb_image,
        processed=modulated,
        max_gain=config.get("max_gain", 1.04)
    )
# ==============================================================================
# END OF SUBCHUNK 84 M 03 — EMULSION THICKNESS VARIANCE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 M 04 — EMULSION LAYER ELASTIC DEFORMATION
# ==============================================================================
# Purpose:
#   Simulate elastic deformation of the emulsion layer under long-term stress,
#   humidity cycling, and base shrinkage, affecting spatial coherence of detail.
#
# Cinematic relevance:
#   - Produces subtle local warping of texture and edges
#   - Breaks mathematically straight contours
#   - Critical for large-format film realism
#
# Runs AFTER:
#   - 84 M 03 (Emulsion Thickness Variance)
# ==============================================================================
import numpy as np
def generate_elastic_deformation_field(
    shape: tuple,
    deformation_strength: float,
    spatial_scale: float = 0.008,
    poisson_ratio: float = 0.35,
    seed: int | None = None
) -> tuple[np.ndarray, np.ndarray]:
    """
    Generates elastic displacement fields (dx, dy).
    """
    if seed is not None:
        np.random.seed(seed)
    h, w = shape
    base_x = np.random.normal(0.0, 1.0, size=(h, w))
    base_y = np.random.normal(0.0, 1.0, size=(h, w))
    mask = _elastic_low_pass(h, w, spatial_scale)
    dx = np.fft.ifft2(np.fft.fft2(base_x) * mask).real
    dy = np.fft.ifft2(np.fft.fft2(base_y) * mask).real
    dx /= (np.max(np.abs(dx)) + 1e-6)
    dy /= (np.max(np.abs(dy)) + 1e-6)
    # Poisson coupling (physical elastic behavior)
    dy = dy * (1.0 - poisson_ratio) + dx * poisson_ratio
    dx *= deformation_strength
    dy *= deformation_strength
    return dx, dy
def _elastic_low_pass(h: int, w: int, scale: float) -> np.ndarray:
    """
    Frequency response for elastic deformation.
    """
    y = np.linspace(-1.0, 1.0, h)[:, None]
    x = np.linspace(-1.0, 1.0, w)[None, :]
    r = np.sqrt(x * x + y * y)
    return np.exp(-(r / max(scale, 1e-6)) ** 3)
def apply_elastic_deformation(
    rgb_image: np.ndarray,
    dx: np.ndarray,
    dy: np.ndarray
) -> np.ndarray:
    """
    Applies elastic deformation using backward sampling.
    """
    h, w, _ = rgb_image.shape
    yy, xx = np.meshgrid(
        np.arange(h), np.arange(w), indexing="ij"
    )
    src_x = np.clip(xx + dx, 0, w - 1)
    src_y = np.clip(yy + dy, 0, h - 1)
    x0 = np.floor(src_x).astype(np.int32)
    y0 = np.floor(src_y).astype(np.int32)
    x1 = np.clip(x0 + 1, 0, w - 1)
    y1 = np.clip(y0 + 1, 0, h - 1)
    wx = src_x - x0
    wy = src_y - y0
    out = (
        rgb_image[y0, x0] * (1 - wx) * (1 - wy) +
        rgb_image[y0, x1] * wx * (1 - wy) +
        rgb_image[y1, x0] * (1 - wx) * wy +
        rgb_image[y1, x1] * wx * wy
    )
    return np.clip(out, 0.0, 1.0)
def deformation_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.03
) -> np.ndarray:
    """
    Prevents elastic warping from altering exposure energy.
    """
    rms_r = np.sqrt(np.mean(reference ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_r / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_emulsion_elastic_deformation(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies elastic deformation to emulsion layer.
    """
    deformation_strength = aging_state.get(
        "emulsion_elastic_deformation", 0.0
    )
    dx, dy = generate_elastic_deformation_field(
        shape=rgb_image.shape[:2],
        deformation_strength=deformation_strength * config.get("strength", 1.0),
        spatial_scale=config.get("spatial_scale", 0.008),
        poisson_ratio=config.get("poisson_ratio", 0.35),
        seed=config.get("seed", None)
    )
    deformed = apply_elastic_deformation(
        rgb_image=rgb_image,
        dx=dx,
        dy=dy
    )
    return deformation_energy_guard(
        reference=rgb_image,
        processed=deformed,
        max_gain=config.get("max_gain", 1.03)
    )
# ==============================================================================
# END OF SUBCHUNK 84 M 04 — EMULSION LAYER ELASTIC DEFORMATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 M 05 — EMULSION GRAIN-DENSITY INTERACTION
# ==============================================================================
# Purpose:
#   Model the physical interaction between silver-halide grain formation
#   and local exposure density inside the emulsion layer.
#
# Cinematic relevance:
#   - Grain behaves differently in shadows, midtones, highlights
#   - Prevents uniform grain overlays
#   - Essential for IMAX / 65mm realism
#
# Runs AFTER:
#   - 84 M 04 (Emulsion Layer Elastic Deformation)
# ==============================================================================
import numpy as np
def compute_density_map(
    rgb_image: np.ndarray,
    gamma: float = 1.15
) -> np.ndarray:
    """
    Computes perceptual density proxy from RGB luminance.
    """
    lum = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    lum = np.clip(lum, 0.0, 1.0)
    # Higher gamma exaggerates density separation
    return np.clip(lum ** gamma, 0.0, 1.0)
def generate_grain_density_field(
    shape: tuple,
    base_strength: float,
    spatial_scale: float = 0.0025,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates base grain structure prior to density modulation.
    """
    if seed is not None:
        np.random.seed(seed)
    h, w = shape
    noise = np.random.normal(0.0, 1.0, size=(h, w))
    # Grain is high-frequency but not white noise
    mask = _grain_band_pass(h, w, spatial_scale)
    grain = np.fft.ifft2(np.fft.fft2(noise) * mask).real
    grain /= (np.max(np.abs(grain)) + 1e-6)
    return grain * base_strength
def _grain_band_pass(h: int, w: int, scale: float) -> np.ndarray:
    """
    Band-pass tuned to silver-halide grain size.
    """
    y = np.linspace(-1.0, 1.0, h)[:, None]
    x = np.linspace(-1.0, 1.0, w)[None, :]
    r = np.sqrt(x * x + y * y)
    low = np.exp(-(r / max(scale * 0.6, 1e-6)) ** 2)
    high = 1.0 - np.exp(-(r / max(scale * 1.6, 1e-6)) ** 2)
    return low * high
def modulate_grain_by_density(
    grain: np.ndarray,
    density: np.ndarray,
    shadow_boost: float = 1.6,
    highlight_suppression: float = 0.55
) -> np.ndarray:
    """
    Grain grows in shadows and collapses in highlights.
    """
    weight = (
        shadow_boost * (1.0 - density) +
        highlight_suppression * density
    )
    return grain * weight
def apply_grain_density_interaction(
    rgb_image: np.ndarray,
    grain_field: np.ndarray
) -> np.ndarray:
    """
    Applies density-modulated grain to image.
    """
    grain_rgb = grain_field[:, :, None]
    return np.clip(rgb_image + grain_rgb, 0.0, 1.0)
def grain_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.02
) -> np.ndarray:
    """
    Ensures grain does not affect exposure energy.
    """
    rms_r = np.sqrt(np.mean(reference ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_r / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_emulsion_grain_density_interaction(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies physically-based grain-density interaction.
    """
    density = compute_density_map(
        rgb_image=rgb_image,
        gamma=config.get("density_gamma", 1.15)
    )
    grain = generate_grain_density_field(
        shape=rgb_image.shape[:2],
        base_strength=config.get("grain_strength", 0.015),
        spatial_scale=config.get("spatial_scale", 0.0025),
        seed=config.get("seed", None)
    )
    grain = modulate_grain_by_density(
        grain=grain,
        density=density,
        shadow_boost=config.get("shadow_boost", 1.6),
        highlight_suppression=config.get("highlight_suppression", 0.55)
    )
    processed = apply_grain_density_interaction(
        rgb_image=rgb_image,
        grain_field=grain
    )
    return grain_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.02)
    )
# ==============================================================================
# END OF SUBCHUNK 84 M 05 — EMULSION GRAIN-DENSITY INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 M 06 — EMULSION AGING NON-LINEARITY
# ==============================================================================
# Purpose:
#   Model non-linear, exposure-dependent aging behavior of photographic emulsion.
#
# Cinematic relevance:
#   - Aging affects shadows, mids, highlights differently
#   - Prevents linear "fade" look
#   - Required for believable archival / long-stored film aesthetics
#
# Runs AFTER:
#   - 84 M 05 (Emulsion Grain-Density Interaction)
# ==============================================================================
import numpy as np
def compute_exposure_zones(
    rgb_image: np.ndarray,
    shadow_cut: float = 0.25,
    highlight_cut: float = 0.75
) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    """
    Splits luminance into shadow / mid / highlight masks.
    """
    lum = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    lum = np.clip(lum, 0.0, 1.0)
    shadows = np.clip((shadow_cut - lum) / shadow_cut, 0.0, 1.0)
    highlights = np.clip((lum - highlight_cut) / (1.0 - highlight_cut), 0.0, 1.0)
    mids = 1.0 - np.maximum(shadows, highlights)
    return shadows, mids, highlights
def aging_response_curve(
    x: np.ndarray,
    exponent: float,
    bias: float
) -> np.ndarray:
    """
    Generic non-linear aging response curve.
    """
    return np.clip((x + bias) ** exponent, 0.0, 1.0)
def compute_aging_gain_map(
    rgb_image: np.ndarray,
    aging_strength: float,
    config: dict
) -> np.ndarray:
    """
    Computes per-pixel aging gain based on exposure zone.
    """
    shadows, mids, highlights = compute_exposure_zones(
        rgb_image,
        shadow_cut=config.get("shadow_cut", 0.25),
        highlight_cut=config.get("highlight_cut", 0.75)
    )
    shadow_resp = aging_response_curve(
        shadows,
        exponent=config.get("shadow_exponent", 1.8),
        bias=config.get("shadow_bias", 0.05)
    )
    mid_resp = aging_response_curve(
        mids,
        exponent=config.get("mid_exponent", 1.0),
        bias=config.get("mid_bias", 0.0)
    )
    highlight_resp = aging_response_curve(
        highlights,
        exponent=config.get("highlight_exponent", 0.75),
        bias=config.get("highlight_bias", -0.05)
    )
    gain = (
        shadow_resp * config.get("shadow_weight", 1.4) +
        mid_resp * config.get("mid_weight", 1.0) +
        highlight_resp * config.get("highlight_weight", 0.65)
    )
    gain /= (
        config.get("shadow_weight", 1.4) +
        config.get("mid_weight", 1.0) +
        config.get("highlight_weight", 0.65)
    )
    return np.clip(1.0 - gain * aging_strength, 0.85, 1.05)
def apply_aging_nonlinearity(
    rgb_image: np.ndarray,
    gain_map: np.ndarray
) -> np.ndarray:
    """
    Applies non-linear aging attenuation.
    """
    return np.clip(rgb_image * gain_map[:, :, None], 0.0, 1.0)
def aging_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.02
) -> np.ndarray:
    """
    Preserves exposure energy consistency.
    """
    rms_r = np.sqrt(np.mean(reference ** 2))
    rms_p = np.sqrt(np.mean(processed ** 2))
    if rms_p < 1e-6:
        return processed
    gain = np.clip(rms_r / rms_p, 1.0 / max_gain, max_gain)
    return processed * gain
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_emulsion_aging_nonlinearity(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies non-linear emulsion aging response.
    """
    aging_strength = aging_state.get("emulsion_aging", 0.0)
    if aging_strength <= 0.0:
        return rgb_image
    gain_map = compute_aging_gain_map(
        rgb_image=rgb_image,
        aging_strength=aging_strength,
        config=config
    )
    processed = apply_aging_nonlinearity(
        rgb_image=rgb_image,
        gain_map=gain_map
    )
    return aging_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.02)
    )
# ==============================================================================
# END OF SUBCHUNK 84 M 06 — EMULSION AGING NON-LINEARITY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 N 01 — DYE CLOUD DIFFUSION DYNAMICS
# ==============================================================================
# Purpose:
#   Simulate spatial diffusion of dye clouds within color film layers.
#
# Cinematic relevance:
#   - Softens chroma edges without blur
#   - Creates organic color bleed at micro scale
#   - Fundamental to analog color separation behavior
#
# Runs AFTER:
#   - 84 M 06 (Emulsion Aging Non-Linearity)
# ==============================================================================
import numpy as np
def generate_diffusion_kernel(
    radius: int,
    diffusion_strength: float
) -> np.ndarray:
    """
    Generates a physically plausible dye diffusion kernel.
    """
    size = radius * 2 + 1
    y, x = np.mgrid[-radius:radius+1, -radius:radius+1]
    r2 = x * x + y * y
    sigma = max(diffusion_strength * radius, 1e-3)
    kernel = np.exp(-r2 / (2.0 * sigma * sigma))
    kernel /= np.sum(kernel)
    return kernel
def diffuse_channel(
    channel: np.ndarray,
    kernel: np.ndarray
) -> np.ndarray:
    """
    Applies diffusion to a single channel.
    """
    pad = kernel.shape[0] // 2
    padded = np.pad(channel, pad, mode="reflect")
    out = np.zeros_like(channel)
    for y in range(out.shape[0]):
        for x in range(out.shape[1]):
            region = padded[
                y:y + kernel.shape[0],
                x:x + kernel.shape[1]
            ]
            out[y, x] = np.sum(region * kernel)
    return out
def apply_dye_cloud_diffusion(
    rgb_image: np.ndarray,
    diffusion_strength: float,
    radius: int = 3
) -> np.ndarray:
    """
    Applies dye cloud diffusion per color layer.
    """
    kernel = generate_diffusion_kernel(
        radius=radius,
        diffusion_strength=diffusion_strength
    )
    out = np.empty_like(rgb_image)
    for c in range(3):
        out[:, :, c] = diffuse_channel(
            rgb_image[:, :, c],
            kernel
        )
    return np.clip(out, 0.0, 1.0)
def chroma_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.01
) -> np.ndarray:
    """
    Preserves chroma energy during diffusion.
    """
    ref_energy = np.mean(reference, axis=2)
    proc_energy = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_energy,
        proc_energy + 1e-6,
        out=np.ones_like(ref_energy),
        where=proc_energy > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_dye_cloud_diffusion(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies dye cloud diffusion dynamics.
    """
    diffusion_strength = aging_state.get("dye_diffusion", 0.0)
    if diffusion_strength <= 0.0:
        return rgb_image
    diffused = apply_dye_cloud_diffusion(
        rgb_image=rgb_image,
        diffusion_strength=diffusion_strength * config.get("strength", 1.0),
        radius=config.get("radius", 3)
    )
    return chroma_energy_guard(
        reference=rgb_image,
        processed=diffused,
        max_gain=config.get("max_gain", 1.01)
    )
# ==============================================================================
# END OF SUBCHUNK 84 N 01 — DYE CLOUD DIFFUSION DYNAMICS
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 N 02 — DYE CLOUD SIZE VARIABILITY
# ==============================================================================
# Purpose:
#   Simulate stochastic variation in dye cloud size across the emulsion.
#
# Cinematic relevance:
#   - Prevents uniform color diffusion
#   - Introduces organic chroma granularity
#   - Critical for large-format film color texture
#
# Runs AFTER:
#   - 84 N 01 (Dye Cloud Diffusion Dynamics)
# ==============================================================================
import numpy as np
def generate_cloud_size_map(
    shape: tuple,
    base_radius: float,
    variability: float,
    spatial_scale: float = 0.01,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates spatially varying dye cloud size map.
    """
    if seed is not None:
        np.random.seed(seed)
    h, w = shape
    noise = np.random.normal(0.0, 1.0, size=(h, w))
    mask = _low_frequency_mask(h, w, spatial_scale)
    field = np.fft.ifft2(np.fft.fft2(noise) * mask).real
    field /= (np.max(np.abs(field)) + 1e-6)
    radius_map = base_radius * (
        1.0 + variability * field
    )
    return np.clip(radius_map, base_radius * 0.5, base_radius * 2.0)
def _low_frequency_mask(h: int, w: int, scale: float) -> np.ndarray:
    """
    Low-frequency mask for cloud size modulation.
    """
    y = np.linspace(-1.0, 1.0, h)[:, None]
    x = np.linspace(-1.0, 1.0, w)[None, :]
    r = np.sqrt(x * x + y * y)
    return np.exp(-(r / max(scale, 1e-6)) ** 2)
def diffuse_channel_variable_radius(
    channel: np.ndarray,
    radius_map: np.ndarray,
    diffusion_strength: float
) -> np.ndarray:
    """
    Applies diffusion with locally varying radius.
    """
    h, w = channel.shape
    out = np.empty_like(channel)
    for y in range(h):
        for x in range(w):
            radius = int(max(1, round(radius_map[y, x])))
            kernel = generate_diffusion_kernel(
                radius=radius,
                diffusion_strength=diffusion_strength
            )
            pad = radius
            padded = np.pad(channel, pad, mode="reflect")
            region = padded[
                y:y + kernel.shape[0],
                x:x + kernel.shape[1]
            ]
            out[y, x] = np.sum(region * kernel)
    return out
def apply_dye_cloud_size_variability(
    rgb_image: np.ndarray,
    radius_map: np.ndarray,
    diffusion_strength: float
) -> np.ndarray:
    """
    Applies variable-size dye cloud diffusion.
    """
    out = np.empty_like(rgb_image)
    for c in range(3):
        out[:, :, c] = diffuse_channel_variable_radius(
            rgb_image[:, :, c],
            radius_map,
            diffusion_strength
        )
    return np.clip(out, 0.0, 1.0)
def cloud_size_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.01
) -> np.ndarray:
    """
    Prevents color energy drift due to size variability.
    """
    ref = np.mean(reference, axis=2)
    proc = np.mean(processed, axis=2)
    ratio = np.divide(
        ref,
        proc + 1e-6,
        out=np.ones_like(ref),
        where=proc > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_dye_cloud_size_variability(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies dye cloud size variability.
    """
    variability = aging_state.get("dye_cloud_size_variation", 0.0)
    if variability <= 0.0:
        return rgb_image
    radius_map = generate_cloud_size_map(
        shape=rgb_image.shape[:2],
        base_radius=config.get("base_radius", 2.5),
        variability=variability * config.get("variability_scale", 1.0),
        spatial_scale=config.get("spatial_scale", 0.01),
        seed=config.get("seed", None)
    )
    processed = apply_dye_cloud_size_variability(
        rgb_image=rgb_image,
        radius_map=radius_map,
        diffusion_strength=config.get("diffusion_strength", 0.6)
    )
    return cloud_size_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.01)
    )
