# ==============================================================================
# SUBCHUNK 84 N 10 — DYE CLOUD LONG-TERM COLOR DRIFT
# ==============================================================================
# Purpose:
#   Model cumulative chromatic drift over long storage time caused by
#   asymmetric dye decay, inter-layer contamination, and spectral instability.
#
# Cinematic relevance:
#   - Produces believable archival hue bias (cyan→green, magenta→orange)
#   - Prevents static “digital aging” look
#   - Integrates all dye-aging phenomena into a coherent final state
#
# Runs AFTER:
#   - 84 N 09 (Dye Cloud Aging Saturation Collapse)
# ==============================================================================
import numpy as np
def compute_hue(rgb: np.ndarray) -> np.ndarray:
    """
    Computes approximate hue angle in radians.
    """
    r, g, b = rgb[:, :, 0], rgb[:, :, 1], rgb[:, :, 2]
    num = np.sqrt(3.0) * (g - b)
    den = 2.0 * r - g - b
    return np.arctan2(num, den)
def hue_drift_curve(
    hue: np.ndarray,
    strength: float,
    bias: float
) -> np.ndarray:
    """
    Produces smooth, film-like hue rotation.
    """
    # Bias steers drift direction (positive = warm, negative = cool)
    drift = strength * np.sin(hue + bias)
    return drift
def rotate_hue(rgb: np.ndarray, delta: np.ndarray) -> np.ndarray:
    """
    Applies hue rotation via YIQ-like approximation.
    """
    # RGB → YIQ
    y = (
        0.299 * rgb[:, :, 0] +
        0.587 * rgb[:, :, 1] +
        0.114 * rgb[:, :, 2]
    )
    i = 0.596 * rgb[:, :, 0] - 0.274 * rgb[:, :, 1] - 0.322 * rgb[:, :, 2]
    q = 0.211 * rgb[:, :, 0] - 0.523 * rgb[:, :, 1] + 0.312 * rgb[:, :, 2]
    cos_d = np.cos(delta)
    sin_d = np.sin(delta)
    i2 = i * cos_d - q * sin_d
    q2 = i * sin_d + q * cos_d
    # YIQ → RGB
    r = y + 0.956 * i2 + 0.621 * q2
    g = y - 0.272 * i2 - 0.647 * q2
    b = y - 1.106 * i2 + 1.703 * q2
    return np.stack([r, g, b], axis=2)
def drift_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.01
) -> np.ndarray:
    """
    Preserves luminance after hue drift.
    """
    ref_l = np.mean(reference, axis=2)
    proc_l = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_l,
        proc_l + 1e-6,
        out=np.ones_like(ref_l),
        where=proc_l > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_dye_cloud_long_term_color_drift(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies long-term color drift to aged dye clouds.
    """
    drift_strength = aging_state.get("dye_long_term_drift", 0.0)
    if drift_strength <= 0.0:
        return rgb_image
    hue = compute_hue(rgb_image)
    delta = hue_drift_curve(
        hue=hue,
        strength=drift_strength * config.get("strength_scale", 1.0),
        bias=config.get("bias", 0.3)
    )
    processed = rotate_hue(rgb_image, delta)
    return drift_energy_guard(
        reference=rgb_image,
        processed=np.clip(processed, 0.0, 1.0),
        max_gain=config.get("max_gain", 1.01)
    )
# ==============================================================================
# END OF SUBCHUNK 84 N 10 — DYE CLOUD LONG-TERM COLOR DRIFT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 O 01 — INTER-LAYER COLOR MEMORY EFFECTS
# ==============================================================================
# Purpose:
#   Model persistent chromatic memory across emulsion layers caused by
#   incomplete chemical reset, gelatin hysteresis, and dye diffusion lag.
#
# Cinematic relevance:
#   - Produces filmic color inertia (colors don’t snap instantly)
#   - Adds temporal cohesion to grading and aging
#   - Prevents frame-to-frame digital color discontinuities
#
# Runs AFTER:
#   - 84 N 10 (Dye Cloud Long-Term Color Drift)
# ==============================================================================
import numpy as np
def init_color_memory(shape: tuple) -> dict:
    """
    Initializes inter-layer color memory buffers.
    """
    h, w = shape
    return {
        "R": np.zeros((h, w), dtype=np.float32),
        "G": np.zeros((h, w), dtype=np.float32),
        "B": np.zeros((h, w), dtype=np.float32),
    }
def update_color_memory(
    memory: dict,
    rgb: np.ndarray,
    decay: float,
    accumulation: float
) -> dict:
    """
    Updates memory buffers with exponential decay and accumulation.
    """
    memory["R"] = memory["R"] * decay + rgb[:, :, 0] * accumulation
    memory["G"] = memory["G"] * decay + rgb[:, :, 1] * accumulation
    memory["B"] = memory["B"] * decay + rgb[:, :, 2] * accumulation
    return memory
def apply_color_memory_bias(
    rgb: np.ndarray,
    memory: dict,
    strength: float
) -> np.ndarray:
    """
    Applies inter-layer memory bias back into the image.
    """
    bias = np.stack([
        memory["R"],
        memory["G"],
        memory["B"],
    ], axis=2)
    return np.clip(
        rgb * (1.0 - strength) + bias * strength,
        0.0,
        1.0
    )
def memory_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.01
) -> np.ndarray:
    """
    Preserves luminance energy after memory application.
    """
    ref_l = np.mean(reference, axis=2)
    proc_l = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_l,
        proc_l + 1e-6,
        out=np.ones_like(ref_l),
        where=proc_l > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_inter_layer_color_memory(
    rgb_image: np.ndarray,
    state: dict,
    config: dict
) -> tuple[np.ndarray, dict]:
    """
    Applies inter-layer color memory and updates persistent state.
    """
    strength = config.get("memory_strength", 0.0)
    if strength <= 0.0:
        return rgb_image, state
    if "color_memory" not in state:
        state["color_memory"] = init_color_memory(rgb_image.shape[:2])
    decay = config.get("decay", 0.985)
    accumulation = config.get("accumulation", 0.015)
    state["color_memory"] = update_color_memory(
        memory=state["color_memory"],
        rgb=rgb_image,
        decay=decay,
        accumulation=accumulation
    )
    processed = apply_color_memory_bias(
        rgb=rgb_image,
        memory=state["color_memory"],
        strength=strength
    )
    processed = memory_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.01)
    )
    return processed, state
# ==============================================================================
# END OF SUBCHUNK 84 O 01 — INTER-LAYER COLOR MEMORY EFFECTS
