# ==============================================================================
# SUBCHUNK 84 O 02 — CHEMICAL RECIPROCITY FAILURE
# ==============================================================================
# Purpose:
#   Model non-linear exposure response caused by breakdown of reciprocity
#   between light intensity and exposure duration in photographic emulsion.
#
# Cinematic relevance:
#   - Critical for night scenes, long exposures, highlights, and shadows
#   - Explains why film behaves differently at low/high light levels
#   - Prevents “perfect” digital exposure linearity
#
# Runs AFTER:
#   - 84 O 01 (Inter-Layer Color Memory Effects)
# ==============================================================================
import numpy as np
def reciprocity_failure_curve(
    exposure: np.ndarray,
    strength: float,
    toe: float,
    shoulder: float
) -> np.ndarray:
    """
    Film-like reciprocity failure response curve.
    """
    # Normalize exposure
    x = np.clip(exposure, 0.0, 1.0)
    # Low-light failure (toe)
    low = x / (x + toe)
    # High-light failure (shoulder)
    high = 1.0 - np.exp(-x / max(shoulder, 1e-6))
    response = low * (1.0 - high)
    return np.clip(
        x * (1.0 - strength) + response * strength,
        0.0,
        1.0
    )
def apply_reciprocity_failure(
    rgb: np.ndarray,
    strength_map: np.ndarray,
    toe: float,
    shoulder: float
) -> np.ndarray:
    """
    Applies reciprocity failure independently per channel.
    """
    out = np.empty_like(rgb)
    for c in range(3):
        out[:, :, c] = reciprocity_failure_curve(
            exposure=rgb[:, :, c],
            strength=strength_map,
            toe=toe,
            shoulder=shoulder
        )
    return out
def reciprocity_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.02
) -> np.ndarray:
    """
    Maintains global luminance balance after reciprocity distortion.
    """
    ref_l = np.mean(reference, axis=2)
    proc_l = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_l,
        proc_l + 1e-6,
        out=np.ones_like(ref_l),
        where=proc_l > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_chemical_reciprocity_failure(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies chemical reciprocity failure to emulate film exposure behavior.
    """
    strength = aging_state.get("reciprocity_failure", 0.0)
    if strength <= 0.0:
        return rgb_image
    # Exposure proxy = luminance
    exposure = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    exposure /= (np.max(exposure) + 1e-6)
    strength_map = (
        strength *
        (0.3 + 0.7 * exposure) *
        config.get("strength_scale", 1.0)
    )
    processed = apply_reciprocity_failure(
        rgb=rgb_image,
        strength_map=strength_map,
        toe=config.get("toe", 0.18),
        shoulder=config.get("shoulder", 0.75)
    )
    return reciprocity_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.02)
    )
