# ==============================================================================
# SUBCHUNK 84 O 03 — LATENT IMAGE DRIFT
# ==============================================================================
# Purpose:
#   Simulate slow spatial and chromatic drift of the latent image before
#   full chemical stabilization, caused by ion diffusion and charge migration.
#
# Cinematic relevance:
#   - Introduces organic temporal instability
#   - Prevents frame-perfect color consistency
#   - Critical for analog motion + time realism
#
# Runs AFTER:
#   - 84 O 02 (Chemical Reciprocity Failure)
# ==============================================================================
import numpy as np
def generate_latent_drift_field(
    shape: tuple,
    amplitude: float,
    spatial_scale: float,
    temporal_phase: float
) -> np.ndarray:
    """
    Generates a smooth spatial drift field for latent image migration.
    """
    h, w = shape
    y = np.linspace(-1.0, 1.0, h)[:, None]
    x = np.linspace(-1.0, 1.0, w)[None, :]
    base = np.sin(
        (x * 2.1 + y * 1.7) * spatial_scale +
        temporal_phase
    )
    base += np.cos(
        (x * 1.3 - y * 2.4) * spatial_scale -
        temporal_phase * 0.7
    )
    base /= (np.max(np.abs(base)) + 1e-6)
    return base * amplitude
def apply_latent_spatial_drift(
    channel: np.ndarray,
    drift: np.ndarray
) -> np.ndarray:
    """
    Applies sub-pixel drift to a single channel.
    """
    h, w = channel.shape
    yy, xx = np.meshgrid(
        np.arange(h), np.arange(w), indexing="ij"
    )
    src_x = np.clip(xx + drift, 0, w - 1)
    src_y = np.clip(yy + drift, 0, h - 1)
    x0 = np.floor(src_x).astype(np.int32)
    y0 = np.floor(src_y).astype(np.int32)
    x1 = np.clip(x0 + 1, 0, w - 1)
    y1 = np.clip(y0 + 1, 0, h - 1)
    wx = src_x - x0
    wy = src_y - y0
    return (
        channel[y0, x0] * (1 - wx) * (1 - wy) +
        channel[y0, x1] * wx * (1 - wy) +
        channel[y1, x0] * (1 - wx) * wy +
        channel[y1, x1] * wx * wy
    )
def apply_latent_image_drift(
    rgb: np.ndarray,
    drift_field: np.ndarray
) -> np.ndarray:
    """
    Applies latent image drift uniformly across channels.
    """
    out = np.empty_like(rgb)
    for c in range(3):
        out[:, :, c] = apply_latent_spatial_drift(
            rgb[:, :, c],
            drift_field
        )
    return np.clip(out, 0.0, 1.0)
def latent_drift_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.01
) -> np.ndarray:
    """
    Preserves luminance energy after latent drift.
    """
    ref_l = np.mean(reference, axis=2)
    proc_l = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_l,
        proc_l + 1e-6,
        out=np.ones_like(ref_l),
        where=proc_l > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_latent_image_drift(
    rgb_image: np.ndarray,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict]:
    """
    Applies latent image drift with temporal evolution.
    """
    strength = config.get("drift_strength", 0.0)
    if strength <= 0.0:
        return rgb_image, temporal_state
    phase = temporal_state.get("latent_phase", 0.0)
    drift_field = generate_latent_drift_field(
        shape=rgb_image.shape[:2],
        amplitude=strength * config.get("amplitude", 0.35),
        spatial_scale=config.get("spatial_scale", 1.4),
        temporal_phase=phase
    )
    processed = apply_latent_image_drift(
        rgb=rgb_image,
        drift_field=drift_field
    )
    temporal_state["latent_phase"] = (
        phase + config.get("phase_increment", 0.015)
    )
    processed = latent_drift_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.01)
    )
    return processed, temporal_state
