# SUBCHUNK 84 O 04 — EXPOSURE-TIME RECIPROCITY COLLAPSE
# ==============================================================================
# Purpose:
#   Model collapse of linear exposure-time reciprocity caused by
#   emulsion inefficiency at extreme short and long exposure durations.
#
# Cinematic relevance:
#   - Explains highlight roll-off at short shutter times
#   - Explains shadow loss and color drift at long exposures
#   - Critical for motion-heavy and night cinematography
#
# Runs AFTER:
#   - 84 O 03 (Latent Image Drift)
# ==============================================================================
import numpy as np
def reciprocity_time_curve(
    exposure: np.ndarray,
    time_factor: float,
    low_time_knee: float,
    high_time_knee: float
) -> np.ndarray:
    """
    Produces time-dependent reciprocity collapse response.
    """
    x = np.clip(exposure, 0.0, 1.0)
    short_exp = x / (x + low_time_knee)
    long_exp = 1.0 - np.exp(-x / max(high_time_knee, 1e-6))
    collapse = short_exp * long_exp
    return np.clip(
        x * (1.0 - time_factor) + collapse * time_factor,
        0.0,
        1.0
    )
def apply_time_reciprocity(
    rgb: np.ndarray,
    time_strength: float,
    low_knee: float,
    high_knee: float
) -> np.ndarray:
    """
    Applies time-based reciprocity failure per channel.
    """
    out = np.empty_like(rgb)
    for c in range(3):
        out[:, :, c] = reciprocity_time_curve(
            exposure=rgb[:, :, c],
            time_factor=time_strength,
            low_time_knee=low_knee,
            high_time_knee=high_knee
        )
    return out
def time_reciprocity_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.02
) -> np.ndarray:
    """
    Maintains luminance consistency after time reciprocity collapse.
    """
    ref_l = np.mean(reference, axis=2)
    proc_l = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_l,
        proc_l + 1e-6,
        out=np.ones_like(ref_l),
        where=proc_l > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_exposure_time_reciprocity(
    rgb_image: np.ndarray,
    capture_state: dict,
    config: dict
) -> np.ndarray:
    """
    Applies exposure-time reciprocity collapse.
    """
    time_strength = capture_state.get("reciprocity_time_strength", 0.0)
    if time_strength <= 0.0:
        return rgb_image
    processed = apply_time_reciprocity(
        rgb=rgb_image,
        time_strength=time_strength * config.get("strength_scale", 1.0),
        low_knee=config.get("low_time_knee", 0.12),
        high_knee=config.get("high_time_knee", 0.85)
    )
    return time_reciprocity_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.02)
    )
