# ==============================================================================
# SUBCHUNK 84 O 06 — TIME-DEPENDENT EMULSION RESPONSE LAG
# ==============================================================================
# Purpose:
#   Model delayed emulsion response to changing exposure and chromatic energy
#   caused by gelatin inertia, developer diffusion latency, and silver halide
#   reaction time constants.
#
# Cinematic relevance:
#   - Introduces temporal “viscosity” to exposure and color changes
#   - Prevents flickery or hyper-reactive exposure behavior
#   - Essential for organic motion, pans, and lighting transitions
#
# Runs AFTER:
#   - 84 O 05 (Latent Dye Activation Delay)
# ==============================================================================
import numpy as np
def emulsion_response_filter(
    current: np.ndarray,
    previous: np.ndarray,
    response_rate: float
) -> np.ndarray:
    """
    Applies first-order temporal lag to emulate emulsion inertia.
    """
    return previous + response_rate * (current - previous)
def compute_response_rate(
    exposure: np.ndarray,
    base_rate: float,
    exposure_scale: float
) -> np.ndarray:
    """
    Computes exposure-dependent response rate.
    """
    return np.clip(
        base_rate * (0.5 + exposure_scale * exposure),
        0.0,
        1.0
    )
def response_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.02
) -> np.ndarray:
    """
    Preserves luminance energy after response lag.
    """
    ref_l = np.mean(reference, axis=2)
    proc_l = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_l,
        proc_l + 1e-6,
        out=np.ones_like(ref_l),
        where=proc_l > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_time_dependent_emulsion_response(
    rgb_image: np.ndarray,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict]:
    """
    Applies time-dependent emulsion response lag.
    """
    lag_strength = config.get("lag_strength", 0.0)
    if lag_strength <= 0.0:
        return rgb_image, temporal_state
    # Initialize previous state
    if "emulsion_prev" not in temporal_state:
        temporal_state["emulsion_prev"] = rgb_image.copy()
    # Exposure proxy
    exposure = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    exposure /= (np.max(exposure) + 1e-6)
    response_rate = compute_response_rate(
        exposure=exposure,
        base_rate=lag_strength * config.get("base_rate", 0.12),
        exposure_scale=config.get("exposure_scale", 0.9)
    )
    prev = temporal_state["emulsion_prev"]
    out = np.empty_like(rgb_image)
    for c in range(3):
        out[:, :, c] = emulsion_response_filter(
            current=rgb_image[:, :, c],
            previous=prev[:, :, c],
            response_rate=response_rate
        )
    temporal_state["emulsion_prev"] = out.copy()
    out = response_energy_guard(
        reference=rgb_image,
        processed=out,
        max_gain=config.get("max_gain", 1.02)
    )
    return out, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 O 06 — TIME-DEPENDENT EMULSION RESPONSE LAG
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 O 07 — CHEMICAL DEVELOPMENT THRESHOLD NOISE
# ==============================================================================
# Purpose:
#   Simulate stochastic threshold behavior during chemical development,
#   where silver halide grains activate only after surpassing localized
#   energy thresholds, producing organic emergence noise.
#
# Cinematic relevance:
#   - Produces film’s characteristic unstable micro-contrast
#   - Explains why film grain “appears” rather than being static
#   - Critical for analog texture without visible artificial noise
#
# Runs AFTER:
#   - 84 O 06 (Time-Dependent Emulsion Response Lag)
# ==============================================================================
import numpy as np
def generate_threshold_noise(
    shape: tuple,
    base_threshold: float,
    variance: float,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates spatially varying chemical activation thresholds.
    """
    if seed is not None:
        np.random.seed(seed)
    noise = np.random.normal(
        loc=base_threshold,
        scale=variance,
        size=shape
    )
    return np.clip(noise, 0.0, 1.0)
def apply_threshold_activation(
    exposure: np.ndarray,
    threshold_map: np.ndarray,
    softness: float
) -> np.ndarray:
    """
    Applies soft threshold activation to exposure.
    """
    delta = exposure - threshold_map
    return 1.0 / (1.0 + np.exp(-delta / max(softness, 1e-6)))
def threshold_noise_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.02
) -> np.ndarray:
    """
    Preserves luminance after threshold noise application.
    """
    ref_l = np.mean(reference, axis=2)
    proc_l = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_l,
        proc_l + 1e-6,
        out=np.ones_like(ref_l),
        where=proc_l > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_chemical_development_threshold_noise(
    rgb_image: np.ndarray,
    development_state: dict,
    config: dict
) -> tuple[np.ndarray, dict]:
    """
    Applies chemical development threshold noise.
    """
    strength = config.get("threshold_noise_strength", 0.0)
    if strength <= 0.0:
        return rgb_image, development_state
    # Exposure proxy
    exposure = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    exposure /= (np.max(exposure) + 1e-6)
    if "threshold_map" not in development_state:
        development_state["threshold_map"] = generate_threshold_noise(
            shape=exposure.shape,
            base_threshold=config.get("base_threshold", 0.45),
            variance=config.get("variance", 0.08),
            seed=config.get("seed", None)
        )
    activation = apply_threshold_activation(
        exposure=exposure,
        threshold_map=development_state["threshold_map"],
        softness=config.get("softness", 0.06)
    )
    processed = rgb_image * (
        1.0 - strength + strength * activation[:, :, None]
    )
    processed = threshold_noise_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.02)
    )
    return processed, development_state
# ==============================================================================
# END OF SUBCHUNK 84 O 07 — CHEMICAL DEVELOPMENT THRESHOLD NOISE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 O 08 — INCOMPLETE DYE FIXATION ARTIFACTS
# ==============================================================================
# Purpose:
#   Simulate incomplete dye fixation during chemical processing, where
#   dye clouds fail to fully stabilize, causing chromatic instability,
#   highlight bleed, and subtle temporal color drift.
#
# Cinematic relevance:
#   - Produces organic highlight chroma instability
#   - Prevents sterile, perfectly locked color channels
#   - Critical for analog highlight behavior and bloom interaction
#
# Runs AFTER:
#   - 84 O 07 (Chemical Development Threshold Noise)
# ==============================================================================
import numpy as np
def compute_fixation_map(
    exposure: np.ndarray,
    instability_strength: float,
    bias: float
) -> np.ndarray:
    """
    Computes spatially varying dye fixation instability.
    """
    x = np.clip(exposure, 0.0, 1.0)
    instability = instability_strength * (1.0 - x + bias)
    return np.clip(instability, 0.0, 1.0)
def apply_fixation_artifacts(
    rgb: np.ndarray,
    fixation_map: np.ndarray,
    chroma_drift: float
) -> np.ndarray:
    """
    Applies per-channel chromatic instability.
    """
    out = rgb.copy()
    # Channel-dependent dye instability
    out[:, :, 0] *= 1.0 + fixation_map * chroma_drift * 0.6
    out[:, :, 1] *= 1.0 - fixation_map * chroma_drift * 0.4
    out[:, :, 2] *= 1.0 + fixation_map * chroma_drift * 0.8
    return np.clip(out, 0.0, 1.0)
def fixation_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.015
) -> np.ndarray:
    """
    Preserves overall luminance after fixation artifacts.
    """
    ref_l = np.mean(reference, axis=2)
    proc_l = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_l,
        proc_l + 1e-6,
        out=np.ones_like(ref_l),
        where=proc_l > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_incomplete_dye_fixation(
    rgb_image: np.ndarray,
    fixation_state: dict,
    config: dict
) -> tuple[np.ndarray, dict]:
    """
    Applies incomplete dye fixation artifacts.
    """
    strength = config.get("fixation_instability_strength", 0.0)
    if strength <= 0.0:
        return rgb_image, fixation_state
    # Exposure proxy
    exposure = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    exposure /= (np.max(exposure) + 1e-6)
    fixation_map = compute_fixation_map(
        exposure=exposure,
        instability_strength=strength,
        bias=config.get("bias", 0.12)
    )
    processed = apply_fixation_artifacts(
        rgb=rgb_image,
        fixation_map=fixation_map,
        chroma_drift=config.get("chroma_drift", 0.04)
    )
    processed = fixation_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.015)
    )
    return processed, fixation_state
# ==============================================================================
# END OF SUBCHUNK 84 O 08 — INCOMPLETE DYE FIXATION ARTIFACTS
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 O 09 — EMULSION AGING CONTRAST COMPRESSION
# ==============================================================================
# Purpose:
#   Simulate long-term contrast compression caused by emulsion aging,
#   gelatin fatigue, dye diffusion broadening, and silver halide instability.
#
# Cinematic relevance:
#   - Produces gentle highlight roll-off and lifted shadows seen in aged film
#   - Prevents harsh digital contrast even in high dynamic range scenes
#   - Core reason older film footage feels “soft but rich”
#
# Runs AFTER:
#   - 84 O 08 (Incomplete Dye Fixation Artifacts)
# ==============================================================================
import numpy as np
def compute_contrast_compression_curve(
    x: np.ndarray,
    compression_strength: float,
    mid_gray: float
) -> np.ndarray:
    """
    Computes non-linear contrast compression curve.
    """
    x = np.clip(x, 0.0, 1.0)
    curve = (
        (x - mid_gray) /
        (1.0 + compression_strength * np.abs(x - mid_gray))
    ) + mid_gray
    return np.clip(curve, 0.0, 1.0)
def apply_contrast_compression(
    rgb: np.ndarray,
    strength: float,
    mid_gray: float
) -> np.ndarray:
    """
    Applies contrast compression per channel.
    """
    out = np.empty_like(rgb)
    for c in range(3):
        out[:, :, c] = compute_contrast_compression_curve(
            rgb[:, :, c],
            compression_strength=strength,
            mid_gray=mid_gray
        )
    return out
def contrast_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.01
) -> np.ndarray:
    """
    Preserves luminance after contrast compression.
    """
    ref_l = np.mean(reference, axis=2)
    proc_l = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_l,
        proc_l + 1e-6,
        out=np.ones_like(ref_l),
        where=proc_l > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_emulsion_aging_contrast_compression(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> tuple[np.ndarray, dict]:
    """
    Applies emulsion aging contrast compression.
    """
    strength = config.get("aging_contrast_strength", 0.0)
    if strength <= 0.0:
        return rgb_image, aging_state
    processed = apply_contrast_compression(
        rgb=rgb_image,
        strength=strength,
        mid_gray=config.get("mid_gray", 0.42)
    )
    processed = contrast_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.01)
    )
    return processed, aging_state
# ==============================================================================
# END OF SUBCHUNK 84 O 09 — EMULSION AGING CONTRAST COMPRESSION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 O 10 — LONG-TERM BASE FOG ACCUMULATION
# ==============================================================================
# Purpose:
#   Simulate base fog buildup caused by aging film base materials,
#   residual silver halide, radiation exposure, and chemical instability.
#
# Cinematic relevance:
#   - Explains lifted blacks and milky shadows in aged film
#   - Adds depth-dependent shadow coloration (brown/green fog)
#   - Prevents perfectly neutral black levels
#
# Runs AFTER:
#   - 84 O 09 (Emulsion Aging Contrast Compression)
# ==============================================================================
import numpy as np
def compute_base_fog_map(
    exposure: np.ndarray,
    fog_strength: float,
    shadow_bias: float
) -> np.ndarray:
    """
    Computes base fog density map with stronger effect in shadows.
    """
    x = np.clip(exposure, 0.0, 1.0)
    fog = fog_strength * (1.0 - x) ** (1.0 + shadow_bias)
    return np.clip(fog, 0.0, 1.0)
def apply_base_fog(
    rgb: np.ndarray,
    fog_map: np.ndarray,
    fog_color: tuple[float, float, float]
) -> np.ndarray:
    """
    Applies colored base fog lift to RGB image.
    """
    fog_r, fog_g, fog_b = fog_color
    out = rgb.copy()
    out[:, :, 0] += fog_map * fog_r
    out[:, :, 1] += fog_map * fog_g
    out[:, :, 2] += fog_map * fog_b
    return np.clip(out, 0.0, 1.0)
def fog_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.01
) -> np.ndarray:
    """
    Preserves overall luminance after base fog application.
    """
    ref_l = np.mean(reference, axis=2)
    proc_l = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_l,
        proc_l + 1e-6,
        out=np.ones_like(ref_l),
        where=proc_l > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_long_term_base_fog(
    rgb_image: np.ndarray,
    aging_state: dict,
    config: dict
) -> tuple[np.ndarray, dict]:
    """
    Applies long-term base fog accumulation.
    """
    fog_strength = config.get("base_fog_strength", 0.0)
    if fog_strength <= 0.0:
        return rgb_image, aging_state
    # Exposure proxy
    exposure = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    exposure /= (np.max(exposure) + 1e-6)
    fog_map = compute_base_fog_map(
        exposure=exposure,
        fog_strength=fog_strength,
        shadow_bias=config.get("shadow_bias", 0.6)
    )
    processed = apply_base_fog(
        rgb=rgb_image,
        fog_map=fog_map,
        fog_color=config.get(
            "fog_color",
            (0.015, 0.020, 0.018)
        )
    )
    processed = fog_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.01)
    )
    return processed, aging_state
# ==============================================================================
# END OF SUBCHUNK 84 O 10 — LONG-TERM BASE FOG ACCUMULATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 P 01 — PHOTOCHEMICAL GRAIN CLUMPING DYNAMICS
# ==============================================================================
# Purpose:
#   Model spatial grain clumping caused by chemical adjacency,
#   developer diffusion overlap, and silver halide proximity effects.
#
# Cinematic relevance:
#   - Explains why film grain forms clusters instead of uniform noise
#   - Produces organic texture that scales with resolution
#   - Prevents “digital sand” appearance
#
# Runs AFTER:
#   - 84 O 10 (Long-Term Base Fog Accumulation)
# ==============================================================================
import numpy as np
import cv2
def generate_base_grain_field(
    shape: tuple,
    density: float,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates initial random grain activation field.
    """
    if seed is not None:
        np.random.seed(seed)
    return (np.random.rand(*shape) < density).astype(np.float32)
def apply_grain_clumping(
    grain_field: np.ndarray,
    clump_radius: int,
    iterations: int
) -> np.ndarray:
    """
    Applies spatial diffusion to form grain clumps.
    """
    kernel = cv2.getStructuringElement(
        cv2.MORPH_ELLIPSE,
        (clump_radius * 2 + 1, clump_radius * 2 + 1)
    )
    clumped = grain_field.copy()
    for _ in range(iterations):
        clumped = cv2.dilate(clumped, kernel)
        clumped = cv2.GaussianBlur(clumped, (0, 0), clump_radius * 0.35)
    return np.clip(clumped, 0.0, 1.0)
def modulate_grain_by_exposure(
    grain_map: np.ndarray,
    exposure: np.ndarray,
    exposure_bias: float
) -> np.ndarray:
    """
    Modulates grain visibility by exposure level.
    """
    return np.clip(
        grain_map * (1.0 - exposure_bias * exposure),
        0.0,
        1.0
    )
def apply_grain_to_rgb(
    rgb: np.ndarray,
    grain_map: np.ndarray,
    strength: float
) -> np.ndarray:
    """
    Applies luminance-weighted grain to RGB image.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    grain = (grain_map - 0.5) * strength
    out = rgb + grain[:, :, None] * (0.4 + 0.6 * luma[:, :, None])
    return np.clip(out, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_photochemical_grain_clumping(
    rgb_image: np.ndarray,
    grain_state: dict,
    config: dict
) -> tuple[np.ndarray, dict]:
    """
    Applies photochemical grain clumping dynamics.
    """
    strength = config.get("grain_clump_strength", 0.0)
    if strength <= 0.0:
        return rgb_image, grain_state
    h, w, _ = rgb_image.shape
    if "grain_field" not in grain_state:
        base_field = generate_base_grain_field(
            shape=(h, w),
            density=config.get("grain_density", 0.08),
            seed=config.get("seed", None)
        )
        grain_state["grain_field"] = apply_grain_clumping(
            grain_field=base_field,
            clump_radius=config.get("clump_radius", 2),
            iterations=config.get("iterations", 2)
        )
    exposure = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    exposure /= (np.max(exposure) + 1e-6)
    grain_map = modulate_grain_by_exposure(
        grain_map=grain_state["grain_field"],
        exposure=exposure,
        exposure_bias=config.get("exposure_bias", 0.7)
    )
    processed = apply_grain_to_rgb(
        rgb=rgb_image,
        grain_map=grain_map,
        strength=strength
    )
    return processed, grain_state
# ==============================================================================
# END OF SUBCHUNK 84 P 01 — PHOTOCHEMICAL GRAIN CLUMPING DYNAMICS
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 P 02 — GRAIN DENSITY–EXPOSURE COUPLING
# ==============================================================================
# Purpose:
#   Couple grain density and visibility to local exposure and scene energy,
#   reflecting silver halide activation probability and developer exhaustion.
#
# Cinematic relevance:
#   - Grain blooms in shadows, tightens in highlights (film-accurate)
#   - Prevents flat, ISO-like grain behavior
#   - Preserves perceived sharpness while remaining organic
#
# Runs AFTER:
#   - 84 P 01 (Photochemical Grain Clumping Dynamics)
# ==============================================================================
import numpy as np
def compute_exposure_luma(rgb: np.ndarray) -> np.ndarray:
    """
    Computes normalized exposure proxy from RGB.
    """
    l = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    return l / (np.max(l) + 1e-6)
def density_curve(
    exposure: np.ndarray,
    shadow_gain: float,
    highlight_suppression: float,
    knee: float
) -> np.ndarray:
    """
    Maps exposure to grain density modulation.
    """
    x = np.clip(exposure, 0.0, 1.0)
    # Shadow amplification with smooth knee
    shadow_term = shadow_gain * (1.0 - x) ** (1.0 + knee)
    # Highlight suppression (grain tightens)
    highlight_term = 1.0 - highlight_suppression * x
    return np.clip(shadow_term * highlight_term, 0.0, 1.0)
def apply_density_to_grain(
    grain_map: np.ndarray,
    density_map: np.ndarray
) -> np.ndarray:
    """
    Applies density modulation to existing grain field.
    """
    return np.clip(grain_map * (1.0 + density_map), 0.0, 1.0)
def grain_density_energy_guard(
    reference: np.ndarray,
    processed: np.ndarray,
    max_gain: float = 1.01
) -> np.ndarray:
    """
    Prevents unintended luminance drift after density coupling.
    """
    ref_l = np.mean(reference, axis=2)
    proc_l = np.mean(processed, axis=2)
    ratio = np.divide(
        ref_l,
        proc_l + 1e-6,
        out=np.ones_like(ref_l),
        where=proc_l > 1e-6
    )
    ratio = np.clip(ratio, 1.0 / max_gain, max_gain)
    return processed * ratio[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_density_exposure_coupling(
    rgb_image: np.ndarray,
    grain_state: dict,
    config: dict
) -> tuple[np.ndarray, dict]:
    """
    Couples grain density to exposure in a film-accurate manner.
    """
    strength = config.get("grain_density_strength", 0.0)
    if strength <= 0.0 or "grain_field" not in grain_state:
        return rgb_image, grain_state
    exposure = compute_exposure_luma(rgb_image)
    density_map = density_curve(
        exposure=exposure,
        shadow_gain=strength * config.get("shadow_gain", 0.9),
        highlight_suppression=config.get("highlight_suppression", 0.6),
        knee=config.get("knee", 0.5)
    )
    grain_state["grain_field"] = apply_density_to_grain(
        grain_map=grain_state["grain_field"],
        density_map=density_map
    )
    # Apply updated grain to image (reuse luminance-weighted application)
    luma = exposure
    grain = (grain_state["grain_field"] - 0.5) * strength
    processed = rgb_image + grain[:, :, None] * (0.35 + 0.65 * luma[:, :, None])
    processed = grain_density_energy_guard(
        reference=rgb_image,
        processed=processed,
        max_gain=config.get("max_gain", 1.01)
    )
    return np.clip(processed, 0.0, 1.0), grain_state
# ==============================================================================
# END OF SUBCHUNK 84 P 02 — GRAIN DENSITY–EXPOSURE COUPLING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 P 03 — GRAIN PHASE COHERENCE DRIFT
# ==============================================================================
# Purpose:
#   Introduce slow temporal drift in grain phase alignment, simulating
#   stochastic reorganization of silver halide clusters between frames.
#
# Cinematic relevance:
#   - Prevents grain from sticking to pixels frame-to-frame
#   - Produces organic “alive” texture in motion
#   - Critical for cinematic pans, tracking shots, and motion blur
#
# Runs AFTER:
#   - 84 P 02 (Grain Density–Exposure Coupling)
# ==============================================================================
import numpy as np
import cv2
def generate_phase_offset(
    shape: tuple,
    magnitude: float,
    seed: int | None = None
) -> np.ndarray:
    """
    Generates a smooth random phase offset field.
    """
    if seed is not None:
        np.random.seed(seed)
    noise = np.random.normal(0.0, magnitude, size=shape).astype(np.float32)
    return cv2.GaussianBlur(noise, (0, 0), magnitude * 2.0)
def warp_grain_field(
    grain: np.ndarray,
    phase_x: np.ndarray,
    phase_y: np.ndarray
) -> np.ndarray:
    """
    Applies sub-pixel warping to grain field based on phase offsets.
    """
    h, w = grain.shape
    grid_x, grid_y = np.meshgrid(
        np.arange(w, dtype=np.float32),
        np.arange(h, dtype=np.float32)
    )
    map_x = grid_x + phase_x
    map_y = grid_y + phase_y
    warped = cv2.remap(
        grain,
        map_x,
        map_y,
        interpolation=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_REFLECT
    )
    return warped
def apply_phase_coherence_drift(
    grain_field: np.ndarray,
    drift_strength: float,
    seed: int | None = None
) -> np.ndarray:
    """
    Applies coherent phase drift to grain field.
    """
    h, w = grain_field.shape
    phase_x = generate_phase_offset(
        shape=(h, w),
        magnitude=drift_strength,
        seed=seed
    )
    phase_y = generate_phase_offset(
        shape=(h, w),
        magnitude=drift_strength,
        seed=None if seed is None else seed + 1
    )
    return warp_grain_field(
        grain=grain_field,
        phase_x=phase_x,
        phase_y=phase_y
    )
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_phase_coherence_drift(
    rgb_image: np.ndarray,
    grain_state: dict,
    config: dict
) -> tuple[np.ndarray, dict]:
    """
    Applies temporal grain phase coherence drift.
    """
    drift_strength = config.get("grain_phase_drift_strength", 0.0)
    if drift_strength <= 0.0 or "grain_field" not in grain_state:
        return rgb_image, grain_state
    grain_state["grain_field"] = apply_phase_coherence_drift(
        grain_field=grain_state["grain_field"],
        drift_strength=drift_strength,
        seed=config.get("seed", None)
    )
    # Apply updated grain to image (same luminance-weighted method)
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    grain = (grain_state["grain_field"] - 0.5) * config.get("grain_strength", 0.0)
    processed = rgb_image + grain[:, :, None] * (0.35 + 0.65 * luma[:, :, None])
    return np.clip(processed, 0.0, 1.0), grain_state
# ==============================================================================
# END OF SUBCHUNK 84 P 03 — GRAIN PHASE COHERENCE DRIFT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 P 04 — GRAIN COLOR CROSS-TALK
# ==============================================================================
# Purpose:
#   Model chromatic coupling between grain and dye layers, where grain
#   modulates color channels unevenly due to dye-cloud overlap, spectral
#   sensitivity mismatch, and emulsion layer diffusion.
#
# Cinematic relevance:
#   - Explains subtle color shimmer in grain-heavy regions
#   - Prevents grayscale-only grain (digital giveaway)
#   - Critical for film stock “color texture”
#
# Runs AFTER:
#   - 84 P 03 (Grain Phase Coherence Drift)
# ==============================================================================
import numpy as np
def compute_color_crosstalk_matrix(
    strength: float,
    bias: tuple[float, float, float]
) -> np.ndarray:
    """
    Builds a 3x3 color cross-talk matrix for grain modulation.
    """
    r_bias, g_bias, b_bias = bias
    base = np.array([
        [1.0, r_bias, r_bias * 0.5],
        [g_bias * 0.6, 1.0, g_bias],
        [b_bias, b_bias * 0.4, 1.0]
    ], dtype=np.float32)
    return np.eye(3, dtype=np.float32) + strength * (base - np.eye(3))
def apply_color_crosstalk_to_grain(
    grain_map: np.ndarray,
    crosstalk_matrix: np.ndarray
) -> np.ndarray:
    """
    Applies color cross-talk to grain map.
    """
    h, w = grain_map.shape
    grain_rgb = np.stack([
        grain_map,
        grain_map,
        grain_map
    ], axis=2)
    # Apply color mixing
    grain_rgb = grain_rgb.reshape(-1, 3) @ crosstalk_matrix.T
    grain_rgb = grain_rgb.reshape(h, w, 3)
    return np.clip(grain_rgb, -1.0, 1.0)
def apply_colored_grain(
    rgb: np.ndarray,
    colored_grain: np.ndarray,
    strength: float
) -> np.ndarray:
    """
    Applies colored grain modulation to RGB image.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    modulation = colored_grain * strength * (0.3 + 0.7 * luma[:, :, None])
    out = rgb + modulation
    return np.clip(out, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_color_crosstalk(
    rgb_image: np.ndarray,
    grain_state: dict,
    config: dict
) -> tuple[np.ndarray, dict]:
    """
    Applies grain color cross-talk.
    """
    strength = config.get("grain_color_crosstalk_strength", 0.0)
    if strength <= 0.0 or "grain_field" not in grain_state:
        return rgb_image, grain_state
    crosstalk_matrix = compute_color_crosstalk_matrix(
        strength=strength,
        bias=config.get("color_bias", (0.08, 0.05, 0.10))
    )
    colored_grain = apply_color_crosstalk_to_grain(
        grain_map=grain_state["grain_field"] - 0.5,
        crosstalk_matrix=crosstalk_matrix
    )
    processed = apply_colored_grain(
        rgb=rgb_image,
        colored_grain=colored_grain,
        strength=config.get("grain_strength", 0.0)
    )
    return processed, grain_state
# ==============================================================================
# END OF SUBCHUNK 84 P 04 — GRAIN COLOR CROSS-TALK
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 P 05 — GRAIN SIZE TEMPORAL BREATHING
# ==============================================================================
# Purpose:
#   Simulate slow temporal variation in apparent grain size caused by
#   developer diffusion, gelatin swelling, and stochastic aggregation changes.
#
# Cinematic relevance:
#   - Grain subtly “breathes” over time instead of staying scale-locked
#   - Prevents static, texture-stamped grain in long shots
#   - Especially visible in skies, walls, and defocused regions
#
# Runs AFTER:
#   - 84 P 04 (Grain Color Cross-Talk)
# ==============================================================================
import numpy as np
import cv2
def generate_breathing_factor(
    frame_index: int,
    amplitude: float,
    period: float
) -> float:
    """
    Computes a smooth oscillatory factor for grain size breathing.
    """
    phase = 2.0 * np.pi * (frame_index / max(period, 1.0))
    return 1.0 + amplitude * np.sin(phase)
def rescale_grain_field(
    grain: np.ndarray,
    scale_factor: float
) -> np.ndarray:
    """
    Rescales grain field to simulate size change.
    """
    h, w = grain.shape
    resized = cv2.resize(
        grain,
        None,
        fx=scale_factor,
        fy=scale_factor,
        interpolation=cv2.INTER_LINEAR
    )
    # Center-crop or pad back to original size
    rh, rw = resized.shape
    if rh > h:
        y0 = (rh - h) // 2
        resized = resized[y0:y0 + h, :]
    if rw > w:
        x0 = (rw - w) // 2
        resized = resized[:, x0:x0 + w]
    if resized.shape[0] < h or resized.shape[1] < w:
        padded = np.zeros((h, w), dtype=resized.dtype)
        padded[:resized.shape[0], :resized.shape[1]] = resized
        resized = padded
    return np.clip(resized, 0.0, 1.0)
def apply_temporal_breathing(
    grain_field: np.ndarray,
    frame_index: int,
    amplitude: float,
    period: float
) -> np.ndarray:
    """
    Applies temporal breathing to grain field.
    """
    factor = generate_breathing_factor(
        frame_index=frame_index,
        amplitude=amplitude,
        period=period
    )
    return rescale_grain_field(
        grain=grain_field,
        scale_factor=factor
    )
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_size_temporal_breathing(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies grain size temporal breathing.
    """
    amplitude = config.get("grain_breathing_amplitude", 0.0)
    if amplitude <= 0.0 or "grain_field" not in grain_state:
        return rgb_image, grain_state, temporal_state
    frame_index = temporal_state.get("frame_index", 0)
    grain_state["grain_field"] = apply_temporal_breathing(
        grain_field=grain_state["grain_field"],
        frame_index=frame_index,
        amplitude=amplitude,
        period=config.get("grain_breathing_period", 120.0)
    )
    temporal_state["frame_index"] = frame_index + 1
    # Re-apply grain using existing strength
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    grain = (grain_state["grain_field"] - 0.5) * config.get("grain_strength", 0.0)
    processed = rgb_image + grain[:, :, None] * (0.35 + 0.65 * luma[:, :, None])
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 P 05 — GRAIN SIZE TEMPORAL BREATHING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 P 06 — GRAIN MOTION PARALLAX RESPONSE
# ==============================================================================
# Purpose:
#   Simulate grain parallax behavior under camera motion, where grain
#   appears to shift relative to scene depth due to emulsion thickness,
#   light scattering, and projection geometry.
#
# Cinematic relevance:
#   - Grain subtly slides against image during motion
#   - Prevents grain from locking to pixels in pans or fly-throughs
#   - Strong realism cue in aerial and tracking shots
#
# Runs AFTER:
#   - 84 P 05 (Grain Size Temporal Breathing)
# ==============================================================================
import numpy as np
import cv2
def estimate_motion_field(
    prev_luma: np.ndarray,
    curr_luma: np.ndarray
) -> tuple[np.ndarray, np.ndarray]:
    """
    Estimates dense optical flow between frames.
    """
    flow = cv2.calcOpticalFlowFarneback(
        prev_luma,
        curr_luma,
        None,
        pyr_scale=0.5,
        levels=3,
        winsize=15,
        iterations=3,
        poly_n=5,
        poly_sigma=1.2,
        flags=0
    )
    return flow[..., 0], flow[..., 1]
def depth_weight_from_luma(
    luma: np.ndarray,
    bias: float
) -> np.ndarray:
    """
    Approximates depth weighting from luminance.
    """
    return np.clip((1.0 - luma) ** (1.0 + bias), 0.0, 1.0)
def apply_grain_parallax(
    grain_field: np.ndarray,
    flow_x: np.ndarray,
    flow_y: np.ndarray,
    depth_weight: np.ndarray,
    parallax_strength: float
) -> np.ndarray:
    """
    Warps grain field based on motion parallax.
    """
    h, w = grain_field.shape
    grid_x, grid_y = np.meshgrid(
        np.arange(w, dtype=np.float32),
        np.arange(h, dtype=np.float32)
    )
    map_x = grid_x + flow_x * depth_weight * parallax_strength
    map_y = grid_y + flow_y * depth_weight * parallax_strength
    warped = cv2.remap(
        grain_field,
        map_x,
        map_y,
        interpolation=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_REFLECT
    )
    return np.clip(warped, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_motion_parallax(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies grain motion parallax response.
    """
    strength = config.get("grain_parallax_strength", 0.0)
    if strength <= 0.0 or "grain_field" not in grain_state:
        return rgb_image, grain_state, temporal_state
    # Compute luminance
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    ).astype(np.float32)
    luma /= (np.max(luma) + 1e-6)
    # Previous luminance
    prev_luma = temporal_state.get("prev_luma")
    if prev_luma is None:
        temporal_state["prev_luma"] = luma.copy()
        return rgb_image, grain_state, temporal_state
    flow_x, flow_y = estimate_motion_field(prev_luma, luma)
    depth_weight = depth_weight_from_luma(
        luma=luma,
        bias=config.get("depth_bias", 0.6)
    )
    grain_state["grain_field"] = apply_grain_parallax(
        grain_field=grain_state["grain_field"],
        flow_x=flow_x,
        flow_y=flow_y,
        depth_weight=depth_weight,
        parallax_strength=strength
    )
    temporal_state["prev_luma"] = luma.copy()
    # Re-apply grain to RGB
    grain = (grain_state["grain_field"] - 0.5) * config.get("grain_strength", 0.0)
    processed = rgb_image + grain[:, :, None] * (0.35 + 0.65 * luma[:, :, None])
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 P 06 — GRAIN MOTION PARALLAX RESPONSE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 P 07 — GRAIN–HALATION INTERACTION
# ==============================================================================
# Purpose:
#   Couple film grain behavior with halation energy so grain contrast,
#   visibility, and micro-structure respond to bright-source bloom.
#
# Cinematic relevance:
#   - Grain softens inside halation cores
#   - Grain intensifies at halation falloff edges
#   - Prevents “digital glow pasted over grain”
#
# Runs AFTER:
#   - 84 P 06 (Grain Motion Parallax Response)
# Requires:
#   - Halation buffer or bright-source mask from optical pipeline
# ==============================================================================
import numpy as np
import cv2
def compute_halation_mask(
    luma: np.ndarray,
    threshold: float,
    blur_radius: int
) -> np.ndarray:
    """
    Generates a soft halation influence mask from luminance.
    """
    mask = np.clip((luma - threshold) / max(1e-6, 1.0 - threshold), 0.0, 1.0)
    if blur_radius > 1:
        k = blur_radius | 1
        mask = cv2.GaussianBlur(mask, (k, k), 0.0)
    return np.clip(mask, 0.0, 1.0)
def modulate_grain_by_halation(
    grain_field: np.ndarray,
    halation_mask: np.ndarray,
    core_soften: float,
    edge_boost: float
) -> np.ndarray:
    """
    Modulates grain contrast based on halation strength.
    """
    # Core: reduce contrast where halation is strongest
    softened = grain_field * (1.0 - core_soften * halation_mask)
    # Edge: boost contrast near halation gradients
    grad_x = cv2.Sobel(halation_mask, cv2.CV_32F, 1, 0, ksize=3)
    grad_y = cv2.Sobel(halation_mask, cv2.CV_32F, 0, 1, ksize=3)
    edge = np.clip(np.sqrt(grad_x ** 2 + grad_y ** 2), 0.0, 1.0)
    boosted = softened * (1.0 + edge_boost * edge)
    return np.clip(boosted, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_halation_interaction(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies grain–halation interaction using luminance-derived halation mask.
    """
    if "grain_field" not in grain_state:
        return rgb_image, grain_state, temporal_state
    # Luminance
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    ).astype(np.float32)
    luma /= (np.max(luma) + 1e-6)
    hal_mask = compute_halation_mask(
        luma=luma,
        threshold=config.get("halation_threshold", 0.85),
        blur_radius=int(config.get("halation_blur_radius", 21))
    )
    grain_state["grain_field"] = modulate_grain_by_halation(
        grain_field=grain_state["grain_field"],
        halation_mask=hal_mask,
        core_soften=config.get("grain_halation_core_soften", 0.35),
        edge_boost=config.get("grain_halation_edge_boost", 0.45)
    )
    # Re-apply grain
    grain = (grain_state["grain_field"] - 0.5) * config.get("grain_strength", 0.0)
    processed = rgb_image + grain[:, :, None] * (0.35 + 0.65 * luma[:, :, None])
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 P 07 — GRAIN–HALATION INTERACTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 P 08 — GRAIN COMPRESSION-ARTIFACT IMMUNITY
# ==============================================================================
# Purpose:
#   Shape film grain statistics so they survive modern video compression
#   (H.264 / H.265 / AV1) without collapsing into blocks, banding, or crawl.
#
# Cinematic relevance:
#   - Grain remains organic after upload to streaming platforms
#   - Prevents macroblock-aligned noise and temporal pumping
#   - Critical for aerial footage distributed online
#
# Runs AFTER:
#   - 84 P 07 (Grain–Halation Interaction)
# ==============================================================================
import numpy as np
import cv2
def bandlimit_grain(
    grain: np.ndarray,
    low_cut: float,
    high_cut: float
) -> np.ndarray:
    """
    Band-limits grain frequency spectrum to compression-safe region.
    """
    h, w = grain.shape
    fft = np.fft.fftshift(np.fft.fft2(grain))
    yy, xx = np.mgrid[:h, :w]
    cy, cx = h // 2, w // 2
    r = np.sqrt((yy - cy) ** 2 + (xx - cx) ** 2)
    r_norm = r / r.max()
    mask = (r_norm >= low_cut) & (r_norm <= high_cut)
    fft_filtered = fft * mask
    filtered = np.real(np.fft.ifft2(np.fft.ifftshift(fft_filtered)))
    return np.clip(filtered, 0.0, 1.0)
def suppress_block_alignment(
    grain: np.ndarray,
    block_size: int,
    strength: float
) -> np.ndarray:
    """
    Breaks alignment with codec macroblocks.
    """
    h, w = grain.shape
    jitter = np.random.uniform(
        -strength,
        strength,
        size=(h // block_size + 1, w // block_size + 1)
    )
    jitter = cv2.resize(jitter, (w, h), interpolation=cv2.INTER_LINEAR)
    return np.clip(grain + jitter, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_compression_immunity(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Shapes grain to survive video compression pipelines.
    """
    if "grain_field" not in grain_state:
        return rgb_image, grain_state, temporal_state
    grain = grain_state["grain_field"]
    grain = bandlimit_grain(
        grain=grain,
        low_cut=config.get("grain_low_freq_cut", 0.02),
        high_cut=config.get("grain_high_freq_cut", 0.45)
    )
    grain = suppress_block_alignment(
        grain=grain,
        block_size=int(config.get("codec_block_size", 16)),
        strength=config.get("grain_block_jitter", 0.015)
    )
    grain_state["grain_field"] = grain
    # Re-apply grain
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    grain_signal = (grain - 0.5) * config.get("grain_strength", 0.0)
    processed = rgb_image + grain_signal[:, :, None] * (0.35 + 0.65 * luma[:, :, None])
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 P 08 — GRAIN COMPRESSION-ARTIFACT IMMUNITY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 P 09 — GRAIN FREQUENCY SPECTRUM DRIFT
# ==============================================================================
# Purpose:
#   Introduce slow temporal drift in the grain frequency spectrum to
#   replicate emulsion micro-aggregation changes over time.
#
# Cinematic relevance:
#   - Prevents static “noise fingerprint”
#   - Adds long-term organic variability in skies and flats
#   - Crucial for extended drone takes and locked-off shots
#
# Runs AFTER:
#   - 84 P 08 (Grain Compression-Artifact Immunity)
# ==============================================================================
import numpy as np
def spectral_weight_mask(
    shape: tuple[int, int],
    center_shift: float,
    bandwidth: float
) -> np.ndarray:
    """
    Builds a smooth radial spectral weighting mask.
    """
    h, w = shape
    yy, xx = np.mgrid[:h, :w]
    cy, cx = h // 2, w // 2
    r = np.sqrt((yy - cy) ** 2 + (xx - cx) ** 2)
    r_norm = r / (r.max() + 1e-6)
    shifted = np.clip(r_norm + center_shift, 0.0, 1.0)
    mask = np.exp(-((shifted - 0.5) ** 2) / (2.0 * bandwidth ** 2))
    return np.clip(mask, 0.0, 1.0)
def apply_spectral_drift(
    grain: np.ndarray,
    drift_phase: float,
    drift_strength: float,
    bandwidth: float
) -> np.ndarray:
    """
    Applies frequency-domain drift to grain field.
    """
    fft = np.fft.fftshift(np.fft.fft2(grain))
    center_shift = np.sin(drift_phase) * drift_strength
    mask = spectral_weight_mask(
        shape=grain.shape,
        center_shift=center_shift,
        bandwidth=bandwidth
    )
    fft_mod = fft * mask
    drifted = np.real(np.fft.ifft2(np.fft.ifftshift(fft_mod)))
    return np.clip(drifted, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_frequency_drift(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Introduces slow spectral drift in grain.
    """
    if "grain_field" not in grain_state:
        return rgb_image, grain_state, temporal_state
    phase = temporal_state.get("grain_drift_phase", 0.0)
    grain_state["grain_field"] = apply_spectral_drift(
        grain=grain_state["grain_field"],
        drift_phase=phase,
        drift_strength=config.get("grain_spectral_drift_strength", 0.015),
        bandwidth=config.get("grain_spectral_bandwidth", 0.18)
    )
    temporal_state["grain_drift_phase"] = (
        phase + config.get("grain_spectral_drift_rate", 0.01)
    ) % (2.0 * np.pi)
    # Re-apply grain
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    grain_signal = (
        grain_state["grain_field"] - 0.5
    ) * config.get("grain_strength", 0.0)
    processed = rgb_image + grain_signal[:, :, None] * (
        0.35 + 0.65 * luma[:, :, None]
    )
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 P 09 — GRAIN FREQUENCY SPECTRUM DRIFT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 P 10 — GRAIN TEMPORAL ENERGY CONSERVATION
# ==============================================================================
# Purpose:
#   Enforce temporal conservation of grain energy so that grain does not
#   artificially intensify or fade across frames due to cumulative processing.
#
# Cinematic relevance:
#   - Prevents grain pumping and flicker in long takes
#   - Maintains perceived stock consistency shot-to-shot
#   - Critical for drone shots with slow exposure changes
#
# Runs AFTER:
#   - 84 P 09 (Grain Frequency Spectrum Drift)
# ==============================================================================
import numpy as np
def compute_grain_energy(grain: np.ndarray) -> float:
    """
    Computes RMS energy of the grain field.
    """
    centered = grain - 0.5
    return float(np.sqrt(np.mean(centered ** 2)))
def normalize_grain_energy(
    grain: np.ndarray,
    target_energy: float,
    eps: float = 1e-6
) -> np.ndarray:
    """
    Scales grain to match target RMS energy.
    """
    current_energy = compute_grain_energy(grain)
    scale = target_energy / max(current_energy, eps)
    return np.clip(0.5 + (grain - 0.5) * scale, 0.0, 1.0)
def adaptive_energy_target(
    base_energy: float,
    luma_mean: float,
    exposure_bias: float
) -> float:
    """
    Adjusts target energy slightly based on exposure and luminance.
    """
    exposure_factor = 1.0 + exposure_bias * (0.5 - luma_mean)
    return base_energy * np.clip(exposure_factor, 0.85, 1.15)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_grain_energy_conservation(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Enforces temporal grain energy consistency.
    """
    if "grain_field" not in grain_state:
        return rgb_image, grain_state, temporal_state
    grain = grain_state["grain_field"]
    # Compute current luminance statistics
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    luma_mean = float(np.mean(luma))
    # Initialize reference energy
    if "grain_energy_ref" not in temporal_state:
        temporal_state["grain_energy_ref"] = compute_grain_energy(grain)
    target_energy = adaptive_energy_target(
        base_energy=temporal_state["grain_energy_ref"],
        luma_mean=luma_mean,
        exposure_bias=config.get("grain_energy_exposure_bias", 0.15)
    )
    grain_state["grain_field"] = normalize_grain_energy(
        grain=grain,
        target_energy=target_energy
    )
    # Re-apply grain with conserved energy
    grain_signal = (
        grain_state["grain_field"] - 0.5
    ) * config.get("grain_strength", 0.0)
    processed = rgb_image + grain_signal[:, :, None] * (
        0.35 + 0.65 * luma[:, :, None]
    )
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 P 10 — GRAIN TEMPORAL ENERGY CONSERVATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Q 01 — PROJECTION OPTICAL SCATTER MODEL
# ==============================================================================
# Purpose:
#   Simulate optical scatter occurring in real film projection systems:
#   projector lens flare, internal reflections, gate flare, and screen bounce.
#
# Cinematic relevance:
#   - Softens contrast in a physically plausible way
#   - Lifts deep blacks slightly without flattening midtones
#   - Creates “cinema glow” impossible to fake with simple bloom
#
# Runs AFTER:
#   - 84 P 10 (Grain Temporal Energy Conservation)
# ==============================================================================
import numpy as np
import cv2
def compute_scatter_kernel(
    radius: int,
    falloff: float
) -> np.ndarray:
    """
    Builds a physically-inspired radial scatter kernel.
    """
    size = radius * 2 + 1
    yy, xx = np.mgrid[-radius:radius+1, -radius:radius+1]
    r = np.sqrt(xx ** 2 + yy ** 2)
    kernel = np.exp(-r * falloff)
    kernel /= np.sum(kernel)
    return kernel.astype(np.float32)
def apply_projection_scatter(
    luma: np.ndarray,
    kernel: np.ndarray,
    strength: float
) -> np.ndarray:
    """
    Applies optical scatter to luminance channel.
    """
    scattered = cv2.filter2D(luma, -1, kernel)
    return np.clip(luma + scattered * strength, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_projection_optical_scatter(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies projection optical scatter to the image.
    """
    strength = config.get("projection_scatter_strength", 0.08)
    if strength <= 0.0:
        return rgb_image, grain_state, temporal_state
    # Compute luminance
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    ).astype(np.float32)
    luma /= (np.max(luma) + 1e-6)
    kernel = compute_scatter_kernel(
        radius=int(config.get("projection_scatter_radius", 15)),
        falloff=config.get("projection_scatter_falloff", 0.15)
    )
    scattered_luma = apply_projection_scatter(
        luma=luma,
        kernel=kernel,
        strength=strength
    )
    # Ratio-preserving reapplication to RGB
    ratio = scattered_luma / (luma + 1e-6)
    processed = rgb_image * ratio[:, :, None]
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Q 01 — PROJECTION OPTICAL SCATTER MODEL
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Q 02 — PROJECTOR GATE DIFFUSION
# ==============================================================================
# Purpose:
#   Simulate microscopic diffusion introduced by the physical projector gate:
#   pressure plate scattering, aperture edge bloom, and emulsion thickness.
#
# Cinematic relevance:
#   - Softens hard geometric edges without blurring detail
#   - Introduces subtle “projection softness” in high-contrast transitions
#   - Prevents razor-sharp digital edges in projected highlights
#
# Runs AFTER:
#   - 84 Q 01 (Projection Optical Scatter Model)
# ==============================================================================
import numpy as np
import cv2
def build_gate_diffusion_kernel(
    radius: int,
    anisotropy: float
) -> np.ndarray:
    """
    Builds an anisotropic diffusion kernel mimicking gate pressure and film travel.
    """
    size = radius * 2 + 1
    yy, xx = np.mgrid[-radius:radius+1, -radius:radius+1]
    # Vertical diffusion slightly stronger (film transport direction)
    r = np.sqrt((xx ** 2) + (yy ** 2) * (1.0 + anisotropy))
    kernel = np.exp(-(r ** 2) / (2.0 * (radius ** 2)))
    kernel /= np.sum(kernel)
    return kernel.astype(np.float32)
def apply_gate_diffusion(
    image: np.ndarray,
    kernel: np.ndarray,
    strength: float
) -> np.ndarray:
    """
    Applies gate diffusion with edge-aware blending.
    """
    blurred = cv2.filter2D(image, -1, kernel)
    return np.clip(image * (1.0 - strength) + blurred * strength, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_projector_gate_diffusion(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies projector gate diffusion to RGB image.
    """
    strength = config.get("gate_diffusion_strength", 0.06)
    if strength <= 0.0:
        return rgb_image, grain_state, temporal_state
    kernel = build_gate_diffusion_kernel(
        radius=int(config.get("gate_diffusion_radius", 3)),
        anisotropy=config.get("gate_diffusion_anisotropy", 0.35)
    )
    processed = apply_gate_diffusion(
        image=rgb_image,
        kernel=kernel,
        strength=strength
    )
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Q 02 — PROJECTOR GATE DIFFUSION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Q 03 — LENS–PROJECTOR COUPLED VIGNETTING
# ==============================================================================
# Purpose:
#   Model vignetting as a coupled optical phenomenon between
#   projection lens geometry, gate aperture, and screen incidence angle.
#
# Cinematic relevance:
#   - Corners darken non-linearly with highlight lift preserved
#   - Vignetting strength changes with luminance and scatter
#   - Prevents flat, digital radial masks
#
# Runs AFTER:
#   - 84 Q 02 (Projector Gate Diffusion)
# ==============================================================================
import numpy as np
def build_vignette_field(
    shape: tuple[int, int],
    strength: float,
    exponent: float
) -> np.ndarray:
    """
    Builds a physically weighted vignette field.
    """
    h, w = shape
    yy, xx = np.mgrid[0:h, 0:w]
    nx = (xx - w * 0.5) / (w * 0.5)
    ny = (yy - h * 0.5) / (h * 0.5)
    r = np.sqrt(nx ** 2 + ny ** 2)
    r = np.clip(r, 0.0, 1.0)
    vignette = 1.0 - strength * (r ** exponent)
    return np.clip(vignette, 0.0, 1.0)
def couple_vignette_to_luminance(
    vignette: np.ndarray,
    luma: np.ndarray,
    highlight_preserve: float
) -> np.ndarray:
    """
    Preserves highlights against vignetting using luminance coupling.
    """
    preserve = 1.0 - highlight_preserve * np.clip(luma, 0.0, 1.0)
    return np.clip(vignette + (1.0 - vignette) * preserve, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_lens_projector_vignetting(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies lens–projector coupled vignetting.
    """
    strength = config.get("projection_vignette_strength", 0.18)
    if strength <= 0.0:
        return rgb_image, grain_state, temporal_state
    exponent = config.get("projection_vignette_exponent", 2.2)
    highlight_preserve = config.get("projection_vignette_highlight_preserve", 0.6)
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    vignette = build_vignette_field(
        shape=luma.shape,
        strength=strength,
        exponent=exponent
    )
    vignette = couple_vignette_to_luminance(
        vignette=vignette,
        luma=luma,
        highlight_preserve=highlight_preserve
    )
    processed = rgb_image * vignette[:, :, None]
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Q 03 — LENS–PROJECTOR COUPLED VIGNETTING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Q 04 — PROJECTION LUMINANCE ROLL-OFF
# ==============================================================================
# Purpose:
#   Model the characteristic luminance roll-off of film projection systems,
#   where highlights compress gently and deep blacks lift slightly due to
#   optical flare, screen reflectance, and projector lamp behavior.
#
# Cinematic relevance:
#   - Highlights never clip abruptly
#   - Blacks retain shadow detail without flattening midtones
#   - Prevents harsh digital contrast curves
#
# Runs AFTER:
#   - 84 Q 03 (Lens–Projector Coupled Vignetting)
# ==============================================================================
import numpy as np
def projection_luminance_curve(
    luma: np.ndarray,
    shoulder_strength: float,
    toe_lift: float
) -> np.ndarray:
    """
    Applies a film-projection-style tone curve to luminance.
    """
    # Shoulder compression (highlights)
    shoulder = luma / (luma + shoulder_strength)
    # Toe lift (shadows)
    toe = np.power(luma, 1.0 - toe_lift)
    # Blend toe and shoulder smoothly
    mix = np.clip(luma, 0.0, 1.0)
    rolled = mix * shoulder + (1.0 - mix) * toe
    return np.clip(rolled, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_projection_luminance_rolloff(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies projection-style luminance roll-off.
    """
    shoulder = config.get("projection_shoulder_strength", 0.35)
    toe_lift = config.get("projection_toe_lift", 0.12)
    # Luminance
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    rolled_luma = projection_luminance_curve(
        luma=luma,
        shoulder_strength=shoulder,
        toe_lift=toe_lift
    )
    # Ratio-preserving reapplication
    ratio = rolled_luma / (luma + 1e-6)
    processed = rgb_image * ratio[:, :, None]
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Q 04 — PROJECTION LUMINANCE ROLL-OFF
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Q 05 — SCREEN REFLECTANCE RESPONSE
# ==============================================================================
# Purpose:
#   Model how cinema projection screens reflect light back to the viewer,
#   including gain roll-off, color bias, and contrast compression caused by
#   diffuse vs semi-specular screen materials.
#
# Cinematic relevance:
#   - Slight desaturation in highlights
#   - Blacks lift subtly without killing midtone contrast
#   - Prevents “emissive display” look
#
# Runs AFTER:
#   - 84 Q 04 (Projection Luminance Roll-off)
# ==============================================================================
import numpy as np
def screen_gain_curve(
    luma: np.ndarray,
    peak_gain: float,
    rolloff: float
) -> np.ndarray:
    """
    Models screen gain compression at higher luminance.
    """
    return luma * (1.0 + peak_gain * np.exp(-luma / max(rolloff, 1e-6)))
def apply_screen_color_bias(
    rgb: np.ndarray,
    bias: np.ndarray,
    luma: np.ndarray,
    strength: float
) -> np.ndarray:
    """
    Applies luminance-dependent color bias caused by screen coating.
    """
    bias_rgb = bias.reshape((1, 1, 3))
    mix = strength * luma[:, :, None]
    return np.clip(rgb * (1.0 - mix) + rgb * bias_rgb * mix, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_screen_reflectance_response(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies screen reflectance response model.
    """
    peak_gain = config.get("screen_peak_gain", 0.12)
    rolloff = config.get("screen_gain_rolloff", 0.45)
    color_bias = np.array(
        config.get("screen_color_bias", [1.02, 1.00, 0.98]),
        dtype=np.float32
    )
    bias_strength = config.get("screen_color_bias_strength", 0.25)
    # Compute luminance
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    # Gain compression
    gained_luma = screen_gain_curve(
        luma=luma,
        peak_gain=peak_gain,
        rolloff=rolloff
    )
    # Ratio-preserving luminance remap
    ratio = gained_luma / (luma + 1e-6)
    processed = rgb_image * ratio[:, :, None]
    # Apply color bias
    processed = apply_screen_color_bias(
        rgb=processed,
        bias=color_bias,
        luma=luma,
        strength=bias_strength
    )
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Q 05 — SCREEN REFLECTANCE RESPONSE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Q 06 — VIEWING ANGLE CONTRAST LOSS
# ==============================================================================
# Purpose:
#   Model contrast reduction and subtle chroma shifts caused by off-axis
#   viewing of cinema screens (Lambertian + screen gain behavior).
#
# Cinematic relevance:
#   - Contrast gently reduces toward edges
#   - Blacks lift slightly off-axis without flattening center
#   - Prevents “perfectly uniform monitor” appearance
#
# Runs AFTER:
#   - 84 Q 05 (Screen Reflectance Response)
# ==============================================================================
import numpy as np
def compute_view_angle_field(
    shape: tuple[int, int],
    fov_degrees: float
) -> np.ndarray:
    """
    Computes per-pixel view-angle magnitude based on screen FOV.
    """
    h, w = shape
    yy, xx = np.mgrid[0:h, 0:w]
    nx = (xx - w * 0.5) / (w * 0.5)
    ny = (yy - h * 0.5) / (h * 0.5)
    r = np.sqrt(nx ** 2 + ny ** 2)
    r = np.clip(r, 0.0, 1.0)
    max_angle = np.deg2rad(fov_degrees * 0.5)
    return r * max_angle
def contrast_loss_curve(
    angle: np.ndarray,
    strength: float
) -> np.ndarray:
    """
    Models cosine-based contrast loss with soft falloff.
    """
    loss = np.cos(angle)
    return np.clip(1.0 - strength * (1.0 - loss), 0.0, 1.0)
def chroma_desat_offaxis(
    rgb: np.ndarray,
    angle: np.ndarray,
    strength: float
) -> np.ndarray:
    """
    Slight chroma desaturation at off-axis angles.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    luma = luma[:, :, None]
    mix = np.clip(angle / (angle.max() + 1e-6), 0.0, 1.0)
    mix = mix[:, :, None] * strength
    return np.clip(rgb * (1.0 - mix) + luma * mix, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_viewing_angle_contrast_loss(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies viewing-angle dependent contrast loss and chroma shift.
    """
    strength = config.get("view_angle_contrast_strength", 0.35)
    fov = config.get("screen_view_fov_degrees", 60.0)
    chroma_strength = config.get("view_angle_chroma_desat", 0.25)
    if strength <= 0.0:
        return rgb_image, grain_state, temporal_state
    angle = compute_view_angle_field(
        shape=rgb_image.shape[:2],
        fov_degrees=fov
    )
    # Luminance-based contrast modulation
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    contrast_scale = contrast_loss_curve(
        angle=angle,
        strength=strength
    )
    luma_mod = 0.5 + (luma - 0.5) * contrast_scale
    ratio = luma_mod / (luma + 1e-6)
    processed = rgb_image * ratio[:, :, None]
    # Off-axis chroma desaturation
    processed = chroma_desat_offaxis(
        rgb=processed,
        angle=angle,
        strength=chroma_strength
    )
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Q 06 — VIEWING ANGLE CONTRAST LOSS
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Q 07 — PROJECTION COLOR CROSS-SCATTER
# ==============================================================================
# Purpose:
#   Simulate chromatic cross-scatter occurring in projection systems due to
#   lens coatings, internal reflections, emulsion thickness, and screen diffusion.
#
# Cinematic relevance:
#   - Highlights bleed subtle color into neighboring channels
#   - Prevents sterile RGB separation
#   - Major contributor to “film warmth” and color cohesion
#
# Runs AFTER:
#   - 84 Q 06 (Viewing Angle Contrast Loss)
# ==============================================================================
import numpy as np
import cv2
def build_cross_scatter_matrix(
    strength: float,
    bias: tuple[float, float, float]
) -> np.ndarray:
    """
    Builds a color cross-scatter matrix.
    """
    r_bias, g_bias, b_bias = bias
    matrix = np.array([
        [1.0, strength * r_bias, strength * r_bias],
        [strength * g_bias, 1.0, strength * g_bias],
        [strength * b_bias, strength * b_bias, 1.0]
    ], dtype=np.float32)
    return matrix
def apply_color_cross_scatter(
    rgb: np.ndarray,
    matrix: np.ndarray,
    luma: np.ndarray,
    luma_weight: float
) -> np.ndarray:
    """
    Applies luminance-weighted color cross-scatter.
    """
    h, w, _ = rgb.shape
    reshaped = rgb.reshape(-1, 3)
    scattered = reshaped @ matrix.T
    scattered = scattered.reshape(h, w, 3)
    mix = np.clip(luma * luma_weight, 0.0, 1.0)[:, :, None]
    return np.clip(rgb * (1.0 - mix) + scattered * mix, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_projection_color_cross_scatter(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies projection color cross-scatter.
    """
    strength = config.get("projection_color_scatter_strength", 0.08)
    if strength <= 0.0:
        return rgb_image, grain_state, temporal_state
    bias = tuple(config.get(
        "projection_color_scatter_bias",
        [0.9, 1.0, 1.1]
    ))
    luma_weight = config.get("projection_color_scatter_luma_weight", 0.75)
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    matrix = build_cross_scatter_matrix(
        strength=strength,
        bias=bias
    )
    processed = apply_color_cross_scatter(
        rgb=rgb_image,
        matrix=matrix,
        luma=luma,
        luma_weight=luma_weight
    )
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Q 07 — PROJECTION COLOR CROSS-SCATTER
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Q 08 — SCREEN MICRO-TEXTURE DIFFUSION
# ==============================================================================
# Purpose:
#   Simulate microscopic diffusion caused by cinema screen surface texture
#   (gain beads, matte coating, perforations), producing controlled spatial
#   softening without loss of perceived sharpness.
#
# Cinematic relevance:
#   - Breaks digital edge perfection
#   - Adds organic coherence to motion
#   - Preserves MTF while diffusing micro-contrast
#
# Runs AFTER:
#   - 84 Q 07 (Projection Color Cross-Scatter)
# ==============================================================================
import numpy as np
import cv2
def build_micro_texture_kernel(
    radius: int,
    anisotropy: float
) -> np.ndarray:
    """
    Builds an anisotropic diffusion kernel approximating screen surface texture.
    """
    size = radius * 2 + 1
    y, x = np.mgrid[-radius:radius+1, -radius:radius+1]
    # Elliptical Gaussian (screen fibers / bead stretch)
    sigma_x = radius * (1.0 + anisotropy)
    sigma_y = radius * (1.0 - anisotropy)
    kernel = np.exp(
        -0.5 * ((x ** 2) / (sigma_x ** 2 + 1e-6) +
                (y ** 2) / (sigma_y ** 2 + 1e-6))
    )
    kernel /= np.sum(kernel)
    return kernel.astype(np.float32)
def apply_micro_diffusion(
    channel: np.ndarray,
    kernel: np.ndarray
) -> np.ndarray:
    """
    Applies diffusion to a single channel.
    """
    return cv2.filter2D(channel, -1, kernel, borderType=cv2.BORDER_REFLECT)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_screen_micro_texture_diffusion(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies screen micro-texture diffusion while preserving perceived sharpness.
    """
    strength = config.get("screen_micro_texture_strength", 0.18)
    if strength <= 0.0:
        return rgb_image, grain_state, temporal_state
    radius = int(config.get("screen_micro_texture_radius", 2))
    anisotropy = float(config.get("screen_micro_texture_anisotropy", 0.15))
    kernel = build_micro_texture_kernel(
        radius=radius,
        anisotropy=anisotropy
    )
    # Luminance-driven blend (highlights diffuse more)
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma /= (np.max(luma) + 1e-6)
    processed = np.empty_like(rgb_image)
    for c in range(3):
        blurred = apply_micro_diffusion(
            channel=rgb_image[:, :, c],
            kernel=kernel
        )
        # Diffusion increases with luminance but never dominates
        mix = np.clip(luma * strength, 0.0, strength)
        processed[:, :, c] = (
            rgb_image[:, :, c] * (1.0 - mix) +
            blurred * mix
        )
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Q 08 — SCREEN MICRO-TEXTURE DIFFUSION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Q 09 — AMBIENT LIGHT CONTAMINATION
# ==============================================================================
# Purpose:
#   Simulate ambient room light contamination in cinema projection:
#   reflected spill light lifts blacks, reduces local contrast, and subtly
#   tints shadows based on environment and screen gain.
#
# Cinematic relevance:
#   - Prevents “perfect black” in dark scenes
#   - Adds scene-dependent black lift
#   - Reinforces projected (non-emissive) behavior
#
# Runs AFTER:
#   - 84 Q 08 (Screen Micro-Texture Diffusion)
# ==============================================================================
import numpy as np
def estimate_scene_luminance(rgb: np.ndarray) -> float:
    """
    Estimates average scene luminance for ambient interaction.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    return float(np.mean(luma))
def compute_ambient_lift(
    luma: np.ndarray,
    scene_avg: float,
    base_lift: float,
    dynamic_scale: float
) -> np.ndarray:
    """
    Computes ambient black lift field.
    """
    # Dark regions lift more; highlights resist contamination
    shadow_weight = np.clip(1.0 - luma * 1.25, 0.0, 1.0)
    # Scene brightness increases room bounce
    scene_factor = np.clip(scene_avg * dynamic_scale, 0.0, 1.0)
    return base_lift * shadow_weight * (0.5 + scene_factor)
def apply_ambient_color_tint(
    lift: np.ndarray,
    tint: tuple[float, float, float]
) -> np.ndarray:
    """
    Converts scalar lift into RGB-tinted contamination.
    """
    r_t, g_t, b_t = tint
    rgb_lift = np.zeros((*lift.shape, 3), dtype=np.float32)
    rgb_lift[:, :, 0] = lift * r_t
    rgb_lift[:, :, 1] = lift * g_t
    rgb_lift[:, :, 2] = lift * b_t
    return rgb_lift
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_ambient_light_contamination(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies ambient light contamination to projected image.
    """
    base_lift = config.get("ambient_light_black_lift", 0.03)
    if base_lift <= 0.0:
        return rgb_image, grain_state, temporal_state
    dynamic_scale = config.get("ambient_light_scene_scale", 0.85)
    tint = tuple(config.get(
        "ambient_light_color_tint",
        [1.0, 0.97, 0.94]   # warm theater walls bias
    ))
    # Compute luminance fields
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma = np.clip(luma, 0.0, 1.0)
    scene_avg = estimate_scene_luminance(rgb_image)
    lift_field = compute_ambient_lift(
        luma=luma,
        scene_avg=scene_avg,
        base_lift=base_lift,
        dynamic_scale=dynamic_scale
    )
    rgb_lift = apply_ambient_color_tint(
        lift=lift_field,
        tint=tint
    )
    processed = rgb_image + rgb_lift
    # Soft roll-off to prevent milky highlights
    processed = processed / (1.0 + processed * 0.15)
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Q 09 — AMBIENT LIGHT CONTAMINATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Q 10 — PROJECTION SYSTEM AGING DRIFT
# ==============================================================================
# Purpose:
#   Model slow temporal drift in projection systems caused by lamp aging,
#   phosphor wear, optics yellowing, and panel degradation.
#
# Cinematic relevance:
#   - Subtle white-point drift over runtime
#   - Gradual contrast compression
#   - Slight channel imbalance (often blue loss, warm bias)
#
# Runs AFTER:
#   - 84 Q 09 (Ambient Light Contamination)
# ==============================================================================
import numpy as np
def compute_aging_whitepoint(
    hours: float,
    base_wp: tuple[float, float, float],
    drift_rate: tuple[float, float, float]
) -> np.ndarray:
    """
    Computes aged white-point multiplier based on projector runtime hours.
    """
    r0, g0, b0 = base_wp
    dr, dg, db = drift_rate
    # Logarithmic aging response (fast early, slower later)
    t = np.log1p(hours) / np.log1p(5000.0)
    t = np.clip(t, 0.0, 1.0)
    wp = np.array([
        r0 * (1.0 - dr * t),
        g0 * (1.0 - dg * t),
        b0 * (1.0 - db * t)
    ], dtype=np.float32)
    return wp
def compute_contrast_decay(
    hours: float,
    max_decay: float
) -> float:
    """
    Computes global contrast decay factor from aging optics.
    """
    t = np.sqrt(np.clip(hours / 8000.0, 0.0, 1.0))
    return 1.0 - max_decay * t
def apply_aging_transform(
    rgb: np.ndarray,
    whitepoint: np.ndarray,
    contrast: float
) -> np.ndarray:
    """
    Applies white-point drift and contrast decay.
    """
    # White-point scaling
    aged = rgb * whitepoint[None, None, :]
    # Contrast compression around mid-gray
    aged = 0.5 + (aged - 0.5) * contrast
    return aged
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_projection_system_aging_drift(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies long-term projection system aging drift.
    """
    hours = float(config.get("projection_runtime_hours", 1200.0))
    if hours <= 0.0:
        return rgb_image, grain_state, temporal_state
    base_wp = tuple(config.get(
        "projection_base_whitepoint",
        [1.0, 1.0, 1.0]
    ))
    drift_rate = tuple(config.get(
        "projection_whitepoint_drift_rate",
        [0.04, 0.02, 0.08]  # blue ages fastest
    ))
    max_contrast_decay = float(
        config.get("projection_contrast_max_decay", 0.12)
    )
    whitepoint = compute_aging_whitepoint(
        hours=hours,
        base_wp=base_wp,
        drift_rate=drift_rate
    )
    contrast = compute_contrast_decay(
        hours=hours,
        max_decay=max_contrast_decay
    )
    processed = apply_aging_transform(
        rgb=rgb_image,
        whitepoint=whitepoint,
        contrast=contrast
    )
    # Store aging state for temporal continuity
    temporal_state["projection_aging_hours"] = hours
    temporal_state["projection_whitepoint"] = whitepoint.tolist()
    temporal_state["projection_contrast"] = contrast
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Q 10 — PROJECTION SYSTEM AGING DRIFT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 R 01 — THEATER OPTICAL CHAIN INTEGRATION
# ==============================================================================
# Purpose:
#   Integrate all projection-domain optical effects into a single coherent
#   perceptual model representing the full theater optical chain:
#   projector optics → lens → screen → ambient environment → viewer eye.
#
# Cinematic relevance:
#   - Prevents additive artifacts from stacking independently
#   - Enforces physically plausible interaction order
#   - Locks projection look into a single perceptual space
#
# Runs AFTER:
#   - 84 Q 10 (Projection System Aging Drift)
# ==============================================================================
import numpy as np
def normalize_projection_energy(
    rgb: np.ndarray,
    target_peak: float
) -> np.ndarray:
    """
    Normalizes total projected energy to avoid cumulative brightness inflation.
    """
    peak = np.percentile(rgb, 99.9)
    if peak <= 0.0:
        return rgb
    scale = target_peak / peak
    return rgb * scale
def apply_chain_soft_clamp(
    rgb: np.ndarray,
    knee: float,
    softness: float
) -> np.ndarray:
    """
    Soft perceptual clamp to prevent harsh clipping after chain integration.
    """
    x = rgb
    return x / (1.0 + (x / knee) ** softness)
def integrate_projection_chain(
    rgb: np.ndarray,
    config: dict
) -> np.ndarray:
    """
    Applies final optical-chain integration logic.
    """
    # Normalize accumulated energy
    target_peak = config.get("projection_chain_target_peak", 1.05)
    rgb = normalize_projection_energy(rgb, target_peak)
    # Perceptual soft clamp (lens + eye response)
    knee = config.get("projection_chain_soft_knee", 1.1)
    softness = config.get("projection_chain_softness", 2.4)
    rgb = apply_chain_soft_clamp(rgb, knee, softness)
    return rgb
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_theater_optical_chain_integration(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Integrates all projection-domain optical effects into a unified response.
    """
    enabled = config.get("enable_projection_chain_integration", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    processed = integrate_projection_chain(
        rgb=rgb_image,
        config=config
    )
    # Store perceptual chain metadata
    temporal_state["projection_chain_enabled"] = True
    temporal_state["projection_chain_peak"] = float(
        np.percentile(processed, 99.9)
    )
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 R 01 — THEATER OPTICAL CHAIN INTEGRATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 R 02 — PROJECTION-TO-ACES REFERENCE MAPPING
# ==============================================================================
# Purpose:
#   Remap the final projected-domain image back into an ACES-aligned
#   reference space, preserving theatrical perception while maintaining
#   colorimetric consistency with the original grade.
#
# Cinematic relevance:
#   - Ensures projection artifacts do not break grading intent
#   - Maintains ACES neutrality for downstream ODTs
#   - Allows theater look to coexist with color-managed pipelines
#
# Runs AFTER:
#   - 84 R 01 (Theater Optical Chain Integration)
# ==============================================================================
import numpy as np
def compute_aces_projection_compensation(
    rgb: np.ndarray,
    target_gray: float
) -> float:
    """
    Computes scalar compensation to align mid-gray with ACES reference.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    mid = np.percentile(luma, 50.0)
    if mid <= 1e-6:
        return 1.0
    return target_gray / mid
def apply_aces_reference_mapping(
    rgb: np.ndarray,
    compensation: float,
    chroma_protect: float
) -> np.ndarray:
    """
    Applies luminance compensation while protecting chroma ratios.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    luma = np.clip(luma, 1e-6, None)
    scaled_luma = luma * compensation
    ratio = scaled_luma / luma
    ratio = ratio[:, :, None]
    # Protect chroma from excessive scaling
    protected = rgb * (1.0 - chroma_protect) + (rgb * ratio) * chroma_protect
    return protected
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_projection_to_aces_reference_mapping(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Remaps projected image into ACES-aligned perceptual reference space.
    """
    enabled = config.get("enable_projection_aces_mapping", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    target_gray = float(config.get("aces_reference_midgray", 0.18))
    chroma_protect = float(config.get("aces_chroma_protection", 0.85))
    compensation = compute_aces_projection_compensation(
        rgb=rgb_image,
        target_gray=target_gray
    )
    processed = apply_aces_reference_mapping(
        rgb=rgb_image,
        compensation=compensation,
        chroma_protect=chroma_protect
    )
    temporal_state["projection_aces_compensation"] = compensation
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 R 02 — PROJECTION-TO-ACES REFERENCE MAPPING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 R 03 — SCREEN-DEPENDENT GAMMA OFFSET
# ==============================================================================
# Purpose:
#   Model gamma response changes introduced by cinema screen materials
#   (gain, coating, perforation density) causing non-uniform midtone rolloff.
#
# Cinematic relevance:
#   - Midtones compress subtly without crushing shadows
#   - Highlights retain projection softness
#   - Prevents emissive-display gamma behavior
#
# Runs AFTER:
#   - 84 R 02 (Projection-to-ACES Reference Mapping)
# ==============================================================================
import numpy as np
def compute_screen_gamma_offset(
    luma: np.ndarray,
    base_gamma: float,
    edge_gamma_boost: float
) -> np.ndarray:
    """
    Computes per-pixel gamma based on screen response and radial position.
    """
    h, w = luma.shape
    yy, xx = np.mgrid[0:h, 0:w]
    nx = (xx - w * 0.5) / (w * 0.5)
    ny = (yy - h * 0.5) / (h * 0.5)
    r = np.sqrt(nx ** 2 + ny ** 2)
    r = np.clip(r, 0.0, 1.0)
    gamma_field = base_gamma + edge_gamma_boost * r
    return gamma_field
def apply_gamma_field(
    rgb: np.ndarray,
    gamma_field: np.ndarray
) -> np.ndarray:
    """
    Applies spatially varying gamma to RGB image.
    """
    rgb = np.clip(rgb, 1e-6, 1.0)
    out = np.empty_like(rgb)
    for c in range(3):
        out[:, :, c] = np.power(rgb[:, :, c], gamma_field)
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_screen_dependent_gamma_offset(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies screen-dependent gamma offset.
    """
    enabled = config.get("enable_screen_gamma_offset", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    base_gamma = float(config.get("screen_base_gamma", 1.08))
    edge_gamma_boost = float(config.get("screen_edge_gamma_boost", 0.12))
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    gamma_field = compute_screen_gamma_offset(
        luma=luma,
        base_gamma=base_gamma,
        edge_gamma_boost=edge_gamma_boost
    )
    processed = apply_gamma_field(
        rgb=rgb_image,
        gamma_field=gamma_field
    )
    temporal_state["screen_gamma_base"] = base_gamma
    temporal_state["screen_gamma_edge_boost"] = edge_gamma_boost
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 R 03 — SCREEN-DEPENDENT GAMMA OFFSET
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 R 04 — AUDITORIUM LUMINANCE FALLOFF
# ==============================================================================
# Purpose:
#   Simulate luminance falloff across the projected image caused by auditorium
#   geometry, seating distance, screen curvature, and projector throw.
#
# Cinematic relevance:
#   - Slight edge dimming relative to center
#   - Depth cue during camera motion
#   - Prevents flat, uniformly-lit screen appearance
#
# Runs AFTER:
#   - 84 R 03 (Screen-Dependent Gamma Offset)
# ==============================================================================
import numpy as np
def compute_auditorium_falloff_field(
    shape: tuple[int, int],
    center_gain: float,
    edge_falloff: float,
    curvature: float
) -> np.ndarray:
    """
    Computes a radial luminance falloff field representing auditorium geometry.
    """
    h, w = shape
    yy, xx = np.mgrid[0:h, 0:w]
    nx = (xx - w * 0.5) / (w * 0.5)
    ny = (yy - h * 0.5) / (h * 0.5)
    r = np.sqrt(nx ** 2 + ny ** 2)
    r = np.clip(r, 0.0, 1.0)
    # Curved falloff profile (projector throw + screen curvature)
    profile = np.power(r, curvature)
    falloff = center_gain - edge_falloff * profile
    return np.clip(falloff, 0.0, 1.0)
def apply_luminance_falloff(
    rgb: np.ndarray,
    falloff_field: np.ndarray,
    luma_preserve: float
) -> np.ndarray:
    """
    Applies luminance falloff while preserving color ratios.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    luma = np.clip(luma, 1e-6, None)
    scaled_luma = luma * falloff_field
    ratio = scaled_luma / luma
    ratio = ratio[:, :, None]
    # Blend to avoid over-darkening chroma
    out = rgb * (1.0 - luma_preserve) + (rgb * ratio) * luma_preserve
    return out
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_auditorium_luminance_falloff(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies auditorium-based luminance falloff to the projected image.
    """
    enabled = config.get("enable_auditorium_falloff", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    center_gain = float(config.get("auditorium_center_gain", 1.0))
    edge_falloff = float(config.get("auditorium_edge_falloff", 0.18))
    curvature = float(config.get("auditorium_falloff_curvature", 1.6))
    luma_preserve = float(config.get("auditorium_luma_preserve", 0.85))
    falloff_field = compute_auditorium_falloff_field(
        shape=rgb_image.shape[:2],
        center_gain=center_gain,
        edge_falloff=edge_falloff,
        curvature=curvature
    )
    processed = apply_luminance_falloff(
        rgb=rgb_image,
        falloff_field=falloff_field,
        luma_preserve=luma_preserve
    )
    temporal_state["auditorium_center_gain"] = center_gain
    temporal_state["auditorium_edge_falloff"] = edge_falloff
    temporal_state["auditorium_falloff_curvature"] = curvature
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 R 04 — AUDITORIUM LUMINANCE FALLOFF
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 R 05 — PERCEPTUAL BRIGHTNESS NORMALIZATION
# ==============================================================================
# Purpose:
#   Normalize perceived brightness across scenes and within shots by modeling
#   human contrast sensitivity and midtone anchoring under projected viewing.
#
# Cinematic relevance:
#   - Prevents perceived exposure “pumping” between cuts
#   - Anchors midtones while respecting highlights/shadows
#   - Preserves artistic intent under changing context
#
# Runs AFTER:
#   - 84 R 04 (Auditorium Luminance Falloff)
# ==============================================================================
import numpy as np
def compute_perceptual_anchor(
    luma: np.ndarray,
    percentile: float
) -> float:
    """
    Computes a perceptual midtone anchor from luminance distribution.
    """
    return float(np.percentile(luma, percentile))
def csf_weight(luma: np.ndarray) -> np.ndarray:
    """
    Contrast Sensitivity Function approximation: midtones weighted highest.
    """
    # Peaks near mid-gray; suppresses extremes
    return np.exp(-((luma - 0.5) ** 2) / 0.08)
def normalize_brightness(
    rgb: np.ndarray,
    anchor: float,
    target_anchor: float,
    strength: float
) -> np.ndarray:
    """
    Normalizes perceived brightness around a midtone anchor.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    luma = np.clip(luma, 1e-6, None)
    # Compute adjustment ratio with damping
    ratio = (target_anchor / anchor) ** strength
    # CSF-weighted application to protect highlights/shadows
    w = csf_weight(luma)
    adj = 1.0 + (ratio - 1.0) * w
    return rgb * adj[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_perceptual_brightness_normalization(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies perceptual brightness normalization for cinematic continuity.
    """
    enabled = config.get("enable_perceptual_brightness_norm", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    anchor_percentile = float(
        config.get("perceptual_anchor_percentile", 55.0)
    )
    target_anchor = float(
        config.get("perceptual_target_anchor", 0.18)
    )
    strength = float(
        config.get("perceptual_norm_strength", 0.6)
    )
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma = np.clip(luma, 0.0, 1.0)
    anchor = compute_perceptual_anchor(
        luma=luma,
        percentile=anchor_percentile
    )
    # Temporal smoothing to avoid flicker
    prev_anchor = temporal_state.get("perceptual_prev_anchor", anchor)
    smoothed_anchor = (
        0.7 * prev_anchor + 0.3 * anchor
    )
    processed = normalize_brightness(
        rgb=rgb_image,
        anchor=smoothed_anchor,
        target_anchor=target_anchor,
        strength=strength
    )
    temporal_state["perceptual_prev_anchor"] = smoothed_anchor
    temporal_state["perceptual_target_anchor"] = target_anchor
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 R 05 — PERCEPTUAL BRIGHTNESS NORMALIZATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 R 06 — HUMAN VISUAL ADAPTATION LAG
# ==============================================================================
# Purpose:
#   Model the temporal lag of human visual adaptation to changes in scene
#   luminance and contrast under projected viewing conditions.
#
# Cinematic relevance:
#   - Prevents instantaneous exposure perception
#   - Adds realistic adaptation during scene transitions
#   - Critical for believable dark→bright and bright→dark cuts
#
# Runs AFTER:
#   - 84 R 05 (Perceptual Brightness Normalization)
# ==============================================================================
import numpy as np
def compute_adaptation_target(
    luma: np.ndarray,
    percentile: float
) -> float:
    """
    Computes target adaptation luminance based on scene statistics.
    """
    return float(np.percentile(luma, percentile))
def adaptation_time_constant(
    delta: float,
    dark_to_light_tau: float,
    light_to_dark_tau: float
) -> float:
    """
    Selects adaptation time constant based on direction of luminance change.
    """
    if delta >= 0.0:
        return dark_to_light_tau
    return light_to_dark_tau
def apply_visual_adaptation(
    rgb: np.ndarray,
    adaptation_gain: float,
    strength: float
) -> np.ndarray:
    """
    Applies adaptation gain to image while preserving chroma ratios.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    luma = np.clip(luma, 1e-6, None)
    ratio = adaptation_gain ** strength
    return rgb * ratio
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_human_visual_adaptation_lag(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies human visual adaptation lag to projected image.
    """
    enabled = config.get("enable_visual_adaptation_lag", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    target_percentile = float(
        config.get("adaptation_target_percentile", 60.0)
    )
    dark_to_light_tau = float(
        config.get("adaptation_tau_dark_to_light", 0.35)
    )
    light_to_dark_tau = float(
        config.get("adaptation_tau_light_to_dark", 0.65)
    )
    strength = float(
        config.get("adaptation_strength", 0.9)
    )
    luma = (
        0.2126 * rgb_image[:, :, 0] +
        0.7152 * rgb_image[:, :, 1] +
        0.0722 * rgb_image[:, :, 2]
    )
    luma = np.clip(luma, 0.0, 1.0)
    target = compute_adaptation_target(
        luma=luma,
        percentile=target_percentile
    )
    prev = temporal_state.get("visual_adaptation_level", target)
    delta = target - prev
    tau = adaptation_time_constant(
        delta=delta,
        dark_to_light_tau=dark_to_light_tau,
        light_to_dark_tau=light_to_dark_tau
    )
    # Exponential adaptation step
    adapted = prev + (target - prev) * tau
    gain = adapted / (prev + 1e-6)
    processed = apply_visual_adaptation(
        rgb=rgb_image,
        adaptation_gain=gain,
        strength=strength
    )
    temporal_state["visual_adaptation_level"] = adapted
    temporal_state["visual_adaptation_tau"] = tau
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 R 06 — HUMAN VISUAL ADAPTATION LAG
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 R 07 — TEMPORAL PROJECTION STABILITY
# ==============================================================================
# Purpose:
#   Model microscopic temporal instability present in real cinema projection
#   systems caused by mechanical tolerances, lamp arc wander, optical vibration,
#   and air-path turbulence — WITHOUT visible shake or jitter.
#
# Cinematic relevance:
#   - Breaks digital “perfect lock”
#   - Adds organic temporal life
#   - Prevents static-image fatigue in long shots
#
# Runs AFTER:
#   - 84 R 06 (Human Visual Adaptation Lag)
# ==============================================================================
import numpy as np
def generate_temporal_micro_variation(
    frame_index: int,
    amplitude: float,
    frequency: float
) -> float:
    """
    Generates smooth sub-pixel temporal instability value.
    """
    return amplitude * np.sin(2.0 * np.pi * frequency * frame_index)
def apply_temporal_luminance_wobble(
    rgb: np.ndarray,
    wobble: float,
    strength: float
) -> np.ndarray:
    """
    Applies extremely subtle luminance modulation to simulate projection wobble.
    """
    # Operate in perceptual midtones only
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    weight = np.exp(-((luma - 0.5) ** 2) / 0.12)
    modulation = 1.0 + wobble * strength * weight
    return rgb * modulation[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_temporal_projection_stability(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies sub-visible temporal instability for realistic projection behavior.
    """
    enabled = config.get("enable_temporal_projection_stability", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    frame_index = int(temporal_state.get("frame_index", 0))
    amplitude = float(
        config.get("projection_temporal_amplitude", 0.0025)
    )
    frequency = float(
        config.get("projection_temporal_frequency", 0.18)
    )
    strength = float(
        config.get("projection_temporal_strength", 0.85)
    )
    wobble = generate_temporal_micro_variation(
        frame_index=frame_index,
        amplitude=amplitude,
        frequency=frequency
    )
    processed = apply_temporal_luminance_wobble(
        rgb=rgb_image,
        wobble=wobble,
        strength=strength
    )
    temporal_state["frame_index"] = frame_index + 1
    temporal_state["projection_temporal_wobble"] = wobble
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 R 07 — TEMPORAL PROJECTION STABILITY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 R 08 — AUDIENCE EYE INTEGRATION RESPONSE
# ==============================================================================
# Purpose:
#   Model spatial + temporal integration performed by the human visual system
#   when observing projected imagery, including retinal persistence,
#   spatial pooling, and micro-saccadic smoothing.
#
# Cinematic relevance:
#   - Softens excessive micro-contrast without blur
#   - Adds perceptual continuity during motion
#   - Critical for “film feels smoother than digital” effect
#
# Runs AFTER:
#   - 84 R 07 (Temporal Projection Stability)
# ==============================================================================
import numpy as np
import cv2
def spatial_eye_pooling(
    channel: np.ndarray,
    radius: int,
    sigma: float
) -> np.ndarray:
    """
    Approximates retinal spatial pooling via Gaussian integration.
    """
    k = cv2.getGaussianKernel(ksize=radius * 2 + 1, sigma=sigma)
    kernel = k @ k.T
    return cv2.filter2D(channel, -1, kernel, borderType=cv2.BORDER_REFLECT)
def temporal_eye_integration(
    current: np.ndarray,
    previous: np.ndarray,
    persistence: float
) -> np.ndarray:
    """
    Models retinal persistence / integration over time.
    """
    return previous * persistence + current * (1.0 - persistence)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_audience_eye_integration_response(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies audience eye integration response to projected image.
    """
    enabled = config.get("enable_eye_integration_response", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    spatial_radius = int(
        config.get("eye_spatial_radius", 1)
    )
    spatial_sigma = float(
        config.get("eye_spatial_sigma", 0.6)
    )
    temporal_persistence = float(
        config.get("eye_temporal_persistence", 0.72)
    )
    # Spatial pooling (per-channel)
    spatial = np.empty_like(rgb_image)
    for c in range(3):
        spatial[:, :, c] = spatial_eye_pooling(
            channel=rgb_image[:, :, c],
            radius=spatial_radius,
            sigma=spatial_sigma
        )
    # Temporal integration
    prev = temporal_state.get("eye_integrated_frame", spatial)
    integrated = temporal_eye_integration(
        current=spatial,
        previous=prev,
        persistence=temporal_persistence
    )
    temporal_state["eye_integrated_frame"] = integrated
    temporal_state["eye_spatial_radius"] = spatial_radius
    temporal_state["eye_temporal_persistence"] = temporal_persistence
    return np.clip(integrated, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 R 08 — AUDIENCE EYE INTEGRATION RESPONSE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 R 09 — SCENE-TO-SCENE LUMINANCE MEMORY
# ==============================================================================
# Purpose:
#   Model the human visual system’s short-term luminance memory across scene cuts
#   and major exposure changes, preventing harsh perceptual resets between shots.
#
# Cinematic relevance:
#   - Smooths exposure jumps across cuts
#   - Preserves emotional continuity between scenes
#   - Prevents “digital pop” when brightness shifts suddenly
#
# Runs AFTER:
#   - 84 R 08 (Audience Eye Integration Response)
# ==============================================================================
import numpy as np
def compute_frame_luminance(rgb: np.ndarray) -> float:
    """
    Computes perceptual frame-average luminance.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    return float(np.mean(luma))
def apply_luminance_memory(
    rgb: np.ndarray,
    current_luma: float,
    memory_luma: float,
    strength: float
) -> np.ndarray:
    """
    Blends current frame toward remembered luminance state.
    """
    if memory_luma <= 0.0:
        return rgb
    ratio = memory_luma / max(current_luma, 1e-6)
    ratio = np.clip(ratio, 0.85, 1.15)
    blend = 1.0 + (ratio - 1.0) * strength
    return rgb * blend
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_scene_luminance_memory(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies perceptual luminance memory across scene transitions.
    """
    enabled = config.get("enable_scene_luminance_memory", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    memory_strength = float(
        config.get("scene_luminance_memory_strength", 0.55)
    )
    decay = float(
        config.get("scene_luminance_memory_decay", 0.92)
    )
    current_luma = compute_frame_luminance(rgb_image)
    prev_memory = temporal_state.get(
        "scene_luminance_memory",
        current_luma
    )
    # Apply memory influence
    processed = apply_luminance_memory(
        rgb=rgb_image,
        current_luma=current_luma,
        memory_luma=prev_memory,
        strength=memory_strength
    )
    # Update memory with decay
    updated_memory = (
        prev_memory * decay +
        current_luma * (1.0 - decay)
    )
    temporal_state["scene_luminance_memory"] = updated_memory
    temporal_state["scene_luminance_current"] = current_luma
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 R 09 — SCENE-TO-SCENE LUMINANCE MEMORY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 S 01 — PERCEPTUAL CONTRAST RE-ATTENUATION
# ==============================================================================
# Purpose:
#   Re-balance perceived contrast after luminance memory, eye integration,
#   and projection instability have modified the image, restoring cinematic
#   contrast without reintroducing digital harshness.
#
# Cinematic relevance:
#   - Prevents contrast collapse in long scenes
#   - Avoids artificial HDR “punch”
#   - Matches how human perception adapts contrast dynamically
#
# Runs AFTER:
#   - 84 R 09 (Scene-to-Scene Luminance Memory)
# ==============================================================================
import numpy as np
def perceptual_contrast_curve(
    luma: np.ndarray,
    mid_gray: float,
    strength: float
) -> np.ndarray:
    """
    Soft S-shaped contrast re-attenuation curve centered around mid-gray.
    """
    x = luma - mid_gray
    y = x / (1.0 + strength * np.abs(x))
    return y + mid_gray
def apply_contrast_rebalance(
    rgb: np.ndarray,
    strength: float,
    mid_gray: float
) -> np.ndarray:
    """
    Applies perceptual contrast correction while preserving chroma ratios.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    new_luma = perceptual_contrast_curve(
        luma=luma,
        mid_gray=mid_gray,
        strength=strength
    )
    scale = new_luma / np.maximum(luma, 1e-6)
    return rgb * scale[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_perceptual_contrast_reattenuation(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Re-attenuates contrast to maintain cinematic balance.
    """
    enabled = config.get("enable_perceptual_contrast_reattenuation", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    strength = float(
        config.get("contrast_reattenuation_strength", 1.15)
    )
    mid_gray = float(
        config.get("contrast_mid_gray", 0.42)
    )
    processed = apply_contrast_rebalance(
        rgb=rgb_image,
        strength=strength,
        mid_gray=mid_gray
    )
    temporal_state["contrast_reattenuation_strength"] = strength
    temporal_state["contrast_mid_gray"] = mid_gray
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 S 01 — PERCEPTUAL CONTRAST RE-ATTENUATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 S 02 — LONG-FORM VIEWING FATIGUE COMPENSATION
# ==============================================================================
# Purpose:
#   Compensate for gradual perceptual fatigue that occurs during prolonged
#   viewing of cinematic content, where contrast sensitivity and color
#   responsiveness subtly decline over time.
#
# Cinematic relevance:
#   - Maintains perceived richness over long scenes
#   - Prevents slow “mental dimming” of the image
#   - Critical for feature-length viewing comfort
#
# Runs AFTER:
#   - 84 S 01 (Perceptual Contrast Re-Attenuation)
# ==============================================================================
import numpy as np
def compute_fatigue_factor(
    frame_index: int,
    onset: int,
    rate: float,
    max_strength: float
) -> float:
    """
    Computes accumulated viewing fatigue factor.
    """
    if frame_index < onset:
        return 0.0
    t = frame_index - onset
    fatigue = 1.0 - np.exp(-rate * t)
    return np.clip(fatigue * max_strength, 0.0, max_strength)
def apply_fatigue_compensation(
    rgb: np.ndarray,
    fatigue: float,
    chroma_boost: float,
    contrast_boost: float
) -> np.ndarray:
    """
    Subtly boosts chroma and contrast to counteract perceptual fatigue.
    """
    # Luminance
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    # Chroma separation
    chroma = rgb - luma[:, :, None]
    # Apply fatigue compensation
    chroma *= (1.0 + fatigue * chroma_boost)
    luma = luma * (1.0 + fatigue * contrast_boost)
    return np.clip(luma[:, :, None] + chroma, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_long_form_viewing_fatigue(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies gradual perceptual compensation for long-form viewing fatigue.
    """
    enabled = config.get("enable_long_form_fatigue_compensation", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    frame_index = int(
        temporal_state.get("frame_index", 0)
    )
    onset = int(
        config.get("fatigue_onset_frames", 900)
    )
    rate = float(
        config.get("fatigue_growth_rate", 0.0009)
    )
    max_strength = float(
        config.get("fatigue_max_strength", 0.12)
    )
    chroma_boost = float(
        config.get("fatigue_chroma_boost", 0.25)
    )
    contrast_boost = float(
        config.get("fatigue_contrast_boost", 0.18)
    )
    fatigue = compute_fatigue_factor(
        frame_index=frame_index,
        onset=onset,
        rate=rate,
        max_strength=max_strength
    )
    processed = apply_fatigue_compensation(
        rgb=rgb_image,
        fatigue=fatigue,
        chroma_boost=chroma_boost,
        contrast_boost=contrast_boost
    )
    temporal_state["viewing_fatigue"] = fatigue
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 S 02 — LONG-FORM VIEWING FATIGUE COMPENSATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 S 03 — MICRO-CONTRAST RECOVERY CONTROL
# ==============================================================================
# Purpose:
#   Restore perceptual micro-contrast that may be attenuated by eye integration,
#   fatigue compensation, and projection-domain smoothing — WITHOUT reintroducing
#   digital edge harshness or halo artifacts.
#
# Cinematic relevance:
#   - Preserves tactile texture (faces, fabric, foliage)
#   - Maintains depth separation in midtones
#   - Prevents “velvet blur” look in premium cinema pipelines
#
# Runs AFTER:
#   - 84 S 02 (Long-Form Viewing Fatigue Compensation)
# ==============================================================================
import numpy as np
import cv2
def highpass_micro_detail(
    luma: np.ndarray,
    radius: int,
    sigma: float
) -> np.ndarray:
    """
    Extracts sub-perceptual micro-detail using a controlled high-pass filter.
    """
    blur = cv2.GaussianBlur(
        luma,
        ksize=(radius * 2 + 1, radius * 2 + 1),
        sigmaX=sigma,
        sigmaY=sigma,
        borderType=cv2.BORDER_REFLECT
    )
    return luma - blur
def apply_micro_contrast_recovery(
    rgb: np.ndarray,
    strength: float,
    radius: int,
    sigma: float,
    protect_shadows: bool,
    protect_highlights: bool
) -> np.ndarray:
    """
    Re-injects micro-contrast into luminance while protecting extremes.
    """
    # Compute luminance
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    detail = highpass_micro_detail(
        luma=luma,
        radius=radius,
        sigma=sigma
    )
    # Protection masks
    weight = np.ones_like(luma)
    if protect_shadows:
        weight *= np.clip((luma - 0.05) / 0.25, 0.0, 1.0)
    if protect_highlights:
        weight *= np.clip((1.0 - luma) / 0.25, 0.0, 1.0)
    # Apply controlled detail recovery
    recovered_luma = luma + detail * strength * weight
    # Preserve chroma ratios
    scale = recovered_luma / np.maximum(luma, 1e-6)
    return rgb * scale[:, :, None]
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_micro_contrast_recovery(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies selective micro-contrast recovery for cinematic texture fidelity.
    """
    enabled = config.get("enable_micro_contrast_recovery", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    strength = float(
        config.get("micro_contrast_strength", 0.35)
    )
    radius = int(
        config.get("micro_contrast_radius", 1)
    )
    sigma = float(
        config.get("micro_contrast_sigma", 0.9)
    )
    protect_shadows = bool(
        config.get("micro_contrast_protect_shadows", True)
    )
    protect_highlights = bool(
        config.get("micro_contrast_protect_highlights", True)
    )
    processed = apply_micro_contrast_recovery(
        rgb=rgb_image,
        strength=strength,
        radius=radius,
        sigma=sigma,
        protect_shadows=protect_shadows,
        protect_highlights=protect_highlights
    )
    temporal_state["micro_contrast_strength"] = strength
    return np.clip(processed, 0.0, 1.0), grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 S 03 — MICRO-CONTRAST RECOVERY CONTROL
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 S 04 — TEMPORAL PERCEPTUAL DRIFT CONTROL
# ==============================================================================
# Purpose:
#   Prevent slow, unintended perceptual drift caused by the accumulation of
#   adaptive processes (eye integration, luminance memory, fatigue compensation,
#   micro-contrast recovery) over long timelines.
#
# Cinematic relevance:
#   - Prevents gradual color/contrast “wander”
#   - Maintains director-intended look consistency
#   - Critical for long takes and feature-length films
#
# Runs AFTER:
#   - 84 S 03 (Micro-Contrast Recovery Control)
# ==============================================================================
import numpy as np
def compute_reference_anchor(
    rgb: np.ndarray
) -> tuple[float, float]:
    """
    Computes perceptual anchor values (mean luminance, chroma magnitude).
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    chroma = rgb - luma[:, :, None]
    chroma_mag = float(np.mean(np.linalg.norm(chroma, axis=2)))
    return float(np.mean(luma)), chroma_mag
def apply_anchor_correction(
    rgb: np.ndarray,
    current_anchor: tuple[float, float],
    reference_anchor: tuple[float, float],
    strength: float
) -> np.ndarray:
    """
    Gently pulls image back toward reference perceptual anchor.
    """
    curr_luma, curr_chroma = current_anchor
    ref_luma, ref_chroma = reference_anchor
    luma_ratio = ref_luma / max(curr_luma, 1e-6)
    chroma_ratio = ref_chroma / max(curr_chroma, 1e-6)
    luma_scale = 1.0 + (luma_ratio - 1.0) * strength
    chroma_scale = 1.0 + (chroma_ratio - 1.0) * strength
    # Decompose
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    chroma = rgb - luma[:, :, None]
    corrected_luma = luma * luma_scale
    corrected_chroma = chroma * chroma_scale
    return np.clip(corrected_luma[:, :, None] + corrected_chroma, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_temporal_perceptual_drift_control(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Stabilizes perceptual parameters over time by anchoring to a reference state.
    """
    enabled = config.get("enable_perceptual_drift_control", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    anchor_strength = float(
        config.get("perceptual_anchor_strength", 0.08)
    )
    current_anchor = compute_reference_anchor(rgb_image)
    reference_anchor = temporal_state.get(
        "perceptual_reference_anchor",
        current_anchor
    )
    processed = apply_anchor_correction(
        rgb=rgb_image,
        current_anchor=current_anchor,
        reference_anchor=reference_anchor,
        strength=anchor_strength
    )
    # Slowly update reference anchor (very slow drift allowed)
    blend = 0.995
    temporal_state["perceptual_reference_anchor"] = (
        reference_anchor[0] * blend + current_anchor[0] * (1.0 - blend),
        reference_anchor[1] * blend + current_anchor[1] * (1.0 - blend)
    )
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 S 04 — TEMPORAL PERCEPTUAL DRIFT CONTROL
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 S 05 — PERCEPTUAL NEUTRAL POINT STABILIZATION
# ==============================================================================
# Purpose:
#   Stabilize the perceptual neutral (gray/white balance) point over time by
#   counteracting slow chromatic bias accumulation introduced by adaptive stages.
#
# Cinematic relevance:
#   - Prevents gradual warm/cool drift in long scenes
#   - Maintains consistent skin tones and whites
#   - Mirrors real-world projection calibration anchors
#
# Runs AFTER:
#   - 84 S 04 (Temporal Perceptual Drift Control)
# ==============================================================================
import numpy as np
def estimate_neutral_bias(rgb: np.ndarray) -> np.ndarray:
    """
    Estimates chromatic bias by comparing channel means in near-neutral regions.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    # Select near-neutral luminance window
    mask = (luma > 0.25) & (luma < 0.75)
    if not np.any(mask):
        return np.zeros(3, dtype=np.float32)
    mean_rgb = np.mean(rgb[mask], axis=0)
    neutral = np.mean(mean_rgb)
    return mean_rgb - neutral
def apply_neutral_correction(
    rgb: np.ndarray,
    bias: np.ndarray,
    strength: float
) -> np.ndarray:
    """
    Applies gentle chromatic correction toward perceptual neutrality.
    """
    correction = bias * strength
    corrected = rgb - correction[None, None, :]
    return np.clip(corrected, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_perceptual_neutral_stabilization(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Stabilizes perceptual neutral point over time.
    """
    enabled = config.get("enable_neutral_point_stabilization", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    strength = float(
        config.get("neutral_stabilization_strength", 0.12)
    )
    current_bias = estimate_neutral_bias(rgb_image)
    reference_bias = temporal_state.get(
        "neutral_reference_bias",
        current_bias
    )
    # Blend current bias into reference slowly
    blend = 0.98
    stabilized_bias = (
        reference_bias * blend +
        current_bias * (1.0 - blend)
    )
    processed = apply_neutral_correction(
        rgb=rgb_image,
        bias=stabilized_bias,
        strength=strength
    )
    temporal_state["neutral_reference_bias"] = stabilized_bias
    temporal_state["neutral_stabilization_strength"] = strength
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 S 05 — PERCEPTUAL NEUTRAL POINT STABILIZATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 T 01 — CINEMATIC SCENE ENERGY NORMALIZATION
# ==============================================================================
# Purpose:
#   Normalize perceived scene "energy" (combined luminance, contrast, chroma,
#   and micro-activity) so that consecutive scenes feel intentionally paced,
#   not accidentally louder or flatter than intended.
#
# Cinematic relevance:
#   - Maintains consistent emotional loudness
#   - Prevents accidental intensity spikes
#   - Enables director-controlled pacing across cuts
#
# Runs AFTER:
#   - 84 S 05 (Perceptual Neutral Point Stabilization)
# ==============================================================================
import numpy as np
def compute_scene_energy(
    rgb: np.ndarray
) -> float:
    """
    Computes a scalar representing overall perceptual scene energy.
    """
    # Luminance
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    # Contrast (standard deviation)
    contrast = float(np.std(luma))
    # Chroma magnitude
    chroma = rgb - luma[:, :, None]
    chroma_energy = float(np.mean(np.linalg.norm(chroma, axis=2)))
    # Combined weighted energy
    return (
        0.55 * float(np.mean(luma)) +
        0.30 * contrast +
        0.15 * chroma_energy
    )
def apply_energy_normalization(
    rgb: np.ndarray,
    current_energy: float,
    target_energy: float,
    strength: float
) -> np.ndarray:
    """
    Gently scales scene energy toward a target level.
    """
    if current_energy <= 0.0:
        return rgb
    ratio = target_energy / current_energy
    ratio = 1.0 + (ratio - 1.0) * strength
    # Decompose
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    chroma = rgb - luma[:, :, None]
    # Apply scaling mostly to luma, lightly to chroma
    luma *= ratio
    chroma *= (1.0 + (ratio - 1.0) * 0.5)
    return np.clip(luma[:, :, None] + chroma, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_cinematic_scene_energy_normalization(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Normalizes scene energy to maintain cinematic pacing.
    """
    enabled = config.get("enable_scene_energy_normalization", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    strength = float(
        config.get("scene_energy_normalization_strength", 0.65)
    )
    current_energy = compute_scene_energy(rgb_image)
    reference_energy = temporal_state.get(
        "reference_scene_energy",
        current_energy
    )
    processed = apply_energy_normalization(
        rgb=rgb_image,
        current_energy=current_energy,
        target_energy=reference_energy,
        strength=strength
    )
    # Slowly update reference energy (scene-aware, not frame-noisy)
    blend = 0.97
    temporal_state["reference_scene_energy"] = (
        reference_energy * blend +
        current_energy * (1.0 - blend)
    )
    temporal_state["current_scene_energy"] = current_energy
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 T 01 — CINEMATIC SCENE ENERGY NORMALIZATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 T 02 — SCENE EMOTIONAL INTENSITY BALANCING
# ==============================================================================
# Purpose:
#   Balance perceived emotional intensity of a scene by regulating the combined
#   impact of luminance contrast, color saturation, motion energy, and micro-detail.
#
# Cinematic relevance:
#   - Prevents emotionally “overcooked” shots
#   - Preserves subtlety in quiet scenes
#   - Allows intensity to rise only when narratively justified
#
# Runs AFTER:
#   - 84 T 01 (Cinematic Scene Energy Normalization)
# ==============================================================================
import numpy as np
def compute_emotional_intensity(
    rgb: np.ndarray
) -> float:
    """
    Estimates perceptual emotional intensity of a frame.
    """
    # Luminance contrast
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    contrast = float(np.std(luma))
    # Saturation energy
    chroma = rgb - luma[:, :, None]
    saturation = float(np.mean(np.linalg.norm(chroma, axis=2)))
    # Highlight presence (emotional “spark”)
    highlights = float(np.mean(np.clip(luma - 0.7, 0.0, 1.0)))
    return (
        0.45 * contrast +
        0.40 * saturation +
        0.15 * highlights
    )
def apply_emotional_balance(
    rgb: np.ndarray,
    current_intensity: float,
    target_intensity: float,
    strength: float
) -> np.ndarray:
    """
    Adjusts scene intensity toward a target emotional level.
    """
    if current_intensity <= 0.0:
        return rgb
    ratio = target_intensity / current_intensity
    ratio = 1.0 + (ratio - 1.0) * strength
    # Decompose
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    chroma = rgb - luma[:, :, None]
    # Apply emotional shaping:
    # contrast scales less than saturation to avoid harshness
    luma = luma * (1.0 + (ratio - 1.0) * 0.6)
    chroma = chroma * (1.0 + (ratio - 1.0) * 0.85)
    return np.clip(luma[:, :, None] + chroma, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_scene_emotional_intensity_balancing(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Balances scene emotional intensity for cinematic pacing.
    """
    enabled = config.get("enable_scene_emotional_intensity_balancing", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    strength = float(
        config.get("emotional_intensity_balance_strength", 0.55)
    )
    current_intensity = compute_emotional_intensity(rgb_image)
    reference_intensity = temporal_state.get(
        "reference_emotional_intensity",
        current_intensity
    )
    processed = apply_emotional_balance(
        rgb=rgb_image,
        current_intensity=current_intensity,
        target_intensity=reference_intensity,
        strength=strength
    )
    # Slowly adapt reference to narrative context
    blend = 0.965
    temporal_state["reference_emotional_intensity"] = (
        reference_intensity * blend +
        current_intensity * (1.0 - blend)
    )
    temporal_state["current_emotional_intensity"] = current_intensity
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 T 02 — SCENE EMOTIONAL INTENSITY BALANCING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 T 03 — NARRATIVE CONTRAST PACING CONTROL
# ==============================================================================
# Purpose:
#   Control how contrast rises and falls across narrative time, ensuring
#   that visual contrast follows story rhythm rather than random scene variance.
#
# Cinematic relevance:
#   - Prevents visual exhaustion in high-intensity sequences
#   - Allows contrast to "breathe" with story beats
#   - Mirrors professional DI pacing used in feature films
#
# Runs AFTER:
#   - 84 T 02 (Scene Emotional Intensity Balancing)
# ==============================================================================
import numpy as np
def compute_scene_contrast(rgb: np.ndarray) -> float:
    """
    Computes perceptual scene contrast using luminance dispersion.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    return float(np.std(luma))
def apply_contrast_pacing(
    rgb: np.ndarray,
    current_contrast: float,
    target_contrast: float,
    strength: float
) -> np.ndarray:
    """
    Gently steers scene contrast toward narrative target.
    """
    if current_contrast <= 1e-6:
        return rgb
    ratio = target_contrast / current_contrast
    ratio = 1.0 + (ratio - 1.0) * strength
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    chroma = rgb - luma[:, :, None]
    # Contrast pacing acts primarily on luminance
    luma = np.mean(luma) + (luma - np.mean(luma)) * ratio
    return np.clip(luma[:, :, None] + chroma, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_narrative_contrast_pacing(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies narrative-aware contrast pacing across scenes.
    """
    enabled = config.get("enable_narrative_contrast_pacing", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    strength = float(
        config.get("narrative_contrast_pacing_strength", 0.45)
    )
    current_contrast = compute_scene_contrast(rgb_image)
    reference_contrast = temporal_state.get(
        "reference_narrative_contrast",
        current_contrast
    )
    processed = apply_contrast_pacing(
        rgb=rgb_image,
        current_contrast=current_contrast,
        target_contrast=reference_contrast,
        strength=strength
    )
    # Narrative pacing evolves slowly, scene-by-scene
    blend = 0.96
    temporal_state["reference_narrative_contrast"] = (
        reference_contrast * blend +
        current_contrast * (1.0 - blend)
    )
    temporal_state["current_scene_contrast"] = current_contrast
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 T 03 — NARRATIVE CONTRAST PACING CONTROL
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 T 04 — CROSS-SCENE EMOTIONAL CONTINUITY
# ==============================================================================
# Purpose:
#   Preserve emotional continuity across scene boundaries by softly bridging
#   emotional intensity, chroma presence, and contrast between consecutive scenes.
#
# Cinematic relevance:
#   - Prevents emotional whiplash on hard cuts
#   - Maintains audience immersion
#   - Mirrors professional editorial color continuity workflows
#
# Runs AFTER:
#   - 84 T 03 (Narrative Contrast Pacing Control)
# ==============================================================================
import numpy as np
def extract_emotional_signature(rgb: np.ndarray) -> np.ndarray:
    """
    Extracts a compact emotional signature: [mean luma, contrast, chroma energy].
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    contrast = float(np.std(luma))
    chroma = rgb - luma[:, :, None]
    chroma_energy = float(np.mean(np.linalg.norm(chroma, axis=2)))
    return np.array(
        [float(np.mean(luma)), contrast, chroma_energy],
        dtype=np.float32
    )
def apply_emotional_continuity(
    rgb: np.ndarray,
    current_sig: np.ndarray,
    reference_sig: np.ndarray,
    strength: float
) -> np.ndarray:
    """
    Applies soft emotional bridging toward reference signature.
    """
    delta = reference_sig - current_sig
    adjustment = delta * strength
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    chroma = rgb - luma[:, :, None]
    # Apply continuity shaping
    luma = luma + adjustment[0]
    chroma = chroma * (1.0 + adjustment[2])
    # Contrast shaping via deviation scaling
    luma_mean = np.mean(luma)
    luma = luma_mean + (luma - luma_mean) * (1.0 + adjustment[1])
    return np.clip(luma[:, :, None] + chroma, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_cross_scene_emotional_continuity(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Ensures emotional continuity across scene transitions.
    """
    enabled = config.get("enable_cross_scene_emotional_continuity", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    strength = float(
        config.get("cross_scene_continuity_strength", 0.35)
    )
    current_sig = extract_emotional_signature(rgb_image)
    reference_sig = temporal_state.get(
        "reference_emotional_signature",
        current_sig
    )
    processed = apply_emotional_continuity(
        rgb=rgb_image,
        current_sig=current_sig,
        reference_sig=reference_sig,
        strength=strength
    )
    # Update reference slowly (scene-level, not frame-level)
    blend = 0.97
    temporal_state["reference_emotional_signature"] = (
        reference_sig * blend + current_sig * (1.0 - blend)
    )
    temporal_state["current_emotional_signature"] = current_sig
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 T 04 — CROSS-SCENE EMOTIONAL CONTINUITY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 T 05 — GLOBAL NARRATIVE LUMINANCE ARC
# ==============================================================================
# Purpose:
#   Establish and maintain a long-range luminance trajectory across the film,
#   shaping perceived narrative progression (rise, plateau, resolution).
#
# Cinematic relevance:
#   - Prevents random brightness drift across scenes
#   - Enables deliberate “act-based” luminance storytelling
#   - Mirrors feature-film DI luminance arcs (e.g., darker Act I, lifted Act III)
#
# Runs AFTER:
#   - 84 T 04 (Cross-Scene Emotional Continuity)
# ==============================================================================
import numpy as np
def compute_scene_luminance(rgb: np.ndarray) -> float:
    """
    Computes mean scene luminance in linear space.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    return float(np.mean(luma))
def narrative_luminance_target(
    scene_index: int,
    total_scenes: int,
    arc_shape: str
) -> float:
    """
    Generates target luminance for a scene based on narrative arc shape.
    """
    t = np.clip(scene_index / max(total_scenes - 1, 1), 0.0, 1.0)
    if arc_shape == "rise":
        return 0.45 + 0.20 * t
    if arc_shape == "fall":
        return 0.65 - 0.20 * t
    if arc_shape == "valley":
        return 0.55 - 0.15 * np.sin(np.pi * t)
    if arc_shape == "hill":
        return 0.45 + 0.15 * np.sin(np.pi * t)
    # Neutral fallback
    return 0.50
def apply_luminance_arc(
    rgb: np.ndarray,
    current_luma: float,
    target_luma: float,
    strength: float
) -> np.ndarray:
    """
    Steers scene luminance toward narrative target without flattening contrast.
    """
    if current_luma <= 1e-6:
        return rgb
    delta = target_luma - current_luma
    gain = 1.0 + delta * strength
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    chroma = rgb - luma[:, :, None]
    # Lift or lower luminance while preserving local contrast
    luma = np.mean(luma) + (luma - np.mean(luma)) * gain
    return np.clip(luma[:, :, None] + chroma, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_global_narrative_luminance_arc(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies long-range luminance shaping across narrative timeline.
    """
    enabled = config.get("enable_global_luminance_arc", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    arc_shape = config.get("narrative_luminance_arc_shape", "hill")
    strength = float(config.get("narrative_luminance_arc_strength", 0.40))
    scene_index = int(temporal_state.get("scene_index", 0))
    total_scenes = int(temporal_state.get("total_scenes", 1))
    current_luma = compute_scene_luminance(rgb_image)
    target_luma = narrative_luminance_target(
        scene_index=scene_index,
        total_scenes=total_scenes,
        arc_shape=arc_shape
    )
    processed = apply_luminance_arc(
        rgb=rgb_image,
        current_luma=current_luma,
        target_luma=target_luma,
        strength=strength
    )
    temporal_state["current_scene_luminance"] = current_luma
    temporal_state["target_scene_luminance"] = target_luma
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 T 05 — GLOBAL NARRATIVE LUMINANCE ARC
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 U 01 — DIRECTOR INTENT WEIGHTING MATRIX
# ==============================================================================
# Purpose:
#   Resolve competing cinematic intents (mood, subject, motion, exposure,
#   color bias) into a single coherent control signal per scene.
#
# Cinematic relevance:
#   - Prevents conflicting AI decisions
#   - Mirrors how human directors prioritize intent hierarchies
#   - Foundation for intent-driven look modulation
#
# Runs AFTER:
#   - 84 T 05 (Global Narrative Luminance Arc)
# ==============================================================================
import numpy as np
def build_intent_weight_matrix(intent_state: dict) -> np.ndarray:
    """
    Builds a normalized intent weighting vector from current intent state.
    Order: [emotion, subject, motion, exposure, color]
    """
    weights = np.array([
        float(intent_state.get("emotion", 0.5)),
        float(intent_state.get("subject", 0.5)),
        float(intent_state.get("motion", 0.5)),
        float(intent_state.get("exposure", 0.5)),
        float(intent_state.get("color", 0.5)),
    ], dtype=np.float32)
    total = np.sum(weights)
    if total <= 1e-6:
        return np.ones_like(weights) / len(weights)
    return weights / total
def apply_intent_weighting(
    rgb: np.ndarray,
    weights: np.ndarray
) -> np.ndarray:
    """
    Applies high-level intent weighting to RGB image.
    """
    emotion_w, subject_w, motion_w, exposure_w, color_w = weights
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    chroma = rgb - luma[:, :, None]
    # Emotion primarily affects contrast
    luma = np.mean(luma) + (luma - np.mean(luma)) * (1.0 + 0.6 * emotion_w)
    # Exposure intent affects global gain
    luma *= (1.0 + 0.4 * (exposure_w - 0.5))
    # Color intent affects chroma energy
    chroma *= (1.0 + 0.7 * (color_w - 0.5))
    return np.clip(luma[:, :, None] + chroma, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_director_intent_weighting(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Resolves multi-axis cinematic intent into a unified control influence.
    """
    enabled = config.get("enable_director_intent_weighting", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    intent_state = temporal_state.get("intent_state", {})
    weights = build_intent_weight_matrix(intent_state)
    processed = apply_intent_weighting(
        rgb=rgb_image,
        weights=weights
    )
    temporal_state["resolved_intent_weights"] = weights
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 U 01 — DIRECTOR INTENT WEIGHTING MATRIX
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 U 02 — SHOT-TYPE EMOTIONAL BIAS PROFILES
# ==============================================================================
# Purpose:
#   Encode how different shot types bias emotional perception and therefore
#   modulate contrast, chroma density, motion tolerance, and exposure preference.
#
# Cinematic relevance:
#   - Close-ups favor softer contrast and richer skin chroma
#   - Wide shots tolerate higher contrast and cooler palettes
#   - Moving shots bias toward exposure stability over peak contrast
#
# Runs AFTER:
#   - 84 U 01 (Director Intent Weighting Matrix)
# ==============================================================================
import numpy as np
# ------------------------------------------------------------------------------
# Shot-Type Bias Definitions
# ------------------------------------------------------------------------------
SHOT_TYPE_PROFILES = {
    "close_up": {
        "contrast_bias": -0.20,
        "chroma_bias": +0.25,
        "exposure_bias": +0.05,
        "motion_tolerance": -0.15,
    },
    "medium": {
        "contrast_bias": 0.00,
        "chroma_bias": +0.10,
        "exposure_bias": 0.00,
        "motion_tolerance": 0.00,
    },
    "wide": {
        "contrast_bias": +0.25,
        "chroma_bias": -0.05,
        "exposure_bias": -0.05,
        "motion_tolerance": +0.20,
    },
    "aerial": {
        "contrast_bias": +0.30,
        "chroma_bias": -0.10,
        "exposure_bias": -0.08,
        "motion_tolerance": +0.30,
    },
    "tracking": {
        "contrast_bias": -0.05,
        "chroma_bias": +0.05,
        "exposure_bias": +0.10,
        "motion_tolerance": +0.35,
    },
}
def resolve_shot_profile(shot_type: str) -> dict:
    """
    Returns the emotional bias profile for a given shot type.
    """
    return SHOT_TYPE_PROFILES.get(
        shot_type,
        SHOT_TYPE_PROFILES["medium"]
    )
# ------------------------------------------------------------------------------
# Bias Application
# ------------------------------------------------------------------------------
def apply_shot_type_bias(
    rgb: np.ndarray,
    profile: dict,
    strength: float
) -> np.ndarray:
    """
    Applies shot-type emotional bias to RGB image.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    chroma = rgb - luma[:, :, None]
    # Contrast bias
    c_bias = profile["contrast_bias"] * strength
    luma_mean = np.mean(luma)
    luma = luma_mean + (luma - luma_mean) * (1.0 + c_bias)
    # Exposure bias (global gain)
    e_bias = profile["exposure_bias"] * strength
    luma *= (1.0 + e_bias)
    # Chroma bias
    ch_bias = profile["chroma_bias"] * strength
    chroma *= (1.0 + ch_bias)
    return np.clip(luma[:, :, None] + chroma, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_shot_type_emotional_bias(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies shot-type-specific emotional biasing.
    """
    enabled = config.get("enable_shot_type_bias", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    shot_type = temporal_state.get("shot_type", "medium")
    strength = float(config.get("shot_type_bias_strength", 0.60))
    profile = resolve_shot_profile(shot_type)
    processed = apply_shot_type_bias(
        rgb=rgb_image,
        profile=profile,
        strength=strength
    )
    temporal_state["active_shot_profile"] = profile
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 U 02 — SHOT-TYPE EMOTIONAL BIAS PROFILES
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 U 03 — INTENT-DRIVEN LOOK MODULATION
# ==============================================================================
# Purpose:
#   Translate resolved director intent into concrete visual modulation,
#   shaping contrast, chroma density, exposure bias, and local emphasis
#   in a coordinated, cinematic manner.
#
# Cinematic relevance:
#   - Converts abstract intent into visible look decisions
#   - Prevents disjointed grading behaviors
#   - Mimics how human directors steer colorists during DI
#
# Runs AFTER:
#   - 84 U 02 (Shot-Type Emotional Bias Profiles)
# ==============================================================================
import numpy as np
def compute_intent_modulators(weights: np.ndarray) -> dict:
    """
    Derives visual modulation coefficients from intent weights.
    """
    emotion_w, subject_w, motion_w, exposure_w, color_w = weights
    return {
        "contrast_gain": 1.0 + 0.7 * emotion_w,
        "local_focus":  0.4 + 0.6 * subject_w,
        "motion_soft":  0.3 + 0.7 * motion_w,
        "exposure_gain":1.0 + 0.5 * (exposure_w - 0.5),
        "chroma_gain":  1.0 + 0.8 * (color_w - 0.5),
    }
def apply_intent_look(
    rgb: np.ndarray,
    modulators: dict,
    strength: float
) -> np.ndarray:
    """
    Applies intent-driven modulation to RGB image.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    chroma = rgb - luma[:, :, None]
    # Contrast shaping (emotion-driven)
    luma_mean = np.mean(luma)
    luma = luma_mean + (luma - luma_mean) * (
        1.0 + (modulators["contrast_gain"] - 1.0) * strength
    )
    # Exposure shaping (global)
    luma *= (
        1.0 + (modulators["exposure_gain"] - 1.0) * strength
    )
    # Chroma shaping (color intent)
    chroma *= (
        1.0 + (modulators["chroma_gain"] - 1.0) * strength
    )
    # Subject emphasis (local contrast boost proxy)
    focus = modulators["local_focus"] * strength
    luma = luma_mean + (luma - luma_mean) * (1.0 + focus * 0.25)
    return np.clip(luma[:, :, None] + chroma, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_intent_driven_look_modulation(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies director-intent-driven look modulation.
    """
    enabled = config.get("enable_intent_look_modulation", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    strength = float(config.get("intent_look_strength", 0.65))
    weights = temporal_state.get(
        "resolved_intent_weights",
        np.ones(5, dtype=np.float32) / 5.0
    )
    modulators = compute_intent_modulators(weights)
    processed = apply_intent_look(
        rgb=rgb_image,
        modulators=modulators,
        strength=strength
    )
    temporal_state["active_intent_modulators"] = modulators
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 U 03 — INTENT-DRIVEN LOOK MODULATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 U 04 — NARRATIVE EMPHASIS CURVES
# ==============================================================================
# Purpose:
#   Shape how visual emphasis evolves over time within a scene, allowing
#   narrative beats to subtly guide viewer attention via contrast and luminance
#   emphasis rather than explicit cuts.
#
# Cinematic relevance:
#   - Drives emotional focus without camera movement
#   - Mimics professional power-window automation in DI
#   - Enables emphasis peaks at story-critical moments
#
# Runs AFTER:
#   - 84 U 03 (Intent-Driven Look Modulation)
# ==============================================================================
import numpy as np
# ------------------------------------------------------------------------------
# Emphasis Curve Models
# ------------------------------------------------------------------------------
def emphasis_curve(t: float, mode: str) -> float:
    """
    Generates an emphasis scalar based on normalized narrative time t ∈ [0,1].
    """
    t = np.clip(t, 0.0, 1.0)
    if mode == "rise":
        return t
    if mode == "fall":
        return 1.0 - t
    if mode == "peak":
        return np.sin(np.pi * t)
    if mode == "double_peak":
        return np.sin(np.pi * t) ** 2
    # Neutral
    return 1.0
def apply_emphasis(
    rgb: np.ndarray,
    emphasis: float,
    strength: float
) -> np.ndarray:
    """
    Applies emphasis by selectively boosting local contrast and luminance.
    """
    luma = (
        0.2126 * rgb[:, :, 0] +
        0.7152 * rgb[:, :, 1] +
        0.0722 * rgb[:, :, 2]
    )
    chroma = rgb - luma[:, :, None]
    luma_mean = np.mean(luma)
    gain = 1.0 + emphasis * strength * 0.35
    luma = luma_mean + (luma - luma_mean) * gain
    return np.clip(luma[:, :, None] + chroma, 0.0, 1.0)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_narrative_emphasis_curves(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies narrative emphasis shaping within scenes.
    """
    enabled = config.get("enable_narrative_emphasis", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    curve_mode = config.get("narrative_emphasis_curve", "peak")
    strength = float(config.get("narrative_emphasis_strength", 0.50))
    frame_index = int(temporal_state.get("frame_index", 0))
    frames_in_scene = int(temporal_state.get("frames_in_scene", 1))
    t = frame_index / max(frames_in_scene - 1, 1)
    emphasis = emphasis_curve(t, curve_mode)
    processed = apply_emphasis(
        rgb=rgb_image,
        emphasis=emphasis,
        strength=strength
    )
    temporal_state["current_emphasis"] = emphasis
    return processed, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 U 04 — NARRATIVE EMPHASIS CURVES
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 U 05 — INTENT PERSISTENCE & DECAY
# ==============================================================================
# Purpose:
#   Stabilize director intent over time by introducing controlled persistence
#   and decay, preventing rapid oscillations while still allowing adaptation
#   to new narrative or visual conditions.
#
# Cinematic relevance:
#   - Prevents AI "decision flicker"
#   - Mirrors how human directors maintain intent across shots
#   - Allows slow emotional evolution rather than abrupt shifts
#
# Runs AFTER:
#   - 84 U 04 (Narrative Emphasis Curves)
# ==============================================================================
import numpy as np
def decay_intent(
    previous: np.ndarray,
    current: np.ndarray,
    persistence: float
) -> np.ndarray:
    """
    Applies exponential decay to intent vectors.
    """
    persistence = np.clip(persistence, 0.0, 1.0)
    return previous * persistence + current * (1.0 - persistence)
def normalize_intent(intent: np.ndarray) -> np.ndarray:
    """
    Ensures intent vector remains normalized.
    """
    total = np.sum(intent)
    if total <= 1e-6:
        return np.ones_like(intent) / len(intent)
    return intent / total
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_intent_persistence_and_decay(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies temporal persistence and decay to director intent.
    """
    enabled = config.get("enable_intent_persistence", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    persistence = float(
        config.get("intent_persistence_factor", 0.92)
    )
    current_intent = np.array(
        temporal_state.get(
            "resolved_intent_weights",
            np.ones(5, dtype=np.float32) / 5.0
        ),
        dtype=np.float32
    )
    previous_intent = np.array(
        temporal_state.get(
            "persistent_intent",
            current_intent
        ),
        dtype=np.float32
    )
    decayed = decay_intent(
        previous=previous_intent,
        current=current_intent,
        persistence=persistence
    )
    decayed = normalize_intent(decayed)
    temporal_state["persistent_intent"] = decayed
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 U 05 — INTENT PERSISTENCE & DECAY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 V 01 — AUTONOMOUS SHOT GRAMMAR ENGINE
# ==============================================================================
# Purpose:
#   Formalize cinematic shot grammar into a deterministic-yet-expressive engine
#   that selects shot types based on intent, motion, subject dynamics, and
#   narrative phase.
#
# Cinematic relevance:
#   - Replaces hard-coded shot rules with film-language grammar
#   - Enables director-like shot reasoning (when to go wide, close, track)
#   - Foundation for autonomous, non-random cinematography
#
# Runs AFTER:
#   - 84 U 05 (Intent Persistence & Decay)
# ==============================================================================
import numpy as np
# ------------------------------------------------------------------------------
# Shot Grammar Definitions
# ------------------------------------------------------------------------------
SHOT_GRAMMAR_RULES = {
    "establishing": {
        "preferred_intent": ["emotion", "environment"],
        "min_motion": 0.2,
        "max_motion": 0.8,
        "duration_bias": +0.4,
    },
    "close_up": {
        "preferred_intent": ["emotion", "subject"],
        "min_motion": 0.0,
        "max_motion": 0.4,
        "duration_bias": -0.2,
    },
    "tracking": {
        "preferred_intent": ["motion", "subject"],
        "min_motion": 0.3,
        "max_motion": 1.0,
        "duration_bias": 0.0,
    },
    "aerial_wide": {
        "preferred_intent": ["environment", "motion"],
        "min_motion": 0.4,
        "max_motion": 1.0,
        "duration_bias": +0.3,
    },
    "detail": {
        "preferred_intent": ["subject"],
        "min_motion": 0.0,
        "max_motion": 0.3,
        "duration_bias": -0.3,
    },
}
INTENT_INDEX = {
    "emotion": 0,
    "subject": 1,
    "motion": 2,
    "exposure": 3,
    "color": 4,
    "environment": 0,  # environment folds into emotion weighting
}
# ------------------------------------------------------------------------------
# Grammar Resolution Logic
# ------------------------------------------------------------------------------
def score_shot_type(
    shot_name: str,
    intent_vector: np.ndarray,
    motion_level: float
) -> float:
    """
    Scores a shot type based on intent alignment and motion constraints.
    """
    rule = SHOT_GRAMMAR_RULES[shot_name]
    # Intent alignment score
    intent_score = 0.0
    for key in rule["preferred_intent"]:
        idx = INTENT_INDEX.get(key)
        if idx is not None and idx < len(intent_vector):
            intent_score += intent_vector[idx]
    intent_score /= max(len(rule["preferred_intent"]), 1)
    # Motion compatibility score
    if motion_level < rule["min_motion"]:
        motion_score = 0.0
    elif motion_level > rule["max_motion"]:
        motion_score = 0.0
    else:
        motion_score = 1.0
    return intent_score * motion_score
def select_shot_type(
    intent_vector: np.ndarray,
    motion_level: float
) -> str:
    """
    Selects the most appropriate shot type based on grammar scoring.
    """
    best_score = -1.0
    best_shot = "medium"
    for shot_name in SHOT_GRAMMAR_RULES.keys():
        score = score_shot_type(
            shot_name=shot_name,
            intent_vector=intent_vector,
            motion_level=motion_level
        )
        if score > best_score:
            best_score = score
            best_shot = shot_name
    return best_shot
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_autonomous_shot_grammar(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Resolves cinematic shot type autonomously using film grammar.
    """
    enabled = config.get("enable_autonomous_shot_grammar", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    intent_vector = temporal_state.get(
        "persistent_intent",
        np.ones(5, dtype=np.float32) / 5.0
    )
    motion_level = float(
        temporal_state.get("scene_motion_level", 0.0)
    )
    shot_type = select_shot_type(
        intent_vector=intent_vector,
        motion_level=motion_level
    )
    temporal_state["shot_type"] = shot_type
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 V 01 — AUTONOMOUS SHOT GRAMMAR ENGINE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 V 02 — SHOT TRANSITION LOGIC
# ==============================================================================
# Purpose:
#   Determine WHEN and HOW the system transitions between shot types,
#   preventing abrupt cuts while enabling motivated, cinematic transitions.
#
# Cinematic relevance:
#   - Avoids rapid AI-driven shot flipping
#   - Ensures transitions feel intentional, not reactive
#   - Mirrors editorial decision-making in professional cinema
#
# Runs AFTER:
#   - 84 V 01 (Autonomous Shot Grammar Engine)
# ==============================================================================
import numpy as np
# ------------------------------------------------------------------------------
# Transition Constraints
# ------------------------------------------------------------------------------
SHOT_TRANSITION_MATRIX = {
    ("establishing", "close_up"): 0.6,
    ("close_up", "tracking"): 0.7,
    ("tracking", "aerial_wide"): 0.8,
    ("aerial_wide", "close_up"): 0.9,
    ("detail", "close_up"): 0.4,
}
def transition_cost(prev_shot: str, next_shot: str) -> float:
    """
    Returns transition resistance between shot types.
    Lower = easier transition.
    """
    if prev_shot == next_shot:
        return 0.0
    return SHOT_TRANSITION_MATRIX.get(
        (prev_shot, next_shot),
        0.75  # default conservative resistance
    )
def should_transition(
    prev_shot: str,
    next_shot: str,
    scene_energy: float,
    persistence: float
) -> bool:
    """
    Determines whether a shot transition should occur.
    """
    cost = transition_cost(prev_shot, next_shot)
    # High energy scenes tolerate faster transitions
    threshold = cost * (1.0 - 0.5 * scene_energy)
    # Persistence resists change
    threshold += persistence * 0.25
    return scene_energy > threshold
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_shot_transition_logic(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies cinematic shot transition logic.
    """
    enabled = config.get("enable_shot_transition_logic", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    prev_shot = temporal_state.get("previous_shot_type", "medium")
    next_shot = temporal_state.get("shot_type", prev_shot)
    scene_energy = float(
        temporal_state.get("scene_energy", 0.5)
    )
    persistence = float(
        config.get("shot_transition_persistence", 0.6)
    )
    if should_transition(
        prev_shot=prev_shot,
        next_shot=next_shot,
        scene_energy=scene_energy,
        persistence=persistence
    ):
        temporal_state["active_shot_type"] = next_shot
    else:
        temporal_state["active_shot_type"] = prev_shot
    temporal_state["previous_shot_type"] = temporal_state["active_shot_type"]
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 V 02 — SHOT TRANSITION LOGIC
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 V 03 — TEMPORAL SHOT COHERENCE
# ==============================================================================
# Purpose:
#   Maintain temporal coherence of shot selection across frames and beats,
#   preventing oscillation while allowing motivated evolution of shot language.
#
# Cinematic relevance:
#   - Prevents AI "shot flicker"
#   - Preserves audience spatial understanding
#   - Mirrors assistant editor continuity enforcement
#
# Runs AFTER:
#   - 84 V 02 (Shot Transition Logic)
# ==============================================================================
import numpy as np
def update_shot_coherence(
    previous_shot: str,
    candidate_shot: str,
    coherence_factor: float
) -> str:
    """
    Dampens rapid oscillation between shot types.
    """
    if previous_shot == candidate_shot:
        return previous_shot
    # High coherence favors stability
    if np.random.rand() < coherence_factor:
        return previous_shot
    return candidate_shot
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_temporal_shot_coherence(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies temporal coherence constraints to shot selection.
    """
    enabled = config.get("enable_temporal_shot_coherence", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    coherence_factor = float(
        config.get("shot_coherence_factor", 0.85)
    )
    previous = temporal_state.get(
        "coherent_shot_type",
        temporal_state.get("active_shot_type", "medium")
    )
    candidate = temporal_state.get(
        "active_shot_type",
        previous
    )
    coherent = update_shot_coherence(
        previous_shot=previous,
        candidate_shot=candidate,
        coherence_factor=coherence_factor
    )
    temporal_state["coherent_shot_type"] = coherent
    temporal_state["active_shot_type"] = coherent
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 V 03 — TEMPORAL SHOT COHERENCE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 V 04 — CINEMATIC MOTION PRIORITY RESOLVER
# ==============================================================================
# Purpose:
#   Resolve conflicts between competing motion intents (subject tracking,
#   camera drift, orbit, push/pull) using cinematic priority rules.
#
# Cinematic relevance:
#   - Prevents chaotic motion decisions
#   - Preserves dominant visual intent
#   - Mimics real-world director vs operator arbitration
#
# Runs AFTER:
#   - 84 V 03 (Temporal Shot Coherence)
# ==============================================================================
import numpy as np
MOTION_PRIORITY_TABLE = {
    "subject_lock": 1.0,
    "tracking": 0.9,
    "orbit": 0.8,
    "push_pull": 0.7,
    "pan": 0.6,
    "idle_drift": 0.3,
}
def resolve_motion_priority(
    motion_votes: dict
) -> str:
    """
    Selects the dominant motion intent based on weighted priority.
    """
    if not motion_votes:
        return "idle_drift"
    best_motion = None
    best_score = -np.inf
    for motion, confidence in motion_votes.items():
        base_priority = MOTION_PRIORITY_TABLE.get(motion, 0.2)
        score = base_priority * confidence
        if score > best_score:
            best_score = score
            best_motion = motion
    return best_motion
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_motion_priority_resolution(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Resolves competing motion intents into a single cinematic directive.
    """
    enabled = config.get("enable_motion_priority_resolver", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    motion_votes = temporal_state.get("motion_intents", {})
    resolved_motion = resolve_motion_priority(motion_votes)
    temporal_state["resolved_motion_intent"] = resolved_motion
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 V 04 — CINEMATIC MOTION PRIORITY RESOLVER
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 V 05 — SHOT DURATION INTELLIGENCE
# ==============================================================================
# Purpose:
#   Determine optimal shot hold duration based on motion energy,
#   subject dynamics, and cinematic pacing principles.
#
# Cinematic relevance:
#   - Prevents rushed cuts
#   - Avoids overstaying static shots
#   - Mimics editor pacing instincts
#
# Runs AFTER:
#   - 84 V 04 (Cinematic Motion Priority Resolver)
# ==============================================================================
import numpy as np
SHOT_BASE_DURATION = {
    "establishing": 4.5,
    "tracking": 3.5,
    "close_up": 2.8,
    "detail": 2.2,
    "aerial_wide": 5.0,
    "medium": 3.2,
}
def compute_shot_duration(
    shot_type: str,
    motion_energy: float,
    subject_activity: float
) -> float:
    """
    Computes adaptive shot duration in seconds.
    """
    base = SHOT_BASE_DURATION.get(shot_type, 3.0)
    # High motion shortens acceptable duration
    motion_factor = 1.0 - 0.4 * np.clip(motion_energy, 0.0, 1.0)
    # Active subjects demand quicker editorial rhythm
    subject_factor = 1.0 - 0.3 * np.clip(subject_activity, 0.0, 1.0)
    duration = base * motion_factor * subject_factor
    return float(np.clip(duration, 1.2, 6.5))
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_shot_duration_intelligence(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Updates shot duration targets based on scene dynamics.
    """
    enabled = config.get("enable_shot_duration_intelligence", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    shot_type = temporal_state.get(
        "active_shot_type", "medium"
    )
    motion_energy = float(
        temporal_state.get("scene_energy", 0.5)
    )
    subject_activity = float(
        temporal_state.get("subject_activity", 0.4)
    )
    duration = compute_shot_duration(
        shot_type=shot_type,
        motion_energy=motion_energy,
        subject_activity=subject_activity
    )
    temporal_state["target_shot_duration"] = duration
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 V 05 — SHOT DURATION INTELLIGENCE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 W 01 — AUTONOMOUS CAMERA PATH GRAMMAR
# ==============================================================================
# Purpose:
#   Define a cinematic grammar for camera movement paths, ensuring
#   spatially meaningful motion rather than reactive point-to-point drift.
#
# Cinematic relevance:
#   - Produces readable, intentional camera motion
#   - Avoids robotic zig-zag trajectories
#   - Mirrors dolly, crane, and aerial grammar in cinema
#
# Runs AFTER:
#   - 84 V 05 (Shot Duration Intelligence)
# ==============================================================================
import numpy as np
CAMERA_PATH_GRAMMAR = {
    "static_hold": {
        "curvature": 0.0,
        "speed_bias": 0.0
    },
    "push_in": {
        "curvature": 0.05,
        "speed_bias": 0.6
    },
    "pull_out": {
        "curvature": 0.05,
        "speed_bias": 0.6
    },
    "lateral_track": {
        "curvature": 0.1,
        "speed_bias": 0.7
    },
    "orbit": {
        "curvature": 0.4,
        "speed_bias": 0.5
    },
    "aerial_arc": {
        "curvature": 0.25,
        "speed_bias": 0.8
    }
}
def select_camera_path(
    shot_type: str,
    resolved_motion: str
) -> str:
    """
    Selects a camera path grammar based on shot type and motion intent.
    """
    if resolved_motion == "subject_lock":
        return "static_hold"
    if shot_type in ("close_up", "detail"):
        return "push_in"
    if shot_type == "tracking":
        return "lateral_track"
    if shot_type == "aerial_wide":
        return "aerial_arc"
    if resolved_motion == "orbit":
        return "orbit"
    return "static_hold"
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_camera_path_grammar(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Assigns a cinematic camera path grammar to the temporal state.
    """
    enabled = config.get("enable_camera_path_grammar", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    shot_type = temporal_state.get(
        "active_shot_type", "medium"
    )
    resolved_motion = temporal_state.get(
        "resolved_motion_intent", "idle_drift"
    )
    path_type = select_camera_path(
        shot_type=shot_type,
        resolved_motion=resolved_motion
    )
    grammar = CAMERA_PATH_GRAMMAR.get(
        path_type, CAMERA_PATH_GRAMMAR["static_hold"]
    )
    temporal_state["camera_path_type"] = path_type
    temporal_state["camera_path_curvature"] = grammar["curvature"]
    temporal_state["camera_path_speed_bias"] = grammar["speed_bias"]
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 W 01 — AUTONOMOUS CAMERA PATH GRAMMAR
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 W 02 — MOTION ARC CONTINUITY
# ==============================================================================
# Purpose:
#   Enforce continuous motion arcs over time, preventing abrupt curvature
#   changes that break cinematic flow.
#
# Cinematic relevance:
#   - Maintains graceful, readable camera motion
#   - Avoids mechanical direction snapping
#   - Matches dolly/crane arc behavior in film production
#
# Runs AFTER:
#   - 84 W 01 (Autonomous Camera Path Grammar)
# ==============================================================================
import numpy as np
def blend_motion_arc(
    previous_arc: float,
    target_arc: float,
    continuity_factor: float
) -> float:
    """
    Smoothly blends motion curvature across frames.
    """
    continuity_factor = np.clip(continuity_factor, 0.0, 1.0)
    return (
        previous_arc * continuity_factor +
        target_arc * (1.0 - continuity_factor)
    )
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_motion_arc_continuity(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies continuity constraints to camera motion curvature.
    """
    enabled = config.get("enable_motion_arc_continuity", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    previous_arc = float(
        temporal_state.get("previous_motion_arc", 0.0)
    )
    target_arc = float(
        temporal_state.get("camera_path_curvature", 0.0)
    )
    continuity_factor = float(
        config.get("motion_arc_continuity_factor", 0.85)
    )
    blended_arc = blend_motion_arc(
        previous_arc=previous_arc,
        target_arc=target_arc,
        continuity_factor=continuity_factor
    )
    temporal_state["camera_path_curvature"] = blended_arc
    temporal_state["previous_motion_arc"] = blended_arc
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 W 02 — MOTION ARC CONTINUITY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 W 03 — PATH SMOOTHNESS CONSTRAINTS
# ==============================================================================
# Purpose:
#   Enforce spatial smoothness in camera trajectories by limiting jerk
#   and acceleration spikes across frames.
#
# Cinematic relevance:
#   - Eliminates robotic snapping
#   - Preserves crane/dolly realism
#   - Matches physical inertia expectations
#
# Runs AFTER:
#   - 84 W 02 (Motion Arc Continuity)
# ==============================================================================
import numpy as np
def smooth_path_vector(
    previous_vec: np.ndarray,
    target_vec: np.ndarray,
    smooth_factor: float
) -> np.ndarray:
    """
    Applies exponential smoothing to camera motion vectors.
    """
    smooth_factor = np.clip(smooth_factor, 0.0, 1.0)
    return (
        previous_vec * smooth_factor +
        target_vec * (1.0 - smooth_factor)
    )
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_path_smoothness_constraints(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Smooths camera motion vectors to maintain cinematic inertia.
    """
    enabled = config.get("enable_path_smoothness", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    previous_vec = np.array(
        temporal_state.get("previous_motion_vector", [0.0, 0.0, 0.0]),
        dtype=np.float32
    )
    target_vec = np.array(
        temporal_state.get("desired_motion_vector", previous_vec),
        dtype=np.float32
    )
    smooth_factor = float(
        config.get("path_smoothness_factor", 0.8)
    )
    smoothed_vec = smooth_path_vector(
        previous_vec=previous_vec,
        target_vec=target_vec,
        smooth_factor=smooth_factor
    )
    temporal_state["smoothed_motion_vector"] = smoothed_vec.tolist()
    temporal_state["previous_motion_vector"] = smoothed_vec.tolist()
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 W 03 — PATH SMOOTHNESS CONSTRAINTS
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 W 04 — VELOCITY ENVELOPE SHAPING
# ==============================================================================
# Purpose:
#   Shape camera velocity over time to respect physical acceleration
#   limits and cinematic ease-in / ease-out behavior.
#
# Cinematic relevance:
#   - Prevents robotic start/stop motion
#   - Emulates dolly/crane inertia
#   - Ensures graceful velocity ramps
#
# Runs AFTER:
#   - 84 W 03 (Path Smoothness Constraints)
# ==============================================================================
import numpy as np
def shape_velocity_envelope(
    previous_velocity: np.ndarray,
    target_velocity: np.ndarray,
    max_accel: float,
    dt: float
) -> np.ndarray:
    """
    Limits acceleration to cinematic bounds.
    """
    delta_v = target_velocity - previous_velocity
    max_delta = max_accel * max(dt, 1e-3)
    delta_mag = np.linalg.norm(delta_v)
    if delta_mag > max_delta:
        delta_v = delta_v / (delta_mag + 1e-6) * max_delta
    return previous_velocity + delta_v
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_velocity_envelope_shaping(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies cinematic velocity shaping to motion vectors.
    """
    enabled = config.get("enable_velocity_envelope", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    previous_velocity = np.array(
        temporal_state.get("previous_velocity", [0.0, 0.0, 0.0]),
        dtype=np.float32
    )
    target_velocity = np.array(
        temporal_state.get("smoothed_motion_vector", previous_velocity),
        dtype=np.float32
    )
    max_accel = float(
        config.get("max_cinematic_accel", 0.35)
    )
    dt = float(
        temporal_state.get("frame_delta_time", 1.0 / 30.0)
    )
    shaped_velocity = shape_velocity_envelope(
        previous_velocity=previous_velocity,
        target_velocity=target_velocity,
        max_accel=max_accel,
        dt=dt
    )
    temporal_state["shaped_velocity"] = shaped_velocity.tolist()
    temporal_state["previous_velocity"] = shaped_velocity.tolist()
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 W 04 — VELOCITY ENVELOPE SHAPING
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 W 05 — OBSTACLE-AWARE PATH BIAS
# ==============================================================================
# Purpose:
#   Bias camera motion paths away from obstacles while preserving
#   cinematic intent and shot grammar.
#
# Cinematic relevance:
#   - Avoids sudden evasive motion
#   - Preserves framing integrity near obstacles
#   - Enables confident autonomous navigation visuals
#
# Runs AFTER:
#   - 84 W 04 (Velocity Envelope Shaping)
# ==============================================================================
import numpy as np
def compute_obstacle_bias(
    motion_vector: np.ndarray,
    obstacle_vectors: list,
    safety_radius: float
) -> np.ndarray:
    """
    Applies repulsion bias from nearby obstacles.
    """
    bias = np.zeros(3, dtype=np.float32)
    for obs in obstacle_vectors:
        obs_vec = np.array(obs["direction"], dtype=np.float32)
        distance = float(obs.get("distance", safety_radius))
        if distance < safety_radius:
            strength = (safety_radius - distance) / safety_radius
            bias -= obs_vec * strength
    return motion_vector + bias
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_obstacle_aware_path_bias(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies obstacle-aware bias to shaped velocity.
    """
    enabled = config.get("enable_obstacle_aware_path_bias", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    shaped_velocity = np.array(
        temporal_state.get("shaped_velocity", [0.0, 0.0, 0.0]),
        dtype=np.float32
    )
    obstacle_vectors = temporal_state.get(
        "obstacle_vectors", []
    )
    safety_radius = float(
        config.get("obstacle_safety_radius", 2.5)
    )
    biased_velocity = compute_obstacle_bias(
        motion_vector=shaped_velocity,
        obstacle_vectors=obstacle_vectors,
        safety_radius=safety_radius
    )
    temporal_state["final_motion_vector"] = biased_velocity.tolist()
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 W 05 — OBSTACLE-AWARE PATH BIAS
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 X 01 — MULTI-SUBJECT SPATIAL NEGOTIATION
# ==============================================================================
# Purpose:
#   Resolve spatial layout when multiple subjects compete for framing,
#   ensuring readable composition and cinematic balance.
#
# Cinematic relevance:
#   - Prevents frame clutter
#   - Preserves hierarchy of subjects
#   - Emulates operator intuition in ensemble shots
#
# Runs AFTER:
#   - 84 W 05 (Obstacle-Aware Path Bias)
# ==============================================================================
import numpy as np
def compute_subject_weight(
    size: float,
    motion: float,
    saliency: float
) -> float:
    """
    Computes a normalized weight representing subject importance.
    """
    return (
        0.4 * np.clip(size, 0.0, 1.0) +
        0.3 * np.clip(motion, 0.0, 1.0) +
        0.3 * np.clip(saliency, 0.0, 1.0)
    )
def negotiate_subject_positions(subjects: list) -> dict:
    """
    Determines primary and secondary subjects for framing.
    """
    if not subjects:
        return {}
    weights = []
    for s in subjects:
        w = compute_subject_weight(
            size=s.get("size", 0.5),
            motion=s.get("motion", 0.5),
            saliency=s.get("saliency", 0.5)
        )
        weights.append(w)
    weights = np.array(weights)
    primary_idx = int(np.argmax(weights))
    return {
        "primary_subject_index": primary_idx,
        "secondary_subject_indices": [
            i for i in range(len(subjects)) if i != primary_idx
        ]
    }
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_multi_subject_spatial_negotiation(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Resolves subject hierarchy and updates framing priorities.
    """
    enabled = config.get("enable_multi_subject_negotiation", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    subjects = temporal_state.get("detected_subjects", [])
    negotiation = negotiate_subject_positions(subjects)
    temporal_state["subject_hierarchy"] = negotiation
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 X 01 — MULTI-SUBJECT SPATIAL NEGOTIATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 X 02 — SUBJECT DOMINANCE RESOLUTION
# ==============================================================================
# Purpose:
#   Resolve dominance among detected subjects to determine framing authority,
#   ensuring the primary subject governs composition and motion decisions.
#
# Cinematic relevance:
#   - Prevents frame tug-of-war
#   - Preserves narrative clarity
#   - Matches director-led subject hierarchy
#
# Runs AFTER:
#   - 84 X 01 (Multi-Subject Spatial Negotiation)
# ==============================================================================
import numpy as np
def dominance_score(
    size: float,
    motion: float,
    persistence: float,
    centrality: float
) -> float:
    """
    Computes dominance score for a subject.
    """
    return (
        0.35 * np.clip(size, 0.0, 1.0) +
        0.25 * np.clip(motion, 0.0, 1.0) +
        0.20 * np.clip(persistence, 0.0, 1.0) +
        0.20 * np.clip(centrality, 0.0, 1.0)
    )
def resolve_subject_dominance(subjects: list) -> int:
    """
    Returns index of dominant subject.
    """
    if not subjects:
        return -1
    scores = []
    for s in subjects:
        score = dominance_score(
            size=s.get("size", 0.5),
            motion=s.get("motion", 0.5),
            persistence=s.get("persistence", 0.5),
            centrality=s.get("centrality", 0.5)
        )
        scores.append(score)
    return int(np.argmax(scores))
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_subject_dominance_resolution(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Determines dominant subject and updates framing authority.
    """
    enabled = config.get("enable_subject_dominance_resolution", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    subjects = temporal_state.get("detected_subjects", [])
    dominant_idx = resolve_subject_dominance(subjects)
    temporal_state["dominant_subject_index"] = dominant_idx
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 X 02 — SUBJECT DOMINANCE RESOLUTION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 X 03 — MULTI-TARGET SHOT ARBITRATION
# ==============================================================================
# Purpose:
#   Select the most cinematic framing target when multiple valid subjects
#   compete for shot ownership across time.
#
# Cinematic relevance:
#   - Prevents indecisive framing shifts
#   - Maintains narrative focus
#   - Emulates assistant editor arbitration logic
#
# Runs AFTER:
#   - 84 X 02 (Subject Dominance Resolution)
# ==============================================================================
import numpy as np
def arbitration_score(
    dominance: float,
    screen_position: float,
    temporal_stability: float
) -> float:
    """
    Computes arbitration score for a subject candidate.
    """
    return (
        0.45 * np.clip(dominance, 0.0, 1.0) +
        0.30 * np.clip(screen_position, 0.0, 1.0) +
        0.25 * np.clip(temporal_stability, 0.0, 1.0)
    )
def arbitrate_shot_target(subjects: list) -> int:
    """
    Returns index of the subject selected as shot target.
    """
    if not subjects:
        return -1
    scores = []
    for s in subjects:
        score = arbitration_score(
            dominance=s.get("dominance", 0.5),
            screen_position=s.get("screen_position", 0.5),
            temporal_stability=s.get("temporal_stability", 0.5)
        )
        scores.append(score)
    return int(np.argmax(scores))
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_multi_target_shot_arbitration(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Selects a single framing target among multiple candidates.
    """
    enabled = config.get("enable_multi_target_arbitration", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    subjects = temporal_state.get("detected_subjects", [])
    target_idx = arbitrate_shot_target(subjects)
    temporal_state["active_shot_target_index"] = target_idx
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 X 03 — MULTI-TARGET SHOT ARBITRATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 X 04 — CROWD FRAMING STABILITY
# ==============================================================================
# Purpose:
#   Stabilize framing decisions in crowd scenarios to avoid oscillation
#   between multiple similarly-ranked subjects.
#
# Cinematic relevance:
#   - Prevents frame indecision in ensemble scenes
#   - Preserves spatial clarity and hierarchy
#   - Mimics human operator bias toward stable group framing
#
# Runs AFTER:
#   - 84 X 03 (Multi-Target Shot Arbitration)
# ==============================================================================
import numpy as np
def compute_crowd_stability_weight(
    subject_density: float,
    inter_subject_motion: float
) -> float:
    """
    Computes stability bias in crowded scenes.
    """
    density_term = np.clip(subject_density, 0.0, 1.0)
    motion_term = 1.0 - np.clip(inter_subject_motion, 0.0, 1.0)
    return 0.6 * density_term + 0.4 * motion_term
def stabilize_crowd_target(
    previous_target: int,
    candidate_target: int,
    stability_weight: float
) -> int:
    """
    Dampens rapid switching in crowded scenes.
    """
    if previous_target == candidate_target:
        return previous_target
    if np.random.rand() < stability_weight:
        return previous_target
    return candidate_target
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_crowd_framing_stability(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies crowd stability bias to active shot target.
    """
    enabled = config.get("enable_crowd_framing_stability", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    previous_target = temporal_state.get(
        "previous_shot_target_index",
        temporal_state.get("active_shot_target_index", -1)
    )
    candidate_target = temporal_state.get(
        "active_shot_target_index", -1
    )
    subject_density = float(
        temporal_state.get("subject_density", 0.5)
    )
    inter_subject_motion = float(
        temporal_state.get("inter_subject_motion", 0.5)
    )
    stability_weight = compute_crowd_stability_weight(
        subject_density=subject_density,
        inter_subject_motion=inter_subject_motion
    )
    stabilized_target = stabilize_crowd_target(
        previous_target=previous_target,
        candidate_target=candidate_target,
        stability_weight=stability_weight
    )
    temporal_state["active_shot_target_index"] = stabilized_target
    temporal_state["previous_shot_target_index"] = stabilized_target
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 X 04 — CROWD FRAMING STABILITY
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 X 05 — OCCLUSION-AWARE SUBJECT PERSISTENCE
# ==============================================================================
# Purpose:
#   Maintain shot continuity when the active subject is temporarily occluded
#   by geometry, crowd movement, or motion blur.
#
# Cinematic relevance:
#   - Prevents abrupt subject drops during partial occlusions
#   - Mimics human operator anticipation
#   - Preserves narrative continuity across brief interruptions
#
# Runs AFTER:
#   - 84 X 04 (Crowd Framing Stability)
# ==============================================================================
import numpy as np
def compute_occlusion_confidence(
    visibility_ratio: float,
    motion_consistency: float,
    depth_separation: float
) -> float:
    """
    Estimates confidence that an occluded subject should persist as active.
    """
    v = np.clip(visibility_ratio, 0.0, 1.0)
    m = np.clip(motion_consistency, 0.0, 1.0)
    d = np.clip(depth_separation, 0.0, 1.0)
    return 0.45 * m + 0.35 * d + 0.20 * v
def should_persist_subject(
    occlusion_confidence: float,
    persistence_threshold: float
) -> bool:
    """
    Decides whether to keep the current subject active.
    """
    return occlusion_confidence >= persistence_threshold
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_occlusion_aware_persistence(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Maintains subject lock through brief occlusions.
    """
    enabled = config.get("enable_occlusion_persistence", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    active_idx = temporal_state.get("active_shot_target_index", -1)
    subjects = temporal_state.get("detected_subjects", [])
    if active_idx < 0 or active_idx >= len(subjects):
        return rgb_image, grain_state, temporal_state
    subject = subjects[active_idx]
    visibility_ratio = float(subject.get("visibility_ratio", 0.0))
    motion_consistency = float(subject.get("motion_consistency", 0.5))
    depth_separation = float(subject.get("depth_separation", 0.5))
    occlusion_confidence = compute_occlusion_confidence(
        visibility_ratio=visibility_ratio,
        motion_consistency=motion_consistency,
        depth_separation=depth_separation
    )
    persistence_threshold = float(
        config.get("occlusion_persistence_threshold", 0.55)
    )
    persist = should_persist_subject(
        occlusion_confidence=occlusion_confidence,
        persistence_threshold=persistence_threshold
    )
    temporal_state["occlusion_confidence"] = occlusion_confidence
    temporal_state["subject_persisted"] = persist
    if not persist:
        # Allow downstream arbitration to replace subject
        temporal_state["active_shot_target_index"] = -1
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 X 05 — OCCLUSION-AWARE SUBJECT PERSISTENCE
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Y 01 — ENVIRONMENTAL MOTION CONTEXT
# ==============================================================================
# Purpose:
#   Model large-scale environmental motion influences (wind fields,
#   background parallax, global flow) to contextualize camera and subject motion.
#
# Cinematic relevance:
#   - Separates subject motion from environment motion
#   - Prevents over-stabilization in dynamic scenes
#   - Preserves natural motion energy
#
# Runs BEFORE:
#   - 84 Y 02 (Weather-Driven Motion Bias)
# ==============================================================================
import numpy as np
def estimate_environmental_flow(
    optical_flow: np.ndarray,
    subject_masks: list[np.ndarray]
) -> np.ndarray:
    """
    Estimates dominant environmental motion by excluding subject regions.
    """
    if not subject_masks:
        return np.mean(optical_flow, axis=(0, 1))
    mask = np.ones(optical_flow.shape[:2], dtype=bool)
    for sm in subject_masks:
        mask &= ~sm.astype(bool)
    if not np.any(mask):
        return np.mean(optical_flow, axis=(0, 1))
    return np.mean(optical_flow[mask], axis=0)
def compute_environment_motion_strength(
    env_flow: np.ndarray
) -> float:
    """
    Computes scalar strength of environmental motion.
    """
    return float(np.linalg.norm(env_flow))
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_environmental_motion_context(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Extracts and stores environmental motion context.
    """
    enabled = config.get("enable_environment_motion_context", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    optical_flow = temporal_state.get("optical_flow", None)
    subject_masks = temporal_state.get("subject_masks", [])
    if optical_flow is None:
        temporal_state["environment_flow"] = np.zeros(2)
        temporal_state["environment_motion_strength"] = 0.0
        return rgb_image, grain_state, temporal_state
    env_flow = estimate_environmental_flow(
        optical_flow=optical_flow,
        subject_masks=subject_masks
    )
    env_strength = compute_environment_motion_strength(env_flow)
    temporal_state["environment_flow"] = env_flow
    temporal_state["environment_motion_strength"] = env_strength
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Y 01 — ENVIRONMENTAL MOTION CONTEXT
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Y 02 — WEATHER-DRIVEN MOTION BIAS
# ==============================================================================
# Purpose:
#   Apply physically-plausible motion bias derived from weather conditions
#   (wind, gust variability, precipitation) to contextualize stabilization
#   and framing decisions without introducing jitter.
#
# Cinematic relevance:
#   - Preserves natural motion under wind/rain
#   - Prevents over-damping in adverse weather
#   - Matches real aerial cinematography behavior
#
# Runs AFTER:
#   - 84 Y 01 (Environmental Motion Context)
# ==============================================================================
import numpy as np
def weather_bias_vector(
    wind_speed: float,
    wind_direction_rad: float,
    gust_factor: float,
    precipitation_intensity: float
) -> np.ndarray:
    """
    Computes a 2D motion bias vector induced by weather.
    """
    ws = np.clip(wind_speed, 0.0, 30.0) / 30.0
    gf = np.clip(gust_factor, 0.0, 1.0)
    pi = np.clip(precipitation_intensity, 0.0, 1.0)
    base_mag = ws * (0.6 + 0.4 * gf)
    damp = 1.0 - 0.35 * pi
    mag = base_mag * damp
    return np.array([
        mag * np.cos(wind_direction_rad),
        mag * np.sin(wind_direction_rad)
    ], dtype=np.float32)
def blend_weather_with_environment(
    env_flow: np.ndarray,
    weather_flow: np.ndarray,
    blend_ratio: float
) -> np.ndarray:
    """
    Blends environmental flow with weather-induced bias.
    """
    br = np.clip(blend_ratio, 0.0, 1.0)
    return (1.0 - br) * env_flow + br * weather_flow
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_weather_driven_motion_bias(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Injects weather-driven motion bias into the environmental motion model.
    """
    enabled = config.get("enable_weather_motion_bias", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    env_flow = temporal_state.get("environment_flow", np.zeros(2, dtype=np.float32))
    wind_speed = float(temporal_state.get("wind_speed", 0.0))
    wind_dir = float(temporal_state.get("wind_direction_rad", 0.0))
    gust = float(temporal_state.get("wind_gust_factor", 0.0))
    precip = float(temporal_state.get("precipitation_intensity", 0.0))
    weather_flow = weather_bias_vector(
        wind_speed=wind_speed,
        wind_direction_rad=wind_dir,
        gust_factor=gust,
        precipitation_intensity=precip
    )
    blend_ratio = float(config.get("weather_bias_blend", 0.35))
    biased_flow = blend_weather_with_environment(
        env_flow=env_flow,
        weather_flow=weather_flow,
        blend_ratio=blend_ratio
    )
    temporal_state["weather_flow"] = weather_flow
    temporal_state["environment_flow_biased"] = biased_flow
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Y 02 — WEATHER-DRIVEN MOTION BIAS
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Y 03 — WIND-COUPLED CAMERA COMPENSATION
# ==============================================================================
# Purpose:
#   Compensate camera motion based on wind-induced drift while preserving
#   cinematic inertia and avoiding over-correction.
#
# Cinematic relevance:
#   - Natural resistance to gusts
#   - Prevents “robotic lock” in windy scenes
#   - Matches real aerial operator behavior
#
# Runs AFTER:
#   - 84 Y 02 (Weather-Driven Motion Bias)
# ==============================================================================
import numpy as np
def wind_compensation_gain(
    wind_speed: float,
    scene_energy: float
) -> float:
    """
    Computes adaptive gain for wind compensation.
    """
    ws = np.clip(wind_speed, 0.0, 30.0) / 30.0
    se = np.clip(scene_energy, 0.0, 1.0)
    # Strong wind → more compensation; high scene energy → less damping
    return np.clip(0.25 + 0.55 * ws - 0.30 * se, 0.05, 0.75)
def apply_wind_compensation(
    camera_motion: np.ndarray,
    wind_flow: np.ndarray,
    gain: float
) -> np.ndarray:
    """
    Applies wind-aware correction to camera motion vector.
    """
    return camera_motion - gain * wind_flow
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_wind_coupled_camera_compensation(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Adjusts camera motion using wind-aware compensation.
    """
    enabled = config.get("enable_wind_camera_compensation", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    camera_motion = temporal_state.get(
        "camera_motion_vector", np.zeros(2, dtype=np.float32)
    )
    wind_flow = temporal_state.get(
        "weather_flow", np.zeros(2, dtype=np.float32)
    )
    wind_speed = float(temporal_state.get("wind_speed", 0.0))
    scene_energy = float(temporal_state.get("scene_energy", 0.5))
    gain = wind_compensation_gain(
        wind_speed=wind_speed,
        scene_energy=scene_energy
    )
    compensated_motion = apply_wind_compensation(
        camera_motion=camera_motion,
        wind_flow=wind_flow,
        gain=gain
    )
    temporal_state["camera_motion_compensated"] = compensated_motion
    temporal_state["wind_compensation_gain"] = gain
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Y 03 — WIND-COUPLED CAMERA COMPENSATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Y 04 — TERRAIN-INDUCED MOTION ADAPTATION
# ==============================================================================
# Purpose:
#   Adapt motion compensation and framing behavior based on terrain-induced
#   parallax, elevation change, and ground texture frequency.
#
# Cinematic relevance:
#   - Prevents over-stabilization during altitude or slope transitions
#   - Preserves cinematic parallax over complex terrain
#   - Matches helicopter/drone operator intuition
#
# Runs AFTER:
#   - 84 Y 03 (Wind-Coupled Camera Compensation)
# ==============================================================================
import numpy as np
def estimate_terrain_parallax_strength(
    depth_gradient: float,
    altitude_rate: float,
    ground_texture_freq: float
) -> float:
    """
    Estimates parallax strength induced by terrain and altitude change.
    """
    dg = np.clip(depth_gradient, 0.0, 1.0)
    ar = np.clip(abs(altitude_rate), 0.0, 5.0) / 5.0
    gt = np.clip(ground_texture_freq, 0.0, 1.0)
    return np.clip(0.4 * dg + 0.35 * ar + 0.25 * gt, 0.0, 1.0)
def terrain_motion_gain(
    parallax_strength: float,
    scene_energy: float
) -> float:
    """
    Computes gain to preserve terrain-induced motion.
    """
    ps = np.clip(parallax_strength, 0.0, 1.0)
    se = np.clip(scene_energy, 0.0, 1.0)
    return np.clip(0.2 + 0.6 * ps - 0.25 * se, 0.05, 0.8)
def apply_terrain_motion_adaptation(
    motion_vector: np.ndarray,
    terrain_flow: np.ndarray,
    gain: float
) -> np.ndarray:
    """
    Blends terrain-induced flow into camera motion.
    """
    return motion_vector + gain * terrain_flow
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_terrain_induced_motion_adaptation(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Preserves cinematic parallax and terrain motion cues.
    """
    enabled = config.get("enable_terrain_motion_adaptation", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    camera_motion = temporal_state.get(
        "camera_motion_compensated", np.zeros(2, dtype=np.float32)
    )
    terrain_flow = temporal_state.get(
        "terrain_flow", np.zeros(2, dtype=np.float32)
    )
    depth_gradient = float(temporal_state.get("depth_gradient", 0.0))
    altitude_rate = float(temporal_state.get("altitude_rate", 0.0))
    ground_texture_freq = float(
        temporal_state.get("ground_texture_frequency", 0.5)
    )
    scene_energy = float(temporal_state.get("scene_energy", 0.5))
    parallax_strength = estimate_terrain_parallax_strength(
        depth_gradient=depth_gradient,
        altitude_rate=altitude_rate,
        ground_texture_freq=ground_texture_freq
    )
    gain = terrain_motion_gain(
        parallax_strength=parallax_strength,
        scene_energy=scene_energy
    )
    adapted_motion = apply_terrain_motion_adaptation(
        motion_vector=camera_motion,
        terrain_flow=terrain_flow,
        gain=gain
    )
    temporal_state["camera_motion_terrain_adapted"] = adapted_motion
    temporal_state["terrain_parallax_strength"] = parallax_strength
    temporal_state["terrain_motion_gain"] = gain
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Y 04 — TERRAIN-INDUCED MOTION ADAPTATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Y 05 — ATMOSPHERIC PERSPECTIVE STABILIZATION
# ==============================================================================
# Purpose:
#   Stabilize perceived motion and contrast shifts caused by atmospheric
#   perspective (haze, humidity, distance-based attenuation) without flattening
#   depth cues or cinematic scale.
#
# Cinematic relevance:
#   - Preserves depth and scale in wide aerial shots
#   - Prevents contrast pumping in haze
#   - Matches real-world aerial cinematography behavior
#
# Runs AFTER:
#   - 84 Y 04 (Terrain-Induced Motion Adaptation)
# ==============================================================================
import numpy as np
def estimate_atmospheric_attenuation(
    haze_density: float,
    visibility_range: float,
    scene_depth_mean: float
) -> float:
    """
    Estimates atmospheric attenuation strength based on haze and depth.
    """
    hd = np.clip(haze_density, 0.0, 1.0)
    vr = np.clip(visibility_range, 0.1, 50.0) / 50.0
    sd = np.clip(scene_depth_mean, 0.0, 1.0)
    return np.clip(0.45 * hd + 0.35 * (1.0 - vr) + 0.20 * sd, 0.0, 1.0)
def atmospheric_motion_damping(
    attenuation_strength: float,
    scene_energy: float
) -> float:
    """
    Computes damping factor to reduce perceived motion amplification in haze.
    """
    a = np.clip(attenuation_strength, 0.0, 1.0)
    se = np.clip(scene_energy, 0.0, 1.0)
    return np.clip(0.15 + 0.55 * a - 0.30 * se, 0.05, 0.7)
def apply_atmospheric_perspective_stabilization(
    motion_vector: np.ndarray,
    damping: float
) -> np.ndarray:
    """
    Dampens motion to account for atmospheric perspective.
    """
    return motion_vector * (1.0 - damping)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_atmospheric_perspective_stabilization(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Stabilizes motion perception under atmospheric perspective effects.
    """
    enabled = config.get("enable_atmospheric_perspective_stabilization", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    camera_motion = temporal_state.get(
        "camera_motion_terrain_adapted", np.zeros(2, dtype=np.float32)
    )
    haze_density = float(temporal_state.get("haze_density", 0.0))
    visibility_range = float(temporal_state.get("visibility_range", 30.0))
    scene_depth_mean = float(temporal_state.get("scene_depth_mean", 0.5))
    scene_energy = float(temporal_state.get("scene_energy", 0.5))
    attenuation_strength = estimate_atmospheric_attenuation(
        haze_density=haze_density,
        visibility_range=visibility_range,
        scene_depth_mean=scene_depth_mean
    )
    damping = atmospheric_motion_damping(
        attenuation_strength=attenuation_strength,
        scene_energy=scene_energy
    )
    stabilized_motion = apply_atmospheric_perspective_stabilization(
        motion_vector=camera_motion,
        damping=damping
    )
    temporal_state["camera_motion_atmospheric_stabilized"] = stabilized_motion
    temporal_state["atmospheric_attenuation_strength"] = attenuation_strength
    temporal_state["atmospheric_motion_damping"] = damping
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Y 05 — ATMOSPHERIC PERSPECTIVE STABILIZATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Z 01 — GLOBAL SCENE ENERGY NORMALIZATION
# ==============================================================================
# Purpose:
#   Normalize perceived scene energy (motion + contrast + luminance dynamics)
#   into a stable reference domain to ensure cinematic consistency across shots.
#
# Cinematic relevance:
#   - Prevents energy spikes between frames
#   - Stabilizes grading and motion perception
#   - Establishes a global “cinematic baseline”
#
# Runs BEFORE:
#   - 84 Z 02 (Temporal Energy Clamping)
# ==============================================================================
import numpy as np
def compute_scene_energy(
    motion_magnitude: float,
    contrast_delta: float,
    luminance_variance: float
) -> float:
    """
    Computes scalar scene energy from motion, contrast, and luminance dynamics.
    """
    m = np.clip(motion_magnitude, 0.0, 5.0) / 5.0
    c = np.clip(contrast_delta, 0.0, 1.0)
    l = np.clip(luminance_variance, 0.0, 1.0)
    return np.clip(0.45 * m + 0.35 * c + 0.20 * l, 0.0, 1.0)
def normalize_scene_energy(
    raw_energy: float,
    target_energy: float,
    adaptation_rate: float
) -> float:
    """
    Smoothly normalizes scene energy toward a target baseline.
    """
    re = np.clip(raw_energy, 0.0, 1.0)
    te = np.clip(target_energy, 0.0, 1.0)
    ar = np.clip(adaptation_rate, 0.0, 1.0)
    return re + ar * (te - re)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_global_scene_energy_normalization(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Computes and normalizes global scene energy for downstream modules.
    """
    enabled = config.get("enable_global_scene_energy_norm", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    motion_mag = float(
        temporal_state.get("motion_magnitude", 0.0)
    )
    contrast_delta = float(
        temporal_state.get("contrast_delta", 0.0)
    )
    luminance_var = float(
        temporal_state.get("luminance_variance", 0.0)
    )
    raw_energy = compute_scene_energy(
        motion_magnitude=motion_mag,
        contrast_delta=contrast_delta,
        luminance_variance=luminance_var
    )
    target_energy = float(
        config.get("target_scene_energy", 0.55)
    )
    adaptation_rate = float(
        config.get("scene_energy_adaptation_rate", 0.15)
    )
    normalized_energy = normalize_scene_energy(
        raw_energy=raw_energy,
        target_energy=target_energy,
        adaptation_rate=adaptation_rate
    )
    temporal_state["scene_energy_raw"] = raw_energy
    temporal_state["scene_energy"] = normalized_energy
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Z 01 — GLOBAL SCENE ENERGY NORMALIZATION
# ==============================================================================
# ==============================================================================
# SUBCHUNK 84 Z 02 — TEMPORAL ENERGY CLAMPING
# ==============================================================================
# Purpose:
#   Clamp frame-to-frame scene energy deltas to prevent perceptual pumping
#   while preserving intentional kinetic beats.
#
# Cinematic relevance:
#   - Eliminates jittery energy spikes
#   - Preserves rhythm during action
#   - Matches editorial smoothing practices
#
# Runs AFTER:
#   - 84 Z 01 (Global Scene Energy Normalization)
# ==============================================================================
import numpy as np
def clamp_energy_delta(
    prev_energy: float,
    curr_energy: float,
    max_delta: float
) -> float:
    """
    Clamps change in scene energy between frames.
    """
    pe = np.clip(prev_energy, 0.0, 1.0)
    ce = np.clip(curr_energy, 0.0, 1.0)
    md = np.clip(max_delta, 0.0, 1.0)
    delta = np.clip(ce - pe, -md, md)
    return np.clip(pe + delta, 0.0, 1.0)
def adaptive_max_delta(
    scene_energy: float,
    scene_energy_velocity: float
) -> float:
    """
    Adapts allowable delta based on current energy and its velocity.
    """
    se = np.clip(scene_energy, 0.0, 1.0)
    sv = np.clip(abs(scene_energy_velocity), 0.0, 1.0)
    # High energy or fast ramps allow larger deltas
    return np.clip(0.04 + 0.20 * se + 0.15 * sv, 0.04, 0.35)
# ------------------------------------------------------------------------------
# Integration Helper
# ------------------------------------------------------------------------------
def process_temporal_energy_clamping(
    rgb_image: np.ndarray,
    grain_state: dict,
    temporal_state: dict,
    config: dict
) -> tuple[np.ndarray, dict, dict]:
    """
    Applies temporal clamping to scene energy.
    """
    enabled = config.get("enable_temporal_energy_clamp", True)
    if not enabled:
        return rgb_image, grain_state, temporal_state
    prev_energy = float(
        temporal_state.get("scene_energy_prev",
            temporal_state.get("scene_energy", 0.5))
    )
    curr_energy = float(
        temporal_state.get("scene_energy", 0.5)
    )
    energy_velocity = float(
        temporal_state.get("scene_energy_velocity", 0.0)
    )
    max_delta = adaptive_max_delta(
        scene_energy=curr_energy,
        scene_energy_velocity=energy_velocity
    )
    clamped_energy = clamp_energy_delta(
        prev_energy=prev_energy,
        curr_energy=curr_energy,
        max_delta=max_delta
    )
    temporal_state["scene_energy_prev"] = clamped_energy
    temporal_state["scene_energy"] = clamped_energy
    temporal_state["scene_energy_clamp_delta"] = max_delta
    return rgb_image, grain_state, temporal_state
# ==============================================================================
# END OF SUBCHUNK 84 Z 02 — TEMPORAL ENERGY CLAMPING
# ==============================================================================
# ==============================================================================
# CHUNK 84 Z 03 — GLOBAL CINEMATIC INTENT CONSOLIDATION ENGINE
# ==============================================================================
#
# Purpose:
#   Final high-level consolidation layer that merges:
#     - Shot intent
#     - Scene energy
#     - Narrative continuity
#     - Environmental dynamics
#   into a single, temporally stable cinematic control signal.
#
#   This signal becomes the authoritative “cinematic truth” used
#   downstream by tone, motion, exposure, and grading engines.
#
# Design Goals:
#   • Human-perceivable impact only (no subliminal noise)
#   • Temporal coherence over brilliance spikes
#   • Editor-grade predictability
#   • AI-driven but non-chaotic
#
# ==============================================================================


import numpy as np


class GlobalCinematicIntentConsolidator:
    """
    Consolidates multiple upstream cinematic signals into a single,
    bounded, temporally coherent intent vector.
    """
    def __init__(
        self,
        temporal_window: int = 12,
        stability_bias: float = 0.72,
        max_delta_per_frame: float = 0.08,
    ):
        self.temporal_window = temporal_window
        self.stability_bias = stability_bias
        self.max_delta_per_frame = max_delta_per_frame
        self._history = []
        self._last_output = None
    def _clamp_vector(self, v: np.ndarray) -> np.ndarray:
        return np.clip(v, 0.0, 1.0)
    def _temporal_smooth(self, v: np.ndarray) -> np.ndarray:
        self._history.append(v)
        if len(self._history) > self.temporal_window:
            self._history.pop(0)
        weights = np.linspace(
            self.stability_bias, 1.0, len(self._history)
        )
        weights /= weights.sum()
        smoothed = np.sum(
            np.stack(self._history) * weights[:, None],
            axis=0,
        )
        return smoothed
    def _limit_rate_of_change(
        self, current: np.ndarray
    ) -> np.ndarray:
        if self._last_output is None:
            return current
        delta = current - self._last_output
        delta = np.clip(
            delta,
            -self.max_delta_per_frame,
            self.max_delta_per_frame,
        )
        return self._last_output + delta
    def consolidate(
        self,
        shot_intent: np.ndarray,
        scene_energy: np.ndarray,
        narrative_weight: np.ndarray,
        environment_context: np.ndarray,
    ) -> np.ndarray:
        """
        Parameters (all normalized 0–1 vectors):
            shot_intent         : framing, motion, focus priorities
            scene_energy        : kinetic vs calm balance
            narrative_weight    : story emphasis vs observation
            environment_context : wind, terrain, light volatility
        Returns:
            consolidated_intent : final authoritative cinematic vector
        """
        # Step 1 — Weighted fusion
        fused = (
            0.35 * shot_intent +
            0.25 * scene_energy +
            0.25 * narrative_weight +
            0.15 * environment_context
        )
        fused = self._clamp_vector(fused)
        # Step 2 — Temporal smoothing
        fused = self._temporal_smooth(fused)
        # Step 3 — Rate limiting (prevents AI jitter)
        fused = self._limit_rate_of_change(fused)
        fused = self._clamp_vector(fused)
        self._last_output = fused
        return fused
# ==============================================================================
# END OF CHUNK 84 Z 03
# ==============================================================================
# ==============================================================================
# CHUNK 84 Z 04 — CINEMATIC PRIORITY ARBITRATION LAYER
# ==============================================================================
#
# Purpose:
#   Resolves conflicts between competing cinematic objectives such as:
#     - Motion smoothness vs emotional emphasis
#     - Environmental realism vs narrative clarity
#     - Subject dominance vs compositional balance
#
#   Produces a stable priority mask that downstream systems obey.
#
# Design Principles:
#   • No hard overrides (all arbitration is continuous)
#   • Human-visible impact only
#   • Editor-grade predictability
#
# ==============================================================================


import numpy as np


class CinematicPriorityArbitrator:
    """
    Arbitrates priority between competing cinematic control signals.
    Output is a normalized priority vector used as a multiplier mask.
    """
    def __init__(
        self,
        dominance_bias: float = 0.6,
        balance_bias: float = 0.4,
        soft_floor: float = 0.15,
    ):
        self.dominance_bias = dominance_bias
        self.balance_bias = balance_bias
        self.soft_floor = soft_floor
    @staticmethod
    def _normalize(v: np.ndarray) -> np.ndarray:
        s = np.sum(v)
        if s <= 1e-6:
            return np.ones_like(v) / len(v)
        return v / s
    def arbitrate(
        self,
        motion_priority: np.ndarray,
        emotion_priority: np.ndarray,
        environment_priority: np.ndarray,
        composition_priority: np.ndarray,
    ) -> np.ndarray:
        """
        Parameters (all normalized 0–1 vectors):
            motion_priority       : smoothness, stability, inertia
            emotion_priority      : emphasis, intensity, mood
            environment_priority  : wind, terrain, volatility
            composition_priority  : framing, balance, geometry
        Returns:
            priority_mask : normalized arbitration result
        """
        # Step 1 — Bias dominant narrative/emotional intent
        dominant = (
            self.dominance_bias * emotion_priority +
            self.balance_bias * composition_priority
        )
        # Step 2 — Preserve physical plausibility
        physical = 0.5 * motion_priority + 0.5 * environment_priority
        # Step 3 — Soft arbitration (no winner-takes-all)
        combined = 0.55 * dominant + 0.45 * physical
        # Step 4 — Soft floor prevents total suppression
        combined = np.maximum(combined, self.soft_floor)
        # Step 5 — Normalize for downstream consistency
        priority_mask = self._normalize(combined)
        return priority_mask
# ==============================================================================
# END OF CHUNK 84 Z 04
# ==============================================================================
# ==============================================================================
# CHUNK 84 Z 05 — CONFLICT RESOLUTION BETWEEN MOTION VS EMOTION
# ==============================================================================
#
# Purpose:
#   Resolves dynamic tension between physical motion constraints
#   (stability, inertia, smoothness) and emotional storytelling
#   demands (intensity, urgency, dramatic emphasis).
#
#   Ensures emotional intent NEVER causes physically implausible
#   or visually jarring motion artifacts.
#
# Cinematic Rationale:
#   Human audiences forgive reduced drama before broken physics,
#   but prefer emotional emphasis when motion remains believable.
#
# ==============================================================================


import numpy as np


class MotionEmotionConflictResolver:
    """
    Balances emotional drive against physical motion feasibility.
    Produces a modulation vector that downstream systems must obey.
    """
    def __init__(
        self,
        emotion_ceiling: float = 0.82,
        motion_floor: float = 0.35,
        inertia_bias: float = 0.65,
    ):
        self.emotion_ceiling = emotion_ceiling
        self.motion_floor = motion_floor
        self.inertia_bias = inertia_bias
    @staticmethod
    def _clamp(v: np.ndarray) -> np.ndarray:
        return np.clip(v, 0.0, 1.0)
    def resolve(
        self,
        motion_vector: np.ndarray,
        emotion_vector: np.ndarray,
        priority_mask: np.ndarray,
    ) -> np.ndarray:
        """
        Parameters:
            motion_vector   : physical feasibility & smoothness
            emotion_vector  : dramatic emphasis intent
            priority_mask   : arbitration result from 84Z-04
        Returns:
            resolved_vector : physically valid emotional motion intent
        """
        # Step 1 — Prevent emotional overshoot
        emotion_limited = np.minimum(
            emotion_vector, self.emotion_ceiling
        )
        # Step 2 — Enforce minimum motion plausibility
        motion_enforced = np.maximum(
            motion_vector, self.motion_floor
        )
        # Step 3 — Inertia-aware blending
        blended = (
            self.inertia_bias * motion_enforced +
            (1.0 - self.inertia_bias) * emotion_limited
        )
        # Step 4 — Apply cinematic priorities
        resolved = blended * priority_mask
        resolved = self._clamp(resolved)
        return resolved
# ==============================================================================
# END OF CHUNK 84 Z 05
# ==============================================================================
# ==============================================================================
# CHUNK 84 Z 06 — SCENE-LEVEL ENERGY PERSISTENCE CONTROL
# ==============================================================================
#
# Purpose:
#   Maintains perceptual energy continuity across a scene by preventing
#   abrupt drops or spikes in cinematic intensity unless narratively justified.
#
# Cinematic Motivation:
#   Viewers perceive energy changes more strongly than absolute energy.
#   Sudden unmotivated shifts break immersion and feel "AI-generated".
#
#   This module enforces:
#     • Energy inertia
#     • Controlled decay
#     • Justified escalation
#
# ==============================================================================

import numpy as np


class SceneEnergyPersistenceController:
    """
    Enforces scene-level energy continuity using temporal inertia
    and bounded rate-of-change logic.
    """
    def __init__(
        self,
        memory_length: int = 24,
        max_rise_per_frame: float = 0.06,
        max_drop_per_frame: float = 0.04,
        decay_bias: float = 0.92,
    ):
        self.memory_length = memory_length
        self.max_rise_per_frame = max_rise_per_frame
        self.max_drop_per_frame = max_drop_per_frame
        self.decay_bias = decay_bias
        self._energy_history = []
        self._last_energy = None
    @staticmethod
    def _clamp(v: np.ndarray) -> np.ndarray:
        return np.clip(v, 0.0, 1.0)
    def _update_history(self, energy: np.ndarray):
        self._energy_history.append(energy)
        if len(self._energy_history) > self.memory_length:
            self._energy_history.pop(0)
    def _historical_mean(self) -> np.ndarray:
        if not self._energy_history:
            return None
        return np.mean(np.stack(self._energy_history), axis=0)
    def enforce(
        self,
        current_energy: np.ndarray,
        narrative_override: float = 0.0,
    ) -> np.ndarray:
        """
        Parameters:
            current_energy     : instantaneous energy vector (0–1)
            narrative_override : allows justified escalation (0–1)
        Returns:
            stabilized_energy  : scene-consistent energy output
        """
        current_energy = self._clamp(current_energy)
        if self._last_energy is None:
            self._last_energy = current_energy
            self._update_history(current_energy)
            return current_energy
        # Step 1 — Compute delta
        delta = current_energy - self._last_energy
        # Step 2 — Bound escalation and decay
        rise_limit = self.max_rise_per_frame * (1.0 + narrative_override)
        drop_limit = self.max_drop_per_frame
        delta = np.where(
            delta > 0,
            np.minimum(delta, rise_limit),
            np.maximum(delta, -drop_limit),
        )
        stabilized = self._last_energy + delta
        # Step 3 — Historical gravity (prevents drift)
        historical_mean = self._historical_mean()
        if historical_mean is not None:
            stabilized = (
                self.decay_bias * stabilized +
                (1.0 - self.decay_bias) * historical_mean
            )
        stabilized = self._clamp(stabilized)
        self._last_energy = stabilized
        self._update_history(stabilized)
        return stabilized
# ==============================================================================
# END OF CHUNK 84 Z 06
# ==============================================================================
# ==============================================================================
# CHUNK 84 Z 07 — CROSS-SHOT INTENT MEMORY
# ==============================================================================
#
# Purpose:
#   Maintains semantic and emotional continuity across shot boundaries
#   by persisting high-level cinematic intent beyond single-shot lifespan.
#
# Cinematic Motivation:
#   Human editors preserve "feel" across cuts even when composition changes.
#   Without this, AI shots feel episodic instead of authored.
#
#   This module enables:
#     • Intent carry-over
#     • Controlled intent decay
#     • Cross-shot emotional coherence
#
# ==============================================================================

import numpy as np


class CrossShotIntentMemory:
    """
    Stores and manages cinematic intent across shot transitions.
    Prevents perceptual resets at cut boundaries.
    """
    def __init__(
        self,
        memory_depth: int = 6,
        decay_rate: float = 0.85,
        reinforcement_threshold: float = 0.15,
    ):
        self.memory_depth = memory_depth
        self.decay_rate = decay_rate
        self.reinforcement_threshold = reinforcement_threshold
        self._intent_memory = []
    @staticmethod
    def _clamp(v: np.ndarray) -> np.ndarray:
        return np.clip(v, 0.0, 1.0)
    def _decay_memory(self):
        for i in range(len(self._intent_memory)):
            self._intent_memory[i] *= self.decay_rate
    def register_shot_intent(self, intent_vector: np.ndarray):
        """
        Called at shot boundaries to register the final intent
        of the outgoing shot.
        """
        intent_vector = self._clamp(intent_vector)
        self._intent_memory.insert(0, intent_vector)
        if len(self._intent_memory) > self.memory_depth:
            self._intent_memory.pop()
        self._decay_memory()
    def apply_to_new_shot(
        self,
        current_intent: np.ndarray,
    ) -> np.ndarray:
        """
        Blends historical intent into the new shot if perceptually relevant.
        """
        current_intent = self._clamp(current_intent)
        if not self._intent_memory:
            return current_intent
        historical = np.mean(
            np.stack(self._intent_memory),
            axis=0,
        )
        delta = np.abs(historical - current_intent)
        # Only reinforce where difference is perceptually meaningful
        mask = delta > self.reinforcement_threshold
        blended = np.where(
            mask,
            0.6 * historical + 0.4 * current_intent,
            current_intent,
        )
        return self._clamp(blended)
# ==============================================================================
# END OF CHUNK 84 Z 07
# ==============================================================================
# ==============================================================================
# CHUNK 84 Z 08 — EDITORIAL STABILITY GUARDRAILS
# ==============================================================================
#
# Purpose:
#   Prevents AI-driven cinematic control from entering visually unstable,
#   editor-rejected states such as:
#     • excessive contrast pumping
#     • rapid tonal polarity flips
#     • oscillating emotional emphasis
#
#   Acts as the final “editor veto” before intent propagates downstream.
#
# Cinematic Motivation:
#   Human editors instinctively reject footage that feels indecisive.
#   This layer enforces decisiveness and perceptual calm.
#
# ==============================================================================

import numpy as np


class EditorialStabilityGuardrails:
    """
    Enforces hard and soft bounds on cinematic intent to guarantee
    editorial acceptability.
    """
    def __init__(
        self,
        max_variance: float = 0.12,
        stability_window: int = 16,
        snap_strength: float = 0.65,
    ):
        self.max_variance = max_variance
        self.stability_window = stability_window
        self.snap_strength = snap_strength
        self._history = []
    @staticmethod
    def _clamp(v: np.ndarray) -> np.ndarray:
        return np.clip(v, 0.0, 1.0)
    def _update_history(self, v: np.ndarray):
        self._history.append(v)
        if len(self._history) > self.stability_window:
            self._history.pop(0)
    def _historical_anchor(self) -> np.ndarray:
        if not self._history:
            return None
        return np.mean(np.stack(self._history), axis=0)
    def enforce(
        self,
        intent_vector: np.ndarray,
    ) -> np.ndarray:
        """
        Applies editorial stability constraints to the intent vector.
        """
        intent_vector = self._clamp(intent_vector)
        anchor = self._historical_anchor()
        if anchor is None:
            self._update_history(intent_vector)
            return intent_vector
        deviation = intent_vector - anchor
        deviation = np.clip(
            deviation,
            -self.max_variance,
            self.max_variance,
        )
        stabilized = (
            self.snap_strength * (anchor + deviation) +
            (1.0 - self.snap_strength) * intent_vector
        )
        stabilized = self._clamp(stabilized)
        self._update_history(stabilized)
        return stabilized
# ==============================================================================
# END OF CHUNK 84 Z 08
# ==============================================================================
# ==============================================================================
# CHUNK 84 Z 09 — CINEMATIC FAIL-SAFE & DEGENERACY PREVENTION
# ==============================================================================
#
# Purpose:
#   Detects and suppresses pathological AI states that cause:
#     • intent collapse (flat, lifeless output)
#     • intent explosion (over-driven, chaotic visuals)
#     • oscillatory indecision
#
#   Acts as the last defensive layer before final output normalization.
#
# Cinematic Motivation:
#   Even well-designed AI systems can enter unstable attractor states.
#   Human cinematography NEVER does — this layer enforces that rule.
#
# ==============================================================================

import numpy as np


class CinematicFailsafeController:
    """
    Detects degenerate cinematic intent states and forces recovery
    into stable, editor-acceptable regions.
    """
    def __init__(
        self,
        min_energy_norm: float = 0.18,
        max_energy_norm: float = 0.92,
        oscillation_threshold: float = 0.14,
        recovery_strength: float = 0.55,
        history_depth: int = 10,
    ):
        self.min_energy_norm = min_energy_norm
        self.max_energy_norm = max_energy_norm
        self.oscillation_threshold = oscillation_threshold
        self.recovery_strength = recovery_strength
        self.history_depth = history_depth
        self._history = []
    @staticmethod
    def _clamp(v: np.ndarray) -> np.ndarray:
        return np.clip(v, 0.0, 1.0)
    def _update_history(self, v: np.ndarray):
        self._history.append(v)
        if len(self._history) > self.history_depth:
            self._history.pop(0)
    def _energy_norm(self, v: np.ndarray) -> float:
        return float(np.linalg.norm(v) / np.sqrt(len(v)))
    def _detect_oscillation(self) -> bool:
        if len(self._history) < 3:
            return False
        diffs = [
            np.linalg.norm(self._history[i] - self._history[i - 1])
            for i in range(1, len(self._history))
        ]
        return np.mean(diffs) > self.oscillation_threshold
    def enforce(
        self,
        intent_vector: np.ndarray,
        editorial_anchor: np.ndarray,
    ) -> np.ndarray:
        """
        Parameters:
            intent_vector     : incoming cinematic intent
            editorial_anchor  : stable editorial reference state
        Returns:
            safe_intent       : stabilized, fail-safe intent vector
        """
        intent_vector = self._clamp(intent_vector)
        self._update_history(intent_vector)
        energy = self._energy_norm(intent_vector)
        unstable = False
        if energy < self.min_energy_norm:
            unstable = True
        if energy > self.max_energy_norm:
            unstable = True
        if self._detect_oscillation():
            unstable = True
        if not unstable:
            return intent_vector
        # Recovery: pull intent back toward editorial anchor
        recovered = (
            (1.0 - self.recovery_strength) * intent_vector +
            self.recovery_strength * editorial_anchor
        )
        return self._clamp(recovered)
# ==============================================================================
# END OF CHUNK 84 Z 09
# ==============================================================================
# ==============================================================================
# CHUNK 84 Z 10 — FINAL INTENT NORMALIZATION & OUTPUT LOCK
# ==============================================================================
#
# Purpose:
#   Produces the final, authoritative cinematic intent vector that is:
#     • strictly bounded
#     • temporally coherent
#     • editorially stable
#
#   This vector is the ONLY signal allowed to propagate beyond 84Z
#   into tone, exposure, motion, grading, and render subsystems.
#
# Cinematic Motivation:
#   Human cinematography has a final “commit” moment. This layer
#   replicates that commitment—preventing late-stage drift.
#
# ==============================================================================

import numpy as np


class FinalIntentOutputLock:
    """
    Normalizes and locks cinematic intent to a stable, bounded output
    suitable for downstream consumption.
    """
    def __init__(
        self,
        soft_min: float = 0.05,
        soft_max: float = 0.95,
        l2_target: float = 0.65,
        quantization_bins: int = 256,
    ):
        self.soft_min = soft_min
        self.soft_max = soft_max
        self.l2_target = l2_target
        self.quantization_bins = quantization_bins
    @staticmethod
    def _clamp(v: np.ndarray, lo: float, hi: float) -> np.ndarray:
        return np.clip(v, lo, hi)
    def _l2_normalize(self, v: np.ndarray) -> np.ndarray:
        norm = np.linalg.norm(v)
        if norm <= 1e-6:
            return v
        return v * (self.l2_target / norm)
    def _quantize(self, v: np.ndarray) -> np.ndarray:
        """
        Quantization is subtle and perceptually invisible; it prevents
        floating drift and ensures deterministic playback.
        """
        q = self.quantization_bins - 1
        return np.round(v * q) / q
    def lock(
        self,
        intent_vector: np.ndarray,
    ) -> np.ndarray:
        """
        Produces the final locked cinematic intent.
        """
        # Step 1 — Soft bounds (prevents hard clipping artifacts)
        locked = self._clamp(
            intent_vector,
            self.soft_min,
            self.soft_max,
        )
        # Step 2 — Energy normalization (scene-consistent magnitude)
        locked = self._l2_normalize(locked)
        # Step 3 — Final clamp
        locked = self._clamp(locked, 0.0, 1.0)
        # Step 4 — Deterministic quantization
        locked = self._quantize(locked)
        return locked
# ==============================================================================
# END OF CHUNK 84 Z 10
# ==============================================================================
# ==============================================================================
# CHUNK 85 A 01 — NARRATIVE RHYTHM INITIALIZATION
# ==============================================================================
#
# Purpose:
#   Establishes the foundational temporal rhythm model that governs
#   pacing, beat emphasis, and energy flow across scenes.
#
#   This is the first story-level layer above raw cinematic intent.
#
# Cinematic Motivation:
#   Films are not just sequences of shots—they breathe. Rhythm defines
#   how tension builds, releases, and sustains audience engagement.
#
# ==============================================================================

import numpy as np


class NarrativeRhythmInitializer:
    """
    Initializes and maintains a baseline narrative rhythm vector
    used by all downstream story-level systems.
    """
    def __init__(
        self,
        base_tempo: float = 0.5,
        tempo_bounds: tuple = (0.25, 0.85),
        adaptation_rate: float = 0.08,
        memory_window: int = 32,
    ):
        self.base_tempo = base_tempo
        self.tempo_bounds = tempo_bounds
        self.adaptation_rate = adaptation_rate
        self.memory_window = memory_window
        self._tempo_history = []
        self._current_tempo = base_tempo
    @staticmethod
    def _clamp(v: float, lo: float, hi: float) -> float:
        return float(np.clip(v, lo, hi))
    def _update_history(self, tempo: float):
        self._tempo_history.append(tempo)
        if len(self._tempo_history) > self.memory_window:
            self._tempo_history.pop(0)
    def _historical_anchor(self) -> float:
        if not self._tempo_history:
            return self.base_tempo
        return float(np.mean(self._tempo_history))
    def initialize(
        self,
        global_intent: np.ndarray,
        scene_energy: np.ndarray,
    ) -> float:
        """
        Parameters:
            global_intent : final intent vector from 84Z
            scene_energy  : stabilized scene energy vector
        Returns:
            narrative_tempo : scalar tempo control (0–1)
        """
        # Step 1 — Derive instantaneous tempo cue
        intent_energy = float(np.mean(global_intent))
        scene_drive = float(np.mean(scene_energy))
        instantaneous = 0.6 * intent_energy + 0.4 * scene_drive
        # Step 2 — Adaptive smoothing toward historical rhythm
        anchor = self._historical_anchor()
        tempo = (
            (1.0 - self.adaptation_rate) * anchor +
            self.adaptation_rate * instantaneous
        )
        # Step 3 — Enforce cinematic bounds
        tempo = self._clamp(
            tempo,
            self.tempo_bounds[0],
            self.tempo_bounds[1],
        )
        # Step 4 — Update state
        self._current_tempo = tempo
        self._update_history(tempo)
        return tempo
# ==============================================================================
# END OF CHUNK 85 A 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 A 02 — SCENE BEAT DETECTION & CLASSIFICATION
# ==============================================================================
#
# Purpose:
#   Detects and classifies cinematic beats within a scene based on
#   temporal energy changes, motion dynamics, and narrative tempo.
#
#   Produces discrete beat markers used by emotional arc, tension,
#   and pacing systems downstream.
#
# Cinematic Motivation:
#   Editors subconsciously cut on beats. This system formalizes that
#   instinct using perceptually grounded signals.
#
# ==============================================================================

import numpy as np


class SceneBeatDetector:
    """
    Identifies cinematic beats and classifies their narrative role.
    """
    def __init__(
        self,
        energy_threshold: float = 0.18,
        motion_threshold: float = 0.22,
        min_interval: int = 6,
        smoothing_window: int = 9,
    ):
        self.energy_threshold = energy_threshold
        self.motion_threshold = motion_threshold
        self.min_interval = min_interval
        self.smoothing_window = smoothing_window
        self._last_beat_frame = -min_interval
    @staticmethod
    def _smooth(signal: np.ndarray, k: int) -> np.ndarray:
        if len(signal) < k:
            return signal
        kernel = np.ones(k) / k
        return np.convolve(signal, kernel, mode="same")
    def detect_beats(
        self,
        energy_curve: np.ndarray,
        motion_curve: np.ndarray,
        frame_indices: np.ndarray,
    ):
        """
        Parameters:
            energy_curve  : normalized luminance / contrast energy
            motion_curve  : normalized motion magnitude
            frame_indices : frame numbers
        Returns:
            beats : list of dicts with keys:
                    frame, strength, type
        """
        beats = []
        energy_s = self._smooth(energy_curve, self.smoothing_window)
        motion_s = self._smooth(motion_curve, self.smoothing_window)
        for i in range(1, len(frame_indices) - 1):
            if (i - self._last_beat_frame) < self.min_interval:
                continue
            energy_peak = (
                energy_s[i] > self.energy_threshold and
                energy_s[i] > energy_s[i - 1] and
                energy_s[i] > energy_s[i + 1]
            )
            motion_peak = (
                motion_s[i] > self.motion_threshold and
                motion_s[i] > motion_s[i - 1] and
                motion_s[i] > motion_s[i + 1]
            )
            if not (energy_peak or motion_peak):
                continue
            strength = float(
                0.6 * energy_s[i] + 0.4 * motion_s[i]
            )
            if energy_peak and motion_peak:
                beat_type = "impact"
            elif energy_peak:
                beat_type = "emotional"
            else:
                beat_type = "kinetic"
            beats.append({
                "frame": int(frame_indices[i]),
                "strength": strength,
                "type": beat_type,
            })
            self._last_beat_frame = i
        return beats
# ==============================================================================
# END OF CHUNK 85 A 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 A 03 — EMOTIONAL ARC MODELING
# ==============================================================================
#
# Purpose:
#   Models the evolving emotional trajectory of a scene or sequence
#   using detected beats, narrative tempo, and intent vectors.
#
#   Produces a smooth, editor-usable emotional arc signal.
#
# Cinematic Motivation:
#   High-end films guide audience emotion deliberately over time.
#   Abrupt emotional reversals without setup are rejected by viewers.
#
# ==============================================================================

import numpy as np


class EmotionalArcModel:
    """
    Constructs a continuous emotional arc from discrete cinematic beats.
    """
    def __init__(
        self,
        rise_rate: float = 0.12,
        fall_rate: float = 0.08,
        sustain_decay: float = 0.015,
        memory_window: int = 48,
    ):
        self.rise_rate = rise_rate
        self.fall_rate = fall_rate
        self.sustain_decay = sustain_decay
        self.memory_window = memory_window
        self._arc_history = []
        self._current_emotion = 0.5
    @staticmethod
    def _clamp(v: float) -> float:
        return float(np.clip(v, 0.0, 1.0))
    def _update_history(self, v: float):
        self._arc_history.append(v)
        if len(self._arc_history) > self.memory_window:
            self._arc_history.pop(0)
    def _historical_baseline(self) -> float:
        if not self._arc_history:
            return self._current_emotion
        return float(np.mean(self._arc_history))
    def update(
        self,
        beats: list,
        narrative_tempo: float,
        global_intent: np.ndarray,
    ) -> float:
        """
        Parameters:
            beats            : list of beat dicts from SceneBeatDetector
            narrative_tempo  : scalar tempo from NarrativeRhythmInitializer
            global_intent    : stabilized cinematic intent vector
        Returns:
            emotion_level : scalar emotional intensity (0–1)
        """
        baseline = self._historical_baseline()
        emotion = baseline
        # Aggregate beat influence
        for beat in beats:
            strength = beat["strength"]
            btype = beat["type"]
            if btype == "impact":
                delta = self.rise_rate * strength
            elif btype == "emotional":
                delta = 0.7 * self.rise_rate * strength
            else:  # kinetic
                delta = 0.4 * self.rise_rate * strength
            emotion += delta
        # Tempo-modulated relaxation
        relaxation = self.fall_rate * (1.0 - narrative_tempo)
        emotion -= relaxation
        # Intent-driven sustain bias
        intent_bias = float(np.mean(global_intent)) - 0.5
        emotion += intent_bias * 0.05
        # Slow decay to prevent emotional plateaus
        emotion -= self.sustain_decay
        emotion = self._clamp(emotion)
        self._current_emotion = emotion
        self._update_history(emotion)
        return emotion
# ==============================================================================
# END OF CHUNK 85 A 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 A 04 — MULTI-SCENE CONTINUITY TRACKING
# ==============================================================================
#
# Purpose:
#   Tracks narrative and emotional continuity across scene boundaries,
#   preventing abrupt tonal or rhythmic discontinuities.
#
#   Acts as the “editor memory” that spans cuts.
#
# Cinematic Motivation:
#   High-end films preserve emotional logic across scenes even when
#   visual content changes drastically.
#
# ==============================================================================

import numpy as np


class MultiSceneContinuityTracker:
    """
    Maintains cross-scene emotional and rhythmic continuity.
    """
    def __init__(
        self,
        continuity_strength: float = 0.55,
        reset_threshold: float = 0.42,
        max_memory: int = 12,
    ):
        self.continuity_strength = continuity_strength
        self.reset_threshold = reset_threshold
        self.max_memory = max_memory
        self._scene_memory = []
    @staticmethod
    def _clamp(v: float) -> float:
        return float(np.clip(v, 0.0, 1.0))
    def _update_memory(self, state: dict):
        self._scene_memory.append(state)
        if len(self._scene_memory) > self.max_memory:
            self._scene_memory.pop(0)
    def _memory_anchor(self) -> dict:
        if not self._scene_memory:
            return None
        avg_emotion = float(
            np.mean([s["emotion"] for s in self._scene_memory])
        )
        avg_tempo = float(
            np.mean([s["tempo"] for s in self._scene_memory])
        )
        return {
            "emotion": avg_emotion,
            "tempo": avg_tempo,
        }
    def apply(
        self,
        emotion: float,
        tempo: float,
        scene_cut_strength: float,
    ) -> tuple:
        """
        Parameters:
            emotion            : current scene emotional level
            tempo              : current narrative tempo
            scene_cut_strength : 0–1 measure of scene discontinuity
        Returns:
            continuity_emotion, continuity_tempo
        """
        anchor = self._memory_anchor()
        if anchor is None or scene_cut_strength > self.reset_threshold:
            continuity_emotion = emotion
            continuity_tempo = tempo
        else:
            continuity_emotion = (
                self.continuity_strength * anchor["emotion"] +
                (1.0 - self.continuity_strength) * emotion
            )
            continuity_tempo = (
                self.continuity_strength * anchor["tempo"] +
                (1.0 - self.continuity_strength) * tempo
            )
        continuity_emotion = self._clamp(continuity_emotion)
        continuity_tempo = self._clamp(continuity_tempo)
        self._update_memory({
            "emotion": continuity_emotion,
            "tempo": continuity_tempo,
        })
        return continuity_emotion, continuity_tempo
# ==============================================================================
# END OF CHUNK 85 A 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 A 05 — NARRATIVE TENSION ACCUMULATION
# ==============================================================================
#
# Purpose:
#   Accumulates and releases narrative tension over time based on
#   emotional arc, beat density, and continuity-conditioned tempo.
#
#   Produces a stable tension signal used for editorial decisions
#   (cuts, holds, reveals).
#
# Cinematic Motivation:
#   Tension is not emotion alone; it is expectation under restraint.
#   Great films modulate tension deliberately, not reactively.
#
# ==============================================================================

import numpy as np


class NarrativeTensionAccumulator:
    """
    Builds a coherent tension curve across beats and scenes,
    preventing premature release or runaway escalation.
    """
    def __init__(
        self,
        accumulation_rate: float = 0.10,
        release_rate: float = 0.14,
        max_tension: float = 1.0,
        min_tension: float = 0.0,
        inertia: float = 0.72,
    ):
        self.accumulation_rate = accumulation_rate
        self.release_rate = release_rate
        self.max_tension = max_tension
        self.min_tension = min_tension
        self.inertia = inertia
        self._tension = 0.35
    @staticmethod
    def _clamp(v: float, lo: float, hi: float) -> float:
        return float(np.clip(v, lo, hi))
    def update(
        self,
        emotion_level: float,
        beats: list,
        narrative_tempo: float,
        continuity_bias: float = 0.0,
    ) -> float:
        """
        Parameters:
            emotion_level   : scalar from EmotionalArcModel
            beats           : list of detected beats
            narrative_tempo : continuity-conditioned tempo
            continuity_bias : signed bias from continuity tracker (-1..1)
        Returns:
            tension_level : scalar tension (0–1)
        """
        beat_density = len(beats)
        # Accumulation driven by emotion and tempo
        accumulate = (
            self.accumulation_rate *
            (0.6 * emotion_level + 0.4 * narrative_tempo) *
            (1.0 + 0.15 * beat_density)
        )
        # Release when emotion stabilizes or tempo drops
        release = (
            self.release_rate *
            max(0.0, 0.5 - narrative_tempo)
        )
        # Continuity bias encourages sustained tension across scenes
        accumulate += 0.05 * continuity_bias
        target = self._tension + accumulate - release
        # Inertia prevents jittery tension oscillation
        tension = (
            self.inertia * self._tension +
            (1.0 - self.inertia) * target
        )
        tension = self._clamp(
            tension,
            self.min_tension,
            self.max_tension,
        )
        self._tension = tension
        return tension
# ==============================================================================
# END OF CHUNK 85 A 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 A 06 — MICRO-BEAT ACCENTUATION
# ==============================================================================
#
# Purpose:
#   Enhances perceptually meaningful micro-beats within scenes
#   without creating artificial rhythm or over-editing.
#
#   Operates below macro-beat level but above subliminal noise.
#
# Cinematic Motivation:
#   Human editors subtly emphasize micro-moments (eye flicks,
#   camera inertia changes, tonal pivots) to add polish and intent.
#
# ==============================================================================

import numpy as np


class MicroBeatAccentuationEngine:
    """
    Applies controlled accentuation to micro-beats while
    respecting narrative tension and emotional arc.
    """
    def __init__(
        self,
        accent_strength: float = 0.18,
        decay_rate: float = 0.22,
        max_boost: float = 0.35,
        tempo_sensitivity: float = 0.4,
    ):
        self.accent_strength = accent_strength
        self.decay_rate = decay_rate
        self.max_boost = max_boost
        self.tempo_sensitivity = tempo_sensitivity
        self._residual_accent = 0.0
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(
        self,
        beats: list,
        narrative_tempo: float,
        tension_level: float,
    ) -> float:
        """
        Parameters:
            beats            : list of beat dicts
            narrative_tempo  : scalar tempo
            tension_level    : current narrative tension
        Returns:
            accent_signal : scalar accent modulation (0–1)
        """
        accent = self._residual_accent * (1.0 - self.decay_rate)
        for beat in beats:
            if beat["type"] == "kinetic":
                local_boost = 0.6
            elif beat["type"] == "emotional":
                local_boost = 0.9
            else:  # impact
                local_boost = 1.0
            tempo_factor = 1.0 + self.tempo_sensitivity * narrative_tempo
            tension_gate = 1.0 - 0.4 * tension_level
            accent += (
                self.accent_strength *
                beat["strength"] *
                local_boost *
                tempo_factor *
                tension_gate
            )
        accent = self._clamp(accent, 0.0, self.max_boost)
        self._residual_accent = accent
        return accent
# ==============================================================================
# END OF CHUNK 85 A 06
# ==============================================================================
# ==============================================================================
# CHUNK 85 A 07 — PACING DRIFT COMPENSATION
# ==============================================================================
#
# Purpose:
#   Detects and corrects long-term pacing drift caused by cumulative
#   micro-adjustments, beat clustering, or emotional inertia.
#
#   Ensures narrative tempo remains aligned with editorial intent.
#
# Cinematic Motivation:
#   Films that slowly drift in pacing feel “off” even if no single
#   cut is wrong. Editors subconsciously correct this over time.
#
# ==============================================================================

import numpy as np


class PacingDriftCompensator:
    """
    Monitors tempo evolution and applies corrective bias to
    prevent slow pacing drift.
    """
    def __init__(
        self,
        reference_tempo: float = 0.5,
        drift_threshold: float = 0.08,
        correction_strength: float = 0.22,
        memory_window: int = 40,
    ):
        self.reference_tempo = reference_tempo
        self.drift_threshold = drift_threshold
        self.correction_strength = correction_strength
        self.memory_window = memory_window
        self._tempo_history = []
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _update_history(self, tempo: float):
        self._tempo_history.append(tempo)
        if len(self._tempo_history) > self.memory_window:
            self._tempo_history.pop(0)
    def _drift(self) -> float:
        if not self._tempo_history:
            return 0.0
        return float(
            np.mean(self._tempo_history) - self.reference_tempo
        )
    def apply(
        self,
        narrative_tempo: float,
    ) -> float:
        """
        Parameters:
            narrative_tempo : tempo after continuity conditioning
        Returns:
            corrected_tempo : drift-compensated tempo
        """
        self._update_history(narrative_tempo)
        drift = self._drift()
        if abs(drift) < self.drift_threshold:
            return narrative_tempo
        correction = (
            -self.correction_strength *
            np.sign(drift) *
            (abs(drift) - self.drift_threshold)
        )
        corrected = narrative_tempo + correction
        corrected = self._clamp(corrected)
        return corrected
# ==============================================================================
# END OF CHUNK 85 A 07
# ==============================================================================
# ==============================================================================
# CHUNK 85 A 08 — NARRATIVE NOISE INJECTION
# ==============================================================================
#
# Purpose:
#   Injects controlled, perceptible variability into narrative pacing
#   and emotional flow to prevent algorithmic rigidity.
#
#   This is NOT subliminal noise — it operates at editor-visible scale.
#
# Cinematic Motivation:
#   Perfectly smooth pacing feels artificial. Human editors introduce
#   subtle irregularity to preserve organic flow.
#
# ==============================================================================

import numpy as np


class NarrativeNoiseInjector:
    """
    Applies bounded stochastic variation to narrative signals,
    gated by tension and tempo to avoid chaos.
    """
    def __init__(
        self,
        noise_strength: float = 0.04,
        max_deviation: float = 0.07,
        tension_gate: float = 0.65,
        temporal_smooth: float = 0.78,
        seed: int | None = None,
    ):
        self.noise_strength = noise_strength
        self.max_deviation = max_deviation
        self.tension_gate = tension_gate
        self.temporal_smooth = temporal_smooth
        self._rng = np.random.default_rng(seed)
        self._prev_noise = 0.0
    @staticmethod
    def _clamp(v: float, lo: float = -1.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(
        self,
        base_value: float,
        tension_level: float,
        narrative_tempo: float,
    ) -> float:
        """
        Parameters:
            base_value      : narrative signal to perturb (0–1)
            tension_level   : current narrative tension (0–1)
            narrative_tempo : current tempo (0–1)
        Returns:
            perturbed_value : organically varied signal
        """
        # High tension suppresses noise
        if tension_level > self.tension_gate:
            return base_value
        # Tempo-scaled stochastic variation
        raw_noise = self._rng.normal(
            loc=0.0,
            scale=self.noise_strength * (0.5 + 0.5 * narrative_tempo),
        )
        raw_noise = self._clamp(
            raw_noise,
            -self.max_deviation,
            self.max_deviation,
        )
        # Temporal smoothing prevents jitter
        noise = (
            self.temporal_smooth * self._prev_noise +
            (1.0 - self.temporal_smooth) * raw_noise
        )
        self._prev_noise = noise
        perturbed = base_value + noise
        return float(np.clip(perturbed, 0.0, 1.0))
# ==============================================================================
# END OF CHUNK 85 A 08
# ==============================================================================
# ==============================================================================
# CHUNK 85 A 10 — RHYTHM OUTPUT CONDITIONING
# ==============================================================================
#
# Purpose:
#   Final conditioning and normalization of narrative rhythm signals
#   before they propagate to downstream cinematic systems
#   (framing, exposure dynamics, cut timing, motion emphasis).
#
#   Acts as the authoritative “editor lock” for rhythm.
#
# Cinematic Motivation:
#   Even well-modeled rhythm must be constrained into a clean,
#   predictable output envelope to avoid emergent instability.
#
# ==============================================================================

import numpy as np


class RhythmOutputConditioner:
    """
    Conditions, clamps, and stabilizes final narrative rhythm outputs.
    """
    def __init__(
        self,
        smoothing: float = 0.82,
        min_output: float = 0.15,
        max_output: float = 0.85,
        deadzone: float = 0.01,
    ):
        self.smoothing = smoothing
        self.min_output = min_output
        self.max_output = max_output
        self.deadzone = deadzone
        self._prev_output = None
    @staticmethod
    def _clamp(v: float, lo: float, hi: float) -> float:
        return float(np.clip(v, lo, hi))
    def condition(
        self,
        tempo: float,
        tension: float,
        emotion: float,
        accent: float,
    ) -> float:
        """
        Parameters:
            tempo   : narrative tempo (0–1)
            tension : narrative tension (0–1)
            emotion : emotional arc level (0–1)
            accent  : micro-beat accentuation (0–1)
        Returns:
            rhythm_output : final conditioned rhythm scalar (0–1)
        """
        # Weighted fusion (editorially tuned)
        raw = (
            0.38 * tempo +
            0.32 * tension +
            0.22 * emotion +
            0.08 * accent
        )
        raw = self._clamp(raw, self.min_output, self.max_output)
        # Deadzone to prevent micro-jitter
        if self._prev_output is not None:
            if abs(raw - self._prev_output) < self.deadzone:
                raw = self._prev_output
        # Temporal smoothing (editor lock)
        if self._prev_output is None:
            output = raw
        else:
            output = (
                self.smoothing * self._prev_output +
                (1.0 - self.smoothing) * raw
            )
        output = self._clamp(output, 0.0, 1.0)
        self._prev_output = output
        return output
# ==============================================================================
# END OF CHUNK 85 A 10
# ==============================================================================
# ==============================================================================
# CHUNK 85 B 01 — CROSS-SEQUENCE RHYTHM HARMONIZATION
# ==============================================================================
#
# Purpose:
#   Aligns narrative rhythm across adjacent sequences to prevent
#   perceptual discontinuity when transitioning between acts or locations.
#
#   Operates above scene-level continuity and below act-level pacing.
#
# Cinematic Motivation:
#   Feature films maintain rhythmic coherence even when cutting
#   between radically different visual or emotional environments.
#
# ==============================================================================

import numpy as np


class CrossSequenceRhythmHarmonizer:
    """
    Harmonizes rhythm across sequences using adaptive anchoring.
    """
    def __init__(
        self,
        harmony_strength: float = 0.48,
        max_offset: float = 0.18,
        memory_size: int = 6,
    ):
        self.harmony_strength = harmony_strength
        self.max_offset = max_offset
        self.memory_size = memory_size
        self._sequence_memory = []
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _update_memory(self, rhythm: float):
        self._sequence_memory.append(rhythm)
        if len(self._sequence_memory) > self.memory_size:
            self._sequence_memory.pop(0)
    def _anchor(self) -> float:
        if not self._sequence_memory:
            return None
        return float(np.mean(self._sequence_memory))
    def harmonize(
        self,
        current_rhythm: float,
        transition_strength: float,
    ) -> float:
        """
        Parameters:
            current_rhythm      : rhythm from previous stage (0–1)
            transition_strength : cut/transition intensity (0–1)
        Returns:
            harmonized_rhythm : cross-sequence stabilized rhythm
        """
        anchor = self._anchor()
        if anchor is None:
            self._update_memory(current_rhythm)
            return current_rhythm
        blend = (
            self.harmony_strength *
            (1.0 - transition_strength)
        )
        offset = current_rhythm - anchor
        offset = np.clip(offset, -self.max_offset, self.max_offset)
        harmonized = (
            blend * (anchor + offset) +
            (1.0 - blend) * current_rhythm
        )
        harmonized = self._clamp(harmonized)
        self._update_memory(harmonized)
        return harmonized
# ==============================================================================
# END OF CHUNK 85 B 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 B 02 — LONG-RANGE TEMPO COHERENCE
# ==============================================================================
#
# Purpose:
#   Enforces coherence of narrative tempo over long temporal horizons
#   (minutes to acts), preventing gradual divergence from story intent.
#
#   Operates above sequence harmonization and below act-level alignment.
#
# Cinematic Motivation:
#   Audiences sense when a film “loses its rhythm” over time even if
#   individual scenes feel correct. This layer prevents that decay.
#
# ==============================================================================

import numpy as np


class LongRangeTempoCoherence:
    """
    Maintains tempo coherence over extended durations using
    adaptive anchoring and slow corrective bias.
    """
    def __init__(
        self,
        coherence_strength: float = 0.36,
        correction_rate: float = 0.04,
        max_correction: float = 0.12,
        horizon: int = 120,
    ):
        self.coherence_strength = coherence_strength
        self.correction_rate = correction_rate
        self.max_correction = max_correction
        self.horizon = horizon
        self._tempo_history = []
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _update_history(self, tempo: float):
        self._tempo_history.append(tempo)
        if len(self._tempo_history) > self.horizon:
            self._tempo_history.pop(0)
    def _long_anchor(self) -> float | None:
        if len(self._tempo_history) < self.horizon // 3:
            return None
        return float(np.mean(self._tempo_history))
    def apply(
        self,
        current_tempo: float,
        narrative_phase_weight: float = 1.0,
    ) -> float:
        """
        Parameters:
            current_tempo          : tempo from previous stage (0–1)
            narrative_phase_weight : importance of coherence (0–1)
        Returns:
            coherent_tempo : long-range stabilized tempo
        """
        self._update_history(current_tempo)
        anchor = self._long_anchor()
        if anchor is None:
            return current_tempo
        deviation = current_tempo - anchor
        correction = (
            -self.correction_rate *
            narrative_phase_weight *
            deviation
        )
        correction = np.clip(
            correction,
            -self.max_correction,
            self.max_correction,
        )
        coherent = (
            self.coherence_strength * (current_tempo + correction) +
            (1.0 - self.coherence_strength) * current_tempo
        )
        coherent = self._clamp(coherent)
        return coherent
# ==============================================================================
# END OF CHUNK 85 B 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 B 03 — MULTI-ACT PACING ALIGNMENT
# ==============================================================================
#
# Purpose:
#   Aligns pacing behavior across cinematic acts (Act I / II / III)
#   ensuring that tempo evolution follows classical narrative dynamics.
#
#   Prevents mid-film pacing inversion (e.g. Act II feeling faster
#   than climax, or Act I feeling rushed).
#
# Cinematic Motivation:
#   Top-tier films exhibit controlled tempo escalation across acts,
#   even when local scene rhythm fluctuates.
#
# ==============================================================================

import numpy as np


class MultiActPacingAligner:
    """
    Enforces act-based pacing envelopes using adaptive tempo shaping.
    """
    def __init__(
        self,
        act_profiles: dict | None = None,
        alignment_strength: float = 0.52,
        max_act_pull: float = 0.20,
    ):
        if act_profiles is None:
            # Classical three-act envelope
            act_profiles = {
0.38,  # Act I: setup
0.55,  # Act II: development
0.72,  # Act III: climax
            }
        self.act_profiles = act_profiles
        self.alignment_strength = alignment_strength
        self.max_act_pull = max_act_pull
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def align(
        self,
        current_tempo: float,
        act_index: int,
        act_progress: float,
    ) -> float:
        """
        Parameters:
            current_tempo : incoming tempo (0–1)
            act_index     : current act number (1, 2, 3…)
            act_progress  : progress within act (0–1)
        Returns:
            aligned_tempo : tempo aligned to act envelope
        """
        target = self.act_profiles.get(
            act_index,
            np.mean(list(self.act_profiles.values())),
        )
        # Progressive influence increases deeper into act
        influence = (
            self.alignment_strength *
            np.clip(act_progress, 0.0, 1.0)
        )
        delta = target - current_tempo
        delta = np.clip(delta, -self.max_act_pull, self.max_act_pull)
        aligned = (
            (1.0 - influence) * current_tempo +
            influence * (current_tempo + delta)
        )
        return self._clamp(aligned)
# ==============================================================================
# END OF CHUNK 85 B 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 B 04 — NARRATIVE PHASE LOCKING
# ==============================================================================
#
# Purpose:
#   Locks temporal rhythm to narrative phase boundaries such as:
#   setup → inciting → escalation → climax → resolution.
#
#   Prevents rhythm leakage across narrative phase transitions.
#
# Cinematic Motivation:
#   High-end films exhibit a perceptible “gear shift” at phase
#   boundaries without abrupt tempo discontinuities.
#
# ==============================================================================

import numpy as np


class NarrativePhaseLocker:
    """
    Stabilizes rhythm around narrative phase transitions.
    """
    def __init__(
        self,
        phase_targets: dict | None = None,
        lock_strength: float = 0.44,
        transition_window: float = 0.18,
    ):
        if phase_targets is None:
            phase_targets = {
                "setup": 0.32,
                "inciting": 0.40,
                "escalation": 0.55,
                "climax": 0.78,
                "resolution": 0.42,
            }
        self.phase_targets = phase_targets
        self.lock_strength = lock_strength
        self.transition_window = transition_window
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def lock(
        self,
        current_rhythm: float,
        phase: str,
        phase_progress: float,
    ) -> float:
        """
        Parameters:
            current_rhythm : rhythm input (0–1)
            phase          : narrative phase label
            phase_progress : progress within phase (0–1)
        Returns:
            locked_rhythm : phase-consistent rhythm
        """
        target = self.phase_targets.get(phase)
        if target is None:
            return current_rhythm
        # Only engage near phase boundary
        window = self.transition_window
        distance = min(phase_progress, 1.0 - phase_progress)
        if distance > window:
            return current_rhythm
        proximity = 1.0 - (distance / window)
        influence = self.lock_strength * proximity
        delta = target - current_rhythm
        locked = (
            (1.0 - influence) * current_rhythm +
            influence * (current_rhythm + delta)
        )
        return self._clamp(locked)
# ==============================================================================
# END OF CHUNK 85 B 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 B 05 — EDITORIAL RHYTHM OVERRIDES
# ==============================================================================
#
# Purpose:
#   Allows high-level editorial intent to override algorithmic rhythm
#   decisions in exceptional narrative or stylistic situations.
#
#   Designed to respect director-driven rhythm mandates while
#   maintaining system stability.
#
# Cinematic Motivation:
#   Even the most mathematically perfect rhythm must yield to
#   deliberate editorial choices in prestige cinema.
#
# ==============================================================================

import numpy as np


class EditorialRhythmOverride:
    """
    Applies bounded editorial overrides to rhythm computation.
    """
    def __init__(
        self,
        max_override: float = 0.25,
        override_blend: float = 0.62,
    ):
        self.max_override = max_override
        self.override_blend = override_blend
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(
        self,
        base_rhythm: float,
        editorial_target: float | None,
        authority: float = 1.0,
    ) -> float:
        """
        Parameters:
            base_rhythm      : rhythm from system (0–1)
            editorial_target : desired rhythm override (0–1 or None)
            authority        : override authority (0–1)
        Returns:
            overridden_rhythm : rhythm after editorial influence
        """
        if editorial_target is None:
            return base_rhythm
        authority = np.clip(authority, 0.0, 1.0)
        delta = editorial_target - base_rhythm
        delta = np.clip(delta, -self.max_override, self.max_override)
        influence = self.override_blend * authority
        overridden = (
            (1.0 - influence) * base_rhythm +
            influence * (base_rhythm + delta)
        )
        return self._clamp(overridden)
# ==============================================================================
# END OF CHUNK 85 B 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 B 06 — RHYTHM REGRESSION GUARD
# ==============================================================================
#
# Purpose:
#   Prevents backward drift in narrative rhythm once tempo escalation
#   has been earned by story progression.
#
#   Acts as a hysteresis layer against accidental de-escalation caused
#   by local scene softness or transient calm.
#
# Cinematic Motivation:
#   Prestige films do not “lose momentum” unless deliberately intended.
#   This guard preserves earned pacing authority.
#
# ==============================================================================

import numpy as np


class RhythmRegressionGuard:
    """
    Enforces non-regressive rhythm behavior with controlled forgiveness.
    """
    def __init__(
        self,
        tolerance: float = 0.06,
        recovery_rate: float = 0.18,
        forgiveness_window: int = 24,
    ):
        self.tolerance = tolerance
        self.recovery_rate = recovery_rate
        self.forgiveness_window = forgiveness_window
        self._peak_rhythm = None
        self._cooldown = 0
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(self, current_rhythm: float) -> float:
        """
        Parameters:
            current_rhythm : incoming rhythm value (0–1)
        Returns:
            guarded_rhythm : rhythm after regression protection
        """
        if self._peak_rhythm is None:
            self._peak_rhythm = current_rhythm
            return current_rhythm
        # Update peak rhythm
        if current_rhythm > self._peak_rhythm:
            self._peak_rhythm = current_rhythm
            self._cooldown = self.forgiveness_window
            return current_rhythm
        # Allow temporary softness
        if self._cooldown > 0:
            self._cooldown -= 1
            return current_rhythm
        # Prevent excessive regression
        min_allowed = self._peak_rhythm - self.tolerance
        if current_rhythm < min_allowed:
            correction = (
                self.recovery_rate *
                (min_allowed - current_rhythm)
            )
            current_rhythm += correction
        return self._clamp(current_rhythm)
# ==============================================================================
# END OF CHUNK 85 B 06
# ==============================================================================
# ==============================================================================
# CHUNK 85 B 07 — STRUCTURAL BEAT ANCHORS
# ==============================================================================
#
# Purpose:
#   Establishes fixed rhythmic anchor points (“beats”) within sequences
#   to stabilize pacing around key narrative or visual events.
#
#   These anchors resist drift and serve as reference points for
#   downstream rhythm modulation.
#
# Cinematic Motivation:
#   Major beats (reveals, impacts, emotional turns) carry a stable
#   temporal signature that audiences subconsciously lock onto.
#
# ==============================================================================

import numpy as np


class StructuralBeatAnchors:
    """
    Maintains and enforces rhythmic anchors across a sequence.
    """
    def __init__(
        self,
        anchor_strength: float = 0.58,
        anchor_tolerance: float = 0.10,
        max_pull: float = 0.22,
    ):
        self.anchor_strength = anchor_strength
        self.anchor_tolerance = anchor_tolerance
        self.max_pull = max_pull
        self._anchors = {}
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def register_anchor(
        self,
        anchor_id: str,
        rhythm_value: float,
    ):
        """
        Registers or updates a structural beat anchor.
        """
        self._anchors[anchor_id] = self._clamp(rhythm_value)
    def remove_anchor(self, anchor_id: str):
        if anchor_id in self._anchors:
            del self._anchors[anchor_id]
    def apply(
        self,
        current_rhythm: float,
        active_anchor: str | None,
        anchor_weight: float = 1.0,
    ) -> float:
        """
        Parameters:
            current_rhythm : incoming rhythm (0–1)
            active_anchor  : anchor identifier or None
            anchor_weight  : anchor influence (0–1)
        Returns:
            anchored_rhythm : rhythm stabilized around anchor
        """
        if active_anchor is None:
            return current_rhythm
        target = self._anchors.get(active_anchor)
        if target is None:
            return current_rhythm
        deviation = target - current_rhythm
        if abs(deviation) < self.anchor_tolerance:
            return current_rhythm
        pull = (
            self.anchor_strength *
            anchor_weight *
            np.clip(deviation, -self.max_pull, self.max_pull)
        )
        anchored = current_rhythm + pull
        return self._clamp(anchored)
# ==============================================================================
# END OF CHUNK 85 B 07
# ==============================================================================
# ==============================================================================
# CHUNK 85 B 08 — MACRO RHYTHM VARIANCE CONTROL
# ==============================================================================
#
# Purpose:
#   Controls excessive rhythmic variance across extended spans while
#   preserving intentional contrast between scenes.
#
#   Prevents erratic pacing patterns that feel unstable or amateur.
#
# Cinematic Motivation:
#   Elite films allow rhythm to breathe, but never to fluctuate wildly.
#   Variance is sculpted, not accidental.
#
# ==============================================================================

import numpy as np
from collections import deque


class MacroRhythmVarianceController:
    """
    Regulates long-horizon rhythm variance with adaptive damping.
    """
    def __init__(
        self,
        window: int = 96,
        variance_target: float = 0.018,
        damping_strength: float = 0.46,
        max_damping: float = 0.20,
    ):
        self.window = window
        self.variance_target = variance_target
        self.damping_strength = damping_strength
        self.max_damping = max_damping
        self._history = deque(maxlen=window)
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(self, current_rhythm: float) -> float:
        """
        Parameters:
            current_rhythm : incoming rhythm value (0–1)
        Returns:
            stabilized_rhythm : variance-controlled rhythm
        """
        self._history.append(current_rhythm)
        if len(self._history) < self.window // 2:
            return current_rhythm
        variance = np.var(self._history)
        excess = variance - self.variance_target
        if excess <= 0.0:
            return current_rhythm
        damping = (
            self.damping_strength *
            np.clip(excess / self.variance_target, 0.0, 1.0)
        )
        damping = np.clip(damping, 0.0, self.max_damping)
        mean = float(np.mean(self._history))
        stabilized = (
            (1.0 - damping) * current_rhythm +
            damping * mean
        )
        return self._clamp(stabilized)
# ==============================================================================
# END OF CHUNK 85 B 08
# ==============================================================================
# ==============================================================================
# CHUNK 85 B 10 — SEQUENCE RHYTHM OUTPUT BUS
# ==============================================================================
#
# Purpose:
#   Consolidates rhythm signals from all prior 85B controllers into a
#   single, stable output for downstream narrative, editing, and motion
#   systems.
#
#   Acts as the authoritative handoff point for sequence-level rhythm.
#
# Cinematic Motivation:
#   Top-tier pipelines expose one coherent rhythm signal—never a
#   conflicting set—ensuring editorial, motion, and grading systems
#   operate in lockstep.
#
# ==============================================================================

import numpy as np


class SequenceRhythmOutputBus:
    """
    Final aggregation and conditioning of sequence rhythm.
    """
    def __init__(
        self,
        smoothing: float = 0.42,
        snap_tolerance: float = 0.05,
        confidence_gain: float = 0.65,
    ):
        self.smoothing = smoothing
        self.snap_tolerance = snap_tolerance
        self.confidence_gain = confidence_gain
        self._prev_output = None
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def emit(
        self,
        rhythm_signal: float,
        confidence: float = 1.0,
    ) -> float:
        """
        Parameters:
            rhythm_signal : aggregated rhythm input (0–1)
            confidence    : system confidence weight (0–1)
        Returns:
            output_rhythm : stabilized sequence rhythm output
        """
        rhythm_signal = self._clamp(rhythm_signal)
        confidence = np.clip(confidence, 0.0, 1.0)
        if self._prev_output is None:
            self._prev_output = rhythm_signal
            return rhythm_signal
        # Confidence-weighted smoothing
        alpha = self.smoothing * (self.confidence_gain * confidence)
        smoothed = (
            (1.0 - alpha) * self._prev_output +
            alpha * rhythm_signal
        )
        # Snap if close enough to prevent micro-jitter
        if abs(smoothed - rhythm_signal) < self.snap_tolerance:
            smoothed = rhythm_signal
        smoothed = self._clamp(smoothed)
        self._prev_output = smoothed
        return smoothed
# ==============================================================================
# END OF CHUNK 85 B 10
# ==============================================================================
# ==============================================================================
# CHUNK 85 C 01 — ACT-TO-ACT TEMPORAL HANDOFF
# ==============================================================================
#
# Purpose:
#   Manages rhythm continuity when transitioning between cinematic acts,
#   ensuring momentum transfer without perceptual discontinuity.
#
#   Prevents abrupt tempo resets or artificial acceleration at act
#   boundaries.
#
# Cinematic Motivation:
#   In top-tier films, act transitions feel inevitable—not mechanical.
#   Rhythm flows forward even as narrative stakes change.
#
# ==============================================================================

import numpy as np


class ActToActTemporalHandoff:
    """
    Handles controlled rhythm handoff across act boundaries.
    """
    def __init__(
        self,
        handoff_strength: float = 0.54,
        decay_rate: float = 0.22,
        max_delta: float = 0.18,
        settle_window: int = 12,
    ):
        self.handoff_strength = handoff_strength
        self.decay_rate = decay_rate
        self.max_delta = max_delta
        self.settle_window = settle_window
        self._handoff_buffer = []
        self._frames_since_handoff = 0
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def notify_act_transition(self, outgoing_rhythm: float):
        """
        Called once at act boundary to seed handoff state.
        """
        self._handoff_buffer = [self._clamp(outgoing_rhythm)]
        self._frames_since_handoff = 0
    def apply(
        self,
        incoming_rhythm: float,
        is_new_act: bool,
    ) -> float:
        """
        Parameters:
            incoming_rhythm : rhythm computed for new act (0–1)
            is_new_act       : True during initial act transition window
        Returns:
            handed_rhythm : rhythm after act handoff conditioning
        """
        incoming_rhythm = self._clamp(incoming_rhythm)
        if not is_new_act or not self._handoff_buffer:
            return incoming_rhythm
        anchor = float(np.mean(self._handoff_buffer))
        delta = incoming_rhythm - anchor
        delta = np.clip(delta, -self.max_delta, self.max_delta)
        blend = (
            self.handoff_strength *
            np.exp(-self.decay_rate * self._frames_since_handoff)
        )
        handed = (
            (1.0 - blend) * incoming_rhythm +
            blend * (anchor + delta)
        )
        handed = self._clamp(handed)
        self._handoff_buffer.append(handed)
        if len(self._handoff_buffer) > self.settle_window:
            self._handoff_buffer.pop(0)
        self._frames_since_handoff += 1
        return handed
# ==============================================================================
# END OF CHUNK 85 C 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 C 02 — GLOBAL NARRATIVE TEMPO ENVELOPE
# ==============================================================================
#
# Purpose:
#   Defines and enforces the high-level tempo arc of the entire film or
#   long-form sequence, independent of local scene fluctuations.
#
#   Serves as the “spine” against which all rhythm layers are validated.
#
# Cinematic Motivation:
#   World-class films follow a clear tempo arc—slow ignition, controlled
#   escalation, decisive climax, and intentional release.
#
# ==============================================================================

import numpy as np


class GlobalNarrativeTempoEnvelope:
    """
    Enforces a long-horizon tempo envelope across the full narrative.
    """
    def __init__(
        self,
        envelope_points: list | None = None,
        enforcement_strength: float = 0.48,
        max_pull: float = 0.22,
    ):
        if envelope_points is None:
            # (progress, tempo) pairs across full narrative
            envelope_points = [
                (0.00, 0.30),  # opening
                (0.20, 0.42),
                (0.45, 0.55),
                (0.70, 0.72),  # climax
                (0.90, 0.48),
                (1.00, 0.38),  # resolution
            ]
        self.envelope_points = sorted(envelope_points)
        self.enforcement_strength = enforcement_strength
        self.max_pull = max_pull
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _interpolate(self, progress: float) -> float:
        for i in range(len(self.envelope_points) - 1):
            p0, t0 = self.envelope_points[i]
            p1, t1 = self.envelope_points[i + 1]
            if p0 <= progress <= p1:
                w = (progress - p0) / max(p1 - p0, 1e-6)
                return (1.0 - w) * t0 + w * t1
        return self.envelope_points[-1][1]
    def apply(
        self,
        current_tempo: float,
        narrative_progress: float,
    ) -> float:
        """
        Parameters:
            current_tempo       : incoming tempo (0–1)
            narrative_progress  : full-story progress (0–1)
        Returns:
            enveloped_tempo : tempo aligned to narrative arc
        """
        target = self._interpolate(
            np.clip(narrative_progress, 0.0, 1.0)
        )
        delta = target - current_tempo
        delta = np.clip(delta, -self.max_pull, self.max_pull)
        aligned = (
            (1.0 - self.enforcement_strength) * current_tempo +
            self.enforcement_strength * (current_tempo + delta)
        )
        return self._clamp(aligned)
# ==============================================================================
# END OF CHUNK 85 C 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 C 03 — INTER-SEQUENCE TEMPORAL CONTINUITY
# ==============================================================================
#
# Purpose:
#   Maintains temporal continuity across adjacent sequences so that
#   pacing evolution feels intentional rather than episodic.
#
#   Bridges rhythm state between sequences inside the same act.
#
# Cinematic Motivation:
#   Elite films avoid “resetting” tempo when cutting between locations
#   or subplots. Momentum is preserved across boundaries.
#
# ==============================================================================

import numpy as np


class InterSequenceTemporalContinuity:
    """
    Smooths rhythm transitions between neighboring sequences.
    """
    def __init__(
        self,
        continuity_strength: float = 0.46,
        max_adjustment: float = 0.16,
        memory: int = 8,
    ):
        self.continuity_strength = continuity_strength
        self.max_adjustment = max_adjustment
        self.memory = memory
        self._recent_sequences = []
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _anchor(self) -> float | None:
        if not self._recent_sequences:
            return None
        return float(np.mean(self._recent_sequences))
    def register_sequence_end(self, final_rhythm: float):
        """
        Called at the end of a sequence to store its terminal rhythm.
        """
        self._recent_sequences.append(self._clamp(final_rhythm))
        if len(self._recent_sequences) > self.memory:
            self._recent_sequences.pop(0)
    def apply(
        self,
        incoming_rhythm: float,
    ) -> float:
        """
        Parameters:
            incoming_rhythm : initial rhythm of new sequence (0–1)
        Returns:
            continuous_rhythm : continuity-corrected rhythm
        """
        incoming_rhythm = self._clamp(incoming_rhythm)
        anchor = self._anchor()
        if anchor is None:
            return incoming_rhythm
        delta = anchor - incoming_rhythm
        delta = np.clip(delta, -self.max_adjustment, self.max_adjustment)
        corrected = (
            (1.0 - self.continuity_strength) * incoming_rhythm +
            self.continuity_strength * (incoming_rhythm + delta)
        )
        return self._clamp(corrected)
# ==============================================================================
# END OF CHUNK 85 C 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 C 04 — NARRATIVE ENERGY CONSERVATION
# ==============================================================================
#
# Purpose:
#   Enforces conservation of narrative energy across time, preventing
#   artificial energy creation or loss caused by local rhythm noise.
#
#   Ensures that pacing “energy” can only be transferred or transformed,
#   not spontaneously amplified or destroyed.
#
# Cinematic Motivation:
#   In elite cinema, energy is carefully accumulated and released.
#   Sudden unexplained pacing spikes feel amateur and break immersion.
#
# ==============================================================================

import numpy as np
from collections import deque


class NarrativeEnergyConservation:
    """
    Conserves narrative pacing energy over extended temporal windows.
    """
    def __init__(
        self,
        window: int = 64,
        max_energy_gain: float = 0.15,
        max_energy_loss: float = 0.18,
        redistribution_rate: float = 0.22,
    ):
        self.window = window
        self.max_energy_gain = max_energy_gain
        self.max_energy_loss = max_energy_loss
        self.redistribution_rate = redistribution_rate
        self._energy_history = deque(maxlen=window)
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(
        self,
        current_rhythm: float,
    ) -> float:
        """
        Parameters:
            current_rhythm : incoming rhythm value (0–1)
        Returns:
            conserved_rhythm : energy-conserved rhythm
        """
        current_rhythm = self._clamp(current_rhythm)
        self._energy_history.append(current_rhythm)
        if len(self._energy_history) < self.window:
            return current_rhythm
        avg_energy = float(np.mean(self._energy_history))
        delta = current_rhythm - avg_energy
        # Limit spontaneous energy gain
        if delta > self.max_energy_gain:
            current_rhythm = (
                avg_energy +
                self.max_energy_gain
            )
        # Limit excessive energy loss
        elif delta < -self.max_energy_loss:
            current_rhythm = (
                avg_energy -
                self.max_energy_loss
            )
        # Gentle redistribution toward equilibrium
        redistributed = (
            (1.0 - self.redistribution_rate) * current_rhythm +
            self.redistribution_rate * avg_energy
        )
        return self._clamp(redistributed)
# ==============================================================================
# END OF CHUNK 85 C 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 C 05 — MACRO EMOTIONAL MOMENTUM
# ==============================================================================
#
# Purpose:
#   Models large-scale emotional momentum across extended narrative spans.
#   Prevents abrupt emotional reversals unless narratively justified.
#
#   Acts as a low-frequency emotional integrator layered above raw rhythm.
#
# Cinematic Motivation:
#   High-end cinema maintains emotional directionality.
#   Momentum may slow or accelerate, but rarely inverts instantly.
#
# ==============================================================================

import numpy as np
from collections import deque


class MacroEmotionalMomentum:
    """
    Tracks and stabilizes emotional momentum across long horizons.
    """
    def __init__(
        self,
        horizon: int = 180,
        momentum_strength: float = 0.62,
        reversal_resistance: float = 0.48,
        max_emotional_slope: float = 0.012,
    ):
        self.horizon = horizon
        self.momentum_strength = momentum_strength
        self.reversal_resistance = reversal_resistance
        self.max_emotional_slope = max_emotional_slope
        self._history = deque(maxlen=horizon)
        self._momentum = 0.0
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _estimate_trend(self) -> float:
        if len(self._history) < 2:
            return 0.0
        x = np.arange(len(self._history))
        y = np.array(self._history)
        slope, _ = np.polyfit(x, y, 1)
        return float(slope)
    def apply(
        self,
        rhythm: float,
    ) -> float:
        """
        Parameters:
            rhythm : incoming rhythm value (0–1)
        Returns:
            momentum_adjusted_rhythm : emotionally coherent rhythm
        """
        rhythm = self._clamp(rhythm)
        self._history.append(rhythm)
        trend = self._estimate_trend()
        trend = np.clip(trend, -self.max_emotional_slope, self.max_emotional_slope)
        # Update momentum integrator
        self._momentum = (
            (1.0 - self.momentum_strength) * self._momentum +
            self.momentum_strength * trend
        )
        proposed = rhythm + self._momentum
        # Resist emotional reversals
        reversal = np.sign(self._momentum) != np.sign(trend)
        if reversal:
            proposed = (
                rhythm +
                self.reversal_resistance * self._momentum
            )
        return self._clamp(proposed)
# ==============================================================================
# END OF CHUNK 85 C 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 C 06 — TEMPORAL AUTHORITY ARBITRATION
# ==============================================================================
#
# Purpose:
#   Arbitrates between competing temporal controllers (rhythm, energy,
#   momentum, continuity) to determine final authoritative pacing.
#
#   Prevents over-dominance of any single controller during conflicts.
#
# Cinematic Motivation:
#   Real films balance multiple pacing forces simultaneously.
#   This module acts as the “editor’s judgment” layer.
#
# ==============================================================================

import numpy as np
from typing import Dict


class TemporalAuthorityArbitration:
    """
    Resolves conflicts between multiple temporal control signals.
    """
    def __init__(
        self,
        weights: Dict[str, float] | None = None,
        dominance_limit: float = 0.42,
        smoothing: float = 0.35,
    ):
        # Default controller weights
        self.weights = weights or {
            "base": 1.0,
            "continuity": 0.9,
            "energy": 0.85,
            "momentum": 0.95,
        }
        self.dominance_limit = dominance_limit
        self.smoothing = smoothing
        self._last_output = None
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _normalize_weights(self):
        total = sum(self.weights.values())
        if total <= 0.0:
            return
        for k in self.weights:
            self.weights[k] /= total
    def apply(
        self,
        signals: Dict[str, float],
    ) -> float:
        """
        Parameters:
            signals : dict of named temporal signals (0–1)
        Returns:
            authoritative_rhythm : final arbitrated rhythm
        """
        self._normalize_weights()
        weighted = {}
        for k, v in signals.items():
            w = self.weights.get(k, 0.0)
            weighted[k] = w * self._clamp(v)
        total = sum(weighted.values())
        if total <= 0.0:
            return self._last_output or 0.0
        # Prevent dominance by a single controller
        for k in weighted:
            weighted[k] = min(weighted[k], self.dominance_limit * total)
        combined = sum(weighted.values()) / sum(self.weights.values())
        # Temporal smoothing (editorial inertia)
        if self._last_output is not None:
            combined = (
                (1.0 - self.smoothing) * combined +
                self.smoothing * self._last_output
            )
        combined = self._clamp(combined)
        self._last_output = combined
        return combined
# ==============================================================================
# END OF CHUNK 85 C 06
# ==============================================================================
# ==============================================================================
# CHUNK 85 C 07 — ACT BOUNDARY SHOCK ABSORPTION
# ==============================================================================
#
# Purpose:
#   Dampens abrupt rhythm discontinuities at act boundaries.
#
#   Allows decisive act transitions while preventing perceptual
#   “tempo whiplash” that breaks cinematic immersion.
#
# Cinematic Motivation:
#   Top-tier films shift pacing between acts deliberately, but
#   transitions are eased through editorial buffering.
#
# ==============================================================================

import numpy as np


class ActBoundaryShockAbsorption:
    """
    Absorbs pacing shocks occurring at act boundaries.
    """
    def __init__(
        self,
        absorption_strength: float = 0.68,
        max_delta: float = 0.22,
        decay: float = 0.18,
    ):
        self.absorption_strength = absorption_strength
        self.max_delta = max_delta
        self.decay = decay
        self._residual = 0.0
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(
        self,
        previous_rhythm: float,
        incoming_rhythm: float,
        is_act_boundary: bool,
    ) -> float:
        """
        Parameters:
            previous_rhythm : rhythm at end of previous act (0–1)
            incoming_rhythm : rhythm at start of new act (0–1)
            is_act_boundary : True if transition crosses act boundary
        Returns:
            absorbed_rhythm : shock-absorbed rhythm value
        """
        previous_rhythm = self._clamp(previous_rhythm)
        incoming_rhythm = self._clamp(incoming_rhythm)
        if not is_act_boundary:
            # Residual energy decays naturally
            self._residual *= (1.0 - self.decay)
            return incoming_rhythm
        delta = incoming_rhythm - previous_rhythm
        delta = np.clip(delta, -self.max_delta, self.max_delta)
        absorbed_delta = (
            (1.0 - self.absorption_strength) * delta
        )
        # Store absorbed energy to release gradually
        self._residual += delta - absorbed_delta
        output = previous_rhythm + absorbed_delta
        output += self._residual * self.decay
        return self._clamp(output)
# ==============================================================================
# END OF CHUNK 85 C 07
# ==============================================================================
# ==============================================================================
# CHUNK 85 C 08 — LONG-HORIZON RHYTHM MEMORY
# ==============================================================================
#
# Purpose:
#   Maintains a persistent memory of long-term pacing history
#   across acts and major narrative sections.
#
#   Allows the system to "remember" how fast or slow the story
#   has felt over extended durations and compensate accordingly.
#
# Cinematic Motivation:
#   Great films exhibit subconscious rhythm awareness —
#   later sections respond to earlier pacing without repeating it.
#
# ==============================================================================

import numpy as np
from collections import deque


class LongHorizonRhythmMemory:
    """
    Stores and leverages long-term pacing memory.
    """
    def __init__(
        self,
        horizon: int = 720,
        influence: float = 0.38,
        decay: float = 0.004,
        max_bias: float = 0.12,
    ):
        self.horizon = horizon
        self.influence = influence
        self.decay = decay
        self.max_bias = max_bias
        self._memory = deque(maxlen=horizon)
        self._bias = 0.0
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _compute_memory_average(self) -> float:
        if not self._memory:
            return 0.0
        return float(np.mean(self._memory))
    def update(self, rhythm: float):
        """
        Registers rhythm into long-term memory.
        """
        rhythm = self._clamp(rhythm)
        self._memory.append(rhythm)
    def apply(
        self,
        rhythm: float,
    ) -> float:
        """
        Parameters:
            rhythm : incoming rhythm value (0–1)
        Returns:
            memory_adjusted_rhythm : rhythm influenced by long-horizon memory
        """
        rhythm = self._clamp(rhythm)
        avg = self._compute_memory_average()
        deviation = rhythm - avg
        # Slowly decay historical bias
        self._bias *= (1.0 - self.decay)
        # Update bias based on deviation
        self._bias += deviation * self.influence
        self._bias = np.clip(self._bias, -self.max_bias, self.max_bias)
        adjusted = rhythm - self._bias
        return self._clamp(adjusted)
# ==============================================================================
# END OF CHUNK 85 C 08
# ==============================================================================
# ==============================================================================
# CHUNK 85 C 10 — ACT RHYTHM OUTPUT INTERFACE
# ==============================================================================
#
# Purpose:
#   Defines the canonical interface for emitting the final,
#   authoritative rhythm signal for an act.
#
#   This is the single point of convergence for all upstream
#   temporal logic and guarantees stable downstream consumption.
#
# Cinematic Motivation:
#   In real post-production pipelines, all pacing decisions
#   ultimately collapse into one authoritative timing intent.
#
# ==============================================================================

import numpy as np
from typing import Dict, Any


class ActRhythmOutputInterface:
    """
    Final authoritative rhythm emitter for an act.
    """
    def __init__(
        self,
        quantization: float = 0.0025,
        stability_smoothing: float = 0.22,
    ):
        self.quantization = quantization
        self.stability_smoothing = stability_smoothing
        self._last_output = None
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _quantize(self, v: float) -> float:
        if self.quantization <= 0.0:
            return v
        return round(v / self.quantization) * self.quantization
    def emit(
        self,
        rhythm: float,
        metadata: Dict[str, Any] | None = None,
    ) -> Dict[str, Any]:
        """
        Parameters:
            rhythm   : final rhythm value (0–1)
            metadata : optional diagnostic/contextual info
        Returns:
            payload : structured rhythm output
        """
        rhythm = self._clamp(rhythm)
        rhythm = self._quantize(rhythm)
        if self._last_output is not None:
            rhythm = (
                (1.0 - self.stability_smoothing) * rhythm +
                self.stability_smoothing * self._last_output
            )
        rhythm = self._clamp(rhythm)
        self._last_output = rhythm
        return {
            "act_rhythm": rhythm,
            "confidence": 1.0 - abs(rhythm - (self._last_output or rhythm)),
            "meta": metadata or {},
        }
# ==============================================================================
# END OF CHUNK 85 C 10
# ==============================================================================
# ==============================================================================
# CHUNK 85 D 01 — TEMPORAL TENSION ACCUMULATION
# ==============================================================================
#
# Purpose:
#   Accumulates narrative tension over time based on sustained rhythm,
#   preventing premature release and enabling controlled escalation.
#
#   Acts as a cinematic “pressure vessel” for pacing energy.
#
# Cinematic Motivation:
#   High-end films do not spike tension randomly; they build it
#   gradually, storing unresolved energy until release is earned.
#
# ==============================================================================

import numpy as np


class TemporalTensionAccumulation:
    """
    Accumulates and regulates narrative tension over time.
    """
    def __init__(
        self,
        accumulation_rate: float = 0.018,
        saturation_level: float = 0.92,
        leakage: float = 0.006,
        sensitivity: float = 1.15,
    ):
        self.accumulation_rate = accumulation_rate
        self.saturation_level = saturation_level
        self.leakage = leakage
        self.sensitivity = sensitivity
        self._tension = 0.0
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(
        self,
        rhythm: float,
    ) -> float:
        """
        Parameters:
            rhythm : authoritative rhythm value (0–1)
        Returns:
            tension : accumulated narrative tension (0–1)
        """
        rhythm = self._clamp(rhythm)
        drive = max(0.0, rhythm - 0.5) * self.sensitivity
        # Accumulate tension
        self._tension += drive * self.accumulation_rate
        # Natural leakage prevents infinite buildup
        self._tension *= (1.0 - self.leakage)
        # Saturation clamp
        self._tension = min(self._tension, self.saturation_level)
        return self._clamp(self._tension)
# ==============================================================================
# END OF CHUNK 85 D 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 D 02 — RELEASE ANTICIPATION CURVE
# ==============================================================================
#
# Purpose:
#   Shapes the audience’s anticipation of tension release by biasing
#   pacing as accumulated tension approaches a release threshold.
#
#   Prevents premature payoff and enables deliberate “hold” before release.
#
# Cinematic Motivation:
#   Elite films stretch anticipation right before payoff, creating
#   heightened emotional impact without increasing raw action.
#
# ==============================================================================

import numpy as np


class ReleaseAnticipationCurve:
    """
    Biases rhythm to heighten anticipation as tension nears release.
    """
    def __init__(
        self,
        anticipation_strength: float = 0.64,
        threshold: float = 0.78,
        max_hold: float = 0.18,
        curvature: float = 2.2,
    ):
        self.anticipation_strength = anticipation_strength
        self.threshold = threshold
        self.max_hold = max_hold
        self.curvature = curvature
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(
        self,
        rhythm: float,
        tension: float,
    ) -> float:
        """
        Parameters:
            rhythm  : authoritative rhythm value (0–1)
            tension : accumulated tension value (0–1)
        Returns:
            biased_rhythm : rhythm adjusted for release anticipation
        """
        rhythm = self._clamp(rhythm)
        tension = self._clamp(tension)
        if tension < self.threshold:
            return rhythm
        # Normalized anticipation factor
        x = (tension - self.threshold) / max(1e-6, (1.0 - self.threshold))
        x = self._clamp(x)
        # Nonlinear anticipation curve
        anticipation = (x ** self.curvature) * self.anticipation_strength
        anticipation = min(anticipation, self.max_hold)
        # Slow rhythm slightly to stretch anticipation
        adjusted = rhythm * (1.0 - anticipation)
        return self._clamp(adjusted)
# ==============================================================================
# END OF CHUNK 85 D 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 D 03 — CONTROLLED PACING ELASTICITY
# ==============================================================================
#
# Purpose:
#   Allows pacing to stretch or compress under tension without
#   breaking narrative continuity or emotional credibility.
#
#   Provides elastic response instead of rigid tempo enforcement.
#
# Cinematic Motivation:
#   Elite editing flexes time subtly — moments breathe or tighten
#   based on emotional load rather than fixed rhythm.
#
# ==============================================================================

import numpy as np


class ControlledPacingElasticity:
    """
    Applies elastic scaling to rhythm under controlled constraints.
    """
    def __init__(
        self,
        elasticity: float = 0.34,
        tension_coupling: float = 0.55,
        max_stretch: float = 0.22,
        max_compress: float = 0.18,
    ):
        self.elasticity = elasticity
        self.tension_coupling = tension_coupling
        self.max_stretch = max_stretch
        self.max_compress = max_compress
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(
        self,
        rhythm: float,
        tension: float,
    ) -> float:
        """
        Parameters:
            rhythm  : authoritative rhythm (0–1)
            tension : accumulated tension (0–1)
        Returns:
            elastic_rhythm : rhythm after elastic adjustment
        """
        rhythm = self._clamp(rhythm)
        tension = self._clamp(tension)
        # Elastic response centered around mid-tension
        offset = (tension - 0.5) * self.tension_coupling
        adjustment = offset * self.elasticity
        if adjustment > 0:
            adjustment = min(adjustment, self.max_stretch)
        else:
            adjustment = max(adjustment, -self.max_compress)
        adjusted = rhythm * (1.0 + adjustment)
        return self._clamp(adjusted)
# ==============================================================================
# END OF CHUNK 85 D 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 D 04 — NARRATIVE BREATH SPACING
# ==============================================================================
#
# Purpose:
#   Inserts controlled breathing space between high-tension beats,
#   preventing emotional saturation and viewer fatigue.
#
#   Manages micro-pauses without collapsing overall momentum.
#
# Cinematic Motivation:
#   Great films consciously allow moments to breathe —
#   silence and stillness amplify what comes next.
#
# ==============================================================================

import numpy as np


class NarrativeBreathSpacing:
    """
    Injects controlled breathing intervals into pacing flow.
    """
    def __init__(
        self,
        breath_threshold: float = 0.82,
        breath_strength: float = 0.28,
        min_spacing: float = 0.04,
        recovery_rate: float = 0.12,
    ):
        self.breath_threshold = breath_threshold
        self.breath_strength = breath_strength
        self.min_spacing = min_spacing
        self.recovery_rate = recovery_rate
        self._cooldown = 0.0
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(
        self,
        rhythm: float,
        tension: float,
    ) -> float:
        """
        Parameters:
            rhythm  : authoritative rhythm (0–1)
            tension : accumulated tension (0–1)
        Returns:
            spaced_rhythm : rhythm after breath spacing
        """
        rhythm = self._clamp(rhythm)
        tension = self._clamp(tension)
        if tension > self.breath_threshold and self._cooldown <= 0.0:
            # Insert a subtle pacing pause
            spacing = max(self.min_spacing, rhythm * self.breath_strength)
            rhythm = rhythm - spacing
            self._cooldown = spacing
        # Recover from spacing gradually
        if self._cooldown > 0.0:
            self._cooldown *= (1.0 - self.recovery_rate)
        return self._clamp(rhythm)
# ==============================================================================
# END OF CHUNK 85 D 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 D 05 — TENSION DECAY MODELING
# ==============================================================================
#
# Purpose:
#   Models the natural decay of narrative tension after peaks or releases.
#
#   Prevents tension from remaining artificially elevated once the
#   narrative has earned a cooldown.
#
# Cinematic Motivation:
#   In elite cinema, tension dissipates organically after payoff.
#   Abrupt drops feel fake; flat plateaus feel exhausting.
#
# ==============================================================================

import numpy as np


class TensionDecayModeling:
    """
    Controls post-peak decay of accumulated narrative tension.
    """
    def __init__(
        self,
        base_decay: float = 0.032,
        adaptive_factor: float = 0.58,
        floor: float = 0.08,
        recovery_bias: float = 0.22,
    ):
        self.base_decay = base_decay
        self.adaptive_factor = adaptive_factor
        self.floor = floor
        self.recovery_bias = recovery_bias
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def apply(
        self,
        tension: float,
        rhythm: float,
    ) -> float:
        """
        Parameters:
            tension : current accumulated tension (0–1)
            rhythm  : authoritative rhythm value (0–1)
        Returns:
            decayed_tension : tension after decay modeling
        """
        tension = self._clamp(tension)
        rhythm = self._clamp(rhythm)
        # Faster decay when rhythm slows (cooldown phases)
        adaptive_decay = self.base_decay * (1.0 + (1.0 - rhythm) * self.adaptive_factor)
        decayed = tension * (1.0 - adaptive_decay)
        # Prevent total collapse; retain narrative residue
        decayed = max(decayed, self.floor * rhythm)
        # Slight recovery bias to avoid flatlining
        decayed += self.recovery_bias * (rhythm - 0.5) * 0.02
        return self._clamp(decayed)
# ==============================================================================
# END OF CHUNK 85 D 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 D 09 — NONLINEAR STRESS QUANTIZATION
# ==============================================================================
#
# Purpose:
#   Converts continuous narrative stress into perceptually meaningful
#   discrete states while preserving smooth transitions.
#
# Cinematic Motivation:
#   Editors and audiences perceive tension in phases (calm → pressure →
#   brink → release). This maps continuous values into cinematic plateaus
#   without banding or abrupt jumps.
#
# ==============================================================================

import numpy as np


class NonlinearStressQuantization:
    """
    Maps continuous stress values to perceptual plateaus with hysteresis.
    """
    def __init__(
        self,
        anchors=None,
        softness: float = 0.12,
        hysteresis: float = 0.035,
    ):
        # Default cinematic anchor points (calibrated perceptually)
        if anchors is None:
            anchors = [0.05, 0.22, 0.42, 0.65, 0.85]
        self.anchors = np.array(sorted(anchors), dtype=np.float32)
        self.softness = float(softness)
        self.hysteresis = float(hysteresis)
        self._last_state = None
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _soft_snap(self, value: float) -> float:
        """
        Softly attracts value toward nearest anchor without hard snapping.
        """
        diffs = self.anchors - value
        weights = np.exp(-(diffs ** 2) / max(self.softness ** 2, 1e-6))
        weights /= np.sum(weights)
        return float(np.sum(self.anchors * weights))
    def _apply_hysteresis(self, target: float) -> float:
        """
        Prevents rapid flipping between adjacent states.
        """
        if self._last_state is None:
            self._last_state = target
            return target
        delta = target - self._last_state
        if abs(delta) < self.hysteresis:
            return self._last_state
        self._last_state = target
        return target
    def apply(self, stress: float) -> float:
        """
        Parameters:
            stress : continuous stress value (0–1)
        Returns:
            quantized_stress : perceptually quantized stress (0–1)
        """
        stress = self._clamp(stress)
        snapped = self._soft_snap(stress)
        stabilized = self._apply_hysteresis(snapped)
        return self._clamp(stabilized)
# ==============================================================================
# END OF CHUNK 85 D 09
# ==============================================================================
# ==============================================================================
# CHUNK 85 D 10 — TENSION OUTPUT INTERFACE
# ==============================================================================
#
# Purpose:
#   Standardizes and exposes the final narrative tension signal for
#   downstream cinematic systems (editing cadence, camera motion bias,
#   grading emphasis, sound design coupling).
#
# Cinematic Motivation:
#   Elite pipelines require a clean, stable, and interpretable signal
#   that downstream modules can trust without re-deriving semantics.
#
# ==============================================================================

import numpy as np
from dataclasses import dataclass
@dataclass
class TensionPacket:
    """
    Immutable container for narrative tension state.
    """
    value: float
    phase: str
    confidence: float
    timestamp: float
class TensionOutputInterface:
    """
    Normalizes, labels, and publishes the final tension signal.
    """
    def __init__(
        self,
        phase_bins=None,
        min_confidence: float = 0.35,
    ):
        # Perceptual phase bins (low → high)
        if phase_bins is None:
            phase_bins = [
                (0.00, 0.18, "calm"),
                (0.18, 0.36, "unease"),
                (0.36, 0.58, "pressure"),
                (0.58, 0.78, "brink"),
                (0.78, 1.01, "release"),
            ]
        self.phase_bins = phase_bins
        self.min_confidence = float(min_confidence)
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _phase_from_value(self, v: float) -> str:
        for lo, hi, name in self.phase_bins:
            if lo <= v < hi:
                return name
        return self.phase_bins[-1][2]
    def _confidence_from_stability(
        self,
        value: float,
        derivative: float,
        noise: float,
    ) -> float:
        """
        Estimates confidence from stability cues.
        """
        # Penalize high derivative and noise
        stability = 1.0 - (abs(derivative) * 0.7 + noise * 0.6)
        stability *= 0.85 + 0.15 * value  # high tension slightly boosts confidence
        return self._clamp(stability)
    def publish(
        self,
        value: float,
        derivative: float,
        noise: float,
        timestamp: float,
    ) -> TensionPacket:
        """
        Parameters:
            value      : final tension value (0–1)
            derivative : temporal slope of tension
            noise      : estimated residual instability (0–1)
            timestamp  : seconds
        Returns:
            TensionPacket
        """
        v = self._clamp(value)
        phase = self._phase_from_value(v)
        conf = self._confidence_from_stability(v, derivative, noise)
        if conf < self.min_confidence:
            # Degrade phase reliability rather than mutating value
            phase = f"{phase}_uncertain"
        return TensionPacket(
            value=v,
            phase=phase,
            confidence=conf,
            timestamp=float(timestamp),
        )
# ==============================================================================
# END OF CHUNK 85 D 10
# ==============================================================================
# ==============================================================================
# CHUNK 85 E 01 — NARRATIVE ENERGY TRANSFER
# ==============================================================================
#
# Purpose:
#   Transfers narrative energy between consecutive scenes or shots while
#   preserving emotional continuity and avoiding perceptual discontinuities.
#
# Cinematic Motivation:
#   High-end cinema carries emotional charge across cuts. Energy should
#   neither reset nor leak uncontrollably between narrative units.
#
# ==============================================================================

import numpy as np
class NarrativeEnergyTransfer:
    """
    Computes energy carry-over across scene boundaries with perceptual damping.
    """
    def __init__(
        self,
        carry_strength: float = 0.62,
        damping: float = 0.18,
        saturation_guard: float = 0.92,
        memory_halflife: float = 2.4,
    ):
        self.carry_strength = float(carry_strength)
        self.damping = float(damping)
        self.saturation_guard = float(saturation_guard)
        self.memory_halflife = float(memory_halflife)
        self._last_energy = None
        self._last_timestamp = None
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def _temporal_decay(self, dt: float) -> float:
        """
        Exponential decay based on elapsed time.
        """
        if dt <= 0.0:
            return 1.0
        return float(np.exp(-dt / max(self.memory_halflife, 1e-6)))
    def reset(self):
        """
        Clears stored narrative energy (hard scene break).
        """
        self._last_energy = None
        self._last_timestamp = None
    def apply(
        self,
        current_energy: float,
        timestamp: float,
    ) -> float:
        """
        Parameters:
            current_energy : instantaneous narrative energy (0–1)
            timestamp      : seconds
        Returns:
            transferred_energy : energy after cross-scene transfer
        """
        current_energy = self._clamp(current_energy)
        if self._last_energy is None:
            self._last_energy = current_energy
            self._last_timestamp = float(timestamp)
            return current_energy
        dt = float(timestamp - self._last_timestamp)
        decay = self._temporal_decay(dt)
        carried = self._last_energy * decay * self.carry_strength
        # Blend with damping to avoid overshoot
        blended = (
            current_energy * (1.0 - self.damping)
            + carried * (1.0 + self.damping)
        )
        # Guard against saturation accumulation
        blended = min(blended, self.saturation_guard)
        blended = self._clamp(blended)
        # Update memory
        self._last_energy = blended
        self._last_timestamp = float(timestamp)
        return blended
# ==============================================================================
# END OF CHUNK 85 E 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 E 02 — CROSS-SCENE TENSION CONTINUITY
# ==============================================================================
#
# Purpose:
#   Ensures perceived tension continuity across hard and soft scene cuts,
#   preventing audience shock from discontinuous emotional state changes.
#
# Cinematic Motivation:
#   Top-tier films maintain subconscious emotional continuity even across
#   aggressive edits. This module smooths tension trajectories across cuts
#   without flattening narrative intent.
#
# ==============================================================================

import numpy as np
class CrossSceneTensionContinuity:
    """
    Smooths tension values across scene boundaries with adaptive blending.
    """
    def __init__(
        self,
        blend_strength: float = 0.54,
        cut_sensitivity: float = 0.38,
        continuity_floor: float = 0.12,
        max_jump: float = 0.32,
    ):
        self.blend_strength = float(blend_strength)
        self.cut_sensitivity = float(cut_sensitivity)
        self.continuity_floor = float(continuity_floor)
        self.max_jump = float(max_jump)
        self._prev_tension = None
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def reset(self):
        """
        Clears continuity memory (true narrative reset).
        """
        self._prev_tension = None
    def apply(
        self,
        tension: float,
        cut_strength: float,
    ) -> float:
        """
        Parameters:
            tension      : instantaneous tension after cut (0–1)
            cut_strength : estimated cut aggressiveness (0–1)
        Returns:
            smoothed_tension : perceptually continuous tension
        """
        tension = self._clamp(tension)
        cut_strength = self._clamp(cut_strength)
        if self._prev_tension is None:
            self._prev_tension = tension
            return tension
        # Limit excessive jumps
        delta = tension - self._prev_tension
        delta = np.clip(delta, -self.max_jump, self.max_jump)
        constrained = self._prev_tension + delta
        # Adaptive blend based on cut severity
        blend = self.blend_strength * (1.0 - cut_strength * self.cut_sensitivity)
        smoothed = (
            constrained * blend
            + tension * (1.0 - blend)
        )
        # Maintain minimal continuity residue
        smoothed = max(smoothed, self.continuity_floor * (1.0 - cut_strength))
        smoothed = self._clamp(smoothed)
        self._prev_tension = smoothed
        return smoothed
# ==============================================================================
# END OF CHUNK 85 E 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 E 03 — EMOTIONAL MOMENTUM PRESERVATION
# ==============================================================================
#
# Purpose:
#   Preserves emotional momentum across time by biasing transitions toward
#   previously established narrative direction without freezing dynamics.
#
# Cinematic Motivation:
#   Great cinema maintains emotional directionality. Momentum should bend
#   transitions, not lock them, avoiding whiplash or stagnation.
#
# ==============================================================================

import numpy as np


class EmotionalMomentumPreservation:
    """
    Applies directional bias to emotional state evolution.
    """
    def __init__(
        self,
        momentum_strength: float = 0.46,
        decay_rate: float = 0.22,
        max_bias: float = 0.28,
        inertia_floor: float = 0.06,
    ):
        self.momentum_strength = float(momentum_strength)
        self.decay_rate = float(decay_rate)
        self.max_bias = float(max_bias)
        self.inertia_floor = float(inertia_floor)
        self._last_value = None
        self._velocity = 0.0
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def reset(self):
        """
        Clears stored momentum (hard emotional reset).
        """
        self._last_value = None
        self._velocity = 0.0
    def apply(
        self,
        value: float,
        dt: float,
    ) -> float:
        """
        Parameters:
            value : instantaneous emotional value (0–1)
            dt    : time delta in seconds
        Returns:
            momentum_preserved_value : adjusted value (0–1)
        """
        value = self._clamp(value)
        dt = max(float(dt), 1e-6)
        if self._last_value is None:
            self._last_value = value
            self._velocity = 0.0
            return value
        # Compute directional velocity
        raw_velocity = (value - self._last_value) / dt
        # Exponential decay of previous momentum
        self._velocity *= np.exp(-self.decay_rate * dt)
        # Blend new velocity into momentum
        self._velocity += raw_velocity * self.momentum_strength * dt
        # Limit bias magnitude
        self._velocity = np.clip(
            self._velocity,
            -self.max_bias,
            self.max_bias,
        )
        # Apply inertia bias
        biased = value + self._velocity
        # Prevent total stalling
        if abs(self._velocity) < self.inertia_floor:
            biased = value * (1.0 - self.inertia_floor) + biased * self.inertia_floor
        biased = self._clamp(biased)
        self._last_value = biased
        return biased
# ==============================================================================
# END OF CHUNK 85 E 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 E 04 — VIEWER FATIGUE SAFEGUARD
# ==============================================================================
#
# Purpose:
#   Actively prevents prolonged high-intensity emotional states that
#   cause viewer fatigue, desensitization, or disengagement.
#
# Cinematic Motivation:
#   Elite cinema modulates intensity over time. Sustained peaks dull
#   emotional response; controlled relief preserves impact.
#
# ==============================================================================

import numpy as np


class ViewerFatigueSafeguard:
    """
    Regulates sustained emotional intensity to avoid audience fatigue.
    """
    def __init__(
        self,
        fatigue_threshold: float = 0.72,
        max_duration: float = 6.0,
        relief_strength: float = 0.18,
        recovery_rate: float = 0.25,
    ):
        self.fatigue_threshold = float(fatigue_threshold)
        self.max_duration = float(max_duration)
        self.relief_strength = float(relief_strength)
        self.recovery_rate = float(recovery_rate)
        self._time_over_threshold = 0.0
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def reset(self):
        """
        Clears fatigue accumulation (scene reset or cooldown).
        """
        self._time_over_threshold = 0.0
    def apply(
        self,
        intensity: float,
        dt: float,
    ) -> float:
        """
        Parameters:
            intensity : current emotional intensity (0–1)
            dt        : time delta in seconds
        Returns:
            regulated_intensity : fatigue-safe intensity
        """
        intensity = self._clamp(intensity)
        dt = max(float(dt), 1e-6)
        if intensity > self.fatigue_threshold:
            self._time_over_threshold += dt
        else:
            # Gradual recovery when below threshold
            self._time_over_threshold *= np.exp(-self.recovery_rate * dt)
        if self._time_over_threshold > self.max_duration:
            # Apply relief scaling once fatigue limit exceeded
            excess = self._time_over_threshold - self.max_duration
            relief = self.relief_strength * (1.0 - np.exp(-excess))
            intensity *= (1.0 - relief)
        return self._clamp(intensity)
# ==============================================================================
# END OF CHUNK 85 E 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 E 05 — PEAK DENSITY REGULATION
# ==============================================================================
#
# Purpose:
#   Regulates the temporal density of emotional peaks to preserve impact,
#   preventing clustering that causes desensitization.
#
# Cinematic Motivation:
#   Masterful films space their peaks. Too many highs collapse perceived
#   intensity; controlled spacing amplifies each payoff.
#
# ==============================================================================

import numpy as np


class PeakDensityRegulation:
    """
    Enforces perceptual spacing between emotional peaks.
    """
    def __init__(
        self,
        peak_threshold: float = 0.75,
        min_spacing: float = 3.2,
        suppression_strength: float = 0.35,
        recovery_curve: float = 0.45,
    ):
        self.peak_threshold = float(peak_threshold)
        self.min_spacing = float(min_spacing)
        self.suppression_strength = float(suppression_strength)
        self.recovery_curve = float(recovery_curve)
        self._last_peak_time = None
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def reset(self):
        """
        Clears peak history (hard narrative reset).
        """
        self._last_peak_time = None
    def apply(
        self,
        intensity: float,
        timestamp: float,
    ) -> float:
        """
        Parameters:
            intensity : current emotional intensity (0–1)
            timestamp : seconds
        Returns:
            regulated_intensity : intensity after peak density control
        """
        intensity = self._clamp(intensity)
        is_peak = intensity >= self.peak_threshold
        if not is_peak:
            return intensity
        if self._last_peak_time is None:
            self._last_peak_time = float(timestamp)
            return intensity
        dt = float(timestamp - self._last_peak_time)
        if dt >= self.min_spacing:
            # Peak is sufficiently spaced; accept fully
            self._last_peak_time = float(timestamp)
            return intensity
        # Suppress clustered peaks smoothly
        proximity = 1.0 - (dt / max(self.min_spacing, 1e-6))
        suppression = (
            self.suppression_strength
            * (proximity ** (1.0 + self.recovery_curve))
        )
        regulated = intensity * (1.0 - suppression)
        regulated = self._clamp(regulated)
        # Do not update last_peak_time to avoid cascading suppression
        return regulated
# ==============================================================================
# END OF CHUNK 85 E 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 F 01 — NARRATIVE PHASE ALIGNMENT
# ==============================================================================
#
# Purpose:
#   Aligns emotional, tension, and energy phases into a coherent narrative
#   phase signal usable by editing cadence, camera motion bias, and grading.
#
# Cinematic Motivation:
#   High-end cinema operates in phases (build, hold, release). When internal
#   systems drift out of phase, the result feels chaotic. This module enforces
#   phase coherence without flattening dynamics.
#
# ==============================================================================

import numpy as np


class NarrativePhaseAlignment:
    """
    Produces a unified narrative phase from multiple emotional drivers.
    """
    def __init__(
        self,
        tension_weight: float = 0.42,
        energy_weight: float = 0.34,
        emotion_weight: float = 0.24,
        coherence_bias: float = 0.18,
    ):
        self.tension_weight = float(tension_weight)
        self.energy_weight = float(energy_weight)
        self.emotion_weight = float(emotion_weight)
        self.coherence_bias = float(coherence_bias)
        self._last_phase = None
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def reset(self):
        """
        Clears stored phase memory.
        """
        self._last_phase = None
    def apply(
        self,
        tension: float,
        energy: float,
        emotion: float,
    ) -> float:
        """
        Parameters:
            tension : normalized narrative tension (0–1)
            energy  : normalized narrative energy (0–1)
            emotion : normalized emotional intensity (0–1)
        Returns:
            phase : unified narrative phase (0–1)
        """
        tension = self._clamp(tension)
        energy = self._clamp(energy)
        emotion = self._clamp(emotion)
        weighted = (
            tension * self.tension_weight
            + energy * self.energy_weight
            + emotion * self.emotion_weight
        )
        # Normalize weight sum
        weighted /= (
            self.tension_weight
            + self.energy_weight
            + self.emotion_weight
        )
        if self._last_phase is None:
            self._last_phase = weighted
            return weighted
        # Enforce coherence with gentle attraction to prior phase
        phase = (
            weighted * (1.0 - self.coherence_bias)
            + self._last_phase * self.coherence_bias
        )
        phase = self._clamp(phase)
        self._last_phase = phase
        return phase
# ==============================================================================
# END OF CHUNK 85 F 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 F 02 — PHASE TRANSITION SMOOTHING
# ==============================================================================
#
# Purpose:
#   Smooths transitions between narrative phases to avoid perceptual
#   discontinuities while preserving intentional inflection points.
#
# Cinematic Motivation:
#   Elite edits glide between phases unless a hard cut is narratively earned.
#   This module enforces continuity without blunting dramatic pivots.
#
# ==============================================================================

import numpy as np


class PhaseTransitionSmoothing:
    """
    Applies adaptive temporal smoothing to narrative phase changes.
    """
    def __init__(
        self,
        base_smoothing: float = 0.42,
        inflection_sensitivity: float = 0.55,
        max_lag: float = 0.18,
        snap_threshold: float = 0.26,
    ):
        self.base_smoothing = float(base_smoothing)
        self.inflection_sensitivity = float(inflection_sensitivity)
        self.max_lag = float(max_lag)
        self.snap_threshold = float(snap_threshold)
        self._last_phase = None
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def reset(self):
        """
        Clears phase smoothing history.
        """
        self._last_phase = None
    def apply(
        self,
        phase: float,
        phase_velocity: float,
    ) -> float:
        """
        Parameters:
            phase          : instantaneous phase (0–1)
            phase_velocity : temporal derivative of phase
        Returns:
            smoothed_phase : perceptually smoothed phase
        """
        phase = self._clamp(phase)
        if self._last_phase is None:
            self._last_phase = phase
            return phase
        # Detect inflection (intentional sharp change)
        inflection = min(abs(phase_velocity) * self.inflection_sensitivity, 1.0)
        # Reduce smoothing near inflections
        smoothing = self.base_smoothing * (1.0 - inflection)
        # Hard snap if change exceeds narrative threshold
        delta = phase - self._last_phase
        if abs(delta) > self.snap_threshold:
            self._last_phase = phase
            return phase
        # Apply bounded smoothing
        smoothed = (
            self._last_phase * smoothing
            + phase * (1.0 - smoothing)
        )
        # Limit perceptual lag
        lag = smoothed - phase
        lag = np.clip(lag, -self.max_lag, self.max_lag)
        smoothed = phase + lag
        smoothed = self._clamp(smoothed)
        self._last_phase = smoothed
        return smoothed
# ==============================================================================
# END OF CHUNK 85 F 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 F 04 — PHASE DRIFT COMPENSATION
# ==============================================================================
#
# Purpose:
#   Detects and compensates slow phase drift between camera-level AI,
#   edge (Radxa) preprocessing, and cloud/laptop inference outputs.
#
# System Integration:
#   - Camera AI (on Radxa): provides local phase estimate
#   - VPS / Cloud AI: provides authoritative phase intent
#   - Laptop AI: provides high-fidelity phase refinement
#   This module reconciles them without oscillation.
#
# ==============================================================================

import numpy as np


class PhaseDriftCompensation:
    """
    Compensates slow divergence between multiple phase authorities.
    """
    def __init__(
        self,
        drift_rate: float = 0.06,
        correction_strength: float = 0.38,
        max_correction: float = 0.22,
        trust_weights=None,
    ):
        self.drift_rate = float(drift_rate)
        self.correction_strength = float(correction_strength)
        self.max_correction = float(max_correction)
        # Relative trust: camera(radxa), vps/cloud, laptop
        if trust_weights is None:
            trust_weights = {
                "camera": 0.25,
                "cloud": 0.45,
                "laptop": 0.30,
            }
        self.trust_weights = trust_weights
        self._reference_phase = None
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def reset(self):
        """
        Clears accumulated drift (hard sync event).
        """
        self._reference_phase = None
    def _weighted_reference(self, phases: dict) -> float:
        """
        Computes trust-weighted reference phase.
        """
        total_w = 0.0
        acc = 0.0
        for k, v in phases.items():
            w = self.trust_weights.get(k, 0.0)
            acc += self._clamp(v) * w
            total_w += w
        return acc / max(total_w, 1e-6)
    def apply(
        self,
        phase_sources: dict,
        dt: float,
    ) -> dict:
        """
        Parameters:
            phase_sources : dict[str, float]
                keys expected: 'camera', 'cloud', 'laptop'
            dt            : time delta in seconds
        Returns:
            compensated_phases : dict[str, float]
        """
        if not phase_sources:
            return {}
        dt = max(float(dt), 1e-6)
        reference = self._weighted_reference(phase_sources)
        if self._reference_phase is None:
            self._reference_phase = reference
        # Slowly move reference to avoid authority snapping
        ref_delta = reference - self._reference_phase
        self._reference_phase += ref_delta * self.drift_rate * dt
        self._reference_phase = self._clamp(self._reference_phase)
        compensated = {}
        for k, v in phase_sources.items():
            v = self._clamp(v)
            delta = self._reference_phase - v
            correction = np.clip(
                delta * self.correction_strength,
                -self.max_correction,
                self.max_correction,
            )
            compensated[k] = self._clamp(v + correction)
        return compensated
# ==============================================================================
# END OF CHUNK 85 F 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 F 05 — PHASE STABILITY GUARD
# ==============================================================================
#
# Purpose:
#   Prevents oscillation, chatter, and authority tug-of-war in the unified
#   narrative phase when multiple AI layers are active simultaneously.
#
# System Context:
#   - Camera AI (Radxa): fast, local, noisy
#   - Cloud AI (VPS): intent-driven, higher latency
#   - Laptop AI: high-fidelity, heavy inference
#
#   This guard ensures the final phase signal is stable, cinematic,
#   and safe to drive downstream systems (motion, grade, pacing).
#
# ==============================================================================

import numpy as np


class PhaseStabilityGuard:
    """
    Suppresses rapid phase oscillations while preserving intentional changes.
    """
    def __init__(
        self,
        stability_window: int = 6,
        max_rate: float = 0.35,
        damping: float = 0.42,
        snap_override: float = 0.48,
    ):
        self.stability_window = int(stability_window)
        self.max_rate = float(max_rate)
        self.damping = float(damping)
        self.snap_override = float(snap_override)
        self._history = []
    @staticmethod
    def _clamp(v: float, lo: float = 0.0, hi: float = 1.0) -> float:
        return float(np.clip(v, lo, hi))
    def reset(self):
        """
        Clears stability history (hard sync / scene reset).
        """
        self._history.clear()
    def _rate_limit(self, current: float, previous: float, dt: float) -> float:
        """
        Enforces maximum phase rate-of-change.
        """
        if dt <= 0.0:
            return current
        max_delta = self.max_rate * dt
        delta = current - previous
        delta = np.clip(delta, -max_delta, max_delta)
        return previous + delta
    def apply(
        self,
        phase: float,
        dt: float,
    ) -> float:
        """
        Parameters:
            phase : unified narrative phase (0–1)
            dt    : time delta in seconds
        Returns:
            stabilized_phase : phase safe for downstream cinematic systems
        """
        phase = self._clamp(phase)
        dt = max(float(dt), 1e-6)
        if not self._history:
            self._history.append(phase)
            return phase
        prev = self._history[-1]
        # Rate limiting
        limited = self._rate_limit(phase, prev, dt)
        # Detect strong intentional change (override damping)
        if abs(limited - prev) > self.snap_override:
            stabilized = limited
        else:
            # Damped smoothing
            stabilized = (
                prev * self.damping
                + limited * (1.0 - self.damping)
            )
        stabilized = self._clamp(stabilized)
        # Update history window
        self._history.append(stabilized)
        if len(self._history) > self.stability_window:
            self._history.pop(0)
        return stabilized
# ==============================================================================
# END OF CHUNK 85 F 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 H 01 — CAMERA AI PERCEPTION CORE
# ==============================================================================
#
# Purpose:
#   Primary camera-side AI perception engine running on Radxa.
#   Converts raw frames into cinematic intent primitives.
#
# Scope:
#   - Real-time operation
#   - No network / no flight control
#   - Feeds higher AI layers later
#
# ==============================================================================

import numpy as np
import cv2


class CameraAIPerceptionCore:
    """
    Radxa-side camera perception engine for cinematic intelligence.
    """
    def __init__(
        self,
        frame_width: int,
        frame_height: int,
        motion_gain: float = 0.9,
        saliency_gain: float = 1.2,
        temporal_alpha: float = 0.65,
    ):
        self.w = int(frame_width)
        self.h = int(frame_height)
        self.motion_gain = float(motion_gain)
        self.saliency_gain = float(saliency_gain)
        self.temporal_alpha = float(temporal_alpha)
        self._prev_gray = None
        self._smoothed_motion = np.zeros(2, dtype=np.float32)
    @staticmethod
    def _clamp01(x: float) -> float:
        return float(np.clip(x, 0.0, 1.0))
    def _optical_motion(self, gray: np.ndarray) -> np.ndarray:
        """
        Computes dominant optical flow vector.
        """
        if self._prev_gray is None:
            self._prev_gray = gray
            return np.zeros(2, dtype=np.float32)
        flow = cv2.calcOpticalFlowFarneback(
            self._prev_gray,
            gray,
            None,
            0.5,
            3,
            15,
            3,
            5,
            1.1,
            0,
        )
        mean_flow = flow.mean(axis=(0, 1))
        self._prev_gray = gray
        return mean_flow.astype(np.float32)
    def _saliency_score(self, frame: np.ndarray) -> float:
        """
        Luminance + contrast based saliency estimate.
        """
        lab = cv2.cvtColor(frame, cv2.COLOR_BGR2LAB)
        l, _, _ = cv2.split(lab)
        l_norm = l.astype(np.float32) / 255.0
        contrast = cv2.Laplacian(l_norm, cv2.CV_32F)
        score = np.mean(np.abs(contrast)) * self.saliency_gain
        return self._clamp01(score)
    def _scene_energy(self, motion_vec: np.ndarray, saliency: float) -> float:
        """
        Estimates perceived scene energy.
        """
        motion_mag = np.linalg.norm(motion_vec)
        energy = (
            motion_mag * self.motion_gain
            + saliency * (1.0 - self.motion_gain)
        )
        return self._clamp01(energy)
    def process_frame(self, frame: np.ndarray) -> dict:
        """
        Processes a single frame and outputs camera intent primitives.
        """
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        motion_vec = self._optical_motion(gray)
        self._smoothed_motion = (
            self._smoothed_motion * self.temporal_alpha
            + motion_vec * (1.0 - self.temporal_alpha)
        )
        saliency = self._saliency_score(frame)
        energy = self._scene_energy(self._smoothed_motion, saliency)
        intent = {
            "motion_x": self._clamp01(0.5 + self._smoothed_motion[0]),
            "motion_y": self._clamp01(0.5 + self._smoothed_motion[1]),
            "saliency": saliency,
            "scene_energy": energy,
        }
        return intent
# ==============================================================================
# END OF CHUNK 85 H 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 H 02 — SUBJECT IMPORTANCE RANKING
# ==============================================================================
#
# Purpose:
#   Ranks subjects in-frame by cinematic importance.
#   Produces normalized priority signals used by framing, exposure,
#   motion intent, and later multi-system arbitration.
#
# Design:
#   - Lightweight (Radxa-capable)
#   - Model-agnostic (accepts detector outputs if present)
#   - Falls back to visual heuristics if detectors are unavailable
#
# ==============================================================================

import numpy as np
import cv2


class SubjectImportanceRanker:
    """
    Computes per-subject cinematic importance scores.
    """
    def __init__(
        self,
        center_bias: float = 0.42,
        size_bias: float = 0.38,
        motion_bias: float = 0.20,
        temporal_smooth: float = 0.6,
    ):
        self.center_bias = float(center_bias)
        self.size_bias = float(size_bias)
        self.motion_bias = float(motion_bias)
        self.temporal_smooth = float(temporal_smooth)
        self._prev_scores = {}
    @staticmethod
    def _clamp01(x: float) -> float:
        return float(np.clip(x, 0.0, 1.0))
    def _center_weight(self, bbox, frame_w, frame_h):
        """
        Higher score for subjects closer to frame center.
        bbox: (x, y, w, h) in pixels
        """
        x, y, w, h = bbox
        cx = x + w * 0.5
        cy = y + h * 0.5
        dx = abs(cx - frame_w * 0.5) / (frame_w * 0.5)
        dy = abs(cy - frame_h * 0.5) / (frame_h * 0.5)
        dist = np.sqrt(dx * dx + dy * dy)
        return self._clamp01(1.0 - dist)
    def _size_weight(self, bbox, frame_w, frame_h):
        """
        Larger subjects are generally more important.
        """
        _, _, w, h = bbox
        area = (w * h) / float(frame_w * frame_h + 1e-6)
        return self._clamp01(np.sqrt(area))
    def _motion_weight(self, motion_mag: float):
        """
        Moving subjects draw attention.
        """
        return self._clamp01(motion_mag)
    def rank(
        self,
        subjects: list,
        frame_shape: tuple,
    ):
        """
        Parameters:
            subjects : list of dicts
                Each subject:
                {
                    "id": hashable,
                    "bbox": (x, y, w, h),
                    "motion": float (0–1)
                }
            frame_shape : (H, W)
        Returns:
            ranked_subjects : list of dicts with 'importance'
        """
        h, w = frame_shape
        ranked = []
        for subj in subjects:
            sid = subj.get("id")
            bbox = subj.get("bbox", (0, 0, 0, 0))
            motion = float(subj.get("motion", 0.0))
            cw = self._center_weight(bbox, w, h)
            sw = self._size_weight(bbox, w, h)
            mw = self._motion_weight(motion)
            score = (
                cw * self.center_bias
                + sw * self.size_bias
                + mw * self.motion_bias
            )
            score = self._clamp01(score)
            # Temporal smoothing per subject
            prev = self._prev_scores.get(sid, score)
            score = (
                prev * self.temporal_smooth
                + score * (1.0 - self.temporal_smooth)
            )
            self._prev_scores[sid] = score
            enriched = dict(subj)
            enriched["importance"] = score
            ranked.append(enriched)
        # Sort by importance descending
        ranked.sort(key=lambda x: x["importance"], reverse=True)
        return ranked
# ==============================================================================
# END OF CHUNK 85 H 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 H 03 — CINEMATIC FRAMING EVALUATOR
# ==============================================================================
#
# Purpose:
#   Evaluates framing quality for detected subjects and scenes.
#   Produces framing desirability scores and suggested framing offsets.
#
# Cinematic Criteria:
#   - Rule-of-thirds adherence
#   - Headroom & lead-room balance
#   - Negative space utilization
#   - Motion-aware composition
#
# Output:
#   FramingIntent primitives used later by motion/exposure engines.
#
# ==============================================================================

import numpy as np


class CinematicFramingEvaluator:
    """
    Computes framing desirability and suggested offsets.
    """
    def __init__(
        self,
        thirds_weight: float = 0.42,
        headroom_weight: float = 0.28,
        leadroom_weight: float = 0.20,
        negative_space_weight: float = 0.10,
        temporal_smooth: float = 0.6,
    ):
        self.thirds_weight = float(thirds_weight)
        self.headroom_weight = float(headroom_weight)
        self.leadroom_weight = float(leadroom_weight)
        self.negative_space_weight = float(negative_space_weight)
        self.temporal_smooth = float(temporal_smooth)
        self._prev_offset = np.zeros(2, dtype=np.float32)
    @staticmethod
    def _clamp01(x: float) -> float:
        return float(np.clip(x, 0.0, 1.0))
    def _rule_of_thirds_score(self, cx, cy, w, h):
        """
        Higher when subject aligns near thirds intersections.
        """
        thirds_x = np.array([w / 3.0, 2.0 * w / 3.0])
        thirds_y = np.array([h / 3.0, 2.0 * h / 3.0])
        dx = np.min(np.abs(thirds_x - cx)) / (w / 3.0)
        dy = np.min(np.abs(thirds_y - cy)) / (h / 3.0)
        score = 1.0 - np.sqrt(dx * dx + dy * dy)
        return self._clamp01(score)
    def _headroom_score(self, bbox, frame_h):
        """
        Penalizes excessive or insufficient headroom.
        """
        _, y, _, h = bbox
        top_space = y / float(frame_h + 1e-6)
        ideal = 0.10  # cinematic headroom target
        return self._clamp01(1.0 - abs(top_space - ideal) * 5.0)
    def _leadroom_score(self, bbox, motion_x, frame_w):
        """
        Rewards space in front of motion direction.
        """
        x, _, w, _ = bbox
        cx = x + w * 0.5
        if motion_x >= 0.0:
            space_ahead = (frame_w - cx) / float(frame_w)
        else:
            space_ahead = cx / float(frame_w)
        return self._clamp01(space_ahead)
    def _negative_space_score(self, bbox, frame_w, frame_h):
        """
        Rewards compositions with breathing room.
        """
        _, _, w, h = bbox
        area_ratio = (w * h) / float(frame_w * frame_h + 1e-6)
        return self._clamp01(1.0 - np.sqrt(area_ratio))
    def evaluate(
        self,
        primary_subject: dict,
        frame_shape: tuple,
        motion_hint: dict,
    ):
        """
        Parameters:
            primary_subject : dict with 'bbox'
            frame_shape     : (H, W)
            motion_hint     : {'motion_x': float}
        Returns:
            framing_intent : dict
        """
        h, w = frame_shape
        bbox = primary_subject.get("bbox", (0, 0, 0, 0))
        x, y, bw, bh = bbox
        cx = x + bw * 0.5
        cy = y + bh * 0.5
        thirds = self._rule_of_thirds_score(cx, cy, w, h)
        headroom = self._headroom_score(bbox, h)
        leadroom = self._leadroom_score(
            bbox, motion_hint.get("motion_x", 0.0), w
        )
        neg_space = self._negative_space_score(bbox, w, h)
        score = (
            thirds * self.thirds_weight
            + headroom * self.headroom_weight
            + leadroom * self.leadroom_weight
            + neg_space * self.negative_space_weight
        )
        score = self._clamp01(score)
        # Suggested framing offset (normalized)
        desired_cx = w * (1.0 / 3.0 if cx < w * 0.5 else 2.0 / 3.0)
        desired_cy = h * 0.5
        offset = np.array(
            [
                (desired_cx - cx) / float(w),
                (desired_cy - cy) / float(h),
            ],
            dtype=np.float32,
        )
        # Temporal smoothing
        offset = (
            self._prev_offset * self.temporal_smooth
            + offset * (1.0 - self.temporal_smooth)
        )
        self._prev_offset = offset
        return {
            "framing_score": score,
            "offset_x": self._clamp01(0.5 + offset[0]),
            "offset_y": self._clamp01(0.5 + offset[1]),
        }
