# END OF CHUNK 85 H 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 H 04 — CAMERA MOTION INTENT GENERATOR
# ==============================================================================
#
# Purpose:
#   Generates camera-side motion intent primitives based on
#   perceived subject dynamics and framing pressure.
#
# Scope:
#   - Runs locally on Radxa
#   - Produces smooth, bounded motion intent signals
#   - No gimbal/flight control here; intent only
#
# Output:
#   {
#     "pan":   0–1,
#     "tilt":  0–1,
#     "push":  0–1,   # perceived dolly-in / out pressure
#     "stabilize": 0–1
#   }
#
# ==============================================================================

import numpy as np


class CameraMotionIntentGenerator:
    """
    Computes motion intent primitives for cinematic camera behavior.
    """
    def __init__(
        self,
        pan_gain: float = 0.85,
        tilt_gain: float = 0.80,
        push_gain: float = 0.65,
        stabilization_bias: float = 0.55,
        temporal_smooth: float = 0.70,
    ):
        self.pan_gain = float(pan_gain)
        self.tilt_gain = float(tilt_gain)
        self.push_gain = float(push_gain)
        self.stabilization_bias = float(stabilization_bias)
        self.temporal_smooth = float(temporal_smooth)
        self._prev = {
            "pan": 0.5,
            "tilt": 0.5,
            "push": 0.5,
            "stabilize": 0.5,
        }
    @staticmethod
    def _clamp01(x: float) -> float:
        return float(np.clip(x, 0.0, 1.0))
    def generate(
        self,
        framing_intent: dict,
        subject_motion: dict,
        scene_energy: float,
    ) -> dict:
        """
        Parameters:
            framing_intent : {"offset_x", "offset_y"}
            subject_motion : {"motion_x", "motion_y"}
            scene_energy   : 0–1
        Returns:
            motion_intent : dict
        """
        fx = framing_intent.get("offset_x", 0.5) - 0.5
        fy = framing_intent.get("offset_y", 0.5) - 0.5
        mx = subject_motion.get("motion_x", 0.5) - 0.5
        my = subject_motion.get("motion_y", 0.5) - 0.5
        # Pan/Tilt follow subject & framing pressure
        pan = 0.5 + (fx + mx) * self.pan_gain
        tilt = 0.5 + (fy + my) * self.tilt_gain
        # Push-in when subject importance + energy are high
        push = 0.5 + (scene_energy - 0.5) * self.push_gain
        # Stabilization increases when energy is low or intent conflict exists
        stabilize = (
            self.stabilization_bias * (1.0 - scene_energy)
            + (1.0 - self.stabilization_bias) * 0.5
        )
        raw = {
            "pan": self._clamp01(pan),
            "tilt": self._clamp01(tilt),
            "push": self._clamp01(push),
            "stabilize": self._clamp01(stabilize),
        }
        # Temporal smoothing for cinematic feel
        out = {}
        for k, v in raw.items():
            out[k] = (
                self._prev[k] * self.temporal_smooth
                + v * (1.0 - self.temporal_smooth)
            )
            out[k] = self._clamp01(out[k])
            self._prev[k] = out[k]
        return out
# ==============================================================================
# END OF CHUNK 85 H 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 H 05 — EXPOSURE & TONE INTENT ENGINE
# ==============================================================================
#
# Purpose:
#   Generates camera-side exposure and tone intent primitives
#   based on scene luminance, contrast distribution, subject priority,
#   and cinematic energy.
#
# Scope:
#   - Runs locally on Radxa
#   - No direct sensor/ISP control here (intent only)
#   - Drives later AE, tone-mapping, and grading systems
#
# Output:
#   {
#     "exposure_bias": 0–1,
#     "highlight_protect": 0–1,
#     "shadow_lift": 0–1,
#     "contrast_bias": 0–1,
#     "tone_aggression": 0–1
#   }
#
# ==============================================================================

import numpy as np
import cv2


class ExposureToneIntentEngine:
    """
    Computes exposure and tone intent primitives for cinematic capture.
    """
    def __init__(
        self,
        mid_gray_target: float = 0.42,
        highlight_bias: float = 0.55,
        shadow_bias: float = 0.45,
        contrast_gain: float = 0.65,
        temporal_smooth: float = 0.75,
    ):
        self.mid_gray_target = float(mid_gray_target)
        self.highlight_bias = float(highlight_bias)
        self.shadow_bias = float(shadow_bias)
        self.contrast_gain = float(contrast_gain)
        self.temporal_smooth = float(temporal_smooth)
        self._prev = {
            "exposure_bias": 0.5,
            "highlight_protect": 0.5,
            "shadow_lift": 0.5,
            "contrast_bias": 0.5,
            "tone_aggression": 0.5,
        }
    @staticmethod
    def _clamp01(x: float) -> float:
        return float(np.clip(x, 0.0, 1.0))
    def _luminance_stats(self, frame: np.ndarray):
        """
        Computes luminance distribution statistics.
        """
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        l = gray.astype(np.float32) / 255.0
        mean_l = float(np.mean(l))
        p10 = float(np.percentile(l, 10))
        p90 = float(np.percentile(l, 90))
        return mean_l, p10, p90
    def generate(
        self,
        frame: np.ndarray,
        subject_importance: float,
        scene_energy: float,
    ) -> dict:
        """
        Parameters:
            frame              : BGR frame
            subject_importance : 0–1
            scene_energy       : 0–1
        Returns:
            exposure_tone_intent : dict
        """
        mean_l, p10, p90 = self._luminance_stats(frame)
        # Exposure bias: keep mid-gray near cinematic target,
        # weighted by subject importance
        exposure_bias = (
            0.5
            + (self.mid_gray_target - mean_l)
            * (0.6 + 0.4 * subject_importance)
        )
        # Highlight protection increases when highlights approach clipping
        highlight_pressure = max(0.0, p90 - 0.85)
        highlight_protect = (
            highlight_pressure * self.highlight_bias
            + scene_energy * (1.0 - self.highlight_bias)
        )
        # Shadow lift when scene is dark or subject is important
        shadow_pressure = max(0.0, 0.15 - p10)
        shadow_lift = (
            shadow_pressure * self.shadow_bias
            + subject_importance * (1.0 - self.shadow_bias)
        )
        # Contrast bias driven by scene energy
        contrast_bias = (
            0.5
            + (scene_energy - 0.5) * self.contrast_gain
        )
        # Overall tone aggression (how hard tone-mapping should push)
        tone_aggression = self._clamp01(
            0.4
            + scene_energy * 0.4
            + subject_importance * 0.2
        )
        raw = {
            "exposure_bias": self._clamp01(exposure_bias),
            "highlight_protect": self._clamp01(highlight_protect),
            "shadow_lift": self._clamp01(shadow_lift),
            "contrast_bias": self._clamp01(contrast_bias),
            "tone_aggression": tone_aggression,
        }
        # Temporal smoothing for cinematic continuity
        out = {}
        for k, v in raw.items():
            out[k] = (
                self._prev[k] * self.temporal_smooth
                + v * (1.0 - self.temporal_smooth)
            )
            out[k] = self._clamp01(out[k])
            self._prev[k] = out[k]
        return out
# ==============================================================================
# END OF CHUNK 85 H 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 H 06 — CAMERA CONFIDENCE SCORING
# ==============================================================================
#
# Purpose:
#   Computes a unified confidence score for camera-side AI decisions.
#   Confidence reflects perception reliability, temporal stability,
#   and scene observability.
#
# Usage:
#   - Gates downstream influence of camera AI
#   - Modulates blending with cloud / laptop AI later
#   - Prevents overreaction in ambiguous scenes
#
# Output:
#   {
#     "confidence": 0–1,
#     "stability":  0–1,
#     "visibility": 0–1
#   }
#
# ==============================================================================

import numpy as np


class CameraConfidenceScoring:
    """
    Evaluates confidence of camera AI intent signals.
    """
    def __init__(
        self,
        stability_weight: float = 0.40,
        visibility_weight: float = 0.35,
        consistency_weight: float = 0.25,
        temporal_window: int = 8,
    ):
        self.stability_weight = float(stability_weight)
        self.visibility_weight = float(visibility_weight)
        self.consistency_weight = float(consistency_weight)
        self.temporal_window = int(temporal_window)
        self._history = []
    @staticmethod
    def _clamp01(x: float) -> float:
        return float(np.clip(x, 0.0, 1.0))
    def _stability_score(self, motion_intent: dict):
        """
        Measures stability of motion intent over time.
        """
        if not self._history:
            return 1.0
        diffs = []
        for prev in self._history:
            diffs.append(
                abs(motion_intent["pan"] - prev["pan"])
                + abs(motion_intent["tilt"] - prev["tilt"])
            )
        mean_diff = np.mean(diffs)
        return self._clamp01(1.0 - mean_diff * 2.0)
    def _visibility_score(
        self,
        saliency: float,
        subject_importance: float,
    ):
        """
        Estimates scene observability.
        """
        return self._clamp01(
            0.6 * saliency + 0.4 * subject_importance
        )
    def _consistency_score(self, scene_energy: float):
        """
        Penalizes sudden scene energy spikes.
        """
        if not self._history:
            return 1.0
        energies = [h["scene_energy"] for h in self._history]
        variance = np.var(energies + [scene_energy])
        return self._clamp01(1.0 - variance * 3.0)
    def evaluate(
        self,
        motion_intent: dict,
        saliency: float,
        subject_importance: float,
        scene_energy: float,
    ) -> dict:
        """
        Parameters:
            motion_intent      : dict
            saliency           : 0–1
            subject_importance : 0–1
            scene_energy       : 0–1
        Returns:
            confidence_packet : dict
        """
        stability = self._stability_score(motion_intent)
        visibility = self._visibility_score(
            saliency, subject_importance
        )
        consistency = self._consistency_score(scene_energy)
        confidence = (
            stability * self.stability_weight
            + visibility * self.visibility_weight
            + consistency * self.consistency_weight
        )
        confidence = self._clamp01(confidence)
        packet = {
            "confidence": confidence,
            "stability": stability,
            "visibility": visibility,
            "scene_energy": scene_energy,
        }
        # Update history
        self._history.append(
            {
                "pan": motion_intent["pan"],
                "tilt": motion_intent["tilt"],
                "scene_energy": scene_energy,
            }
        )
        if len(self._history) > self.temporal_window:
            self._history.pop(0)
        return packet
# ==============================================================================
# END OF CHUNK 85 H 06
# ==============================================================================
# ==============================================================================
# CHUNK 85 H 07 — CAMERA INTENT FUSION & PRIORITIZATION
# ==============================================================================
#
# Purpose:
#   Fuses perception, framing, exposure, and confidence signals
#   into a single camera-intent packet.
#
# Notes:
#   - Runs fully on Radxa
#   - Output is deterministic, bounded, and explainable
#   - Designed for later arbitration with laptop / cloud AI
#
# ==============================================================================

import numpy as np


class CameraIntentFusion:
    """
    Produces a unified camera intent from multiple AI subsystems.
    """
    def __init__(
        self,
        motion_weight: float = 0.35,
        framing_weight: float = 0.30,
        exposure_weight: float = 0.20,
        confidence_weight: float = 0.15,
    ):
        self.motion_weight = float(motion_weight)
        self.framing_weight = float(framing_weight)
        self.exposure_weight = float(exposure_weight)
        self.confidence_weight = float(confidence_weight)
    @staticmethod
    def _clamp(x: float, lo: float = -1.0, hi: float = 1.0) -> float:
        return float(np.clip(x, lo, hi))
    def fuse(
        self,
        motion_intent: dict,
        framing_score: float,
        exposure_intent: dict,
        confidence_packet: dict,
    ) -> dict:
        """
        Parameters:
            motion_intent     : {pan, tilt, zoom}
            framing_score     : 0–1
            exposure_intent   : {ev_bias, highlight_protect}
            confidence_packet : output of CameraConfidenceScoring
        Returns:
            unified_intent : dict
        """
        confidence = confidence_packet["confidence"]
        # Weighted fusion
        pan = (
            motion_intent["pan"] * self.motion_weight
            + framing_score * self.framing_weight
        ) * confidence
        tilt = (
            motion_intent["tilt"] * self.motion_weight
            + framing_score * self.framing_weight
        ) * confidence
        zoom = motion_intent.get("zoom", 0.0) * confidence
        ev_bias = exposure_intent["ev_bias"] * self.exposure_weight * confidence
        unified = {
            "pan": self._clamp(pan),
            "tilt": self._clamp(tilt),
            "zoom": self._clamp(zoom),
            "ev_bias": self._clamp(ev_bias, -2.0, 2.0),
            "confidence": confidence,
            "priority": self._compute_priority(confidence, framing_score),
        }
        return unified
    @staticmethod
    def _compute_priority(confidence: float, framing_score: float) -> float:
        """
        Higher priority = stronger recommendation to downstream AI.
        """
        return float(
            np.clip(0.7 * confidence + 0.3 * framing_score, 0.0, 1.0)
        )
# ==============================================================================
# END OF CHUNK 85 H 07
# ==============================================================================
# ==============================================================================
# CHUNK 85 H 09 — CAMERA INTENT TEMPORAL SMOOTHING
# ==============================================================================
#
# Purpose:
#   Applies physically-plausible temporal smoothing to camera intent signals.
#   Prevents jitter and oscillation while preserving fast reaction to real motion.
#
# Design:
#   - Dual-rate EMA (attack / release)
#   - Confidence-weighted smoothing
#   - Axis-decoupled (pan, tilt, zoom, EV)
#
# ==============================================================================

import numpy as np


class CameraIntentTemporalSmoothing:
    """
    Temporal smoother for camera intent packets.
    """
    def __init__(
        self,
        attack_tau: float = 0.15,
        release_tau: float = 0.35,
        ev_tau: float = 0.45,
        min_confidence: float = 0.15,
    ):
        self.attack_tau = float(attack_tau)
        self.release_tau = float(release_tau)
        self.ev_tau = float(ev_tau)
        self.min_confidence = float(min_confidence)
        self._state = None
    @staticmethod
    def _ema(prev: float, curr: float, tau: float) -> float:
        """
        Exponential moving average.
        """
        alpha = np.clip(1.0 - np.exp(-1.0 / max(tau, 1e-4)), 0.0, 1.0)
        return prev + alpha * (curr - prev)
    def _smooth_axis(
        self,
        prev: float,
        curr: float,
        confidence: float,
    ) -> float:
        """
        Uses faster attack when magnitude increases,
        slower release when settling.
        """
        delta = abs(curr) - abs(prev)
        tau = self.attack_tau if delta > 0 else self.release_tau
        tau *= np.clip(1.0 / max(confidence, self.min_confidence), 0.6, 2.0)
        return self._ema(prev, curr, tau)
    def apply(self, intent: dict) -> dict:
        """
        Parameters:
            intent : unified camera intent (from CameraIntentFusion)
        Returns:
            smoothed_intent : dict
        """
        if self._state is None:
            self._state = intent.copy()
            return intent
        conf = intent.get("confidence", 1.0)
        pan = self._smooth_axis(
            self._state["pan"], intent["pan"], conf
        )
        tilt = self._smooth_axis(
            self._state["tilt"], intent["tilt"], conf
        )
        zoom = self._smooth_axis(
            self._state.get("zoom", 0.0),
            intent.get("zoom", 0.0),
            conf,
        )
        ev_bias = self._ema(
            self._state.get("ev_bias", 0.0),
            intent.get("ev_bias", 0.0),
            self.ev_tau,
        )
        smoothed = {
            "pan": float(np.clip(pan, -1.0, 1.0)),
            "tilt": float(np.clip(tilt, -1.0, 1.0)),
            "zoom": float(np.clip(zoom, -1.0, 1.0)),
            "ev_bias": float(np.clip(ev_bias, -2.0, 2.0)),
            "confidence": conf,
            "priority": intent.get("priority", 0.5),
        }
        self._state = smoothed
        return smoothed
# ==============================================================================
# END OF CHUNK 85 H 09
# ==============================================================================
# ==============================================================================
# CHUNK 85 I 01 — CAMERA-SIDE INTENT PACKET SERIALIZATION
# ==============================================================================
#
# Purpose:
#   Serializes camera AI intent into a deterministic, versioned packet.
#   Optimized for low latency, forward compatibility, and auditability.
#
# Design:
#   - Explicit schema + versioning
#   - Float quantization to reduce payload size
#   - JSON-first (CBOR-ready)
#
# ==============================================================================

import json
import time
import math
from typing import Dict, Any


class CameraIntentSerializer:
    """
    Serializes unified camera intent for transport.
    """
    SCHEMA_VERSION = "85I.01"
    def __init__(
        self,
        quantize_decimals: int = 4,
        clamp_pan_tilt: float = 1.0,
        clamp_zoom: float = 1.0,
        clamp_ev: float = 2.0,
    ):
        self.quantize_decimals = int(quantize_decimals)
        self.clamp_pan_tilt = float(clamp_pan_tilt)
        self.clamp_zoom = float(clamp_zoom)
        self.clamp_ev = float(clamp_ev)
    @staticmethod
    def _clamp(x: float, lo: float, hi: float) -> float:
        return max(lo, min(hi, float(x)))
    def _q(self, x: float) -> float:
        """
        Quantize float to fixed decimals.
        """
        return round(float(x), self.quantize_decimals)
    def serialize(
        self,
        intent: Dict[str, Any],
        camera_id: str,
        frame_id: int,
    ) -> Dict[str, Any]:
        """
        Parameters:
            intent   : unified camera intent (post-smoothing)
            camera_id: unique camera identifier
            frame_id : monotonically increasing frame index
        Returns:
            packet : dict (JSON-safe)
        """
        pan = self._clamp(
            intent.get("pan", 0.0),
            -self.clamp_pan_tilt,
            self.clamp_pan_tilt,
        )
        tilt = self._clamp(
            intent.get("tilt", 0.0),
            -self.clamp_pan_tilt,
            self.clamp_pan_tilt,
        )
        zoom = self._clamp(
            intent.get("zoom", 0.0),
            -self.clamp_zoom,
            self.clamp_zoom,
        )
        ev_bias = self._clamp(
            intent.get("ev_bias", 0.0),
            -self.clamp_ev,
            self.clamp_ev,
        )
        packet = {
            "schema": self.SCHEMA_VERSION,
            "ts": time.time(),
            "camera_id": str(camera_id),
            "frame_id": int(frame_id),
            "intent": {
                "pan": self._q(pan),
                "tilt": self._q(tilt),
                "zoom": self._q(zoom),
                "ev_bias": self._q(ev_bias),
                "confidence": self._q(intent.get("confidence", 1.0)),
                "priority": self._q(intent.get("priority", 0.5)),
            },
        }
        return packet
    def to_json(self, packet: Dict[str, Any]) -> str:
        """
        JSON serialization with stable key order.
        """
        return json.dumps(
            packet,
            separators=(",", ":"),
            sort_keys=True,
        )
# ==============================================================================
# END OF CHUNK 85 I 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 I 02 — INTENT PACKET VALIDATION & SANITY CHECKS
# ==============================================================================
#
# Purpose:
#   Validates serialized camera intent packets before transmission.
#   Prevents malformed data, NaNs, time regressions, and out-of-range values.
#
# Guarantees:
#   - Schema/version compliance
#   - Numeric bounds and finiteness
#   - Monotonic frame/time ordering
#   - Safe null-intent substitution on failure
#
# ==============================================================================

import math
import time
from typing import Dict, Any, Tuple


class CameraIntentValidator:
    """
    Performs strict validation and sanitization of camera intent packets.
    """
    REQUIRED_TOP_KEYS = {"schema", "ts", "camera_id", "frame_id", "intent"}
    REQUIRED_INTENT_KEYS = {
        "pan",
        "tilt",
        "zoom",
        "ev_bias",
        "confidence",
        "priority",
    }
    def __init__(
        self,
        max_time_skew_s: float = 1.0,
        max_frame_jump: int = 3,
    ):
        self.max_time_skew_s = float(max_time_skew_s)
        self.max_frame_jump = int(max_frame_jump)
        self._last_ts = None
        self._last_frame = None
    @staticmethod
    def _is_finite(x: float) -> bool:
        return isinstance(x, (int, float)) and math.isfinite(x)
    @staticmethod
    def _clamp(x: float, lo: float, hi: float) -> float:
        return max(lo, min(hi, x))
    def _validate_structure(self, packet: Dict[str, Any]) -> Tuple[bool, str]:
        if not isinstance(packet, dict):
            return False, "packet_not_dict"
        if not self.REQUIRED_TOP_KEYS.issubset(packet.keys()):
            return False, "missing_top_keys"
        if not isinstance(packet["intent"], dict):
            return False, "intent_not_dict"
        if not self.REQUIRED_INTENT_KEYS.issubset(
            packet["intent"].keys()
        ):
            return False, "missing_intent_keys"
        return True, "ok"
    def _validate_numeric_ranges(self, intent: Dict[str, Any]) -> Tuple[bool, str]:
        checks = {
            "pan": (-1.0, 1.0),
            "tilt": (-1.0, 1.0),
            "zoom": (-1.0, 1.0),
            "ev_bias": (-2.0, 2.0),
            "confidence": (0.0, 1.0),
            "priority": (0.0, 1.0),
        }
        for k, (lo, hi) in checks.items():
            v = intent.get(k)
            if not self._is_finite(v):
                return False, f"non_finite_{k}"
            if v < lo - 1e-6 or v > hi + 1e-6:
                return False, f"out_of_range_{k}"
        return True, "ok"
    def _validate_time_and_frame(
        self, ts: float, frame_id: int
    ) -> Tuple[bool, str]:
        now = time.time()
        if abs(ts - now) > self.max_time_skew_s:
            return False, "time_skew"
        if self._last_frame is not None:
            if frame_id < self._last_frame:
                return False, "frame_regression"
            if frame_id - self._last_frame > self.max_frame_jump:
                return False, "frame_jump"
        return True, "ok"
    def _null_intent(self, packet: Dict[str, Any]) -> Dict[str, Any]:
        """
        Safe fallback intent: no motion, neutral exposure.
        """
        packet = dict(packet)
        packet["intent"] = {
            "pan": 0.0,
            "tilt": 0.0,
            "zoom": 0.0,
            "ev_bias": 0.0,
            "confidence": 0.0,
            "priority": 0.0,
        }
        packet["validation"] = "null_fallback"
        return packet
    def validate(self, packet: Dict[str, Any]) -> Dict[str, Any]:
        """
        Returns:
            validated_packet (may be null-intent if invalid)
        """
        ok, reason = self._validate_structure(packet)
        if not ok:
            return self._null_intent(packet)
        ok, reason = self._validate_numeric_ranges(packet["intent"])
        if not ok:
            return self._null_intent(packet)
        ok, reason = self._validate_time_and_frame(
            packet["ts"], packet["frame_id"]
        )
        if not ok:
            return self._null_intent(packet)
        # Passed validation
        self._last_ts = packet["ts"]
        self._last_frame = packet["frame_id"]
        packet["validation"] = "ok"
        return packet
# ==============================================================================
# END OF CHUNK 85 I 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 I 04 — LATENCY & CLOCK SKEW TAGGING
# ==============================================================================
#
# Purpose:
#   Attaches latency and clock-skew metadata to camera intent packets.
#   Enables downstream AI to align intents with frames deterministically.
#
# Design:
#   - Monotonic time where available
#   - Transport-agnostic
#   - Skew-safe (bounded deltas)
#
# ==============================================================================

import time
import math
from typing import Dict, Any


class CameraLatencyTagger:
    """
    Adds latency and clock-skew annotations to intent packets.
    """
    def __init__(
        self,
        max_skew_s: float = 0.5,
        max_latency_s: float = 1.0,
    ):
        self.max_skew_s = float(max_skew_s)
        self.max_latency_s = float(max_latency_s)
        self._last_mono = None
    @staticmethod
    def _mono_time() -> float:
        """
        Returns monotonic time if available.
        """
        try:
            return time.monotonic()
        except Exception:
            return time.time()
    @staticmethod
    def _clamp(x: float, lo: float, hi: float) -> float:
        return max(lo, min(hi, float(x)))
    def tag(self, packet: Dict[str, Any]) -> Dict[str, Any]:
        """
        Parameters:
            packet : validated camera intent packet
        Returns:
            packet_with_latency : dict
        """
        now_wall = time.time()
        now_mono = self._mono_time()
        ts = float(packet.get("ts", now_wall))
        # Wall-clock skew
        skew = now_wall - ts
        skew = self._clamp(skew, -self.max_skew_s, self.max_skew_s)
        # Inter-packet monotonic delta
        if self._last_mono is None:
            mono_delta = 0.0
        else:
            mono_delta = now_mono - self._last_mono
            mono_delta = self._clamp(
                mono_delta, 0.0, self.max_latency_s
            )
        self._last_mono = now_mono
        latency_meta = {
            "t_wall_send": self._clamp(ts, ts - self.max_latency_s, ts + self.max_latency_s),
            "t_wall_tag": now_wall,
            "t_mono_delta": mono_delta,
            "clock_skew": skew,
        }
        packet = dict(packet)
        packet["latency"] = latency_meta
        return packet
# ==============================================================================
# END OF CHUNK 85 I 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 I 05 — MULTI-CAMERA INTENT MERGING
# ==============================================================================
#
# Purpose:
#   Merges multiple camera intent packets into a single coherent intent.
#   Used when internal + external cameras both produce AI signals.
#
# Design:
#   - Confidence-weighted blending
#   - Priority arbitration
#   - Deterministic resolution
#
# ==============================================================================

from typing import Dict, List
import numpy as np


class MultiCameraIntentMerger:
    """
    Merges multiple camera intent packets into one.
    """
    def __init__(
        self,
        min_confidence: float = 0.10,
        dominance_threshold: float = 0.65,
    ):
        self.min_confidence = float(min_confidence)
        self.dominance_threshold = float(dominance_threshold)
    @staticmethod
    def _blend(a: float, b: float, wa: float, wb: float) -> float:
        wsum = wa + wb
        if wsum <= 1e-6:
            return 0.0
        return (a * wa + b * wb) / wsum
    def merge(self, packets: List[Dict]) -> Dict:
        """
        Parameters:
            packets : list of validated, latency-tagged intent packets
        Returns:
            merged_packet : dict
        """
        valid = [
            p for p in packets
            if p["intent"]["confidence"] >= self.min_confidence
        ]
        if not valid:
            return packets[0]
        if len(valid) == 1:
            return valid[0]
        valid = sorted(
            valid,
            key=lambda p: p["intent"]["priority"],
            reverse=True,
        )
        lead = valid[0]
        second = valid[1]
        if lead["intent"]["confidence"] >= self.dominance_threshold:
            return lead
        w1 = lead["intent"]["confidence"]
        w2 = second["intent"]["confidence"]
        merged_intent = {
            "pan": self._blend(
                lead["intent"]["pan"],
                second["intent"]["pan"],
                w1, w2,
            ),
            "tilt": self._blend(
                lead["intent"]["tilt"],
                second["intent"]["tilt"],
                w1, w2,
            ),
            "zoom": self._blend(
                lead["intent"]["zoom"],
                second["intent"]["zoom"],
                w1, w2,
            ),
            "ev_bias": self._blend(
                lead["intent"]["ev_bias"],
                second["intent"]["ev_bias"],
                w1, w2,
            ),
            "confidence": max(w1, w2),
            "priority": max(
                lead["intent"]["priority"],
                second["intent"]["priority"],
            ),
        }
        merged = dict(lead)
        merged["intent"] = merged_intent
        merged["merge"] = "confidence_weighted"
        return merged
