# ==============================================================================
# CHUNK 85 I 06 — FAILSAFE NULL-INTENT FALLBACK
# ==============================================================================
#
# Purpose:
#   Provides a deterministic, safe fallback intent when camera AI
#   confidence collapses, packets are invalid, or timing is violated.
#
# Design:
#   - Zero-motion, neutral exposure
#   - Explicit reason tagging
#   - Hard-bounded output (never NaN)
#
# ==============================================================================

from typing import Dict, Any
import time


class CameraNullIntentFallback:
    """
    Generates a safe null camera intent.
    """
    def __init__(
        self,
        min_confidence: float = 0.10,
        max_latency_s: float = 1.0,
    ):
        self.min_confidence = float(min_confidence)
        self.max_latency_s = float(max_latency_s)
    def should_fallback(self, packet: Dict[str, Any]) -> bool:
        """
        Determines whether fallback must be applied.
        """
        intent = packet.get("intent", {})
        conf = intent.get("confidence", 0.0)
        if conf < self.min_confidence:
            return True
        latency = packet.get("latency", {})
        if latency:
            now = time.time()
            ts = latency.get("t_wall_send", now)
            if abs(now - ts) > self.max_latency_s:
                return True
        if packet.get("validation") != "ok":
            return True
        return False
    def apply(self, packet: Dict[str, Any], reason: str = "failsafe") -> Dict[str, Any]:
        """
        Returns a null-intent packet.
        """
        null_packet = dict(packet)
        null_packet["intent"] = {
            "pan": 0.0,
            "tilt": 0.0,
            "zoom": 0.0,
            "ev_bias": 0.0,
            "confidence": 0.0,
            "priority": 0.0,
        }
        null_packet["failsafe"] = {
            "active": True,
            "reason": reason,
        }
        return null_packet
