# ==============================================================================
# CHUNK 85 I 08 — CBOR / BINARY COMPACT ENCODING
# ==============================================================================
#
# Purpose:
#   Encodes validated camera intent packets into compact binary form.
#   Reduces payload size, CPU overhead, and transmission latency.
#
# Design:
#   - CBOR primary (RFC 7049 / 8949)
#   - Deterministic key ordering
#   - Optional float down-casting
#
# ==============================================================================

from typing import Dict, Any, Optional
import struct
try:
    import cbor2
    _CBOR_AVAILABLE = True
except Exception:
    _CBOR_AVAILABLE = False


class CameraIntentBinaryEncoder:
    """
    Encodes camera intent packets into compact binary form.
    """
    SCHEMA_VERSION = "85I.08"
    def __init__(
        self,
        use_cbor: bool = True,
        float16: bool = False,
    ):
        self.use_cbor = bool(use_cbor and _CBOR_AVAILABLE)
        self.float16 = bool(float16)
    @staticmethod
    def _to_float16(x: float) -> float:
        """
        Down-cast float to IEEE-754 half precision and back.
        """
        return struct.unpack(
            "e", struct.pack("e", float(x))
        )[0]
    def _quantize_intent(self, intent: Dict[str, Any]) -> Dict[str, Any]:
        """
        Optionally reduces float precision for transport.
        """
        if not self.float16:
            return intent
        q = {}
        for k, v in intent.items():
            if isinstance(v, float):
                q[k] = self._to_float16(v)
            else:
                q[k] = v
        return q
    def encode(self, packet: Dict[str, Any]) -> bytes:
        """
        Encodes packet to binary.
        """
        payload = {
            "schema": self.SCHEMA_VERSION,
            "camera_id": packet.get("camera_id"),
            "frame_id": packet.get("frame_id"),
            "ts": packet.get("ts"),
            "intent": self._quantize_intent(packet.get("intent", {})),
            "latency": packet.get("latency", {}),
            "validation": packet.get("validation", "ok"),
        }
        if self.use_cbor:
            return cbor2.dumps(payload)
        # Fallback: simple struct-based binary (fixed order)
        intent = payload["intent"]
        return struct.pack(
            "!4f2f",
            float(intent.get("pan", 0.0)),
            float(intent.get("tilt", 0.0)),
            float(intent.get("zoom", 0.0)),
            float(intent.get("ev_bias", 0.0)),
            float(intent.get("confidence", 0.0)),
            float(intent.get("priority", 0.0)),
        )
    def decode(self, blob: bytes) -> Optional[Dict[str, Any]]:
        """
        Decodes binary payload back to dict (CBOR only).
        """
        if not self.use_cbor:
            return None
        return cbor2.loads(blob)
