# ==============================================================================
# CHUNK 85 J 01 — RADXA CAMERA AI TRANSMIT LOOP
# ==============================================================================
#
# Purpose:
#   Runs the camera-AI egress loop on Radxa.
#   Pulls finalized intent packets and transmits them with bounded latency.
#
# Design:
#   - Transport-agnostic (UDP/TCP/WS)
#   - Non-blocking, drop-oldest under backpressure
#   - Deterministic cadence with jitter tolerance
#
# ==============================================================================

import socket
import threading
import time
from collections import deque
from typing import Callable, Optional


class CameraAITransmitLoop:
    """
    Camera AI transmit loop for Radxa.
    """
    def __init__(
        self,
        encoder,                     # CameraIntentBinaryEncoder
        endpoint: tuple,              # (host, port)
        transport: str = "udp",       # "udp" | "tcp"
        target_hz: float = 30.0,
        queue_size: int = 64,
        socket_timeout_s: float = 0.01,
    ):
        self.encoder = encoder
        self.endpoint = endpoint
        self.transport = transport.lower()
        self.target_hz = float(target_hz)
        self.queue_size = int(queue_size)
        self.socket_timeout_s = float(socket_timeout_s)
        self._queue = deque(maxlen=self.queue_size)
        self._thread = None
        self._running = False
        self._sock = None
    def _init_socket(self):
        if self.transport == "udp":
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        elif self.transport == "tcp":
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.connect(self.endpoint)
        else:
            raise ValueError("unsupported_transport")
        sock.settimeout(self.socket_timeout_s)
        self._sock = sock
    def push(self, packet: dict):
        """
        Pushes a prepared packet into transmit queue.
        Oldest packets are dropped under pressure.
        """
        if len(self._queue) >= self.queue_size:
            self._queue.popleft()
        self._queue.append(packet)
    def _send(self, blob: bytes):
        if self.transport == "udp":
            self._sock.sendto(blob, self.endpoint)
        else:
            self._sock.sendall(blob)
    def _loop(self):
        period = 1.0 / max(self.target_hz, 1.0)
        next_t = time.time()
        while self._running:
            now = time.time()
            if now < next_t:
                time.sleep(max(0.0, next_t - now))
            next_t += period
            if not self._queue:
                continue
            packet = self._queue.pop()
            try:
                blob = self.encoder.encode(packet)
                self._send(blob)
            except Exception:
                # Silent drop; health handled elsewhere
                pass
    def start(self):
        if self._running:
            return
        self._init_socket()
        self._running = True
        self._thread = threading.Thread(
            target=self._loop,
            daemon=True,
        )
        self._thread.start()
    def stop(self):
        self._running = False
        if self._thread:
            self._thread.join(timeout=0.5)
        if self._sock:
            try:
                self._sock.close()
            except Exception:
                pass
# ==============================================================================
# END OF CHUNK 85 J 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 J 02 — TRANSMIT RATE CONTROL & BACKPRESSURE
# ==============================================================================
#
# Purpose:
#   Dynamically regulates camera intent transmit rate based on
#   queue depth, send latency, and downstream pressure.
#
# Design:
#   - Soft backpressure via adaptive FPS
#   - Never blocks camera AI thread
#   - Perceptually smooth rate changes
#
# ==============================================================================

import time
import math


class CameraTransmitRateController:
    """
    Adaptive rate controller for camera AI transmit loop.
    """
    def __init__(
        self,
        base_hz: float = 30.0,
        min_hz: float = 10.0,
        max_hz: float = 60.0,
        queue_soft_limit: int = 24,
        queue_hard_limit: int = 48,
        smoothing_tau: float = 0.4,
    ):
        self.base_hz = float(base_hz)
        self.min_hz = float(min_hz)
        self.max_hz = float(max_hz)
        self.queue_soft_limit = int(queue_soft_limit)
        self.queue_hard_limit = int(queue_hard_limit)
        self.smoothing_tau = float(smoothing_tau)
        self._current_hz = self.base_hz
        self._last_update = time.time()
    @staticmethod
    def _ema(prev: float, target: float, tau: float) -> float:
        alpha = 1.0 - math.exp(-1.0 / max(tau, 1e-4))
        return prev + alpha * (target - prev)
    def update(self, queue_depth: int) -> float:
        """
        Computes a new transmit rate based on queue depth.
        Returns:
            new_hz : float
        """
        if queue_depth >= self.queue_hard_limit:
            target_hz = self.min_hz
        elif queue_depth >= self.queue_soft_limit:
            frac = (
                (queue_depth - self.queue_soft_limit)
                / max(1, self.queue_hard_limit - self.queue_soft_limit)
            )
            target_hz = (
                self.base_hz
                - frac * (self.base_hz - self.min_hz)
            )
        else:
            target_hz = self.max_hz
        target_hz = max(self.min_hz, min(self.max_hz, target_hz))
        now = time.time()
        dt = now - self._last_update
        self._last_update = now
        self._current_hz = self._ema(
            self._current_hz,
            target_hz,
            self.smoothing_tau,
        )
        return self._current_hz
