# ==============================================================================
# CHUNK 85 J 03 — CAMERA AI HEALTH HEARTBEAT
# ==============================================================================
#
# Purpose:
#   Emit a lightweight, periodic health heartbeat from the camera AI runtime
#   (Radxa-side) to upstream consumers (VPS / Laptop / Cloud Router).
#
# Guarantees:
#   - Zero blocking of inference threads
#   - Bounded payload size
#   - Deterministic cadence with jitter tolerance
#
# Payload includes:
#   - monotonic timestamp
#   - inference FPS (smoothed)
#   - queue depth
#   - dropped-frame counters
#   - thermal / load summary (if available)
#
# ==============================================================================

import time
import threading
from typing import Callable, Dict, Optional


class CameraAIHeartbeat:
    """
    Periodic health heartbeat emitter for camera AI.
    """
    def __init__(
        self,
        emit_fn: Callable[[Dict], None],
        interval_sec: float = 1.0,
    ):
        self.emit_fn = emit_fn
        self.interval_sec = float(interval_sec)
        self._lock = threading.Lock()
        self._running = False
        self._thread: Optional[threading.Thread] = None
        # Metrics (updated by camera AI runtime)
        self._fps_ema = 0.0
        self._queue_depth = 0
        self._dropped_frames = 0
        self._last_emit = 0.0
        # Optional system stats
        self._cpu_load = None
        self._temp_c = None
    def update_metrics(
        self,
        fps_ema: float,
        queue_depth: int,
        dropped_frames: int,
        cpu_load: Optional[float] = None,
        temp_c: Optional[float] = None,
    ) -> None:
        with self._lock:
            self._fps_ema = float(fps_ema)
            self._queue_depth = int(queue_depth)
            self._dropped_frames = int(dropped_frames)
            self._cpu_load = cpu_load
            self._temp_c = temp_c
    def _build_payload(self) -> Dict:
        with self._lock:
            payload = {
                "ts_monotonic": time.monotonic(),
                "fps_ema": round(self._fps_ema, 3),
                "queue_depth": self._queue_depth,
                "dropped_frames": self._dropped_frames,
            }
            if self._cpu_load is not None:
                payload["cpu_load"] = round(float(self._cpu_load), 3)
            if self._temp_c is not None:
                payload["temp_c"] = round(float(self._temp_c), 2)
        return payload
    def _run(self) -> None:
        self._last_emit = time.monotonic()
        while self._running:
            now = time.monotonic()
            if now - self._last_emit >= self.interval_sec:
                payload = self._build_payload()
                try:
                    self.emit_fn(payload)
                except Exception:
                    # Heartbeat must never crash camera AI
                    pass
                self._last_emit = now
            # Short sleep to keep timing accurate without busy-wait
            time.sleep(min(0.05, self.interval_sec * 0.25))
    def start(self) -> None:
        if self._running:
            return
        self._running = True
        self._thread = threading.Thread(
            target=self._run,
            name="CameraAIHeartbeat",
            daemon=True,
        )
        self._thread.start()
    def stop(self) -> None:
        self._running = False
        if self._thread is not None:
            self._thread.join(timeout=1.0)
            self._thread = None
