# ==============================================================================
# CHUNK 85 J 04 — CAMERA AI WATCHDOG & AUTO-RESET
# ==============================================================================
#
# Purpose:
#   Detect stalled inference / transmit loops and recover automatically
#   without operator intervention or system reboot.
#
# Guarantees:
#   - Never interferes with realtime inference threads
#   - Bounded false positives via grace windows
#   - Deterministic recovery path
#
# Recovery Actions (escalating):
#   1. Soft signal (state reset)
#   2. Pipeline restart callback
#   3. Full camera AI process restart hook
#
# ==============================================================================

import time
import threading
from typing import Callable, Optional


class CameraAIWatchdog:
    """
    Watchdog supervising camera AI liveness and progress.
    """
    def __init__(
        self,
        stall_timeout_sec: float = 2.5,
        check_interval_sec: float = 0.5,
        on_soft_reset: Optional[Callable[[], None]] = None,
        on_pipeline_restart: Optional[Callable[[], None]] = None,
        on_process_restart: Optional[Callable[[], None]] = None,
    ):
        self.stall_timeout_sec = float(stall_timeout_sec)
        self.check_interval_sec = float(check_interval_sec)
        self.on_soft_reset = on_soft_reset
        self.on_pipeline_restart = on_pipeline_restart
        self.on_process_restart = on_process_restart
        self._lock = threading.Lock()
        self._running = False
        self._thread: Optional[threading.Thread] = None
        self._last_progress_ts = time.monotonic()
        self._stall_count = 0
    def notify_progress(self) -> None:
        """
        Must be called by camera AI runtime whenever forward progress occurs:
        frame processed, intent emitted, or queue drained.
        """
        with self._lock:
            self._last_progress_ts = time.monotonic()
            self._stall_count = 0
    def _handle_stall(self) -> None:
        """
        Escalating recovery strategy.
        """
        self._stall_count += 1
        if self._stall_count == 1:
            if self.on_soft_reset:
                try:
                    self.on_soft_reset()
                except Exception:
                    pass
        elif self._stall_count == 2:
            if self.on_pipeline_restart:
                try:
                    self.on_pipeline_restart()
                except Exception:
                    pass
        elif self._stall_count >= 3:
            if self.on_process_restart:
                try:
                    self.on_process_restart()
                except Exception:
                    pass
    def _run(self) -> None:
        while self._running:
            now = time.monotonic()
            with self._lock:
                elapsed = now - self._last_progress_ts
            if elapsed >= self.stall_timeout_sec:
                self._handle_stall()
            time.sleep(self.check_interval_sec)
    def start(self) -> None:
        if self._running:
            return
        self._running = True
        self._thread = threading.Thread(
            target=self._run,
            name="CameraAIWatchdog",
            daemon=True,
        )
        self._thread.start()
    def stop(self) -> None:
        self._running = False
        if self._thread is not None:
            self._thread.join(timeout=1.0)
            self._thread = None
