# ==============================================================================
# CHUNK 85 J 05 — CAMERA AI CONFIG HOT-RELOAD
# ==============================================================================
#
# Purpose:
#   Enable live, zero-downtime reconfiguration of camera-AI parameters
#   (rates, thresholds, feature toggles) while inference is running.
#
# Guarantees:
#   - Atomic config swaps
#   - No frame drops during reload
#   - Validation before apply
#
# ==============================================================================

import threading
import json
import time
from typing import Callable, Dict, Optional


class CameraAIConfigManager:
    """
    Hot-reloadable configuration manager for camera AI runtime.
    """
    def __init__(
        self,
        load_fn: Callable[[], Dict],
        validate_fn: Optional[Callable[[Dict], bool]] = None,
        on_apply_fn: Optional[Callable[[Dict], None]] = None,
    ):
        self.load_fn = load_fn
        self.validate_fn = validate_fn
        self.on_apply_fn = on_apply_fn
        self._lock = threading.Lock()
        self._active_config: Dict = {}
        self._last_reload_ts = 0.0
    def load_initial(self) -> Dict:
        cfg = self.load_fn()
        if self.validate_fn and not self.validate_fn(cfg):
            raise ValueError("Initial camera AI config invalid")
        with self._lock:
            self._active_config = cfg
        return cfg
    def reload(self) -> bool:
        """
        Reload configuration from source and apply atomically.
        Returns True if applied, False if rejected.
        """
        try:
            new_cfg = self.load_fn()
        except Exception:
            return False
        if self.validate_fn and not self.validate_fn(new_cfg):
            return False
        with self._lock:
            self._active_config = new_cfg
            self._last_reload_ts = time.monotonic()
        if self.on_apply_fn:
            try:
                self.on_apply_fn(new_cfg)
            except Exception:
                pass
        return True
    def get(self) -> Dict:
        with self._lock:
            return dict(self._active_config)
    @property
    def last_reload_age(self) -> float:
        return time.monotonic() - self._last_reload_ts
