# ==============================================================================
# ==============================================================================
# CHUNK 85 J 07 — CAMERA AI OUTPUT QUALITY FEEDBACK LOOP
# ==============================================================================
#
# Purpose:
#   Continuously evaluate the perceptual quality and temporal reliability
#   of camera-AI outputs and feed corrective signals back into upstream
#   inference, intent generation, and stabilization stages.
#
# Why this matters:
#   Hollywood-grade cinematography depends on:
#     - confidence stability
#     - motion coherence
#     - absence of micro-oscillation
#
# This loop is what prevents "AI twitch".
#
# ==============================================================================

import math
import time
from collections import deque
from typing import Dict, Tuple


class CameraAIOutputQualityLoop:
    """
    Evaluates temporal quality of camera AI outputs and emits
    corrective gains for upstream modules.
    """
    def __init__(
        self,
        window: int = 20,
        min_confidence: float = 0.55,
        max_motion_energy: float = 1.25,
    ):
        self.window = int(window)
        self.min_confidence = float(min_confidence)
        self.max_motion_energy = float(max_motion_energy)
        self._confidence_hist = deque(maxlen=self.window)
        self._motion_hist = deque(maxlen=self.window)
        self._timestamp_hist = deque(maxlen=self.window)
    def _variance(self, values) -> float:
        if len(values) < 2:
            return 0.0
        mean = sum(values) / len(values)
        return sum((v - mean) ** 2 for v in values) / len(values)
    def update(
        self,
        confidence: float,
        motion_energy: float,
    ) -> Dict[str, float]:
        """
        Update quality metrics and return correction multipliers.
        Returns:
            dict with:
              - confidence_gain
              - stability_gain
              - damping_gain
        """
        now = time.monotonic()
        self._confidence_hist.append(float(confidence))
        self._motion_hist.append(float(motion_energy))
        self._timestamp_hist.append(now)
        conf_avg = sum(self._confidence_hist) / len(self._confidence_hist)
        conf_var = self._variance(self._confidence_hist)
        motion_avg = sum(self._motion_hist) / len(self._motion_hist)
        motion_var = self._variance(self._motion_hist)
        # --- Confidence correction ---
        if conf_avg < self.min_confidence:
            confidence_gain = max(
                0.5,
                conf_avg / max(self.min_confidence, 1e-6),
            )
        else:
            confidence_gain = 1.0
        # --- Stability correction ---
        stability_gain = 1.0 / (1.0 + math.sqrt(motion_var))
        # --- Damping against high-frequency oscillation ---
        if motion_avg > self.max_motion_energy:
            damping_gain = self.max_motion_energy / motion_avg
        else:
            damping_gain = 1.0
        return {
            "confidence_gain": round(confidence_gain, 4),
            "stability_gain": round(stability_gain, 4),
            "damping_gain": round(damping_gain, 4),
        }
# ==============================================================================
# END OF CHUNK 85 J 07
# ==============================================================================
# ==============================================================================
# CHUNK 85 J 09 — TEMPORAL COHERENCE ENFORCER
# ==============================================================================
#
# Purpose:
#   Enforce strict temporal coherence on camera-AI intent outputs to
#   eliminate jitter, snapping, and micro-oscillation while preserving
#   responsiveness required for cinematic motion.
#
# Design:
#   - Critically-damped smoothing (no laggy overshoot)
#   - Adaptive alpha based on motion energy
#   - Deterministic behavior (no randomness)
#
# ==============================================================================

import numpy as np
import math


class TemporalCoherenceEnforcer:
    """
    Applies adaptive temporal smoothing to intent vectors
    (e.g., pan/tilt/zoom/framing deltas).
    """
    def __init__(
        self,
        base_alpha: float = 0.85,
        min_alpha: float = 0.65,
        max_alpha: float = 0.92,
        energy_ref: float = 1.0,
    ):
        self.base_alpha = float(base_alpha)
        self.min_alpha = float(min_alpha)
        self.max_alpha = float(max_alpha)
        self.energy_ref = float(energy_ref)
        self._prev: np.ndarray | None = None
    def _adaptive_alpha(self, motion_energy: float) -> float:
        """
        Higher motion → lower alpha (more responsiveness)
        Lower motion → higher alpha (more stability)
        """
        if motion_energy <= 0.0:
            return self.max_alpha
        ratio = min(2.0, motion_energy / max(self.energy_ref, 1e-6))
        alpha = self.base_alpha - 0.15 * (ratio - 1.0)
        return float(
            max(self.min_alpha, min(self.max_alpha, alpha))
        )
    def apply(
        self,
        intent_vector: np.ndarray,
        motion_energy: float,
    ) -> np.ndarray:
        """
        Smooth the incoming intent vector.
        Args:
            intent_vector : ndarray (N,)
            motion_energy : scalar describing scene or subject motion
        """
        v = np.asarray(intent_vector, dtype=np.float32)
        if self._prev is None:
            self._prev = v.copy()
            return v
        alpha = self._adaptive_alpha(float(motion_energy))
        # Critically damped exponential smoothing
        out = alpha * self._prev + (1.0 - alpha) * v
        self._prev = out
        return out
# ==============================================================================
# END OF CHUNK 85 J 09
