# ==============================================================================
# CHUNK 85 K 01 — VPS INTENT INGEST ADAPTER
# ==============================================================================
#
# Purpose:
#   First authoritative entry-point on the VPS for any intent coming from
#   Camera AI (Radxa) or Laptop AI.
#
# Responsibilities:
#   - Canonicalize raw intent packets
#   - Enforce size and schema limits
#   - Attach deterministic metadata
#   - Prepare for validation & routing
#
# ==============================================================================

import time
import uuid
from typing import Dict, Any, Tuple, Optional


class VPSIntentIngestAdapter:
    """
    Canonical ingest adapter for all upstream AI intent sources.
    """
    MAX_PAYLOAD_BYTES = 64 * 1024
    def __init__(
        self,
        source_id: str,
        source_type: str = "camera_ai",
    ):
        self.source_id = str(source_id)
        self.source_type = str(source_type)
    def _estimate_size(self, obj: Any) -> int:
        try:
            return len(repr(obj).encode("utf-8"))
        except Exception:
            return self.MAX_PAYLOAD_BYTES + 1
    def _basic_checks(self, packet: Dict[str, Any]) -> Optional[str]:
        if not isinstance(packet, dict):
            return "packet_not_dict"
        if self._estimate_size(packet) > self.MAX_PAYLOAD_BYTES:
            return "packet_too_large"
        if "intent_type" not in packet:
            return "missing_intent_type"
        return None
    def ingest(
        self,
        packet: Dict[str, Any],
    ) -> Tuple[bool, Optional[Dict[str, Any]], Optional[str]]:
        """
        Returns:
            (ok, envelope, error_code)
        """
        err = self._basic_checks(packet)
        if err:
            return False, None, err
        now_mono = time.monotonic()
        now_wall = time.time()
        envelope = {
            "envelope_id": str(uuid.uuid4()),
            "source": {
                "id": self.source_id,
                "type": self.source_type,
            },
            "timestamps": {
                "origin_mono": packet.get("ts_monotonic"),
                "ingest_mono": now_mono,
                "ingest_wall": now_wall,
            },
            "intent": {
                "type": packet.get("intent_type"),
                "confidence": float(packet.get("confidence", 0.5)),
                "payload": packet.get("payload", {}),
            },
            "version": int(packet.get("version", 1)),
            "signature": packet.get("signature"),
        }
        return True, envelope, None
# ==============================================================================
# END OF CHUNK 85 K 01
