# ==============================================================================
# CHUNK 85 K 02 — VPS VALIDATION & AUTH LAYER
# ==============================================================================
#
# Purpose:
#   Hardened validation and authorization layer for all AI intents
#   arriving at the VPS. Ensures:
#     - Schema integrity
#     - Confidence sanity
#     - Source authorization
#     - Replay protection
#
# Notes:
#   This layer is intentionally lightweight and deterministic to
#   minimize latency while preventing malformed or hostile inputs
#   from propagating downstream.
#
# ==============================================================================

import hashlib
import hmac
import time
from typing import Dict, Any, Optional, Tuple


class VPSIntentAuthValidator:
    """
    Validates envelopes produced by VPSIntentIngestAdapter.
    """
    # Acceptable bounds tuned for cinematic intent reliability
    MIN_CONFIDENCE = 0.15
    MAX_CONFIDENCE = 0.99
    MAX_CLOCK_SKEW_SEC = 5.0
    def __init__(
        self,
        shared_secret: bytes,
        authorized_sources: Optional[Dict[str, str]] = None,
    ):
        self._secret = shared_secret
        self._authorized_sources = authorized_sources or {}
    def _verify_signature(self, envelope: Dict[str, Any]) -> bool:
        sig = envelope.get("signature")
        if not sig:
            return False
        body = repr({
            "source": envelope.get("source"),
            "intent": envelope.get("intent"),
            "version": envelope.get("version"),
        }).encode("utf-8")
        expected = hmac.new(
            self._secret,
            body,
            hashlib.sha256,
        ).hexdigest()
        return hmac.compare_digest(str(sig), expected)
    def _check_source(self, envelope: Dict[str, Any]) -> bool:
        src = envelope.get("source", {})
        src_id = src.get("id")
        src_type = src.get("type")
        if not src_id or not src_type:
            return False
        expected_type = self._authorized_sources.get(src_id)
        if expected_type is None:
            return False
        return expected_type == src_type
    def _check_confidence(self, envelope: Dict[str, Any]) -> bool:
        conf = envelope.get("intent", {}).get("confidence")
        if conf is None:
            return False
        try:
            conf = float(conf)
        except Exception:
            return False
        return self.MIN_CONFIDENCE <= conf <= self.MAX_CONFIDENCE
    def _check_timestamps(self, envelope: Dict[str, Any]) -> bool:
        ts = envelope.get("timestamps", {})
        ingest_wall = ts.get("ingest_wall")
        if ingest_wall is None:
            return False
        now = time.time()
        return abs(now - float(ingest_wall)) <= self.MAX_CLOCK_SKEW_SEC
    def validate(
        self,
        envelope: Dict[str, Any],
    ) -> Tuple[bool, Optional[str]]:
        """
        Returns:
            (ok, error_code)
        """
        if not isinstance(envelope, dict):
            return False, "invalid_envelope_type"
        if not self._check_source(envelope):
            return False, "unauthorized_source"
        if not self._check_confidence(envelope):
            return False, "confidence_out_of_bounds"
        if not self._check_timestamps(envelope):
            return False, "timestamp_skew"
        if not self._verify_signature(envelope):
            return False, "signature_mismatch"
        return True, None
# ==============================================================================
# END OF CHUNK 85 K 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 K 03 — VPS BACKPRESSURE TO CAMERA AI
# ==============================================================================
#
# Purpose:
#   Provide deterministic, low-latency backpressure from VPS to upstream
#   Camera AI / Laptop AI sources to prevent overload, oscillation, or
#   runaway intent emission under high compute or network contention.
#
# Core Concepts:
#   - Token-bucket rate control per source
#   - Adaptive cooldown windows
#   - Explicit feedback hints (throttle / resume)
#
# ==============================================================================

import time
from typing import Dict, Any, Tuple


class VPSBackpressureController:
    """
    Adaptive backpressure controller for AI intent sources.
    """
    DEFAULT_RATE = 20.0          # intents/sec
    BURST_CAPACITY = 10.0        # max burst tokens
    COOLDOWN_SEC = 0.25
    def __init__(self):
        self._sources: Dict[str, Dict[str, float]] = {}
    def _now(self) -> float:
        return time.monotonic()
    def _init_source(self, source_id: str):
        self._sources[source_id] = {
            "tokens": self.BURST_CAPACITY,
            "last_refill": self._now(),
            "rate": self.DEFAULT_RATE,
            "cooldown_until": 0.0,
        }
    def _refill(self, state: Dict[str, float]):
        now = self._now()
        elapsed = now - state["last_refill"]
        if elapsed <= 0:
            return
        refill = elapsed * state["rate"]
        state["tokens"] = min(
            self.BURST_CAPACITY,
            state["tokens"] + refill,
        )
        state["last_refill"] = now
    def evaluate(
        self,
        source_id: str,
    ) -> Tuple[bool, Dict[str, Any]]:
        """
        Returns:
            (allow, feedback)
        """
        if source_id not in self._sources:
            self._init_source(source_id)
        state = self._sources[source_id]
        now = self._now()
        # Cooldown enforcement
        if now < state["cooldown_until"]:
            return False, {
                "action": "throttle",
                "retry_after": state["cooldown_until"] - now,
            }
        self._refill(state)
        if state["tokens"] >= 1.0:
            state["tokens"] -= 1.0
            return True, {
                "action": "ok",
                "tokens_left": state["tokens"],
            }
        # Token starvation → apply cooldown
        state["cooldown_until"] = now + self.COOLDOWN_SEC
        return False, {
            "action": "throttle",
            "retry_after": self.COOLDOWN_SEC,
        }
    def tune_rate(
        self,
        source_id: str,
        new_rate: float,
    ):
        if source_id not in self._sources:
            self._init_source(source_id)
        self._sources[source_id]["rate"] = max(1.0, float(new_rate))
# ==============================================================================
# END OF CHUNK 85 K 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 K 04 — VPS INTENT NORMALIZATION
# ==============================================================================
#
# Purpose:
#   Convert validated AI intent envelopes into a canonical, deterministic
#   structure consumed by downstream cinematic planners and flight-safe
#   command mappers. This stage:
#     - Normalizes coordinate frames and units
#     - Clamps semantic ranges
#     - Resolves defaults deterministically
#     - Attaches derived fields for downstream efficiency
#
# ==============================================================================

from typing import Dict, Any
import math


class VPSIntentNormalizer:
    """
    Canonical intent normalization.
    """
    # Semantic bounds (cinematic-safe)
    MAX_SPEED_MPS = 15.0
    MAX_YAW_RATE_DPS = 90.0
    MAX_ALT_DELTA_M = 10.0
    def __init__(self):
        pass
    def _clamp(self, v: float, lo: float, hi: float) -> float:
        return max(lo, min(hi, v))
    def _normalize_vector(self, vec: Dict[str, Any]) -> Dict[str, float]:
        """
        Normalize motion vectors to SI units and safe ranges.
        """
        vx = float(vec.get("vx", 0.0))
        vy = float(vec.get("vy", 0.0))
        vz = float(vec.get("vz", 0.0))
        mag = math.sqrt(vx * vx + vy * vy + vz * vz)
        if mag > self.MAX_SPEED_MPS and mag > 0:
            scale = self.MAX_SPEED_MPS / mag
            vx *= scale
            vy *= scale
            vz *= scale
        return {
            "vx_mps": vx,
            "vy_mps": vy,
            "vz_mps": vz,
        }
    def normalize(self, envelope: Dict[str, Any]) -> Dict[str, Any]:
        intent = envelope.get("intent", {})
        payload = intent.get("payload", {})
        motion = payload.get("motion", {})
        camera = payload.get("camera", {})
        norm_motion = self._normalize_vector(motion)
        yaw_rate = self._clamp(
            float(motion.get("yaw_rate_dps", 0.0)),
            -self.MAX_YAW_RATE_DPS,
            self.MAX_YAW_RATE_DPS,
        )
        alt_delta = self._clamp(
            float(motion.get("alt_delta_m", 0.0)),
            -self.MAX_ALT_DELTA_M,
            self.MAX_ALT_DELTA_M,
        )
        normalized = {
            "envelope_id": envelope.get("envelope_id"),
            "source": envelope.get("source"),
            "intent_type": intent.get("type"),
            "confidence": float(intent.get("confidence", 0.5)),
            "motion": {
                **norm_motion,
                "yaw_rate_dps": yaw_rate,
                "alt_delta_m": alt_delta,
            },
            "camera": {
                "target": camera.get("target"),
                "framing": camera.get("framing", "auto"),
                "zoom": float(camera.get("zoom", 1.0)),
            },
            "derived": {
                "speed_mps": math.sqrt(
                    norm_motion["vx_mps"] ** 2
                    + norm_motion["vy_mps"] ** 2
                    + norm_motion["vz_mps"] ** 2
                ),
            },
            "timestamps": envelope.get("timestamps"),
            "version": envelope.get("version"),
        }
        return normalized
# ==============================================================================
# END OF CHUNK 85 K 04
