# ==============================================================================
# CHUNK 85 K 05 — VPS AI COMMAND DISPATCH
# ==============================================================================
#
# Purpose:
#   Dispatch normalized AI intents to the appropriate downstream execution
#   domains with strict separation of concerns:
#     - Flight-safe command channel (ArduPilot-compatible)
#     - Camera control channel (GoPro / internal camera)
#     - Cinematic planning channel (cloud/laptop AI)
#
# Design Goals:
#   - Deterministic routing
#   - Explicit capability gating
#   - Zero hidden side-effects
#   - Low latency, async-friendly
#
# ==============================================================================

import time
from typing import Dict, Any, Callable, Optional, Tuple


class VPSCommandDispatch:
    """
    Routes normalized intents to registered executors.
    """
    def __init__(self):
        # Executors are injected (dependency inversion)
        self._flight_executor: Optional[Callable[[Dict[str, Any]], bool]] = None
        self._camera_executor: Optional[Callable[[Dict[str, Any]], bool]] = None
        self._cinematic_executor: Optional[Callable[[Dict[str, Any]], bool]] = None
    # --------------------------------------------------------------------------
    # Registration
    # --------------------------------------------------------------------------
    def register_flight_executor(
        self,
        fn: Callable[[Dict[str, Any]], bool],
    ):
        self._flight_executor = fn
    def register_camera_executor(
        self,
        fn: Callable[[Dict[str, Any]], bool],
    ):
        self._camera_executor = fn
    def register_cinematic_executor(
        self,
        fn: Callable[[Dict[str, Any]], bool],
    ):
        self._cinematic_executor = fn
    # --------------------------------------------------------------------------
    # Dispatch Logic
    # --------------------------------------------------------------------------
    def _dispatch_flight(self, intent: Dict[str, Any]) -> bool:
        if not self._flight_executor:
            return False
        return bool(self._flight_executor(intent))
    def _dispatch_camera(self, intent: Dict[str, Any]) -> bool:
        if not self._camera_executor:
            return False
        return bool(self._camera_executor(intent))
    def _dispatch_cinematic(self, intent: Dict[str, Any]) -> bool:
        if not self._cinematic_executor:
            return False
        return bool(self._cinematic_executor(intent))
    def dispatch(
        self,
        normalized_intent: Dict[str, Any],
    ) -> Tuple[bool, Dict[str, Any]]:
        """
        Returns:
            (ok, report)
        """
        report = {
            "envelope_id": normalized_intent.get("envelope_id"),
            "ts_dispatch": time.time(),
            "results": {},
        }
        intent_type = normalized_intent.get("intent_type")
        # Flight commands (always gated)
        if intent_type in ("move", "follow", "orbit", "hold"):
            ok = self._dispatch_flight(normalized_intent)
            report["results"]["flight"] = ok
        else:
            report["results"]["flight"] = False
        # Camera commands
        if "camera" in normalized_intent:
            ok = self._dispatch_camera(normalized_intent)
            report["results"]["camera"] = ok
        else:
            report["results"]["camera"] = False
        # Cinematic / planning layer
        ok = self._dispatch_cinematic(normalized_intent)
        report["results"]["cinematic"] = ok
        overall_ok = any(report["results"].values())
        return overall_ok, report
# ==============================================================================
# END OF CHUNK 85 K 05
