# ==============================================================================
# CHUNK 85 K 07 — VPS TELEMETRY FEEDBACK LOOP
# ==============================================================================
#
# Purpose:
#   Close the control loop between execution domains (flight, camera,
#   cinematic planners) and upstream AI producers (Camera AI, Laptop AI).
#   This module aggregates execution telemetry and produces compact,
#   rate-limited feedback signals used to:
#     - Adapt intent emission rates
#     - Refine confidence calibration
#     - Detect drift, lag, or saturation
#
# Design:
#   - Pull-based snapshot aggregation (no blocking)
#   - Monotonic timestamps for latency math
#   - Loss-tolerant ring buffers
#
# ==============================================================================

import time
from collections import deque
from typing import Dict, Any, Deque, Optional, Tuple


class VPSTelemetryFeedback:
    """
    Aggregates downstream execution telemetry and emits feedback hints
    for upstream AI systems.
    """
    MAX_HISTORY = 64
    FEEDBACK_INTERVAL_SEC = 0.1
    def __init__(self):
        self._history: Dict[str, Deque[Dict[str, Any]]] = {}
        self._last_emit: Dict[str, float] = {}
    def _now(self) -> float:
        return time.monotonic()
    def _get_buf(self, source_id: str) -> Deque[Dict[str, Any]]:
        if source_id not in self._history:
            self._history[source_id] = deque(maxlen=self.MAX_HISTORY)
        return self._history[source_id]
    # --------------------------------------------------------------------------
    # Ingest
    # --------------------------------------------------------------------------
    def ingest_execution_report(
        self,
        source_id: str,
        report: Dict[str, Any],
    ):
        """
        Ingests a dispatch execution report from VPSCommandDispatch.
        """
        buf = self._get_buf(source_id)
        buf.append({
            "ts": self._now(),
            "report": report,
        })
    # --------------------------------------------------------------------------
    # Analysis
    # --------------------------------------------------------------------------
    def _summarize(
        self,
        buf: Deque[Dict[str, Any]],
    ) -> Dict[str, Any]:
        if not buf:
            return {}
        total = len(buf)
        ok_flight = 0
        ok_camera = 0
        ok_cinematic = 0
        for item in buf:
            res = item["report"].get("results", {})
            ok_flight += int(bool(res.get("flight")))
            ok_camera += int(bool(res.get("camera")))
            ok_cinematic += int(bool(res.get("cinematic")))
        return {
            "samples": total,
            "flight_ok_ratio": ok_flight / total,
            "camera_ok_ratio": ok_camera / total,
            "cinematic_ok_ratio": ok_cinematic / total,
        }
    # --------------------------------------------------------------------------
    # Emit feedback
    # --------------------------------------------------------------------------
    def emit_feedback(
        self,
        source_id: str,
    ) -> Optional[Dict[str, Any]]:
        """
        Returns feedback dict if emission interval elapsed, else None.
        """
        now = self._now()
        last = self._last_emit.get(source_id, 0.0)
        if (now - last) < self.FEEDBACK_INTERVAL_SEC:
            return None
        buf = self._get_buf(source_id)
        summary = self._summarize(buf)
        if not summary:
            return None
        self._last_emit[source_id] = now
        # Heuristic hints (kept conservative)
        throttle_hint = False
        if summary["flight_ok_ratio"] < 0.8:
            throttle_hint = True
        feedback = {
            "source_id": source_id,
            "ts": time.time(),
            "summary": summary,
            "hints": {
                "throttle": throttle_hint,
                "confidence_bias": (
                    -0.05 if summary["cinematic_ok_ratio"] < 0.85 else 0.0
                ),
            },
        }
        return feedback
# ==============================================================================
# END OF CHUNK 85 K 07
