# ==============================================================================
# CHUNK 85 K 09 — VPS FAILSAFE INTENT QUARANTINE
# ==============================================================================
#
# Purpose:
#   Provide a hardened quarantine layer for AI intents that exhibit unsafe,
#   inconsistent, or degrading behavior. This layer:
#     - Isolates suspect intents without blocking the pipeline
#     - Applies exponential cooldowns per source
#     - Preserves forensic context for later analysis
#     - Emits explicit fail-safe signals upstream
#
# Design:
#   - Deterministic rules (no ML)
#   - Lossless capture of last-N envelopes
#   - Zero coupling to execution domains
#
# ==============================================================================

import time
from collections import deque
from typing import Dict, Any, Deque, Optional, Tuple


class VPSIntentQuarantine:
    """
    Quarantines and rate-limits suspect intents on a per-source basis.
    """
    MAX_QUARANTINE_HISTORY = 32
    BASE_COOLDOWN_SEC = 0.5
    MAX_COOLDOWN_SEC = 10.0
    def __init__(self):
        self._history: Dict[str, Deque[Dict[str, Any]]] = {}
        self._strike_count: Dict[str, int] = {}
        self._cooldown_until: Dict[str, float] = {}
    def _now(self) -> float:
        return time.monotonic()
    def _get_hist(self, source_id: str) -> Deque[Dict[str, Any]]:
        if source_id not in self._history:
            self._history[source_id] = deque(maxlen=self.MAX_QUARANTINE_HISTORY)
        return self._history[source_id]
    def _compute_cooldown(self, strikes: int) -> float:
        # Exponential backoff with clamp
        cd = self.BASE_COOLDOWN_SEC * (2 ** max(0, strikes - 1))
        return min(cd, self.MAX_COOLDOWN_SEC)
    def record_violation(
        self,
        source_id: str,
        envelope: Dict[str, Any],
        reason: str,
    ) -> Dict[str, Any]:
        """
        Records a violation, updates cooldown, and returns a quarantine notice.
        """
        hist = self._get_hist(source_id)
        hist.append({
            "ts": self._now(),
            "envelope_id": envelope.get("envelope_id"),
            "intent_type": envelope.get("intent", {}).get("type"),
            "reason": reason,
        })
        strikes = self._strike_count.get(source_id, 0) + 1
        self._strike_count[source_id] = strikes
        cooldown = self._compute_cooldown(strikes)
        until = self._now() + cooldown
        self._cooldown_until[source_id] = until
        return {
            "source_id": source_id,
            "action": "quarantine",
            "reason": reason,
            "strikes": strikes,
            "cooldown_sec": cooldown,
            "resume_after_mono": until,
        }
    def allow(self, source_id: str) -> Tuple[bool, Optional[Dict[str, Any]]]:
        """
        Checks if a source is allowed to emit intents.
        Returns (allow, notice_if_blocked).
        """
        now = self._now()
        until = self._cooldown_until.get(source_id, 0.0)
        if now < until:
            return False, {
                "source_id": source_id,
                "action": "blocked",
                "retry_after": max(0.0, until - now),
                "strikes": self._strike_count.get(source_id, 0),
            }
        return True, None
    def snapshot(
        self,
        source_id: str,
    ) -> Dict[str, Any]:
        """
        Returns a compact snapshot for observability/UI.
        """
        hist = list(self._get_hist(source_id))
        return {
            "source_id": source_id,
            "strikes": self._strike_count.get(source_id, 0),
            "cooldown_until": self._cooldown_until.get(source_id, 0.0),
            "recent": hist[-5:],
        }
# ==============================================================================
# END OF CHUNK 85 K 09
