# ==============================================================================
# CHUNK 85 L 01 — CAMERA AI ↔ VPS SESSION HANDSHAKE
# ==============================================================================
#
# Purpose:
#   Establish a deterministic, low-latency session between Camera AI
#   (Radxa / Laptop edge) and the VPS. The handshake:
#     - Authenticates the camera AI instance
#     - Negotiates protocol versions
#     - Binds a session_id for all subsequent messages
#     - Publishes minimal capabilities required for routing
#
# Design:
#   - One-round-trip handshake
#   - Idempotent retries
#   - No blocking on downstream services
#
# ==============================================================================

import time
import uuid
from typing import Dict, Any, Optional, Tuple


class CameraAIVPSSession:
    """
    Session handshake manager between Camera AI and VPS.
    """
    SUPPORTED_PROTOCOLS = (1, 2)
    SESSION_TTL_SEC = 30.0
    def __init__(self):
        self._sessions: Dict[str, Dict[str, Any]] = {}
    def _now(self) -> float:
        return time.monotonic()
    def _is_protocol_supported(self, proto: int) -> bool:
        return int(proto) in self.SUPPORTED_PROTOCOLS
    def initiate(
        self,
        source_id: str,
        protocol_version: int,
        capabilities: Dict[str, Any],
    ) -> Tuple[bool, Dict[str, Any]]:
        """
        Initiates or refreshes a session.
        Returns:
            (ok, response)
        """
        if not self._is_protocol_supported(protocol_version):
            return False, {
                "error": "unsupported_protocol",
                "supported": list(self.SUPPORTED_PROTOCOLS),
            }
        session_id = str(uuid.uuid4())
        now = self._now()
        self._sessions[session_id] = {
            "source_id": source_id,
            "protocol": int(protocol_version),
            "capabilities": dict(capabilities or {}),
            "created_mono": now,
            "last_seen_mono": now,
            "expires_mono": now + self.SESSION_TTL_SEC,
        }
        response = {
            "session_id": session_id,
            "protocol": protocol_version,
            "expires_in_sec": self.SESSION_TTL_SEC,
            "server_time": time.time(),
        }
        return True, response
    def touch(self, session_id: str) -> bool:
        """
        Refreshes session liveness.
        """
        sess = self._sessions.get(session_id)
        if not sess:
            return False
        now = self._now()
        sess["last_seen_mono"] = now
        sess["expires_mono"] = now + self.SESSION_TTL_SEC
        return True
    def validate(self, session_id: str) -> bool:
        """
        Validates session existence and TTL.
        """
        sess = self._sessions.get(session_id)
        if not sess:
            return False
        return self._now() <= sess["expires_mono"]
    def snapshot(self, session_id: str) -> Optional[Dict[str, Any]]:
        """
        Returns a read-only snapshot for observability.
        """
        sess = self._sessions.get(session_id)
        if not sess:
            return None
        return {
            "source_id": sess["source_id"],
            "protocol": sess["protocol"],
            "capabilities": sess["capabilities"],
            "expires_in_sec": max(
                0.0, sess["expires_mono"] - self._now()
            ),
        }
# ==============================================================================
# END OF CHUNK 85 L 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 L 02 — CAMERA AI HEALTH & HEARTBEAT
# ==============================================================================
#
# Purpose:
#   Provide continuous liveness, health, and performance signaling from
#   Camera AI (Radxa / Laptop edge) to VPS. Enables:
#     - Fast detection of stalls or overload
#     - Adaptive routing / throttling
#     - Operator observability without heavy telemetry
#
# Design:
#   - Fixed-rate heartbeat (monotonic)
#   - Compact health vector (CPU/GPU/mem/latency)
#   - Graceful degradation (partial reports accepted)
#
# ==============================================================================

import time
from typing import Dict, Any, Optional


class CameraAIHealthHeartbeat:
    """
    Tracks health heartbeats per Camera AI session.
    """
    HEARTBEAT_TIMEOUT_SEC = 1.0
    STALE_SESSION_SEC = 3.0
    def __init__(self):
        self._last_hb: Dict[str, Dict[str, Any]] = {}
    def _now(self) -> float:
        return time.monotonic()
    def ingest(
        self,
        session_id: str,
        health: Dict[str, Any],
    ) -> bool:
        """
        Ingests a heartbeat payload.
        """
        now = self._now()
        self._last_hb[session_id] = {
            "ts_mono": now,
            "cpu": float(health.get("cpu", 0.0)),
            "gpu": float(health.get("gpu", 0.0)),
            "mem": float(health.get("mem", 0.0)),
            "lat_ms": float(health.get("lat_ms", 0.0)),
            "drops": int(health.get("drops", 0)),
        }
        return True
    def is_alive(self, session_id: str) -> bool:
        """
        Returns True if heartbeat is recent.
        """
        hb = self._last_hb.get(session_id)
        if not hb:
            return False
        return (self._now() - hb["ts_mono"]) <= self.HEARTBEAT_TIMEOUT_SEC
    def is_stale(self, session_id: str) -> bool:
        hb = self._last_hb.get(session_id)
        if not hb:
            return True
        return (self._now() - hb["ts_mono"]) >= self.STALE_SESSION_SEC
    def snapshot(self, session_id: str) -> Optional[Dict[str, Any]]:
        """
        Returns compact health snapshot for UI / routing logic.
        """
        hb = self._last_hb.get(session_id)
        if not hb:
            return None
        age = self._now() - hb["ts_mono"]
        return {
            "age_sec": age,
            "cpu": hb["cpu"],
            "gpu": hb["gpu"],
            "mem": hb["mem"],
            "lat_ms": hb["lat_ms"],
            "drops": hb["drops"],
            "status": (
                "alive" if age <= self.HEARTBEAT_TIMEOUT_SEC else "degraded"
            ),
        }
# ==============================================================================
# END OF CHUNK 85 L 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 L 03 — CAMERA AI TIMEBASE SYNC
# ==============================================================================
#
# Purpose:
#   Establish a stable, low-drift timebase alignment between Camera AI
#   (Radxa / Laptop) and VPS. This is critical for:
#     - Cross-device latency estimation
#     - Frame-to-intent correlation
#     - Temporal consistency in cinematic planning
#
# Design:
#   - Lightweight NTP-like offset estimation
#   - Monotonic clock dominance
#   - Drift-aware smoothing (EMA)
#
# ==============================================================================

import time
from typing import Dict, Any


class CameraAITimebaseSync:
    """
    Maintains time offset estimation between Camera AI and VPS.
    """
    ALPHA = 0.2               # EMA smoothing factor
    MAX_OFFSET_SEC = 0.5
    def __init__(self):
        self._offset_sec: float = 0.0
        self._initialized = False
    def _now(self) -> float:
        return time.monotonic()
    def update(
        self,
        client_mono: float,
        server_wall: float,
    ) -> Dict[str, float]:
        """
        Update offset estimation using client monotonic timestamp
        and server wall-clock timestamp.
        """
        server_mono = self._now()
        # Estimate offset: server_mono - client_mono
        measured = server_mono - float(client_mono)
        if not self._initialized:
            self._offset_sec = measured
            self._initialized = True
        else:
            self._offset_sec = (
                (1.0 - self.ALPHA) * self._offset_sec
                + self.ALPHA * measured
            )
        # Clamp to sane bounds
        if abs(self._offset_sec) > self.MAX_OFFSET_SEC:
            self._offset_sec = max(
                -self.MAX_OFFSET_SEC,
                min(self._offset_sec, self.MAX_OFFSET_SEC),
            )
        return {
            "offset_sec": self._offset_sec,
            "drift_sec": measured - self._offset_sec,
        }
    def to_server_mono(self, client_mono: float) -> float:
        """
        Converts client monotonic timestamp to server monotonic domain.
        """
        return float(client_mono) + self._offset_sec
    def snapshot(self) -> Dict[str, float]:
        return {
            "offset_sec": self._offset_sec,
            "initialized": self._initialized,
        }
