# ==============================================================================
# CHUNK 85 L 04 — CAMERA AI CAPABILITY NEGOTIATION
# ==============================================================================
#
# Purpose:
#   Negotiate and lock an explicit capability contract between Camera AI
#   (Radxa / Laptop edge) and VPS. This ensures:
#     - Deterministic feature usage (no guessing)
#     - Graceful degradation when resources drop
#     - Forward-compatible upgrades
#
# Design:
#   - Capability sets are declarative (no side effects)
#   - Server is authoritative on final grant
#   - Results are immutable for the session lifetime
#
# ==============================================================================

from typing import Dict, Any, List, Tuple


class CameraAICapabilityNegotiator:
    """
    Negotiates Camera AI capabilities with the VPS.
    """
    # Server-supported capability universe
    SUPPORTED = {
        "frame_stream": {"max_fps": 240, "formats": ("rgb", "yuv", "raw")},
        "gyro_stream": {"rates_hz": (100, 200, 400)},
        "object_tracking": {"max_objects": 32},
        "exposure_control": {"modes": ("auto", "manual", "ai")},
        "zoom_control": {"range": (1.0, 8.0)},
        "focus_control": {"modes": ("auto", "continuous")},
    }
    def __init__(self):
        pass
    def _intersect_scalar(self, req: Any, sup: Any) -> Any:
        try:
            return req if req in sup else sup
        except Exception:
            return sup
    def _intersect_range(self, req: Any, sup: Any) -> Any:
        try:
            lo = max(req[0], sup[0])
            hi = min(req[1], sup[1])
            return (lo, hi) if lo <= hi else sup
        except Exception:
            return sup
    def negotiate(
        self,
        requested: Dict[str, Any],
    ) -> Tuple[Dict[str, Any], List[str]]:
        """
        Returns:
            (granted_capabilities, rejected_keys)
        """
        granted: Dict[str, Any] = {}
        rejected: List[str] = []
        for cap, req_val in (requested or {}).items():
            sup_val = self.SUPPORTED.get(cap)
            if sup_val is None:
                rejected.append(cap)
                continue
            # Structured capability negotiation
            if isinstance(req_val, dict) and isinstance(sup_val, dict):
                out: Dict[str, Any] = {}
                for k, rv in req_val.items():
                    sv = sup_val.get(k)
                    if sv is None:
                        continue
                    if isinstance(rv, (int, float)):
                        out[k] = min(rv, sv)
                    elif isinstance(rv, (tuple, list)):
                        out[k] = self._intersect_range(rv, sv)
                    else:
                        out[k] = self._intersect_scalar(rv, sv)
                granted[cap] = out
            else:
                granted[cap] = sup_val
        return granted, rejected
