# ==============================================================================
# CHUNK 85 L 05 — CAMERA AI STREAM AUTHORIZATION
# ==============================================================================
#
# Purpose:
#   Authorize, gate, and lifecycle-manage camera data streams (video, gyro,
#   metadata) from Camera AI to VPS. Ensures:
#     - Session-bound access only
#     - Capability-compliant stream parameters
#     - Explicit start/stop semantics
#     - Rate and bandwidth enforcement
#
# Design:
#   - Stateless authorization checks
#   - Per-stream leases with TTL
#   - Graceful revocation on health/session failure
#
# ==============================================================================

import time
from typing import Dict, Any, Optional, Tuple


class CameraAIStreamAuthorizer:
    """
    Authorizes camera and sensor streams for a Camera AI session.
    """
    DEFAULT_TTL_SEC = 5.0
    def __init__(self):
        self._leases: Dict[str, Dict[str, Any]] = {}
    def _now(self) -> float:
        return time.monotonic()
    def authorize(
        self,
        session_id: str,
        stream_type: str,
        params: Dict[str, Any],
        granted_capabilities: Dict[str, Any],
    ) -> Tuple[bool, Dict[str, Any]]:
        """
        Attempts to authorize a stream.
        Returns:
            (ok, response)
        """
        cap = granted_capabilities.get(stream_type)
        if cap is None:
            return False, {"error": "capability_not_granted"}
        # Parameter compliance check
        for k, v in params.items():
            lim = cap.get(k)
            if lim is None:
                continue
            if isinstance(lim, (int, float)) and float(v) > lim:
                return False, {"error": "param_exceeds_cap", "param": k}
        lease_id = f"{session_id}:{stream_type}"
        now = self._now()
        self._leases[lease_id] = {
            "session_id": session_id,
            "stream_type": stream_type,
            "params": dict(params),
            "granted": dict(cap),
            "issued_mono": now,
            "expires_mono": now + self.DEFAULT_TTL_SEC,
        }
        return True, {
            "lease_id": lease_id,
            "expires_in_sec": self.DEFAULT_TTL_SEC,
        }
    def renew(self, lease_id: str) -> bool:
        lease = self._leases.get(lease_id)
        if not lease:
            return False
        lease["expires_mono"] = self._now() + self.DEFAULT_TTL_SEC
        return True
    def revoke(self, lease_id: str):
        self._leases.pop(lease_id, None)
    def is_active(self, lease_id: str) -> bool:
        lease = self._leases.get(lease_id)
        if not lease:
            return False
        return self._now() <= lease["expires_mono"]
    def snapshot(self, session_id: str) -> Dict[str, Any]:
        """
        Returns active leases for a session.
        """
        out = {}
        for lid, lease in self._leases.items():
            if lease["session_id"] == session_id:
                out[lid] = {
                    "stream_type": lease["stream_type"],
                    "expires_in_sec": max(
        0.0, lease["expires_mono"] - self._now()
                    ),
                }
        return out
