# ==============================================================================
# CHUNK 85 L 07 — CAMERA AI ERROR REPORTING & HEALTH MONITOR
# ==============================================================================
#
# Purpose:
#   Centralized, low-latency error reporting + health monitoring for Camera AI.
#   This module ensures:
#     - Deterministic error categorization
#     - Temporal aggregation (no log spam)
#     - Actionable severity levels for upstream AI + VPS
#     - Hard separation between camera faults and flight logic
#
# Why it matters (cinematic relevance):
#   Silent camera faults destroy shots. This layer allows AI to:
#     - Switch exposure strategies
#     - Reduce bitrate / resolution safely
#     - Request cloud fallback inference
#     - Abort a shot before visual corruption occurs
#
# ==============================================================================

import time
from enum import Enum
from typing import Dict, Any, List, Optional


class CameraAIErrorSeverity(Enum):
    INFO = 0
    WARNING = 1
    DEGRADED = 2
    CRITICAL = 3
    FATAL = 4


class CameraAIErrorCode(Enum):
    FRAME_DROP = "frame_drop"
    LATENCY_SPIKE = "latency_spike"
    SENSOR_TIMEOUT = "sensor_timeout"
    GYRO_DESYNC = "gyro_desync"
    METADATA_CORRUPTION = "metadata_corruption"
    BITRATE_OVERFLOW = "bitrate_overflow"
    AUTH_EXPIRED = "auth_expired"
    UNKNOWN = "unknown"


class CameraAIHealthMonitor:
    """
    Tracks camera AI health state and reports actionable errors upstream.
    """
    AGGREGATION_WINDOW_SEC = 1.5
    def __init__(self):
        self._last_emit_ts: float = 0.0
        self._error_counters: Dict[str, int] = {}
        self._last_error_ts: Dict[str, float] = {}
        self._current_state: CameraAIErrorSeverity = CameraAIErrorSeverity.INFO
    def _now(self) -> float:
        return time.monotonic()
    def report(
        self,
        code: CameraAIErrorCode,
        severity: CameraAIErrorSeverity,
        context: Optional[Dict[str, Any]] = None,
    ) -> Optional[Dict[str, Any]]:
        """
        Registers an error event.
        Returns a structured report if emitted, else None.
        """
        key = code.value
        now = self._now()
        self._error_counters[key] = self._error_counters.get(key, 0) + 1
        self._last_error_ts[key] = now
        # Escalate global state if needed
        if severity.value > self._current_state.value:
            self._current_state = severity
        # Temporal aggregation gate
        if now - self._last_emit_ts < self.AGGREGATION_WINDOW_SEC:
            return None
        self._last_emit_ts = now
        payload = {
            "ts_mono": now,
            "severity": severity.name,
            "global_state": self._current_state.name,
            "errors": [],
        }
        for err, count in list(self._error_counters.items()):
            payload["errors"].append({
                "code": err,
                "count": count,
                "last_seen_sec_ago": now - self._last_error_ts.get(err, now),
            })
        if context:
            payload["context"] = dict(context)
        # Reset counters after emit
        self._error_counters.clear()
        return payload
    def current_state(self) -> CameraAIErrorSeverity:
        return self._current_state
    def reset(self):
        self._error_counters.clear()
        self._last_error_ts.clear()
        self._current_state = CameraAIErrorSeverity.INFO
