# ==============================================================================
# CHUNK 85 M 01 — CAMERA AI FRAME INGEST CORE
# ==============================================================================
#
# Purpose:
#   Deterministic, low-latency ingest of camera frames into the Camera AI system.
#   This module is the *first* true AI boundary after sensor capture.
#
# Responsibilities:
#   - Accept frames from:
#       * GoPro (RTSP / USB capture)
#       * Internal reference camera
#   - Normalize frame representation
#   - Timestamp with monotonic + sensor clocks
#   - Attach minimal ingest metadata
#   - Enforce ingest rate & backpressure
#
# Cinematic importance:
#   If ingest is unstable, EVERYTHING downstream fails:
#     exposure, grading, motion, AI intent.
#
# ==============================================================================

import time
import threading
from collections import deque
from typing import Any, Dict, Optional, Tuple


class CameraFrame:
    """
    Canonical frame container used across Camera AI.
    """
    __slots__ = (
        "frame_id",
        "image",
        "width",
        "height",
        "pixel_format",
        "ts_sensor",
        "ts_mono",
        "source",
    )
    def __init__(
        self,
        frame_id: int,
        image: Any,
        width: int,
        height: int,
        pixel_format: str,
        ts_sensor: Optional[float],
        source: str,
    ):
        self.frame_id = frame_id
        self.image = image
        self.width = width
        self.height = height
        self.pixel_format = pixel_format
        self.ts_sensor = ts_sensor
        self.ts_mono = time.monotonic()
        self.source = source
class CameraAIFrameIngest:
    """
    High-performance ingest buffer for Camera AI frames.
    """
    def __init__(
        self,
        max_queue: int = 6,
        drop_oldest: bool = True,
    ):
        self._queue = deque(maxlen=max_queue)
        self._lock = threading.Lock()
        self._frame_counter = 0
        self._drop_oldest = drop_oldest
    def push(
        self,
        image: Any,
        width: int,
        height: int,
        pixel_format: str,
        ts_sensor: Optional[float],
        source: str,
    ) -> bool:
        """
        Pushes a new frame into ingest queue.
        Returns False if frame was dropped.
        """
        with self._lock:
            if len(self._queue) == self._queue.maxlen:
                if not self._drop_oldest:
                    return False
                self._queue.popleft()
            frame = CameraFrame(
                frame_id=self._frame_counter,
                image=image,
                width=width,
                height=height,
                pixel_format=pixel_format,
                ts_sensor=ts_sensor,
                source=source,
            )
            self._frame_counter += 1
            self._queue.append(frame)
            return True
    def pop(self) -> Optional[CameraFrame]:
        """
        Pops the oldest available frame.
        """
        with self._lock:
            if not self._queue:
                return None
            return self._queue.popleft()
    def depth(self) -> int:
        with self._lock:
            return len(self._queue)
    def stats(self) -> Dict[str, Any]:
        """
        Lightweight stats for adaptive scheduling.
        """
        with self._lock:
            return {
                "queued": len(self._queue),
                "max_queue": self._queue.maxlen,
                "frames_ingested": self._frame_counter,
            }
