# ==============================================================================
# CHUNK 85 M 02 — CAMERA AI FRAME + METADATA FUSION
# ==============================================================================
#
# Purpose:
#   Fuse raw camera frames with all associated metadata into a single
#   temporally-coherent structure usable by:
#     - Exposure AI
#     - Stabilization AI
#     - Framing / subject tracking AI
#     - Cloud reinforcement AI
#
# Metadata Sources:
#   - GoPro GPMF (gyro, exposure, ISO, shutter, WB)
#   - Internal reference camera timestamps
#   - Ingest-layer monotonic clock
#
# Cinematic Importance:
#   Without deterministic metadata fusion, AI decisions drift,
#   causing visible instability, exposure pumping, or motion jitter.
#
# ==============================================================================

from typing import Dict, Any, Optional
import time


class CameraAIMetadataPacket:
    """
    Canonical metadata packet aligned to a single video frame.
    """
    __slots__ = (
        "frame_id",
        "ts_sensor",
        "ts_mono",
        "gyro",
        "exposure",
        "iso",
        "shutter",
        "white_balance",
        "confidence",
    )
    def __init__(
        self,
        frame_id: int,
        ts_sensor: Optional[float],
        gyro: Optional[Dict[str, Any]],
        exposure: Optional[float],
        iso: Optional[float],
        shutter: Optional[float],
        white_balance: Optional[Dict[str, float]],
        confidence: float,
    ):
        self.frame_id = frame_id
        self.ts_sensor = ts_sensor
        self.ts_mono = time.monotonic()
        self.gyro = gyro
        self.exposure = exposure
        self.iso = iso
        self.shutter = shutter
        self.white_balance = white_balance
        self.confidence = confidence


class CameraAIFusedFrame:
    """
    Unified structure passed to all downstream AI modules.
    """
    __slots__ = (
        "frame",
        "metadata",
        "fusion_latency_ms",
    )
    def __init__(
        self,
        frame,
        metadata: CameraAIMetadataPacket,
    ):
        self.frame = frame
        self.metadata = metadata
        self.fusion_latency_ms = (
            (time.monotonic() - frame.ts_mono) * 1000.0
        )


class CameraAIFrameMetadataFusion:
    """
    Deterministic fusion of frame + metadata with latency tracking.
    """
    def __init__(self):
        self._last_metadata_by_frame: Dict[int, CameraAIMetadataPacket] = {}
    def ingest_metadata(
        self,
        frame_id: int,
        ts_sensor: Optional[float],
        gyro: Optional[Dict[str, Any]],
        exposure: Optional[float],
        iso: Optional[float],
        shutter: Optional[float],
        white_balance: Optional[Dict[str, float]],
        confidence: float = 1.0,
    ):
        """
        Called by metadata producers (GPMF parser, internal camera, etc.).
        """
        pkt = CameraAIMetadataPacket(
            frame_id=frame_id,
            ts_sensor=ts_sensor,
            gyro=gyro,
            exposure=exposure,
            iso=iso,
            shutter=shutter,
            white_balance=white_balance,
            confidence=confidence,
        )
        self._last_metadata_by_frame[frame_id] = pkt
    def fuse(
        self,
        frame,
    ) -> Optional[CameraAIFusedFrame]:
        """
        Attempts to fuse metadata with a frame.
        Returns None if metadata not yet available.
        """
        pkt = self._last_metadata_by_frame.pop(frame.frame_id, None)
        if pkt is None:
            return None
        return CameraAIFusedFrame(frame, pkt)
    def pending_metadata(self) -> int:
        return len(self._last_metadata_by_frame)
