# ==============================================================================
# CHUNK 85 M 03 — CAMERA AI GYRO / IMU TEMPORAL ALIGNMENT
# ==============================================================================
#
# Purpose:
#   Precisely align high-frequency gyro / IMU data with video frames.
#   This enables:
#     - Sub-pixel electronic stabilization
#     - Motion-aware exposure decisions
#     - Accurate camera motion vectors for AI framing
#
# Data Sources:
#   - GoPro GPMF gyro stream (high-rate, rolling)
#   - Internal reference IMU (lower latency, lower noise)
#
# Cinematic Importance:
#   Misaligned gyro = warping, jitter, rolling artifacts.
#   Correct alignment = ARRI-level motion smoothness.
#
# ==============================================================================

import bisect
from typing import List, Tuple, Optional, Dict
import math


class GyroSample:
    """
    Single gyro / IMU sample.
    """
    __slots__ = ("ts_sensor", "x", "y", "z")
    def __init__(self, ts_sensor: float, x: float, y: float, z: float):
        self.ts_sensor = ts_sensor
        self.x = x
        self.y = y
        self.z = z


class CameraAIGyroTimeline:
    """
    Time-ordered gyro buffer with interpolation support.
    """
    def __init__(self, max_samples: int = 4096):
        self._samples: List[GyroSample] = []
        self._max = max_samples
    def push(self, sample: GyroSample):
        self._samples.append(sample)
        if len(self._samples) > self._max:
            self._samples.pop(0)
    def _timestamps(self) -> List[float]:
        return [s.ts_sensor for s in self._samples]
    def interpolate(self, ts: float) -> Optional[Tuple[float, float, float]]:
        """
        Linearly interpolate gyro vector at requested timestamp.
        """
        if len(self._samples) < 2:
            return None
        times = self._timestamps()
        idx = bisect.bisect_left(times, ts)
        if idx <= 0 or idx >= len(self._samples):
            return None
        s0 = self._samples[idx - 1]
        s1 = self._samples[idx]
        t = (ts - s0.ts_sensor) / (s1.ts_sensor - s0.ts_sensor)
        return (
            s0.x + (s1.x - s0.x) * t,
            s0.y + (s1.y - s0.y) * t,
            s0.z + (s1.z - s0.z) * t,
        )


class CameraAIGyroAligner:
    """
    Aligns fused frames with gyro data.
    """
    def __init__(self):
        self._timeline = CameraAIGyroTimeline()
    def ingest_gyro(
        self,
        ts_sensor: float,
        x: float,
        y: float,
        z: float,
    ):
        self._timeline.push(GyroSample(ts_sensor, x, y, z))
    def align(
        self,
        fused_frame,
    ) -> Optional[Dict[str, float]]:
        """
        Returns aligned gyro vector for a fused frame.
        """
        ts = fused_frame.metadata.ts_sensor
        if ts is None:
            return None
        g = self._timeline.interpolate(ts)
        if g is None:
            return None
        gx, gy, gz = g
        magnitude = math.sqrt(gx * gx + gy * gy + gz * gz)
        return {
            "gx": gx,
            "gy": gy,
            "gz": gz,
            "magnitude": magnitude,
        }
