# ==============================================================================
# CHUNK 85 M 04 — CAMERA AI TEMPORAL RING BUFFER
# ==============================================================================
#
# Purpose:
#   Provide a deterministic, low-latency temporal buffer for fused frames.
#   This buffer is the backbone for:
#     - Stabilization (past + future context)
#     - Motion vector extraction
#     - Exposure smoothing
#     - AI shot planning with temporal awareness
#
# Design goals:
#   - Lock-free reads where possible
#   - Fixed memory footprint
#   - O(1) push / pop
#   - Frame-index-based access
#
# Cinematic importance:
#   Hollywood-grade footage depends on *temporal context*.
#   Single-frame AI always looks robotic.
#
# ==============================================================================

from typing import Optional, List, Dict, Any
import threading


class CameraAITemporalBuffer:
    """
    Fixed-size temporal ring buffer for fused frames.
    """
    def __init__(self, capacity: int = 16):
        if capacity < 4:
            raise ValueError("Temporal buffer capacity too small")
        self._capacity = capacity
        self._buffer: List[Optional[Any]] = [None] * capacity
        self._head = 0
        self._count = 0
        self._lock = threading.Lock()
    def push(self, fused_frame: Any):
        """
        Inserts a new fused frame into the buffer.
        Oldest frame is overwritten when full.
        """
        with self._lock:
            self._buffer[self._head] = fused_frame
            self._head = (self._head + 1) % self._capacity
            self._count = min(self._count + 1, self._capacity)
    def size(self) -> int:
        return self._count
    def is_full(self) -> bool:
        return self._count == self._capacity
    def _index_from_tail(self, offset: int) -> int:
        """
        Returns buffer index relative to newest frame.
        offset = 0 => newest
        offset = 1 => previous
        """
        return (self._head - 1 - offset) % self._capacity
    def get_recent(self, n: int) -> List[Any]:
        """
        Returns up to n most recent frames (newest first).
        """
        with self._lock:
            n = min(n, self._count)
            out = []
            for i in range(n):
                idx = self._index_from_tail(i)
                frame = self._buffer[idx]
                if frame is not None:
                    out.append(frame)
            return out
    def get_window(
        self,
        center_offset: int,
        radius: int,
    ) -> List[Any]:
        """
        Returns a symmetric temporal window around a frame.
        center_offset: offset from newest (0 = newest)
        radius: number of frames before and after
        """
        with self._lock:
            out = []
            for d in range(-radius, radius + 1):
                offset = center_offset + d
                if offset < 0 or offset >= self._count:
                    continue
                idx = self._index_from_tail(offset)
                frame = self._buffer[idx]
                if frame is not None:
                    out.append(frame)
            return out
    def stats(self) -> Dict[str, Any]:
        """
        Lightweight telemetry for scheduling AI.
        """
        with self._lock:
            return {
                "capacity": self._capacity,
                "count": self._count,
                "head_index": self._head,
            }
