# ==============================================================================
# CHUNK 85 M 05 — CAMERA AI LATENCY-AWARE FRAME SCHEDULING
# ==============================================================================
#
# Purpose:
#   Dynamically schedule frames for downstream AI processing based on:
#     - End-to-end latency
#     - Buffer pressure
#     - Motion intensity
#     - Cinematic priority
#
# This ensures:
#   - No AI backlog during fast motion
#   - Graceful degradation instead of dropped shots
#   - Stable output even under compute stress
#
# Cinematic importance:
#   Hollywood-quality footage depends on *predictable timing*.
#   Latency spikes cause jitter, exposure pumping, and AI indecision.
#
# ==============================================================================

import time
from typing import Optional, Dict, Any


class CameraAILatencyScheduler:
    """
    Schedules frames based on latency and system pressure.
    """
    TARGET_LATENCY_MS = 25.0
    MAX_LATENCY_MS = 60.0
    def __init__(self):
        self._last_emit_ts = time.monotonic()
        self._dropped_frames = 0
    def evaluate(
        self,
        fused_frame,
        buffer_stats: Dict[str, Any],
        motion_energy: float,
    ) -> bool:
        """
        Returns True if frame should be processed,
        False if it should be skipped to preserve stability.
        """
        now = time.monotonic()
        latency_ms = (now - fused_frame.frame.ts_mono) * 1000.0
        # Hard reject if dangerously late
        if latency_ms > self.MAX_LATENCY_MS:
            self._dropped_frames += 1
            return False
        # Buffer pressure heuristic
        pressure = buffer_stats["count"] / buffer_stats["capacity"]
        # Motion-aware priority
        priority = 1.0 + min(motion_energy, 5.0)
        # Latency-adaptive threshold
        dynamic_budget = self.TARGET_LATENCY_MS / priority
        if latency_ms > dynamic_budget and pressure > 0.6:
            self._dropped_frames += 1
            return False
        self._last_emit_ts = now
        return True
    def stats(self) -> Dict[str, Any]:
        return {
            "dropped_frames": self._dropped_frames,
            "last_emit_sec_ago": time.monotonic() - self._last_emit_ts,
        }
