# CHUNK 85 M 06 — CAMERA AI DUAL-CAMERA COHERENCE (INTERNAL + GOPRO)
# ==============================================================================
#
# Purpose:
#   Maintain strict temporal, geometric, and semantic coherence between:
#     - External GoPro Hero camera (cinematic master)
#     - Internal reference camera (low-latency motion + stabilization)
#
# This module enables:
#   - Shared AI understanding across both cameras
#   - Gyro + motion reinforcement when one stream degrades
#   - Cross-camera confidence boosting
#   - Seamless fallback without visual discontinuity
#
# Cinematic importance:
#   Professional rigs ALWAYS use multi-sensor fusion.
#   Single-camera AI = fragile + inconsistent.
#
# ==============================================================================

from typing import Optional, Dict, Any, Tuple
import math
import time


class CameraAICameraState:
    """
    Runtime state for a single camera stream.
    """
    __slots__ = (
        "last_frame_id",
        "last_ts_sensor",
        "motion_energy",
        "confidence",
    )
    def __init__(self):
        self.last_frame_id: int = -1
        self.last_ts_sensor: Optional[float] = None
        self.motion_energy: float = 0.0
        self.confidence: float = 1.0


class CameraAIDualCameraCoherence:
    """
    Maintains coherence between internal and external cameras.
    """
    MAX_TIME_DELTA_SEC = 0.012   # ~12 ms tolerance
    MOTION_BLEND_LIMIT = 4.0
    def __init__(self):
        self._gopro = CameraAICameraState()
        self._internal = CameraAICameraState()
    def _update_state(
        self,
        state: CameraAICameraState,
        fused_frame,
        gyro_vector: Optional[Dict[str, float]],
    ):
        state.last_frame_id = fused_frame.frame.frame_id
        state.last_ts_sensor = fused_frame.metadata.ts_sensor
        if gyro_vector:
            state.motion_energy = min(
                gyro_vector["magnitude"],
                self.MOTION_BLEND_LIMIT,
            )
        else:
            state.motion_energy *= 0.95
        state.confidence = fused_frame.metadata.confidence
    def ingest(
        self,
        fused_frame,
        gyro_vector: Optional[Dict[str, float]],
    ):
        """
        Ingests a fused frame from either camera.
        """
        src = fused_frame.frame.source
        if src == "gopro":
            self._update_state(self._gopro, fused_frame, gyro_vector)
        elif src == "internal":
            self._update_state(self._internal, fused_frame, gyro_vector)
    def coherence_score(self) -> float:
        """
        Returns a 0..1 coherence score between both cameras.
        """
        if (
            self._gopro.last_ts_sensor is None
            or self._internal.last_ts_sensor is None
        ):
            return 0.0
        dt = abs(
            self._gopro.last_ts_sensor
            - self._internal.last_ts_sensor
        )
        time_score = max(
            0.0,
            1.0 - (dt / self.MAX_TIME_DELTA_SEC),
        )
        motion_diff = abs(
            self._gopro.motion_energy
            - self._internal.motion_energy
        )
        motion_score = max(
            0.0,
            1.0 - (motion_diff / self.MOTION_BLEND_LIMIT),
        )
        conf_score = min(
            self._gopro.confidence,
            self._internal.confidence,
        )
        return time_score * motion_score * conf_score
    def blended_motion_energy(self) -> float:
        """
        Returns motion energy blended across cameras.
        """
        w_g = self._gopro.confidence
        w_i = self._internal.confidence
        denom = max(w_g + w_i, 1e-6)
        return (
            self._gopro.motion_energy * w_g
            + self._internal.motion_energy * w_i
        ) / denom
    def dominant_camera(self) -> str:
        """
        Returns which camera should drive AI decisions.
        """
        if self._gopro.confidence >= self._internal.confidence:
            return "gopro"
        return "internal"
    def snapshot(self) -> Dict[str, Any]:
        """
        Debug / telemetry snapshot.
        """
        return {
            "coherence": self.coherence_score(),
            "dominant": self.dominant_camera(),
            "gopro": {
                "motion": self._gopro.motion_energy,
                "confidence": self._gopro.confidence,
            },
            "internal": {
                "motion": self._internal.motion_energy,
                "confidence": self._internal.confidence,
            },
        }
