# ==============================================================================
# CHUNK 85 M 07 — CAMERA AI CONFIDENCE-WEIGHTED FUSION CONTROL
# ==============================================================================
#
# Purpose:
#   Dynamically weight, gate, and arbitrate AI decisions using confidence
#   scores derived from:
#     - Sensor integrity
#     - Metadata validity
#     - Dual-camera coherence
#     - Motion stability
#
# This is the FINAL authority layer before AI actions are taken.
#
# Cinematic importance:
#   Prevents AI from making aggressive or incorrect decisions
#   when data quality degrades — a key difference between
#   amateur AI footage and Hollywood-grade reliability.
#
# ==============================================================================

from typing import Dict, Any


class CameraAIConfidenceController:
    """
    Computes global confidence scores and decision gates.
    """
    MIN_CONFIDENCE_TO_ACT = 0.35
    MIN_CONFIDENCE_FOR_HARD_ACTION = 0.65
    def __init__(self):
        self._last_global_confidence: float = 1.0
    def compute_global_confidence(
        self,
        fused_frame,
        coherence_score: float,
        motion_energy: float,
    ) -> float:
        """
        Produces a single confidence scalar [0..1].
        """
        meta_conf = fused_frame.metadata.confidence
        # Penalize extreme motion (motion blur risk)
        motion_penalty = max(0.0, 1.0 - (motion_energy / 6.0))
        # Temporal stability bias
        temporal_bias = 0.9 + 0.1 * min(coherence_score, 1.0)
        global_conf = (
            meta_conf
            * coherence_score
            * motion_penalty
            * temporal_bias
        )
        # Clamp
        global_conf = max(0.0, min(global_conf, 1.0))
        self._last_global_confidence = global_conf
        return global_conf
    def allow_action(self, confidence: float) -> bool:
        """
        Determines if AI is allowed to act at all.
        """
        return confidence >= self.MIN_CONFIDENCE_TO_ACT
    def allow_hard_action(self, confidence: float) -> bool:
        """
        Determines if AI can make irreversible / strong decisions
        (e.g. aggressive reframing, exposure jumps).
        """
        return confidence >= self.MIN_CONFIDENCE_FOR_HARD_ACTION
    def snapshot(self) -> Dict[str, Any]:
        return {
            "last_global_confidence": self._last_global_confidence,
            "min_to_act": self.MIN_CONFIDENCE_TO_ACT,
            "min_hard": self.MIN_CONFIDENCE_FOR_HARD_ACTION,
        }
