# ==============================================================================
# CHUNK 85 M 08 — CAMERA AI MOTION-VECTOR EXTRACTION
# ==============================================================================
#
# Purpose:
#   Extract physically meaningful motion vectors from:
#     - Gyro-aligned temporal frames
#     - Pixel-domain frame deltas
#
# These vectors are used by:
#   - Electronic image stabilization (EIS)
#   - Rolling-shutter correction
#   - AI reframing & subject locking
#   - Motion-aware exposure & shutter control
#
# Cinematic importance:
#   Film-grade motion must feel *inertial*, not digital.
#   This layer bridges sensor physics → visual motion.
#
# ==============================================================================

from typing import Dict, Any, Optional, Tuple
import numpy as np


class CameraAIMotionVector:
    """
    Canonical motion vector representation.
    """
    __slots__ = (
        "dx",
        "dy",
        "rotation",
        "confidence",
    )
    def __init__(
        self,
        dx: float,
        dy: float,
        rotation: float,
        confidence: float,
    ):
        self.dx = dx
        self.dy = dy
        self.rotation = rotation
        self.confidence = confidence


class CameraAIMotionVectorExtractor:
    """
    Computes motion vectors from temporal frames and gyro alignment.
    """
    MAX_TRANSLATION = 32.0     # pixels
    MAX_ROTATION = 0.15       # radians
    def __init__(self):
        self._last_gray: Optional[np.ndarray] = None
    def _to_gray(self, image: np.ndarray) -> np.ndarray:
        if image.ndim == 2:
            return image
        return np.dot(image[..., :3], [0.299, 0.587, 0.114])
    def extract(
        self,
        fused_frame,
        gyro_vector: Optional[Dict[str, float]],
    ) -> Optional[CameraAIMotionVector]:
        """
        Extracts motion vector for the given frame.
        """
        image = fused_frame.frame.image
        gray = self._to_gray(image)
        if self._last_gray is None:
            self._last_gray = gray
            return None
        # Pixel-domain translation estimate (phase correlation)
        shift = np.fft.ifft2(
            np.fft.fft2(self._last_gray)
            * np.conj(np.fft.fft2(gray))
        )
        shift = np.abs(shift)
        dy, dx = np.unravel_index(np.argmax(shift), shift.shape)
        if dx > gray.shape[1] // 2:
            dx -= gray.shape[1]
        if dy > gray.shape[0] // 2:
            dy -= gray.shape[0]
        dx = float(np.clip(dx, -self.MAX_TRANSLATION, self.MAX_TRANSLATION))
        dy = float(np.clip(dy, -self.MAX_TRANSLATION, self.MAX_TRANSLATION))
        # Gyro-informed rotation estimate
        rotation = 0.0
        rot_conf = 0.0
        if gyro_vector:
            rotation = float(
                np.clip(
                    gyro_vector["gz"] * 0.002,
                    -self.MAX_ROTATION,
                    self.MAX_ROTATION,
                )
            )
            rot_conf = min(1.0, gyro_vector["magnitude"] / 3.0)
        # Confidence estimation
        trans_mag = np.sqrt(dx * dx + dy * dy)
        trans_conf = max(0.0, 1.0 - (trans_mag / self.MAX_TRANSLATION))
        confidence = min(1.0, trans_conf * (0.5 + 0.5 * rot_conf))
        self._last_gray = gray
        return CameraAIMotionVector(
            dx=dx,
            dy=dy,
            rotation=rotation,
            confidence=confidence,
        )
# ==============================================================================
# END OF CHUNK 85 M 08
# ==============================================================================
# ==============================================================================
# CHUNK 85 M 09 — CAMERA AI ROLLING-SHUTTER COMPENSATION
# ==============================================================================
#
# Purpose:
#   Compensate CMOS rolling-shutter artifacts using:
#     - Gyro-derived angular velocity
#     - Motion vectors (pixel-domain)
#     - Per-row temporal offset modeling
#
# This module corrects:
#   - Skew during fast yaw
#   - Wobble / jello during vibration
#   - Vertical shear in high-speed motion
#
# Cinematic importance:
#   Rolling-shutter artifacts instantly reveal “cheap digital”.
#   Correcting them is mandatory for cinema-grade drone footage.
#
# ==============================================================================

from typing import Optional, Dict, Any
import numpy as np


class CameraAIRollingShutterModel:
    """
    Models rolling-shutter timing across the sensor.
    """
    __slots__ = (
        "readout_time_sec",
        "rows",
    )
    def __init__(self, readout_time_sec: float, rows: int):
        self.readout_time_sec = readout_time_sec
        self.rows = rows
    def row_time_offset(self, row: int) -> float:
        """
        Time offset (seconds) from frame midpoint for a given row.
        """
        return (
            (row / max(self.rows - 1, 1)) - 0.5
        ) * self.readout_time_sec


class CameraAIRollingShutterCompensator:
    """
    Applies rolling-shutter correction to frames.
    """
    MAX_WARP_PX = 48.0
    def __init__(self, model: CameraAIRollingShutterModel):
        self._model = model
    def compensate(
        self,
        fused_frame,
        motion_vector,
        gyro_vector: Optional[Dict[str, float]],
    ):
        """
        Returns a rolling-shutter compensated image.
        """
        img = fused_frame.frame.image
        h, w = img.shape[:2]
        # Prepare output
        corrected = np.zeros_like(img)
        # Angular velocity (rad/s)
        yaw_rate = gyro_vector["gz"] if gyro_vector else 0.0
        # Translation components
        dx = motion_vector.dx if motion_vector else 0.0
        dy = motion_vector.dy if motion_vector else 0.0
        for row in range(h):
            dt = self._model.row_time_offset(row)
            # Rotation-induced horizontal shift
            rot_shift = yaw_rate * dt * w
            # Translation-induced shift
            trans_x = dx * (dt / max(self._model.readout_time_sec, 1e-6))
            trans_y = dy * (dt / max(self._model.readout_time_sec, 1e-6))
            shift_x = np.clip(
                rot_shift + trans_x,
                -self.MAX_WARP_PX,
                self.MAX_WARP_PX,
            )
            shift_y = np.clip(
                trans_y,
                -self.MAX_WARP_PX,
                self.MAX_WARP_PX,
            )
            src_y = int(np.clip(row + shift_y, 0, h - 1))
            if shift_x >= 0:
                sx = int(min(w - 1, shift_x))
                corrected[row, sx:] = img[src_y, : w - sx]
            else:
                sx = int(min(w - 1, -shift_x))
                corrected[row, : w - sx] = img[src_y, sx:]
        return corrected
