# ==============================================================================
# CHUNK 85 M 10 — CAMERA AI FRAME QUALITY SCORING
# ==============================================================================
#
# Purpose:
#   Produce a continuous, differentiable quality score per frame that reflects
#   cinematic usability. This score is consumed by:
#     - Exposure AI (risk-aware decisions)
#     - Stabilization strength modulation
#     - Shot selection / rejection
#     - Cloud-side multi-take ranking
#
# What it measures (physically & perceptually grounded):
#   - Motion blur severity (temporal MTF proxy)
#   - Rolling-shutter residual error (post-correction)
#   - Noise visibility (signal-dependent)
#   - Highlight clipping risk (ACES headroom-aware)
#   - Shadow crush risk
#   - Local contrast integrity (micro-contrast)
#
# Output:
#   quality_score ∈ [0, 1], higher is better.
#
# ==============================================================================

from typing import Dict, Optional
import numpy as np


class CameraAIFrameQualityScorer:
    """
    Computes a robust cinematic quality score for a frame.
    """
    __slots__ = (
        "_w_blur",
        "_w_noise",
        "_w_clip",
        "_w_shadow",
        "_w_rs",
        "_w_contrast",
    )
    def __init__(
        self,
        w_blur: float = 0.22,
        w_noise: float = 0.18,
        w_clip: float = 0.18,
        w_shadow: float = 0.14,
        w_rs: float = 0.16,
        w_contrast: float = 0.12,
    ):
        # Weights sum to 1.00 by design
        self._w_blur = w_blur
        self._w_noise = w_noise
        self._w_clip = w_clip
        self._w_shadow = w_shadow
        self._w_rs = w_rs
        self._w_contrast = w_contrast
    def score(
        self,
        linear_frame: np.ndarray,
        motion_metrics: Dict[str, float],
        noise_metrics: Dict[str, float],
        rs_residual_px: float,
        exposure_metrics: Dict[str, float],
    ) -> float:
        """
        Returns a scalar quality score in [0, 1].
        """
        blur_penalty = self._blur_penalty(motion_metrics)
        noise_penalty = self._noise_penalty(noise_metrics)
        clip_penalty = self._clip_penalty(exposure_metrics)
        shadow_penalty = self._shadow_penalty(exposure_metrics)
        rs_penalty = self._rs_quality_penalty(rs_residual_px)
        contrast_penalty = self._contrast_penalty(linear_frame)
        total_penalty = (
            self._w_blur * blur_penalty
            + self._w_noise * noise_penalty
            + self._w_clip * clip_penalty
            + self._w_shadow * shadow_penalty
            + self._w_rs * rs_penalty
            + self._w_contrast * contrast_penalty
        )
        return float(np.clip(1.0 - total_penalty, 0.0, 1.0))
    # --------------------------------------------------------------------------
    # Individual penalty terms (0 = perfect, 1 = unusable)
    # --------------------------------------------------------------------------
    def _blur_penalty(self, motion_metrics: Dict[str, float]) -> float:
        """
        Penalize shutter-induced blur using normalized motion energy.
        """
        blur_energy = motion_metrics.get("blur_energy", 0.0)
        return float(np.clip(blur_energy / 1.5, 0.0, 1.0))
    def _noise_penalty(self, noise_metrics: Dict[str, float]) -> float:
        """
        Penalize perceptible noise, weighted toward shadows.
        """
        luma_noise = noise_metrics.get("luma_noise", 0.0)
        chroma_noise = noise_metrics.get("chroma_noise", 0.0)
        return float(np.clip(0.7 * luma_noise + 0.3 * chroma_noise, 0.0, 1.0))
    def _clip_penalty(self, exposure_metrics: Dict[str, float]) -> float:
        """
        Penalize highlight clipping using ACES headroom awareness.
        """
        clip_ratio = exposure_metrics.get("highlight_clip_ratio", 0.0)
        return float(np.clip(clip_ratio / 0.02, 0.0, 1.0))
    def _shadow_penalty(self, exposure_metrics: Dict[str, float]) -> float:
        """
        Penalize crushed shadows (lost detail).
        """
        shadow_loss = exposure_metrics.get("shadow_detail_loss", 0.0)
        return float(np.clip(shadow_loss / 0.15, 0.0, 1.0))
    def _rs_quality_penalty(self, rs_residual_px: float) -> float:
        """
        Penalize remaining rolling-shutter artifacts after correction.
        """
        return float(np.clip(abs(rs_residual_px) / 6.0, 0.0, 1.0))
    def _contrast_penalty(self, linear_frame: np.ndarray) -> float:
        """
        Penalize micro-contrast collapse (flat digital look).
        """
        # Local contrast proxy: std of Laplacian magnitude
        if linear_frame.ndim == 3:
            luma = (
                0.2126 * linear_frame[..., 0]
                + 0.7152 * linear_frame[..., 1]
                + 0.0722 * linear_frame[..., 2]
            )
        else:
            luma = linear_frame
        lap = np.abs(
            np.gradient(np.gradient(luma, axis=0), axis=1)
        )
        contrast = float(np.mean(lap))
        return float(np.clip(0.04 / max(contrast, 1e-6), 0.0, 1.0))
