# END OF CHUNK 85 M 10
# ==============================================================================
# ==============================================================================
# CHUNK 85 N 01 — CAMERA AI EXPOSURE INTENT ENGINE
# ==============================================================================
#
# Purpose:
#   Convert scene understanding + motion + artistic intent into a
#   physically-grounded exposure target in linear light.
#
# This engine DOES NOT set camera parameters directly.
# It produces an "exposure intent" that downstream modules translate into:
#   - ISO / Shutter / ND choices
#   - Highlight protection strength
#   - Motion-blur tolerance
#
# Cinematic principles enforced:
#   - Protect highlights first (filmic latitude)
#   - Preserve midtone skin exposure
#   - Allow controlled shadow roll-off (never crush early)
#   - Respect motion (shutter angle discipline)
#
# ==============================================================================

from typing import Dict, Optional
import numpy as np


class CameraAIExposureIntent:
    """
    Represents a high-level exposure target in scene-linear space.
    """
    __slots__ = (
        "target_middle_gray",
        "highlight_headroom_stops",
        "shadow_floor_stops",
        "motion_blur_budget",
        "confidence",
    )
    def __init__(
        self,
        target_middle_gray: float,
        highlight_headroom_stops: float,
        shadow_floor_stops: float,
        motion_blur_budget: float,
        confidence: float,
    ):
        self.target_middle_gray = target_middle_gray
        self.highlight_headroom_stops = highlight_headroom_stops
        self.shadow_floor_stops = shadow_floor_stops
        self.motion_blur_budget = motion_blur_budget
        self.confidence = confidence


class CameraAIExposureIntentEngine:
    """
    Computes exposure intent from scene statistics and motion context.
    """
    # Canonical cinema references
    MIDDLE_GRAY = 0.18
    def __init__(
        self,
        max_highlight_headroom: float = 3.5,
        min_highlight_headroom: float = 1.5,
        max_shadow_floor: float = -7.0,
    ):
        self._max_headroom = max_highlight_headroom
        self._min_headroom = min_highlight_headroom
        self._max_shadow_floor = max_shadow_floor
    def compute_intent(
        self,
        linear_frame: np.ndarray,
        scene_metrics: Dict[str, float],
        motion_metrics: Dict[str, float],
        frame_quality: float,
    ) -> CameraAIExposureIntent:
        """
        Returns an exposure intent object.
        """
        # ------------------------------------------------------------------
        # Scene luminance analysis
        # ------------------------------------------------------------------
        avg_luma = scene_metrics.get("avg_luma", self.MIDDLE_GRAY)
        highlight_ratio = scene_metrics.get("highlight_ratio", 0.0)
        shadow_ratio = scene_metrics.get("shadow_ratio", 0.0)
        # ------------------------------------------------------------------
        # Motion context
        # ------------------------------------------------------------------
        motion_energy = motion_metrics.get("motion_energy", 0.0)
        angular_velocity = motion_metrics.get("angular_velocity", 0.0)
        # ------------------------------------------------------------------
        # Target middle gray adjustment
        # ------------------------------------------------------------------
        # Bias mid-gray slightly darker in highlight-heavy scenes
        highlight_bias = np.clip(highlight_ratio * 0.25, 0.0, 0.12)
        target_middle = np.clip(
            self.MIDDLE_GRAY * (1.0 - highlight_bias),
            0.12,
            0.22,
        )
        # ------------------------------------------------------------------
        # Highlight headroom (in stops)
        # ------------------------------------------------------------------
        # More headroom when highlights dominate
        headroom = (
            self._max_headroom
            - highlight_ratio * (self._max_headroom - self._min_headroom)
        )
        headroom = np.clip(
            headroom,
            self._min_headroom,
            self._max_headroom,
        )
        # ------------------------------------------------------------------
        # Shadow floor (negative stops below middle gray)
        # ------------------------------------------------------------------
        # Lift shadow floor slightly if noise risk is high
        shadow_floor = self._max_shadow_floor + shadow_ratio * 1.5
        shadow_floor = min(shadow_floor, -3.5)
        # ------------------------------------------------------------------
        # Motion blur budget (normalized)
        # ------------------------------------------------------------------
        # Higher motion → lower blur tolerance
        motion_blur_budget = float(
            np.clip(1.0 - (motion_energy + angular_velocity) * 0.4, 0.2, 1.0)
        )
        # ------------------------------------------------------------------
        # Confidence estimation
        # ------------------------------------------------------------------
        # Low confidence if frame quality is already degraded
        confidence = float(np.clip(frame_quality, 0.2, 1.0))
        return CameraAIExposureIntent(
            target_middle_gray=target_middle,
            highlight_headroom_stops=headroom,
            shadow_floor_stops=shadow_floor,
            motion_blur_budget=motion_blur_budget,
            confidence=confidence,
        )
# ==============================================================================
# END OF CHUNK 85 N 01
