# ==============================================================================
# CHUNK 85 N 02 — CAMERA AI EXPOSURE TEMPORAL SMOOTHING
# ==============================================================================
#
# Purpose:
#   Stabilize exposure intent over time while preserving responsiveness
#   to genuine scene changes (e.g., sun breaks, tunnels, silhouettes).
#
# Cinematic rules enforced:
#   - No visible exposure pumping
#   - Fast dark→bright transitions allowed (protect highlights)
#   - Slow bright→dark transitions (avoid shadow noise jumps)
#   - Confidence-weighted smoothing (bad frames influence less)
#
# ==============================================================================

from typing import Optional
import numpy as np


class CameraAIExposureTemporalSmoother:
    """
    Applies asymmetric, confidence-aware temporal smoothing to exposure intent.
    """
    __slots__ = (
        "_alpha_up",
        "_alpha_down",
        "_prev_intent",
    )
    def __init__(
        self,
        alpha_up: float = 0.35,
        alpha_down: float = 0.12,
    ):
        """
        alpha_up:
            Responsiveness when scene gets brighter (protect highlights).
        alpha_down:
            Responsiveness when scene gets darker (avoid noise pumping).
        """
        self._alpha_up = float(np.clip(alpha_up, 0.05, 0.6))
        self._alpha_down = float(np.clip(alpha_down, 0.02, 0.4))
        self._prev_intent: Optional["CameraAIExposureIntent"] = None
    def reset(self):
        self._prev_intent = None
    def smooth(
        self,
        current: "CameraAIExposureIntent",
    ) -> "CameraAIExposureIntent":
        """
        Returns a temporally smoothed exposure intent.
        """
        if self._prev_intent is None:
            self._prev_intent = current
            return current
        prev = self._prev_intent
        # ------------------------------------------------------------------
        # Determine direction of change (middle gray as proxy)
        # ------------------------------------------------------------------
        delta = current.target_middle_gray - prev.target_middle_gray
        alpha = self._alpha_up if delta < 0.0 else self._alpha_down
        # Confidence-weighted adaptation
        alpha *= float(np.clip(current.confidence, 0.3, 1.0))
        # ------------------------------------------------------------------
        # Smooth each component
        # ------------------------------------------------------------------
        target_middle = (
            prev.target_middle_gray
            + alpha * (current.target_middle_gray - prev.target_middle_gray)
        )
        highlight_headroom = (
            prev.highlight_headroom_stops
            + alpha * (
                current.highlight_headroom_stops
                - prev.highlight_headroom_stops
            )
        )
        shadow_floor = (
            prev.shadow_floor_stops
            + alpha * (
                current.shadow_floor_stops
                - prev.shadow_floor_stops
            )
        )
        motion_blur_budget = (
            prev.motion_blur_budget
            + alpha * (
                current.motion_blur_budget
                - prev.motion_blur_budget
            )
        )
        confidence = float(
            np.clip(
                0.6 * prev.confidence + 0.4 * current.confidence,
                0.2,
                1.0,
            )
        )
        smoothed = CameraAIExposureIntent(
            target_middle_gray=target_middle,
            highlight_headroom_stops=highlight_headroom,
            shadow_floor_stops=shadow_floor,
            motion_blur_budget=motion_blur_budget,
            confidence=confidence,
        )
        self._prev_intent = smoothed
        return smoothed
# ==============================================================================
# END OF CHUNK 85 N 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 N 03 — CAMERA AI HIGHLIGHT PRESERVATION LOGIC
# ==============================================================================
#
# Purpose:
#   Prevent irreversible highlight clipping while maintaining natural roll-off.
#
# This module:
#   - Predicts highlight saturation BEFORE it happens
#   - Applies pre-emptive compression (not hard clipping)
#   - Preserves hue integrity in high-energy channels
#
# Cinematic rules enforced:
#   - Highlights must roll, never clip abruptly
#   - Hue must not skew under compression
#   - Speculars may compress harder than diffuse highlights
#
# ACES-aligned behavior:
#   Operates in scene-linear, AP1 primaries assumed.
#
# ==============================================================================

from typing import Tuple
import numpy as np


class CameraAIHighlightPreserver:
    """
    Applies highlight protection in scene-linear space.
    """
    __slots__ = (
        "_knee_start",
        "_knee_strength",
        "_specular_bias",
    )
    def __init__(
        self,
        knee_start: float = 0.75,
        knee_strength: float = 0.65,
        specular_bias: float = 0.25,
    ):
        """
        knee_start:
            Normalized linear level where compression begins.
        knee_strength:
            Compression aggressiveness (higher = softer roll-off).
        specular_bias:
            Extra compression applied to specular highlights.
        """
        self._knee_start = float(np.clip(knee_start, 0.6, 0.9))
        self._knee_strength = float(np.clip(knee_strength, 0.2, 0.9))
        self._specular_bias = float(np.clip(specular_bias, 0.0, 0.5))
    def preserve(
        self,
        linear_rgb: np.ndarray,
        highlight_mask: np.ndarray,
    ) -> np.ndarray:
        """
        Applies highlight compression while preserving color ratios.
        """
        rgb = linear_rgb.copy()
        # Compute luminance (AP1 / Rec.709 close proxy)
        luma = (
            0.2126 * rgb[..., 0]
            + 0.7152 * rgb[..., 1]
            + 0.0722 * rgb[..., 2]
        )
        # Identify highlight region
        knee = self._knee_start * np.max(luma)
        over = np.maximum(luma - knee, 0.0)
        # Specular detection (fast local contrast spike)
        specular = highlight_mask.astype(np.float32)
        # Compression curve (smooth knee)
        compression = over / (over + self._knee_strength)
        # Bias compression for speculars
        compression *= (1.0 + specular * self._specular_bias)
        compression = np.clip(compression, 0.0, 0.85)
        # Apply ratio-preserving compression
        scale = 1.0 - compression
        rgb[..., 0] *= scale
        rgb[..., 1] *= scale
        rgb[..., 2] *= scale
        return rgb
# ==============================================================================
# END OF CHUNK 85 N 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 N 04 — CAMERA AI SHADOW DETAIL PROTECTION
# ==============================================================================
#
# Purpose:
#   Preserve perceptible shadow detail while controlling noise and avoiding
#   washed-out blacks. This module works in scene-linear space and prepares
#   shadows for downstream filmic tone mapping.
#
# Cinematic rules enforced:
#   - Shadows should retain texture, not turn gray
#   - Noise amplification must be controlled
#   - Black floor should feel “anchored”, not floating
#
# Key idea:
#   Apply adaptive shadow lift with noise-aware gating and soft floor anchoring.
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIShadowProtector:
    """
    Protects shadow detail while maintaining cinematic black levels.
    """
    __slots__ = (
        "_lift_strength",
        "_noise_gate",
        "_black_floor",
    )
    def __init__(
        self,
        lift_strength: float = 0.35,
        noise_gate: float = 0.12,
        black_floor: float = 0.003,
    ):
        """
        lift_strength:
            Maximum fractional lift applied to deep shadows.
        noise_gate:
            Threshold above which noise limits shadow lifting.
        black_floor:
            Absolute minimum linear value to anchor blacks.
        """
        self._lift_strength = float(np.clip(lift_strength, 0.1, 0.6))
        self._noise_gate = float(np.clip(noise_gate, 0.05, 0.25))
        self._black_floor = float(np.clip(black_floor, 1e-4, 0.01))
    def protect(
        self,
        linear_rgb: np.ndarray,
        noise_metrics: Dict[str, float],
    ) -> np.ndarray:
        """
        Returns shadow-protected linear RGB.
        """
        rgb = linear_rgb.copy()
        # Compute luminance
        luma = (
            0.2126 * rgb[..., 0]
            + 0.7152 * rgb[..., 1]
            + 0.0722 * rgb[..., 2]
        )
        # Noise estimation (prefer luma noise)
        luma_noise = noise_metrics.get("luma_noise", 0.0)
        # Shadow mask (smooth falloff)
        shadow_mask = np.clip(
            (0.12 - luma) / 0.12,
            0.0,
            1.0,
        )
        # Noise-aware attenuation
        noise_atten = np.clip(
            1.0 - (luma_noise / max(self._noise_gate, 1e-6)),
            0.0,
            1.0,
        )
        # Final lift factor
        lift = self._lift_strength * shadow_mask * noise_atten
        # Apply lift proportionally (ratio-preserving)
        rgb[..., 0] += rgb[..., 0] * lift
        rgb[..., 1] += rgb[..., 1] * lift
        rgb[..., 2] += rgb[..., 2] * lift
        # Anchor blacks (prevent floating)
        rgb[..., 0] = np.maximum(rgb[..., 0], self._black_floor)
        rgb[..., 1] = np.maximum(rgb[..., 1], self._black_floor)
        rgb[..., 2] = np.maximum(rgb[..., 2], self._black_floor)
        return rgb
# ==============================================================================
# END OF CHUNK 85 N 04
