# ==============================================================================
# CHUNK 85 N 05 — CAMERA AI ISO–SHUTTER TRADEOFF MODEL
# ==============================================================================
#
# Purpose:
#   Decide the optimal balance between ISO gain and shutter speed based on:
#     - Exposure intent (from 85N-01/02)
#     - Motion context (blur tolerance)
#     - Noise characteristics
#     - Rolling-shutter risk
#
# Cinematic principles enforced:
#   - Maintain a filmic shutter angle whenever possible
#   - Prefer ISO increase over shutter drag once blur budget is exceeded
#   - Avoid ISO jumps that cause visible noise pumping
#
# This module outputs *targets*, not hardware commands.
#
# ==============================================================================

from typing import Dict, Tuple
import numpy as np


class CameraAIISOSHutterDecision:
    """
    Represents a recommended ISO and shutter time pair.
    """
    __slots__ = (
        "iso",
        "shutter_sec",
        "confidence",
    )
    def __init__(self, iso: int, shutter_sec: float, confidence: float):
        self.iso = int(iso)
        self.shutter_sec = float(shutter_sec)
        self.confidence = float(confidence)


class CameraAIISOSHutterModel:
    """
    Computes ISO–shutter tradeoff respecting cinematic motion rules.
    """
    # Reference cinema shutter angle (180°)
    SHUTTER_ANGLE = 0.5
    def __init__(
        self,
        min_iso: int = 100,
        max_iso: int = 6400,
        min_shutter: float = 1.0 / 240.0,
        max_shutter: float = 1.0 / 30.0,
    ):
        self._min_iso = min_iso
        self._max_iso = max_iso
        self._min_shutter = min_shutter
        self._max_shutter = max_shutter
    def decide(
        self,
        fps: float,
        exposure_intent: "CameraAIExposureIntent",
        noise_metrics: Dict[str, float],
    ) -> CameraAIISOSHutterDecision:
        """
        Returns ISO/shutter recommendation.
        """
        # --------------------------------------------------------------
        # Ideal cinematic shutter from shutter angle
        # --------------------------------------------------------------
        ideal_shutter = self.SHUTTER_ANGLE / max(fps, 1e-6)
        # Clamp to camera limits
        shutter = float(
            np.clip(ideal_shutter, self._min_shutter, self._max_shutter)
        )
        # --------------------------------------------------------------
        # Motion blur constraint
        # --------------------------------------------------------------
        blur_budget = exposure_intent.motion_blur_budget
        # If motion is high, shorten shutter
        shutter *= float(np.clip(blur_budget, 0.4, 1.0))
        # --------------------------------------------------------------
        # ISO estimation
        # --------------------------------------------------------------
        # Estimate ISO based on exposure deficit
        # (relative to middle gray target)
        target_gray = exposure_intent.target_middle_gray
        # Simple proxy: darker target → higher ISO
        iso_scale = self._min_iso * (0.18 / max(target_gray, 1e-6))
        # Noise-aware ISO limiting
        luma_noise = noise_metrics.get("luma_noise", 0.0)
        noise_penalty = np.clip(luma_noise / 0.15, 0.0, 1.0)
        iso = iso_scale * (1.0 + noise_penalty * 0.6)
        iso = int(np.clip(iso, self._min_iso, self._max_iso))
        # --------------------------------------------------------------
        # Confidence estimation
        # --------------------------------------------------------------
        confidence = float(
            np.clip(
                exposure_intent.confidence * (1.0 - noise_penalty * 0.5),
                0.2,
                1.0,
            )
        )
        return CameraAIISOSHutterDecision(
            iso=iso,
            shutter_sec=shutter,
            confidence=confidence,
        )
# ==============================================================================
# END OF CHUNK 85 N 05
