# ==============================================================================
# CHUNK 85 N 06 — CAMERA AI ND FILTER STRATEGY
# ==============================================================================
#
# Purpose:
#   Decide when and how strongly ND filtration should be applied to:
#     - Preserve cinematic shutter angles
#     - Prevent highlight clipping in high-luminance scenes
#     - Avoid ISO inflation in bright daylight
#
# This module operates at the *intent* level.
# It does NOT directly actuate hardware; it outputs ND density targets.
#
# Cinematic rules enforced:
#   - Prefer ND over shutter shortening in bright scenes
#   - Maintain stable ND (avoid flicker / rapid switching)
#   - Respect motion blur budget
#
# Typical drone scenario:
#   High sun + fast motion + fixed aperture → ND is mandatory.
#
# ==============================================================================

from typing import Optional
import numpy as np


class CameraAINDDecision:
    """
    Represents an ND filter strength recommendation.
    """
    __slots__ = (
        "nd_stops",
        "confidence",
    )
    def __init__(self, nd_stops: float, confidence: float):
        self.nd_stops = float(nd_stops)
        self.confidence = float(confidence)


class CameraAINDStrategy:
    """
    Computes ND filtration requirements from exposure intent and scene brightness.
    """
    def __init__(
        self,
        max_nd_stops: float = 6.0,
        nd_step: float = 0.5,
        hysteresis: float = 0.25,
    ):
        """
        max_nd_stops:
            Maximum supported ND strength (e.g., ND64 ≈ 6 stops).
        nd_step:
            Quantization step for ND filters.
        hysteresis:
            Prevents ND flicker by requiring meaningful change.
        """
        self._max_nd = max_nd_stops
        self._step = nd_step
        self._hysteresis = hysteresis
        self._prev_nd: Optional[float] = None
    def decide(
        self,
        scene_luminance_ev: float,
        exposure_intent: "CameraAIExposureIntent",
        shutter_sec: float,
        fps: float,
    ) -> CameraAINDDecision:
        """
        Returns ND strength recommendation in stops.
        """
        # --------------------------------------------------------------
        # Ideal shutter for cinematic motion
        # --------------------------------------------------------------
        ideal_shutter = 0.5 / max(fps, 1e-6)
        # --------------------------------------------------------------
        # Determine overexposure pressure
        # --------------------------------------------------------------
        shutter_ratio = ideal_shutter / max(shutter_sec, 1e-6)
        # If shutter already shorter than ideal, ND needed
        ev_pressure = max(np.log2(shutter_ratio), 0.0)
        # Add highlight headroom pressure
        ev_pressure += max(
            0.0,
            scene_luminance_ev
            - exposure_intent.highlight_headroom_stops,
        )
        # --------------------------------------------------------------
        # Compute raw ND requirement
        # --------------------------------------------------------------
        nd_required = np.clip(ev_pressure, 0.0, self._max_nd)
        # Quantize to real ND steps
        nd_quantized = round(nd_required / self._step) * self._step
        # --------------------------------------------------------------
        # Hysteresis to prevent flicker
        # --------------------------------------------------------------
        if self._prev_nd is not None:
            if abs(nd_quantized - self._prev_nd) < self._hysteresis:
                nd_quantized = self._prev_nd
        self._prev_nd = nd_quantized
        # --------------------------------------------------------------
        # Confidence estimation
        # --------------------------------------------------------------
        confidence = float(
            np.clip(exposure_intent.confidence, 0.3, 1.0)
        )
        return CameraAINDDecision(
            nd_stops=nd_quantized,
            confidence=confidence,
        )
