# ==============================================================================
# CHUNK 85 N 07 — CAMERA AI EXPOSURE FAILURE DETECTION
# ==============================================================================
#
# Purpose:
#   Detect exposure states that are no longer recoverable or acceptable
#   for cinematic output, and emit structured failure signals.
#
# Failure modes detected:
#   - Irreversible highlight clipping
#   - Shadow detail collapse (noise-dominated)
#   - Exposure oscillation / pumping
#   - Parameter saturation (ISO or shutter pegged)
#
# This module does NOT change exposure.
# It reports failure severity so upstream AI can:
#   - Adjust intent
#   - Switch capture strategy
#   - Flag takes for discard or cloud re-render
#
# ==============================================================================

from typing import Dict, Optional
import numpy as np


class CameraAIExposureFailureReport:
    """
    Structured exposure failure signal.
    """
    __slots__ = (
        "failed",
        "severity",
        "reasons",
    )
    def __init__(self, failed: bool, severity: float, reasons: Dict[str, float]):
        self.failed = bool(failed)
        self.severity = float(severity)
        self.reasons = reasons


class CameraAIExposureFailureDetector:
    """
    Detects exposure failure conditions using scene-linear analysis.
    """
    def __init__(
        self,
        max_clip_ratio: float = 0.025,
        max_shadow_noise: float = 0.18,
        max_iso: int = 6400,
        max_shutter_sec: float = 1.0 / 30.0,
        oscillation_threshold: float = 0.15,
    ):
        self._max_clip_ratio = max_clip_ratio
        self._max_shadow_noise = max_shadow_noise
        self._max_iso = max_iso
        self._max_shutter = max_shutter_sec
        self._oscillation_th = oscillation_threshold
        self._prev_middle_gray: Optional[float] = None
    def detect(
        self,
        exposure_metrics: Dict[str, float],
        noise_metrics: Dict[str, float],
        iso: int,
        shutter_sec: float,
        exposure_intent: "CameraAIExposureIntent",
    ) -> CameraAIExposureFailureReport:
        """
        Returns a failure report for the current frame.
        """
        reasons: Dict[str, float] = {}
        # --------------------------------------------------------------
        # Highlight clipping failure
        # --------------------------------------------------------------
        clip_ratio = exposure_metrics.get("highlight_clip_ratio", 0.0)
        if clip_ratio > self._max_clip_ratio:
            reasons["highlight_clipping"] = np.clip(
                clip_ratio / self._max_clip_ratio, 0.0, 2.0
            )
        # --------------------------------------------------------------
        # Shadow noise collapse
        # --------------------------------------------------------------
        luma_noise = noise_metrics.get("luma_noise", 0.0)
        if luma_noise > self._max_shadow_noise:
            reasons["shadow_noise"] = np.clip(
                luma_noise / self._max_shadow_noise, 0.0, 2.0
            )
        # --------------------------------------------------------------
        # Parameter saturation
        # --------------------------------------------------------------
        if iso >= self._max_iso:
            reasons["iso_saturation"] = 1.0
        if shutter_sec >= self._max_shutter:
            reasons["shutter_saturation"] = 1.0
        # --------------------------------------------------------------
        # Exposure oscillation detection
        # --------------------------------------------------------------
        curr_mid = exposure_intent.target_middle_gray
        if self._prev_middle_gray is not None:
            oscillation = abs(curr_mid - self._prev_middle_gray)
            if oscillation > self._oscillation_th:
                reasons["exposure_oscillation"] = np.clip(
                    oscillation / self._oscillation_th, 0.0, 2.0
                )
        self._prev_middle_gray = curr_mid
        # --------------------------------------------------------------
        # Aggregate failure decision
        # --------------------------------------------------------------
        if reasons:
            severity = float(
                np.clip(
                    np.mean(list(reasons.values())),
                    0.0,
                    1.0,
                )
            )
            return CameraAIExposureFailureReport(
                failed=True,
                severity=severity,
                reasons=reasons,
            )
        return CameraAIExposureFailureReport(
            failed=False,
            severity=0.0,
            reasons={},
        )
