# ==============================================================================
# CHUNK 85 N 08 — CAMERA AI SCENE DYNAMIC RANGE ESTIMATOR
# ==============================================================================
#
# Purpose:
#   Estimate the usable scene dynamic range (in stops) directly from
#   scene-linear imagery, with noise-aware shadow limits and highlight
#   headroom awareness.
#
# Why this matters:
#   - Determines whether the scene fits in sensor latitude
#   - Drives highlight vs shadow prioritization
#   - Informs ACES tone-mapping strength
#   - Signals when cloud HDR reconstruction may be required
#
# Cinematic rules enforced:
#   - Dynamic range must be *usable*, not theoretical
#   - Noise floor defines shadow limit
#   - Specular spikes do not inflate DR estimate
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAISceneDynamicRangeEstimator:
    """
    Estimates usable dynamic range of the scene in stops.
    """
    __slots__ = (
        "_noise_floor_ev",
        "_clip_percentile",
    )
    def __init__(
        self,
        noise_floor_ev: float = -7.5,
        clip_percentile: float = 99.9,
    ):
        """
        noise_floor_ev:
            Lowest usable shadow level in EV (noise-limited).
        clip_percentile:
            Percentile used to ignore rare specular outliers.
        """
        self._noise_floor_ev = noise_floor_ev
        self._clip_percentile = clip_percentile
    def estimate(
        self,
        linear_rgb: np.ndarray,
        noise_metrics: Dict[str, float],
    ) -> float:
        """
        Returns usable scene dynamic range in stops.
        """
        # ------------------------------------------------------------------
        # Compute scene luminance
        # ------------------------------------------------------------------
        luma = (
            0.2126 * linear_rgb[..., 0]
            + 0.7152 * linear_rgb[..., 1]
            + 0.0722 * linear_rgb[..., 2]
        )
        luma = np.clip(luma, 1e-8, None)
        # ------------------------------------------------------------------
        # Highlight ceiling (ignore extreme speculars)
        # ------------------------------------------------------------------
        highlight_level = np.percentile(luma, self._clip_percentile)
        highlight_ev = np.log2(highlight_level / 0.18)
        # ------------------------------------------------------------------
        # Shadow floor (noise-aware)
        # ------------------------------------------------------------------
        luma_noise = noise_metrics.get("luma_noise", 0.0)
        # Noise lifts shadow floor
        noise_penalty_ev = np.clip(luma_noise / 0.1, 0.0, 2.0)
        shadow_ev = self._noise_floor_ev + noise_penalty_ev
        # ------------------------------------------------------------------
        # Usable dynamic range
        # ------------------------------------------------------------------
        dynamic_range = max(highlight_ev - shadow_ev, 0.0)
        return float(np.clip(dynamic_range, 0.0, 20.0))
# ==============================================================================
# END OF CHUNK 85 N 08
# ==============================================================================
# ==============================================================================
# CHUNK 85 N 09 — CAMERA AI EXPOSURE CONFIDENCE FEEDBACK ENGINE
# ==============================================================================
#
# Purpose:
#   Produce a continuous confidence score (0–1) describing how reliable
#   the current exposure decision is, given noise, motion, DR stress,
#   clipping risk, and temporal stability.
#
# Why this matters:
#   - Prevents AI from overreacting to unreliable frames
#   - Gates autonomous exposure overrides
#   - Signals when cloud-assisted refinement is required
#   - Allows UI / logging to reflect trustworthiness of exposure
#
# Cinematic constraints:
#   - Confidence must decay smoothly (no binary jumps)
#   - Motion + noise reduce trust even if histogram looks “good”
#   - Overconfidence is worse than underconfidence
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIExposureConfidenceEngine:
    """
    Computes exposure reliability score for camera AI.
    """
    __slots__ = (
        "_motion_weight",
        "_noise_weight",
        "_clip_weight",
        "_temporal_weight",
    )
    def __init__(
        self,
        motion_weight: float = 0.30,
        noise_weight: float = 0.30,
        clip_weight: float = 0.25,
        temporal_weight: float = 0.15,
    ):
        self._motion_weight = motion_weight
        self._noise_weight = noise_weight
        self._clip_weight = clip_weight
        self._temporal_weight = temporal_weight
    def compute(
        self,
        exposure_metrics: Dict[str, float],
        noise_metrics: Dict[str, float],
        motion_metrics: Dict[str, float],
        temporal_metrics: Dict[str, float],
    ) -> float:
        """
        Returns exposure confidence score in range [0, 1].
        """
        # ------------------------------------------------------------------
        # Motion confidence (fast motion = less reliable metering)
        # ------------------------------------------------------------------
        motion_mag = motion_metrics.get("motion_magnitude", 0.0)
        motion_conf = np.exp(-motion_mag * 2.5)
        # ------------------------------------------------------------------
        # Noise confidence (noise undermines shadow accuracy)
        # ------------------------------------------------------------------
        luma_noise = noise_metrics.get("luma_noise", 0.0)
        noise_conf = np.exp(-luma_noise * 8.0)
        # ------------------------------------------------------------------
        # Clipping confidence (highlight or shadow loss)
        # ------------------------------------------------------------------
        highlight_clip = exposure_metrics.get("highlight_clip_ratio", 0.0)
        shadow_clip = exposure_metrics.get("shadow_clip_ratio", 0.0)
        clip_penalty = highlight_clip * 1.2 + shadow_clip * 0.8
        clip_conf = np.exp(-clip_penalty * 6.0)
        # ------------------------------------------------------------------
        # Temporal stability confidence
        # ------------------------------------------------------------------
        exposure_delta = temporal_metrics.get("exposure_delta_ev", 0.0)
        temporal_conf = np.exp(-abs(exposure_delta) * 1.8)
        # ------------------------------------------------------------------
        # Weighted fusion
        # ------------------------------------------------------------------
        confidence = (
            motion_conf * self._motion_weight
            + noise_conf * self._noise_weight
            + clip_conf * self._clip_weight
            + temporal_conf * self._temporal_weight
        )
        return float(np.clip(confidence, 0.0, 1.0))
# ==============================================================================
# END OF CHUNK 85 N 09
# ==============================================================================
# ==============================================================================
# CHUNK 85 O 01 — CAMERA AI WHITE BALANCE INTENT ENGINE
# ==============================================================================
#
# Purpose:
#   Infer *intentional* white balance target (not just neutral gray),
#   balancing scene physics, subject priority, and cinematic bias.
#
# Why this matters:
#   - Cinematic WB is rarely mathematically neutral
#   - Preserves warmth in faces, coolness in skies, mood consistency
#   - Prevents WB “hunting” in mixed or changing light
#
# Cinematic constraints:
#   - Human skin tones dominate intent unless explicitly overridden
#   - Scene mood > absolute chromatic neutrality
#   - Intent must be temporally stable and explainable
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIWhiteBalanceIntentEngine:
    """
    Determines intended white balance target for cinematic rendering.
    """
    __slots__ = (
        "_skin_priority",
        "_scene_priority",
        "_mood_bias_strength",
    )
    def __init__(
        self,
        skin_priority: float = 0.55,
        scene_priority: float = 0.30,
        mood_bias_strength: float = 0.15,
    ):
        """
        skin_priority:
            Weight given to detected skin chromaticity.
        scene_priority:
            Weight given to global scene illuminant estimate.
        mood_bias_strength:
            Artistic bias allowing warm/cool intent shifts.
        """
        self._skin_priority = skin_priority
        self._scene_priority = scene_priority
        self._mood_bias_strength = mood_bias_strength
    def infer_intent(
        self,
        scene_wb: np.ndarray,
        skin_wb: np.ndarray,
        mood_vector: np.ndarray,
    ) -> np.ndarray:
        """
        Returns intended white balance chromaticity (RGB gains).
        scene_wb:
            Estimated neutral illuminant gains.
        skin_wb:
            Gains that render skin tones naturally.
        mood_vector:
            Artistic bias vector (e.g. warm sunset, cool dusk).
        """
        # Normalize inputs
        scene_wb = scene_wb / np.mean(scene_wb)
        skin_wb = skin_wb / np.mean(skin_wb)
        mood_vector = mood_vector / (np.mean(mood_vector) + 1e-6)
        # ------------------------------------------------------------------
        # Intent fusion
        # ------------------------------------------------------------------
        intent_wb = (
            skin_wb * self._skin_priority
            + scene_wb * self._scene_priority
            + mood_vector * self._mood_bias_strength
        )
        # Prevent extreme color casts
        intent_wb = np.clip(intent_wb, 0.6, 1.6)
        # Re-normalize to preserve exposure
        intent_wb /= np.mean(intent_wb)
        return intent_wb.astype(np.float32)
# ==============================================================================
# END OF CHUNK 85 O 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 O 02 — CAMERA AI WHITE BALANCE TEMPORAL STABILITY ENGINE
# ==============================================================================
#
# Purpose:
#   Enforce smooth, perceptually stable white balance over time while
#   remaining responsive to genuine illuminant changes.
#
# Why this matters:
#   - Prevents distracting color flicker during motion
#   - Avoids WB “hunting” in mixed or unstable lighting
#   - Maintains shot-to-shot continuity for editing
#
# Cinematic constraints:
#   - WB changes must be slow enough to feel intentional
#   - Sudden real light changes must still be respected
#   - Skin tones are protected from oscillation
#
# ==============================================================================

from typing import Optional
import numpy as np


class CameraAIWhiteBalanceTemporalStability:
    """
    Temporal smoothing and hysteresis for white balance intent.
    """
    __slots__ = (
        "_smoothing_strength",
        "_max_delta_per_frame",
        "_previous_wb",
    )
    def __init__(
        self,
        smoothing_strength: float = 0.92,
        max_delta_per_frame: float = 0.04,
    ):
        """
        smoothing_strength:
            Exponential smoothing factor (higher = more stable).
        max_delta_per_frame:
            Maximum allowed WB gain change per frame.
        """
        self._smoothing_strength = smoothing_strength
        self._max_delta_per_frame = max_delta_per_frame
        self._previous_wb: Optional[np.ndarray] = None
    def stabilize(
        self,
        intended_wb: np.ndarray,
    ) -> np.ndarray:
        """
        Returns temporally stabilized white balance gains.
        """
        intended_wb = intended_wb.astype(np.float32)
        if self._previous_wb is None:
            self._previous_wb = intended_wb.copy()
            return intended_wb
        # ------------------------------------------------------------------
        # Exponential smoothing
        # ------------------------------------------------------------------
        smoothed = (
            self._previous_wb * self._smoothing_strength
            + intended_wb * (1.0 - self._smoothing_strength)
        )
        # ------------------------------------------------------------------
        # Clamp per-frame change to avoid flicker
        # ------------------------------------------------------------------
        delta = smoothed - self._previous_wb
        delta = np.clip(
            delta,
            -self._max_delta_per_frame,
            self._max_delta_per_frame,
        )
        stabilized = self._previous_wb + delta
        # Re-normalize to preserve exposure
        stabilized /= np.mean(stabilized)
        self._previous_wb = stabilized
        return stabilized
# ==============================================================================
# END OF CHUNK 85 O 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 O 03 — CAMERA AI ILLUMINANT CLASSIFICATION ENGINE
# ==============================================================================
#
# Purpose:
#   Classify dominant scene illuminants (daylight, tungsten, LED, mixed)
#   using chromatic statistics, spatial clustering, and spectral cues.
#
# Why this matters:
#   - Enables correct WB intent under mixed lighting
#   - Prevents color casts from dominant-but-irrelevant light sources
#   - Feeds Mixed-Lighting Resolver and Skin Protection engines
#
# Cinematic constraints:
#   - Classification must be stable over time
#   - Spatial relevance > global dominance
#   - Avoids overfitting to specular highlights
#
# ==============================================================================

from typing import Dict, Tuple
import numpy as np


class CameraAIIlluminantClassifier:
    """
    Classifies scene illuminant types and their relative influence.
    """
    __slots__ = (
        "_daylight_cct_range",
        "_tungsten_cct_range",
        "_led_cct_range",
        "_min_region_weight",
    )
    def __init__(
        self,
        daylight_cct_range: Tuple[int, int] = (5200, 6500),
        tungsten_cct_range: Tuple[int, int] = (2600, 3400),
        led_cct_range: Tuple[int, int] = (3600, 5200),
        min_region_weight: float = 0.08,
    ):
        self._daylight_cct_range = daylight_cct_range
        self._tungsten_cct_range = tungsten_cct_range
        self._led_cct_range = led_cct_range
        self._min_region_weight = min_region_weight
    def classify(
        self,
        region_chromaticities: np.ndarray,
        region_weights: np.ndarray,
        estimated_cct: np.ndarray,
    ) -> Dict[str, float]:
        """
        Returns normalized influence weights for each illuminant class.
        region_chromaticities:
            Nx3 chromaticity samples (scene-linear).
        region_weights:
            Relative spatial importance of each region.
        estimated_cct:
            Correlated color temperature estimate per region.
        """
        weights = region_weights.astype(np.float32)
        weights /= (np.sum(weights) + 1e-6)
        daylight = 0.0
        tungsten = 0.0
        led = 0.0
        unknown = 0.0
        for cct, w in zip(estimated_cct, weights):
            if w < self._min_region_weight:
                continue
            if self._daylight_cct_range[0] <= cct <= self._daylight_cct_range[1]:
                daylight += w
            elif self._tungsten_cct_range[0] <= cct <= self._tungsten_cct_range[1]:
                tungsten += w
            elif self._led_cct_range[0] <= cct <= self._led_cct_range[1]:
                led += w
            else:
                unknown += w
        total = daylight + tungsten + led + unknown + 1e-6
        return {
            "daylight": daylight / total,
            "tungsten": tungsten / total,
            "led": led / total,
            "unknown": unknown / total,
        }
# ==============================================================================
# END OF CHUNK 85 O 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 O 04 — CAMERA AI MIXED-LIGHTING RESOLVER
# ==============================================================================
#
# Purpose:
#   Resolve competing illuminants into a coherent, cinematic white-balance
#   strategy that preserves subject fidelity while respecting scene mood.
#
# Why this matters:
#   - Real scenes are rarely lit by a single illuminant
#   - Naive averaging causes muddy skin tones and color pollution
#   - Cinematic intent often *embraces* mixed lighting selectively
#
# Cinematic constraints:
#   - Subjects (faces) override background lighting
#   - Background lights may remain intentionally colored
#   - Transitions must be spatially and temporally stable
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIMixedLightingResolver:
    """
    Resolves mixed illuminant scenarios into a usable WB strategy.
    """
    __slots__ = (
        "_subject_priority",
        "_background_priority",
        "_max_scene_bias",
    )
    def __init__(
        self,
        subject_priority: float = 0.65,
        background_priority: float = 0.35,
        max_scene_bias: float = 0.25,
    ):
        """
        subject_priority:
            Weight of subject-facing illuminant.
        background_priority:
            Weight of background illuminant influence.
        max_scene_bias:
            Clamp for how far scene WB may drift from subject.
        """
        self._subject_priority = subject_priority
        self._background_priority = background_priority
        self._max_scene_bias = max_scene_bias
    def resolve(
        self,
        illuminant_weights: Dict[str, float],
        subject_wb: np.ndarray,
        scene_wb: np.ndarray,
    ) -> np.ndarray:
        """
        Returns resolved WB gains for mixed-light scene.
        """
        # Normalize inputs
        subject_wb = subject_wb / np.mean(subject_wb)
        scene_wb = scene_wb / np.mean(scene_wb)
        # ------------------------------------------------------------------
        # Compute scene influence strength
        # ------------------------------------------------------------------
        mixed_strength = (
            illuminant_weights.get("tungsten", 0.0)
            + illuminant_weights.get("led", 0.0)
        )
        mixed_strength = np.clip(mixed_strength, 0.0, 1.0)
        # ------------------------------------------------------------------
        # Blend subject vs scene
        # ------------------------------------------------------------------
        resolved = (
            subject_wb * self._subject_priority
            + scene_wb * self._background_priority * mixed_strength
        )
        # ------------------------------------------------------------------
        # Prevent excessive drift from subject
        # ------------------------------------------------------------------
        drift = resolved - subject_wb
        drift = np.clip(
            drift,
            -self._max_scene_bias,
            self._max_scene_bias,
        )
        resolved = subject_wb + drift
        # Re-normalize to preserve exposure
        resolved /= np.mean(resolved)
        return resolved.astype(np.float32)
# ==============================================================================
# END OF CHUNK 85 O 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 O 05 — CAMERA AI SKIN-TONE BIAS PROTECTION ENGINE
# ==============================================================================
#
# Purpose:
#   Protect human skin tones from destructive white-balance shifts,
#   preserving natural hue, saturation, and luminance across lighting changes.
#
# Why this matters:
#   - Humans are hyper-sensitive to skin tone errors
#   - WB corrections that are “technically right” can look wrong
#   - Cinematic footage prioritizes faces over background accuracy
#
# Cinematic constraints:
#   - Maintain skin hue within perceptual corridor
#   - Prevent saturation collapse or over-warming
#   - Work in scene-linear space prior to ACES
#
# ==============================================================================

from typing import Tuple
import numpy as np


class CameraAISkinToneBiasProtection:
    """
    Applies protective constraints to WB gains based on detected skin regions.
    """
    __slots__ = (
        "_hue_tolerance",
        "_sat_tolerance",
        "_luma_tolerance",
    )
    def __init__(
        self,
        hue_tolerance: float = 0.035,
        sat_tolerance: float = 0.25,
        luma_tolerance: float = 0.30,
    ):
        """
        hue_tolerance:
            Maximum allowed skin hue deviation (normalized).
        sat_tolerance:
            Maximum allowed saturation change.
        luma_tolerance:
            Maximum allowed luminance deviation.
        """
        self._hue_tolerance = hue_tolerance
        self._sat_tolerance = sat_tolerance
        self._luma_tolerance = luma_tolerance
    def protect(
        self,
        wb_gains: np.ndarray,
        skin_rgb_mean: np.ndarray,
        reference_skin_rgb: np.ndarray,
    ) -> Tuple[np.ndarray, float]:
        """
        Returns protected WB gains and protection strength applied.
        """
        # Normalize inputs
        wb_gains = wb_gains / np.mean(wb_gains)
        # Apply WB to skin
        corrected_skin = skin_rgb_mean * wb_gains
        corrected_skin /= np.max(corrected_skin) + 1e-6
        ref_skin = reference_skin_rgb / (np.max(reference_skin_rgb) + 1e-6)
        # ------------------------------------------------------------------
        # Compute perceptual deltas
        # ------------------------------------------------------------------
        hue_delta = np.linalg.norm(
            corrected_skin[:2] - ref_skin[:2]
        )
        sat_delta = abs(
            np.std(corrected_skin) - np.std(ref_skin)
        )
        luma_delta = abs(
            np.mean(corrected_skin) - np.mean(ref_skin)
        )
        # ------------------------------------------------------------------
        # Determine protection strength
        # ------------------------------------------------------------------
        protection = max(
            hue_delta / self._hue_tolerance,
            sat_delta / self._sat_tolerance,
            luma_delta / self._luma_tolerance,
        )
        protection = np.clip(protection, 0.0, 1.0)
        # ------------------------------------------------------------------
        # Pull WB back toward skin-safe neutral if needed
        # ------------------------------------------------------------------
        if protection > 0.0:
            neutral = np.ones(3, dtype=np.float32)
            wb_gains = (
                wb_gains * (1.0 - protection)
                + neutral * protection
            )
            wb_gains /= np.mean(wb_gains)
        return wb_gains.astype(np.float32), float(protection)
# ==============================================================================
# END OF CHUNK 85 O 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 O 06 — CAMERA AI WHITE BALANCE CONFIDENCE METRIC
# ==============================================================================
#
# Purpose:
#   Quantify how trustworthy the current white-balance decision is,
#   considering illuminant certainty, temporal stability, skin protection
#   pressure, and mixed-light complexity.
#
# Why this matters:
#   - Prevents aggressive WB changes under uncertainty
#   - Gates autonomous overrides and cloud escalation
#   - Provides explainable diagnostics for logs/UI
#
# Cinematic constraints:
#   - Confidence must decay smoothly, never snap
#   - Mixed-light scenes reduce confidence appropriately
#   - Skin protection pressure lowers trust automatically
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIWhiteBalanceConfidenceMetric:
    """
    Computes confidence score for current WB state.
    """
    __slots__ = (
        "_illuminant_weight",
        "_temporal_weight",
        "_skin_weight",
        "_mixed_weight",
    )
    def __init__(
        self,
        illuminant_weight: float = 0.35,
        temporal_weight: float = 0.30,
        skin_weight: float = 0.20,
        mixed_weight: float = 0.15,
    ):
        self._illuminant_weight = illuminant_weight
        self._temporal_weight = temporal_weight
        self._skin_weight = skin_weight
        self._mixed_weight = mixed_weight
    def compute(
        self,
        illuminant_confidence: float,
        temporal_delta: float,
        skin_protection_strength: float,
        mixed_lighting_strength: float,
    ) -> float:
        """
        Returns WB confidence score in range [0, 1].
        """
        # ------------------------------------------------------------------
        # Illuminant certainty
        # ------------------------------------------------------------------
        illum_conf = np.clip(illuminant_confidence, 0.0, 1.0)
        # ------------------------------------------------------------------
        # Temporal stability
        # ------------------------------------------------------------------
        temporal_conf = np.exp(-abs(temporal_delta) * 2.0)
        # ------------------------------------------------------------------
        # Skin protection pressure (more pressure = less confidence)
        # ------------------------------------------------------------------
        skin_conf = 1.0 - np.clip(skin_protection_strength, 0.0, 1.0)
        # ------------------------------------------------------------------
        # Mixed lighting complexity
        # ------------------------------------------------------------------
        mixed_conf = 1.0 - np.clip(mixed_lighting_strength, 0.0, 1.0)
        # ------------------------------------------------------------------
        # Weighted fusion
        # ------------------------------------------------------------------
        confidence = (
            illum_conf * self._illuminant_weight
            + temporal_conf * self._temporal_weight
            + skin_conf * self._skin_weight
            + mixed_conf * self._mixed_weight
        )
        return float(np.clip(confidence, 0.0, 1.0))
# ==============================================================================
# END OF CHUNK 85 O 06
# ==============================================================================
# ==============================================================================
# CHUNK 85 O 07 — CAMERA AI WB OVERRIDE SAFETY GATE
# ==============================================================================
#
# Purpose:
#   Decide whether the camera AI is allowed to apply or update white-balance
#   overrides in the current frame, based on confidence, stability, and
#   perceptual risk.
#
# Why this matters:
#   - Prevents aggressive WB changes during uncertainty
#   - Acts as a hard guardrail before autonomous color intervention
#   - Ensures cinematic continuity across shots
#
# Cinematic constraints:
#   - Overrides only allowed when confidence is high enough
#   - Rapid scene changes temporarily freeze WB
#   - Human skin risk always blocks unsafe overrides
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIWhiteBalanceOverrideSafetyGate:
    """
    Safety gate controlling whether WB overrides may be applied.
    """
    __slots__ = (
        "_min_confidence",
        "_max_temporal_delta",
        "_skin_risk_limit",
        "_cooldown_frames",
        "_cooldown_counter",
    )
    def __init__(
        self,
        min_confidence: float = 0.62,
        max_temporal_delta: float = 0.35,
        skin_risk_limit: float = 0.45,
        cooldown_frames: int = 12,
    ):
        """
        min_confidence:
            Minimum WB confidence required to allow override.
        max_temporal_delta:
            Maximum allowed WB delta EV before freeze.
        skin_risk_limit:
            Protection threshold beyond which overrides are blocked.
        cooldown_frames:
            Frames to hold WB steady after a blocked override.
        """
        self._min_confidence = min_confidence
        self._max_temporal_delta = max_temporal_delta
        self._skin_risk_limit = skin_risk_limit
        self._cooldown_frames = cooldown_frames
        self._cooldown_counter = 0
    def allow_override(
        self,
        wb_confidence: float,
        temporal_delta: float,
        skin_protection_strength: float,
        scene_change_score: float,
    ) -> bool:
        """
        Returns True if WB override is allowed this frame.
        """
        # ------------------------------------------------------------------
        # Cooldown handling
        # ------------------------------------------------------------------
        if self._cooldown_counter > 0:
            self._cooldown_counter -= 1
            return False
        # ------------------------------------------------------------------
        # Confidence gate
        # ------------------------------------------------------------------
        if wb_confidence < self._min_confidence:
            self._cooldown_counter = self._cooldown_frames
            return False
        # ------------------------------------------------------------------
        # Temporal instability gate
        # ------------------------------------------------------------------
        if abs(temporal_delta) > self._max_temporal_delta:
            self._cooldown_counter = self._cooldown_frames
            return False
        # ------------------------------------------------------------------
        # Skin risk gate
        # ------------------------------------------------------------------
        if skin_protection_strength > self._skin_risk_limit:
            self._cooldown_counter = self._cooldown_frames
            return False
        # ------------------------------------------------------------------
        # Scene change gate (hard cut / sudden lighting change)
        # ------------------------------------------------------------------
        if scene_change_score > 0.75:
            self._cooldown_counter = self._cooldown_frames
            return False
        return True
# ==============================================================================
# END OF CHUNK 85 O 07
# ==============================================================================
# ==============================================================================
# CHUNK 85 O 08 — CAMERA AI WB ↔ EXPOSURE COUPLING LOGIC
# ==============================================================================
#
# Purpose:
#   Maintain physical and perceptual consistency between white balance
#   gains and exposure decisions, preventing color shifts from altering
#   scene brightness or clipping behavior.
#
# Why this matters:
#   - WB changes affect channel energy and effective exposure
#   - Uncoupled systems cause highlight clipping after WB shifts
#   - Cinematic cameras treat WB and exposure as a coupled system
#
# Cinematic constraints:
#   - WB must not silently raise exposure
#   - Highlight headroom is preserved across WB changes
#   - Skin luminance stability is prioritized
#
# ==============================================================================

from typing import Tuple
import numpy as np


class CameraAIWBExposureCoupling:
    """
    Couples white balance gains with exposure compensation to preserve
    luminance and highlight headroom.
    """
    __slots__ = (
        "_luma_preservation_strength",
        "_highlight_protection_strength",
    )
    def __init__(
        self,
        luma_preservation_strength: float = 0.75,
        highlight_protection_strength: float = 0.85,
    ):
        """
        luma_preservation_strength:
            Degree to which mean luminance is preserved after WB.
        highlight_protection_strength:
            Degree to which highlight headroom is protected.
        """
        self._luma_preservation_strength = luma_preservation_strength
        self._highlight_protection_strength = highlight_protection_strength
    def couple(
        self,
        wb_gains: np.ndarray,
        exposure_ev: float,
        linear_rgb: np.ndarray,
    ) -> Tuple[np.ndarray, float]:
        """
        Returns adjusted WB gains and exposure EV offset.
        """
        # ------------------------------------------------------------------
        # Compute pre-WB luminance
        # ------------------------------------------------------------------
        luma_pre = (
            0.2126 * linear_rgb[..., 0]
            + 0.7152 * linear_rgb[..., 1]
            + 0.0722 * linear_rgb[..., 2]
        )
        mean_luma_pre = np.mean(luma_pre)
        # ------------------------------------------------------------------
        # Apply WB and recompute luminance
        # ------------------------------------------------------------------
        wb_rgb = linear_rgb * wb_gains.reshape(1, 1, 3)
        luma_post = (
            0.2126 * wb_rgb[..., 0]
            + 0.7152 * wb_rgb[..., 1]
            + 0.0722 * wb_rgb[..., 2]
        )
        mean_luma_post = np.mean(luma_post)
        # ------------------------------------------------------------------
        # Luminance compensation (EV)
        # ------------------------------------------------------------------
        if mean_luma_post > 1e-6:
            luma_ev_delta = np.log2(mean_luma_pre / mean_luma_post)
        else:
            luma_ev_delta = 0.0
        luma_ev_delta *= self._luma_preservation_strength
        # ------------------------------------------------------------------
        # Highlight protection adjustment
        # ------------------------------------------------------------------
        highlight_pre = np.percentile(luma_pre, 99.9)
        highlight_post = np.percentile(luma_post, 99.9)
        highlight_ev_delta = 0.0
        if highlight_post > highlight_pre and highlight_pre > 1e-6:
            highlight_ev_delta = np.log2(highlight_pre / highlight_post)
        highlight_ev_delta *= self._highlight_protection_strength
        # ------------------------------------------------------------------
        # Final exposure compensation
        # ------------------------------------------------------------------
        exposure_adjustment = luma_ev_delta + highlight_ev_delta
        adjusted_exposure = exposure_ev + exposure_adjustment
        return wb_gains.astype(np.float32), float(adjusted_exposure)
# ==============================================================================
# END OF CHUNK 85 O 08
