# ==============================================================================
# CHUNK 85 P 01 — CAMERA AI EXPOSURE INTENT HARMONIZATION
# ==============================================================================
#
# Purpose:
#   Fuse all exposure-relevant signals (scene DR, subject priority,
#   motion, noise, WB coupling, and cinematic intent) into a single,
#   coherent exposure intent expressed in EV.
#
# Why this matters:
#   - Prevents competing subsystems from “fighting” exposure
#   - Enables explainable, stable autonomous exposure
#   - Aligns technical exposure with cinematic goals
#
# Cinematic constraints:
#   - Faces override backgrounds unless explicitly deprioritized
#   - Highlight preservation beats shadow lifting
#   - Intent must change smoothly over time
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIExposureIntentHarmonizer:
    """
    Produces a unified exposure intent (EV) from multiple camera-AI signals.
    """
    __slots__ = (
        "_subject_weight",
        "_scene_weight",
        "_motion_weight",
        "_noise_weight",
        "_wb_coupling_weight",
    )
    def __init__(
        self,
        subject_weight: float = 0.40,
        scene_weight: float = 0.30,
        motion_weight: float = 0.15,
        noise_weight: float = 0.10,
        wb_coupling_weight: float = 0.05,
    ):
        """
        subject_weight:
            Importance of subject (faces/targets) exposure.
        scene_weight:
            Importance of overall scene exposure balance.
        motion_weight:
            Penalizes long exposures under motion.
        noise_weight:
            Penalizes underexposure in noisy conditions.
        wb_coupling_weight:
            Small corrective weight from WB–exposure coupling.
        """
        self._subject_weight = subject_weight
        self._scene_weight = scene_weight
        self._motion_weight = motion_weight
        self._noise_weight = noise_weight
        self._wb_coupling_weight = wb_coupling_weight
    def harmonize(
        self,
        subject_ev: float,
        scene_ev: float,
        motion_metric: float,
        noise_metric: float,
        wb_exposure_offset: float,
        dynamic_range_stops: float,
    ) -> float:
        """
        Returns final exposure intent in EV.
        """
        # ------------------------------------------------------------------
        # Base weighted fusion (subject vs scene)
        # ------------------------------------------------------------------
        base_ev = (
            subject_ev * self._subject_weight
            + scene_ev * self._scene_weight
        )
        # ------------------------------------------------------------------
        # Motion penalty (reduce exposure under fast motion)
        # ------------------------------------------------------------------
        motion_penalty = -np.clip(motion_metric, 0.0, 1.0) * self._motion_weight
        # ------------------------------------------------------------------
        # Noise compensation (slightly lift exposure if noise is high)
        # ------------------------------------------------------------------
        noise_comp = np.clip(noise_metric, 0.0, 1.0) * self._noise_weight
        # ------------------------------------------------------------------
        # WB coupling adjustment (from previous chunk)
        # ------------------------------------------------------------------
        wb_comp = wb_exposure_offset * self._wb_coupling_weight
        # ------------------------------------------------------------------
        # Dynamic range sanity clamp
        # ------------------------------------------------------------------
        # Do not push exposure beyond what DR can support
        dr_limit = np.clip(dynamic_range_stops - 1.0, 4.0, 14.0)
        dr_comp = np.clip(base_ev, -dr_limit, dr_limit)
        # ------------------------------------------------------------------
        # Final exposure intent
        # ------------------------------------------------------------------
        exposure_intent = (
            dr_comp
            + motion_penalty
            + noise_comp
            + wb_comp
        )
        return float(exposure_intent)
# ==============================================================================
# END OF CHUNK 85 P 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 P 02 — CAMERA AI EXPOSURE OVERRIDE AUTHORITY
# ==============================================================================
#
# Purpose:
#   Decide when the camera AI is permitted to override exposure parameters
#   (shutter / ISO / ND intent) based on confidence, safety, and cinematic risk.
#
# Why this matters:
#   - Prevents reckless autonomous exposure changes
#   - Ensures overrides occur only under high confidence
#   - Enables safe cooperation with user or director intent
#
# Cinematic constraints:
#   - Overrides must be conservative and explainable
#   - Highlight safety always dominates
#   - Temporal stability is enforced
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIExposureOverrideAuthority:
    """
    Governs whether exposure overrides are allowed this frame.
    """
    __slots__ = (
        "_min_confidence",
        "_max_ev_step",
        "_highlight_risk_limit",
        "_cooldown_frames",
        "_cooldown_counter",
    )
    def __init__(
        self,
        min_confidence: float = 0.65,
        max_ev_step: float = 0.25,
        highlight_risk_limit: float = 0.40,
        cooldown_frames: int = 10,
    ):
        """
        min_confidence:
            Minimum exposure confidence required to allow override.
        max_ev_step:
            Maximum EV change allowed per decision.
        highlight_risk_limit:
            Threshold beyond which exposure increases are blocked.
        cooldown_frames:
            Frames to wait after a denied override.
        """
        self._min_confidence = min_confidence
        self._max_ev_step = max_ev_step
        self._highlight_risk_limit = highlight_risk_limit
        self._cooldown_frames = cooldown_frames
        self._cooldown_counter = 0
    def allow(
        self,
        exposure_confidence: float,
        requested_ev_delta: float,
        highlight_risk: float,
        scene_change_score: float,
    ) -> float:
        """
        Returns approved EV delta (may be clamped or zeroed).
        """
        # ------------------------------------------------------------------
        # Cooldown handling
        # ------------------------------------------------------------------
        if self._cooldown_counter > 0:
            self._cooldown_counter -= 1
            return 0.0
        # ------------------------------------------------------------------
        # Confidence gate
        # ------------------------------------------------------------------
        if exposure_confidence < self._min_confidence:
            self._cooldown_counter = self._cooldown_frames
            return 0.0
        # ------------------------------------------------------------------
        # Scene volatility gate
        # ------------------------------------------------------------------
        if scene_change_score > 0.70:
            self._cooldown_counter = self._cooldown_frames
            return 0.0
        # ------------------------------------------------------------------
        # Highlight risk gate (blocks exposure increases)
        # ------------------------------------------------------------------
        if highlight_risk > self._highlight_risk_limit and requested_ev_delta > 0.0:
            self._cooldown_counter = self._cooldown_frames
            return 0.0
        # ------------------------------------------------------------------
        # Clamp EV step
        # ------------------------------------------------------------------
        approved_delta = np.clip(
            requested_ev_delta,
            -self._max_ev_step,
            self._max_ev_step,
        )
        return float(approved_delta)
# ==============================================================================
# END OF CHUNK 85 P 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 P 03 — CAMERA AI EXPOSURE TEMPORAL GOVERNOR
# ==============================================================================
#
# Purpose:
#   Enforce temporal smoothness and inertia on exposure intent changes,
#   preventing flicker, pumping, and nervous AI behavior.
#
# Why this matters:
#   - Cinema exposure changes are gradual and motivated
#   - Sudden EV jumps break realism and audience comfort
#   - Temporal coherence preserves perceived dynamic range
#
# Cinematic constraints:
#   - Exposure ramps, never jumps
#   - Faster darkening than brightening (human perception)
#   - Motion and cuts reset inertia
#
# ==============================================================================

import numpy as np


class CameraAIExposureTemporalGovernor:
    """
    Applies temporal smoothing and inertia to exposure intent (EV).
    """
    __slots__ = (
        "_rise_rate",
        "_fall_rate",
        "_max_accel",
        "_prev_ev",
        "_initialized",
    )
    def __init__(
        self,
        rise_rate: float = 0.08,
        fall_rate: float = 0.12,
        max_accel: float = 0.20,
    ):
        """
        rise_rate:
            Max EV/frame when brightening.
        fall_rate:
            Max EV/frame when darkening (faster than rise).
        max_accel:
            Maximum change in rate between frames.
        """
        self._rise_rate = rise_rate
        self._fall_rate = fall_rate
        self._max_accel = max_accel
        self._prev_ev = 0.0
        self._initialized = False
    def reset(self, ev: float):
        """
        Hard reset (scene cut, camera mode change).
        """
        self._prev_ev = ev
        self._initialized = True
    def apply(
        self,
        target_ev: float,
        scene_cut: bool = False,
        motion_spike: bool = False,
    ) -> float:
        """
        Returns temporally governed EV.
        """
        # ------------------------------------------------------------------
        # Initialization or scene cut
        # ------------------------------------------------------------------
        if not self._initialized or scene_cut:
            self.reset(target_ev)
            return float(target_ev)
        # ------------------------------------------------------------------
        # Determine direction
        # ------------------------------------------------------------------
        delta = target_ev - self._prev_ev
        if delta >= 0.0:
            rate = self._rise_rate
        else:
            rate = self._fall_rate
        # ------------------------------------------------------------------
        # Motion spike dampening
        # ------------------------------------------------------------------
        if motion_spike:
            rate *= 0.5
        # ------------------------------------------------------------------
        # Clamp acceleration
        # ------------------------------------------------------------------
        step = np.clip(delta, -rate, rate)
        accel = step - (self._prev_ev - (self._prev_ev - step))
        accel = np.clip(accel, -self._max_accel, self._max_accel)
        new_ev = self._prev_ev + accel
        # ------------------------------------------------------------------
        # Commit
        # ------------------------------------------------------------------
        self._prev_ev = new_ev
        return float(new_ev)
# ==============================================================================
# END OF CHUNK 85 P 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 P 04 — CAMERA AI HIGHLIGHT PROTECTION LOGIC
# ==============================================================================
#
# Purpose:
#   Prevent irreversible highlight clipping while preserving
#   perceived brightness and cinematic contrast.
#
# Core principles:
#   - Highlights are more fragile than shadows
#   - Clipping is irreversible and non-cinematic
#   - Protection must be perceptual, not purely numeric
#
# Strategy:
#   - Predict highlight headroom in linear scene-referred space
#   - Apply soft roll-off guidance to exposure intent
#   - Bias protection based on subject importance and motion
#
# ==============================================================================

import numpy as np


class CameraAIHighlightProtector:
    """
    Computes highlight risk and applies exposure bias to protect roll-off.
    """
    __slots__ = (
        "_white_point",
        "_soft_knee",
        "_max_bias_ev",
    )
    def __init__(
        self,
        white_point: float = 1.0,
        soft_knee: float = 0.85,
        max_bias_ev: float = 1.2,
    ):
        """
        white_point:
            Normalized linear white (scene-referred).
        soft_knee:
            Fraction of white where highlight compression begins.
        max_bias_ev:
            Maximum negative EV bias allowed for highlight protection.
        """
        self._white_point = float(white_point)
        self._soft_knee = float(soft_knee)
        self._max_bias_ev = float(max_bias_ev)
    def evaluate_risk(
        self,
        linear_luma: np.ndarray,
    ) -> float:
        """
        Returns highlight risk score in [0, 1].
        """
        # Robust percentile avoids specular outliers
        p99 = np.percentile(linear_luma, 99.0)
        knee_point = self._white_point * self._soft_knee
        if p99 <= knee_point:
            return 0.0
        risk = (p99 - knee_point) / max(
            self._white_point - knee_point, 1e-6
        )
        return float(np.clip(risk, 0.0, 1.0))
    def compute_exposure_bias(
        self,
        highlight_risk: float,
        subject_priority: float,
        motion_energy: float,
    ) -> float:
        """
        Computes EV bias (negative) to protect highlights.
        subject_priority:
            >1.0 if subject is highlight-critical (faces, skies).
        """
        # Motion reduces aggressive bias (avoid flicker)
        motion_factor = 1.0 / (1.0 + motion_energy)
        # Priority increases protection strength
        strength = highlight_risk * subject_priority * motion_factor
        bias = -strength * self._max_bias_ev
        return float(np.clip(bias, -self._max_bias_ev, 0.0))
    def apply(
        self,
        target_ev: float,
        linear_luma: np.ndarray,
        subject_priority: float = 1.0,
        motion_energy: float = 0.0,
    ) -> float:
        """
        Returns highlight-protected EV.
        """
        risk = self.evaluate_risk(linear_luma)
        if risk <= 0.0:
            return float(target_ev)
        bias = self.compute_exposure_bias(
            risk,
            subject_priority,
            motion_energy,
        )
        return float(target_ev + bias)
# ==============================================================================
# END OF CHUNK 85 P 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 P 05 — CAMERA AI SHADOW PRESERVATION LOGIC
# ==============================================================================
#
# Purpose:
#   Preserve shadow detail and prevent crush while maintaining
#   cinematic contrast and noise discipline.
#
# Core principles:
#   - Shadows carry texture and mood
#   - Lifting shadows blindly increases noise and breaks realism
#   - Protection must be content-aware and exposure-aware
#
# Strategy:
#   - Estimate shadow headroom in scene-linear space
#   - Modulate exposure intent with soft lift (never hard)
#   - Coordinate with ISO/noise tradeoff (next chunks)
#
# ==============================================================================

import numpy as np


class CameraAIShadowPreserver:
    """
    Computes shadow risk and applies controlled EV lift
    without inducing noise or flattening contrast.
    """
    __slots__ = (
        "_black_point",
        "_soft_toe",
        "_max_lift_ev",
    )
    def __init__(
        self,
        black_point: float = 0.0,
        soft_toe: float = 0.06,
        max_lift_ev: float = 0.9,
    ):
        """
        black_point:
            Scene-linear black reference.
        soft_toe:
            Fraction above black where shadow compression begins.
        max_lift_ev:
            Maximum positive EV lift allowed.
        """
        self._black_point = float(black_point)
        self._soft_toe = float(soft_toe)
        self._max_lift_ev = float(max_lift_ev)
    def evaluate_risk(
        self,
        linear_luma: np.ndarray,
    ) -> float:
        """
        Returns shadow risk score in [0, 1].
        """
        # Use low percentile to detect shadow starvation
        p05 = np.percentile(linear_luma, 5.0)
        toe_point = self._black_point + self._soft_toe
        if p05 >= toe_point:
            return 0.0
        risk = (toe_point - p05) / max(toe_point, 1e-6)
        return float(np.clip(risk, 0.0, 1.0))
    def compute_exposure_lift(
        self,
        shadow_risk: float,
        subject_priority: float,
        motion_energy: float,
    ) -> float:
        """
        Computes EV lift (positive) to preserve shadow detail.
        subject_priority:
            >1.0 if shadows contain critical detail (faces, wardrobe).
        """
        # Motion discourages aggressive lifting (noise visibility)
        motion_factor = 1.0 / (1.0 + 1.5 * motion_energy)
        strength = shadow_risk * subject_priority * motion_factor
        lift = strength * self._max_lift_ev
        return float(np.clip(lift, 0.0, self._max_lift_ev))
    def apply(
        self,
        target_ev: float,
        linear_luma: np.ndarray,
        subject_priority: float = 1.0,
        motion_energy: float = 0.0,
    ) -> float:
        """
        Returns shadow-preserved EV.
        """
        risk = self.evaluate_risk(linear_luma)
        if risk <= 0.0:
            return float(target_ev)
        lift = self.compute_exposure_lift(
            risk,
            subject_priority,
            motion_energy,
        )
        return float(target_ev + lift)
# ==============================================================================
# END OF CHUNK 85 P 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 P 06 — CAMERA AI EXPOSURE CONFIDENCE GATE
# ==============================================================================
#
# Purpose:
#   Quantify confidence in exposure intent before allowing it
#   to influence camera parameters (shutter / ISO / ND).
#
# Why this matters:
#   - AI perception can be uncertain (occlusion, flare, motion blur)
#   - Low-confidence exposure changes cause visible instability
#   - Cinema cameras only act when confidence is high
#
# Strategy:
#   - Aggregate multiple confidence signals:
#       * Luma stability
#       * Motion consistency
#       * Subject lock certainty
#       * Temporal agreement
#   - Gate exposure updates when confidence < threshold
#
# ==============================================================================

import numpy as np
from typing import Dict


class CameraAIExposureConfidenceGate:
    """
    Computes a scalar confidence score for exposure decisions
    and determines whether updates are allowed.
    """
    __slots__ = (
        "_min_confidence",
        "_temporal_weight",
        "_motion_weight",
        "_subject_weight",
        "_luma_weight",
        "_prev_confidence",
    )
    def __init__(
        self,
        min_confidence: float = 0.55,
        temporal_weight: float = 0.35,
        motion_weight: float = 0.20,
        subject_weight: float = 0.25,
        luma_weight: float = 0.20,
    ):
        """
        min_confidence:
            Minimum confidence required to apply exposure changes.
        Weights:
            Must sum to ~1.0.
        """
        self._min_confidence = float(min_confidence)
        self._temporal_weight = float(temporal_weight)
        self._motion_weight = float(motion_weight)
        self._subject_weight = float(subject_weight)
        self._luma_weight = float(luma_weight)
        self._prev_confidence = 1.0
    def _temporal_confidence(
        self,
        ev_history: np.ndarray,
    ) -> float:
        """
        Measures agreement of exposure intent over time.
        """
        if ev_history.size < 3:
            return 1.0
        variance = float(np.var(ev_history[-5:]))
        return float(np.exp(-variance * 4.0))
    def _motion_confidence(
        self,
        motion_energy: float,
    ) -> float:
        """
        High motion reduces certainty of exposure analysis.
        """
        return float(1.0 / (1.0 + motion_energy))
    def _subject_confidence(
        self,
        subject_lock_score: float,
    ) -> float:
        """
        Confidence that the intended subject is correctly identified.
        """
        return float(np.clip(subject_lock_score, 0.0, 1.0))
    def _luma_confidence(
        self,
        luma_histogram: np.ndarray,
    ) -> float:
        """
        Confidence based on histogram stability.
        """
        if luma_histogram.size == 0:
            return 0.0
        entropy = -np.sum(
            luma_histogram * np.log2(luma_histogram + 1e-9)
        )
        # High entropy = stable tonal distribution
        return float(np.clip(entropy / 6.0, 0.0, 1.0))
    def compute(
        self,
        ev_history: np.ndarray,
        motion_energy: float,
        subject_lock_score: float,
        luma_histogram: np.ndarray,
    ) -> float:
        """
        Returns confidence score in [0, 1].
        """
        c_temporal = self._temporal_confidence(ev_history)
        c_motion = self._motion_confidence(motion_energy)
        c_subject = self._subject_confidence(subject_lock_score)
        c_luma = self._luma_confidence(luma_histogram)
        confidence = (
            c_temporal * self._temporal_weight
            + c_motion * self._motion_weight
            + c_subject * self._subject_weight
            + c_luma * self._luma_weight
        )
        # Temporal smoothing to avoid flicker in gating
        confidence = 0.7 * self._prev_confidence + 0.3 * confidence
        self._prev_confidence = confidence
        return float(np.clip(confidence, 0.0, 1.0))
    def allow_update(self, confidence: float) -> bool:
        """
        Returns True if exposure update is allowed.
        """
        return bool(confidence >= self._min_confidence)
# ==============================================================================
# END OF CHUNK 85 P 06
# ==============================================================================
# ==============================================================================
# CHUNK 85 P 07 — CAMERA AI EXPOSURE ↔ MOTION COUPLING
# ==============================================================================
#
# Purpose:
#   Couple exposure behavior directly to camera and scene motion
#   to prevent motion blur artifacts, exposure pumping, and
#   non-cinematic shutter behavior.
#
# Cinematic rationale:
#   - Motion defines acceptable shutter speed boundaries
#   - High motion demands exposure stability over brightness
#   - Low motion allows expressive exposure shaping
#
# Strategy:
#   - Compute motion-adaptive exposure damping
#   - Bias exposure decisions toward shutter discipline
#   - Enforce cinematic shutter angle equivalents
#
# ==============================================================================

import numpy as np


class CameraAIExposureMotionCoupler:
    """
    Couples exposure intent with motion metrics to preserve
    cinematic motion rendering.
    """
    __slots__ = (
        "_base_shutter_angle",
        "_max_shutter_angle",
        "_min_shutter_angle",
        "_motion_ref",
    )
    def __init__(
        self,
        base_shutter_angle: float = 180.0,
        max_shutter_angle: float = 220.0,
        min_shutter_angle: float = 90.0,
        motion_ref: float = 1.0,
    ):
        """
        base_shutter_angle:
            Nominal cinematic shutter angle.
        max_shutter_angle:
            Upper bound (slow motion / low motion scenes).
        min_shutter_angle:
            Lower bound (fast motion scenes).
        motion_ref:
            Motion energy reference for normalization.
        """
        self._base_shutter_angle = float(base_shutter_angle)
        self._max_shutter_angle = float(max_shutter_angle)
        self._min_shutter_angle = float(min_shutter_angle)
        self._motion_ref = float(motion_ref)
    def compute_motion_factor(
        self,
        motion_energy: float,
    ) -> float:
        """
        Returns normalized motion factor in [0, 1].
        """
        return float(
            np.clip(motion_energy / self._motion_ref, 0.0, 1.0)
        )
    def recommend_shutter_angle(
        self,
        motion_energy: float,
    ) -> float:
        """
        Computes motion-adaptive shutter angle.
        """
        m = self.compute_motion_factor(motion_energy)
        # High motion → smaller shutter angle
        angle = (
            self._base_shutter_angle * (1.0 - m)
            + self._min_shutter_angle * m
        )
        return float(
            np.clip(
                angle,
                self._min_shutter_angle,
                self._max_shutter_angle,
            )
        )
    def dampen_exposure_delta(
        self,
        exposure_delta_ev: float,
        motion_energy: float,
    ) -> float:
        """
        Reduces exposure changes under high motion to avoid flicker.
        """
        m = self.compute_motion_factor(motion_energy)
        damping = 1.0 / (1.0 + 2.0 * m)
        return float(exposure_delta_ev * damping)
    def apply(
        self,
        target_ev: float,
        prev_ev: float,
        motion_energy: float,
    ) -> float:
        """
        Returns motion-aware EV.
        """
        delta = target_ev - prev_ev
        delta = self.dampen_exposure_delta(delta, motion_energy)
        return float(prev_ev + delta)
# ==============================================================================
# END OF CHUNK 85 P 07
# ==============================================================================
# ==============================================================================
# CHUNK 85 P 08 — CAMERA AI EXPOSURE ↔ ISO NOISE TRADEOFF
# ==============================================================================
#
# Purpose:
#   Balance exposure intent against ISO-induced noise,
#   preserving cinematic texture without plasticity.
#
# Cinematic rationale:
#   - ISO noise is more objectionable than controlled underexposure
#   - Grain should be intentional, not sensor-driven
#   - Prefer shutter/ND/exposure bias before ISO escalation
#
# Strategy:
#   - Predict noise growth as a function of ISO
#   - Penalize ISO increases non-linearly
#   - Gate ISO jumps based on motion and subject priority
#
# ==============================================================================

import numpy as np


class CameraAIExposureISONoiseTradeoff:
    """
    Computes ISO recommendations that respect cinematic noise limits.
    """
    __slots__ = (
        "_base_iso",
        "_max_iso",
        "_noise_ref_iso",
        "_noise_growth",
    )
    def __init__(
        self,
        base_iso: int = 100,
        max_iso: int = 3200,
        noise_ref_iso: int = 800,
        noise_growth: float = 1.6,
    ):
        """
        base_iso:
            Native sensor ISO (minimum noise).
        max_iso:
            Hard ceiling for ISO escalation.
        noise_ref_iso:
            ISO where noise becomes clearly visible.
        noise_growth:
            Exponential noise growth factor.
        """
        self._base_iso = int(base_iso)
        self._max_iso = int(max_iso)
        self._noise_ref_iso = int(noise_ref_iso)
        self._noise_growth = float(noise_growth)
    def estimate_noise_penalty(
        self,
        iso: int,
    ) -> float:
        """
        Returns normalized noise penalty in [0, 1+].
        """
        if iso <= self._noise_ref_iso:
            return 0.0
        ratio = iso / float(self._noise_ref_iso)
        penalty = np.power(ratio, self._noise_growth) - 1.0
        return float(max(penalty, 0.0))
    def recommend_iso(
        self,
        target_ev_delta: float,
        current_iso: int,
        motion_energy: float,
        subject_priority: float = 1.0,
    ) -> int:
        """
        Computes ISO adjustment respecting noise discipline.
        target_ev_delta:
            Positive EV means scene too dark.
        """
        # If no positive EV deficit, never raise ISO
        if target_ev_delta <= 0.0:
            return int(current_iso)
        # Motion discourages ISO jumps (noise more visible)
        motion_penalty = 1.0 + 1.5 * motion_energy
        # Subject priority allows some flexibility
        priority_factor = max(subject_priority, 0.5)
        # Proposed ISO increase (log2 relationship)
        iso_step = np.power(2.0, target_ev_delta)
        proposed_iso = int(current_iso * iso_step)
        proposed_iso = min(proposed_iso, self._max_iso)
        # Noise-based rejection
        noise_penalty = self.estimate_noise_penalty(proposed_iso)
        acceptance = priority_factor / (1.0 + noise_penalty * motion_penalty)
        if acceptance < 0.5:
            # Reject ISO increase; hold current
            return int(current_iso)
        return int(proposed_iso)
