# ==============================================================================
# CHUNK 85 P 09 — CAMERA AI EXPOSURE FAILURE RECOVERY
# ==============================================================================
#
# Purpose:
#   Detect exposure system failure modes and recover gracefully
#   without visible artifacts, freezes, or abrupt jumps.
#
# Failure modes addressed:
#   - Oscillation / hunting
#   - Confidence collapse
#   - Latency-induced stale decisions
#   - Sensor saturation or blackout
#
# Cinematic requirement:
#   Recovery must be invisible. The audience should never
#   notice that the AI "panicked".
#
# Strategy:
#   - Monitor exposure stability metrics
#   - Enter controlled fallback states
#   - Gradually re-enter autonomous control
#
# ==============================================================================

import time
import numpy as np
from typing import Optional


class CameraAIExposureFailureRecovery:
    """
    Supervises exposure control and recovers from failure modes.
    """
    __slots__ = (
        "_last_good_ev",
        "_last_update_ts",
        "_freeze_timeout",
        "_oscillation_threshold",
        "_confidence_floor",
        "_in_recovery",
    )
    def __init__(
        self,
        freeze_timeout: float = 0.40,
        oscillation_threshold: float = 0.35,
        confidence_floor: float = 0.30,
    ):
        """
        freeze_timeout:
            Seconds without stable update before recovery triggers.
        oscillation_threshold:
            EV variance threshold indicating hunting.
        confidence_floor:
            Minimum confidence before forced stabilization.
        """
        self._freeze_timeout = float(freeze_timeout)
        self._oscillation_threshold = float(oscillation_threshold)
        self._confidence_floor = float(confidence_floor)
        self._last_good_ev: Optional[float] = None
        self._last_update_ts: float = time.monotonic()
        self._in_recovery: bool = False
    def _detect_freeze(self) -> bool:
        """
        Detects stalled exposure updates.
        """
        dt = time.monotonic() - self._last_update_ts
        return bool(dt > self._freeze_timeout)
    def _detect_oscillation(
        self,
        ev_history: np.ndarray,
    ) -> bool:
        """
        Detects exposure hunting via variance.
        """
        if ev_history.size < 5:
            return False
        var = float(np.var(ev_history[-6:]))
        return bool(var > self._oscillation_threshold)
    def update_good_state(
        self,
        ev: float,
        confidence: float,
    ):
        """
        Stores last known good exposure state.
        """
        if confidence >= self._confidence_floor:
            self._last_good_ev = float(ev)
            self._last_update_ts = time.monotonic()
            self._in_recovery = False
    def evaluate(
        self,
        proposed_ev: float,
        ev_history: np.ndarray,
        confidence: float,
    ) -> float:
        """
        Returns safe EV, engaging recovery if needed.
        """
        freeze = self._detect_freeze()
        oscillation = self._detect_oscillation(ev_history)
        low_conf = confidence < self._confidence_floor
        if freeze or oscillation or low_conf:
            self._in_recovery = True
            # If we have a known good state, gently return to it
            if self._last_good_ev is not None:
                return float(self._last_good_ev)
            # Absolute fallback: hold last EV in history
            if ev_history.size > 0:
                return float(ev_history[-1])
            # Final safety: accept proposed EV (no better option)
            return float(proposed_ev)
        # Normal operation
        self._last_update_ts = time.monotonic()
        return float(proposed_ev)
    def in_recovery(self) -> bool:
        """
        Returns True if system is currently stabilizing.
        """
        return bool(self._in_recovery)
# ==============================================================================
# END OF CHUNK 85 P 09
# ==============================================================================
# ==============================================================================
# CHUNK 85 P 10 — CAMERA AI EXPOSURE FINAL ARBITRATION
# ==============================================================================
#
# Purpose:
#   Fuse all exposure-related decisions into a single,
#   authoritative exposure intent that is safe, cinematic,
#   and temporally coherent.
#
# Inputs converged:
#   - Raw exposure intent (EV)
#   - Temporal governor output
#   - Highlight protection bias
#   - Shadow preservation lift
#   - Motion coupling dampening
#   - ISO noise discipline
#   - Confidence gate
#   - Failure recovery override
#
# Cinematic requirement:
#   There must be ONE final authority.
#   No conflicting AI subsystems are allowed downstream.
#
# ==============================================================================

from typing import Optional


class CameraAIExposureFinalArbitrator:
    """
    Produces the final exposure EV used by camera control.
    """
    __slots__ = (
        "_prev_final_ev",
        "_max_step_ev",
    )
    def __init__(
        self,
        max_step_ev: float = 0.25,
    ):
        """
        max_step_ev:
            Absolute EV change limit per frame for final output.
        """
        self._max_step_ev = float(max_step_ev)
        self._prev_final_ev: Optional[float] = None
    def _limit_step(
        self,
        prev_ev: float,
        new_ev: float,
    ) -> float:
        """
        Enforces hard EV step limits.
        """
        delta = new_ev - prev_ev
        if delta > self._max_step_ev:
            return prev_ev + self._max_step_ev
        if delta < -self._max_step_ev:
            return prev_ev - self._max_step_ev
        return new_ev
    def arbitrate(
        self,
        proposed_ev: float,
        confidence_ok: bool,
        recovery_ev: Optional[float] = None,
    ) -> float:
        """
        Returns final EV after arbitration.
        precedence order:
            1. Failure recovery override
            2. Confidence gating
            3. Step-limited convergence
        """
        # ------------------------------------------------------------------
        # Failure recovery has absolute priority
        # ------------------------------------------------------------------
        if recovery_ev is not None:
            final_ev = float(recovery_ev)
        else:
            # ------------------------------------------------------------------
            # Confidence gate
            # ------------------------------------------------------------------
            if not confidence_ok and self._prev_final_ev is not None:
                final_ev = float(self._prev_final_ev)
            else:
                final_ev = float(proposed_ev)
        # ------------------------------------------------------------------
        # Step limiting
        # ------------------------------------------------------------------
        if self._prev_final_ev is not None:
            final_ev = self._limit_step(self._prev_final_ev, final_ev)
        self._prev_final_ev = final_ev
        return final_ev
# ==============================================================================
# END OF CHUNK 85 P 10
# ==============================================================================
# ==============================================================================
# CHUNK 85 Q 01 — CAMERA AI DUAL-CAMERA EXPOSURE UNIFICATION
# ==============================================================================
#
# Purpose:
#   Unify exposure intelligence between:
#     - Internal reference camera (gyro / low-latency)
#     - External GoPro Hero camera (primary image quality)
#
# Why this matters:
#   - Internal camera sees motion first (lower latency)
#   - GoPro provides final pixels (higher latency, higher DR)
#   - Exposure decisions must be coherent across both
#
# Cinematic requirement:
#   The audience must perceive ONE camera, not two disagreeing systems.
#
# Strategy:
#   - Normalize both cameras into scene-referred EV space
#   - Weight decisions by latency, DR, and confidence
#   - Produce a single unified exposure intent
#
# ==============================================================================

import numpy as np
from typing import Dict


class CameraAIDualExposureUnifier:
    """
    Fuses exposure intent from internal and external cameras.
    """
    __slots__ = (
        "_internal_weight",
        "_external_weight",
        "_latency_bias",
    )
    def __init__(
        self,
        internal_weight: float = 0.45,
        external_weight: float = 0.55,
        latency_bias: float = 0.15,
    ):
        """
        internal_weight:
            Baseline trust in internal camera exposure.
        external_weight:
            Baseline trust in GoPro exposure.
        latency_bias:
            Extra weight granted to lower-latency source.
        """
        self._internal_weight = float(internal_weight)
        self._external_weight = float(external_weight)
        self._latency_bias = float(latency_bias)
    def _normalize_weights(
        self,
        wi: float,
        we: float,
    ) -> Dict[str, float]:
        total = wi + we
        if total <= 0.0:
            return {"internal": 0.5, "external": 0.5}
        return {
            "internal": wi / total,
            "external": we / total,
        }
    def unify(
        self,
        internal_ev: float,
        external_ev: float,
        internal_confidence: float,
        external_confidence: float,
        internal_latency_ms: float,
        external_latency_ms: float,
    ) -> float:
        """
        Returns unified exposure EV.
        """
        # ------------------------------------------------------------------
        # Latency-aware weighting
        # ------------------------------------------------------------------
        latency_advantage = (
            external_latency_ms - internal_latency_ms
        ) / max(external_latency_ms, 1.0)
        latency_factor = np.clip(latency_advantage, -1.0, 1.0)
        wi = (
            self._internal_weight
            + latency_factor * self._latency_bias
        ) * internal_confidence
        we = (
            self._external_weight
            - latency_factor * self._latency_bias
        ) * external_confidence
        weights = self._normalize_weights(wi, we)
        # ------------------------------------------------------------------
        # Unified exposure
        # ------------------------------------------------------------------
        unified_ev = (
            internal_ev * weights["internal"]
            + external_ev * weights["external"]
        )
        return float(unified_ev)
# ==============================================================================
# END OF CHUNK 85 Q 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 Q 02 — CAMERA AI DUAL-CAMERA TEMPORAL SYNC
# ==============================================================================
#
# Purpose:
#   Temporally align internal camera frames and GoPro frames
#   so that AI decisions operate on the same *moment in time*,
#   despite different capture pipelines and latencies.
#
# Why this matters:
#   - Internal camera is low-latency but lower quality
#   - GoPro is high-quality but high-latency
#   - Unsynced frames cause exposure oscillation and framing drift
#
# Cinematic requirement:
#   Temporal coherence must be maintained even when
#   frame rates, codecs, and pipelines differ.
#
# Strategy:
#   - Track monotonic timestamps from both cameras
#   - Estimate and continuously refine latency offset
#   - Interpolate or delay internal camera state as needed
#
# ==============================================================================

import time
import numpy as np
from typing import Optional


class CameraAIDualTemporalSync:
    """
    Aligns internal and external camera streams in time.
    """
    __slots__ = (
        "_latency_offset_ms",
        "_alpha",
        "_initialized",
    )
    def __init__(
        self,
        initial_offset_ms: float = 0.0,
        smoothing_alpha: float = 0.08,
    ):
        """
        initial_offset_ms:
            Initial guess of external-internal latency offset.
        smoothing_alpha:
            EMA smoothing factor for offset refinement.
        """
        self._latency_offset_ms = float(initial_offset_ms)
        self._alpha = float(smoothing_alpha)
        self._initialized = False
    def update(
        self,
        internal_ts_mono: float,
        external_ts_mono: float,
    ):
        """
        Updates latency offset estimate using paired frames.
        """
        observed_offset = (
            external_ts_mono - internal_ts_mono
        ) * 1000.0
        if not self._initialized:
            self._latency_offset_ms = observed_offset
            self._initialized = True
            return
        # Exponential moving average to avoid jitter
        self._latency_offset_ms = (
            (1.0 - self._alpha) * self._latency_offset_ms
            + self._alpha * observed_offset
        )
    def align_internal_timestamp(
        self,
        internal_ts_mono: float,
    ) -> float:
        """
        Returns internal timestamp shifted forward
        to match external camera timebase.
        """
        return float(
            internal_ts_mono + self._latency_offset_ms / 1000.0
        )
    def get_latency_offset_ms(self) -> float:
        """
        Returns current latency offset estimate.
        """
        return float(self._latency_offset_ms)
# ==============================================================================
# END OF CHUNK 85 Q 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 Q 03 — CAMERA AI DUAL-CAMERA CONFIDENCE FUSION
# ==============================================================================
#
# Purpose:
#   Fuse confidence signals from internal reference camera and GoPro
#   to produce a single, stable confidence vector for AI decisions.
#
# Why this matters:
#   - Internal camera: low latency, lower fidelity
#   - GoPro: high fidelity, higher latency, compression artifacts
#   - Each camera fails differently under motion, light, or noise
#
# Cinematic requirement:
#   AI decisions (exposure, framing, WB, motion intent) must be driven
#   by the *most trustworthy* source at each moment, without hard switches.
#
# Strategy:
#   - Compute per-camera confidence vectors
#   - Weight them dynamically using reliability heuristics
#   - Produce a normalized fused confidence output
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIDualConfidenceFusion:
    """
    Fuses confidence metrics from internal and external cameras.
    """
    __slots__ = (
        "_min_confidence",
        "_latency_penalty_scale",
    )
    def __init__(
        self,
        min_confidence: float = 0.05,
        latency_penalty_scale: float = 0.15,
    ):
        """
        min_confidence:
            Lower bound to avoid zero-weight collapse.
        latency_penalty_scale:
            Penalizes high-latency camera confidence.
        """
        self._min_confidence = float(min_confidence)
        self._latency_penalty_scale = float(latency_penalty_scale)
    def fuse(
        self,
        internal_conf: Dict[str, float],
        external_conf: Dict[str, float],
        external_latency_ms: float,
    ) -> Dict[str, float]:
        """
        Returns fused confidence dictionary.
        """
        # ------------------------------------------------------------------
        # Convert to aligned vectors
        # ------------------------------------------------------------------
        keys = sorted(
            set(internal_conf.keys()) | set(external_conf.keys())
        )
        int_vec = np.array(
            [internal_conf.get(k, 0.0) for k in keys],
            dtype=np.float32,
        )
        ext_vec = np.array(
            [external_conf.get(k, 0.0) for k in keys],
            dtype=np.float32,
        )
        # ------------------------------------------------------------------
        # Latency-based reliability weighting
        # ------------------------------------------------------------------
        latency_penalty = np.exp(
            -self._latency_penalty_scale * max(external_latency_ms, 0.0)
        )
        int_weight = 1.0
        ext_weight = float(latency_penalty)
        # ------------------------------------------------------------------
        # Apply minimum confidence floor
        # ------------------------------------------------------------------
        int_vec = np.maximum(int_vec, self._min_confidence)
        ext_vec = np.maximum(ext_vec, self._min_confidence)
        # ------------------------------------------------------------------
        # Weighted fusion
        # ------------------------------------------------------------------
        fused = (
            int_weight * int_vec + ext_weight * ext_vec
        ) / (int_weight + ext_weight)
        # Normalize to [0, 1] range
        fused = np.clip(fused, 0.0, 1.0)
        return {
            key: float(fused[i])
            for i, key in enumerate(keys)
        }
# ==============================================================================
# END OF CHUNK 85 Q 03
