# ==============================================================================
# CHUNK 85 Q 04 — CAMERA AI CROSS-CAMERA FAILURE HANDLING
# ==============================================================================
#
# Purpose:
#   Detect, classify, and mitigate failure modes across internal and external
#   cameras without abrupt behavior changes.
#
# Failure classes handled:
#   - Signal loss / frame stall
#   - Exposure collapse (clipping / blackout)
#   - Motion corruption (rolling shutter / vibration smear)
#   - Metadata desync (timestamps / gyro mismatch)
#
# Design goals:
#   - Zero hard cutovers
#   - Confidence-weighted degradation
#   - Fast recovery with hysteresis
#
# ==============================================================================

from typing import Dict, Tuple
import numpy as np
import time


class CameraAICrossFailureHandler:
    """
    Cross-camera failure detection and mitigation layer.
    """
    __slots__ = (
        "_stall_timeout_ms",
        "_clip_threshold",
        "_motion_var_threshold",
        "_hysteresis_frames",
        "_last_ok_ts_internal",
        "_last_ok_ts_external",
        "_fail_state_internal",
        "_fail_state_external",
        "_recovery_counter_internal",
        "_recovery_counter_external",
    )
    def __init__(
        self,
        stall_timeout_ms: float = 120.0,
        clip_threshold: float = 0.985,
        motion_var_threshold: float = 0.65,
        hysteresis_frames: int = 6,
    ):
        self._stall_timeout_ms = float(stall_timeout_ms)
        self._clip_threshold = float(clip_threshold)
        self._motion_var_threshold = float(motion_var_threshold)
        self._hysteresis_frames = int(hysteresis_frames)
        now = time.time() * 1000.0
        self._last_ok_ts_internal = now
        self._last_ok_ts_external = now
        self._fail_state_internal = False
        self._fail_state_external = False
        self._recovery_counter_internal = 0
        self._recovery_counter_external = 0
    # ------------------------------------------------------------------
    # Failure detection primitives
    # ------------------------------------------------------------------
    def _detect_stall(self, last_ok_ms: float, now_ms: float) -> bool:
        return (now_ms - last_ok_ms) > self._stall_timeout_ms
    def _detect_exposure_collapse(
        self,
        luma_hist: np.ndarray,
    ) -> bool:
        if luma_hist.size == 0:
            return True
        clipped_ratio = luma_hist[-1]
        return clipped_ratio > self._clip_threshold
    def _detect_motion_corruption(
        self,
        gyro_variance: float,
    ) -> bool:
        return gyro_variance > self._motion_var_threshold
    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def evaluate_camera(
        self,
        camera_id: str,
        luma_hist: np.ndarray,
        gyro_variance: float,
        frame_ok: bool,
        timestamp_ms: float,
    ) -> Dict[str, float]:
        """
        Returns per-camera failure diagnostics and severity.
        """
        now_ms = timestamp_ms
        if camera_id == "internal":
            last_ok = self._last_ok_ts_internal
        else:
            last_ok = self._last_ok_ts_external
        stall = self._detect_stall(last_ok, now_ms)
        exposure_fail = self._detect_exposure_collapse(luma_hist)
        motion_fail = self._detect_motion_corruption(gyro_variance)
        hard_fail = stall or (not frame_ok)
        soft_fail = exposure_fail or motion_fail
        severity = 0.0
        if hard_fail:
            severity = 1.0
        elif soft_fail:
            severity = 0.5
        return {
            "stall": float(stall),
            "exposure": float(exposure_fail),
            "motion": float(motion_fail),
            "severity": float(severity),
        }
    def update_state(
        self,
        camera_id: str,
        diagnostics: Dict[str, float],
        timestamp_ms: float,
    ) -> Tuple[bool, float]:
        """
        Updates failure state with hysteresis.
        Returns (is_failed, reliability_multiplier).
        """
        severity = diagnostics["severity"]
        if camera_id == "internal":
            fail_state = self._fail_state_internal
            recovery_counter = self._recovery_counter_internal
        else:
            fail_state = self._fail_state_external
            recovery_counter = self._recovery_counter_external
        if severity >= 1.0:
            fail_state = True
            recovery_counter = 0
        elif severity == 0.0:
            if fail_state:
                recovery_counter += 1
                if recovery_counter >= self._hysteresis_frames:
                    fail_state = False
                    recovery_counter = 0
        else:
            recovery_counter = 0
        if camera_id == "internal":
            self._fail_state_internal = fail_state
            self._recovery_counter_internal = recovery_counter
            if not fail_state:
                self._last_ok_ts_internal = timestamp_ms
        else:
            self._fail_state_external = fail_state
            self._recovery_counter_external = recovery_counter
            if not fail_state:
                self._last_ok_ts_external = timestamp_ms
        reliability = 0.0 if fail_state else (1.0 - 0.5 * severity)
        return fail_state, float(np.clip(reliability, 0.0, 1.0))
# ==============================================================================
# END OF CHUNK 85 Q 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 Q 05 — CAMERA AI CROSS-CAMERA PRIORITY ARBITRATION
# ==============================================================================
#
# Purpose:
#   Resolve competing camera intents (internal vs GoPro) into a single
#   authoritative decision stream for exposure, framing, and stabilization.
#
# Core principle:
#   Priority is NOT static. It is computed per-frame using:
#     - Confidence fusion output
#     - Failure reliability multipliers
#     - Scene-dependent weighting (motion vs fidelity)
#
# This prevents:
#   - Internal cam dominating when fidelity matters
#   - GoPro dominating when latency or corruption matters
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIPriorityArbitrator:
    """
    Computes dynamic priority weights between cameras.
    """
    __slots__ = (
        "_motion_bias",
        "_fidelity_bias",
    )
    def __init__(
        self,
        motion_bias: float = 0.6,
        fidelity_bias: float = 0.4,
    ):
        """
        motion_bias:
            Weight favoring low-latency internal camera under motion.
        fidelity_bias:
            Weight favoring high-fidelity external camera when stable.
        """
        self._motion_bias = float(motion_bias)
        self._fidelity_bias = float(fidelity_bias)
    def arbitrate(
        self,
        fused_confidence: Dict[str, float],
        reliability_internal: float,
        reliability_external: float,
        motion_level: float,
    ) -> Dict[str, float]:
        """
        Returns normalized priority weights for each camera.
        """
        # ------------------------------------------------------------------
        # Motion-adaptive weighting
        # ------------------------------------------------------------------
        motion_level = float(np.clip(motion_level, 0.0, 1.0))
        internal_base = self._motion_bias * motion_level
        external_base = self._fidelity_bias * (1.0 - motion_level)
        # ------------------------------------------------------------------
        # Apply reliability multipliers
        # ------------------------------------------------------------------
        internal_weight = internal_base * reliability_internal
        external_weight = external_base * reliability_external
        # ------------------------------------------------------------------
        # Inject confidence-aware modulation
        # ------------------------------------------------------------------
        mean_conf = float(
            np.mean(list(fused_confidence.values()))
        )
        internal_weight *= (0.5 + 0.5 * mean_conf)
        external_weight *= (0.5 + 0.5 * mean_conf)
        # ------------------------------------------------------------------
        # Normalize
        # ------------------------------------------------------------------
        total = internal_weight + external_weight
        if total <= 1e-6:
            return {
                "internal": 0.5,
                "external": 0.5,
            }
        return {
            "internal": float(internal_weight / total),
            "external": float(external_weight / total),
        }
# ==============================================================================
# END OF CHUNK 85 Q 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 R 01 — CAMERA AI UNIFIED SHUTTER / ISO / ND RESOLVER
# ==============================================================================
#
# Purpose:
#   Resolve shutter speed, ISO, and ND filter strength into a single
#   physically-plausible exposure configuration driven by AI intent.
#
# Cinematic constraints:
#   - Preserve motion cadence (180° rule where possible)
#   - Avoid ISO noise amplification unless unavoidable
#   - Prefer optical attenuation (ND) over digital gain
#
# Inputs:
#   - Target exposure value (EV)
#   - Motion level (from IMU / optical flow)
#   - Scene luminance statistics
#
# Output:
#   - Dict with shutter_s, iso, nd_stops
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIExposureResolver:
    """
    Unified exposure parameter solver for cinematic capture.
    """
    __slots__ = (
        "_base_fps",
        "_max_iso",
        "_min_iso",
        "_max_nd",
    )
    def __init__(
        self,
        base_fps: float = 24.0,
        min_iso: int = 100,
        max_iso: int = 1600,
        max_nd_stops: float = 8.0,
    ):
        self._base_fps = float(base_fps)
        self._min_iso = int(min_iso)
        self._max_iso = int(max_iso)
        self._max_nd = float(max_nd_stops)
    def resolve(
        self,
        target_ev: float,
        motion_level: float,
        scene_luma: float,
    ) -> Dict[str, float]:
        """
        Compute optimal shutter, ISO, and ND.
        """
        # ------------------------------------------------------------------
        # Shutter selection (motion-aware)
        # ------------------------------------------------------------------
        motion_level = float(np.clip(motion_level, 0.0, 1.0))
        # 180-degree rule baseline
        base_shutter = 1.0 / (2.0 * self._base_fps)
        # Increase shutter speed under high motion to reduce smear
        shutter = base_shutter * (1.0 - 0.5 * motion_level)
        shutter = float(np.clip(shutter, 1.0 / 4000.0, 1.0 / 24.0))
        # ------------------------------------------------------------------
        # ISO / ND tradeoff
        # ------------------------------------------------------------------
        # Approximate exposure offset from shutter
        shutter_ev_offset = np.log2(base_shutter / shutter)
        remaining_ev = target_ev - shutter_ev_offset
        # Prefer ND before ISO increase
        nd_stops = np.clip(remaining_ev, 0.0, self._max_nd)
        iso_ev = remaining_ev - nd_stops
        iso = self._min_iso * (2.0 ** iso_ev)
        iso = float(np.clip(iso, self._min_iso, self._max_iso))
        # If ISO saturated, push remainder into ND
        if iso >= self._max_iso and nd_stops < self._max_nd:
            nd_stops = min(
                self._max_nd,
                nd_stops + (iso_ev - np.log2(self._max_iso / self._min_iso))
            )
        return {
            "shutter_s": float(shutter),
            "iso": float(iso),
            "nd_stops": float(nd_stops),
        }
# ==============================================================================
# END OF CHUNK 85 R 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 R 02 — CAMERA AI CAMERA-MODE STATE MACHINE
# ==============================================================================
#
# Purpose:
#   Govern camera operating modes using a deterministic, hysteresis-aware
#   state machine so exposure, motion cadence, and grading intents remain
#   stable across rapidly changing scenes.
#
# Modes:
#   - LOCKED_CINEMATIC: Stable scenes, strict cadence, minimal variance
#   - DYNAMIC_CINEMATIC: Moderate motion/light changes, controlled adaptation
#   - ACTION_PROTECT: High motion, prioritize clarity over cadence
#   - LOW_LIGHT_PROTECT: Noise-aware, ISO-managed stabilization
#
# Design principles:
#   - No frame-to-frame flapping
#   - Entry/exit hysteresis
#   - Scene-driven, not user-toggle driven
#
# ==============================================================================

from enum import Enum
from typing import Dict
import numpy as np


class CameraMode(Enum):
    LOCKED_CINEMATIC = 0
    DYNAMIC_CINEMATIC = 1
    ACTION_PROTECT = 2
    LOW_LIGHT_PROTECT = 3


class CameraAIModeStateMachine:
    """
    Deterministic camera mode state machine with hysteresis.
    """
    __slots__ = (
        "_mode",
        "_motion_enter",
        "_motion_exit",
        "_luma_low_enter",
        "_luma_low_exit",
        "_hold_frames",
        "_hold_counter",
    )
    def __init__(
        self,
        motion_enter: float = 0.55,
        motion_exit: float = 0.35,
        luma_low_enter: float = 0.22,
        luma_low_exit: float = 0.32,
        hold_frames: int = 8,
    ):
        self._mode = CameraMode.LOCKED_CINEMATIC
        self._motion_enter = float(motion_enter)
        self._motion_exit = float(motion_exit)
        self._luma_low_enter = float(luma_low_enter)
        self._luma_low_exit = float(luma_low_exit)
        self._hold_frames = int(hold_frames)
        self._hold_counter = 0
    def _can_transition(self) -> bool:
        if self._hold_counter <= 0:
            return True
        self._hold_counter -= 1
        return False
    def update(
        self,
        motion_level: float,
        mean_luma: float,
    ) -> CameraMode:
        """
        Update state machine based on scene metrics.
        """
        motion_level = float(np.clip(motion_level, 0.0, 1.0))
        mean_luma = float(np.clip(mean_luma, 0.0, 1.0))
        if not self._can_transition():
            return self._mode
        # --------------------------------------------------------------
        # Low-light overrides (highest priority)
        # --------------------------------------------------------------
        if self._mode != CameraMode.LOW_LIGHT_PROTECT:
            if mean_luma < self._luma_low_enter:
                self._mode = CameraMode.LOW_LIGHT_PROTECT
                self._hold_counter = self._hold_frames
                return self._mode
        else:
            if mean_luma > self._luma_low_exit:
                self._mode = CameraMode.DYNAMIC_CINEMATIC
                self._hold_counter = self._hold_frames
                return self._mode
        # --------------------------------------------------------------
        # Motion-driven transitions
        # --------------------------------------------------------------
        if self._mode == CameraMode.LOCKED_CINEMATIC:
            if motion_level > self._motion_enter:
                self._mode = CameraMode.DYNAMIC_CINEMATIC
                self._hold_counter = self._hold_frames
        elif self._mode == CameraMode.DYNAMIC_CINEMATIC:
            if motion_level > (self._motion_enter + 0.15):
                self._mode = CameraMode.ACTION_PROTECT
                self._hold_counter = self._hold_frames
            elif motion_level < self._motion_exit:
                self._mode = CameraMode.LOCKED_CINEMATIC
                self._hold_counter = self._hold_frames
        elif self._mode == CameraMode.ACTION_PROTECT:
            if motion_level < self._motion_exit:
                self._mode = CameraMode.DYNAMIC_CINEMATIC
                self._hold_counter = self._hold_frames
        return self._mode
    def export_intent(self) -> Dict[str, float]:
        """
        Convert mode into downstream intent weights.
        """
        if self._mode == CameraMode.LOCKED_CINEMATIC:
            return {
                "cadence_priority": 1.0,
                "noise_priority": 0.4,
                "motion_freeze": 0.0,
            }
        if self._mode == CameraMode.DYNAMIC_CINEMATIC:
            return {
                "cadence_priority": 0.7,
                "noise_priority": 0.6,
                "motion_freeze": 0.2,
            }
        if self._mode == CameraMode.ACTION_PROTECT:
            return {
                "cadence_priority": 0.2,
                "noise_priority": 0.7,
                "motion_freeze": 0.9,
            }
        # LOW_LIGHT_PROTECT
        return {
            "cadence_priority": 0.1,
            "noise_priority": 1.0,
            "motion_freeze": 0.4,
        }
# ==============================================================================
# END OF CHUNK 85 R 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 R 03 — CAMERA AI EXPOSURE INTENT ARBITRATION
# ==============================================================================
#
# Purpose:
#   Combine multiple exposure-driving intents into a single, stable
#   exposure directive for the resolver.
#
# Inputs:
#   - Camera mode intent (from state machine)
#   - Cross-camera priority weights
#   - Scene luminance statistics
#   - Highlight / shadow risk estimates
#
# Output:
#   - Target exposure EV offset
#   - Highlight protection bias
#   - Shadow lift bias
#
# Design goal:
#   Cinematic exposure that feels *decided*, not reactive.
#
# ==============================================================================

from typing import Dict
import numpy as np


class CameraAIExposureIntentArbitrator:
    """
    Arbitrates exposure-driving intents into a unified EV directive.
    """
    __slots__ = (
        "_highlight_weight",
        "_shadow_weight",
        "_priority_scale",
    )
    def __init__(
        self,
        highlight_weight: float = 0.65,
        shadow_weight: float = 0.45,
        priority_scale: float = 1.0,
    ):
        self._highlight_weight = float(highlight_weight)
        self._shadow_weight = float(shadow_weight)
        self._priority_scale = float(priority_scale)
    def arbitrate(
        self,
        mode_intent: Dict[str, float],
        camera_priority: Dict[str, float],
        scene_luma: float,
        highlight_risk: float,
        shadow_risk: float,
    ) -> Dict[str, float]:
        """
        Produce exposure intent values.
        """
        # Clamp inputs
        scene_luma = float(np.clip(scene_luma, 0.0, 1.0))
        highlight_risk = float(np.clip(highlight_risk, 0.0, 1.0))
        shadow_risk = float(np.clip(shadow_risk, 0.0, 1.0))
        # ------------------------------------------------------------------
        # Base EV from scene brightness
        # ------------------------------------------------------------------
        base_ev = np.log2(max(scene_luma, 1e-4))
        # ------------------------------------------------------------------
        # Mode-driven bias
        # ------------------------------------------------------------------
        cadence_priority = mode_intent.get("cadence_priority", 0.5)
        noise_priority = mode_intent.get("noise_priority", 0.5)
        mode_bias = (
            -0.5 * cadence_priority +
             0.4 * noise_priority
        )
        # ------------------------------------------------------------------
        # Highlight / shadow protection
        # ------------------------------------------------------------------
        highlight_bias = -self._highlight_weight * highlight_risk
        shadow_bias = self._shadow_weight * shadow_risk
        # ------------------------------------------------------------------
        # Cross-camera priority influence
        # ------------------------------------------------------------------
        priority_bias = (
            camera_priority.get("external", 0.5) -
            camera_priority.get("internal", 0.5)
        ) * self._priority_scale
        # ------------------------------------------------------------------
        # Final EV target
        # ------------------------------------------------------------------
        target_ev = (
            base_ev +
            mode_bias +
            highlight_bias +
            shadow_bias +
            priority_bias
        )
        return {
            "target_ev": float(target_ev),
            "highlight_bias": float(highlight_bias),
            "shadow_bias": float(shadow_bias),
        }
# ==============================================================================
# END OF CHUNK 85 R 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 R 04 — CAMERA AI TEMPORAL EXPOSURE SMOOTHING
# ==============================================================================
#
# Purpose:
#   Stabilize exposure decisions over time without introducing lag
#   or cinematic “rubber-banding”.
#
# Design goals:
#   - Eliminate frame-to-frame EV flicker
#   - Preserve responsiveness to real lighting changes
#   - Respect motion context and confidence gating
#
# Strategy:
#   - Adaptive EMA with motion-aware alpha
#   - Confidence-gated smoothing
#   - Hard clamp to prevent temporal overshoot
#
# ==============================================================================

from typing import Optional
import numpy as np


class CameraAITemporalExposureSmoother:
    """
    Motion- and confidence-aware temporal smoother for exposure EV.
    """
    __slots__ = (
        "_base_alpha",
        "_motion_alpha_boost",
        "_max_delta_ev",
        "_prev_ev",
    )
    def __init__(
        self,
        base_alpha: float = 0.08,
        motion_alpha_boost: float = 0.35,
        max_delta_ev: float = 0.4,
    ):
        """
        base_alpha:
            Baseline EMA factor (low = smoother).
        motion_alpha_boost:
            Extra responsiveness under high motion.
        max_delta_ev:
            Absolute EV change clamp per frame.
        """
        self._base_alpha = float(base_alpha)
        self._motion_alpha_boost = float(motion_alpha_boost)
        self._max_delta_ev = float(max_delta_ev)
        self._prev_ev: Optional[float] = None
    def _clamp_delta(self, prev: float, cur: float) -> float:
        delta = cur - prev
        if delta > self._max_delta_ev:
            return prev + self._max_delta_ev
        if delta < -self._max_delta_ev:
            return prev - self._max_delta_ev
        return cur
    def smooth(
        self,
        target_ev: float,
        motion_level: float,
        confidence: float,
    ) -> float:
        """
        Returns temporally-smoothed exposure EV.
        """
        target_ev = float(target_ev)
        motion_level = float(np.clip(motion_level, 0.0, 1.0))
        confidence = float(np.clip(confidence, 0.0, 1.0))
        if self._prev_ev is None:
            self._prev_ev = target_ev
            return target_ev
        # ------------------------------------------------------------------
        # Adaptive alpha computation
        # ------------------------------------------------------------------
        alpha = (
            self._base_alpha
            + motion_level * self._motion_alpha_boost
        )
        # Confidence gate (low confidence → smoother)
        alpha *= confidence
        alpha = float(np.clip(alpha, 0.01, 0.9))
        # ------------------------------------------------------------------
        # EMA smoothing
        # ------------------------------------------------------------------
        smoothed = (
            (1.0 - alpha) * self._prev_ev
            + alpha * target_ev
        )
        # Hard clamp to prevent overshoot
        smoothed = self._clamp_delta(self._prev_ev, smoothed)
        self._prev_ev = smoothed
        return float(smoothed)
# ==============================================================================
# END OF CHUNK 85 R 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 R 05 — CAMERA AI HIGHLIGHT / SHADOW PROTECTION LOGIC
# ==============================================================================
#
# Purpose:
#   Protect highlight detail and shadow integrity during exposure decisions,
#   emulating film shoulder/toe behavior while remaining sensor-aware.
#
# Design goals:
#   - Prevent highlight clipping under sudden brightness spikes
#   - Avoid crushing shadows in low-key scenes
#   - Maintain cinematic contrast and perceived dynamic range
#
# Strategy:
#   - Luminance percentile analysis
#   - Adaptive EV bias offsets
#   - Shoulder/toe soft limiting
#
# ==============================================================================

import numpy as np
from typing import Tuple


class CameraAIHighlightShadowProtector:
    """
    Exposure bias correction engine that protects highlights and shadows
    using film-inspired shoulder/toe logic.
    """
    __slots__ = (
        "_highlight_thresh",
        "_shadow_thresh",
        "_highlight_weight",
        "_shadow_weight",
        "_max_bias_ev",
    )
    def __init__(
        self,
        highlight_thresh: float = 0.98,
        shadow_thresh: float = 0.04,
        highlight_weight: float = 0.7,
        shadow_weight: float = 0.6,
        max_bias_ev: float = 1.2,
    ):
        """
        highlight_thresh:
            Percentile threshold for highlight risk.
        shadow_thresh:
            Percentile threshold for shadow risk.
        highlight_weight:
            Influence of highlight protection.
        shadow_weight:
            Influence of shadow protection.
        max_bias_ev:
            Absolute clamp for exposure bias.
        """
        self._highlight_thresh = float(highlight_thresh)
        self._shadow_thresh = float(shadow_thresh)
        self._highlight_weight = float(highlight_weight)
        self._shadow_weight = float(shadow_weight)
        self._max_bias_ev = float(max_bias_ev)
    def _percentiles(
        self, luminance: np.ndarray
    ) -> Tuple[float, float]:
        """
        Compute robust highlight and shadow percentiles.
        """
        hi = float(np.percentile(luminance, 99.9))
        lo = float(np.percentile(luminance, 0.1))
        return hi, lo
    def compute_bias(
        self,
        luminance: np.ndarray,
        base_ev: float,
    ) -> float:
        """
        Returns EV bias to apply on top of base exposure.
        """
        lum = luminance.astype(np.float32)
        hi, lo = self._percentiles(lum)
        bias = 0.0
        # ------------------------------------------------------------------
        # Highlight protection (film shoulder)
        # ------------------------------------------------------------------
        if hi > self._highlight_thresh:
            over = (hi - self._highlight_thresh) / max(
                1e-6, 1.0 - self._highlight_thresh
            )
            bias -= over * self._highlight_weight
        # ------------------------------------------------------------------
        # Shadow protection (film toe)
        # ------------------------------------------------------------------
        if lo < self._shadow_thresh:
            under = (self._shadow_thresh - lo) / max(
                1e-6, self._shadow_thresh
            )
            bias += under * self._shadow_weight
        # Clamp bias
        bias = float(
            np.clip(bias, -self._max_bias_ev, self._max_bias_ev)
        )
        return float(base_ev + bias)
# ==============================================================================
# END OF CHUNK 85 R 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 R 06 — CAMERA AI DYNAMIC HDR MERGE STRATEGY
# ==============================================================================
#
# Purpose:
#   Merge multi-exposure intent (or pseudo-HDR from single exposure)
#   into a stable, filmic HDR representation suitable for ACES pipelines.
#
# Design goals:
#   - Preserve highlight detail without haloing
#   - Lift shadow information without noise pumping
#   - Maintain temporal stability across frames
#
# Strategy:
#   - Exposure-bracket intent synthesis
#   - Luminance-weighted blending
#   - Filmic highlight compression
#
# ==============================================================================

import numpy as np
from typing import List, Optional


class CameraAIDynamicHDRMerger:
    """
    Dynamic HDR merge engine designed for real-time camera AI.
    Works with true multi-exposure or pseudo-HDR inputs.
    """
    __slots__ = (
        "_highlight_knee",
        "_shadow_floor",
        "_temporal_smooth",
        "_max_gain",
    )
    def __init__(
        self,
        highlight_knee: float = 0.85,
        shadow_floor: float = 0.02,
        temporal_smooth: float = 0.15,
        max_gain: float = 4.0,
    ):
        """
        highlight_knee:
            Luminance level where highlight compression begins.
        shadow_floor:
            Minimum luminance considered recoverable.
        temporal_smooth:
            Temporal smoothing factor (0 = none).
        max_gain:
            Maximum amplification allowed for shadow recovery.
        """
        self._highlight_knee = float(highlight_knee)
        self._shadow_floor = float(shadow_floor)
        self._temporal_smooth = float(temporal_smooth)
        self._max_gain = float(max_gain)
    def _compress_highlights(self, lum: np.ndarray) -> np.ndarray:
        """
        Film-inspired highlight compression (soft shoulder).
        """
        knee = self._highlight_knee
        out = lum.copy()
        mask = out > knee
        x = out[mask]
        out[mask] = knee + (1.0 - knee) * (
            1.0 - np.exp(-(x - knee) / (1.0 - knee))
        )
        return out
    def _lift_shadows(self, lum: np.ndarray) -> np.ndarray:
        """
        Controlled shadow lifting with gain limiting.
        """
        out = lum.copy()
        mask = out < self._shadow_floor
        if np.any(mask):
            gain = np.clip(
                self._shadow_floor / np.maximum(out[mask], 1e-6),
                1.0,
                self._max_gain,
            )
            out[mask] = out[mask] * gain
        return out
    def merge(
        self,
        frames: List[np.ndarray],
        weights: Optional[List[float]] = None,
        prev_hdr: Optional[np.ndarray] = None,
    ) -> np.ndarray:
        """
        Merge frames into HDR luminance.
        frames:
            List of linear luminance frames (0–1).
        weights:
            Optional exposure confidence weights.
        prev_hdr:
            Previous HDR frame for temporal smoothing.
        """
        if not frames:
            raise ValueError("HDR merge requires at least one frame.")
        stack = np.stack(frames, axis=0).astype(np.float32)
        if weights is None:
            weights = [1.0 / len(frames)] * len(frames)
        w = np.asarray(weights, dtype=np.float32)
        w = w / np.maximum(np.sum(w), 1e-6)
        hdr = np.tensordot(w, stack, axes=(0, 0))
        # Filmic operations
        hdr = self._compress_highlights(hdr)
        hdr = self._lift_shadows(hdr)
        # Temporal stabilization
        if prev_hdr is not None:
            alpha = self._temporal_smooth
            hdr = (1.0 - alpha) * hdr + alpha * prev_hdr
        return np.clip(hdr, 0.0, 1.0)
# ==============================================================================
# END OF CHUNK 85 R 06
# ==============================================================================
# ==============================================================================
# CHUNK 85 R 07 — CAMERA AI COLOR TEMPERATURE & WHITE BALANCE ARBITRATION
# ==============================================================================
#
# Purpose:
#   Resolve color temperature (CCT) and white balance intents from multiple
#   signals (scene analysis, sensor stats, temporal history) into a stable,
#   filmic WB decision suitable for ACES pipelines.
#
# Design goals:
#   - Avoid WB pumping/flicker
#   - Preserve creative intent (warm/cool bias)
#   - Respect illuminant continuity across shots
#
# Strategy:
#   - Multi-source CCT voting
#   - Confidence-weighted arbitration
#   - Temporal inertia with scene-cut reset
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class CameraAIWhiteBalanceArbiter:
    """
    White balance and color temperature arbitration engine.
    Produces a stable CCT and RGB gains for cinematic capture.
    """
    __slots__ = (
        "_min_cct",
        "_max_cct",
        "_temporal_alpha",
        "_scene_reset_delta",
    )
    def __init__(
        self,
        min_cct: float = 1800.0,
        max_cct: float = 12000.0,
        temporal_alpha: float = 0.12,
        scene_reset_delta: float = 1500.0,
    ):
        """
        min_cct / max_cct:
            Physical bounds for camera CCT.
        temporal_alpha:
            Temporal smoothing factor for WB.
        scene_reset_delta:
            CCT jump threshold to reset smoothing (scene cut).
        """
        self._min_cct = float(min_cct)
        self._max_cct = float(max_cct)
        self._temporal_alpha = float(temporal_alpha)
        self._scene_reset_delta = float(scene_reset_delta)
    def _clip_cct(self, cct: float) -> float:
        return float(np.clip(cct, self._min_cct, self._max_cct))
    def _arbiter(
        self,
        sources: Dict[str, float],
        confidences: Dict[str, float],
    ) -> float:
        """
        Confidence-weighted CCT arbitration.
        """
        total_w = 0.0
        accum = 0.0
        for k, cct in sources.items():
            w = float(confidences.get(k, 0.0))
            if w <= 0.0:
                continue
            accum += cct * w
            total_w += w
        if total_w <= 1e-6:
            return float(np.mean(list(sources.values())))
        return accum / total_w
    def compute_cct(
        self,
        source_ccts: Dict[str, float],
        source_conf: Dict[str, float],
        prev_cct: Optional[float] = None,
    ) -> float:
        """
        Compute final color temperature (Kelvin).
        """
        raw_cct = self._arbiter(source_ccts, source_conf)
        raw_cct = self._clip_cct(raw_cct)
        if prev_cct is None:
            return raw_cct
        # Scene cut detection
        if abs(raw_cct - prev_cct) > self._scene_reset_delta:
            return raw_cct
        # Temporal smoothing
        a = self._temporal_alpha
        return (1.0 - a) * prev_cct + a * raw_cct
    @staticmethod
    def cct_to_rgb_gains(cct: float) -> np.ndarray:
        """
        Convert CCT to normalized RGB gains (linear).
        Uses a smooth approximation suitable for real-time use.
        """
        t = cct / 100.0
        if t <= 66.0:
            r = 1.0
            g = np.clip(0.390081578769 * np.log(t) - 0.631841443788, 0.0, 1.0)
            b = 0.0 if t <= 19.0 else np.clip(
                0.543206789110 * np.log(t - 10.0) - 1.19625408914,
                0.0,
                1.0,
            )
        else:
            r = np.clip(1.29293618606 * ((t - 60.0) ** -0.1332047592), 0.0, 1.0)
            g = np.clip(1.1298908609 * ((t - 60.0) ** -0.0755148492), 0.0, 1.0)
            b = 1.0
        gains = np.array([r, g, b], dtype=np.float32)
        return gains / np.maximum(np.mean(gains), 1e-6)
# ==============================================================================
# END OF CHUNK 85 R 07
# ==============================================================================
# ==============================================================================
# CHUNK 85 R 08 — SENSOR SATURATION ROLL-OFF MODEL
# ==============================================================================
#
# Purpose:
#   Model sensor channel saturation and chroma compression near clipping,
#   preventing hue skew and channel clipping artifacts while preserving
#   perceived highlight colorfulness in a filmic manner.
#
# Design goals:
#   - Prevent hard RGB clipping
#   - Maintain hue stability near saturation
#   - Emulate film shoulder chroma compression
#
# Strategy:
#   - Luminance-driven saturation attenuation
#   - Channel-energy balancing
#   - Soft-knee roll-off curve
#
# ==============================================================================

import numpy as np
from typing import Optional


class CameraAISensorSaturationRollOff:
    """
    Sensor saturation roll-off engine.
    Operates in linear RGB before tone mapping / ACES RRT.
    """
    __slots__ = (
        "_knee_start",
        "_knee_end",
        "_max_chroma_compress",
        "_luma_weights",
    )
    def __init__(
        self,
        knee_start: float = 0.82,
        knee_end: float = 0.98,
        max_chroma_compress: float = 0.65,
        luma_weights: Optional[np.ndarray] = None,
    ):
        """
        knee_start:
            Luminance where saturation roll-off begins.
        knee_end:
            Luminance where maximum roll-off is reached.
        max_chroma_compress:
            Maximum chroma attenuation at full saturation.
        luma_weights:
            RGB weights for luminance calculation.
        """
        self._knee_start = float(knee_start)
        self._knee_end = float(knee_end)
        self._max_chroma_compress = float(max_chroma_compress)
        if luma_weights is None:
            # Linear Rec.709 / ACES-approx weights
            self._luma_weights = np.array([0.2126, 0.7152, 0.0722], dtype=np.float32)
        else:
            self._luma_weights = luma_weights.astype(np.float32)
    def _compute_luminance(self, rgb: np.ndarray) -> np.ndarray:
        """
        Compute linear luminance from RGB.
        """
        return np.tensordot(rgb, self._luma_weights, axes=([-1], [0]))
    def _rolloff_factor(self, lum: np.ndarray) -> np.ndarray:
        """
        Compute smooth roll-off factor based on luminance.
        """
        k0 = self._knee_start
        k1 = self._knee_end
        t = (lum - k0) / max(1e-6, (k1 - k0))
        t = np.clip(t, 0.0, 1.0)
        # Smoothstep curve
        return t * t * (3.0 - 2.0 * t)
    def apply(self, rgb: np.ndarray) -> np.ndarray:
        """
        Apply sensor saturation roll-off to linear RGB image.
        rgb:
            Linear RGB image, values expected in [0, 1+].
        """
        rgb = rgb.astype(np.float32)
        lum = self._compute_luminance(rgb)
        roll = self._rolloff_factor(lum)
        # Compute chroma (distance from luminance)
        chroma = rgb - lum[..., None]
        # Compression factor
        compress = 1.0 - roll[..., None] * self._max_chroma_compress
        # Apply chroma compression
        rgb_out = lum[..., None] + chroma * compress
        # Soft channel clipping safety
        rgb_out = np.minimum(rgb_out, 1.0 + 0.25 * roll[..., None])
        return np.clip(rgb_out, 0.0, None)
# ==============================================================================
# END OF CHUNK 85 R 08
# ==============================================================================
# ==============================================================================
# CHUNK 85 R 09 — EXPOSURE FAILURE RECOVERY OVERRIDES
# ==============================================================================
#
# Purpose:
#   Detect and recover from catastrophic exposure failures caused by
#   abrupt illumination changes (strobes, lightning, tunnels, specular hits),
#   preventing visible blown frames or crushed sequences.
#
# Design goals:
#   - One-frame recovery when possible
#   - No oscillation after recovery
#   - Cinematic continuity (no visible jumps)
#
# Strategy:
#   - Failure classification (over / under / mixed)
#   - Emergency EV clamp
#   - Decay-based release back to AI control
#
# ==============================================================================

import numpy as np
from typing import Optional, Dict


class CameraAIExposureFailureRecovery:
    """
    Emergency exposure override system.
    Temporarily supersedes normal exposure AI when failure is detected.
    """
    __slots__ = (
        "_clip_hi",
        "_clip_lo",
        "_ev_step",
        "_max_override_frames",
        "_release_rate",
    )
    def __init__(
        self,
        clip_hi: float = 0.995,
        clip_lo: float = 0.005,
        ev_step: float = 1.5,
        max_override_frames: int = 12,
        release_rate: float = 0.25,
    ):
        """
        clip_hi / clip_lo:
            Luminance thresholds indicating clipping.
        ev_step:
            Emergency EV correction step.
        max_override_frames:
            Maximum frames to hold override.
        release_rate:
            Blend-back rate to normal AI exposure.
        """
        self._clip_hi = float(clip_hi)
        self._clip_lo = float(clip_lo)
        self._ev_step = float(ev_step)
        self._max_override_frames = int(max_override_frames)
        self._release_rate = float(release_rate)
    def _detect_failure(self, lum: np.ndarray) -> Optional[str]:
        """
        Classify exposure failure type.
        """
        hi = float(np.percentile(lum, 99.95))
        lo = float(np.percentile(lum, 0.05))
        if hi > self._clip_hi and lo < self._clip_lo:
            return "mixed"
        if hi > self._clip_hi:
            return "over"
        if lo < self._clip_lo:
            return "under"
        return None
    def compute_override(
        self,
        luminance: np.ndarray,
        base_ev: float,
        state: Dict[str, float],
    ) -> float:
        """
        Returns EV value after failure recovery logic.
        state:
            Mutable dict storing override state between frames.
        """
        lum = luminance.astype(np.float32)
        failure = self._detect_failure(lum)
        # Initialize state
        if "override_frames" not in state:
            state["override_frames"] = 0
            state["override_ev"] = base_ev
        if failure is not None:
            # Trigger or extend override
            state["override_frames"] = min(
                state["override_frames"] + 1,
                self._max_override_frames,
            )
            if failure == "over":
                state["override_ev"] = base_ev - self._ev_step
            elif failure == "under":
                state["override_ev"] = base_ev + self._ev_step
            else:
                # Mixed failure → prioritize highlights
                state["override_ev"] = base_ev - (self._ev_step * 0.75)
            return state["override_ev"]
        # No failure detected
        if state["override_frames"] > 0:
            # Gradual release back to base exposure
            a = self._release_rate
            state["override_ev"] = (
                (1.0 - a) * state["override_ev"] + a * base_ev
            )
            state["override_frames"] -= 1
            return state["override_ev"]
        return base_ev
# ==============================================================================
# END OF CHUNK 85 R 09
# ==============================================================================
# ==============================================================================
# CHUNK 85 R 10 — EXPOSURE INTENT CONFIDENCE SCORING
# ==============================================================================
#
# Purpose:
#   Assign a quantitative confidence score to exposure decisions,
#   enabling arbitration between competing intents (scene AI,
#   recovery overrides, creative bias, temporal stability).
#
# Design goals:
#   - Prefer stable, well-supported exposure intents
#   - Penalize noisy or contradictory signals
#   - Enable graceful handoff between exposure subsystems
#
# Strategy:
#   - Signal agreement scoring
#   - Temporal consistency weighting
#   - Failure-history penalty
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class CameraAIExposureConfidenceScorer:
    """
    Computes confidence score (0–1) for a proposed exposure intent.
    Used by higher-level arbitration logic.
    """
    __slots__ = (
        "_temporal_weight",
        "_agreement_weight",
        "_failure_weight",
    )
    def __init__(
        self,
        temporal_weight: float = 0.35,
        agreement_weight: float = 0.45,
        failure_weight: float = 0.20,
    ):
        """
        temporal_weight:
            Importance of temporal stability.
        agreement_weight:
            Importance of multi-signal agreement.
        failure_weight:
            Penalty weight for recent exposure failures.
        """
        self._temporal_weight = float(temporal_weight)
        self._agreement_weight = float(agreement_weight)
        self._failure_weight = float(failure_weight)
    def _temporal_score(
        self, current_ev: float, prev_ev: Optional[float]
    ) -> float:
        """
        Penalize abrupt exposure jumps.
        """
        if prev_ev is None:
            return 1.0
        delta = abs(current_ev - prev_ev)
        return float(np.exp(-delta))
    def _agreement_score(
        self, intents: Dict[str, float]
    ) -> float:
        """
        Score agreement between exposure intent sources.
        """
        if not intents:
            return 0.0
        values = np.array(list(intents.values()), dtype=np.float32)
        spread = float(np.std(values))
        # Lower spread → higher agreement
        return float(np.exp(-spread * 1.5))
    def _failure_penalty(self, recent_failures: int) -> float:
        """
        Penalize confidence if recent exposure failures occurred.
        """
        return float(np.exp(-0.5 * recent_failures))
    def score(
        self,
        proposed_ev: float,
        intent_sources: Dict[str, float],
        prev_ev: Optional[float],
        recent_failures: int,
    ) -> float:
        """
        Compute final confidence score.
        """
        t = self._temporal_score(proposed_ev, prev_ev)
        a = self._agreement_score(intent_sources)
        f = self._failure_penalty(recent_failures)
        score = (
            self._temporal_weight * t
            + self._agreement_weight * a
            + self._failure_weight * f
        )
        return float(np.clip(score, 0.0, 1.0))
# ==============================================================================
# END OF CHUNK 85 R 10
# ==============================================================================
# ==============================================================================
# CHUNK 85 S 01 — CAMERA AI SCENE CLASSIFICATION CORE
# ==============================================================================
#
# Purpose:
#   Classify the current scene into cinematic-relevant categories using
#   lightweight, real-time features suitable for onboard + edge inference.
#
# Design goals:
#   - Robust to motion, noise, and lighting changes
#   - Fast enough for per-frame evaluation
#   - Produce stable scene labels with confidence
#
# Scene classes (non-exhaustive):
#   - daylight_exterior
#   - golden_hour
#   - night_exterior
#   - interior_lowkey
#   - interior_highkey
#   - backlit
#   - high_contrast
#
# Strategy:
#   - Luminance statistics + contrast metrics
#   - Color temperature & saturation cues
#   - Temporal hysteresis to avoid label flicker
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional, Tuple


class CameraAISceneClassifier:
    """
    Real-time scene classification engine for cinematic camera AI.
    Outputs scene label and confidence score.
    """
    __slots__ = (
        "_contrast_thresh",
        "_lowkey_luma",
        "_highkey_luma",
        "_temporal_alpha",
        "_prev_scene",
        "_prev_conf",
    )
    def __init__(
        self,
        contrast_thresh: float = 0.35,
        lowkey_luma: float = 0.18,
        highkey_luma: float = 0.65,
        temporal_alpha: float = 0.15,
    ):
        """
        contrast_thresh:
            Threshold for classifying high-contrast scenes.
        lowkey_luma:
            Mean luminance threshold for low-key scenes.
        highkey_luma:
            Mean luminance threshold for high-key scenes.
        temporal_alpha:
            Temporal smoothing factor for scene confidence.
        """
        self._contrast_thresh = float(contrast_thresh)
        self._lowkey_luma = float(lowkey_luma)
        self._highkey_luma = float(highkey_luma)
        self._temporal_alpha = float(temporal_alpha)
        self._prev_scene: Optional[str] = None
        self._prev_conf: float = 0.0
    @staticmethod
    def _luminance_stats(lum: np.ndarray) -> Tuple[float, float]:
        """
        Compute mean luminance and contrast proxy.
        """
        mean_l = float(np.mean(lum))
        p90 = float(np.percentile(lum, 90.0))
        p10 = float(np.percentile(lum, 10.0))
        contrast = max(0.0, p90 - p10)
        return mean_l, contrast
    def _classify(
        self,
        mean_l: float,
        contrast: float,
        cct: Optional[float],
    ) -> Tuple[str, float]:
        """
        Heuristic scene classification with confidence estimate.
        """
        # Base confidence
        conf = 0.6
        # High contrast / backlit
        if contrast > self._contrast_thresh:
            if mean_l < self._lowkey_luma:
                return "backlit", conf + 0.2
            return "high_contrast", conf + 0.2
        # Low-key / high-key interiors
        if mean_l < self._lowkey_luma:
            return "interior_lowkey", conf + 0.1
        if mean_l > self._highkey_luma:
            return "interior_highkey", conf + 0.1
        # Exterior daylight heuristics
        if cct is not None:
            if 3500.0 < cct < 5200.0:
                return "golden_hour", conf + 0.15
            if cct >= 5200.0:
                return "daylight_exterior", conf + 0.15
            if cct < 3500.0:
                return "night_exterior", conf + 0.15
        return "neutral_scene", conf
    def classify(
        self,
        luminance: np.ndarray,
        cct: Optional[float] = None,
    ) -> Tuple[str, float]:
        """
        Classify current frame into a scene category.
        Returns:
            (scene_label, confidence)
        """
        lum = luminance.astype(np.float32)
        mean_l, contrast = self._luminance_stats(lum)
        scene, conf = self._classify(mean_l, contrast, cct)
        # Temporal stabilization
        if self._prev_scene == scene:
            a = self._temporal_alpha
            conf = (1.0 - a) * self._prev_conf + a * conf
        self._prev_scene = scene
        self._prev_conf = conf
        return scene, float(np.clip(conf, 0.0, 1.0))
# ==============================================================================
# END OF CHUNK 85 S 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 S 02 — SHOT TYPE SEMANTIC DETECTION
# ==============================================================================
#
# Purpose:
#   Infer cinematic shot type semantics from scene statistics, motion cues,
#   subject scale, and camera dynamics. Outputs a stable semantic label with
#   confidence for downstream composition and motion planning.
#
# Shot types (non-exhaustive):
#   - wide_establishing
#   - medium_subject
#   - close_up
#   - tracking
#   - reveal
#   - locked_off
#   - aerial_orbit
#
# Strategy:
#   - Subject scale vs frame
#   - Camera motion energy
#   - Temporal hysteresis to avoid shot flicker
#
# ==============================================================================

import numpy as np
from typing import Optional, Tuple


class CameraAIShotTypeDetector:
    """
    Determines cinematic shot type using lightweight heuristics suitable
    for real-time autonomous camera systems.
    """
    __slots__ = (
        "_scale_close",
        "_scale_wide",
        "_motion_low",
        "_motion_high",
        "_temporal_alpha",
        "_prev_type",
        "_prev_conf",
    )
    def __init__(
        self,
        scale_close: float = 0.45,
        scale_wide: float = 0.18,
        motion_low: float = 0.03,
        motion_high: float = 0.15,
        temporal_alpha: float = 0.18,
    ):
        """
        scale_close:
            Subject occupies this fraction of frame → close-up.
        scale_wide:
            Subject below this fraction → wide shot.
        motion_low:
            Camera motion energy considered static.
        motion_high:
            Camera motion energy considered dynamic.
        temporal_alpha:
            Temporal smoothing factor for shot type confidence.
        """
        self._scale_close = float(scale_close)
        self._scale_wide = float(scale_wide)
        self._motion_low = float(motion_low)
        self._motion_high = float(motion_high)
        self._temporal_alpha = float(temporal_alpha)
        self._prev_type: Optional[str] = None
        self._prev_conf: float = 0.0
    def _classify(
        self,
        subject_scale: Optional[float],
        motion_energy: float,
    ) -> Tuple[str, float]:
        """
        Heuristic classification with confidence.
        """
        conf = 0.6
        # No subject detected → environment-driven shots
        if subject_scale is None:
            if motion_energy < self._motion_low:
                return "locked_off", conf + 0.15
            if motion_energy > self._motion_high:
                return "aerial_orbit", conf + 0.15
            return "wide_establishing", conf
        # Subject-driven shots
        if subject_scale >= self._scale_close:
            return "close_up", conf + 0.2
        if subject_scale <= self._scale_wide:
            if motion_energy > self._motion_high:
                return "reveal", conf + 0.15
            return "wide_establishing", conf + 0.1
        # Medium framing
        if motion_energy > self._motion_high:
            return "tracking", conf + 0.15
        return "medium_subject", conf + 0.1
    def detect(
        self,
        subject_scale: Optional[float],
        motion_energy: float,
    ) -> Tuple[str, float]:
        """
        Detect shot type.
        subject_scale:
            Fraction of frame occupied by primary subject (0–1).
        motion_energy:
            Normalized camera motion metric.
        """
        shot, conf = self._classify(subject_scale, motion_energy)
        # Temporal stabilization
        if self._prev_type == shot:
            a = self._temporal_alpha
            conf = (1.0 - a) * self._prev_conf + a * conf
        self._prev_type = shot
        self._prev_conf = conf
        return shot, float(np.clip(conf, 0.0, 1.0))
# ==============================================================================
# END OF CHUNK 85 S 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 S 03 — SUBJECT IMPORTANCE RANKING
# ==============================================================================
#
# Purpose:
#   Rank detected subjects by cinematic importance to decide framing,
#   focus priority, exposure bias, and motion intent in autonomous capture.
#
# Design goals:
#   - Prefer humans and faces over objects
#   - Weight motion, size, and saliency
#   - Maintain temporal consistency (no subject popping)
#
# Subject signals considered:
#   - Class (person, vehicle, animal, object)
#   - Screen size / scale
#   - Motion magnitude
#   - Saliency / contrast
#
# ==============================================================================

import numpy as np
from typing import List, Dict, Optional


class CameraAISubjectImportanceRanker:
    """
    Computes a normalized importance score (0–1) for each detected subject.
    Used by framing, exposure bias, and motion planning subsystems.
    """
    __slots__ = (
        "_class_weights",
        "_motion_weight",
        "_scale_weight",
        "_saliency_weight",
        "_temporal_alpha",
        "_prev_scores",
    )
    def __init__(
        self,
        class_weights: Optional[Dict[str, float]] = None,
        motion_weight: float = 0.25,
        scale_weight: float = 0.30,
        saliency_weight: float = 0.20,
        temporal_alpha: float = 0.18,
    ):
        """
        class_weights:
            Base importance per subject class.
        motion_weight:
            Contribution of subject motion.
        scale_weight:
            Contribution of screen size.
        saliency_weight:
            Contribution of visual saliency.
        temporal_alpha:
            Temporal smoothing factor for importance stability.
        """
        if class_weights is None:
            self._class_weights = {
                "person": 1.0,
                "face": 1.1,
                "vehicle": 0.75,
                "animal": 0.7,
                "object": 0.4,
                "background": 0.1,
            }
        else:
            self._class_weights = dict(class_weights)
        self._motion_weight = float(motion_weight)
        self._scale_weight = float(scale_weight)
        self._saliency_weight = float(saliency_weight)
        self._temporal_alpha = float(temporal_alpha)
        self._prev_scores: Dict[int, float] = {}
    def _base_class_score(self, cls: str) -> float:
        return float(self._class_weights.get(cls, 0.3))
    def rank(
        self,
        subjects: List[Dict],
    ) -> List[Dict]:
        """
        Rank subjects by cinematic importance.
        Each subject dict must contain:
            - id: stable identifier
            - class: semantic label
            - scale: fraction of frame (0–1)
            - motion: normalized motion magnitude (0–1)
            - saliency: normalized saliency (0–1)
        """
        ranked = []
        for subj in subjects:
            sid = int(subj["id"])
            cls = str(subj.get("class", "object"))
            base = self._base_class_score(cls)
            motion = float(subj.get("motion", 0.0))
            scale = float(subj.get("scale", 0.0))
            sal = float(subj.get("saliency", 0.0))
            score = (
                base
                + self._motion_weight * motion
                + self._scale_weight * scale
                + self._saliency_weight * sal
            )
            score = np.clip(score, 0.0, 1.5)
            # Temporal stabilization per subject
            if sid in self._prev_scores:
                a = self._temporal_alpha
                score = (1.0 - a) * self._prev_scores[sid] + a * score
            self._prev_scores[sid] = score
            subj_out = dict(subj)
            subj_out["importance"] = float(np.clip(score, 0.0, 1.0))
            ranked.append(subj_out)
        # Sort descending by importance
        ranked.sort(key=lambda x: x["importance"], reverse=True)
        return ranked
# ==============================================================================
# END OF CHUNK 85 S 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 S 04 — CAMERA AI COMPOSITION INTENT ENGINE
# ==============================================================================
#
# Purpose:
#   Translate ranked subjects + scene context into a concrete
#   cinematic composition intent (what to frame, how to frame, why).
#
# Outputs (intent schema):
#   - primary_subject_id
#   - secondary_subject_ids
#   - framing_style (close, medium, wide, tracking, reveal)
#   - screen_region (rule-of-thirds target)
#   - camera_motion_hint (static, push, pull, pan, orbit)
#   - exposure_bias_hint
#   - stability_priority
#
# ==============================================================================

import numpy as np
from typing import List, Dict, Optional


class CameraAICompositionIntentEngine:
    """
    Converts subject importance rankings and scene signals
    into a deterministic composition intent used by
    framing, motion, and exposure controllers.
    """
    __slots__ = (
        "_min_primary_score",
        "_secondary_ratio",
        "_motion_threshold",
        "_wide_scene_threshold",
    )
    def __init__(
        self,
        min_primary_score: float = 0.35,
        secondary_ratio: float = 0.55,
        motion_threshold: float = 0.22,
        wide_scene_threshold: float = 0.65,
    ):
        """
        min_primary_score:
            Minimum importance to be considered primary subject.
        secondary_ratio:
            Relative score threshold for secondary subjects.
        motion_threshold:
            Scene motion above which tracking shots are preferred.
        wide_scene_threshold:
            Scene openness above which wide compositions dominate.
        """
        self._min_primary_score = float(min_primary_score)
        self._secondary_ratio = float(secondary_ratio)
        self._motion_threshold = float(motion_threshold)
        self._wide_scene_threshold = float(wide_scene_threshold)
    def _choose_framing_style(
        self,
        primary: Dict,
        scene_motion: float,
        scene_openness: float,
    ) -> str:
        # Wide landscapes or establishing shots
        if scene_openness > self._wide_scene_threshold:
            return "wide"
        # Strong subject motion → tracking
        if scene_motion > self._motion_threshold:
            return "tracking"
        # Close-up preference for faces / people
        if primary.get("class") in ("face", "person"):
            return "medium" if primary.get("scale", 0.0) > 0.25 else "close"
        return "medium"
    def _camera_motion_hint(
        self,
        framing_style: str,
        scene_motion: float,
    ) -> str:
        if framing_style == "tracking":
            return "follow"
        if scene_motion < 0.08:
            return "static"
        if framing_style == "wide":
            return "slow_pan"
        return "subtle_push"
    def _screen_region_from_subject(self, subject: Dict) -> str:
        # Rule-of-thirds targeting
        cx = float(subject.get("cx", 0.5))
        cy = float(subject.get("cy", 0.5))
        horiz = "center"
        vert = "center"
        if cx < 0.33:
            horiz = "left"
        elif cx > 0.66:
            horiz = "right"
        if cy < 0.33:
            vert = "top"
        elif cy > 0.66:
            vert = "bottom"
        return f"{vert}_{horiz}"
    def infer_intent(
        self,
        ranked_subjects: List[Dict],
        scene_motion: float,
        scene_openness: float,
    ) -> Optional[Dict]:
        """
        Generate composition intent from ranked subjects.
        ranked_subjects must be sorted descending by importance.
        """
        if not ranked_subjects:
            return None
        primary = ranked_subjects[0]
        if primary.get("importance", 0.0) < self._min_primary_score:
            return None
        primary_id = primary["id"]
        # Secondary subjects
        sec_ids = []
        p_score = float(primary["importance"])
        for s in ranked_subjects[1:]:
            if float(s.get("importance", 0.0)) >= p_score * self._secondary_ratio:
                sec_ids.append(s["id"])
        framing_style = self._choose_framing_style(
            primary, scene_motion, scene_openness
        )
        intent = {
            "primary_subject_id": primary_id,
            "secondary_subject_ids": sec_ids,
            "framing_style": framing_style,
            "screen_region": self._screen_region_from_subject(primary),
            "camera_motion_hint": self._camera_motion_hint(
                framing_style, scene_motion
            ),
            "exposure_bias_hint": float(
                np.clip(primary.get("importance", 0.5) - 0.5, -0.3, 0.3)
            ),
            "stability_priority": "high"
            if framing_style in ("close", "medium")
            else "medium",
        }
        return intent
# ==============================================================================
# END OF CHUNK 85 S 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 S 05 — CINEMATIC FRAMING RULE ENGINE
# ==============================================================================
#
# Purpose:
#   Convert composition intent into concrete framing constraints:
#   headroom, lead-room, horizon placement, subject scale,
#   and safety margins — all perceptible at cinema scale.
#
# Inputs:
#   - intent (from CameraAICompositionIntentEngine)
#   - subject geometry (bbox, velocity, depth proxy)
#   - camera state (FOV, aspect, stabilization budget)
#
# Outputs:
#   - framing_constraints dict consumed by camera + gimbal logic
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class CinematicFramingRuleEngine:
    """
    Enforces cinematic framing rules that are *visibly* important:
    rule-of-thirds, lead-room, headroom, horizon discipline,
    and safety margins for stabilization.
    """
    __slots__ = (
        "_base_headroom",
        "_leadroom_gain",
        "_horizon_band",
        "_min_safe_margin",
        "_max_scale_boost",
    )
    def __init__(
        self,
        base_headroom: float = 0.12,
        leadroom_gain: float = 0.18,
        horizon_band: float = 0.08,
        min_safe_margin: float = 0.06,
        max_scale_boost: float = 1.35,
    ):
        """
        base_headroom:
            Default headroom above primary subject (fraction of frame).
        leadroom_gain:
            Additional horizontal space added in motion direction.
        horizon_band:
            Allowed vertical band for horizon placement.
        min_safe_margin:
            Margin reserved for stabilization & crop safety.
        max_scale_boost:
            Upper bound for subject scale emphasis.
        """
        self._base_headroom = float(base_headroom)
        self._leadroom_gain = float(leadroom_gain)
        self._horizon_band = float(horizon_band)
        self._min_safe_margin = float(min_safe_margin)
        self._max_scale_boost = float(max_scale_boost)
    def _compute_leadroom(
        self,
        vx: float,
        framing_style: str,
    ) -> float:
        if framing_style not in ("tracking", "follow"):
            return 0.0
        return np.clip(vx * self._leadroom_gain, -0.25, 0.25)
    def _subject_scale(
        self,
        importance: float,
        framing_style: str,
    ) -> float:
        if framing_style == "close":
            return self._max_scale_boost
        if framing_style == "medium":
            return 1.0 + 0.35 * importance
        return 1.0
    def _horizon_target(
        self,
        scene_openness: float,
    ) -> float:
        # Cinematic horizons live slightly below center in wide shots
        base = 0.5 + 0.1 * (scene_openness - 0.5)
        return float(
            np.clip(
                base,
                0.5 - self._horizon_band,
                0.5 + self._horizon_band,
            )
        )
    def compute_constraints(
        self,
        intent: Dict,
        subject: Dict,
        camera_state: Dict,
        scene_openness: float,
    ) -> Optional[Dict]:
        """
        Generate framing constraints.
        """
        if intent is None or subject is None:
            return None
        vx = float(subject.get("vx", 0.0))
        leadroom = self._compute_leadroom(
            vx, intent["camera_motion_hint"]
        )
        scale = self._subject_scale(
            subject.get("importance", 0.5),
            intent["framing_style"],
        )
        horizon_y = self._horizon_target(scene_openness)
        safe_margin = max(
            self._min_safe_margin,
            camera_state.get("stabilization_margin", 0.0),
        )
        constraints = {
            "target_screen_region": intent["screen_region"],
            "leadroom_x": float(leadroom),
            "headroom_y": float(self._base_headroom),
            "subject_scale": float(scale),
            "horizon_y": float(horizon_y),
            "safe_margin": float(safe_margin),
            "lock_horizon": intent["framing_style"] == "wide",
        }
        return constraints
# ==============================================================================
# END OF CHUNK 85 S 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 S 06 — RULE-BASED HORIZON & HEADROOM CONTROL
# ==============================================================================
#
# Purpose:
#   Enforce perceptually correct horizon placement and headroom
#   under camera motion, terrain slope, subject elevation, and
#   stabilization constraints.
#
# Inputs:
#   - framing_constraints (from 85 S 05)
#   - IMU-derived pitch/roll (smoothed)
#   - scene geometry (ground plane confidence)
#   - subject vertical extent
#
# Outputs:
#   - horizon_lock_y
#   - dynamic_headroom_y
#   - vertical_crop_limits
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class HorizonHeadroomController:
    """
    Maintains cinematic horizon discipline while preserving
    subject headroom and stabilization safety.
    """
    __slots__ = (
        "_max_pitch_comp",
        "_max_roll_comp",
        "_headroom_gain",
        "_ground_conf_weight",
        "_crop_guard",
    )
    def __init__(
        self,
        max_pitch_comp: float = 0.18,
        max_roll_comp: float = 0.12,
        headroom_gain: float = 0.35,
        ground_conf_weight: float = 0.6,
        crop_guard: float = 0.05,
    ):
        """
        max_pitch_comp:
            Upper bound for pitch-based horizon correction.
        max_roll_comp:
            Upper bound for roll-based horizon correction.
        headroom_gain:
            Scales dynamic headroom based on subject elevation.
        ground_conf_weight:
            Weight for trusting ground-plane estimation.
        crop_guard:
            Extra margin to avoid crop-edge hits during EIS.
        """
        self._max_pitch_comp = float(max_pitch_comp)
        self._max_roll_comp = float(max_roll_comp)
        self._headroom_gain = float(headroom_gain)
        self._ground_conf_weight = float(ground_conf_weight)
        self._crop_guard = float(crop_guard)
    def _imu_horizon_offset(
        self,
        pitch: float,
        roll: float,
    ) -> float:
        # Convert pitch/roll into normalized vertical offset
        pitch_off = np.clip(pitch, -self._max_pitch_comp, self._max_pitch_comp)
        roll_off = np.clip(roll, -self._max_roll_comp, self._max_roll_comp)
        return float(pitch_off + 0.5 * roll_off)
    def _dynamic_headroom(
        self,
        base_headroom: float,
        subject_y: float,
    ) -> float:
        # Subjects high in frame need more headroom to breathe
        delta = (0.5 - subject_y) * self._headroom_gain
        return float(np.clip(base_headroom + delta, 0.05, 0.35))
    def compute(
        self,
        framing_constraints: Dict,
        imu_state: Dict,
        scene_geometry: Dict,
        subject: Dict,
    ) -> Optional[Dict]:
        """
        Returns stabilized horizon + headroom controls.
        """
        if framing_constraints is None:
            return None
        pitch = float(imu_state.get("pitch", 0.0))
        roll = float(imu_state.get("roll", 0.0))
        ground_conf = float(scene_geometry.get("ground_confidence", 0.0))
        ground_conf = np.clip(ground_conf, 0.0, 1.0)
        base_horizon = float(framing_constraints.get("horizon_y", 0.5))
        imu_offset = self._imu_horizon_offset(pitch, roll)
        # Blend IMU vs scene ground plane
        horizon_y = base_horizon + (
            imu_offset * (1.0 - self._ground_conf_weight * ground_conf)
        )
        horizon_y = float(np.clip(horizon_y, 0.3, 0.7))
        subject_y = float(subject.get("cy", 0.5))
        headroom = self._dynamic_headroom(
            framing_constraints.get("headroom_y", 0.12),
            subject_y,
        )
        safe_margin = float(framing_constraints.get("safe_margin", 0.06))
        vertical_crop_limits = (
            safe_margin + self._crop_guard,
            1.0 - safe_margin - self._crop_guard,
        )
        return {
            "horizon_lock_y": horizon_y,
            "dynamic_headroom_y": headroom,
            "vertical_crop_limits": vertical_crop_limits,
            "lock_enabled": framing_constraints.get("lock_horizon", False),
        }
# ==============================================================================
# END OF CHUNK 85 S 06
# ==============================================================================
# ==============================================================================
# CHUNK 85 S 07 — SUBJECT-CENTRIC REFRAMING LOGIC
# ==============================================================================
#
# Purpose:
#   Convert framing constraints + horizon/headroom controls into
#   concrete reframing targets (pan/tilt/zoom offsets) that keep the
#   primary subject dominant while respecting cinematic intent.
#
# Inputs:
#   - intent (composition intent)
#   - framing_constraints (85 S 05)
#   - horizon_controls (85 S 06)
#   - subject geometry (bbox, center, scale, velocity)
#   - camera model (FOV, aspect)
#
# Outputs:
#   - target_pan_offset
#   - target_tilt_offset
#   - target_zoom_factor
#   - recenter_priority
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class SubjectCentricReframer:
    """
    Computes smooth, perceptually-correct reframing targets
    centered on the primary subject without inducing jitter.
    """
    __slots__ = (
        "_pan_gain",
        "_tilt_gain",
        "_max_pan",
        "_max_tilt",
        "_zoom_smooth",
    )
    def __init__(
        self,
        pan_gain: float = 0.85,
        tilt_gain: float = 0.9,
        max_pan: float = 0.35,
        max_tilt: float = 0.28,
        zoom_smooth: float = 0.15,
    ):
        """
        pan_gain / tilt_gain:
            Proportional gains for reframing offsets.
        max_pan / max_tilt:
            Hard limits to avoid aggressive motion.
        zoom_smooth:
            Dampening factor for zoom changes.
        """
        self._pan_gain = float(pan_gain)
        self._tilt_gain = float(tilt_gain)
        self._max_pan = float(max_pan)
        self._max_tilt = float(max_tilt)
        self._zoom_smooth = float(zoom_smooth)
    def _screen_region_target(self, region: str) -> np.ndarray:
        # Map rule-of-thirds regions to normalized targets
        mapping = {
            "top_left": (0.33, 0.33),
            "top_center": (0.50, 0.33),
            "top_right": (0.66, 0.33),
            "center_left": (0.33, 0.50),
            "center_center": (0.50, 0.50),
            "center_right": (0.66, 0.50),
            "bottom_left": (0.33, 0.66),
            "bottom_center": (0.50, 0.66),
            "bottom_right": (0.66, 0.66),
        }
        return np.array(mapping.get(region, (0.5, 0.5)), dtype=np.float32)
    def _compute_pan_tilt(
        self,
        subject_center: np.ndarray,
        target_center: np.ndarray,
    ) -> np.ndarray:
        delta = target_center - subject_center
        pan = np.clip(delta[0] * self._pan_gain, -self._max_pan, self._max_pan)
        tilt = np.clip(delta[1] * self._tilt_gain, -self._max_tilt, self._max_tilt)
        return np.array([pan, tilt], dtype=np.float32)
    def _compute_zoom(
        self,
        desired_scale: float,
        current_zoom: float,
    ) -> float:
        delta = desired_scale - current_zoom
        return float(current_zoom + delta * self._zoom_smooth)
    def reframe(
        self,
        intent: Dict,
        framing_constraints: Dict,
        horizon_controls: Dict,
        subject: Dict,
        camera_state: Dict,
    ) -> Optional[Dict]:
        """
        Produce reframing commands for camera/gimbal layers.
        """
        if intent is None or subject is None:
            return None
        subject_center = np.array(
            [subject.get("cx", 0.5), subject.get("cy", 0.5)],
            dtype=np.float32,
        )
        target_center = self._screen_region_target(
            framing_constraints.get("target_screen_region", "center_center")
        )
        pan_tilt = self._compute_pan_tilt(subject_center, target_center)
        desired_scale = float(framing_constraints.get("subject_scale", 1.0))
        current_zoom = float(camera_state.get("zoom", 1.0))
        zoom = self._compute_zoom(desired_scale, current_zoom)
        recenter_priority = (
            "high"
            if intent.get("stability_priority") == "high"
            else "medium"
        )
        return {
            "target_pan_offset": float(pan_tilt[0]),
            "target_tilt_offset": float(pan_tilt[1]),
            "target_zoom_factor": float(zoom),
            "recenter_priority": recenter_priority,
            "horizon_lock_y": horizon_controls.get("horizon_lock_y", 0.5),
        }
# ==============================================================================
# END OF CHUNK 85 S 07
# ==============================================================================
# ==============================================================================
# CHUNK 85 S 08 — MULTI-SUBJECT CONFLICT RESOLUTION
# ==============================================================================
#
# Purpose:
#   Resolve framing, scale, and motion conflicts when multiple
#   subjects compete for visual dominance in the frame.
#
# This module:
#   - Preserves primary subject dominance
#   - Prevents oscillation between subjects
#   - Allows secondary subjects to remain contextually visible
#   - Maintains cinematic balance (not surveillance framing)
#
# Inputs:
#   - composition intent
#   - ranked subject list
#   - reframing output (85 S 07)
#
# Outputs:
#   - resolved_pan_offset
#   - resolved_tilt_offset
#   - resolved_zoom_factor
#   - subject_lock_state
#
# ==============================================================================

import numpy as np
from typing import Dict, List, Optional


class MultiSubjectConflictResolver:
    """
    Ensures stable cinematic framing when multiple subjects
    compete for attention.
    """
    __slots__ = (
        "_lock_hysteresis",
        "_secondary_visibility_weight",
        "_max_zoom_reduction",
        "_center_pull_strength",
    )
    def __init__(
        self,
        lock_hysteresis: float = 0.18,
        secondary_visibility_weight: float = 0.35,
        max_zoom_reduction: float = 0.25,
        center_pull_strength: float = 0.4,
    ):
        """
        lock_hysteresis:
            Resistance to switching primary subject.
        secondary_visibility_weight:
            How strongly secondary subjects influence framing.
        max_zoom_reduction:
            Upper bound on zoom-out to fit multiple subjects.
        center_pull_strength:
            How much secondary subjects pull framing center.
        """
        self._lock_hysteresis = float(lock_hysteresis)
        self._secondary_visibility_weight = float(secondary_visibility_weight)
        self._max_zoom_reduction = float(max_zoom_reduction)
        self._center_pull_strength = float(center_pull_strength)
    def _secondary_center_of_mass(self, subjects: List[Dict]) -> Optional[np.ndarray]:
        if not subjects:
            return None
        centers = []
        weights = []
        for s in subjects:
            centers.append([s.get("cx", 0.5), s.get("cy", 0.5)])
            weights.append(s.get("importance", 0.1))
        centers = np.array(centers, dtype=np.float32)
        weights = np.array(weights, dtype=np.float32)
        weights /= max(np.sum(weights), 1e-6)
        return np.sum(centers * weights[:, None], axis=0)
    def resolve(
        self,
        intent: Dict,
        ranked_subjects: List[Dict],
        reframing: Dict,
    ) -> Optional[Dict]:
        """
        Resolve conflicts and output stable framing controls.
        """
        if intent is None or reframing is None:
            return None
        primary_id = intent["primary_subject_id"]
        primary = None
        secondary = []
        for s in ranked_subjects:
            if s["id"] == primary_id:
                primary = s
            else:
                secondary.append(s)
        if primary is None:
            return reframing
        pan = float(reframing["target_pan_offset"])
        tilt = float(reframing["target_tilt_offset"])
        zoom = float(reframing["target_zoom_factor"])
        secondary_com = self._secondary_center_of_mass(secondary)
        if secondary_com is not None and secondary:
            primary_center = np.array(
                [primary.get("cx", 0.5), primary.get("cy", 0.5)],
                dtype=np.float32,
            )
            delta = secondary_com - primary_center
            pan += (
                delta[0]
                * self._secondary_visibility_weight
                * self._center_pull_strength
            )
            tilt += (
                delta[1]
                * self._secondary_visibility_weight
                * self._center_pull_strength
            )
            zoom *= 1.0 - min(
                self._max_zoom_reduction,
                self._secondary_visibility_weight * len(secondary),
            )
        pan = float(np.clip(pan, -0.5, 0.5))
        tilt = float(np.clip(tilt, -0.45, 0.45))
        zoom = float(np.clip(zoom, 0.75, 2.0))
        return {
            "resolved_pan_offset": pan,
            "resolved_tilt_offset": tilt,
            "resolved_zoom_factor": zoom,
            "subject_lock_state": "primary_locked",
        }
# ==============================================================================
# END OF CHUNK 85 S 08
# ==============================================================================
# ==============================================================================
# CHUNK 85 S 09 — INTENT-TO-CAMERA PARAMETER MAPPING
# ==============================================================================
#
# Purpose:
#   Convert resolved framing decisions into concrete, device-agnostic
#   camera parameters (pan/tilt/zoom/exposure/stability hints) with
#   bounded rates and safety clamps suitable for real-time execution.
#
# Inputs:
#   - composition intent
#   - resolved framing (85 S 08)
#   - camera capabilities (limits, rates, latency)
#
# Outputs:
#   - camera_command (normalized + rate-limited)
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class IntentToCameraMapper:
    """
    Deterministic mapping from cinematic intent to executable
    camera commands with rate limits and clamps.
    """
    __slots__ = (
        "_pan_rate",
        "_tilt_rate",
        "_zoom_rate",
        "_exp_rate",
        "_pan_limits",
        "_tilt_limits",
        "_zoom_limits",
    )
    def __init__(
        self,
        pan_rate: float = 0.65,
        tilt_rate: float = 0.65,
        zoom_rate: float = 0.45,
        exp_rate: float = 0.35,
        pan_limits=(-0.6, 0.6),
        tilt_limits=(-0.5, 0.5),
        zoom_limits=(0.7, 2.2),
    ):
        """
        pan/tilt/zoom rates:
            Normalized rate caps per update (smooth, cinema-safe).
        limits:
            Hard mechanical / digital safety bounds.
        """
        self._pan_rate = float(pan_rate)
        self._tilt_rate = float(tilt_rate)
        self._zoom_rate = float(zoom_rate)
        self._exp_rate = float(exp_rate)
        self._pan_limits = tuple(pan_limits)
        self._tilt_limits = tuple(tilt_limits)
        self._zoom_limits = tuple(zoom_limits)
    def _rate_limit(self, target: float, current: float, rate: float) -> float:
        delta = target - current
        delta = np.clip(delta, -rate, rate)
        return float(current + delta)
    def _clamp(self, value: float, limits) -> float:
        return float(np.clip(value, limits[0], limits[1]))
    def map(
        self,
        intent: Dict,
        resolved: Dict,
        camera_state: Dict,
    ) -> Optional[Dict]:
        """
        Produce final camera command dict.
        """
        if intent is None or resolved is None:
            return None
        cur_pan = float(camera_state.get("pan", 0.0))
        cur_tilt = float(camera_state.get("tilt", 0.0))
        cur_zoom = float(camera_state.get("zoom", 1.0))
        cur_exp = float(camera_state.get("exposure_bias", 0.0))
        tgt_pan = float(resolved["resolved_pan_offset"])
        tgt_tilt = float(resolved["resolved_tilt_offset"])
        tgt_zoom = float(resolved["resolved_zoom_factor"])
        tgt_exp = float(intent.get("exposure_bias_hint", 0.0))
        pan = self._rate_limit(tgt_pan, cur_pan, self._pan_rate)
        tilt = self._rate_limit(tgt_tilt, cur_tilt, self._tilt_rate)
        zoom = self._rate_limit(tgt_zoom, cur_zoom, self._zoom_rate)
        exp = self._rate_limit(tgt_exp, cur_exp, self._exp_rate)
        pan = self._clamp(pan, self._pan_limits)
        tilt = self._clamp(tilt, self._tilt_limits)
        zoom = self._clamp(zoom, self._zoom_limits)
        exp = float(np.clip(exp, -0.5, 0.5))
        return {
            "pan": pan,
            "tilt": tilt,
            "zoom": zoom,
            "exposure_bias": exp,
            "stability_priority": intent.get("stability_priority", "medium"),
            "motion_hint": intent.get("camera_motion_hint", "static"),
        }
# ==============================================================================
# END OF CHUNK 85 S 09
# ==============================================================================
# ==============================================================================
# CHUNK 85 S 10 — FRAMING STABILITY VS MOTION TRADEOFF ENGINE
# ==============================================================================
#
# Purpose:
#   Dynamically balance framing stability against required camera motion.
#   Prevents over-stabilization (dead shots) and over-motion (jitter),
#   adapting to scene dynamics and cinematic intent.
#
# Inputs:
#   - camera_command (from 85 S 09)
#   - intent (composition intent)
#   - scene motion metrics
#   - subject velocity + acceleration
#
# Outputs:
#   - stabilized_camera_command
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class FramingStabilityMotionBalancer:
    """
    Adjusts camera motion aggressiveness based on scene dynamics
    and cinematic priority to ensure professional-grade smoothness.
    """
    __slots__ = (
        "_base_stability",
        "_motion_gain",
        "_accel_sensitivity",
        "_max_damping",
    )
    def __init__(
        self,
        base_stability: float = 0.6,
        motion_gain: float = 0.85,
        accel_sensitivity: float = 0.4,
        max_damping: float = 0.7,
    ):
        """
        base_stability:
            Baseline smoothing applied to all camera motion.
        motion_gain:
            How strongly intent-driven motion is allowed through.
        accel_sensitivity:
            Extra damping when subject acceleration spikes.
        max_damping:
            Upper bound on motion suppression.
        """
        self._base_stability = float(base_stability)
        self._motion_gain = float(motion_gain)
        self._accel_sensitivity = float(accel_sensitivity)
        self._max_damping = float(max_damping)
    def _compute_damping(
        self,
        scene_motion: float,
        subject_accel: float,
        stability_priority: str,
    ) -> float:
        damping = self._base_stability
        damping += scene_motion * (1.0 - self._motion_gain)
        damping += subject_accel * self._accel_sensitivity
        if stability_priority == "high":
            damping += 0.15
        return float(np.clip(damping, 0.0, self._max_damping))
    def balance(
        self,
        camera_command: Dict,
        intent: Dict,
        scene_metrics: Dict,
        subject_metrics: Dict,
    ) -> Optional[Dict]:
        """
        Apply adaptive damping to camera motion.
        """
        if camera_command is None:
            return None
        scene_motion = float(scene_metrics.get("motion", 0.0))
        subject_accel = float(subject_metrics.get("accel", 0.0))
        damping = self._compute_damping(
            scene_motion,
            subject_accel,
            intent.get("stability_priority", "medium"),
        )
        stabilized = {}
        for k in ("pan", "tilt", "zoom"):
            stabilized[k] = float(
                camera_command[k] * (1.0 - damping)
            )
        stabilized["exposure_bias"] = camera_command["exposure_bias"]
        stabilized["motion_damping"] = damping
        stabilized["motion_hint"] = camera_command.get("motion_hint", "static")
        return stabilized
# ==============================================================================
# END OF CHUNK 85 S 10
# ==============================================================================
# ==============================================================================
# CHUNK 85 T 01 — CAMERA AI TEMPORAL CONSISTENCY CORE
# ==============================================================================
#
# Purpose:
#   Enforce temporal coherence across frames so that composition,
#   framing, exposure intent, and motion decisions evolve smoothly
#   over time — preventing perceptible AI “decision jitter”.
#
# This module:
#   - Stabilizes intent transitions
#   - Dampens short-lived scene perturbations
#   - Preserves cinematic continuity across cuts and motion
#
# Inputs:
#   - current intent
#   - previous intent state
#   - frame delta time
#
# Outputs:
#   - temporally-consistent intent
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class CameraAITemporalConsistencyCore:
    """
    Provides first-order temporal smoothing and state continuity
    for AI-generated camera intent.
    """
    __slots__ = (
        "_intent_blend_rate",
        "_lock_duration",
        "_last_intent",
        "_lock_timer",
    )
    def __init__(
        self,
        intent_blend_rate: float = 0.18,
        lock_duration: float = 0.45,
    ):
        """
        intent_blend_rate:
            How quickly new intent overrides previous intent.
        lock_duration:
            Minimum time before allowing major intent switches.
        """
        self._intent_blend_rate = float(intent_blend_rate)
        self._lock_duration = float(lock_duration)
        self._last_intent: Optional[Dict] = None
        self._lock_timer: float = 0.0
    def _blend_scalar(self, prev: float, curr: float, alpha: float) -> float:
        return float(prev + (curr - prev) * alpha)
    def _blend_intent(self, prev: Dict, curr: Dict, alpha: float) -> Dict:
        blended = {}
        for k, v in curr.items():
            if isinstance(v, (int, float)) and k in prev:
                blended[k] = self._blend_scalar(prev[k], v, alpha)
            else:
                blended[k] = v
        return blended
    def update(
        self,
        current_intent: Dict,
        dt: float,
    ) -> Dict:
        """
        Apply temporal consistency to intent stream.
        """
        if self._last_intent is None:
            self._last_intent = current_intent
            self._lock_timer = 0.0
            return current_intent
        self._lock_timer += float(dt)
        alpha = self._intent_blend_rate
        if self._lock_timer < self._lock_duration:
            alpha *= 0.5
        smoothed = self._blend_intent(
            self._last_intent,
            current_intent,
            alpha,
        )
        self._last_intent = smoothed
        return smoothed
# ==============================================================================
# END OF CHUNK 85 T 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 T 02 — INTENT SMOOTHING & HYSTERESIS LOGIC
# ==============================================================================
#
# Purpose:
#   Prevent rapid intent oscillation when scene signals fluctuate
#   near decision boundaries (subject ranking, framing choice,
#   motion vs stability tradeoffs).
#
# This layer sits ABOVE temporal blending and enforces
# semantic stability (what the camera is trying to do).
#
# Inputs:
#   - proposed intent (per-frame)
#   - active intent state
#   - scene confidence metrics
#
# Outputs:
#   - accepted intent
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class IntentHysteresisController:
    """
    Applies hysteresis to semantic intent decisions so that
    small fluctuations do not cause visible behavioral changes.
    """
    __slots__ = (
        "_switch_threshold",
        "_release_threshold",
        "_confidence_weight",
        "_active_intent",
    )
    def __init__(
        self,
        switch_threshold: float = 0.22,
        release_threshold: float = 0.14,
        confidence_weight: float = 0.6,
    ):
        """
        switch_threshold:
            Required confidence delta to switch intent.
        release_threshold:
            Lower threshold to release locked intent.
        confidence_weight:
            How strongly scene confidence influences switching.
        """
        self._switch_threshold = float(switch_threshold)
        self._release_threshold = float(release_threshold)
        self._confidence_weight = float(confidence_weight)
        self._active_intent: Optional[Dict] = None
    def _intent_score(self, intent: Dict, scene_conf: float) -> float:
        """
        Compute scalar desirability score for an intent.
        """
        base = 0.0
        if intent.get("stability_priority") == "high":
            base += 0.2
        motion = intent.get("camera_motion_hint", "static")
        if motion in ("follow", "tracking"):
            base += 0.15
        base += scene_conf * self._confidence_weight
        return float(base)
    def update(
        self,
        proposed_intent: Dict,
        scene_confidence: float,
    ) -> Dict:
        """
        Decide whether to accept or reject a new intent.
        """
        if self._active_intent is None:
            self._active_intent = proposed_intent
            return proposed_intent
        prev_score = self._intent_score(
            self._active_intent, scene_confidence
        )
        new_score = self._intent_score(
            proposed_intent, scene_confidence
        )
        delta = new_score - prev_score
        if delta > self._switch_threshold:
            self._active_intent = proposed_intent
            return proposed_intent
        if delta < -self._release_threshold:
            self._active_intent = proposed_intent
            return proposed_intent
        # Hold previous intent
        return self._active_intent
