# ==============================================================================
# CHUNK 85 T 03 — CAMERA AI STATE MEMORY SYSTEM
# ==============================================================================
#
# Purpose:
#   Maintain persistent, interpretable camera AI state across time:
#   shot intent, subject lock, framing bias, exposure bias, and
#   motion context — enabling long cinematic shots and continuity.
#
# This is NOT a cache — it is a semantic memory layer.
#
# Inputs:
#   - accepted intent (post hysteresis & temporal smoothing)
#   - stabilized camera command
#   - scene metrics
#   - dt
#
# Outputs:
#   - updated camera_state
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class CameraAIStateMemory:
    """
    Persistent camera AI memory that evolves slowly over time
    and preserves cinematic continuity.
    """
    __slots__ = (
        "_state",
        "_decay_rate",
        "_confidence_decay",
    )
    def __init__(
        self,
        decay_rate: float = 0.12,
        confidence_decay: float = 0.08,
    ):
        """
        decay_rate:
            How quickly transient state fades.
        confidence_decay:
            How quickly confidence decays without reinforcement.
        """
        self._decay_rate = float(decay_rate)
        self._confidence_decay = float(confidence_decay)
        # Canonical camera AI state
        self._state: Dict = {
            "primary_subject_id": None,
            "shot_type": None,
            "framing_bias": np.zeros(2, dtype=np.float32),
            "exposure_bias": 0.0,
            "motion_style": "static",
            "confidence": 0.5,
            "time_in_state": 0.0,
        }
    def _decay(self, value: float, dt: float) -> float:
        return float(value * np.exp(-self._decay_rate * dt))
    def _blend(self, prev: float, new: float, alpha: float) -> float:
        return float(prev + (new - prev) * alpha)
    def update(
        self,
        intent: Dict,
        camera_command: Dict,
        scene_metrics: Dict,
        dt: float,
    ) -> Dict:
        """
        Update persistent camera AI state.
        """
        dt = float(max(dt, 1e-3))
        self._state["time_in_state"] += dt
        # Subject memory
        new_subject = intent.get("primary_subject_id")
        if new_subject != self._state["primary_subject_id"]:
            self._state["primary_subject_id"] = new_subject
            self._state["time_in_state"] = 0.0
        # Shot / motion style
        self._state["shot_type"] = intent.get(
            "framing_style", self._state["shot_type"]
        )
        self._state["motion_style"] = intent.get(
            "camera_motion_hint", self._state["motion_style"]
        )
        # Framing bias (pan/tilt memory)
        pan = float(camera_command.get("pan", 0.0))
        tilt = float(camera_command.get("tilt", 0.0))
        bias = self._state["framing_bias"]
        bias[0] = self._blend(bias[0], pan, 0.25)
        bias[1] = self._blend(bias[1], tilt, 0.25)
        # Exposure bias memory
        self._state["exposure_bias"] = self._blend(
            self._state["exposure_bias"],
            camera_command.get("exposure_bias", 0.0),
            0.18,
        )
        # Confidence update
        scene_conf = float(scene_metrics.get("confidence", 0.5))
        self._state["confidence"] = self._blend(
            self._state["confidence"],
            scene_conf,
            0.2,
        )
        # Passive decay
        self._state["confidence"] *= np.exp(
            -self._confidence_decay * dt
        )
        return dict(self._state)
# ==============================================================================
# END OF CHUNK 85 T 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 T 04 — CAMERA AI FAIL-SAFE REVERSION LOGIC
# ==============================================================================
#
# Purpose:
#   Provide deterministic, cinematic-safe fallback behavior when
#   AI confidence drops, perception becomes unstable, or intent
#   conflicts arise between internal/external cameras.
#
# This system NEVER hard-resets. It reverts gracefully to
# conservative, visually stable camera behavior.
#
# Inputs:
#   - camera_state (from State Memory)
#   - live perception confidence
#   - multi-camera consistency metrics
#
# Outputs:
#   - sanitized camera command
#
# ==============================================================================

import numpy as np
from typing import Dict


class CameraAIFailSafe:
    """
    Cinematic-safe fallback controller for camera AI.
    """
    __slots__ = (
        "_min_confidence",
        "_recovery_rate",
        "_last_safe_command",
    )
    def __init__(
        self,
        min_confidence: float = 0.35,
        recovery_rate: float = 0.15,
    ):
        """
        min_confidence:
            Below this, fail-safe logic engages.
        recovery_rate:
            Rate at which normal behavior is restored.
        """
        self._min_confidence = float(min_confidence)
        self._recovery_rate = float(recovery_rate)
        # Last known visually safe command
        self._last_safe_command: Dict = {
            "pan": 0.0,
            "tilt": 0.0,
            "roll": 0.0,
            "zoom": 1.0,
            "exposure_bias": 0.0,
            "motion_damping": 1.0,
        }
    def _soft_clamp(self, value: float, limit: float) -> float:
        """
        Soft-limit values to avoid abrupt motion.
        """
        return float(limit * np.tanh(value / max(limit, 1e-6)))
    def update(
        self,
        proposed_command: Dict,
        camera_state: Dict,
        perception_confidence: float,
        camera_consistency: float,
        dt: float,
    ) -> Dict:
        """
        Apply fail-safe logic if needed.
        """
        dt = float(max(dt, 1e-3))
        conf = float(perception_confidence)
        consistency = float(camera_consistency)
        # Determine if fail-safe should engage
        unsafe = (
            conf < self._min_confidence
            or consistency < 0.5
        )
        if unsafe:
            # Revert smoothly toward last safe command
            out = {}
            for k, v in self._last_safe_command.items():
                pv = float(proposed_command.get(k, v))
                out[k] = v + (pv - v) * 0.1
            # Increase damping aggressively
            out["motion_damping"] = min(
                2.0, out.get("motion_damping", 1.0) * 1.25
            )
            return out
        # Normal operation — update safe command memory
        out = {}
        for k, v in proposed_command.items():
            if isinstance(v, (int, float)):
                out[k] = self._soft_clamp(v, limit=3.0)
            else:
                out[k] = v
        # Blend safe memory back toward active command
        for k in self._last_safe_command.keys():
            self._last_safe_command[k] += (
                out.get(k, self._last_safe_command[k])
                - self._last_safe_command[k]
            ) * self._recovery_rate * dt
        return out
# ==============================================================================
# END OF CHUNK 85 T 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 T 05 — CAMERA AI CONFIDENCE SCORING ENGINE
# ==============================================================================
#
# Purpose:
#   Compute a physically and perceptually grounded confidence score
#   for camera AI decisions, used by fail-safe logic, arbitration,
#   and multi-camera fusion.
#
# Confidence reflects:
#   - Vision certainty (detections, tracking stability)
#   - Temporal coherence
#   - Exposure & motion sanity
#   - Cross-camera agreement
#
# Output is continuous [0.0 – 1.0], never binary.
#
# ==============================================================================

import numpy as np
from typing import Dict


class CameraAIConfidenceEngine:
    """
    Computes holistic confidence score for camera AI outputs.
    """
    __slots__ = (
        "_vision_weight",
        "_temporal_weight",
        "_exposure_weight",
        "_motion_weight",
        "_consistency_weight",
        "_ema_confidence",
    )
    def __init__(
        self,
        vision_weight: float = 0.30,
        temporal_weight: float = 0.20,
        exposure_weight: float = 0.15,
        motion_weight: float = 0.15,
        consistency_weight: float = 0.20,
    ):
        wsum = (
            vision_weight
            + temporal_weight
            + exposure_weight
            + motion_weight
            + consistency_weight
        )
        if abs(wsum - 1.0) > 1e-3:
            raise ValueError("CameraAIConfidenceEngine weights must sum to 1.0")
        self._vision_weight = float(vision_weight)
        self._temporal_weight = float(temporal_weight)
        self._exposure_weight = float(exposure_weight)
        self._motion_weight = float(motion_weight)
        self._consistency_weight = float(consistency_weight)
        # Exponential smoothing of confidence to avoid jitter
        self._ema_confidence = 1.0
    @staticmethod
    def _bounded(value: float) -> float:
        return float(np.clip(value, 0.0, 1.0))
    def update(
        self,
        vision_metrics: Dict,
        temporal_metrics: Dict,
        exposure_metrics: Dict,
        motion_metrics: Dict,
        consistency_metrics: Dict,
        dt: float,
    ) -> float:
        """
        Update confidence estimate.
        """
        dt = float(max(dt, 1e-3))
        # Vision confidence
        vision_conf = self._bounded(
            vision_metrics.get("track_stability", 1.0)
            * vision_metrics.get("detection_confidence", 1.0)
        )
        # Temporal coherence (low jitter, low jumps)
        temporal_conf = self._bounded(
            1.0 - temporal_metrics.get("temporal_error", 0.0)
        )
        # Exposure sanity (avoid clipping, pumping)
        exposure_conf = self._bounded(
            1.0
            - max(
                exposure_metrics.get("highlight_clip", 0.0),
                exposure_metrics.get("shadow_crush", 0.0),
            )
        )
        # Motion realism (avoid excessive angular velocity)
        motion_conf = self._bounded(
            1.0 - motion_metrics.get("excess_motion", 0.0)
        )
        # Multi-camera agreement
        consistency_conf = self._bounded(
            consistency_metrics.get("agreement", 1.0)
        )
        raw_conf = (
            vision_conf * self._vision_weight
            + temporal_conf * self._temporal_weight
            + exposure_conf * self._exposure_weight
            + motion_conf * self._motion_weight
            + consistency_conf * self._consistency_weight
        )
        # Smooth confidence evolution
        alpha = 1.0 - np.exp(-dt * 4.0)
        self._ema_confidence += (raw_conf - self._ema_confidence) * alpha
        return self._bounded(self._ema_confidence)
# ==============================================================================
# END OF CHUNK 85 T 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 T 06 — MULTI-CAMERA SYNCHRONIZATION CORE
# ==============================================================================
#
# Purpose:
#   Provide deterministic temporal, spatial, and perceptual alignment
#   between multiple camera streams (e.g., GoPro + internal reference).
#
# Guarantees:
#   - Frame-time alignment (latency-aware)
#   - Motion-consistent transforms
#   - Confidence-weighted fusion
#   - No hard snapping; cinematic continuity preserved
#
# ==============================================================================

import numpy as np
from typing import Dict, Tuple


class MultiCameraSyncCore:
    """
    Synchronizes multiple camera streams into a coherent
    cinematic reference space.
    """
    __slots__ = (
        "_latency_ema",
        "_sync_strength",
        "_max_time_skew",
    )
    def __init__(
        self,
        sync_strength: float = 0.85,
        max_time_skew_ms: float = 35.0,
    ):
        """
        sync_strength:
            Blending factor between cameras (0–1).
        max_time_skew_ms:
            Maximum tolerated temporal skew before damping.
        """
        self._sync_strength = float(np.clip(sync_strength, 0.0, 1.0))
        self._max_time_skew = float(max_time_skew_ms) * 1e-3
        # Track average latency per camera pair
        self._latency_ema: Dict[Tuple[str, str], float] = {}
    @staticmethod
    def _lerp(a: float, b: float, t: float) -> float:
        return float(a + (b - a) * t)
    def _update_latency(
        self,
        cam_a: str,
        cam_b: str,
        measured_skew: float,
        dt: float,
    ) -> float:
        """
        Update EMA latency estimate between two cameras.
        """
        key = (cam_a, cam_b)
        prev = self._latency_ema.get(key, measured_skew)
        alpha = 1.0 - np.exp(-dt * 2.5)
        cur = prev + (measured_skew - prev) * alpha
        self._latency_ema[key] = cur
        return cur
    def synchronize(
        self,
        cam_a_state: Dict,
        cam_b_state: Dict,
        cam_a_name: str,
        cam_b_name: str,
        dt: float,
    ) -> Dict:
        """
        Produce synchronized camera state.
        """
        dt = float(max(dt, 1e-3))
        # Extract timestamps
        t_a = float(cam_a_state.get("timestamp", 0.0))
        t_b = float(cam_b_state.get("timestamp", 0.0))
        skew = t_a - t_b
        # Update latency model
        avg_skew = self._update_latency(
            cam_a_name, cam_b_name, skew, dt
        )
        # Compute skew factor
        skew_mag = abs(avg_skew)
        skew_factor = np.clip(
            1.0 - skew_mag / max(self._max_time_skew, 1e-6),
            0.0,
            1.0,
        )
        # Confidence-weighted blend
        conf_a = float(cam_a_state.get("confidence", 1.0))
        conf_b = float(cam_b_state.get("confidence", 1.0))
        w_sum = conf_a + conf_b + 1e-6
        w_a = conf_a / w_sum
        w_b = conf_b / w_sum
        # Apply synchronization strength
        w_a = self._lerp(w_a, 0.5, self._sync_strength * (1.0 - skew_factor))
        w_b = 1.0 - w_a
        synced: Dict = {}
        # Blend common cinematic parameters
        for key in (
            "pan",
            "tilt",
            "roll",
            "zoom",
            "exposure_bias",
            "motion_damping",
        ):
            va = float(cam_a_state.get(key, 0.0))
            vb = float(cam_b_state.get(key, 0.0))
            synced[key] = self._lerp(va, vb, w_b)
        # Temporal stamp uses dominant confidence camera
        synced["timestamp"] = (
            t_a if conf_a >= conf_b else t_b
        )
        # Combined confidence reflects agreement
        synced["confidence"] = float(
            np.clip(
                min(conf_a, conf_b) * skew_factor
                + max(conf_a, conf_b) * 0.25,
                0.0,
                1.0,
            )
        )
        # Record diagnostics
        synced["sync_skew_sec"] = avg_skew
        synced["sync_quality"] = skew_factor
        return synced
