# ==============================================================================
# CHUNK 85 U 01 — CAMERA AI PERCEPTION ↔ CONTROL BRIDGE
# ==============================================================================
#
# Purpose:
#   Translate high-level perception outputs (subjects, saliency,
#   motion cues) into stable, normalized control intents consumed
#   by downstream camera and flight logic.
#
# Design principles:
#   - Deterministic mapping (no hidden state explosions)
#   - Confidence-aware attenuation
#   - Cinematic continuity over reactivity
#
# Inputs:
#   - perception_state (vision + tracking outputs)
#   - confidence (from CameraAIConfidenceEngine)
#
# Outputs:
#   - control_intent (pan/tilt/zoom/exposure intent space)
#
# ==============================================================================

import numpy as np
from typing import Dict


class CameraAIPerceptionControlBridge:
    """
    Converts perception-level understanding into normalized
    camera control intent.
    """
    __slots__ = (
        "_max_pan_rate",
        "_max_tilt_rate",
        "_max_zoom_rate",
        "_intent_smoothing",
        "_last_intent",
    )
    def __init__(
        self,
        max_pan_rate: float = 1.25,
        max_tilt_rate: float = 1.10,
        max_zoom_rate: float = 0.75,
        intent_smoothing: float = 0.18,
    ):
        """
        max_*_rate:
            Maximum normalized change per second.
        intent_smoothing:
            EMA smoothing for cinematic continuity.
        """
        self._max_pan_rate = float(max_pan_rate)
        self._max_tilt_rate = float(max_tilt_rate)
        self._max_zoom_rate = float(max_zoom_rate)
        self._intent_smoothing = float(np.clip(intent_smoothing, 0.0, 1.0))
        self._last_intent: Dict = {
            "pan": 0.0,
            "tilt": 0.0,
            "zoom": 1.0,
            "exposure_bias": 0.0,
        }
    @staticmethod
    def _soft_limit(value: float, limit: float) -> float:
        return float(limit * np.tanh(value / max(limit, 1e-6)))
    def _derive_pan_tilt(
        self,
        subject_offset: Dict,
    ) -> Dict:
        """
        Convert subject screen offset to pan/tilt intent.
        """
        dx = float(subject_offset.get("x", 0.0))
        dy = float(subject_offset.get("y", 0.0))
        pan = self._soft_limit(dx, self._max_pan_rate)
        tilt = self._soft_limit(-dy, self._max_tilt_rate)
        return {"pan": pan, "tilt": tilt}
    def _derive_zoom(
        self,
        subject_scale: float,
    ) -> float:
        """
        Convert subject size to zoom intent.
        """
        target_zoom = 1.0 / max(subject_scale, 1e-3)
        return self._soft_limit(
            target_zoom - 1.0,
            self._max_zoom_rate,
        ) + 1.0
    def update(
        self,
        perception_state: Dict,
        confidence: float,
        dt: float,
    ) -> Dict:
        """
        Compute camera control intent.
        """
        dt = float(max(dt, 1e-3))
        conf = float(np.clip(confidence, 0.0, 1.0))
        subject = perception_state.get("primary_subject", {})
        # Derive base intents
        pan_tilt = self._derive_pan_tilt(
            subject.get("screen_offset", {})
        )
        zoom = self._derive_zoom(
            subject.get("scale", 1.0)
        )
        exposure_bias = float(
            perception_state.get("exposure_suggestion", 0.0)
        )
        # Confidence attenuation
        pan = pan_tilt["pan"] * conf
        tilt = pan_tilt["tilt"] * conf
        zoom = 1.0 + (zoom - 1.0) * conf
        exposure_bias *= conf
        raw_intent = {
            "pan": pan,
            "tilt": tilt,
            "zoom": zoom,
            "exposure_bias": exposure_bias,
        }
        # Smooth intent for cinematic continuity
        alpha = 1.0 - np.exp(-dt / max(self._intent_smoothing, 1e-6))
        out: Dict = {}
        for k, v in raw_intent.items():
            prev = self._last_intent.get(k, v)
            out[k] = prev + (v - prev) * alpha
        self._last_intent.update(out)
        return out
