# ==============================================================================
# CHUNK 85 U 02 — CAMERA AI → DRONE MOTION INTENT INTERFACE
# ==============================================================================
#
# Purpose:
#   Convert stabilized camera control intent into drone motion intent
#   (velocity + yaw-rate) in a safety-aware, cinematic-first manner.
#
# Guarantees:
#   - No direct motor/ESC control
#   - Bounded, smooth velocity intents
#   - Camera-led cinematography (drone follows the shot, not vice versa)
#
# Outputs:
#   - motion_intent dict suitable for ArduPilot velocity/yaw interfaces
#
# ==============================================================================

import numpy as np
from typing import Dict


class CameraToDroneMotionInterface:
    """
    Translates camera intent into drone motion intent
    using cinematic heuristics and physical constraints.
    """
    __slots__ = (
        "_max_xy_vel",
        "_max_z_vel",
        "_max_yaw_rate",
        "_pan_to_yaw_gain",
        "_tilt_to_z_gain",
        "_damping_gain",
        "_last_motion",
    )
    def __init__(
        self,
        max_xy_velocity: float = 3.5,
        max_z_velocity: float = 1.2,
        max_yaw_rate: float = 45.0,
        pan_to_yaw_gain: float = 0.85,
        tilt_to_z_gain: float = 0.65,
        damping_gain: float = 0.75,
    ):
        """
        max_*:
            Physical velocity limits (m/s, deg/s).
        *_gain:
            Cinematic mapping coefficients.
        """
        self._max_xy_vel = float(max_xy_velocity)
        self._max_z_vel = float(max_z_velocity)
        self._max_yaw_rate = float(max_yaw_rate)
        self._pan_to_yaw_gain = float(pan_to_yaw_gain)
        self._tilt_to_z_gain = float(tilt_to_z_gain)
        self._damping_gain = float(np.clip(damping_gain, 0.0, 1.0))
        self._last_motion: Dict = {
            "vx": 0.0,
            "vy": 0.0,
            "vz": 0.0,
            "yaw_rate": 0.0,
        }
    @staticmethod
    def _limit(value: float, limit: float) -> float:
        return float(limit * np.tanh(value / max(limit, 1e-6)))
    def update(
        self,
        camera_intent: Dict,
        confidence: float,
        dt: float,
    ) -> Dict:
        """
        Generate drone motion intent from camera intent.
        """
        dt = float(max(dt, 1e-3))
        conf = float(np.clip(confidence, 0.0, 1.0))
        # Extract camera intent
        pan = float(camera_intent.get("pan", 0.0))
        tilt = float(camera_intent.get("tilt", 0.0))
        zoom = float(camera_intent.get("zoom", 1.0))
        damping = float(camera_intent.get("motion_damping", 1.0))
        # Cinematic yaw follows pan
        yaw_rate = (
            pan * self._pan_to_yaw_gain * self._max_yaw_rate
        )
        # Vertical motion follows tilt (subtle)
        vz = (
            tilt * self._tilt_to_z_gain * self._max_z_vel
        )
        # Forward/back motion modulated by zoom intent
        vx = (1.0 - zoom) * self._max_xy_vel * 0.6
        vy = 0.0
        # Apply confidence attenuation
        vx *= conf
        vy *= conf
        vz *= conf
        yaw_rate *= conf
        # Soft-limit physical outputs
        vx = self._limit(vx, self._max_xy_vel)
        vy = self._limit(vy, self._max_xy_vel)
        vz = self._limit(vz, self._max_z_vel)
        yaw_rate = self._limit(yaw_rate, self._max_yaw_rate)
        # Damping for cinematic smoothness
        damp = self._damping_gain * damping
        alpha = 1.0 - np.exp(-dt * damp)
        out: Dict = {}
        for k, v in (
            ("vx", vx),
            ("vy", vy),
            ("vz", vz),
            ("yaw_rate", yaw_rate),
        ):
            prev = self._last_motion.get(k, v)
            out[k] = prev + (v - prev) * alpha
        self._last_motion.update(out)
        # Mark intent type for downstream safety layers
        out["intent_type"] = "cinematic_velocity"
        return out
