import numpy as np
from typing import Dict


class AIShotTypeArbitrationEngine:
    """
    High-level cinematic shot selector.
    """
    __slots__ = (
        "_shot_bias",
        "_shot_hysteresis",
        "_last_shot",
        "_last_score",
    )
    def __init__(
        self,
        shot_hysteresis: float = 0.25,
    ):
        """
        shot_hysteresis:
            Resistance to switching shots (0–1).
        """
        self._shot_hysteresis = float(np.clip(shot_hysteresis, 0.0, 1.0))
        # Film-grammar bias weights
        self._shot_bias: Dict[str, float] = {
            "wide": 1.0,
            "medium": 1.1,
            "close": 0.9,
            "orbit": 0.8,
            "reveal": 0.7,
            "lockoff": 0.6,
        }
        self._last_shot: str = "medium"
        self._last_score: float = 0.0
    def _score_shots(
        self,
        perception: Dict,
        confidence: float,
    ) -> Dict[str, float]:
        """
        Compute raw desirability scores for each shot type.
        """
        subject = perception.get("primary_subject", {})
        scale = float(subject.get("scale", 1.0))
        motion = float(subject.get("motion_energy", 0.0))
        context = perception.get("scene_context", {})
        scores: Dict[str, float] = {}
        # Wide shots favor context + low motion
        scores["wide"] = (
            (1.0 - scale)
            * (1.0 - motion)
            * context.get("environment_openness", 0.5)
        )
        # Medium shots are default narrative workhorse
        scores["medium"] = (
            (1.0 - abs(scale - 0.5))
            * (1.0 - motion * 0.5)
        )
        # Close shots favor large subject scale + stability
        scores["close"] = (
            scale * (1.0 - motion)
        )
        # Orbit shots favor stable subject + high confidence
        scores["orbit"] = (
            confidence * (1.0 - motion) * 0.8
        )
        # Reveal shots favor entering subjects
        scores["reveal"] = (
            context.get("occlusion_level", 0.0)
            * confidence
        )
        # Lock-off shots favor very high stability
        scores["lockoff"] = (
            (1.0 - motion) * confidence
        )
        # Apply film bias
        for k in scores:
            scores[k] *= self._shot_bias.get(k, 1.0)
        return scores
    def update(
        self,
        perception_state: Dict,
        confidence: float,
        dt: float,
    ) -> Dict:
        """
        Select active shot type.
        """
        dt = float(max(dt, 1e-3))
        conf = float(np.clip(confidence, 0.0, 1.0))
        scores = self._score_shots(perception_state, conf)
        # Select best candidate
        best_shot = max(scores, key=scores.get)
        best_score = float(scores[best_shot])
        # Apply hysteresis to prevent rapid switching
        if best_shot != self._last_shot:
            if best_score < self._last_score * (1.0 + self._shot_hysteresis):
                best_shot = self._last_shot
                best_score = self._last_score
        self._last_shot = best_shot
        self._last_score = best_score
        return {
            "shot_type": best_shot,
            "shot_score": best_score,
        }
