# ==============================================================================
# CHUNK 85 U 04 — SUBJECT PRIORITY & INTENT WEIGHTING
# ==============================================================================
#
# Purpose:
#   Resolve multiple detected subjects into a single, stable
#   cinematic focus by computing priority weights and blending
#   their intents according to film grammar and temporal stability.
#
# Inputs:
#   - subjects: list of subject descriptors (id, saliency, scale, motion)
#   - global intent hints (from shot arbitration)
#
# Outputs:
#   - primary_subject
#   - blended_intent_weights
#
# ==============================================================================

import numpy as np
from typing import Dict, List


class SubjectPriorityIntentWeighter:
    """
    Computes priority scores for multiple subjects and blends
    their influence into a single cinematic intent.
    """
    __slots__ = (
        "_saliency_weight",
        "_scale_weight",
        "_motion_weight",
        "_temporal_weight",
        "_ema_priority",
    )
    def __init__(
        self,
        saliency_weight: float = 0.40,
        scale_weight: float = 0.25,
        motion_weight: float = 0.20,
        temporal_weight: float = 0.15,
    ):
        wsum = (
            saliency_weight
            + scale_weight
            + motion_weight
            + temporal_weight
        )
        if abs(wsum - 1.0) > 1e-3:
            raise ValueError("SubjectPriorityIntentWeighter weights must sum to 1.0")
        self._saliency_weight = float(saliency_weight)
        self._scale_weight = float(scale_weight)
        self._motion_weight = float(motion_weight)
        self._temporal_weight = float(temporal_weight)
        # Track EMA priority per subject id
        self._ema_priority: Dict[str, float] = {}
    @staticmethod
    def _bounded(v: float) -> float:
        return float(np.clip(v, 0.0, 1.0))
    def _score_subject(
        self,
        subj: Dict,
    ) -> float:
        """
        Compute instantaneous priority score for a subject.
        """
        sal = self._bounded(subj.get("saliency", 0.0))
        scale = self._bounded(subj.get("scale", 0.0))
        motion = self._bounded(1.0 - subj.get("motion_energy", 0.0))
        return (
            sal * self._saliency_weight
            + scale * self._scale_weight
            + motion * self._motion_weight
        )
    def update(
        self,
        subjects: List[Dict],
        dt: float,
    ) -> Dict:
        """
        Resolve primary subject and intent weights.
        """
        dt = float(max(dt, 1e-3))
        if not subjects:
            return {
                "primary_subject": None,
                "weights": {},
            }
        scores: Dict[str, float] = {}
        for subj in subjects:
            sid = str(subj.get("id"))
            raw = self._score_subject(subj)
            # Temporal smoothing per subject
            prev = self._ema_priority.get(sid, raw)
            alpha = 1.0 - np.exp(-dt * 3.0)
            ema = prev + (raw - prev) * alpha
            self._ema_priority[sid] = ema
            scores[sid] = ema
        # Normalize weights
        total = sum(scores.values()) + 1e-6
        weights = {k: v / total for k, v in scores.items()}
        # Select primary subject
        primary_id = max(weights, key=weights.get)
        primary_subject = next(
            s for s in subjects if str(s.get("id")) == primary_id
        )
        return {
            "primary_subject": primary_subject,
            "weights": weights,
        }
# ==============================================================================
# END OF CHUNK 85 U 04
