# ==============================================================================
# CHUNK 85 U 05 — CINEMATIC CONSTRAINT SOLVER
# ==============================================================================
#
# Purpose:
#   Enforce cinematic, physical, and perceptual constraints on
#   camera + motion intents before execution.
#
# Constraints enforced:
#   - Maximum angular velocity / acceleration
#   - Horizon stability & roll suppression
#   - Exposure continuity limits
#   - Shot-type–specific framing bounds
#
# This solver NEVER hard-clips unless absolutely necessary;
# it prefers smooth projection into feasible space.
#
# ==============================================================================

import numpy as np
from typing import Dict


class CinematicConstraintSolver:
    """
    Projects camera and motion intents into a
    cinematically valid constraint space.
    """
    __slots__ = (
        "_max_pan",
        "_max_tilt",
        "_max_roll",
        "_max_exposure_delta",
        "_shot_constraints",
        "_last_state",
    )
    def __init__(
        self,
        max_pan: float = 1.5,
        max_tilt: float = 1.2,
        max_roll: float = 0.4,
        max_exposure_delta: float = 0.35,
    ):
        """
        max_*:
            Absolute cinematic limits per frame.
        """
        self._max_pan = float(max_pan)
        self._max_tilt = float(max_tilt)
        self._max_roll = float(max_roll)
        self._max_exposure_delta = float(max_exposure_delta)
        # Shot-type–specific soft bounds
        self._shot_constraints: Dict[str, Dict] = {
            "wide":   {"zoom_min": 0.6, "zoom_max": 1.2},
            "medium": {"zoom_min": 0.9, "zoom_max": 1.8},
            "close":  {"zoom_min": 1.4, "zoom_max": 3.5},
            "orbit":  {"zoom_min": 1.1, "zoom_max": 2.2},
            "reveal": {"zoom_min": 0.8, "zoom_max": 1.6},
            "lockoff":{"zoom_min": 0.8, "zoom_max": 1.3},
        }
        self._last_state: Dict = {
            "pan": 0.0,
            "tilt": 0.0,
            "roll": 0.0,
            "zoom": 1.0,
            "exposure_bias": 0.0,
        }
    @staticmethod
    def _soft_limit(value: float, limit: float) -> float:
        return float(limit * np.tanh(value / max(limit, 1e-6)))
    def apply(
        self,
        intent: Dict,
        shot_type: str,
        dt: float,
    ) -> Dict:
        """
        Apply cinematic constraints to intent.
        """
        dt = float(max(dt, 1e-3))
        pan = self._soft_limit(
            float(intent.get("pan", 0.0)), self._max_pan
        )
        tilt = self._soft_limit(
            float(intent.get("tilt", 0.0)), self._max_tilt
        )
        roll = self._soft_limit(
            float(intent.get("roll", 0.0)), self._max_roll
        )
        # Exposure continuity constraint
        exp = float(intent.get("exposure_bias", 0.0))
        prev_exp = self._last_state["exposure_bias"]
        exp_delta = np.clip(
            exp - prev_exp,
            -self._max_exposure_delta,
            self._max_exposure_delta,
        )
        exp = prev_exp + exp_delta
        # Shot-specific zoom bounds
        zoom = float(intent.get("zoom", 1.0))
        sc = self._shot_constraints.get(shot_type, {})
        zmin = sc.get("zoom_min", 0.5)
        zmax = sc.get("zoom_max", 4.0)
        zoom = float(np.clip(zoom, zmin, zmax))
        # Temporal smoothing to avoid constraint snapping
        alpha = 1.0 - np.exp(-dt * 5.0)
        out = {
            "pan": self._last_state["pan"] + (pan - self._last_state["pan"]) * alpha,
            "tilt": self._last_state["tilt"] + (tilt - self._last_state["tilt"]) * alpha,
            "roll": self._last_state["roll"] + (roll - self._last_state["roll"]) * alpha,
            "zoom": self._last_state["zoom"] + (zoom - self._last_state["zoom"]) * alpha,
            "exposure_bias": exp,
        }
        self._last_state.update(out)
        return out
