# ==============================================================================
# CHUNK 85 V 01 — AI SHOT TEMPORAL ORCHESTRATION
# ==============================================================================
#
# Purpose:
#   Coordinate shot evolution across time, enforcing minimum
#   shot durations, controlled transitions, and narrative pacing.
#
# This module operates at a higher temporal scale than frame-level
# control, ensuring shots feel intentional rather than reactive.
#
# Inputs:
#   - current_shot_type
#   - shot_score
#   - confidence
#
# Outputs:
#   - active_shot_type (possibly delayed)
#   - transition_state
#
# ==============================================================================

import numpy as np
from typing import Dict


class AIShotTemporalOrchestrator:
    """
    Enforces cinematic timing rules on shot selection.
    """
    __slots__ = (
        "_min_shot_duration",
        "_transition_time",
        "_time_in_shot",
        "_active_shot",
        "_pending_shot",
    )
    def __init__(
        self,
        min_shot_duration: float = 2.0,
        transition_time: float = 0.6,
    ):
        """
        min_shot_duration:
            Minimum time (sec) before switching shots.
        transition_time:
            Duration of cinematic transitions.
        """
        self._min_shot_duration = float(min_shot_duration)
        self._transition_time = float(transition_time)
        self._time_in_shot = 0.0
        self._active_shot: str = None
        self._pending_shot: str = None
    def update(
        self,
        proposed_shot: str,
        shot_score: float,
        confidence: float,
        dt: float,
    ) -> Dict:
        """
        Update temporal orchestration state.
        """
        dt = float(max(dt, 1e-3))
        conf = float(np.clip(confidence, 0.0, 1.0))
        # Initialize on first call
        if self._active_shot is None:
            self._active_shot = proposed_shot
            self._time_in_shot = 0.0
            return {
                "shot_type": self._active_shot,
                "transition": None,
            }
        self._time_in_shot += dt
        # Determine if transition is allowed
        can_switch = (
            self._time_in_shot >= self._min_shot_duration
            and conf > 0.4
        )
        if proposed_shot != self._active_shot and can_switch:
            # Initiate transition
            self._pending_shot = proposed_shot
            self._time_in_shot = 0.0
            return {
                "shot_type": self._active_shot,
                "transition": {
                    "to": proposed_shot,
                    "duration": self._transition_time,
                    "score": shot_score,
                },
            }
        # Complete transition if pending
        if self._pending_shot is not None:
            self._active_shot = self._pending_shot
            self._pending_shot = None
        return {
            "shot_type": self._active_shot,
            "transition": None,
        }
# ==============================================================================
# END OF CHUNK 85 V 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 V 02 — SHOT TRANSITION SMOOTHNESS MODEL
# ==============================================================================
#
# Purpose:
#   Model perceptually smooth cinematic transitions between shots.
#   Controls spatial, exposure, and semantic continuity during transitions.
#
# This layer operates AFTER shot orchestration but BEFORE frame synthesis,
# ensuring that transitions feel deliberate (film-editor-like), not abrupt.
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class ShotTransitionSmoothnessModel:
    """
    Computes smooth interpolation curves for cinematic shot transitions.
    """
    __slots__ = (
        "_transition_progress",
        "_transition_duration",
        "_active",
        "_curve_type",
    )
    def __init__(self, curve_type: str = "cosine"):
        """
        curve_type:
            'linear', 'cosine', or 'sigmoid'
        """
        self._transition_progress = 0.0
        self._transition_duration = 1.0
        self._active = False
        self._curve_type = curve_type
    def start(self, duration: float):
        """
        Initialize a new transition.
        """
        self._transition_duration = max(float(duration), 1e-3)
        self._transition_progress = 0.0
        self._active = True
    def _curve(self, t: float) -> float:
        """
        Perceptual transition curves.
        """
        t = float(np.clip(t, 0.0, 1.0))
        if self._curve_type == "linear":
            return t
        if self._curve_type == "sigmoid":
            return 1.0 / (1.0 + np.exp(-12.0 * (t - 0.5)))
        # Default: cosine (film-editor preferred)
        return 0.5 - 0.5 * np.cos(np.pi * t)
    def update(
        self,
        dt: float,
        prev_params: Dict[str, float],
        next_params: Dict[str, float],
    ) -> Dict[str, float]:
        """
        Blend parameters between shots.
        prev_params / next_params examples:
            {
                "exposure": float,
                "zoom": float,
                "pan": float,
                "tilt": float,
            }
        """
        if not self._active:
            return prev_params
        dt = float(max(dt, 1e-3))
        self._transition_progress += dt / self._transition_duration
        alpha = self._curve(self._transition_progress)
        blended = {}
        for key in prev_params.keys():
            a = float(prev_params[key])
            b = float(next_params.get(key, a))
            blended[key] = (1.0 - alpha) * a + alpha * b
        if self._transition_progress >= 1.0:
            self._active = False
        return blended
