# END OF CHUNK 85 V 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 V 03 — NARRATIVE RHYTHM CONTROLLER
# ==============================================================================
#
# Purpose:
#   Enforce film-editor-grade narrative pacing across shots.
#   Balances motion energy, shot duration, exposure drift, and semantic density
#   to avoid monotony or chaos while sustaining cinematic tension.
#
# Operates above individual shots, below scene orchestration.
#
# ==============================================================================

import numpy as np
from typing import Dict, List, Optional


class NarrativeRhythmController:
    """
    Maintains narrative pacing using perceptual energy metrics.
    """
    __slots__ = (
        "_energy_window",
        "_target_energy",
        "_decay",
        "_history",
    )
    def __init__(
        self,
        energy_window: int = 48,
        target_energy: float = 0.55,
        decay: float = 0.92,
    ):
        """
        energy_window:
            Number of frames used to compute local rhythm.
        target_energy:
            Desired perceptual energy (0..1).
        decay:
            Temporal decay for historical influence.
        """
        self._energy_window = int(max(energy_window, 4))
        self._target_energy = float(np.clip(target_energy, 0.1, 0.9))
        self._decay = float(np.clip(decay, 0.8, 0.99))
        self._history: List[float] = []
    def _compute_energy(
        self,
        motion: float,
        cut_frequency: float,
        semantic_density: float,
    ) -> float:
        """
        Combine perceptual contributors into a single energy scalar.
        """
        motion = float(np.clip(motion, 0.0, 1.0))
        cut_frequency = float(np.clip(cut_frequency, 0.0, 1.0))
        semantic_density = float(np.clip(semantic_density, 0.0, 1.0))
        # Motion dominates rhythm perception, semantics second, cuts last
        return (
            0.55 * motion +
            0.30 * semantic_density +
            0.15 * cut_frequency
        )
    def update(
        self,
        motion: float,
        cut_frequency: float,
        semantic_density: float,
    ) -> Dict[str, float]:
        """
        Update rhythm state and return corrective multipliers.
        Returns:
            {
                "duration_scale": float,
                "motion_damping": float,
                "exposure_slew_limit": float,
            }
        """
        energy = self._compute_energy(
            motion,
            cut_frequency,
            semantic_density,
        )
        # Update history with decay
        if not self._history:
            self._history.append(energy)
        else:
            prev = self._history[-1]
            self._history.append(self._decay * prev + (1.0 - self._decay) * energy)
        # Trim history
        if len(self._history) > self._energy_window:
            self._history = self._history[-self._energy_window :]
        avg_energy = float(np.mean(self._history))
        # Deviation from target
        delta = avg_energy - self._target_energy
        # Convert deviation to cinematic controls
        duration_scale = float(np.clip(1.0 - 0.6 * delta, 0.65, 1.45))
        motion_damping = float(np.clip(1.0 - 0.8 * delta, 0.4, 1.2))
        exposure_slew_limit = float(np.clip(1.0 - 0.5 * abs(delta), 0.5, 1.0))
        return {
            "duration_scale": duration_scale,
            "motion_damping": motion_damping,
            "exposure_slew_limit": exposure_slew_limit,
        }
# ==============================================================================
# END OF CHUNK 85 V 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 V 04 — LONG-HORIZON SHOT PLANNING
# ==============================================================================
#
# Purpose:
#   Enable the AI to reason across extended temporal horizons (seconds → minutes),
#   selecting shots that form coherent cinematic arcs rather than isolated moments.
#
# This module predicts narrative payoff, motion fatigue, and visual redundancy,
# guiding shot selection well ahead of real-time execution.
#
# ==============================================================================

import numpy as np
from typing import Dict, List


class LongHorizonShotPlanner:
    """
    Plans shot sequences using forward-looking cinematic valuation.
    """
    __slots__ = (
        "_horizon",
        "_fatigue_decay",
        "_shot_memory",
        "_semantic_memory",
    )
    def __init__(
        self,
        horizon_seconds: float = 20.0,
        fatigue_decay: float = 0.93,
    ):
        """
        horizon_seconds:
            Lookahead window for planning (perceptual time, not hard time).
        fatigue_decay:
            How fast visual fatigue dissipates.
        """
        self._horizon = float(max(horizon_seconds, 5.0))
        self._fatigue_decay = float(np.clip(fatigue_decay, 0.85, 0.99))
        self._shot_memory: List[Dict[str, float]] = []
        self._semantic_memory: Dict[str, float] = {}
    def _update_fatigue(self):
        """
        Apply temporal decay to accumulated fatigue.
        """
        for entry in self._shot_memory:
            entry["fatigue"] *= self._fatigue_decay
        # Prune near-zero fatigue
        self._shot_memory = [
            e for e in self._shot_memory if e["fatigue"] > 1e-3
        ]
    def register_shot(
        self,
        shot_type: str,
        semantic_tag: str,
        intensity: float,
    ):
        """
        Record an executed shot to influence future planning.
        """
        intensity = float(np.clip(intensity, 0.0, 1.0))
        self._shot_memory.append(
            {
                "type": shot_type,
                "fatigue": intensity,
            }
        )
        self._semantic_memory[semantic_tag] = (
            self._semantic_memory.get(semantic_tag, 0.0) * self._fatigue_decay
            + intensity
        )
    def score_candidate(
        self,
        shot_type: str,
        semantic_tag: str,
        expected_motion: float,
        expected_emotion: float,
    ) -> float:
        """
        Compute long-horizon desirability score for a candidate shot.
        """
        expected_motion = float(np.clip(expected_motion, 0.0, 1.0))
        expected_emotion = float(np.clip(expected_emotion, 0.0, 1.0))
        # Base cinematic value
        value = 0.6 * expected_emotion + 0.4 * expected_motion
        # Penalize repetition fatigue
        for entry in self._shot_memory:
            if entry["type"] == shot_type:
                value -= 0.5 * entry["fatigue"]
        # Penalize semantic overuse
        semantic_fatigue = self._semantic_memory.get(semantic_tag, 0.0)
        value -= 0.4 * semantic_fatigue
        return float(np.clip(value, 0.0, 1.0))
    def select_next_shot(
        self,
        candidates: List[Dict[str, float]],
    ) -> Dict[str, float]:
        """
        Select the best next shot from candidates.
        Each candidate dict must include:
            {
                "shot_type": str,
                "semantic_tag": str,
                "expected_motion": float,
                "expected_emotion": float
            }
        """
        self._update_fatigue()
        best_score = -1.0
        best = None
        for c in candidates:
            score = self.score_candidate(
                c["shot_type"],
                c["semantic_tag"],
                c["expected_motion"],
                c["expected_emotion"],
            )
            if score > best_score:
                best_score = score
                best = c
        return best
