# ==============================================================================
# CHUNK 85 V 05 — EMOTIONAL INTENSITY MODULATION
# ==============================================================================
#
# Purpose:
#   Dynamically shape emotional intensity over time by coordinating motion,
#   framing, exposure response, contrast, and color temperature drift.
#
# This module ensures emotional arcs feel intentional (build → peak → release),
# rather than flat or erratic, matching professional film editing principles.
#
# ==============================================================================

import numpy as np
from typing import Dict


class EmotionalIntensityModulator:
    """
    Controls cinematic emotional pressure over time.
    """
    __slots__ = (
        "_target_intensity",
        "_current_intensity",
        "_slew_rate",
    )
    def __init__(
        self,
        initial_intensity: float = 0.4,
        slew_rate: float = 0.15,
    ):
        """
        initial_intensity:
            Starting emotional baseline (0..1).
        slew_rate:
            Maximum change per second.
        """
        self._target_intensity = float(np.clip(initial_intensity, 0.0, 1.0))
        self._current_intensity = float(np.clip(initial_intensity, 0.0, 1.0))
        self._slew_rate = float(max(slew_rate, 0.01))
    def set_target(self, intensity: float):
        """
        Set desired emotional intensity.
        """
        self._target_intensity = float(np.clip(intensity, 0.0, 1.0))
    def update(self, dt: float) -> Dict[str, float]:
        """
        Progress intensity toward target and output modulation controls.
        Returns:
            {
                "motion_gain": float,
                "contrast_boost": float,
                "color_temp_shift": float,
                "exposure_bias": float
            }
        """
        dt = float(max(dt, 1e-3))
        delta = self._target_intensity - self._current_intensity
        max_step = self._slew_rate * dt
        if abs(delta) > max_step:
            delta = np.sign(delta) * max_step
        self._current_intensity = float(
            np.clip(self._current_intensity + delta, 0.0, 1.0)
        )
        # Map emotional intensity to cinematic controls
        motion_gain = 0.7 + 0.8 * self._current_intensity
        contrast_boost = 1.0 + 0.6 * self._current_intensity
        # Warmth for calm, cooler bias for tension
        color_temp_shift = (
            -150.0 * self._current_intensity
            + 100.0 * (1.0 - self._current_intensity)
        )
        # Slight exposure lift during emotional peaks
        exposure_bias = 0.1 * self._current_intensity
        return {
            "motion_gain": float(np.clip(motion_gain, 0.6, 1.6)),
            "contrast_boost": float(np.clip(contrast_boost, 1.0, 1.8)),
            "color_temp_shift": float(color_temp_shift),
            "exposure_bias": float(np.clip(exposure_bias, 0.0, 0.25)),
        }
# ==============================================================================
# END OF CHUNK 85 V 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 V 06 — TEMPORAL BEAT ALIGNMENT ENGINE
# ==============================================================================
#
# Purpose:
#   Align shot timing, camera motion, and exposure transitions to perceptual
#   temporal “beats” — the invisible rhythm humans feel in high-end cinema.
#
# This module synchronizes:
#   - shot duration changes
#   - motion acceleration / deceleration
#   - exposure & contrast ramps
#
# so that transitions land on emotionally coherent beats rather than arbitrary
# frame boundaries.
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class TemporalBeatAlignmentEngine:
    """
    Maintains perceptual beat phase and aligns cinematic parameters to it.
    """
    __slots__ = (
        "_beat_phase",
        "_beat_frequency",
        "_stability",
    )
    def __init__(
        self,
        beat_frequency: float = 0.6,
        stability: float = 0.92,
    ):
        """
        beat_frequency:
            Average perceptual beats per second (film ≈ 0.4–0.8).
        stability:
            Phase inertia; higher = smoother, lower = more reactive.
        """
        self._beat_phase = 0.0
        self._beat_frequency = float(np.clip(beat_frequency, 0.2, 1.2))
        self._stability = float(np.clip(stability, 0.85, 0.99))
    def update(self, dt: float, energy: float) -> Dict[str, float]:
        """
        Advance beat phase and compute alignment multipliers.
        energy:
            Narrative energy scalar (0..1) from rhythm controller.
        Returns:
            {
                "duration_quantize": float,
                "motion_phase_gain": float,
                "exposure_ramp_smooth": float
            }
        """
        dt = float(max(dt, 1e-3))
        energy = float(np.clip(energy, 0.0, 1.0))
        # Energy slightly accelerates beat perception
        freq = self._beat_frequency * (0.85 + 0.3 * energy)
        target_phase = (self._beat_phase + dt * freq) % 1.0
        # Stabilized phase progression
        self._beat_phase = (
            self._stability * self._beat_phase
            + (1.0 - self._stability) * target_phase
        )
        # Compute beat proximity (0 at beat center, 1 between beats)
        beat_distance = abs(self._beat_phase - 0.5) * 2.0
        beat_strength = 1.0 - beat_distance
        # Map beat alignment to cinematic controls
        duration_quantize = float(
            np.clip(0.85 + 0.3 * beat_strength, 0.75, 1.15)
        )
        motion_phase_gain = float(
            np.clip(0.7 + 0.6 * beat_strength, 0.6, 1.3)
        )
        exposure_ramp_smooth = float(
            np.clip(0.6 + 0.5 * beat_strength, 0.6, 1.0)
        )
        return {
            "duration_quantize": duration_quantize,
            "motion_phase_gain": motion_phase_gain,
            "exposure_ramp_smooth": exposure_ramp_smooth,
        }
# ==============================================================================
# END OF CHUNK 85 V 06
# ==============================================================================
# ==============================================================================
# CHUNK 85 V 07 — SHOT DURATION OPTIMIZATION
# ==============================================================================
#
# Purpose:
#   Determine optimal shot lengths based on perceptual load, motion entropy,
#   narrative importance, and viewer fatigue thresholds.
#
# This module prevents:
#   - shots overstaying their welcome
#   - premature cuts that feel rushed
#
# while preserving cinematic intentionality.
#
# ==============================================================================

import numpy as np
from typing import Dict


class ShotDurationOptimizer:
    """
    Computes adaptive shot duration scaling factors.
    """
    __slots__ = (
        "_base_duration",
        "_fatigue_level",
        "_decay",
    )
    def __init__(
        self,
        base_duration: float = 3.5,
        fatigue_decay: float = 0.94,
    ):
        """
        base_duration:
            Nominal shot length in seconds.
        fatigue_decay:
            Recovery rate from visual fatigue.
        """
        self._base_duration = float(max(base_duration, 0.5))
        self._fatigue_level = 0.0
        self._decay = float(np.clip(fatigue_decay, 0.85, 0.99))
    def update(
        self,
        motion_complexity: float,
        semantic_density: float,
        emotional_weight: float,
        dt: float,
    ) -> Dict[str, float]:
        """
        Update fatigue model and compute duration scaling.
        Inputs are normalized (0..1).
        """
        motion_complexity = float(np.clip(motion_complexity, 0.0, 1.0))
        semantic_density = float(np.clip(semantic_density, 0.0, 1.0))
        emotional_weight = float(np.clip(emotional_weight, 0.0, 1.0))
        dt = float(max(dt, 1e-3))
        perceptual_load = (
            0.45 * motion_complexity +
            0.35 * semantic_density +
            0.20 * emotional_weight
        )
        # Accumulate fatigue
        self._fatigue_level += perceptual_load * dt
        self._fatigue_level *= self._decay
        # Duration scaling logic
        shorten_factor = np.clip(1.0 - 0.6 * self._fatigue_level, 0.55, 1.0)
        extend_factor = 1.0 + 0.4 * emotional_weight * (1.0 - motion_complexity)
        duration_scale = shorten_factor * extend_factor
        optimal_duration = float(
            np.clip(
                self._base_duration * duration_scale,
                0.8,
                8.0,
            )
        )
        return {
            "optimal_duration": optimal_duration,
            "fatigue_level": float(np.clip(self._fatigue_level, 0.0, 1.5)),
        }
# ==============================================================================
# END OF CHUNK 85 V 07
# ==============================================================================
# ==============================================================================
# CHUNK 85 V 08 — MOTION ENERGY REDISTRIBUTION
# ==============================================================================
#
# Purpose:
#   Redistribute motion energy spatially and temporally to avoid jitter peaks,
#   sudden accelerations, and visually exhausting motion clusters.
#
# This layer ensures that:
#   - fast motion feels intentional, not chaotic
#   - slow motion feels weighted, not dead
#   - energy flows across frames like professional dolly / crane work
#
# ==============================================================================

import numpy as np
from typing import Dict


class MotionEnergyRedistributor:
    """
    Smooths and reallocates motion energy over time and axes.
    """
    __slots__ = (
        "_axis_balance",
        "_temporal_buffer",
        "_buffer_size",
        "_decay",
    )
    def __init__(
        self,
        buffer_size: int = 24,
        decay: float = 0.93,
    ):
        """
        buffer_size:
            Number of frames used for motion energy averaging.
        decay:
            Temporal decay factor for stored motion energy.
        """
        self._buffer_size = int(max(buffer_size, 6))
        self._decay = float(np.clip(decay, 0.85, 0.99))
        self._temporal_buffer = []
        self._axis_balance = {
            "x": 1.0,
            "y": 1.0,
            "z": 1.0,
        }
    def _update_buffer(self, energy: float):
        """
        Update rolling energy buffer.
        """
        if not self._temporal_buffer:
            self._temporal_buffer.append(energy)
        else:
            prev = self._temporal_buffer[-1]
            self._temporal_buffer.append(
                self._decay * prev + (1.0 - self._decay) * energy
            )
        if len(self._temporal_buffer) > self._buffer_size:
            self._temporal_buffer = self._temporal_buffer[-self._buffer_size :]
    def update(
        self,
        motion_vector: Dict[str, float],
        dt: float,
    ) -> Dict[str, float]:
        """
        Redistribute motion energy across axes.
        motion_vector:
            {
                "x": lateral motion,
                "y": vertical motion,
                "z": forward/back motion
            }
        """
        dt = float(max(dt, 1e-3))
        # Compute instantaneous energy
        energy = float(
            abs(motion_vector.get("x", 0.0))
            + abs(motion_vector.get("y", 0.0))
            + abs(motion_vector.get("z", 0.0))
        )
        self._update_buffer(energy)
        avg_energy = float(np.mean(self._temporal_buffer))
        # Axis rebalancing:
        # Prevent one axis from dominating motion perception
        for axis in ("x", "y", "z"):
            axis_energy = abs(motion_vector.get(axis, 0.0))
            if avg_energy > 1e-4:
                ratio = axis_energy / avg_energy
            else:
                ratio = 1.0
            # Compress extremes smoothly
            self._axis_balance[axis] = float(
                np.clip(1.2 - 0.6 * ratio, 0.6, 1.2)
            )
        redistributed = {
            axis: float(
                motion_vector.get(axis, 0.0) * self._axis_balance[axis]
            )
            for axis in self._axis_balance
        }
        return {
            "motion": redistributed,
            "avg_energy": avg_energy,
            "axis_balance": dict(self._axis_balance),
        }
# ==============================================================================
# END OF CHUNK 85 V 08
# ==============================================================================
# ==============================================================================
# CHUNK 85 V 09 — TRANSITION ANTICIPATION LOGIC
# ==============================================================================
#
# Purpose:
#   Anticipate upcoming transitions before they occur, allowing motion,
#   exposure, color, and framing to subtly prepare the viewer for a cut.
#
# This avoids:
#   - surprise cuts that feel jarring
#   - last-frame parameter snapping
#
# Instead, transitions feel “pre-absorbed” — a hallmark of top-tier cinema.
#
# ==============================================================================

import numpy as np
from typing import Dict


class TransitionAnticipationLogic:
    """
    Predicts and prepares for upcoming shot transitions.
    """
    __slots__ = (
        "_anticipation_window",
        "_confidence",
        "_prepared",
    )
    def __init__(
        self,
        anticipation_window: float = 0.8,
    ):
        """
        anticipation_window:
            Time (seconds) before a cut during which preparation begins.
        """
        self._anticipation_window = float(max(anticipation_window, 0.2))
        self._confidence = 0.0
        self._prepared = False
    def update(
        self,
        time_to_transition: float,
        motion_energy: float,
        semantic_shift: float,
    ) -> Dict[str, float]:
        """
        Compute anticipation gains as a function of time and certainty.
        Inputs:
            time_to_transition:
                Estimated seconds until next cut.
            motion_energy:
                Current motion magnitude (0..1).
            semantic_shift:
                Expected semantic change magnitude (0..1).
        Returns:
            {
                "motion_softening": float,
                "exposure_pre_bias": float,
                "contrast_pre_taper": float,
                "anticipation_confidence": float
            }
        """
        time_to_transition = float(max(time_to_transition, 0.0))
        motion_energy = float(np.clip(motion_energy, 0.0, 1.0))
        semantic_shift = float(np.clip(semantic_shift, 0.0, 1.0))
        # Compute temporal proximity factor
        if time_to_transition >= self._anticipation_window:
            proximity = 0.0
        else:
            proximity = 1.0 - (time_to_transition / self._anticipation_window)
        # Confidence grows with semantic certainty and temporal proximity
        target_confidence = proximity * (0.6 + 0.4 * semantic_shift)
        # Smooth confidence accumulation
        self._confidence = (
            0.85 * self._confidence + 0.15 * target_confidence
        )
        self._prepared = self._confidence > 0.4
        # Pre-transition modulation
        motion_softening = float(
            np.clip(1.0 - 0.5 * self._confidence * motion_energy, 0.6, 1.0)
        )
        exposure_pre_bias = float(
            0.05 * self._confidence * (1.0 - motion_energy)
        )
        contrast_pre_taper = float(
            np.clip(1.0 - 0.3 * self._confidence, 0.75, 1.0)
        )
        return {
            "motion_softening": motion_softening,
            "exposure_pre_bias": exposure_pre_bias,
            "contrast_pre_taper": contrast_pre_taper,
            "anticipation_confidence": float(self._confidence),
        }
# ==============================================================================
# END OF CHUNK 85 V 09
# ==============================================================================
# ==============================================================================
# CHUNK 85 V 10 — PERCEPTUAL CLOSURE DETECTION
# ==============================================================================
#
# Purpose:
#   Detect when a shot has reached perceptual completion (“closure”) so that
#   cuts occur at moments that feel natural, satisfying, and intentional.
#
# This module fuses:
#   - motion settling
#   - exposure convergence
#   - semantic saturation
#   - viewer fatigue relief
#
# to decide WHEN a shot is truly done.
#
# ==============================================================================

import numpy as np
from typing import Dict


class PerceptualClosureDetector:
    """
    Determines perceptual completeness of a shot.
    """
    __slots__ = (
        "_motion_floor",
        "_exposure_tol",
        "_semantic_window",
        "_closure_confidence",
    )
    def __init__(
        self,
        motion_floor: float = 0.12,
        exposure_tolerance: float = 0.04,
        semantic_window: int = 24,
    ):
        """
        motion_floor:
            Below this normalized motion, movement is considered settled.
        exposure_tolerance:
            Acceptable exposure drift for convergence.
        semantic_window:
            Frames used to detect semantic saturation.
        """
        self._motion_floor = float(np.clip(motion_floor, 0.05, 0.3))
        self._exposure_tol = float(np.clip(exposure_tolerance, 0.01, 0.1))
        self._semantic_window = int(max(semantic_window, 6))
        self._closure_confidence = 0.0
    def update(
        self,
        motion_energy: float,
        exposure_delta: float,
        semantic_change_rate: float,
        fatigue_level: float,
    ) -> Dict[str, float]:
        """
        Evaluate perceptual closure likelihood.
        Inputs (normalized):
            motion_energy:
                Current motion magnitude (0..1)
            exposure_delta:
                Frame-to-frame exposure change
            semantic_change_rate:
                Rate of new semantic information (0..1)
            fatigue_level:
                Viewer fatigue estimate (0..1.5)
        Returns:
            {
                "closure_probability": float,
                "recommend_cut": bool,
                "confidence": float
            }
        """
        motion_energy = float(np.clip(motion_energy, 0.0, 1.0))
        exposure_delta = abs(float(exposure_delta))
        semantic_change_rate = float(np.clip(semantic_change_rate, 0.0, 1.0))
        fatigue_level = float(np.clip(fatigue_level, 0.0, 2.0))
        # Individual convergence signals
        motion_settled = 1.0 - np.clip(
            motion_energy / max(self._motion_floor, 1e-3), 0.0, 1.0
        )
        exposure_settled = 1.0 - np.clip(
            exposure_delta / max(self._exposure_tol, 1e-3), 0.0, 1.0
        )
        semantic_saturated = 1.0 - semantic_change_rate
        fatigue_relief = np.clip(fatigue_level / 1.0, 0.0, 1.0)
        # Weighted fusion (film-editor tuned)
        target_confidence = (
            0.35 * motion_settled +
            0.25 * exposure_settled +
            0.25 * semantic_saturated +
            0.15 * fatigue_relief
        )
        # Temporal smoothing
        self._closure_confidence = (
            0.9 * self._closure_confidence + 0.1 * target_confidence
        )
        recommend_cut = self._closure_confidence > 0.62
        return {
            "closure_probability": float(self._closure_confidence),
            "recommend_cut": bool(recommend_cut),
            "confidence": float(self._closure_confidence),
        }
# ==============================================================================
# END OF CHUNK 85 V 10
# ==============================================================================
# ==============================================================================
# CHUNK 85 W 01 — MULTI-SCENE CINEMATIC MEMORY
# ==============================================================================
#
# Purpose:
#   Maintain a compact, long-lived memory across scenes to preserve narrative
#   intent, visual motifs, emotional tone, and stylistic continuity.
#
# This memory is NOT raw frames. It stores distilled cinematic descriptors that
# influence future shot selection, pacing, color bias, and motion style.
#
# ==============================================================================

import numpy as np
from typing import Dict, List


class MultiSceneCinematicMemory:
    """
    Stores and recalls distilled cinematic context across scenes.
    """
    __slots__ = (
        "_capacity",
        "_decay",
        "_entries",
    )
    def __init__(
        self,
        capacity: int = 32,
        decay: float = 0.96,
    ):
        """
        capacity:
            Maximum number of scene memories retained.
        decay:
            Temporal decay for memory influence.
        """
        self._capacity = int(max(capacity, 8))
        self._decay = float(np.clip(decay, 0.9, 0.99))
        self._entries: List[Dict[str, float]] = []
    def register_scene(
        self,
        style_vector: Dict[str, float],
        emotion_level: float,
        motion_signature: float,
        semantic_theme: float,
    ):
        """
        Store a distilled representation of a completed scene.
        style_vector:
            e.g. contrast, saturation, color temperature bias
        """
        emotion_level = float(np.clip(emotion_level, 0.0, 1.0))
        motion_signature = float(np.clip(motion_signature, 0.0, 1.0))
        semantic_theme = float(np.clip(semantic_theme, 0.0, 1.0))
        entry = {
            "style": dict(style_vector),
            "emotion": emotion_level,
            "motion": motion_signature,
            "semantic": semantic_theme,
            "weight": 1.0,
        }
        self._entries.insert(0, entry)
        if len(self._entries) > self._capacity:
            self._entries = self._entries[: self._capacity]
    def _apply_decay(self):
        """
        Apply temporal decay to memory weights.
        """
        for e in self._entries:
            e["weight"] *= self._decay
        self._entries = [
            e for e in self._entries if e["weight"] > 1e-3
        ]
    def recall_bias(self) -> Dict[str, float]:
        """
        Compute aggregated bias from memory to influence current decisions.
        Returns:
            {
                "emotion_bias": float,
                "motion_bias": float,
                "semantic_bias": float,
                "style_bias": Dict[str, float]
            }
        """
        if not self._entries:
            return {
                "emotion_bias": 0.0,
                "motion_bias": 0.0,
                "semantic_bias": 0.0,
                "style_bias": {},
            }
        self._apply_decay()
        total_weight = sum(e["weight"] for e in self._entries)
        if total_weight <= 1e-6:
            total_weight = 1.0
        emotion = 0.0
        motion = 0.0
        semantic = 0.0
        style_accum: Dict[str, float] = {}
        for e in self._entries:
            w = e["weight"] / total_weight
            emotion += w * e["emotion"]
            motion += w * e["motion"]
            semantic += w * e["semantic"]
            for k, v in e["style"].items():
                style_accum[k] = style_accum.get(k, 0.0) + w * float(v)
        return {
            "emotion_bias": float(np.clip(emotion, 0.0, 1.0)),
            "motion_bias": float(np.clip(motion, 0.0, 1.0)),
            "semantic_bias": float(np.clip(semantic, 0.0, 1.0)),
            "style_bias": style_accum,
        }
# ==============================================================================
# END OF CHUNK 85 W 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 W 02 — SHOT HISTORY DECAY & RECALL
# ==============================================================================
#
# Purpose:
#   Maintain a rolling, decayed history of executed shots so the AI avoids
#   repetitive camera language and enforces cinematic variation over time.
#
#   This directly affects:
#     - Shot selection diversity
#     - Motion grammar balance
#     - Scene pacing evolution
#
# ==============================================================================

import numpy as np
from typing import Dict, List, Tuple


class ShotHistoryMemory:
    """
    Stores recent shots with decay-based influence to prevent repetition.
    """
    __slots__ = (
        "_capacity",
        "_decay",
        "_history",
    )
    def __init__(
        self,
        capacity: int = 64,
        decay: float = 0.93,
    ):
        """
        capacity:
            Number of recent shots to track.
        decay:
            Influence decay per recall cycle.
        """
        self._capacity = int(max(capacity, 16))
        self._decay = float(np.clip(decay, 0.9, 0.99))
        self._history: List[Dict[str, float]] = []
    def register_shot(
        self,
        shot_type: str,
        motion_energy: float,
        duration: float,
        framing_tightness: float,
    ):
        """
        Register an executed shot.
        shot_type:
            e.g. 'orbit', 'push_in', 'static', 'reveal'
        """
        entry = {
            "type": shot_type,
            "motion": float(np.clip(motion_energy, 0.0, 1.0)),
            "duration": float(max(duration, 0.05)),
            "framing": float(np.clip(framing_tightness, 0.0, 1.0)),
            "weight": 1.0,
        }
        self._history.insert(0, entry)
        if len(self._history) > self._capacity:
            self._history = self._history[: self._capacity]
    def _apply_decay(self):
        for h in self._history:
            h["weight"] *= self._decay
        self._history = [
            h for h in self._history if h["weight"] > 1e-3
        ]
    def repetition_penalty(
        self,
        candidate_type: str,
        candidate_motion: float,
    ) -> float:
        """
        Compute penalty score for a candidate shot.
        Returns:
            penalty in range [0, 1]
        """
        if not self._history:
            return 0.0
        self._apply_decay()
        penalty = 0.0
        for h in self._history:
            type_match = 1.0 if h["type"] == candidate_type else 0.0
            motion_sim = 1.0 - abs(h["motion"] - candidate_motion)
            penalty += h["weight"] * (0.6 * type_match + 0.4 * motion_sim)
        penalty = penalty / max(len(self._history), 1)
        return float(np.clip(penalty, 0.0, 1.0))
    def diversity_bias(self) -> Dict[str, float]:
        """
        Provides global diversity signals for the director logic.
        """
        if not self._history:
            return {
                "prefer_motion": 0.5,
                "prefer_static": 0.5,
                "prefer_wide": 0.5,
                "prefer_tight": 0.5,
            }
        total_w = sum(h["weight"] for h in self._history)
        if total_w <= 1e-6:
            total_w = 1.0
        avg_motion = sum(h["motion"] * h["weight"] for h in self._history) / total_w
        avg_framing = sum(h["framing"] * h["weight"] for h in self._history) / total_w
        return {
            "prefer_motion": float(np.clip(1.0 - avg_motion, 0.0, 1.0)),
            "prefer_static": float(np.clip(avg_motion, 0.0, 1.0)),
            "prefer_wide": float(np.clip(1.0 - avg_framing, 0.0, 1.0)),
            "prefer_tight": float(np.clip(avg_framing, 0.0, 1.0)),
        }
# ==============================================================================
# END OF CHUNK 85 W 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 W 03 — SCENE CONTEXT EMBEDDING
# ==============================================================================
#
# Purpose:
#   Build a compact, continuously-updated embedding that represents the
#   current cinematic scene context. This vector conditions:
#     - Shot selection
#     - Motion energy envelopes
#     - Exposure / tone bias
#     - Narrative continuity across time
#
#   This is NOT object detection. It is *scene state cognition*.
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


def _safe_norm(x: np.ndarray, eps: float = 1e-8) -> np.ndarray:
    n = np.linalg.norm(x)
    if n < eps:
        return x * 0.0
    return x / n


class SceneContextEmbedding:
    """
    Maintains a rolling embedding describing the current cinematic scene.
    """
    __slots__ = (
        "_dim",
        "_ema_alpha",
        "_context",
        "_confidence",
    )
    def __init__(
        self,
        dim: int = 64,
        ema_alpha: float = 0.12,
    ):
        """
        dim:
            Embedding dimensionality. Kept small for real-time conditioning.
        ema_alpha:
            Exponential smoothing factor for temporal stability.
        """
        self._dim = int(max(dim, 32))
        self._ema_alpha = float(np.clip(ema_alpha, 0.05, 0.3))
        self._context = np.zeros(self._dim, dtype=np.float32)
        self._confidence = 0.0
    def update(
        self,
        vision_features: np.ndarray,
        motion_stats: Dict[str, float],
        lighting_stats: Dict[str, float],
        semantic_bias: Optional[np.ndarray] = None,
    ):
        """
        Update the scene context.
        vision_features:
            High-level pooled features (e.g., from detector backbone).
        motion_stats:
            { 'mean_flow', 'flow_variance', 'camera_motion' }
        lighting_stats:
            { 'key_level', 'contrast', 'color_temp' }
        semantic_bias:
            Optional bias vector from higher-level narrative AI.
        """
        vf = vision_features.astype(np.float32)
        vf = _safe_norm(vf)
        m = np.array(
            [
                motion_stats.get("mean_flow", 0.0),
                motion_stats.get("flow_variance", 0.0),
                motion_stats.get("camera_motion", 0.0),
            ],
            dtype=np.float32,
        )
        m = np.clip(m, 0.0, 1.0)
        l = np.array(
            [
                lighting_stats.get("key_level", 0.5),
                lighting_stats.get("contrast", 0.5),
                lighting_stats.get("color_temp", 0.5),
            ],
            dtype=np.float32,
        )
        l = np.clip(l, 0.0, 1.0)
        base = np.zeros(self._dim, dtype=np.float32)
        k = min(len(vf), self._dim)
        base[:k] += vf[:k]
        base[0:3] += 0.35 * m
        base[3:6] += 0.25 * l
        if semantic_bias is not None:
            sb = semantic_bias.astype(np.float32)
            sb = _safe_norm(sb)
            ks = min(len(sb), self._dim)
            base[:ks] += 0.4 * sb[:ks]
        base = _safe_norm(base)
        # Exponential temporal integration
        self._context = (
            (1.0 - self._ema_alpha) * self._context
            + self._ema_alpha * base
        )
        # Confidence increases as updates stabilize
        delta = np.linalg.norm(base - self._context)
        self._confidence = float(
            np.clip(1.0 - delta * 2.0, 0.0, 1.0)
        )
    def embedding(self) -> np.ndarray:
        """
        Returns normalized scene embedding.
        """
        return _safe_norm(self._context.copy())
    def confidence(self) -> float:
        """
        Returns confidence in scene stability [0..1].
        """
        return self._confidence
    def similarity(self, other: np.ndarray) -> float:
        """
        Cosine similarity to another scene embedding.
        """
        a = _safe_norm(self._context)
        b = _safe_norm(other)
        return float(np.clip(np.dot(a, b), -1.0, 1.0))
    def reset(self):
        """
        Hard reset for scene cuts.
        """
        self._context[:] = 0.0
        self._confidence = 0.0
