# ==============================================================================
# CHUNK 85 W 04 — CROSS-SCENE VISUAL CONTINUITY
# ==============================================================================
#
# Purpose:
#   Enforce visual and emotional continuity across scene boundaries.
#   This module prevents jarring transitions by harmonizing:
#     - Color temperature & contrast drift
#     - Motion energy envelopes
#     - Framing intent carryover
#     - Exposure anchor points
#
#   This is editorial intelligence, not a filter.
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


def _lerp(a: float, b: float, t: float) -> float:
    return a + (b - a) * t


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, x))


class CrossSceneContinuity:
    """
    Maintains continuity constraints across scene boundaries.
    """
    __slots__ = (
        "_color_anchor",
        "_contrast_anchor",
        "_motion_anchor",
        "_framing_anchor",
        "_exposure_anchor",
        "_memory_strength",
    )
    def __init__(self, memory_strength: float = 0.6):
        """
        memory_strength:
            How strongly previous scene influences the next [0..1].
        """
        self._memory_strength = _clamp(memory_strength, 0.3, 0.85)
        self._color_anchor: Optional[float] = None
        self._contrast_anchor: Optional[float] = None
        self._motion_anchor: Optional[float] = None
        self._framing_anchor: Optional[float] = None
        self._exposure_anchor: Optional[float] = None
    def capture_scene_tail(
        self,
        color_temp: float,
        contrast: float,
        motion_energy: float,
        framing_tightness: float,
        exposure: float,
    ):
        """
        Capture terminal characteristics of a scene.
        """
        self._color_anchor = float(color_temp)
        self._contrast_anchor = float(contrast)
        self._motion_anchor = float(motion_energy)
        self._framing_anchor = float(framing_tightness)
        self._exposure_anchor = float(exposure)
    def apply_to_scene_head(
        self,
        target: Dict[str, float],
        cut_severity: float,
    ) -> Dict[str, float]:
        """
        Apply continuity bias to a new scene.
        cut_severity:
            0.0 = soft cut / same location
            1.0 = hard cut / new narrative beat
        """
        t = _clamp(1.0 - cut_severity, 0.0, 1.0)
        t *= self._memory_strength
        out = dict(target)
        if self._color_anchor is not None:
            out["color_temp"] = _lerp(
                target.get("color_temp", self._color_anchor),
                self._color_anchor,
                t,
            )
        if self._contrast_anchor is not None:
            out["contrast"] = _lerp(
                target.get("contrast", self._contrast_anchor),
                self._contrast_anchor,
                t,
            )
        if self._motion_anchor is not None:
            out["motion_energy"] = _lerp(
                target.get("motion_energy", self._motion_anchor),
                self._motion_anchor,
                t * 0.8,  # motion continuity is weaker
            )
        if self._framing_anchor is not None:
            out["framing_tightness"] = _lerp(
                target.get("framing_tightness", self._framing_anchor),
                self._framing_anchor,
                t,
            )
        if self._exposure_anchor is not None:
            out["exposure"] = _lerp(
                target.get("exposure", self._exposure_anchor),
                self._exposure_anchor,
                t,
            )
        return out
    def reset(self):
        """
        Hard reset (montage, dream, flashback).
        """
        self._color_anchor = None
        self._contrast_anchor = None
        self._motion_anchor = None
        self._framing_anchor = None
        self._exposure_anchor = None
