# CHUNK 85 W 05 — LONG-TERM STYLE CONSISTENCY
# ==============================================================================
#
# Purpose:
#   Maintain a persistent cinematic style vector across long durations
#   (minutes to hours). This ensures the AI does not drift visually even
#   when scene context, lighting, or motion changes.
#
#   This governs:
#     - Color mood coherence
#     - Contrast philosophy (soft vs punchy)
#     - Motion temperament
#     - Framing preference bias
#
# ==============================================================================

import numpy as np
from typing import Dict


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class StyleConsistencyMemory:
    """
    Tracks and enforces long-horizon stylistic intent.
    """
    __slots__ = (
        "_style",
        "_confidence",
        "_adapt_rate",
    )
    def __init__(self, adapt_rate: float = 0.02):
        """
        adapt_rate:
            How fast style can evolve over time.
            Low values preserve identity.
        """
        self._adapt_rate = float(np.clip(adapt_rate, 0.005, 0.05))
        self._style = {
            "color_temp_bias": 0.5,
            "contrast_bias": 0.5,
            "motion_bias": 0.5,
            "framing_bias": 0.5,
        }
        self._confidence = 0.0
    def update_from_scene(
        self,
        scene_stats: Dict[str, float],
        reliability: float,
    ):
        """
        Slowly adapt style from stable scene statistics.
        """
        r = _clamp01(reliability)
        a = self._adapt_rate * r
        for k in self._style.keys():
            if k in scene_stats:
                self._style[k] = (
                    (1.0 - a) * self._style[k]
                    + a * _clamp01(scene_stats[k])
                )
        self._confidence = _clamp01(self._confidence + r * 0.01)
    def enforce(self, target: Dict[str, float]) -> Dict[str, float]:
        """
        Apply style bias to current target intent.
        """
        out = dict(target)
        out["color_temp"] = (
            0.7 * out.get("color_temp", 0.5)
            + 0.3 * self._style["color_temp_bias"]
        )
        out["contrast"] = (
            0.7 * out.get("contrast", 0.5)
            + 0.3 * self._style["contrast_bias"]
        )
        out["motion_energy"] = (
            0.6 * out.get("motion_energy", 0.5)
            + 0.4 * self._style["motion_bias"]
        )
        out["framing_tightness"] = (
            0.6 * out.get("framing_tightness", 0.5)
            + 0.4 * self._style["framing_bias"]
        )
        return out
    def style_vector(self) -> Dict[str, float]:
        """
        Expose current persistent style state.
        """
        return dict(self._style)
    def confidence(self) -> float:
        """
        Confidence that style is stable.
        """
        return self._confidence
    def reset(self):
        """
        Hard reset (new project / new film).
        """
        self._style = {
            "color_temp_bias": 0.5,
            "contrast_bias": 0.5,
            "motion_bias": 0.5,
            "framing_bias": 0.5,
        }
        self._confidence = 0.0
