# CHUNK 85 W 06 — NARRATIVE MOTIF REINFORCEMENT
# ==============================================================================
#
# Purpose:
#   Track and reinforce recurring narrative motifs (visual, motion, tonal)
#   across time so the AI subconsciously “echoes” themes like a human director.
#
#   Motifs include:
#     - Repeated motion signatures (slow push, orbit, hold)
#     - Tonal callbacks (warm safety, cold tension)
#     - Framing patterns (isolation wide → intimate close)
#
# ==============================================================================

import numpy as np
from typing import Dict, List


def _clip01(x: float) -> float:
    return max(0.0, min(1.0, x))


class NarrativeMotifEngine:
    """
    Learns and reinforces repeating cinematic motifs.
    """
    __slots__ = (
        "_motifs",
        "_strength",
        "_decay",
    )
    def __init__(self, decay: float = 0.97):
        """
        decay:
            How quickly unused motifs fade.
        """
        self._decay = float(np.clip(decay, 0.9, 0.995))
        self._motifs: Dict[str, float] = {}
        self._strength = 0.0
    def observe(
        self,
        motion_energy: float,
        framing_tightness: float,
        color_temp: float,
    ):
        """
        Observe a shot and update motif statistics.
        """
        key = (
            f"M{int(motion_energy * 3)}"
            f"F{int(framing_tightness * 3)}"
            f"C{int(color_temp * 3)}"
        )
        self._motifs[key] = self._motifs.get(key, 0.0) + 1.0
        # Apply decay
        for k in list(self._motifs.keys()):
            self._motifs[k] *= self._decay
            if self._motifs[k] < 0.05:
                del self._motifs[k]
        self._strength = _clip01(
            sum(self._motifs.values()) / 8.0
        )
    def reinforce(
        self,
        target: Dict[str, float],
    ) -> Dict[str, float]:
        """
        Bias target intent toward learned motifs.
        """
        if not self._motifs:
            return target
        dominant = max(self._motifs, key=self._motifs.get)
        m_bin = int(dominant[1])
        f_bin = int(dominant[3])
        c_bin = int(dominant[5])
        out = dict(target)
        s = self._strength
        out["motion_energy"] = (
            (1.0 - s) * out.get("motion_energy", 0.5)
            + s * (m_bin / 2.0)
        )
        out["framing_tightness"] = (
            (1.0 - s) * out.get("framing_tightness", 0.5)
            + s * (f_bin / 2.0)
        )
        out["color_temp"] = (
            (1.0 - s) * out.get("color_temp", 0.5)
            + s * (c_bin / 2.0)
        )
        return out
    def motif_strength(self) -> float:
        """
        How strongly motifs are established.
        """
        return self._strength
    def reset(self):
        """
        Reset motif memory.
        """
        self._motifs.clear()
        self._strength = 0.0
