# CHUNK 85 X 01 — CAMERA AI PERCEPTUAL STATE CORE
# ==============================================================================
#
# Purpose:
#   Establish a unified perceptual state vector for the camera AI.
#   This is the internal "awareness" layer that fuses:
#     - Visual saliency
#     - Motion perception
#     - Scene context embedding
#     - Narrative & style bias
#
#   Every autonomous camera decision MUST pass through this state.
#
# ==============================================================================

import numpy as np
from typing import Dict


def _norm(x: np.ndarray, eps: float = 1e-8) -> np.ndarray:
    n = np.linalg.norm(x)
    if n < eps:
        return x * 0.0
    return x / n


class CameraPerceptualState:
    """
    Central perceptual fusion state for camera AI.
    """
    __slots__ = (
        "_vision_vec",
        "_motion_vec",
        "_scene_vec",
        "_style_vec",
        "_motif_strength",
        "_confidence",
    )
    def __init__(self, dim: int = 64):
        self._vision_vec = np.zeros(dim, dtype=np.float32)
        self._motion_vec = np.zeros(8, dtype=np.float32)
        self._scene_vec = np.zeros(dim, dtype=np.float32)
        self._style_vec = np.zeros(4, dtype=np.float32)
        self._motif_strength = 0.0
        self._confidence = 0.0
    def update(
        self,
        vision_features: np.ndarray,
        motion_features: Dict[str, float],
        scene_embedding: np.ndarray,
        style_bias: Dict[str, float],
        motif_strength: float,
    ):
        """
        Update perceptual state from all upstream systems.
        """
        self._vision_vec = _norm(vision_features.astype(np.float32))
        self._motion_vec[:] = [
            motion_features.get("mean_flow", 0.0),
            motion_features.get("flow_variance", 0.0),
            motion_features.get("camera_motion", 0.0),
            motion_features.get("subject_motion", 0.0),
            motion_features.get("parallax", 0.0),
            motion_features.get("stability", 0.5),
            motion_features.get("acceleration", 0.0),
            motion_features.get("jerk", 0.0),
        ]
        self._motion_vec[:] = np.clip(self._motion_vec, 0.0, 1.0)
        self._scene_vec = _norm(scene_embedding.astype(np.float32))
        self._style_vec[:] = [
            style_bias.get("color_temp_bias", 0.5),
            style_bias.get("contrast_bias", 0.5),
            style_bias.get("motion_bias", 0.5),
            style_bias.get("framing_bias", 0.5),
        ]
        self._motif_strength = float(np.clip(motif_strength, 0.0, 1.0))
        # Confidence grows when signals align
        alignment = (
            np.dot(self._vision_vec, self._scene_vec)
            + (1.0 - abs(self._motion_vec[0] - self._motion_vec[5]))
        ) * 0.5
        self._confidence = float(
            np.clip(0.8 * self._confidence + 0.2 * alignment, 0.0, 1.0)
        )
    def fused_state(self) -> np.ndarray:
        """
        Returns a fused perceptual state vector.
        """
        fused = np.concatenate(
            [
                self._vision_vec * 0.35,
                self._scene_vec * 0.35,
                self._motion_vec * 0.2,
                self._style_vec * 0.1,
            ]
        )
        return _norm(fused)
    def confidence(self) -> float:
        """
        Confidence that perception is stable and reliable.
        """
        return self._confidence
    def snapshot(self) -> Dict[str, np.ndarray]:
        """
        Debug / inspection snapshot.
        """
        return {
            "vision": self._vision_vec.copy(),
            "motion": self._motion_vec.copy(),
            "scene": self._scene_vec.copy(),
            "style": self._style_vec.copy(),
            "confidence": np.array([self._confidence], dtype=np.float32),
        }
    def reset(self):
        """
        Hard reset (sensor loss / reboot).
        """
        self._vision_vec[:] = 0.0
        self._motion_vec[:] = 0.0
        self._scene_vec[:] = 0.0
        self._style_vec[:] = 0.0
        self._motif_strength = 0.0
        self._confidence = 0.0
