# CHUNK 85 X 02 — CAMERA INTENT VECTOR SYNTHESIS
# ==============================================================================
#
# Purpose:
#   Convert fused perceptual state into a structured, continuous intent vector
#   that drives exposure, framing, motion, and lens behavior coherently.
#
#   This is NOT a classifier.
#   This is a differentiable decision manifold.
#
# ==============================================================================

import numpy as np
from typing import Dict


def _norm(x: np.ndarray, eps: float = 1e-8) -> np.ndarray:
    n = np.linalg.norm(x)
    if n < eps:
        return x * 0.0
    return x / n


class CameraIntentSynthesizer:
    """
    Synthesizes camera intent from perceptual state.
    """
    __slots__ = (
        "_intent",
        "_confidence",
    )
    def __init__(self):
        self._intent = {
            "motion_energy": 0.5,
            "stability": 0.5,
            "framing_tightness": 0.5,
            "subject_priority": 0.5,
            "exposure_bias": 0.5,
            "tone_bias": 0.5,
        }
        self._confidence = 0.0
    def synthesize(
        self,
        perceptual_state: np.ndarray,
        perceptual_confidence: float,
    ) -> Dict[str, float]:
        """
        Generate intent vector from perceptual embedding.
        """
        p = _norm(perceptual_state.astype(np.float32))
        # Project perceptual axes
        motion_axis = p[0:8].mean()
        scene_axis = p[8:24].mean()
        vision_axis = p[24:40].mean()
        style_axis = p[40:48].mean()
        self._intent["motion_energy"] = float(
            np.clip(0.6 * motion_axis + 0.4 * scene_axis, 0.0, 1.0)
        )
        self._intent["stability"] = float(
            np.clip(1.0 - motion_axis * 0.8, 0.0, 1.0)
        )
        self._intent["framing_tightness"] = float(
            np.clip(0.5 + (vision_axis - 0.5) * 0.7, 0.0, 1.0)
        )
        self._intent["subject_priority"] = float(
            np.clip(vision_axis * 0.9 + scene_axis * 0.1, 0.0, 1.0)
        )
        self._intent["exposure_bias"] = float(
            np.clip(0.5 + (scene_axis - 0.5) * 0.6, 0.0, 1.0)
        )
        self._intent["tone_bias"] = float(
            np.clip(0.5 + (style_axis - 0.5) * 0.8, 0.0, 1.0)
        )
        # Confidence propagation
        self._confidence = float(
            np.clip(
                0.7 * self._confidence
                + 0.3 * perceptual_confidence,
                0.0,
                1.0,
            )
        )
        return dict(self._intent)
    def confidence(self) -> float:
        """
        Confidence that intent is reliable.
        """
        return self._confidence
    def reset(self):
        """
        Hard reset (mode change / failure).
        """
        for k in self._intent:
            self._intent[k] = 0.5
        self._confidence = 0.0
