# ==============================================================================
# CHUNK 85 X 03 — EXPOSURE & TONE INTENT COUPLING
# ==============================================================================
#
# Purpose:
#   Convert high-level camera intent into physically plausible exposure
#   and tone behavior. This ensures that exposure is not reactive, but
#   narratively motivated and visually consistent.
#
#   This governs:
#     - Auto-exposure biasing
#     - Highlight roll-off behavior
#     - Shadow protection strategy
#     - Global tone response curvature
#
# ==============================================================================

import numpy as np
from typing import Dict


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class ExposureToneCoupler:
    """
    Couples camera intent with exposure and tone shaping logic.
    """
    __slots__ = (
        "_exposure_bias",
        "_tone_bias",
        "_adapt_rate",
        "_confidence",
    )
    def __init__(self, adapt_rate: float = 0.15):
        """
        adapt_rate:
            Temporal smoothing factor for exposure transitions.
        """
        self._adapt_rate = float(np.clip(adapt_rate, 0.05, 0.3))
        self._exposure_bias = 0.5
        self._tone_bias = 0.5
        self._confidence = 0.0
    def update(
        self,
        intent: Dict[str, float],
        scene_luminance: Dict[str, float],
        perceptual_confidence: float,
    ) -> Dict[str, float]:
        """
        Update exposure and tone targets.
        scene_luminance:
            { 'avg', 'p90', 'p99', 'dynamic_range' }
        """
        i_exp = _clamp01(intent.get("exposure_bias", 0.5))
        i_tone = _clamp01(intent.get("tone_bias", 0.5))
        # Base exposure anchor
        anchor = scene_luminance.get("avg", 0.5)
        # Protect highlights when tone bias is high
        highlight_protect = _clamp01(
            scene_luminance.get("p99", 0.9) * (0.5 + i_tone)
        )
        # Shadow lift for narrative softness
        shadow_lift = _clamp01(
            (1.0 - scene_luminance.get("dynamic_range", 0.5))
            * (0.5 + i_tone * 0.6)
        )
        target_exposure = _clamp01(
            anchor * (0.8 + i_exp * 0.6)
        )
        target_tone = _clamp01(
            0.5
            + (highlight_protect - shadow_lift) * 0.7
            + (i_tone - 0.5) * 0.6
        )
        # Temporal smoothing
        a = self._adapt_rate
        self._exposure_bias = (
            (1.0 - a) * self._exposure_bias
            + a * target_exposure
        )
        self._tone_bias = (
            (1.0 - a) * self._tone_bias
            + a * target_tone
        )
        self._confidence = float(
            np.clip(
                0.7 * self._confidence
                + 0.3 * perceptual_confidence,
                0.0,
                1.0,
            )
        )
        return {
            "exposure_target": self._exposure_bias,
            "tone_target": self._tone_bias,
            "highlight_protection": highlight_protect,
            "shadow_lift": shadow_lift,
        }
    def confidence(self) -> float:
        """
        Confidence in exposure/tone stability.
        """
        return self._confidence
    def reset(self):
        """
        Hard reset.
        """
        self._exposure_bias = 0.5
        self._tone_bias = 0.5
        self._confidence = 0.0
