# ==============================================================================
# CHUNK 85 X 04 — MOTION VS STABILITY ARBITRATION
# ==============================================================================
#
# Purpose:
#   Resolve conflicts between desired cinematic motion and required visual
#   stability. This module ensures expressive movement without inducing
#   shake, disorientation, or motion sickness.
#
#   This arbitration directly affects:
#     - Camera velocity envelopes
#     - Micro-jitter suppression
#     - Dynamic stabilization strength
#     - Gimbal vs digital stabilization balance
#
# ==============================================================================

import numpy as np
from typing import Dict


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class MotionStabilityArbiter:
    """
    Balances cinematic motion intent against stability constraints.
    """
    __slots__ = (
        "_motion_weight",
        "_stability_weight",
        "_smooth_factor",
        "_confidence",
    )
    def __init__(self, smooth_factor: float = 0.18):
        """
        smooth_factor:
            Temporal smoothing for arbitration transitions.
        """
        self._smooth_factor = float(np.clip(smooth_factor, 0.05, 0.35))
        self._motion_weight = 0.5
        self._stability_weight = 0.5
        self._confidence = 0.0
    def update(
        self,
        intent: Dict[str, float],
        motion_metrics: Dict[str, float],
        perceptual_confidence: float,
    ) -> Dict[str, float]:
        """
        Compute arbitration weights.
        motion_metrics:
            { 'jerk', 'acceleration', 'stability', 'parallax' }
        """
        desired_motion = _clamp01(intent.get("motion_energy", 0.5))
        desired_stability = _clamp01(intent.get("stability", 0.5))
        jerk = _clamp01(motion_metrics.get("jerk", 0.0))
        accel = _clamp01(motion_metrics.get("acceleration", 0.0))
        base_stability = _clamp01(motion_metrics.get("stability", 0.5))
        instability_penalty = _clamp01(
            jerk * 0.6 + accel * 0.4
        )
        target_motion = _clamp01(
            desired_motion * (1.0 - instability_penalty * 0.8)
        )
        target_stability = _clamp01(
            max(desired_stability, base_stability)
        )
        # Temporal smoothing
        a = self._smooth_factor
        self._motion_weight = (
            (1.0 - a) * self._motion_weight
            + a * target_motion
        )
        self._stability_weight = (
            (1.0 - a) * self._stability_weight
            + a * target_stability
        )
        # Confidence grows when conflict is low
        conflict = abs(self._motion_weight - self._stability_weight)
        self._confidence = float(
            np.clip(
                0.8 * self._confidence
                + 0.2 * (1.0 - conflict) * perceptual_confidence,
                0.0,
                1.0,
            )
        )
        return {
            "motion_weight": self._motion_weight,
            "stability_weight": self._stability_weight,
            "dynamic_stabilization": _clamp01(
                self._stability_weight * 0.9
            ),
        }
    def confidence(self) -> float:
        """
        Confidence that motion/stability balance is optimal.
        """
        return self._confidence
    def reset(self):
        """
        Hard reset (mode switch / failure recovery).
        """
        self._motion_weight = 0.5
        self._stability_weight = 0.5
        self._confidence = 0.0
# ==============================================================================
# END OF CHUNK 85 X 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 X 05 — SUBJECT SALIENCY WEIGHTING
# ==============================================================================
#
# Purpose:
#   Compute perceptual saliency weights for subjects and scene elements,
#   allowing the cinematic engine to prioritize framing, exposure,
#   motion, and focus around what the audience will naturally attend to.
#
#   This module fuses:
#     - Vision model outputs (objects, faces, motion)
#     - Scene context (foreground/background separation)
#     - Narrative intent (hero subject, supporting subject)
#
# ==============================================================================

import numpy as np
from typing import Dict, List


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class SubjectSaliencyWeighter:
    """
    Assigns perceptual importance to detected subjects.
    """
    __slots__ = (
        "_temporal_memory",
        "_smooth_factor",
    )
    def __init__(self, smooth_factor: float = 0.22):
        """
        smooth_factor:
            Temporal inertia for saliency stability.
        """
        self._smooth_factor = float(np.clip(smooth_factor, 0.05, 0.4))
        self._temporal_memory: Dict[str, float] = {}
    def evaluate(
        self,
        detections: List[Dict[str, float]],
        scene_metrics: Dict[str, float],
        narrative_intent: Dict[str, float],
    ) -> List[Dict[str, float]]:
        """
        detections:
            Each detection must include:
            { 'id', 'area', 'motion', 'confidence', 'center_dist' }
        scene_metrics:
            { 'depth_separation', 'global_motion' }
        narrative_intent:
            { 'hero_bias', 'motion_focus', 'emotional_weight' }
        """
        depth_sep = _clamp01(scene_metrics.get("depth_separation", 0.5))
        global_motion = _clamp01(scene_metrics.get("global_motion", 0.0))
        hero_bias = _clamp01(narrative_intent.get("hero_bias", 0.5))
        motion_focus = _clamp01(narrative_intent.get("motion_focus", 0.5))
        emotional_weight = _clamp01(
            narrative_intent.get("emotional_weight", 0.5)
        )
        results = []
        for det in detections:
            sid = det.get("id", "unknown")
            area = _clamp01(det.get("area", 0.0))
            motion = _clamp01(det.get("motion", 0.0))
            conf = _clamp01(det.get("confidence", 0.0))
            center_dist = _clamp01(det.get("center_dist", 0.5))
            # Base perceptual importance
            saliency = (
                area * 0.35
                + motion * 0.25 * motion_focus
                + conf * 0.25
                + (1.0 - center_dist) * 0.15
            )
            # Depth separation boosts foreground subjects
            saliency *= 0.7 + 0.3 * depth_sep
            # Emotional scenes bias toward stable subjects
            saliency *= 1.0 - (global_motion * 0.3 * emotional_weight)
            # Narrative hero bias
            if det.get("is_primary", False):
                saliency *= 1.0 + 0.6 * hero_bias
            saliency = _clamp01(saliency)
            # Temporal smoothing per subject
            prev = self._temporal_memory.get(sid, saliency)
            a = self._smooth_factor
            smooth_saliency = (1.0 - a) * prev + a * saliency
            self._temporal_memory[sid] = smooth_saliency
            results.append({
                "id": sid,
                "saliency": smooth_saliency,
            })
        # Normalize across subjects
        total = sum(r["saliency"] for r in results) + 1e-6
        for r in results:
            r["saliency"] = r["saliency"] / total
        return results
    def reset(self):
        """
        Clear temporal memory (scene cut / mode switch).
        """
        self._temporal_memory.clear()
# ==============================================================================
# END OF CHUNK 85 X 05
# ==============================================================================
# ==============================================================================
# CHUNK 85 X 06 — GIMBAL & CAMERA COORDINATION LOGIC
# ==============================================================================
#
# Purpose:
#   Synchronize camera framing, gimbal orientation, and cinematic intent.
#   This module converts subject saliency + motion intent into:
#     - Smooth gimbal pitch/yaw targets
#     - Camera framing offsets (rule-of-thirds, headroom)
#     - Jerk-limited motion for filmic continuity
#
#   Works with:
#     - SubjectSaliencyWeighter outputs
#     - Vision tracking (screen-space + depth)
#     - Camera intrinsic model
#
# ==============================================================================

import numpy as np
from typing import Dict, List, Tuple


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, x))


def _lerp(a: float, b: float, t: float) -> float:
    return a + (b - a) * t


class GimbalCameraCoordinator:
    """
    Computes coordinated gimbal + camera framing commands.
    """
    __slots__ = (
        "_yaw",
        "_pitch",
        "_yaw_vel",
        "_pitch_vel",
        "_response",
    )
    def __init__(self, response: float = 0.18):
        """
        response:
            Controls how fast the system reacts (cinematic inertia).
        """
        self._yaw = 0.0
        self._pitch = 0.0
        self._yaw_vel = 0.0
        self._pitch_vel = 0.0
        self._response = float(np.clip(response, 0.08, 0.35))
    def update(
        self,
        subjects: List[Dict[str, float]],
        frame_size: Tuple[int, int],
        intent: Dict[str, float],
        dt: float,
    ) -> Dict[str, float]:
        """
        subjects:
            [{ 'saliency', 'cx', 'cy', 'depth' }]
        frame_size:
            (width, height)
        intent:
            { 'aggressiveness', 'headroom_bias', 'horizon_lock' }
        """
        if not subjects:
            return {
                "yaw": self._yaw,
                "pitch": self._pitch,
            }
        w, h = frame_size
        agg = _clamp(intent.get("aggressiveness", 0.5), 0.0, 1.0)
        headroom = _clamp(intent.get("headroom_bias", 0.5), 0.0, 1.0)
        horizon_lock = _clamp(intent.get("horizon_lock", 0.0), 0.0, 1.0)
        # Compute weighted target in screen space
        tx = 0.0
        ty = 0.0
        total = 0.0
        for s in subjects:
            wgt = s["saliency"]
            tx += s["cx"] * wgt
            ty += s["cy"] * wgt
            total += wgt
        tx /= max(total, 1e-6)
        ty /= max(total, 1e-6)
        # Rule-of-thirds framing
        thirds_x = 0.5
        thirds_y = _lerp(0.4, 0.33, headroom)
        err_x = (tx - thirds_x)
        err_y = (ty - thirds_y)
        # Convert to angular deltas (normalized FOV model)
        yaw_target = -err_x * (0.6 + 0.4 * agg)
        pitch_target = err_y * (0.5 + 0.3 * agg)
        # Horizon stabilization blending
        pitch_target *= (1.0 - 0.6 * horizon_lock)
        # Critically damped smoothing
        alpha = _clamp(self._response * dt * 60.0, 0.0, 1.0)
        self._yaw = _lerp(self._yaw, yaw_target, alpha)
        self._pitch = _lerp(self._pitch, pitch_target, alpha)
        return {
            "yaw": self._yaw,
            "pitch": self._pitch,
        }
    def reset(self):
        """
        Reset orientation state (scene cut / manual override).
        """
        self._yaw = 0.0
        self._pitch = 0.0
        self._yaw_vel = 0.0
        self._pitch_vel = 0.0
# ==============================================================================
# END OF CHUNK 85 X 06
# ==============================================================================
# ==============================================================================
# CHUNK 85 X 07 — TEMPORAL INTENT SMOOTHING
# ==============================================================================
#
# Purpose:
#   Stabilize high-level cinematic intent over time.
#   This prevents abrupt AI decision changes from causing:
#     - Jerky framing shifts
#     - Exposure pumping
#     - Unnatural gimbal corrections
#
#   This module operates ABOVE raw vision and BELOW shot grammar,
#   acting as a perceptual "director inertia" layer.
#
# ==============================================================================

import numpy as np
from typing import Dict


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class TemporalIntentSmoother:
    """
    Applies perceptually tuned temporal filtering to intent vectors.
    """
    __slots__ = (
        "_state",
        "_rise",
        "_fall",
    )
    def __init__(
        self,
        rise_time: float = 0.25,
        fall_time: float = 0.45,
    ):
        """
        rise_time:
            How quickly intent strengthens (seconds).
        fall_time:
            How slowly intent decays (seconds).
        """
        self._rise = max(0.05, rise_time)
        self._fall = max(0.1, fall_time)
        self._state: Dict[str, float] = {}
    def update(
        self,
        raw_intent: Dict[str, float],
        dt: float,
    ) -> Dict[str, float]:
        """
        raw_intent:
            Arbitrary intent scalars, e.g.:
            { 'aggressiveness', 'emotion', 'motion_focus' }
        """
        smoothed: Dict[str, float] = {}
        for key, value in raw_intent.items():
            v = _clamp01(float(value))
            prev = self._state.get(key, v)
            if v > prev:
                tau = self._rise
            else:
                tau = self._fall
            alpha = 1.0 - np.exp(-dt / max(tau, 1e-6))
            cur = prev + (v - prev) * alpha
            self._state[key] = cur
            smoothed[key] = cur
        return smoothed
    def reset(self):
        """
        Clear intent memory (hard cut / manual override).
        """
        self._state.clear()
# ==============================================================================
# END OF CHUNK 85 X 07
# ==============================================================================
# ==============================================================================
# CHUNK 85 Y 01 — AUTONOMOUS SHOT GRAMMAR CORE
# ==============================================================================
#
# Purpose:
#   Provide a director-level abstraction that converts:
#     perception + intent + context
#   into concrete cinematic shot decisions.
#
#   This module defines WHAT kind of shot should exist:
#     - Wide / Medium / Close
#     - Static / Follow / Orbit / Reveal
#     - Emotional vs kinetic pacing
#
#   It does NOT directly move hardware.
#   It outputs a structured shot intent used downstream.
#
# ==============================================================================

from typing import Dict, List
import numpy as np


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class ShotGrammarEngine:
    """
    High-level cinematic grammar engine.
    """
    __slots__ = (
        "_current_shot",
        "_shot_time",
    )
    def __init__(self):
        self._current_shot: Dict[str, float] = {}
        self._shot_time: float = 0.0
    def evaluate(
        self,
        saliency: List[Dict[str, float]],
        scene_type: str,
        intent: Dict[str, float],
        dt: float,
    ) -> Dict[str, float]:
        """
        saliency:
            Normalized subject saliency list.
        scene_type:
            e.g. 'action', 'dialog', 'establishing'
        intent:
            { 'aggressiveness', 'emotion', 'motion_focus' }
        """
        self._shot_time += dt
        agg = _clamp01(intent.get("aggressiveness", 0.5))
        emo = _clamp01(intent.get("emotion", 0.5))
        mot = _clamp01(intent.get("motion_focus", 0.5))
        # Determine primary subject dominance
        primary_weight = saliency[0]["saliency"] if saliency else 0.0
        # Shot scale logic
        if primary_weight > 0.65:
            scale = _clamp01(0.8 + emo * 0.2)
        else:
            scale = _clamp01(0.4 + (1.0 - emo) * 0.3)
        # Shot motion logic
        if scene_type == "action":
            motion = _clamp01(0.7 + agg * 0.3)
        elif scene_type == "dialog":
            motion = _clamp01(0.2 + emo * 0.2)
        else:
            motion = _clamp01(0.4 + mot * 0.3)
        # Shot persistence (avoid rapid changes)
        if self._shot_time < 2.0 and self._current_shot:
            return self._current_shot
        shot = {
            "scale": scale,          # framing tightness
            "motion": motion,        # camera motion intensity
            "emotion_bias": emo,
            "aggressiveness": agg,
        }
        self._current_shot = shot
        self._shot_time = 0.0
        return shot
    def reset(self):
        """
        Reset shot state (hard cut or manual override).
        """
        self._current_shot = {}
        self._shot_time = 0.0
# ==============================================================================
# END OF CHUNK 85 Y 01
# ==============================================================================
# ==============================================================================
# CHUNK 85 Y 02 — SHOT TRANSITION INTELLIGENCE
# ==============================================================================
#
# Purpose:
#   Decide WHEN and HOW to transition between shots in a way that feels
#   directed, motivated, and invisible to the viewer.
#
#   This module prevents:
#     - Random shot switching
#     - Jarring reframes
#     - Rhythm-breaking cuts
#
#   Outputs transition intent, not hardware commands.
#
# ==============================================================================

from typing import Dict
import numpy as np


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class ShotTransitionEngine:
    """
    Evaluates if a shot transition is needed and how it should occur.
    """
    __slots__ = (
        "_time_in_shot",
        "_last_scale",
        "_last_motion",
    )
    def __init__(self):
        self._time_in_shot = 0.0
        self._last_scale = None
        self._last_motion = None
    def evaluate(
        self,
        current_shot: Dict[str, float],
        scene_change_score: float,
        subject_change_score: float,
        rhythm: Dict[str, float],
        dt: float,
    ) -> Dict[str, float]:
        """
        current_shot:
            Output from ShotGrammarEngine.
        scene_change_score:
            0..1 measure of scene discontinuity.
        subject_change_score:
            0..1 change in dominant subject.
        rhythm:
            { 'pace', 'tension' }
        """
        self._time_in_shot += dt
        pace = _clamp01(rhythm.get("pace", 0.5))
        tension = _clamp01(rhythm.get("tension", 0.5))
        scale = current_shot.get("scale", 0.5)
        motion = current_shot.get("motion", 0.5)
        # Minimum shot duration (cinema-safe)
        min_duration = 1.2 + (1.0 - pace) * 1.5
        transition_needed = False
        if self._time_in_shot > min_duration:
            if scene_change_score > 0.55:
                transition_needed = True
            elif subject_change_score > 0.65:
                transition_needed = True
            elif tension > 0.7 and pace > 0.6:
                transition_needed = True
        # Decide transition type
        transition_type = "hold"
        if transition_needed:
            if abs(scale - (self._last_scale or scale)) > 0.25:
                transition_type = "cut"
            elif motion > 0.6:
                transition_type = "whip"
            else:
                transition_type = "ease"
            self._time_in_shot = 0.0
        self._last_scale = scale
        self._last_motion = motion
        return {
            "transition": transition_type,
            "triggered": transition_needed,
        }
    def reset(self):
        """
        Reset transition state (hard cut / manual override).
        """
        self._time_in_shot = 0.0
        self._last_scale = None
        self._last_motion = None
# ==============================================================================
# END OF CHUNK 85 Y 02
# ==============================================================================
# ==============================================================================
# CHUNK 85 Y 03 — SHOT FAILURE DETECTION & RECOVERY
# ==============================================================================
#
# Purpose:
#   Detect when a shot is failing perceptually or technically and recover
#   gracefully without visible panic, jitter, or abrupt cuts.
#
#   Failure modes covered:
#     - Subject loss / occlusion
#     - Excessive motion blur or shake
#     - Exposure collapse or clipping
#     - Framing drift outside cinematic bounds
#
#   Output is recovery intent (hold, reframe, widen, reset), NOT hardware.
#
# ==============================================================================

from typing import Dict
import numpy as np


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class ShotFailureDetector:
    """
    Evaluates shot health and produces recovery strategies.
    """
    __slots__ = (
        "_loss_timer",
        "_blur_timer",
        "_exposure_timer",
        "_last_health",
    )
    def __init__(self):
        self._loss_timer = 0.0
        self._blur_timer = 0.0
        self._exposure_timer = 0.0
        self._last_health = 1.0
    def evaluate(
        self,
        tracking_confidence: float,
        motion_blur_score: float,
        exposure_health: float,
        framing_error: float,
        dt: float,
    ) -> Dict[str, float]:
        """
        tracking_confidence:
            0..1 confidence of subject tracking.
        motion_blur_score:
            0..1 where >0.6 is perceptually bad.
        exposure_health:
            0..1 where 1 = perfect, 0 = clipped/crushed.
        framing_error:
            0..1 deviation from ideal framing.
        """
        tc = _clamp01(tracking_confidence)
        blur = _clamp01(motion_blur_score)
        exp = _clamp01(exposure_health)
        frame_err = _clamp01(framing_error)
        # Timers accumulate only when bad
        self._loss_timer += dt if tc < 0.4 else -dt * 0.8
        self._blur_timer += dt if blur > 0.6 else -dt * 0.6
        self._exposure_timer += dt if exp < 0.5 else -dt * 0.7
        self._loss_timer = max(0.0, self._loss_timer)
        self._blur_timer = max(0.0, self._blur_timer)
        self._exposure_timer = max(0.0, self._exposure_timer)
        # Aggregate health score
        health = (
            tc * 0.35
            + (1.0 - blur) * 0.25
            + exp * 0.25
            + (1.0 - frame_err) * 0.15
        )
        health = _clamp01(health)
        # Determine recovery mode
        action = "none"
        if self._loss_timer > 0.6:
            action = "widen"
        elif self._blur_timer > 0.5:
            action = "stabilize"
        elif self._exposure_timer > 0.4:
            action = "exposure_reset"
        elif frame_err > 0.5:
            action = "reframe"
        # Prevent oscillation
        if health < self._last_health - 0.25:
            action = "hold"
        self._last_health = health
        return {
            "health": health,
            "recovery_action": action,
        }
    def reset(self):
        """
        Reset failure state (scene cut or manual intervention).
        """
        self._loss_timer = 0.0
        self._blur_timer = 0.0
        self._exposure_timer = 0.0
        self._last_health = 1.0
# ==============================================================================
# END OF CHUNK 85 Y 03
# ==============================================================================
# ==============================================================================
# CHUNK 85 Y 04 — SCENE TYPE CLASSIFICATION
# ==============================================================================
#
# Purpose:
#   Classify the current scene into high-level cinematic categories.
#   This acts as a semantic bridge between raw perception and shot grammar.
#
#   Scene types influence:
#     - Shot scale and duration
#     - Camera motion allowance
#     - Exposure and contrast bias
#     - Transition aggressiveness
#
#   Output is symbolic (scene label + confidence), not control signals.
#
# ==============================================================================

from typing import Dict
import numpy as np


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class SceneTypeClassifier:
    """
    Classifies scene context using perceptual + temporal cues.
    """
    __slots__ = (
        "_memory",
    )
    def __init__(self):
        self._memory: Dict[str, float] = {}
    def evaluate(
        self,
        subject_count: int,
        global_motion: float,
        saliency_entropy: float,
        audio_energy: float,
        intent: Dict[str, float],
    ) -> Dict[str, float]:
        """
        subject_count:
            Number of detected meaningful subjects.
        global_motion:
            0..1 measure of camera + scene motion.
        saliency_entropy:
            0..1 dispersion of attention across subjects.
        audio_energy:
            0..1 normalized audio intensity.
        intent:
            { 'emotion', 'aggressiveness' }
        """
        gm = _clamp01(global_motion)
        se = _clamp01(saliency_entropy)
        ae = _clamp01(audio_energy)
        emo = _clamp01(intent.get("emotion", 0.5))
        agg = _clamp01(intent.get("aggressiveness", 0.5))
        scores = {
            "action": (
                gm * 0.4
                + ae * 0.3
                + agg * 0.2
                + se * 0.1
            ),
            "dialog": (
                (1.0 - gm) * 0.3
                + (1.0 - se) * 0.3
                + emo * 0.3
                + (subject_count <= 2) * 0.1
            ),
            "establishing": (
                (1.0 - gm) * 0.4
                + se * 0.3
                + (subject_count > 3) * 0.2
                + (1.0 - ae) * 0.1
            ),
            "tracking": (
                gm * 0.3
                + (1.0 - se) * 0.3
                + (subject_count == 1) * 0.2
                + agg * 0.2
            ),
        }
        # Normalize and select
        for k in scores:
            scores[k] = max(0.0, scores[k])
        scene = max(scores, key=scores.get)
        confidence = scores[scene] / (sum(scores.values()) + 1e-6)
        # Temporal bias to prevent flicker
        prev = self._memory.get(scene, confidence)
        confidence = 0.7 * prev + 0.3 * confidence
        self._memory[scene] = confidence
        return {
            "scene": scene,
            "confidence": confidence,
        }
    def reset(self):
        """
        Reset classifier memory (hard cut).
        """
        self._memory.clear()
# ==============================================================================
# END OF CHUNK 85 Y 04
# ==============================================================================
# ==============================================================================
# CHUNK 85 Y 05 — NARRATIVE CONTINUITY ENFORCEMENT
# ==============================================================================
#
# Purpose:
#   Preserve narrative coherence across time by enforcing continuity rules.
#   This prevents the AI from violating classical film language, such as:
#     - Sudden emotional reversals
#     - Inconsistent framing scale jumps
#     - Directional discontinuities (screen direction flips)
#
#   This operates above shot grammar and below story intent.
#
# ==============================================================================

from typing import Dict
import numpy as np


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class NarrativeContinuityEngine:
    """
    Enforces cinematic continuity constraints across shots.
    """
    __slots__ = (
        "_last_scale",
        "_last_emotion",
        "_screen_dir",
        "_memory_strength",
    )
    def __init__(self, memory_strength: float = 0.65):
        """
        memory_strength:
            How strongly previous narrative state influences the next shot.
        """
        self._memory_strength = _clamp01(memory_strength)
        self._last_scale = None
        self._last_emotion = None
        self._screen_dir = None
    def enforce(
        self,
        proposed_shot: Dict[str, float],
        subject_direction: float,
    ) -> Dict[str, float]:
        """
        proposed_shot:
            { 'scale', 'emotion_bias', 'motion' }
        subject_direction:
            -1..1 screen-space direction of primary subject.
        """
        shot = dict(proposed_shot)
        # Scale continuity (avoid jump cuts)
        if self._last_scale is not None:
            delta = shot["scale"] - self._last_scale
            max_jump = 0.35
            if abs(delta) > max_jump:
                shot["scale"] = (
                    self._last_scale
                    + np.sign(delta) * max_jump
                )
        # Emotional continuity (no sudden flips)
        if self._last_emotion is not None:
            emo_delta = shot["emotion_bias"] - self._last_emotion
            if abs(emo_delta) > 0.4:
                shot["emotion_bias"] = (
                    self._last_emotion
                    + emo_delta * 0.5
                )
        # Screen direction continuity (180-degree rule)
        cur_dir = np.sign(subject_direction)
        if self._screen_dir is not None:
            if cur_dir != 0 and cur_dir != self._screen_dir:
                shot["motion"] *= 0.6
        # Update memory
        self._last_scale = (
            shot["scale"] * self._memory_strength
            + (self._last_scale or shot["scale"]) * (1.0 - self._memory_strength)
        )
        self._last_emotion = (
            shot["emotion_bias"] * self._memory_strength
            + (self._last_emotion or shot["emotion_bias"])
            * (1.0 - self._memory_strength)
        )
        if cur_dir != 0:
            self._screen_dir = cur_dir
        return shot
    def reset(self):
        """
        Reset narrative memory (hard cut, montage, or manual override).
        """
        self._last_scale = None
        self._last_emotion = None
        self._screen_dir = None
