# CHUNK 85 Y 06 — RHYTHM & PACING CONTROL
# ==============================================================================
#
# Purpose:
#   Control temporal rhythm of shots to achieve film-grade pacing.
#   This governs how long shots live, how intensity ramps,
#   and how visual tempo aligns with emotion and motion.
#
#   This module sits ABOVE shot transitions and BELOW narrative intent.
#
# ==============================================================================

from typing import Dict
import numpy as np


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class RhythmPacingController:
    """
    Governs cinematic rhythm over time.
    """
    __slots__ = (
        "_tempo",
        "_energy",
        "_breath",
    )
    def __init__(self):
        self._tempo = 0.5
        self._energy = 0.5
        self._breath = 0.5
    def update(
        self,
        scene_type: str,
        motion_level: float,
        emotion_level: float,
        dt: float,
    ) -> Dict[str, float]:
        """
        scene_type:
            'action', 'dialog', 'establishing', 'tracking'
        motion_level:
            0..1 perceived kinetic intensity
        emotion_level:
            0..1 emotional weight
        """
        mot = _clamp01(motion_level)
        emo = _clamp01(emotion_level)
        # Base tempo by scene
        if scene_type == "action":
            target_tempo = 0.75 + mot * 0.25
        elif scene_type == "dialog":
            target_tempo = 0.35 + emo * 0.2
        elif scene_type == "establishing":
            target_tempo = 0.25
        else:
            target_tempo = 0.45 + mot * 0.2
        # Energy reflects visual intensity
        target_energy = (
            mot * 0.6
            + emo * 0.4
        )
        # Breath controls micro-pauses (cinematic rest)
        target_breath = (
            1.0 - target_tempo
        ) * (0.6 + emo * 0.4)
        # Smooth updates (director inertia)
        a = _clamp01(dt * 1.5)
        self._tempo = self._tempo + (target_tempo - self._tempo) * a
        self._energy = self._energy + (target_energy - self._energy) * a
        self._breath = self._breath + (target_breath - self._breath) * a
        return {
            "tempo": self._tempo,
            "energy": self._energy,
            "breath": self._breath,
        }
    def reset(self):
        """
        Reset pacing state (montage, hard cut, or manual override).
        """
        self._tempo = 0.5
        self._energy = 0.5
        self._breath = 0.5
