# ==============================================================================

from typing import Dict
import numpy as np


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class IntentConflictResolver:
    """
    Resolves conflicts between multiple intent proposals.
    """
    __slots__ = (
        "_priority_weights",
    )
    def __init__(self):
        # Higher value = stronger authority
        self._priority_weights = {
            "human": 1.00,
            "failure": 0.90,
            "narrative": 0.80,
            "rhythm": 0.65,
            "grammar": 0.60,
            "scene": 0.55,
        }
    def resolve(
        self,
        intents: Dict[str, Dict[str, float]],
    ) -> Dict[str, float]:
        """
        intents:
            {
              'grammar': {...},
              'narrative': {...},
              'rhythm': {...},
              'failure': {...},
              'human': {...}
            }
        """
        resolved: Dict[str, float] = {}
        accum: Dict[str, float] = {}
        for source, values in intents.items():
            w = self._priority_weights.get(source, 0.5)
            for k, v in values.items():
                v = _clamp01(float(v))
                accum[k] = accum.get(k, 0.0) + v * w
        # Normalize per parameter
        for k, total in accum.items():
            max_w = sum(self._priority_weights.values())
            resolved[k] = _clamp01(total / max_w)
        return resolved
