# ==============================================================================

from typing import Dict
import numpy as np


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class DirectorOverrideFusion:
    """
    Fuses autonomous AI intent with human-provided cinematic intent.
    """
    __slots__ = (
        "_authority",
        "_decay_rate",
    )
    def __init__(
        self,
        default_authority: float = 0.25,
        decay_rate: float = 0.6,
    ):
        """
        default_authority:
            How much human intent biases AI when active (0..1).
        decay_rate:
            How quickly manual bias fades back to AI control.
        """
        self._authority = _clamp01(default_authority)
        self._decay_rate = _clamp01(decay_rate)
    def fuse(
        self,
        ai_intent: Dict[str, float],
        human_intent: Dict[str, float],
        dt: float,
    ) -> Dict[str, float]:
        """
        ai_intent:
            Autonomous intent dictionary.
        human_intent:
            Live user input intent (may be partial or empty).
        """
        fused: Dict[str, float] = {}
        # If no human input, decay authority back toward zero
        if not human_intent:
            self._authority *= max(0.0, 1.0 - self._decay_rate * dt)
        else:
            # When human interacts, authority ramps up
            self._authority = _clamp01(self._authority + dt * 0.5)
        for k, ai_val in ai_intent.items():
            ai_v = _clamp01(float(ai_val))
            human_v = _clamp01(human_intent.get(k, ai_v))
            fused_v = (
                ai_v * (1.0 - self._authority)
                + human_v * self._authority
            )
            fused[k] = _clamp01(fused_v)
        return fused
    def force_override(self, strength: float = 1.0):
        """
        Immediately grant full human authority.
        """
        self._authority = _clamp01(strength)
    def reset(self):
        """
        Reset override state.
        """
        self._authority = 0.0
