from typing import Dict, Any
import numpy as np
import time


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, x))


class CameraAIState:
    """
    Persistent internal state of the camera AI.
    """
    __slots__ = (
        "exposure_bias",
        "focus_bias",
        "framing_bias",
        "stability_bias",
        "last_update_ts",
        "scene_confidence",
    )
    def __init__(self):
        self.exposure_bias = 0.5
        self.focus_bias = 0.5
        self.framing_bias = 0.5
        self.stability_bias = 0.5
        self.scene_confidence = 0.0
        self.last_update_ts = time.time()


class AutonomousCameraAICore:
    """
    Entry point for camera AI decision-making.
    """
    __slots__ = (
        "_state",
        "_adapt_rate",
    )
    def __init__(self, adapt_rate: float = 0.35):
        """
        adapt_rate:
            How aggressively camera AI adapts to new scenes.
        """
        self._state = CameraAIState()
        self._adapt_rate = _clamp(adapt_rate, 0.05, 1.0)
    def update(
        self,
        frame_stats: Dict[str, float],
        gyro_stats: Dict[str, float],
        subject_stats: Dict[str, float],
    ) -> Dict[str, float]:
        """
        frame_stats:
            luminance_mean, luminance_contrast, highlight_ratio
        gyro_stats:
            motion_energy, angular_velocity
        subject_stats:
            subject_area, subject_confidence, subject_velocity
        """
        now = time.time()
        dt = max(1e-3, now - self._state.last_update_ts)
        self._state.last_update_ts = now
        # ------------------------------
        # Scene confidence estimation
        # ------------------------------
        conf = _clamp(subject_stats.get("subject_confidence", 0.0))
        self._state.scene_confidence = (
            0.8 * self._state.scene_confidence + 0.2 * conf
        )
        # ------------------------------
        # Exposure intent
        # ------------------------------
        lum = frame_stats.get("luminance_mean", 0.5)
        highlights = frame_stats.get("highlight_ratio", 0.0)
        target_exp = 0.5
        target_exp -= (lum - 0.5) * 0.7
        target_exp -= highlights * 0.4
        self._state.exposure_bias += (
            target_exp - self._state.exposure_bias
        ) * self._adapt_rate * dt
        self._state.exposure_bias = _clamp(self._state.exposure_bias)
        # ------------------------------
        # Focus intent
        # ------------------------------
        subj_area = subject_stats.get("subject_area", 0.0)
        target_focus = _clamp(0.6 + subj_area * 0.4)
        self._state.focus_bias += (
            target_focus - self._state.focus_bias
        ) * self._adapt_rate * dt
        self._state.focus_bias = _clamp(self._state.focus_bias)
        # ------------------------------
        # Framing intent
        # ------------------------------
        subj_vel = subject_stats.get("subject_velocity", 0.0)
        target_frame = _clamp(0.5 + subj_vel * 0.3)
        self._state.framing_bias += (
            target_frame - self._state.framing_bias
        ) * self._adapt_rate * dt
        self._state.framing_bias = _clamp(self._state.framing_bias)
        # ------------------------------
        # Stability intent
        # ------------------------------
        motion = gyro_stats.get("motion_energy", 0.0)
        target_stab = _clamp(1.0 - motion)
        self._state.stability_bias += (
            target_stab - self._state.stability_bias
        ) * self._adapt_rate * dt
        self._state.stability_bias = _clamp(self._state.stability_bias)
        # ------------------------------
        # Emit normalized camera intent
        # ------------------------------
        return {
            "exposure": self._state.exposure_bias,
            "focus": self._state.focus_bias,
            "framing": self._state.framing_bias,
            "stability": self._state.stability_bias,
            "confidence": self._state.scene_confidence,
        }
