from enum import Enum
from typing import Dict
import time
import math


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class CameraAIStateID(Enum):
    INIT = 0
    IDLE = 1
    SEARCHING = 2
    TRACKING = 3
    ACTION = 4
    LOW_LIGHT = 5
    HIGH_CONTRAST = 6
    FAILSAFE = 7


class CameraAIStateMachine:
    """
    Deterministic state machine governing camera AI behavior.
    """
    __slots__ = (
        "_state",
        "_state_enter_ts",
        "_min_state_time",
    )
    def __init__(self, min_state_time: float = 0.35):
        """
        min_state_time:
            Minimum time (seconds) to remain in a state before transition.
        """
        self._state = CameraAIStateID.INIT
        self._state_enter_ts = time.time()
        self._min_state_time = max(0.05, min_state_time)
    @property
    def state(self) -> CameraAIStateID:
        return self._state
    def _can_transition(self) -> bool:
        return (time.time() - self._state_enter_ts) >= self._min_state_time
    def _set_state(self, new_state: CameraAIStateID):
        self._state = new_state
        self._state_enter_ts = time.time()
    def update(
        self,
        camera_intent: Dict[str, float],
        frame_stats: Dict[str, float],
        subject_stats: Dict[str, float],
    ) -> CameraAIStateID:
        """
        Decide next camera AI state.
        camera_intent:
            Output from AutonomousCameraAICore.
        frame_stats:
            luminance_mean, contrast, highlight_ratio
        subject_stats:
            subject_confidence, subject_velocity
        """
        if not self._can_transition():
            return self._state
        lum = frame_stats.get("luminance_mean", 0.5)
        contrast = frame_stats.get("contrast", 0.5)
        highlights = frame_stats.get("highlight_ratio", 0.0)
        subj_conf = subject_stats.get("subject_confidence", 0.0)
        subj_vel = subject_stats.get("subject_velocity", 0.0)
        # ------------------------------
        # INIT → IDLE
        # ------------------------------
        if self._state == CameraAIStateID.INIT:
            self._set_state(CameraAIStateID.IDLE)
            return self._state
        # ------------------------------
        # FAILSAFE conditions
        # ------------------------------
        if math.isnan(lum) or math.isnan(contrast):
            self._set_state(CameraAIStateID.FAILSAFE)
            return self._state
        # ------------------------------
        # LOW LIGHT
        # ------------------------------
        if lum < 0.18:
            if self._state != CameraAIStateID.LOW_LIGHT:
                self._set_state(CameraAIStateID.LOW_LIGHT)
            return self._state
        # ------------------------------
        # HIGH CONTRAST
        # ------------------------------
        if contrast > 0.75 or highlights > 0.25:
            if self._state != CameraAIStateID.HIGH_CONTRAST:
                self._set_state(CameraAIStateID.HIGH_CONTRAST)
            return self._state
        # ------------------------------
        # SUBJECT-AWARE STATES
        # ------------------------------
        if subj_conf < 0.25:
            if self._state != CameraAIStateID.SEARCHING:
                self._set_state(CameraAIStateID.SEARCHING)
            return self._state
        if subj_vel > 0.4:
            if self._state != CameraAIStateID.ACTION:
                self._set_state(CameraAIStateID.ACTION)
            return self._state
        # ------------------------------
        # DEFAULT TRACKING
        # ------------------------------
        if self._state != CameraAIStateID.TRACKING:
            self._set_state(CameraAIStateID.TRACKING)
        return self._state
    def cinematic_bias(self) -> Dict[str, float]:
        """
        Returns per-state cinematic bias multipliers.
        """
        if self._state == CameraAIStateID.LOW_LIGHT:
            return {
                "exposure": 1.15,
                "stability": 1.1,
            }
        if self._state == CameraAIStateID.HIGH_CONTRAST:
            return {
                "exposure": 0.9,
                "framing": 0.95,
            }
        if self._state == CameraAIStateID.ACTION:
            return {
                "stability": 1.25,
                "framing": 1.1,
            }
        if self._state == CameraAIStateID.SEARCHING:
            return {
                "framing": 1.15,
            }
        if self._state == CameraAIStateID.FAILSAFE:
            return {
                "exposure": 0.5,
                "focus": 0.5,
                "framing": 0.5,
                "stability": 1.5,
            }
        return {}
