# ==============================================================================
# CHUNK 85 Z 03 — CAMERA AI FAIL-SAFE LOGIC
# ==============================================================================
#
# Purpose:
#   Provide deterministic, bounded, and reversible fail-safe behavior
#   for camera AI subsystems when confidence collapses or telemetry degrades.
#
#   Guarantees:
#     - No runaway exposure or focus hunting
#     - Stable framing under data loss
#     - Graceful recovery without hard resets
#
#   Scope:
#     Camera-side AI only (no flight control).
#
# ==============================================================================

from typing import Dict
import numpy as np
import math
import time


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class CameraAIFailsafe:
    """
    Centralized fail-safe arbitration for camera AI outputs.
    """
    __slots__ = (
        "_last_good_intent",
        "_last_good_ts",
        "_hold_time",
        "_decay_tau",
    )
    def __init__(
        self,
        hold_time: float = 0.45,
        decay_tau: float = 0.35,
    ):
        """
        hold_time:
            Duration to hold last-known-good intent during failure.
        decay_tau:
            Exponential decay constant back to neutral intent.
        """
        self._last_good_intent: Dict[str, float] = {}
        self._last_good_ts: float = 0.0
        self._hold_time = max(0.1, hold_time)
        self._decay_tau = max(0.05, decay_tau)
    def _is_invalid(self, v: float) -> bool:
        return (
            math.isnan(v)
            or math.isinf(v)
            or v < -1.0
            or v > 2.0
        )
    def _intent_invalid(self, intent: Dict[str, float]) -> bool:
        if not intent:
            return True
        for v in intent.values():
            if self._is_invalid(float(v)):
                return True
        return False
    def update(
        self,
        intent: Dict[str, float],
        confidence: float,
        now: float | None = None,
    ) -> Dict[str, float]:
        """
        Validate and sanitize camera AI intent.
        confidence:
            Global AI confidence (0..1).
        """
        ts = time.time() if now is None else now
        # ------------------------------
        # Healthy intent path
        # ------------------------------
        if confidence >= 0.35 and not self._intent_invalid(intent):
            self._last_good_intent = {
                k: _clamp01(float(v)) for k, v in intent.items()
            }
            self._last_good_ts = ts
            return self._last_good_intent
        # ------------------------------
        # Fail-safe: hold last good
        # ------------------------------
        dt = ts - self._last_good_ts
        if self._last_good_intent and dt <= self._hold_time:
            return dict(self._last_good_intent)
        # ------------------------------
        # Controlled decay to neutral
        # ------------------------------
        decayed: Dict[str, float] = {}
        if self._last_good_intent:
            alpha = math.exp(-dt / self._decay_tau)
            for k, v in self._last_good_intent.items():
                neutral = 0.5
                decayed[k] = _clamp01(neutral + (v - neutral) * alpha)
        else:
            decayed = {
                "exposure": 0.5,
                "focus": 0.5,
                "framing": 0.5,
                "stability": 1.0,
            }
        return decayed
    def hard_neutral(self) -> Dict[str, float]:
        """
        Immediate safe-neutral intent.
        """
        return {
            "exposure": 0.5,
            "focus": 0.5,
            "framing": 0.5,
            "stability": 1.2,
        }
