# ==============================================================================
# CHUNK 85 Z 04 — CAMERA AI EXPOSURE AUTHORITY
# ==============================================================================
#
# Purpose:
#   Resolve final exposure intent by arbitrating between:
#     - Scene luminance statistics
#     - Subject importance & skin-tone protection
#     - Cinematic intent (mood preservation)
#     - Safety bounds (highlight & shadow retention)
#
#   This module DOES NOT set ISO/shutter directly.
#   It outputs a normalized exposure authority signal (0..1).
#
# ==============================================================================

from typing import Dict
import math
import numpy as np


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class CameraAIExposureAuthority:
    """
    Computes a cinematic exposure authority signal.
    """
    __slots__ = (
        "_highlight_guard",
        "_shadow_guard",
        "_skin_protect",
    )
    def __init__(
        self,
        highlight_guard: float = 0.75,
        shadow_guard: float = 0.35,
        skin_protect: float = 0.6,
    ):
        """
        highlight_guard:
            Bias strength to protect highlights.
        shadow_guard:
            Bias strength to preserve shadow texture.
        skin_protect:
            Weight for subject skin-tone preservation.
        """
        self._highlight_guard = _clamp01(highlight_guard)
        self._shadow_guard = _clamp01(shadow_guard)
        self._skin_protect = _clamp01(skin_protect)
    def compute(
        self,
        frame_stats: Dict[str, float],
        subject_stats: Dict[str, float],
        cinematic_bias: Dict[str, float],
    ) -> float:
        """
        frame_stats:
            luminance_mean, highlight_ratio, shadow_ratio
        subject_stats:
            subject_confidence, skin_luma
        cinematic_bias:
            Optional bias from state machine.
        """
        lum = frame_stats.get("luminance_mean", 0.5)
        hi = frame_stats.get("highlight_ratio", 0.0)
        sh = frame_stats.get("shadow_ratio", 0.0)
        subj_conf = subject_stats.get("subject_confidence", 0.0)
        skin_luma = subject_stats.get("skin_luma", lum)
        # ------------------------------
        # Base exposure anchor
        # ------------------------------
        base = 0.5 + (0.5 - lum)
        # ------------------------------
        # Highlight protection
        # ------------------------------
        highlight_penalty = hi * self._highlight_guard
        # ------------------------------
        # Shadow recovery
        # ------------------------------
        shadow_boost = sh * self._shadow_guard
        # ------------------------------
        # Skin-tone preservation
        # ------------------------------
        skin_error = (0.55 - skin_luma)
        skin_bias = skin_error * self._skin_protect * subj_conf
        exposure = base - highlight_penalty + shadow_boost + skin_bias
        # ------------------------------
        # Cinematic bias injection
        # ------------------------------
        exposure *= cinematic_bias.get("exposure", 1.0)
        # ------------------------------
        # Soft compression (prevents jumps)
        # ------------------------------
        exposure = 0.5 + math.tanh((exposure - 0.5) * 1.4) * 0.5
        return _clamp01(exposure)
