# CHUNK 85 Z 05 — CAMERA AI FOCUS & DEPTH CONTROL
# ==============================================================================
#
# Purpose:
#   Compute a stable, cinematic focus & depth intent that balances:
#     - Subject priority and confidence
#     - Motion-aware focus damping
#     - Depth-of-field aesthetics (cinematic separation)
#     - Temporal continuity (no focus hunting)
#
#   Output:
#     Normalized focus intent (0..1) and depth bias (0..1)
#
# ==============================================================================

from typing import Dict, Tuple
import math
import time


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class CameraAIFocusDepth:
    """
    Focus and depth intent generator with cinematic damping.
    """
    __slots__ = (
        "_last_focus",
        "_last_depth",
        "_last_ts",
        "_tau_focus",
        "_tau_depth",
    )
    def __init__(
        self,
        tau_focus: float = 0.28,
        tau_depth: float = 0.45,
    ):
        """
        tau_focus:
            Time constant for focus smoothing (seconds).
        tau_depth:
            Time constant for depth bias smoothing (seconds).
        """
        self._last_focus = 0.5
        self._last_depth = 0.5
        self._last_ts = time.time()
        self._tau_focus = max(0.05, tau_focus)
        self._tau_depth = max(0.05, tau_depth)
    def _smooth(self, prev: float, target: float, dt: float, tau: float) -> float:
        alpha = 1.0 - math.exp(-dt / tau)
        return prev + alpha * (target - prev)
    def compute(
        self,
        subject_stats: Dict[str, float],
        motion_stats: Dict[str, float],
        cinematic_bias: Dict[str, float],
        now: float | None = None,
    ) -> Tuple[float, float]:
        """
        subject_stats:
            subject_confidence, subject_depth, subject_size
        motion_stats:
            camera_motion, subject_velocity
        cinematic_bias:
            Optional state-machine bias
        """
        ts = time.time() if now is None else now
        dt = max(1e-3, ts - self._last_ts)
        self._last_ts = ts
        subj_conf = subject_stats.get("subject_confidence", 0.0)
        subj_depth = subject_stats.get("subject_depth", 0.5)
        subj_size = subject_stats.get("subject_size", 0.5)
        cam_motion = motion_stats.get("camera_motion", 0.0)
        subj_vel = motion_stats.get("subject_velocity", 0.0)
        # ------------------------------
        # Target focus computation
        # ------------------------------
        focus_target = subj_depth
        # Reduce aggressive refocus under motion
        motion_damp = 1.0 - _clamp01(0.6 * cam_motion + 0.4 * subj_vel)
        focus_target = (
            self._last_focus * (1.0 - subj_conf)
            + focus_target * subj_conf
        )
        focus_target = (
            self._last_focus * (1.0 - motion_damp)
            + focus_target * motion_damp
        )
        # ------------------------------
        # Depth-of-field bias
        # ------------------------------
        # Larger subjects → shallower depth for separation
        depth_target = 0.6 - 0.25 * subj_size
        # Motion prefers deeper depth for safety
        depth_target += 0.2 * (cam_motion + subj_vel)
        # Cinematic bias
        depth_target *= cinematic_bias.get("focus", 1.0)
        # ------------------------------
        # Temporal smoothing
        # ------------------------------
        focus_smoothed = self._smooth(
            self._last_focus,
            _clamp01(focus_target),
            dt,
            self._tau_focus,
        )
        depth_smoothed = self._smooth(
            self._last_depth,
            _clamp01(depth_target),
            dt,
            self._tau_depth,
        )
        self._last_focus = focus_smoothed
        self._last_depth = depth_smoothed
        return focus_smoothed, depth_smoothed
