# CHUNK 85 Z 06 — CAMERA AI FRAMING & COMPOSITION ENGINE
# ==============================================================================
#
# Purpose:
#   Generate cinematic framing intent using perceptual composition rules:
#     - Rule-of-thirds & dynamic center bias
#     - Subject lead-room & look-room
#     - Motion-aware reframing (no snap)
#     - Horizon & roll stability bias
#
#   Output:
#     Normalized framing vector:
#       {
#         "x": horizontal framing bias (0..1),
#         "y": vertical framing bias (0..1),
#         "scale": crop / zoom bias (0..1)
#       }
#
# ==============================================================================

from typing import Dict
import math
import time


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class CameraAIFramingEngine:
    """
    Cinematic framing & composition resolver.
    """
    __slots__ = (
        "_last_x",
        "_last_y",
        "_last_scale",
        "_last_ts",
        "_tau_pos",
        "_tau_scale",
    )
    def __init__(
        self,
        tau_position: float = 0.32,
        tau_scale: float = 0.45,
    ):
        """
        tau_position:
            Time constant for framing position smoothing.
        tau_scale:
            Time constant for zoom/crop smoothing.
        """
        self._last_x = 0.5
        self._last_y = 0.5
        self._last_scale = 0.5
        self._last_ts = time.time()
        self._tau_pos = max(0.05, tau_position)
        self._tau_scale = max(0.05, tau_scale)
    def _smooth(self, prev: float, target: float, dt: float, tau: float) -> float:
        alpha = 1.0 - math.exp(-dt / tau)
        return prev + alpha * (target - prev)
    def compute(
        self,
        subject_stats: Dict[str, float],
        motion_stats: Dict[str, float],
        horizon_stats: Dict[str, float],
        cinematic_bias: Dict[str, float],
        now: float | None = None,
    ) -> Dict[str, float]:
        """
        subject_stats:
            subject_x, subject_y, subject_size, subject_velocity_x
        motion_stats:
            camera_motion
        horizon_stats:
            horizon_y, roll_angle
        """
        ts = time.time() if now is None else now
        dt = max(1e-3, ts - self._last_ts)
        self._last_ts = ts
        subj_x = subject_stats.get("subject_x", 0.5)
        subj_y = subject_stats.get("subject_y", 0.5)
        subj_size = subject_stats.get("subject_size", 0.5)
        subj_vel_x = subject_stats.get("subject_velocity_x", 0.0)
        cam_motion = motion_stats.get("camera_motion", 0.0)
        horizon_y = horizon_stats.get("horizon_y", 0.5)
        roll = abs(horizon_stats.get("roll_angle", 0.0))
        # ------------------------------
        # Rule-of-thirds anchor
        # ------------------------------
        thirds_x = 0.33 if subj_x < 0.5 else 0.66
        thirds_y = 0.38
        # Blend between center & thirds
        thirds_weight = _clamp01(subj_size * 1.2)
        x_target = (1.0 - thirds_weight) * 0.5 + thirds_weight * thirds_x
        y_target = (1.0 - thirds_weight) * 0.5 + thirds_weight * thirds_y
        # ------------------------------
        # Lead-room (look direction)
        # ------------------------------
        x_target += 0.15 * math.tanh(subj_vel_x * 2.0)
        # ------------------------------
        # Horizon stabilization
        # ------------------------------
        horizon_pull = _clamp01(1.0 - roll * 2.0)
        y_target = (
            y_target * horizon_pull
            + horizon_y * (1.0 - horizon_pull)
        )
        # ------------------------------
        # Zoom / crop logic
        # ------------------------------
        scale_target = 0.65 - 0.3 * subj_size
        scale_target += 0.25 * cam_motion
        scale_target *= cinematic_bias.get("framing", 1.0)
        # ------------------------------
        # Temporal smoothing
        # ------------------------------
        x_s = self._smooth(self._last_x, _clamp01(x_target), dt, self._tau_pos)
        y_s = self._smooth(self._last_y, _clamp01(y_target), dt, self._tau_pos)
        s_s = self._smooth(self._last_scale, _clamp01(scale_target), dt, self._tau_scale)
        self._last_x = x_s
        self._last_y = y_s
        self._last_scale = s_s
        return {
            "x": x_s,
            "y": y_s,
            "scale": s_s,
        }
