from typing import Dict
import math
import time


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class CameraAITemporalGuard:
    """
    Long-horizon temporal stabilizer for camera AI intent vectors.
    """
    __slots__ = (
        "_state",
        "_last_ts",
        "_tau_fast",
        "_tau_slow",
        "_variance_floor",
    )
    def __init__(
        self,
        tau_fast: float = 0.18,
        tau_slow: float = 0.85,
        variance_floor: float = 0.002,
    ):
        """
        tau_fast:
            Time constant for fast legitimate transitions.
        tau_slow:
            Time constant for slow baseline stabilization.
        variance_floor:
            Minimum variance before freezing motion.
        """
        self._state: Dict[str, float] = {}
        self._last_ts = time.time()
        self._tau_fast = max(0.05, tau_fast)
        self._tau_slow = max(0.2, tau_slow)
        self._variance_floor = max(1e-6, variance_floor)
    def _adaptive_smooth(
        self,
        prev: float,
        target: float,
        dt: float,
        variance: float,
    ) -> float:
        """
        Smooth with adaptive time constant based on signal variance.
        """
        tau = (
            self._tau_fast
            if variance > self._variance_floor
            else self._tau_slow
        )
        alpha = 1.0 - math.exp(-dt / tau)
        return prev + alpha * (target - prev)
    def update(
        self,
        intent: Dict[str, float],
        confidence: float,
        now: float | None = None,
    ) -> Dict[str, float]:
        """
        Stabilize camera AI intent across time.
        intent:
            Raw intent dictionary (normalized).
        confidence:
            Global camera AI confidence (0..1).
        """
        ts = time.time() if now is None else now
        dt = max(1e-3, ts - self._last_ts)
        self._last_ts = ts
        if not self._state:
            self._state = {k: _clamp01(v) for k, v in intent.items()}
            return dict(self._state)
        stabilized: Dict[str, float] = {}
        for k, target in intent.items():
            prev = self._state.get(k, target)
            # Confidence gates aggressiveness
            gated_target = (
                prev * (1.0 - confidence)
                + target * confidence
            )
            variance = abs(gated_target - prev)
            smoothed = self._adaptive_smooth(
                prev,
                gated_target,
                dt,
                variance,
            )
            stabilized[k] = _clamp01(smoothed)
        self._state = stabilized
        return stabilized
    def reset(self):
        """
        Reset temporal memory.
        """
        self._state.clear()
