from typing import Dict
import math
import time


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class CameraAIConfidenceEstimator:
    """
    Computes a robust global confidence score for camera AI.
    """
    __slots__ = (
        "_last_confidence",
        "_last_ts",
        "_tau",
    )
    def __init__(self, tau: float = 0.6):
        """
        tau:
            Time constant for confidence stabilization (seconds).
        """
        self._last_confidence = 0.0
        self._last_ts = time.time()
        self._tau = max(0.1, tau)
    def _smooth(self, prev: float, target: float, dt: float) -> float:
        alpha = 1.0 - math.exp(-dt / self._tau)
        return prev + alpha * (target - prev)
    def compute(
        self,
        perception_stats: Dict[str, float],
        motion_stats: Dict[str, float],
        frame_stats: Dict[str, float],
        now: float | None = None,
    ) -> float:
        """
        perception_stats:
            subject_confidence, detection_stability
        motion_stats:
            camera_motion, subject_velocity
        frame_stats:
            luminance_mean, contrast
        """
        ts = time.time() if now is None else now
        dt = max(1e-3, ts - self._last_ts)
        self._last_ts = ts
        subj_conf = perception_stats.get("subject_confidence", 0.0)
        detect_stability = perception_stats.get("detection_stability", 0.0)
        cam_motion = motion_stats.get("camera_motion", 0.0)
        subj_vel = motion_stats.get("subject_velocity", 0.0)
        lum = frame_stats.get("luminance_mean", 0.5)
        contrast = frame_stats.get("contrast", 0.5)
        # ------------------------------
        # Base perception confidence
        # ------------------------------
        perception_score = (
            0.65 * _clamp01(subj_conf)
            + 0.35 * _clamp01(detect_stability)
        )
        # ------------------------------
        # Motion penalty
        # ------------------------------
        motion_penalty = _clamp01(0.6 * cam_motion + 0.4 * subj_vel)
        # ------------------------------
        # Exposure reliability penalty
        # ------------------------------
        exposure_penalty = abs(lum - 0.5) * 0.4 + max(0.0, contrast - 0.7)
        # ------------------------------
        # Raw confidence synthesis
        # ------------------------------
        raw_confidence = (
            perception_score
            * (1.0 - motion_penalty)
            * (1.0 - exposure_penalty)
        )
        raw_confidence = _clamp01(raw_confidence)
        # ------------------------------
        # Temporal stabilization
        # ------------------------------
        smoothed = self._smooth(self._last_confidence, raw_confidence, dt)
        # Prevent sudden confidence spikes
        smoothed = min(smoothed, self._last_confidence + 0.25)
        self._last_confidence = _clamp01(smoothed)
        return self._last_confidence
    def force_low(self):
        """
        Immediately drop confidence (used by hard fail-safe).
        """
        self._last_confidence = 0.0
