from typing import Dict
import math


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


class CameraAIMultiCameraArbitration:
    """
    Arbitration layer for multi-camera AI intent fusion.
    """
    __slots__ = (
        "_primary_weight",
        "_secondary_weight",
    )
    def __init__(
        self,
        primary_weight: float = 0.7,
        secondary_weight: float = 0.3,
    ):
        """
        primary_weight:
            Weight of primary cinematic camera intent.
        secondary_weight:
            Weight of auxiliary camera intent (reference / gyro).
        """
        total = max(1e-6, primary_weight + secondary_weight)
        self._primary_weight = primary_weight / total
        self._secondary_weight = secondary_weight / total
    def fuse(
        self,
        primary_intent: Dict[str, float],
        secondary_intent: Dict[str, float],
        primary_confidence: float,
        secondary_confidence: float,
    ) -> Dict[str, float]:
        """
        Combine intents using confidence-aware weighting.
        """
        fused: Dict[str, float] = {}
        # Confidence-adjusted weights
        wp = self._primary_weight * _clamp01(primary_confidence)
        ws = self._secondary_weight * _clamp01(secondary_confidence)
        norm = max(1e-6, wp + ws)
        wp /= norm
        ws /= norm
        keys = set(primary_intent.keys()) | set(secondary_intent.keys())
        for k in keys:
            pv = _clamp01(primary_intent.get(k, 0.5))
            sv = _clamp01(secondary_intent.get(k, pv))
            fused_val = wp * pv + ws * sv
            fused[k] = _clamp01(fused_val)
        return fused
    def reweight(
        self,
        primary_weight: float,
        secondary_weight: float,
    ):
        """
        Dynamically adjust camera authority (e.g. during calibration).
        """
        total = max(1e-6, primary_weight + secondary_weight)
        self._primary_weight = primary_weight / total
        self._secondary_weight = secondary_weight / total
