from typing import Dict, Any
import math
import json


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, x))


def _finite(x: float, default: float = 0.5) -> float:
    if x is None or isinstance(x, bool):
        return default
    try:
        xf = float(x)
    except Exception:
        return default
    if math.isnan(xf) or math.isinf(xf):
        return default
    return xf


class CameraAIIntentNormalizer:
    """
    Final authority for camera AI intent normalization and export.
    """
    __slots__ = (
        "_schema",
    )
    def __init__(self):
        """
        Schema defines:
          key -> (default, min, max)
        """
        self._schema: Dict[str, tuple[float, float, float]] = {
            # Exposure & tone
            "exposure": (0.5, 0.0, 1.0),
            # Focus & depth
            "focus": (0.5, 0.0, 1.0),
            "depth": (0.5, 0.0, 1.0),
            # Framing & composition
            "frame_x": (0.5, 0.0, 1.0),
            "frame_y": (0.5, 0.0, 1.0),
            "frame_scale": (0.5, 0.0, 1.0),
            # Stabilization intent
            "stability": (1.0, 0.5, 1.5),
            # Confidence (diagnostic)
            "confidence": (0.0, 0.0, 1.0),
        }
    def normalize(self, intent: Dict[str, Any]) -> Dict[str, float]:
        """
        Normalize arbitrary intent dictionary into canonical form.
        """
        out: Dict[str, float] = {}
        for key, (default, lo, hi) in self._schema.items():
            raw = intent.get(key, default)
            val = _finite(raw, default)
            val = max(lo, min(hi, val))
            out[key] = float(val)
        return out
    def pack(self, intent: Dict[str, float]) -> Dict[str, float]:
        """
        Alias for normalize (semantic clarity).
        """
        return self.normalize(intent)
    def serialize_json(self, intent: Dict[str, float]) -> str:
        """
        Deterministic JSON serialization for cloud / logging / IPC.
        """
        packed = self.normalize(intent)
        return json.dumps(
            packed,
            sort_keys=True,
            separators=(",", ":"),
        )
    def validate(self, intent: Dict[str, float]) -> bool:
        """
        Strict validation check (no mutation).
        """
        for key, (default, lo, hi) in self._schema.items():
            if key not in intent:
                return False
            v = intent[key]
            if not isinstance(v, (int, float)):
                return False
            if math.isnan(v) or math.isinf(v):
                return False
            if v < lo or v > hi:
                return False
        return True
