from typing import Dict, Any, List, Tuple
import math
import time


def _now_ts() -> float:
    return time.time()


def _finite(x: float, default: float = 0.0) -> float:
    try:
        xf = float(x)
    except Exception:
        return default
    if math.isnan(xf) or math.isinf(xf):
        return default
    return xf


class TemporalSample:
    """
    Single timestamped sensor sample with confidence.
    """
    __slots__ = ("ts", "data", "confidence")
    def __init__(self, ts: float, data: Dict[str, float], confidence: float):
        self.ts = float(ts)
        self.data = dict(data)
        self.confidence = max(0.0, min(1.0, float(confidence)))
class TemporalRingBuffer:
    """
    Fixed-size temporal buffer for one sensor modality.
    """
    __slots__ = ("_buf", "_size")
    def __init__(self, size: int = 32):
        self._buf: List[TemporalSample] = []
        self._size = int(size)
    def push(self, sample: TemporalSample):
        self._buf.append(sample)
        if len(self._buf) > self._size:
            self._buf.pop(0)
    def latest(self) -> TemporalSample | None:
        if not self._buf:
            return None
        return self._buf[-1]
    def nearest(self, ts: float) -> TemporalSample | None:
        if not self._buf:
            return None
        best = None
        best_dt = float("inf")
        for s in self._buf:
            dt = abs(s.ts - ts)
            if dt < best_dt:
                best = s
                best_dt = dt
        return best
class MultiSensorTemporalFusion:
    """
    Fuses multiple asynchronous sensor streams into a unified state.
    Expected sensor keys:
      - "vision"
      - "imu"
      - "gyro"
      - "metadata"
    """
    __slots__ = ("_buffers", "_latency_hint")
    def __init__(self, buffer_size: int = 32):
        self._buffers: Dict[str, TemporalRingBuffer] = {
            "vision": TemporalRingBuffer(buffer_size),
            "imu": TemporalRingBuffer(buffer_size),
            "gyro": TemporalRingBuffer(buffer_size),
            "metadata": TemporalRingBuffer(buffer_size),
        }
        # Optional per-sensor latency hints (seconds)
        self._latency_hint: Dict[str, float] = {
            "vision": 0.0,
            "imu": 0.0,
            "gyro": 0.0,
            "metadata": 0.0,
        }
    def set_latency_hint(self, sensor: str, seconds: float):
        if sensor in self._latency_hint:
            self._latency_hint[sensor] = max(0.0, float(seconds))
    def ingest(
        self,
        sensor: str,
        data: Dict[str, float],
        confidence: float,
        ts: float | None = None,
    ):
        """
        Ingest a new sensor sample.
        """
        if sensor not in self._buffers:
            return
        ts_eff = _finite(ts if ts is not None else _now_ts(), _now_ts())
        sample = TemporalSample(ts_eff, data, confidence)
        self._buffers[sensor].push(sample)
    def fuse(self, reference_ts: float | None = None) -> Dict[str, Any]:
        """
        Fuse all sensors into a single state aligned to reference_ts.
        """
        if reference_ts is None:
            reference_ts = _now_ts()
        fused: Dict[str, Any] = {
            "ts": reference_ts,
            "sensors": {},
            "confidence": 0.0,
        }
        total_weight = 0.0
        weighted_conf = 0.0
        for name, buf in self._buffers.items():
            latency = self._latency_hint.get(name, 0.0)
            target_ts = reference_ts - latency
            sample = buf.nearest(target_ts)
            if sample is None:
                continue
            fused["sensors"][name] = {
                "ts": sample.ts,
                "data": dict(sample.data),
                "confidence": sample.confidence,
            }
            weighted_conf += sample.confidence
            total_weight += 1.0
        if total_weight > 0.0:
            fused["confidence"] = weighted_conf / total_weight
        else:
            fused["confidence"] = 0.0
        return fused
