from typing import Dict, Any
import math


def _vec_mag(x: float, y: float, z: float) -> float:
    return math.sqrt(x * x + y * y + z * z)


class CameraMotionState:
    """
    Represents the aligned motion state of the camera.
    """
    __slots__ = (
        "ts",
        "linear_accel",
        "angular_vel",
        "optical_motion",
        "stability_score",
    )
    def __init__(
        self,
        ts: float,
        linear_accel: Dict[str, float],
        angular_vel: Dict[str, float],
        optical_motion: Dict[str, float],
        stability_score: float,
    ):
        self.ts = float(ts)
        self.linear_accel = dict(linear_accel)
        self.angular_vel = dict(angular_vel)
        self.optical_motion = dict(optical_motion)
        self.stability_score = max(0.0, min(1.0, float(stability_score)))
class VisionImuGyroAligner:
    """
    Aligns vision-derived motion with IMU + gyro data.
    Operates on already temporally-fused samples (from 86 A 01).
    """
    __slots__ = ("_alpha_motion", "_alpha_gyro")
    def __init__(self, alpha_motion: float = 0.7, alpha_gyro: float = 0.6):
        # Smoothing factors (EMA-style)
        self._alpha_motion = max(0.0, min(1.0, float(alpha_motion)))
        self._alpha_gyro = max(0.0, min(1.0, float(alpha_gyro)))
    def align(self, fused_sample: Dict[str, Any]) -> CameraMotionState | None:
        """
        Align all sensor inputs into a unified camera motion state.
        """
        sensors = fused_sample.get("sensors", {})
        ts = fused_sample.get("ts", None)
        if ts is None:
            return None
        # Defaults
        accel = {"x": 0.0, "y": 0.0, "z": 0.0}
        gyro = {"x": 0.0, "y": 0.0, "z": 0.0}
        vision = {"dx": 0.0, "dy": 0.0, "confidence": 0.0}
        if "imu" in sensors:
            accel.update(sensors["imu"]["data"])
        if "gyro" in sensors:
            gyro.update(sensors["gyro"]["data"])
        if "vision" in sensors:
            vision.update(sensors["vision"]["data"])
        # Compute magnitudes
        accel_mag = _vec_mag(accel["x"], accel["y"], accel["z"])
        gyro_mag = _vec_mag(gyro["x"], gyro["y"], gyro["z"])
        vision_mag = math.hypot(vision.get("dx", 0.0), vision.get("dy", 0.0))
        # Stability heuristic:
        #   Low inertial movement + low optical motion => high stability
        instability = (
            0.5 * min(1.0, accel_mag / 9.81)
            + 0.3 * min(1.0, gyro_mag / 5.0)
            + 0.2 * min(1.0, vision_mag / 20.0)
        )
        stability = max(0.0, 1.0 - instability)
        return CameraMotionState(
            ts=ts,
            linear_accel=accel,
            angular_vel=gyro,
            optical_motion=vision,
            stability_score=stability,
        )
# ==============================================================================
# END OF CHUNK 86 A 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 A 03 — HIGH-RATE SENSOR TIMEBASE UNIFIER
# ==============================================================================
#
# Purpose:
#   Normalize heterogeneous sensor clocks (camera, IMU, gyro, metadata)
#   into a single monotonic, high-resolution timebase.
#
# Why this matters:
#   - Vision runs at ~30–240 Hz
#   - IMU / gyro run at ~200–1000 Hz
#   - Metadata / GPMF arrives bursty + delayed
#
#   Without a unifier:
#     - Optical flow fights gyro
#     - Exposure AI oscillates
#     - Stabilization overshoots
#
# Design goals:
#   - Monotonic output time
#   - Jitter suppression
#   - Drift detection + correction
#
# ==============================================================================

import time
import math
from typing import Dict, Optional


class TimebaseState:
    """
    Internal representation of a unified timebase.
    """
    __slots__ = (
        "t0_system",
        "t0_reference",
        "scale",
        "last_out",
    )
    def __init__(self):
        self.t0_system = time.time()
        self.t0_reference = 0.0
        self.scale = 1.0
        self.last_out = 0.0


class HighRateTimebaseUnifier:
    """
    Converts arbitrary sensor timestamps into a unified time axis.
    """
    __slots__ = ("_state", "_max_jump", "_drift_alpha")
    def __init__(
        self,
        max_jump_seconds: float = 0.02,
        drift_alpha: float = 0.01,
    ):
        # Max allowed backward/forward jump (seconds)
        self._max_jump = max(0.001, float(max_jump_seconds))
        # EMA factor for drift correction
        self._drift_alpha = max(0.0, min(1.0, float(drift_alpha)))
        self._state = TimebaseState()
    def reset(self, reference_ts: float = 0.0):
        """
        Hard reset of the unified timebase.
        """
        self._state.t0_system = time.time()
        self._state.t0_reference = float(reference_ts)
        self._state.scale = 1.0
        self._state.last_out = float(reference_ts)
    def unify(
        self,
        sensor_ts: float,
        sensor_rate_hint: Optional[float] = None,
    ) -> float:
        """
        Map a sensor timestamp to unified time.
        sensor_ts:
            Timestamp in sensor's own clock domain.
        sensor_rate_hint:
            Optional Hz hint (used for drift correction).
        """
        s = self._state
        # Initial alignment
        if s.last_out == 0.0:
            s.t0_reference = float(sensor_ts)
            s.last_out = float(sensor_ts)
            return s.last_out
        # Raw delta in sensor domain
        delta_sensor = float(sensor_ts - s.t0_reference)
        # Estimate system time delta
        now_sys = time.time()
        delta_sys = now_sys - s.t0_system
        # Optional drift estimation
        if sensor_rate_hint and sensor_rate_hint > 0.0:
            expected_delta = delta_sys * sensor_rate_hint
            observed_delta = delta_sensor * sensor_rate_hint
            drift = observed_delta - expected_delta
            s.scale *= (1.0 - self._drift_alpha * math.tanh(drift * 0.001))
        # Apply scale
        unified = s.t0_reference + delta_sensor * s.scale
        # Enforce monotonicity + clamp jumps
        jump = unified - s.last_out
        if abs(jump) > self._max_jump:
            unified = s.last_out + math.copysign(self._max_jump, jump)
        # Final safety: never go backwards
        if unified < s.last_out:
            unified = s.last_out
        s.last_out = unified
        return unified
# ==============================================================================
# END OF CHUNK 86 A 03
# ==============================================================================
# ==============================================================================
# CHUNK 86 A 04 — CROSS-SENSOR CONFIDENCE PROPAGATION
# ==============================================================================
#
# Purpose:
#   Propagate, attenuate, and reconcile confidence across heterogeneous
#   sensor inputs (vision, IMU, gyro, metadata) to produce a single
#   decision-ready confidence field.
#
# Why this matters:
#   - Prevents vision noise from overpowering inertial certainty
#   - Allows strong IMU stability to damp weak optical flow
#   - Enables cinematic smoothness under partial sensor failure
#
# Core idea:
#   Confidence is not averaged — it is *contextually propagated*
#   based on sensor role, agreement, and recent stability.
#
# ==============================================================================

from typing import Dict, Any
import math


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, float(x)))


class SensorConfidenceModel:
    """
    Defines how confidence from one sensor influences others.
    """
    __slots__ = ("base_weight", "influence")
    def __init__(self, base_weight: float, influence: Dict[str, float]):
        self.base_weight = _clamp01(base_weight)
        self.influence = {
            k: _clamp01(v) for k, v in influence.items()
        }


class CrossSensorConfidencePropagator:
    """
    Computes a unified confidence score with cross-sensor propagation.
    """
    __slots__ = ("_models", "_agreement_gain")
    def __init__(self):
        # Per-sensor confidence behavior
        self._models: Dict[str, SensorConfidenceModel] = {
            "vision": SensorConfidenceModel(
                base_weight=0.9,
                influence={"imu": 0.4, "gyro": 0.4},
            ),
            "imu": SensorConfidenceModel(
                base_weight=1.0,
                influence={"vision": 0.3, "gyro": 0.5},
            ),
            "gyro": SensorConfidenceModel(
                base_weight=0.95,
                influence={"vision": 0.3, "imu": 0.5},
            ),
            "metadata": SensorConfidenceModel(
                base_weight=0.6,
                influence={"vision": 0.2},
            ),
        }
        # Boost when sensors agree temporally and directionally
        self._agreement_gain = 0.15
    def propagate(self, fused_sample: Dict[str, Any]) -> Dict[str, Any]:
        """
        Propagate confidence across sensors and compute unified confidence.
        """
        sensors = fused_sample.get("sensors", {})
        if not sensors:
            fused_sample["confidence"] = 0.0
            return fused_sample
        propagated: Dict[str, float] = {}
        # Initial weighted confidence
        for name, payload in sensors.items():
            model = self._models.get(name)
            if not model:
                continue
            base_conf = _clamp01(payload.get("confidence", 0.0))
            propagated[name] = base_conf * model.base_weight
        # Cross-influence
        for name, model in self._models.items():
            if name not in propagated:
                continue
            for other, influence in model.influence.items():
                if other in sensors:
                    other_conf = _clamp01(sensors[other].get("confidence", 0.0))
                    propagated[name] += influence * other_conf
        # Agreement boost (simple heuristic)
        agree_count = 0
        for a in sensors:
            for b in sensors:
                if a == b:
                    continue
                if abs(
                    sensors[a]["confidence"] - sensors[b]["confidence"]
                ) < 0.2:
                    agree_count += 1
        if agree_count > 0:
            boost = min(
                self._agreement_gain,
                self._agreement_gain * (agree_count / 6.0),
            )
            for k in propagated:
                propagated[k] = _clamp01(propagated[k] + boost)
        # Unified confidence
        if propagated:
            fused_sample["confidence"] = _clamp01(
                sum(propagated.values()) / len(propagated)
            )
        else:
            fused_sample["confidence"] = 0.0
        fused_sample["confidence_detail"] = propagated
        return fused_sample
# ==============================================================================
# END OF CHUNK 86 A 04
# ==============================================================================
# ==============================================================================
# CHUNK 86 A 05 — SENSOR DROPOUT COMPENSATION LOGIC
# ==============================================================================
#
# Purpose:
#   Detect, mask, and compensate for temporary sensor dropouts
#   without causing visible cinematic artifacts or AI instability.
#
# What this protects against:
#   - Vision frame drops (USB / RTSP jitter)
#   - IMU burst loss
#   - Gyro saturation / packet loss
#   - Metadata (GPMF) delays
#
# Design philosophy:
#   - NEVER hard-switch sensors
#   - Gracefully decay trust
#   - Predict short gaps, reset long gaps
#
# ==============================================================================

from typing import Dict, Any
import math
import time


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, float(x)))


class DropoutState:
    """
    Tracks dropout statistics for a single sensor.
    """
    __slots__ = (
        "last_seen_ts",
        "dropout_duration",
        "active",
    )
    def __init__(self):
        self.last_seen_ts = 0.0
        self.dropout_duration = 0.0
        self.active = False


class SensorDropoutCompensator:
    """
    Compensates sensor dropouts using temporal decay and prediction.
    """
    __slots__ = (
        "_states",
        "_soft_timeout",
        "_hard_timeout",
        "_confidence_decay",
    )
    def __init__(
        self,
        soft_timeout: float = 0.05,
        hard_timeout: float = 0.25,
        confidence_decay: float = 0.85,
    ):
        # Soft timeout: start decaying confidence
        self._soft_timeout = float(soft_timeout)
        # Hard timeout: consider sensor inactive
        self._hard_timeout = float(hard_timeout)
        # Per-step confidence decay factor
        self._confidence_decay = _clamp01(confidence_decay)
        self._states: Dict[str, DropoutState] = {}
    def _get_state(self, sensor: str) -> DropoutState:
        if sensor not in self._states:
            self._states[sensor] = DropoutState()
        return self._states[sensor]
    def update(self, fused_sample: Dict[str, Any]) -> Dict[str, Any]:
        """
        Apply dropout compensation to a fused sensor sample.
        """
        now = fused_sample.get("ts", time.time())
        sensors = fused_sample.get("sensors", {})
        for name, state in self._states.items():
            if name not in sensors:
                # Sensor missing in this frame
                dt = now - state.last_seen_ts
                state.dropout_duration = max(0.0, dt)
                if dt > self._soft_timeout:
                    state.active = True
                if dt > self._hard_timeout:
                    state.active = False
            else:
                # Sensor present
                state.last_seen_ts = now
                state.dropout_duration = 0.0
                state.active = False
        # Apply compensation
        for name, payload in list(sensors.items()):
            state = self._get_state(name)
            if state.dropout_duration <= self._soft_timeout:
                continue  # Sensor healthy
            # Soft dropout: decay confidence
            if state.dropout_duration <= self._hard_timeout:
                original_conf = payload.get("confidence", 0.0)
                decay_steps = state.dropout_duration / self._soft_timeout
                decayed = original_conf * (self._confidence_decay ** decay_steps)
                payload["confidence"] = _clamp01(decayed)
            # Hard dropout: zero confidence but keep last data for prediction
            else:
                payload["confidence"] = 0.0
                payload["dropout"] = True
        # Recompute unified confidence
        total = 0.0
        count = 0
        for payload in sensors.values():
            total += _clamp01(payload.get("confidence", 0.0))
            count += 1
        fused_sample["confidence"] = (
            total / count if count > 0 else 0.0
        )
        fused_sample["dropout_states"] = {
            name: {
                "active": state.active,
                "duration": state.dropout_duration,
            }
            for name, state in self._states.items()
        }
        return fused_sample
# ==============================================================================
# END OF CHUNK 86 A 05
# ==============================================================================
# ==============================================================================
# CHUNK 86 B 01 — CAMERA AI STATE ESTIMATOR CORE
# ==============================================================================
#
# Purpose:
#   Convert fused + confidence-propagated sensor data into a stable,
#   predictive Camera AI State used by:
#     - Exposure AI
#     - Framing / composition AI
#     - Stabilization & motion smoothing
#     - Intent interpretation (cinematic decisions)
#
# This is NOT rendering logic.
# This is the *brain state* that everything else reads from.
#
# ==============================================================================

from typing import Dict, Any
import math
import time


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, float(x)))


class CameraAIState:
    """
    Canonical camera AI state snapshot.
    """
    __slots__ = (
        "ts",
        "motion_energy",
        "stability",
        "sensor_confidence",
        "exposure_hint",
        "framing_hint",
        "valid",
    )
    def __init__(self):
        self.ts = 0.0
        self.motion_energy = 0.0
        self.stability = 0.0
        self.sensor_confidence = 0.0
        self.exposure_hint = 0.0
        self.framing_hint = 0.0
        self.valid = False


class CameraAIStateEstimator:
    """
    Estimates the CameraAIState from fused sensor input.
    """
    __slots__ = ("_motion_ema", "_alpha")
    def __init__(self, motion_alpha: float = 0.6):
        # EMA factor for motion energy smoothing
        self._alpha = _clamp01(motion_alpha)
        self._motion_ema = 0.0
    def update(self, fused_sample: Dict[str, Any]) -> CameraAIState:
        state = CameraAIState()
        state.ts = fused_sample.get("ts", time.time())
        state.sensor_confidence = _clamp01(
            fused_sample.get("confidence", 0.0)
        )
        sensors = fused_sample.get("sensors", {})
        # Extract motion indicators
        accel_mag = 0.0
        gyro_mag = 0.0
        vision_mag = 0.0
        if "imu" in sensors:
            a = sensors["imu"]["data"]
            accel_mag = math.sqrt(
                a.get("x", 0.0) ** 2 +
                a.get("y", 0.0) ** 2 +
                a.get("z", 0.0) ** 2
            )
        if "gyro" in sensors:
            g = sensors["gyro"]["data"]
            gyro_mag = math.sqrt(
                g.get("x", 0.0) ** 2 +
                g.get("y", 0.0) ** 2 +
                g.get("z", 0.0) ** 2
            )
        if "vision" in sensors:
            v = sensors["vision"]["data"]
            vision_mag = math.hypot(
                v.get("dx", 0.0),
                v.get("dy", 0.0),
            )
        # Unified motion energy
        raw_motion = (
            0.4 * min(1.0, accel_mag / 9.81) +
            0.4 * min(1.0, gyro_mag / 5.0) +
            0.2 * min(1.0, vision_mag / 20.0)
        )
        self._motion_ema = (
            self._alpha * raw_motion +
            (1.0 - self._alpha) * self._motion_ema
        )
        state.motion_energy = _clamp01(self._motion_ema)
        state.stability = _clamp01(1.0 - state.motion_energy)
        # Exposure hint:
        #   High motion → shorter exposure
        state.exposure_hint = _clamp01(
            1.0 - state.motion_energy
        )
        # Framing hint:
        #   High stability → allow tighter framing
        state.framing_hint = _clamp01(
            state.stability * state.sensor_confidence
        )
        state.valid = state.sensor_confidence > 0.1
        return state
# ==============================================================================
# END OF CHUNK 86 B 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 B 02 — PREDICTIVE MOTION SMOOTHING (CINEMATIC)
# ==============================================================================
#
# Purpose:
#   Predictively smooth camera motion intent using short-horizon forecasting
#   so that cinematic decisions (exposure, framing, stabilization) remain
#   fluid and filmic rather than reactive and jittery.
#
# Key principles:
#   - Preserve *intentional* motion
#   - Suppress micro-jitter and sensor noise
#   - Predict, don’t lag (no visible latency)
#
# Inputs:
#   - CameraAIState (from 86 B 01)
# Outputs:
#   - Smoothed, predictive motion energy & stability
#
# ==============================================================================

from typing import Deque
from collections import deque
import math


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, float(x)))


class MotionHistory:
    """
    Short rolling window of motion energy for prediction.
    """
    __slots__ = ("values", "maxlen")
    def __init__(self, maxlen: int = 8):
        self.maxlen = int(maxlen)
        self.values: Deque[float] = deque(maxlen=self.maxlen)
    def push(self, v: float):
        self.values.append(_clamp01(v))
    def trend(self) -> float:
        """
        Compute short-term trend using simple linear slope.
        """
        n = len(self.values)
        if n < 2:
            return 0.0
        # Normalized index-based slope
        xs = range(n)
        mean_x = (n - 1) / 2.0
        mean_y = sum(self.values) / n
        num = 0.0
        den = 0.0
        for i, y in enumerate(self.values):
            dx = i - mean_x
            num += dx * (y - mean_y)
            den += dx * dx
        if den == 0.0:
            return 0.0
        return num / den


class PredictiveMotionSmoother:
    """
    Predicts near-future motion to stabilize cinematic decisions.
    """
    __slots__ = (
        "_history",
        "_prediction_gain",
        "_smoothing_alpha",
    )
    def __init__(
        self,
        history_len: int = 8,
        prediction_gain: float = 0.4,
        smoothing_alpha: float = 0.65,
    ):
        self._history = MotionHistory(history_len)
        self._prediction_gain = _clamp01(prediction_gain)
        self._smoothing_alpha = _clamp01(smoothing_alpha)
    def smooth(self, motion_energy: float) -> float:
        """
        Return predictively-smoothed motion energy.
        """
        motion_energy = _clamp01(motion_energy)
        self._history.push(motion_energy)
        # Predict next motion via trend
        trend = self._history.trend()
        predicted = motion_energy + self._prediction_gain * trend
        predicted = _clamp01(predicted)
        # EMA smoothing to avoid overshoot
        if len(self._history.values) == 1:
            return predicted
        prev = self._history.values[-2]
        smoothed = (
            self._smoothing_alpha * predicted +
            (1.0 - self._smoothing_alpha) * prev
        )
        return _clamp01(smoothed)
class CinematicMotionAdapter:
    """
    Adapts smoothed motion into cinematic control scalars.
    """
    __slots__ = ("_smoother",)
    def __init__(self):
        self._smoother = PredictiveMotionSmoother()
    def adapt(self, camera_state) -> None:
        """
        Mutates CameraAIState in-place with smoothed values.
        """
        if not getattr(camera_state, "valid", False):
            return
        smoothed_motion = self._smoother.smooth(
            camera_state.motion_energy
        )
        camera_state.motion_energy = smoothed_motion
        camera_state.stability = _clamp01(1.0 - smoothed_motion)
        # Re-derive hints after smoothing
        camera_state.exposure_hint = _clamp01(
            1.0 - smoothed_motion
        )
        camera_state.framing_hint = _clamp01(
            camera_state.stability * camera_state.sensor_confidence
        )
# ==============================================================================
# END OF CHUNK 86 B 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 B 03 — INTENT-READY CAMERA STATE VECTOR
# ==============================================================================
#
# Purpose:
#   Convert internal CameraAIState into a normalized, intent-ready vector
#   that downstream systems (exposure, framing, stabilization, director AI)
#   can consume without re-interpreting raw sensor semantics.
#
# Why this matters:
#   - Decouples sensor math from creative logic
#   - Enables clean handoff to cloud / laptop AI
#   - Prevents logic duplication across modules
#
# Output:
#   A compact, normalized state vector in [0,1] space with semantic meaning.
#
# ==============================================================================

from typing import Dict, Any


def _clamp01(x: float) -> float:
    return max(0.0, min(1.0, float(x)))


class IntentCameraVector:
    """
    Canonical intent-level camera vector.
    """
    __slots__ = (
        "ts",
        "motion",
        "stability",
        "confidence",
        "exposure_bias",
        "framing_aggressiveness",
        "valid",
    )
    def __init__(self):
        self.ts = 0.0
        self.motion = 0.0
        self.stability = 0.0
        self.confidence = 0.0
        self.exposure_bias = 0.0
        self.framing_aggressiveness = 0.0
        self.valid = False


class CameraStateVectorizer:
    """
    Translates CameraAIState into an intent-ready vector.
    """
    __slots__ = ("_min_confidence",)
    def __init__(self, min_confidence: float = 0.15):
        self._min_confidence = _clamp01(min_confidence)
    def vectorize(self, camera_state) -> IntentCameraVector:
        vec = IntentCameraVector()
        if not getattr(camera_state, "valid", False):
            return vec
        if camera_state.sensor_confidence < self._min_confidence:
            return vec
        vec.ts = camera_state.ts
        vec.motion = _clamp01(camera_state.motion_energy)
        vec.stability = _clamp01(camera_state.stability)
        vec.confidence = _clamp01(camera_state.sensor_confidence)
        # Exposure bias:
        #   >0 favors brighter / longer exposure
        #   <0 favors darker / shorter exposure
        vec.exposure_bias = (
            _clamp01(camera_state.exposure_hint) - 0.5
        ) * 2.0
        # Framing aggressiveness:
        #   High stability + confidence → tighter framing allowed
        vec.framing_aggressiveness = _clamp01(
            camera_state.framing_hint
        )
        vec.valid = True
        return vec
class IntentVectorSerializer:
    """
    Serializes intent vectors for IPC / cloud transmission.
    """
    __slots__ = ()
    @staticmethod
    def to_dict(vec: IntentCameraVector) -> Dict[str, Any]:
        return {
            "ts": vec.ts,
            "motion": vec.motion,
            "stability": vec.stability,
            "confidence": vec.confidence,
            "exposure_bias": vec.exposure_bias,
            "framing_aggressiveness": vec.framing_aggressiveness,
            "valid": vec.valid,
        }
# ==============================================================================
# END OF CHUNK 86 B 03
