# ==============================================================================
# CHUNK 86 C 01 — EXPOSURE DECISION CORE (SENSOR-AWARE)
# ==============================================================================
#
# Purpose:
#   Make primary exposure decisions using intent-ready camera vectors,
#   sensor confidence, and motion context.
#
# This module decides:
#   - Whether to bias exposure up/down
#   - How aggressively to react
#   - When to HOLD exposure to avoid pumping
#
# It does NOT apply exposure — it computes *intent*.
#
# ==============================================================================

from typing import Dict
import math


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class ExposureIntent:
    """
    Represents exposure intent for downstream application.
    """
    __slots__ = (
        "bias",
        "strength",
        "lock",
    )
    def __init__(self):
        self.bias = 0.0        # [-1, +1]
        self.strength = 0.0   # [0, 1]
        self.lock = False     # freeze exposure if True


class ExposureDecisionCore:
    """
    Computes exposure intent from camera intent vectors.
    """
    __slots__ = (
        "_motion_lock_threshold",
        "_confidence_floor",
        "_max_strength",
    )
    def __init__(
        self,
        motion_lock_threshold: float = 0.75,
        confidence_floor: float = 0.2,
        max_strength: float = 0.85,
    ):
        # Above this motion → lock exposure (avoid smear/pumping)
        self._motion_lock_threshold = _clamp(
            motion_lock_threshold, 0.0, 1.0
        )
        # Below this confidence → weaken response
        self._confidence_floor = _clamp(
            confidence_floor, 0.0, 1.0
        )
        self._max_strength = _clamp(max_strength, 0.0, 1.0)
    def decide(self, intent_vec) -> ExposureIntent:
        exp = ExposureIntent()
        if not getattr(intent_vec, "valid", False):
            return exp
        motion = _clamp(intent_vec.motion, 0.0, 1.0)
        confidence = _clamp(intent_vec.confidence, 0.0, 1.0)
        # High motion → lock exposure
        if motion >= self._motion_lock_threshold:
            exp.lock = True
            return exp
        # Base bias from intent vector
        bias = _clamp(intent_vec.exposure_bias, -1.0, 1.0)
        # Strength scales with confidence and inverse motion
        motion_factor = 1.0 - motion
        conf_factor = (
            confidence / self._confidence_floor
            if confidence < self._confidence_floor
            else 1.0
        )
        strength = (
            abs(bias) *
            motion_factor *
            conf_factor
        )
        exp.bias = bias
        exp.strength = _clamp(
            strength, 0.0, self._max_strength
        )
        return exp
class ExposureIntentSerializer:
    """
    Converts exposure intent to a portable representation.
    """
    __slots__ = ()
    @staticmethod
    def to_dict(exp: ExposureIntent) -> Dict[str, float | bool]:
        return {
            "bias": exp.bias,
            "strength": exp.strength,
            "lock": exp.lock,
        }
