# ==============================================================================
# CHUNK 86 C 02 — HIGHLIGHT PROTECTION & ROLL-OFF ENGINE
# ==============================================================================
#
# Purpose:
#   Preserve highlight detail using film-like roll-off instead of hard clipping.
#
# This engine:
#   - Detects highlight risk from exposure intent + sensor state
#   - Applies perceptual shoulder compression
#   - Maintains color integrity under extreme luminance
#
# Design philosophy:
#   Film never clips — it compresses.
#   This module enforces that rule.
#
# ==============================================================================

import math
from typing import Dict


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class HighlightProtectionIntent:
    """
    Encodes highlight compression intent.
    """
    __slots__ = (
        "shoulder_strength",
        "rolloff_knee",
        "preserve_chroma",
        "active",
    )
    def __init__(self):
        self.shoulder_strength = 0.0   # [0,1]
        self.rolloff_knee = 1.0        # normalized luminance
        self.preserve_chroma = True
        self.active = False


class HighlightRollOffEngine:
    """
    Computes highlight roll-off parameters from exposure intent.
    """
    __slots__ = (
        "_base_knee",
        "_max_strength",
    )
    def __init__(
        self,
        base_knee: float = 0.82,
        max_strength: float = 0.9,
    ):
        # Knee where compression begins (normalized linear space)
        self._base_knee = _clamp(base_knee, 0.6, 0.95)
        self._max_strength = _clamp(max_strength, 0.0, 1.0)
    def compute(self, exposure_intent, camera_state) -> HighlightProtectionIntent:
        hp = HighlightProtectionIntent()
        if exposure_intent.lock:
            return hp
        # Exposure bias > 0 means pushing brightness
        bias = _clamp(exposure_intent.bias, -1.0, 1.0)
        strength = _clamp(exposure_intent.strength, 0.0, 1.0)
        # Sensor headroom estimate
        headroom = _clamp(
            getattr(camera_state, "highlight_headroom", 0.5),
            0.0,
            1.0,
        )
        # If pushing exposure and headroom is limited → activate
        risk = max(0.0, bias) * (1.0 - headroom)
        if risk < 0.05:
            return hp
        hp.active = True
        # Shoulder strength scales with risk and intent strength
        hp.shoulder_strength = _clamp(
            risk * strength * 1.4,
            0.0,
            self._max_strength,
        )
        # Knee moves lower as risk increases
        hp.rolloff_knee = _clamp(
            self._base_knee - risk * 0.25,
            0.6,
            0.95,
        )
        # Always preserve chroma — film does not bleach color
        hp.preserve_chroma = True
        return hp
class HighlightIntentSerializer:
    """
    Serializes highlight intent for downstream tone mapping.
    """
    __slots__ = ()
    @staticmethod
    def to_dict(hp: HighlightProtectionIntent) -> Dict[str, float | bool]:
        return {
            "active": hp.active,
            "shoulder_strength": hp.shoulder_strength,
            "rolloff_knee": hp.rolloff_knee,
            "preserve_chroma": hp.preserve_chroma,
        }
