# ==============================================================================
# CHUNK 86 C 03 — SHADOW PRESERVATION LOGIC
# ==============================================================================
#
# Purpose:
#   Preserve shadow detail while maintaining perceived contrast.
#
# This engine:
#   - Detects shadow crush risk from exposure + scene contrast
#   - Applies film-like toe lift (non-linear)
#   - Maintains local contrast and chroma integrity
#
# Film principle:
#   Shadows carry texture, not emptiness.
#
# ==============================================================================

import math
from typing import Dict


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class ShadowPreservationIntent:
    """
    Encodes shadow lift / toe compression intent.
    """
    __slots__ = (
        "toe_strength",
        "toe_start",
        "local_contrast_protect",
        "active",
    )
    def __init__(self):
        self.toe_strength = 0.0     # [0,1]
        self.toe_start = 0.0        # normalized luminance
        self.local_contrast_protect = True
        self.active = False


class ShadowPreservationEngine:
    """
    Computes shadow preservation parameters from exposure + scene state.
    """
    __slots__ = (
        "_base_toe",
        "_max_strength",
    )
    def __init__(
        self,
        base_toe: float = 0.12,
        max_strength: float = 0.85,
    ):
        # Toe start point in normalized linear space
        self._base_toe = _clamp(base_toe, 0.05, 0.25)
        self._max_strength = _clamp(max_strength, 0.0, 1.0)
    def compute(self, exposure_intent, scene_state) -> ShadowPreservationIntent:
        sp = ShadowPreservationIntent()
        if exposure_intent.lock:
            return sp
        bias = _clamp(exposure_intent.bias, -1.0, 1.0)
        strength = _clamp(exposure_intent.strength, 0.0, 1.0)
        # Scene shadow density estimate
        shadow_density = _clamp(
            getattr(scene_state, "shadow_density", 0.5),
            0.0,
            1.0,
        )
        # Risk increases when pulling exposure down in dark scenes
        risk = max(0.0, -bias) * shadow_density
        if risk < 0.05:
            return sp
        sp.active = True
        # Toe lift strength scales gently — avoid milky blacks
        sp.toe_strength = _clamp(
            risk * strength * 1.2,
            0.0,
            self._max_strength,
        )
        # Toe start shifts upward slightly under high risk
        sp.toe_start = _clamp(
            self._base_toe + risk * 0.08,
            0.05,
            0.3,
        )
        sp.local_contrast_protect = True
        return sp
class ShadowIntentSerializer:
    """
    Serializes shadow intent for tone mapping stages.
    """
    __slots__ = ()
    @staticmethod
    def to_dict(sp: ShadowPreservationIntent) -> Dict[str, float | bool]:
        return {
            "active": sp.active,
            "toe_strength": sp.toe_strength,
            "toe_start": sp.toe_start,
            "local_contrast_protect": sp.local_contrast_protect,
        }
