# ==============================================================================
# CHUNK 86 C 04 — TEMPORAL EXPOSURE STABILITY CONTROLLER
# ==============================================================================
#
# Purpose:
#   Prevent exposure pumping and temporal brightness jitter across frames.
#
# Cinematic principle:
#   Exposure changes must feel intentional, slow, and motivated — never reactive.
#
# This module:
#   - Tracks exposure deltas over time
#   - Applies inertia and hysteresis
#   - Preserves scene continuity during motion or lighting change
#
# ==============================================================================

from collections import deque
from typing import Deque


def _lerp(a: float, b: float, t: float) -> float:
    return a + (b - a) * t


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class TemporalExposureState:
    """
    Maintains rolling exposure history for stabilization.
    """
    __slots__ = (
        "history",
        "last_output",
    )
    def __init__(self, window: int = 12):
        self.history: Deque[float] = deque(maxlen=window)
        self.last_output: float | None = None


class TemporalExposureStabilizer:
    """
    Applies cinematic inertia to exposure changes.
    """
    __slots__ = (
        "_attack",
        "_release",
        "_max_step",
    )
    def __init__(
        self,
        attack: float = 0.15,
        release: float = 0.05,
        max_step: float = 0.08,
    ):
        # attack: how fast exposure increases
        # release: how slow exposure decreases
        self._attack = _clamp(attack, 0.01, 0.5)
        self._release = _clamp(release, 0.01, 0.5)
        self._max_step = _clamp(max_step, 0.01, 0.25)
    def update(
        self,
        target_exposure: float,
        state: TemporalExposureState,
    ) -> float:
        target_exposure = float(target_exposure)
        if state.last_output is None:
            state.last_output = target_exposure
            state.history.append(target_exposure)
            return target_exposure
        delta = target_exposure - state.last_output
        # Limit per-frame exposure movement
        delta = _clamp(delta, -self._max_step, self._max_step)
        # Different inertia for brightening vs darkening
        if delta > 0.0:
            smoothed = _lerp(
                state.last_output,
                state.last_output + delta,
                self._attack,
            )
        else:
            smoothed = _lerp(
                state.last_output,
                state.last_output + delta,
                self._release,
            )
        state.last_output = smoothed
        state.history.append(smoothed)
        return smoothed
class TemporalExposureDiagnostics:
    """
    Provides metrics for debugging exposure stability.
    """
    __slots__ = ()
    @staticmethod
    def variance(state: TemporalExposureState) -> float:
        if not state.history:
            return 0.0
        mean = sum(state.history) / len(state.history)
        return sum((x - mean) ** 2 for x in state.history) / len(state.history)
