# ==============================================================================
# CHUNK 86 D 01 — SUBJECT-AWARE FRAMING CORE
# ==============================================================================
#
# Purpose:
#   Convert perception outputs (subjects, saliency, motion) into
#   stable, cinematic framing intents.
#
# Cinematic principles:
#   - Frame what matters, not what moves the most
#   - Respect headroom, lead-room, and narrative emphasis
#   - Avoid reactive jitter; intent must be temporally coherent
#
# Inputs:
#   - detected subjects (bbox, class, confidence)
#   - saliency map summary
#   - camera state (FOV, aspect)
#
# Outputs:
#   - framing intent (center, scale, priority)
#
# ==============================================================================

from dataclasses import dataclass
from typing import List, Tuple


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


@dataclass
class Subject:
    """
    Detected subject abstraction.
    """
    cx: float              # normalized center x [0,1]
    cy: float              # normalized center y [0,1]
    w: float               # normalized width
    h: float               # normalized height
    confidence: float      # detection confidence
    importance: float      # semantic importance (AI-estimated)
    motion: float          # normalized motion magnitude


@dataclass
class FramingIntent:
    """
    Framing output used by downstream camera / crop logic.
    """
    target_x: float
    target_y: float
    scale: float
    priority: float
    active: bool


class SubjectFramingCore:
    """
    Computes cinematic framing intent from detected subjects.
    """
    __slots__ = (
        "_min_conf",
        "_importance_bias",
        "_motion_penalty",
    )
    def __init__(
        self,
        min_confidence: float = 0.4,
        importance_bias: float = 0.65,
        motion_penalty: float = 0.25,
    ):
        self._min_conf = _clamp(min_confidence, 0.1, 0.9)
        self._importance_bias = _clamp(importance_bias, 0.0, 1.0)
        self._motion_penalty = _clamp(motion_penalty, 0.0, 1.0)
    def _score_subject(self, s: Subject) -> float:
        """
        Higher score means higher framing priority.
        """
        conf = _clamp(s.confidence, 0.0, 1.0)
        if conf < self._min_conf:
            return 0.0
        importance = _clamp(s.importance, 0.0, 1.0)
        motion = _clamp(s.motion, 0.0, 1.0)
        # Penalize pure motion chasing; cinema favors meaning
        score = (
            conf *
            ((importance * self._importance_bias) +
             ((1.0 - motion) * (1.0 - self._importance_bias)))
        )
        # Mild suppression for erratic motion
        score *= (1.0 - motion * self._motion_penalty)
        return score
    def compute(
        self,
        subjects: List[Subject],
        saliency_center: Tuple[float, float] | None = None,
    ) -> FramingIntent:
        if not subjects:
            # Fallback to saliency or neutral center
            if saliency_center:
                return FramingIntent(
                    target_x=_clamp(saliency_center[0], 0.0, 1.0),
                    target_y=_clamp(saliency_center[1], 0.0, 1.0),
                    scale=1.0,
                    priority=0.2,
                    active=True,
                )
            return FramingIntent(
                target_x=0.5,
                target_y=0.5,
                scale=1.0,
                priority=0.0,
                active=False,
            )
        # Score all subjects
        best_score = 0.0
        best_subject: Subject | None = None
        for s in subjects:
            score = self._score_subject(s)
            if score > best_score:
                best_score = score
                best_subject = s
        if best_subject is None:
            return FramingIntent(
                target_x=0.5,
                target_y=0.5,
                scale=1.0,
                priority=0.0,
                active=False,
            )
        # Compute cinematic scale: favor medium shots
        size = _clamp(best_subject.w * best_subject.h, 0.01, 1.0)
        scale = _clamp(0.45 / math.sqrt(size), 0.6, 1.4)
        return FramingIntent(
            target_x=_clamp(best_subject.cx, 0.0, 1.0),
            target_y=_clamp(best_subject.cy, 0.0, 1.0),
            scale=scale,
            priority=_clamp(best_score, 0.0, 1.0),
            active=True,
        )
