# ==============================================================================
# CHUNK 86 D 02 — COMPOSITION RULE ENGINE (CINEMATIC)
# ==============================================================================
#
# Purpose:
#   Apply classical + modern cinematic composition rules on top of
#   raw framing intent.
#
# Rules enforced:
#   - Rule of thirds (soft, not rigid)
#   - Headroom preservation
#   - Lead room in direction of motion / gaze
#   - Center bias suppression (avoid amateur framing)
#
# Output:
#   Refined framing intent suitable for autonomous camera control.
#
# ==============================================================================

import math
from typing import Optional


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class CompositionIntent:
    """
    Composition-adjusted framing intent.
    """
    __slots__ = (
        "x",
        "y",
        "scale",
        "confidence",
    )
    def __init__(self, x: float, y: float, scale: float, confidence: float):
        self.x = x
        self.y = y
        self.scale = scale
        self.confidence = confidence


class CompositionRuleEngine:
    """
    Applies cinematic composition constraints.
    """
    __slots__ = (
        "_thirds_strength",
        "_headroom",
        "_leadroom_gain",
        "_center_bias_suppression",
    )
    def __init__(
        self,
        thirds_strength: float = 0.35,
        headroom: float = 0.12,
        leadroom_gain: float = 0.18,
        center_bias_suppression: float = 0.25,
    ):
        self._thirds_strength = _clamp(thirds_strength, 0.0, 1.0)
        self._headroom = _clamp(headroom, 0.05, 0.25)
        self._leadroom_gain = _clamp(leadroom_gain, 0.0, 0.5)
        self._center_bias_suppression = _clamp(center_bias_suppression, 0.0, 0.5)
    def _apply_rule_of_thirds(self, x: float, y: float) -> tuple[float, float]:
        """
        Soft attraction toward nearest thirds intersection.
        """
        thirds = (1.0 / 3.0, 2.0 / 3.0)
        tx = min(thirds, key=lambda t: abs(x - t))
        ty = min(thirds, key=lambda t: abs(y - t))
        x = x + (tx - x) * self._thirds_strength
        y = y + (ty - y) * self._thirds_strength
        return x, y
    def apply(
        self,
        framing_intent,
        gaze_direction: Optional[float] = None,
    ) -> CompositionIntent:
        x = _clamp(framing_intent.target_x, 0.0, 1.0)
        y = _clamp(framing_intent.target_y, 0.0, 1.0)
        scale = framing_intent.scale
        # Apply rule of thirds softly
        x, y = self._apply_rule_of_thirds(x, y)
        # Headroom: push framing slightly down
        y = _clamp(y + self._headroom * 0.5, 0.0, 1.0)
        # Lead room based on gaze or motion direction
        if gaze_direction is not None:
            lead = _clamp(gaze_direction, -1.0, 1.0)
            x = _clamp(x + lead * self._leadroom_gain, 0.0, 1.0)
        # Suppress dead-center framing unless necessary
        center_dist = abs(x - 0.5)
        if center_dist < 0.05:
            push = (0.5 - x)
            x = _clamp(
                x + push * self._center_bias_suppression,
                0.0,
                1.0,
            )
        confidence = framing_intent.priority
        return CompositionIntent(
            x=x,
            y=y,
            scale=_clamp(scale, 0.5, 1.6),
            confidence=_clamp(confidence, 0.0, 1.0),
        )
