# ==============================================================================
# CHUNK 86 D 03 — GAZE & VISUAL WEIGHT ESTIMATOR
# ==============================================================================
#
# Purpose:
#   Estimate subject gaze direction and perceptual visual weight to
#   guide lead-room, balance, and narrative emphasis.
#
# Cinematic principle:
#   Viewers follow eyes before motion. Gaze defines story direction.
#
# Inputs:
#   - subject geometry
#   - motion vectors
#   - face orientation (if available)
#
# Outputs:
#   - normalized gaze direction (-1 left → +1 right)
#   - visual weight scalar (0 → 1)
#
# ==============================================================================

import math
from typing import Optional


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class GazeEstimate:
    """
    Gaze and perceptual weight output.
    """
    __slots__ = (
        "direction",
        "weight",
        "confidence",
    )
    def __init__(self, direction: float, weight: float, confidence: float):
        self.direction = direction    # [-1, 1]
        self.weight = weight          # [0, 1]
        self.confidence = confidence  # [0, 1]


class GazeWeightEstimator:
    """
    Computes gaze direction and visual weight for a subject.
    """
    __slots__ = (
        "_motion_bias",
        "_size_bias",
        "_center_bias",
    )
    def __init__(
        self,
        motion_bias: float = 0.45,
        size_bias: float = 0.35,
        center_bias: float = 0.20,
    ):
        self._motion_bias = _clamp(motion_bias, 0.0, 1.0)
        self._size_bias = _clamp(size_bias, 0.0, 1.0)
        self._center_bias = _clamp(center_bias, 0.0, 1.0)
    def estimate(
        self,
        cx: float,
        width: float,
        motion_x: Optional[float] = None,
        face_yaw: Optional[float] = None,
    ) -> GazeEstimate:
        # --- Gaze direction ---
        components = []
        weights = []
        if face_yaw is not None:
            # face_yaw assumed normalized [-1, 1]
            components.append(_clamp(face_yaw, -1.0, 1.0))
            weights.append(0.6)
        if motion_x is not None:
            components.append(_clamp(motion_x, -1.0, 1.0))
            weights.append(0.4)
        if components:
            gaze = sum(c * w for c, w in zip(components, weights)) / sum(weights)
            gaze_conf = _clamp(sum(weights), 0.0, 1.0)
        else:
            gaze = 0.0
            gaze_conf = 0.0
        # --- Visual weight ---
        size_weight = _clamp(math.sqrt(width), 0.0, 1.0)
        center_weight = 1.0 - abs(cx - 0.5) * 2.0
        center_weight = _clamp(center_weight, 0.0, 1.0)
        motion_weight = 0.0
        if motion_x is not None:
            motion_weight = _clamp(abs(motion_x), 0.0, 1.0)
        visual_weight = (
            size_weight * self._size_bias +
            center_weight * self._center_bias +
            motion_weight * self._motion_bias
        )
        visual_weight = _clamp(visual_weight, 0.0, 1.0)
        confidence = _clamp((gaze_conf + visual_weight) * 0.5, 0.0, 1.0)
        return GazeEstimate(
            direction=_clamp(gaze, -1.0, 1.0),
            weight=visual_weight,
            confidence=confidence,
        )
