# END OF CHUNK 86 D 03
# ==============================================================================
# ==============================================================================
# CHUNK 86 D 04 — DYNAMIC REFRAMING SMOOTHER
# ==============================================================================
#
# Purpose:
#   Smooth framing intent over time to eliminate jitter, snap,
#   and robotic camera behavior.
#
# Cinematic principle:
#   Camera motion must feel motivated, inertial, and human-operated.
#
# This module:
#   - Applies temporal damping to framing targets
#   - Uses asymmetric acceleration/deceleration
#   - Preserves intent priority during fast subject changes
#
# ==============================================================================

from collections import deque
from typing import Deque


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


def _lerp(a: float, b: float, t: float) -> float:
    return a + (b - a) * t


class ReframeState:
    """
    Stores temporal state for reframing smoothing.
    """
    __slots__ = (
        "x",
        "y",
        "scale",
        "confidence_hist",
    )
    def __init__(self, history: int = 10):
        self.x: float | None = None
        self.y: float | None = None
        self.scale: float | None = None
        self.confidence_hist: Deque[float] = deque(maxlen=history)


class DynamicReframingSmoother:
    """
    Applies cinematic inertia to framing motion.
    """
    __slots__ = (
        "_attack",
        "_release",
        "_scale_damping",
    )
    def __init__(
        self,
        attack: float = 0.18,
        release: float = 0.06,
        scale_damping: float = 0.12,
    ):
        self._attack = _clamp(attack, 0.05, 0.5)
        self._release = _clamp(release, 0.01, 0.3)
        self._scale_damping = _clamp(scale_damping, 0.02, 0.3)
    def update(self, intent, state: ReframeState):
        """
        Smooth framing intent into stable camera motion.
        """
        if state.x is None:
            state.x = intent.x
            state.y = intent.y
            state.scale = intent.scale
            state.confidence_hist.append(intent.confidence)
            return intent
        # Choose inertia based on confidence
        inertia = (
            self._attack if intent.confidence > 0.5 else self._release
        )
        # Smooth position
        state.x = _lerp(state.x, intent.x, inertia)
        state.y = _lerp(state.y, intent.y, inertia)
        # Smooth scale more conservatively
        state.scale = _lerp(
            state.scale,
            intent.scale,
            self._scale_damping,
        )
        state.confidence_hist.append(intent.confidence)
        intent.x = _clamp(state.x, 0.0, 1.0)
        intent.y = _clamp(state.y, 0.0, 1.0)
        intent.scale = _clamp(state.scale, 0.5, 1.6)
        return intent
