# ==============================================================================
# CHUNK 86 D 05 — HORIZON & ROLL BIAS CONTROL
# ==============================================================================
#
# Purpose:
#   Maintain a stable cinematic horizon while allowing intentional roll
#   when motivated by motion or narrative context.
#
# Cinematic principle:
#   A level horizon is subconscious comfort. Roll must be deliberate,
#   slow, and story-driven — never accidental.
#
# This module:
#   - Suppresses micro-roll jitter
#   - Applies bias toward level horizon
#   - Allows controlled roll during dynamic shots
#
# ==============================================================================

from collections import deque
from typing import Deque, Optional


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


def _lerp(a: float, b: float, t: float) -> float:
    return a + (b - a) * t


class HorizonState:
    """
    Maintains temporal state for horizon stabilization.
    """
    __slots__ = (
        "roll",
        "history",
    )
    def __init__(self, window: int = 15):
        self.roll: float | None = None
        self.history: Deque[float] = deque(maxlen=window)


class HorizonRollController:
    """
    Controls horizon stability and cinematic roll bias.
    """
    __slots__ = (
        "_level_strength",
        "_max_roll",
        "_roll_inertia",
        "_dynamic_allowance",
    )
    def __init__(
        self,
        level_strength: float = 0.75,
        max_roll: float = 6.0,
        roll_inertia: float = 0.08,
        dynamic_allowance: float = 0.4,
    ):
        # level_strength: bias toward 0° roll
        self._level_strength = _clamp(level_strength, 0.0, 1.0)
        # max_roll in degrees
        self._max_roll = _clamp(max_roll, 0.0, 15.0)
        # inertia: smoothing factor
        self._roll_inertia = _clamp(roll_inertia, 0.01, 0.3)
        # dynamic allowance scales roll during fast motion
        self._dynamic_allowance = _clamp(dynamic_allowance, 0.0, 1.0)
    def update(
        self,
        measured_roll: float,
        motion_intensity: Optional[float],
        state: HorizonState,
    ) -> float:
        """
        Update stabilized roll angle (degrees).
        """
        measured_roll = float(measured_roll)
        if state.roll is None:
            state.roll = measured_roll
            state.history.append(measured_roll)
            return measured_roll
        motion = _clamp(motion_intensity or 0.0, 0.0, 1.0)
        # Compute desired roll bias
        dynamic_factor = motion * self._dynamic_allowance
        target_roll = measured_roll * (1.0 - self._level_strength)
        target_roll += measured_roll * dynamic_factor
        target_roll = _clamp(
            target_roll,
            -self._max_roll,
            self._max_roll,
        )
        # Smooth roll change
        state.roll = _lerp(
            state.roll,
            target_roll,
            self._roll_inertia,
        )
        state.history.append(state.roll)
        return state.roll
class HorizonDiagnostics:
    """
    Diagnostics for horizon stability.
    """
    __slots__ = ()
    @staticmethod
    def average_roll(state: HorizonState) -> float:
        if not state.history:
            return 0.0
        return sum(state.history) / len(state.history)
