# ==============================================================================
# CHUNK 86 D 06 — MULTI-SUBJECT ARBITRATION LOGIC
# ==============================================================================
#
# Purpose:
#   Resolve conflicts when multiple subjects compete for framing priority.
#
# Cinematic principle:
#   Cinema does not jump subjects randomly.
#   Priority follows narrative importance, continuity, and viewer attention.
#
# This module:
#   - Scores all visible subjects
#   - Maintains temporal continuity (anti-flicker)
#   - Allows intentional subject handoff
#
# ==============================================================================

from typing import List, Optional


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class ArbitrationState:
    """
    Tracks dominant subject across frames.
    """
    __slots__ = (
        "active_id",
        "hold_time",
    )
    def __init__(self):
        self.active_id: Optional[int] = None
        self.hold_time: float = 0.0


class SubjectCandidate:
    """
    Lightweight subject descriptor for arbitration.
    """
    __slots__ = (
        "id",
        "priority",
        "confidence",
        "visual_weight",
    )
    def __init__(
        self,
        id: int,
        priority: float,
        confidence: float,
        visual_weight: float,
    ):
        self.id = id
        self.priority = _clamp(priority, 0.0, 1.0)
        self.confidence = _clamp(confidence, 0.0, 1.0)
        self.visual_weight = _clamp(visual_weight, 0.0, 1.0)


class MultiSubjectArbitrator:
    """
    Chooses a dominant subject in a cinematic, stable manner.
    """
    __slots__ = (
        "_switch_threshold",
        "_min_hold_frames",
    )
    def __init__(
        self,
        switch_threshold: float = 0.18,
        min_hold_frames: int = 12,
    ):
        # Required score delta to switch subjects
        self._switch_threshold = _clamp(switch_threshold, 0.05, 0.5)
        # Minimum frames before allowing subject switch
        self._min_hold_frames = max(1, int(min_hold_frames))
    def _score(self, s: SubjectCandidate) -> float:
        """
        Composite cinematic score.
        """
        return (
            s.priority * 0.45 +
            s.visual_weight * 0.35 +
            s.confidence * 0.20
        )
    def choose(
        self,
        subjects: List[SubjectCandidate],
        state: ArbitrationState,
    ) -> Optional[int]:
        if not subjects:
            state.active_id = None
            state.hold_time = 0.0
            return None
        scored = [(self._score(s), s) for s in subjects]
        scored.sort(key=lambda x: x[0], reverse=True)
        best_score, best_subject = scored[0]
        # No active subject yet
        if state.active_id is None:
            state.active_id = best_subject.id
            state.hold_time = 0.0
            return best_subject.id
        # Find current active subject
        current_score = None
        for score, s in scored:
            if s.id == state.active_id:
                current_score = score
                break
        # If active subject disappeared
        if current_score is None:
            state.active_id = best_subject.id
            state.hold_time = 0.0
            return best_subject.id
        state.hold_time += 1.0
        # Enforce minimum hold duration
        if state.hold_time < self._min_hold_frames:
            return state.active_id
        # Allow switch only if dominance is clear
        if (best_score - current_score) > self._switch_threshold:
            state.active_id = best_subject.id
            state.hold_time = 0.0
            return best_subject.id
        return state.active_id
