# ==============================================================================
# CHUNK 86 D 07 — CINEMATIC SHOT TYPE CLASSIFIER
# ==============================================================================
#
# Purpose:
#   Classify the current shot into cinematic shot types based on
#   subject scale, motion, narrative priority, and context.
#
# Cinematic principle:
#   Shot type defines emotion.
#   Wide establishes, medium connects, close reveals.
#
# Shot types (normalized):
#   - EXTREME_WIDE
#   - WIDE
#   - MEDIUM
#   - MEDIUM_CLOSE
#   - CLOSE
#
# Outputs:
#   - shot_type (string)
#   - confidence (0–1)
#
# ==============================================================================

from enum import Enum


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class ShotType(str, Enum):
    EXTREME_WIDE = "extreme_wide"
    WIDE = "wide"
    MEDIUM = "medium"
    MEDIUM_CLOSE = "medium_close"
    CLOSE = "close"


class ShotClassification:
    """
    Result of shot type classification.
    """
    __slots__ = (
        "shot_type",
        "confidence",
    )
    def __init__(self, shot_type: ShotType, confidence: float):
        self.shot_type = shot_type
        self.confidence = _clamp(confidence, 0.0, 1.0)


class ShotTypeClassifier:
    """
    Determines cinematic shot type.
    """
    __slots__ = (
        "_motion_bias",
        "_priority_bias",
    )
    def __init__(
        self,
        motion_bias: float = 0.35,
        priority_bias: float = 0.25,
    ):
        self._motion_bias = _clamp(motion_bias, 0.0, 1.0)
        self._priority_bias = _clamp(priority_bias, 0.0, 1.0)
    def classify(
        self,
        subject_scale: float,
        motion_intensity: float,
        narrative_priority: float,
    ) -> ShotClassification:
        """
        subject_scale: normalized subject area [0–1]
        motion_intensity: [0–1]
        narrative_priority: [0–1]
        """
        subject_scale = _clamp(subject_scale, 0.0, 1.0)
        motion = _clamp(motion_intensity, 0.0, 1.0)
        priority = _clamp(narrative_priority, 0.0, 1.0)
        # Weighted perceived intimacy
        intimacy = (
            subject_scale * 0.6 +
            priority * self._priority_bias -
            motion * self._motion_bias
        )
        intimacy = _clamp(intimacy, 0.0, 1.0)
        if intimacy < 0.15:
            return ShotClassification(ShotType.EXTREME_WIDE, 1.0 - intimacy)
        if intimacy < 0.30:
            return ShotClassification(ShotType.WIDE, 0.8)
        if intimacy < 0.55:
            return ShotClassification(ShotType.MEDIUM, 0.85)
        if intimacy < 0.75:
            return ShotClassification(ShotType.MEDIUM_CLOSE, 0.9)
        return ShotClassification(ShotType.CLOSE, 1.0)
