# ==============================================================================
# CHUNK 86 D 08 — SHOT DURATION & CUT TIMING MODEL
# ==============================================================================
#
# Purpose:
#   Determine how long to hold a shot and when to cut, based on
#   motion, narrative intensity, and visual stability.
#
# Cinematic principle:
#   Hold long enough to feel intentional; cut only when the story asks.
#
# This module:
#   - Computes optimal shot duration windows
#   - Prevents rapid-fire cuts
#   - Aligns cut timing with motion troughs
#
# ==============================================================================

import math
from collections import deque
from typing import Deque, Optional


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class ShotTimingState:
    """
    Temporal state for shot timing decisions.
    """
    __slots__ = (
        "frames_held",
        "motion_hist",
        "last_cut_frame",
    )
    def __init__(self, window: int = 20):
        self.frames_held: int = 0
        self.motion_hist: Deque[float] = deque(maxlen=window)
        self.last_cut_frame: int = 0


class ShotTimingDecision:
    """
    Output decision for cut timing.
    """
    __slots__ = (
        "should_cut",
        "confidence",
        "recommended_hold_frames",
    )
    def __init__(
        self,
        should_cut: bool,
        confidence: float,
        recommended_hold_frames: int,
    ):
        self.should_cut = should_cut
        self.confidence = _clamp(confidence, 0.0, 1.0)
        self.recommended_hold_frames = max(1, int(recommended_hold_frames))


class ShotTimingModel:
    """
    Computes cinematic shot duration and cut timing.
    """
    __slots__ = (
        "_min_hold",
        "_max_hold",
        "_motion_sensitivity",
        "_priority_bias",
    )
    def __init__(
        self,
        min_hold_frames: int = 24,
        max_hold_frames: int = 180,
        motion_sensitivity: float = 0.6,
        priority_bias: float = 0.4,
    ):
        self._min_hold = max(6, int(min_hold_frames))
        self._max_hold = max(self._min_hold, int(max_hold_frames))
        self._motion_sensitivity = _clamp(motion_sensitivity, 0.0, 1.0)
        self._priority_bias = _clamp(priority_bias, 0.0, 1.0)
    def update(
        self,
        motion_intensity: float,
        narrative_priority: float,
        state: ShotTimingState,
    ) -> ShotTimingDecision:
        motion = _clamp(motion_intensity, 0.0, 1.0)
        priority = _clamp(narrative_priority, 0.0, 1.0)
        state.frames_held += 1
        state.motion_hist.append(motion)
        # Base hold time scales inversely with motion
        dynamic_hold = (
            self._max_hold * (1.0 - motion * self._motion_sensitivity)
        )
        # Narrative importance extends hold
        dynamic_hold *= (1.0 + priority * self._priority_bias)
        recommended = int(_clamp(dynamic_hold, self._min_hold, self._max_hold))
        # Enforce minimum hold
        if state.frames_held < self._min_hold:
            return ShotTimingDecision(False, 0.0, recommended)
        # Detect motion trough (good cut point)
        if len(state.motion_hist) >= 5:
            recent = list(state.motion_hist)[-5:]
            trough = recent[2] == min(recent)
        else:
            trough = False
        should_cut = False
        confidence = 0.0
        if state.frames_held >= recommended and trough:
            should_cut = True
            confidence = 0.8 + priority * 0.2
        # Absolute max hold safeguard
        if state.frames_held >= self._max_hold:
            should_cut = True
            confidence = 1.0
        return ShotTimingDecision(
            should_cut=should_cut,
            confidence=confidence,
            recommended_hold_frames=recommended,
        )
