# ==============================================================================
# CHUNK 86 D 09 — NARRATIVE PRIORITY MEMORY
# ==============================================================================
#
# Purpose:
#   Maintain short- and mid-term memory of narrative importance so the
#   system avoids premature cuts, redundant angles, or loss of story focus.
#
# Cinematic principle:
#   Story beats persist across shots; priority decays, it does not vanish.
#
# This module:
#   - Tracks priority over time
#   - Smooths abrupt priority changes
#   - Exposes a stable priority signal to timing and motion planners
#
# ==============================================================================

from collections import deque
from typing import Deque


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class NarrativePriorityMemory:
    """
    Temporal memory for narrative importance.
    """
    __slots__ = (
        "_short_window",
        "_long_window",
        "_decay",
        "_short_hist",
        "_long_hist",
        "_current",
    )
    def __init__(
        self,
        short_window: int = 12,
        long_window: int = 90,
        decay: float = 0.985,
    ):
        self._short_window = max(3, int(short_window))
        self._long_window = max(self._short_window, int(long_window))
        self._decay = _clamp(decay, 0.90, 0.999)
        self._short_hist: Deque[float] = deque(maxlen=self._short_window)
        self._long_hist: Deque[float] = deque(maxlen=self._long_window)
        self._current: float = 0.0
    def update(self, instantaneous_priority: float) -> float:
        """
        Update memory with a new instantaneous narrative priority.
        Returns the smoothed priority signal.
        """
        p = _clamp(instantaneous_priority, 0.0, 1.0)
        # Exponential decay of current importance
        self._current *= self._decay
        # New information competes with memory
        if p > self._current:
            self._current = p
        self._short_hist.append(self._current)
        self._long_hist.append(self._current)
        # Short-term captures immediate beats
        short_avg = sum(self._short_hist) / len(self._short_hist)
        # Long-term preserves scene-level intent
        long_avg = sum(self._long_hist) / len(self._long_hist)
        # Blend: short-term leads, long-term stabilizes
        blended = 0.65 * short_avg + 0.35 * long_avg
        self._current = _clamp(blended, 0.0, 1.0)
        return self._current
    def force_hold(self, boost: float = 0.15) -> float:
        """
        Temporarily boosts priority to prevent cuts during critical beats.
        """
        self._current = _clamp(self._current + boost, 0.0, 1.0)
        return self._current
    def reset(self) -> None:
        """
        Hard reset between scenes.
        """
        self._short_hist.clear()
        self._long_hist.clear()
        self._current = 0.0
