# END OF CHUNK 86 D 09
# ==============================================================================
# ==============================================================================
# CHUNK 86 D 10 — INTENT CONFIDENCE DECAY SYSTEM
# ==============================================================================
#
# Purpose:
#   Stabilize high-level cinematic intent signals over time by applying
#   perceptually-grounded decay, hysteresis, and reinforcement.
#
# Cinematic principle:
#   Human-directed intent should fade smoothly, not snap, unless overridden
#   by stronger evidence or explicit user direction.
#
# This module:
#   - Applies asymmetric decay (slower decay for strong intent)
#   - Adds hysteresis to avoid rapid intent flipping
#   - Allows reinforcement from vision/audio/user cues
#
# ==============================================================================

from typing import Dict, Optional


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class IntentConfidenceDecay:
    """
    Manages confidence levels for named cinematic intents
    (e.g., 'follow_subject', 'establishing_shot', 'hold_closeup').
    """
    __slots__ = (
        "_conf",
        "_base_decay",
        "_strong_decay",
        "_hysteresis",
        "_reinforce_gain",
    )
    def __init__(
        self,
        base_decay: float = 0.985,
        strong_decay: float = 0.995,
        hysteresis: float = 0.08,
        reinforce_gain: float = 0.25,
    ):
        """
        base_decay:
            Default exponential decay for weak/moderate intents.
        strong_decay:
            Slower decay applied when confidence is already high.
        hysteresis:
            Minimum delta required to switch dominant intent.
        reinforce_gain:
            Gain applied when reinforcing signals arrive.
        """
        self._conf: Dict[str, float] = {}
        self._base_decay = _clamp(base_decay, 0.90, 0.999)
        self._strong_decay = _clamp(strong_decay, self._base_decay, 0.9999)
        self._hysteresis = _clamp(hysteresis, 0.0, 0.3)
        self._reinforce_gain = _clamp(reinforce_gain, 0.0, 1.0)
    def update(
        self,
        intent: str,
        instantaneous_confidence: float,
        reinforce: bool = False,
    ) -> float:
        """
        Update confidence for a specific intent.
        reinforce:
            If True, boosts confidence using reinforce_gain.
        """
        c_new = _clamp(instantaneous_confidence)
        c_prev = self._conf.get(intent, 0.0)
        # Choose decay regime based on existing confidence
        decay = (
            self._strong_decay if c_prev >= 0.6 else self._base_decay
        )
        # Decay previous confidence
        c = c_prev * decay
        # Compete with new evidence
        if c_new > c:
            c = c_new
        # Optional reinforcement from aligned cues
        if reinforce:
            c += self._reinforce_gain * (1.0 - c)
        self._conf[intent] = _clamp(c)
        return self._conf[intent]
    def decay_all(self) -> None:
        """
        Apply decay to all intents (called once per frame/tick).
        """
        for k, v in list(self._conf.items()):
            decay = (
                self._strong_decay if v >= 0.6 else self._base_decay
            )
            nv = v * decay
            # Cull negligible intents to keep state minimal
            if nv < 0.01:
                del self._conf[k]
            else:
                self._conf[k] = nv
    def dominant_intent(self) -> Optional[str]:
        """
        Returns the currently dominant intent, if any,
        respecting hysteresis to avoid rapid switching.
        """
        if not self._conf:
            return None
        # Find top two intents
        sorted_items = sorted(
            self._conf.items(), key=lambda kv: kv[1], reverse=True
        )
        top_intent, top_val = sorted_items[0]
        if len(sorted_items) == 1:
            return top_intent
        _, second_val = sorted_items[1]
        # Enforce hysteresis margin
        if (top_val - second_val) < self._hysteresis:
            return None
        return top_intent
    def get_confidence(self, intent: str) -> float:
        """
        Query confidence for a given intent.
        """
        return self._conf.get(intent, 0.0)
    def reset(self) -> None:
        """
        Clear all intent confidences (scene cut or hard reset).
        """
        self._conf.clear()
