# ==============================================================================
# CHUNK 86 E 01 — CAMERA MOTION STYLE SELECTOR
# ==============================================================================
#
# Purpose:
#   Selects an optimal camera motion style (static, pan, tilt, dolly,
#   truck, orbit) based on narrative intent, subject dynamics, and
#   motion energy budget.
#
# Cinematic principle:
#   Motion should express story intent; unnecessary motion degrades
#   perceived production value.
#
# Inputs:
#   - Dominant narrative intent
#   - Subject velocity & screen-space drift
#   - Scene scale & depth cues
#   - Motion energy budget (fatigue control)
#
# Outputs:
#   - Discrete motion style label
#   - Normalized confidence score
#
# ==============================================================================

from typing import Dict, Tuple


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class CameraMotionStyleSelector:
    """
    Chooses camera motion style using perceptual heuristics.
    """
    __slots__ = (
        "_weights",
        "_last_style",
        "_stickiness",
    )
    def __init__(self, stickiness: float = 0.15):
        """
        stickiness:
            Bias to retain previous motion style to avoid jitter.
        """
        self._weights: Dict[str, Dict[str, float]] = {
            "static": {
                "low_motion": 1.0,
                "intimate": 0.8,
                "establish": 0.2,
            },
            "pan": {
                "lateral_motion": 0.9,
                "follow": 0.6,
            },
            "tilt": {
                "vertical_motion": 0.9,
                "reveal": 0.7,
            },
            "dolly": {
                "depth_change": 1.0,
                "emphasis": 0.6,
            },
            "truck": {
                "parallel_motion": 0.9,
                "follow": 0.5,
            },
            "orbit": {
                "hero_subject": 1.0,
                "dramatic": 0.8,
            },
        }
        self._last_style: str = "static"
        self._stickiness = _clamp(stickiness, 0.0, 0.5)
    def select(
        self,
        intent: str,
        subject_speed: float,
        screen_drift: Tuple[float, float],
        depth_change: float,
        motion_budget: float,
    ) -> Tuple[str, float]:
        """
        Returns (motion_style, confidence).
        subject_speed:
            World or image-space speed (normalized 0–1).
        screen_drift:
            (dx, dy) normalized drift of subject in frame.
        depth_change:
            Estimated change in depth (0–1).
        motion_budget:
            Remaining motion energy (0–1).
        """
        # Gate motion if budget is depleted
        if motion_budget < 0.15:
            self._last_style = "static"
            return "static", 1.0
        dx, dy = abs(screen_drift[0]), abs(screen_drift[1])
        features = {
            "low_motion": 1.0 - _clamp(subject_speed),
            "lateral_motion": _clamp(dx),
            "vertical_motion": _clamp(dy),
            "parallel_motion": _clamp(subject_speed * dx),
            "depth_change": _clamp(depth_change),
            "follow": _clamp(subject_speed),
            "intimate": 1.0 if intent in ("intimate", "dialog") else 0.0,
            "establish": 1.0 if intent == "establishing" else 0.0,
            "reveal": 1.0 if intent == "reveal" else 0.0,
            "emphasis": 1.0 if intent in ("emphasis", "focus") else 0.0,
            "hero_subject": 1.0 if intent == "hero" else 0.0,
            "dramatic": 1.0 if intent in ("dramatic", "climax") else 0.0,
        }
        scores: Dict[str, float] = {}
        for style, wmap in self._weights.items():
            s = 0.0
            for k, w in wmap.items():
                s += w * features.get(k, 0.0)
            # Penalize heavy motion when subject is nearly static
            if style != "static" and subject_speed < 0.1:
                s *= 0.5
            scores[style] = s
        # Apply stickiness to previous style
        scores[self._last_style] += self._stickiness
        # Select best style
        best_style = max(scores, key=scores.get)
        best_score = scores[best_style]
        # Normalize confidence
        total = sum(scores.values()) + 1e-6
        confidence = _clamp(best_score / total)
        self._last_style = best_style
        return best_style, confidence
    def reset(self) -> None:
        """
        Reset style memory between scenes.
        """
        self._last_style = "static"
