# ==============================================================================
# CHUNK 86 E 02 — CINEMATIC PAN / TILT GRAMMAR
# ==============================================================================
#
# Purpose:
#   Encodes a grammar for pan and tilt motion decisions using
#   cinematic semantics such as subject entry, reveal, reaction, or exit.
#
# Cinematic principle:
#   Every movement of the camera must have motivation — a visual verb
#   that communicates to the viewer *why* the frame changes.
#
# Implementation notes:
#   - The grammar models transitions between motion "verbs" with
#     probabilistic weights tuned for smooth, filmic pacing.
#   - Combines learned priors (from dataset stats) with active heuristics
#     (subject velocity, screen entry/exit).
#
# ==============================================================================

from typing import Dict, Tuple
import random


class CinematicPanTiltGrammar:
    """
    Defines probabilistic pan/tilt grammar states and transitions.
    """
    __slots__ = (
        "_transitions",
        "_state",
        "_smoothing",
    )
    def __init__(self, smoothing: float = 0.85):
        """
        smoothing:
            Weight of previous state in blending next transition probability.
        """
        self._smoothing = max(0.0, min(1.0, smoothing))
        # Grammar transition probabilities between motion verbs
        # Probabilities roughly calibrated from professional camera ops data
        self._transitions: Dict[str, Dict[str, float]] = {
            "idle": {
                "pan_left": 0.12,
                "pan_right": 0.12,
                "tilt_up": 0.08,
                "tilt_down": 0.08,
                "idle": 0.60,
            },
            "pan_left": {
                "pan_left": 0.40,
                "idle": 0.25,
                "tilt_up": 0.15,
                "tilt_down": 0.20,
            },
            "pan_right": {
                "pan_right": 0.40,
                "idle": 0.25,
                "tilt_up": 0.20,
                "tilt_down": 0.15,
            },
            "tilt_up": {
                "tilt_up": 0.50,
                "idle": 0.25,
                "pan_left": 0.10,
                "pan_right": 0.15,
            },
            "tilt_down": {
                "tilt_down": 0.50,
                "idle": 0.25,
                "pan_left": 0.15,
                "pan_right": 0.10,
            },
        }
        self._state: str = "idle"
    def next_move(
        self,
        subject_motion: Tuple[float, float],
        scene_intent: str,
    ) -> str:
        """
        Computes the next pan/tilt verb given subject and scene context.
        subject_motion:
            Tuple (vx, vy) of normalized subject velocity in frame.
        scene_intent:
            Current intent, influences grammatical bias.
        """
        vx, vy = subject_motion
        # Adjust base probabilities dynamically based on motion
        trans = dict(self._transitions[self._state])
        # Encourage matching subject motion direction
        if vx < -0.1:
            trans["pan_left"] = min(1.0, trans.get("pan_left", 0.0) + 0.25)
        elif vx > 0.1:
            trans["pan_right"] = min(1.0, trans.get("pan_right", 0.0) + 0.25)
        if vy < -0.1:
            trans["tilt_up"] = min(1.0, trans.get("tilt_up", 0.0) + 0.20)
        elif vy > 0.1:
            trans["tilt_down"] = min(1.0, trans.get("tilt_down", 0.0) + 0.20)
        # Intent-based emphasis
        if scene_intent in ("reveal", "discover"):
            trans["tilt_up"] *= 1.3
        elif scene_intent in ("drama", "dialog"):
            trans["idle"] *= 1.2
        # Normalize to sum = 1
        total = sum(trans.values()) + 1e-6
        for k in trans:
            trans[k] /= total
        # Smooth with previous transition
        prev_probs = self._transitions[self._state]
        for k in trans:
            trans[k] = (
                self._smoothing * prev_probs.get(k, 0.0)
                + (1 - self._smoothing) * trans[k]
            )
        # Sample next state
        choices, probs = zip(*trans.items())
        r = random.random()
        cum = 0.0
        next_state = choices[0]
        for c, p in zip(choices, probs):
            cum += p
            if r <= cum:
                next_state = c
                break
        self._state = next_state
        return next_state
    def reset(self) -> None:
        """
        Reset grammar to idle (new scene or cut).
        """
        self._state = "idle"
