# ==============================================================================
# CHUNK 86 E 03 — DOLLY / TRUCK MOTION PLANNER
# ==============================================================================
#
# Purpose:
#   Plans smooth dolly (forward/back) and truck (sideways) camera motion
#   trajectories that respect cinematic pacing, subject comfort, and
#   spatial continuity.
#
# Cinematic principle:
#   Dolly movement conveys emotional emphasis; truck movement preserves
#   spatial relationship without drawing attention to itself.
#
# This planner:
#   - Generates velocity profiles with eased acceleration
#   - Couples motion strength to narrative emphasis
#   - Avoids depth oscillation and lateral jitter
#
# ==============================================================================

from typing import Tuple


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


def _ease_in_out(t: float) -> float:
    """
    Smooth cubic ease-in-out.
    """
    t = _clamp(t)
    return 3 * t ** 2 - 2 * t ** 3


class DollyTruckMotionPlanner:
    """
    Computes dolly and truck motion vectors per frame.
    """
    __slots__ = (
        "_max_speed",
        "_accel_time",
        "_phase",
    )
    def __init__(
        self,
        max_speed: float = 0.6,
        accel_time: float = 0.4,
    ):
        """
        max_speed:
            Maximum normalized camera translation speed.
        accel_time:
            Fraction of motion spent accelerating/decelerating.
        """
        self._max_speed = _clamp(max_speed)
        self._accel_time = _clamp(accel_time, 0.05, 0.5)
        self._phase = 0.0
    def plan(
        self,
        mode: str,
        emphasis: float,
        lateral_offset: float,
        depth_offset: float,
        dt: float,
    ) -> Tuple[float, float]:
        """
        Returns (truck_velocity, dolly_velocity).
        mode:
            'dolly', 'truck', or 'combined'
        emphasis:
            Narrative emphasis (0–1).
        lateral_offset:
            Desired sideways correction (-1 to 1).
        depth_offset:
            Desired forward/back correction (-1 to 1).
        dt:
            Delta time (seconds), normalized scale assumed.
        """
        emphasis = _clamp(emphasis)
        # Advance motion phase
        self._phase = min(1.0, self._phase + dt)
        # Compute eased gain
        eased = _ease_in_out(
            min(self._phase / max(self._accel_time, 1e-3), 1.0)
        )
        speed = self._max_speed * eased * emphasis
        truck_v = 0.0
        dolly_v = 0.0
        if mode in ("truck", "combined"):
            truck_v = speed * _clamp(lateral_offset, -1.0, 1.0)
        if mode in ("dolly", "combined"):
            dolly_v = speed * _clamp(depth_offset, -1.0, 1.0)
        return truck_v, dolly_v
    def reset(self) -> None:
        """
        Reset motion phase (cut or style change).
        """
        self._phase = 0.0
