# ==============================================================================
# CHUNK 86 E 04 — MOTION STYLE PERSISTENCE MEMORY
# ==============================================================================
#
# Purpose:
#   Prevents rapid oscillation between camera motion styles by maintaining
#   a short-term persistence memory with decay and reinforcement.
#
# Cinematic principle:
#   Professional camera operation favors commitment — once a motion begins,
#   it is allowed to breathe unless a stronger narrative force intervenes.
#
# This module:
#   - Stores recent motion styles with confidence
#   - Applies decay rather than abrupt switching
#   - Enforces minimum hold time for stylistic continuity
#
# ==============================================================================

from typing import Dict


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class MotionStylePersistenceMemory:
    """
    Memory system that stabilizes camera motion styles over time.
    """
    __slots__ = (
        "_memory",
        "_decay",
        "_min_hold",
    )
    def __init__(
        self,
        decay: float = 0.97,
        min_hold: int = 12,
    ):
        """
        decay:
            Per-frame confidence decay for inactive styles.
        min_hold:
            Minimum frames to hold a chosen style before switching.
        """
        self._decay = _clamp(decay, 0.90, 0.999)
        self._min_hold = max(1, int(min_hold))
        self._memory: Dict[str, Dict[str, float]] = {}
    def update(self, style: str, confidence: float) -> str:
        """
        Update persistence memory with a proposed style.
        Returns the style that should actually be used.
        """
        confidence = _clamp(confidence)
        # Decay all existing styles
        for s in list(self._memory.keys()):
            self._memory[s]["conf"] *= self._decay
            self._memory[s]["age"] += 1
            if self._memory[s]["conf"] < 0.01:
                del self._memory[s]
        # Insert or reinforce proposed style
        if style not in self._memory:
            self._memory[style] = {
                "conf": confidence,
                "age": 0,
            }
        else:
            self._memory[style]["conf"] = max(
                self._memory[style]["conf"], confidence
            )
            self._memory[style]["age"] = 0
        # Select best style respecting minimum hold
        best_style = style
        best_conf = self._memory[style]["conf"]
        for s, v in self._memory.items():
            if v["age"] < self._min_hold:
                continue
            if v["conf"] > best_conf:
                best_style = s
                best_conf = v["conf"]
        return best_style
    def reset(self) -> None:
        """
        Clears persistence memory (scene cut or hard reset).
        """
        self._memory.clear()
