# ==============================================================================
# CHUNK 86 E 05 — MOTION ENERGY BUDGET CONTROLLER
# ==============================================================================
#
# Purpose:
#   Regulates cumulative camera motion to prevent visual fatigue and
#   over-stylization while preserving impact during narrative peaks.
#
# Cinematic principle:
#   Great cinematography uses motion sparingly — restraint increases impact.
#
# This controller:
#   - Tracks motion energy accumulation over time
#   - Applies recovery when motion is minimal
#   - Gates aggressive motion styles when budget is depleted
#
# ==============================================================================

def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class MotionEnergyBudgetController:
    """
    Maintains a rolling budget of allowable camera motion.
    """
    __slots__ = (
        "_budget",
        "_decay_rate",
        "_recovery_rate",
    )
    def __init__(
        self,
        initial_budget: float = 1.0,
        decay_rate: float = 0.04,
        recovery_rate: float = 0.02,
    ):
        """
        initial_budget:
            Starting motion energy (0–1).
        decay_rate:
            Budget consumed per unit motion.
        recovery_rate:
            Budget regained per frame when motion is low.
        """
        self._budget = _clamp(initial_budget)
        self._decay_rate = _clamp(decay_rate, 0.001, 0.2)
        self._recovery_rate = _clamp(recovery_rate, 0.001, 0.2)
    def update(self, motion_magnitude: float) -> float:
        """
        Updates and returns the remaining motion budget.
        motion_magnitude:
            Normalized magnitude of camera motion (0–1).
        """
        motion_magnitude = _clamp(motion_magnitude)
        # Consume budget proportionally to motion
        self._budget -= motion_magnitude * self._decay_rate
        # Recover when motion is minimal
        if motion_magnitude < 0.1:
            self._budget += self._recovery_rate * (1.0 - self._budget)
        self._budget = _clamp(self._budget)
        return self._budget
    def can_apply(self, required_energy: float) -> bool:
        """
        Checks whether a motion requiring given energy is allowed.
        """
        return self._budget >= _clamp(required_energy)
    def reset(self) -> None:
        """
        Reset budget (scene cut or explicit reset).
        """
        self._budget = 1.0
