# ==============================================================================
# CHUNK 86 F 01 — SHOT DURATION PREDICTION ENGINE
# ==============================================================================
#
# Purpose:
#   Predicts optimal shot duration in frames/seconds based on narrative
#   intensity, motion energy, subject dynamics, and viewer fatigue models.
#
# Cinematic principle:
#   Shot length communicates emotion. Faster cuts raise urgency; longer
#   holds increase intimacy and gravity.
#
# This engine:
#   - Estimates a target duration window (min, ideal, max)
#   - Adapts to motion energy and narrative priority
#   - Provides soft constraints to downstream cut logic
#
# ==============================================================================

from typing import Tuple


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class ShotDurationPredictionEngine:
    """
    Predicts shot duration using perceptual and narrative heuristics.
    """
    __slots__ = (
        "_base_min",
        "_base_ideal",
        "_base_max",
    )
    def __init__(
        self,
        base_min: float = 0.8,
        base_ideal: float = 2.5,
        base_max: float = 6.0,
    ):
        """
        base_*:
            Baseline shot durations in seconds for neutral scenes.
        """
        self._base_min = max(0.2, base_min)
        self._base_ideal = max(self._base_min, base_ideal)
        self._base_max = max(self._base_ideal, base_max)
    def predict(
        self,
        narrative_priority: float,
        motion_energy: float,
        subject_speed: float,
        viewer_fatigue: float,
    ) -> Tuple[float, float, float]:
        """
        Returns (min_sec, ideal_sec, max_sec).
        narrative_priority:
            Importance of current beat (0–1).
        motion_energy:
            Accumulated motion energy (0–1).
        subject_speed:
            Normalized subject motion (0–1).
        viewer_fatigue:
            Estimated viewer fatigue (0–1).
        """
        np = _clamp(narrative_priority)
        me = _clamp(motion_energy)
        ss = _clamp(subject_speed)
        vf = _clamp(viewer_fatigue)
        # Narrative emphasis stretches shots
        narrative_scale = 1.0 + 1.2 * np
        # High motion compresses duration
        motion_scale = 1.0 - 0.8 * max(me, ss)
        # Fatigue encourages longer holds (rest)
        fatigue_scale = 1.0 + 0.6 * vf
        scale = narrative_scale * motion_scale * fatigue_scale
        scale = max(0.35, scale)
        min_sec = self._base_min * scale
        ideal_sec = self._base_ideal * scale
        max_sec = self._base_max * scale
        # Enforce ordering and sanity
        min_sec = max(0.2, min_sec)
        ideal_sec = max(min_sec, ideal_sec)
        max_sec = max(ideal_sec, max_sec)
        return min_sec, ideal_sec, max_sec
    def reset(self) -> None:
        """
        No persistent state; included for interface symmetry.
        """
        pass
