# ==============================================================================
# CHUNK 86 F 02 — ADAPTIVE COMPOSITION REFINEMENT
# ==============================================================================
#
# Purpose:
#   Continuously refines framing to maintain strong composition under
#   subject motion, camera movement, and narrative changes.
#
# Cinematic principle:
#   Composition is not static — it breathes subtly to keep visual balance
#   without drawing attention to the camera.
#
# This module:
#   - Tracks rule-of-thirds & headroom error
#   - Applies micro-corrections over time (no snapping)
#   - Prioritizes subject stability over perfect geometry
#
# ==============================================================================

from typing import Tuple


def _clamp(x: float, lo: float = -1.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class AdaptiveCompositionRefinement:
    """
    Maintains aesthetically balanced framing through slow corrective drift.
    """
    __slots__ = (
        "_gain",
        "_max_adjust",
    )
    def __init__(
        self,
        gain: float = 0.08,
        max_adjust: float = 0.25,
    ):
        """
        gain:
            Correction strength per frame.
        max_adjust:
            Hard cap on correction magnitude.
        """
        self._gain = max(0.0, min(0.3, gain))
        self._max_adjust = max(0.05, min(0.5, max_adjust))
    def refine(
        self,
        subject_center: Tuple[float, float],
        desired_center: Tuple[float, float],
    ) -> Tuple[float, float]:
        """
        Returns subtle (dx, dy) correction offsets.
        subject_center:
            Current subject position in normalized frame coords (-1..1).
        desired_center:
            Ideal framing point (rule-of-thirds, etc).
        """
        sx, sy = subject_center
        dx, dy = desired_center
        err_x = _clamp(dx - sx)
        err_y = _clamp(dy - sy)
        corr_x = _clamp(err_x * self._gain, -self._max_adjust, self._max_adjust)
        corr_y = _clamp(err_y * self._gain, -self._max_adjust, self._max_adjust)
        return corr_x, corr_y
    def reset(self) -> None:
        """
        No persistent state; reset provided for interface consistency.
        """
        pass
