# ==============================================================================
# CHUNK 86 F 03 — SUBJECT SALIENCY TEMPORAL FILTER
# ==============================================================================
#
# Purpose:
#   Stabilize subject importance signals over time so attention does not
#   flicker between competing elements in the frame.
#
# Cinematic principle:
#   Viewers expect the camera to “know” what matters. Saliency must evolve
#   smoothly, not frame-to-frame.
#
# This module:
#   - Applies temporal smoothing to raw saliency scores
#   - Preserves dominance of primary subjects
#   - Allows gradual handoff between subjects
#
# ==============================================================================

from typing import Dict


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class SubjectSaliencyTemporalFilter:
    """
    Temporal filter for stabilizing subject saliency signals.
    """
    __slots__ = (
        "_alpha",
        "_saliency",
        "_dominance_bias",
    )
    def __init__(
        self,
        alpha: float = 0.85,
        dominance_bias: float = 0.15,
    ):
        """
        alpha:
            Exponential smoothing factor (higher = more stable).
        dominance_bias:
            Bias to preserve previously dominant subject.
        """
        self._alpha = _clamp(alpha, 0.6, 0.98)
        self._dominance_bias = _clamp(dominance_bias, 0.0, 0.5)
        self._saliency: Dict[str, float] = {}
    def update(self, raw_saliency: Dict[str, float]) -> Dict[str, float]:
        """
        Update saliency map with new raw measurements.
        raw_saliency:
            Dict of {subject_id: saliency_score}.
        """
        # Normalize incoming saliency
        total = sum(max(0.0, v) for v in raw_saliency.values()) + 1e-6
        norm = {
            k: max(0.0, v) / total for k, v in raw_saliency.items()
        }
        # Identify previous dominant subject
        prev_dom = None
        if self._saliency:
            prev_dom = max(self._saliency, key=self._saliency.get)
        # Update saliency with exponential smoothing
        new_saliency: Dict[str, float] = {}
        for sid, v in norm.items():
            prev = self._saliency.get(sid, 0.0)
            new_saliency[sid] = (
                self._alpha * prev + (1.0 - self._alpha) * v
            )
        # Apply dominance bias to avoid rapid subject switching
        if prev_dom and prev_dom in new_saliency:
            new_saliency[prev_dom] += self._dominance_bias
        # Renormalize
        total_new = sum(new_saliency.values()) + 1e-6
        for k in new_saliency:
            new_saliency[k] = _clamp(new_saliency[k] / total_new)
        self._saliency = new_saliency
        return dict(self._saliency)
    def dominant_subject(self) -> str:
        """
        Returns the ID of the dominant subject, if any.
        """
        if not self._saliency:
            return ""
        return max(self._saliency, key=self._saliency.get)
    def reset(self) -> None:
        """
        Clears saliency memory (scene cut).
        """
        self._saliency.clear()
