# ==============================================================================
# CHUNK 86 F 04 — FRAMING ERROR ACCUMULATION MODEL
# ==============================================================================
#
# Purpose:
#   Accumulate small framing errors over time to drive smooth,
#   intentional re-centering instead of reactive oscillation.
#
# Cinematic principle:
#   Cameras drift with intent. Corrections should feel motivated,
#   not nervous.
#
# This module:
#   - Integrates framing error with decay
#   - Introduces dead-zone tolerance
#   - Outputs a bounded correction vector
#
# ==============================================================================

from typing import Tuple


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class FramingErrorAccumulator:
    """
    Integrates framing error over time to produce cinematic correction intent.
    """
    __slots__ = (
        "_decay",
        "_dead_zone",
        "_max_integral",
        "_ix",
        "_iy",
    )
    def __init__(
        self,
        decay: float = 0.92,
        dead_zone: float = 0.04,
        max_integral: float = 0.6,
    ):
        """
        decay:
            Memory decay per frame (closer to 1.0 = longer memory).
        dead_zone:
            Error magnitude below which accumulation is ignored.
        max_integral:
            Hard cap on accumulated correction.
        """
        self._decay = _clamp(decay, 0.7, 0.99)
        self._dead_zone = _clamp(dead_zone, 0.0, 0.15)
        self._max_integral = _clamp(max_integral, 0.2, 1.0)
        self._ix = 0.0
        self._iy = 0.0
    def update(self, error: Tuple[float, float]) -> Tuple[float, float]:
        """
        Update the accumulator with current framing error.
        error:
            (ex, ey) framing error in normalized frame space (-1..1).
        """
        ex, ey = error
        # Apply dead-zone
        if abs(ex) < self._dead_zone:
            ex = 0.0
        if abs(ey) < self._dead_zone:
            ey = 0.0
        # Integrate with decay
        self._ix = self._ix * self._decay + ex
        self._iy = self._iy * self._decay + ey
        # Clamp accumulated intent
        self._ix = _clamp(self._ix, -self._max_integral, self._max_integral)
        self._iy = _clamp(self._iy, -self._max_integral, self._max_integral)
        return self._ix, self._iy
    def reset(self) -> None:
        """
        Clears accumulated error (scene cut or reframing event).
        """
        self._ix = 0.0
        self._iy = 0.0
