# ==============================================================================
# CHUNK 86 F 05 — CUT SUPPRESSION LOGIC
# ==============================================================================
#
# Purpose:
#   Prevents unintended rapid reframing or micro-cuts caused by
#   transient subject motion, detection noise, or brief occlusions.
#
# Cinematic principle:
#   Real films do not "panic cut". The camera commits to a shot
#   unless a strong narrative or compositional reason forces a change.
#
# This module:
#   - Applies temporal hysteresis to cut decisions
#   - Uses motion-energy-aware suppression windows
#   - Outputs a boolean permission to cut or reframe
#
# ==============================================================================

from typing import Optional


def _clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, float(x)))


class CutSuppressionLogic:
    """
    Controls whether a cut / hard reframe is allowed at a given moment.
    """
    __slots__ = (
        "_min_hold_frames",
        "_motion_threshold",
        "_energy_decay",
        "_energy",
        "_hold_counter",
    )
    def __init__(
        self,
        min_hold_frames: int = 24,
        motion_threshold: float = 0.35,
        energy_decay: float = 0.88,
    ):
        """
        min_hold_frames:
            Minimum frames a shot must be held before a cut is allowed.
        motion_threshold:
            Motion energy above which cuts are suppressed.
        energy_decay:
            Temporal decay for motion energy integration.
        """
        self._min_hold_frames = max(6, int(min_hold_frames))
        self._motion_threshold = _clamp(motion_threshold, 0.1, 1.0)
        self._energy_decay = _clamp(energy_decay, 0.7, 0.99)
        self._energy = 0.0
        self._hold_counter = 0
    def update_motion_energy(self, instantaneous_energy: float) -> None:
        """
        Integrates instantaneous motion energy.
        instantaneous_energy:
            Normalized motion magnitude (0..1).
        """
        e = _clamp(instantaneous_energy, 0.0, 1.0)
        self._energy = self._energy * self._energy_decay + e
        self._energy = _clamp(self._energy, 0.0, 1.0)
    def allow_cut(self) -> bool:
        """
        Determines whether a cut or aggressive reframe is permitted.
        """
        self._hold_counter += 1
        # Enforce minimum shot duration
        if self._hold_counter < self._min_hold_frames:
            return False
        # Suppress cuts during high motion energy
        if self._energy > self._motion_threshold:
            return False
        return True
    def register_cut(self) -> None:
        """
        Call when a cut or hard reframe is executed.
        """
        self._hold_counter = 0
        self._energy = 0.0
    def reset(self) -> None:
        """
        Hard reset (scene change or manual override).
        """
        self._hold_counter = 0
        self._energy = 0.0
