# END OF CHUNK 86 G 05
# ==============================================================================
# ==============================================================================
# CHUNK 86 H 01 — SHOT CONTINUITY RESOLVER
# ==============================================================================
#
# Purpose:
#   Preserves perceptual continuity across frames and micro-reframes,
#   ensuring the shot feels like a single intentional camera take.
#
# Cinematic principle:
#   Real cinematography respects spatial memory. Subjects do not
#   teleport, axes do not flip, and framing evolves coherently.
#
# This module:
#   - Tracks framing deltas over time
#   - Penalizes axis inversions and spatial jumps
#   - Outputs a continuity score + corrected framing suggestion
#
# ==============================================================================

from typing import Tuple
import math


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class ShotContinuityResolver:
    """
    Evaluates and enforces spatial continuity of a shot.
    """
    __slots__ = (
        "_prev_center",
        "_prev_scale",
        "_prev_angle",
        "_memory_decay",
    )
    def __init__(self, memory_decay: float = 0.92):
        """
        memory_decay:
            How long spatial memory persists (closer to 1 = longer).
        """
        self._memory_decay = _clamp(memory_decay, 0.8, 0.99)
        self._prev_center = None  # (x, y)
        self._prev_scale = None   # zoom / crop scalar
        self._prev_angle = None   # camera yaw/roll proxy
    def _distance(self, a: Tuple[float, float], b: Tuple[float, float]) -> float:
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return math.sqrt(dx * dx + dy * dy)
    def evaluate(
        self,
        center: Tuple[float, float],
        scale: float,
        angle: float,
    ) -> Tuple[float, Tuple[float, float], float]:
        """
        Evaluates continuity and returns corrected framing.
        center:
            Normalized frame center (0..1, 0..1)
        scale:
            Normalized zoom/crop scale (0..1)
        angle:
            Normalized angular orientation (-1..1)
        Returns:
            continuity_score (0..1),
            corrected_center,
            corrected_scale
        """
        continuity = 1.0
        corrected_center = center
        corrected_scale = scale
        if self._prev_center is not None:
            # Penalize large spatial jumps
            dist = self._distance(center, self._prev_center)
            continuity *= _clamp(1.0 - dist * 1.8)
            # Penalize aggressive zoom changes
            scale_delta = abs(scale - self._prev_scale)
            continuity *= _clamp(1.0 - scale_delta * 2.0)
            # Penalize axis inversions / angle flips
            angle_delta = abs(angle - self._prev_angle)
            if angle_delta > 0.5:
                continuity *= 0.6
            # Soft correction toward previous framing
            w = _clamp(1.0 - continuity)
            corrected_center = (
                (1.0 - w) * center[0] + w * self._prev_center[0],
                (1.0 - w) * center[1] + w * self._prev_center[1],
            )
            corrected_scale = (
                (1.0 - w) * scale + w * self._prev_scale
            )
        # Update memory with decay
        if self._prev_center is None:
            self._prev_center = center
            self._prev_scale = scale
            self._prev_angle = angle
        else:
            self._prev_center = (
                self._memory_decay * self._prev_center[0] +
                (1.0 - self._memory_decay) * center[0],
                self._memory_decay * self._prev_center[1] +
                (1.0 - self._memory_decay) * center[1],
            )
            self._prev_scale = (
                self._memory_decay * self._prev_scale +
                (1.0 - self._memory_decay) * scale
            )
            self._prev_angle = (
                self._memory_decay * self._prev_angle +
                (1.0 - self._memory_decay) * angle
            )
        return _clamp(continuity), corrected_center, _clamp(corrected_scale)
    def reset(self) -> None:
        """
        Clears spatial memory (hard cut or manual override).
        """
        self._prev_center = None
        self._prev_scale = None
        self._prev_angle = None
