# END OF CHUNK 86 H 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 H 02 — CROSS-SHOT INTENT MEMORY
# ==============================================================================
#
# Purpose:
#   Maintains high-level cinematic intent across frames and micro-shots
#   so that framing, motion, and pacing decisions remain goal-consistent.
#
# Cinematic principle:
#   Human operators remember *why* a shot is happening.
#   Without intent memory, AI shots drift and feel unmotivated.
#
# This module:
#   - Stores persistent intent vectors (track, reveal, observe, pursue)
#   - Decays intent over time instead of hard reset
#   - Outputs dominant intent + confidence
#
# ==============================================================================

from typing import Dict, Tuple
import math


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class CrossShotIntentMemory:
    """
    Stores and blends cinematic intent across time.
    """
    __slots__ = (
        "_intent_weights",
        "_decay",
    )
    def __init__(self, decay: float = 0.94):
        """
        decay:
            Intent persistence factor per frame.
        """
        self._decay = _clamp(decay, 0.85, 0.99)
        self._intent_weights: Dict[str, float] = {}
    def push_intent(self, intent: str, strength: float) -> None:
        """
        Adds or reinforces an intent.
        intent:
            Semantic intent label.
        strength:
            Importance (0..1).
        """
        s = _clamp(strength)
        if intent in self._intent_weights:
            self._intent_weights[intent] = max(
                self._intent_weights[intent],
                s
            )
        else:
            self._intent_weights[intent] = s
    def update(self) -> None:
        """
        Applies decay to all stored intents.
        """
        for k in list(self._intent_weights.keys()):
            self._intent_weights[k] *= self._decay
            if self._intent_weights[k] < 0.01:
                del self._intent_weights[k]
    def dominant_intent(self) -> Tuple[str, float]:
        """
        Returns the dominant intent and confidence.
        """
        if not self._intent_weights:
            return "neutral", 0.0
        intent = max(
            self._intent_weights.items(),
            key=lambda x: x[1]
        )
        total = sum(self._intent_weights.values())
        confidence = intent[1] / max(total, 1e-6)
        return intent[0], _clamp(confidence)
    def clear(self) -> None:
        """
        Hard reset of intent memory.
        """
        self._intent_weights.clear()
