# END OF CHUNK 86 H 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 H 03 — REFRAME COHERENCE FILTER
# ==============================================================================
#
# Purpose:
#   Ensures reframing operations evolve smoothly and logically over time,
#   preventing jitter, indecision, or contradictory framing impulses.
#
# Cinematic principle:
#   Professional camera operators commit to a move.
#   Micro-reframes must reinforce intent, not fight each other.
#
# This module:
#   - Detects conflicting reframe vectors
#   - Dampens oscillatory behavior
#   - Outputs a stabilized reframe vector
#
# ==============================================================================

from typing import Tuple
import math


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


def _vec_len(v: Tuple[float, float]) -> float:
    return math.sqrt(v[0] * v[0] + v[1] * v[1])


class ReframeCoherenceFilter:
    """
    Stabilizes reframe direction and magnitude across frames.
    """
    __slots__ = (
        "_prev_vec",
        "_coherence",
        "_decay",
    )
    def __init__(self, decay: float = 0.9):
        """
        decay:
            How strongly previous reframe direction influences current.
        """
        self._decay = _clamp(decay, 0.8, 0.98)
        self._prev_vec: Tuple[float, float] = (0.0, 0.0)
        self._coherence: float = 1.0
    def apply(
        self,
        proposed_vec: Tuple[float, float],
    ) -> Tuple[Tuple[float, float], float]:
        """
        Applies coherence filtering.
        proposed_vec:
            Normalized (dx, dy) reframe direction.
        Returns:
            filtered_vec,
            coherence_score (0..1)
        """
        pvx, pvy = proposed_vec
        prevx, prevy = self._prev_vec
        # Dot product measures directional agreement
        dot = pvx * prevx + pvy * prevy
        # Penalize opposing impulses
        if dot < 0.0:
            self._coherence *= 0.7
        else:
            self._coherence = _clamp(
                self._coherence + 0.05 * dot
            )
        # Blend directions based on coherence
        w = self._coherence * self._decay
        fx = (1.0 - w) * pvx + w * prevx
        fy = (1.0 - w) * pvy + w * prevy
        mag = _vec_len((fx, fy))
        if mag > 1e-6:
            fx /= mag
            fy /= mag
        self._prev_vec = (fx, fy)
        return self._prev_vec, _clamp(self._coherence)
    def reset(self) -> None:
        """
        Resets coherence state (scene cut or override).
        """
        self._prev_vec = (0.0, 0.0)
        self._coherence = 1.0
# ==============================================================================
# END OF CHUNK 86 H 03
# ==============================================================================
# ==============================================================================
# CHUNK 86 H 04 — SUBJECT PERSISTENCE MODEL
# ==============================================================================
#
# Purpose:
#   Maintains temporal continuity of subject identity and importance,
#   preventing flicker, target swapping, or priority collapse.
#
# Cinematic principle:
#   Human operators subconsciously remember who matters in a shot.
#   A subject does not lose importance because of a brief occlusion.
#
# This module:
#   - Tracks subject persistence across frames
#   - Applies temporal decay instead of binary loss
#   - Outputs stabilized subject saliency
#
# ==============================================================================

from typing import Dict
import math


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class SubjectPersistenceModel:
    """
    Tracks and stabilizes subject importance over time.
    """
    __slots__ = (
        "_subjects",
        "_decay",
        "_boost",
    )
    def __init__(
        self,
        decay: float = 0.93,
        boost: float = 0.15,
    ):
        """
        decay:
            Per-frame persistence of subject importance.
        boost:
            Reinforcement when subject is re-observed.
        """
        self._decay = _clamp(decay, 0.85, 0.99)
        self._boost = _clamp(boost, 0.05, 0.35)
        self._subjects: Dict[str, float] = {}
    def update(self, observed_subjects: Dict[str, float]) -> Dict[str, float]:
        """
        Updates persistence using current observations.
        observed_subjects:
            Mapping subject_id -> instantaneous saliency (0..1)
        Returns:
            Persisted saliency map.
        """
        # Decay existing subjects
        for sid in list(self._subjects.keys()):
            self._subjects[sid] *= self._decay
            if self._subjects[sid] < 0.01:
                del self._subjects[sid]
        # Reinforce observed subjects
        for sid, sal in observed_subjects.items():
            s = _clamp(sal)
            if sid in self._subjects:
                self._subjects[sid] = _clamp(
                    self._subjects[sid] + self._boost * s
                )
            else:
                self._subjects[sid] = s
        # Normalize for stability
        total = sum(self._subjects.values())
        if total > 1e-6:
            for sid in self._subjects:
                self._subjects[sid] /= total
        return dict(self._subjects)
    def dominant_subject(self) -> str:
        """
        Returns the most persistent subject ID.
        """
        if not self._subjects:
            return ""
        return max(self._subjects.items(), key=lambda x: x[1])[0]
    def reset(self) -> None:
        """
        Clears subject memory (hard cut).
        """
        self._subjects.clear()
# ==============================================================================
# END OF CHUNK 86 H 04
# ==============================================================================
# ==============================================================================
# CHUNK 86 H 05 — VISUAL INTENT ARBITRATION
# ==============================================================================
#
# Purpose:
#   Resolves conflicts between multiple simultaneous visual intents
#   (tracking, reframing, stabilization, narrative emphasis).
#
# Cinematic principle:
#   A shot has ONE dominant intention at any moment.
#   Secondary intents must support — never override — the primary.
#
# This module:
#   - Scores competing visual intents
#   - Selects a dominant intent
#   - Soft-blends subordinate intents
#
# ==============================================================================

from typing import Dict, Tuple


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class VisualIntentArbitrator:
    """
    Chooses and stabilizes the dominant visual intent.
    """
    __slots__ = (
        "_dominant",
        "_stickiness",
    )
    def __init__(self, stickiness: float = 0.85):
        """
        stickiness:
            Resistance to switching dominant intent.
        """
        self._stickiness = _clamp(stickiness, 0.7, 0.95)
        self._dominant: str = ""
    def arbitrate(
        self,
        intents: Dict[str, float],
    ) -> Tuple[str, Dict[str, float]]:
        """
        Arbitrates between competing intents.
        intents:
            Mapping intent_name -> confidence (0..1)
        Returns:
            dominant_intent,
            blended_intents (normalized weights)
        """
        if not intents:
            return "", {}
        # Normalize
        total = sum(max(0.0, v) for v in intents.values())
        if total <= 1e-6:
            return "", {}
        norm = {k: v / total for k, v in intents.items()}
        # Determine candidate dominant
        candidate = max(norm.items(), key=lambda x: x[1])[0]
        # Apply stickiness
        if self._dominant and self._dominant in norm:
            if norm[self._dominant] * self._stickiness >= norm[candidate]:
                candidate = self._dominant
        self._dominant = candidate
        # Reweight: dominant emphasized, others suppressed
        blended: Dict[str, float] = {}
        for k, v in norm.items():
            if k == self._dominant:
                blended[k] = _clamp(0.6 + 0.4 * v)
            else:
                blended[k] = _clamp(0.4 * v)
        # Renormalize
        s = sum(blended.values())
        if s > 1e-6:
            for k in blended:
                blended[k] /= s
        return self._dominant, blended
    def reset(self) -> None:
        """
        Clears dominant intent (scene cut or override).
        """
        self._dominant = ""
# ==============================================================================
# END OF CHUNK 86 H 05
# ==============================================================================
# ==============================================================================
# CHUNK 86 I 01 — NARRATIVE SALIENCY TRACKER
# ==============================================================================
#
# Purpose:
#   Tracks what visually "matters" in a scene over time, not just what is visible.
#
# Cinematic principle:
#   Viewers follow narrative importance, not raw motion or brightness.
#
# This module:
#   - Maintains temporal saliency memory
#   - Boosts story-relevant subjects
#   - Prevents abrupt attention drops after cuts or occlusions
#
# ==============================================================================

from typing import Dict, Any


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class NarrativeSaliencyTracker:
    """
    Tracks narrative importance of scene entities over time.
    """
    __slots__ = (
        "_memory",
        "_decay",
        "_boost",
    )
    def __init__(
        self,
        decay: float = 0.92,
        reentry_boost: float = 1.35,
    ):
        """
        decay:
            Temporal persistence of narrative importance.
        reentry_boost:
            Multiplier applied when a known subject reappears.
        """
        self._decay = _clamp(decay, 0.85, 0.99)
        self._boost = _clamp(reentry_boost, 1.1, 1.6)
        self._memory: Dict[str, float] = {}
    def update(
        self,
        detections: Dict[str, Dict[str, Any]],
    ) -> Dict[str, float]:
        """
        Updates narrative saliency based on current detections.
        detections:
            id -> {
                "confidence": float,
                "screen_area": float,
                "motion": float,
                "is_primary": bool
            }
        Returns:
            id -> narrative saliency score (0..1)
        """
        # Decay existing memory
        for k in list(self._memory.keys()):
            self._memory[k] *= self._decay
            if self._memory[k] < 1e-3:
                del self._memory[k]
        # Integrate current detections
        for obj_id, info in detections.items():
            conf = _clamp(info.get("confidence", 0.0))
            area = _clamp(info.get("screen_area", 0.0))
            motion = _clamp(info.get("motion", 0.0))
            primary = bool(info.get("is_primary", False))
            # Base narrative contribution
            base = (
                0.45 * conf +
                0.35 * area +
                0.20 * motion
            )
            # Story emphasis
            if primary:
                base *= 1.25
            # Re-entry boost
            if obj_id in self._memory:
                base *= self._boost
            self._memory[obj_id] = _clamp(
                self._memory.get(obj_id, 0.0) + base
            )
        # Normalize saliency
        total = sum(self._memory.values())
        if total > 1e-6:
            return {k: v / total for k, v in self._memory.items()}
        return {}
    def reset(self) -> None:
        """
        Clears narrative memory (hard cut or chapter change).
        """
        self._memory.clear()
# ==============================================================================
# END OF CHUNK 86 I 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 I 02 — SUBJECT IMPORTANCE SCORING
# ==============================================================================
#
# Purpose:
#   Computes a stable, scene-aware importance score per subject that feeds
#   framing, exposure bias, focus priority, and motion planning.
#
# Cinematic principle:
#   Importance ≠ saliency. Importance blends story role, persistence, and intent.
#
# Inputs:
#   - Narrative saliency (temporal memory)
#   - Spatial prominence (area, position)
#   - Behavioral cues (motion intent, stability)
#   - Semantic role hints (primary/secondary)
#
# Outputs:
#   - Per-subject importance score (0..1), normalized
#
# ==============================================================================

from typing import Dict, Any, Tuple


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


def _center_bias(pos: Tuple[float, float]) -> float:
    """
    Computes a soft center-weighting (rule-of-thirds tolerant).
    pos: normalized (x, y) in [0..1]
    """
    x, y = pos
    cx = 1.0 - abs(x - 0.5) * 2.0
    cy = 1.0 - abs(y - 0.5) * 2.0
    return _clamp(0.6 * cx + 0.4 * cy)


class SubjectImportanceScorer:
    """
    Blends narrative memory with physical and semantic cues to
    compute stable subject importance.
    """
    __slots__ = (
        "_w_narrative",
        "_w_spatial",
        "_w_motion",
        "_w_semantic",
    )
    def __init__(
        self,
        w_narrative: float = 0.40,
        w_spatial: float = 0.25,
        w_motion: float = 0.20,
        w_semantic: float = 0.15,
    ):
        total = w_narrative + w_spatial + w_motion + w_semantic
        self._w_narrative = w_narrative / total
        self._w_spatial = w_spatial / total
        self._w_motion = w_motion / total
        self._w_semantic = w_semantic / total
    def score(
        self,
        subjects: Dict[str, Dict[str, Any]],
        narrative_saliency: Dict[str, float],
    ) -> Dict[str, float]:
        """
        subjects:
            id -> {
                "screen_area": float,
                "position": (x, y),
                "motion": float,
                "stability": float,
                "role": "primary" | "secondary" | "background"
            }
        narrative_saliency:
            id -> temporal saliency (0..1)
        Returns:
            id -> importance score (0..1), normalized
        """
        raw: Dict[str, float] = {}
        for sid, info in subjects.items():
            # Narrative contribution
            narr = _clamp(narrative_saliency.get(sid, 0.0))
            # Spatial prominence
            area = _clamp(info.get("screen_area", 0.0))
            pos = info.get("position", (0.5, 0.5))
            spatial = _clamp(0.6 * area + 0.4 * _center_bias(pos))
            # Motion intent (favor purposeful motion over jitter)
            motion = _clamp(info.get("motion", 0.0))
            stability = _clamp(info.get("stability", 0.5))
            motion_term = _clamp(motion * stability)
            # Semantic role
            role = info.get("role", "background")
            if role == "primary":
                semantic = 1.0
            elif role == "secondary":
                semantic = 0.6
            else:
                semantic = 0.3
            score = (
                self._w_narrative * narr +
                self._w_spatial * spatial +
                self._w_motion * motion_term +
                self._w_semantic * semantic
            )
            raw[sid] = _clamp(score)
        # Normalize to sum=1
        total = sum(raw.values())
        if total > 1e-6:
            return {k: v / total for k, v in raw.items()}
        return {}
# ==============================================================================
# END OF CHUNK 86 I 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 I 03 — GAZE ATTRACTION ESTIMATOR
# ==============================================================================
#
# Purpose:
#   Estimates where human attention will naturally gravitate in the frame,
#   combining subject orientation, motion vectors, contrast, and implied gaze.
#
# Cinematic principle:
#   Viewers follow eyes, faces, leading motion, and contrast before anything else.
#
# This module:
#   - Predicts attention pull per subject
#   - Penalizes erratic micro-motion
#   - Boosts intentional gaze & leading vectors
#
# ==============================================================================

from typing import Dict, Any, Tuple


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


def _vec_magnitude(v: Tuple[float, float]) -> float:
    return (v[0] * v[0] + v[1] * v[1]) ** 0.5


def _dot(a: Tuple[float, float], b: Tuple[float, float]) -> float:
    return a[0] * b[0] + a[1] * b[1]


class GazeAttractionEstimator:
    """
    Estimates perceptual attention pull for each subject in frame.
    """
    __slots__ = (
        "_w_face",
        "_w_motion",
        "_w_contrast",
        "_w_gaze",
    )
    def __init__(
        self,
        w_face: float = 0.35,
        w_motion: float = 0.25,
        w_contrast: float = 0.20,
        w_gaze: float = 0.20,
    ):
        total = w_face + w_motion + w_contrast + w_gaze
        self._w_face = w_face / total
        self._w_motion = w_motion / total
        self._w_contrast = w_contrast / total
        self._w_gaze = w_gaze / total
    def estimate(
        self,
        subjects: Dict[str, Dict[str, Any]],
    ) -> Dict[str, float]:
        """
        subjects:
            id -> {
                "has_face": bool,
                "motion_vec": (dx, dy),
                "motion_stability": float,
                "contrast": float,
                "gaze_vec": (gx, gy) | None
            }
        Returns:
            id -> gaze attraction score (0..1), normalized
        """
        raw: Dict[str, float] = {}
        for sid, info in subjects.items():
            # Face presence dominates gaze
            face_term = 1.0 if info.get("has_face", False) else 0.0
            # Motion attraction (directional, not jitter)
            mv = info.get("motion_vec", (0.0, 0.0))
            motion_mag = _clamp(_vec_magnitude(mv))
            stability = _clamp(info.get("motion_stability", 0.5))
            motion_term = motion_mag * stability
            # Contrast pull
            contrast = _clamp(info.get("contrast", 0.0))
            # Gaze direction alignment
            gaze_vec = info.get("gaze_vec")
            if gaze_vec is not None and motion_mag > 1e-4:
                align = _dot(mv, gaze_vec)
                gaze_term = _clamp((align + 1.0) * 0.5)
            else:
                gaze_term = 0.0
            score = (
                self._w_face * face_term +
                self._w_motion * motion_term +
                self._w_contrast * contrast +
                self._w_gaze * gaze_term
            )
            raw[sid] = _clamp(score)
        total = sum(raw.values())
        if total > 1e-6:
            return {k: v / total for k, v in raw.items()}
        return {}
# ==============================================================================
# END OF CHUNK 86 I 03
# ==============================================================================
# ==============================================================================
# CHUNK 86 I 04 — VISUAL WEIGHT BALANCER
# ==============================================================================
#
# Purpose:
#   Balances perceived visual weight across the frame so that dominant subjects
#   feel intentional, grounded, and cinematic rather than accidentally heavy.
#
# Cinematic principle:
#   Composition is not symmetry — it is perceptual equilibrium.
#
# This module:
#   - Computes visual mass per subject
#   - Accounts for position, scale, luminance, and motion
#   - Outputs normalized balancing coefficients
#
# ==============================================================================

from typing import Dict, Any, Tuple


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


def _edge_penalty(pos: Tuple[float, float]) -> float:
    """
    Penalizes edge-heavy placement unless intentionally weighted elsewhere.
    """
    x, y = pos
    dx = abs(x - 0.5) * 2.0
    dy = abs(y - 0.5) * 2.0
    return _clamp(1.0 - 0.6 * (dx + dy))


class VisualWeightBalancer:
    """
    Computes visual weight distribution and balancing factors.
    """
    __slots__ = (
        "_w_area",
        "_w_luma",
        "_w_motion",
        "_w_position",
    )
    def __init__(
        self,
        w_area: float = 0.40,
        w_luma: float = 0.25,
        w_motion: float = 0.20,
        w_position: float = 0.15,
    ):
        total = w_area + w_luma + w_motion + w_position
        self._w_area = w_area / total
        self._w_luma = w_luma / total
        self._w_motion = w_motion / total
        self._w_position = w_position / total
    def balance(
        self,
        subjects: Dict[str, Dict[str, Any]],
    ) -> Dict[str, float]:
        """
        subjects:
            id -> {
                "screen_area": float,
                "luminance": float,
                "motion": float,
                "position": (x, y)
            }
        Returns:
            id -> visual weight coefficient (0..1), normalized
        """
        raw: Dict[str, float] = {}
        for sid, info in subjects.items():
            area = _clamp(info.get("screen_area", 0.0))
            luma = _clamp(info.get("luminance", 0.5))
            motion = _clamp(info.get("motion", 0.0))
            pos = info.get("position", (0.5, 0.5))
            position_term = _edge_penalty(pos)
            weight = (
                self._w_area * area +
                self._w_luma * luma +
                self._w_motion * motion +
                self._w_position * position_term
            )
            raw[sid] = _clamp(weight)
        total = sum(raw.values())
        if total > 1e-6:
            return {k: v / total for k, v in raw.items()}
        return {}
# ==============================================================================
# END OF CHUNK 86 I 04
# ==============================================================================
# ==============================================================================
# CHUNK 86 I 05 — ATTENTION CONTINUITY FILTER
# ==============================================================================
#
# Purpose:
#   Enforces temporal smoothness of viewer attention across frames so that
#   gaze transitions feel intentional, cinematic, and emotionally guided.
#
# Cinematic principle:
#   Cuts and motion should *redirect* attention, not reset it.
#
# This module:
#   - Dampens abrupt saliency jumps
#   - Preserves dominant subject focus across short occlusions
#   - Smooths multi-subject attention redistribution
#
# ==============================================================================

from typing import Dict


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class AttentionContinuityFilter:
    """
    Temporal filter for attention weights to ensure cinematic continuity.
    """
    __slots__ = (
        "_memory",
        "_alpha_rise",
        "_alpha_fall",
        "_min_hold",
    )
    def __init__(
        self,
        alpha_rise: float = 0.35,
        alpha_fall: float = 0.15,
        min_hold: float = 0.08,
    ):
        """
        alpha_rise:
            Responsiveness when attention increases.
        alpha_fall:
            Slower decay when attention decreases (prevents popping).
        min_hold:
            Minimum retained attention for recently dominant subjects.
        """
        self._alpha_rise = _clamp(alpha_rise, 0.1, 0.6)
        self._alpha_fall = _clamp(alpha_fall, 0.05, 0.4)
        self._min_hold = _clamp(min_hold, 0.02, 0.2)
        self._memory: Dict[str, float] = {}
    def apply(
        self,
        current_attention: Dict[str, float],
    ) -> Dict[str, float]:
        """
        current_attention:
            id -> instantaneous attention weight (0..1, normalized)
        Returns:
            id -> temporally filtered attention (0..1, normalized)
        """
        output: Dict[str, float] = {}
        # Update or decay memory
        for sid, cur in current_attention.items():
            prev = self._memory.get(sid, 0.0)
            if cur > prev:
                alpha = self._alpha_rise
            else:
                alpha = self._alpha_fall
            filtered = prev + alpha * (cur - prev)
            output[sid] = _clamp(filtered)
        # Retain recently important subjects briefly
        for sid, prev in self._memory.items():
            if sid not in output and prev > self._min_hold:
                output[sid] = _clamp(prev * (1.0 - self._alpha_fall))
        # Normalize
        total = sum(output.values())
        if total > 1e-6:
            for sid in output:
                output[sid] /= total
        self._memory = output.copy()
        return output
    def reset(self) -> None:
        """
        Clears continuity state (hard cut, montage reset).
        """
        self._memory.clear()
# ==============================================================================
# END OF CHUNK 86 I 05
# ==============================================================================
# ==============================================================================
# CHUNK 86 J 01 — INTENT-AWARE FRAMING RESOLVER
# ==============================================================================
#
# Purpose:
#   Converts high-level cinematic intent (story, emotion, subject priority)
#   into concrete framing targets that downstream crop, pan, and motion
#   solvers can act upon consistently.
#
# Cinematic principle:
#   Framing is an expression of intent, not geometry.
#
# This module:
#   - Resolves competing subject priorities
#   - Applies narrative and attention weights
#   - Outputs a dominant framing anchor + secondary constraints
#
# ==============================================================================

from typing import Dict, Any, Tuple, Optional


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class IntentAwareFramingResolver:
    """
    Resolves cinematic intent into actionable framing targets.
    """
    __slots__ = (
        "_intent_bias",
        "_min_secondary_weight",
    )
    def __init__(
        self,
        intent_bias: float = 0.65,
        min_secondary_weight: float = 0.15,
    ):
        """
        intent_bias:
            Weight given to explicit cinematic intent vs emergent attention.
        min_secondary_weight:
            Ensures secondary subjects remain contextually present.
        """
        self._intent_bias = _clamp(intent_bias, 0.4, 0.8)
        self._min_secondary_weight = _clamp(min_secondary_weight, 0.05, 0.3)
    def resolve(
        self,
        importance: Dict[str, float],
        attention: Dict[str, float],
        intent: Dict[str, Any],
        subjects: Dict[str, Dict[str, Any]],
    ) -> Dict[str, Any]:
        """
        importance:
            id -> subject importance score
        attention:
            id -> attention weight
        intent:
            {
                "mode": "follow" | "observe" | "reveal" | "establish",
                "preferred_subject": id | None,
                "energy": 0..1
            }
        subjects:
            id -> {
                "position": (x, y),
                "screen_area": float
            }
        Returns:
            {
                "primary_id": str | None,
                "primary_anchor": (x, y),
                "secondary": {id: weight},
                "energy": float
            }
        """
        combined: Dict[str, float] = {}
        # Blend importance and attention
        for sid in subjects.keys():
            imp = importance.get(sid, 0.0)
            att = attention.get(sid, 0.0)
            combined[sid] = _clamp(
                self._intent_bias * imp +
                (1.0 - self._intent_bias) * att
            )
        # Override with explicit intent if provided
        preferred = intent.get("preferred_subject")
        if preferred in combined:
            combined[preferred] = max(combined.values()) * 1.15
        # Determine primary subject
        if combined:
            primary_id = max(combined, key=combined.get)
        else:
            primary_id = None
        # Primary anchor
        if primary_id is not None:
            primary_anchor: Optional[Tuple[float, float]] = subjects[
                primary_id
            ].get("position", (0.5, 0.5))
        else:
            primary_anchor = None
        # Secondary context weights
        secondary: Dict[str, float] = {}
        total_secondary = 0.0
        for sid, score in combined.items():
            if sid == primary_id:
                continue
            w = max(score, self._min_secondary_weight)
            secondary[sid] = w
            total_secondary += w
        # Normalize secondary weights
        if total_secondary > 1e-6:
            for sid in secondary:
                secondary[sid] /= total_secondary
        return {
            "primary_id": primary_id,
            "primary_anchor": primary_anchor,
            "secondary": secondary,
            "energy": _clamp(intent.get("energy", 0.5)),
        }
# ==============================================================================
# END OF CHUNK 86 J 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 J 02 — FRAMING CONSTRAINT HARMONIZER
# ==============================================================================
#
# Purpose:
#   Resolves conflicts between multiple framing constraints so that the final
#   composition is stable, intentional, and cinematographically valid.
#
# Cinematic principle:
#   Good framing satisfies many constraints quietly rather than one perfectly.
#
# This module:
#   - Blends hard and soft constraints
#   - Prevents constraint oscillation
#   - Outputs a single, coherent framing target
#
# ==============================================================================

from typing import Dict, Any, Tuple


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


def _lerp(a: float, b: float, t: float) -> float:
    return a + (b - a) * t


def _lerp2(
    a: Tuple[float, float],
    b: Tuple[float, float],
    t: float,
) -> Tuple[float, float]:
    return (
        _lerp(a[0], b[0], t),
        _lerp(a[1], b[1], t),
    )


class FramingConstraintHarmonizer:
    """
    Harmonizes multiple framing constraints into a single target anchor.
    """
    __slots__ = (
        "_hard_weight",
        "_soft_weight",
        "_temporal_smooth",
        "_prev_anchor",
    )
    def __init__(
        self,
        hard_weight: float = 0.65,
        soft_weight: float = 0.35,
        temporal_smooth: float = 0.25,
    ):
        """
        hard_weight:
            Priority given to non-negotiable constraints (safety, subject retention).
        soft_weight:
            Priority given to aesthetic constraints (rule-of-thirds, balance).
        temporal_smooth:
            Dampening factor to prevent jitter between frames.
        """
        self._hard_weight = _clamp(hard_weight, 0.4, 0.8)
        self._soft_weight = _clamp(soft_weight, 0.2, 0.6)
        self._temporal_smooth = _clamp(temporal_smooth, 0.05, 0.5)
        self._prev_anchor: Tuple[float, float] = (0.5, 0.5)
    def resolve(
        self,
        hard_constraints: Dict[str, Tuple[float, float]],
        soft_constraints: Dict[str, Tuple[float, float]],
    ) -> Tuple[float, float]:
        """
        hard_constraints:
            name -> (x, y) anchor candidates (must be respected)
        soft_constraints:
            name -> (x, y) anchor candidates (aesthetic preferences)
        Returns:
            Final framing anchor (x, y)
        """
        # Average hard constraints
        if hard_constraints:
            hx = sum(p[0] for p in hard_constraints.values()) / len(hard_constraints)
            hy = sum(p[1] for p in hard_constraints.values()) / len(hard_constraints)
            hard_anchor = (_clamp(hx), _clamp(hy))
        else:
            hard_anchor = self._prev_anchor
        # Average soft constraints
        if soft_constraints:
            sx = sum(p[0] for p in soft_constraints.values()) / len(soft_constraints)
            sy = sum(p[1] for p in soft_constraints.values()) / len(soft_constraints)
            soft_anchor = (_clamp(sx), _clamp(sy))
        else:
            soft_anchor = hard_anchor
        # Blend hard and soft
        blended = _lerp2(
            hard_anchor,
            soft_anchor,
            self._soft_weight,
        )
        # Temporal smoothing
        final_anchor = _lerp2(
            self._prev_anchor,
            blended,
            self._temporal_smooth,
        )
        self._prev_anchor = final_anchor
        return final_anchor
# ==============================================================================
# END OF CHUNK 86 J 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 J 03 — RULE-OF-THIRDS DEFORMATION ENGINE
# ==============================================================================
#
# Purpose:
#   Applies an adaptive, intent-aware deformation of the classic rule-of-thirds
#   grid so that framing feels cinematic even under dynamic motion, lenses,
#   and non-ideal subject layouts.
#
# Cinematic principle:
#   The rule-of-thirds is a guideline, not a cage.
#
# This module:
#   - Warps thirds lines based on intent, energy, and subject distribution
#   - Preserves horizon and headroom priority
#   - Outputs soft target anchors (not hard snaps)
#
# ==============================================================================

from typing import Dict, Any, Tuple


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


def _lerp(a: float, b: float, t: float) -> float:
    return a + (b - a) * t


def _lerp2(
    a: Tuple[float, float],
    b: Tuple[float, float],
    t: float,
) -> Tuple[float, float]:
    return (
        _lerp(a[0], b[0], t),
        _lerp(a[1], b[1], t),
    )


class RuleOfThirdsDeformationEngine:
    """
    Generates adaptive thirds anchors influenced by cinematic intent.
    """
    __slots__ = (
        "_max_shift",
        "_energy_sensitivity",
        "_prev_anchor",
    )
    def __init__(
        self,
        max_shift: float = 0.12,
        energy_sensitivity: float = 0.6,
    ):
        """
        max_shift:
            Maximum deviation from canonical thirds lines.
        energy_sensitivity:
            How strongly cinematic energy deforms composition.
        """
        self._max_shift = _clamp(max_shift, 0.05, 0.25)
        self._energy_sensitivity = _clamp(energy_sensitivity, 0.2, 1.0)
        self._prev_anchor: Tuple[float, float] = (1 / 3, 1 / 3)
    def compute(
        self,
        primary_anchor: Tuple[float, float],
        energy: float,
        subject_distribution: Dict[str, Dict[str, Any]],
    ) -> Tuple[float, float]:
        """
        primary_anchor:
            Base anchor from intent resolver (x, y)
        energy:
            Cinematic energy (0..1)
        subject_distribution:
            id -> {
                "position": (x, y),
                "weight": float
            }
        Returns:
            Deformed thirds anchor (x, y)
        """
        # Canonical thirds nearest to primary anchor
        thirds_x = 1 / 3 if primary_anchor[0] < 0.5 else 2 / 3
        thirds_y = 1 / 3 if primary_anchor[1] < 0.5 else 2 / 3
        base_anchor = (thirds_x, thirds_y)
        # Distribution bias (center of visual mass)
        if subject_distribution:
            wx = 0.0
            wy = 0.0
            wt = 0.0
            for info in subject_distribution.values():
                w = info.get("weight", 0.0)
                pos = info.get("position", (0.5, 0.5))
                wx += pos[0] * w
                wy += pos[1] * w
                wt += w
            if wt > 1e-6:
                dist_center = (_clamp(wx / wt), _clamp(wy / wt))
            else:
                dist_center = base_anchor
        else:
            dist_center = base_anchor
        # Energy-driven deformation
        energy_shift = _clamp(energy * self._energy_sensitivity)
        target = _lerp2(
            base_anchor,
            dist_center,
            energy_shift,
        )
        # Clamp deformation radius
        dx = _clamp(target[0] - base_anchor[0], -self._max_shift, self._max_shift)
        dy = _clamp(target[1] - base_anchor[1], -self._max_shift, self._max_shift)
        deformed = (
            _clamp(base_anchor[0] + dx),
            _clamp(base_anchor[1] + dy),
        )
        # Temporal smoothing
        final_anchor = _lerp2(
            self._prev_anchor,
            deformed,
            0.35,
        )
        self._prev_anchor = final_anchor
        return final_anchor
# ==============================================================================
# END OF CHUNK 86 J 03
