# ==============================================================================
# CHUNK 86 J 04 — DYNAMIC HORIZON STABILIZER
# ==============================================================================
#
# Purpose:
#   Maintains a visually stable horizon while allowing intentional roll,
#   banking, and energy-driven tilt without inducing viewer discomfort.
#
# Cinematic principle:
#   The audience forgives motion — but not an unintentionally crooked world.
#
# This module:
#   - Estimates perceived horizon tilt
#   - Filters micro-roll jitter
#   - Allows intent-driven horizon bias (action, reveal, chaos)
#
# ==============================================================================

from typing import Dict, Any


def _clamp(x: float, lo: float = -1.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class DynamicHorizonStabilizer:
    """
    Stabilizes horizon orientation while preserving cinematic intent.
    """
    __slots__ = (
        "_alpha",
        "_max_correction",
        "_prev_angle",
    )
    def __init__(
        self,
        smoothing: float = 0.12,
        max_correction_deg: float = 6.0,
    ):
        """
        smoothing:
            Temporal smoothing factor for horizon correction.
        max_correction_deg:
            Maximum automatic correction allowed (degrees).
        """
        self._alpha = max(0.02, min(0.4, smoothing))
        self._max_correction = abs(max_correction_deg)
        self._prev_angle = 0.0
    def stabilize(
        self,
        measured_roll_deg: float,
        intent: Dict[str, Any],
    ) -> float:
        """
        measured_roll_deg:
            Raw horizon roll angle from vision/IMU fusion.
        intent:
            {
                "energy": 0..1,
                "allow_tilt": bool,
                "tilt_bias": -1..1 (optional)
            }
        Returns:
            Corrected horizon roll angle (degrees)
        """
        energy = intent.get("energy", 0.5)
        allow_tilt = intent.get("allow_tilt", False)
        tilt_bias = _clamp(intent.get("tilt_bias", 0.0))
        # Base correction target
        if allow_tilt:
            target = measured_roll_deg * (1.0 - 0.6 * energy)
        else:
            target = 0.0
        # Apply artistic bias (e.g., Dutch angle)
        target += tilt_bias * self._max_correction
        # Clamp correction
        target = max(
            -self._max_correction,
            min(self._max_correction, target),
        )
        # Temporal smoothing
        corrected = self._prev_angle + self._alpha * (target - self._prev_angle)
        self._prev_angle = corrected
        return corrected
