# END OF CHUNK 86 J 04
# ==============================================================================
# ==============================================================================
# CHUNK 86 J 05 — SUBJECT-CENTRIC CROP SOLVER
# ==============================================================================
#
# Purpose:
#   Computes a dynamic crop window that prioritizes the primary subject while
#   preserving cinematic headroom, lead-room, and contextual breathing space.
#
# Cinematic principle:
#   Cropping is invisible when done right — it feels like the camera “chose” well.
#
# This module:
#   - Solves crop center & scale from subject geometry
#   - Preserves headroom for faces and bodies
#   - Biases lead-room in direction of motion or gaze
#
# ==============================================================================

from typing import Dict, Any, Tuple


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


def _lerp(a: float, b: float, t: float) -> float:
    return a + (b - a) * t


def _lerp2(
    a: Tuple[float, float],
    b: Tuple[float, float],
    t: float,
) -> Tuple[float, float]:
    return (
        _lerp(a[0], b[0], t),
        _lerp(a[1], b[1], t),
    )


class SubjectCentricCropSolver:
    """
    Computes a cinematic crop window centered on narrative subjects.
    """
    __slots__ = (
        "_min_scale",
        "_max_scale",
        "_headroom_ratio",
        "_leadroom_ratio",
        "_smooth",
        "_prev_center",
        "_prev_scale",
    )
    def __init__(
        self,
        min_scale: float = 0.65,
        max_scale: float = 1.00,
        headroom_ratio: float = 0.18,
        leadroom_ratio: float = 0.12,
        temporal_smooth: float = 0.25,
    ):
        """
        min_scale:
            Tightest allowed crop (zoom-in limit).
        max_scale:
            Widest allowed crop (zoom-out limit).
        headroom_ratio:
            Vertical space preserved above subject (faces/heads).
        leadroom_ratio:
            Horizontal space added in direction of motion/gaze.
        """
        self._min_scale = _clamp(min_scale, 0.4, 0.9)
        self._max_scale = _clamp(max_scale, self._min_scale, 1.0)
        self._headroom_ratio = _clamp(headroom_ratio, 0.05, 0.35)
        self._leadroom_ratio = _clamp(leadroom_ratio, 0.05, 0.3)
        self._smooth = _clamp(temporal_smooth, 0.05, 0.6)
        self._prev_center: Tuple[float, float] = (0.5, 0.5)
        self._prev_scale: float = 1.0
    def solve(
        self,
        subject: Dict[str, Any],
        intent: Dict[str, Any],
    ) -> Dict[str, float]:
        """
        subject:
            {
                "bbox": (x, y, w, h),     # normalized
                "position": (x, y),      # center
                "motion_vec": (dx, dy),  # normalized
                "has_face": bool
            }
        intent:
            {
                "energy": 0..1,
                "mode": str
            }
        Returns:
            {
                "center_x": float,
                "center_y": float,
                "scale": float
            }
        """
        bx, by, bw, bh = subject.get("bbox", (0.5, 0.5, 0.2, 0.2))
        cx, cy = subject.get("position", (0.5, 0.5))
        mvx, mvy = subject.get("motion_vec", (0.0, 0.0))
        has_face = subject.get("has_face", False)
        energy = intent.get("energy", 0.5)
        # Base scale from subject size
        subj_size = max(bw, bh)
        target_scale = _clamp(
            1.0 - subj_size * (0.8 + 0.4 * energy),
            self._min_scale,
            self._max_scale,
        )
        # Headroom adjustment
        headroom = self._headroom_ratio * (1.2 if has_face else 1.0)
        cy_adj = cy - bh * headroom
        # Lead-room adjustment
        cx_adj = cx + mvx * self._leadroom_ratio
        target_center = (
            _clamp(cx_adj),
            _clamp(cy_adj),
        )
        # Temporal smoothing
        smooth_center = _lerp2(
            self._prev_center,
            target_center,
            self._smooth,
        )
        smooth_scale = _lerp(
            self._prev_scale,
            target_scale,
            self._smooth,
        )
        self._prev_center = smooth_center
        self._prev_scale = smooth_scale
        return {
            "center_x": smooth_center[0],
            "center_y": smooth_center[1],
            "scale": smooth_scale,
        }
# ==============================================================================
# END OF CHUNK 86 J 05
# ==============================================================================
# ==============================================================================
# CHUNK 86 J 06 — CAMERA ENERGY TRANSLATION LAYER
# ==============================================================================
#
# Purpose:
#   Translates abstract cinematic “energy” into concrete camera behavior
#   modifiers (responsiveness, damping, overshoot, stiffness).
#
# Cinematic principle:
#   Energy defines *how alive* the camera feels — not how fast it moves.
#
# This module:
#   - Converts narrative energy into motion coefficients
#   - Prevents twitchy behavior at high energy
#   - Preserves weight and inertia at low energy
#
# ==============================================================================

from typing import Dict


def _clamp(x: float, lo: float = 0.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class CameraEnergyTranslator:
    """
    Converts cinematic energy into camera control coefficients.
    """
    __slots__ = (
        "_min_response",
        "_max_response",
        "_min_damping",
        "_max_damping",
        "_min_overshoot",
        "_max_overshoot",
    )
    def __init__(
        self,
        min_response: float = 0.15,
        max_response: float = 0.95,
        min_damping: float = 0.65,
        max_damping: float = 0.15,
        min_overshoot: float = 0.0,
        max_overshoot: float = 0.25,
    ):
        """
        response:
            How quickly camera reacts to changes.
        damping:
            How strongly motion is smoothed.
        overshoot:
            Allowed kinetic overshoot for dynamic shots.
        """
        self._min_response = min_response
        self._max_response = max_response
        self._min_damping = min_damping
        self._max_damping = max_damping
        self._min_overshoot = min_overshoot
        self._max_overshoot = max_overshoot
    def translate(self, energy: float) -> Dict[str, float]:
        """
        energy:
            Cinematic energy scalar (0..1).
        Returns:
            {
                "response": float,
                "damping": float,
                "overshoot": float
            }
        """
        e = _clamp(energy)
        # Non-linear response curve
        response = (
            self._min_response
            + (self._max_response - self._min_response) * (e ** 0.85)
        )
        # Inverse damping curve (high energy = less damping)
        damping = (
            self._max_damping
            + (self._min_damping - self._max_damping) * ((1.0 - e) ** 1.2)
        )
        # Overshoot allowed only at higher energies
        overshoot = (
            self._min_overshoot
            + (self._max_overshoot - self._min_overshoot) * (e ** 1.6)
        )
        return {
            "response": response,
            "damping": damping,
            "overshoot": overshoot,
        }
# ==============================================================================
# END OF CHUNK 86 J 06
# ==============================================================================
# ==============================================================================
# CHUNK 86 J 07 — MOTION-TO-FRAMING COUPLER
# ==============================================================================
#
# Purpose:
#   Couples physical motion vectors (translation, velocity, acceleration)
#   into framing decisions (crop shift, look-ahead, lead room).
#
# Cinematic principle:
#   The frame should anticipate motion, not react to it.
#
# This module:
#   - Predicts subject motion intent
#   - Allocates lead-room dynamically
#   - Prevents edge-crash and late framing
#
# ==============================================================================

from typing import Tuple, Dict


def _clamp(x: float, lo: float = -1.0, hi: float = 1.0) -> float:
    return max(lo, min(hi, float(x)))


class MotionToFramingCoupler:
    """
    Converts motion vectors into framing offsets.
    """
    __slots__ = (
        "_lookahead_gain",
        "_max_lead",
        "_prev_offset",
    )
    def __init__(
        self,
        lookahead_gain: float = 0.35,
        max_lead: float = 0.18,
    ):
        """
        lookahead_gain:
            Strength of motion anticipation.
        max_lead:
            Maximum normalized framing offset allowed.
        """
        self._lookahead_gain = lookahead_gain
        self._max_lead = abs(max_lead)
        self._prev_offset = (0.0, 0.0)
    def compute_offset(
        self,
        velocity_xy: Tuple[float, float],
        acceleration_xy: Tuple[float, float],
        intent: Dict[str, float],
    ) -> Tuple[float, float]:
        """
        velocity_xy:
            Normalized subject velocity (x, y).
        acceleration_xy:
            Normalized subject acceleration (x, y).
        intent:
            {
                "energy": 0..1,
                "anticipation": 0..1
            }
        Returns:
            (x_offset, y_offset) normalized to frame.
        """
        energy = intent.get("energy", 0.5)
        anticipation = intent.get("anticipation", 0.5)
        vx, vy = velocity_xy
        ax, ay = acceleration_xy
        # Predictive motion vector
        px = vx + 0.5 * ax
        py = vy + 0.5 * ay
        # Lead-room scaling
        lead_scale = self._lookahead_gain * (0.4 + 0.6 * anticipation)
        tx = _clamp(px * lead_scale * (0.6 + 0.8 * energy))
        ty = _clamp(py * lead_scale * (0.6 + 0.8 * energy))
        # Clamp to maximum allowed lead
        tx = _clamp(tx, -self._max_lead, self._max_lead)
        ty = _clamp(ty, -self._max_lead, self._max_lead)
        # Light temporal smoothing to avoid jitter
        ox, oy = self._prev_offset
        out_x = ox + 0.25 * (tx - ox)
        out_y = oy + 0.25 * (ty - oy)
        self._prev_offset = (out_x, out_y)
        return out_x, out_y
# ==============================================================================
# END OF CHUNK 86 J 07
# ==============================================================================
# ==============================================================================
# CHUNK 86 J 08 — LENS BREATHING COMPENSATION MODEL
# ==============================================================================
#
# Purpose:
#   Compensate apparent FOV changes caused by focus distance variation
#   (lens breathing) during autofocus and subject tracking.
#
# Cinematic principle:
#   Focus pulls must not feel like zooms.
#
# This module:
#   - Estimates breathing-induced scale shift
#   - Applies inverse crop/scale to stabilize framing
#   - Preserves composition during AF transitions
#
# ==============================================================================

from typing import Optional


def _lerp(a: float, b: float, t: float) -> float:
    return a + (b - a) * t


class LensBreathingCompensator:
    """
    Models and compensates lens breathing as a function of focus distance.
    """
    __slots__ = (
        "_breathing_strength",
        "_focus_min",
        "_focus_max",
        "_prev_scale",
    )
    def __init__(
        self,
        breathing_strength: float = 0.045,
        focus_min_m: float = 0.3,
        focus_max_m: float = 50.0,
    ):
        """
        breathing_strength:
            Typical cinema lenses range 2–6% across focus throw.
        focus_min_m / focus_max_m:
            Operational focus distance bounds in meters.
        """
        self._breathing_strength = max(0.0, breathing_strength)
        self._focus_min = max(0.01, focus_min_m)
        self._focus_max = max(self._focus_min + 0.01, focus_max_m)
        self._prev_scale = 1.0
    def estimate_scale(
        self,
        focus_distance_m: float,
        subject_priority: float = 0.5,
    ) -> float:
        """
        focus_distance_m:
            Current lens focus distance.
        subject_priority:
            0..1 — higher values damp compensation to preserve subject size.
        Returns:
            Multiplicative scale factor to counter breathing.
        """
        d = max(self._focus_min, min(self._focus_max, focus_distance_m))
        # Normalize focus travel (near = 1, far = 0)
        t = 1.0 - (d - self._focus_min) / (self._focus_max - self._focus_min)
        # Raw breathing curve (slightly eased for cinema feel)
        breathing = self._breathing_strength * (t ** 1.15)
        # Reduce compensation when subject importance is high
        damp = _lerp(1.0, 0.65, max(0.0, min(1.0, subject_priority)))
        target_scale = 1.0 / (1.0 + breathing * damp)
        # Temporal smoothing to avoid micro-pumping
        out_scale = self._prev_scale + 0.2 * (target_scale - self._prev_scale)
        self._prev_scale = out_scale
        return out_scale
# ==============================================================================
# END OF CHUNK 86 J 08
# ==============================================================================
# ==============================================================================
# CHUNK 86 J 09 — CINEMATIC DEAD-ZONE MANAGER
# ==============================================================================
#
# Purpose:
#   Introduce perceptual dead-zones in framing and motion response
#   so the camera does not react to insignificant subject drift.
#
# Cinematic principle:
#   Human-operated cameras ignore micro-motion until it matters.
#
# This module:
#   - Defines adaptive dead-zones based on shot energy
#   - Prevents nervous micro-corrections
#   - Allows decisive motion when thresholds are crossed
#
# ==============================================================================

from typing import Tuple


def _abs(x: float) -> float:
    return x if x >= 0.0 else -x


class CinematicDeadZoneManager:
    """
    Suppresses insignificant motion to maintain visual calm.
    """
    __slots__ = (
        "_base_dead_zone",
        "_energy_scale",
    )
    def __init__(
        self,
        base_dead_zone: float = 0.015,
        energy_scale: float = 0.6,
    ):
        """
        base_dead_zone:
            Minimum normalized movement ignored by framing logic.
        energy_scale:
            Higher values reduce dead-zone during high-energy shots.
        """
        self._base_dead_zone = max(0.0, base_dead_zone)
        self._energy_scale = max(0.0, energy_scale)
    def apply(
        self,
        offset_xy: Tuple[float, float],
        shot_energy: float,
    ) -> Tuple[float, float]:
        """
        offset_xy:
            Proposed framing offset (x, y).
        shot_energy:
            0..1 — perceived intensity of the shot.
        Returns:
            Filtered offset with dead-zone applied.
        """
        ox, oy = offset_xy
        # Adaptive dead-zone shrinks as energy increases
        dz = self._base_dead_zone * (1.0 - self._energy_scale * shot_energy)
        dz = max(0.002, dz)
        fx = 0.0 if _abs(ox) < dz else ox
        fy = 0.0 if _abs(oy) < dz else oy
        return fx, fy
# ==============================================================================
# END OF CHUNK 86 J 09
# ==============================================================================
# ==============================================================================
# CHUNK 86 J 10 — EDGE TENSION SUPPRESSION ENGINE
# ==============================================================================
#
# Purpose:
#   Prevent subjects from drifting too close to frame edges by applying
#   nonlinear repulsive forces that preserve cinematic balance.
#
# Cinematic principle:
#   Subjects should feel comfortably framed, never cramped or clipped.
#
# This module:
#   - Detects proximity to frame boundaries
#   - Applies smooth inward bias (no hard snapping)
#   - Preserves intentional edge-framing when required
#
# ==============================================================================

from typing import Tuple


def _sign(x: float) -> float:
    if x > 0.0:
        return 1.0
    if x < 0.0:
        return -1.0
    return 0.0


class EdgeTensionSuppressor:
    """
    Applies soft repulsion when framing approaches unsafe edge zones.
    """
    __slots__ = (
        "_safe_margin",
        "_tension_strength",
    )
    def __init__(
        self,
        safe_margin: float = 0.38,
        tension_strength: float = 0.55,
    ):
        """
        safe_margin:
            Normalized half-frame distance beyond which tension increases.
        tension_strength:
            Controls how aggressively the subject is pushed inward.
        """
        self._safe_margin = max(0.2, min(0.49, safe_margin))
        self._tension_strength = max(0.0, tension_strength)
    def apply(
        self,
        offset_xy: Tuple[float, float],
        intentional_edge: float = 0.0,
    ) -> Tuple[float, float]:
        """
        offset_xy:
            Current framing offset (x, y), normalized.
        intentional_edge:
            0..1 — allows edge framing when artistically desired.
        Returns:
            Adjusted framing offset.
        """
        ox, oy = offset_xy
        fx, fy = ox, oy
        # Horizontal edge tension
        ax = abs(ox)
        if ax > self._safe_margin:
            excess = (ax - self._safe_margin) / (0.5 - self._safe_margin)
            force = excess ** 1.35
            damp = 1.0 - max(0.0, min(1.0, intentional_edge))
            fx -= _sign(ox) * force * self._tension_strength * damp
        # Vertical edge tension
        ay = abs(oy)
        if ay > self._safe_margin:
            excess = (ay - self._safe_margin) / (0.5 - self._safe_margin)
            force = excess ** 1.35
            damp = 1.0 - max(0.0, min(1.0, intentional_edge))
            fy -= _sign(oy) * force * self._tension_strength * damp
        return fx, fy
# ==============================================================================
# END OF CHUNK 86 J 10
# ==============================================================================
# ==============================================================================
# CHUNK 86 K 01 — MULTI-SUBJECT PRIORITY RESOLVER
# ==============================================================================
#
# Purpose:
#   Resolve which subject should dominate framing, focus, and exposure
#   when multiple candidates are present.
#
# Cinematic principle:
#   The camera must always “know” who the scene is about.
#
# This module:
#   - Scores subjects using cinematic relevance
#   - Enforces temporal stability (no rapid subject hopping)
#   - Supports director intent overrides
#
# ==============================================================================

from typing import List, Dict, Optional


class MultiSubjectPriorityResolver:
    """
    Determines the dominant subject in multi-actor scenes.
    """
    __slots__ = (
        "_stickiness",
        "_prev_id",
    )
    def __init__(self, stickiness: float = 0.75):
        """
        stickiness:
            Resistance to switching subjects unless confidence is high.
        """
        self._stickiness = max(0.0, min(1.0, stickiness))
        self._prev_id: Optional[str] = None
    def resolve(
        self,
        subjects: List[Dict],
        director_bias: Optional[str] = None,
    ) -> Optional[Dict]:
        """
        subjects:
            [
              {
                "id": str,
                "score": float,   # base cinematic relevance
                "size": float,    # relative frame occupancy
                "motion": float,  # perceived energy
                "salience": float # semantic importance
              }
            ]
        director_bias:
            Optional subject id explicitly requested by AI director.
        Returns:
            Selected subject dict or None.
        """
        if not subjects:
            self._prev_id = None
            return None
        # Director intent has absolute priority
        if director_bias:
            for s in subjects:
                if s.get("id") == director_bias:
                    self._prev_id = s.get("id")
                    return s
        # Compute composite score
        best = None
        best_score = -1e9
        for s in subjects:
            score = (
                0.40 * s.get("score", 0.0) +
                0.25 * s.get("salience", 0.0) +
                0.20 * s.get("size", 0.0) +
                0.15 * s.get("motion", 0.0)
            )
            # Apply stickiness to previous subject
            if s.get("id") == self._prev_id:
                score *= (1.0 + self._stickiness)
            if score > best_score:
                best_score = score
                best = s
        self._prev_id = best.get("id") if best else None
        return best
# ==============================================================================
# END OF CHUNK 86 K 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 K 02 — SUBJECT DOMINANCE SCORING MODEL
# ==============================================================================
#
# Purpose:
#   Produce a stable, film-aware dominance score for each detected subject
#   that reflects how strongly the camera + drone AI should favor it.
#
# Cinematic principle:
#   Dominance is not just size or motion — it is narrative gravity.
#
# This module:
#   - Combines visual, semantic, and temporal factors
#   - Dampens noisy fluctuations
#   - Outputs a normalized dominance score (0..1)
#
# ==============================================================================

from typing import Dict


def _clamp01(x: float) -> float:
    if x < 0.0:
        return 0.0
    if x > 1.0:
        return 1.0
    return x


class SubjectDominanceScorer:
    """
    Computes cinematic dominance for a subject candidate.
    """
    __slots__ = (
        "_temporal_inertia",
        "_prev_scores",
    )
    def __init__(self, temporal_inertia: float = 0.65):
        """
        temporal_inertia:
            Higher values stabilize dominance over time (less flicker).
        """
        self._temporal_inertia = _clamp01(temporal_inertia)
        self._prev_scores: Dict[str, float] = {}
    def score(
        self,
        subject: Dict,
        scene_context: Dict,
    ) -> float:
        """
        subject:
            {
              "id": str,
              "size": float,        # frame occupancy (0..1)
              "motion": float,      # normalized motion energy
              "focus": float,       # focus confidence
              "salience": float,    # semantic importance
              "centered": float     # proximity to frame center
            }
        scene_context:
            {
              "shot_energy": float,
              "director_intent": float,
              "crowd_level": float
            }
        Returns:
            dominance score in range 0..1
        """
        sid = subject.get("id", "")
        # Base perceptual dominance
        base = (
            0.30 * subject.get("salience", 0.0) +
            0.20 * subject.get("size", 0.0) +
            0.15 * subject.get("motion", 0.0) +
            0.20 * subject.get("focus", 0.0) +
            0.15 * subject.get("centered", 0.0)
        )
        # Scene-aware modulation
        energy = scene_context.get("shot_energy", 0.5)
        intent = scene_context.get("director_intent", 0.5)
        crowd = scene_context.get("crowd_level", 0.0)
        # In crowded scenes, emphasize salience over size
        crowd_bias = 1.0 - 0.35 * crowd
        raw_score = base * (0.7 + 0.3 * intent) * crowd_bias
        raw_score *= (0.8 + 0.2 * energy)
        raw_score = _clamp01(raw_score)
        # Temporal stabilization
        prev = self._prev_scores.get(sid, raw_score)
        out = (
            self._temporal_inertia * prev +
            (1.0 - self._temporal_inertia) * raw_score
        )
        self._prev_scores[sid] = out
        return out
# ==============================================================================
# END OF CHUNK 86 K 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 K 03 — INTENT PERSISTENCE FILTER
# ==============================================================================
#
# Purpose:
#   Maintain stable, long-horizon user and director intent across frames
#   so cinematic behavior does not reset or jitter over time.
#
# Cinematic principle:
#   A shot has memory. Intent should decay, not disappear.
#
# This module:
#   - Persists semantic + cinematic intent
#   - Applies controlled decay over time
#   - Resolves conflicts between new vs ongoing intent
#
# ==============================================================================

from typing import Dict, Optional


def _clamp01(x: float) -> float:
    if x < 0.0:
        return 0.0
    if x > 1.0:
        return 1.0
    return x


class IntentPersistenceFilter:
    """
    Stabilizes high-level cinematic intent over time.
    """
    __slots__ = (
        "_decay_rate",
        "_reinforce_gain",
        "_intent_state",
    )
    def __init__(
        self,
        decay_rate: float = 0.02,
        reinforce_gain: float = 0.6,
    ):
        """
        decay_rate:
            Per-frame decay of intent strength.
        reinforce_gain:
            How strongly new matching intent reinforces existing state.
        """
        self._decay_rate = max(0.0, decay_rate)
        self._reinforce_gain = _clamp01(reinforce_gain)
        self._intent_state: Dict[str, float] = {}
    def update(
        self,
        new_intent: Optional[Dict[str, float]],
    ) -> Dict[str, float]:
        """
        new_intent:
            {
              "follow_subject": 0..1,
              "cinematic_energy": 0..1,
              "aggression": 0..1,
              "stability": 0..1,
              "emotion": 0..1
            }
        Returns:
            Persisted intent state.
        """
        # Decay existing intent smoothly
        for k in list(self._intent_state.keys()):
            v = self._intent_state[k] - self._decay_rate
            if v <= 0.0:
                del self._intent_state[k]
            else:
                self._intent_state[k] = v
        if not new_intent:
            return dict(self._intent_state)
        # Reinforce or inject new intent
        for k, v in new_intent.items():
            v = _clamp01(v)
            if k in self._intent_state:
                self._intent_state[k] = _clamp01(
                    self._intent_state[k] +
                    self._reinforce_gain * v
                )
            else:
                self._intent_state[k] = v
        return dict(self._intent_state)
# ==============================================================================
# END OF CHUNK 86 K 03
# ==============================================================================
# ==============================================================================
# CHUNK 86 K 04 — OCCLUSION-AWARE SUBJECT ARBITRATION
# ==============================================================================
#
# Purpose:
#   Preserve correct subject ownership and cinematic intent when the
#   dominant subject is partially or temporarily occluded.
#
# Cinematic principle:
#   A camera does not abandon its subject just because something passes
#   in front of them.
#
# This module:
#   - Detects occlusion likelihood
#   - Maintains subject lock through short occlusions
#   - Smoothly transitions only when occlusion is persistent
#
# ==============================================================================

from typing import Dict, Optional


def _clamp01(x: float) -> float:
    if x < 0.0:
        return 0.0
    if x > 1.0:
        return 1.0
    return x


class OcclusionAwareArbitrator:
    """
    Handles subject arbitration under partial or full occlusion.
    """
    __slots__ = (
        "_occlusion_memory",
        "_max_hold_frames",
        "_hold_counter",
        "_active_subject_id",
    )
    def __init__(
        self,
        max_hold_frames: int = 18,
        occlusion_memory: float = 0.75,
    ):
        """
        max_hold_frames:
            Frames to preserve subject lock during occlusion.
        occlusion_memory:
            Weight applied to past visibility confidence.
        """
        self._max_hold_frames = max(1, int(max_hold_frames))
        self._occlusion_memory = _clamp01(occlusion_memory)
        self._hold_counter = 0
        self._active_subject_id: Optional[str] = None
    def update(
        self,
        candidate: Dict,
        visibility_confidence: float,
    ) -> Dict:
        """
        candidate:
            Current dominant subject candidate.
        visibility_confidence:
            0..1 — confidence that subject is fully visible.
        Returns:
            Stable subject selection dict.
        """
        sid = candidate.get("id")
        vis = _clamp01(visibility_confidence)
        if self._active_subject_id is None:
            self._active_subject_id = sid
            self._hold_counter = 0
            return candidate
        # If same subject, reset hold counter
        if sid == self._active_subject_id:
            self._hold_counter = 0
            return candidate
        # Occlusion detected — preserve previous subject
        if vis < 0.55:
            self._hold_counter += 1
            if self._hold_counter <= self._max_hold_frames:
                return candidate  # continue tracking logic upstream
        # Persistent occlusion → allow subject switch
        self._active_subject_id = sid
        self._hold_counter = 0
        return candidate
# ==============================================================================
# END OF CHUNK 86 K 04
