# ==============================================================================
# CHUNK 86 K 05 — SUBJECT ROLE CLASSIFICATION ENGINE
# ==============================================================================
#
# Purpose:
#   Assign stable cinematic roles to detected subjects so framing,
#   focus, motion, and exposure behave like a human cinematographer.
#
# Cinematic principle:
#   Cameras don’t track “objects” — they frame protagonists, antagonists,
#   supports, and contextual elements differently.
#
# This module:
#   - Classifies subjects into cinematic roles
#   - Stabilizes roles temporally
#   - Exposes role weights to downstream camera & flight AI
#
# ==============================================================================

from typing import Dict


def _clamp01(x: float) -> float:
    if x < 0.0:
        return 0.0
    if x > 1.0:
        return 1.0
    return x


class SubjectRoleClassifier:
    """
    Assigns cinematic roles to subjects based on dominance and context.
    """
    __slots__ = (
        "_role_memory",
        "_role_stickiness",
    )
    def __init__(self, role_stickiness: float = 0.7):
        """
        role_stickiness:
            Resistance to role switching over time.
        """
        self._role_stickiness = _clamp01(role_stickiness)
        self._role_memory: Dict[str, str] = {}
    def classify(
        self,
        subject: Dict,
        dominance: float,
        scene_context: Dict,
    ) -> str:
        """
        subject:
            {
              "id": str,
              "salience": float,
              "motion": float,
              "size": float
            }
        dominance:
            Dominance score (0..1)
        scene_context:
            {
              "crowd_level": float,
              "conflict": float,
              "narrative_focus": float
            }
        Returns:
            role: one of
              ["hero", "secondary", "antagonist", "context"]
        """
        sid = subject.get("id", "")
        # Retrieve previous role if present
        prev_role = self._role_memory.get(sid)
        crowd = scene_context.get("crowd_level", 0.0)
        conflict = scene_context.get("conflict", 0.0)
        narrative = scene_context.get("narrative_focus", 0.5)
        # Base role decision
        if dominance > 0.72 and narrative > 0.5:
            role = "hero"
        elif conflict > 0.6 and subject.get("motion", 0.0) > 0.5:
            role = "antagonist"
        elif dominance > 0.35:
            role = "secondary"
        else:
            role = "context"
        # Apply stickiness to avoid flicker
        if prev_role and prev_role != role:
            if self._role_stickiness > 0.0:
                role = prev_role
        self._role_memory[sid] = role
        return role
# ==============================================================================
# END OF CHUNK 86 K 05
