# ==============================================================================
# CHUNK 86 K 06 — CINEMATIC FOCUS OWNERSHIP LOGIC
# ==============================================================================
#
# Purpose:
#   Decide which subject owns focus at any moment and enforce that
#   ownership across camera, lens, and framing subsystems.
#
# Cinematic principle:
#   Focus is a narrative decision, not a reflex.
#
# This module:
#   - Assigns a single focus owner
#   - Prevents focus wars between subjects
#   - Allows intentional focus pulls
#
# ==============================================================================

from typing import Dict, Optional


def _clamp01(x: float) -> float:
    if x < 0.0:
        return 0.0
    if x > 1.0:
        return 1.0
    return x


class FocusOwnershipController:
    """
    Manages cinematic focus ownership across subjects.
    """
    __slots__ = (
        "_current_owner",
        "_lock_strength",
        "_handoff_threshold",
    )
    def __init__(
        self,
        lock_strength: float = 0.8,
        handoff_threshold: float = 0.18,
    ):
        """
        lock_strength:
            How resistant focus is to switching once owned.
        handoff_threshold:
            Minimum dominance delta required to transfer focus.
        """
        self._lock_strength = _clamp01(lock_strength)
        self._handoff_threshold = max(0.01, handoff_threshold)
        self._current_owner: Optional[str] = None
    def resolve_owner(
        self,
        subject_id: str,
        dominance: float,
        intent: Dict,
    ) -> Optional[str]:
        """
        subject_id:
            Candidate subject ID.
        dominance:
            Dominance score (0..1).
        intent:
            {
              "force_focus": bool,
              "focus_pull": float  # 0..1 desire to change focus
            }
        Returns:
            Active focus owner subject ID.
        """
        # Forced focus via director / user intent
        if intent.get("force_focus"):
            self._current_owner = subject_id
            return self._current_owner
        # No owner yet
        if self._current_owner is None:
            self._current_owner = subject_id
            return self._current_owner
        # Same subject retains ownership
        if subject_id == self._current_owner:
            return self._current_owner
        # Evaluate handoff conditions
        pull = _clamp01(intent.get("focus_pull", 0.0))
        effective_threshold = self._handoff_threshold * (1.0 - pull)
        if dominance > effective_threshold:
            # Apply lock resistance
            if pull > (1.0 - self._lock_strength):
                self._current_owner = subject_id
        return self._current_owner
# ==============================================================================
# END OF CHUNK 86 K 06
# ==============================================================================
# ==============================================================================
# CHUNK 86 K 07 — ATTENTION HANDOFF STABILIZER
# ==============================================================================
#
# Purpose:
#   Smooth, filmic transitions when focus ownership changes.
#
# Cinematic principle:
#   Focus handoff must feel intentional — never abrupt.
#
# This module:
#   - Applies temporal easing to focus transitions
#   - Prevents snap refocus and oscillation
#   - Supports intentional rack-focus pacing
#
# ==============================================================================

from typing import Optional


def _lerp(a: float, b: float, t: float) -> float:
    return a + (b - a) * t


def _clamp01(x: float) -> float:
    if x < 0.0:
        return 0.0
    if x > 1.0:
        return 1.0
    return x


class FocusHandoffStabilizer:
    """
    Controls temporal smoothing during focus ownership changes.
    """
    __slots__ = (
        "_active",
        "_progress",
        "_duration",
        "_from_depth",
        "_to_depth",
    )
    def __init__(self, duration_sec: float = 0.45):
        """
        duration_sec:
            Time for full focus transition (cinematic rack duration).
        """
        self._duration = max(0.05, duration_sec)
        self._active = False
        self._progress = 0.0
        self._from_depth: float = 0.0
        self._to_depth: float = 0.0
    def begin(self, from_depth: float, to_depth: float):
        """
        Initiate a stabilized focus handoff.
        """
        self._from_depth = max(0.0, from_depth)
        self._to_depth = max(0.0, to_depth)
        self._progress = 0.0
        self._active = True
    def update(self, dt: float) -> Optional[float]:
        """
        Advance transition.
        Returns:
            Current stabilized focus depth, or None if inactive.
        """
        if not self._active:
            return None
        self._progress += dt / self._duration
        t = _clamp01(self._progress)
        # Smoothstep easing for cinematic feel
        t_smooth = t * t * (3.0 - 2.0 * t)
        depth = _lerp(self._from_depth, self._to_depth, t_smooth)
        if t >= 1.0:
            self._active = False
        return depth
# ==============================================================================
# END OF CHUNK 86 K 07
# ==============================================================================
# ==============================================================================
# CHUNK 86 K 08 — MULTI-INTENT CONFLICT RESOLVER
# ==============================================================================
#
# Purpose:
#   Resolve conflicts between multiple competing cinematic intents.
#
# Cinematic principle:
#   When multiple voices exist (user, AI, subject saliency),
#   there must be a single authoritative decision path.
#
# This module:
#   - Weighs user intent, AI director intent, and scene saliency
#   - Prevents oscillation between conflicting commands
#   - Produces a unified cinematic intent vector
#
# ==============================================================================

from typing import Dict


def _clamp01(x: float) -> float:
    if x < 0.0:
        return 0.0
    if x > 1.0:
        return 1.0
    return x


class IntentConflictResolver:
    """
    Resolves conflicts between multiple cinematic intent sources.
    """
    __slots__ = (
        "_user_weight",
        "_ai_weight",
        "_scene_weight",
    )
    def __init__(
        self,
        user_weight: float = 0.5,
        ai_weight: float = 0.35,
        scene_weight: float = 0.15,
    ):
        total = user_weight + ai_weight + scene_weight
        if total <= 0.0:
            total = 1.0
        self._user_weight = user_weight / total
        self._ai_weight = ai_weight / total
        self._scene_weight = scene_weight / total
    def resolve(self, user: Dict, ai: Dict, scene: Dict) -> Dict:
        """
        Combine multiple intent sources into one authoritative intent.
        Each dict may contain:
            - focus_pull (0..1)
            - framing_bias (-1..1)
            - motion_energy (0..1)
        """
        def _get(d, k, default=0.0):
            return float(d.get(k, default))
        intent = {}
        intent["focus_pull"] = _clamp01(
            _get(user, "focus_pull") * self._user_weight +
            _get(ai, "focus_pull") * self._ai_weight +
            _get(scene, "focus_pull") * self._scene_weight
        )
        intent["framing_bias"] = (
            _get(user, "framing_bias") * self._user_weight +
            _get(ai, "framing_bias") * self._ai_weight +
            _get(scene, "framing_bias") * self._scene_weight
        )
        intent["motion_energy"] = _clamp01(
            _get(user, "motion_energy") * self._user_weight +
            _get(ai, "motion_energy") * self._ai_weight +
            _get(scene, "motion_energy") * self._scene_weight
        )
        # Hard overrides (never averaged)
        if user.get("force_focus"):
            intent["force_focus"] = True
        if user.get("manual_override"):
            intent["manual_override"] = True
        return intent
# ==============================================================================
# END OF CHUNK 86 K 08
