# ==============================================================================
# CHUNK 86 K 09 — SUBJECT EXIT & RE-ENTRY LOGIC
# ==============================================================================
#
# Purpose:
#   Maintain cinematic continuity when a tracked subject:
#     - Temporarily exits frame
#     - Is occluded
#     - Re-enters the scene
#
# Cinematic principle:
#   A subject leaving the frame should feel intentional,
#   never like a tracking failure.
#
# This module:
#   - Predicts subject trajectory during absence
#   - Maintains shot intention during occlusion
#   - Smoothly re-locks framing on re-entry
#
# ==============================================================================

import math
import time
from typing import Optional, Dict


class SubjectPresenceModel:
    """
    Tracks subject presence, absence, and cinematic re-entry.
    """

    __slots__ = (
        "_last_seen_ts",
        "_last_position",
        "_velocity",
        "_absence_confidence",
        "_max_absence_time",
    )

    def __init__(self, max_absence_time: float = 2.5):
        self._last_seen_ts = 0.0
        self._last_position = None
        self._velocity = (0.0, 0.0)
        self._absence_confidence = 0.0
        self._max_absence_time = max_absence_time


    def update_seen(self, position_xy, timestamp: float):
        """
        Call when subject is confidently detected.
        """
        if self._last_position is not None:
            dt = max(timestamp - self._last_seen_ts, 1e-4)
            vx = (position_xy[0] - self._last_position[0]) / dt
            vy = (position_xy[1] - self._last_position[1]) / dt
            self._velocity = (vx, vy)

        self._last_position = position_xy
        self._last_seen_ts = timestamp
        self._absence_confidence = 0.0


    def update_missing(self, timestamp: float):
        """
        Call when subject is not detected.
        """
        dt = timestamp - self._last_seen_ts
        self._absence_confidence = min(dt / self._max_absence_time, 1.0)


    def predicted_position(self, timestamp: float):
        """
        Predict subject position during absence.
        """
        if self._last_position is None:
            return None

        dt = timestamp - self._last_seen_ts
        px = self._last_position[0] + self._velocity[0] * dt
        py = self._last_position[1] + self._velocity[1] * dt
        return (px, py)


    def presence_state(self) -> Dict:
        """
        Returns presence state used by cinematic planner.
        """
        if self._absence_confidence <= 0.05:
            state = "present"
        elif self._absence_confidence < 1.0:
            state = "temporarily_missing"
        else:
            state = "lost"

        return {
            "state": state,
            "absence_confidence": self._absence_confidence,
        }


class CinematicReentryController:
    """
    Handles smooth re-entry framing when subject returns.
    """

    __slots__ = (
        "_relock_strength",
    )

    def __init__(self, relock_strength: float = 0.85):
        self._relock_strength = relock_strength


    def compute_reentry_bias(
        self,
        predicted_pos,
        detected_pos,
    ):
        """
        Compute smooth framing correction vector.
        """
        if predicted_pos is None or detected_pos is None:
            return (0.0, 0.0)

        dx = detected_pos[0] - predicted_pos[0]
        dy = detected_pos[1] - predicted_pos[1]

        return (
            dx * self._relock_strength,
            dy * self._relock_strength,
        )


