# ==============================================================================
# CHUNK 86 K 10 — NARRATIVE PRIORITY ESCALATOR
# ==============================================================================
#
# Purpose:
#   Dynamically elevate or suppress cinematic priorities
#   based on narrative significance over time.
#
# Cinematic principle:
#   Not all moments are equal.
#   Story-critical actions must override aesthetic preferences.
#
# This module:
#   - Scores narrative importance of events
#   - Escalates priority smoothly (no snapping)
#   - Decays priority when narrative weight passes
#
# ==============================================================================

import math
import time
from typing import Dict


def _smoothstep(x: float) -> float:
    if x <= 0.0:
        return 0.0
    if x >= 1.0:
        return 1.0
    return x * x * (3.0 - 2.0 * x)


class NarrativeEvent:
    """
    Represents a narrative-relevant event.
    """

    __slots__ = (
        "base_weight",
        "start_time",
        "duration",
    )

    def __init__(self, base_weight: float, duration: float):
        self.base_weight = max(0.0, base_weight)
        self.start_time = time.time()
        self.duration = max(0.01, duration)


    def weight_at(self, now: float) -> float:
        """
        Smooth time-based weight curve.
        """
        t = (now - self.start_time) / self.duration
        return self.base_weight * _smoothstep(t)


class NarrativePriorityEscalator:
    """
    Aggregates narrative events and computes final priority bias.
    """

    __slots__ = (
        "_events",
        "_decay_rate",
    )

    def __init__(self, decay_rate: float = 0.85):
        self._events = []
        self._decay_rate = decay_rate


    def register_event(self, base_weight: float, duration: float):
        """
        Register a new narrative event.
        """
        self._events.append(NarrativeEvent(base_weight, duration))


    def compute_priority(self) -> float:
        """
        Compute combined narrative priority scalar.
        """
        now = time.time()
        total = 0.0

        alive = []
        for ev in self._events:
            w = ev.weight_at(now)
            if w > 1e-4:
                total += w
                alive.append(ev)

        self._events = alive
        return min(total, 1.0)


    def apply_to_intent(self, intent: Dict) -> Dict:
        """
        Elevate intent parameters based on narrative priority.
        """
        priority = self.compute_priority()

        if priority <= 0.0:
            return intent

        boosted = dict(intent)

        # Motion energy rises during narrative peaks
        if "motion_energy" in boosted:
            boosted["motion_energy"] = min(
                1.0,
                boosted["motion_energy"] + priority * 0.4
            )

        # Framing bias becomes more assertive
        if "framing_bias" in boosted:
            boosted["framing_bias"] *= (1.0 + priority * 0.6)

        # Focus locking during critical moments
        if priority > 0.65:
            boosted["force_focus"] = True

        return boosted


