# CHUNK 86 L 01 — SHOT GRAMMAR STATE MACHINE
# ==============================================================================
#
# Purpose:
#   Formalize cinematic language as a deterministic state machine.
#
# Cinematic principle:
#   Cinema is grammar, not filters.
#   Every shot exists in a legal context relative to the previous one.
#
# This module:
#   - Encodes shot grammar states (establishing, medium, close, action, cutaway)
#   - Tracks transitions with temporal stability
#   - Exposes legality + preference signals for downstream engines
#
# ==============================================================================

import time
from enum import Enum, auto
from typing import Dict, Tuple


class ShotType(Enum):
    ESTABLISHING = auto()
    WIDE = auto()
    MEDIUM = auto()
    CLOSE = auto()
    EXTREME_CLOSE = auto()
    ACTION = auto()
    CUTAWAY = auto()


class GrammarState:
    """
    Represents a current shot grammar state with temporal context.
    """

    __slots__ = (
        "shot_type",
        "entered_at",
        "min_hold",
    )

    def __init__(self, shot_type: ShotType, min_hold: float):
        self.shot_type = shot_type
        self.entered_at = time.time()
        self.min_hold = min_hold


    def age(self) -> float:
        return time.time() - self.entered_at


    def can_exit(self) -> bool:
        return self.age() >= self.min_hold


# Hard grammar legality table (film-school rules)
_LEGAL_TRANSITIONS = {
    ShotType.ESTABLISHING: {
        ShotType.WIDE,
        ShotType.MEDIUM,
    },
    ShotType.WIDE: {
        ShotType.MEDIUM,
        ShotType.ACTION,
        ShotType.CUTAWAY,
    },
    ShotType.MEDIUM: {
        ShotType.CLOSE,
        ShotType.ACTION,
        ShotType.CUTAWAY,
    },
    ShotType.CLOSE: {
        ShotType.EXTREME_CLOSE,
        ShotType.MEDIUM,
        ShotType.CUTAWAY,
    },
    ShotType.EXTREME_CLOSE: {
        ShotType.CLOSE,
        ShotType.CUTAWAY,
    },
    ShotType.ACTION: {
        ShotType.MEDIUM,
        ShotType.CLOSE,
        ShotType.CUTAWAY,
    },
    ShotType.CUTAWAY: {
        ShotType.WIDE,
        ShotType.MEDIUM,
        ShotType.CLOSE,
    },
}


class ShotGrammarStateMachine:
    """
    Deterministic cinematic grammar controller.
    """

    __slots__ = (
        "_state",
        "_default_hold",
    )

    def __init__(self):
        self._default_hold = {
            ShotType.ESTABLISHING: 2.5,
            ShotType.WIDE: 2.0,
            ShotType.MEDIUM: 1.8,
            ShotType.CLOSE: 1.6,
            ShotType.EXTREME_CLOSE: 1.2,
            ShotType.ACTION: 1.0,
            ShotType.CUTAWAY: 0.8,
        }
        self._state = GrammarState(
            ShotType.ESTABLISHING,
            self._default_hold[ShotType.ESTABLISHING],
        )


    def current(self) -> ShotType:
        return self._state.shot_type


    def legality(self, next_shot: ShotType) -> bool:
        return next_shot in _LEGAL_TRANSITIONS[self._state.shot_type]


    def preference_score(self, next_shot: ShotType) -> float:
        """
        Soft preference for transitions (used by planners).
        """
        if not self.legality(next_shot):
            return 0.0
        age = self._state.age()
        base = min(age / self._state.min_hold, 1.0)
        # Penalize repetitive oscillation
        if next_shot == self._state.shot_type:
            return 0.1
        return base


    def request_transition(self, next_shot: ShotType) -> Tuple[bool, float]:
        """
        Ask state machine if transition is allowed and how strongly.
        """
        if not self.legality(next_shot):
            return False, 0.0
        if not self._state.can_exit():
            return False, 0.0
        score = self.preference_score(next_shot)
        return True, score


    def force_transition(self, next_shot: ShotType):
        """
        Immediate transition (narrative override).
        """
        self._state = GrammarState(
            next_shot,
            self._default_hold[next_shot],
        )


    def commit_transition(self, next_shot: ShotType):
        """
        Commit a legal transition.
        """
        allowed, _ = self.request_transition(next_shot)
        if not allowed:
            return False
        self._state = GrammarState(
            next_shot,
            self._default_hold[next_shot],
        )
        return True


    def export_context(self) -> Dict:
        """
        Export grammar context for downstream AI.
        """
        return {
            "shot_type": self._state.shot_type.name,
            "age": self._state.age(),
            "min_hold": self._state.min_hold,
        }


