class GrammarCameraConstraints:
    """
    Converts shot grammar context into actionable camera constraints.
    """

    __slots__ = ()

    @staticmethod
    def get_constraints(grammar_context: Dict) -> CameraConstraintProfile:
        shot = grammar_context.get("shot_type", "MEDIUM")
        return _GRAMMAR_CONSTRAINTS.get(
            shot,
            _GRAMMAR_CONSTRAINTS["MEDIUM"],
        )


    @staticmethod
    def clamp_motion(
        desired: Dict[str, float],
        constraints: CameraConstraintProfile,
    ) -> Dict[str, float]:
        """
        Clamp camera motion commands to grammar limits.
        """
        out = dict(desired)

        out["pan_rate"] = max(
            -constraints.max_pan_rate,
            min(constraints.max_pan_rate, out.get("pan_rate", 0.0)),
        )

        out["tilt_rate"] = max(
            -constraints.max_tilt_rate,
            min(constraints.max_tilt_rate, out.get("tilt_rate", 0.0)),
        )

        out["zoom_rate"] = max(
            -constraints.max_zoom_rate,
            min(constraints.max_zoom_rate, out.get("zoom_rate", 0.0)),
        )

        out["translation_speed"] = max(
            0.0,
            min(
                constraints.max_translation_speed,
                out.get("translation_speed", 0.0),
            ),
        )

        return out


    @staticmethod
    def validate_subject_scale(
        subject_ratio: float,
        constraints: CameraConstraintProfile,
    ) -> Tuple[bool, float]:
        """
        Check if subject occupies legal screen space.
        Returns (valid, correction_bias).
        """
        if subject_ratio < constraints.min_subject_screen_ratio:
            return False, -1.0
        if subject_ratio > constraints.max_subject_screen_ratio:
            return False, 1.0
        return True, 0.0


