# ==============================================================================
# CHUNK 86 L 03 — SHOT TRANSITION LEGALITY MATRIX
# ==============================================================================
#
# Purpose:
#   Define hard legality and soft preference scores for shot transitions.
#
# Cinematic principle:
#   Some transitions are illegal, some are legal-but-ugly,
#   and some are narratively elegant.
#
# This module:
#   - Encodes a matrix of legal / illegal shot transitions
#   - Assigns cinematic quality scores to each legal transition
#   - Feeds downstream cut and pacing engines
#
# ==============================================================================

from typing import Dict, Tuple
from enum import Enum


class TransitionQuality(Enum):
    ILLEGAL = 0
    POOR = 1
    NEUTRAL = 2
    GOOD = 3
    EXCELLENT = 4


# Hard legality + quality matrix (cinema-informed)
_TRANSITION_MATRIX: Dict[Tuple[str, str], TransitionQuality] = {
    # ESTABLISHING
    ("ESTABLISHING", "WIDE"): TransitionQuality.EXCELLENT,
    ("ESTABLISHING", "MEDIUM"): TransitionQuality.GOOD,
    ("ESTABLISHING", "CLOSE"): TransitionQuality.POOR,
    ("ESTABLISHING", "ACTION"): TransitionQuality.NEUTRAL,
    # WIDE
    ("WIDE", "MEDIUM"): TransitionQuality.EXCELLENT,
    ("WIDE", "CLOSE"): TransitionQuality.GOOD,
    ("WIDE", "ACTION"): TransitionQuality.GOOD,
    ("WIDE", "CUTAWAY"): TransitionQuality.NEUTRAL,
    # MEDIUM
    ("MEDIUM", "CLOSE"): TransitionQuality.EXCELLENT,
    ("MEDIUM", "WIDE"): TransitionQuality.GOOD,
    ("MEDIUM", "ACTION"): TransitionQuality.GOOD,
    ("MEDIUM", "CUTAWAY"): TransitionQuality.NEUTRAL,
    # CLOSE
    ("CLOSE", "EXTREME_CLOSE"): TransitionQuality.EXCELLENT,
    ("CLOSE", "MEDIUM"): TransitionQuality.GOOD,
    ("CLOSE", "CUTAWAY"): TransitionQuality.GOOD,
    # EXTREME CLOSE
    ("EXTREME_CLOSE", "CLOSE"): TransitionQuality.GOOD,
    ("EXTREME_CLOSE", "CUTAWAY"): TransitionQuality.EXCELLENT,
    # ACTION
    ("ACTION", "MEDIUM"): TransitionQuality.GOOD,
    ("ACTION", "CLOSE"): TransitionQuality.GOOD,
    ("ACTION", "CUTAWAY"): TransitionQuality.EXCELLENT,
    # CUTAWAY
    ("CUTAWAY", "WIDE"): TransitionQuality.GOOD,
    ("CUTAWAY", "MEDIUM"): TransitionQuality.GOOD,
    ("CUTAWAY", "CLOSE"): TransitionQuality.NEUTRAL,
}


class ShotTransitionLegality:
    """
    Evaluates legality and cinematic quality of shot transitions.
    """

    __slots__ = ()

    @staticmethod
    def evaluate(from_shot: str, to_shot: str) -> TransitionQuality:
        """
        Return transition quality enum.
        """
        return _TRANSITION_MATRIX.get(
            (from_shot, to_shot),
            TransitionQuality.ILLEGAL,
        )


    @staticmethod
    def is_legal(from_shot: str, to_shot: str) -> bool:
        """
        Hard legality check.
        """
        return (
            ShotTransitionLegality.evaluate(from_shot, to_shot)
            != TransitionQuality.ILLEGAL
        )


    @staticmethod
    def quality_score(from_shot: str, to_shot: str) -> float:
        """
        Convert quality enum to normalized scalar (0..1).
        """
        quality = ShotTransitionLegality.evaluate(from_shot, to_shot)
        if quality == TransitionQuality.ILLEGAL:
            return 0.0
        if quality == TransitionQuality.POOR:
            return 0.25
        if quality == TransitionQuality.NEUTRAL:
            return 0.5
        if quality == TransitionQuality.GOOD:
            return 0.75
        if quality == TransitionQuality.EXCELLENT:
            return 1.0
        return 0.0


    @staticmethod
    def export_matrix() -> Dict[str, Dict[str, float]]:
        """
        Export full matrix for debugging or visualization.
        """
        out: Dict[str, Dict[str, float]] = {}
        for (frm, to), q in _TRANSITION_MATRIX.items():
            out.setdefault(frm, {})[to] = ShotTransitionLegality.quality_score(
                frm, to
            )
        return out


