# ==============================================================================
# CHUNK 86 L 04 — AUTONOMOUS CUT DECISION ENGINE
# ==============================================================================
#
# Purpose:
#   Decide *when* and *whether* to cut, based on grammar, legality,
#   narrative priority, motion, and viewer comfort.
#
# Cinematic principle:
#   A cut is a narrative statement, not a reaction.
#
# This module:
#   - Aggregates grammar readiness, transition quality, rhythm, and narrative weight
#   - Suppresses cuts during motion peaks or emotional continuity
#   - Produces a scalar cut-probability (0..1) + hard veto
#
# ==============================================================================

import math
import time
from typing import Dict, Tuple


def _sigmoid(x: float) -> float:
    return 1.0 / (1.0 + math.exp(-x))


class AutonomousCutDecisionEngine:
    """
    Computes cut decisions using multi-factor cinematic reasoning.
    """

    __slots__ = (
        "_last_cut_time",
        "_min_interval",
    )

    def __init__(self, min_interval: float = 0.8):
        self._last_cut_time = 0.0
        self._min_interval = min_interval


    def _cooldown_ok(self) -> bool:
        return (time.time() - self._last_cut_time) >= self._min_interval


    def evaluate(
        self,
        grammar_context: Dict,
        transition_quality: float,
        narrative_priority: float,
        motion_energy: float,
        rhythm_pressure: float,
        emotional_lock: bool,
    ) -> Tuple[bool, float]:
        """
        Evaluate cut decision.
        Returns:
            (allow_cut, probability)
        """
        # Hard vetoes
        if not self._cooldown_ok():
            return False, 0.0
        if emotional_lock:
            return False, 0.0
        age = float(grammar_context.get("age", 0.0))
        min_hold = float(grammar_context.get("min_hold", 1.0))
        hold_readiness = max(0.0, min((age - min_hold) / max(min_hold, 1e-3), 1.0))
        # Motion suppresses cuts unless narratively critical
        motion_suppression = 1.0 - min(motion_energy, 1.0)
        # Narrative priority can override motion suppression
        narrative_boost = min(narrative_priority * 1.5, 1.0)
        # Combine factors
        raw_score = (
            hold_readiness * 0.35 +
            transition_quality * 0.30 +
            rhythm_pressure * 0.20 +
            narrative_boost * 0.15
        )
        # Apply motion suppression (soft)
        raw_score *= (0.6 + 0.4 * motion_suppression)
        probability = _sigmoid((raw_score - 0.5) * 6.0)
        allow = probability > 0.55
        if allow:
            self._last_cut_time = time.time()
        return allow, probability


