# ==============================================================================
# CHUNK 86 L 05 — SHOT DURATION INTELLIGENCE MODEL
# ==============================================================================
#
# Purpose:
#   Predict optimal shot duration dynamically based on content,
#   motion, narrative weight, and viewer cognitive load.
#
# Cinematic principle:
#   Duration is meaning.
#   The same shot held too long or too short changes the story.
#
# This module:
#   - Computes adaptive ideal hold time per shot
#   - Adjusts for motion energy, emotional weight, and narrative peaks
#   - Feeds cut engines and pacing modulators
#
# ==============================================================================

import math
from typing import Dict


def _lerp(a: float, b: float, t: float) -> float:
    return a + (b - a) * max(0.0, min(1.0, t))


class ShotDurationIntelligence:
    """
    Computes optimal shot duration in seconds.
    """

    __slots__ = (
        "_base_durations",
    )

    def __init__(self):
        # Baseline durations informed by film analysis (seconds)
        self._base_durations = {
            "ESTABLISHING": 3.5,
            "WIDE": 3.0,
            "MEDIUM": 2.6,
            "CLOSE": 2.2,
            "EXTREME_CLOSE": 1.6,
            "ACTION": 1.2,
            "CUTAWAY": 1.0,
        }


    def compute(
        self,
        grammar_context: Dict,
        motion_energy: float,
        narrative_priority: float,
        emotional_intensity: float,
        viewer_fatigue: float,
    ) -> float:
        """
        Compute ideal shot duration.
        Inputs expected in 0..1 range where applicable.
        """
        shot_type = grammar_context.get("shot_type", "MEDIUM")
        base = self._base_durations.get(shot_type, 2.5)
        # Motion shortens duration
        motion_factor = _lerp(1.0, 0.55, motion_energy)
        # Narrative importance extends duration (let moments breathe)
        narrative_factor = _lerp(1.0, 1.6, narrative_priority)
        # Emotional intensity prefers longer holds (eye contact, silence)
        emotional_factor = _lerp(1.0, 1.4, emotional_intensity)
        # Viewer fatigue shortens duration to maintain engagement
        fatigue_factor = _lerp(1.0, 0.7, viewer_fatigue)
        duration = (
            base *
            motion_factor *
            narrative_factor *
            emotional_factor *
            fatigue_factor
        )
        # Clamp to cinematic sanity bounds
        return max(0.6, min(duration, 6.0))


