# ==============================================================================
# CHUNK 86 L 06 — RHYTHM & PACING MODULATOR
# ==============================================================================
#
# Purpose:
#   Shape temporal rhythm across shots and movements so the film
#   feels intentional, musical, and emotionally coherent.
#
# Cinematic principle:
#   Rhythm is the invisible score of cinema.
#   Viewers feel pacing before they understand it.
#
# This module:
#   - Tracks recent shot durations and cut density
#   - Modulates pacing pressure to accelerate or decelerate editing
#   - Prevents monotonous or chaotic temporal patterns
#
# ==============================================================================

import time
from collections import deque
from typing import Deque


class RhythmPacingModulator:
    """
    Maintains temporal rhythm and computes pacing pressure.
    """

    __slots__ = (
        "_window",
        "_durations",
        "_last_update",
    )

    def __init__(self, window_seconds: float = 12.0):
        self._window = window_seconds
        self._durations: Deque[float] = deque()
        self._last_update = time.time()


    def register_shot(self, duration: float):
        """
        Register a completed shot duration.
        """
        now = time.time()
        self._durations.append((now, duration))
        # Trim window
        while self._durations and (now - self._durations[0][0]) > self._window:
            self._durations.popleft()


    def pacing_pressure(self) -> float:
        """
        Compute pacing pressure scalar (0..1).
        Higher values encourage faster cutting.
        """
        if not self._durations:
            return 0.0
        durations = [d for _, d in self._durations]
        avg = sum(durations) / len(durations)
        # Film-informed comfort band
        ideal_low = 1.2
        ideal_high = 3.0
        if avg < ideal_low:
            # Too fast → slow down
            return 0.0
        if avg > ideal_high:
            # Too slow → speed up
            return min((avg - ideal_high) / ideal_high, 1.0)
        # Inside comfort band → neutral pacing
        return 0.3


    def reset(self):
        """
        Reset rhythm history (e.g., after hard narrative transition).
        """
        self._durations.clear()
        self._last_update = time.time()


