# ==============================================================================
# CHUNK 86 L 07 — EMOTIONAL BEAT SYNCHRONIZER
# ==============================================================================
#
# Purpose:
#   Synchronize camera motion, cut timing, and framing with
#   detected emotional beats in the scene.
#
# Cinematic principle:
#   Emotion leads, technique follows.
#   A cut or move at the wrong emotional micro-moment kills impact.
#
# This module:
#   - Tracks emotional intensity over time
#   - Detects rising, peaking, and resolving emotional beats
#   - Locks or releases cuts and motion at correct moments
#
# ==============================================================================

import time
from collections import deque
from typing import Deque, Tuple


class EmotionalBeat:
    """
    Represents a detected emotional beat.
    """

    __slots__ = (
        "timestamp",
        "intensity",
    )

    def __init__(self, intensity: float):
        self.timestamp = time.time()
        self.intensity = max(0.0, min(1.0, intensity))


class EmotionalBeatSynchronizer:
    """
    Aligns cinematic decisions with emotional flow.
    """

    __slots__ = (
        "_window",
        "_beats",
        "_lock_threshold",
        "_release_threshold",
    )

    def __init__(
        self,
        window_seconds: float = 4.0,
        lock_threshold: float = 0.65,
        release_threshold: float = 0.35,
    ):
        self._window = window_seconds
        self._beats: Deque[EmotionalBeat] = deque()
        self._lock_threshold = lock_threshold
        self._release_threshold = release_threshold


    def register_intensity(self, intensity: float):
        """
        Register instantaneous emotional intensity (0..1).
        """
        beat = EmotionalBeat(intensity)
        self._beats.append(beat)
        # Trim window
        now = beat.timestamp
        while self._beats and (now - self._beats[0].timestamp) > self._window:
            self._beats.popleft()


    def current_state(self) -> Tuple[bool, float]:
        """
        Returns:
            (emotional_lock, peak_intensity)
        emotional_lock:
            True when cuts/moves should be suppressed.
        """
        if not self._beats:
            return False, 0.0
        intensities = [b.intensity for b in self._beats]
        peak = max(intensities)
        # Lock during emotional peaks
        if peak >= self._lock_threshold:
            return True, peak
        # Release once emotion resolves
        if peak <= self._release_threshold:
            return False, peak
        # Transitional zone → partial lock
        return True, peak * 0.5


    def recommended_motion_damping(self) -> float:
        """
        Suggest motion damping factor (0..1).
        Higher means smoother / slower motion.
        """
        lock, peak = self.current_state()
        if not lock:
            return 0.0
        # Strong emotion → heavy damping
        return min(peak * 1.2, 1.0)


    def reset(self):
        """
        Clear emotional history (scene change).
        """
        self._beats.clear()


