# ==============================================================================
# CHUNK 86 L 08 — CONTINUITY ERROR DETECTOR
# ==============================================================================
#
# Purpose:
#   Detect and prevent cinematic continuity errors across time,
#   cuts, camera moves, and grading states.
#
# Detects:
#   - 180° rule violations
#   - Eye-line jumps
#   - Motion direction discontinuity
#   - Exposure / color jumps across adjacent cuts
#
# Cinematic principle:
#   Continuity is invisible when correct, catastrophic when broken.
#
# ==============================================================================

import numpy as np
from dataclasses import dataclass
from typing import Optional, Tuple


@dataclass
class ContinuityState:
    """
    Stores the previous frame's cinematic context.
    """
    camera_forward: np.ndarray      # 3D forward vector
    subject_screen_pos: np.ndarray  # (x, y) normalized
    motion_vector: np.ndarray       # 2D motion on screen
    exposure: float                 # EV-like scalar
    color_bias: np.ndarray          # RGB bias
    timestamp: float


class ContinuityErrorDetector:
    """
    Validates temporal and spatial continuity.
    """

    __slots__ = (
        "_prev",
        "_axis_tolerance",
        "_eyeline_tolerance",
        "_exposure_jump_limit",
        "_color_jump_limit",
    )

    def __init__(
        self,
        axis_tolerance_deg: float = 35.0,
        eyeline_tolerance: float = 0.18,
        exposure_jump_limit: float = 0.75,
        color_jump_limit: float = 0.12,
    ):
        self._prev: Optional[ContinuityState] = None
        self._axis_tolerance = axis_tolerance_deg
        self._eyeline_tolerance = eyeline_tolerance
        self._exposure_jump_limit = exposure_jump_limit
        self._color_jump_limit = color_jump_limit


    def reset(self):
        self._prev = None


    def _angle_between(self, a: np.ndarray, b: np.ndarray) -> float:
        """
        Compute angle in degrees between vectors.
        """
        a_n = a / (np.linalg.norm(a) + 1e-6)
        b_n = b / (np.linalg.norm(b) + 1e-6)
        dot = np.clip(np.dot(a_n, b_n), -1.0, 1.0)
        return np.degrees(np.arccos(dot))


    def evaluate(
        self,
        camera_forward: np.ndarray,
        subject_screen_pos: np.ndarray,
        motion_vector: np.ndarray,
        exposure: float,
        color_bias: np.ndarray,
        timestamp: float,
    ) -> Tuple[bool, dict]:
        """
        Evaluate continuity against previous state.
        Returns:
            (ok, diagnostics)
        """
        diagnostics = {
            "axis_violation": False,
            "eyeline_violation": False,
            "motion_violation": False,
            "exposure_violation": False,
            "color_violation": False,
        }
        if self._prev is None:
            self._prev = ContinuityState(
                camera_forward,
                subject_screen_pos,
                motion_vector,
                exposure,
                color_bias,
                timestamp,
            )
            return True, diagnostics
        # 180-degree rule / axis check
        axis_angle = self._angle_between(
            self._prev.camera_forward, camera_forward
        )
        if axis_angle > self._axis_tolerance:
            diagnostics["axis_violation"] = True
        # Eye-line continuity
        eyeline_shift = np.linalg.norm(
            subject_screen_pos - self._prev.subject_screen_pos
        )
        if eyeline_shift > self._eyeline_tolerance:
            diagnostics["eyeline_violation"] = True
        # Motion direction consistency
        if np.linalg.norm(self._prev.motion_vector) > 1e-3:
            dot = np.dot(
                motion_vector, self._prev.motion_vector
            )
            if dot < 0.0:
                diagnostics["motion_violation"] = True
        # Exposure jump
        if abs(exposure - self._prev.exposure) > self._exposure_jump_limit:
            diagnostics["exposure_violation"] = True
        # Color bias jump
        color_delta = np.linalg.norm(
            color_bias - self._prev.color_bias
        )
        if color_delta > self._color_jump_limit:
            diagnostics["color_violation"] = True
        ok = not any(diagnostics.values())
        # Update state only if acceptable (prevents drift)
        if ok:
            self._prev = ContinuityState(
                camera_forward,
                subject_screen_pos,
                motion_vector,
                exposure,
                color_bias,
                timestamp,
            )
        return ok, diagnostics


