# ==============================================================================
# CHUNK 86 L 09 — VIEWER COMFORT & MOTION SICKNESS GUARD
# ==============================================================================
#
# Purpose:
#   Prevent viewer discomfort caused by excessive motion,
#   acceleration spikes, jitter, or visual-vestibular mismatch.
#
# Guards against:
#   - Excessive angular velocity
#   - Sudden acceleration / deceleration
#   - High-frequency micro-jitter
#   - Conflicting motion cues vs visual flow
#
# Cinematic principle:
#   The audience should feel motion, not fight it.
#
# ==============================================================================

import numpy as np
from collections import deque
from typing import Deque, Tuple


class MotionSample:
    __slots__ = (
        "timestamp",
        "velocity",
        "angular_velocity",
    )

    def __init__(
        self,
        timestamp: float,
        velocity: np.ndarray,
        angular_velocity: np.ndarray,
    ):
        self.timestamp = timestamp
        self.velocity = velocity
        self.angular_velocity = angular_velocity


class ViewerComfortGuard:
    """
    Monitors motion patterns and enforces comfort constraints.
    """

    __slots__ = (
        "_window",
        "_samples",
        "_max_ang_vel",
        "_max_accel",
        "_jitter_threshold",
    )

    def __init__(
        self,
        window_seconds: float = 2.0,
        max_angular_velocity_deg: float = 120.0,
        max_accel: float = 6.0,
        jitter_threshold: float = 0.35,
    ):
        self._window = window_seconds
        self._samples: Deque[MotionSample] = deque()
        self._max_ang_vel = np.radians(max_angular_velocity_deg)
        self._max_accel = max_accel
        self._jitter_threshold = jitter_threshold


    def register_motion(
        self,
        timestamp: float,
        velocity: np.ndarray,
        angular_velocity: np.ndarray,
    ):
        """
        Register motion state.
        """
        sample = MotionSample(timestamp, velocity, angular_velocity)
        self._samples.append(sample)
        # Trim window
        while self._samples and (
            timestamp - self._samples[0].timestamp > self._window
        ):
            self._samples.popleft()


    def _compute_acceleration(self) -> float:
        if len(self._samples) < 2:
            return 0.0
        s1, s2 = self._samples[-2], self._samples[-1]
        dt = max(s2.timestamp - s1.timestamp, 1e-3)
        dv = np.linalg.norm(s2.velocity - s1.velocity)
        return dv / dt


    def _compute_jitter(self) -> float:
        if len(self._samples) < 4:
            return 0.0
        ang_vels = np.array(
            [np.linalg.norm(s.angular_velocity) for s in self._samples]
        )
        return np.std(ang_vels)


    def evaluate(self) -> Tuple[bool, dict]:
        """
        Evaluate viewer comfort constraints.
        Returns:
            (ok, diagnostics)
        """
        diagnostics = {
            "angular_velocity_violation": False,
            "acceleration_violation": False,
            "jitter_violation": False,
        }
        if not self._samples:
            return True, diagnostics
        # Angular velocity check
        max_ang = max(
            np.linalg.norm(s.angular_velocity)
            for s in self._samples
        )
        if max_ang > self._max_ang_vel:
            diagnostics["angular_velocity_violation"] = True
        # Acceleration check
        accel = self._compute_acceleration()
        if accel > self._max_accel:
            diagnostics["acceleration_violation"] = True
        # Jitter check
        jitter = self._compute_jitter()
        if jitter > self._jitter_threshold:
            diagnostics["jitter_violation"] = True
        ok = not any(diagnostics.values())
        return ok, diagnostics


    def recommended_smoothing(self) -> float:
        """
        Suggest smoothing strength (0..1).
        """
        accel = self._compute_acceleration()
        jitter = self._compute_jitter()
        smooth = 0.0
        smooth += min(accel / self._max_accel, 1.0) * 0.6
        smooth += min(jitter / self._jitter_threshold, 1.0) * 0.4
        return min(smooth, 1.0)


    def reset(self):
        self._samples.clear()


