# ==============================================================================
# CHUNK 86 L 10 — COGNITIVE LOAD REGULATOR
# ==============================================================================
#
# Purpose:
#   Prevent visual overload by dynamically regulating how much
#   information is presented to the viewer at any moment.
#
# Controls:
#   - Motion density
#   - Contrast complexity
#   - Subject count pressure
#   - Camera maneuver aggressiveness
#
# Cinematic principle:
#   The audience should feel immersed, not overwhelmed.
#
# ==============================================================================

import numpy as np
from collections import deque
from typing import Deque, Dict


class CognitiveSample:
    __slots__ = (
        "timestamp",
        "motion_energy",
        "contrast_energy",
        "subject_count",
    )

    def __init__(
        self,
        timestamp: float,
        motion_energy: float,
        contrast_energy: float,
        subject_count: int,
    ):
        self.timestamp = timestamp
        self.motion_energy = motion_energy
        self.contrast_energy = contrast_energy
        self.subject_count = subject_count


class CognitiveLoadRegulator:
    """
    Computes instantaneous and temporal cognitive load and
    recommends cinematic dampening when limits are exceeded.
    """

    __slots__ = (
        "_window",
        "_samples",
        "_max_motion",
        "_max_contrast",
        "_max_subjects",
    )

    def __init__(
        self,
        window_seconds: float = 3.0,
        max_motion_energy: float = 1.2,
        max_contrast_energy: float = 1.1,
        max_subjects: int = 3,
    ):
        self._window = window_seconds
        self._samples: Deque[CognitiveSample] = deque()
        self._max_motion = max_motion_energy
        self._max_contrast = max_contrast_energy
        self._max_subjects = max_subjects


    def register_state(
        self,
        timestamp: float,
        motion_energy: float,
        contrast_energy: float,
        subject_count: int,
    ):
        """
        Register instantaneous scene complexity metrics.
        """
        sample = CognitiveSample(
            timestamp,
            motion_energy,
            contrast_energy,
            subject_count,
        )
        self._samples.append(sample)
        # Trim window
        while self._samples and (
            timestamp - self._samples[0].timestamp > self._window
        ):
            self._samples.popleft()


    def _aggregate(self) -> Dict[str, float]:
        if not self._samples:
            return {
                "motion": 0.0,
                "contrast": 0.0,
                "subjects": 0.0,
            }
        motion = np.mean([s.motion_energy for s in self._samples])
        contrast = np.mean([s.contrast_energy for s in self._samples])
        subjects = np.mean([s.subject_count for s in self._samples])
        return {
            "motion": motion,
            "contrast": contrast,
            "subjects": subjects,
        }


    def evaluate(self) -> Dict[str, float]:
        """
        Returns normalized cognitive load metrics (0..1+).
        """
        agg = self._aggregate()
        load = {
            "motion_load": agg["motion"] / self._max_motion,
            "contrast_load": agg["contrast"] / self._max_contrast,
            "subject_load": agg["subjects"] / max(self._max_subjects, 1),
        }
        return load


    def recommended_reduction(self) -> Dict[str, float]:
        """
        Suggest reduction factors for cinematic systems.
        Returns values in range 0..1
        """
        load = self.evaluate()
        reduction = {
            "motion_damping": min(load["motion_load"], 1.0),
            "contrast_softening": min(load["contrast_load"], 1.0),
            "subject_deemphasis": min(load["subject_load"], 1.0),
        }
        return reduction


    def reset(self):
        self._samples.clear()


