# ==============================================================================
# ==============================================================================
# CHUNK 86 M 01 — SUBJECT ATTENTION HEATMAP ENGINE
# ==============================================================================
#
# Purpose:
#   Build a continuous spatial-temporal attention field representing
#   where the viewer's eye SHOULD be guided at every moment.
#
# This engine fuses:
#   - Subject detections (people, vehicles, faces, animals)
#   - Motion vectors (optical flow magnitude & direction)
#   - Luminance contrast gradients
#   - Narrative persistence bias
#
# Output:
#   A normalized attention heatmap in image space (0..1)
#
# Cinematic principle:
#   Cinema is not about showing everything —
#   it is about controlling where the audience looks.
#
# ==============================================================================

import numpy as np
from typing import List, Tuple


class AttentionSource:
    __slots__ = (
        "x",
        "y",
        "weight",
        "radius",
    )

    def __init__(
        self,
        x: float,
        y: float,
        weight: float,
        radius: float,
    ):
        self.x = x
        self.y = y
        self.weight = weight
        self.radius = radius


class SubjectAttentionHeatmap:
    """
    Generates and maintains an attention heatmap over the frame.
    """

    __slots__ = (
        "width",
        "height",
        "_decay",
        "_map",
    )

    def __init__(
        self,
        width: int,
        height: int,
        temporal_decay: float = 0.85,
    ):
        self.width = width
        self.height = height
        self._decay = temporal_decay
        self._map = np.zeros((height, width), dtype=np.float32)


    def _apply_decay(self):
        """
        Temporal decay ensures attention persists but does not stick forever.
        """
        self._map *= self._decay


    def _splat(
        self,
        source: AttentionSource,
    ):
        """
        Add a Gaussian attention blob to the map.
        """
        cx = int(source.x * self.width)
        cy = int(source.y * self.height)
        radius_px = int(source.radius * max(self.width, self.height))
        if radius_px <= 1:
            return
        y, x = np.ogrid[-cy : self.height - cy, -cx : self.width - cx]
        mask = x * x + y * y <= radius_px * radius_px
        gaussian = np.exp(
            -(x * x + y * y) / (2.0 * (radius_px * 0.45) ** 2)
        )
        self._map[mask] += gaussian[mask] * source.weight


    def update(
        self,
        sources: List[AttentionSource],
    ) -> np.ndarray:
        """
        Update heatmap from attention sources.
        """
        self._apply_decay()
        for src in sources:
            self._splat(src)
        # Normalize safely
        max_val = np.max(self._map)
        if max_val > 0:
            self._map /= max_val
        return self._map.copy()


    def peak(self) -> Tuple[float, float]:
        """
        Returns normalized coordinates (x,y) of peak attention.
        """
        idx = np.argmax(self._map)
        y, x = np.unravel_index(idx, self._map.shape)
        return (
            x / float(self.width),
            y / float(self.height),
        )


    def reset(self):
        self._map.fill(0.0)


