# END OF CHUNK 86 M 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 M 02 — SALIENCY FUSION CORE
# ==============================================================================
#
# Purpose:
#   Fuse multiple perceptual saliency channels into a single,
#   physically and perceptually grounded saliency field.
#
# Inputs:
#   - Motion saliency (optical flow magnitude)
#   - Contrast saliency (luminance + chroma gradients)
#   - Face / subject priors
#   - Narrative persistence bias
#
# Output:
#   Unified saliency map (0..1) suitable for framing, exposure,
#   focus, and motion intent.
#
# Cinematic principle:
#   The eye is drawn by contrast, motion, and meaning — in that order,
#   unless narrative intent overrides it.
#
# ==============================================================================

import numpy as np
from typing import Dict


class SaliencyFusionCore:
    """
    Combines multiple saliency channels with perceptual weighting
    and temporal smoothing.
    """

    __slots__ = (
        "_weights",
        "_temporal_alpha",
        "_prev_map",
    )

    def __init__(
        self,
        weights: Dict[str, float] = None,
        temporal_alpha: float = 0.65,
    ):
        # Default perceptual weights (sum not required to be 1)
        self._weights = weights or {
            "motion": 1.0,
            "contrast": 0.9,
            "subject": 1.4,
            "narrative": 1.2,
        }
        self._temporal_alpha = temporal_alpha
        self._prev_map = None


    def _normalize(self, m: np.ndarray) -> np.ndarray:
        max_v = np.max(m)
        if max_v > 0:
            return m / max_v
        return m


    def fuse(
        self,
        motion_map: np.ndarray,
        contrast_map: np.ndarray,
        subject_map: np.ndarray,
        narrative_map: np.ndarray,
    ) -> np.ndarray:
        """
        Fuse saliency maps into a single field.
        All inputs expected in linear space, same resolution.
        """
        fused = (
            motion_map * self._weights["motion"]
            + contrast_map * self._weights["contrast"]
            + subject_map * self._weights["subject"]
            + narrative_map * self._weights["narrative"]
        )
        fused = self._normalize(fused)
        # Temporal smoothing to prevent jittery attention
        if self._prev_map is not None:
            fused = (
                self._temporal_alpha * fused
                + (1.0 - self._temporal_alpha) * self._prev_map
            )
        self._prev_map = fused.copy()
        return fused


    def reset(self):
        self._prev_map = None


