# END OF CHUNK 86 M 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 M 03 — MULTI-SUBJECT PRIORITY ARBITRATION
# ==============================================================================
#
# Purpose:
#   Resolve conflicts when multiple subjects compete for attention
#   by assigning stable, cinematic priorities over time.
#
# Inputs:
#   - Subject detections with confidence & class
#   - Saliency heatmap
#   - Narrative persistence weights
#
# Output:
#   Ordered subject list with normalized priority scores
#
# Cinematic principle:
#   Cinema chooses a subject — it does not argue with itself.
#
# ==============================================================================

from typing import List, Dict
import math


class SubjectCandidate:
    __slots__ = (
        "id",
        "x",
        "y",
        "confidence",
        "cls",
        "area",
    )

    def __init__(
        self,
        sid: int,
        x: float,
        y: float,
        confidence: float,
        cls: str,
        area: float,
    ):
        self.id = sid
        self.x = x
        self.y = y
        self.confidence = confidence
        self.cls = cls
        self.area = area


class MultiSubjectArbitrator:
    """
    Determines which subject should dominate cinematic attention.
    """

    __slots__ = (
        "_class_bias",
        "_persistence",
        "_last_subject",
    )

    def __init__(
        self,
        class_bias: Dict[str, float] = None,
        persistence_bias: float = 0.25,
    ):
        self._class_bias = class_bias or {
            "person": 1.4,
            "vehicle": 1.1,
            "animal": 1.0,
            "object": 0.7,
        }
        self._persistence = persistence_bias
        self._last_subject = None


    def _subject_score(
        self,
        s: SubjectCandidate,
        saliency_value: float,
    ) -> float:
        """
        Compute subject priority score.
        """
        cls_bias = self._class_bias.get(s.cls, 1.0)
        area_boost = math.sqrt(max(s.area, 1e-6))
        score = (
            s.confidence
            * cls_bias
            * saliency_value
            * area_boost
        )
        if self._last_subject == s.id:
            score *= (1.0 + self._persistence)
        return score


    def arbitrate(
        self,
        subjects: List[SubjectCandidate],
        saliency_sampler,
    ) -> List[Dict]:
        """
        Returns subjects ordered by cinematic priority.
        """
        ranked = []
        for s in subjects:
            sal = saliency_sampler(s.x, s.y)
            score = self._subject_score(s, sal)
            ranked.append(
                {
                    "id": s.id,
                    "score": score,
                    "cls": s.cls,
                    "x": s.x,
                    "y": s.y,
                }
            )
        ranked.sort(key=lambda r: r["score"], reverse=True)
        if ranked:
            self._last_subject = ranked[0]["id"]
        return ranked


    def reset(self):
        self._last_subject = None


