# END OF CHUNK 86 M 03
# ==============================================================================
# ==============================================================================
# CHUNK 86 M 04 — NARRATIVE FOCUS PERSISTENCE
# ==============================================================================
#
# Purpose:
#   Maintain narrative continuity by preserving focus on a chosen
#   subject or region across time, even when momentary saliency dips.
#
# Inputs:
#   - Ranked subject priorities
#   - Saliency map
#   - Temporal confidence history
#
# Output:
#   Persistence-weighted subject priority adjustments
#
# Cinematic principle:
#   Story beats persist beyond instantaneous visual stimulus.
#
# ==============================================================================

import time
from typing import Dict, List


class NarrativeFocusState:
    __slots__ = (
        "subject_id",
        "strength",
        "last_update",
    )

    def __init__(self, subject_id: int, strength: float):
        self.subject_id = subject_id
        self.strength = strength
        self.last_update = time.time()


class NarrativeFocusPersistence:
    """
    Applies temporal inertia to subject focus to avoid erratic switching.
    """

    __slots__ = (
        "_decay_rate",
        "_boost",
        "_state",
    )

    def __init__(
        self,
        decay_rate: float = 0.92,
        persistence_boost: float = 0.35,
    ):
        self._decay_rate = decay_rate
        self._boost = persistence_boost
        self._state: NarrativeFocusState | None = None


    def update(
        self,
        ranked_subjects: List[Dict],
    ) -> List[Dict]:
        """
        Apply persistence bias to ranked subject list.
        """
        now = time.time()
        # Decay existing focus
        if self._state is not None:
            dt = now - self._state.last_update
            self._state.strength *= self._decay_rate ** max(dt, 0.0)
            self._state.last_update = now
        # Initialize focus if none exists
        if self._state is None and ranked_subjects:
            self._state = NarrativeFocusState(
                ranked_subjects[0]["id"], 1.0
            )
        # Apply boost to persistent subject
        for s in ranked_subjects:
            if self._state and s["id"] == self._state.subject_id:
                s["score"] *= (1.0 + self._boost * self._state.strength)
        # Re-sort after adjustment
        ranked_subjects.sort(key=lambda r: r["score"], reverse=True)
        # Update focus state if top subject changes significantly
        if ranked_subjects:
            top_id = ranked_subjects[0]["id"]
            if (
                self._state is None
                or top_id != self._state.subject_id
            ):
                self._state = NarrativeFocusState(top_id, 1.0)
        return ranked_subjects


    def reset(self):
        self._state = None


