# ==============================================================================
# CHUNK 86 M 05 — ATTENTION DECAY & RECOVERY MODEL
# ==============================================================================
#
# Purpose:
#   Model how viewer attention naturally fades and recovers over time
#   to prevent fixation and to enable intentional re-framing.
#
# Inputs:
#   - Current attention heatmap
#   - Narrative focus state
#   - Time since last major reframing event
#
# Output:
#   Attention modulation scalar and recovery trigger signals
#
# Cinematic principle:
#   Even strong subjects must eventually breathe —
#   attention decays, then is re-earned.
#
# ==============================================================================

import time
import numpy as np
from typing import Dict


class AttentionDecayRecovery:
    """
    Handles decay of sustained attention and triggers recovery events.
    """

    __slots__ = (
        "_decay_half_life",
        "_recovery_threshold",
        "_last_event_time",
    )

    def __init__(
        self,
        decay_half_life: float = 4.5,
        recovery_threshold: float = 0.35,
    ):
        self._decay_half_life = decay_half_life
        self._recovery_threshold = recovery_threshold
        self._last_event_time = time.time()


    def _decay_factor(self, elapsed: float) -> float:
        """
        Exponential decay factor based on half-life.
        """
        if elapsed <= 0:
            return 1.0
        return 0.5 ** (elapsed / self._decay_half_life)


    def evaluate(
        self,
        attention_map: np.ndarray,
    ) -> Dict[str, float | bool]:
        """
        Evaluate current attention stability and recovery need.
        """
        now = time.time()
        elapsed = now - self._last_event_time
        decay = self._decay_factor(elapsed)
        peak_attention = float(np.max(attention_map))
        mean_attention = float(np.mean(attention_map))
        sustained_focus = peak_attention * decay
        needs_recovery = sustained_focus < self._recovery_threshold
        if needs_recovery:
            self._last_event_time = now
        return {
            "decay_factor": decay,
            "sustained_focus": sustained_focus,
            "mean_attention": mean_attention,
            "trigger_recovery": needs_recovery,
        }


    def reset(self):
        self._last_event_time = time.time()


