# ==============================================================================
# CHUNK 86 N 01 — AUTONOMOUS FRAMING INTENT GENERATOR
# ==============================================================================
#
# Purpose:
#   Convert perceptual attention + narrative state into a stable,
#   cinematic framing intent that downstream camera and flight
#   controllers can execute smoothly.
#
# Inputs:
#   - Peak attention coordinates (x,y)
#   - Subject priority ranking
#   - Cognitive load reduction hints
#   - Attention decay / recovery signals
#
# Output:
#   High-level framing intent:
#     {
#       "target_x": float,
#       "target_y": float,
#       "tightness": 0..1,
#       "confidence": 0..1,
#     }
#
# Cinematic principle:
#   The camera must *intend* a frame before it ever moves.
#
# ==============================================================================

from typing import Dict, List


class FramingIntent:
    __slots__ = (
        "target_x",
        "target_y",
        "tightness",
        "confidence",
    )

    def __init__(
        self,
        target_x: float,
        target_y: float,
        tightness: float,
        confidence: float,
    ):
        self.target_x = target_x
        self.target_y = target_y
        self.tightness = tightness
        self.confidence = confidence


class AutonomousFramingIntentGenerator:
    """
    Generates stable framing intent from perceptual and narrative inputs.
    """

    __slots__ = (
        "_min_confidence",
        "_tightness_bias",
    )

    def __init__(
        self,
        min_confidence: float = 0.15,
        tightness_bias: float = 0.6,
    ):
        self._min_confidence = min_confidence
        self._tightness_bias = tightness_bias


    def generate(
        self,
        attention_peak: tuple[float, float],
        ranked_subjects: List[Dict],
        cognitive_reduction: Dict[str, float],
        recovery_state: Dict[str, float | bool],
    ) -> FramingIntent:
        """
        Generate framing intent for this frame.
        """
        x, y = attention_peak
        # Base confidence from subject priority
        if ranked_subjects:
            base_conf = min(ranked_subjects[0]["score"], 1.0)
        else:
            base_conf = self._min_confidence
        # Tightness adapts to cognitive load
        load_pressure = max(
            cognitive_reduction.get("motion_damping", 0.0),
            cognitive_reduction.get("subject_deemphasis", 0.0),
        )
        tightness = self._tightness_bias * (1.0 - load_pressure)
        # Recovery triggers encourage reframing looseness
        if recovery_state.get("trigger_recovery", False):
            tightness *= 0.85
            base_conf *= 0.9
        # Clamp outputs
        tightness = max(0.15, min(tightness, 1.0))
        confidence = max(self._min_confidence, min(base_conf, 1.0))
        return FramingIntent(
            target_x=x,
            target_y=y,
            tightness=tightness,
            confidence=confidence,
        )


