# ==============================================================================
# CHUNK 86 N 02 — RULE-OF-THIRDS & DYNAMIC RECOMPOSITION ENGINE
# ==============================================================================
#
# Purpose:
#   Convert framing intent into a compositionally optimal target
#   using classical cinematic composition rules with dynamic offsets.
#
# Rules enforced:
#   - Rule of thirds (primary)
#   - Lead room (motion-aware)
#   - Headroom preservation (for people)
#   - Edge avoidance & balance
#
# Output:
#   Refined framing target (x, y) with composition confidence
#
# Cinematic principle:
#   Composition is classical — but execution must be alive.
#
# ==============================================================================

from typing import Dict, Tuple
import math


class DynamicRecompositionEngine:
    """
    Applies cinematic composition rules to framing intent.
    """

    __slots__ = (
        "_thirds",
        "_edge_margin",
    )

    def __init__(
        self,
        edge_margin: float = 0.06,
    ):
        # Rule-of-thirds anchor points
        self._thirds = [
            (1.0 / 3.0, 1.0 / 3.0),
            (2.0 / 3.0, 1.0 / 3.0),
            (1.0 / 3.0, 2.0 / 3.0),
            (2.0 / 3.0, 2.0 / 3.0),
        ]
        self._edge_margin = edge_margin


    def _nearest_third(
        self,
        x: float,
        y: float,
    ) -> Tuple[float, float]:
        """
        Find nearest rule-of-thirds anchor.
        """
        best = None
        best_d = float("inf")
        for tx, ty in self._thirds:
            d = (x - tx) ** 2 + (y - ty) ** 2
            if d < best_d:
                best = (tx, ty)
                best_d = d
        return best


    def _edge_safe(
        self,
        v: float,
    ) -> float:
        """
        Prevent framing from sticking to edges.
        """
        return max(self._edge_margin, min(1.0 - self._edge_margin, v))


    def recompute(
        self,
        intent: Dict,
        motion_vector: Tuple[float, float] | None = None,
    ) -> Dict:
        """
        Recompute framing target using composition logic.
        """
        x = intent["target_x"]
        y = intent["target_y"]
        # Snap softly toward rule-of-thirds
        tx, ty = self._nearest_third(x, y)
        strength = intent.get("confidence", 0.5)
        x = x * (1.0 - strength) + tx * strength
        y = y * (1.0 - strength) + ty * strength
        # Lead room based on motion direction
        if motion_vector is not None:
            mx, my = motion_vector
            mag = math.hypot(mx, my)
            if mag > 1e-3:
                x += 0.08 * (mx / mag)
                y += 0.05 * (my / mag)
        # Edge safety
        x = self._edge_safe(x)
        y = self._edge_safe(y)
        return {
            "target_x": x,
            "target_y": y,
            "composition_confidence": strength,
        }


