# END OF CHUNK 86 N 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 N 03 — HORIZON & ROLL ALIGNMENT CONTROLLER
# ==============================================================================
#
# Purpose:
#   Maintain a visually level horizon and controlled roll behavior
#   during autonomous camera motion and framing.
#
# Inputs:
#   - IMU roll estimate (radians)
#   - Vision-based horizon line (optional)
#   - Camera motion intent
#
# Output:
#   Roll correction command (normalized -1..1)
#
# Cinematic principle:
#   A stable horizon is subconsciously expected.
#   Intentional roll is rare and must be deliberate.
#
# ==============================================================================

import math
from typing import Optional, Tuple


class HorizonRollAlignmentController:
    """
    Computes roll correction to keep horizon visually level while
    allowing limited intentional roll when justified.
    """

    __slots__ = (
        "_max_roll_deg",
        "_roll_deadband",
        "_vision_weight",
    )

    def __init__(
        self,
        max_roll_deg: float = 5.0,
        roll_deadband_deg: float = 0.3,
        vision_weight: float = 0.6,
    ):
        self._max_roll = math.radians(max_roll_deg)
        self._deadband = math.radians(roll_deadband_deg)
        self._vision_weight = vision_weight


    def _clamp(self, v: float, limit: float) -> float:
        if v > limit:
            return limit
        if v < -limit:
            return -limit
        return v


    def compute(
        self,
        imu_roll: float,
        vision_horizon_roll: Optional[float] = None,
        cinematic_roll_bias: float = 0.0,
    ) -> float:
        """
        Compute roll correction command.
        imu_roll:
            Roll from IMU (radians)
        vision_horizon_roll:
            Estimated roll from horizon detection (radians)
        cinematic_roll_bias:
            Intentional roll request (-1..1 scaled later)
        """
        # Fuse IMU and vision if available
        if vision_horizon_roll is not None:
            roll_est = (
                imu_roll * (1.0 - self._vision_weight)
                + vision_horizon_roll * self._vision_weight
            )
        else:
            roll_est = imu_roll
        # Deadband to avoid micro jitter
        if abs(roll_est) < self._deadband:
            roll_est = 0.0
        # Base correction tries to cancel roll
        correction = -roll_est
        # Apply intentional cinematic bias (very limited)
        correction += cinematic_roll_bias * self._max_roll * 0.25
        # Clamp to cinematic safety limits
        correction = self._clamp(correction, self._max_roll)
        # Normalize output (-1..1)
        if self._max_roll > 0:
            correction /= self._max_roll
        return correction


