# ==============================================================================
# CHUNK 86 N 04 — PARALLAX-AWARE CAMERA TRANSLATION PLANNER
# ==============================================================================
#
# Purpose:
#   Generate camera translation vectors that create cinematic parallax
#   while preserving subject framing, depth separation, and motion comfort.
#
# Cinematic principle:
#   Parallax (foreground/background relative motion) is the #1 depth cue
#   in cinema. Controlled lateral motion beats forward motion.
#
# Inputs:
#   - Subject depth estimate (meters)
#   - Background depth estimate (meters)
#   - Desired shot scale (wide/medium/close)
#   - Subject screen position
#
# Output:
#   Camera translation intent vector (dx, dy, dz) in normalized space
#
# Safety:
#   Outputs intent only — downstream autopilot enforces constraints.
#
# ==============================================================================

import math
from typing import Tuple


class ParallaxTranslationPlanner:
    """
    Plans cinematic camera translation to maximize depth separation
    without disturbing composition or inducing motion sickness.
    """

    __slots__ = (
        "_max_lateral",
        "_max_forward",
        "_depth_bias",
        "_comfort_gain",
    )

    def __init__(
        self,
        max_lateral: float = 1.0,
        max_forward: float = 0.6,
        depth_bias: float = 0.75,
        comfort_gain: float = 0.85,
    ):
        """
        max_lateral:
            Maximum normalized sideways motion
        max_forward:
            Maximum normalized forward/back motion
        depth_bias:
            Preference for lateral vs forward parallax (0..1)
        comfort_gain:
            Global damping for human comfort
        """
        self._max_lateral = max_lateral
        self._max_forward = max_forward
        self._depth_bias = depth_bias
        self._comfort_gain = comfort_gain


    def _clamp(self, v: float, limit: float) -> float:
        if v > limit:
            return limit
        if v < -limit:
            return -limit
        return v


    def plan(
        self,
        subject_depth_m: float,
        background_depth_m: float,
        shot_scale: float,
        subject_screen_x: float,
    ) -> Tuple[float, float, float]:
        """
        Compute translation intent.
        subject_depth_m:
            Estimated distance to subject (meters)
        background_depth_m:
            Estimated distance to background (meters)
        shot_scale:
            0.0 = extreme wide, 1.0 = extreme close
        subject_screen_x:
            Subject horizontal position (-1..1)
        """
        # Prevent division issues
        subject_depth_m = max(subject_depth_m, 0.1)
        background_depth_m = max(background_depth_m, subject_depth_m + 0.1)
        # Depth separation ratio (how strong parallax can be)
        depth_ratio = (background_depth_m - subject_depth_m) / background_depth_m
        depth_ratio = max(0.0, min(depth_ratio, 1.0))
        # Cinematic preference: lateral motion > forward motion
        lateral_strength = depth_ratio * self._depth_bias
        forward_strength = depth_ratio * (1.0 - self._depth_bias)
        # Shot scale modulation:
        # Close shots = less translation, wide shots = more
        scale_gain = 1.0 - shot_scale
        # Subject position influences lateral direction
        lateral_dir = -subject_screen_x
        # Compute raw motions
        dx = lateral_dir * lateral_strength * scale_gain
        dz = forward_strength * scale_gain
        # No vertical translation for cinematic stability
        dy = 0.0
        # Comfort damping
        dx *= self._comfort_gain
        dz *= self._comfort_gain
        # Clamp to safety bounds
        dx = self._clamp(dx, self._max_lateral)
        dz = self._clamp(dz, self._max_forward)
        return dx, dy, dz


