# ==============================================================================
# CHUNK 86 N 05 — VELOCITY SMOOTHING & INERTIAL DAMPING
# ==============================================================================
#
# Purpose:
#   Convert raw motion intent into smooth, inertial, cinema-grade movement.
#   Eliminates jitter, overshoot, and robotic response while preserving intent.
#
# Cinematic principle:
#   Cameras do not "teleport velocity".
#   They accelerate, coast, and settle.
#
# Inputs:
#   - Desired velocity vector (vx, vy, vz)
#   - Previous velocity state
#   - Frame delta time
#
# Output:
#   Smoothed velocity vector (vx, vy, vz)
#
# Notes:
#   - This operates BEFORE autopilot safety constraints
#   - Autopilot still enforces absolute limits
#
# ==============================================================================

import numpy as np
from typing import Tuple


class VelocityInertialDamper:
    """
    Applies critically-damped smoothing to velocity commands.
    """

    __slots__ = (
        "_response_time",
        "_max_accel",
        "_deadzone",
    )

    def __init__(
        self,
        response_time: float = 0.35,
        max_accel: float = 2.5,
        deadzone: float = 0.002,
    ):
        """
        response_time:
            Time constant for velocity convergence (seconds)
        max_accel:
            Maximum allowed acceleration magnitude (normalized units/sec^2)
        deadzone:
            Suppresses micro jitter near zero
        """
        self._response_time = max(response_time, 0.05)
        self._max_accel = max_accel
        self._deadzone = deadzone


    def _apply_deadzone(self, v: np.ndarray) -> np.ndarray:
        v[np.abs(v) < self._deadzone] = 0.0
        return v


    def _limit_accel(
        self,
        dv: np.ndarray,
        dt: float,
    ) -> np.ndarray:
        if dt <= 0:
            return np.zeros_like(dv)
        accel = dv / dt
        mag = np.linalg.norm(accel)
        if mag > self._max_accel:
            accel *= self._max_accel / mag
        return accel * dt


    def smooth(
        self,
        desired_velocity: Tuple[float, float, float],
        previous_velocity: Tuple[float, float, float],
        dt: float,
    ) -> Tuple[float, float, float]:
        """
        Smooth velocity using critically damped response.
        """
        desired = np.array(desired_velocity, dtype=np.float32)
        previous = np.array(previous_velocity, dtype=np.float32)
        # Compute ideal exponential convergence
        alpha = 1.0 - np.exp(-dt / self._response_time)
        target = previous + alpha * (desired - previous)
        # Acceleration limiting
        dv = target - previous
        dv_limited = self._limit_accel(dv, dt)
        smoothed = previous + dv_limited
        # Deadzone to remove micro jitter
        smoothed = self._apply_deadzone(smoothed)
        return float(smoothed[0]), float(smoothed[1]), float(smoothed[2])


