# END OF CHUNK 86 N 05
# ==============================================================================
# ==============================================================================
# CHUNK 86 O 01 — SHOT TYPE CLASSIFIER (WIDE / MEDIUM / CLOSE)
# ==============================================================================
#
# Purpose:
#   Classify shot intent into cinematic shot types using perception + context.
#   Drives framing, lens selection, motion limits, and transition rules.
#
# Inputs:
#   - Subject bounding boxes (from vision)
#   - Frame resolution & FOV
#   - Scene context (speed, altitude, environment)
#
# Outputs:
#   - ShotType enum: WIDE / MEDIUM / CLOSE
#   - Confidence score
#
# Notes:
#   - Model-agnostic: works with YOLO/DeepSORT outputs
#   - Deterministic + hysteresis to avoid flicker
#
# ==============================================================================

from enum import Enum
from typing import List, Tuple
import numpy as np


class ShotType(Enum):
    WIDE = 0
    MEDIUM = 1
    CLOSE = 2


class ShotTypeClassifier:
    """
    Cinematic shot classifier with temporal hysteresis.
    """

    __slots__ = (
        "_last_type",
        "_hold_frames",
        "_hold_counter",
        "_thresholds",
    )

    def __init__(
        self,
        thresholds: Tuple[float, float] = (0.12, 0.32),
        hold_frames: int = 12,
    ):
        """
        thresholds:
            Normalized subject area thresholds:
            (wide_to_medium, medium_to_close)
        hold_frames:
            Frames to hold classification before switching
        """
        self._thresholds = thresholds
        self._hold_frames = max(hold_frames, 1)
        self._last_type = ShotType.WIDE
        self._hold_counter = 0


    @staticmethod
    def _bbox_area_norm(
        bboxes: List[Tuple[int, int, int, int]],
        frame_w: int,
        frame_h: int,
    ) -> float:
        if not bboxes:
            return 0.0
        areas = []
        for x1, y1, x2, y2 in bboxes:
            w = max(0, x2 - x1)
            h = max(0, y2 - y1)
            areas.append(w * h)
        total = np.sum(areas)
        return float(total) / float(frame_w * frame_h + 1e-6)


    def _classify_raw(self, area_norm: float) -> ShotType:
        t_wm, t_mc = self._thresholds
        if area_norm < t_wm:
            return ShotType.WIDE
        elif area_norm < t_mc:
            return ShotType.MEDIUM
        return ShotType.CLOSE


    def classify(
        self,
        bboxes: List[Tuple[int, int, int, int]],
        frame_w: int,
        frame_h: int,
        scene_speed: float = 0.0,
    ) -> Tuple[ShotType, float]:
        """
        Returns (shot_type, confidence)
        """
        area_norm = self._bbox_area_norm(bboxes, frame_w, frame_h)
        raw = self._classify_raw(area_norm)
        # Speed bias: faster scenes favor wider shots
        if scene_speed > 0.6 and raw == ShotType.CLOSE:
            raw = ShotType.MEDIUM
        # Temporal hysteresis
        if raw != self._last_type:
            self._hold_counter += 1
            if self._hold_counter >= self._hold_frames:
                self._last_type = raw
                self._hold_counter = 0
        else:
            self._hold_counter = 0
        # Confidence based on distance from thresholds
        t_wm, t_mc = self._thresholds
        if self._last_type == ShotType.WIDE:
            conf = 1.0 - min(1.0, area_norm / (t_wm + 1e-6))
        elif self._last_type == ShotType.MEDIUM:
            conf = 1.0 - min(
                abs(area_norm - (t_wm + t_mc) * 0.5) / (t_mc - t_wm + 1e-6), 1.0
            )
        else:
            conf = min(1.0, (area_norm - t_mc) / (1.0 - t_mc + 1e-6))
        return self._last_type, float(np.clip(conf, 0.0, 1.0))


