# ==============================================================================
# CHUNK 86 O 02 — SHOT TRANSITION STYLE SELECTOR
# ==============================================================================
#
# Purpose:
#   Decide HOW to transition between shot types:
#   - Hard cut
#   - Motivated camera move (dolly/orbit/crane)
#   - Match-action continuity move
#
# Drives:
#   - Camera motion envelopes
#   - Cut eligibility flags
#   - Downstream flight vector smoothing
#
# Design:
#   Deterministic + context-aware (no randomness).
#   Temporal coherence prioritized over novelty.
#
# ==============================================================================

from enum import Enum
from typing import Dict, Tuple
import numpy as np


class TransitionStyle(Enum):
    HARD_CUT = 0
    MOTIVATED_MOVE = 1
    MATCH_ACTION = 2


class ShotTransitionSelector:
    """
    Cinematic transition decision engine.
    """

    __slots__ = (
        "_last_style",
        "_cooldown",
        "_cooldown_counter",
    )

    def __init__(self, cooldown_frames: int = 18):
        self._last_style = TransitionStyle.MOTIVATED_MOVE
        self._cooldown = max(1, cooldown_frames)
        self._cooldown_counter = 0


    def _motion_energy(self, velocity: np.ndarray) -> float:
        return float(np.linalg.norm(velocity))


    def _subject_motion_score(self, subject_delta: Tuple[float, float]) -> float:
        dx, dy = subject_delta
        return float(np.sqrt(dx * dx + dy * dy))


    def select(
        self,
        prev_shot,
        next_shot,
        camera_velocity: np.ndarray,
        subject_motion_px: Tuple[float, float],
        scene_context: Dict,
    ) -> TransitionStyle:
        """
        prev_shot / next_shot: ShotType
        camera_velocity: 3D velocity vector
        subject_motion_px: subject movement in pixels/frame
        scene_context:
            {
                "is_action": bool,
                "is_dialogue": bool,
                "altitude": float,
                "occlusion_risk": float
            }
        """

        energy = self._motion_energy(camera_velocity)
        subj_score = self._subject_motion_score(subject_motion_px)
        is_action = scene_context.get("is_action", False)
        is_dialogue = scene_context.get("is_dialogue", False)
        occlusion = scene_context.get("occlusion_risk", 0.0)

        # Cooldown to avoid rapid style flicker
        if self._cooldown_counter > 0:
            self._cooldown_counter -= 1
            return self._last_style

        # Rule 1: Match action during fast subject movement
        if subj_score > 6.0 and energy > 0.4:
            style = TransitionStyle.MATCH_ACTION

        # Rule 2: Hard cut for dialogue / low motion / high occlusion risk
        elif is_dialogue or (energy < 0.15 and subj_score < 1.0) or occlusion > 0.6:
            style = TransitionStyle.HARD_CUT

        # Rule 3: Motivated move for spatial continuity
        else:
            style = TransitionStyle.MOTIVATED_MOVE

        # Bias: avoid repeated hard cuts unless necessary
        if (
            style == TransitionStyle.HARD_CUT
            and self._last_style == TransitionStyle.HARD_CUT
            and not is_dialogue
        ):
            style = TransitionStyle.MOTIVATED_MOVE

        self._last_style = style
        self._cooldown_counter = self._cooldown
        return style


# ==============================================================================
# END OF CHUNK 86 O 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 O 03 — CUT VS MOVE DECISION ENGINE
# ==============================================================================
#
# Purpose:
#   Decide if the next transition should be executed as:
#     - Editorial cut (instant transition)
#     - Physical camera motion (drone + gimbal move)
#
# This is the FINAL gate before flight vectors are generated.
#
# Key goals:
#   - Avoid unnecessary drone motion
#   - Preserve cinematic continuity
#   - Reduce risk during high-speed or high-altitude shots
#
# ==============================================================================

from typing import Dict
import numpy as np


class CutMoveDecisionEngine:
    """
    Determines whether a transition should be a cut or a move.
    """

    __slots__ = (
        "_min_move_distance",
        "_max_safe_speed",
        "_altitude_bias",
    )

    def __init__(
        self,
        min_move_distance_m: float = 1.2,
        max_safe_speed: float = 8.0,
        altitude_bias: float = 1.4,
    ):
        """
        min_move_distance_m:
            Minimum spatial change required to justify a move
        max_safe_speed:
            Above this speed, prefer cuts
        altitude_bias:
            Penalize moves at high altitude (risk-aware)
        """
        self._min_move_distance = min_move_distance_m
        self._max_safe_speed = max_safe_speed
        self._altitude_bias = altitude_bias


    @staticmethod
    def _euclidean(a: np.ndarray, b: np.ndarray) -> float:
        return float(np.linalg.norm(a - b))


    def decide(
        self,
        current_cam_pos: np.ndarray,
        target_cam_pos: np.ndarray,
        current_velocity: np.ndarray,
        scene_context: Dict,
    ) -> bool:
        """
        Returns:
            True  -> execute MOVE
            False -> execute CUT
        scene_context keys:
            {
                "altitude": float,
                "battery": float,
                "gps_quality": float,
                "obstacle_density": float
            }
        """

        # Distance-based justification
        dist = self._euclidean(current_cam_pos, target_cam_pos)
        if dist < self._min_move_distance:
            return False

        speed = float(np.linalg.norm(current_velocity))
        if speed > self._max_safe_speed:
            return False

        altitude = scene_context.get("altitude", 0.0)
        altitude_penalty = 1.0 + (altitude / 30.0) * self._altitude_bias

        obstacle_density = scene_context.get("obstacle_density", 0.0)
        obstacle_penalty = 1.0 + obstacle_density * 2.5

        gps_quality = scene_context.get("gps_quality", 1.0)
        gps_penalty = 1.0 + (1.0 - gps_quality) * 3.0

        battery = scene_context.get("battery", 1.0)
        battery_penalty = 1.0 + max(0.0, 0.4 - battery) * 2.0

        risk_score = (
            altitude_penalty
            * obstacle_penalty
            * gps_penalty
            * battery_penalty
        )

        # Final decision metric
        move_score = dist / (risk_score + 1e-6)

        # Threshold empirically tuned for cinematic safety
        return move_score > 0.85


# ==============================================================================
# END OF CHUNK 86 O 03
# ==============================================================================
# ==============================================================================
# CHUNK 86 O 04 — MOTION CONTINUITY MEMORY
# ==============================================================================
#
# Purpose:
#   Maintain temporal continuity of camera intent and motion vectors.
#   Prevents abrupt changes in direction, speed, and framing logic.
#
# Inputs:
#   - Current desired camera vector (position / velocity)
#   - Shot type + transition intent
#
# Outputs:
#   - Smoothed, continuity-preserving motion vector
#
# Design:
#   - Exponential decay memory
#   - Intent-aware blending
#   - Hard reset on cut events
#
# ==============================================================================

from typing import Optional
import numpy as np


class MotionContinuityMemory:
    """
    Temporal motion memory for cinematic continuity.
    """

    __slots__ = (
        "_memory_vector",
        "_memory_weight",
        "_decay",
        "_last_shot_type",
    )

    def __init__(
        self,
        decay: float = 0.88,
        initial_weight: float = 0.6,
    ):
        """
        decay:
            Exponential decay factor per frame (0.0–1.0)
        initial_weight:
            Initial influence of past motion
        """
        self._decay = float(np.clip(decay, 0.0, 0.995))
        self._memory_weight = float(np.clip(initial_weight, 0.0, 1.0))
        self._memory_vector: Optional[np.ndarray] = None
        self._last_shot_type = None


    def reset(self):
        """
        Hard reset of continuity memory (used on editorial cuts).
        """
        self._memory_vector = None
        self._memory_weight = 0.0
        self._last_shot_type = None


    def update(
        self,
        desired_vector: np.ndarray,
        shot_type,
        is_cut: bool = False,
    ) -> np.ndarray:
        """
        Returns a continuity-smoothed motion vector.
        """
        desired_vector = desired_vector.astype(np.float32, copy=False)

        # Editorial cut => no continuity carryover
        if is_cut:
            self.reset()
            self._memory_vector = desired_vector.copy()
            self._memory_weight = 0.0
            self._last_shot_type = shot_type
            return desired_vector

        # Initialize memory
        if self._memory_vector is None:
            self._memory_vector = desired_vector.copy()
            self._last_shot_type = shot_type
            return desired_vector

        # Shot-type change reduces memory influence
        if shot_type != self._last_shot_type:
            self._memory_weight *= 0.5

        # Decay memory weight
        self._memory_weight *= self._decay

        # Blend vectors
        blended = (
            desired_vector * (1.0 - self._memory_weight)
            + self._memory_vector * self._memory_weight
        )

        # Update stored memory
        self._memory_vector = blended
        self._last_shot_type = shot_type

        return blended


# ==============================================================================
# END OF CHUNK 86 O 04
# ==============================================================================
# ==============================================================================
# CHUNK 86 O 05 — NARRATIVE RHYTHM CONTROLLER
# ==============================================================================
#
# Purpose:
#   Control the temporal rhythm of shots to match cinematic storytelling.
#   Regulates shot duration, pacing acceleration, and deceleration.
#
# Why this matters:
#   Hollywood cinematography is NOT spatial only — rhythm is everything.
#   This module governs when the AI should linger, rush, or breathe.
#
# Inputs:
#   - Scene energy
#   - Shot type
#   - Subject motion
#
# Outputs:
#   - Target shot duration
#   - Tempo multiplier for motion systems
#
# ==============================================================================

from typing import Dict, Tuple
import numpy as np


class NarrativeRhythmController:
    """
    Cinematic pacing controller.
    """

    __slots__ = (
        "_base_durations",
        "_tempo_memory",
        "_tempo_decay",
    )

    def __init__(self):
        # Base durations in seconds per shot type
        self._base_durations = {
            "WIDE": 4.8,
            "MEDIUM": 3.2,
            "CLOSE": 2.1,
        }
        self._tempo_memory = 1.0
        self._tempo_decay = 0.92


    def compute(
        self,
        shot_type,
        scene_context: Dict,
        subject_speed: float,
    ) -> Tuple[float, float]:
        """
        Returns:
            (target_duration_seconds, tempo_multiplier)
        scene_context keys:
            {
                "is_action": bool,
                "is_emotional": bool,
                "music_intensity": float (0–1)
            }
        """

        base = self._base_durations.get(str(shot_type), 3.0)

        is_action = scene_context.get("is_action", False)
        is_emotional = scene_context.get("is_emotional", False)
        music = float(scene_context.get("music_intensity", 0.0))

        # Scene energy estimation
        energy = (
            (1.2 if is_action else 0.8)
            + subject_speed * 0.4
            + music * 0.6
        )

        # Emotional scenes slow pacing
        if is_emotional:
            energy *= 0.75

        # Compute tempo multiplier
        tempo = np.clip(energy, 0.5, 2.0)

        # Smooth tempo transitions
        tempo = (
            self._tempo_memory * self._tempo_decay
            + tempo * (1.0 - self._tempo_decay)
        )
        self._tempo_memory = tempo

        # Duration inversely proportional to tempo
        duration = base / max(tempo, 1e-3)

        # Clamp for cinematic realism
        duration = float(np.clip(duration, 1.2, 8.0))

        return duration, tempo


# ==============================================================================
# END OF CHUNK 86 O 05
# ==============================================================================
# ==============================================================================
# CHUNK 86 P 01 — LENS & FOV STRATEGY ENGINE
# ==============================================================================
#
# Purpose:
#   Select an optimal cinematic lens profile (effective focal length & FOV)
#   based on shot intent, subject distance, motion, and narrative context.
#
# Why this matters:
#   Lens choice defines cinematic language more than resolution.
#   This engine emulates real DP decisions (ARRI / RED workflows).
#
# Inputs:
#   - ShotType (WIDE / MEDIUM / CLOSE)
#   - Subject distance (meters)
#   - Scene motion energy
#   - Desired background separation
#
# Outputs:
#   - Target focal length (35mm equivalent)
#   - Target horizontal FOV (degrees)
#
# ==============================================================================

from typing import Dict, Tuple
import numpy as np


class LensFOVStrategyEngine:
    """
    Cinematic lens selection logic.
    """

    __slots__ = (
        "_lens_sets",
        "_fov_smoothing",
        "_last_focal",
    )

    def __init__(self):
        # Cinematic prime lens sets (35mm equivalent)
        self._lens_sets = {
            "WIDE": np.array([18.0, 21.0, 24.0, 28.0, 35.0]),
            "MEDIUM": np.array([35.0, 40.0, 50.0, 65.0]),
            "CLOSE": np.array([65.0, 85.0, 100.0, 135.0]),
        }
        self._fov_smoothing = 0.85
        self._last_focal: float = 35.0


    @staticmethod
    def _focal_to_fov(focal_mm: float, sensor_width_mm: float = 36.0) -> float:
        """
        Convert focal length to horizontal FOV (degrees).
        """
        return float(
            2.0
            * np.degrees(
                np.arctan((sensor_width_mm * 0.5) / max(focal_mm, 1e-6))
            )
        )


    def _select_from_set(
        self,
        lens_set: np.ndarray,
        distance_m: float,
        motion_energy: float,
    ) -> float:
        """
        Choose focal length biased by distance & motion.
        """
        # Distance bias: closer subject -> longer focal
        dist_norm = np.clip(distance_m / 10.0, 0.0, 1.0)
        # Motion bias: faster motion -> wider lens
        motion_bias = np.clip(1.0 - motion_energy, 0.3, 1.0)
        idx_f = dist_norm * motion_bias * (len(lens_set) - 1)
        idx = int(np.clip(round(idx_f), 0, len(lens_set) - 1))
        return float(lens_set[idx])


    def resolve(
        self,
        shot_type,
        subject_distance_m: float,
        scene_context: Dict,
    ) -> Tuple[float, float]:
        """
        Returns:
            (focal_length_mm, horizontal_fov_deg)
        scene_context keys:
            {
                "motion_energy": float (0–1),
                "background_separation": float (0–1),
                "is_emotional": bool
            }
        """

        lens_set = self._lens_sets.get(str(shot_type), self._lens_sets["MEDIUM"])
        motion_energy = float(scene_context.get("motion_energy", 0.0))
        bg_sep = float(scene_context.get("background_separation", 0.5))
        is_emotional = scene_context.get("is_emotional", False)

        focal = self._select_from_set(lens_set, subject_distance_m, motion_energy)

        # Emotional scenes favor longer lenses
        if is_emotional:
            focal *= 1.15

        # Background separation bias
        focal *= np.clip(1.0 + bg_sep * 0.4, 1.0, 1.5)

        # Smooth focal transitions (avoid zoom jitter)
        focal = (
            self._last_focal * self._fov_smoothing
            + focal * (1.0 - self._fov_smoothing)
        )
        self._last_focal = focal

        fov = self._focal_to_fov(focal)
        return float(focal), float(fov)


# ==============================================================================
# END OF CHUNK 86 P 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 P 02 — DYNAMIC FOCAL LENGTH RESOLVER
# ==============================================================================
#
# Purpose:
#   Convert discrete lens intent into continuous, time-consistent focal changes.
#   Emulates real cinema zoom / lens swap behavior without perceptual jumps.
#
# Why this matters:
#   Human viewers immediately notice unnatural focal stepping.
#   This module enforces optical plausibility and cinematic smoothness.
#
# Inputs:
#   - Target focal length (from Lens Strategy)
#   - Shot duration & tempo
#   - Motion continuity state
#
# Outputs:
#   - Frame-by-frame focal length
#
# ==============================================================================

from typing import Optional
import numpy as np


class DynamicFocalLengthResolver:
    """
    Continuous focal length interpolator with cinematic constraints.
    """

    __slots__ = (
        "_current_focal",
        "_max_rate",
        "_min_rate",
        "_inertia",
    )

    def __init__(
        self,
        initial_focal: float = 35.0,
        max_rate_mm_per_s: float = 28.0,
        min_rate_mm_per_s: float = 4.0,
        inertia: float = 0.82,
    ):
        """
        max_rate_mm_per_s:
            Upper bound for zoom speed (prevents snap zooms)
        min_rate_mm_per_s:
            Lower bound to avoid imperceptible drift
        inertia:
            Resistance to rapid focal direction changes
        """
        self._current_focal = float(initial_focal)
        self._max_rate = float(max_rate_mm_per_s)
        self._min_rate = float(min_rate_mm_per_s)
        self._inertia = float(np.clip(inertia, 0.0, 0.98))


    def reset(self, focal: Optional[float] = None):
        if focal is not None:
            self._current_focal = float(focal)


    def update(
        self,
        target_focal: float,
        delta_time_s: float,
        tempo: float = 1.0,
    ) -> float:
        """
        Resolve next focal length step.
        """
        delta = target_focal - self._current_focal
        if abs(delta) < 1e-3:
            return self._current_focal
        # Tempo-modulated zoom speed
        rate = np.clip(
            abs(delta) * tempo,
            self._min_rate,
            self._max_rate,
        )
        step = np.sign(delta) * rate * delta_time_s
        # Inertia smoothing
        step = (
            step * (1.0 - self._inertia)
            + (target_focal - self._current_focal) * self._inertia * 0.05
        )
        # Clamp overshoot
        if abs(step) > abs(delta):
            step = delta
        self._current_focal += step
        return float(self._current_focal)


# ==============================================================================
# END OF CHUNK 86 P 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 P 03 — PERSPECTIVE COMPRESSION MODEL
# ==============================================================================
#
# Purpose:
#   Model real-world perspective compression effects caused by focal length.
#   Ensures spatial relationships scale correctly as lenses change.
#
# Why this matters:
#   Hollywood cinematography relies heavily on compression to:
#     - Stack backgrounds
#     - Isolate subjects
#     - Control perceived motion speed
#
# This module ensures focal length ≠ just FOV.
#
# ==============================================================================

from typing import Tuple
import numpy as np


class PerspectiveCompressionModel:
    """
    Computes perspective compression factors based on focal length.
    """

    __slots__ = (
        "_reference_focal",
        "_compression_curve",
    )

    def __init__(
        self,
        reference_focal_mm: float = 35.0,
        compression_curve: float = 0.65,
    ):
        """
        reference_focal_mm:
            Neutral perspective reference (35mm cinema baseline)
        compression_curve:
            Controls how aggressively compression scales (>0 cinematic)
        """
        self._reference_focal = float(reference_focal_mm)
        self._compression_curve = float(np.clip(compression_curve, 0.2, 1.2))


    def compute(
        self,
        focal_mm: float,
        subject_distance_m: float,
    ) -> Tuple[float, float]:
        """
        Returns:
            (depth_compression_factor, motion_scale_factor)
        depth_compression_factor:
            >1  => background pulled closer
        motion_scale_factor:
            <1  => motion appears slower (telephoto look)
        """

        focal_ratio = focal_mm / max(self._reference_focal, 1e-6)

        # Depth compression increases non-linearly with focal length
        depth_comp = np.power(focal_ratio, self._compression_curve)

        # Distance attenuates extreme compression
        dist_atten = np.clip(subject_distance_m / 15.0, 0.4, 1.0)
        depth_comp *= dist_atten

        # Motion scaling: longer lenses exaggerate shake, slow perceived motion
        motion_scale = 1.0 / np.sqrt(depth_comp + 1e-6)
        motion_scale = float(np.clip(motion_scale, 0.35, 1.1))

        return float(depth_comp), motion_scale


# ==============================================================================
# END OF CHUNK 86 P 03
# ==============================================================================
# ==============================================================================
# CHUNK 86 P 04 — PARALLAX CONSISTENCY CONTROLLER
# ==============================================================================
#
# Purpose:
#   Enforce physically-consistent parallax during camera translation/orbits.
#   Aligns foreground/background motion with lens compression and subject depth.
#
# Why this matters:
#   Cinematic realism collapses if near/far planes slide at incorrect rates.
#   This controller harmonizes parallax with focal length and motion vectors.
#
# Inputs:
#   - Camera lateral velocity
#   - Depth compression factor
#   - Subject depth estimate
#
# Outputs:
#   - Parallax-scaled motion multipliers (fg, subj, bg)
#
# ==============================================================================

from typing import Tuple
import numpy as np


class ParallaxConsistencyController:
    """
    Computes parallax multipliers for foreground, subject, and background layers.
    """

    __slots__ = (
        "_fg_gain",
        "_bg_gain",
        "_stability",
    )

    def __init__(
        self,
        foreground_gain: float = 1.35,
        background_gain: float = 0.65,
        stability: float = 0.9,
    ):
        """
        foreground_gain:
            Amplification for near-plane motion
        background_gain:
            Attenuation for far-plane motion
        stability:
            Temporal smoothing (0–1)
        """
        self._fg_gain = float(np.clip(foreground_gain, 1.0, 2.0))
        self._bg_gain = float(np.clip(background_gain, 0.3, 1.0))
        self._stability = float(np.clip(stability, 0.0, 0.98))


    def compute(
        self,
        lateral_velocity: np.ndarray,
        depth_compression: float,
        subject_depth_m: float,
    ) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """
        Returns:
            (fg_vec, subj_vec, bg_vec)
        """

        # Normalize velocity
        v = lateral_velocity.astype(np.float32, copy=False)

        # Depth normalization (closer subject => stronger parallax)
        depth_norm = np.clip(1.0 / max(subject_depth_m, 0.5), 0.3, 2.0)

        # Compression moderates parallax extremes
        comp = np.clip(depth_compression, 0.5, 3.0)

        fg_scale = self._fg_gain * depth_norm * comp
        subj_scale = 1.0
        bg_scale = self._bg_gain / max(comp, 1e-6)

        # Apply scaling
        fg_vec = v * fg_scale
        subj_vec = v * subj_scale
        bg_vec = v * bg_scale

        # Stability smoothing
        fg_vec *= self._stability
        subj_vec *= self._stability
        bg_vec *= self._stability

        return fg_vec, subj_vec, bg_vec


# ==============================================================================
# END OF CHUNK 86 P 04
# ==============================================================================
# ==============================================================================
# CHUNK 86 P 05 — BACKGROUND SEPARATION LOGIC
# ==============================================================================
#
# Purpose:
#   Quantify and enforce subject–background separation using depth, lens,
#   motion, and contrast cues (without fake blur or dust-tier tricks).
#
# Why this matters:
#   High-end cinema shots feel "layered". This module creates that separation
#   through physically-plausible cues instead of artificial post blur.
#
# Inputs:
#   - Subject depth & size
#   - Focal length & compression
#   - Relative motion (subject vs background)
#
# Outputs:
#   - Separation score (0–1)
#   - Separation guidance weights for downstream engines
#
# ==============================================================================

from typing import Dict, Tuple
import numpy as np


class BackgroundSeparationLogic:
    """
    Computes cinematic background separation strength.
    """

    __slots__ = (
        "_depth_weight",
        "_motion_weight",
        "_lens_weight",
    )

    def __init__(
        self,
        depth_weight: float = 0.45,
        motion_weight: float = 0.35,
        lens_weight: float = 0.20,
    ):
        """
        Weights sum to ~1.0 (intentionally not exact to allow bias).
        """
        self._depth_weight = float(np.clip(depth_weight, 0.0, 1.0))
        self._motion_weight = float(np.clip(motion_weight, 0.0, 1.0))
        self._lens_weight = float(np.clip(lens_weight, 0.0, 1.0))


    @staticmethod
    def _depth_score(subject_depth_m: float) -> float:
        # Closer subjects separate more strongly
        return float(np.clip(1.0 / max(subject_depth_m, 0.8), 0.0, 1.0))


    @staticmethod
    def _motion_score(
        subject_velocity: float,
        background_velocity: float,
    ) -> float:
        # Relative motion difference
        delta = abs(subject_velocity - background_velocity)
        return float(np.clip(delta / 3.5, 0.0, 1.0))


    @staticmethod
    def _lens_score(depth_compression: float) -> float:
        # Telephoto compression increases separation
        return float(np.clip((depth_compression - 1.0) * 0.6, 0.0, 1.0))


    def compute(
        self,
        subject_depth_m: float,
        subject_velocity: float,
        background_velocity: float,
        depth_compression: float,
    ) -> Tuple[float, Dict[str, float]]:
        """
        Returns:
            separation_score (0–1),
            guidance_weights {
                "contrast_bias",
                "motion_bias",
                "tone_bias"
            }
        """

        d = self._depth_score(subject_depth_m)
        m = self._motion_score(subject_velocity, background_velocity)
        l = self._lens_score(depth_compression)

        separation = (
            d * self._depth_weight
            + m * self._motion_weight
            + l * self._lens_weight
        )

        separation = float(np.clip(separation, 0.0, 1.0))

        # Guidance weights steer downstream processing
        guidance = {
            "contrast_bias": separation * 0.6,
            "motion_bias": separation * 0.3,
            "tone_bias": separation * 0.4,
        }

        return separation, guidance


# ==============================================================================
# END OF CHUNK 86 P 05
# ==============================================================================
# ==============================================================================
# CHUNK 86 P 06 — SUBJECT ISOLATION WEIGHTING
# ==============================================================================
#
# Purpose:
#   Convert separation metrics into stable, film-like isolation weights that
#   drive contrast, exposure, color priority, and motion emphasis — WITHOUT
#   fake masks or artificial blur.
#
# Core idea:
#   Cinema isolates subjects via:
#     - Micro-contrast prioritization
#     - Local exposure bias
#     - Motion salience
#     - Color energy allocation
#
#   This module computes isolation weights consumed by downstream engines
#   (tone, exposure, color, motion).
#
# Inputs:
#   - Separation score (from 86 P 05)
#   - Subject size (frame ratio)
#   - Subject confidence (vision certainty)
#
# Outputs:
#   - Isolation vector (multi-channel weighting)
#
# ==============================================================================

from typing import Dict
import numpy as np


class SubjectIsolationWeighting:
    """
    Computes perceptual isolation weights for cinematic pipelines.
    """

    __slots__ = (
        "_contrast_gain",
        "_exposure_gain",
        "_color_gain",
        "_motion_gain",
    )

    def __init__(
        self,
        contrast_gain: float = 1.15,
        exposure_gain: float = 0.85,
        color_gain: float = 0.90,
        motion_gain: float = 1.10,
    ):
        self._contrast_gain = float(contrast_gain)
        self._exposure_gain = float(exposure_gain)
        self._color_gain = float(color_gain)
        self._motion_gain = float(motion_gain)


    @staticmethod
    def _normalize(value: float, lo: float, hi: float) -> float:
        return float(np.clip((value - lo) / max(hi - lo, 1e-6), 0.0, 1.0))


    def compute(
        self,
        separation_score: float,
        subject_frame_ratio: float,
        subject_confidence: float,
    ) -> Dict[str, float]:
        """
        Args:
            separation_score: 0–1 (from background separation logic)
            subject_frame_ratio: fraction of frame occupied by subject
            subject_confidence: vision certainty (0–1)
        Returns:
            dict of isolation weights:
                contrast_weight
                exposure_weight
                color_weight
                motion_weight
        """

        sep = float(np.clip(separation_score, 0.0, 1.0))
        size = self._normalize(subject_frame_ratio, 0.05, 0.45)
        conf = float(np.clip(subject_confidence, 0.0, 1.0))

        # Perceptual dominance factor
        dominance = sep * (0.6 + 0.4 * conf) * (0.7 + 0.3 * size)

        dominance = float(np.clip(dominance, 0.0, 1.0))

        isolation = {
            "contrast_weight": dominance * self._contrast_gain,
            "exposure_weight": dominance * self._exposure_gain,
            "color_weight": dominance * self._color_gain,
            "motion_weight": dominance * self._motion_gain,
        }

        # Clamp outputs to safe cinematic bounds
        for k in isolation:
            isolation[k] = float(np.clip(isolation[k], 0.0, 1.25))

        return isolation


