# ==============================================================================
# CHUNK 86 P 07 — FOREGROUND–BACKGROUND DEPTH BALANCER
# ==============================================================================
#
# Purpose:
#   Maintain physically believable depth layering when camera or subject moves.
#   Prevents foreground from overpowering subject or background from collapsing.
#
# Why this is critical:
#   Hollywood shots maintain:
#     - Foreground motion energy (presence)
#     - Subject dominance (attention lock)
#     - Background stability (context)
#
#   This module dynamically rebalances depth energy in real-time.
#
# Inputs:
#   - Parallax vectors (fg, subj, bg)
#   - Isolation weights
#   - Camera motion magnitude
#
# Outputs:
#   - Balanced motion vectors for render + control layers
#
# ==============================================================================

import numpy as np
from typing import Tuple, Dict


class DepthBalancer:
    """
    Balances depth-layer motion energy for cinematic realism.
    """

    __slots__ = (
        "_fg_cap",
        "_bg_floor",
        "_subject_priority",
    )

    def __init__(
        self,
        foreground_cap: float = 1.6,
        background_floor: float = 0.35,
        subject_priority: float = 1.25,
    ):
        """
        foreground_cap:
            Maximum amplification allowed for near-plane motion
        background_floor:
            Minimum retained motion for far-plane context
        subject_priority:
            Boost factor ensuring subject dominance
        """
        self._fg_cap = float(np.clip(foreground_cap, 1.0, 2.5))
        self._bg_floor = float(np.clip(background_floor, 0.15, 0.6))
        self._subject_priority = float(np.clip(subject_priority, 1.0, 1.8))


    def apply(
        self,
        fg_vec: np.ndarray,
        subj_vec: np.ndarray,
        bg_vec: np.ndarray,
        isolation: Dict[str, float],
        camera_motion_mag: float,
    ) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """
        Returns balanced (fg, subj, bg) motion vectors.
        """

        cam_mag = float(np.clip(camera_motion_mag, 0.01, 10.0))

        # Subject dominance scaling
        subj_boost = self._subject_priority * isolation.get(
            "motion_weight", 1.0
        )

        subj_vec_bal = subj_vec * subj_boost

        # Foreground moderation
        fg_energy = np.linalg.norm(fg_vec) + 1e-6
        fg_limit = self._fg_cap * cam_mag

        if fg_energy > fg_limit:
            fg_vec_bal = fg_vec * (fg_limit / fg_energy)
        else:
            fg_vec_bal = fg_vec

        # Background stabilization
        bg_energy = np.linalg.norm(bg_vec) + 1e-6
        bg_min = self._bg_floor * cam_mag

        if bg_energy < bg_min:
            bg_vec_bal = bg_vec * (bg_min / bg_energy)
        else:
            bg_vec_bal = bg_vec

        return fg_vec_bal, subj_vec_bal, bg_vec_bal


