# ==============================================================================
# CHUNK 86 P 08 — CINEMATIC ZOOM EMOTIONAL BIAS
# ==============================================================================
#
# Purpose:
#   Encode emotional intent into zoom behavior.
#   Prevents robotic zooms and enforces film-language semantics.
#
# Emotional grammar:
#   Push-in  -> intimacy, discovery, empathy
#   Pull-out -> isolation, scale, dread
#
# This module biases zoom velocity, acceleration, and damping
# based on scene emotion, subject importance, and narrative phase.
#
# Inputs:
#   - Base zoom command (scalar)
#   - Scene emotion vector
#   - Subject saliency score
#   - Narrative phase (intro / build / climax / resolve)
#
# Outputs:
#   - Emotionally biased zoom command
#
# ==============================================================================

import numpy as np
from typing import Dict


class CinematicZoomBias:
    """
    Applies emotional intelligence to zoom behavior.
    """

    __slots__ = (
        "_max_gain",
        "_min_gain",
        "_phase_weights",
    )

    def __init__(
        self,
        max_gain: float = 1.8,
        min_gain: float = 0.6,
    ):
        self._max_gain = float(np.clip(max_gain, 1.2, 2.5))
        self._min_gain = float(np.clip(min_gain, 0.3, 0.9))

        # Narrative phase weighting
        self._phase_weights: Dict[str, float] = {
            "intro": 0.85,
            "build": 1.0,
            "climax": 1.35,
            "resolve": 0.75,
        }


    def apply(
        self,
        base_zoom: float,
        emotion: Dict[str, float],
        subject_saliency: float,
        narrative_phase: str,
    ) -> float:
        """
        Returns emotionally biased zoom scalar.
        Positive = push-in, Negative = pull-out
        """

        # Normalize inputs
        z = float(np.clip(base_zoom, -1.0, 1.0))
        sal = float(np.clip(subject_saliency, 0.0, 1.0))

        # Emotional intent extraction
        intimacy = emotion.get("intimacy", 0.0)
        tension = emotion.get("tension", 0.0)
        awe = emotion.get("awe", 0.0)

        # Directional intent
        intent = (
            0.7 * intimacy
            - 0.6 * tension
            - 0.8 * awe
        )

        # Subject dominance amplification
        intent *= (0.6 + 0.8 * sal)

        # Narrative phase modulation
        phase_w = self._phase_weights.get(narrative_phase, 1.0)
        intent *= phase_w

        # Convert intent into gain
        gain = np.clip(
            1.0 + intent,
            self._min_gain,
            self._max_gain,
        )

        # Apply to base zoom
        zoom_out = z * gain

        # Dead-zone damping to avoid micro-zoom jitter
        if abs(zoom_out) < 0.02:
            zoom_out = 0.0

        return float(np.clip(zoom_out, -1.0, 1.0))


