# ==============================================================================
# CHUNK 86 P 09 — OPTICAL BREATHING COMPENSATION
# ==============================================================================
#
# Purpose:
#   Compensate for focus-induced field-of-view changes ("lens breathing")
#   to preserve cinematic continuity during focus pulls.
#
# Why this matters:
#   • Consumer lenses visibly change FOV during focus shifts
#   • Cinema lenses are engineered to suppress this
#   • AI-controlled focus without compensation looks amateur
#
# This module:
#   • Estimates breathing magnitude from focus delta
#   • Applies inverse FOV correction
#   • Preserves subject scale during focus transitions
#
# Inputs:
#   - Focus distance (prev → current)
#   - Lens profile (breathing coefficient)
#   - Sensor crop factor
#
# Outputs:
#   - FOV correction scalar
#
# ==============================================================================

import numpy as np


class OpticalBreathingCompensator:
    """
    Compensates lens breathing to maintain stable framing.
    """

    __slots__ = (
        "_breathing_coeff",
        "_max_correction",
    )

    def __init__(
        self,
        breathing_coefficient: float = 0.045,
        max_correction: float = 0.08,
    ):
        """
        breathing_coefficient:
            Lens-specific breathing sensitivity
        max_correction:
            Hard clamp to prevent visible zoom artifacts
        """
        self._breathing_coeff = float(np.clip(breathing_coefficient, 0.01, 0.12))
        self._max_correction = float(np.clip(max_correction, 0.02, 0.15))


    def compute_correction(
        self,
        prev_focus_m: float,
        curr_focus_m: float,
        sensor_crop: float = 1.0,
    ) -> float:
        """
        Returns inverse FOV scale to counteract breathing.
        """

        # Focus delta in log space (perceptual)
        prev_f = max(prev_focus_m, 0.05)
        curr_f = max(curr_focus_m, 0.05)

        focus_delta = np.log(curr_f / prev_f)

        # Raw breathing estimate
        breathing = focus_delta * self._breathing_coeff

        # Apply sensor crop normalization
        breathing /= max(sensor_crop, 0.5)

        # Clamp correction
        breathing = float(
            np.clip(breathing, -self._max_correction, self._max_correction)
        )

        # Convert to inverse scale (zoom out if lens zoomed in)
        correction = 1.0 - breathing

        return float(np.clip(correction, 0.85, 1.15))


