# ==============================================================================
# ==============================================================================
# CHUNK 86 P 10 — FOCUS PULL INTENT GENERATOR
# ==============================================================================
#
# Purpose:
#   Generate narrative-aware focus pull intent curves rather than
#   reactive autofocus jumps.
#
# Why this matters:
#   • Cinema focus moves are intentional, not reactive
#   • Emotion, pacing, and subject hierarchy dictate timing
#   • AI must "decide" focus, not chase contrast
#
# This module:
#   • Converts scene intent → continuous focus trajectory
#   • Supports rack, hold, drift, and snap pulls
#   • Outputs time-parameterized focus distance curves
#
# Inputs:
#   - Subject depth ordering
#   - Narrative intent (reveal, tension, transition)
#   - Motion magnitude
#
# Outputs:
#   - Focus distance curve (meters vs time)
#
# ==============================================================================

import numpy as np
from typing import Dict, Literal


FocusMode = Literal["hold", "rack", "drift", "snap"]


class FocusPullIntentGenerator:
    """
    Produces cinematic focus pull trajectories.
    """

    __slots__ = (
        "_min_duration",
        "_max_duration",
        "_ease_strength",
    )

    def __init__(
        self,
        min_duration_s: float = 0.25,
        max_duration_s: float = 2.5,
        ease_strength: float = 0.85,
    ):
        """
        min_duration_s:
            Fastest allowed pull (prevents nervous focus)
        max_duration_s:
            Slowest allowed pull (prevents boredom)
        ease_strength:
            Controls S-curve softness
        """
        self._min_duration = float(np.clip(min_duration_s, 0.1, 0.6))
        self._max_duration = float(np.clip(max_duration_s, 1.0, 4.0))
        self._ease_strength = float(np.clip(ease_strength, 0.5, 0.95))


    def generate(
        self,
        start_focus_m: float,
        end_focus_m: float,
        intent: FocusMode,
        motion_energy: float,
        fps: int = 24,
    ) -> np.ndarray:
        """
        Returns per-frame focus distance curve.
        """

        start_f = max(start_focus_m, 0.05)
        end_f = max(end_focus_m, 0.05)

        # Duration scales with motion + distance
        dist_mag = abs(np.log(end_f / start_f))
        motion_factor = np.clip(motion_energy, 0.2, 2.0)

        base_duration = dist_mag * motion_factor
        duration_s = np.clip(
            base_duration,
            self._min_duration,
            self._max_duration,
        )

        total_frames = max(int(duration_s * fps), 2)

        t = np.linspace(0.0, 1.0, total_frames)

        if intent == "hold":
            curve = np.full(total_frames, start_f)

        elif intent == "snap":
            curve = np.concatenate(
                [
                    np.full(total_frames // 2, start_f),
                    np.full(total_frames - total_frames // 2, end_f),
                ]
            )

        else:
            # Smooth S-curve for rack/drift
            ease = 1 / (1 + np.exp(-((t - 0.5) * 12 * self._ease_strength)))
            if intent == "drift":
                ease = ease * 0.6  # softer transition

            log_f = np.log(start_f) + ease * np.log(end_f / start_f)
            curve = np.exp(log_f)

        return curve.astype(np.float32)


