# ==============================================================================
# CHUNK 86 Q 01 — TEMPORAL SHOT CONTINUITY MEMORY
# ==============================================================================
#
# Purpose:
#   Preserve cinematic continuity across time by remembering prior shot
#   decisions (framing, exposure bias, color mood, motion cadence).
#
# Why this matters:
#   • Cinema is not frame-by-frame optimization
#   • Continuity errors are immediately noticeable (jumping mood/exposure)
#   • Hollywood editors enforce continuity manually—AI must do it implicitly
#
# This module:
#   • Maintains a rolling temporal memory
#   • Applies inertia to prevent abrupt aesthetic changes
#   • Provides continuity hints to downstream modules
#
# Inputs:
#   - Shot decisions per frame
#   - Scene boundaries
#   - Motion & cut likelihood
#
# Outputs:
#   - Smoothed continuity state
#
# ==============================================================================

import numpy as np
from typing import Dict, Any


class TemporalShotMemory:
    """
    Rolling memory for cinematic continuity across frames and shots.
    """

    __slots__ = (
        "_memory",
        "_decay",
        "_hard_reset_threshold",
    )

    def __init__(
        self,
        decay: float = 0.92,
        hard_reset_threshold: float = 0.85,
    ):
        """
        decay:
            Exponential decay for older decisions
        hard_reset_threshold:
            Scene-cut confidence needed to reset memory
        """
        self._memory: Dict[str, float] = {}
        self._decay = float(np.clip(decay, 0.85, 0.98))
        self._hard_reset_threshold = float(
            np.clip(hard_reset_threshold, 0.6, 0.95)
        )


    def update(
        self,
        current: Dict[str, float],
        cut_confidence: float,
    ) -> Dict[str, float]:
        """
        Update continuity memory and return blended state.
        """

        # Hard reset on strong cut
        if cut_confidence >= self._hard_reset_threshold:
            self._memory = current.copy()
            return current

        blended: Dict[str, float] = {}

        for k, v in current.items():
            prev = self._memory.get(k, v)
            blended_val = prev * self._decay + v * (1.0 - self._decay)
            blended[k] = float(blended_val)

        # Decay unseen keys
        for k in list(self._memory.keys()):
            if k not in current:
                self._memory[k] *= self._decay
                blended[k] = float(self._memory[k])

        self._memory = blended
        return blended


    def get(self, key: str, default: float = 0.0) -> float:
        """
        Access a continuity value.
        """
        return float(self._memory.get(key, default))


    def snapshot(self) -> Dict[str, float]:
        """
        Return full continuity state.
        """
        return dict(self._memory)


