# ==============================================================================
# CHUNK 86 Q 02 — NARRATIVE MOMENTUM TRACKER
# ==============================================================================
#
# Purpose:
#   Track and regulate the perceived narrative speed of a scene to maintain
#   cinematic pacing consistency across shots.
#
# Why this matters:
#   • Films control momentum to guide emotion (tension, calm, release)
#   • AI that reacts only to visuals creates erratic pacing
#   • Viewers subconsciously detect pacing errors instantly
#
# This module:
#   • Estimates narrative momentum from motion, cuts, and framing change
#   • Applies inertia to prevent abrupt pacing shifts
#   • Feeds pacing hints to camera, focus, and flight planners
#
# Inputs:
#   - Motion energy
#   - Cut probability
#   - Framing delta
#
# Outputs:
#   - Normalized momentum scalar (0 = calm, 1 = intense)
#
# ==============================================================================

import numpy as np
from typing import Dict


class NarrativeMomentumTracker:
    """
    Tracks cinematic pacing over time.
    """

    __slots__ = (
        "_momentum",
        "_smoothing",
        "_gain",
    )

    def __init__(
        self,
        smoothing: float = 0.88,
        gain: float = 1.15,
    ):
        """
        smoothing:
            Temporal inertia for pacing changes
        gain:
            Sensitivity of momentum response
        """
        self._momentum = 0.0
        self._smoothing = float(np.clip(smoothing, 0.75, 0.95))
        self._gain = float(np.clip(gain, 0.8, 1.5))


    def update(
        self,
        motion_energy: float,
        cut_probability: float,
        framing_delta: float,
    ) -> float:
        """
        Update and return narrative momentum.
        """

        # Normalize inputs
        m = np.clip(motion_energy, 0.0, 2.0)
        c = np.clip(cut_probability, 0.0, 1.0)
        f = np.clip(framing_delta, 0.0, 1.5)

        # Raw momentum estimation
        raw = (
            0.45 * m +
            0.35 * c +
            0.20 * f
        )

        raw *= self._gain
        raw = float(np.clip(raw, 0.0, 1.0))

        # Apply temporal smoothing
        self._momentum = (
            self._momentum * self._smoothing +
            raw * (1.0 - self._smoothing)
        )

        return float(self._momentum)


    def get(self) -> float:
        """
        Current momentum value.
        """
        return float(self._momentum)


    def hints(self) -> Dict[str, float]:
        """
        Provide pacing hints for downstream systems.
        """
        return {
            "preferred_shot_duration": float(
                np.clip(3.0 - 2.0 * self._momentum, 0.8, 4.0)
            ),
            "camera_aggression": float(self._momentum),
            "focus_speed": float(0.5 + self._momentum),
        }


