# END OF CHUNK 86 Q 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 Q 03 — EMOTIONAL ARC CONSISTENCY FILTER
# ==============================================================================
#
# Purpose:
#   Enforce emotional continuity across shots so mood evolves smoothly
#   instead of oscillating due to local visual triggers.
#
# Why this matters:
#   • Cinema emotion progresses intentionally (build → peak → resolve)
#   • Viewers feel inconsistency instantly, even subconsciously
#   • AI reacting frame-by-frame destroys emotional coherence
#
# This module:
#   • Tracks emotional state over time
#   • Applies inertia and clamping to mood changes
#   • Harmonizes color, contrast, motion, and camera intent
#
# Inputs:
#   - Scene emotion estimate (valence, arousal)
#   - Narrative momentum
#   - Cut confidence
#
# Outputs:
#   - Stabilized emotional state vector
#
# ==============================================================================

import numpy as np
from typing import Tuple, Dict


class EmotionalArcFilter:
    """
    Maintains emotionally coherent progression across shots.
    """

    __slots__ = (
        "_valence",
        "_arousal",
        "_inertia",
        "_max_step",
    )

    def __init__(
        self,
        inertia: float = 0.9,
        max_step: float = 0.25,
    ):
        """
        inertia:
            Resistance to emotional change (higher = smoother arc)
        max_step:
            Maximum allowed emotional jump per update
        """
        self._valence = 0.0   # negative ↔ positive
        self._arousal = 0.0   # calm ↔ intense
        self._inertia = float(np.clip(inertia, 0.8, 0.97))
        self._max_step = float(np.clip(max_step, 0.1, 0.4))


    def update(
        self,
        estimated_valence: float,
        estimated_arousal: float,
        momentum: float,
        cut_confidence: float,
    ) -> Tuple[float, float]:
        """
        Update emotional arc and return (valence, arousal).
        """

        # Normalize inputs
        ev = float(np.clip(estimated_valence, -1.0, 1.0))
        ea = float(np.clip(estimated_arousal, 0.0, 1.0))
        mom = float(np.clip(momentum, 0.0, 1.0))

        # Emotional responsiveness increases with momentum
        responsiveness = 1.0 - self._inertia * (1.0 - mom)

        # Proposed deltas
        dv = (ev - self._valence) * responsiveness
        da = (ea - self._arousal) * responsiveness

        # Clamp jumps
        dv = float(np.clip(dv, -self._max_step, self._max_step))
        da = float(np.clip(da, -self._max_step, self._max_step))

        # Hard reset on confident cut
        if cut_confidence > 0.9:
            self._valence = ev
            self._arousal = ea
        else:
            self._valence += dv
            self._arousal += da

        # Final clamp
        self._valence = float(np.clip(self._valence, -1.0, 1.0))
        self._arousal = float(np.clip(self._arousal, 0.0, 1.0))

        return self._valence, self._arousal


    def mood_hints(self) -> Dict[str, float]:
        """
        Convert emotional state into downstream control hints.
        """
        return {
            "color_temperature_bias": float(self._valence),
            "contrast_bias": float(0.5 + 0.5 * self._arousal),
            "motion_smoothness": float(1.0 - 0.7 * self._arousal),
            "camera_aggression": float(self._arousal),
        }


