# END OF CHUNK 86 Q 03
# ==============================================================================
# ==============================================================================
# CHUNK 86 Q 04 — SUBJECT IMPORTANCE PERSISTENCE
# ==============================================================================
#
# Purpose:
#   Maintain stable subject priority over time so the AI does not
#   constantly re-rank attention based on transient visual changes.
#
# Why this matters:
#   • Humans expect the “main subject” to stay important
#   • Pure saliency-based systems flicker focus and framing
#   • Professional cinematography enforces subject continuity
#
# This module:
#   • Tracks subject importance with temporal inertia
#   • Allows slow decay, not instant drops
#   • Boosts narrative-relevant subjects automatically
#
# Inputs:
#   - Detected subjects + raw importance
#   - Narrative momentum
#   - Cut confidence
#
# Outputs:
#   - Persisted subject importance map
#
# ==============================================================================

import numpy as np
from typing import Dict


class SubjectImportancePersistence:
    """
    Maintains stable subject importance across frames and shots.
    """

    __slots__ = (
        "_importance",
        "_decay",
        "_boost_gain",
    )

    def __init__(
        self,
        decay: float = 0.93,
        boost_gain: float = 1.25,
    ):
        """
        decay:
            How slowly importance decays over time
        boost_gain:
            Multiplier for narratively important subjects
        """
        self._importance: Dict[str, float] = {}
        self._decay = float(np.clip(decay, 0.85, 0.98))
        self._boost_gain = float(np.clip(boost_gain, 1.0, 1.8))


    def update(
        self,
        detected: Dict[str, float],
        narrative_momentum: float,
        cut_confidence: float,
    ) -> Dict[str, float]:
        """
        Update and return persisted importance values.
        """

        # Reset on strong cut
        if cut_confidence > 0.9:
            self._importance = detected.copy()
            return detected

        updated: Dict[str, float] = {}

        for sid, raw_val in detected.items():
            prev = self._importance.get(sid, raw_val)
            blended = prev * self._decay + raw_val * (1.0 - self._decay)

            # Momentum increases dominance of key subjects
            blended *= 1.0 + narrative_momentum * (self._boost_gain - 1.0)

            updated[sid] = float(np.clip(blended, 0.0, 1.0))

        # Decay subjects no longer detected
        for sid in list(self._importance.keys()):
            if sid not in detected:
                self._importance[sid] *= self._decay
                if self._importance[sid] > 0.05:
                    updated[sid] = float(self._importance[sid])

        self._importance = updated
        return updated


    def primary_subject(self) -> str:
        """
        Return subject ID with highest importance.
        """
        if not self._importance:
            return ""
        return max(self._importance, key=self._importance.get)


