# END OF CHUNK 86 Q 04
# ==============================================================================
# ==============================================================================
# CHUNK 86 Q 05 — SCENE RHYTHM HARMONIZER
# ==============================================================================
#
# Purpose:
#   Harmonize shot duration, camera motion cadence, and edit pacing into
#   a coherent rhythmic pattern across a scene.
#
# Why this matters:
#   • Professional films have rhythmic “breathing”
#   • Random pacing feels amateur even with good visuals
#   • Rhythm synchronizes motion, cuts, and emotional beats
#
# This module:
#   • Derives a target rhythm from momentum + emotion
#   • Quantizes pacing into cinematic bands
#   • Outputs tempo hints for camera, focus, and edit timing
#
# Inputs:
#   - Narrative momentum
#   - Emotional arousal
#   - Recent shot durations
#
# Outputs:
#   - Rhythm state + timing hints
#
# ==============================================================================

import numpy as np
from typing import List, Dict


class SceneRhythmHarmonizer:
    """
    Maintains coherent cinematic rhythm across shots.
    """

    __slots__ = (
        "_tempo",
        "_inertia",
        "_bands",
    )

    def __init__(
        self,
        inertia: float = 0.9,
    ):
        """
        inertia:
            Resistance to tempo change
        """
        self._tempo = 0.5  # 0=slow, 1=fast
        self._inertia = float(np.clip(inertia, 0.8, 0.97))
        # Cinematic tempo bands (seconds per shot)
        self._bands = {
            "very_slow": (6.0, 10.0),
            "slow": (4.0, 6.0),
            "moderate": (2.5, 4.0),
            "fast": (1.5, 2.5),
            "very_fast": (0.7, 1.5),
        }


    def update(
        self,
        momentum: float,
        arousal: float,
        recent_shot_durations: List[float],
    ) -> Dict[str, float]:
        """
        Update rhythm state and return timing hints.
        """

        mom = float(np.clip(momentum, 0.0, 1.0))
        aro = float(np.clip(arousal, 0.0, 1.0))

        # Desired tempo driven by emotion + momentum
        desired = 0.6 * mom + 0.4 * aro

        # Smooth tempo evolution
        self._tempo = (
            self._tempo * self._inertia +
            desired * (1.0 - self._inertia)
        )

        self._tempo = float(np.clip(self._tempo, 0.0, 1.0))

        # Select tempo band
        if self._tempo < 0.15:
            band = "very_slow"
        elif self._tempo < 0.35:
            band = "slow"
        elif self._tempo < 0.6:
            band = "moderate"
        elif self._tempo < 0.8:
            band = "fast"
        else:
            band = "very_fast"

        lo, hi = self._bands[band]

        # Recent duration bias (avoid oscillation)
        if recent_shot_durations:
            avg = float(np.mean(recent_shot_durations[-5:]))
            target_duration = 0.6 * avg + 0.4 * ((lo + hi) * 0.5)
        else:
            target_duration = (lo + hi) * 0.5

        target_duration = float(np.clip(target_duration, lo, hi))

        return {
            "tempo": self._tempo,
            "tempo_band": band,
            "target_shot_duration": target_duration,
            "camera_motion_smoothness": float(1.0 - self._tempo * 0.6),
            "cut_frequency_hint": float(self._tempo),
        }


