# ==============================================================================
# CHUNK 86 Q 06 — CUT ANTICIPATION PREDICTOR
# ==============================================================================
#
# Purpose:
#   Predict imminent cuts and proactively adapt camera, motion, focus,
#   and grading so transitions feel intentional rather than abrupt.
#
# Why this matters:
#   • Editors prepare shots *before* a cut (ease motion, stabilize framing)
#   • AI that reacts after cuts feels jumpy and amateur
#   • Anticipation enables cinematic pre-roll and exit posture
#
# This module:
#   • Estimates cut likelihood from multi-signal cues
#   • Produces a short-horizon anticipation scalar
#   • Emits pre-cut adaptation hints
#
# Inputs:
#   - Motion acceleration
#   - Framing instability
#   - Narrative momentum spikes
#   - Rhythm pressure
#
# Outputs:
#   - Cut anticipation probability (0..1)
#   - Pre-cut control hints
#
# ==============================================================================

import numpy as np
from typing import Dict


class CutAnticipationPredictor:
    """
    Predicts near-future cuts and provides pre-cut adaptation hints.
    """

    __slots__ = (
        "_anticipation",
        "_smoothing",
        "_weights",
    )

    def __init__(
        self,
        smoothing: float = 0.9,
        weights: Dict[str, float] = None,
    ):
        """
        smoothing:
            Temporal inertia to prevent flicker
        weights:
            Contribution of signals to cut likelihood
        """
        self._anticipation = 0.0
        self._smoothing = float(np.clip(smoothing, 0.8, 0.97))
        self._weights = weights or {
            "motion_accel": 0.35,
            "framing_instability": 0.30,
            "momentum_spike": 0.20,
            "rhythm_pressure": 0.15,
        }


    def update(
        self,
        motion_accel: float,
        framing_instability: float,
        momentum_spike: float,
        rhythm_pressure: float,
    ) -> Dict[str, float]:
        """
        Update anticipation state and return probability + hints.
        """

        # Normalize inputs
        ma = np.clip(motion_accel, 0.0, 2.0)
        fi = np.clip(framing_instability, 0.0, 1.0)
        ms = np.clip(momentum_spike, 0.0, 1.0)
        rp = np.clip(rhythm_pressure, 0.0, 1.0)

        # Weighted likelihood
        raw = (
            self._weights["motion_accel"] * ma +
            self._weights["framing_instability"] * fi +
            self._weights["momentum_spike"] * ms +
            self._weights["rhythm_pressure"] * rp
        )

        raw = float(np.clip(raw, 0.0, 1.0))

        # Smooth anticipation
        self._anticipation = (
            self._anticipation * self._smoothing +
            raw * (1.0 - self._smoothing)
        )

        self._anticipation = float(np.clip(self._anticipation, 0.0, 1.0))

        # Pre-cut adaptation hints
        hints = {
            "ease_camera_motion": float(self._anticipation),
            "stabilize_framing": float(0.5 + 0.5 * self._anticipation),
            "reduce_focus_motion": float(self._anticipation),
            "pre_cut_hold_ms": float(120 + 380 * self._anticipation),
        }

        return {
            "cut_anticipation": self._anticipation,
            "hints": hints,
        }


    def get(self) -> float:
        """
        Current anticipation probability.
        """
        return float(self._anticipation)


