# ==============================================================================
# CHUNK 86 Q 07 — MULTI-SHOT INTENT RESOLVER
# ==============================================================================
#
# Purpose:
#   Resolve and stabilize intent when multiple shots contribute to a
#   single narrative goal (e.g., chase, reveal, dialogue exchange).
#
# Why this matters:
#   • Real cinematography plans shots as a sequence, not in isolation
#   • Conflicting intents create visual whiplash
#   • AI must maintain a dominant intent across shot boundaries
#
# This module:
#   • Aggregates per-shot intents over a rolling window
#   • Suppresses outlier intents
#   • Outputs a resolved, dominant intent with confidence
#
# Inputs:
#   - Current shot intent candidates
#   - Temporal continuity memory
#   - Narrative momentum
#
# Outputs:
#   - Resolved intent + confidence
#
# ==============================================================================

import numpy as np
from typing import Dict, Tuple


class MultiShotIntentResolver:
    """
    Resolves dominant cinematic intent across multiple shots.
    """

    __slots__ = (
        "_intent_scores",
        "_decay",
        "_confidence_floor",
    )

    def __init__(
        self,
        decay: float = 0.9,
        confidence_floor: float = 0.15,
    ):
        """
        decay:
            How quickly past intents fade
        confidence_floor:
            Minimum confidence to keep an intent alive
        """
        self._intent_scores: Dict[str, float] = {}
        self._decay = float(np.clip(decay, 0.8, 0.97))
        self._confidence_floor = float(
            np.clip(confidence_floor, 0.05, 0.3)
        )


    def update(
        self,
        current_intents: Dict[str, float],
        narrative_momentum: float,
    ) -> Tuple[str, float]:
        """
        Update intent state and return (dominant_intent, confidence).
        """

        # Decay existing intents
        for k in list(self._intent_scores.keys()):
            self._intent_scores[k] *= self._decay
            if self._intent_scores[k] < self._confidence_floor:
                del self._intent_scores[k]

        # Inject current intents
        for intent, score in current_intents.items():
            boosted = score * (1.0 + 0.5 * narrative_momentum)
            self._intent_scores[intent] = (
                self._intent_scores.get(intent, 0.0) + boosted
            )

        if not self._intent_scores:
            return "", 0.0

        # Normalize and select dominant intent
        total = sum(self._intent_scores.values()) + 1e-6
        for k in self._intent_scores:
            self._intent_scores[k] /= total

        dominant = max(self._intent_scores, key=self._intent_scores.get)
        confidence = float(self._intent_scores[dominant])

        return dominant, confidence


    def snapshot(self) -> Dict[str, float]:
        """
        Return normalized intent distribution.
        """
        return dict(self._intent_scores)


