# ==============================================================================
# CHUNK 86 Q 08 — LONG-TAKE STABILITY REGULATOR
# ==============================================================================
#
# Purpose:
#   Maintain perceptual stability during long, continuous shots
#   by damping oscillatory intent, motion, and framing decisions.
#
# Why this matters:
#   • Long takes amplify micro-instability
#   • Human viewers subconsciously expect "confident patience"
#   • Over-reactive AI ruins cinematic immersion
#
# This module:
#   • Detects long-take conditions
#   • Applies adaptive temporal damping
#   • Preserves slow, deliberate motion evolution
#
# Inputs:
#   - Shot duration
#   - Motion vector history
#   - Intent confidence
#
# Outputs:
#   - Stabilized motion / intent weights
#
# ==============================================================================

import numpy as np
from collections import deque
from typing import Deque, Tuple


class LongTakeStabilityRegulator:
    """
    Dampens decision volatility during extended shots.
    """

    __slots__ = (
        "_history",
        "_window",
        "_min_duration",
        "_base_damping",
    )

    def __init__(
        self,
        window: int = 24,
        min_duration_sec: float = 6.0,
        base_damping: float = 0.85,
    ):
        """
        window:
            Number of past frames considered
        min_duration_sec:
            Shot length threshold for long-take behavior
        base_damping:
            Core temporal damping factor
        """
        self._window = int(np.clip(window, 8, 64))
        self._min_duration = float(np.clip(min_duration_sec, 3.0, 20.0))
        self._base_damping = float(np.clip(base_damping, 0.7, 0.95))
        self._history: Deque[np.ndarray] = deque(maxlen=self._window)


    def update(
        self,
        motion_vector: np.ndarray,
        shot_duration_sec: float,
        intent_confidence: float,
    ) -> np.ndarray:
        """
        Returns stabilized motion vector.
        """

        mv = np.asarray(motion_vector, dtype=np.float32)
        self._history.append(mv)

        # If not a long take, return raw motion
        if shot_duration_sec < self._min_duration:
            return mv

        # Compute historical mean motion
        hist = np.stack(self._history, axis=0)
        mean_motion = np.mean(hist, axis=0)

        # Confidence-aware damping
        confidence_weight = np.clip(intent_confidence, 0.1, 1.0)
        damping = self._base_damping ** confidence_weight

        # Blend current motion with stabilized trajectory
        stabilized = (
            damping * mean_motion +
            (1.0 - damping) * mv
        )

        return stabilized


    def reset(self):
        """
        Clear temporal history.
        """
        self._history.clear()


