# ==============================================================================
# CHUNK 86 Q 10 — DIRECTOR OVERRIDE ARBITRATION
# ==============================================================================
#
# Purpose:
#   Deterministically arbitrate between:
#     • AI cinematic intent
#     • Human operator input
#     • Safety & system constraints
#
# Why this matters:
#   • Prevents command thrash (AI vs human)
#   • Ensures safety & continuity
#   • Preserves cinematic flow when overrides end
#
# Strategy:
#   Priority tiers + decay-based handoff:
#     1) Safety (hard override)
#     2) Human (soft override with decay)
#     3) AI Director (default)
#
# Outputs:
#   • Finalized control intent (camera + motion)
#
# ==============================================================================

import numpy as np
from typing import Dict, Any


class DirectorOverrideArbitrator:
    """
    Resolves control intent between AI, human input, and safety constraints.
    """

    __slots__ = (
        "_human_decay",
        "_human_strength",
        "_last_source",
    )

    def __init__(self, human_decay: float = 0.92):
        """
        human_decay:
            Per-frame decay applied after human input stops.
        """
        self._human_decay = float(np.clip(human_decay, 0.85, 0.99))
        self._human_strength = 0.0
        self._last_source = "ai"


    def update(
        self,
        ai_intent: Dict[str, Any],
        human_intent: Dict[str, Any] = None,
        safety_intent: Dict[str, Any] = None,
    ) -> Dict[str, Any]:
        """
        Return resolved intent dict.
        """

        # 1) Safety override (absolute)
        if safety_intent:
            self._human_strength = 0.0
            self._last_source = "safety"
            return safety_intent

        # 2) Human override (decays)
        if human_intent:
            self._human_strength = 1.0
            self._last_source = "human"
            return human_intent

        # Decay human influence
        self._human_strength *= self._human_decay

        if self._human_strength > 0.01:
            # Blend back to AI smoothly
            blended = {}
            for k in ai_intent:
                a = ai_intent.get(k, 0.0)
                h = human_intent.get(k, a) if human_intent else a
                w = self._human_strength
                blended[k] = (1.0 - w) * a + w * h
            self._last_source = "human→ai"
            return blended

        # 3) AI default
        self._last_source = "ai"
        return ai_intent


    @property
    def last_source(self) -> str:
        """
        Returns the source that last controlled the system.
        """
        return self._last_source


