# ==============================================================================
# CHUNK 86 R 01 — CROSS-SCENE VISUAL COHESION
# ==============================================================================
#
# Purpose:
#   Maintain perceptual continuity across consecutive scenes so
#   autonomous edits feel intentionally directed, not algorithmic.
#
# What this enforces:
#   • Color palette drift limits
#   • Contrast & exposure continuity
#   • Motion cadence consistency
#   • Framing intent persistence
#
# Why this matters:
#   Humans detect visual discontinuity instantly.
#   Feature films actively manage cross-scene cohesion—even across cuts.
#
# Inputs:
#   - Previous scene signature
#   - Current scene metrics
#
# Outputs:
#   - Cohesion-corrected scene parameters
#
# ==============================================================================

import numpy as np
from typing import Dict


class CrossSceneVisualCohesion:
    """
    Enforces continuity constraints across scene boundaries.
    """

    __slots__ = (
        "_prev_signature",
        "_color_strength",
        "_contrast_strength",
        "_motion_strength",
    )

    def __init__(
        self,
        color_strength: float = 0.65,
        contrast_strength: float = 0.55,
        motion_strength: float = 0.45,
    ):
        """
        Strength parameters control how strongly the previous scene
        influences the current one.
        """
        self._color_strength = float(np.clip(color_strength, 0.3, 0.9))
        self._contrast_strength = float(np.clip(contrast_strength, 0.3, 0.9))
        self._motion_strength = float(np.clip(motion_strength, 0.2, 0.8))
        self._prev_signature = None


    def extract_signature(self, scene_metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Reduce a scene to its perceptual signature.
        """
        return {
            "avg_hue": scene_metrics.get("avg_hue", 0.0),
            "avg_sat": scene_metrics.get("avg_sat", 0.0),
            "avg_luma": scene_metrics.get("avg_luma", 0.0),
            "contrast": scene_metrics.get("contrast", 0.0),
            "motion_energy": scene_metrics.get("motion_energy", 0.0),
            "framing_bias": scene_metrics.get("framing_bias", 0.0),
        }


    def apply(
        self,
        current_metrics: Dict[str, float],
    ) -> Dict[str, float]:
        """
        Apply cross-scene cohesion adjustments.
        """

        if self._prev_signature is None:
            self._prev_signature = self.extract_signature(current_metrics)
            return current_metrics

        out = dict(current_metrics)
        prev = self._prev_signature

        # Color cohesion
        out["avg_hue"] = (
            (1.0 - self._color_strength) * current_metrics["avg_hue"]
            + self._color_strength * prev["avg_hue"]
        )
        out["avg_sat"] = (
            (1.0 - self._color_strength) * current_metrics["avg_sat"]
            + self._color_strength * prev["avg_sat"]
        )

        # Exposure & contrast cohesion
        out["avg_luma"] = (
            (1.0 - self._contrast_strength) * current_metrics["avg_luma"]
            + self._contrast_strength * prev["avg_luma"]
        )
        out["contrast"] = (
            (1.0 - self._contrast_strength) * current_metrics["contrast"]
            + self._contrast_strength * prev["contrast"]
        )

        # Motion cadence cohesion
        out["motion_energy"] = (
            (1.0 - self._motion_strength) * current_metrics["motion_energy"]
            + self._motion_strength * prev["motion_energy"]
        )

        # Framing intent persistence
        out["framing_bias"] = (
            0.6 * current_metrics["framing_bias"]
            + 0.4 * prev["framing_bias"]
        )

        # Update signature for next scene
        self._prev_signature = self.extract_signature(out)
        return out


    def reset(self):
        """
        Reset cohesion history (e.g., hard cut or chapter break).
        """
        self._prev_signature = None


