# END OF CHUNK 86 R 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 R 02 — VISUAL MOTIF PERSISTENCE
# ==============================================================================
#
# Purpose:
#   Preserve and gently evolve recurring visual motifs across shots/scenes
#   (palette anchors, contrast signatures, framing biases), so autonomous
#   footage feels intentionally authored.
#
# Core ideas:
#   • Motifs are not frozen; they decay or evolve with narrative time
#   • Persistence strength adapts to scene similarity
#   • Sudden motif breaks require explicit reset
#
# Inputs:
#   - Scene metrics (color, contrast, motion, framing)
#   - Optional scene similarity score
#
# Outputs:
#   - Motif-corrected metrics
#
# ==============================================================================

import numpy as np
from typing import Dict, Optional


class VisualMotifPersistence:
    """
    Tracks and applies persistent visual motifs with controlled evolution.
    """

    __slots__ = (
        "_motif",
        "_decay",
        "_max_strength",
        "_min_strength",
    )

    def __init__(
        self,
        decay: float = 0.04,
        max_strength: float = 0.75,
        min_strength: float = 0.25,
    ):
        """
        decay:
            Natural motif fade per scene (prevents staleness).
        strength bounds:
            Clamp how much the motif can influence a scene.
        """
        self._decay = float(np.clip(decay, 0.0, 0.15))
        self._max_strength = float(np.clip(max_strength, 0.4, 0.9))
        self._min_strength = float(np.clip(min_strength, 0.1, 0.5))
        self._motif: Optional[Dict[str, float]] = None


    @staticmethod
    def _blend(a: float, b: float, w: float) -> float:
        return (1.0 - w) * a + w * b


    def _init_motif(self, metrics: Dict[str, float]) -> None:
        self._motif = {
            "hue": metrics.get("avg_hue", 0.0),
            "sat": metrics.get("avg_sat", 0.0),
            "luma": metrics.get("avg_luma", 0.0),
            "contrast": metrics.get("contrast", 0.0),
            "framing_bias": metrics.get("framing_bias", 0.0),
        }


    def apply(
        self,
        metrics: Dict[str, float],
        similarity: Optional[float] = None,
    ) -> Dict[str, float]:
        """
        Apply motif persistence.
        similarity:
            Optional [0..1] scene similarity score. Higher means stronger
            persistence.
        """
        if self._motif is None:
            self._init_motif(metrics)
            return metrics

        sim = 0.6 if similarity is None else float(np.clip(similarity, 0.0, 1.0))
        strength = np.clip(
            self._min_strength + sim * (self._max_strength - self._min_strength),
            self._min_strength,
            self._max_strength,
        )

        out = dict(metrics)

        # Apply motif blending
        out["avg_hue"] = self._blend(metrics["avg_hue"], self._motif["hue"], strength)
        out["avg_sat"] = self._blend(metrics["avg_sat"], self._motif["sat"], strength)
        out["avg_luma"] = self._blend(metrics["avg_luma"], self._motif["luma"], strength)
        out["contrast"] = self._blend(metrics["contrast"], self._motif["contrast"], strength)
        out["framing_bias"] = self._blend(
            metrics["framing_bias"], self._motif["framing_bias"], strength * 0.7
        )

        # Motif evolution (slow drift toward current scene)
        evolve = max(0.0, 1.0 - self._decay)
        self._motif["hue"] = self._blend(self._motif["hue"], out["avg_hue"], evolve)
        self._motif["sat"] = self._blend(self._motif["sat"], out["avg_sat"], evolve)
        self._motif["luma"] = self._blend(self._motif["luma"], out["avg_luma"], evolve)
        self._motif["contrast"] = self._blend(self._motif["contrast"], out["contrast"], evolve)
        self._motif["framing_bias"] = self._blend(
            self._motif["framing_bias"], out["framing_bias"], evolve
        )

        return out


    def reset(self) -> None:
        """
        Hard reset of motif (e.g., chapter break, explicit style change).
        """
        self._motif = None


