# ==============================================================================
# CHUNK 86 R 03 — EMOTIONAL CONTINUITY MAPPER
# ==============================================================================
#
# Purpose:
#   Maintain emotional coherence across shots and scenes by mapping
#   low-level visual signals (luma, color, motion, framing) into a
#   stable emotional trajectory.
#
# Why this matters:
#   Humans perceive emotion continuity before logic continuity.
#   Professional cinema deliberately manages emotional slope.
#
# Emotional axes modeled:
#   • Intensity      (calm ↔ energetic)
#   • Warmth         (cold ↔ warm)
#   • Tension        (relaxed ↔ stressed)
#   • Intimacy       (distant ↔ intimate)
#
# Inputs:
#   - Scene metrics
#
# Outputs:
#   - Emotion-stabilized scene metrics
#
# ==============================================================================

import numpy as np
from typing import Dict


class EmotionalContinuityMapper:
    """
    Tracks emotional state across scenes and prevents perceptual jumps.
    """

    __slots__ = (
        "_emotion_state",
        "_response_rate",
        "_max_delta",
    )

    def __init__(
        self,
        response_rate: float = 0.35,
        max_delta: float = 0.45,
    ):
        """
        response_rate:
            How quickly emotion adapts to new stimuli.
        max_delta:
            Maximum allowed emotional change per scene.
        """
        self._response_rate = float(np.clip(response_rate, 0.15, 0.6))
        self._max_delta = float(np.clip(max_delta, 0.2, 0.7))
        self._emotion_state = None


    def _infer_emotion(self, m: Dict[str, float]) -> Dict[str, float]:
        """
        Infer emotional axes from scene metrics.
        """
        return {
            "intensity": np.clip(
                0.5 * m.get("motion_energy", 0.0)
                + 0.5 * m.get("contrast", 0.0),
                0.0,
                1.0,
            ),
            "warmth": np.clip(
                0.7 * m.get("avg_sat", 0.0)
                + 0.3 * (m.get("avg_hue", 0.0) - 0.5),
                0.0,
                1.0,
            ),
            "tension": np.clip(
                0.6 * m.get("motion_energy", 0.0)
                + 0.4 * (1.0 - m.get("avg_luma", 0.0)),
                0.0,
                1.0,
            ),
            "intimacy": np.clip(
                0.6 * (1.0 - abs(m.get("framing_bias", 0.0)))
                + 0.4 * (1.0 - m.get("motion_energy", 0.0)),
                0.0,
                1.0,
            ),
        }


    def _limit_delta(self, prev: float, new: float) -> float:
        delta = new - prev
        delta = np.clip(delta, -self._max_delta, self._max_delta)
        return prev + delta


    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Apply emotional continuity constraints to scene metrics.
        """
        inferred = self._infer_emotion(metrics)

        if self._emotion_state is None:
            self._emotion_state = inferred
            return metrics

        stabilized = {}
        for k in inferred:
            prev = self._emotion_state[k]
            target = inferred[k]
            blended = (
                (1.0 - self._response_rate) * prev
                + self._response_rate * target
            )
            stabilized[k] = self._limit_delta(prev, blended)

        # Update emotional state
        self._emotion_state = stabilized

        out = dict(metrics)

        # Apply emotional stabilization back into scene parameters
        out["contrast"] *= 0.8 + 0.4 * stabilized["intensity"]
        out["avg_sat"] *= 0.85 + 0.3 * stabilized["warmth"]
        out["motion_energy"] *= 0.8 + 0.5 * stabilized["tension"]
        out["framing_bias"] *= 0.9 + 0.2 * (1.0 - stabilized["intimacy"])

        return out


    def reset(self) -> None:
        """
        Reset emotional continuity (e.g., explicit mood change).
        """
        self._emotion_state = None


