# ==============================================================================
# CHUNK 86 R 04 — NARRATIVE TENSION ACCUMULATOR
# ==============================================================================
#
# Purpose:
#   Model, accumulate, and release narrative tension across shots/scenes
#   so autonomous footage follows a deliberate dramatic arc rather than
#   random intensity fluctuations.
#
# Core concepts:
#   • Tension builds faster than it releases (cinema rule)
#   • Visual pressure (contrast, motion, framing) feeds tension
#   • Controlled release avoids viewer fatigue
#
# Inputs:
#   - Scene metrics (motion, contrast, luma, framing)
#
# Outputs:
#   - Tension-conditioned scene metrics
#
# ==============================================================================

import numpy as np
from typing import Dict


class NarrativeTensionAccumulator:
    """
    Accumulates narrative tension and regulates its release.
    """

    __slots__ = (
        "_tension",
        "_build_rate",
        "_release_rate",
        "_ceiling",
        "_floor",
    )

    def __init__(
        self,
        build_rate: float = 0.35,
        release_rate: float = 0.18,
        ceiling: float = 1.0,
        floor: float = 0.0,
    ):
        """
        build_rate:
            How quickly tension accumulates under pressure.
        release_rate:
            How slowly tension dissipates (slower than build).
        """
        self._build_rate = float(np.clip(build_rate, 0.15, 0.6))
        self._release_rate = float(np.clip(release_rate, 0.05, 0.35))
        self._ceiling = float(ceiling)
        self._floor = float(floor)
        self._tension = 0.0


    def _infer_pressure(self, m: Dict[str, float]) -> float:
        """
        Infer instantaneous dramatic pressure from visual metrics.
        """
        pressure = (
            0.45 * m.get("motion_energy", 0.0)
            + 0.35 * m.get("contrast", 0.0)
            + 0.20 * (1.0 - m.get("avg_luma", 0.0))
        )
        pressure += 0.15 * abs(m.get("framing_bias", 0.0))
        return float(np.clip(pressure, 0.0, 1.0))


    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Apply tension accumulation and regulation to scene metrics.
        """
        pressure = self._infer_pressure(metrics)

        if pressure > self._tension:
            # Build tension faster than release
            delta = self._build_rate * (pressure - self._tension)
        else:
            delta = self._release_rate * (pressure - self._tension)

        self._tension = np.clip(
            self._tension + delta,
            self._floor,
            self._ceiling,
        )

        out = dict(metrics)

        # Map accumulated tension back into visuals
        # Higher tension = tighter contrast & more kinetic feel
        out["contrast"] *= 0.85 + 0.5 * self._tension
        out["motion_energy"] *= 0.8 + 0.6 * self._tension

        # Subtle luma compression under high tension
        out["avg_luma"] *= 1.0 - 0.15 * self._tension

        # Framing pressure (edge bias increases with tension)
        out["framing_bias"] *= 0.9 + 0.4 * self._tension

        return out


    def force_release(self, strength: float = 1.0) -> None:
        """
        Explicit tension release (e.g., scene resolution).
        """
        strength = float(np.clip(strength, 0.0, 1.0))
        self._tension = np.clip(
            self._tension * (1.0 - 0.6 * strength),
            self._floor,
            self._ceiling,
        )


    def reset(self) -> None:
        """
        Hard reset of tension accumulator.
        """
        self._tension = 0.0


