# ==============================================================================
# CHUNK 86 R 05 — TEMPORAL PACING REGULATOR
# ==============================================================================
#
# Purpose:
#   Regulate temporal rhythm across shots so autonomous footage follows
#   intentional cinematic pacing (beats, pauses, accelerations).
#
# Why this matters:
#   Pacing is one of the strongest subconscious signals of professionalism.
#   Humans notice bad pacing before bad color.
#
# Core rules:
#   • Fast motion ≠ fast pacing (contrast, framing matter)
#   • Tension compresses time perception
#   • Emotional releases require temporal breathing space
#
# Inputs:
#   - Scene metrics
#   - Narrative tension (implicit via metrics)
#
# Outputs:
#   - Pacing-conditioned scene metrics
#
# ==============================================================================

import numpy as np
from typing import Dict


class TemporalPacingRegulator:
    """
    Regulates perceived pacing by shaping motion, contrast,
    and temporal emphasis.
    """

    __slots__ = (
        "_pace_state",
        "_adapt_rate",
        "_min_pace",
        "_max_pace",
    )

    def __init__(
        self,
        adapt_rate: float = 0.3,
        min_pace: float = 0.25,
        max_pace: float = 0.85,
    ):
        """
        adapt_rate:
            Speed at which pacing adapts to new scenes.
        pace bounds:
            Clamp perceived pacing to cinematic limits.
        """
        self._adapt_rate = float(np.clip(adapt_rate, 0.15, 0.6))
        self._min_pace = float(np.clip(min_pace, 0.1, 0.5))
        self._max_pace = float(np.clip(max_pace, 0.6, 1.0))
        self._pace_state = 0.5


    def _infer_pace(self, m: Dict[str, float]) -> float:
        """
        Infer perceived pacing from visual metrics.
        """
        pace = (
            0.4 * m.get("motion_energy", 0.0)
            + 0.25 * m.get("contrast", 0.0)
            + 0.2 * abs(m.get("framing_bias", 0.0))
            + 0.15 * (1.0 - m.get("avg_luma", 0.0))
        )
        return float(np.clip(pace, 0.0, 1.0))


    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Apply temporal pacing regulation.
        """
        inferred = self._infer_pace(metrics)

        # Smooth pacing changes
        self._pace_state = (
            (1.0 - self._adapt_rate) * self._pace_state
            + self._adapt_rate * inferred
        )
        self._pace_state = float(
            np.clip(self._pace_state, self._min_pace, self._max_pace)
        )

        out = dict(metrics)

        # High pacing compresses time perception
        out["motion_energy"] *= 0.85 + 0.6 * self._pace_state
        out["contrast"] *= 0.9 + 0.4 * self._pace_state

        # Low pacing expands visual breathing room
        slow_factor = 1.0 - self._pace_state
        out["avg_luma"] *= 1.0 + 0.15 * slow_factor
        out["framing_bias"] *= 0.95 + 0.2 * self._pace_state

        return out


    def reset(self) -> None:
        """
        Reset pacing (e.g., chapter boundary or montage break).
        """
        self._pace_state = 0.5


