# ==============================================================================
# CHUNK 86 R 06 — SHOT TRANSITION GRAMMAR
# ==============================================================================
#
# Purpose:
#   Define and enforce cinematic grammar for transitions between shots,
#   ensuring autonomous cuts feel motivated, smooth, and intentional.
#
# Why this matters:
#   Viewers subconsciously read meaning from HOW shots transition.
#   Random or abrupt transitions instantly break “film language”.
#
# Transition grammar modeled:
#   • Hard cut (impact, tension spikes)
#   • Soft cut (dialogue, continuity)
#   • Motion match cut (kinetic continuity)
#   • Luma-driven dissolve (emotional release)
#
# Inputs:
#   - Previous scene metrics
#   - Current scene metrics
#
# Outputs:
#   - Transition-conditioned scene metrics
#
# ==============================================================================

import numpy as np
from typing import Dict


class ShotTransitionGrammar:
    """
    Determines and enforces grammatically correct shot transitions.
    """

    __slots__ = (
        "_prev_metrics",
        "_cut_bias",
        "_dissolve_bias",
    )

    def __init__(
        self,
        cut_bias: float = 0.55,
        dissolve_bias: float = 0.45,
    ):
        """
        cut_bias:
            Preference toward hard/soft cuts.
        dissolve_bias:
            Preference toward dissolves when emotional continuity allows.
        """
        self._cut_bias = float(np.clip(cut_bias, 0.3, 0.8))
        self._dissolve_bias = float(np.clip(dissolve_bias, 0.2, 0.7))
        self._prev_metrics: Dict[str, float] | None = None


    def _infer_transition_type(
        self,
        prev: Dict[str, float],
        curr: Dict[str, float],
    ) -> str:
        """
        Infer appropriate transition type based on metric deltas.
        """
        delta_motion = abs(curr["motion_energy"] - prev["motion_energy"])
        delta_luma = abs(curr["avg_luma"] - prev["avg_luma"])
        delta_contrast = abs(curr["contrast"] - prev["contrast"])

        tension_jump = delta_motion + delta_contrast
        emotional_shift = delta_luma + delta_contrast

        if tension_jump > 0.7:
            return "hard_cut"
        if emotional_shift < 0.35 and self._dissolve_bias > 0.4:
            return "dissolve"
        if delta_motion < 0.25:
            return "motion_match"
        return "soft_cut"


    def apply(
        self,
        metrics: Dict[str, float],
    ) -> Dict[str, float]:
        """
        Apply transition grammar constraints.
        """
        if self._prev_metrics is None:
            self._prev_metrics = dict(metrics)
            return metrics

        transition = self._infer_transition_type(
            self._prev_metrics, metrics
        )

        out = dict(metrics)

        # Apply transition-specific conditioning
        if transition == "hard_cut":
            # Emphasize contrast & immediacy
            out["contrast"] *= 1.1
            out["motion_energy"] *= 1.05

        elif transition == "soft_cut":
            # Reduce perceptual shock
            out["contrast"] *= 0.95
            out["avg_luma"] *= 1.02

        elif transition == "motion_match":
            # Align motion vectors perceptually
            out["motion_energy"] = (
                0.7 * out["motion_energy"]
                + 0.3 * self._prev_metrics["motion_energy"]
            )

        elif transition == "dissolve":
            # Smooth emotional handoff
            out["avg_luma"] = (
                0.6 * out["avg_luma"]
                + 0.4 * self._prev_metrics["avg_luma"]
            )
            out["contrast"] *= 0.9

        # Update previous metrics
        self._prev_metrics = dict(out)
        return out


    def reset(self) -> None:
        """
        Reset transition history (explicit editorial break).
        """
        self._prev_metrics = None


