# ==============================================================================
# CHUNK 86 R 07 — CUT MOTIVATION ANALYZER
# ==============================================================================
#
# Purpose:
#   Ensure every cut is motivated by cinematic necessity rather than
#   algorithmic convenience. This module evaluates whether a cut is
#   justified by information gain, emotional shift, motion dynamics,
#   or narrative pressure.
#
# Why this matters:
#   Unmotivated cuts are immediately perceived as “AI-made”.
#   Professional cinema treats cuts as semantic operators.
#
# Cut motivations modeled:
#   • Information reveal
#   • Emotional progression
#   • Motion continuity / contrast
#   • Tension escalation or release
#
# Inputs:
#   - Previous scene metrics
#   - Current scene metrics
#
# Outputs:
#   - Motivation-weighted scene metrics
#
# ==============================================================================

import numpy as np
from typing import Dict


class CutMotivationAnalyzer:
    """
    Evaluates and enforces motivation behind shot cuts.
    """

    __slots__ = (
        "_prev_metrics",
        "_min_motivation",
    )

    def __init__(self, min_motivation: float = 0.25):
        """
        min_motivation:
            Minimum acceptable motivation score for a cut.
        """
        self._min_motivation = float(np.clip(min_motivation, 0.1, 0.6))
        self._prev_metrics: Dict[str, float] | None = None


    def _compute_motivation(
        self,
        prev: Dict[str, float],
        curr: Dict[str, float],
    ) -> float:
        """
        Compute motivation score for a cut.
        """
        info_gain = abs(curr["contrast"] - prev["contrast"]) + abs(
            curr["avg_luma"] - prev["avg_luma"]
        )

        emotional_shift = abs(curr["avg_sat"] - prev["avg_sat"]) + abs(
            curr["avg_hue"] - prev["avg_hue"]
        )

        motion_delta = abs(
            curr["motion_energy"] - prev["motion_energy"]
        )

        framing_change = abs(
            curr["framing_bias"] - prev["framing_bias"]
        )

        motivation = (
            0.35 * info_gain
            + 0.25 * emotional_shift
            + 0.25 * motion_delta
            + 0.15 * framing_change
        )

        return float(np.clip(motivation, 0.0, 1.0))


    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Apply cut motivation analysis.
        """
        if self._prev_metrics is None:
            self._prev_metrics = dict(metrics)
            return metrics

        motivation = self._compute_motivation(
            self._prev_metrics, metrics
        )

        out = dict(metrics)

        if motivation < self._min_motivation:
            # Damp unmotivated cut impact
            damp = 0.5 + 0.5 * motivation / self._min_motivation
            out["contrast"] *= damp
            out["motion_energy"] *= damp
            out["framing_bias"] *= damp

        # Update previous metrics
        self._prev_metrics = dict(out)
        return out


    def reset(self) -> None:
        """
        Reset cut motivation history.
        """
        self._prev_metrics = None


