# ==============================================================================
# CHUNK 86 R 08 — SCENE BOUNDARY INTELLIGENCE
# ==============================================================================
#
# Purpose:
#   Detect, validate, and reason about scene boundaries so autonomous
#   editing decisions feel intentional rather than arbitrary.
#
# Why this matters:
#   Poor scene boundary detection causes:
#     • Premature cuts
#     • Overstayed shots
#     • Emotional whiplash
#
# This module determines:
#   • Whether a scene should continue
#   • Whether a boundary is emerging
#   • Whether a hard or soft boundary is appropriate
#
# Inputs:
#   - Scene metrics (motion, luma, contrast, framing)
#   - Accumulated narrative tension (implicit)
#
# Outputs:
#   - Boundary-conditioned scene metrics
#
# ==============================================================================

import numpy as np
from typing import Dict


class SceneBoundaryIntelligence:
    """
    Infers and enforces scene boundary logic.
    """

    __slots__ = (
        "_boundary_pressure",
        "_build_rate",
        "_release_rate",
        "_threshold",
    )

    def __init__(
        self,
        build_rate: float = 0.28,
        release_rate: float = 0.18,
        threshold: float = 0.75,
    ):
        """
        build_rate:
            Speed at which boundary pressure accumulates.
        release_rate:
            How quickly pressure relaxes when continuation is justified.
        threshold:
            Pressure level at which a scene boundary is likely.
        """
        self._build_rate = float(np.clip(build_rate, 0.1, 0.6))
        self._release_rate = float(np.clip(release_rate, 0.05, 0.4))
        self._threshold = float(np.clip(threshold, 0.5, 0.9))
        self._boundary_pressure = 0.0


    def _infer_pressure(self, m: Dict[str, float]) -> float:
        """
        Infer boundary pressure from scene exhaustion signals.
        """
        pressure = (
            0.35 * m.get("motion_energy", 0.0)
            + 0.30 * abs(m.get("framing_bias", 0.0))
            + 0.20 * m.get("contrast", 0.0)
            + 0.15 * (1.0 - m.get("avg_luma", 0.0))
        )
        return float(np.clip(pressure, 0.0, 1.0))


    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Apply scene boundary intelligence.
        """
        pressure = self._infer_pressure(metrics)

        if pressure > self._boundary_pressure:
            delta = self._build_rate * (pressure - self._boundary_pressure)
        else:
            delta = self._release_rate * (pressure - self._boundary_pressure)

        self._boundary_pressure = float(
            np.clip(self._boundary_pressure + delta, 0.0, 1.0)
        )

        out = dict(metrics)

        if self._boundary_pressure > self._threshold:
            # Signal impending boundary: gently prepare visuals
            out["contrast"] *= 0.95
            out["motion_energy"] *= 0.9
            out["avg_luma"] *= 1.05

        return out


    def boundary_imminent(self) -> bool:
        """
        Whether a scene boundary is imminent.
        """
        return self._boundary_pressure > self._threshold


    def reset(self) -> None:
        """
        Reset boundary intelligence (after cut).
        """
        self._boundary_pressure = 0.0


