# ==============================================================================
# ==============================================================================
# CHUNK 86 R 09 — MULTI-SCENE ARC SYNTHESIS
# ==============================================================================
#
# Purpose:
#   Synthesize continuity, emotional trajectory, and visual progression
#   across multiple scenes so the film feels "directed", not reactive.
#
# Cinematic Rationale:
#   Top-tier cinema does NOT optimize scenes independently.
#   It enforces:
#     • Rising / falling emotional arcs
#     • Visual rhythm progression
#     • Intentional contrast between scenes
#
# This module:
#   - Tracks arc state across scenes
#   - Biases scene parameters toward narrative coherence
#   - Prevents repetitive visual plateaus
#
# Inputs:
#   - Scene metrics (per-scene summary)
#   - Boundary signals
#
# Outputs:
#   - Arc-conditioned scene parameters
#
# ==============================================================================

import numpy as np
from typing import Dict


class MultiSceneArcSynthesizer:
    """
    Maintains and enforces multi-scene cinematic arcs.
    """

    __slots__ = (
        "_arc_energy",
        "_arc_direction",
        "_memory",
        "_memory_decay",
    )

    def __init__(
        self,
        memory_decay: float = 0.92,
    ):
        """
        memory_decay:
            How long previous scenes influence the current arc.
        """
        self._arc_energy = 0.0
        self._arc_direction = 1.0  # +1 rising, -1 resolving
        self._memory = {
            "motion": 0.0,
            "contrast": 0.0,
            "luma": 0.0,
        }
        self._memory_decay = float(np.clip(memory_decay, 0.85, 0.98))


    def _update_memory(self, metrics: Dict[str, float]) -> None:
        """
        Update rolling scene memory.
        """
        self._memory["motion"] = (
            self._memory_decay * self._memory["motion"]
            + (1.0 - self._memory_decay) * metrics.get("motion_energy", 0.0)
        )
        self._memory["contrast"] = (
            self._memory_decay * self._memory["contrast"]
            + (1.0 - self._memory_decay) * metrics.get("contrast", 0.0)
        )
        self._memory["luma"] = (
            self._memory_decay * self._memory["luma"]
            + (1.0 - self._memory_decay) * metrics.get("avg_luma", 0.0)
        )


    def _infer_arc_direction(self, boundary_triggered: bool) -> None:
        """
        Determine whether arc should rise or resolve.
        """
        if boundary_triggered:
            # After a cut, encourage contrast or escalation
            self._arc_direction *= -1.0


    def apply(
        self,
        metrics: Dict[str, float],
        boundary_triggered: bool,
    ) -> Dict[str, float]:
        """
        Apply arc synthesis to scene metrics.
        """
        self._update_memory(metrics)
        self._infer_arc_direction(boundary_triggered)

        # Compute arc pressure
        arc_delta = (
            0.4 * metrics.get("motion_energy", 0.0)
            + 0.35 * metrics.get("contrast", 0.0)
            + 0.25 * (1.0 - metrics.get("avg_luma", 0.0))
        )

        self._arc_energy = float(
            np.clip(
                self._arc_energy
                + self._arc_direction * 0.15 * arc_delta,
                0.0,
                1.0,
            )
        )

        out = dict(metrics)

        # Enforce arc-aware adjustments
        if self._arc_direction > 0:
            # Rising arc: intensify carefully
            out["motion_energy"] *= 1.0 + 0.12 * self._arc_energy
            out["contrast"] *= 1.0 + 0.10 * self._arc_energy
        else:
            # Resolving arc: soften and open image
            out["motion_energy"] *= 1.0 - 0.15 * self._arc_energy
            out["contrast"] *= 1.0 - 0.12 * self._arc_energy
            out["avg_luma"] *= 1.0 + 0.08 * self._arc_energy

        # Prevent visual plateau (key cinematic failure mode)
        plateau = (
            abs(out["motion_energy"] - self._memory["motion"]) < 0.02
            and abs(out["contrast"] - self._memory["contrast"]) < 0.02
        )

        if plateau:
            out["contrast"] *= 1.05
            out["motion_energy"] *= 0.97

        return out


    def arc_state(self) -> Dict[str, float]:
        """
        Current arc diagnostic state.
        """
        return {
            "arc_energy": self._arc_energy,
            "arc_direction": self._arc_direction,
            "memory_motion": self._memory["motion"],
            "memory_contrast": self._memory["contrast"],
            "memory_luma": self._memory["luma"],
        }


    def reset(self) -> None:
        """
        Reset arc synthesis (hard narrative reset).
        """
        self._arc_energy = 0.0
        self._arc_direction = 1.0
        self._memory = {k: 0.0 for k in self._memory}


