# ==============================================================================
# CHUNK 86 R 10 — EDITORIAL INTENT HARMONIZER
# ==============================================================================
#
# Purpose:
#   Harmonize competing cinematic intents (motion, emotion, composition,
#   pacing) into a single coherent editorial directive.
#
# Why this matters:
#   Hollywood-grade editing is not about maximizing one metric.
#   It is about resolving *conflicts*:
#     - Motion vs. Stability
#     - Emotion vs. Readability
#     - Subject vs. Environment
#
#   This module acts as a "virtual editor-in-chief".
#
# Inputs:
#   - Scene metrics (motion, saliency, luma, contrast)
#   - Narrative pressure & arc signals
#
# Outputs:
#   - Harmonized editorial intent weights
#
# ==============================================================================

import numpy as np
from typing import Dict


class EditorialIntentHarmonizer:
    """
    Resolves competing cinematic objectives into a unified intent vector.
    """

    __slots__ = (
        "_memory",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.85):
        """
        inertia:
            Temporal smoothing of intent to avoid jittery editorial behavior.
        """
        self._inertia = float(np.clip(inertia, 0.6, 0.95))
        self._memory = {
            "motion_bias": 0.5,
            "stability_bias": 0.5,
            "emotion_bias": 0.5,
            "environment_bias": 0.5,
        }


    def _normalize(self, d: Dict[str, float]) -> Dict[str, float]:
        s = sum(max(v, 0.0) for v in d.values()) + 1e-6
        return {k: float(v / s) for k, v in d.items()}


    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Compute harmonized editorial intent.
        """
        raw_intent = {
            "motion_bias": metrics.get("motion_energy", 0.5),
            "stability_bias": 1.0 - metrics.get("motion_energy", 0.5),
            "emotion_bias": metrics.get("emotional_saliency", 0.5),
            "environment_bias": metrics.get("scene_scale", 0.5),
        }

        raw_intent = self._normalize(raw_intent)

        # Temporal inertia blending
        blended = {}
        for k, v in raw_intent.items():
            prev = self._memory.get(k, 0.5)
            blended[k] = (
                self._inertia * prev + (1.0 - self._inertia) * v
            )

        blended = self._normalize(blended)
        self._memory = blended

        return blended


    def reset(self) -> None:
        """
        Reset editorial memory (hard cut or chapter transition).
        """
        self._memory = {
            "motion_bias": 0.5,
            "stability_bias": 0.5,
            "emotion_bias": 0.5,
            "environment_bias": 0.5,
        }


