# END OF CHUNK 86 R 10
# ==============================================================================
# ==============================================================================
# CHUNK 86 S 01 — SCENE SALIENCY FUSION
# ==============================================================================
#
# Purpose:
#   Fuse multi-dimensional saliency signals into a single authoritative
#   scene importance field used by:
#     • shot persistence
#     • reframing bias
#     • exposure priority
#     • cut resistance
#
# Why this matters:
#   Hollywood-level cinematography is NOT about raw sharpness or color alone;
#   it is about *what the audience is guided to care about*.
#
# This module ensures the AI never treats all pixels equally.
#
# Inputs (per-frame / rolling):
#   - motion saliency
#   - contrast saliency
#   - subject probability maps
#   - narrative weight
#
# Outputs:
#   - unified saliency field (0–1)
#
# ==============================================================================

import numpy as np
from typing import Dict


class SceneSaliencyFusion:
    """
    Produces a unified saliency field that represents
    what *matters most* in the scene at this moment.
    """

    __slots__ = (
        "_motion_w",
        "_contrast_w",
        "_subject_w",
        "_narrative_w",
        "_temporal_memory",
    )

    def __init__(
        self,
        motion_weight: float = 0.30,
        contrast_weight: float = 0.20,
        subject_weight: float = 0.35,
        narrative_weight: float = 0.15,
        temporal_memory: float = 0.85,
    ):
        self._motion_w = motion_weight
        self._contrast_w = contrast_weight
        self._subject_w = subject_weight
        self._narrative_w = narrative_weight
        self._temporal_memory = temporal_memory


    def fuse(
        self,
        motion_map: np.ndarray,
        contrast_map: np.ndarray,
        subject_map: np.ndarray,
        narrative_scalar: float,
        prev_saliency: np.ndarray | None = None,
    ) -> np.ndarray:
        """
        Generate fused saliency map.
        """
        # Normalize inputs
        m = self._normalize(motion_map)
        c = self._normalize(contrast_map)
        s = self._normalize(subject_map)

        fused = (
            self._motion_w * m
            + self._contrast_w * c
            + self._subject_w * s
            + self._narrative_w * narrative_scalar
        )

        fused = self._normalize(fused)

        if prev_saliency is not None:
            fused = (
                self._temporal_memory * prev_saliency
                + (1.0 - self._temporal_memory) * fused
            )

        return self._normalize(fused)


    @staticmethod
    def _normalize(arr: np.ndarray) -> np.ndarray:
        amin = np.min(arr)
        amax = np.max(arr)
        if amax - amin < 1e-6:
            return np.zeros_like(arr)
        return (arr - amin) / (amax - amin)


