# END OF CHUNK 86 S 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 S 02 — SUBJECT DOMINANCE RESOLVER
# ==============================================================================
#
# Purpose:
#   Determine which subject MUST dominate the frame at any given time
#   based on cinematic priority, not raw detection confidence.
#
# Why this matters:
#   Many AI systems fail by:
#     • Over-weighting detection confidence
#     • Ignoring narrative relevance
#     • Oscillating between subjects
#
# This module introduces:
#   • Temporal dominance memory
#   • Narrative inertia
#   • Anti-flicker subject locking
#
# Inputs:
#   - Detected subjects with attributes
#   - Scene context metrics
#
# Outputs:
#   - Dominant subject ID
#   - Dominance confidence
#
# ==============================================================================

import numpy as np
from typing import List, Dict, Optional


class SubjectDominanceResolver:
    """
    Resolves which subject should dominate the frame.
    """

    __slots__ = (
        "_locked_id",
        "_lock_strength",
        "_decay_rate",
        "_switch_threshold",
    )

    def __init__(
        self,
        decay_rate: float = 0.06,
        switch_threshold: float = 0.22,
    ):
        """
        decay_rate:
            How quickly dominance lock decays over time.
        switch_threshold:
            Required dominance margin to justify switching subjects.
        """
        self._decay_rate = float(np.clip(decay_rate, 0.01, 0.2))
        self._switch_threshold = float(np.clip(switch_threshold, 0.1, 0.5))
        self._locked_id: Optional[int] = None
        self._lock_strength: float = 0.0


    def _score_subject(self, subj: Dict[str, float], scene: Dict[str, float]) -> float:
        """
        Cinematic dominance score.
        """
        score = (
            0.35 * subj.get("screen_area", 0.0)
            + 0.25 * subj.get("motion_energy", 0.0)
            + 0.20 * subj.get("semantic_importance", 0.0)
            + 0.10 * subj.get("gaze_alignment", 0.0)
            + 0.10 * scene.get("narrative_focus", 0.0)
        )
        return float(np.clip(score, 0.0, 1.0))


    def resolve(
        self,
        subjects: List[Dict[str, float]],
        scene_metrics: Dict[str, float],
    ) -> Dict[str, Optional[float]]:
        """
        Resolve dominant subject.
        """
        if not subjects:
            self._lock_strength = max(0.0, self._lock_strength - self._decay_rate)
            if self._lock_strength <= 0.0:
                self._locked_id = None
            return {"subject_id": None, "confidence": 0.0}

        scores = []
        for s in subjects:
            score = self._score_subject(s, scene_metrics)
            scores.append((s["id"], score))

        scores.sort(key=lambda x: x[1], reverse=True)
        top_id, top_score = scores[0]

        if self._locked_id is None:
            self._locked_id = top_id
            self._lock_strength = top_score
        else:
            if top_id == self._locked_id:
                self._lock_strength = min(1.0, self._lock_strength + top_score * 0.3)
            else:
                delta = top_score - self._lock_strength
                if delta > self._switch_threshold:
                    self._locked_id = top_id
                    self._lock_strength = top_score
                else:
                    self._lock_strength = max(
        0.0, self._lock_strength - self._decay_rate
                    )

        return {
            "subject_id": self._locked_id,
            "confidence": float(np.clip(self._lock_strength, 0.0, 1.0)),
        }


    def reset(self) -> None:
        """
        Force reset dominance state.
        """
        self._locked_id = None
        self._lock_strength = 0.0


