# END OF CHUNK 86 S 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 S 03 — MULTI-SUBJECT PRIORITY ENGINE
# ==============================================================================
#
# Purpose:
#   Resolve priority when multiple subjects compete for cinematic focus.
#   This is where footage stops feeling like "tracking"
#   and starts feeling "directed".
#
# Why this matters:
#   • Real scenes rarely have a single subject
#   • Hollywood shots dynamically re-weight subjects
#   • Priority is NOT static — it evolves per frame
#
# This engine:
#   • Scores subjects by cinematic importance
#   • Applies temporal hysteresis (no flicker)
#   • Outputs a dominant subject vector
#
# Inputs (per subject):
#   - Screen size
#   - Motion salience
#   - Framing centrality
#   - Historical dominance
#
# Outputs:
#   - Ordered subject priority list
#   - Dominant subject confidence
#
# ==============================================================================

import numpy as np
from typing import List, Dict


class MultiSubjectPriorityEngine:
    """
    Computes cinematic dominance among competing subjects.
    """

    __slots__ = (
        "_memory",
        "_decay",
        "_lock_bias",
    )

    def __init__(
        self,
        dominance_decay: float = 0.92,
        lock_bias: float = 0.35,
    ):
        """
        dominance_decay:
            Temporal smoothing of subject dominance.
        lock_bias:
            Bias toward previously dominant subject (prevents jitter).
        """
        self._decay = float(np.clip(dominance_decay, 0.85, 0.98))
        self._lock_bias = float(np.clip(lock_bias, 0.15, 0.6))
        self._memory: Dict[int, float] = {}


    def _score_subject(self, s: Dict[str, float]) -> float:
        """
        Compute instantaneous cinematic score.
        """
        return (
            0.40 * s.get("screen_area", 0.0)
            + 0.30 * s.get("motion", 0.0)
            + 0.20 * (1.0 - abs(s.get("frame_offset", 0.0)))
            + 0.10 * s.get("focus_confidence", 0.0)
        )


    def resolve(self, subjects: List[Dict[str, float]]) -> List[Dict[str, float]]:
        """
        Resolve priority ordering.
        """
        scored = []

        for idx, subj in enumerate(subjects):
            inst_score = self._score_subject(subj)

            prev = self._memory.get(idx, inst_score)
            blended = (
                self._decay * prev
                + (1.0 - self._decay) * inst_score
            )

            # Apply dominance lock bias
            blended += self._lock_bias * prev

            self._memory[idx] = blended

            out = dict(subj)
            out["cinematic_priority"] = blended
            scored.append(out)

        scored.sort(
            key=lambda s: s["cinematic_priority"],
            reverse=True,
        )

        return scored


    def dominant_subject(self, subjects: List[Dict[str, float]]) -> Dict[str, float]:
        """
        Return dominant subject only.
        """
        resolved = self.resolve(subjects)
        return resolved[0] if resolved else {}


    def reset(self) -> None:
        """
        Reset dominance memory (scene cut).
        """
        self._memory.clear()


