# ==============================================================================
# CHUNK 86 S 04 — TEMPORAL SALIENCY STABILIZATION
# ==============================================================================
#
# Purpose:
#   Prevent saliency flicker and editorial indecision by enforcing
#   temporal continuity in what the system considers "important".
#
# Why this matters:
#   Humans perceive meaning over TIME, not frames.
#   Unstable saliency destroys perceived intelligence and intent.
#
# This module:
#   • Smooths saliency importance across time
#   • Preserves dominant narrative focus
#   • Suppresses short-lived distractions
#
# Inputs:
#   - Per-frame saliency vectors
#   - Scene context weights
#
# Outputs:
#   - Temporally coherent saliency field
#
# ==============================================================================

import numpy as np
from collections import deque
from typing import Dict, List


class TemporalSaliencyStabilizer:
    """
    Stabilizes saliency signals over time to enforce cinematic continuity.
    """

    __slots__ = (
        "_history",
        "_window",
        "_decay",
        "_dominance_bias",
    )

    def __init__(
        self,
        window: int = 12,
        decay: float = 0.92,
        dominance_bias: float = 1.15,
    ):
        """
        window:
            Number of frames used for temporal smoothing.
        decay:
            Exponential decay applied to older saliency.
        dominance_bias:
            Bias that preserves primary subject importance.
        """
        self._window = max(4, int(window))
        self._decay = float(np.clip(decay, 0.85, 0.98))
        self._dominance_bias = float(np.clip(dominance_bias, 1.0, 1.3))
        self._history: deque = deque(maxlen=self._window)


    def _aggregate(self) -> Dict[str, float]:
        """
        Aggregate saliency history with decay.
        """
        accum: Dict[str, float] = {}
        weight_sum = 0.0

        for i, frame_sal in enumerate(reversed(self._history)):
            w = self._decay ** i
            weight_sum += w
            for k, v in frame_sal.items():
                accum[k] = accum.get(k, 0.0) + v * w

        if weight_sum > 0.0:
            for k in accum:
                accum[k] /= weight_sum

        return accum


    def apply(self, saliency: Dict[str, float]) -> Dict[str, float]:
        """
        Apply temporal stabilization to saliency map.
        """
        if not saliency:
            return saliency

        self._history.append(dict(saliency))
        stable = self._aggregate()

        # Identify dominant subject
        dominant_key = max(stable, key=stable.get)
        stable[dominant_key] *= self._dominance_bias

        # Renormalize
        total = sum(stable.values())
        if total > 0.0:
            for k in stable:
                stable[k] /= total

        return stable


    def reset(self) -> None:
        """
        Reset temporal history (on hard scene cut).
        """
        self._history.clear()


