# END OF CHUNK 86 S 04
# ==============================================================================
# ==============================================================================
# CHUNK 86 S 05 — TEMPORAL SCENE COHERENCE ENGINE
# ==============================================================================
#
# Purpose:
#   Maintain temporal coherence of visual, emotional, and motion attributes
#   across extended scene durations so autonomous cinematography feels
#   deliberately directed rather than algorithmically reactive.
#
# Why this matters:
#   Humans instantly detect temporal inconsistency.
#   This module prevents:
#     • Color mood drift
#     • Motion intent oscillation
#     • Exposure instability across seconds/minutes
#
# Operates above frame-level logic.
# Works at scene-time scale (seconds → minutes).
#
# ==============================================================================

import numpy as np
from typing import Dict


class TemporalSceneCoherenceEngine:
    """
    Enforces long-term coherence of scene attributes.
    """

    __slots__ = (
        "_state",
        "_inertia",
        "_memory_decay",
    )

    def __init__(
        self,
        inertia: float = 0.82,
        memory_decay: float = 0.015,
    ):
        """
        inertia:
            Resistance to abrupt changes (higher = more cinematic stability).
        memory_decay:
            Rate at which older scene state influence fades.
        """
        self._inertia = float(np.clip(inertia, 0.6, 0.95))
        self._memory_decay = float(np.clip(memory_decay, 0.005, 0.05))
        self._state: Dict[str, float] | None = None


    def _blend(self, prev: float, curr: float) -> float:
        return (
            self._inertia * prev
            + (1.0 - self._inertia) * curr
        )


    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Apply temporal coherence constraints to scene metrics.
        """
        if self._state is None:
            self._state = dict(metrics)
            return metrics

        out = {}
        for key, value in metrics.items():
            prev = self._state.get(key, value)
            out[key] = self._blend(prev, value)

        # Decay memory slowly to allow scene evolution
        for key in self._state:
            self._state[key] = (
                (1.0 - self._memory_decay) * self._state[key]
                + self._memory_decay * out.get(key, self._state[key])
            )

        return out


    def reset(self) -> None:
        """
        Explicit scene break (cut / chapter change).
        """
        self._state = None


