# END OF CHUNK 86 S 05
# ==============================================================================
# ==============================================================================
# CHUNK 86 S 06 — TEMPORAL SALIENCY PERSISTENCE
# ==============================================================================
#
# Purpose:
#   Maintain perceptual continuity of visual importance across time.
#   Prevents AI from "forgetting" what the audience is already engaged with.
#
# Why this matters:
#   Human viewers form short-term visual memory.
#   If saliency resets every frame, footage feels AI-generated and fake.
#
# This module:
#   • Tracks saliency inertia
#   • Preserves narrative focus across motion, cuts, exposure shifts
#   • Enables emotionally coherent shot progression
#
# Inputs:
#   - Current frame saliency map
#   - Prior temporal saliency state
#
# Outputs:
#   - Persistence-weighted saliency map
#
# ==============================================================================

import numpy as np
from typing import Optional


class TemporalSaliencyPersistence:
    """
    Maintains saliency continuity over time using perceptual inertia.
    """

    __slots__ = (
        "_memory",
        "_decay_rate",
        "_reinforce_rate",
        "_memory_floor",
    )

    def __init__(
        self,
        decay_rate: float = 0.12,
        reinforce_rate: float = 0.65,
        memory_floor: float = 0.08,
    ):
        """
        decay_rate:
            How quickly forgotten saliency fades.
        reinforce_rate:
            How strongly repeated saliency reinforces memory.
        memory_floor:
            Minimum retained awareness (prevents popping).
        """
        self._decay_rate = float(np.clip(decay_rate, 0.05, 0.25))
        self._reinforce_rate = float(np.clip(reinforce_rate, 0.4, 0.9))
        self._memory_floor = float(np.clip(memory_floor, 0.0, 0.15))
        self._memory: Optional[np.ndarray] = None


    def reset(self) -> None:
        """
        Clears saliency memory (hard scene cut).
        """
        self._memory = None


    def apply(self, saliency: np.ndarray) -> np.ndarray:
        """
        Apply temporal persistence to saliency map.
        """
        if self._memory is None:
            self._memory = saliency.copy()
            return saliency

        # Decay previous memory
        self._memory *= (1.0 - self._decay_rate)

        # Reinforce where current saliency agrees
        reinforce_mask = saliency > self._memory
        self._memory[reinforce_mask] += (
            self._reinforce_rate
            * (saliency[reinforce_mask] - self._memory[reinforce_mask])
        )

        # Enforce perceptual floor
        self._memory = np.maximum(self._memory, self._memory_floor)

        # Normalize safely
        max_val = np.max(self._memory)
        if max_val > 1e-6:
            self._memory /= max_val

        return self._memory.copy()


