# END OF CHUNK 86 S 06
# ==============================================================================
# ==============================================================================
# CHUNK 86 S 07 — SUBJECT CONTINUITY MEMORY
# ==============================================================================
#
# Purpose:
#   Maintain persistent subject identity, dominance, and cinematic importance
#   across time so autonomous shot decisions feel directed, not reactive.
#
# Why this matters:
#   • Prevents subject "popping" or loss between cuts
#   • Enables long-form follow shots with editorial awareness
#   • Preserves emotional focus across evolving compositions
#
# Inputs:
#   - Per-frame subject detections (ID, confidence, bbox, motion)
#   - Scene saliency metrics
#
# Outputs:
#   - Continuity-weighted subject priorities
#
# ==============================================================================

import numpy as np
from collections import defaultdict, deque
from typing import Dict, List


class SubjectContinuityMemory:
    """
    Maintains temporal memory of subjects to ensure cinematic continuity.
    """

    __slots__ = (
        "_memory",
        "_decay_rate",
        "_max_history",
    )

    def __init__(
        self,
        decay_rate: float = 0.12,
        max_history: int = 48,
    ):
        """
        decay_rate:
            Rate at which absent subjects fade from priority.
        max_history:
            Number of frames used for continuity smoothing.
        """
        self._decay_rate = float(np.clip(decay_rate, 0.02, 0.3))
        self._max_history = int(np.clip(max_history, 16, 120))
        self._memory = defaultdict(lambda: deque(maxlen=self._max_history))


    def _update_subject(
        self,
        sid: int,
        score: float,
        motion: float,
        size: float,
    ) -> None:
        """
        Update internal memory trace for a subject.
        """
        weighted_score = (
            0.45 * score +
            0.30 * motion +
            0.25 * size
        )
        self._memory[sid].append(float(np.clip(weighted_score, 0.0, 1.0)))


    def ingest(
        self,
        subjects: List[Dict[str, float]],
    ) -> None:
        """
        Ingest current frame subjects.
        """
        active_ids = set()

        for s in subjects:
            sid = int(s["id"])
            active_ids.add(sid)

            self._update_subject(
                sid=sid,
                score=s.get("confidence", 0.0),
                motion=s.get("motion", 0.0),
                size=s.get("size", 0.0),
            )

        # Decay subjects not seen this frame
        for sid in list(self._memory.keys()):
            if sid not in active_ids:
                if self._memory[sid]:
                    decayed = self._memory[sid][-1] * (1.0 - self._decay_rate)
                    self._memory[sid].append(decayed)
                if self._memory[sid][-1] < 0.05:
                    del self._memory[sid]


    def resolve_priorities(self) -> Dict[int, float]:
        """
        Compute continuity-aware priority per subject.
        """
        priorities = {}

        for sid, history in self._memory.items():
            if not history:
                continue

            # Exponentially favor consistency
            weights = np.linspace(0.6, 1.0, num=len(history))
            score = float(np.sum(np.array(history) * weights) / np.sum(weights))
            priorities[sid] = score

        return priorities


    def dominant_subject(self) -> int:
        """
        Returns the most continuity-significant subject ID.
        """
        priorities = self.resolve_priorities()
        if not priorities:
            return -1
        return max(priorities, key=priorities.get)


    def reset(self) -> None:
        """
        Clears all continuity memory.
        """
        self._memory.clear()


