# ==============================================================================
# CHUNK 86 S 08 — ATTENTION TRANSFER DYNAMICS
# ==============================================================================
#
# Purpose:
#   Model how viewer attention transfers between subjects over time,
#   ensuring cinematic focus shifts feel natural, intentional, and
#   emotionally coherent.
#
# Why this matters:
#   Abrupt or incorrect attention shifts instantly break cinematic
#   immersion. High-end films carefully choreograph when and how
#   attention leaves one subject and lands on another.
#
# This system:
#   • Tracks dominant subject attention
#   • Predicts transfer readiness
#   • Smoothly reallocates visual priority
#
# Inputs:
#   - Subject saliency scores
#   - Motion vectors
#   - Gaze direction estimates
#
# Outputs:
#   - Attention-weighted subject priorities
#
# ==============================================================================

import numpy as np
from typing import Dict, List


class AttentionTransferEngine:
    """
    Handles cinematic attention flow between multiple subjects.
    """

    __slots__ = (
        "_current_subject",
        "_attention_energy",
        "_transfer_threshold",
        "_decay_rate",
    )

    def __init__(
        self,
        transfer_threshold: float = 0.62,
        decay_rate: float = 0.14,
    ):
        """
        transfer_threshold:
            Minimum competing saliency required to trigger attention shift.
        decay_rate:
            Speed at which attention energy dissipates.
        """
        self._current_subject = None
        self._attention_energy = 0.0
        self._transfer_threshold = float(
            np.clip(transfer_threshold, 0.45, 0.8)
        )
        self._decay_rate = float(np.clip(decay_rate, 0.05, 0.3))


    def _normalize(self, values: Dict[str, float]) -> Dict[str, float]:
        total = sum(max(v, 0.0) for v in values.values()) + 1e-6
        return {k: max(v, 0.0) / total for k, v in values.items()}


    def update(
        self,
        saliency: Dict[str, float],
        motion: Dict[str, float],
        gaze: Dict[str, float],
    ) -> Dict[str, float]:
        """
        Update attention state and compute attention-weighted priorities.
        """
        combined = {}
        for k in saliency.keys():
            combined[k] = (
                0.5 * saliency.get(k, 0.0)
                + 0.3 * motion.get(k, 0.0)
                + 0.2 * gaze.get(k, 0.0)
            )

        combined = self._normalize(combined)

        dominant = max(combined, key=combined.get)
        dominant_value = combined[dominant]

        if self._current_subject is None:
            self._current_subject = dominant
            self._attention_energy = dominant_value
        else:
            if (
                dominant != self._current_subject
                and dominant_value > self._transfer_threshold
            ):
                self._attention_energy -= self._decay_rate
                if self._attention_energy <= 0.0:
                    self._current_subject = dominant
                    self._attention_energy = dominant_value
            else:
                self._attention_energy = min(
                    1.0,
                    self._attention_energy + dominant_value * 0.1,
                )

        # Bias priorities toward current subject
        output = {}
        for k, v in combined.items():
            if k == self._current_subject:
                output[k] = v * (1.2 + 0.5 * self._attention_energy)
            else:
                output[k] = v * (1.0 - 0.3 * self._attention_energy)

        return self._normalize(output)


    def current_focus(self) -> str:
        """
        Returns currently dominant subject.
        """
        return self._current_subject


