# ==============================================================================
# CHUNK 86 S 09 — TEMPORAL ATTENTION ARBITRATION ENGINE
# ==============================================================================
#
# Purpose:
#   Resolve temporal competition between multiple active subjects, motions,
#   and compositional forces over time.
#
# Why this matters:
#   Hollywood-level cinematography is NOT about detecting subjects —
#   it's about deciding WHO deserves attention NOW vs LATER.
#
#   This engine:
#     • Prevents attention flicker
#     • Enforces intentional focus persistence
#     • Enables smooth narrative-driven attention handoffs
#
# Inputs:
#   - Per-subject saliency scores
#   - Motion energy
#   - Narrative priority hints
#
# Outputs:
#   - Stabilized attention weights
#
# ==============================================================================

import numpy as np
from typing import Dict, List


class TemporalAttentionArbitrator:
    """
    Stabilizes attention over time using cinematic persistence rules.
    """

    __slots__ = (
        "_memory",
        "_decay",
        "_inertia",
        "_handoff_bias",
    )

    def __init__(
        self,
        decay: float = 0.12,
        inertia: float = 0.65,
        handoff_bias: float = 0.22,
    ):
        """
        decay:
            How quickly forgotten subjects lose influence.
        inertia:
            Resistance to attention switching.
        handoff_bias:
            How easily narrative importance overrides inertia.
        """
        self._decay = float(np.clip(decay, 0.05, 0.3))
        self._inertia = float(np.clip(inertia, 0.4, 0.9))
        self._handoff_bias = float(np.clip(handoff_bias, 0.1, 0.4))
        self._memory: Dict[str, float] = {}


    def _normalize(self, weights: Dict[str, float]) -> Dict[str, float]:
        s = sum(weights.values()) + 1e-6
        return {k: v / s for k, v in weights.items()}


    def apply(
        self,
        candidates: Dict[str, Dict[str, float]],
    ) -> Dict[str, float]:
        """
        candidates:
            {
                subject_id: {
                    "saliency": float,
                    "motion": float,
                    "narrative": float
                }
            }
        """
        updated: Dict[str, float] = {}

        # Step 1 — decay memory
        for k in list(self._memory.keys()):
            self._memory[k] *= (1.0 - self._decay)
            if self._memory[k] < 0.01:
                del self._memory[k]

        # Step 2 — compute raw scores
        for sid, m in candidates.items():
            raw = (
                0.45 * m.get("saliency", 0.0)
                + 0.30 * m.get("motion", 0.0)
                + 0.25 * m.get("narrative", 0.0)
            )
            prev = self._memory.get(sid, 0.0)
            blended = (
                self._inertia * prev
                + (1.0 - self._inertia) * raw
                + self._handoff_bias * m.get("narrative", 0.0)
            )
            updated[sid] = float(np.clip(blended, 0.0, 1.0))

        # Step 3 — normalize + commit memory
        normalized = self._normalize(updated)
        self._memory = dict(normalized)

        return normalized


    def dominant_subject(self) -> str:
        """
        Returns the currently dominant subject.
        """
        if not self._memory:
            return ""
        return max(self._memory.items(), key=lambda x: x[1])[0]


    def reset(self) -> None:
        """
        Clears temporal attention memory.
        """
        self._memory.clear()


