# ==============================================================================
# CHUNK 86 S 10 — SCENE COHERENCE STABILITY CONTROLLER
# ==============================================================================
#
# Purpose:
#   Maintain perceptual and emotional coherence across a scene by
#   suppressing unintended micro-variations while preserving intentional
#   cinematic evolution.
#
# Why this matters:
#   Even perfect shots feel "cheap" if coherence drifts frame-to-frame.
#   High-end cinema maintains invisible continuity across:
#     • Exposure
#     • Color mood
#     • Motion rhythm
#     • Framing intention
#
# This module acts as the final *scene-level stabilizer* before editorial
# decisions are made.
#
# Inputs:
#   - Aggregated scene metrics
#   - Historical scene state
#
# Outputs:
#   - Coherence-corrected metrics
#
# ==============================================================================

import numpy as np
from typing import Dict


class SceneCoherenceStabilityController:
    """
    Enforces scene-level coherence without killing cinematic intent.
    """

    __slots__ = (
        "_memory",
        "_lock_strength",
        "_drift_tolerance",
    )

    def __init__(
        self,
        lock_strength: float = 0.85,
        drift_tolerance: float = 0.12,
    ):
        """
        lock_strength:
            How strongly scene intent resists random drift.
        drift_tolerance:
            Allowed deviation before correction activates.
        """
        self._lock_strength = float(np.clip(lock_strength, 0.6, 0.95))
        self._drift_tolerance = float(np.clip(drift_tolerance, 0.05, 0.25))
        self._memory: Dict[str, float] = {}


    def _stabilize(self, key: str, value: float) -> float:
        """
        Stabilize a metric against unintended drift.
        """
        if key not in self._memory:
            self._memory[key] = value
            return value

        prev = self._memory[key]
        delta = value - prev

        if abs(delta) < self._drift_tolerance:
            stabilized = prev + delta * (1.0 - self._lock_strength)
        else:
            stabilized = value  # intentional change

        self._memory[key] = stabilized
        return stabilized


    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Apply coherence stabilization across key scene dimensions.
        """
        out = dict(metrics)

        for key in (
            "avg_luma",
            "contrast",
            "color_temperature",
            "motion_energy",
            "framing_bias",
        ):
            if key in out:
                out[key] = self._stabilize(key, out[key])

        return out


    def reset_scene(self) -> None:
        """
        Reset coherence memory on hard scene cut.
        """
        self._memory.clear()


