# ==============================================================================
# CHUNK 86 T 01 — TEMPORAL ATTENTION COHERENCE ENGINE
# ==============================================================================
#
# Purpose:
#   Maintain perceptual continuity of viewer attention across frames.
#   Prevents AI-driven framing, exposure, or emphasis from "flickering"
#   or oscillating between competing visual priorities.
#
# Why this matters:
#   Hollywood-level cinematography feels INTENTIONAL.
#   Attention shifts must feel motivated, not reactive.
#
# Core principles:
#   • Attention has inertia
#   • Dominant subjects decay slowly
#   • New subjects must earn dominance
#
# Inputs:
#   - Saliency maps
#   - Subject confidence scores
#   - Motion vectors
#
# Outputs:
#   - Coherence-weighted attention field
#
# ==============================================================================

import numpy as np
from typing import Dict


class TemporalAttentionCoherence:
    """
    Enforces cinematic-grade temporal attention stability.
    """

    __slots__ = (
        "_attention_state",
        "_decay_rate",
        "_lock_threshold",
        "_promotion_rate",
    )

    def __init__(
        self,
        decay_rate: float = 0.92,
        lock_threshold: float = 0.65,
        promotion_rate: float = 0.18,
    ):
        """
        decay_rate:
            How slowly existing attention decays (higher = more stable).
        lock_threshold:
            Confidence level required to lock attention.
        promotion_rate:
            Speed at which new contenders gain influence.
        """
        self._decay_rate = float(np.clip(decay_rate, 0.85, 0.98))
        self._lock_threshold = float(np.clip(lock_threshold, 0.5, 0.85))
        self._promotion_rate = float(np.clip(promotion_rate, 0.05, 0.35))
        self._attention_state: Dict[str, float] = {}


    def update(self, saliency: Dict[str, float]) -> Dict[str, float]:
        """
        Update attention state with new saliency observations.
        """
        updated = {}

        # Decay existing attention
        for k, v in self._attention_state.items():
            updated[k] = v * self._decay_rate

        # Promote new contenders
        for k, v in saliency.items():
            if k in updated:
                delta = self._promotion_rate * (v - updated[k])
                updated[k] += delta
            else:
                updated[k] = v * self._promotion_rate

        # Normalize
        total = sum(max(v, 0.0) for v in updated.values()) + 1e-6
        for k in updated:
            updated[k] /= total

        self._attention_state = updated
        return dict(updated)


    def dominant_subject(self) -> str | None:
        """
        Returns the currently dominant subject if locked.
        """
        if not self._attention_state:
            return None

        subject, confidence = max(
            self._attention_state.items(), key=lambda x: x[1]
        )

        if confidence >= self._lock_threshold:
            return subject
        return None


    def reset(self) -> None:
        """
        Reset attention coherence (scene cut).
        """
        self._attention_state.clear()


