# END OF CHUNK 86 T 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 T 02 — TEMPORAL RHYTHM COHERENCE ENGINE
# ==============================================================================
#
# Purpose:
#   Maintain perceptual rhythm consistency across shots and micro-edits.
#   Ensures pacing feels deliberate, cinematic, and emotionally aligned.
#
# Core idea:
#   Humans subconsciously detect timing irregularities long before
#   noticing color or grain. This engine enforces rhythm continuity
#   using perceptual tempo modeling rather than fixed durations.
#
# Inputs:
#   - Motion energy history
#   - Scene tension envelope
#   - Cut cadence history
#
# Outputs:
#   - Time-weighted pacing multipliers
#   - Edit stretch/compress hints
#
# ==============================================================================

import numpy as np
from collections import deque
from typing import Dict


class TemporalRhythmCoherence:
    """
    Maintains temporal pacing coherence across scenes.
    """

    __slots__ = (
        "_motion_hist",
        "_tension_hist",
        "_cadence_hist",
        "_window",
        "_target_rhythm",
    )

    def __init__(self, window: int = 48):
        self._window = int(np.clip(window, 24, 96))
        self._motion_hist = deque(maxlen=self._window)
        self._tension_hist = deque(maxlen=self._window)
        self._cadence_hist = deque(maxlen=self._window)
        self._target_rhythm = 1.0


    def _robust_mean(self, arr):
        if not arr:
            return 0.0
        a = np.asarray(arr, dtype=np.float32)
        lo, hi = np.percentile(a, [10, 90])
        return float(np.clip(a.mean(), lo, hi))


    def update(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Update rhythm model using current frame/scene metrics.
        """
        motion = metrics.get("motion_energy", 0.0)
        tension = metrics.get("scene_tension", 0.0)
        cadence = metrics.get("cut_interval", 1.0)

        self._motion_hist.append(motion)
        self._tension_hist.append(tension)
        self._cadence_hist.append(cadence)

        avg_motion = self._robust_mean(self._motion_hist)
        avg_tension = self._robust_mean(self._tension_hist)
        avg_cadence = self._robust_mean(self._cadence_hist)

        # Derive perceptual rhythm target
        rhythm = (
            0.45 * avg_motion
            + 0.35 * avg_tension
            + 0.20 * (1.0 / max(avg_cadence, 1e-3))
        )

        self._target_rhythm = float(
            np.clip(0.7 * self._target_rhythm + 0.3 * rhythm, 0.4, 2.2)
        )

        out = dict(metrics)

        # Apply rhythm compensation
        out["time_stretch"] = float(np.clip(1.0 / self._target_rhythm, 0.5, 1.5))
        out["motion_energy"] *= float(np.clip(self._target_rhythm, 0.8, 1.2))
        out["scene_tension"] *= float(np.clip(self._target_rhythm, 0.9, 1.15))

        return out


    def rhythm_state(self) -> float:
        """
        Current rhythm scalar ( >1 = faster, <1 = slower ).
        """
        return self._target_rhythm


    def reset(self) -> None:
        """
        Reset rhythm history (hard cut or chapter break).
        """
        self._motion_hist.clear()
        self._tension_hist.clear()
        self._cadence_hist.clear()
        self._target_rhythm = 1.0


