# ==============================================================================
# CHUNK 86 T 03 — TEMPORAL CONTINUITY ENFORCEMENT
# ==============================================================================
#
# Purpose:
#   Enforce high-level temporal continuity across frames and shots so that
#   autonomous edits feel deliberate, filmic, and emotionally coherent.
#
# Why this matters:
#   Humans subconsciously track:
#     • Exposure drift
#     • Color temperature drift
#     • Motion rhythm changes
#
#   If these change abruptly without narrative justification, the result
#   feels amateur — even if every frame is "technically correct".
#
# Inputs:
#   - Frame-level metrics (luma, chroma, motion vectors)
#   - Scene-level continuity state
#
# Outputs:
#   - Continuity-corrected metrics
#
# ==============================================================================

import numpy as np
from typing import Dict


class TemporalContinuityEnforcer:
    """
    Maintains perceptual continuity across time.
    """

    __slots__ = (
        "_ema_luma",
        "_ema_temp",
        "_ema_motion",
        "_alpha_fast",
        "_alpha_slow",
    )

    def __init__(
        self,
        alpha_fast: float = 0.35,
        alpha_slow: float = 0.08,
    ):
        """
        alpha_fast:
            Response speed for justified changes (cuts, emphasis).
        alpha_slow:
            Response speed for ambient continuity drift.
        """
        self._alpha_fast = float(np.clip(alpha_fast, 0.2, 0.6))
        self._alpha_slow = float(np.clip(alpha_slow, 0.02, 0.15))
        self._ema_luma = None
        self._ema_temp = None
        self._ema_motion = None


    def _ema(self, prev: float, new: float, alpha: float) -> float:
        return prev + alpha * (new - prev)


    def apply(
        self,
        metrics: Dict[str, float],
        cut_likely: bool = False,
    ) -> Dict[str, float]:
        """
        Apply temporal continuity constraints.
        """
        out = dict(metrics)
        alpha = self._alpha_fast if cut_likely else self._alpha_slow

        if self._ema_luma is None:
            self._ema_luma = metrics.get("avg_luma", 0.5)
            self._ema_temp = metrics.get("color_temp", 6500.0)
            self._ema_motion = metrics.get("motion_energy", 0.0)

        self._ema_luma = self._ema(
            self._ema_luma, metrics.get("avg_luma", self._ema_luma), alpha
        )
        self._ema_temp = self._ema(
            self._ema_temp, metrics.get("color_temp", self._ema_temp), alpha
        )
        self._ema_motion = self._ema(
            self._ema_motion, metrics.get("motion_energy", self._ema_motion), alpha
        )

        # Enforce continuity envelopes
        out["avg_luma"] = float(
            np.clip(metrics.get("avg_luma", 0.5), self._ema_luma * 0.92, self._ema_luma * 1.08)
        )
        out["color_temp"] = float(
            np.clip(metrics.get("color_temp", 6500.0), self._ema_temp * 0.95, self._ema_temp * 1.05)
        )
        out["motion_energy"] = float(
            np.clip(metrics.get("motion_energy", 0.0), self._ema_motion * 0.85, self._ema_motion * 1.15)
        )

        return out


    def reset(self) -> None:
        """
        Reset continuity state (hard scene cut).
        """
        self._ema_luma = None
        self._ema_temp = None
        self._ema_motion = None


