# ==============================================================================
# CHUNK 86 T 04 — TEMPORAL SHOT CONFIDENCE SMOOTHING
# ==============================================================================
#
# Purpose:
#   Stabilize shot-selection confidence over time to avoid
#   jitter, indecision, or oscillation between valid options.
#
# Cinematic Rationale:
#   Human directors commit to shots unless strong evidence appears.
#   This module creates confidence inertia with adaptive decay.
#
# ==============================================================================

import numpy as _np


class TemporalShotConfidenceSmoother:
    """
    Applies temporal smoothing to shot confidence vectors.
    """

    __slots__ = (
        "_state",
        "_decay_base",
        "_boost_threshold",
    )

    def __init__(
        self,
        decay_base: float = 0.94,
        boost_threshold: float = 0.22
    ):
        """
        decay_base:
            Baseline per-frame decay for confidence memory.
        boost_threshold:
            Required delta to override existing dominant shot.
        """
        self._state = {}
        self._decay_base = float(_np.clip(decay_base, 0.88, 0.98))
        self._boost_threshold = float(_np.clip(boost_threshold, 0.12, 0.35))


    def update(self, confidence_dict: dict) -> dict:
        """
        Update smoothed confidence values.
        Parameters:
            confidence_dict:
                Raw confidence scores per shot type.
        """

        if not self._state:
            self._state = confidence_dict.copy()
            return confidence_dict

        smoothed = {}

        # Identify current dominant shot
        prev_top = max(self._state, key=self._state.get)
        prev_val = self._state.get(prev_top, 0.0)

        for k, v in confidence_dict.items():
            prev = self._state.get(k, 0.0)

            # Adaptive decay:
            decay = self._decay_base
            if k == prev_top:
                decay = min(decay + 0.03, 0.99)

            blended = prev * decay + v * (1.0 - decay)
            smoothed[k] = blended

        # Enforce dominance inertia
        current_top = max(smoothed, key=smoothed.get)
        if current_top != prev_top:
            delta = smoothed[current_top] - smoothed[prev_top]
            if delta < self._boost_threshold:
                smoothed[prev_top] += delta * 0.65
                smoothed[current_top] -= delta * 0.65

        # Normalize
        total = sum(smoothed.values()) + 1e-6
        for k in smoothed:
            smoothed[k] /= total

        self._state = smoothed
        return smoothed


