# ==============================================================================
# CHUNK 86 T 05 — TEMPORAL CONTINUITY STABILIZATION
# ==============================================================================
#
# Purpose:
#   Enforce perceptual continuity across time so exposure, color,
#   contrast, and motion do not drift or jitter between frames or shots.
#
# Cinematic relevance:
#   Human vision is extremely sensitive to temporal inconsistency.
#   Even minor instability immediately reads as “digital” or “AI”.
#
# This module:
#   • Stabilizes tone evolution
#   • Dampens parameter oscillation
#   • Preserves intentional change while rejecting noise
#
# Inputs:
#   - Current frame metrics
#   - Temporal history buffer
#
# Outputs:
#   - Temporally stabilized metrics
#
# ==============================================================================

import numpy as np
from typing import Dict


class TemporalContinuityStabilizer:
    """
    Enforces smooth temporal evolution of cinematic parameters.
    """

    __slots__ = (
        "_history",
        "_window",
        "_stability_strength",
    )

    def __init__(
        self,
        window: int = 6,
        stability_strength: float = 0.75,
    ):
        """
        window:
            Number of previous frames used for temporal smoothing.
        stability_strength:
            Weight of historical influence vs current frame.
        """
        self._window = int(np.clip(window, 3, 12))
        self._stability_strength = float(np.clip(stability_strength, 0.5, 0.9))
        self._history: list[Dict[str, float]] = []


    def _temporal_mean(self) -> Dict[str, float]:
        """
        Compute temporal mean of stored history.
        """
        keys = self._history[0].keys()
        mean = {}
        for k in keys:
            mean[k] = float(
                np.mean([h[k] for h in self._history])
            )
        return mean


    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Apply temporal continuity stabilization.
        """
        if not self._history:
            self._history.append(dict(metrics))
            return metrics

        history_mean = self._temporal_mean()
        out = {}

        for k, v in metrics.items():
            stabilized = (
                self._stability_strength * history_mean[k]
                + (1.0 - self._stability_strength) * v
            )
            out[k] = float(stabilized)

        # Update history buffer
        self._history.append(dict(out))
        if len(self._history) > self._window:
            self._history.pop(0)

        return out


    def reset(self) -> None:
        """
        Reset temporal history (intentional stylistic break).
        """
        self._history.clear()


