# ==============================================================================
# CHUNK 86 T 06 — EMOTIONAL PEAK ANTICIPATION ENGINE (DIRECTOR-LEVEL)
# ==============================================================================
#
# Purpose:
#   Anticipate emotionally significant peaks with narrative awareness,
#   classify their semantic nature, and broadcast shot intent ahead of time
#   while enforcing cinematic restraint and post-peak recovery.
#
# This is NOT a signal amplifier.
# This is a director-cognition module.
#
# Core capabilities:
#   • Narrative phase–aware peak permission
#   • Emotional peak semantic classification
#   • Cross-system shot-intent broadcasting
#   • Automatic peak suppression / refractory control
#
# ==============================================================================

import numpy as np
from typing import Dict, Literal


NarrativePhase = Literal["SETUP", "DEVELOPMENT", "CLIMAX", "RESOLUTION"]
PeakType = Literal["AWE", "FEAR", "TRIUMPH", "LOSS", "NEUTRAL"]


class EmotionalPeakAnticipator:
    """
    Director-level anticipation engine.
    Determines not just IF a peak is coming,
    but WHETHER it should be allowed,
    WHAT KIND of peak it is,
    and HOW the shot language must prepare.
    """

    __slots__ = (
        "_history",
        "_window",
        "_anticipation_strength",
        "_last_peak_score",
        "_refractory_timer",
        "_refractory_length",
    )

    def __init__(
        self,
        window: int = 14,
        anticipation_strength: float = 0.9,
        refractory_length: int = 18,
    ):
        self._window = int(np.clip(window, 8, 32))
        self._anticipation_strength = float(
            np.clip(anticipation_strength, 0.7, 1.3)
        )
        self._refractory_length = int(np.clip(refractory_length, 8, 40))
        self._history = []
        self._last_peak_score = 0.0
        self._refractory_timer = 0


    # --------------------------------------------------------------------------
    # Narrative cognition
    # --------------------------------------------------------------------------

    def _narrative_gate(self, phase: NarrativePhase) -> float:
        """
        Control how freely peaks are allowed based on ACT position.
        """
        return {
            "SETUP": 0.35,        # Strong restraint
            "DEVELOPMENT": 0.65,  # Shaped peaks
            "CLIMAX": 1.00,       # Full release allowed
            "RESOLUTION": 0.45,   # Emotional settling
        }.get(phase, 0.6)


    # --------------------------------------------------------------------------
    # Trend & acceleration analysis
    # --------------------------------------------------------------------------

    def _compute_trend(self) -> float:
        if len(self._history) < 4:
            return 0.0

        h = np.array(self._history[-self._window :], dtype=np.float32)
        v = np.diff(h)
        a = np.diff(v)

        if a.size == 0:
            return 0.0

        accel = np.mean(np.clip(a, 0.0, None))
        return float(np.clip(accel * 4.0, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Emotional semantics
    # --------------------------------------------------------------------------

    def _classify_peak_type(self, m: Dict[str, float]) -> PeakType:
        """
        Infer emotional quality of the peak.
        """
        tension = m.get("scene_tension", 0.0)
        motion = m.get("motion_energy", 0.0)
        luma = m.get("avg_luma", 0.5)
        contrast = m.get("contrast", 0.5)

        if tension > 0.7 and luma < 0.45:
            return "FEAR"
        if motion > 0.75 and contrast > 0.65:
            return "TRIUMPH"
        if luma > 0.65 and motion < 0.4:
            return "AWE"
        if motion < 0.35 and contrast < 0.45:
            return "LOSS"

        return "NEUTRAL"


    # --------------------------------------------------------------------------
    # Main update
    # --------------------------------------------------------------------------

    def update(
        self,
        metrics: Dict[str, float],
        narrative_phase: NarrativePhase,
    ) -> Dict[str, float]:
        """
        Update anticipation state with full cinematic cognition.
        """

        momentum = float(metrics.get("emotional_momentum", 0.0))
        self._history.append(momentum)

        if len(self._history) > self._window * 2:
            self._history.pop(0)

        trend = self._compute_trend()

        # Base likelihood
        base_peak = np.clip((momentum - 0.55) * 2.2, 0.0, 1.0)

        # Narrative permission
        narrative_weight = self._narrative_gate(narrative_phase)

        # Refractory suppression
        if self._refractory_timer > 0:
            self._refractory_timer -= 1
            suppression = 0.25
        else:
            suppression = 1.0

        peak_likelihood = np.clip(
            (0.6 * base_peak + 0.4 * trend)
            * narrative_weight
            * suppression,
            0.0,
            1.0,
        )

        # Temporal smoothing
        peak_likelihood = (
            self._last_peak_score * 0.65 + peak_likelihood * 0.35
        )

        self._last_peak_score = peak_likelihood

        # Detect committed peak → trigger refractory window
        if peak_likelihood > 0.85:
            self._refractory_timer = self._refractory_length

        peak_type = self._classify_peak_type(metrics)

        # ------------------------------------------------------------------
        # Shot-intent broadcast (NOT hard control)
        # ------------------------------------------------------------------

        intent = {
            "AWE":     {"frame_expand": 1.15, "motion_soften": 0.9},
            "FEAR":    {"frame_tighten": 1.10, "shadow_bias": 1.1},
            "TRIUMPH": {"motion_expand": 1.15, "saturation_lift": 1.1},
            "LOSS":    {"motion_dampen": 0.85, "desat": 0.9},
            "NEUTRAL": {},
        }[peak_type]

        out = dict(metrics)

        bias = peak_likelihood * self._anticipation_strength

        out["contrast"] *= 1.0 + 0.05 * bias
        out["motion_energy"] *= 1.0 + 0.07 * bias
        out["avg_luma"] *= 1.0 - 0.03 * bias

        out["emotional_peak_likelihood"] = peak_likelihood
        out["emotional_peak_type"] = peak_type
        out["narrative_phase"] = narrative_phase
        out["shot_intent"] = intent
        out["peak_refractory_active"] = self._refractory_timer > 0

        return out


    def reset(self) -> None:
        """
        Hard reset (only for major narrative discontinuities).
        """
        self._history.clear()
        self._last_peak_score = 0.0
        self._refractory_timer = 0


# ==============================================================================
# END OF CHUNK 86 T 06 (PATCHED — DIRECTOR LEVEL)
# ==============================================================================
# ==============================================================================
# CHUNK 86 T 07 — RELEASE & RESOLUTION TIMING LOGIC
# ==============================================================================
#
# Purpose:
#   Govern how emotional energy is released after a peak and how the
#   system transitions into resolution without collapse, overextension,
#   or emotional whiplash.
#
# This module answers:
#   • How long should the emotion linger?
#   • How fast is it allowed to fall?
#   • When is restraint required instead of release?
#
# Cinema truth:
#   Emotion does not end at the peak.
#   The *aftermath* is where meaning is felt.
#
# ==============================================================================

import numpy as np
from typing import Dict, Literal


ResolutionMode = Literal[
    "LINGER",        # Let emotion breathe
    "CONTROLLED",    # Shaped descent
    "ABRUPT",        # Intentional snap (rare)
    "SUPPRESSED",   # Withheld release (false peak)
]


class EmotionalReleaseController:
    """
    Director-level controller for post-peak emotional behavior.
    Prevents:
        • Emotional cliff-drop
        • Endless plateau
        • Inflation through repeated peaks
    Enables:
        • Earned aftermath
        • Meaningful silence
        • Controlled descent into resolution
    """

    __slots__ = (
        "_cooldown",
        "_linger_timer",
        "_last_mode",
    )

    def __init__(
        self,
        base_linger: int = 20,
        base_cooldown: int = 14,
    ):
        self._cooldown = 0
        self._linger_timer = 0
        self._last_mode: ResolutionMode = "CONTROLLED"

        self._base_linger = int(np.clip(base_linger, 8, 60))
        self._base_cooldown = int(np.clip(base_cooldown, 6, 40))


    # --------------------------------------------------------------------------
    # Resolution mode decision
    # --------------------------------------------------------------------------

    def _select_mode(
        self,
        peak_strength: float,
        peak_type: str,
        narrative_phase: str,
    ) -> ResolutionMode:
        """
        Decide how emotion should resolve after a peak.
        """

        if peak_strength < 0.45:
            return "SUPPRESSED"

        if narrative_phase == "CLIMAX":
            if peak_type in ("LOSS", "AWE"):
                return "LINGER"
            return "CONTROLLED"

        if narrative_phase == "DEVELOPMENT":
            return "CONTROLLED"

        if narrative_phase == "SETUP":
            return "SUPPRESSED"

        if narrative_phase == "RESOLUTION":
            return "LINGER"

        return "CONTROLLED"


    # --------------------------------------------------------------------------
    # Main update
    # --------------------------------------------------------------------------

    def update(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Apply release shaping and resolution timing.
        """

        peak_likelihood = float(metrics.get("emotional_peak_likelihood", 0.0))
        peak_type = metrics.get("emotional_peak_type", "NEUTRAL")
        phase = metrics.get("narrative_phase", "DEVELOPMENT")

        mode = self._select_mode(peak_likelihood, peak_type, phase)
        self._last_mode = mode

        out = dict(metrics)

        # ------------------------------------------------------------------
        # Linger logic
        # ------------------------------------------------------------------

        if mode == "LINGER":
            if self._linger_timer <= 0:
                self._linger_timer = int(
                    self._base_linger * np.clip(peak_likelihood, 0.6, 1.2)
                )

            self._linger_timer -= 1

            out["contrast"] *= 1.0 + 0.04
            out["motion_energy"] *= 0.92
            out["avg_luma"] *= 1.0 - 0.02

        else:
            self._linger_timer = 0


        # ------------------------------------------------------------------
        # Controlled release
        # ------------------------------------------------------------------

        if mode == "CONTROLLED":
            fall_rate = 0.06 + 0.08 * peak_likelihood

            out["contrast"] *= 1.0 - fall_rate * 0.6
            out["motion_energy"] *= 1.0 - fall_rate
            out["avg_luma"] *= 1.0 + fall_rate * 0.4


        # ------------------------------------------------------------------
        # Suppressed release (false peak handling)
        # ------------------------------------------------------------------

        if mode == "SUPPRESSED":
            out["contrast"] *= 0.96
            out["motion_energy"] *= 0.90
            out["avg_luma"] *= 1.05


        # ------------------------------------------------------------------
        # Cooldown enforcement
        # ------------------------------------------------------------------

        if peak_likelihood > 0.85:
            self._cooldown = self._base_cooldown

        if self._cooldown > 0:
            self._cooldown -= 1
            out["peak_suppression_bias"] = 0.7
        else:
            out["peak_suppression_bias"] = 1.0


        out["resolution_mode"] = mode
        out["resolution_cooldown_active"] = self._cooldown > 0
        out["linger_active"] = self._linger_timer > 0

        return out


    def reset(self) -> None:
        """
        Reset release state (used only on hard narrative breaks).
        """
        self._cooldown = 0
        self._linger_timer = 0
        self._last_mode = "CONTROLLED"


# ==============================================================================
# END OF CHUNK 86 T 07
# ==============================================================================
# ==============================================================================
# CHUNK 86 U 01 — SHOT-TO-SHOT NARRATIVE COHERENCE
# ==============================================================================
#
# Purpose:
#   Maintain emotional, narrative, and perceptual coherence across shots
#   using a multi-axis affective state vector instead of scalar emotion.
#
# This chunk is the OFFICIAL transition point from:
#   scalar emotion  →  affective vector cognition
#
# Core responsibilities:
#   • Maintain a persistent emotional state vector
#   • Prevent incoherent emotional jumps between shots
#   • Shape transitions based on affect compatibility
#   • Provide a stable substrate for anticipation & release engines
#
# ==============================================================================

import numpy as np
from typing import Dict, List


AFFECT_AXES = (
    "tension",
    "awe",
    "grief",
    "relief",
    "triumph",
)


class AffectiveStateVector:
    """
    Persistent multi-axis emotional state.
    This represents how the audience currently *feels*,
    not what the frame technically contains.
    """

    __slots__ = (
        "_state",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.82):
        self._state: Dict[str, float] = {k: 0.0 for k in AFFECT_AXES}
        self._inertia = float(np.clip(inertia, 0.6, 0.95))


    def blend(self, incoming: Dict[str, float]) -> Dict[str, float]:
        """
        Blend incoming affect with inertia to preserve continuity.
        """
        out = {}

        for k in AFFECT_AXES:
            prev = self._state.get(k, 0.0)
            inc = float(incoming.get(k, 0.0))

            # Inertia prevents emotional whiplash
            v = prev * self._inertia + inc * (1.0 - self._inertia)

            out[k] = float(np.clip(v, 0.0, 1.0))

        self._state = out
        return dict(out)


    def dominant_axis(self) -> str:
        """
        Return the dominant emotional dimension.
        """
        return max(self._state.items(), key=lambda x: x[1])[0]


    def snapshot(self) -> Dict[str, float]:
        return dict(self._state)


class ShotNarrativeCoherence:
    """
    Director-level coherence controller.
    Ensures that consecutive shots feel emotionally intentional,
    not merely visually consistent.
    """

    __slots__ = (
        "_affect",
        "_history",
        "_history_len",
    )

    def __init__(self, history_len: int = 5):
        self._affect = AffectiveStateVector()
        self._history: List[Dict[str, float]] = []
        self._history_len = int(np.clip(history_len, 3, 7))


    # --------------------------------------------------------------------------
    # Affective inference
    # --------------------------------------------------------------------------

    def _infer_affect(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Infer affective components from scene metrics.
        NOTE:
        This is a *projection*, not full semantic understanding.
        Higher-level AI may override or enrich this later.
        """

        motion = metrics.get("motion_energy", 0.0)
        contrast = metrics.get("contrast", 0.0)
        luma = metrics.get("avg_luma", 0.5)
        tension = metrics.get("scene_tension", 0.0)

        return {
            "tension": float(np.clip(tension, 0.0, 1.0)),
            "awe": float(np.clip(luma * (1.0 - motion), 0.0, 1.0)),
            "grief": float(np.clip((1.0 - luma) * (1.0 - motion), 0.0, 1.0)),
            "relief": float(np.clip((1.0 - tension) * luma, 0.0, 1.0)),
            "triumph": float(np.clip(motion * contrast, 0.0, 1.0)),
        }


    # --------------------------------------------------------------------------
    # Main update
    # --------------------------------------------------------------------------

    def update(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Update shot-to-shot narrative coherence.
        """

        inferred = self._infer_affect(metrics)
        affect = self._affect.blend(inferred)

        self._history.append(affect)
        if len(self._history) > self._history_len:
            self._history.pop(0)

        out = dict(metrics)

        # Attach affective state
        out["emotional_vector"] = dict(affect)
        out["dominant_emotion"] = self._affect.dominant_axis()

        # Coherence hint for downstream systems
        out["affective_stability"] = float(
            np.mean([v for v in affect.values()])
        )

        return out


    def reset(self) -> None:
        """
        Reset only on hard narrative discontinuity.
        """
        self._affect = AffectiveStateVector()
        self._history.clear()


