# END OF CHUNK 86 U 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 U 02 — INTENT-PRESERVING METRIC NORMALIZER
# ==============================================================================
#
# Purpose:
#   Convert affective state vectors into perceptually localized,
#   asymmetric adjustments across motion, tone, and structure
#   WITHOUT destroying the underlying emotional intent.
#
# This is where cinema stops being "global math" and becomes
# subject-aware, depth-aware, and perceptually realistic.
#
# Key principles:
#   • Emotion does not affect the whole frame equally
#   • Motion resolves before luminance
#   • Background releases before subject
#   • Periphery softens before center
#
# ==============================================================================

import numpy as np
from typing import Dict


class IntentPreservingNormalizer:
    """
    Projects affective vectors into perceptual-space modifiers
    while preserving narrative and emotional intent.
    """

    __slots__ = (
        "_subject_weight",
        "_periphery_weight",
    )

    def __init__(
        self,
        subject_weight: float = 0.7,
        periphery_weight: float = 0.5,
    ):
        self._subject_weight = float(np.clip(subject_weight, 0.5, 0.9))
        self._periphery_weight = float(np.clip(periphery_weight, 0.3, 0.7))


    # --------------------------------------------------------------------------
    # Projection helpers
    # --------------------------------------------------------------------------

    def _axis_influence(self, affect: Dict[str, float]) -> Dict[str, float]:
        """
        Compute perceptual influence strengths from affective axes.
        """
        return {
            "motion": (
                0.6 * affect.get("tension", 0.0)
                + 0.4 * affect.get("triumph", 0.0)
            ),
            "luma": (
                0.7 * affect.get("awe", 0.0)
                + 0.3 * affect.get("relief", 0.0)
            ),
            "contrast": (
                0.5 * affect.get("tension", 0.0)
                + 0.5 * affect.get("grief", 0.0)
            ),
        }


    # --------------------------------------------------------------------------
    # Main normalization
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Apply intent-preserving, perceptually localized normalization.
        """

        affect = metrics.get("emotional_vector")
        if not isinstance(affect, dict):
            return metrics

        influence = self._axis_influence(affect)

        out = dict(metrics)

        # --------------------------------------------------------------
        # Motion resolves first (cinematic truth)
        # --------------------------------------------------------------

        motion_release = np.clip(influence["motion"], 0.0, 1.0)

        out["motion_energy_subject"] = (
            out.get("motion_energy", 0.0)
            * (1.0 - 0.35 * motion_release * self._subject_weight)
        )

        out["motion_energy_background"] = (
            out.get("motion_energy", 0.0)
            * (1.0 - 0.55 * motion_release)
        )


        # --------------------------------------------------------------
        # Luminance releases slower than motion
        # --------------------------------------------------------------

        luma_release = np.clip(influence["luma"], 0.0, 1.0)

        out["avg_luma_subject"] = (
            out.get("avg_luma", 0.5)
            * (1.0 + 0.10 * luma_release * self._subject_weight)
        )

        out["avg_luma_background"] = (
            out.get("avg_luma", 0.5)
            * (1.0 + 0.18 * luma_release)
        )


        # --------------------------------------------------------------
        # Contrast tightens or relaxes asymmetrically
        # --------------------------------------------------------------

        contrast_bias = np.clip(influence["contrast"], 0.0, 1.0)

        out["contrast_subject"] = (
            out.get("contrast", 0.5)
            * (1.0 + 0.12 * contrast_bias * self._subject_weight)
        )

        out["contrast_background"] = (
            out.get("contrast", 0.5)
            * (1.0 - 0.15 * contrast_bias)
        )


        # --------------------------------------------------------------
        # Peripheral softening (implicit, not explicit blur)
        # --------------------------------------------------------------

        out["peripheral_softening"] = (
            self._periphery_weight
            * (affect.get("grief", 0.0) + affect.get("awe", 0.0))
        )


        # --------------------------------------------------------------
        # Preserve original intent (important)
        # --------------------------------------------------------------

        out["intent_preserved"] = True
        out["perceptual_projection_active"] = True

        return out


    def reset(self) -> None:
        """
        No persistent state to reset.
        """
        pass


