# END OF CHUNK 86 U 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 U 03 — LONG-ARC CINEMATIC MEMORY
# ==============================================================================
#
# Purpose:
#   Maintain a compact episodic memory of recent emotional resolutions
#   and use it to adapt future release, linger, and restraint behavior.
#
# This is where the system stops being merely intelligent
# and begins developing *taste*.
#
# Cinema truth:
#   Directors remember how an emotion landed.
#   They adjust instinctively next time.
#
# ==============================================================================

import numpy as np
from typing import Dict, List


class AffectiveEpisode:
    """
    Represents the outcome of a completed emotional arc.
    """

    __slots__ = (
        "vector",
        "dominant",
        "resolution_mode",
        "satisfaction",
    )

    def __init__(
        self,
        vector: Dict[str, float],
        dominant: str,
        resolution_mode: str,
        satisfaction: float,
    ):
        self.vector = dict(vector)
        self.dominant = dominant
        self.resolution_mode = resolution_mode
        self.satisfaction = float(np.clip(satisfaction, 0.0, 1.0))


class LongArcCinematicMemory:
    """
    Director-level episodic memory.
    Remembers how emotional moments resolved and subtly adjusts
    future behavior to improve audience experience.
    """

    __slots__ = (
        "_episodes",
        "_capacity",
        "_ema_rate",
        "_taste_bias",
    )

    def __init__(
        self,
        capacity: int = 5,
        ema_rate: float = 0.35,
    ):
        self._capacity = int(np.clip(capacity, 3, 7))
        self._ema_rate = float(np.clip(ema_rate, 0.15, 0.6))
        self._episodes: List[AffectiveEpisode] = []
        self._taste_bias = {
            "linger": 1.0,
            "release": 1.0,
            "restraint": 1.0,
        }


    # --------------------------------------------------------------------------
    # Episode ingestion
    # --------------------------------------------------------------------------

    def record_episode(self, metrics: Dict[str, float]) -> None:
        """
        Capture the outcome of an emotional resolution.
        Satisfaction is inferred indirectly — no hard labels.
        """

        vector = metrics.get("emotional_vector", {})
        dominant = metrics.get("dominant_emotion", "neutral")
        resolution_mode = metrics.get("resolution_mode", "CONTROLLED")

        # Heuristic satisfaction proxy:
        # Stable affect + low suppression bias implies good landing
        stability = float(metrics.get("affective_stability", 0.5))
        suppression = float(metrics.get("peak_suppression_bias", 1.0))

        satisfaction = np.clip(
            0.6 * stability + 0.4 * suppression,
            0.0,
            1.0,
        )

        episode = AffectiveEpisode(
            vector=vector,
            dominant=dominant,
            resolution_mode=resolution_mode,
            satisfaction=satisfaction,
        )

        self._episodes.append(episode)
        if len(self._episodes) > self._capacity:
            self._episodes.pop(0)


    # --------------------------------------------------------------------------
    # Taste adaptation
    # --------------------------------------------------------------------------

    def _update_taste(self) -> None:
        """
        Update internal taste biases based on recent episodes.
        """

        if not self._episodes:
            return

        # Aggregate satisfaction by resolution behavior
        linger_scores = []
        release_scores = []
        restraint_scores = []

        for e in self._episodes:
            if e.resolution_mode == "LINGER":
                linger_scores.append(e.satisfaction)
            elif e.resolution_mode == "CONTROLLED":
                release_scores.append(e.satisfaction)
            elif e.resolution_mode == "SUPPRESSED":
                restraint_scores.append(e.satisfaction)

        def ema(prev: float, values: List[float]) -> float:
            if not values:
                return prev
            return prev * (1.0 - self._ema_rate) + np.mean(values) * self._ema_rate

        self._taste_bias["linger"] = ema(
            self._taste_bias["linger"], linger_scores
        )
        self._taste_bias["release"] = ema(
            self._taste_bias["release"], release_scores
        )
        self._taste_bias["restraint"] = ema(
            self._taste_bias["restraint"], restraint_scores
        )


    # --------------------------------------------------------------------------
    # Public interface
    # --------------------------------------------------------------------------

    def adapt(self) -> Dict[str, float]:
        """
        Update taste memory and expose adaptive biases.
        """

        self._update_taste()

        return {
            "linger_bias": float(np.clip(self._taste_bias["linger"], 0.7, 1.3)),
            "release_bias": float(np.clip(self._taste_bias["release"], 0.7, 1.3)),
            "restraint_bias": float(np.clip(self._taste_bias["restraint"], 0.7, 1.3)),
        }


    def reset(self) -> None:
        """
        Reset memory (used only on new narrative start).
        """
        self._episodes.clear()
        self._taste_bias = {
            "linger": 1.0,
            "release": 1.0,
            "restraint": 1.0,
        }


