# END OF CHUNK 86 U 03
# ==============================================================================
# ==============================================================================
# CHUNK 86 V 01 — TEMPORAL INTENT PERSISTENCE GATE
# ==============================================================================
#
# Purpose:
#   Preserve cinematic intent across frames and shots so that
#   high-level decisions do not flicker, oscillate, or self-cancel.
#
# This module answers:
#   • Should intent persist or be allowed to change?
#   • How resistant should intent be to momentary noise?
#   • When is a transition justified vs destabilizing?
#
# Cinema truth:
#   Directors commit to intent.
#   They do not re-decide every frame.
#
# ==============================================================================

import numpy as np
from typing import Dict


class TemporalIntentGate:
    """
    Director-level temporal stabilizer for intent vectors.
    Prevents:
        • Intent flicker
        • Shot indecision
        • Micro-reversals of framing / motion goals
    Enables:
        • Commitment
        • Deliberate transitions
        • Perceived confidence in camera behavior
    """

    __slots__ = (
        "_intent",
        "_confidence",
        "_resistance",
    )

    def __init__(
        self,
        resistance: float = 0.78,
    ):
        """
        resistance:
            How strongly prior intent resists change.
        """
        self._resistance = float(np.clip(resistance, 0.6, 0.9))
        self._intent: Dict[str, float] = {}
        self._confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Intent distance
    # --------------------------------------------------------------------------

    def _intent_distance(
        self, a: Dict[str, float], b: Dict[str, float]
    ) -> float:
        """
        Measure semantic distance between two intent states.
        """
        if not a or not b:
            return 1.0

        keys = set(a.keys()) | set(b.keys())
        diffs = []

        for k in keys:
            diffs.append(abs(a.get(k, 0.0) - b.get(k, 0.0)))

        return float(np.clip(np.mean(diffs), 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Main update
    # --------------------------------------------------------------------------

    def update(
        self,
        incoming_intent: Dict[str, float],
        stability: float,
    ) -> Dict[str, float]:
        """
        Decide whether to persist, blend, or replace intent.
        stability:
            Affective stability from narrative coherence (0–1).
        """

        stability = float(np.clip(stability, 0.0, 1.0))

        # First intent always commits
        if not self._intent:
            self._intent = dict(incoming_intent)
            self._confidence = stability
            return dict(self._intent)

        distance = self._intent_distance(self._intent, incoming_intent)

        # High stability → resist change
        gate = self._resistance * stability

        if distance < gate:
            # Reinforce existing intent
            self._confidence = min(1.0, self._confidence + 0.1 * stability)
            return dict(self._intent)

        # Intent transition is justified → blend slowly
        blend = np.clip(distance * (1.0 - gate), 0.1, 0.5)

        new_intent = {}
        for k in set(self._intent) | set(incoming_intent):
            prev = self._intent.get(k, 0.0)
            inc = incoming_intent.get(k, 0.0)
            new_intent[k] = prev * (1.0 - blend) + inc * blend

        self._intent = new_intent
        self._confidence = stability

        return dict(self._intent)


    def snapshot(self) -> Dict[str, float]:
        """
        Return current committed intent.
        """
        return dict(self._intent)


    def reset(self) -> None:
        """
        Reset intent (only on major narrative reset).
        """
        self._intent.clear()
        self._confidence = 0.0


