# ==============================================================================
# CHUNK 86 V 02 — PERCEPTUAL SALIENCY ARBITRATION
# ==============================================================================
#
# Purpose:
#   Determine which regions, subjects, or elements of the frame
#   deserve perceptual priority based on narrative intent,
#   affective state, and motion dynamics.
#
# This module answers:
#   • Where should the audience look?
#   • What should dominate perception right now?
#   • What must decay into background?
#
# Cinema truth:
#   Emotion follows attention.
#   Attention is actively directed, not passively received.
#
# ==============================================================================

import numpy as np
from typing import Dict


class PerceptualSaliencyArbitrator:
    """
    Director-level attention controller.
    Arbitrates perceptual dominance between competing elements
    using intent, affect, and motion cues.
    """

    __slots__ = (
        "_baseline_bias",
        "_inertia",
        "_saliency",
    )

    def __init__(
        self,
        baseline_bias: float = 0.5,
        inertia: float = 0.75,
    ):
        self._baseline_bias = float(np.clip(baseline_bias, 0.3, 0.7))
        self._inertia = float(np.clip(inertia, 0.6, 0.9))
        self._saliency: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Saliency inference
    # --------------------------------------------------------------------------

    def _infer_saliency(
        self,
        metrics: Dict[str, float],
    ) -> Dict[str, float]:
        """
        Infer relative saliency weights.
        Keys represent abstract perceptual zones or subjects
        (e.g., 'subject', 'background', 'motion', 'static').
        """

        affect = metrics.get("emotional_vector", {})
        intent = metrics.get("shot_intent", {})

        motion = metrics.get("motion_energy", 0.0)
        contrast = metrics.get("contrast", 0.0)

        subject_priority = (
            0.4 * affect.get("tension", 0.0)
            + 0.4 * affect.get("triumph", 0.0)
            + 0.2 * intent.get("frame_tighten", 0.0)
        )

        background_priority = (
            0.3 * affect.get("awe", 0.0)
            + 0.3 * affect.get("grief", 0.0)
            + 0.2 * (1.0 - motion)
        )

        motion_priority = (
            0.5 * motion
            + 0.3 * affect.get("tension", 0.0)
            + 0.2 * intent.get("motion_expand", 0.0)
        )

        static_priority = (
            0.5 * (1.0 - motion)
            + 0.3 * affect.get("awe", 0.0)
        )

        raw = {
            "subject": subject_priority,
            "background": background_priority,
            "motion": motion_priority,
            "static": static_priority,
        }

        # Normalize
        total = sum(raw.values()) + 1e-6
        return {k: float(v / total) for k, v in raw.items()}


    # --------------------------------------------------------------------------
    # Main update
    # --------------------------------------------------------------------------

    def update(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Update perceptual saliency state and attach weights.
        """

        inferred = self._infer_saliency(metrics)

        # Apply inertia to prevent attention flicker
        if not self._saliency:
            self._saliency = inferred
        else:
            blended = {}
            for k in inferred:
                prev = self._saliency.get(k, self._baseline_bias)
                inc = inferred[k]
                blended[k] = prev * self._inertia + inc * (1.0 - self._inertia)
            self._saliency = blended

        out = dict(metrics)

        out["perceptual_saliency"] = dict(self._saliency)
        out["primary_focus"] = max(
            self._saliency.items(), key=lambda x: x[1]
        )[0]

        return out


    def reset(self) -> None:
        """
        Reset saliency (used only on hard scene cuts).
        """
        self._saliency.clear()


