# END OF CHUNK 86 V 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 W 01 — SUBJECT-CENTRIC EMOTIONAL WEIGHTING
# ==============================================================================
#
# Purpose:
#   Determine how emotional weight is distributed between subject,
#   environment, and residual background so that feeling is *carried*
#   by the correct visual agent.
#
# This module answers:
#   • Who is emotionally responsible for the moment?
#   • Should emotion live on the subject or the world?
#   • How much should the environment echo vs defer?
#
# Cinema truth:
#   Emotion must have a carrier.
#   Otherwise it diffuses and loses meaning.
#
# ==============================================================================

import numpy as np
from typing import Dict


class SubjectEmotionalWeighting:
    """
    Director-level emotional load distributor.
    Assigns emotional dominance between subject and environment
    based on affective state, saliency, and narrative intent.
    """

    __slots__ = (
        "_subject_bias",
        "_environment_bias",
    )

    def __init__(
        self,
        subject_bias: float = 0.65,
        environment_bias: float = 0.35,
    ):
        self._subject_bias = float(np.clip(subject_bias, 0.5, 0.85))
        self._environment_bias = float(np.clip(environment_bias, 0.15, 0.5))


    # --------------------------------------------------------------------------
    # Weight computation
    # --------------------------------------------------------------------------

    def _compute_weights(
        self,
        affect: Dict[str, float],
        saliency: Dict[str, float],
    ) -> Dict[str, float]:
        """
        Compute normalized emotional weights.
        """

        # Subject carries emotion in tension, triumph, grief
        subject_load = (
            0.4 * affect.get("tension", 0.0)
            + 0.4 * affect.get("triumph", 0.0)
            + 0.3 * affect.get("grief", 0.0)
            + 0.2 * saliency.get("subject", 0.0)
        )

        # Environment carries awe, relief, aftermath
        environment_load = (
            0.5 * affect.get("awe", 0.0)
            + 0.4 * affect.get("relief", 0.0)
            + 0.2 * saliency.get("background", 0.0)
        )

        # Normalize with biases
        subject_weight = subject_load * self._subject_bias
        environment_weight = environment_load * self._environment_bias

        residual = max(
            0.0,
            1.0 - (subject_weight + environment_weight),
        )

        total = subject_weight + environment_weight + residual + 1e-6

        return {
            "subject": float(subject_weight / total),
            "environment": float(environment_weight / total),
            "residual": float(residual / total),
        }


    # --------------------------------------------------------------------------
    # Main update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Attach emotional weight distribution to metrics.
        """

        affect = metrics.get("emotional_vector")
        saliency = metrics.get("perceptual_saliency")

        if not isinstance(affect, dict) or not isinstance(saliency, dict):
            return metrics

        weights = self._compute_weights(affect, saliency)

        out = dict(metrics)

        out["emotional_weight_distribution"] = weights
        out["emotion_carrier"] = max(
            weights.items(), key=lambda x: x[1]
        )[0]

        return out


    def reset(self) -> None:
        """
        No persistent state.
        """
        pass


# ==============================================================================
# END OF CHUNK 86 W 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 W 02 — DEPTH-AWARE EMOTIONAL FALLOFF
# ==============================================================================
#
# Purpose:
#   Model how emotional intensity attenuates across spatial depth so that
#   foreground, midground, and background carry emotion differently.
#
# This module answers:
#   • How far does emotion travel into space?
#   • Should background echo or dissolve the feeling?
#   • When does distance create emotional silence?
#
# Cinema truth:
#   Emotion weakens with distance — unless deliberately staged otherwise.
#
# ==============================================================================

import numpy as np
from typing import Dict


class DepthAwareEmotionalFalloff:
    """
    Director-level spatial emotion attenuator.
    Shapes how affect decays through depth planes, enabling
    foreground dominance, midground support, and background quiet.
    """

    __slots__ = (
        "_foreground_bias",
        "_midground_bias",
        "_background_bias",
    )

    def __init__(
        self,
        foreground_bias: float = 1.0,
        midground_bias: float = 0.65,
        background_bias: float = 0.35,
    ):
        self._foreground_bias = float(np.clip(foreground_bias, 0.8, 1.2))
        self._midground_bias = float(np.clip(midground_bias, 0.4, 0.9))
        self._background_bias = float(np.clip(background_bias, 0.15, 0.6))


    # --------------------------------------------------------------------------
    # Falloff computation
    # --------------------------------------------------------------------------

    def _depth_weights(
        self,
        carrier: str,
    ) -> Dict[str, float]:
        """
        Compute base depth weights based on emotion carrier.
        """

        if carrier == "subject":
            return {
                "foreground": self._foreground_bias,
                "midground": self._midground_bias,
                "background": self._background_bias,
            }

        if carrier == "environment":
            return {
                "foreground": 0.75 * self._foreground_bias,
                "midground": 1.0 * self._midground_bias,
                "background": 1.15 * self._background_bias,
            }

        # residual or undefined carrier
        return {
            "foreground": 0.6 * self._foreground_bias,
            "midground": 0.6 * self._midground_bias,
            "background": 0.6 * self._background_bias,
        }


    # --------------------------------------------------------------------------
    # Main application
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        """
        Attach depth-aware emotional attenuation factors.
        """

        carrier = metrics.get("emotion_carrier")
        affect = metrics.get("emotional_vector")

        if not isinstance(affect, dict):
            return metrics

        weights = self._depth_weights(carrier)

        # Normalize weights
        total = sum(weights.values()) + 1e-6
        for k in weights:
            weights[k] = float(weights[k] / total)

        out = dict(metrics)

        # Depth-modulated affect
        out["depth_emotional_falloff"] = {
            "foreground": {
                k: v * weights["foreground"] for k, v in affect.items()
            },
            "midground": {
                k: v * weights["midground"] for k, v in affect.items()
            },
            "background": {
                k: v * weights["background"] for k, v in affect.items()
            },
        }

        out["depth_falloff_active"] = True

        return out


    def reset(self) -> None:
        """
        No persistent state.
        """
        pass


