# END OF CHUNK 86 W 02
# ==============================================================================
# ==============================================================================
# CHUNK 86 W 03 — ENVIRONMENTAL EMOTIONAL ECHO MODELING
# ==============================================================================
#
# Purpose:
#   Model how the environment emotionally reacts AFTER the subject
#   has expressed emotion — enabling cinematic resonance, silence,
#   and world-scale feeling.
#
# Cinema truth:
#   The world never reacts instantly.
#   It absorbs emotion, then echoes it back.
#
# ==============================================================================

import numpy as np
from typing import Dict


class EnvironmentalEmotionalEcho:
    """
    Director-level environmental resonance engine.
    Controls how emotion propagates into lighting, contrast,
    saturation, and motion of the environment over time.
    """

    __slots__ = (
        "_echo_state",
        "_decay_rate",
        "_inertia",
    )

    def __init__(
        self,
        decay_rate: float = 0.12,
        inertia: float = 0.85,
    ):
        self._decay_rate = float(np.clip(decay_rate, 0.05, 0.25))
        self._inertia = float(np.clip(inertia, 0.7, 0.95))
        self._echo_state: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Echo inference
    # --------------------------------------------------------------------------

    def _infer_echo(self, metrics: Dict[str, float]) -> Dict[str, float]:
        affect = metrics.get("emotional_vector", {})
        carrier = metrics.get("emotion_carrier", "subject")

        awe = affect.get("awe", 0.0)
        grief = affect.get("grief", 0.0)
        relief = affect.get("relief", 0.0)
        triumph = affect.get("triumph", 0.0)

        # Environment echoes slower, broader emotions
        echo_strength = np.clip(
            0.5 * awe
            + 0.4 * grief
            + 0.3 * relief,
            0.0,
            1.0,
        )

        # Subject-dominant emotion suppresses environment initially
        if carrier == "subject":
            echo_strength *= 0.75

        return {
            "env_contrast_echo": echo_strength * 0.6,
            "env_saturation_echo": echo_strength * 0.7,
            "env_motion_echo": echo_strength * 0.4,
            "env_luma_drift": -echo_strength * 0.3,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        inferred = self._infer_echo(metrics)

        if not self._echo_state:
            self._echo_state = inferred
        else:
            blended = {}
            for k, v in inferred.items():
                prev = self._echo_state.get(k, 0.0)
                blended[k] = (
                    prev * self._inertia
                    + v * (1.0 - self._inertia)
                )
            self._echo_state = blended

        # Natural decay over time
        for k in self._echo_state:
            self._echo_state[k] *= (1.0 - self._decay_rate)

        out = dict(metrics)

        out["environmental_emotional_echo"] = dict(self._echo_state)
        out["environment_echo_active"] = any(
            abs(v) > 0.01 for v in self._echo_state.values()
        )

        return out


    def reset(self) -> None:
        """
        Reset environmental echo (hard cut or scene change).
        """
        self._echo_state.clear()


