# END OF CHUNK 86 W 03
# ==============================================================================
# ==============================================================================
# CHUNK 86 W 04 — SILENCE & NEGATIVE SPACE INTELLIGENCE
# ==============================================================================
#
# Purpose:
#   Actively decide when to withhold motion, contrast, and visual
#   emphasis so that emotion can breathe without interference.
#
# Cinema truth:
#   Silence is not absence — it is a decision.
#
# ==============================================================================

import numpy as np
from typing import Dict


class SilenceNegativeSpaceController:
    """
    Director-level restraint engine.
    Determines when the system should reduce activity,
    hold frames, or suppress expressive behavior.
    """

    __slots__ = (
        "_silence_state",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.88):
        self._inertia = float(np.clip(inertia, 0.75, 0.97))
        self._silence_state: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Silence inference
    # --------------------------------------------------------------------------

    def _infer_silence(self, metrics: Dict[str, float]) -> Dict[str, float]:
        affect = metrics.get("emotional_vector", {})
        echo_active = metrics.get("environment_echo_active", False)
        phase = metrics.get("narrative_phase", "development")

        grief = affect.get("grief", 0.0)
        awe = affect.get("awe", 0.0)
        relief = affect.get("relief", 0.0)
        tension = affect.get("tension", 0.0)

        # Silence grows after release, grief, or awe
        silence_strength = np.clip(
            0.5 * grief
            + 0.4 * awe
            + 0.3 * relief
            - 0.4 * tension,
            0.0,
            1.0,
        )

        # Resolution phases encourage stillness
        if phase in ("resolution", "aftermath"):
            silence_strength *= 1.2

        # Active environmental echo delays silence slightly
        if echo_active:
            silence_strength *= 0.85

        return {
            "motion_suppression": silence_strength,
            "contrast_suppression": silence_strength * 0.7,
            "framing_hold": silence_strength * 0.8,
            "expressive_lock": silence_strength > 0.6,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        inferred = self._infer_silence(metrics)

        if not self._silence_state:
            self._silence_state = inferred
        else:
            blended = {}
            for k, v in inferred.items():
                prev = self._silence_state.get(k, 0.0)
                blended[k] = (
                    prev * self._inertia
                    + v * (1.0 - self._inertia)
                )
            self._silence_state = blended

        out = dict(metrics)

        out["silence_negative_space"] = dict(self._silence_state)
        out["silence_active"] = self._silence_state.get(
            "motion_suppression", 0.0
        ) > 0.25

        return out


    def reset(self) -> None:
        """
        Reset silence state on hard narrative transition.
        """
        self._silence_state.clear()


