# END OF CHUNK 86 W 04
# ==============================================================================
# ==============================================================================
# CHUNK 86 W 05 — TEMPORAL RHYTHM & PACING GOVERNOR
# ==============================================================================
#
# Purpose:
#   Regulate how quickly or slowly cinematic emotion evolves over time,
#   preventing rushed beats or dragged moments.
#
# Cinema truth:
#   Pacing is emotion over time.
#
# ==============================================================================

import numpy as np
from typing import Dict


class TemporalRhythmGovernor:
    """
    Director-level pacing controller.
    Modulates emotional update rates based on narrative phase,
    emotional intensity, and silence state.
    """

    __slots__ = (
        "_pace_state",
        "_base_rate",
        "_inertia",
    )

    def __init__(
        self,
        base_rate: float = 0.12,
        inertia: float = 0.85,
    ):
        self._base_rate = float(np.clip(base_rate, 0.05, 0.25))
        self._inertia = float(np.clip(inertia, 0.7, 0.95))
        self._pace_state: float = base_rate


    # --------------------------------------------------------------------------
    # Pace inference
    # --------------------------------------------------------------------------

    def _infer_pace(self, metrics: Dict[str, float]) -> float:
        affect = metrics.get("emotional_vector", {})
        phase = metrics.get("narrative_phase", "development")
        silence = metrics.get("silence_active", False)

        tension = affect.get("tension", 0.0)
        awe = affect.get("awe", 0.0)
        grief = affect.get("grief", 0.0)
        triumph = affect.get("triumph", 0.0)

        # Base emotional pace
        pace = (
            0.5 * tension
            + 0.4 * triumph
            - 0.4 * grief
            - 0.3 * awe
        )

        pace = np.clip(pace, -1.0, 1.0)

        # Narrative shaping
        if phase == "climax":
            pace *= 1.3
        elif phase in ("resolution", "aftermath"):
            pace *= 0.6

        # Silence enforces slowdown
        if silence:
            pace *= 0.5

        # Convert to rate
        return float(
            np.clip(
                self._base_rate * (1.0 + pace),
                0.03,
                0.35,
            )
        )


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        inferred_rate = self._infer_pace(metrics)

        self._pace_state = (
            self._pace_state * self._inertia
            + inferred_rate * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["temporal_pacing_rate"] = self._pace_state
        out["pacing_slow"] = self._pace_state < self._base_rate * 0.8
        out["pacing_fast"] = self._pace_state > self._base_rate * 1.2

        return out


    def reset(self) -> None:
        """
        Reset pacing on hard narrative reset.
        """
        self._pace_state = self._base_rate


# ==============================================================================
# END OF CHUNK 86 W 05
# ==============================================================================
# ==============================================================================
# CHUNK 86 W 06 — EMOTIONAL PEAK CONTAINMENT GOVERNOR
# ==============================================================================
#
# Purpose:
#   Prevent emotional inflation by actively containing peaks so that
#   climaxes remain meaningful and do not exhaust the audience.
#
# Cinema truth:
#   Not every rise deserves release.
#
# ==============================================================================

import numpy as np
from typing import Dict


class EmotionalPeakContainmentGovernor:
    """
    Director-level peak regulator.
    Detects rising emotional peaks and decides whether to:
    - allow escalation
    - plateau
    - gently compress expression
    """

    __slots__ = (
        "_containment_level",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.82):
        self._inertia = float(np.clip(inertia, 0.7, 0.95))
        self._containment_level: float = 0.0


    # --------------------------------------------------------------------------
    # Peak inference
    # --------------------------------------------------------------------------

    def _infer_containment(self, metrics: Dict[str, float]) -> float:
        affect = metrics.get("emotional_vector", {})
        phase = metrics.get("narrative_phase", "development")
        pacing = metrics.get("temporal_pacing_rate", 0.1)

        tension = affect.get("tension", 0.0)
        triumph = affect.get("triumph", 0.0)
        awe = affect.get("awe", 0.0)

        raw_peak = np.clip(
            0.5 * tension + 0.6 * triumph + 0.3 * awe,
            0.0,
            1.0,
        )

        # Early or mid narrative suppresses full release
        if phase in ("setup", "development"):
            raw_peak *= 0.65

        # Excessive pacing triggers containment
        if pacing > 0.18:
            raw_peak *= 1.2

        # Convert to containment pressure
        return float(np.clip(raw_peak - 0.55, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        inferred = self._infer_containment(metrics)

        self._containment_level = (
            self._containment_level * self._inertia
            + inferred * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["peak_containment_level"] = self._containment_level
        out["peak_allowed"] = self._containment_level < 0.3
        out["peak_compressed"] = self._containment_level > 0.5

        # Apply subtle containment effects
        if out["peak_compressed"]:
            out["contrast"] *= 1.0 - 0.08 * self._containment_level
            out["motion_energy"] *= 1.0 - 0.10 * self._containment_level

        return out


    def reset(self) -> None:
        """
        Reset containment on hard narrative boundary.
        """
        self._containment_level = 0.0


