# END OF CHUNK 86 W 06
# ==============================================================================
# ==============================================================================
# CHUNK 86 W 07 — POST-PEAK REFRACTORY & COOLDOWN LOGIC
# ==============================================================================
#
# Purpose:
#   Enforce a refractory period after emotional peaks so that
#   intensity cannot immediately re-escalate, preserving contrast
#   between moments and preventing emotional fatigue.
#
# Cinema truth:
#   After a peak, the audience needs time to recover.
#
# ==============================================================================

import numpy as np
from typing import Dict


class PostPeakRefractoryController:
    """
    Director-level cooldown governor.
    Applies temporal inhibition after major emotional peaks,
    shaping the fall rather than abruptly cutting intensity.
    """

    __slots__ = (
        "_refractory",
        "_cooldown_rate",
        "_inertia",
    )

    def __init__(
        self,
        cooldown_rate: float = 0.18,
        inertia: float = 0.9,
    ):
        self._cooldown_rate = float(np.clip(cooldown_rate, 0.08, 0.35))
        self._inertia = float(np.clip(inertia, 0.8, 0.97))
        self._refractory: float = 0.0


    # --------------------------------------------------------------------------
    # Refractory inference
    # --------------------------------------------------------------------------

    def _infer_refractory(self, metrics: Dict[str, float]) -> float:
        peak = metrics.get("peak_containment_level", 0.0)
        phase = metrics.get("narrative_phase", "development")
        silence = metrics.get("silence_active", False)

        base = np.clip(peak * 1.2, 0.0, 1.0)

        # Climax produces stronger cooldown
        if phase == "climax":
            base *= 1.25

        # Silence accelerates recovery
        if silence:
            base *= 0.85

        return base


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        inferred = self._infer_refractory(metrics)

        # Build refractory state
        self._refractory = max(
            self._refractory * self._inertia,
            inferred,
        )

        # Natural cooldown
        self._refractory *= (1.0 - self._cooldown_rate)

        out = dict(metrics)

        out["post_peak_refractory"] = self._refractory
        out["refractory_active"] = self._refractory > 0.15

        # Suppress re-escalation
        if out["refractory_active"]:
            out["contrast"] *= 1.0 - 0.12 * self._refractory
            out["motion_energy"] *= 1.0 - 0.15 * self._refractory

        return out


    def reset(self) -> None:
        """
        Reset refractory state on hard cut or scene change.
        """
        self._refractory = 0.0


# ==============================================================================
# END OF CHUNK 86 W 07
# ==============================================================================
# ==============================================================================
# CHUNK 86 W 08 — LONG-HORIZON EMOTIONAL DRIFT CONTROL
# ==============================================================================
#
# Purpose:
#   Prevent slow, unnoticed emotional drift across extended sequences,
#   ensuring the film maintains intentional tonal direction over time.
#
# Cinema truth:
#   Drift kills intention.
#
# ==============================================================================

import numpy as np
from typing import Dict


class LongHorizonEmotionalDriftController:
    """
    Director-level long-range stabilizer.
    Monitors accumulated emotional bias across time and gently
    nudges the system back toward intended narrative equilibrium.
    """

    __slots__ = (
        "_baseline",
        "_accumulator",
        "_adapt_rate",
    )

    def __init__(
        self,
        adapt_rate: float = 0.02,
    ):
        self._adapt_rate = float(np.clip(adapt_rate, 0.005, 0.05))
        self._baseline: Dict[str, float] = {}
        self._accumulator: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Drift inference
    # --------------------------------------------------------------------------

    def _infer_drift(
        self,
        affect: Dict[str, float],
    ) -> Dict[str, float]:
        drift = {}
        for k, v in affect.items():
            base = self._baseline.get(k, v)
            drift[k] = v - base
        return drift


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        affect = metrics.get("emotional_vector")

        if not isinstance(affect, dict):
            return metrics

        # Initialize baseline slowly
        if not self._baseline:
            self._baseline = dict(affect)

        drift = self._infer_drift(affect)

        # Accumulate drift
        for k, v in drift.items():
            prev = self._accumulator.get(k, 0.0)
            self._accumulator[k] = prev + v * self._adapt_rate

        out = dict(metrics)

        out["emotional_drift"] = dict(self._accumulator)

        # Apply gentle counter-drift
        corrected = {}
        for k, v in affect.items():
            correction = self._accumulator.get(k, 0.0)
            corrected[k] = float(
                np.clip(v - correction, 0.0, 1.0)
            )

        out["emotional_vector"] = corrected
        out["drift_control_active"] = any(
            abs(v) > 0.05 for v in self._accumulator.values()
        )

        return out


    def reset(self) -> None:
        """
        Reset long-horizon memory (chapter boundary).
        """
        self._baseline.clear()
        self._accumulator.clear()


