# CHUNK 86 W 09 — NARRATIVE PHASE TRANSITION STABILIZER
# ==============================================================================
#
# Purpose:
#   Smooth transitions between narrative phases so emotional
#   behavior does not snap or feel mechanically staged.
#
# Cinema truth:
#   Phase changes are felt gradually, not announced.
#
# ==============================================================================

import numpy as np
from typing import Dict


class NarrativePhaseTransitionStabilizer:
    """
    Director-level phase continuity controller.
    Applies hysteresis and temporal smoothing when narrative
    phases change (setup → development → climax → resolution).
    """

    __slots__ = (
        "_phase_confidence",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.8, 0.97))
        self._phase_confidence: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Phase inference
    # --------------------------------------------------------------------------

    def _update_confidence(self, phase: str) -> None:
        # Decay all confidences
        for k in list(self._phase_confidence.keys()):
            self._phase_confidence[k] *= self._inertia

        # Reinforce current phase
        self._phase_confidence[phase] = (
            self._phase_confidence.get(phase, 0.0)
            + (1.0 - self._inertia)
        )


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        phase = metrics.get("narrative_phase")

        if not isinstance(phase, str):
            return metrics

        self._update_confidence(phase)

        # Dominant phase by confidence
        stable_phase = max(
            self._phase_confidence,
            key=self._phase_confidence.get,
        )

        out = dict(metrics)

        out["narrative_phase_stable"] = stable_phase
        out["phase_confidence"] = dict(self._phase_confidence)

        # Transitional softness indicator
        out["phase_transition_active"] = (
            self._phase_confidence.get(stable_phase, 0.0) < 0.7
        )

        return out


    def reset(self) -> None:
        """
        Reset phase memory on chapter break.
        """
        self._phase_confidence.clear()


