# CHUNK 86 W 10 — DIRECTOR INTENT PERSISTENCE CORE
# ==============================================================================
#
# Purpose:
#   Preserve high-level directorial intent across shots and time,
#   preventing the system from reacting myopically to local stimuli.
#
# Cinema truth:
#   A director remembers what they are trying to say.
#
# ==============================================================================

import numpy as np
from typing import Dict


class DirectorIntentPersistenceCore:
    """
    Director-level intent memory.
    Maintains and reinforces long-lived cinematic intent so that
    framing, motion, and tone remain aligned with narrative goals.
    """

    __slots__ = (
        "_intent_vector",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.92):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._intent_vector: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Intent inference
    # --------------------------------------------------------------------------

    def _infer_intent(self, metrics: Dict[str, float]) -> Dict[str, float]:
        affect = metrics.get("emotional_vector", {})
        phase = metrics.get("narrative_phase_stable")

        intent = {
            "gravity": affect.get("grief", 0.0) + affect.get("awe", 0.0),
            "urgency": affect.get("tension", 0.0),
            "uplift": affect.get("triumph", 0.0) + affect.get("relief", 0.0),
        }

        # Phase shaping
        if phase == "climax":
            intent["urgency"] *= 1.2
        elif phase in ("resolution", "aftermath"):
            intent["gravity"] *= 1.15

        return {
            k: float(np.clip(v, 0.0, 1.0))
            for k, v in intent.items()
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        inferred = self._infer_intent(metrics)

        if not self._intent_vector:
            self._intent_vector = inferred
        else:
            blended = {}
            for k, v in inferred.items():
                prev = self._intent_vector.get(k, 0.0)
                blended[k] = (
                    prev * self._inertia
                    + v * (1.0 - self._inertia)
                )
            self._intent_vector = blended

        out = dict(metrics)

        out["director_intent"] = dict(self._intent_vector)
        out["intent_active"] = any(
            v > 0.2 for v in self._intent_vector.values()
        )

        return out


    def reset(self) -> None:
        """
        Reset intent memory on narrative reboot.
        """
        self._intent_vector.clear()


