# CHUNK 86 W 11 — CROSS-SCENE EMOTIONAL CALLBACK ENGINE
# ==============================================================================
#
# Purpose:
#   Reintroduce emotional motifs from earlier scenes so the audience
#   feels continuity, memory, and thematic cohesion.
#
# Cinema truth:
#   Meaning deepens when emotion remembers itself.
#
# ==============================================================================

import numpy as np
from typing import Dict, List


class CrossSceneEmotionalCallbackEngine:
    """
    Director-level emotional recall system.
    Stores distilled emotional signatures from prior scenes and
    selectively reactivates them when contextually appropriate.
    """

    __slots__ = (
        "_memory",
        "_capacity",
        "_decay",
    )

    def __init__(
        self,
        capacity: int = 5,
        decay: float = 0.9,
    ):
        self._capacity = int(np.clip(capacity, 3, 10))
        self._decay = float(np.clip(decay, 0.8, 0.98))
        self._memory: List[Dict[str, float]] = []


    # --------------------------------------------------------------------------
    # Memory update
    # --------------------------------------------------------------------------

    def _store_signature(self, affect: Dict[str, float]) -> None:
        signature = {
            k: float(v)
            for k, v in affect.items()
            if v > 0.3
        }

        if not signature:
            return

        self._memory.append(signature)

        if len(self._memory) > self._capacity:
            self._memory.pop(0)


    # --------------------------------------------------------------------------
    # Callback inference
    # --------------------------------------------------------------------------

    def _infer_callback(self, affect: Dict[str, float]) -> Dict[str, float]:
        if not self._memory:
            return {}

        callback = {}

        for past in self._memory:
            for k, v in past.items():
                callback[k] = max(
                    callback.get(k, 0.0),
                    v * self._decay,
                )

        # Only reintroduce if current affect is low
        return {
            k: v
            for k, v in callback.items()
            if affect.get(k, 0.0) < v * 0.6
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        affect = metrics.get("emotional_vector")

        if not isinstance(affect, dict):
            return metrics

        self._store_signature(affect)

        callback = self._infer_callback(affect)

        out = dict(metrics)

        if callback:
            blended = {}
            for k, v in affect.items():
                blended[k] = max(v, callback.get(k, 0.0))
            out["emotional_vector"] = blended
            out["emotional_callback_active"] = True
        else:
            out["emotional_callback_active"] = False

        return out


    def reset(self) -> None:
        """
        Clear emotional memory on full narrative reset.
        """
        self._memory.clear()


