# CHUNK 86 W 12 — EMOTIONAL MEMORY CONSOLIDATION LAYER
# ==============================================================================
#
# Purpose:
#   Convert short-term emotional callbacks into stable long-term
#   cinematic memory so themes persist across large narrative spans.
#
# Cinema truth:
#   Repetition without consolidation feels accidental.
#
# ==============================================================================

import numpy as np
from typing import Dict


class EmotionalMemoryConsolidationLayer:
    """
    Director-level emotional long-term memory.
    Stabilizes frequently recurring emotional motifs so they
    influence intent, pacing, and framing in future scenes.
    """

    __slots__ = (
        "_long_term_memory",
        "_threshold",
        "_decay",
    )

    def __init__(
        self,
        threshold: float = 0.35,
        decay: float = 0.995,
    ):
        self._threshold = float(np.clip(threshold, 0.2, 0.6))
        self._decay = float(np.clip(decay, 0.97, 0.999))
        self._long_term_memory: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Consolidation inference
    # --------------------------------------------------------------------------

    def _consolidate(self, affect: Dict[str, float]) -> None:
        for k, v in affect.items():
            if v > self._threshold:
                prev = self._long_term_memory.get(k, 0.0)
                self._long_term_memory[k] = max(prev, v)
            elif k in self._long_term_memory:
                self._long_term_memory[k] *= self._decay


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        affect = metrics.get("emotional_vector")

        if not isinstance(affect, dict):
            return metrics

        self._consolidate(affect)

        out = dict(metrics)

        out["emotional_long_term_memory"] = dict(self._long_term_memory)
        out["memory_consolidation_active"] = bool(
            self._long_term_memory
        )

        return out


    def reset(self) -> None:
        """
        Clear long-term emotional memory on full narrative reset.
        """
        self._long_term_memory.clear()


