import numpy as np
from typing import Dict


class DirectorTasteCalibration:
    """
    Director-level stylistic preference engine.
    Learns persistent biases toward contrast, motion, framing,
    and color response based on repeated emotional outcomes.
    """

    __slots__ = (
        "_taste_vector",
        "_learn_rate",
        "_inertia",
    )

    def __init__(
        self,
        learn_rate: float = 0.015,
        inertia: float = 0.93,
    ):
        self._learn_rate = float(np.clip(learn_rate, 0.005, 0.05))
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._taste_vector: Dict[str, float] = {
            "contrast_bias": 0.0,
            "motion_bias": 0.0,
            "luma_bias": 0.0,
            "saturation_bias": 0.0,
        }


    # --------------------------------------------------------------------------
    # Taste inference
    # --------------------------------------------------------------------------

    def _infer_adjustment(self, metrics: Dict[str, float]) -> Dict[str, float]:
        intent = metrics.get("director_intent", {})
        memory = metrics.get("emotional_long_term_memory", {})

        gravity = intent.get("gravity", 0.0)
        urgency = intent.get("urgency", 0.0)
        uplift = intent.get("uplift", 0.0)

        adjustment = {
            "contrast_bias": 0.4 * gravity + 0.3 * urgency,
            "motion_bias": 0.5 * urgency - 0.3 * gravity,
            "luma_bias": -0.4 * gravity + 0.2 * uplift,
            "saturation_bias": 0.4 * uplift,
        }

        # Reinforce remembered motifs
        for k in memory:
            if k == "grief":
                adjustment["contrast_bias"] += 0.1
                adjustment["luma_bias"] -= 0.1
            elif k == "triumph":
                adjustment["saturation_bias"] += 0.1
                adjustment["motion_bias"] += 0.05

        return adjustment


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        inferred = self._infer_adjustment(metrics)

        # Update taste vector gradually
        for k, v in inferred.items():
            prev = self._taste_vector.get(k, 0.0)
            self._taste_vector[k] = (
                prev * self._inertia
                + v * self._learn_rate
            )

        out = dict(metrics)

        out["director_taste"] = dict(self._taste_vector)
        out["taste_active"] = any(
            abs(v) > 0.05 for v in self._taste_vector.values()
        )

        return out


    def reset(self) -> None:
        """
        Reset stylistic taste (rarely used; director change).
        """
        for k in self._taste_vector:
            self._taste_vector[k] = 0.0


