import numpy as np
from typing import Dict


class LongFormThematicReinforcementEngine:
    """
    Director-level thematic convergence engine.
    Gradually amplifies dominant emotional themes while gently
    suppressing contradictory signals over extended durations.
    """

    __slots__ = (
        "_theme_strength",
        "_reinforce_rate",
        "_inertia",
    )

    def __init__(
        self,
        reinforce_rate: float = 0.02,
        inertia: float = 0.94,
    ):
        self._reinforce_rate = float(np.clip(reinforce_rate, 0.005, 0.05))
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._theme_strength: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Theme inference
    # --------------------------------------------------------------------------

    def _infer_theme(self, memory: Dict[str, float]) -> Dict[str, float]:
        if not memory:
            return {}

        total = sum(memory.values()) + 1e-6
        return {
            k: v / total
            for k, v in memory.items()
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        memory = metrics.get("emotional_long_term_memory", {})

        inferred = self._infer_theme(memory)

        if inferred:
            for k, v in inferred.items():
                prev = self._theme_strength.get(k, 0.0)
                self._theme_strength[k] = (
                    prev * self._inertia
                    + v * self._reinforce_rate
                )

        out = dict(metrics)

        out["thematic_strength"] = dict(self._theme_strength)
        out["thematic_reinforcement_active"] = bool(
            self._theme_strength
        )

        return out


    def reset(self) -> None:
        """
        Reset thematic memory on full narrative reset.
        """
        self._theme_strength.clear()


