import numpy as np
from typing import Dict


class CinematicBiasLearningLoop:
    """
    Director-level adaptive bias learner.
    Adjusts internal biases based on emotional payoff signals so
    stylistic decisions converge toward effectiveness.
    """

    __slots__ = (
        "_bias_weights",
        "_learn_rate",
        "_inertia",
    )

    def __init__(
        self,
        learn_rate: float = 0.01,
        inertia: float = 0.9,
    ):
        self._learn_rate = float(np.clip(learn_rate, 0.002, 0.05))
        self._inertia = float(np.clip(inertia, 0.8, 0.97))
        self._bias_weights: Dict[str, float] = {
            "contrast": 0.0,
            "motion": 0.0,
            "luma": 0.0,
            "saturation": 0.0,
        }


    # --------------------------------------------------------------------------
    # Bias inference
    # --------------------------------------------------------------------------

    def _infer_reward(self, metrics: Dict[str, float]) -> Dict[str, float]:
        affect = metrics.get("emotional_vector", {})
        payoff = (
            affect.get("awe", 0.0)
            + affect.get("triumph", 0.0)
            + affect.get("relief", 0.0)
            - affect.get("tension", 0.0)
        )

        return {
            "contrast": payoff,
            "motion": payoff * 0.8,
            "luma": payoff * 0.6,
            "saturation": payoff * 0.7,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        reward = self._infer_reward(metrics)

        for k, r in reward.items():
            prev = self._bias_weights.get(k, 0.0)
            self._bias_weights[k] = (
                prev * self._inertia
                + r * self._learn_rate
            )

        out = dict(metrics)

        out["cinematic_bias_weights"] = dict(self._bias_weights)
        out["bias_learning_active"] = any(
            abs(v) > 0.05 for v in self._bias_weights.values()
        )

        return out


    def reset(self) -> None:
        """
        Reset learned cinematic biases (director override).
        """
        for k in self._bias_weights:
            self._bias_weights[k] = 0.0


