import numpy as np
from typing import Dict


class DirectorAudienceFeedbackAssimilator:
    """
    Director-level feedback assimilation engine.
    Converts weak, indirect feedback into gradual preference updates
    without destabilizing current narrative intent.
    """

    __slots__ = (
        "_feedback_state",
        "_gain",
        "_inertia",
    )

    def __init__(
        self,
        gain: float = 0.06,
        inertia: float = 0.92,
    ):
        self._gain = float(np.clip(gain, 0.01, 0.15))
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._feedback_state: Dict[str, float] = {
            "engagement": 0.0,
            "satisfaction": 0.0,
            "fatigue": 0.0,
        }


    # --------------------------------------------------------------------------
    # Feedback inference
    # --------------------------------------------------------------------------

    def _infer_feedback(self, metrics: Dict[str, float]) -> Dict[str, float]:
        affect = metrics.get("emotional_vector", {})
        pacing_fast = metrics.get("pacing_fast", False)
        refractory = metrics.get("refractory_active", False)

        engagement = (
            affect.get("awe", 0.0)
            + affect.get("tension", 0.0)
        )

        satisfaction = (
            affect.get("relief", 0.0)
            + affect.get("triumph", 0.0)
        )

        fatigue = (
            0.5 * affect.get("tension", 0.0)
            + (0.3 if pacing_fast else 0.0)
            + (0.3 if refractory else 0.0)
        )

        return {
            "engagement": float(np.clip(engagement, 0.0, 1.0)),
            "satisfaction": float(np.clip(satisfaction, 0.0, 1.0)),
            "fatigue": float(np.clip(fatigue, 0.0, 1.0)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        inferred = self._infer_feedback(metrics)

        for k, v in inferred.items():
            prev = self._feedback_state.get(k, 0.0)
            self._feedback_state[k] = (
                prev * self._inertia
                + v * self._gain
            )

        out = dict(metrics)

        out["audience_feedback"] = dict(self._feedback_state)
        out["feedback_active"] = any(
            v > 0.15 for v in self._feedback_state.values()
        )

        return out


    def reset(self) -> None:
        """
        Reset accumulated audience feedback (new audience context).
        """
        for k in self._feedback_state:
            self._feedback_state[k] = 0.0


