import numpy as np
from typing import Dict


class EmotionalAuthorityArbitrationLayer:
    """
    Director-level emotional arbitration engine.
    Assigns authority weights to emotional drivers and produces
    a final, coherent emotional command vector.
    """

    __slots__ = (
        "_authority_weights",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.8, 0.97))
        self._authority_weights: Dict[str, float] = {
            "director_intent": 0.4,
            "audience_feedback": 0.25,
            "emotional_momentum": 0.2,
            "silence": 0.15,
        }


    # --------------------------------------------------------------------------
    # Authority inference
    # --------------------------------------------------------------------------

    def _infer_authority(self, metrics: Dict[str, float]) -> Dict[str, float]:
        phase = metrics.get("narrative_phase_stable")
        refractory = metrics.get("refractory_active", False)
        silence = metrics.get("silence_active", False)

        weights = dict(self._authority_weights)

        # Director intent dominates climax and resolution
        if phase in ("climax", "resolution"):
            weights["director_intent"] += 0.1

        # Silence gains authority during aftermath
        if silence:
            weights["silence"] += 0.1

        # Refractory suppresses feedback-driven escalation
        if refractory:
            weights["audience_feedback"] *= 0.6

        # Normalize
        total = sum(weights.values()) + 1e-6
        return {k: v / total for k, v in weights.items()}


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        inferred = self._infer_authority(metrics)

        # Smooth authority transitions
        for k, v in inferred.items():
            prev = self._authority_weights.get(k, 0.0)
            self._authority_weights[k] = (
                prev * self._inertia
                + v * (1.0 - self._inertia)
            )

        out = dict(metrics)

        out["emotional_authority"] = dict(self._authority_weights)
        out["authority_resolved"] = True

        return out


    def reset(self) -> None:
        """
        Reset authority weights (hard director override).
        """
        self._authority_weights = {
            "director_intent": 0.4,
            "audience_feedback": 0.25,
            "emotional_momentum": 0.2,
            "silence": 0.15,
        }


