import numpy as np
from typing import Dict


class CameraEmotionActuationBridge:
    """
    Director-to-camera execution bridge.
    Converts abstract emotional authority and intent into
    physically actionable camera control signals.
    """

    __slots__ = (
        "_last_commands",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.88):
        self._inertia = float(np.clip(inertia, 0.8, 0.97))
        self._last_commands: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Actuation inference
    # --------------------------------------------------------------------------

    def _infer_commands(self, metrics: Dict[str, float]) -> Dict[str, float]:
        authority = metrics.get("emotional_authority", {})
        intent = metrics.get("director_intent", {})
        taste = metrics.get("director_taste", {})
        silence = metrics.get("silence_active", False)

        gravity = intent.get("gravity", 0.0)
        urgency = intent.get("urgency", 0.0)
        uplift = intent.get("uplift", 0.0)

        commands = {
            "pan_speed": 0.6 * urgency - 0.4 * gravity,
            "tilt_speed": 0.5 * urgency - 0.3 * gravity,
            "zoom_rate": 0.4 * urgency + 0.3 * gravity,
            "exposure_shift": -0.5 * gravity + 0.3 * uplift,
            "contrast_shift": taste.get("contrast_bias", 0.0),
            "saturation_shift": taste.get("saturation_bias", 0.0),
        }

        # Silence enforces restraint
        if silence:
            for k in ("pan_speed", "tilt_speed", "zoom_rate"):
                commands[k] *= 0.4

        return {
            k: float(np.clip(v, -1.0, 1.0))
            for k, v in commands.items()
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        inferred = self._infer_commands(metrics)

        if not self._last_commands:
            self._last_commands = inferred
        else:
            blended = {}
            for k, v in inferred.items():
                prev = self._last_commands.get(k, 0.0)
                blended[k] = (
                    prev * self._inertia
                    + v * (1.0 - self._inertia)
                )
            self._last_commands = blended

        out = dict(metrics)

        out["camera_actuation"] = dict(self._last_commands)
        out["camera_actuation_active"] = any(
            abs(v) > 0.02 for v in self._last_commands.values()
        )

        return out


    def reset(self) -> None:
        """
        Reset camera actuation memory (cut or takeover).
        """
        self._last_commands.clear()


