# CHUNK 86 W 19 — DIRECTOR SAFETY ENVELOPE
# ==============================================================================
#
# Purpose:
#   Impose hard cinematic safety constraints so emotional authority
#   can never drive the camera into visually or narratively unsafe states.
#
# Cinema truth:
#   Great direction pushes boundaries — but never breaks the frame.
#
# ==============================================================================

import numpy as np
from typing import Dict


class DirectorSafetyEnvelope:
    """
    Director-level safety constraint system.
    Clamps camera and emotional outputs within validated cinematic
    operating ranges, regardless of upstream intensity.
    """

    __slots__ = (
        "_limits",
    )

    def __init__(self):
        self._limits = {
            "pan_speed": (-0.8, 0.8),
            "tilt_speed": (-0.7, 0.7),
            "zoom_rate": (-0.6, 0.6),
            "exposure_shift": (-0.5, 0.5),
            "contrast_shift": (-0.4, 0.4),
            "saturation_shift": (-0.4, 0.4),
        }


    # --------------------------------------------------------------------------
    # Safety enforcement
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        commands = metrics.get("camera_actuation")

        if not isinstance(commands, dict):
            return metrics

        safe = {}
        for k, v in commands.items():
            if k in self._limits:
                lo, hi = self._limits[k]
                safe[k] = float(np.clip(v, lo, hi))
            else:
                safe[k] = v

        out = dict(metrics)

        out["camera_actuation_safe"] = safe
        out["safety_envelope_active"] = True

        return out


    def reset(self) -> None:
        """
        Safety envelope has no dynamic state to reset.
        """
        pass


