# CHUNK 86 W 20 — AUTONOMOUS CINEMATIC FAILSAFE LOGIC
# ==============================================================================
#
# Purpose:
#   Detect unstable cinematic states and automatically degrade
#   expressiveness to preserve coherence, safety, and watchability.
#
# Cinema truth:
#   When control is lost, restraint saves the scene.
#
# ==============================================================================

import numpy as np
from typing import Dict


class AutonomousCinematicFailsafe:
    """
    Director-level autonomous failsafe controller.
    Monitors internal instability signals and enforces graceful
    degradation rather than abrupt shutdown.
    """

    __slots__ = (
        "_instability",
        "_threshold",
        "_inertia",
    )

    def __init__(
        self,
        threshold: float = 0.6,
        inertia: float = 0.9,
    ):
        self._threshold = float(np.clip(threshold, 0.3, 0.9))
        self._inertia = float(np.clip(inertia, 0.8, 0.98))
        self._instability: float = 0.0


    # --------------------------------------------------------------------------
    # Instability inference
    # --------------------------------------------------------------------------

    def _infer_instability(self, metrics: Dict[str, float]) -> float:
        pacing_fast = metrics.get("pacing_fast", False)
        refractory = metrics.get("refractory_active", False)
        authority = metrics.get("emotional_authority", {})

        conflict = max(authority.values()) - min(authority.values()) \
            if authority else 0.0

        instability = (
            0.4 * (1.0 if pacing_fast else 0.0)
            + 0.3 * (1.0 if refractory else 0.0)
            + 0.3 * conflict
        )

        return float(np.clip(instability, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        inferred = self._infer_instability(metrics)

        self._instability = (
            self._instability * self._inertia
            + inferred * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["cinematic_instability"] = self._instability
        out["failsafe_active"] = self._instability > self._threshold

        # Graceful degradation
        if out["failsafe_active"]:
            out["camera_actuation_safe"] = {
                k: v * 0.5
                for k, v in out.get("camera_actuation_safe", {}).items()
            }
            out["expressive_lock"] = True

        return out


    def reset(self) -> None:
        """
        Reset failsafe state after recovery.
        """
        self._instability = 0.0


