# CHUNK 86 W 21 — MANUAL OVERRIDE & AI YIELD PROTOCOL
# ==============================================================================
#
# Purpose:
#   Define strict authority transfer rules between autonomous
#   cinematic AI and human/manual control without instability.
#
# Cinema truth:
#   A great director knows when to step back.
#
# ==============================================================================

import numpy as np
from typing import Dict


class ManualOverrideAIYieldProtocol:
    """
    Director-level authority handoff controller.
    Ensures smooth yielding of control to human input and
    clean re-acquisition without emotional discontinuity.
    """

    __slots__ = (
        "_override_active",
        "_yield_strength",
        "_inertia",
    )

    def __init__(
        self,
        inertia: float = 0.9,
    ):
        self._inertia = float(np.clip(inertia, 0.8, 0.98))
        self._override_active: bool = False
        self._yield_strength: float = 0.0


    # --------------------------------------------------------------------------
    # Override detection
    # --------------------------------------------------------------------------

    def _detect_override(self, metrics: Dict[str, float]) -> bool:
        return bool(metrics.get("manual_override", False))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        override = self._detect_override(metrics)

        if override:
            self._override_active = True
            self._yield_strength = min(
                1.0,
                self._yield_strength + (1.0 - self._inertia),
            )
        else:
            self._yield_strength = max(
                0.0,
                self._yield_strength * self._inertia,
            )
            if self._yield_strength < 0.05:
                self._override_active = False

        out = dict(metrics)

        out["ai_yield_strength"] = self._yield_strength
        out["ai_active"] = not self._override_active

        # Blend camera actuation during handoff
        if self._override_active:
            out["camera_actuation_safe"] = {
                k: v * (1.0 - self._yield_strength)
                for k, v in out.get("camera_actuation_safe", {}).items()
            }

        return out


    def reset(self) -> None:
        """
        Force reset override state.
        """
        self._override_active = False
        self._yield_strength = 0.0


