# CHUNK 86 W 22 — CAMERA DIRECTOR SHUTDOWN SEQUENCER
# ==============================================================================
#
# Purpose:
#   Perform a graceful, narratively coherent shutdown of the
#   Camera Director AI when the session, mission, or system ends.
#
# Cinema truth:
#   Endings matter as much as beginnings.
#
# ==============================================================================

import numpy as np
from typing import Dict


class CameraDirectorShutdownSequencer:
    """
    Director-level shutdown orchestration system.
    Ensures emotional tapering, camera stabilization, and state
    persistence before relinquishing control.
    """

    __slots__ = (
        "_shutdown_progress",
        "_inertia",
        "_completed",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.8, 0.98))
        self._shutdown_progress: float = 0.0
        self._completed: bool = False


    # --------------------------------------------------------------------------
    # Shutdown inference
    # --------------------------------------------------------------------------

    def _infer_shutdown(self, metrics: Dict[str, float]) -> bool:
        return bool(metrics.get("shutdown_requested", False))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, float]) -> Dict[str, float]:
        if self._completed:
            return metrics

        if self._infer_shutdown(metrics):
            self._shutdown_progress = min(
                1.0,
                self._shutdown_progress + (1.0 - self._inertia),
            )
        else:
            self._shutdown_progress *= self._inertia

        out = dict(metrics)

        out["shutdown_progress"] = self._shutdown_progress

        # Cinematic tapering
        if self._shutdown_progress > 0.0:
            out["camera_actuation_safe"] = {
                k: v * (1.0 - self._shutdown_progress)
                for k, v in out.get("camera_actuation_safe", {}).items()
            }
            out["expressive_lock"] = True

        if self._shutdown_progress >= 0.99:
            self._completed = True
            out["camera_director_shutdown_complete"] = True

        return out


    def reset(self) -> None:
        """
        Reset shutdown sequencer (new session).
        """
        self._shutdown_progress = 0.0
        self._completed = False


