# ==============================================================================
# CHUNK 86 X 01 — CROSS-MODULE TIMING CONTRACT
# ==============================================================================
#
# Purpose:
#   Establish a deterministic timing contract between Camera Director AI,
#   flight controller logic, gimbal control, encoder, and cloud uplink.
#
# Backbone truth:
#   Cinematic intelligence collapses if modules drift in time.
#
# ==============================================================================

import time
from typing import Dict


class CrossModuleTimingContract:
    """
    System-level timing authority.
    Defines update rates, deadlines, and freshness guarantees so
    distributed modules remain temporally coherent.
    """

    __slots__ = (
        "_last_tick",
        "_periods",
        "_deadlines",
    )

    def __init__(self):
        self._last_tick: Dict[str, float] = {}
        self._periods: Dict[str, float] = {
            "camera_director": 1 / 30,      # 30 Hz
            "gimbal_control": 1 / 60,        # 60 Hz
            "flight_telemetry": 1 / 20,     # 20 Hz
            "cloud_sync": 1 / 5,            # 5 Hz
        }
        self._deadlines: Dict[str, float] = {
            "camera_director": 0.05,
            "gimbal_control": 0.02,
            "flight_telemetry": 0.1,
            "cloud_sync": 0.3,
        }


    # --------------------------------------------------------------------------
    # Timing checks
    # --------------------------------------------------------------------------

    def should_tick(self, module: str) -> bool:
        now = time.time()
        last = self._last_tick.get(module, 0.0)
        period = self._periods.get(module)

        if period is None:
            return False

        if (now - last) >= period:
            self._last_tick[module] = now
            return True

        return False


    def deadline_missed(self, module: str) -> bool:
        now = time.time()
        last = self._last_tick.get(module, now)
        deadline = self._deadlines.get(module)

        if deadline is None:
            return False

        return (now - last) > deadline


    # --------------------------------------------------------------------------
    # Diagnostics
    # --------------------------------------------------------------------------

    def snapshot(self) -> Dict[str, float]:
        return {
            module: time.time() - ts
            for module, ts in self._last_tick.items()
        }


