# ==============================================================================
# CHUNK 86 X 02 — DISTRIBUTED STATE SYNCHRONIZER
# ==============================================================================
#
# Purpose:
#   Maintain a single coherent cinematic + flight state across
#   Radxa (AI), ESP32 (actuation), Flight Controller, Mobile App,
#   and Cloud backend.
#
# Backbone truth:
#   Authority without synchronization becomes chaos.
#
# ==============================================================================

import time
from typing import Dict, Any


class DistributedStateSynchronizer:
    """
    Backbone-level state synchronization authority.
    Resolves distributed updates using timestamps, authority
    priority, and freshness guarantees.
    """

    __slots__ = (
        "_state",
        "_timestamps",
        "_authority_rank",
        "_ttl",
    )

    def __init__(self):
        self._state: Dict[str, Any] = {}
        self._timestamps: Dict[str, float] = {}

        # Higher number = higher authority
        self._authority_rank: Dict[str, int] = {
            "manual": 4,
            "camera_director": 3,
            "flight_controller": 2,
            "cloud": 1,
        }

        # Time-to-live per domain (seconds)
        self._ttl: Dict[str, float] = {
            "camera": 0.2,
            "flight": 0.3,
            "telemetry": 0.5,
            "cloud": 1.0,
        }


    # --------------------------------------------------------------------------
    # State update
    # --------------------------------------------------------------------------

    def update(
        self,
        key: str,
        value: Any,
        source: str,
    ) -> bool:
        now = time.time()

        prev_ts = self._timestamps.get(key, 0.0)
        prev_src = self._state.get(f"{key}__src")

        # Authority arbitration
        if prev_src:
            if self._authority_rank.get(source, 0) < \
               self._authority_rank.get(prev_src, 0):
                return False

        # Freshness check
        domain = key.split("_")[0]
        ttl = self._ttl.get(domain, 0.5)
        if (now - prev_ts) < ttl * 0.2:
            # Prevent excessive churn
            return False

        self._state[key] = value
        self._state[f"{key}__src"] = source
        self._timestamps[key] = now

        return True


    # --------------------------------------------------------------------------
    # State retrieval
    # --------------------------------------------------------------------------

    def get(self, key: str) -> Any:
        ts = self._timestamps.get(key)
        if ts is None:
            return None

        domain = key.split("_")[0]
        ttl = self._ttl.get(domain, 0.5)

        if (time.time() - ts) > ttl:
            return None

        return self._state.get(key)


    def snapshot(self) -> Dict[str, Any]:
        now = time.time()
        snap = {}

        for k, v in self._state.items():
            if k.endswith("__src"):
                continue

            ts = self._timestamps.get(k, 0.0)
            domain = k.split("_")[0]
            ttl = self._ttl.get(domain, 0.5)

            if (now - ts) <= ttl:
                snap[k] = v

        return snap


    # --------------------------------------------------------------------------
    # Reset
    # --------------------------------------------------------------------------

    def reset(self) -> None:
        """
        Clear all synchronized state (system reboot).
        """
        self._state.clear()
        self._timestamps.clear()


