# ==============================================================================
# CHUNK 86 X 04 — RADXA ↔ ESP32 COMMAND ARBITRATION LAYER
# ==============================================================================
#
# Purpose:
#   Mediate all commands flowing from Radxa (AI + director logic)
#   to ESP32 (real-time actuation) with strict safety and authority rules.
#
# Backbone truth:
#   High-level intelligence must never bypass low-level safety.
#
# ==============================================================================

from typing import Dict, Any


class RadxaESP32CommandArbitrationLayer:
    """
    Onboard command arbitration authority.
    Ensures only validated, rate-limited, and context-safe commands
    reach the ESP32 motor, gimbal, and peripheral controllers.
    """

    __slots__ = (
        "_last_sent",
        "_rate_limits",
        "_enabled",
    )

    def __init__(self):
        self._enabled: bool = True
        self._last_sent: Dict[str, float] = {}
        self._rate_limits: Dict[str, float] = {
            "gimbal": 1 / 60,
            "camera": 1 / 30,
            "lights": 1 / 10,
        }


    # --------------------------------------------------------------------------
    # Validation
    # --------------------------------------------------------------------------

    def _validate(self, cmd: Dict[str, Any]) -> bool:
        if not isinstance(cmd, dict):
            return False

        if "type" not in cmd or "value" not in cmd:
            return False

        if cmd["type"] not in self._rate_limits:
            return False

        return True


    # --------------------------------------------------------------------------
    # Arbitration
    # --------------------------------------------------------------------------

    def allow(self, cmd: Dict[str, Any], now: float) -> bool:
        if not self._enabled:
            return False

        if not self._validate(cmd):
            return False

        key = cmd["type"]
        last = self._last_sent.get(key, 0.0)
        min_interval = self._rate_limits[key]

        if (now - last) < min_interval:
            return False

        self._last_sent[key] = now
        return True


    # --------------------------------------------------------------------------
    # Control
    # --------------------------------------------------------------------------

    def disable(self) -> None:
        self._enabled = False


    def enable(self) -> None:
        self._enabled = True


    def reset(self) -> None:
        self._last_sent.clear()
        self._enabled = True


