# ==============================================================================
# CHUNK 86 X 05 — MAVLINK INTENT INJECTION GATEWAY
# ==============================================================================
#
# Purpose:
#   Translate high-level cinematic / mission intent into strictly
#   bounded MAVLink-compatible directives for ArduPilot / Pixhawk.
#
# Backbone truth:
#   Intent may guide the aircraft — never directly drive it.
#
# ==============================================================================

from typing import Dict, Any, Optional
import time


class MAVLinkIntentInjectionGateway:
    """
    Safety-critical intent injection gateway.
    Converts abstract intent (follow, orbit, frame, pace) into
    MAVLink-safe command envelopes without violating FC autonomy,
    pilot authority, or failsafe logic.
    """

    __slots__ = (
        "_allowed_modes",
        "_last_injection",
        "_min_interval",
    )

    def __init__(self):
        self._allowed_modes = {
            "GUIDED",
            "AUTO",
            "LOITER",
        }
        self._last_injection: float = 0.0
        self._min_interval: float = 0.2  # seconds


    # --------------------------------------------------------------------------
    # Validation
    # --------------------------------------------------------------------------

    def _validate_context(self, state: Dict[str, Any]) -> bool:
        if not state.get("fc_connected", False):
            return False

        if state.get("manual_override", False):
            return False

        if state.get("failsafe_active", False):
            return False

        if state.get("flight_mode") not in self._allowed_modes:
            return False

        return True


    def _validate_intent(self, intent: Dict[str, Any]) -> bool:
        if not isinstance(intent, dict):
            return False

        if "type" not in intent:
            return False

        if intent["type"] not in {
            "follow",
            "orbit",
            "hold_frame",
            "reframe",
            "pace_adjust",
        }:
            return False

        return True


    # --------------------------------------------------------------------------
    # Injection
    # --------------------------------------------------------------------------

    def inject(
        self,
        intent: Dict[str, Any],
        state: Dict[str, Any],
    ) -> Optional[Dict[str, Any]]:
        now = time.time()

        if (now - self._last_injection) < self._min_interval:
            return None

        if not self._validate_context(state):
            return None

        if not self._validate_intent(intent):
            return None

        self._last_injection = now

        # Produce a *bounded* MAVLink intent envelope
        return {
            "mavlink_intent": intent["type"],
            "parameters": intent.get("params", {}),
            "timestamp": now,
            "source": "camera_director",
        }


    # --------------------------------------------------------------------------
    # Reset
    # --------------------------------------------------------------------------

    def reset(self) -> None:
        """
        Reset injection timing (link reset / mission restart).
        """
        self._last_injection = 0.0


