# ==============================================================================
# CHUNK 86 X 06 — VISION → CINEMATIC SEMANTIC BRIDGE
# ==============================================================================
#
# Purpose:
#   Convert low-level vision outputs (detections, tracks, depth,
#   saliency) into high-level cinematic semantics usable by the
#   Camera Director and mission logic.
#
# Backbone truth:
#   Vision is data. Cinema is meaning.
#
# ==============================================================================

from typing import Dict, List, Any
import numpy as np


class VisionCinematicSemanticBridge:
    """
    Semantic elevation layer for visual perception.
    Transforms raw perception into entities, roles, importance,
    and cinematic affordances (subject, background, threat, beauty).
    """

    __slots__ = (
        "_temporal_memory",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.85):
        self._inertia = float(np.clip(inertia, 0.7, 0.95))
        self._temporal_memory: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Semantic inference
    # --------------------------------------------------------------------------

    def _infer_entities(
        self,
        detections: List[Dict[str, Any]],
    ) -> Dict[str, Dict[str, float]]:
        entities: Dict[str, Dict[str, float]] = {}

        for det in detections:
            label = det.get("label")
            if not label:
                continue

            sal = float(det.get("saliency", 0.0))
            motion = float(det.get("motion", 0.0))
            depth = float(det.get("depth", 1.0))

            importance = (
                0.5 * sal
                + 0.3 * motion
                + 0.2 * (1.0 - depth)
            )

            entities[label] = {
                "importance": float(np.clip(importance, 0.0, 1.0)),
                "saliency": sal,
                "motion": motion,
                "depth": depth,
            }

        return entities


    def _classify_roles(
        self,
        entities: Dict[str, Dict[str, float]],
    ) -> Dict[str, str]:
        if not entities:
            return {}

        # Highest importance becomes primary subject
        primary = max(
            entities.items(),
            key=lambda kv: kv[1]["importance"],
        )[0]

        roles = {}
        for label, data in entities.items():
            if label == primary:
                roles[label] = "subject"
            elif data["importance"] > 0.4:
                roles[label] = "supporting"
            else:
                roles[label] = "background"

        return roles


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        detections = metrics.get("vision_detections")

        if not isinstance(detections, list):
            return metrics

        entities = self._infer_entities(detections)
        roles = self._classify_roles(entities)

        # Temporal smoothing of importance
        for k, v in entities.items():
            prev = self._temporal_memory.get(k, v["importance"])
            self._temporal_memory[k] = (
                prev * self._inertia
                + v["importance"] * (1.0 - self._inertia)
            )
            v["importance"] = self._temporal_memory[k]

        out = dict(metrics)

        out["cinematic_entities"] = entities
        out["cinematic_roles"] = roles
        out["primary_subject"] = next(
            (k for k, r in roles.items() if r == "subject"),
            None,
        )

        return out


    def reset(self) -> None:
        """
        Clear temporal semantic memory (scene cut).
        """
        self._temporal_memory.clear()


