# CHUNK 86 X 07 — AI MISSION GRAMMAR INTERPRETER
# ==============================================================================
#
# Purpose:
#   Convert semantic intent (from cloud NLP or onboard reasoning)
#   into structured, machine-executable mission primitives that
#   remain safe, interruptible, and cinematographically meaningful.
#
# Backbone truth:
#   Language is ambiguous. Missions must not be.
#
# ==============================================================================

from typing import Dict, Any, Optional, List


class AIMissionGrammarInterpreter:
    """
    Mission grammar interpreter.
    Translates high-level intent into a bounded mission graph
    composed of validated cinematic and flight primitives.
    """

    __slots__ = (
        "_supported_primitives",
    )

    def __init__(self):
        self._supported_primitives = {
            "follow_subject",
            "orbit_subject",
            "hold_position",
            "reframe_subject",
            "adjust_pacing",
            "maintain_distance",
        }


    # --------------------------------------------------------------------------
    # Primitive validation
    # --------------------------------------------------------------------------

    def _validate_primitive(self, p: Dict[str, Any]) -> bool:
        if not isinstance(p, dict):
            return False

        if p.get("type") not in self._supported_primitives:
            return False

        if "confidence" in p and p["confidence"] < 0.4:
            return False

        return True


    # --------------------------------------------------------------------------
    # Grammar interpretation
    # --------------------------------------------------------------------------

    def interpret(
        self,
        intent: Dict[str, Any],
    ) -> Optional[List[Dict[str, Any]]]:
        if not isinstance(intent, dict):
            return None

        primitives = intent.get("primitives")
        if not isinstance(primitives, list):
            return None

        mission: List[Dict[str, Any]] = []

        for p in primitives:
            if not self._validate_primitive(p):
                continue

            mission.append({
                "type": p["type"],
                "params": p.get("params", {}),
                "confidence": p.get("confidence", 0.5),
            })

        if not mission:
            return None

        return mission


    # --------------------------------------------------------------------------
    # Reset
    # --------------------------------------------------------------------------

    def reset(self) -> None:
        """
        Stateless interpreter — no reset required.
        """
        pass


