# CHUNK 86 X 08 — CLOUD NATURAL-LANGUAGE INTENT PARSER
# ==============================================================================
#
# Purpose:
#   Convert unrestricted human natural language (voice or text)
#   into structured, confidence-scored cinematic mission intent
#   using cloud-scale language intelligence.
#
# Backbone truth:
#   Humans speak in stories. Systems must extract intent.
#
# ==============================================================================

from typing import Dict, Any, List
import time


class CloudNaturalLanguageIntentParser:
    """
    Cloud-level natural language intent parser.
    Interfaces with LLM-class models (GPT / Gemini / Claude) to
    extract cinematic mission primitives with uncertainty modeling.
    """

    __slots__ = (
        "_confidence_floor",
        "_last_parse_time",
    )

    def __init__(self, confidence_floor: float = 0.45):
        self._confidence_floor = float(
            max(0.3, min(confidence_floor, 0.7))
        )
        self._last_parse_time: float = 0.0


    # --------------------------------------------------------------------------
    # LLM response validation
    # --------------------------------------------------------------------------

    def _validate_llm_output(self, payload: Dict[str, Any]) -> bool:
        if not isinstance(payload, dict):
            return False

        if "primitives" not in payload:
            return False

        if not isinstance(payload["primitives"], list):
            return False

        return True


    # --------------------------------------------------------------------------
    # Parse
    # --------------------------------------------------------------------------

    def parse(
        self,
        llm_payload: Dict[str, Any],
    ) -> Dict[str, Any]:
        now = time.time()
        self._last_parse_time = now

        if not self._validate_llm_output(llm_payload):
            return {
                "primitives": [],
                "confidence": 0.0,
                "timestamp": now,
            }

        primitives: List[Dict[str, Any]] = []
        confidences: List[float] = []

        for p in llm_payload["primitives"]:
            conf = float(p.get("confidence", 0.0))
            if conf < self._confidence_floor:
                continue

            primitives.append({
                "type": p.get("type"),
                "params": p.get("params", {}),
                "confidence": conf,
            })
            confidences.append(conf)

        overall_confidence = (
            sum(confidences) / len(confidences)
            if confidences else 0.0
        )

        return {
            "primitives": primitives,
            "confidence": overall_confidence,
            "timestamp": now,
        }


    # --------------------------------------------------------------------------
    # Reset
    # --------------------------------------------------------------------------

    def reset(self) -> None:
        """
        Reset parser timing (session reset).
        """
        self._last_parse_time = 0.0


