# ==============================================================================
# CHUNK 86 X 09 — VISION-GUIDED SUBJECT LOCK ENGINE
# ==============================================================================
#
# Purpose:
#   Establish and maintain a hard, cinematic-grade subject lock
#   using multi-cue vision (appearance, motion, depth, saliency).
#
# Backbone truth:
#   Without subject lock, there is no autonomous cinematography.
#
# ==============================================================================

from typing import Dict, Any, Optional
import numpy as np


class VisionGuidedSubjectLockEngine:
    """
    Cinematic subject locking authority.
    Maintains a persistent subject identity across occlusion,
    motion, scale change, and viewpoint shifts.
    """

    __slots__ = (
        "_locked_id",
        "_lock_strength",
        "_appearance_memory",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.88):
        self._inertia = float(np.clip(inertia, 0.8, 0.97))
        self._locked_id: Optional[str] = None
        self._lock_strength: float = 0.0
        self._appearance_memory: Dict[str, np.ndarray] = {}


    # --------------------------------------------------------------------------
    # Candidate scoring
    # --------------------------------------------------------------------------

    def _score_candidate(
        self,
        entity: Dict[str, Any],
        appearance: Optional[np.ndarray],
    ) -> float:
        importance = entity.get("importance", 0.0)
        motion = entity.get("motion", 0.0)
        depth = entity.get("depth", 1.0)

        score = (
            0.45 * importance
            + 0.35 * motion
            + 0.20 * (1.0 - depth)
        )

        if appearance is not None and self._locked_id in self._appearance_memory:
            prev = self._appearance_memory[self._locked_id]
            if prev.shape == appearance.shape:
                similarity = float(
                    np.dot(prev, appearance)
                    / (np.linalg.norm(prev) * np.linalg.norm(appearance) + 1e-6)
                )
                score += 0.25 * similarity

        return float(np.clip(score, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        entities = metrics.get("cinematic_entities")
        appearances = metrics.get("entity_appearances", {})

        if not isinstance(entities, dict):
            return metrics

        best_id = None
        best_score = 0.0

        for eid, data in entities.items():
            appearance = appearances.get(eid)
            score = self._score_candidate(data, appearance)

            if score > best_score:
                best_score = score
                best_id = eid

        if best_id:
            if self._locked_id == best_id:
                self._lock_strength = min(
                    1.0,
                    self._lock_strength * self._inertia + 0.2,
                )
            else:
                self._locked_id = best_id
                self._lock_strength = best_score

            # Update appearance memory
            if appearances.get(best_id) is not None:
                self._appearance_memory[best_id] = appearances[best_id]

        out = dict(metrics)

        out["locked_subject_id"] = self._locked_id
        out["subject_lock_strength"] = self._lock_strength
        out["subject_lock_active"] = self._lock_strength > 0.4

        return out


    def reset(self) -> None:
        """
        Clear subject lock (scene cut / explicit release).
        """
        self._locked_id = None
        self._lock_strength = 0.0
        self._appearance_memory.clear()


