# ==============================================================================
# CHUNK 86 X 10 — MISSION → MAVLINK BEHAVIOR PLANNER
# ==============================================================================
#
# Purpose:
#   Convert validated mission primitives + subject lock state into
#   bounded, FC-safe behavioral directives consumable by ArduPilot.
#
# Backbone truth:
#   The planner suggests motion — the FC executes physics.
#
# ==============================================================================

from typing import Dict, Any, Optional
import math


class MissionToMAVLinkBehaviorPlanner:
    """
    Mission behavior planner.
    Maps cinematic mission intent into velocity, yaw, and position
    envelopes that remain within FC-controlled stabilization.
    """

    __slots__ = (
        "_last_plan",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.85):
        self._inertia = max(0.7, min(inertia, 0.95))
        self._last_plan: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Primitive planners
    # --------------------------------------------------------------------------

    def _plan_follow(
        self,
        params: Dict[str, Any],
        state: Dict[str, Any],
    ) -> Dict[str, float]:
        distance = float(params.get("distance", 8.0))
        max_speed = float(params.get("max_speed", 3.0))

        rel_x = float(state.get("subject_rel_x", 0.0))
        rel_y = float(state.get("subject_rel_y", distance))
        rel_z = float(state.get("subject_rel_z", 0.0))

        vx = max(-max_speed, min(max_speed, rel_x * 0.4))
        vy = max(-max_speed, min(max_speed, (rel_y - distance) * 0.4))
        vz = max(-1.0, min(1.0, -rel_z * 0.3))

        yaw_rate = max(-0.6, min(0.6, math.atan2(rel_x, rel_y)))

        return {
            "vx": vx,
            "vy": vy,
            "vz": vz,
            "yaw_rate": yaw_rate,
        }


    def _plan_orbit(
        self,
        params: Dict[str, Any],
        state: Dict[str, Any],
    ) -> Dict[str, float]:
        radius = float(params.get("radius", 10.0))
        angular_speed = float(params.get("angular_speed", 0.3))

        angle = float(state.get("orbit_angle", 0.0))

        vx = -angular_speed * radius * math.sin(angle)
        vy = angular_speed * radius * math.cos(angle)
        yaw_rate = angular_speed

        return {
            "vx": vx,
            "vy": vy,
            "vz": 0.0,
            "yaw_rate": yaw_rate,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def plan(
        self,
        primitive: Dict[str, Any],
        state: Dict[str, Any],
    ) -> Optional[Dict[str, float]]:
        ptype = primitive.get("type")

        if ptype == "follow_subject":
            plan = self._plan_follow(primitive.get("params", {}), state)
        elif ptype == "orbit_subject":
            plan = self._plan_orbit(primitive.get("params", {}), state)
        else:
            return None

        # Smooth plans
        if not self._last_plan:
            self._last_plan = plan
        else:
            blended = {}
            for k, v in plan.items():
                prev = self._last_plan.get(k, 0.0)
                blended[k] = prev * self._inertia + v * (1.0 - self._inertia)
            self._last_plan = blended

        return dict(self._last_plan)


    def reset(self) -> None:
        """
        Reset planner memory (mode change).
        """
        self._last_plan.clear()


