# ==============================================================================
# CHUNK 86 X 12 — MULTI-TARGET ARBITRATION ENGINE
# ==============================================================================
#
# Purpose:
#   Resolve competition between multiple viable subjects in complex
#   scenes while preserving narrative intent, emotional continuity,
#   and cinematic stability.
#
# Backbone truth:
#   Cinema chooses deliberately — never reflexively.
#
# ==============================================================================

from typing import Dict, Any, Optional
import numpy as np


class MultiTargetArbitrationEngine:
    """
    Cinematic multi-target arbitration authority.
    Selects, maintains, or transitions subject focus using importance,
    temporal continuity, mission relevance, and emotional context.
    """

    __slots__ = (
        "_current_target",
        "_commitment",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.8, 0.97))
        self._current_target: Optional[str] = None
        self._commitment: float = 0.0


    # --------------------------------------------------------------------------
    # Arbitration scoring
    # --------------------------------------------------------------------------

    def _score(
        self,
        entity: Dict[str, Any],
        mission_bias: float,
    ) -> float:
        importance = entity.get("importance", 0.0)
        motion = entity.get("motion", 0.0)
        depth = entity.get("depth", 1.0)

        score = (
            0.5 * importance
            + 0.3 * mission_bias
            + 0.2 * (1.0 - depth)
        )

        score += 0.1 * motion
        return float(np.clip(score, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        entities = metrics.get("cinematic_entities", {})
        mission_focus = metrics.get("mission_focus", {})

        if not isinstance(entities, dict) or not entities:
            return metrics

        best_id = None
        best_score = 0.0

        for eid, data in entities.items():
            bias = float(mission_focus.get(eid, 0.0))
            score = self._score(data, bias)

            if score > best_score:
                best_score = score
                best_id = eid

        # Commitment logic (avoid rapid switching)
        if best_id:
            if self._current_target == best_id:
                self._commitment = min(
                    1.0,
                    self._commitment * self._inertia + 0.15,
                )
            else:
                transition_cost = max(0.0, self._commitment - best_score)
                if transition_cost < 0.3:
                    self._current_target = best_id
                    self._commitment = best_score
                else:
                    self._commitment *= self._inertia

        out = dict(metrics)

        out["arbitrated_subject_id"] = self._current_target
        out["subject_commitment"] = self._commitment
        out["subject_transition_allowed"] = self._commitment < 0.6

        return out


    def reset(self) -> None:
        """
        Clear arbitration state (scene cut).
        """
        self._current_target = None
        self._commitment = 0.0


