# ==============================================================================
# CHUNK 86 X 13 — SUBJECT REACQUISITION & OCCLUSION RECOVERY
# ==============================================================================
#
# Purpose:
#   Recover lost or occluded subjects gracefully without abrupt
#   camera motion, narrative breaks, or identity thrashing.
#
# Backbone truth:
#   Loss is inevitable. Recovery defines quality.
#
# ==============================================================================

from typing import Dict, Any, Optional
import time
import numpy as np


class SubjectReacquisitionOcclusionRecovery:
    """
    Occlusion-aware subject recovery system.
    Maintains probabilistic belief over subject identity and position
    during temporary loss, enabling smooth reacquisition.
    """

    __slots__ = (
        "_last_seen_time",
        "_belief_strength",
        "_max_occlusion_time",
        "_decay",
    )

    def __init__(
        self,
        max_occlusion_time: float = 3.0,
        decay: float = 0.85,
    ):
        self._max_occlusion_time = float(max(1.0, max_occlusion_time))
        self._decay = float(np.clip(decay, 0.7, 0.95))
        self._last_seen_time: Optional[float] = None
        self._belief_strength: float = 0.0


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        now = time.time()
        subject_id = metrics.get("locked_subject_id")
        visible = metrics.get("subject_lock_active", False)

        if visible and subject_id:
            self._last_seen_time = now
            self._belief_strength = min(1.0, self._belief_strength + 0.2)
        else:
            if self._last_seen_time is not None:
                dt = now - self._last_seen_time
                if dt < self._max_occlusion_time:
                    self._belief_strength *= self._decay
                else:
                    self._belief_strength = 0.0
                    self._last_seen_time = None

        out = dict(metrics)

        out["subject_belief_strength"] = self._belief_strength
        out["subject_occluded"] = (
            not visible and self._belief_strength > 0.2
        )
        out["reacquisition_allowed"] = (
            self._belief_strength > 0.1
        )

        return out


    def reset(self) -> None:
        """
        Clear recovery state (hard cut or mission abort).
        """
        self._last_seen_time = None
        self._belief_strength = 0.0


