# ==============================================================================
# CHUNK 86 X 14 — CINEMATIC CAMERA–GIMBAL COUPLING LAYER
# ==============================================================================
#
# Purpose:
#   Bind high-level cinematic camera intent to real gimbal physics
#   while preserving emotional framing, inertia, and shot continuity.
#
# Backbone truth:
#   Emotion dies if the gimbal does not understand intent.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class CinematicCameraGimbalCoupling:
    """
    Camera–gimbal intent coupling system.
    Converts camera framing intent into physically achievable gimbal
    trajectories while preserving expressive timing and inertia.
    """

    __slots__ = (
        "_pitch",
        "_yaw",
        "_roll",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.8, 0.97))
        self._pitch: float = 0.0
        self._yaw: float = 0.0
        self._roll: float = 0.0


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        intent = metrics.get("camera_actuation_safe")
        if not isinstance(intent, dict):
            return metrics

        target_pitch = float(intent.get("tilt_speed", 0.0))
        target_yaw = float(intent.get("pan_speed", 0.0))
        target_roll = float(intent.get("roll", 0.0))

        self._pitch = (
            self._pitch * self._inertia
            + target_pitch * (1.0 - self._inertia)
        )
        self._yaw = (
            self._yaw * self._inertia
            + target_yaw * (1.0 - self._inertia)
        )
        self._roll = (
            self._roll * self._inertia
            + target_roll * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["gimbal_command"] = {
            "pitch": self._pitch,
            "yaw": self._yaw,
            "roll": self._roll,
        }

        return out


    def reset(self) -> None:
        """
        Reset gimbal coupling state (hard cut).
        """
        self._pitch = 0.0
        self._yaw = 0.0
        self._roll = 0.0


