# ==============================================================================
# CHUNK 86 X 15 — EXPRESSIVE CAMERA TRAJECTORY SYNTHESIZER
# ==============================================================================
#
# Purpose:
#   Synthesize continuous, emotionally expressive camera motion
#   trajectories that encode intent, anticipation, and release
#   instead of reactive frame-to-frame steering.
#
# Backbone truth:
#   Cinema moves with meaning, not correction.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class ExpressiveCameraTrajectorySynthesizer:
    """
    Cinematic camera trajectory generator.
    Converts momentary camera intent into temporally shaped
    trajectories with anticipation, overshoot, and settling.
    """

    __slots__ = (
        "_state",
        "_velocity",
        "_inertia",
        "_expressiveness",
    )

    def __init__(
        self,
        inertia: float = 0.85,
        expressiveness: float = 0.6,
    ):
        self._inertia = float(np.clip(inertia, 0.7, 0.95))
        self._expressiveness = float(np.clip(expressiveness, 0.2, 1.0))
        self._state = {
            "pan": 0.0,
            "tilt": 0.0,
            "zoom": 0.0,
        }
        self._velocity = {
            "pan": 0.0,
            "tilt": 0.0,
            "zoom": 0.0,
        }


    # --------------------------------------------------------------------------
    # Trajectory synthesis
    # --------------------------------------------------------------------------

    def _step_axis(
        self,
        axis: str,
        target: float,
    ) -> float:
        pos = self._state[axis]
        vel = self._velocity[axis]

        error = target - pos

        accel = (
            error * (0.6 + 0.6 * self._expressiveness)
            - vel * (0.4 + 0.3 * self._expressiveness)
        )

        vel = vel * self._inertia + accel * (1.0 - self._inertia)
        pos = pos + vel

        self._velocity[axis] = vel
        self._state[axis] = pos

        return pos


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        intent = metrics.get("camera_actuation_safe")
        if not isinstance(intent, dict):
            return metrics

        pan_tgt = float(intent.get("pan_speed", 0.0))
        tilt_tgt = float(intent.get("tilt_speed", 0.0))
        zoom_tgt = float(intent.get("zoom_rate", 0.0))

        pan = self._step_axis("pan", pan_tgt)
        tilt = self._step_axis("tilt", tilt_tgt)
        zoom = self._step_axis("zoom", zoom_tgt)

        out = dict(metrics)

        out["camera_trajectory"] = {
            "pan": pan,
            "tilt": tilt,
            "zoom": zoom,
        }

        out["trajectory_expressive"] = True

        return out


    def reset(self) -> None:
        """
        Reset trajectory memory (scene cut).
        """
        for k in self._state:
            self._state[k] = 0.0
            self._velocity[k] = 0.0


