#   composition evolves with feeling, not just geometry.
#
# Backbone truth:
#   Emotion bends the frame — even when the subject stays centered.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class EmotionalFramingBiasEngine:
    """
    Emotion-aware framing bias system.
    Applies low-amplitude compositional offsets based on emotional
    state (tension, awe, intimacy, isolation) without breaking lock.
    """

    __slots__ = (
        "_bias_x",
        "_bias_y",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.92):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._bias_x: float = 0.0
        self._bias_y: float = 0.0


    # --------------------------------------------------------------------------
    # Bias synthesis
    # --------------------------------------------------------------------------

    def _target_bias(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        # Emotional components expected to be normalized [0..1]
        tension = float(metrics.get("emotion_tension", 0.0))
        awe = float(metrics.get("emotion_awe", 0.0))
        intimacy = float(metrics.get("emotion_intimacy", 0.0))
        isolation = float(metrics.get("emotion_isolation", 0.0))

        # Horizontal bias: tension & isolation compress frame
        x = (
            -0.15 * tension
            + 0.10 * awe
            - 0.20 * isolation
        )

        # Vertical bias: awe lifts, intimacy lowers
        y = (
            0.20 * awe
            - 0.15 * intimacy
            - 0.05 * tension
        )

        return {
            "x": float(np.clip(x, -0.3, 0.3)),
            "y": float(np.clip(y, -0.3, 0.3)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_bias(metrics)

        self._bias_x = (
            self._bias_x * self._inertia
            + target["x"] * (1.0 - self._inertia)
        )
        self._bias_y = (
            self._bias_y * self._inertia
            + target["y"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["framing_bias"] = {
            "x": self._bias_x,
            "y": self._bias_y,
        }
        out["framing_bias_active"] = True

        return out


    def reset(self) -> None:
        """
        Reset framing bias (hard cut).
        """
        self._bias_x = 0.0
        self._bias_y = 0.0


