#   distance into a coherent spatial strategy.
#
# Backbone truth:
#   Shot scale is emotional language, not just distance.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class ShotScaleDistanceOrchestrator:
    """
    Shot-scale orchestration engine.
    Determines desired subject distance and zoom behavior based on
    emotional state, narrative phase, and cinematic momentum.
    """

    __slots__ = (
        "_target_distance",
        "_target_scale",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.97))
        self._target_distance: float = 8.0
        self._target_scale: str = "medium"


    # --------------------------------------------------------------------------
    # Scale inference
    # --------------------------------------------------------------------------

    def _infer_scale(self, metrics: Dict[str, Any]) -> str:
        tension = float(metrics.get("emotion_tension", 0.0))
        intimacy = float(metrics.get("emotion_intimacy", 0.0))
        awe = float(metrics.get("emotion_awe", 0.0))
        phase = metrics.get("narrative_phase", "development")

        if phase == "climax" and awe > 0.5:
            return "wide"
        if intimacy > 0.5:
            return "close"
        if tension > 0.6:
            return "medium"
        return "medium"


    def _scale_to_distance(self, scale: str) -> float:
        return {
            "wide": 15.0,
            "medium": 8.0,
            "close": 4.0,
        }.get(scale, 8.0)


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        scale = self._infer_scale(metrics)
        desired_distance = self._scale_to_distance(scale)

        self._target_distance = (
            self._target_distance * self._inertia
            + desired_distance * (1.0 - self._inertia)
        )

        self._target_scale = scale

        out = dict(metrics)

        out["shot_scale"] = self._target_scale
        out["desired_subject_distance"] = self._target_distance

        return out


    def reset(self) -> None:
        """
        Reset shot-scale orchestration (scene cut).
        """
        self._target_distance = 8.0
        self._target_scale = "medium"


