#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class CinematicExposureMotionCoupling:
    """
    Exposure–motion coupling engine.
    Modulates exposure intent based on motion energy, emotional
    momentum, and narrative phase to avoid robotic AE behavior.
    """

    __slots__ = (
        "_exposure_bias",
        "_shutter_bias",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._exposure_bias: float = 0.0
        self._shutter_bias: float = 0.0


    # --------------------------------------------------------------------------
    # Bias inference
    # --------------------------------------------------------------------------

    def _target_bias(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        motion = float(metrics.get("motion_energy", 0.0))
        momentum = float(metrics.get("emotional_momentum", 0.0))
        tension = float(metrics.get("emotion_tension", 0.0))
        phase = metrics.get("narrative_phase", "development")

        # Exposure: slow scenes open up, fast scenes tighten
        exposure = (
            0.25 * (1.0 - motion)
            + 0.15 * momentum
            - 0.20 * tension
        )

        # Shutter intent: motion blur allowed in calm, reduced in tension
        shutter = (
            0.30 * motion
            - 0.25 * tension
        )

        # Narrative modulation
        if phase == "climax":
            exposure -= 0.10
            shutter += 0.10
        elif phase == "resolution":
            exposure += 0.15
            shutter -= 0.10

        return {
            "exposure": float(np.clip(exposure, -0.5, 0.5)),
            "shutter": float(np.clip(shutter, -0.5, 0.5)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_bias(metrics)

        self._exposure_bias = (
            self._exposure_bias * self._inertia
            + target["exposure"] * (1.0 - self._inertia)
        )
        self._shutter_bias = (
            self._shutter_bias * self._inertia
            + target["shutter"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["exposure_bias"] = self._exposure_bias
        out["shutter_bias"] = self._shutter_bias
        out["exposure_motion_coupled"] = True

        return out


    def reset(self) -> None:
        """
        Reset exposure–motion coupling (hard cut).
        """
        self._exposure_bias = 0.0
        self._shutter_bias = 0.0


