from typing import Dict, Any
import numpy as np


class SubjectBackgroundDepthSeparationEngine:
    """
    Perceptual depth separation system.
    Manipulates contrast, exposure, motion emphasis, and framing
    asymmetrically between subject and background regions.
    """

    __slots__ = (
        "_subject_boost",
        "_background_suppress",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._subject_boost: float = 0.0
        self._background_suppress: float = 0.0


    # --------------------------------------------------------------------------
    # Separation inference
    # --------------------------------------------------------------------------

    def _target_separation(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        lock = float(metrics.get("subject_lock_strength", 0.0))
        motion = float(metrics.get("motion_energy", 0.0))
        awe = float(metrics.get("emotion_awe", 0.0))
        tension = float(metrics.get("emotion_tension", 0.0))

        subject = (
            0.35 * lock
            + 0.25 * awe
            + 0.15 * (1.0 - motion)
        )

        background = (
            0.30 * tension
            + 0.20 * motion
        )

        return {
            "subject": float(np.clip(subject, 0.0, 1.0)),
            "background": float(np.clip(background, 0.0, 1.0)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_separation(metrics)

        self._subject_boost = (
            self._subject_boost * self._inertia
            + target["subject"] * (1.0 - self._inertia)
        )
        self._background_suppress = (
            self._background_suppress * self._inertia
            + target["background"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["subject_emphasis"] = {
            "contrast": 0.10 * self._subject_boost,
            "exposure": 0.08 * self._subject_boost,
            "sharpness": 0.12 * self._subject_boost,
        }

        out["background_emphasis"] = {
            "contrast": -0.10 * self._background_suppress,
            "exposure": -0.12 * self._background_suppress,
            "motion_softening": 0.15 * self._background_suppress,
        }

        out["depth_separation_active"] = True

        return out


    def reset(self) -> None:
        """
        Reset depth separation (hard cut).
        """
        self._subject_boost = 0.0
        self._background_suppress = 0.0


