from typing import Dict, Any
import numpy as np


class EmotionAwareLensBreathingCompensation:
    """
    Emotion-aware lens breathing compensator.
    Modulates perceived frame scale, exposure, and framing bias
    during zoom/focus changes to either suppress or gently stylize
    breathing based on emotional context.
    """

    __slots__ = (
        "_scale_bias",
        "_exposure_bias",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.92):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._scale_bias: float = 0.0
        self._exposure_bias: float = 0.0


    # --------------------------------------------------------------------------
    # Breathing intent inference
    # --------------------------------------------------------------------------

    def _target_bias(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        zoom_rate = float(metrics.get("camera_trajectory", {}).get("zoom", 0.0))
        tension = float(metrics.get("emotion_tension", 0.0))
        intimacy = float(metrics.get("emotion_intimacy", 0.0))
        awe = float(metrics.get("emotion_awe", 0.0))
        phase = metrics.get("narrative_phase", "development")

        breathing_intensity = abs(zoom_rate)

        # Default: suppress breathing
        scale = -0.6 * breathing_intensity
        exposure = -0.3 * breathing_intensity

        # Emotional exceptions
        if intimacy > 0.5:
            # Allow gentle breathing to feel organic
            scale *= 0.3
            exposure *= 0.3
        elif awe > 0.5 and phase == "climax":
            # Stylize breathing as expansion
            scale = 0.4 * breathing_intensity
            exposure = 0.2 * breathing_intensity
        elif tension > 0.6:
            # Aggressively suppress during tension
            scale *= 1.2
            exposure *= 1.2

        return {
            "scale": float(np.clip(scale, -0.4, 0.4)),
            "exposure": float(np.clip(exposure, -0.3, 0.3)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_bias(metrics)

        self._scale_bias = (
            self._scale_bias * self._inertia
            + target["scale"] * (1.0 - self._inertia)
        )
        self._exposure_bias = (
            self._exposure_bias * self._inertia
            + target["exposure"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["lens_breathing_compensation"] = {
            "scale_bias": self._scale_bias,
            "exposure_bias": self._exposure_bias,
        }
        out["lens_breathing_managed"] = True

        return out


    def reset(self) -> None:
        """
        Reset breathing compensation (hard cut).
        """
        self._scale_bias = 0.0
        self._exposure_bias = 0.0


