#   Control shot rhythm at a sub-second level so motion, camera
#   changes, and holds feel intentional rather than mechanically smooth.
#
# Backbone truth:
#   Cinema breathes. Rhythm is breath.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class ShotRhythmMicroPacingController:
    """
    Micro-pacing and rhythm controller.
    Modulates how quickly camera intent is allowed to evolve based on
    emotional pressure, narrative phase, and recent change history.
    """

    __slots__ = (
        "_pace",
        "_last_change",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._pace: float = 1.0
        self._last_change: float = time.time()


    # --------------------------------------------------------------------------
    # Pace inference
    # --------------------------------------------------------------------------

    def _target_pace(self, metrics: Dict[str, Any]) -> float:
        tension = float(metrics.get("emotion_tension", 0.0))
        awe = float(metrics.get("emotion_awe", 0.0))
        momentum = float(metrics.get("emotional_momentum", 0.0))
        phase = metrics.get("narrative_phase", "development")

        pace = (
            1.0
            + 0.8 * tension
            - 0.6 * awe
            + 0.4 * momentum
        )

        if phase == "resolution":
            pace *= 0.7
        elif phase == "climax":
            pace *= 1.1

        return float(np.clip(pace, 0.4, 2.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        now = time.time()
        target = self._target_pace(metrics)

        self._pace = (
            self._pace * self._inertia
            + target * (1.0 - self._inertia)
        )

        dt = max(1e-3, now - self._last_change)
        self._last_change = now

        out = dict(metrics)

        out["micro_pace"] = self._pace
        out["temporal_stretch"] = 1.0 / self._pace
        out["rhythm_dt"] = dt

        return out


    def reset(self) -> None:
        """
        Reset pacing state (hard cut).
        """
        self._pace = 1.0
        self._last_change = time.time()


