from typing import Dict, Any
import numpy as np


class EmotionalHighlightShadowSculptor:
    """
    Emotion-driven highlight & shadow sculpting engine.
    Shapes tonal extremes based on emotional intent, depth context,
    and subject importance rather than raw luminance statistics.
    """

    __slots__ = (
        "_highlight_bias",
        "_shadow_bias",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.92):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._highlight_bias: float = 0.0
        self._shadow_bias: float = 0.0


    # --------------------------------------------------------------------------
    # Bias inference
    # --------------------------------------------------------------------------

    def _target_bias(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        tension = float(metrics.get("emotion_tension", 0.0))
        awe = float(metrics.get("emotion_awe", 0.0))
        grief = float(metrics.get("emotion_grief", 0.0))
        relief = float(metrics.get("emotion_relief", 0.0))
        depth = float(metrics.get("subject_depth", 0.5))
        phase = metrics.get("narrative_phase", "development")

        # Highlights: awe & relief allow lift, tension restrains
        highlight = (
            0.35 * awe
            + 0.25 * relief
            - 0.30 * tension
        )

        # Shadows: grief & tension deepen, resolution releases
        shadow = (
            0.40 * grief
            + 0.30 * tension
            - 0.20 * relief
        )

        # Depth modulation — foreground gets priority
        highlight *= (1.0 - 0.3 * depth)
        shadow *= (1.0 + 0.4 * depth)

        # Narrative shaping
        if phase == "climax":
            highlight *= 0.8
            shadow *= 1.2
        elif phase == "resolution":
            highlight *= 1.1
            shadow *= 0.7

        return {
            "highlight": float(np.clip(highlight, -0.5, 0.5)),
            "shadow": float(np.clip(shadow, -0.6, 0.6)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_bias(metrics)

        self._highlight_bias = (
            self._highlight_bias * self._inertia
            + target["highlight"] * (1.0 - self._inertia)
        )
        self._shadow_bias = (
            self._shadow_bias * self._inertia
            + target["shadow"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["tonal_sculpting"] = {
            "highlight_bias": self._highlight_bias,
            "shadow_bias": self._shadow_bias,
        }
        out["tonal_sculpting_active"] = True

        return out


    def reset(self) -> None:
        """
        Reset highlight/shadow sculpting (hard cut).
        """
        self._highlight_bias = 0.0
        self._shadow_bias = 0.0


