from typing import Dict, Any
import numpy as np
import time


class CinematicSilenceHoldTimeManager:
    """
    Silence & hold-time orchestration engine.
    Determines when motion and camera evolution should slow,
    pause, or hold to allow emotional absorption.
    """

    __slots__ = (
        "_hold_factor",
        "_last_peak_time",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._hold_factor: float = 0.0
        self._last_peak_time: float = 0.0


    # --------------------------------------------------------------------------
    # Hold inference
    # --------------------------------------------------------------------------

    def _target_hold(self, metrics: Dict[str, Any]) -> float:
        awe = float(metrics.get("emotion_awe", 0.0))
        grief = float(metrics.get("emotion_grief", 0.0))
        relief = float(metrics.get("emotion_relief", 0.0))
        momentum = float(metrics.get("emotional_momentum", 0.0))
        phase = metrics.get("narrative_phase", "development")

        hold = (
            0.6 * awe
            + 0.5 * grief
            + 0.3 * relief
        )

        hold *= (1.0 - 0.5 * momentum)

        if phase == "climax":
            hold *= 0.6
        elif phase == "resolution":
            hold *= 1.2

        return float(np.clip(hold, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_hold(metrics)

        self._hold_factor = (
            self._hold_factor * self._inertia
            + target * (1.0 - self._inertia)
        )

        now = time.time()
        if metrics.get("peak_event", False):
            self._last_peak_time = now

        out = dict(metrics)

        out["hold_factor"] = self._hold_factor
        out["allow_motion"] = self._hold_factor < 0.6
        out["hold_active"] = self._hold_factor > 0.3
        out["time_since_peak"] = now - self._last_peak_time

        return out


    def reset(self) -> None:
        """
        Reset silence/hold state (hard cut).
        """
        self._hold_factor = 0.0
        self._last_peak_time = 0.0


