# ==============================================================================
# CHUNK 86 X 25 — SHOT ENDING & TRANSITION INTENTION ENGINE
# ==============================================================================
#
# Purpose:
#   Determine when a shot is emotionally and narratively complete,
#   and shape the transition into the next shot without abruptness,
#   loss of intent, or mechanical timing.
#
# Backbone truth:
#   Shots do not end — they resolve.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class ShotEndingTransitionIntentionEngine:
    """
    Shot ending & transition intention controller.
    Evaluates emotional saturation, motion settling, and narrative
    readiness to decide when a shot may gracefully conclude.
    """

    __slots__ = (
        "_completion",
        "_cooldown",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._completion: float = 0.0
        self._cooldown: float = 0.0


    # --------------------------------------------------------------------------
    # Completion inference
    # --------------------------------------------------------------------------

    def _target_completion(self, metrics: Dict[str, Any]) -> float:
        momentum = float(metrics.get("emotional_momentum", 0.0))
        hold = float(metrics.get("hold_factor", 0.0))
        motion = float(metrics.get("motion_energy", 0.0))
        relief = float(metrics.get("emotion_relief", 0.0))
        phase = metrics.get("narrative_phase", "development")

        completion = (
            0.5 * relief
            + 0.4 * hold
            + 0.3 * (1.0 - motion)
        )

        completion *= (1.0 - 0.6 * momentum)

        if phase == "resolution":
            completion *= 1.2

        return float(np.clip(completion, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_completion(metrics)

        self._completion = (
            self._completion * self._inertia
            + target * (1.0 - self._inertia)
        )

        # Cooldown prevents immediate re-triggering
        if self._completion > 0.7:
            self._cooldown = min(1.0, self._cooldown + 0.2)
        else:
            self._cooldown *= self._inertia

        out = dict(metrics)

        out["shot_completion"] = self._completion
        out["transition_ready"] = self._completion > 0.6
        out["transition_cooldown"] = self._cooldown

        return out


    def reset(self) -> None:
        """
        Reset transition intention (hard cut).
        """
        self._completion = 0.0
        self._cooldown = 0.0


