# ==============================================================================
# CHUNK 86 X 26 — EMOTIONAL COOLDOWN & POST-PEAK RECOVERY
# ==============================================================================
#
# Purpose:
#   Shape emotional recovery after peaks so intensity decays with
#   narrative grace instead of collapsing or compounding.
#
# Backbone truth:
#   What happens after the peak defines whether it mattered.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class EmotionalCooldownPostPeakRecovery:
    """
    Post-peak emotional recovery engine.
    Introduces refractory periods, asymmetric decay, and memory-aware
    cooldown shaping to prevent emotional inflation.
    """

    __slots__ = (
        "_cooldown_level",
        "_last_peak_time",
        "_refractory",
        "_inertia",
    )

    def __init__(
        self,
        inertia: float = 0.9,
        refractory: float = 3.0,
    ):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._refractory = float(max(1.0, refractory))
        self._cooldown_level: float = 0.0
        self._last_peak_time: float = 0.0


    # --------------------------------------------------------------------------
    # Cooldown inference
    # --------------------------------------------------------------------------

    def _target_cooldown(self, metrics: Dict[str, Any]) -> float:
        tension = float(metrics.get("emotion_tension", 0.0))
        relief = float(metrics.get("emotion_relief", 0.0))
        grief = float(metrics.get("emotion_grief", 0.0))
        momentum = float(metrics.get("emotional_momentum", 0.0))

        cooldown = (
            0.5 * relief
            + 0.4 * grief
            - 0.6 * tension
        )

        cooldown *= (1.0 + 0.5 * momentum)

        return float(np.clip(cooldown, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        now = time.time()

        if metrics.get("peak_event", False):
            self._last_peak_time = now
            self._cooldown_level = max(self._cooldown_level, 0.5)

        target = self._target_cooldown(metrics)

        # Refractory enforcement
        if now - self._last_peak_time < self._refractory:
            target = max(target, 0.4)

        self._cooldown_level = (
            self._cooldown_level * self._inertia
            + target * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["emotional_cooldown"] = self._cooldown_level
        out["cooldown_active"] = self._cooldown_level > 0.3
        out["refractory_remaining"] = max(
            0.0, self._refractory - (now - self._last_peak_time)
        )

        return out


    def reset(self) -> None:
        """
        Reset cooldown state (hard cut).
        """
        self._cooldown_level = 0.0
        self._last_peak_time = 0.0


