#   and flight safety constraints so control transitions are safe,
#   smooth, and intention-preserving.
#
# Backbone truth:
#   Authority must shift without chaos.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class DirectorSafetyOverrideGovernor:
    """
    Director-level authority arbitration system.
    Resolves conflicts between AI autonomy, human override,
    and hard safety constraints with graded dominance.
    """

    __slots__ = (
        "_authority_level",
        "_override_strength",
        "_safety_pressure",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._authority_level: float = 1.0  # 1.0 = AI, 0.0 = Human
        self._override_strength: float = 0.0
        self._safety_pressure: float = 0.0


    # --------------------------------------------------------------------------
    # Authority inference
    # --------------------------------------------------------------------------

    def _target_authority(self, metrics: Dict[str, Any]) -> float:
        human_input = float(metrics.get("human_override_strength", 0.0))
        safety_risk = float(metrics.get("flight_risk_level", 0.0))
        mission_critical = float(metrics.get("mission_criticality", 0.0))

        authority = (
            1.0
            - 0.8 * human_input
            - 1.2 * safety_risk
            + 0.4 * mission_critical
        )

        return float(np.clip(authority, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_authority(metrics)

        self._authority_level = (
            self._authority_level * self._inertia
            + target * (1.0 - self._inertia)
        )

        self._override_strength = 1.0 - self._authority_level
        self._safety_pressure = float(metrics.get("flight_risk_level", 0.0))

        out = dict(metrics)

        out["authority_level"] = self._authority_level
        out["ai_control_enabled"] = self._authority_level > 0.4
        out["human_control_enabled"] = self._authority_level < 0.8
        out["safety_override_active"] = self._safety_pressure > 0.6

        return out


    def reset(self) -> None:
        """
        Reset authority arbitration (hard cut / emergency).
        """
        self._authority_level = 1.0
        self._override_strength = 0.0
        self._safety_pressure = 0.0


