#
# ==============================================================================

from typing import Dict, Any, List, Optional
import numpy as np
import time


class AutonomousShotChainMissionContinuity:
    """
    Autonomous shot chaining engine.
    Generates and maintains a rolling horizon of next-shot intentions
    so transitions feel inevitable, not reactive.
    """

    __slots__ = (
        "_shot_queue",
        "_lookahead",
        "_inertia",
        "_last_update",
    )

    def __init__(
        self,
        lookahead: int = 2,
        inertia: float = 0.9,
    ):
        self._lookahead = int(max(1, lookahead))
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._shot_queue: List[Dict[str, Any]] = []
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Shot proposal synthesis
    # --------------------------------------------------------------------------

    def _propose_next_shot(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        phase = metrics.get("narrative_phase", "development")
        momentum = float(metrics.get("emotional_momentum", 0.0))
        tension = float(metrics.get("emotion_tension", 0.0))
        awe = float(metrics.get("emotion_awe", 0.0))

        if phase == "climax":
            style = "expansive"
        elif tension > 0.6:
            style = "contained"
        elif awe > 0.5:
            style = "revelatory"
        else:
            style = "observational"

        duration = (
            2.0
            + 2.5 * awe
            + 1.5 * (1.0 - tension)
        )

        return {
            "style": style,
            "expected_duration": float(np.clip(duration, 1.5, 6.0)),
            "confidence": 0.6 + 0.3 * momentum,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        now = time.time()

        # Refresh shot queue if needed
        if (
            len(self._shot_queue) < self._lookahead
            or metrics.get("transition_ready", False)
        ):
            self._shot_queue.clear()
            for _ in range(self._lookahead):
                self._shot_queue.append(
                    self._propose_next_shot(metrics)
                )

        out = dict(metrics)

        out["current_shot_plan"] = (
            self._shot_queue[0] if self._shot_queue else None
        )
        out["upcoming_shots"] = self._shot_queue[1:]

        self._last_update = now

        return out


    def reset(self) -> None:
        """
        Reset autonomous shot chain (mission restart).
        """
        self._shot_queue.clear()
        self._last_update = time.time()


