# CHUNK 86 X 29 — HUMAN-IN-THE-LOOP ARBITRATION LAYER
# ==============================================================================
#
# Purpose:
#   Allow seamless, graded human intervention during autonomous
#   operation while preserving cinematic intent, safety, and flow.
#
# Backbone truth:
#   A great director accepts notes without losing the film.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class HumanInTheLoopArbitrationLayer:
    """
    Human-in-the-loop arbitration system.
    Blends human inputs with AI intent using confidence, persistence,
    and safety-aware weighting rather than hard overrides.
    """

    __slots__ = (
        "_human_weight",
        "_ai_weight",
        "_last_human_time",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._human_weight: float = 0.0
        self._ai_weight: float = 1.0
        self._last_human_time: float = 0.0


    # --------------------------------------------------------------------------
    # Weight inference
    # --------------------------------------------------------------------------

    def _target_weights(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        human_strength = float(metrics.get("human_override_strength", 0.0))
        authority = float(metrics.get("authority_level", 1.0))
        safety = float(metrics.get("flight_risk_level", 0.0))

        human = (
            0.9 * human_strength
            + 0.4 * (1.0 - authority)
        )

        # Safety always reduces manual authority
        human *= (1.0 - 0.8 * safety)

        human = float(np.clip(human, 0.0, 1.0))
        ai = 1.0 - human

        return {
            "human": human,
            "ai": ai,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        now = time.time()

        if metrics.get("human_override_active", False):
            self._last_human_time = now

        target = self._target_weights(metrics)

        self._human_weight = (
            self._human_weight * self._inertia
            + target["human"] * (1.0 - self._inertia)
        )
        self._ai_weight = (
            self._ai_weight * self._inertia
            + target["ai"] * (1.0 - self._inertia)
        )

        # Normalize defensively
        s = max(1e-6, self._human_weight + self._ai_weight)
        self._human_weight /= s
        self._ai_weight /= s

        out = dict(metrics)

        out["control_blend"] = {
            "human": self._human_weight,
            "ai": self._ai_weight,
        }
        out["human_recent"] = (now - self._last_human_time) < 1.5
        out["blended_control_active"] = self._human_weight > 0.1

        return out


    def reset(self) -> None:
        """
        Reset arbitration blend (mission restart).
        """
        self._human_weight = 0.0
        self._ai_weight = 1.0
        self._last_human_time = 0.0


