# CHUNK 86 X 30 — CLOUD–ONBOARD INTENT SYNCHRONIZATION BRIDGE
# ==============================================================================
#
# Purpose:
#   Synchronize high-level intent between cloud AI (LLM / vision),
#   onboard director AI, and mobile app with determinism, authority
#   tracking, and latency awareness.
#
# Backbone truth:
#   Intent must converge, not race.
#
# ==============================================================================

from typing import Dict, Any, Optional
import time
import hashlib


class CloudOnboardIntentSynchronizationBridge:
    """
    Deterministic intent synchronization bridge.
    Ensures that intent updates from cloud, onboard, or app are
    ordered, conflict-resolved, and safely applied.
    """

    __slots__ = (
        "_last_intent_hash",
        "_last_source",
        "_last_timestamp",
    )

    def __init__(self):
        self._last_intent_hash: Optional[str] = None
        self._last_source: Optional[str] = None
        self._last_timestamp: float = 0.0


    # --------------------------------------------------------------------------
    # Intent hashing
    # --------------------------------------------------------------------------

    def _hash_intent(self, intent: Dict[str, Any]) -> str:
        blob = repr(sorted(intent.items())).encode("utf-8")
        return hashlib.sha256(blob).hexdigest()


    # --------------------------------------------------------------------------
    # Synchronization
    # --------------------------------------------------------------------------

    def apply(
        self,
        metrics: Dict[str, Any],
        incoming_intent: Optional[Dict[str, Any]],
        source: Optional[str],
    ) -> Dict[str, Any]:
        now = time.time()
        out = dict(metrics)

        if not incoming_intent or not source:
            return out

        intent_hash = self._hash_intent(incoming_intent)

        # Reject duplicates
        if intent_hash == self._last_intent_hash:
            return out

        # Authority-aware ordering
        authority = float(metrics.get("authority_level", 1.0))
        source_priority = {
            "safety": 3,
            "human": 2,
            "cloud": 1,
            "onboard": 0,
        }.get(source, 0)

        last_priority = {
            "safety": 3,
            "human": 2,
            "cloud": 1,
            "onboard": 0,
        }.get(self._last_source, 0)

        # Higher priority always wins
        if source_priority < last_priority and authority > 0.5:
            return out

        # Accept intent
        self._last_intent_hash = intent_hash
        self._last_source = source
        self._last_timestamp = now

        out["active_intent"] = incoming_intent
        out["intent_source"] = source
        out["intent_timestamp"] = now
        out["intent_synced"] = True

        return out


    def reset(self) -> None:
        """
        Reset synchronization state (mission restart).
        """
        self._last_intent_hash = None
        self._last_source = None
        self._last_timestamp = 0.0


