# CHUNK 86 X 31 — CROSS-DEVICE DIRECTOR STATE REPLICATION
# ==============================================================================
#
# Purpose:
#   Replicate director-level state coherently across cloud AI,
#   onboard director, and mobile app so all participants operate
#   on the same cinematic reality.
#
# Backbone truth:
#   A film collapses when directors disagree.
#
# ==============================================================================

from typing import Dict, Any, Optional
import time
import hashlib


class CrossDeviceDirectorStateReplication:
    """
    Deterministic director-state replication engine.
    Maintains a causally ordered, versioned director state shared
    across all system nodes with conflict suppression.
    """

    __slots__ = (
        "_state_hash",
        "_state_version",
        "_last_source",
        "_last_update",
    )

    def __init__(self):
        self._state_hash: Optional[str] = None
        self._state_version: int = 0
        self._last_source: Optional[str] = None
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # State hashing
    # --------------------------------------------------------------------------

    def _hash_state(self, state: Dict[str, Any]) -> str:
        blob = repr(sorted(state.items())).encode("utf-8")
        return hashlib.sha256(blob).hexdigest()


    # --------------------------------------------------------------------------
    # Replication
    # --------------------------------------------------------------------------

    def apply(
        self,
        metrics: Dict[str, Any],
        incoming_state: Optional[Dict[str, Any]],
        source: Optional[str],
    ) -> Dict[str, Any]:
        out = dict(metrics)
        now = time.time()

        if not incoming_state or not source:
            return out

        state_hash = self._hash_state(incoming_state)

        # Ignore identical state
        if state_hash == self._state_hash:
            return out

        incoming_version = int(incoming_state.get("state_version", 0))

        # Causal ordering
        if incoming_version < self._state_version:
            return out

        # Authority hierarchy
        priority = {
            "safety": 3,
            "human": 2,
            "onboard": 1,
            "cloud": 0,
        }.get(source, 0)

        last_priority = {
            "safety": 3,
            "human": 2,
            "onboard": 1,
            "cloud": 0,
        }.get(self._last_source, 0)

        if priority < last_priority:
            return out

        # Accept replicated state
        self._state_hash = state_hash
        self._state_version = incoming_version
        self._last_source = source
        self._last_update = now

        out["director_state"] = incoming_state
        out["director_state_version"] = incoming_version
        out["director_state_source"] = source
        out["director_state_synced"] = True

        return out


    def reset(self) -> None:
        """
        Reset replicated director state (mission restart).
        """
        self._state_hash = None
        self._state_version = 0
        self._last_source = None
        self._last_update = 0.0


