# ==============================================================================
# CHUNK 86 X 32 — LATENCY-AWARE COMMAND RECONCILIATION
# ==============================================================================
#
# Purpose:
#   Reconcile delayed, reordered, or duplicated commands arriving
#   from cloud, mobile, or onboard sources so execution remains
#   safe, deterministic, and intent-consistent under real networks.
#
# Backbone truth:
#   Latency is not an error — ignoring it is.
#
# ==============================================================================

from typing import Dict, Any, Optional
import time
import numpy as np


class LatencyAwareCommandReconciliation:
    """
    Latency-aware command reconciliation engine.
    Orders, filters, and dampens incoming commands using causal
    windows, authority weighting, and temporal confidence decay.
    """

    __slots__ = (
        "_last_applied_time",
        "_command_window",
        "_inertia",
    )

    def __init__(
        self,
        command_window: float = 0.35,
        inertia: float = 0.9,
    ):
        self._command_window = float(max(0.1, command_window))
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._last_applied_time: float = 0.0


    # --------------------------------------------------------------------------
    # Command acceptance logic
    # --------------------------------------------------------------------------

    def _accept(
        self,
        cmd_time: float,
        authority: float,
    ) -> bool:
        # Reject commands too far in the past
        if cmd_time < self._last_applied_time - self._command_window:
            return False

        # Authority-gated acceptance
        if authority < 0.3:
            return False

        return True


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        metrics: Dict[str, Any],
        incoming_command: Optional[Dict[str, Any]],
    ) -> Dict[str, Any]:
        out = dict(metrics)

        if not incoming_command:
            return out

        cmd_time = float(incoming_command.get("timestamp", time.time()))
        authority = float(metrics.get("authority_level", 1.0))

        if not self._accept(cmd_time, authority):
            out["command_rejected"] = True
            return out

        # Temporal confidence decay
        age = max(0.0, time.time() - cmd_time)
        confidence = float(incoming_command.get("confidence", 1.0))
        confidence *= np.exp(-age / self._command_window)

        if confidence < 0.2:
            out["command_rejected"] = True
            return out

        # Apply command
        self._last_applied_time = cmd_time

        out["active_command"] = incoming_command
        out["command_confidence"] = confidence
        out["command_applied"] = True

        return out


    def reset(self) -> None:
        """
        Reset reconciliation state (mission restart).
        """
        self._last_applied_time = 0.0


