# ==============================================================================
# CHUNK 86 X 33 — FAIL-SAFE INTENT ROLLBACK & RECOVERY
# ==============================================================================
#
# Purpose:
#   Guarantee robustly recover from faults, desyncs, or unsafe intent
#   states by rolling back to the last known-good director intent
#   while preserving safety, continuity, and emotional coherence.
#
# Backbone truth:
#   Recovery is part of direction, not a failure.
#
# ==============================================================================

from typing import Dict, Any, Optional
import time
import copy


class FailSafeIntentRollbackRecovery:
    """
    Fail-safe intent rollback & recovery engine.
    Maintains a bounded history of validated intents and director
    states, enabling safe rollback under fault or safety triggers.
    """

    __slots__ = (
        "_intent_history",
        "_max_history",
        "_last_good_time",
    )

    def __init__(self, max_history: int = 5):
        self._max_history = int(max(2, max_history))
        self._intent_history: list = []
        self._last_good_time: float = 0.0


    # --------------------------------------------------------------------------
    # Intent validation
    # --------------------------------------------------------------------------

    def _is_intent_safe(self, intent: Dict[str, Any]) -> bool:
        # Placeholder for safety checks:
        # - flight envelope
        # - geofence
        # - authority constraints
        return bool(intent)


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        metrics: Dict[str, Any],
        active_intent: Optional[Dict[str, Any]],
    ) -> Dict[str, Any]:
        out = dict(metrics)
        now = time.time()

        fault = bool(metrics.get("safety_override_active", False))
        desync = bool(metrics.get("intent_desync", False))

        # Store safe intent snapshots
        if active_intent and self._is_intent_safe(active_intent):
            self._intent_history.append(copy.deepcopy(active_intent))
            if len(self._intent_history) > self._max_history:
                self._intent_history.pop(0)
            self._last_good_time = now

        # Trigger rollback
        if fault or desync:
            if self._intent_history:
                rollback_intent = self._intent_history[-1]
                out["active_intent"] = rollback_intent
                out["intent_rolled_back"] = True
                out["rollback_age"] = now - self._last_good_time
            else:
                out["intent_rolled_back"] = False

        return out


    def reset(self) -> None:
        """
        Reset rollback history (mission restart).
        """
        self._intent_history.clear()
        self._last_good_time = 0.0


