# ==============================================================================
# CHUNK 86 X 34 — DISTRIBUTED DIRECTOR HEALTH MONITOR
# ==============================================================================
#
# Purpose:
#   Continuously assess the health of the distributed director system
#   (cloud AI, onboard AI, mobile app, comms) and surface degradation
#   before it affects flight safety or cinematic intent.
#
# Backbone truth:
#   Failure is gradual — detection must be earlier.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class DistributedDirectorHealthMonitor:
    """
    Distributed health monitoring engine.
    Aggregates node-level vitals into a graded system-health model,
    enabling preemptive mitigation instead of reactive recovery.
    """

    __slots__ = (
        "_node_health",
        "_system_health",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.92):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._node_health: Dict[str, float] = {}
        self._system_health: float = 1.0


    # --------------------------------------------------------------------------
    # Node evaluation
    # --------------------------------------------------------------------------

    def _evaluate_node(self, node_metrics: Dict[str, Any]) -> float:
        latency = float(node_metrics.get("latency", 0.0))
        drop = float(node_metrics.get("packet_loss", 0.0))
        cpu = float(node_metrics.get("cpu_load", 0.0))
        stale = float(node_metrics.get("staleness", 0.0))

        health = (
            1.0
            - 0.4 * latency
            - 0.3 * drop
            - 0.2 * cpu
            - 0.4 * stale
        )

        return float(np.clip(health, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(metrics)

        node_reports = metrics.get("node_reports", {})
        if not isinstance(node_reports, dict):
            return out

        # Evaluate each node
        for node_id, node_metrics in node_reports.items():
            self._node_health[node_id] = self._evaluate_node(node_metrics)

        # Aggregate system health
        if self._node_health:
            avg_health = float(np.mean(list(self._node_health.values())))
        else:
            avg_health = 1.0

        self._system_health = (
            self._system_health * self._inertia
            + avg_health * (1.0 - self._inertia)
        )

        out["director_health"] = {
            "nodes": dict(self._node_health),
            "system": self._system_health,
        }

        out["health_degraded"] = self._system_health < 0.6
        out["health_critical"] = self._system_health < 0.4

        return out


    def reset(self) -> None:
        """
        Reset health monitor (mission restart).
        """
        self._node_health.clear()
        self._system_health = 1.0


