# CHUNK 86 X 35 — MISSION-LEVEL AUDIT & FORENSICS LOGGER
# ==============================================================================
#
# Purpose:
#   Capture a complete, causally ordered audit trail of all director
#   decisions, intent changes, safety events, and authority shifts
#   for replay, analysis, and legal/engineering forensics.
#
# Backbone truth:
#   If a decision can’t be explained, it wasn’t controlled.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import json
import hashlib


class MissionLevelAuditForensicsLogger:
    """
    Mission-level audit & forensics logging engine.
    Records immutable, time-ordered decision frames with hashing
    so every autonomous action can be reconstructed precisely.
    """

    __slots__ = (
        "_records",
        "_last_hash",
        "_mission_id",
    )

    def __init__(self, mission_id: str):
        self._mission_id = mission_id
        self._records: List[Dict[str, Any]] = []
        self._last_hash: str = "GENESIS"


    # --------------------------------------------------------------------------
    # Hashing
    # --------------------------------------------------------------------------

    def _hash_record(self, record: Dict[str, Any]) -> str:
        blob = json.dumps(record, sort_keys=True).encode("utf-8")
        h = hashlib.sha256(blob).hexdigest()
        return hashlib.sha256((self._last_hash + h).encode("utf-8")).hexdigest()


    # --------------------------------------------------------------------------
    # Logging
    # --------------------------------------------------------------------------

    def log(self, metrics: Dict[str, Any]) -> None:
        timestamp = time.time()

        record = {
            "mission_id": self._mission_id,
            "timestamp": timestamp,
            "authority_level": metrics.get("authority_level"),
            "active_intent": metrics.get("active_intent"),
            "shot_plan": metrics.get("current_shot_plan"),
            "emotional_state": {
                k: metrics.get(k)
                for k in (
                    "emotion_tension",
                    "emotion_awe",
                    "emotion_grief",
                    "emotion_relief",
                    "emotional_momentum",
                )
            },
            "safety": {
                "risk": metrics.get("flight_risk_level"),
                "override": metrics.get("safety_override_active"),
            },
            "health": metrics.get("director_health"),
            "source": metrics.get("intent_source"),
        }

        record_hash = self._hash_record(record)
        record["hash"] = record_hash
        record["prev_hash"] = self._last_hash

        self._last_hash = record_hash
        self._records.append(record)


    # --------------------------------------------------------------------------
    # Export
    # --------------------------------------------------------------------------

    def export(self) -> List[Dict[str, Any]]:
        """
        Export full audit log (immutable).
        """
        return list(self._records)


    def reset(self) -> None:
        """
        Reset audit logger (new mission).
        """
        self._records.clear()
        self._last_hash = "GENESIS"


