from typing import Dict, Any
import numpy as np
import time


class AutonomousMissionReadinessGate:
    """
    Mission readiness gating engine.
    Aggregates health, confidence, contracts, and safety into a graded
    readiness score that governs whether autonomy may engage and at
    what strength.
    """

    __slots__ = (
        "_readiness",
        "_last_change",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.92):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._readiness: float = 0.0
        self._last_change: float = 0.0


    # --------------------------------------------------------------------------
    # Readiness inference
    # --------------------------------------------------------------------------

    def _target_readiness(self, metrics: Dict[str, Any]) -> float:
        health = float(
            metrics.get("director_health", {}).get("system", 1.0)
        )
        confidence = float(metrics.get("director_confidence", 1.0))
        contract_ok = 1.0 if metrics.get("contract_verified", False) else 0.0
        safety_ok = 0.0 if metrics.get("safety_override_active", False) else 1.0
        human_recent = 1.0 if metrics.get("human_recent", False) else 0.5

        readiness = (
            0.35 * health
            + 0.30 * confidence
            + 0.20 * contract_ok
            + 0.15 * safety_ok
        )

        readiness *= human_recent

        return float(np.clip(readiness, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_readiness(metrics)

        self._readiness = (
            self._readiness * self._inertia
            + target * (1.0 - self._inertia)
        )

        now = time.time()
        if abs(self._readiness - target) > 0.2:
            self._last_change = now

        out = dict(metrics)

        out["mission_readiness"] = self._readiness
        out["autonomy_allowed"] = self._readiness > 0.7
        out["autonomy_limited"] = 0.4 < self._readiness <= 0.7
        out["autonomy_blocked"] = self._readiness <= 0.4
        out["readiness_last_change"] = self._last_change

        return out


    def reset(self) -> None:
        """
        Reset mission readiness (mission restart).
        """
        self._readiness = 0.0
        self._last_change = 0.0


