from typing import Dict, Any
import time
import json


class LiveDirectorIntentTelemetryStream:
    """
    Live director intent telemetry stream.
    Publishes a compact, semantically meaningful snapshot of what
    the director AI is trying to do *right now* and why.
    """

    __slots__ = (
        "_last_emit",
        "_emit_interval",
    )

    def __init__(self, emit_interval: float = 0.25):
        self._emit_interval = float(max(0.05, emit_interval))
        self._last_emit: float = 0.0


    # --------------------------------------------------------------------------
    # Emission logic
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        now = time.time()
        out = dict(metrics)

        if now - self._last_emit < self._emit_interval:
            return out

        payload = {
            "timestamp": now,
            "intent": metrics.get("active_intent"),
            "shot_plan": metrics.get("current_shot_plan"),
            "emotional_state": {
                "tension": metrics.get("emotion_tension"),
                "awe": metrics.get("emotion_awe"),
                "grief": metrics.get("emotion_grief"),
                "relief": metrics.get("emotion_relief"),
                "momentum": metrics.get("emotional_momentum"),
            },
            "authority": metrics.get("authority_level"),
            "confidence": metrics.get("director_confidence"),
            "readiness": metrics.get("mission_readiness"),
            "safety": {
                "risk": metrics.get("flight_risk_level"),
                "override": metrics.get("safety_override_active"),
            },
        }

        # Serialized form for transport (WS / UDP / gRPC)
        out["director_intent_telemetry"] = json.dumps(payload)
        out["telemetry_emitted"] = True

        self._last_emit = now
        return out


    def reset(self) -> None:
        """
        Reset telemetry stream (mission restart).
        """
        self._last_emit = 0.0


