# CHUNK 86 X 41 — REAL-TIME CINEMATIC KPI EVALUATOR
# ==============================================================================
#
# Purpose:
#   Quantify cinematic quality continuously during capture so the
#   director AI can adapt framing, motion, exposure, and pacing
#   *while the shot is happening*, not after.
#
# Backbone truth:
#   You can’t direct what you can’t measure — but you must measure
#   what cinema actually perceives.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class RealTimeCinematicKPIEvaluator:
    """
    Real-time cinematic KPI evaluation engine.
    Produces perceptual, director-meaningful KPIs instead of raw
    signal metrics, enabling closed-loop cinematic control.
    """

    __slots__ = (
        "_kpi",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._kpi: Dict[str, float] = {
            "composition": 0.5,
            "motion_quality": 0.5,
            "exposure_emotion": 0.5,
            "subject_readability": 0.5,
            "overall_cinematic_score": 0.5,
        }


    # --------------------------------------------------------------------------
    # KPI inference
    # --------------------------------------------------------------------------

    def _target_kpi(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        framing = float(metrics.get("framing_quality", 0.5))
        motion = float(metrics.get("motion_energy", 0.5))
        stability = float(metrics.get("stability_score", 0.5))
        exposure = float(metrics.get("exposure_balance", 0.5))
        emotion = float(metrics.get("emotional_momentum", 0.5))
        subject = float(metrics.get("subject_saliency", 0.5))

        composition = (
            0.6 * framing
            + 0.4 * subject
        )

        motion_quality = (
            0.5 * stability
            + 0.3 * (1.0 - abs(motion - 0.5) * 2.0)
            + 0.2 * emotion
        )

        exposure_emotion = (
            0.6 * exposure
            + 0.4 * (1.0 - abs(exposure - emotion))
        )

        subject_readability = (
            0.7 * subject
            + 0.3 * framing
        )

        overall = (
            0.25 * composition
            + 0.25 * motion_quality
            + 0.20 * exposure_emotion
            + 0.20 * subject_readability
            + 0.10 * emotion
        )

        return {
            "composition": float(np.clip(composition, 0.0, 1.0)),
            "motion_quality": float(np.clip(motion_quality, 0.0, 1.0)),
            "exposure_emotion": float(np.clip(exposure_emotion, 0.0, 1.0)),
            "subject_readability": float(np.clip(subject_readability, 0.0, 1.0)),
            "overall_cinematic_score": float(np.clip(overall, 0.0, 1.0)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_kpi(metrics)

        for k, v in target.items():
            self._kpi[k] = (
                self._kpi[k] * self._inertia
                + v * (1.0 - self._inertia)
            )

        out = dict(metrics)
        out["cinematic_kpi"] = dict(self._kpi)
        out["cinematic_quality_good"] = self._kpi["overall_cinematic_score"] > 0.65
        out["cinematic_quality_poor"] = self._kpi["overall_cinematic_score"] < 0.4

        return out


    def reset(self) -> None:
        """
        Reset cinematic KPI evaluator (mission restart).
        """
        for k in self._kpi:
            self._kpi[k] = 0.5


