# ==============================================================================
# CHUNK 86 X 42 — AI-TO-FLIGHT ENVELOPE TRANSLATOR
# ==============================================================================
#
# Purpose:
#   Translate high-level cinematic and director intent into a
#   physically safe, dynamically feasible flight envelope without
#   ever issuing raw motor or PID-level commands.
#
# Backbone truth:
#   Direction suggests — physics disposes.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class AIToFlightEnvelopeTranslator:
    """
    AI-to-flight envelope translation engine.
    Converts cinematic intent (pace, tension, framing pressure)
    into bounded velocity, acceleration, yaw-rate, and climb-rate
    envelopes that the flight controller may safely track.
    """

    __slots__ = (
        "_envelope",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._envelope: Dict[str, float] = {
            "max_velocity": 1.0,
            "max_acceleration": 1.0,
            "max_yaw_rate": 1.0,
            "max_climb_rate": 1.0,
        }


    # --------------------------------------------------------------------------
    # Envelope inference
    # --------------------------------------------------------------------------

    def _target_envelope(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        tension = float(metrics.get("emotion_tension", 0.0))
        awe = float(metrics.get("emotion_awe", 0.0))
        grief = float(metrics.get("emotion_grief", 0.0))
        confidence = float(metrics.get("director_confidence", 1.0))
        safety = float(metrics.get("flight_risk_level", 0.0))

        pace = (
            0.6 * awe
            + 0.4 * (1.0 - grief)
        )

        velocity = (
            0.5
            + 0.7 * pace
            - 0.8 * tension
        )

        acceleration = (
            0.4
            + 0.6 * pace
            - 0.6 * tension
        )

        yaw_rate = (
            0.3
            + 0.7 * tension
            + 0.3 * pace
        )

        climb = (
            0.4
            + 0.6 * awe
            - 0.5 * grief
        )

        # Confidence & safety gating
        scale = confidence * (1.0 - 0.7 * safety)

        return {
            "max_velocity": float(np.clip(velocity * scale, 0.2, 2.0)),
            "max_acceleration": float(np.clip(acceleration * scale, 0.2, 2.5)),
            "max_yaw_rate": float(np.clip(yaw_rate * scale, 0.2, 3.0)),
            "max_climb_rate": float(np.clip(climb * scale, 0.2, 2.0)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_envelope(metrics)

        for k, v in target.items():
            self._envelope[k] = (
                self._envelope[k] * self._inertia
                + v * (1.0 - self._inertia)
            )

        out = dict(metrics)
        out["flight_envelope"] = dict(self._envelope)
        out["envelope_constrained"] = (
            metrics.get("flight_risk_level", 0.0) > 0.3
        )

        return out


    def reset(self) -> None:
        """
        Reset flight envelope (mission restart).
        """
        self._envelope = {
            "max_velocity": 1.0,
            "max_acceleration": 1.0,
            "max_yaw_rate": 1.0,
            "max_climb_rate": 1.0,
        }


