#   zoom pressure, focus behavior, and exposure bias — without
#   micromanaging hardware or breaking cinematic continuity.
#
# Backbone truth:
#   The camera must feel guided, not driven.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class GimbalCameraControlIntentMapper:
    """
    Director-intent → camera/gimbal control mapper.
    Produces smooth, bounded control intents for downstream camera
    and gimbal controllers while preserving emotional tone.
    """

    __slots__ = (
        "_camera_intent",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._camera_intent: Dict[str, float] = {
            "gimbal_pitch_bias": 0.0,
            "gimbal_yaw_bias": 0.0,
            "zoom_pressure": 0.0,
            "focus_pressure": 0.0,
            "exposure_bias": 0.0,
        }


    # --------------------------------------------------------------------------
    # Intent inference
    # --------------------------------------------------------------------------

    def _target_intent(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        tension = float(metrics.get("emotion_tension", 0.0))
        awe = float(metrics.get("emotion_awe", 0.0))
        grief = float(metrics.get("emotion_grief", 0.0))
        subject = float(metrics.get("subject_saliency", 0.0))
        distance = float(metrics.get("subject_distance", 0.5))

        pitch = (
            -0.4 * grief
            + 0.3 * awe
        )

        yaw = (
            0.5 * tension
            + 0.3 * (1.0 - distance)
        )

        zoom = (
            0.6 * subject
            + 0.4 * (1.0 - distance)
        )

        focus = (
            0.7 * subject
            + 0.2 * tension
        )

        exposure = (
            0.5 * awe
            - 0.4 * grief
            - 0.3 * tension
        )

        return {
            "gimbal_pitch_bias": float(np.clip(pitch, -1.0, 1.0)),
            "gimbal_yaw_bias": float(np.clip(yaw, -1.0, 1.0)),
            "zoom_pressure": float(np.clip(zoom, 0.0, 1.0)),
            "focus_pressure": float(np.clip(focus, 0.0, 1.0)),
            "exposure_bias": float(np.clip(exposure, -1.0, 1.0)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_intent(metrics)

        for k, v in target.items():
            self._camera_intent[k] = (
                self._camera_intent[k] * self._inertia
                + v * (1.0 - self._inertia)
            )

        out = dict(metrics)
        out["camera_control_intent"] = dict(self._camera_intent)
        out["camera_intent_active"] = True

        return out


    def reset(self) -> None:
        """
        Reset camera control intent (mission restart).
        """
        for k in self._camera_intent:
            self._camera_intent[k] = 0.0


