# CHUNK 86 X 44 — SUBJECT-AWARE MOTION PLANNER
# ==============================================================================
#
# Purpose:
#   Plan drone motion trajectories that are explicitly conditioned
#   on subject behavior, distance, emotional intent, and cinematic
#   pacing — not just navigation efficiency.
#
# Backbone truth:
#   The subject leads. The camera follows with intent.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class SubjectAwareMotionPlanner:
    """
    Subject-aware motion planning engine.
    Produces directional motion biases and speed shaping that respond
    to subject saliency, movement, and emotional context.
    """

    __slots__ = (
        "_motion_bias",
        "_speed_scale",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._motion_bias = {
            "forward": 0.0,
            "lateral": 0.0,
            "vertical": 0.0,
        }
        self._speed_scale: float = 1.0


    # --------------------------------------------------------------------------
    # Motion inference
    # --------------------------------------------------------------------------

    def _target_motion(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        subject_motion = float(metrics.get("subject_motion", 0.0))
        subject_distance = float(metrics.get("subject_distance", 0.5))
        subject_saliency = float(metrics.get("subject_saliency", 0.0))
        tension = float(metrics.get("emotion_tension", 0.0))
        awe = float(metrics.get("emotion_awe", 0.0))
        grief = float(metrics.get("emotion_grief", 0.0))

        forward = (
            0.6 * subject_motion
            + 0.4 * (1.0 - subject_distance)
            - 0.5 * tension
        )

        lateral = (
            0.5 * subject_motion
            + 0.3 * tension
            - 0.4 * grief
        )

        vertical = (
            0.6 * awe
            - 0.5 * grief
        )

        speed = (
            0.5
            + 0.4 * subject_saliency
            + 0.3 * subject_motion
            - 0.6 * grief
            - 0.5 * tension
        )

        return {
            "forward": float(np.clip(forward, -1.0, 1.0)),
            "lateral": float(np.clip(lateral, -1.0, 1.0)),
            "vertical": float(np.clip(vertical, -1.0, 1.0)),
            "speed": float(np.clip(speed, 0.3, 1.5)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_motion(metrics)

        for axis in ("forward", "lateral", "vertical"):
            self._motion_bias[axis] = (
                self._motion_bias[axis] * self._inertia
                + target[axis] * (1.0 - self._inertia)
            )

        self._speed_scale = (
            self._speed_scale * self._inertia
            + target["speed"] * (1.0 - self._inertia)
        )

        out = dict(metrics)
        out["subject_motion_plan"] = {
            "bias": dict(self._motion_bias),
            "speed_scale": self._speed_scale,
        }
        out["subject_motion_active"] = True

        return out


    def reset(self) -> None:
        """
        Reset subject-aware motion planning (mission restart).
        """
        for k in self._motion_bias:
            self._motion_bias[k] = 0.0
        self._speed_scale = 1.0


