# CHUNK 86 X 45 — OBSTACLE & PROXIMITY-AWARE SHOT MODULATOR
# ==============================================================================
#
# Purpose:
#   Integrate obstacle distance, proximity pressure, and safety margins
#   directly into shot modulation so safety reshapes cinematic intent
#   instead of abruptly cancelling it.
#
# Backbone truth:
#   Great direction adapts under constraint — it doesn’t panic.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class ObstacleProximityAwareShotModulator:
    """
    Obstacle & proximity-aware shot modulation engine.
    Softly bends motion, framing pressure, and camera aggression
    as obstacles encroach — preserving cinematic continuity
    while enforcing safety margins.
    """

    __slots__ = (
        "_proximity_pressure",
        "_shot_softening",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._proximity_pressure: float = 0.0
        self._shot_softening: float = 0.0


    # --------------------------------------------------------------------------
    # Proximity inference
    # --------------------------------------------------------------------------

    def _target_proximity(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        nearest = float(metrics.get("nearest_obstacle_distance", 1.0))
        velocity = float(metrics.get("current_velocity", 0.0))
        envelope = metrics.get("flight_envelope", {})

        safe_dist = 0.6 + 0.4 * velocity
        intrusion = max(0.0, safe_dist - nearest)

        pressure = intrusion / max(safe_dist, 1e-3)

        soften = (
            0.6 * pressure
            + 0.3 * velocity
        )

        return {
            "pressure": float(np.clip(pressure, 0.0, 1.0)),
            "soften": float(np.clip(soffen := soften, 0.0, 1.0)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_proximity(metrics)

        self._proximity_pressure = (
            self._proximity_pressure * self._inertia
            + target["pressure"] * (1.0 - self._inertia)
        )

        self._shot_softening = (
            self._shot_softening * self._inertia
            + target["soften"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        # Modulate cinematic aggressiveness
        if "subject_motion_plan" in out:
            out["subject_motion_plan"]["speed_scale"] *= (
                1.0 - 0.6 * self._shot_softening
            )

        if "camera_control_intent" in out:
            out["camera_control_intent"]["zoom_pressure"] *= (
                1.0 - 0.7 * self._shot_softening
            )
            out["camera_control_intent"]["gimbal_yaw_bias"] *= (
                1.0 - 0.5 * self._shot_softening
            )

        out["proximity_pressure"] = self._proximity_pressure
        out["shot_softening"] = self._shot_softening
        out["proximity_modulation_active"] = self._proximity_pressure > 0.05

        return out


    def reset(self) -> None:
        """
        Reset proximity modulation (mission restart).
        """
        self._proximity_pressure = 0.0
        self._shot_softening = 0.0


