# ==============================================================================
# CHUNK 86 X 46 — MULTI-TARGET CINEMATIC PRIORITIZATION ENGINE
# ==============================================================================
#
# Purpose:
#   Resolve cinematic priority when multiple subjects compete for
#   attention, ensuring narrative clarity, emotional correctness,
#   and smooth transitions without hard target snaps.
#
# Backbone truth:
#   Cinema chooses who matters — and when.
#
# ==============================================================================

from typing import Dict, Any, List
import numpy as np


class MultiTargetCinematicPrioritizationEngine:
    """
    Multi-target cinematic prioritization engine.
    Computes a continuous priority distribution across visible
    subjects using saliency, narrative role, emotional alignment,
    and temporal persistence.
    """

    __slots__ = (
        "_priorities",
        "_active_target",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._priorities: Dict[str, float] = {}
        self._active_target: str = ""


    # --------------------------------------------------------------------------
    # Priority inference
    # --------------------------------------------------------------------------

    def _score_subject(self, subject: Dict[str, Any], metrics: Dict[str, Any]) -> float:
        saliency = float(subject.get("saliency", 0.0))
        distance = float(subject.get("distance", 1.0))
        motion = float(subject.get("motion", 0.0))
        role = float(subject.get("narrative_role_weight", 0.5))

        emotion_align = 1.0 - abs(
            metrics.get("emotional_momentum", 0.5)
            - subject.get("emotional_affinity", 0.5)
        )

        score = (
            0.35 * saliency
            + 0.20 * motion
            + 0.15 * (1.0 - distance)
            + 0.20 * role
            + 0.10 * emotion_align
        )

        return float(np.clip(score, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        subjects: List[Dict[str, Any]] = metrics.get("subjects", [])
        out = dict(metrics)

        if not subjects:
            return out

        new_priorities: Dict[str, float] = {}

        for subject in subjects:
            sid = subject.get("id")
            if not sid:
                continue
            score = self._score_subject(subject, metrics)
            prev = self._priorities.get(sid, score)
            new_priorities[sid] = (
                prev * self._inertia + score * (1.0 - self._inertia)
            )

        if new_priorities:
            self._active_target = max(new_priorities, key=new_priorities.get)

        self._priorities = new_priorities

        out["cinematic_targets"] = dict(self._priorities)
        out["primary_subject_id"] = self._active_target
        out["multi_target_active"] = len(new_priorities) > 1

        return out


    def reset(self) -> None:
        """
        Reset target prioritization (mission restart).
        """
        self._priorities.clear()
        self._active_target = ""


