# CHUNK 86 X 47 — DYNAMIC PATH RECOMPOSITION ENGINE
# ==============================================================================
#
# Purpose:
#   Recompose flight paths dynamically when subject priority,
#   emotional intent, safety constraints, or obstacles change —
#   without producing visible jumps, hesitations, or intent loss.
#
# Backbone truth:
#   The audience must never see the replan.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class DynamicPathRecompositionEngine:
    """
    Dynamic path recomposition engine.
    Continuously warps the active trajectory using intent-weighted
    blending instead of discrete replans.
    """

    __slots__ = (
        "_path_bias",
        "_smoothness",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._path_bias = {
            "forward": 0.0,
            "lateral": 0.0,
            "vertical": 0.0,
        }
        self._smoothness: float = 1.0


    # --------------------------------------------------------------------------
    # Path inference
    # --------------------------------------------------------------------------

    def _target_path_bias(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        subject_bias = metrics.get("subject_motion_plan", {}).get("bias", {})
        envelope = metrics.get("flight_envelope", {})
        proximity = float(metrics.get("proximity_pressure", 0.0))
        emotion = float(metrics.get("emotional_momentum", 0.0))

        forward = (
            0.7 * subject_bias.get("forward", 0.0)
            * envelope.get("max_velocity", 1.0)
        )

        lateral = (
            0.6 * subject_bias.get("lateral", 0.0)
            * envelope.get("max_velocity", 1.0)
        )

        vertical = (
            0.5 * subject_bias.get("vertical", 0.0)
            * envelope.get("max_climb_rate", 1.0)
        )

        smoothness = (
            1.0
            - 0.5 * proximity
            + 0.2 * (1.0 - emotion)
        )

        return {
            "forward": float(np.clip(forward, -1.0, 1.0)),
            "lateral": float(np.clip(lateral, -1.0, 1.0)),
            "vertical": float(np.clip(vertical, -1.0, 1.0)),
            "smoothness": float(np.clip(smoothness, 0.3, 1.0)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_path_bias(metrics)

        for axis in ("forward", "lateral", "vertical"):
            self._path_bias[axis] = (
                self._path_bias[axis] * self._inertia
                + target[axis] * (1.0 - self._inertia)
            )

        self._smoothness = (
            self._smoothness * self._inertia
            + target["smoothness"] * (1.0 - self._inertia)
        )

        out = dict(metrics)
        out["dynamic_path_bias"] = dict(self._path_bias)
        out["path_smoothness"] = self._smoothness
        out["path_recomposition_active"] = True

        return out


    def reset(self) -> None:
        """
        Reset dynamic path recomposition (mission restart).
        """
        for k in self._path_bias:
            self._path_bias[k] = 0.0
        self._smoothness = 1.0


