# ==============================================================================
# CHUNK 86 X 48 — CINEMATIC RISK–REWARD ARBITRATION CORE
# ==============================================================================
#
# Purpose:
#   Continuously arbitrate between cinematic reward and operational
#   risk so the director AI can pursue bold shots *only when justified*,
#   and gracefully retreat when the cost outweighs the value.
#
# Backbone truth:
#   The best directors know when not to take the shot.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class CinematicRiskRewardArbitrationCore:
    """
    Cinematic risk–reward arbitration engine.
    Balances cinematic payoff against safety, confidence, proximity,
    and system health using graded tradeoffs instead of absolutes.
    """

    __slots__ = (
        "_risk_budget",
        "_reward_pressure",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._risk_budget: float = 1.0
        self._reward_pressure: float = 0.0


    # --------------------------------------------------------------------------
    # Arbitration inference
    # --------------------------------------------------------------------------

    def _target_balance(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        cinematic = float(
            metrics.get("cinematic_kpi", {}).get("overall_cinematic_score", 0.5)
        )
        confidence = float(metrics.get("director_confidence", 1.0))
        proximity = float(metrics.get("proximity_pressure", 0.0))
        risk = float(metrics.get("flight_risk_level", 0.0))
        health = float(
            metrics.get("director_health", {}).get("system", 1.0)
        )

        reward = (
            0.5 * cinematic
            + 0.3 * confidence
            + 0.2 * health
        )

        cost = (
            0.5 * risk
            + 0.3 * proximity
            + 0.2 * (1.0 - health)
        )

        margin = reward - cost

        risk_budget = np.clip(
            0.5 + margin,
            0.2,
            1.0,
        )

        reward_pressure = np.clip(
            reward * (1.0 - cost),
            0.0,
            1.0,
        )

        return {
            "risk_budget": float(risk_budget),
            "reward_pressure": float(reward_pressure),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_balance(metrics)

        self._risk_budget = (
            self._risk_budget * self._inertia
            + target["risk_budget"] * (1.0 - self._inertia)
        )

        self._reward_pressure = (
            self._reward_pressure * self._inertia
            + target["reward_pressure"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["cinematic_risk_budget"] = self._risk_budget
        out["cinematic_reward_pressure"] = self._reward_pressure
        out["high_risk_allowed"] = self._risk_budget > 0.7
        out["risk_suppression_active"] = self._risk_budget < 0.4

        return out


    def reset(self) -> None:
        """
        Reset risk–reward arbitration (mission restart).
        """
        self._risk_budget = 1.0
        self._reward_pressure = 0.0


