# ==============================================================================
# CHUNK 86 X 49 — HUMAN–AI AUTHORITY BLENDING LAYER
# ==============================================================================
#
# Purpose:
#   Blend human pilot input and AI director intent into a single,
#   stable authority stream that preserves safety, cinematic intent,
#   and operator trust without oscillation or control fights.
#
# Backbone truth:
#   Authority is shared — not stolen.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class HumanAIAuthorityBlendingLayer:
    """
    Human–AI authority blending engine.
    Merges manual input and autonomous intent using confidence,
    recency, risk, and cinematic reward to determine final control.
    """

    __slots__ = (
        "_authority_weight",
        "_last_human_input",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._authority_weight: float = 1.0  # 1.0 = AI dominant
        self._last_human_input: float = 0.0


    # --------------------------------------------------------------------------
    # Authority inference
    # --------------------------------------------------------------------------

    def _target_weight(self, metrics: Dict[str, Any]) -> float:
        confidence = float(metrics.get("director_confidence", 1.0))
        readiness = float(metrics.get("mission_readiness", 1.0))
        risk_budget = float(metrics.get("cinematic_risk_budget", 1.0))
        human_strength = float(metrics.get("human_input_strength", 0.0))

        now = time.time()
        if human_strength > 0.1:
            self._last_human_input = now

        human_recent = np.clip((now - self._last_human_input) / 2.0, 0.0, 1.0)
        human_pressure = human_strength * (1.0 - human_recent)

        ai_weight = (
            0.5 * confidence
            + 0.3 * readiness
            + 0.2 * risk_budget
        )

        ai_weight *= (1.0 - 0.8 * human_pressure)

        return float(np.clip(ai_weight, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_weight(metrics)

        self._authority_weight = (
            self._authority_weight * self._inertia
            + target * (1.0 - self._inertia)
        )

        out = dict(metrics)
        out["ai_authority_weight"] = self._authority_weight
        out["human_authority_weight"] = 1.0 - self._authority_weight
        out["authority_blended"] = True

        return out


    def reset(self) -> None:
        """
        Reset authority blending (mission restart).
        """
        self._authority_weight = 1.0
        self._last_human_input = 0.0


