# ==============================================================================
# CHUNK 86 X 50 — INTENT-STABLE FAILSAFE DEGRADATION ENGINE
# ==============================================================================
#
# Purpose:
#   Degrade autonomy, motion, and camera aggression under rising risk
#   while preserving narrative intent, continuity, and shot coherence.
#
# Backbone truth:
#   Safety should bend the shot — not break the story.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class IntentStableFailsafeDegradationEngine:
    """
    Intent-stable failsafe degradation engine.
    Applies progressive, intent-aware soft constraints as risk,
    uncertainty, or health degradation increases — avoiding abrupt
    cinematic collapse while guaranteeing safety margins.
    """

    __slots__ = (
        "_degrade_level",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.92):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._degrade_level: float = 0.0  # 0 = none, 1 = max


    # --------------------------------------------------------------------------
    # Degradation inference
    # --------------------------------------------------------------------------

    def _target_degrade(self, metrics: Dict[str, Any]) -> float:
        risk = float(metrics.get("flight_risk_level", 0.0))
        proximity = float(metrics.get("proximity_pressure", 0.0))
        confidence = float(metrics.get("director_confidence", 1.0))
        health = float(
            metrics.get("director_health", {}).get("system", 1.0)
        )
        contract_ok = 1.0 if metrics.get("contract_verified", False) else 0.0

        pressure = (
            0.5 * risk
            + 0.3 * proximity
            + 0.4 * (1.0 - confidence)
            + 0.3 * (1.0 - health)
            + 0.4 * (1.0 - contract_ok)
        )

        return float(np.clip(pressure, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_degrade(metrics)

        self._degrade_level = (
            self._degrade_level * self._inertia
            + target * (1.0 - self._inertia)
        )

        out = dict(metrics)

        # Soften motion & camera aggression proportionally
        soften = self._degrade_level

        if "subject_motion_plan" in out:
            out["subject_motion_plan"]["speed_scale"] *= (1.0 - 0.7 * soften)

        if "flight_envelope" in out:
            out["flight_envelope"]["max_velocity"] *= (1.0 - 0.6 * soften)
            out["flight_envelope"]["max_acceleration"] *= (1.0 - 0.6 * soften)
            out["flight_envelope"]["max_yaw_rate"] *= (1.0 - 0.5 * soften)
            out["flight_envelope"]["max_climb_rate"] *= (1.0 - 0.5 * soften)

        if "camera_control_intent" in out:
            out["camera_control_intent"]["zoom_pressure"] *= (1.0 - 0.7 * soften)
            out["camera_control_intent"]["gimbal_yaw_bias"] *= (1.0 - 0.6 * soften)
            out["camera_control_intent"]["exposure_bias"] *= (1.0 - 0.4 * soften)

        out["failsafe_degrade_level"] = self._degrade_level
        out["failsafe_active"] = self._degrade_level > 0.15
        out["failsafe_severe"] = self._degrade_level > 0.6

        return out


    def reset(self) -> None:
        """
        Reset failsafe degradation (mission restart).
        """
        self._degrade_level = 0.0


