# CHUNK 86 X 51 — AUTONOMOUS SHOT COMPLETION DETECTOR
# ==============================================================================
#
# Purpose:
#   Determine when a cinematic shot has reached narrative,
#   emotional, and visual completion so the director AI can
#   hold, release, or transition without human instruction.
#
# Backbone truth:
#   A shot ends when it has *said what it needed to say*.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class AutonomousShotCompletionDetector:
    """
    Autonomous shot completion detection engine.
    Infers shot completion using emotional resolution,
    cinematic KPI saturation, motion decay, and intent stability.
    """

    __slots__ = (
        "_completion_score",
        "_last_peak_time",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._completion_score: float = 0.0
        self._last_peak_time: float = 0.0


    # --------------------------------------------------------------------------
    # Completion inference
    # --------------------------------------------------------------------------

    def _target_completion(self, metrics: Dict[str, Any]) -> float:
        kpi = float(
            metrics.get("cinematic_kpi", {}).get("overall_cinematic_score", 0.5)
        )
        motion = float(metrics.get("motion_energy", 0.5))
        momentum = float(metrics.get("emotional_momentum", 0.0))
        intent_stable = 1.0 - float(metrics.get("intent_change_rate", 0.0))
        risk = float(metrics.get("flight_risk_level", 0.0))

        resolution = (
            0.4 * kpi
            + 0.3 * (1.0 - motion)
            + 0.2 * (1.0 - momentum)
            + 0.1 * intent_stable
        )

        # Risk accelerates completion
        resolution *= (1.0 + 0.5 * risk)

        return float(np.clip(resolution, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_completion(metrics)

        self._completion_score = (
            self._completion_score * self._inertia
            + target * (1.0 - self._inertia)
        )

        now = time.time()
        if self._completion_score > 0.8:
            self._last_peak_time = now

        out = dict(metrics)
        out["shot_completion_score"] = self._completion_score
        out["shot_complete"] = self._completion_score > 0.75
        out["shot_release_recommended"] = (
            self._completion_score > 0.65
            and (now - self._last_peak_time) > 0.5
        )

        return out


    def reset(self) -> None:
        """
        Reset shot completion detection (mission restart).
        """
        self._completion_score = 0.0
        self._last_peak_time = 0.0


