# CHUNK 86 X 52 — SHOT MEMORY & CONTINUITY LEDGER
# ==============================================================================
#
# Purpose:
#   Maintain a rolling, structured memory of completed shots so
#   the director AI preserves continuity of emotion, pacing,
#   framing logic, and narrative progression across the mission.
#
# Backbone truth:
#   Cinema is memory — without it, every shot is a reset.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import numpy as np


class ShotMemoryContinuityLedger:
    """
    Shot memory & continuity ledger.
    Stores compact summaries of recent shots and exposes continuity
    signals that shape future pacing, emotion, and framing decisions.
    """

    __slots__ = (
        "_shots",
        "_max_history",
    )

    def __init__(self, max_history: int = 12):
        self._max_history = int(max(4, max_history))
        self._shots: List[Dict[str, Any]] = []


    # --------------------------------------------------------------------------
    # Recording
    # --------------------------------------------------------------------------

    def record(self, metrics: Dict[str, Any]) -> None:
        """
        Record a completed shot summary.
        """
        shot = {
            "timestamp": time.time(),
            "intent": metrics.get("active_intent"),
            "primary_subject": metrics.get("primary_subject_id"),
            "emotion": {
                "tension": metrics.get("emotion_tension"),
                "awe": metrics.get("emotion_awe"),
                "grief": metrics.get("emotion_grief"),
                "relief": metrics.get("emotion_relief"),
            },
            "cinematic_score": metrics.get(
                "cinematic_kpi", {}
            ).get("overall_cinematic_score"),
            "risk_budget": metrics.get("cinematic_risk_budget"),
        }

        self._shots.append(shot)
        if len(self._shots) > self._max_history:
            self._shots.pop(0)


    # --------------------------------------------------------------------------
    # Continuity signals
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(metrics)

        if not self._shots:
            out["continuity_context"] = {}
            return out

        recent = self._shots[-3:]

        avg_score = float(
            np.mean([s.get("cinematic_score", 0.5) for s in recent])
        )

        emotional_drift = {
            k: float(
                np.mean([s["emotion"].get(k, 0.0) for s in recent])
            )
            for k in ("tension", "awe", "grief", "relief")
        }

        out["continuity_context"] = {
            "recent_shot_count": len(self._shots),
            "recent_avg_quality": avg_score,
            "emotional_drift": emotional_drift,
            "last_primary_subject": recent[-1].get("primary_subject"),
        }

        return out


    def reset(self) -> None:
        """
        Reset shot memory (mission restart).
        """
        self._shots.clear()


