# ==============================================================================
# CHUNK 86 X 53 — NARRATIVE PHASE TRANSITION ENGINE
# ==============================================================================
#
# Purpose:
#   Infer and transition narrative phases (setup, development,
#   escalation, climax, resolution) using emotional trajectories,
#   shot continuity, and cinematic saturation — not hard rules.
#
# Backbone truth:
#   Stories shift gradually — cinema must feel that shift.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class NarrativePhaseTransitionEngine:
    """
    Narrative phase transition engine.
    Maintains a probabilistic belief over narrative phases and
    transitions smoothly based on emotional momentum, continuity,
    and shot completion behavior.
    """

    __slots__ = (
        "_phase_belief",
        "_active_phase",
        "_inertia",
    )

    PHASES = (
        "setup",
        "development",
        "escalation",
        "climax",
        "resolution",
    )


    def __init__(self, inertia: float = 0.93):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._phase_belief = {p: 0.0 for p in self.PHASES}
        self._phase_belief["setup"] = 1.0
        self._active_phase: str = "setup"


    # --------------------------------------------------------------------------
    # Phase inference
    # --------------------------------------------------------------------------

    def _target_belief(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        momentum = float(metrics.get("emotional_momentum", 0.0))
        completion = float(metrics.get("shot_completion_score", 0.0))
        continuity = metrics.get("continuity_context", {})
        recent_quality = float(continuity.get("recent_avg_quality", 0.5))

        belief = {p: 0.0 for p in self.PHASES}

        belief["setup"] = np.clip(1.0 - momentum * 1.5, 0.0, 1.0)
        belief["development"] = np.clip(momentum * (1.0 - completion), 0.0, 1.0)
        belief["escalation"] = np.clip(momentum * completion * 1.2, 0.0, 1.0)
        belief["climax"] = np.clip(momentum**2 * recent_quality, 0.0, 1.0)
        belief["resolution"] = np.clip((1.0 - momentum) * completion, 0.0, 1.0)

        total = sum(belief.values()) + 1e-6
        for k in belief:
            belief[k] /= total

        return belief


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_belief(metrics)

        for phase, prob in target.items():
            self._phase_belief[phase] = (
                self._phase_belief.get(phase, 0.0) * self._inertia
                + prob * (1.0 - self._inertia)
            )

        self._active_phase = max(self._phase_belief, key=self._phase_belief.get)

        out = dict(metrics)
        out["narrative_phase"] = self._active_phase
        out["narrative_phase_belief"] = dict(self._phase_belief)

        return out


    def reset(self) -> None:
        """
        Reset narrative phase state (mission restart).
        """
        self._phase_belief = {p: 0.0 for p in self.PHASES}
        self._phase_belief["setup"] = 1.0
        self._active_phase = "setup"


