# CHUNK 86 X 54 — LONG-HORIZON EMOTIONAL ARC REGULATOR
# ==============================================================================
#
# Purpose:
#   Regulate emotional intensity across the *entire mission* so
#   peaks remain meaningful, escalation is earned, and resolution
#   arrives with emotional truth instead of exhaustion.
#
# Backbone truth:
#   Emotion without restraint becomes noise.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class LongHorizonEmotionalArcRegulator:
    """
    Long-horizon emotional arc regulation engine.
    Shapes emotional growth and decay across shots using narrative
    phase, cumulative peak exposure, and diminishing returns logic.
    """

    __slots__ = (
        "_arc_pressure",
        "_peak_exposure",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.95):
        self._inertia = float(np.clip(inertia, 0.90, 0.99))
        self._arc_pressure: float = 0.0
        self._peak_exposure: float = 0.0


    # --------------------------------------------------------------------------
    # Arc inference
    # --------------------------------------------------------------------------

    def _target_arc(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        phase = metrics.get("narrative_phase", "setup")
        momentum = float(metrics.get("emotional_momentum", 0.0))
        completion = float(metrics.get("shot_completion_score", 0.0))
        reward = float(metrics.get("cinematic_reward_pressure", 0.0))

        phase_gain = {
            "setup": 0.3,
            "development": 0.5,
            "escalation": 0.8,
            "climax": 1.0,
            "resolution": 0.4,
        }.get(phase, 0.5)

        arc_pressure = momentum * phase_gain * (1.0 - self._peak_exposure)
        peak_exposure = (
            self._peak_exposure
            + completion * reward * phase_gain * 0.2
        )

        return {
            "arc_pressure": float(np.clip(arc_pressure, 0.0, 1.0)),
            "peak_exposure": float(np.clip(peak_exposure, 0.0, 1.0)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_arc(metrics)

        self._arc_pressure = (
            self._arc_pressure * self._inertia
            + target["arc_pressure"] * (1.0 - self._inertia)
        )

        self._peak_exposure = (
            self._peak_exposure * self._inertia
            + target["peak_exposure"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        # Regulate future emotional amplification
        out["emotional_arc_pressure"] = self._arc_pressure
        out["emotional_peak_exposure"] = self._peak_exposure
        out["emotional_suppression_active"] = self._peak_exposure > 0.6

        return out


    def reset(self) -> None:
        """
        Reset long-horizon emotional arc state (mission restart).
        """
        self._arc_pressure = 0.0
        self._peak_exposure = 0.0


