# CHUNK 86 X 55 — MISSION-LEVEL CINEMATIC PACING CONTROLLER
# ==============================================================================
#
# Purpose:
#   Control temporal pacing across the entire mission so shot length,
#   motion cadence, and emotional dwell time evolve intentionally
#   with narrative phase and audience fatigue — not clock time.
#
# Backbone truth:
#   Pacing is invisible direction.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class MissionLevelCinematicPacingController:
    """
    Mission-level cinematic pacing controller.
    Modulates temporal cadence, shot dwell bias, and motion tempo
    using narrative phase, emotional arc pressure, and recent pacing
    history to avoid rush or drag.
    """

    __slots__ = (
        "_tempo_bias",
        "_dwell_bias",
        "_fatigue",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.94):
        self._inertia = float(np.clip(inertia, 0.90, 0.99))
        self._tempo_bias: float = 1.0
        self._dwell_bias: float = 1.0
        self._fatigue: float = 0.0


    # --------------------------------------------------------------------------
    # Pacing inference
    # --------------------------------------------------------------------------

    def _target_pacing(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        phase = metrics.get("narrative_phase", "setup")
        arc_pressure = float(metrics.get("emotional_arc_pressure", 0.0))
        peak_exposure = float(metrics.get("emotional_peak_exposure", 0.0))
        completion = float(metrics.get("shot_completion_score", 0.0))

        base_tempo = {
            "setup": 0.8,
            "development": 0.9,
            "escalation": 1.1,
            "climax": 1.25,
            "resolution": 0.75,
        }.get(phase, 1.0)

        tempo = base_tempo * (1.0 + 0.4 * arc_pressure)
        tempo *= (1.0 - 0.5 * peak_exposure)

        dwell = (
            1.0
            + 0.6 * (1.0 - completion)
            + 0.4 * arc_pressure
        )

        fatigue = (
            0.3 * peak_exposure
            + 0.2 * arc_pressure
        )

        return {
            "tempo": float(np.clip(tempo, 0.6, 1.5)),
            "dwell": float(np.clip(dwell, 0.6, 1.8)),
            "fatigue": float(np.clip(fatigue, 0.0, 1.0)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_pacing(metrics)

        self._tempo_bias = (
            self._tempo_bias * self._inertia
            + target["tempo"] * (1.0 - self._inertia)
        )

        self._dwell_bias = (
            self._dwell_bias * self._inertia
            + target["dwell"] * (1.0 - self._inertia)
        )

        self._fatigue = (
            self._fatigue * self._inertia
            + target["fatigue"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["cinematic_tempo_bias"] = self._tempo_bias
        out["shot_dwell_bias"] = self._dwell_bias
        out["audience_fatigue_estimate"] = self._fatigue

        return out


    def reset(self) -> None:
        """
        Reset mission-level pacing (mission restart).
        """
        self._tempo_bias = 1.0
        self._dwell_bias = 1.0
        self._fatigue = 0.0


