# ==============================================================================
# CHUNK 86 X 56 — CLOUD ↔ ONBOARD DIRECTOR SYNCHRONIZATION CORE
# ==============================================================================
#
# Purpose:
#   Maintain coherent director intent across cloud AI, onboard
#   director, and mobile app despite latency, packet loss,
#   partial disconnects, and compute asymmetry.
#
# Backbone truth:
#   Authority without synchronization becomes contradiction.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class CloudOnboardDirectorSynchronizationCore:
    """
    Cloud ↔ onboard director synchronization core.
    Reconciles distributed intent streams using semantic confidence,
    freshness, authority weighting, and degradation-aware merging.
    """

    __slots__ = (
        "_last_cloud_update",
        "_last_onboard_update",
        "_intent_confidence",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.92):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._last_cloud_update: float = 0.0
        self._last_onboard_update: float = 0.0
        self._intent_confidence: float = 1.0


    # --------------------------------------------------------------------------
    # Synchronization inference
    # --------------------------------------------------------------------------

    def _freshness(self, ts: float, horizon: float = 2.0) -> float:
        age = time.time() - ts
        return float(np.clip(1.0 - age / horizon, 0.0, 1.0))


    def _target_confidence(self, metrics: Dict[str, Any]) -> float:
        cloud_ok = metrics.get("cloud_link_active", False)
        onboard_ok = metrics.get("onboard_ok", True)
        latency = float(metrics.get("cloud_latency", 0.0))
        risk = float(metrics.get("flight_risk_level", 0.0))

        confidence = (
            0.5 * (1.0 if onboard_ok else 0.0)
            + 0.3 * (1.0 if cloud_ok else 0.0)
            + 0.2 * (1.0 - np.clip(latency / 1.5, 0.0, 1.0))
        )

        confidence *= (1.0 - 0.5 * risk)

        return float(np.clip(confidence, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        now = time.time()

        if metrics.get("cloud_update_received"):
            self._last_cloud_update = now
        if metrics.get("onboard_update_received"):
            self._last_onboard_update = now

        cloud_fresh = self._freshness(self._last_cloud_update)
        onboard_fresh = self._freshness(self._last_onboard_update)

        target_conf = self._target_confidence(metrics)

        self._intent_confidence = (
            self._intent_confidence * self._inertia
            + target_conf * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["director_sync"] = {
            "cloud_freshness": cloud_fresh,
            "onboard_freshness": onboard_fresh,
            "intent_confidence": self._intent_confidence,
            "cloud_preferred": cloud_fresh > onboard_fresh + 0.2,
            "onboard_preferred": onboard_fresh >= cloud_fresh,
        }

        out["director_sync_degraded"] = self._intent_confidence < 0.5

        return out


    def reset(self) -> None:
        """
        Reset synchronization state (mission restart).
        """
        self._last_cloud_update = 0.0
        self._last_onboard_update = 0.0
        self._intent_confidence = 1.0


