# ==============================================================================
# CHUNK 86 X 57 — DISTRIBUTED INTENT CONSENSUS ENGINE
# ==============================================================================
#
# Purpose:
#   Resolve intent disagreements across cloud AI, onboard director,
#   and human input into a single, stable, narratively-correct intent
#   without oscillation or dominance collapse.
#
# Backbone truth:
#   Consensus is alignment, not voting.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class DistributedIntentConsensusEngine:
    """
    Distributed intent consensus engine.
    Forms a unified intent vector by weighting semantic agreement,
    authority confidence, freshness, and cinematic alignment.
    """

    __slots__ = (
        "_consensus_strength",
        "_last_resolution_time",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._consensus_strength: float = 1.0
        self._last_resolution_time: float = 0.0


    # --------------------------------------------------------------------------
    # Consensus inference
    # --------------------------------------------------------------------------

    def _semantic_alignment(self, intents: Dict[str, Any]) -> float:
        """
        Estimate semantic agreement across intent sources.
        """
        vectors = [v for v in intents.values() if isinstance(v, dict)]
        if len(vectors) < 2:
            return 1.0

        magnitudes = [
            np.linalg.norm(list(v.values())) for v in vectors
        ]
        spread = np.std(magnitudes)
        return float(np.clip(1.0 - spread, 0.0, 1.0))


    def _target_consensus(self, metrics: Dict[str, Any]) -> float:
        intents = metrics.get("intent_sources", {})
        alignment = self._semantic_alignment(intents)

        sync = metrics.get("director_sync", {})
        confidence = float(sync.get("intent_confidence", 1.0))

        risk = float(metrics.get("flight_risk_level", 0.0))
        fatigue = float(metrics.get("audience_fatigue_estimate", 0.0))

        consensus = (
            0.5 * alignment
            + 0.3 * confidence
            + 0.2 * (1.0 - fatigue)
        )

        consensus *= (1.0 - 0.6 * risk)

        return float(np.clip(consensus, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_consensus(metrics)

        self._consensus_strength = (
            self._consensus_strength * self._inertia
            + target * (1.0 - self._inertia)
        )

        now = time.time()
        if self._consensus_strength > 0.7:
            self._last_resolution_time = now

        out = dict(metrics)
        out["intent_consensus_strength"] = self._consensus_strength
        out["intent_stable"] = self._consensus_strength > 0.6
        out["intent_conflict_active"] = self._consensus_strength < 0.4
        out["last_intent_resolution"] = self._last_resolution_time

        return out


    def reset(self) -> None:
        """
        Reset distributed intent consensus (mission restart).
        """
        self._consensus_strength = 1.0
        self._last_resolution_time = 0.0


