# CHUNK 86 X 58 — CROSS-DEVICE LATENCY COMPENSATION LAYER
# ==============================================================================
#
# Purpose:
#   Compensate for asymmetric latency across cloud AI, onboard
#   director, and mobile control so delayed intent still resolves
#   coherently, safely, and cinematically.
#
# Backbone truth:
#   Latency is not delay — it is uncertainty.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CrossDeviceLatencyCompensationLayer:
    """
    Cross-device latency compensation layer.
    Applies intent prediction, decay, and authority reweighting
    to mask latency without hallucinating control.
    """

    __slots__ = (
        "_latency_bias",
        "_prediction_confidence",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._latency_bias: float = 0.0
        self._prediction_confidence: float = 1.0


    # --------------------------------------------------------------------------
    # Latency inference
    # --------------------------------------------------------------------------

    def _target_latency(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        cloud_latency = float(metrics.get("cloud_latency", 0.0))
        uplink_latency = float(metrics.get("uplink_latency", 0.0))
        downlink_latency = float(metrics.get("downlink_latency", 0.0))

        worst = max(cloud_latency, uplink_latency, downlink_latency)

        bias = np.clip(worst / 1.5, 0.0, 1.0)
        confidence = 1.0 - bias

        return {
            "bias": float(bias),
            "confidence": float(np.clip(confidence, 0.2, 1.0)),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_latency(metrics)

        self._latency_bias = (
            self._latency_bias * self._inertia
            + target["bias"] * (1.0 - self._inertia)
        )

        self._prediction_confidence = (
            self._prediction_confidence * self._inertia
            + target["confidence"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        # Reduce reliance on remote intent as latency rises
        if "director_sync" in out:
            out["director_sync"]["cloud_weight"] = (
                1.0 - self._latency_bias
            )
            out["director_sync"]["onboard_weight"] = (
                1.0 + 0.5 * self._latency_bias
            )

        out["latency_compensation"] = {
            "latency_bias": self._latency_bias,
            "prediction_confidence": self._prediction_confidence,
        }

        out["latency_degraded"] = self._latency_bias > 0.4

        return out


    def reset(self) -> None:
        """
        Reset latency compensation state (mission restart).
        """
        self._latency_bias = 0.0
        self._prediction_confidence = 1.0


