# CHUNK 86 X 60 — MISSION SAFETY ENVELOPE GOVERNOR
# ==============================================================================
#
# Purpose:
#   Enforce the ultimate mission safety envelope that bounds
#   altitude, velocity, proximity, airspace, and authority —
#   regardless of cinematic intent or AI confidence.
#
# Backbone truth:
#   Cinema may bend — physics and law do not.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class MissionSafetyEnvelopeGovernor:
    """
    Mission safety envelope governor.
    Acts as the final arbiter that clamps, reshapes, or vetoes
    any intent that would violate physical, regulatory,
    or contractual mission boundaries.
    """

    __slots__ = (
        "_envelope_pressure",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.95):
        self._inertia = float(np.clip(inertia, 0.90, 0.99))
        self._envelope_pressure: float = 0.0


    # --------------------------------------------------------------------------
    # Envelope inference
    # --------------------------------------------------------------------------

    def _target_pressure(self, metrics: Dict[str, Any]) -> float:
        altitude = float(metrics.get("current_altitude", 0.0))
        max_alt = float(metrics.get("mission_limits", {}).get("max_altitude", 120.0))

        velocity = float(metrics.get("current_velocity", 0.0))
        max_vel = float(metrics.get("mission_limits", {}).get("max_velocity", 15.0))

        proximity = float(metrics.get("proximity_pressure", 0.0))
        airspace_ok = 1.0 if metrics.get("airspace_clear", True) else 0.0
        authority_ok = 1.0 if metrics.get("authority_valid", True) else 0.0

        alt_violation = np.clip((altitude - max_alt) / max_alt, 0.0, 1.0)
        vel_violation = np.clip((velocity - max_vel) / max_vel, 0.0, 1.0)

        pressure = (
            0.4 * alt_violation
            + 0.3 * vel_violation
            + 0.4 * proximity
            + 0.6 * (1.0 - airspace_ok)
            + 0.5 * (1.0 - authority_ok)
        )

        return float(np.clip(pressure, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_pressure(metrics)

        self._envelope_pressure = (
            self._envelope_pressure * self._inertia
            + target * (1.0 - self._inertia)
        )

        out = dict(metrics)

        # Progressive clamping instead of hard cut
        clamp = self._envelope_pressure

        if "flight_envelope" in out:
            out["flight_envelope"]["max_velocity"] *= (1.0 - 0.7 * clamp)
            out["flight_envelope"]["max_acceleration"] *= (1.0 - 0.7 * clamp)
            out["flight_envelope"]["max_yaw_rate"] *= (1.0 - 0.6 * clamp)
            out["flight_envelope"]["max_climb_rate"] *= (1.0 - 0.6 * clamp)

        if "subject_motion_plan" in out:
            out["subject_motion_plan"]["speed_scale"] *= (1.0 - 0.8 * clamp)

        out["mission_envelope_pressure"] = self._envelope_pressure
        out["mission_envelope_active"] = self._envelope_pressure > 0.1
        out["mission_envelope_critical"] = self._envelope_pressure > 0.7

        return out


    def reset(self) -> None:
        """
        Reset mission safety envelope (mission restart).
        """
        self._envelope_pressure = 0.0


