from typing import Dict, Any
import numpy as np
import time


class CloudAppIntentReflectionBridge:
    """
    Cloud ↔ App intent reflection bridge.
    Translates internal director state into explainable,
    latency-aware summaries suitable for real-time UI display.
    """

    __slots__ = (
        "_last_emit_time",
        "_emit_interval",
    )

    def __init__(self, emit_interval: float = 0.25):
        self._emit_interval = float(np.clip(emit_interval, 0.1, 1.0))
        self._last_emit_time: float = 0.0


    # --------------------------------------------------------------------------
    # Reflection synthesis
    # --------------------------------------------------------------------------

    def _synthesize(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        phase = metrics.get("narrative_phase", "unknown")
        intent = metrics.get("active_intent")
        authority = metrics.get("ai_authority_weight", 1.0)
        confidence = metrics.get("director_confidence", 1.0)
        risk = metrics.get("mission_envelope_pressure", 0.0)

        summary = {
            "intent": intent,
            "phase": phase,
            "authority": float(np.clip(authority, 0.0, 1.0)),
            "confidence": float(np.clip(confidence, 0.0, 1.0)),
            "risk_level": float(np.clip(risk, 0.0, 1.0)),
        }

        if metrics.get("failsafe_active"):
            summary["note"] = "Safety constraints shaping shot"
        elif metrics.get("intent_conflict_active"):
            summary["note"] = "Resolving intent disagreement"
        elif metrics.get("latency_degraded"):
            summary["note"] = "Latency compensation active"
        else:
            summary["note"] = "Autonomous cinematic control"

        return summary


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        now = time.time()
        out = dict(metrics)

        if (now - self._last_emit_time) < self._emit_interval:
            return out

        out["app_intent_reflection"] = self._synthesize(metrics)
        self._last_emit_time = now

        return out


    def reset(self) -> None:
        """
        Reset app reflection state (mission restart).
        """
        self._last_emit_time = 0.0


