#   by evaluating narrative fulfillment, safety state, user intent,
#   and diminishing cinematic returns — not just time or battery.
#
# Backbone truth:
#   A mission ends when the story is finished — not when the clock says so.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class AutonomousMissionCompletionArbiter:
    """
    Autonomous mission completion arbiter.
    Determines mission termination readiness using narrative closure,
    emotional arc exhaustion, safety pressure, and user satisfaction.
    """

    __slots__ = (
        "_completion_readiness",
        "_last_completion_signal",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.94):
        self._inertia = float(np.clip(inertia, 0.90, 0.99))
        self._completion_readiness: float = 0.0
        self._last_completion_signal: float = 0.0


    # --------------------------------------------------------------------------
    # Completion inference
    # --------------------------------------------------------------------------

    def _target_completion(self, metrics: Dict[str, Any]) -> float:
        phase = metrics.get("narrative_phase", "setup")
        arc_exhausted = float(metrics.get("emotional_peak_exposure", 0.0))
        fatigue = float(metrics.get("audience_fatigue_estimate", 0.0))
        envelope = float(metrics.get("mission_envelope_pressure", 0.0))
        confidence = float(metrics.get("director_confidence", 1.0))
        user_ok = 1.0 if metrics.get("user_objective_met", False) else 0.0

        narrative_ready = (
            1.0 if phase in ("resolution", "climax") else 0.0
        )

        readiness = (
            0.35 * narrative_ready
            + 0.25 * arc_exhausted
            + 0.20 * fatigue
            + 0.15 * envelope
            + 0.10 * user_ok
        )

        readiness *= confidence

        return float(np.clip(readiness, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_completion(metrics)

        self._completion_readiness = (
            self._completion_readiness * self._inertia
            + target * (1.0 - self._inertia)
        )

        now = time.time()
        if self._completion_readiness > 0.8:
            self._last_completion_signal = now

        out = dict(metrics)

        out["mission_completion_readiness"] = self._completion_readiness
        out["mission_complete"] = self._completion_readiness > 0.85
        out["mission_completion_recommended"] = (
            self._completion_readiness > 0.7
            and (now - self._last_completion_signal) > 1.0
        )

        return out


    def reset(self) -> None:
        """
        Reset mission completion state (mission restart).
        """
        self._completion_readiness = 0.0
        self._last_completion_signal = 0.0


