from typing import Dict, Any, List
import numpy as np
import time


class PostMissionNarrativeSynthesisEngine:
    """
    Post-mission narrative synthesis engine.
    Converts episodic shot memory and mission signals into a compact,
    causally-linked narrative representation suitable for learning
    and cross-mission reasoning.
    """

    __slots__ = (
        "_narrative",
    )

    def __init__(self):
        self._narrative: Dict[str, Any] = {}


    # --------------------------------------------------------------------------
    # Synthesis
    # --------------------------------------------------------------------------

    def synthesize(
        self,
        shot_ledger: List[Dict[str, Any]],
        metrics: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Build post-mission narrative summary.
        """
        if not shot_ledger:
            return {}

        emotions = {
            k: float(
                np.mean(
                    [
        s.get("emotion", {}).get(k, 0.0)
        for s in shot_ledger
                    ]
                )
            )
            for k in ("tension", "awe", "grief", "relief")
        }

        quality = float(
            np.mean(
                [
                    s.get("cinematic_score", 0.5)
                    for s in shot_ledger
                ]
            )
        )

        self._narrative = {
            "mission_id": metrics.get("mission_id"),
            "duration": metrics.get("mission_duration"),
            "final_phase": metrics.get("narrative_phase"),
            "average_quality": quality,
            "dominant_emotion": max(emotions, key=emotions.get),
            "emotional_signature": emotions,
            "peak_exposure": metrics.get("emotional_peak_exposure"),
            "risk_profile": metrics.get("mission_envelope_pressure"),
            "completion_confidence": metrics.get(
                "mission_completion_readiness"
            ),
            "timestamp": time.time(),
        }

        return dict(self._narrative)


    def reset(self) -> None:
        """
        Reset narrative synthesis state.
        """
        self._narrative.clear()


