from typing import Dict, Any, List
import numpy as np
import time


class CloudTrainingSignalExtractionLayer:
    """
    Cloud training signal extraction layer.
    Distills mission narratives, shot outcomes, and intent decisions
    into compact, privacy-safe learning samples suitable for
    continual cloud training.
    """

    __slots__ = (
        "_samples",
    )

    def __init__(self):
        self._samples: List[Dict[str, Any]] = []


    # --------------------------------------------------------------------------
    # Extraction
    # --------------------------------------------------------------------------

    def extract(
        self,
        narrative: Dict[str, Any],
        shot_ledger: List[Dict[str, Any]],
    ) -> List[Dict[str, Any]]:
        """
        Extract training samples from mission narrative and shots.
        """
        if not narrative or not shot_ledger:
            return []

        for shot in shot_ledger:
            sample = {
                "mission_id": narrative.get("mission_id"),
                "timestamp": shot.get("timestamp"),
                "intent": shot.get("intent"),
                "primary_subject": shot.get("primary_subject"),
                "emotion": shot.get("emotion"),
                "cinematic_score": shot.get("cinematic_score"),
                "risk_budget": shot.get("risk_budget"),
                "mission_context": {
                    "final_phase": narrative.get("final_phase"),
                    "average_quality": narrative.get("average_quality"),
                    "dominant_emotion": narrative.get("dominant_emotion"),
                },
            }

            self._samples.append(sample)

        return list(self._samples)


    def reset(self) -> None:
        """
        Reset extracted samples buffer.
        """
        self._samples.clear()


