from typing import Dict, Any
import numpy as np
import time


class DirectorSelfEvaluationLearningHooks:
    """
    Director self-evaluation & learning hooks.
    Compares predicted intent value against realized outcomes,
    tracking bias, confidence calibration, and stylistic drift.
    """

    __slots__ = (
        "_calibration_error",
        "_style_bias",
        "_confidence_drift",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.96):
        self._inertia = float(np.clip(inertia, 0.90, 0.99))
        self._calibration_error: float = 0.0
        self._style_bias: Dict[str, float] = {}
        self._confidence_drift: float = 0.0


    # --------------------------------------------------------------------------
    # Evaluation inference
    # --------------------------------------------------------------------------

    def _target_evaluation(self, metrics: Dict[str, Any]) -> Dict[str, float]:
        predicted = float(
            metrics.get("predicted_cinematic_value", 0.5)
        )
        realized = float(
            metrics.get("cinematic_kpi", {}).get(
                "overall_cinematic_score", 0.5
            )
        )

        confidence = float(metrics.get("director_confidence", 1.0))
        phase = metrics.get("narrative_phase", "unknown")

        calibration_error = realized - predicted
        confidence_drift = calibration_error * confidence

        return {
            "calibration_error": float(np.clip(calibration_error, -1.0, 1.0)),
            "confidence_drift": float(np.clip(confidence_drift, -1.0, 1.0)),
            "phase": phase,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_evaluation(metrics)

        self._calibration_error = (
            self._calibration_error * self._inertia
            + target["calibration_error"] * (1.0 - self._inertia)
        )

        self._confidence_drift = (
            self._confidence_drift * self._inertia
            + target["confidence_drift"] * (1.0 - self._inertia)
        )

        phase = target["phase"]
        if phase not in self._style_bias:
            self._style_bias[phase] = 0.0

        self._style_bias[phase] = (
            self._style_bias[phase] * self._inertia
            + self._calibration_error * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["self_evaluation"] = {
            "calibration_error": self._calibration_error,
            "confidence_drift": self._confidence_drift,
            "style_bias": dict(self._style_bias),
            "timestamp": time.time(),
        }

        return out


    def reset(self) -> None:
        """
        Reset self-evaluation state (mission restart).
        """
        self._calibration_error = 0.0
        self._confidence_drift = 0.0
        self._style_bias.clear()


