# CHUNK 86 X 66 — CROSS-MISSION STYLE CONSISTENCY ENGINE
# ==============================================================================
#
# Purpose:
#   Maintain stylistic coherence across missions so the director AI
#   develops a recognizable cinematic “voice” that persists while
#   still adapting to context and subject matter.
#
# Backbone truth:
#   Style is memory expressed through restraint.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class CrossMissionStyleConsistencyEngine:
    """
    Cross-mission style consistency engine.
    Stabilizes recurring stylistic tendencies (pace, contrast bias,
    motion aggressiveness, framing preference) across missions while
    allowing controlled evolution.
    """

    __slots__ = (
        "_style_vector",
        "_plasticity",
    )

    def __init__(self, plasticity: float = 0.08):
        self._plasticity = float(np.clip(plasticity, 0.02, 0.2))
        self._style_vector: Dict[str, float] = {
            "pace_bias": 1.0,
            "contrast_bias": 1.0,
            "motion_bias": 1.0,
            "framing_tightness": 0.5,
        }


    # --------------------------------------------------------------------------
    # Style update
    # --------------------------------------------------------------------------

    def update_from_evaluation(self, self_eval: Dict[str, Any]) -> None:
        """
        Adjust persistent style vector using self-evaluation feedback.
        """
        bias = self_eval.get("style_bias", {})

        for k in self._style_vector:
            delta = bias.get(k, 0.0)
            self._style_vector[k] += self._plasticity * delta
            self._style_vector[k] = float(
                np.clip(self._style_vector[k], 0.5, 1.5)
            )


    # --------------------------------------------------------------------------
    # Application
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(metrics)

        out["style_consistency"] = dict(self._style_vector)

        # Gently bias downstream systems
        if "cinematic_tempo_bias" in out:
            out["cinematic_tempo_bias"] *= self._style_vector["pace_bias"]

        if "camera_control_intent" in out:
            out["camera_control_intent"]["contrast_bias"] *= (
                self._style_vector["contrast_bias"]
            )

        if "subject_motion_plan" in out:
            out["subject_motion_plan"]["speed_scale"] *= (
                self._style_vector["motion_bias"]
            )

        return out


    def reset(self) -> None:
        """
        Reset style consistency (explicit user reset only).
        """
        self._style_vector = {
            "pace_bias": 1.0,
            "contrast_bias": 1.0,
            "motion_bias": 1.0,
            "framing_tightness": 0.5,
        }


