# CHUNK 86 X 67 — CLOUD MODEL FEEDBACK ASSIMILATION LAYER
# ==============================================================================
#
# Purpose:
#   Assimilate structured feedback from cloud-trained director models
#   into the onboard director AI without destabilizing live missions,
#   preserving stylistic continuity and safety guarantees.
#
# Backbone truth:
#   Learning must be absorbed — not injected.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CloudModelFeedbackAssimilationLayer:
    """
    Cloud model feedback assimilation layer.
    Gradually integrates cloud-derived improvement signals
    into the onboard director’s decision priors using
    confidence-weighted, inertia-controlled blending.
    """

    __slots__ = (
        "_assimilation_state",
        "_blend_rate",
    )

    def __init__(self, blend_rate: float = 0.05):
        self._blend_rate = float(np.clip(blend_rate, 0.01, 0.15))
        self._assimilation_state: Dict[str, float] = {}


    # --------------------------------------------------------------------------
    # Assimilation
    # --------------------------------------------------------------------------

    def assimilate(
        self,
        local_priors: Dict[str, float],
        cloud_feedback: Dict[str, Any],
    ) -> Dict[str, float]:
        """
        Blend cloud feedback into local priors safely.
        """
        confidence = float(cloud_feedback.get("confidence", 0.0))
        updates = cloud_feedback.get("prior_adjustments", {})

        weight = self._blend_rate * confidence

        for k, delta in updates.items():
            base = local_priors.get(k, 0.0)
            adjusted = base + weight * float(delta)
            self._assimilation_state[k] = adjusted

        return dict(self._assimilation_state)


    # --------------------------------------------------------------------------
    # Application
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(metrics)

        if "cloud_model_feedback" not in metrics:
            return out

        priors = metrics.get("director_priors", {})
        feedback = metrics["cloud_model_feedback"]

        updated = self.assimilate(priors, feedback)

        out["director_priors"] = updated
        out["cloud_feedback_applied"] = True
        out["cloud_feedback_timestamp"] = time.time()

        return out


    def reset(self) -> None:
        """
        Reset assimilation state (model rollback).
        """
        self._assimilation_state.clear()


