# ==============================================================================

from typing import Dict, Any
import json
import os
import time
import numpy as np


class DirectorPersonalityVectorPersistence:
    """
    Director personality vector persistence.
    Stores and restores long-term director traits such as stylistic
    bias, risk tolerance, pacing temperament, and confidence calibration.
    """

    __slots__ = (
        "_path",
        "_personality",
    )

    def __init__(self, path: str = "/data/director_personality.json"):
        self._path = path
        self._personality: Dict[str, float] = {}
        self._load()


    # --------------------------------------------------------------------------
    # Persistence
    # --------------------------------------------------------------------------

    def _load(self) -> None:
        if not os.path.exists(self._path):
            return
        try:
            with open(self._path, "r") as f:
                data = json.load(f)
            if isinstance(data, dict):
                self._personality = {
                    k: float(v) for k, v in data.items()
                }
        except Exception:
            self._personality = {}


    def _save(self) -> None:
        try:
            with open(self._path, "w") as f:
                json.dump(self._personality, f)
        except Exception:
            pass


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def update(self, traits: Dict[str, float]) -> None:
        """
        Update and persist personality traits.
        """
        for k, v in traits.items():
            self._personality[k] = float(
                np.clip(v, 0.0, 1.0)
            )
        self._personality["last_updated"] = time.time()
        self._save()


    # --------------------------------------------------------------------------
    # Application
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(metrics)
        out["director_personality"] = dict(self._personality)
        return out


    def reset(self) -> None:
        """
        Hard reset personality (explicit operator action).
        """
        self._personality.clear()
        self._save()


