#   stylistic state, evolve independently, and later merge without
#   collapsing identity or losing learned nuance.
#
# Backbone truth:
#   Style evolution is branching, not linear.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class MultiUserStyleForkMergeEngine:
    """
    Multi-user style fork & merge engine.
    Supports parallel stylistic evolution with lineage-aware merging
    using confidence-weighted reconciliation instead of naive averaging.
    """

    __slots__ = (
        "_branches",
    )

    def __init__(self):
        self._branches: Dict[str, Dict[str, Any]] = {}


    # --------------------------------------------------------------------------
    # Forking
    # --------------------------------------------------------------------------

    def fork(
        self,
        base_style: Dict[str, float],
        branch_id: str,
    ) -> None:
        """
        Create a new style branch from base style.
        """
        self._branches[branch_id] = {
            "style": dict(base_style),
            "confidence": 1.0,
            "created": time.time(),
        }


    # --------------------------------------------------------------------------
    # Merge
    # --------------------------------------------------------------------------

    def merge(
        self,
        base_style: Dict[str, float],
        branch_id: str,
    ) -> Dict[str, float]:
        """
        Merge branch back into base style.
        """
        branch = self._branches.get(branch_id)
        if not branch:
            return dict(base_style)

        merged = dict(base_style)
        confidence = float(np.clip(branch.get("confidence", 0.5), 0.0, 1.0))

        for k, v in branch["style"].items():
            base = base_style.get(k, v)
            merged[k] = base + confidence * (v - base)

        del self._branches[branch_id]

        return merged


    # --------------------------------------------------------------------------
    # Application
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(metrics)
        out["style_branches_active"] = list(self._branches.keys())
        return out


    def reset(self) -> None:
        """
        Reset all style branches.
        """
        self._branches.clear()


