from typing import Dict, Any
import numpy as np
import time


class HumanInTheLoopOverrideArbitration:
    """
    Human-in-the-loop override arbitration.
    Blends human input and AI autonomy using authority weighting,
    temporal smoothing, and post-override intent reintegration.
    """

    __slots__ = (
        "_override_strength",
        "_last_human_input",
        "_reintegration_bias",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.9):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._override_strength: float = 0.0
        self._last_human_input: float = 0.0
        self._reintegration_bias: float = 0.5


    # --------------------------------------------------------------------------
    # Override inference
    # --------------------------------------------------------------------------

    def _target_override(self, metrics: Dict[str, Any]) -> float:
        human_active = 1.0 if metrics.get("human_input_active") else 0.0
        urgency = float(metrics.get("human_input_urgency", 0.0))
        risk = float(metrics.get("mission_envelope_pressure", 0.0))
        latency = float(metrics.get("input_latency", 0.0))

        strength = (
            0.6 * human_active
            + 0.3 * urgency
            + 0.2 * risk
        )

        strength *= (1.0 - np.clip(latency / 1.0, 0.0, 1.0))

        return float(np.clip(strength, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_override(metrics)

        self._override_strength = (
            self._override_strength * self._inertia
            + target * (1.0 - self._inertia)
        )

        now = time.time()
        if metrics.get("human_input_active"):
            self._last_human_input = now

        # Reintegration bias grows the longer AI regains control
        idle = now - self._last_human_input
        self._reintegration_bias = float(
            np.clip(0.5 + 0.5 * idle / 3.0, 0.5, 1.0)
        )

        out = dict(metrics)

        out["override_state"] = {
            "override_strength": self._override_strength,
            "reintegration_bias": self._reintegration_bias,
            "human_preferred": self._override_strength > 0.6,
            "ai_preferred": self._override_strength < 0.4,
        }

        # Blend authority instead of switching
        out["ai_authority_weight"] = (
            (1.0 - self._override_strength) * self._reintegration_bias
        )
        out["human_authority_weight"] = self._override_strength

        return out


    def reset(self) -> None:
        """
        Reset override arbitration state (mission restart).
        """
        self._override_strength = 0.0
        self._last_human_input = 0.0
        self._reintegration_bias = 0.5


