# ==============================================================================
#
# Purpose:
#   Maintain a cryptographically-consistent, causally-linked ledger
#   of autonomous decisions so every action taken by the director
#   can be attributed, explained, audited, and improved.
#
# Backbone truth:
#   Trust is memory with structure.
#
# ==============================================================================

from typing import Dict, Any, List
import hashlib
import time
import json


class DirectorTrustAccountabilityLedger:
    """
    Director trust & accountability ledger.
    Records intent, context, authority state, and outcome hashes
    in an append-only, causally-linked chain suitable for audit,
    incident review, and regulatory explanation.
    """

    __slots__ = (
        "_ledger",
        "_last_hash",
    )

    def __init__(self):
        self._ledger: List[Dict[str, Any]] = []
        self._last_hash: str = ""


    # --------------------------------------------------------------------------
    # Hashing
    # --------------------------------------------------------------------------

    def _hash_entry(self, entry: Dict[str, Any]) -> str:
        payload = json.dumps(entry, sort_keys=True).encode("utf-8")
        return hashlib.sha256(payload).hexdigest()


    # --------------------------------------------------------------------------
    # Recording
    # --------------------------------------------------------------------------

    def record(self, metrics: Dict[str, Any]) -> None:
        """
        Append a new accountability entry.
        """
        entry = {
            "timestamp": time.time(),
            "intent": metrics.get("active_intent"),
            "authority": {
                "ai": metrics.get("ai_authority_weight"),
                "human": metrics.get("human_authority_weight"),
            },
            "risk": metrics.get("mission_envelope_pressure"),
            "phase": metrics.get("narrative_phase"),
            "confidence": metrics.get("director_confidence"),
            "previous_hash": self._last_hash,
        }

        entry_hash = self._hash_entry(entry)
        entry["hash"] = entry_hash

        self._ledger.append(entry)
        self._last_hash = entry_hash


    # --------------------------------------------------------------------------
    # Access
    # --------------------------------------------------------------------------

    def export(self) -> List[Dict[str, Any]]:
        """
        Export full accountability ledger.
        """
        return list(self._ledger)


    def reset(self) -> None:
        """
        Reset ledger (explicit regulatory clearance only).
        """
        self._ledger.clear()
        self._last_hash = ""


