import numpy as np
import time


class RegulatoryComplianceReasoningLayer:
    """
    Regulatory compliance reasoning layer.
    Evaluates proposed actions against airspace class, altitude limits,
    proximity to people, data capture constraints, and jurisdictional
    rules — producing both decisions and explanations.
    """

    __slots__ = (
        "_compliance_pressure",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.93):
        self._inertia = float(np.clip(inertia, 0.88, 0.99))
        self._compliance_pressure: float = 0.0


    # --------------------------------------------------------------------------
    # Compliance inference
    # --------------------------------------------------------------------------

    def _target_pressure(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        altitude = float(metrics.get("current_altitude", 0.0))
        jurisdiction = metrics.get("jurisdiction", "unknown")
        airspace = metrics.get("airspace_class", "G")
        people_nearby = float(metrics.get("people_density", 0.0))
        recording = bool(metrics.get("camera_recording", False))
        consent = bool(metrics.get("privacy_consent", False))

        reasons = []

        pressure = 0.0

        if altitude > metrics.get("reg_limits", {}).get("max_altitude", 120.0):
            pressure += 0.6
            reasons.append("Altitude exceeds regulatory limit")

        if airspace not in ("G", "E"):
            pressure += 0.7
            reasons.append(f"Restricted airspace class {airspace}")

        if people_nearby > 0.6:
            pressure += 0.5
            reasons.append("High people density")

        if recording and not consent:
            pressure += 0.8
            reasons.append("Recording without consent")

        return {
            "pressure": float(np.clip(pressure, 0.0, 1.0)),
            "reasons": reasons,
            "jurisdiction": jurisdiction,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_pressure(metrics)

        self._compliance_pressure = (
            self._compliance_pressure * self._inertia
            + target["pressure"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        out["regulatory_compliance"] = {
            "pressure": self._compliance_pressure,
            "reasons": target["reasons"],
            "jurisdiction": target["jurisdiction"],
            "timestamp": time.time(),
        }

        out["regulatory_block"] = self._compliance_pressure > 0.7
        out["regulatory_warning"] = 0.3 < self._compliance_pressure <= 0.7

        return out


    def reset(self) -> None:
        """
        Reset compliance reasoning (mission restart).
        """
        self._compliance_pressure = 0.0


