from typing import Dict, Any, List
import numpy as np
import time


class PrivacyAwareCinematographyFilter:
    """
    Privacy-aware cinematography filter.
    Applies perceptual and compositional constraints to avoid
    intrusive capture of non-consenting subjects while preserving
    narrative and aesthetic integrity.
    """

    __slots__ = (
        "_privacy_pressure",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.93):
        self._inertia = float(np.clip(inertia, 0.88, 0.99))
        self._privacy_pressure: float = 0.0


    # --------------------------------------------------------------------------
    # Privacy inference
    # --------------------------------------------------------------------------

    def _target_pressure(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        bystanders = float(metrics.get("bystander_density", 0.0))
        consented_subjects = metrics.get("consented_subjects", [])
        detected_faces = metrics.get("detected_faces", [])
        zoom = float(metrics.get("camera_zoom", 1.0))

        pressure = 0.0
        reasons: List[str] = []

        unconsented_faces = max(
            0,
            len(detected_faces) - len(consented_subjects),
        )

        if unconsented_faces > 0:
            pressure += 0.4
            reasons.append("Unconsented individuals in frame")

        if bystanders > 0.5:
            pressure += 0.4
            reasons.append("High bystander density")

        if zoom > 2.5 and unconsented_faces > 0:
            pressure += 0.6
            reasons.append("Zoom amplifies privacy risk")

        return {
            "pressure": float(np.clip(pressure, 0.0, 1.0)),
            "reasons": reasons,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_pressure(metrics)

        self._privacy_pressure = (
            self._privacy_pressure * self._inertia
            + target["pressure"] * (1.0 - self._inertia)
        )

        out = dict(metrics)

        # Privacy pressure reshapes perception instead of hard censoring
        if "camera_control_intent" in out:
            out["camera_control_intent"]["focus_priority"] *= (
                1.0 - 0.7 * self._privacy_pressure
            )
            out["camera_control_intent"]["background_softness"] += (
                0.6 * self._privacy_pressure
            )
            out["camera_control_intent"]["zoom_limit"] = min(
                out["camera_control_intent"].get("zoom_limit", 4.0),
                4.0 - 2.0 * self._privacy_pressure,
            )

        if "subject_selection" in out:
            out["subject_selection"]["non_primary_weight"] *= (
                1.0 - 0.8 * self._privacy_pressure
            )

        out["privacy_filter"] = {
            "pressure": self._privacy_pressure,
            "reasons": target["reasons"],
            "timestamp": time.time(),
        }

        out["privacy_constraint_active"] = self._privacy_pressure > 0.25

        return out


    def reset(self) -> None:
        """
        Reset privacy filter state (mission restart).
        """
        self._privacy_pressure = 0.0


