from typing import Dict, Any, List
import numpy as np
import time


class PreemptiveEvasionAbortPlanner:
    """
    Preemptive evasion & abort planner.
    Plans graded evasive maneuvers and abort paths using
    predicted risk, environmental constraints, and recovery
    affordances — not binary escape commands.
    """

    __slots__ = (
        "_active_plan",
        "_confidence",
    )

    def __init__(self):
        self._active_plan: Dict[str, Any] = {}
        self._confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Planning
    # --------------------------------------------------------------------------

    def _generate_candidates(self, metrics: Dict[str, Any]) -> List[Dict[str, Any]]:
        altitude = float(metrics.get("current_altitude", 0.0))
        obstacles = float(metrics.get("obstacle_density", 0.0))
        wind = float(metrics.get("weather_turbulence_index", 0.0))
        people = float(metrics.get("people_density", 0.0))

        candidates = []

        # Vertical retreat
        candidates.append({
            "type": "vertical_climb",
            "risk_reduction": max(0.0, 0.6 - obstacles),
            "ethics_cost": people * 0.4,
            "energy_cost": 0.4,
        })

        # Lateral retreat
        candidates.append({
            "type": "lateral_displacement",
            "risk_reduction": max(0.0, 0.7 - obstacles - wind),
            "ethics_cost": people * 0.2,
            "energy_cost": 0.3,
        })

        # Descent & hover
        candidates.append({
            "type": "controlled_descent",
            "risk_reduction": max(0.0, 0.5 - wind),
            "ethics_cost": people * 0.6,
            "energy_cost": 0.2,
        })

        return candidates


    def _score(self, c: Dict[str, Any]) -> float:
        return (
            1.2 * c["risk_reduction"]
            - 0.6 * c["ethics_cost"]
            - 0.4 * c["energy_cost"]
        )


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        anticipated = float(metrics.get("anticipated_risk", {}).get("level", 0.0))
        if anticipated < 0.3:
            return metrics

        candidates = self._generate_candidates(metrics)
        scored = [(self._score(c), c) for c in candidates]
        scored.sort(key=lambda x: x[0], reverse=True)

        best_score, best = scored[0]
        self._active_plan = best
        self._confidence = float(np.clip(best_score, 0.0, 1.0))

        out = dict(metrics)
        out["evasion_plan"] = {
            "type": best["type"],
            "confidence": self._confidence,
            "timestamp": time.time(),
        }

        out["abort_preemptive"] = self._confidence > 0.4

        return out


    def reset(self) -> None:
        """
        Reset evasion planner state.
        """
        self._active_plan.clear()
        self._confidence = 0.0


