from typing import Dict, Any, List
import numpy as np
import time


class AutonomousSafeLandingOrchestrator:
    """
    Autonomous safe-landing orchestrator.
    Selects, validates, and executes landing strategies that maximize
    survivability, minimize public risk, and preserve hardware integrity
    even under partial system failure.
    """

    __slots__ = (
        "_active_site",
        "_landing_confidence",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.95):
        self._inertia = float(np.clip(inertia, 0.9, 0.99))
        self._active_site: Dict[str, Any] = {}
        self._landing_confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Site evaluation
    # --------------------------------------------------------------------------

    def _evaluate_sites(self, metrics: Dict[str, Any]) -> List[Dict[str, Any]]:
        sites = metrics.get("candidate_landing_sites", [])
        people = float(metrics.get("people_density", 0.0))
        wind = float(metrics.get("weather_turbulence_index", 0.0))
        power = float(metrics.get("power_margin", 1.0))
        visibility = float(metrics.get("visibility_confidence", 1.0))

        evaluated = []

        for s in sites:
            score = (
                0.4 * s.get("terrain_flatness", 0.0)
                + 0.3 * (1.0 - s.get("obstacle_density", 1.0))
                + 0.2 * visibility
                + 0.2 * power
                - 0.4 * people
                - 0.3 * wind
            )

            evaluated.append({
                "site": s,
                "score": float(np.clip(score, 0.0, 1.0)),
            })

        return evaluated


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        trigger = (
            metrics.get("emergency_active")
            or metrics.get("abort_preemptive")
            or metrics.get("power_margin", 1.0) < 0.25
        )

        if not trigger:
            return metrics

        evaluated = self._evaluate_sites(metrics)
        if not evaluated:
            return metrics

        evaluated.sort(key=lambda x: x["score"], reverse=True)
        best = evaluated[0]

        self._landing_confidence = (
            self._landing_confidence * self._inertia
            + best["score"] * (1.0 - self._inertia)
        )

        self._active_site = best["site"]

        out = dict(metrics)
        out["landing_plan"] = {
            "site": self._active_site,
            "confidence": self._landing_confidence,
            "timestamp": time.time(),
        }

        out["landing_authorized"] = self._landing_confidence > 0.4
        out["landing_immediate"] = self._landing_confidence > 0.7

        return out


    def reset(self) -> None:
        """
        Reset landing orchestrator state.
        """
        self._active_site.clear()
        self._landing_confidence = 0.0


