from typing import Dict, Any, List
import time
import hashlib
import json


class MissionDebriefCognitiveArchive:
    """
    Mission debrief cognitive archive.
    Stores distilled mission intelligence — not raw telemetry —
    enabling future reasoning, pattern discovery, and retrospective
    improvement across the director AI.
    """

    __slots__ = (
        "_archive",
    )

    def __init__(self):
        self._archive: List[Dict[str, Any]] = []


    # --------------------------------------------------------------------------
    # Archival
    # --------------------------------------------------------------------------

    def _fingerprint(self, mission: Dict[str, Any]) -> str:
        payload = json.dumps(mission, sort_keys=True).encode("utf-8")
        return hashlib.sha256(payload).hexdigest()


    def archive(
        self,
        narrative: Dict[str, Any],
        outcome: Dict[str, Any],
        incidents: List[Dict[str, Any]],
    ) -> Dict[str, Any]:
        """
        Archive a completed mission as a cognitive record.
        """
        record = {
            "timestamp": time.time(),
            "mission_id": narrative.get("mission_id"),
            "narrative_arc": narrative.get("arc_shape"),
            "dominant_emotion": narrative.get("dominant_emotion"),
            "average_quality": narrative.get("average_quality"),
            "final_phase": narrative.get("final_phase"),
            "incidents": incidents,
            "outcome": outcome,
        }

        record["fingerprint"] = self._fingerprint(record)
        self._archive.append(record)

        return record


    # --------------------------------------------------------------------------
    # Query
    # --------------------------------------------------------------------------

    def query(self, key: str, value: Any) -> List[Dict[str, Any]]:
        """
        Query archive by key/value match.
        """
        return [
            r for r in self._archive
            if r.get(key) == value
        ]


    def export(self) -> List[Dict[str, Any]]:
        """
        Export full cognitive archive.
        """
        return list(self._archive)


    def reset(self) -> None:
        """
        Reset cognitive archive (explicit operator action).
        """
        self._archive.clear()


