from typing import Dict, Any, List
import numpy as np
import time


class CrossMissionKnowledgeDistillationCore:
    """
    Cross-mission knowledge distillation core.
    Converts mission-level cognitive records into abstract priors
    governing emotion pacing, risk tolerance, authority blending,
    and outcome optimization across future missions.
    """

    __slots__ = (
        "_priors",
        "_confidence",
    )

    def __init__(self):
        self._priors: Dict[str, float] = {}
        self._confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Distillation
    # --------------------------------------------------------------------------

    def distill(self, archives: List[Dict[str, Any]]) -> Dict[str, float]:
        """
        Distill priors from multiple mission archives.
        """
        if not archives:
            return self._priors

        quality = []
        risk = []
        emotion = []
        incidents = []

        for a in archives:
            quality.append(a.get("average_quality", 0.0))
            risk.append(
                len(a.get("incidents", [])) * 0.2
            )
            emotion.append(
                1.0 if a.get("dominant_emotion") in ("awe", "triumph") else 0.5
            )
            incidents.append(len(a.get("incidents", [])))

        self._priors = {
            "quality_expectation": float(np.clip(np.mean(quality), 0.0, 1.0)),
            "risk_tolerance": float(np.clip(1.0 - np.mean(risk), 0.0, 1.0)),
            "emotional_boldness": float(np.clip(np.mean(emotion), 0.0, 1.0)),
            "incident_frequency": float(np.clip(np.mean(incidents), 0.0, 1.0)),
        }

        self._confidence = float(
            np.clip(len(archives) / 20.0, 0.1, 1.0)
        )

        self._priors["confidence"] = self._confidence
        self._priors["last_updated"] = time.time()

        return dict(self._priors)


    # --------------------------------------------------------------------------
    # Application
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(metrics)
        out["distilled_priors"] = dict(self._priors)
        out["distillation_confidence"] = self._confidence
        return out


    def reset(self) -> None:
        """
        Reset distilled knowledge.
        """
        self._priors.clear()
        self._confidence = 0.0


