from typing import Dict, Any
import numpy as np
import time


class DirectorConfidenceCalibrationEngine:
    """
    Director confidence calibration engine.
    Aligns internal confidence with historical outcomes, uncertainty,
    incident rates, and human override frequency, producing a
    well-calibrated authority signal.
    """

    __slots__ = (
        "_confidence",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.94):
        self._inertia = float(np.clip(inertia, 0.9, 0.99))
        self._confidence: float = 0.5


    # --------------------------------------------------------------------------
    # Calibration inference
    # --------------------------------------------------------------------------

    def _target_confidence(self, metrics: Dict[str, Any]) -> float:
        quality = float(metrics.get("average_quality", 0.5))
        incidents = float(len(metrics.get("incidents", []))) * 0.2
        uncertainty = float(metrics.get("perceptual_uncertainty", 0.0))
        overrides = float(metrics.get("human_override_rate", 0.0))
        safety = float(metrics.get("public_safety", {}).get("priority", 0.0))

        target = (
            0.6 * quality
            - 0.4 * incidents
            - 0.5 * uncertainty
            - 0.3 * overrides
            - 0.4 * safety
        )

        return float(np.clip(target, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        target = self._target_confidence(metrics)

        self._confidence = (
            self._confidence * self._inertia
            + target * (1.0 - self._inertia)
        )

        out = dict(metrics)
        out["director_confidence"] = self._confidence
        out["confidence_calibrated_at"] = time.time()

        return out


    def reset(self) -> None:
        """
        Reset confidence calibration (explicit operator action).
        """
        self._confidence = 0.5


