from typing import Dict, Any
import numpy as np
import time


class LongHorizonStyleEvolutionModel:
    """
    Long-horizon style evolution model.
    Adjusts high-level stylistic parameters slowly and reversibly,
    preserving core identity while incorporating validated learning
    from extended operation.
    """

    __slots__ = (
        "_style",
        "_identity_anchor",
        "_rate",
    )

    def __init__(self, base_style: Dict[str, float], rate: float = 0.02):
        self._style = dict(base_style)
        self._identity_anchor = dict(base_style)
        self._rate = float(np.clip(rate, 0.005, 0.05))


    # --------------------------------------------------------------------------
    # Evolution
    # --------------------------------------------------------------------------

    def evolve(self, signals: Dict[str, Any]) -> Dict[str, float]:
        """
        Evolve style using bounded, confidence-weighted updates.
        """
        confidence = float(signals.get("distillation_confidence", 0.0))
        priors = signals.get("distilled_priors", {})
        calibration = float(signals.get("director_confidence", 0.5))

        for k, anchor in self._identity_anchor.items():
            prior = float(priors.get(k, anchor))
            delta = self._rate * confidence * (prior - self._style.get(k, anchor))
            # Anchor pull prevents drift
            anchor_pull = 0.5 * (anchor - self._style.get(k, anchor))
            self._style[k] += delta + 0.01 * anchor_pull

        # Global temperament coupling
        if "emotional_boldness" in priors:
            self._style["emotional_boldness"] = float(
                np.clip(
                    self._style.get("emotional_boldness", 0.5)
                    + self._rate * (priors["emotional_boldness"] - calibration),
                    0.0,
                    1.0,
                )
            )

        self._style["last_evolved"] = time.time()
        return dict(self._style)


    # --------------------------------------------------------------------------
    # Application
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(metrics)
        out["evolved_style"] = dict(self._style)
        return out


    def reset(self) -> None:
        """
        Reset to identity anchor (explicit operator action).
        """
        self._style = dict(self._identity_anchor)


