#   Shared intelligence requires semantic, not temporal, consistency.
#
# ==============================================================================

from typing import Dict, Any
import time
import hashlib
import json


class CrossDeviceDirectorSynchronizationLayer:
    """
    Cross-device director synchronization layer.
    Maintains a causally-consistent shared director state using
    semantic hashes, confidence weighting, and authority domains
    rather than naive timestamp-based mirroring.
    """

    __slots__ = (
        "_state_hash",
        "_last_sync",
    )

    def __init__(self):
        self._state_hash: str = ""
        self._last_sync: float = 0.0


    # --------------------------------------------------------------------------
    # Hashing
    # --------------------------------------------------------------------------

    def _hash_state(self, state: Dict[str, Any]) -> str:
        payload = json.dumps(state, sort_keys=True).encode("utf-8")
        return hashlib.sha256(payload).hexdigest()


    # --------------------------------------------------------------------------
    # Synchronization
    # --------------------------------------------------------------------------

    def synchronize(
        self,
        local_state: Dict[str, Any],
        remote_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Synchronize local and remote director states.
        """
        local_hash = self._hash_state(local_state)
        remote_hash = self._hash_state(remote_state)

        if local_hash == remote_hash:
            return local_state

        # Authority-based reconciliation
        local_conf = float(local_state.get("director_confidence", 0.5))
        remote_conf = float(remote_state.get("director_confidence", 0.5))

        if remote_conf > local_conf:
            merged = dict(remote_state)
        else:
            merged = dict(local_state)

        self._state_hash = self._hash_state(merged)
        self._last_sync = time.time()

        merged["sync_state"] = {
            "hash": self._state_hash,
            "timestamp": self._last_sync,
        }

        return merged


    def reset(self) -> None:
        """
        Reset synchronization state.
        """
        self._state_hash = ""
        self._last_sync = 0.0


