# CHUNK 86 X 86 — CLOUD ↔ EDGE COGNITIVE CONSISTENCY MONITOR
# ==============================================================================
#
# Purpose:
#   Continuously detect and quantify silent divergence between cloud
#   director cognition and edge (Radxa) cognition before it manifests
#   as unsafe or incoherent behavior.
#
# Backbone truth:
#   Desynchronization is failure in slow motion.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CloudEdgeCognitiveConsistencyMonitor:
    """
    Cloud ↔ edge cognitive consistency monitor.
    Computes semantic divergence across key cognitive axes
    (intent, confidence, risk, ethics) and raises graded alerts
    long before hard failure.
    """

    __slots__ = (
        "_divergence",
        "_inertia",
        "_last_alert",
    )

    def __init__(self, inertia: float = 0.94):
        self._inertia = float(np.clip(inertia, 0.9, 0.99))
        self._divergence: float = 0.0
        self._last_alert: float = 0.0


    # --------------------------------------------------------------------------
    # Divergence estimation
    # --------------------------------------------------------------------------

    def _estimate_divergence(
        self,
        cloud: Dict[str, Any],
        edge: Dict[str, Any],
    ) -> Dict[str, Any]:
        d = 0.0
        reasons = []

        for k in (
            "active_intent",
            "director_confidence",
            "anticipated_risk",
            "ethical_constraints",
            "public_safety",
        ):
            if cloud.get(k) != edge.get(k):
                d += 0.2
                reasons.append(f"Mismatch in {k}")

        return {
            "divergence": float(np.clip(d, 0.0, 1.0)),
            "reasons": reasons,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        cloud_state: Dict[str, Any],
        edge_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        target = self._estimate_divergence(cloud_state, edge_state)

        self._divergence = (
            self._divergence * self._inertia
            + target["divergence"] * (1.0 - self._inertia)
        )

        now = time.time()
        if self._divergence > 0.4:
            self._last_alert = now

        return {
            "cognitive_divergence": {
                "level": self._divergence,
                "reasons": target["reasons"],
                "timestamp": now,
            },
            "divergence_warning": self._divergence > 0.25,
            "divergence_critical": self._divergence > 0.6,
            "last_alert": self._last_alert,
        }


    def reset(self) -> None:
        """
        Reset divergence monitoring.
        """
        self._divergence = 0.0
        self._last_alert = 0.0


