from typing import Dict, Any, List
import numpy as np
import time


class MultiModalIntentGroundingBridge:
    """
    Multi-modal intent grounding bridge.
    Fuses language intent, visual saliency, motion affordances,
    and safety context into a single grounded intent vector
    suitable for cinematic planning and control.
    """

    __slots__ = (
        "_grounded_intent",
        "_confidence",
    )

    def __init__(self):
        self._grounded_intent: Dict[str, Any] = {}
        self._confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Grounding
    # --------------------------------------------------------------------------

    def ground(
        self,
        language: Dict[str, Any],
        vision: Dict[str, Any],
        motion: Dict[str, Any],
        safety: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Ground intent across modalities.
        """
        intent_type = language.get("intent_type", "unknown")
        target = vision.get("primary_subject")
        affordances = motion.get("available_actions", [])
        safety_level = float(safety.get("priority", 0.0))

        confidence = (
            0.4 * language.get("confidence", 0.0)
            + 0.3 * vision.get("confidence", 0.0)
            + 0.3 * (1.0 - safety_level)
        )

        self._grounded_intent = {
            "type": intent_type,
            "target": target,
            "affordances": affordances,
            "safety_bias": safety_level,
        }

        self._confidence = float(np.clip(confidence, 0.0, 1.0))

        return {
            "grounded_intent": self._grounded_intent,
            "grounding_confidence": self._confidence,
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset grounded intent state.
        """
        self._grounded_intent.clear()
        self._confidence = 0.0


