from typing import Dict, Any, List
import numpy as np
import time


class NaturalLanguageDirectorActionCompiler:
    """
    Natural language → director action compiler.
    Converts grounded, multi-modal intent into an ordered action
    program that the director can schedule, adapt, or refuse.
    """

    __slots__ = (
        "_last_program",
        "_confidence",
    )

    def __init__(self):
        self._last_program: List[Dict[str, Any]] = []
        self._confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Compilation
    # --------------------------------------------------------------------------

    def compile(
        self,
        grounded_intent: Dict[str, Any],
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Compile grounded intent into a director action program.
        """
        intent_type = grounded_intent.get("type", "unknown")
        target = grounded_intent.get("target")
        affordances = grounded_intent.get("affordances", [])
        safety_bias = float(grounded_intent.get("safety_bias", 0.0))

        program: List[Dict[str, Any]] = []

        # High-level intent decomposition
        if intent_type == "follow":
            program.append({
                "action": "track_subject",
                "target": target,
                "priority": 0.8,
            })
            program.append({
                "action": "maintain_distance",
                "target": target,
                "priority": 0.7,
            })

        elif intent_type == "cinematic_shot":
            program.append({
                "action": "optimize_framing",
                "style": context.get("requested_style", "neutral"),
                "priority": 0.7,
            })
            program.append({
                "action": "smooth_camera_motion",
                "priority": 0.6,
            })

        else:
            program.append({
                "action": "observe",
                "priority": 0.3,
            })

        # Safety modulation
        for step in program:
            step["priority"] *= (1.0 - 0.5 * safety_bias)

        # Confidence estimation
        self._confidence = float(
            np.clip(
                0.5
                + 0.3 * (1.0 - safety_bias)
                + 0.2 * (len(program) / 3.0),
                0.0,
                1.0,
            )
        )

        self._last_program = program

        return {
            "director_action_program": program,
            "program_confidence": self._confidence,
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset compiled program.
        """
        self._last_program.clear()
        self._confidence = 0.0


