# CHUNK 86 X 89 — VISION-LANGUAGE CROSS-ATTENTION CONTROLLER
# ==============================================================================
#
# Purpose:
#   Bind linguistic references to visual entities across time so
#   “what the user means” remains aligned with “what the system sees”,
#   even as saliency, motion, and context evolve.
#
# Backbone truth:
#   Attention is not where the eyes go — it’s where meaning stays.
#
# ==============================================================================

from typing import Dict, Any, List
import numpy as np
import time


class VisionLanguageCrossAttentionController:
    """
    Vision-language cross-attention controller.
    Maintains stable bindings between linguistic references and
    visual entities using confidence-weighted, temporally-smoothed
    cross-attention — resistant to distractors and saliency shifts.
    """

    __slots__ = (
        "_bindings",
        "_attention_map",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.92):
        self._bindings: Dict[str, Any] = {}
        self._attention_map: Dict[str, float] = {}
        self._inertia = float(np.clip(inertia, 0.85, 0.99))


    # --------------------------------------------------------------------------
    # Attention computation
    # --------------------------------------------------------------------------

    def _compute_attention(
        self,
        language_refs: List[Dict[str, Any]],
        vision_entities: List[Dict[str, Any]],
    ) -> Dict[str, float]:
        attention: Dict[str, float] = {}

        for ref in language_refs:
            ref_id = ref.get("id")
            ref_conf = float(ref.get("confidence", 0.0))

            best_score = 0.0
            best_entity = None

            for ent in vision_entities:
                score = (
                    0.5 * float(ent.get("semantic_match", 0.0))
                    + 0.3 * float(ent.get("temporal_consistency", 0.0))
                    + 0.2 * float(ent.get("saliency", 0.0))
                )

                if score > best_score:
                    best_score = score
                    best_entity = ent.get("id")

            if best_entity is not None:
                attention[best_entity] = ref_conf * best_score

        return attention


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        language: Dict[str, Any],
        vision: Dict[str, Any],
    ) -> Dict[str, Any]:
        refs = language.get("references", [])
        entities = vision.get("entities", [])

        new_attention = self._compute_attention(refs, entities)

        # Temporal smoothing
        for k, v in new_attention.items():
            prev = self._attention_map.get(k, 0.0)
            self._attention_map[k] = (
                prev * self._inertia + v * (1.0 - self._inertia)
            )

        # Normalize
        total = sum(self._attention_map.values()) + 1e-6
        for k in self._attention_map:
            self._attention_map[k] /= total

        self._bindings = {
            "primary_target": max(
                self._attention_map,
                key=self._attention_map.get,
                default=None,
            ),
            "attention_map": dict(self._attention_map),
        }

        return {
            "vision_language_binding": dict(self._bindings),
            "binding_confidence": max(self._attention_map.values(), default=0.0),
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset attention bindings.
        """
        self._bindings.clear()
        self._attention_map.clear()


