from typing import Dict, Any, List
import numpy as np
import time


class IntentToMotionPrimitiveTranslator:
    """
    Intent → motion primitive translator.
    Converts director action programs into time-aware motion primitives
    suitable for downstream trajectory synthesis and control layers.
    """

    __slots__ = (
        "_last_primitives",
        "_confidence",
    )

    def __init__(self):
        self._last_primitives: List[Dict[str, Any]] = []
        self._confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Translation
    # --------------------------------------------------------------------------

    def _primitive_from_action(
        self,
        action: Dict[str, Any],
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        kind = action.get("action")
        priority = float(action.get("priority", 0.5))
        safety = float(context.get("safety_bias", 0.0))

        if kind == "track_subject":
            return {
                "primitive": "relative_follow",
                "gain": 0.6 * priority * (1.0 - safety),
                "smoothness": 0.8,
            }

        if kind == "maintain_distance":
            return {
                "primitive": "distance_hold",
                "gain": 0.5 * priority,
                "tolerance": 0.2,
            }

        if kind == "optimize_framing":
            return {
                "primitive": "framing_adjust",
                "gain": 0.4 * priority,
                "smoothness": 0.9,
            }

        if kind == "smooth_camera_motion":
            return {
                "primitive": "motion_damping",
                "gain": 0.7,
            }

        return {
            "primitive": "observe",
            "gain": 0.1,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def translate(
        self,
        program: List[Dict[str, Any]],
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Translate director action program into motion primitives.
        """
        primitives: List[Dict[str, Any]] = []

        for step in program:
            primitives.append(
                self._primitive_from_action(step, context)
            )

        self._confidence = float(
            np.clip(
                np.mean([p.get("gain", 0.0) for p in primitives]) if primitives else 0.0,
                0.0,
                1.0,
            )
        )

        self._last_primitives = primitives

        return {
            "motion_primitives": primitives,
            "translation_confidence": self._confidence,
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset motion primitive translation state.
        """
        self._last_primitives.clear()
        self._confidence = 0.0


