#   from motion primitives while preserving narrative intent,
#   emotional pacing, and physical feasibility.
#
# Backbone truth:
#   Trajectory is the sentence cinema writes in space.
#
# ==============================================================================

from typing import Dict, Any, List
import numpy as np
import time


class CinematicTrajectorySynthesisEngine:
    """
    Cinematic trajectory synthesis engine.
    Integrates motion primitives into smooth, time-parameterized
    trajectories that balance elegance, responsiveness, and safety.
    """

    __slots__ = (
        "_trajectory",
        "_confidence",
        "_temporal_horizon",
    )

    def __init__(self, temporal_horizon: float = 3.0):
        self._trajectory: List[Dict[str, Any]] = []
        self._confidence: float = 0.0
        self._temporal_horizon = float(np.clip(temporal_horizon, 1.0, 6.0))


    # --------------------------------------------------------------------------
    # Synthesis
    # --------------------------------------------------------------------------

    def _integrate(
        self,
        primitives: List[Dict[str, Any]],
        state: Dict[str, Any],
    ) -> List[Dict[str, Any]]:
        t = 0.0
        dt = self._temporal_horizon / max(len(primitives), 1)
        path = []

        pos = np.array(state.get("position", [0.0, 0.0, 0.0]), dtype=float)
        vel = np.zeros(3)

        for p in primitives:
            gain = float(p.get("gain", 0.1))
            smooth = float(p.get("smoothness", 0.7))

            direction = np.array(state.get("desired_direction", [1.0, 0.0, 0.0]))
            vel = smooth * vel + (1.0 - smooth) * gain * direction
            pos = pos + vel * dt

            path.append({
                "t": t,
                "position": pos.tolist(),
                "velocity": vel.tolist(),
            })

            t += dt

        return path


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        primitives: List[Dict[str, Any]],
        state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Generate cinematic trajectory from motion primitives.
        """
        if not primitives:
            return {}

        path = self._integrate(primitives, state)
        self._trajectory = path

        self._confidence = float(
            np.clip(
                np.mean([np.linalg.norm(p["velocity"]) for p in path]),
                0.0,
                1.0,
            )
        )

        return {
            "cinematic_trajectory": path,
            "trajectory_confidence": self._confidence,
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset trajectory synthesis state.
        """
        self._trajectory.clear()
        self._confidence = 0.0


