# CHUNK 86 X 92 — GIMBAL–DRONE COHERENT MOTION PLANNER
# ==============================================================================
#
# Purpose:
#   Enforce coherence between drone body motion and gimbal motion
#   so framing intent, subject tracking, and cinematic smoothness
#   are achieved without internal control conflict.
#
# Backbone truth:
#   The camera and the vehicle must think as one body.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class GimbalDroneCoherentMotionPlanner:
    """
    Gimbal–drone coherent motion planner.
    Couples vehicle trajectory and gimbal actuation so camera intent
    is satisfied primarily through vehicle motion, with gimbal used
    only for fine residual correction.
    """

    __slots__ = (
        "_gimbal_bias",
        "_vehicle_bias",
        "_confidence",
    )

    def __init__(self):
        self._gimbal_bias = 0.3
        self._vehicle_bias = 0.7
        self._confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Planning
    # --------------------------------------------------------------------------

    def apply(
        self,
        trajectory: Dict[str, Any],
        framing: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Compute coherent gimbal and vehicle adjustments.
        """
        desired_view = np.array(framing.get("desired_view", [0.0, 0.0]))
        current_view = np.array(framing.get("current_view", [0.0, 0.0]))
        error = desired_view - current_view

        vehicle_adjust = self._vehicle_bias * error
        gimbal_adjust = self._gimbal_bias * error

        self._confidence = float(
            np.clip(1.0 - np.linalg.norm(error), 0.0, 1.0)
        )

        return {
            "vehicle_view_adjustment": vehicle_adjust.tolist(),
            "gimbal_view_adjustment": gimbal_adjust.tolist(),
            "coherence_confidence": self._confidence,
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset planner state.
        """
        self._confidence = 0.0


