# CHUNK 86 X 93 — REAL-TIME CONSTRAINT SATISFACTION LAYER
# ==============================================================================
#
# Purpose:
#   Enforce physical, safety, ethical, and cinematic constraints
#   continuously during execution — resolving conflicts smoothly
#   instead of reacting after violations occur.
#
# Backbone truth:
#   Constraints are guidance, not brakes.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class RealTimeConstraintSatisfactionLayer:
    """
    Real-time constraint satisfaction layer.
    Softly enforces multiple competing constraints by projecting
    desired actions back into the feasible manifold at control rate.
    """

    __slots__ = (
        "_violation",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.93):
        self._inertia = float(np.clip(inertia, 0.85, 0.99))
        self._violation: float = 0.0


    # --------------------------------------------------------------------------
    # Constraint projection
    # --------------------------------------------------------------------------

    def _project(
        self,
        desired: Dict[str, Any],
        limits: Dict[str, Any],
    ) -> Dict[str, Any]:
        projected = {}

        for k, v in desired.items():
            if k in limits:
                lo, hi = limits[k]
                projected[k] = float(np.clip(v, lo, hi))
            else:
                projected[k] = v

        return projected


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        desired_action: Dict[str, Any],
        constraints: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Apply constraints to desired action.
        """
        limits = constraints.get("limits", {})
        projected = self._project(desired_action, limits)

        # Estimate violation magnitude
        violation = 0.0
        for k, v in desired_action.items():
            if k in projected:
                violation += abs(v - projected[k])

        self._violation = (
            self._violation * self._inertia
            + violation * (1.0 - self._inertia)
        )

        return {
            "constrained_action": projected,
            "constraint_violation": self._violation,
            "constraint_active": self._violation > 0.01,
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset constraint satisfaction state.
        """
        self._violation = 0.0


