# CHUNK 86 X 94 — SAFETY-WEIGHTED TRAJECTORY REGULATOR
# ==============================================================================
#
# Purpose:
#   Regulate cinematic trajectories by dynamically reweighting
#   intent, elegance, and motion authority against real-time
#   safety, ethics, and uncertainty signals.
#
# Backbone truth:
#   Style yields to safety — but never collapses.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class SafetyWeightedTrajectoryRegulator:
    """
    Safety-weighted trajectory regulator.
    Softly attenuates trajectory aggressiveness based on evolving
    risk signals, preserving continuity while preventing escalation.
    """

    __slots__ = (
        "_authority_scale",
        "_inertia",
    )

    def __init__(self, inertia: float = 0.92):
        self._inertia = float(np.clip(inertia, 0.85, 0.99))
        self._authority_scale: float = 1.0


    # --------------------------------------------------------------------------
    # Regulation
    # --------------------------------------------------------------------------

    def apply(
        self,
        trajectory: Dict[str, Any],
        risk: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Regulate trajectory authority based on safety context.
        """
        risk_level = float(risk.get("level", 0.0))
        ethics = float(risk.get("ethics", 0.0))
        uncertainty = float(risk.get("uncertainty", 0.0))

        target_scale = float(
            np.clip(
                1.0
                - 0.6 * risk_level
                - 0.4 * ethics
                - 0.3 * uncertainty,
                0.1,
                1.0,
            )
        )

        self._authority_scale = (
            self._authority_scale * self._inertia
            + target_scale * (1.0 - self._inertia)
        )

        regulated = []
        for p in trajectory.get("cinematic_trajectory", []):
            regulated.append({
                "t": p["t"],
                "position": p["position"],
                "velocity": (np.array(p["velocity"]) * self._authority_scale).tolist(),
            })

        return {
            "regulated_trajectory": regulated,
            "authority_scale": self._authority_scale,
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset trajectory regulation.
        """
        self._authority_scale = 1.0


