# CHUNK 86 X 95 — LOW-LEVEL CONTROL INTERFACE (MAVLINK / PWM BOUNDARY)
# ==============================================================================
#
# Purpose:
#   Define a strict, safe boundary between high-level cinematic
#   intent and low-level flight control by translating regulated
#   trajectories into controller-agnostic control intents.
#
# Backbone truth:
#   Abstraction prevents accidents.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class LowLevelControlInterface:
    """
    Low-level control interface.
    Converts regulated trajectories into normalized control intents
    (attitude / velocity / position targets) without exposing
    actuator-level commands.
    """

    __slots__ = (
        "_last_command",
        "_confidence",
    )

    def __init__(self):
        self._last_command: Dict[str, Any] = {}
        self._confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Translation
    # --------------------------------------------------------------------------

    def _trajectory_to_setpoint(
        self,
        point: Dict[str, Any],
        limits: Dict[str, float],
    ) -> Dict[str, float]:
        vel = np.array(point.get("velocity", [0.0, 0.0, 0.0]), dtype=float)

        max_v = float(limits.get("max_velocity", 5.0))
        vel = np.clip(vel, -max_v, max_v)

        return {
            "vx": float(vel[0]),
            "vy": float(vel[1]),
            "vz": float(vel[2]),
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        regulated: Dict[str, Any],
        limits: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Produce controller-agnostic control intent.
        """
        traj = regulated.get("regulated_trajectory", [])
        if not traj:
            return {}

        current = traj[0]
        setpoint = self._trajectory_to_setpoint(current, limits)

        self._last_command = {
            "mode": "velocity_target",
            "setpoint": setpoint,
            "timestamp": time.time(),
        }

        self._confidence = float(
            np.clip(
                1.0 - np.linalg.norm(list(setpoint.values())) / (limits.get("max_velocity", 5.0) + 1e-6),
                0.0,
                1.0,
            )
        )

        return {
            "control_intent": dict(self._last_command),
            "control_confidence": self._confidence,
        }


    def reset(self) -> None:
        """
        Reset low-level control intent.
        """
        self._last_command.clear()
        self._confidence = 0.0


