#   A good takeover feels invisible.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class HumanOverrideArbitrationCore:
    """
    Human override arbitration core.
    Blends human and AI authority using confidence, intent alignment,
    and temporal smoothing to prevent snaps, oscillation, or loss
    of situational awareness during handoff.
    """

    __slots__ = (
        "_human_weight",
        "_ai_weight",
        "_inertia",
        "_last_change",
    )

    def __init__(self, inertia: float = 0.90):
        self._inertia = float(np.clip(inertia, 0.85, 0.98))
        self._human_weight: float = 0.0
        self._ai_weight: float = 1.0
        self._last_change: float = 0.0


    # --------------------------------------------------------------------------
    # Arbitration
    # --------------------------------------------------------------------------

    def apply(
        self,
        human: Dict[str, Any],
        ai: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Blend authority between human and AI.
        """
        human_intent = float(human.get("intent_strength", 0.0))
        human_latency = float(human.get("latency", 0.0))
        ai_conf = float(ai.get("director_confidence", 0.5))
        safety = float(ai.get("public_safety", {}).get("priority", 0.0))

        # Target authority
        target_human = float(
            np.clip(
                human_intent * (1.0 - human_latency) * (1.0 - safety),
                0.0,
                1.0,
            )
        )
        target_ai = 1.0 - target_human

        # Smooth transition
        self._human_weight = (
            self._human_weight * self._inertia
            + target_human * (1.0 - self._inertia)
        )
        self._ai_weight = 1.0 - self._human_weight

        self._last_change = time.time()

        return {
            "authority_blend": {
                "human": self._human_weight,
                "ai": self._ai_weight,
            },
            "override_active": self._human_weight > 0.5,
            "handoff_stable": abs(self._human_weight - target_human) < 0.1,
            "timestamp": self._last_change,
        }


    def reset(self) -> None:
        """
        Reset authority arbitration.
        """
        self._human_weight = 0.0
        self._ai_weight = 1.0
        self._last_change = 0.0


