#   human and director AI, preventing micro-oscillation, authority
#   chatter, or gradual loss of control coherence.
#
# Backbone truth:
#   Authority must settle before action can be trusted.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class AuthorityHandoffStabilizer:
    """
    Authority handoff stabilizer.
    Introduces temporal damping, confidence gating, and intent
    consistency checks to ensure authority transitions converge
    cleanly instead of oscillating.
    """

    __slots__ = (
        "_stable_authority",
        "_dwell_time",
        "_last_transition",
    )

    def __init__(self, dwell_time: float = 1.2):
        self._dwell_time = float(np.clip(dwell_time, 0.5, 3.0))
        self._stable_authority: str = "ai"
        self._last_transition: float = 0.0


    # --------------------------------------------------------------------------
    # Stabilization
    # --------------------------------------------------------------------------

    def apply(
        self,
        arbitration: Dict[str, Any],
        intent_alignment: float,
    ) -> Dict[str, Any]:
        """
        Stabilize authority after arbitration.
        """
        now = time.time()
        human_w = float(arbitration.get("authority_blend", {}).get("human", 0.0))
        ai_w = float(arbitration.get("authority_blend", {}).get("ai", 1.0))

        desired = "human" if human_w > ai_w else "ai"

        # Intent consistency gate
        if intent_alignment < 0.3:
            desired = "ai"

        # Dwell enforcement
        if desired != self._stable_authority:
            if now - self._last_transition >= self._dwell_time:
                self._stable_authority = desired
                self._last_transition = now

        return {
            "stable_authority": self._stable_authority,
            "handoff_locked": now - self._last_transition < self._dwell_time,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset handoff stabilization.
        """
        self._stable_authority = "ai"
        self._last_transition = 0.0


