# ==============================================================================
#
# Purpose:
#   Provide a controlled, recoverable descent-and-hold behavior
#   when safety margins degrade but before full emergency state
#   escalation is required.
#
# Backbone truth:
#   Survival is bought with time.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class FailSafeDescentHoldLogic:
    """
    Fail-safe descent & hold logic.
    Executes a gentle, reversible descent combined with lateral
    stabilization and hover-hold, creating a temporal buffer for
    recovery, reconnection, or escalation decisions.
    """

    __slots__ = (
        "_active",
        "_descent_rate",
        "_confidence",
        "_start_time",
    )

    def __init__(self, descent_rate: float = 0.6):
        self._descent_rate = float(np.clip(descent_rate, 0.2, 1.2))
        self._active: bool = False
        self._confidence: float = 0.0
        self._start_time: float = 0.0


    # --------------------------------------------------------------------------
    # Activation
    # --------------------------------------------------------------------------

    def apply(
        self,
        metrics: Dict[str, Any],
        state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Apply fail-safe descent & hold behavior.
        """
        trigger = (
            metrics.get("link_degraded")
            or metrics.get("power_margin", 1.0) < 0.2
            or metrics.get("cognitive_divergence", {}).get("divergence_critical")
        )

        if not trigger:
            self._active = False
            self._confidence = 0.0
            return {}

        if not self._active:
            self._start_time = time.time()
            self._active = True

        altitude = float(state.get("altitude", 0.0))
        min_alt = float(metrics.get("min_safe_altitude", 2.0))

        vz = -self._descent_rate if altitude > min_alt else 0.0

        self._confidence = float(
            np.clip(
                1.0 - abs(vz) / (self._descent_rate + 1e-6),
                0.0,
                1.0,
            )
        )

        return {
            "failsafe_active": True,
            "failsafe_mode": "descent_hold",
            "velocity_override": {
                "vx": 0.0,
                "vy": 0.0,
                "vz": vz,
            },
            "hold_lateral": True,
            "confidence": self._confidence,
            "activated_at": self._start_time,
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset fail-safe logic.
        """
        self._active = False
        self._confidence = 0.0
        self._start_time = 0.0


