# CHUNK 86 X 99 — EMERGENCY STATE MACHINE
# ==============================================================================
#
# Purpose:
#   Unify all critical failure, hazard, and safety escalation paths
#   into a deterministic emergency state machine with clear entry,
#   persistence, recovery, and terminal behaviors.
#
# Backbone truth:
#   In crisis, ambiguity kills.
#
# ==============================================================================

from typing import Dict, Any
import time


class EmergencyStateMachine:
    """
    Emergency state machine.
    Governs escalation from degraded operation through controlled
    fail-safe behaviors to terminal emergency actions, ensuring
    predictable and survivable outcomes.
    """

    __slots__ = (
        "_state",
        "_entered_at",
    )

    STATES = (
        "normal",
        "degraded",
        "failsafe",
        "emergency",
        "terminal",
    )

    def __init__(self):
        self._state: str = "normal"
        self._entered_at: float = time.time()


    # --------------------------------------------------------------------------
    # Transition logic
    # --------------------------------------------------------------------------

    def _transition(self, new_state: str) -> None:
        if new_state != self._state:
            self._state = new_state
            self._entered_at = time.time()


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        """
        Update emergency state based on system metrics.
        """
        critical = bool(metrics.get("critical_failure"))
        failsafe = bool(metrics.get("failsafe_active"))
        degraded = bool(
            metrics.get("link_degraded")
            or metrics.get("power_margin", 1.0) < 0.35
            or metrics.get("cognitive_divergence", {}).get("divergence_warning")
        )

        # Escalation
        if critical:
            self._transition("emergency")
        elif failsafe:
            self._transition("failsafe")
        elif degraded:
            self._transition("degraded")
        else:
            self._transition("normal")

        # Terminal condition
        if (
            self._state == "emergency"
            and metrics.get("recovery_possible") is False
        ):
            self._transition("terminal")

        return {
            "emergency_state": self._state,
            "entered_at": self._entered_at,
            "time_in_state": time.time() - self._entered_at,
            "is_terminal": self._state == "terminal",
        }


    def reset(self) -> None:
        """
        Reset emergency state machine.
        """
        self._state = "normal"
        self._entered_at = time.time()


