from typing import Dict, Any
import numpy as np
import time


class MissionLevelSupervisorCore:
    """
    Mission-level supervisor core.
    Maintains mission coherence by arbitrating between intent,
    progress, safety, and resource constraints, issuing corrective
    guidance long before failure conditions arise.
    """

    __slots__ = (
        "_mission_state",
        "_confidence",
        "_started_at",
    )

    def __init__(self):
        self._mission_state: str = "initializing"
        self._confidence: float = 0.0
        self._started_at: float = time.time()


    # --------------------------------------------------------------------------
    # State evaluation
    # --------------------------------------------------------------------------

    def _evaluate_state(self, metrics: Dict[str, Any]) -> str:
        if metrics.get("emergency_state") == "terminal":
            return "aborted"

        if metrics.get("mission_complete"):
            return "completed"

        if metrics.get("emergency_state") in ("emergency", "failsafe"):
            return "recovering"

        if metrics.get("progress", 0.0) < 0.1:
            return "executing"

        if metrics.get("anticipated_risk", {}).get("level", 0.0) > 0.6:
            return "high_risk_execution"

        return "executing"


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, metrics: Dict[str, Any]) -> Dict[str, Any]:
        """
        Update mission-level supervision.
        """
        new_state = self._evaluate_state(metrics)
        self._mission_state = new_state

        quality = float(metrics.get("average_quality", 0.5))
        safety = float(metrics.get("public_safety", {}).get("priority", 0.0))
        risk = float(metrics.get("anticipated_risk", {}).get("level", 0.0))

        self._confidence = float(
            np.clip(
                0.6 * quality - 0.5 * risk - 0.4 * safety,
                0.0,
                1.0,
            )
        )

        return {
            "mission_state": self._mission_state,
            "mission_confidence": self._confidence,
            "mission_duration": time.time() - self._started_at,
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset mission supervision state.
        """
        self._mission_state = "initializing"
        self._confidence = 0.0
        self._started_at = time.time()


