from typing import Dict, Any, List
import numpy as np
import time


class CrossMissionSafetyGovernor:
    """
    Cross-mission safety governor.
    Aggregates historical incidents, near-misses, and policy signals
    to continuously shape mission authority, operational envelopes,
    and escalation thresholds across flights.
    """

    __slots__ = (
        "_risk_memory",
        "_decay",
        "_last_update",
    )

    def __init__(self, decay: float = 0.985):
        self._decay = float(np.clip(decay, 0.95, 0.999))
        self._risk_memory: Dict[str, float] = {}
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Risk aggregation
    # --------------------------------------------------------------------------

    def _update_risk(
        self,
        key: str,
        magnitude: float,
    ) -> None:
        prev = self._risk_memory.get(key, 0.0)
        self._risk_memory[key] = float(
            np.clip(
                prev * self._decay + magnitude * (1.0 - self._decay),
                0.0,
                1.0,
            )
        )


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        mission_metrics: Dict[str, Any],
        incident_reports: List[Dict[str, Any]],
    ) -> Dict[str, Any]:
        """
        Update cross-mission safety governance.
        """
        now = time.time()

        for inc in incident_reports:
            self._update_risk(
                inc.get("type", "unknown"),
                float(inc.get("severity", 0.0)),
            )

        location_risk = self._risk_memory.get(
            mission_metrics.get("area_id", "global"),
            0.0,
        )

        authority_limit = float(
            np.clip(
                1.0 - 0.7 * location_risk,
                0.2,
                1.0,
            )
        )

        self._last_update = now

        return {
            "cross_mission_risk": dict(self._risk_memory),
            "authority_limit": authority_limit,
            "last_update": self._last_update,
        }


    def reset(self) -> None:
        """
        Reset cross-mission safety memory.
        """
        self._risk_memory.clear()
        self._last_update = time.time()


