from typing import Dict, Any, List
import numpy as np
import time


class FleetWideIncidentIntelligenceLayer:
    """
    Fleet-wide incident intelligence layer.
    Aggregates, normalizes, and propagates incident intelligence
    across all operational nodes, converting raw events into
    predictive safety priors and policy signals.
    """

    __slots__ = (
        "_incident_memory",
        "_severity_decay",
        "_last_sync",
    )

    def __init__(self, severity_decay: float = 0.97):
        self._severity_decay = float(np.clip(severity_decay, 0.9, 0.995))
        self._incident_memory: Dict[str, float] = {}
        self._last_sync: float = time.time()


    # --------------------------------------------------------------------------
    # Intelligence synthesis
    # --------------------------------------------------------------------------

    def _encode_incident(self, inc: Dict[str, Any]) -> str:
        return (
            f"{inc.get('type','unknown')}:"
            f"{inc.get('context','global')}"
        )


    def _accumulate(self, key: str, severity: float) -> None:
        prev = self._incident_memory.get(key, 0.0)
        self._incident_memory[key] = float(
            np.clip(
                prev * self._severity_decay
                + severity * (1.0 - self._severity_decay),
                0.0,
                1.0,
            )
        )


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        incidents: List[Dict[str, Any]],
        fleet_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update fleet-wide incident intelligence.
        """
        for inc in incidents:
            key = self._encode_incident(inc)
            self._accumulate(
                key,
                float(inc.get("severity", 0.0)),
            )

        # Predictive risk prior
        active_region = fleet_state.get("operational_region", "global")
        regional_risk = max(
            v for k, v in self._incident_memory.items()
            if active_region in k
        ) if self._incident_memory else 0.0

        self._last_sync = time.time()

        return {
            "fleet_incident_intelligence": dict(self._incident_memory),
            "regional_risk_prior": float(regional_risk),
            "last_sync": self._last_sync,
        }


    def reset(self) -> None:
        """
        Reset fleet-wide intelligence.
        """
        self._incident_memory.clear()
        self._last_sync = time.time()


