from typing import Dict, Any
import numpy as np
import time


class CloudEdgeMissionArbitrationBus:
    """
    Cloud–edge mission arbitration bus.
    Blends cloud-provided guidance with edge-resident autonomy using
    latency-aware confidence weighting and failover semantics.
    """

    __slots__ = (
        "_edge_weight",
        "_cloud_weight",
        "_latency_budget",
        "_last_sync",
    )

    def __init__(self, latency_budget_ms: float = 250.0):
        self._latency_budget = float(np.clip(latency_budget_ms, 50.0, 1500.0))
        self._edge_weight: float = 1.0
        self._cloud_weight: float = 0.0
        self._last_sync: float = 0.0


    # --------------------------------------------------------------------------
    # Arbitration
    # --------------------------------------------------------------------------

    def apply(
        self,
        edge: Dict[str, Any],
        cloud: Dict[str, Any],
        link: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Arbitrate mission authority between edge and cloud.
        """
        latency = float(link.get("rtt_ms", 9999.0))
        link_quality = float(link.get("quality", 0.0))
        cloud_conf = float(cloud.get("confidence", 0.0))
        edge_conf = float(edge.get("confidence", 1.0))

        # Latency-aware blending
        cloud_viable = latency <= self._latency_budget and link_quality > 0.3

        target_cloud = float(
            np.clip(
                cloud_conf * link_quality if cloud_viable else 0.0,
                0.0,
                1.0,
            )
        )
        target_edge = 1.0 - target_cloud

        # Smooth authority
        alpha = 0.15
        self._cloud_weight = (
            (1.0 - alpha) * self._cloud_weight + alpha * target_cloud
        )
        self._edge_weight = 1.0 - self._cloud_weight

        self._last_sync = time.time()

        return {
            "mission_authority": {
                "edge": self._edge_weight,
                "cloud": self._cloud_weight,
            },
            "effective_intent": edge.get("intent")
                if self._edge_weight >= self._cloud_weight
                else cloud.get("intent"),
            "last_sync": self._last_sync,
        }


    def reset(self) -> None:
        """
        Reset arbitration bus.
        """
        self._edge_weight = 1.0
        self._cloud_weight = 0.0
        self._last_sync = 0.0


