from typing import Dict, Any
import time


class DirectorCloudCognitiveBridge:
    """
    Director AI ↔ cloud cognitive bridge.
    Manages prompt construction, context grounding, response
    validation, and confidence estimation when interacting with
    large-scale cloud reasoning models.
    """

    __slots__ = (
        "_last_query",
        "_last_response",
        "_confidence",
        "_last_sync",
    )

    def __init__(self):
        self._last_query: Dict[str, Any] = {}
        self._last_response: Dict[str, Any] = {}
        self._confidence: float = 0.0
        self._last_sync: float = 0.0


    # --------------------------------------------------------------------------
    # Prompt grounding
    # --------------------------------------------------------------------------

    def _build_prompt(
        self,
        intent: Dict[str, Any],
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        return {
            "system_role": "cinematic_director_ai",
            "intent_summary": intent,
            "environment": context.get("environment"),
            "constraints": context.get("constraints"),
            "safety_policy": context.get("safety_policy"),
        }


    # --------------------------------------------------------------------------
    # Validation
    # --------------------------------------------------------------------------

    def _validate_response(self, response: Dict[str, Any]) -> bool:
        return (
            "action_plan" in response
            and "confidence" in response
            and response.get("confidence", 0.0) > 0.2
        )


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        intent: Dict[str, Any],
        context: Dict[str, Any],
        cloud_response: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Process cloud cognitive response into grounded director input.
        """
        self._last_query = self._build_prompt(intent, context)

        if not self._validate_response(cloud_response):
            self._confidence = 0.0
            return {
                "bridge_valid": False,
                "reason": "invalid_or_low_confidence_response",
                "timestamp": time.time(),
            }

        self._last_response = cloud_response
        self._confidence = float(cloud_response.get("confidence", 0.0))
        self._last_sync = time.time()

        return {
            "bridge_valid": True,
            "grounded_action_plan": cloud_response.get("action_plan"),
            "bridge_confidence": self._confidence,
            "timestamp": self._last_sync,
        }


    def reset(self) -> None:
        """
        Reset cognitive bridge state.
        """
        self._last_query.clear()
        self._last_response.clear()
        self._confidence = 0.0
        self._last_sync = 0.0


