class NaturalLanguageMissionCompiler:
    """
    Natural-language mission compiler.
    Transforms free-form user language into a probabilistic mission
    graph composed of goals, constraints, stylistic modifiers, and
    uncertainty annotations — without relying on rigid templates.
    """

    __slots__ = (
        "_last_input",
        "_compiled_mission",
        "_confidence",
    )

    def __init__(self):
        self._last_input: str = ""
        self._compiled_mission: Dict[str, Any] = {}
        self._confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Compilation primitives
    # --------------------------------------------------------------------------

    def _extract_goals(self, semantic: Dict[str, Any]) -> List[Dict[str, Any]]:
        return semantic.get("goals", [])


    def _extract_constraints(self, semantic: Dict[str, Any]) -> Dict[str, Any]:
        return semantic.get("constraints", {})


    def _extract_style(self, semantic: Dict[str, Any]) -> Dict[str, Any]:
        return semantic.get("style", {})


    def _estimate_uncertainty(self, semantic: Dict[str, Any]) -> float:
        ambiguity = float(semantic.get("ambiguity", 0.0))
        confidence = float(semantic.get("semantic_confidence", 0.5))
        return float(np.clip(1.0 - confidence + ambiguity, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        user_text: str,
        semantic_parse: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Compile user language into mission structure.
        """
        self._last_input = user_text

        goals = self._extract_goals(semantic_parse)
        constraints = self._extract_constraints(semantic_parse)
        style = self._extract_style(semantic_parse)

        uncertainty = self._estimate_uncertainty(semantic_parse)

        self._compiled_mission = {
            "goals": goals,
            "constraints": constraints,
            "style": style,
            "uncertainty": uncertainty,
            "compiled_at": time.time(),
        }

        self._confidence = float(
            np.clip(
                1.0 - uncertainty,
                0.0,
                1.0,
            )
        )

        return {
            "compiled_mission": dict(self._compiled_mission),
            "compiler_confidence": self._confidence,
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset mission compiler state.
        """
        self._last_input = ""
        self._compiled_mission.clear()
        self._confidence = 0.0


