# CHUNK 86 Z 03 — SEMANTIC INTENT VALIDATION & GROUNDING
# ==============================================================================
#
# Purpose:
#   Validate and ground compiled semantic intent against physical,
#   legal, safety, and cinematic feasibility before any execution,
#   preventing impossible, unsafe, or incoherent missions.
#
# Backbone truth:
#   Understanding without grounding is hallucination.
#
# ==============================================================================

from typing import Dict, Any, List
import numpy as np
import time


class SemanticIntentValidationGrounding:
    """
    Semantic intent validation & grounding.
    Ensures that language-compiled mission intent is compatible with
    real-world constraints, cinematic logic, and ethical boundaries.
    """

    __slots__ = (
        "_last_validation",
        "_confidence",
        "_failure_reasons",
    )

    def __init__(self):
        self._last_validation: Dict[str, Any] = {}
        self._confidence: float = 0.0
        self._failure_reasons: List[str] = []


    # --------------------------------------------------------------------------
    # Validation primitives
    # --------------------------------------------------------------------------

    def _validate_physics(self, mission: Dict[str, Any], state: Dict[str, Any]) -> bool:
        max_speed = float(state.get("max_speed", 10.0))
        for g in mission.get("goals", []):
            if g.get("required_speed", 0.0) > max_speed:
                self._failure_reasons.append("physics_speed_exceeded")
                return False
        return True


    def _validate_safety(self, mission: Dict[str, Any], safety: Dict[str, Any]) -> bool:
        if safety.get("no_fly"):
            self._failure_reasons.append("restricted_airspace")
            return False
        if mission.get("style", {}).get("aggressive") and safety.get("crowd_density", 0.0) > 0.3:
            self._failure_reasons.append("unsafe_aggressive_style")
            return False
        return True


    def _validate_legality(self, mission: Dict[str, Any], regulations: Dict[str, Any]) -> bool:
        if regulations.get("requires_vlos") and not mission.get("constraints", {}).get("vlos"):
            self._failure_reasons.append("vlos_violation")
            return False
        return True


    def _validate_cinematic_logic(self, mission: Dict[str, Any]) -> bool:
        goals = mission.get("goals", [])
        if not goals:
            self._failure_reasons.append("no_cinematic_goal")
            return False
        return True


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        compiled_mission: Dict[str, Any],
        world_state: Dict[str, Any],
        safety_context: Dict[str, Any],
        regulations: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Validate and ground semantic mission intent.
        """
        self._failure_reasons.clear()

        ok = (
            self._validate_physics(compiled_mission, world_state)
            and self._validate_safety(compiled_mission, safety_context)
            and self._validate_legality(compiled_mission, regulations)
            and self._validate_cinematic_logic(compiled_mission)
        )

        self._confidence = float(
            np.clip(
                1.0 - 0.25 * len(self._failure_reasons),
                0.0,
                1.0,
            )
        )

        self._last_validation = {
            "valid": ok,
            "confidence": self._confidence,
            "failures": list(self._failure_reasons),
            "timestamp": time.time(),
        }

        return dict(self._last_validation)


    def reset(self) -> None:
        """
        Reset validation state.
        """
        self._last_validation.clear()
        self._failure_reasons.clear()
        self._confidence = 0.0


