from typing import Dict, Any, List
import numpy as np
import time


class ConversationalMemoryDialogueState:
    """
    Conversational memory & dialogue state.
    Stores distilled conversational state rather than raw transcripts,
    enabling long-horizon coherence, clarification, and intent repair.
    """

    __slots__ = (
        "_dialogue_state",
        "_memory",
        "_salience_decay",
        "_last_update",
    )

    def __init__(self, salience_decay: float = 0.96):
        self._salience_decay = float(np.clip(salience_decay, 0.9, 0.995))
        self._dialogue_state: Dict[str, Any] = {}
        self._memory: List[Dict[str, Any]] = []
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Memory primitives
    # --------------------------------------------------------------------------

    def _decay_memory(self) -> None:
        for m in self._memory:
            m["salience"] *= self._salience_decay


    def _prune(self, threshold: float = 0.05) -> None:
        self._memory = [m for m in self._memory if m["salience"] >= threshold]


    def _integrate_turn(self, turn: Dict[str, Any]) -> None:
        self._memory.append({
            "content": turn,
            "salience": float(turn.get("salience", 0.5)),
            "timestamp": time.time(),
        })


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        turn: Dict[str, Any],
        resolved_intent: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update conversational memory with a new dialogue turn.
        """
        self._decay_memory()
        self._integrate_turn(turn)
        self._prune()

        # Update dialogue state
        self._dialogue_state.update({
            "last_user_goal": resolved_intent.get("primary_goal"),
            "style_preferences": resolved_intent.get("style"),
            "open_questions": resolved_intent.get("open_questions", []),
        })

        self._last_update = time.time()

        return {
            "dialogue_state": dict(self._dialogue_state),
            "memory_size": len(self._memory),
            "last_update": self._last_update,
        }


    def reset(self) -> None:
        """
        Reset conversational memory and state.
        """
        self._dialogue_state.clear()
        self._memory.clear()
        self._last_update = time.time()


