# CHUNK 86 Z 05 — AMBIGUITY RESOLUTION & CLARIFICATION ENGINE
# ==============================================================================
#
# Purpose:
#   Decide—per intent fragment—whether ambiguity should be inferred,
#   clarified, deferred, or rejected, preserving cinematic momentum
#   while preventing unsafe or incoherent execution.
#
# Backbone truth:
#   Great directors clarify only when silence would be worse.
#
# ==============================================================================

from typing import Dict, Any, List
import numpy as np
import time


class AmbiguityResolutionClarificationEngine:
    """
    Ambiguity resolution & clarification engine.
    Evaluates semantic uncertainty, risk, and narrative continuity
    to determine the minimal intervention strategy required to
    safely and coherently proceed.
    """

    __slots__ = (
        "_threshold_infer",
        "_threshold_clarify",
        "_threshold_reject",
        "_last_decision",
    )

    def __init__(
        self,
        infer_threshold: float = 0.25,
        clarify_threshold: float = 0.55,
        reject_threshold: float = 0.80,
    ):
        self._threshold_infer = float(np.clip(infer_threshold, 0.1, 0.4))
        self._threshold_clarify = float(np.clip(clarify_threshold, 0.4, 0.7))
        self._threshold_reject = float(np.clip(reject_threshold, 0.7, 0.95))
        self._last_decision: Dict[str, Any] = {}


    # --------------------------------------------------------------------------
    # Decision logic
    # --------------------------------------------------------------------------

    def _classify(
        self,
        uncertainty: float,
        risk: float,
        narrative_importance: float,
    ) -> str:
        score = (
            0.5 * uncertainty
            + 0.3 * risk
            + 0.2 * narrative_importance
        )

        if score < self._threshold_infer:
            return "infer"

        if score < self._threshold_clarify:
            return "clarify"

        if score < self._threshold_reject:
            return "defer"

        return "reject"


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        compiled_mission: Dict[str, Any],
        validation: Dict[str, Any],
        narrative_context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Resolve ambiguity strategy for current mission.
        """
        uncertainty = float(compiled_mission.get("uncertainty", 0.0))
        risk = float(narrative_context.get("risk_level", 0.0))
        importance = float(narrative_context.get("importance", 0.5))

        decision = self._classify(uncertainty, risk, importance)

        self._last_decision = {
            "strategy": decision,
            "uncertainty": uncertainty,
            "risk": risk,
            "importance": importance,
            "timestamp": time.time(),
        }

        response: Dict[str, Any] = {
            "ambiguity_strategy": decision,
            "timestamp": self._last_decision["timestamp"],
        }

        if decision == "clarify":
            response["clarification_prompt"] = (
                "Could you clarify your intent so I can execute this safely?"
            )

        if decision == "reject":
            response["rejection_reason"] = (
                "The request is too ambiguous or risky to proceed."
            )

        return response


    def reset(self) -> None:
        """
        Reset ambiguity resolution state.
        """
        self._last_decision.clear()


