# CHUNK 86 Z 06 — INTENT CONFIDENCE CALIBRATION LOOP
# ==============================================================================
#
# Purpose:
#   Continuously calibrate the Director AI’s confidence in its
#   interpreted intent by reconciling language certainty, grounding
#   validation, execution feedback, and temporal consistency.
#
# Backbone truth:
#   Confidence must be earned every frame.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class IntentConfidenceCalibrationLoop:
    """
    Intent confidence calibration loop.
    Dynamically adjusts confidence estimates to avoid overcommitment
    under ambiguity and underutilization under clarity, maintaining
    epistemic humility across time.
    """

    __slots__ = (
        "_confidence",
        "_inertia",
        "_history",
        "_last_update",
    )

    def __init__(self, inertia: float = 0.88):
        self._inertia = float(np.clip(inertia, 0.75, 0.97))
        self._confidence: float = 0.0
        self._history: Dict[str, float] = {}
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Calibration primitives
    # --------------------------------------------------------------------------

    def _score_language(self, semantic: Dict[str, Any]) -> float:
        return float(np.clip(semantic.get("semantic_confidence", 0.5), 0.0, 1.0))


    def _score_grounding(self, validation: Dict[str, Any]) -> float:
        return float(validation.get("confidence", 0.0))


    def _score_execution(self, feedback: Dict[str, Any]) -> float:
        return float(np.clip(feedback.get("execution_success", 0.5), 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        semantic: Dict[str, Any],
        validation: Dict[str, Any],
        execution_feedback: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Calibrate intent confidence using multi-source evidence.
        """
        lang = self._score_language(semantic)
        ground = self._score_grounding(validation)
        execu = self._score_execution(execution_feedback)

        target = float(
            np.clip(
                0.45 * lang + 0.35 * ground + 0.20 * execu,
                0.0,
                1.0,
            )
        )

        self._confidence = (
            self._confidence * self._inertia
            + target * (1.0 - self._inertia)
        )

        self._history = {
            "language": lang,
            "grounding": ground,
            "execution": execu,
        }

        self._last_update = time.time()

        return {
            "intent_confidence": self._confidence,
            "confidence_sources": dict(self._history),
            "timestamp": self._last_update,
        }


    def reset(self) -> None:
        """
        Reset confidence calibration.
        """
        self._confidence = 0.0
        self._history.clear()
        self._last_update = time.time()


