from typing import Dict, Any
import numpy as np
import time


class HumanPreferenceLearningCore:
    """
    Human preference learning core.
    Infers stylistic bias from implicit feedback signals such as
    manual overrides, corrections, dwell time, re-recording, and
    acceptance patterns — converging on a personalized cinematic style.
    """

    __slots__ = (
        "_preference_model",
        "_learning_rate",
        "_confidence",
        "_last_update",
    )

    def __init__(self, learning_rate: float = 0.08):
        self._learning_rate = float(np.clip(learning_rate, 0.01, 0.2))
        self._preference_model: Dict[str, float] = {
            "motion_energy": 0.5,
            "shot_distance": 0.5,
            "camera_aggressiveness": 0.5,
            "color_intensity": 0.5,
            "tempo": 0.5,
        }
        self._confidence: float = 0.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Learning primitives
    # --------------------------------------------------------------------------

    def _update_axis(self, key: str, delta: float) -> None:
        prev = self._preference_model.get(key, 0.5)
        self._preference_model[key] = float(
            np.clip(
                prev + self._learning_rate * delta,
                0.0,
                1.0,
            )
        )


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        feedback: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update human preference model using implicit feedback.
        """
        # Interpret feedback deltas
        for axis, signal in feedback.get("style_feedback", {}).items():
            delta = float(np.clip(signal, -1.0, 1.0))
            self._update_axis(axis, delta)

        acceptance = float(feedback.get("acceptance", 0.5))
        correction = float(feedback.get("manual_corrections", 0.0))

        self._confidence = float(
            np.clip(
                acceptance - 0.5 * correction,
                0.0,
                1.0,
            )
        )

        self._last_update = time.time()

        return {
            "learned_preferences": dict(self._preference_model),
            "preference_confidence": self._confidence,
            "timestamp": self._last_update,
        }


    def reset(self) -> None:
        """
        Reset learned preferences.
        """
        for k in self._preference_model:
            self._preference_model[k] = 0.5
        self._confidence = 0.0
        self._last_update = time.time()


