# CHUNK 86 Z 08 — LONG-HORIZON INTENT DRIFT MONITOR
# ==============================================================================
#
# Purpose:
#   Detect, quantify, and correct slow intent drift across long
#   horizons—missions, sessions, and environmental changes—without
#   abrupt resets or loss of cinematic continuity.
#
# Backbone truth:
#   Drift is dangerous precisely because it feels smooth.
#
# ==============================================================================

from typing import Dict, Any, Deque
from collections import deque
import numpy as np
import time


class LongHorizonIntentDriftMonitor:
    """
    Long-horizon intent drift monitor.
    Tracks intent embeddings and execution outcomes over extended
    windows, estimating gradual divergence and issuing corrective
    bias rather than hard intervention.
    """

    __slots__ = (
        "_intent_history",
        "_window",
        "_drift_level",
        "_last_update",
    )

    def __init__(self, window: int = 64):
        self._window = int(np.clip(window, 16, 256))
        self._intent_history: Deque[np.ndarray] = deque(maxlen=self._window)
        self._drift_level: float = 0.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Drift estimation
    # --------------------------------------------------------------------------

    def _estimate_drift(self) -> float:
        if len(self._intent_history) < 4:
            return 0.0

        base = self._intent_history[0]
        tail = self._intent_history[-1]

        dist = float(np.linalg.norm(tail - base))
        norm = float(np.linalg.norm(base) + 1e-6)

        return float(np.clip(dist / norm, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        intent_embedding: np.ndarray,
        execution_quality: float,
    ) -> Dict[str, Any]:
        """
        Update drift monitor with new intent observation.
        """
        self._intent_history.append(
            np.asarray(intent_embedding, dtype=float)
        )

        raw_drift = self._estimate_drift()

        # Execution quality modulates severity
        adjusted = raw_drift * (1.0 - float(np.clip(execution_quality, 0.0, 1.0)))

        # Temporal smoothing
        self._drift_level = (
            0.9 * self._drift_level + 0.1 * adjusted
        )

        self._last_update = time.time()

        return {
            "intent_drift": self._drift_level,
            "drift_raw": raw_drift,
            "window_size": len(self._intent_history),
            "timestamp": self._last_update,
        }


    def reset(self) -> None:
        """
        Reset drift monitoring.
        """
        self._intent_history.clear()
        self._drift_level = 0.0
        self._last_update = time.time()


