# CHUNK 86 Z 09 — CINEMATIC PERSONALITY & STYLE MODEL
# ==============================================================================
#
# Purpose:
#   Synthesize learned human preferences, narrative tendencies,
#   emotional pacing biases, and visual aesthetics into a coherent,
#   persistent cinematic personality that guides all future decisions.
#
# Backbone truth:
#   Style is not a setting — it is behavior over time.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CinematicPersonalityStyleModel:
    """
    Cinematic personality & style model.
    Encapsulates a director-like identity that shapes framing,
    motion grammar, emotional pacing, and aesthetic bias across
    missions while remaining adaptive to context and feedback.
    """

    __slots__ = (
        "_style_vector",
        "_identity_strength",
        "_last_update",
    )

    def __init__(self):
        # Core stylistic axes normalized [0,1]
        self._style_vector: Dict[str, float] = {
            "intimacy": 0.5,          # close vs distant framing
            "kinetic_energy": 0.5,    # calm vs dynamic motion
            "emotional_contrast": 0.5,# restrained vs expressive
            "visual_risk": 0.5,       # conservative vs bold shots
            "tempo": 0.5,             # slow burn vs rapid pacing
        }
        self._identity_strength: float = 0.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Integration primitives
    # --------------------------------------------------------------------------

    def _blend(self, key: str, target: float, alpha: float) -> None:
        prev = self._style_vector.get(key, 0.5)
        self._style_vector[key] = float(
            np.clip(
                prev * (1.0 - alpha) + target * alpha,
                0.0,
                1.0,
            )
        )


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        learned_preferences: Dict[str, float],
        narrative_bias: Dict[str, float],
        drift_signal: float,
    ) -> Dict[str, Any]:
        """
        Update cinematic personality using preferences, narrative bias,
        and long-horizon drift correction.
        """
        alpha = float(np.clip(0.15 * (1.0 - drift_signal), 0.05, 0.25))

        # Map learned preferences into personality axes
        mapping = {
            "motion_energy": "kinetic_energy",
            "shot_distance": "intimacy",
            "camera_aggressiveness": "visual_risk",
            "tempo": "tempo",
            "color_intensity": "emotional_contrast",
        }

        for pref, axis in mapping.items():
            if pref in learned_preferences:
                self._blend(axis, learned_preferences[pref], alpha)

        # Narrative bias nudges (acts, genre, emotional arc)
        for axis, bias in narrative_bias.items():
            if axis in self._style_vector:
                self._blend(axis, bias, 0.05)

        # Identity strength increases as drift decreases
        self._identity_strength = float(
            np.clip(1.0 - drift_signal, 0.0, 1.0)
        )

        self._last_update = time.time()

        return {
            "cinematic_personality": dict(self._style_vector),
            "identity_strength": self._identity_strength,
            "timestamp": self._last_update,
        }


    def reset(self) -> None:
        """
        Reset cinematic personality.
        """
        for k in self._style_vector:
            self._style_vector[k] = 0.5
        self._identity_strength = 0.0
        self._last_update = time.time()


