from typing import Dict, Any
import json
import time
import hashlib


class DirectorIdentityPersistenceLayer:
    """
    Director identity persistence layer.
    Provides versioned, checksummed persistence for cinematic identity
    state, enabling safe restoration, migration, and synchronization
    across environments.
    """

    __slots__ = (
        "_identity_state",
        "_version",
        "_checksum",
        "_last_saved",
    )

    def __init__(self, version: str = "1.0"):
        self._version = version
        self._identity_state: Dict[str, Any] = {}
        self._checksum: str = ""
        self._last_saved: float = 0.0


    # --------------------------------------------------------------------------
    # Persistence primitives
    # --------------------------------------------------------------------------

    def _compute_checksum(self, payload: Dict[str, Any]) -> str:
        blob = json.dumps(payload, sort_keys=True).encode("utf-8")
        return hashlib.sha256(blob).hexdigest()


    # --------------------------------------------------------------------------
    # Save / Load
    # --------------------------------------------------------------------------

    def save(self, state: Dict[str, Any]) -> Dict[str, Any]:
        """
        Persist director identity state.
        """
        self._identity_state = dict(state)
        self._checksum = self._compute_checksum(self._identity_state)
        self._last_saved = time.time()

        return {
            "saved": True,
            "version": self._version,
            "checksum": self._checksum,
            "timestamp": self._last_saved,
        }


    def load(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        """
        Load and validate director identity state.
        """
        checksum = self._compute_checksum(payload)

        if checksum != payload.get("checksum"):
            return {
                "loaded": False,
                "reason": "checksum_mismatch",
            }

        self._identity_state = dict(payload.get("state", {}))
        self._checksum = checksum
        self._last_saved = time.time()

        return {
            "loaded": True,
            "version": self._version,
            "timestamp": self._last_saved,
        }


    def export(self) -> Dict[str, Any]:
        """
        Export identity payload for synchronization.
        """
        return {
            "version": self._version,
            "state": dict(self._identity_state),
            "checksum": self._checksum,
            "timestamp": self._last_saved,
        }


    def reset(self) -> None:
        """
        Reset identity persistence layer.
        """
        self._identity_state.clear()
        self._checksum = ""
        self._last_saved = time.time()


