from typing import Dict, Any
import time


class CrossSessionCognitiveContinuityBus:
    """
    Cross-session cognitive continuity bus.
    Aggregates identity state, dialogue context, active intent,
    narrative phase, and confidence baselines into a resumable
    cognitive snapshot that can be restored deterministically.
    """

    __slots__ = (
        "_snapshot",
        "_last_checkpoint",
    )

    def __init__(self):
        self._snapshot: Dict[str, Any] = {}
        self._last_checkpoint: float = 0.0


    # --------------------------------------------------------------------------
    # Snapshot construction
    # --------------------------------------------------------------------------

    def checkpoint(
        self,
        identity: Dict[str, Any],
        dialogue: Dict[str, Any],
        intent: Dict[str, Any],
        narrative: Dict[str, Any],
        confidence: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Create a cognitive continuity snapshot.
        """
        self._snapshot = {
            "identity": dict(identity),
            "dialogue_state": dict(dialogue),
            "active_intent": dict(intent),
            "narrative_context": dict(narrative),
            "confidence_state": dict(confidence),
            "timestamp": time.time(),
        }

        self._last_checkpoint = self._snapshot["timestamp"]

        return {
            "checkpointed": True,
            "timestamp": self._last_checkpoint,
        }


    # --------------------------------------------------------------------------
    # Restore
    # --------------------------------------------------------------------------

    def restore(self) -> Dict[str, Any]:
        """
        Restore last cognitive snapshot.
        """
        if not self._snapshot:
            return {
                "restored": False,
                "reason": "no_snapshot_available",
            }

        return {
            "restored": True,
            "snapshot": dict(self._snapshot),
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Reset continuity bus.
        """
        self._snapshot.clear()
        self._last_checkpoint = time.time()


