from typing import Dict, Any
import time
import numpy as np


class MultiDeviceIdentitySynchronization:
    """
    Multi-device identity synchronization.
    Resolves identity updates from multiple endpoints using confidence-
    weighted merging, temporal precedence, and integrity validation.
    """

    __slots__ = (
        "_merged_state",
        "_last_sync",
    )

    def __init__(self):
        self._merged_state: Dict[str, Any] = {}
        self._last_sync: float = 0.0


    # --------------------------------------------------------------------------
    # Merge primitives
    # --------------------------------------------------------------------------

    def _merge_axis(
        self,
        a: float,
        b: float,
        wa: float,
        wb: float,
    ) -> float:
        total = wa + wb + 1e-6
        return float(np.clip((a * wa + b * wb) / total, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        local_state: Dict[str, Any],
        remote_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Synchronize identity states between devices.
        """
        merged: Dict[str, Any] = {}

        local_conf = float(local_state.get("identity_strength", 0.5))
        remote_conf = float(remote_state.get("identity_strength", 0.5))

        for k in set(local_state.keys()) | set(remote_state.keys()):
            lv = local_state.get(k)
            rv = remote_state.get(k)

            if isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
                merged[k] = self._merge_axis(lv, rv, local_conf, remote_conf)
            else:
                merged[k] = lv if local_conf >= remote_conf else rv

        self._merged_state = merged
        self._last_sync = time.time()

        return {
            "synchronized_identity": dict(self._merged_state),
            "timestamp": self._last_sync,
        }


    def reset(self) -> None:
        """
        Reset synchronization state.
        """
        self._merged_state.clear()
        self._last_sync = time.time()


