#   (maps, regulations, learned priors) and edge-derived local reality
#   (sensors, perception, latency-bound truth) before mission execution.
#
# Backbone truth:
#   Global knowledge is broad. Local knowledge is sharp.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class CloudEdgeKnowledgeReconciliationLayer:
    """
    Cloud–edge knowledge reconciliation layer.
    Resolves conflicting beliefs by estimating freshness, confidence,
    and observability — producing a unified world model suitable for
    real-time decision making.
    """

    __slots__ = (
        "_world_model",
        "_last_reconcile",
    )

    def __init__(self):
        self._world_model: Dict[str, Any] = {}
        self._last_reconcile: float = 0.0


    # --------------------------------------------------------------------------
    # Reconciliation primitives
    # --------------------------------------------------------------------------

    def _confidence_weight(
        self,
        confidence: float,
        freshness: float,
    ) -> float:
        return float(
            np.clip(confidence * np.exp(-freshness), 0.0, 1.0)
        )


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        cloud_knowledge: Dict[str, Any],
        edge_knowledge: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Reconcile cloud and edge knowledge into a unified world model.
        """
        now = time.time()
        unified: Dict[str, Any] = {}

        cloud_age = float(cloud_knowledge.get("age", 1.0))
        edge_age = float(edge_knowledge.get("age", 0.1))

        cloud_conf = float(cloud_knowledge.get("confidence", 0.6))
        edge_conf = float(edge_knowledge.get("confidence", 0.9))

        wc = self._confidence_weight(cloud_conf, cloud_age)
        we = self._confidence_weight(edge_conf, edge_age)

        for k in set(cloud_knowledge.keys()) | set(edge_knowledge.keys()):
            cv = cloud_knowledge.get(k)
            ev = edge_knowledge.get(k)

            if isinstance(cv, (int, float)) and isinstance(ev, (int, float)):
                unified[k] = (
                    (cv * wc + ev * we) / (wc + we + 1e-6)
                )
            else:
                unified[k] = ev if we >= wc else cv

        self._world_model = unified
        self._last_reconcile = now

        return {
            "world_model": dict(self._world_model),
            "weights": {
                "cloud": wc,
                "edge": we,
            },
            "timestamp": self._last_reconcile,
        }


    def reset(self) -> None:
        """
        Reset reconciliation state.
        """
        self._world_model.clear()
        self._last_reconcile = time.time()


