from typing import Dict, Any, Callable
import time
import numpy as np


class RealTimeMissionExecutionSpine:
    """
    Real-time mission execution spine.
    Orchestrates mission phases, evaluates authority and safety at each
    tick, and emits control intents that downstream systems translate
    into flight, gimbal, and camera actions.
    """

    __slots__ = (
        "_active_mission",
        "_phase",
        "_last_tick",
        "_authority",
        "_safety_state",
    )

    def __init__(self):
        self._active_mission: Dict[str, Any] = {}
        self._phase: str = "idle"
        self._last_tick: float = 0.0
        self._authority: float = 1.0
        self._safety_state: Dict[str, Any] = {}


    # --------------------------------------------------------------------------
    # Mission lifecycle
    # --------------------------------------------------------------------------

    def start(self, mission: Dict[str, Any]) -> None:
        self._active_mission = dict(mission)
        self._phase = "initialize"
        self._last_tick = time.time()


    def stop(self) -> None:
        self._active_mission.clear()
        self._phase = "idle"


    # --------------------------------------------------------------------------
    # Execution tick
    # --------------------------------------------------------------------------

    def tick(
        self,
        world_model: Dict[str, Any],
        authority: float,
        safety: Dict[str, Any],
        controller: Callable[[Dict[str, Any]], Dict[str, Any]],
    ) -> Dict[str, Any]:
        """
        Advance mission execution by one real-time tick.
        """
        now = time.time()
        dt = now - self._last_tick
        self._last_tick = now

        self._authority = float(np.clip(authority, 0.0, 1.0))
        self._safety_state = dict(safety)

        # Phase transitions
        if self._phase == "initialize":
            self._phase = "execute"

        if self._phase == "execute":
            if self._safety_state.get("abort"):
                self._phase = "abort"
            elif self._active_mission.get("completed"):
                self._phase = "complete"

        # Emit control intent
        control_intent = {
            "mission": self._active_mission,
            "phase": self._phase,
            "authority": self._authority,
            "world": world_model,
            "dt": dt,
        }

        output = controller(control_intent)

        return {
            "phase": self._phase,
            "control_output": output,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset execution spine.
        """
        self._active_mission.clear()
        self._phase = "idle"
        self._last_tick = time.time()
        self._authority = 1.0
        self._safety_state.clear()


