# CHUNK 86 AD 01 — AUTONOMY AUTHORITY ESCALATION LADDER
# ==============================================================================
#
# Purpose:
#   Define a graded, reversible authority ladder that dynamically
#   allocates control between Human, Director AI, Cloud Cognition,
#   and Safety Systems based on confidence, context, and risk.
#
# Backbone truth:
#   Control is not a switch — it is a spectrum.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class AutonomyAuthorityEscalationLadder:
    """
    Autonomy authority escalation ladder.
    Determines real-time authority allocation across actors using
    confidence-weighted, safety-aware escalation and de-escalation
    rather than abrupt ownership transfer.
    """

    __slots__ = (
        "_authority_state",
        "_last_update",
    )

    def __init__(self):
        # Authority fractions sum to 1.0
        self._authority_state: Dict[str, float] = {
            "human": 0.0,
            "director_ai": 1.0,
            "cloud_ai": 0.0,
            "safety": 0.0,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Escalation primitives
    # --------------------------------------------------------------------------

    def _normalize(self) -> None:
        total = sum(self._authority_state.values()) + 1e-6
        for k in self._authority_state:
            self._authority_state[k] /= total


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        human_input: Dict[str, Any],
        director_confidence: float,
        cloud_confidence: float,
        safety_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update authority allocation.
        """
        risk = float(safety_state.get("risk_level", 0.0))
        emergency = bool(safety_state.get("emergency", False))

        # Safety overrides all
        if emergency:
            self._authority_state = {
                "human": 0.0,
                "director_ai": 0.0,
                "cloud_ai": 0.0,
                "safety": 1.0,
            }
        else:
            # Human intent nudges authority upward
            human_pressure = float(human_input.get("assertiveness", 0.0))

            self._authority_state["human"] = np.clip(
                self._authority_state["human"] + 0.2 * human_pressure,
                0.0,
                1.0,
            )

            # Director AI authority follows confidence inversely with risk
            self._authority_state["director_ai"] = np.clip(
                director_confidence * (1.0 - risk),
                0.0,
                1.0,
            )

            # Cloud AI assists when local confidence drops
            self._authority_state["cloud_ai"] = np.clip(
                cloud_confidence * (1.0 - director_confidence),
                0.0,
                1.0,
            )

            self._authority_state["safety"] = np.clip(
                risk,
                0.0,
                1.0,
            )

            self._normalize()

        self._last_update = time.time()

        return {
            "authority_allocation": dict(self._authority_state),
            "timestamp": self._last_update,
        }


    def reset(self) -> None:
        """
        Reset authority ladder.
        """
        self._authority_state = {
            "human": 0.0,
            "director_ai": 1.0,
            "cloud_ai": 0.0,
            "safety": 0.0,
        }
        self._last_update = time.time()


