from typing import Dict, Any
import numpy as np
import time


class HumanInTheLoopArbitrationGate:
    """
    Human-in-the-loop arbitration gate.
    Mediates human control input against active autonomous intent,
    resolving conflicts through intent-aware blending rather than
    hard override.
    """

    __slots__ = (
        "_engagement_level",
        "_last_input_time",
    )

    def __init__(self):
        self._engagement_level: float = 0.0
        self._last_input_time: float = 0.0


    # --------------------------------------------------------------------------
    # Engagement estimation
    # --------------------------------------------------------------------------

    def _estimate_engagement(self, human_input: Dict[str, Any]) -> float:
        magnitude = float(human_input.get("magnitude", 0.0))
        persistence = float(human_input.get("persistence", 0.0))
        return float(
            np.clip(0.6 * magnitude + 0.4 * persistence, 0.0, 1.0)
        )


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        human_input: Dict[str, Any],
        autonomous_intent: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Arbitrate human input against autonomous intent.
        """
        now = time.time()
        engagement = self._estimate_engagement(human_input)

        # Temporal smoothing of engagement
        self._engagement_level = (
            0.85 * self._engagement_level + 0.15 * engagement
        )

        self._last_input_time = now

        # Blend control intent
        blended_intent = dict(autonomous_intent)
        for axis, value in human_input.get("axes", {}).items():
            auto_val = autonomous_intent.get(axis, 0.0)
            blended_intent[axis] = (
                auto_val * (1.0 - self._engagement_level)
                + value * self._engagement_level
            )

        return {
            "blended_intent": blended_intent,
            "human_engagement": self._engagement_level,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset arbitration gate.
        """
        self._engagement_level = 0.0
        self._last_input_time = time.time()


