# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class ManualControlInjectionBlendingLayer:
    """
    Manual control injection & blending layer.
    Filters, rate-limits, and contextually blends human control input
    into the Director AI’s control intent while preserving safety,
    cinematic continuity, and vehicle stability.
    """

    __slots__ = (
        "_blend_strength",
        "_last_input_time",
        "_smoothing",
    )

    def __init__(self, smoothing: float = 0.85):
        self._smoothing = float(np.clip(smoothing, 0.7, 0.95))
        self._blend_strength: float = 0.0
        self._last_input_time: float = 0.0


    # --------------------------------------------------------------------------
    # Signal conditioning
    # --------------------------------------------------------------------------

    def _smooth(self, prev: float, target: float) -> float:
        return prev * self._smoothing + target * (1.0 - self._smoothing)


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        manual_input: Dict[str, float],
        ai_intent: Dict[str, float],
        engagement: float,
    ) -> Dict[str, Any]:
        """
        Blend manual control with AI intent.
        """
        now = time.time()

        self._blend_strength = self._smooth(
            self._blend_strength,
            float(np.clip(engagement, 0.0, 1.0)),
        )

        blended: Dict[str, float] = {}

        for axis in set(manual_input.keys()) | set(ai_intent.keys()):
            m = float(manual_input.get(axis, 0.0))
            a = float(ai_intent.get(axis, 0.0))

            blended[axis] = (
                a * (1.0 - self._blend_strength)
                + m * self._blend_strength
            )

        self._last_input_time = now

        return {
            "blended_control": blended,
            "blend_strength": self._blend_strength,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset blending layer.
        """
        self._blend_strength = 0.0
        self._last_input_time = time.time()


