# ==============================================================================
# CHUNK 86 AH 01 — AI ↔ FLIGHT CONTROLLER COMMAND FIREWALL
# ==============================================================================
#
# Purpose:
#   Enforce a strict, non-bypassable firewall between high-level
#   AI intent and low-level flight controller commands, ensuring
#   only validated, rate-limited, physically-safe commands reach
#   the flight stack.
#
# Backbone truth:
#   Every crash is a command that should never have existed.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class AIFlightControllerCommandFirewall:
    """
    AI ↔ flight controller command firewall.
    Validates command structure, bounds, rate-of-change, authority,
    and safety context before forwarding anything to the FC interface.
    """

    __slots__ = (
        "_last_command",
        "_last_time",
        "_rate_limits",
    )

    def __init__(self):
        self._last_command: Dict[str, float] = {}
        self._last_time: float = time.time()
        self._rate_limits: Dict[str, float] = {
            "roll": 2.0,       # rad/s
            "pitch": 2.0,
            "yaw": 2.5,
            "throttle": 1.5,
        }


    # --------------------------------------------------------------------------
    # Validation primitives
    # --------------------------------------------------------------------------

    def _rate_limit(self, axis: str, value: float, dt: float) -> float:
        prev = self._last_command.get(axis, 0.0)
        limit = self._rate_limits.get(axis, 1.0) * max(dt, 1e-3)
        return float(np.clip(value, prev - limit, prev + limit))


    def _clamp_physical(self, axis: str, value: float) -> float:
        if axis == "throttle":
            return float(np.clip(value, 0.0, 1.0))
        return float(np.clip(value, -1.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        proposed_command: Dict[str, float],
        authority: float,
        safety_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Sanitize and approve a control command.
        """
        now = time.time()
        dt = now - self._last_time
        self._last_time = now

        if safety_state.get("kill_chain_active"):
            return {
                "approved": False,
                "reason": "kill_chain_active",
            }

        approved: Dict[str, float] = {}

        for axis, value in proposed_command.items():
            v = float(value) * float(np.clip(authority, 0.0, 1.0))
            v = self._rate_limit(axis, v, dt)
            v = self._clamp_physical(axis, v)
            approved[axis] = v

        self._last_command = dict(approved)

        return {
            "approved": True,
            "command": approved,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset firewall state.
        """
        self._last_command.clear()
        self._last_time = time.time()


