# ==============================================================================

from typing import Dict, Any, Deque
from collections import deque
import time


class DeterministicControlPacketScheduler:
    """
    Deterministic control packet scheduler.
    Maintains fixed-rate emission, monotonic sequencing, and bounded
    buffering to ensure the flight controller receives commands in
    a predictable, recoverable temporal structure.
    """

    __slots__ = (
        "_queue",
        "_rate_hz",
        "_last_emit",
        "_seq",
    )

    def __init__(self, rate_hz: float = 50.0, buffer: int = 5):
        self._rate_hz = float(max(rate_hz, 10.0))
        self._queue: Deque[Dict[str, Any]] = deque(maxlen=buffer)
        self._last_emit: float = 0.0
        self._seq: int = 0


    # --------------------------------------------------------------------------
    # Scheduling primitives
    # --------------------------------------------------------------------------

    def enqueue(self, command: Dict[str, Any]) -> None:
        """
        Enqueue a sanitized control command.
        """
        payload = dict(command)
        payload["seq"] = self._seq
        payload["timestamp"] = time.time()
        self._seq += 1
        self._queue.append(payload)


    # --------------------------------------------------------------------------
    # Emit
    # --------------------------------------------------------------------------

    def emit(self) -> Dict[str, Any]:
        """
        Emit next control packet if timing allows.
        """
        now = time.time()
        interval = 1.0 / self._rate_hz

        if now - self._last_emit < interval:
            return {
                "emitted": False,
            }

        if not self._queue:
            return {
                "emitted": False,
            }

        packet = self._queue.popleft()
        self._last_emit = now

        return {
            "emitted": True,
            "packet": packet,
        }


    def reset(self) -> None:
        """
        Reset scheduler.
        """
        self._queue.clear()
        self._last_emit = time.time()
        self._seq = 0


