# ==============================================================================
# CHUNK 86 AJ 01 — MAVLINK TRANSLATION & SANITIZATION LAYER
# ==============================================================================
#
# Purpose:
#   Translate sanitized, deterministic control packets into
#   flight-controller-compatible MAVLink messages with strict
#   unit correctness, message hygiene, and FC-profile compliance.
#
# Backbone truth:
#   Translation is where intent most often dies.
#
# ==============================================================================

from typing import Dict, Any, Optional
import time
import math


class MAVLinkTranslationSanitizationLayer:
    """
    MAVLink translation & sanitization layer.
    Converts normalized control intents into MAVLink-compatible
    structures while enforcing units, bounds, message rates,
    and FC-specific constraints.
    """

    __slots__ = (
        "_fc_profile",
        "_last_emit",
    )

    def __init__(self, fc_profile: Optional[Dict[str, Any]] = None):
        # FC profile defines scaling, message types, axis conventions
        self._fc_profile = fc_profile or {
            "roll_scale": 1.0,      # normalized → radians
            "pitch_scale": 1.0,
            "yaw_rate_scale": 1.0, # normalized → rad/s
            "throttle_scale": 1.0, # normalized → [0,1]
            "message": "SET_ATTITUDE_TARGET",
        }
        self._last_emit: float = 0.0


    # --------------------------------------------------------------------------
    # Translation primitives
    # --------------------------------------------------------------------------

    def _clamp(self, v: float, lo: float, hi: float) -> float:
        return float(max(lo, min(hi, v)))


    def _normalize_quaternion(
        self,
        roll: float,
        pitch: float,
        yaw: float,
    ) -> Dict[str, float]:
        """
        Convert Euler angles to normalized quaternion.
        """
        cr = math.cos(roll * 0.5)
        sr = math.sin(roll * 0.5)
        cp = math.cos(pitch * 0.5)
        sp = math.sin(pitch * 0.5)
        cy = math.cos(yaw * 0.5)
        sy = math.sin(yaw * 0.5)

        qw = cr * cp * cy + sr * sp * sy
        qx = sr * cp * cy - cr * sp * sy
        qy = cr * sp * cy + sr * cp * sy
        qz = cr * cp * sy - sr * sp * cy

        norm = math.sqrt(qw * qw + qx * qx + qy * qy + qz * qz) + 1e-9

        return {
            "qw": qw / norm,
            "qx": qx / norm,
            "qy": qy / norm,
            "qz": qz / norm,
        }


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        control_packet: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Translate a control packet into MAVLink-ready payload.
        """
        now = time.time()
        self._last_emit = now

        roll = self._clamp(
            float(control_packet.get("roll", 0.0))
            * self._fc_profile["roll_scale"],
            -math.pi,
            math.pi,
        )

        pitch = self._clamp(
            float(control_packet.get("pitch", 0.0))
            * self._fc_profile["pitch_scale"],
            -math.pi,
            math.pi,
        )

        yaw_rate = self._clamp(
            float(control_packet.get("yaw", 0.0))
            * self._fc_profile["yaw_rate_scale"],
            -math.pi,
            math.pi,
        )

        throttle = self._clamp(
            float(control_packet.get("throttle", 0.0))
            * self._fc_profile["throttle_scale"],
            0.0,
            1.0,
        )

        attitude = self._normalize_quaternion(roll, pitch, 0.0)

        mavlink_payload = {
            "type": self._fc_profile["message"],
            "attitude": attitude,
            "yaw_rate": yaw_rate,
            "throttle": throttle,
            "timestamp": now,
        }

        return {
            "translated": True,
            "mavlink_payload": mavlink_payload,
        }


    def reset(self) -> None:
        """
        Reset translation state.
        """
        self._last_emit = time.time()


