from typing import Dict, Any, Optional
import time


class RedundantCommandChannelHeartbeatMonitor:
    """
    Redundant command channel & heartbeat monitor.
    Maintains primary/secondary command channels, tracks heartbeats,
    and escalates safety or authority responses upon degradation.
    """

    __slots__ = (
        "_primary_last_seen",
        "_secondary_last_seen",
        "_heartbeat_timeout",
        "_active_channel",
    )

    def __init__(self, heartbeat_timeout: float = 0.25):
        self._heartbeat_timeout = float(max(heartbeat_timeout, 0.05))
        self._primary_last_seen: float = 0.0
        self._secondary_last_seen: float = 0.0
        self._active_channel: str = "primary"


    # --------------------------------------------------------------------------
    # Heartbeat ingestion
    # --------------------------------------------------------------------------

    def ingest(
        self,
        channel: str,
        heartbeat: Dict[str, Any],
    ) -> None:
        """
        Ingest heartbeat from a command channel.
        """
        now = time.time()
        if channel == "primary":
            self._primary_last_seen = now
        elif channel == "secondary":
            self._secondary_last_seen = now


    # --------------------------------------------------------------------------
    # Evaluation
    # --------------------------------------------------------------------------

    def evaluate(self) -> Dict[str, Any]:
        """
        Evaluate channel health and select active channel.
        """
        now = time.time()
        primary_alive = (now - self._primary_last_seen) <= self._heartbeat_timeout
        secondary_alive = (now - self._secondary_last_seen) <= self._heartbeat_timeout

        if primary_alive:
            self._active_channel = "primary"
        elif secondary_alive:
            self._active_channel = "secondary"
        else:
            self._active_channel = "none"

        return {
            "primary_alive": primary_alive,
            "secondary_alive": secondary_alive,
            "active_channel": self._active_channel,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset heartbeat monitor.
        """
        self._primary_last_seen = 0.0
        self._secondary_last_seen = 0.0
        self._active_channel = "primary"


