from typing import Dict, Any
import time
import numpy as np


class FlightControllerFeedbackAssimilationCore:
    """
    Flight controller feedback assimilation core.
    Interprets low-level FC telemetry into semantically meaningful
    signals that downstream cognition, safety, and authority systems
    can reason about deterministically.
    """

    __slots__ = (
        "_state",
        "_confidence",
        "_last_update",
    )

    def __init__(self):
        self._state: Dict[str, Any] = {}
        self._confidence: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Assimilation primitives
    # --------------------------------------------------------------------------

    def _compute_confidence(self, telemetry: Dict[str, Any]) -> float:
        """
        Compute confidence from estimator health indicators.
        """
        ekf_ok = float(telemetry.get("ekf_ok", 1.0))
        vib = float(telemetry.get("vibration", 0.0))
        imu_var = float(telemetry.get("imu_variance", 0.0))

        confidence = (
            0.5 * ekf_ok
            + 0.3 * (1.0 - np.clip(vib, 0.0, 1.0))
            + 0.2 * (1.0 - np.clip(imu_var, 0.0, 1.0))
        )

        return float(np.clip(confidence, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, telemetry: Dict[str, Any]) -> Dict[str, Any]:
        """
        Assimilate FC telemetry into internal state.
        """
        now = time.time()

        self._confidence = self._compute_confidence(telemetry)

        self._state = {
            "attitude": telemetry.get("attitude"),
            "rates": telemetry.get("rates"),
            "position": telemetry.get("position"),
            "velocity": telemetry.get("velocity"),
            "armed": telemetry.get("armed", False),
            "mode": telemetry.get("mode"),
            "confidence": self._confidence,
        }

        self._last_update = now

        return {
            "assimilated_state": dict(self._state),
            "confidence": self._confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset feedback assimilation core.
        """
        self._state.clear()
        self._confidence = 1.0
        self._last_update = time.time()


