# CHUNK 86 AM 01 — STATE ESTIMATION CONFIDENCE TRACKER
# ==============================================================================
#
# Purpose:
#   Track estimator confidence as a temporally-evolving signal rather
#   than a point estimate, enabling anticipation of degradation,
#   graceful authority rebalancing, and preemptive safety modulation.
#
# Backbone truth:
#   Confidence is a trajectory, not a number.
#
# ==============================================================================

from typing import Dict, Any, Deque
from collections import deque
import numpy as np
import time


class StateEstimationConfidenceTracker:
    """
    State estimation confidence tracker.
    Maintains a rolling temporal model of estimator confidence,
    detecting trends, volatility, and inflection points rather
    than reacting to instantaneous drops.
    """

    __slots__ = (
        "_history",
        "_window",
        "_trend",
        "_volatility",
        "_last_update",
    )

    def __init__(self, window: int = 30):
        self._window = int(max(window, 5))
        self._history: Deque[float] = deque(maxlen=self._window)
        self._trend: float = 0.0
        self._volatility: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Analysis primitives
    # --------------------------------------------------------------------------

    def _analyze(self) -> None:
        values = np.array(self._history, dtype=float)
        if values.size < 3:
            self._trend = 0.0
            self._volatility = 0.0
            return

        x = np.arange(values.size)
        coeffs = np.polyfit(x, values, 1)

        self._trend = float(coeffs[0])
        self._volatility = float(np.std(values))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(self, confidence_sample: float) -> Dict[str, Any]:
        """
        Update confidence history and compute temporal metrics.
        """
        now = time.time()
        sample = float(np.clip(confidence_sample, 0.0, 1.0))

        self._history.append(sample)
        self._analyze()
        self._last_update = now

        return {
            "confidence_mean": float(np.mean(self._history)),
            "confidence_trend": self._trend,
            "confidence_volatility": self._volatility,
            "samples": len(self._history),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset confidence tracker.
        """
        self._history.clear()
        self._trend = 0.0
        self._volatility = 0.0
        self._last_update = time.time()


