# CHUNK 86 AN 01 — CLOSED-LOOP STABILITY & GAIN GOVERNOR
# ==============================================================================
#
# Purpose:
#   Dynamically regulate control-loop aggressiveness so cinematic
#   intent is preserved while respecting vehicle stability margins,
#   estimator confidence, and environmental uncertainty.
#
# Backbone truth:
#   Beautiful motion exists at the edge of stability — not beyond it.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class ClosedLoopStabilityGainGovernor:
    """
    Closed-loop stability & gain governor.
    Modulates control gains in real time based on estimator confidence,
    motion intensity, and detected instability precursors to prevent
    oscillation, overshoot, and loss of control.
    """

    __slots__ = (
        "_base_gains",
        "_current_scale",
        "_last_update",
    )

    def __init__(self, base_gains: Dict[str, float] = None):
        self._base_gains = base_gains or {
            "roll": 1.0,
            "pitch": 1.0,
            "yaw": 1.0,
        }
        self._current_scale: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Gain modulation
    # --------------------------------------------------------------------------

    def apply(
        self,
        confidence: float,
        motion_energy: float,
        volatility: float,
    ) -> Dict[str, Any]:
        """
        Compute scaled gains for current conditions.
        """
        now = time.time()

        # Confidence reduces aggression when low
        conf_factor = np.clip(confidence, 0.3, 1.0)

        # High motion requires damping
        motion_factor = np.clip(1.0 - 0.5 * motion_energy, 0.5, 1.0)

        # Volatility penalizes sharp gains
        vol_factor = np.clip(1.0 - volatility, 0.4, 1.0)

        target_scale = conf_factor * motion_factor * vol_factor

        # Temporal smoothing
        self._current_scale = (
            0.9 * self._current_scale + 0.1 * target_scale
        )

        scaled_gains = {
            axis: gain * self._current_scale
            for axis, gain in self._base_gains.items()
        }

        self._last_update = now

        return {
            "gain_scale": self._current_scale,
            "scaled_gains": scaled_gains,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset gain governor.
        """
        self._current_scale = 1.0
        self._last_update = time.time()


