# CHUNK 86 AO 01 — MISSION-LEVEL ADAPTIVE RISK MODULATOR
# ==============================================================================
#
# Purpose:
#   Track, accumulate, and reason about mission-level risk as a
#   continuous signal, enabling proactive adaptation of autonomy,
#   cinematic intent, and execution strategy before failure occurs.
#
# Backbone truth:
#   The best missions end early — on purpose.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class MissionLevelAdaptiveRiskModulator:
    """
    Mission-level adaptive risk modulator.
    Aggregates estimator confidence trends, environmental stress,
    control saturation, and mission complexity into a unified
    risk trajectory that shapes downstream decision making.
    """

    __slots__ = (
        "_risk",
        "_trend",
        "_last_update",
    )

    def __init__(self):
        self._risk: float = 0.0
        self._trend: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Risk aggregation
    # --------------------------------------------------------------------------

    def apply(
        self,
        confidence_mean: float,
        confidence_trend: float,
        motion_energy: float,
        saturation: float,
        environment_stress: float,
    ) -> Dict[str, Any]:
        """
        Update mission-level risk estimate.
        """
        now = time.time()

        # Confidence decay drives risk
        conf_risk = np.clip(1.0 - confidence_mean, 0.0, 1.0)
        trend_risk = np.clip(-confidence_trend, 0.0, 1.0)

        # Motion and saturation increase risk
        dyn_risk = np.clip(0.6 * motion_energy + 0.4 * saturation, 0.0, 1.0)

        # Environmental uncertainty
        env_risk = np.clip(environment_stress, 0.0, 1.0)

        instantaneous = (
            0.35 * conf_risk
            + 0.25 * trend_risk
            + 0.25 * dyn_risk
            + 0.15 * env_risk
        )

        # Temporal smoothing to avoid oscillation
        self._risk = 0.9 * self._risk + 0.1 * instantaneous
        self._trend = instantaneous - self._risk

        self._last_update = now

        return {
            "mission_risk": self._risk,
            "risk_trend": self._trend,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset mission risk modulator.
        """
        self._risk = 0.0
        self._trend = 0.0
        self._last_update = time.time()


