#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CinematicIntentDegradationController:
    """
    Cinematic intent degradation controller.
    Modulates cinematic parameters along a continuous degradation curve
    driven by mission risk, ensuring visual output remains intentional
    and coherent under constraint.
    """

    __slots__ = (
        "_degradation",
        "_last_update",
    )

    def __init__(self):
        self._degradation: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Degradation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        cinematic_intent: Dict[str, Any],
        mission_risk: float,
    ) -> Dict[str, Any]:
        """
        Degrade cinematic intent proportional to mission risk.
        """
        now = time.time()
        risk = float(np.clip(mission_risk, 0.0, 1.0))

        # Smooth degradation trajectory
        self._degradation = 0.9 * self._degradation + 0.1 * risk

        degraded = dict(cinematic_intent)

        # Motion ambition reduces first
        degraded["motion_energy"] = (
            cinematic_intent.get("motion_energy", 0.0)
            * (1.0 - 0.6 * self._degradation)
        )

        # Framing simplifies
        degraded["framing_aggression"] = (
            cinematic_intent.get("framing_aggression", 0.0)
            * (1.0 - 0.7 * self._degradation)
        )

        # Exposure and contrast soften last
        degraded["contrast"] = (
            cinematic_intent.get("contrast", 1.0)
            * (1.0 - 0.4 * self._degradation)
        )

        degraded["exposure_bias"] = (
            cinematic_intent.get("exposure_bias", 0.0)
            * (1.0 - 0.3 * self._degradation)
        )

        degraded["cinematic_degradation"] = self._degradation

        self._last_update = now

        return {
            "degraded_intent": degraded,
            "degradation_level": self._degradation,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset degradation controller.
        """
        self._degradation = 0.0
        self._last_update = time.time()


