# CHUNK 86 AQ 01 — AUTONOMOUS ABORT REASONING ENGINE
# ==============================================================================
#
# Purpose:
#   Reason about when and why to abort a mission using multi-factor,
#   confidence-aware, temporally-consistent logic that produces
#   explainable abort decisions rather than reactive panic stops.
#
# Backbone truth:
#   A good abort is a decision — not a reflex.
#
# ==============================================================================

from typing import Dict, Any, List
import numpy as np
import time


class AutonomousAbortReasoningEngine:
    """
    Autonomous abort reasoning engine.
    Synthesizes mission risk trajectory, estimator confidence,
    control stability, environmental stress, and safety signals
    into a coherent abort decision with traceable justification.
    """

    __slots__ = (
        "_abort_score",
        "_contributors",
        "_last_update",
    )

    def __init__(self):
        self._abort_score: float = 0.0
        self._contributors: Dict[str, float] = {}
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Reasoning primitives
    # --------------------------------------------------------------------------

    def _score_component(self, value: float, weight: float) -> float:
        return float(np.clip(value * weight, 0.0, 1.0))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        mission_risk: float,
        risk_trend: float,
        confidence_mean: float,
        confidence_trend: float,
        stability_margin: float,
        safety_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Evaluate whether mission should be aborted.
        """
        now = time.time()

        # Component risks
        r_mission = self._score_component(mission_risk, 0.35)
        r_trend = self._score_component(max(risk_trend, 0.0), 0.15)
        r_conf = self._score_component(1.0 - confidence_mean, 0.25)
        r_conf_trend = self._score_component(max(-confidence_trend, 0.0), 0.10)
        r_stability = self._score_component(1.0 - stability_margin, 0.10)

        # Safety hard signals
        r_safety = 0.0
        if safety_state.get("collision_imminent"):
            r_safety = 1.0
        elif safety_state.get("loss_of_control"):
            r_safety = 0.9
        elif safety_state.get("geofence_breach"):
            r_safety = 0.8

        self._contributors = {
            "mission_risk": r_mission,
            "risk_trend": r_trend,
            "confidence": r_conf,
            "confidence_trend": r_conf_trend,
            "stability": r_stability,
            "safety": r_safety,
        }

        instantaneous = (
            r_mission
            + r_trend
            + r_conf
            + r_conf_trend
            + r_stability
            + r_safety
        )

        # Temporal smoothing to prevent oscillatory aborts
        self._abort_score = 0.85 * self._abort_score + 0.15 * instantaneous

        decision = self._abort_score >= 0.75

        self._last_update = now

        return {
            "abort": decision,
            "abort_score": self._abort_score,
            "contributors": dict(self._contributors),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset abort reasoning engine.
        """
        self._abort_score = 0.0
        self._contributors.clear()
        self._last_update = time.time()


