from typing import Dict, Any
import time
import numpy as np


class GracefulMissionTerminationOrchestrator:
    """
    Graceful mission termination orchestrator.
    Selects and executes the most appropriate termination strategy
    based on safety state, confidence, environment, and human intent,
    ensuring controlled transitions instead of abrupt shutdown.
    """

    __slots__ = (
        "_mode",
        "_last_update",
    )

    def __init__(self):
        self._mode: str = "none"
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Decision logic
    # --------------------------------------------------------------------------

    def _select_mode(
        self,
        safety_state: Dict[str, Any],
        confidence: float,
        human_preference: str,
    ) -> str:
        if safety_state.get("collision_imminent"):
            return "land_immediately"

        if safety_state.get("power_critical"):
            return "land_immediately"

        if confidence < 0.3:
            return "return_to_home"

        if human_preference in {"loiter", "hold"}:
            return human_preference

        return "return_to_home"


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        safety_state: Dict[str, Any],
        confidence: float,
        human_preference: str = "auto",
    ) -> Dict[str, Any]:
        """
        Determine termination strategy.
        """
        now = time.time()

        self._mode = self._select_mode(
            safety_state,
            float(np.clip(confidence, 0.0, 1.0)),
            human_preference,
        )

        self._last_update = now

        return {
            "termination_mode": self._mode,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset termination orchestrator.
        """
        self._mode = "none"
        self._last_update = time.time()


