from typing import Dict, Any, List
import numpy as np
import time


class PostMissionCognitiveAestheticDebrief:
    """
    Post-mission cognitive & aesthetic debrief.
    Synthesizes mission execution traces into structured lessons about
    decision quality, risk management, cinematic effectiveness, and
    human satisfaction — without hindsight bias.
    """

    __slots__ = (
        "_summary",
        "_last_update",
    )

    def __init__(self):
        self._summary: Dict[str, Any] = {}
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Debrief primitives
    # --------------------------------------------------------------------------

    def _score_cinema(self, metrics: Dict[str, float]) -> float:
        """
        Compute overall cinematic effectiveness score.
        """
        return float(np.clip(
            0.4 * metrics.get("framing_quality", 0.0)
            + 0.3 * metrics.get("motion_smoothness", 0.0)
            + 0.3 * metrics.get("exposure_consistency", 0.0),
            0.0,
            1.0,
        ))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        mission_trace: List[Dict[str, Any]],
        final_state: Dict[str, Any],
        user_feedback: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Execute post-mission debrief.
        """
        now = time.time()

        avg_risk = float(np.mean([t.get("mission_risk", 0.0) for t in mission_trace]))
        avg_confidence = float(np.mean([t.get("confidence", 1.0) for t in mission_trace]))

        cinema_score = self._score_cinema(final_state.get("cinematic_metrics", {}))

        self._summary = {
            "mission_completed": final_state.get("completed", False),
            "average_risk": avg_risk,
            "average_confidence": avg_confidence,
            "cinematic_score": cinema_score,
            "user_satisfaction": user_feedback.get("rating"),
            "termination_mode": final_state.get("termination_mode"),
        }

        self._last_update = now

        return {
            "debrief_summary": dict(self._summary),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset debrief state.
        """
        self._summary.clear()
        self._last_update = time.time()


