from typing import Dict, Any
import numpy as np
import time


class LongTermLearningStyleAdaptationKernel:
    """
    Long-term learning & style adaptation kernel.
    Integrates post-mission debriefs into a slowly-updating latent
    style vector that shapes future cinematic decisions without
    reacting to noise or single-mission anomalies.
    """

    __slots__ = (
        "_style_vector",
        "_learning_rate",
        "_last_update",
    )

    def __init__(self, learning_rate: float = 0.02):
        self._learning_rate = float(np.clip(learning_rate, 0.005, 0.05))
        self._style_vector: Dict[str, float] = {
            "motion_preference": 0.5,
            "framing_boldness": 0.5,
            "contrast_taste": 0.5,
            "pace_bias": 0.5,
        }
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Learning update
    # --------------------------------------------------------------------------

    def apply(
        self,
        debrief_summary: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update style vector from debrief summary.
        """
        now = time.time()

        satisfaction = debrief_summary.get("user_satisfaction")
        cinema_score = float(debrief_summary.get("cinematic_score", 0.5))

        if satisfaction is None:
            satisfaction = cinema_score

        # Compute delta scaled by satisfaction deviation
        delta = self._learning_rate * (float(satisfaction) - 0.5)

        self._style_vector["motion_preference"] = float(np.clip(
            self._style_vector["motion_preference"] + delta,
            0.0,
            1.0,
        ))

        self._style_vector["framing_boldness"] = float(np.clip(
            self._style_vector["framing_boldness"] + 0.8 * delta,
            0.0,
            1.0,
        ))

        self._style_vector["contrast_taste"] = float(np.clip(
            self._style_vector["contrast_taste"] + 0.6 * delta,
            0.0,
            1.0,
        ))

        self._style_vector["pace_bias"] = float(np.clip(
            self._style_vector["pace_bias"] + 0.7 * delta,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "style_vector": dict(self._style_vector),
            "learning_rate": self._learning_rate,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset style kernel.
        """
        self._style_vector = {
            "motion_preference": 0.5,
            "framing_boldness": 0.5,
            "contrast_taste": 0.5,
            "pace_bias": 0.5,
        }
        self._last_update = time.time()


