from typing import Dict, Any, List
import numpy as np
import time


class CrossMissionMemoryConsolidationEngine:
    """
    Cross-mission memory consolidation engine.
    Compresses mission debriefs into weighted memory atoms that influence
    future reasoning, risk anticipation, and stylistic priors without
    storing raw execution traces indefinitely.
    """

    __slots__ = (
        "_memory_atoms",
        "_capacity",
        "_last_update",
    )

    def __init__(self, capacity: int = 64):
        self._capacity = int(max(capacity, 16))
        self._memory_atoms: List[Dict[str, Any]] = []
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Consolidation primitives
    # --------------------------------------------------------------------------

    def _importance(self, summary: Dict[str, Any]) -> float:
        """
        Compute importance score for a mission summary.
        """
        risk = float(summary.get("average_risk", 0.0))
        cinema = float(summary.get("cinematic_score", 0.5))
        satisfaction = summary.get("user_satisfaction")
        if satisfaction is None:
            satisfaction = cinema

        return float(np.clip(
            0.4 * risk + 0.3 * cinema + 0.3 * satisfaction,
            0.0,
            1.0,
        ))


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        debrief_summary: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Consolidate a mission debrief into memory.
        """
        now = time.time()

        atom = {
            "timestamp": now,
            "summary": dict(debrief_summary),
            "importance": self._importance(debrief_summary),
        }

        self._memory_atoms.append(atom)

        # Enforce capacity by pruning lowest-importance memories
        if len(self._memory_atoms) > self._capacity:
            self._memory_atoms.sort(
                key=lambda a: a["importance"],
                reverse=True,
            )
            self._memory_atoms = self._memory_atoms[: self._capacity]

        self._last_update = now

        return {
            "memory_size": len(self._memory_atoms),
            "last_importance": atom["importance"],
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset consolidated memory.
        """
        self._memory_atoms.clear()
        self._last_update = time.time()


