from typing import Dict, Any
import numpy as np
import time


class DirectorPersonalityDriftRegulator:
    """
    Director personality drift regulator.
    Constrains long-term stylistic adaptation within a bounded
    identity manifold, ensuring accumulated learning sharpens
    intent instead of erasing creative coherence.
    """

    __slots__ = (
        "_baseline",
        "_max_deviation",
        "_last_update",
    )

    def __init__(
        self,
        baseline_style: Dict[str, float],
        max_deviation: float = 0.25,
    ):
        self._baseline = dict(baseline_style)
        self._max_deviation = float(np.clip(max_deviation, 0.1, 0.4))
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Regulation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        style_vector: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Regulate style vector to prevent identity drift.
        """
        now = time.time()

        regulated = {}
        deviations = {}

        for k, v in style_vector.items():
            base = self._baseline.get(k, 0.5)
            delta = float(v - base)
            clamped = float(np.clip(
                delta,
                -self._max_deviation,
                self._max_deviation,
            ))
            regulated[k] = base + clamped
            deviations[k] = delta

        self._last_update = now

        return {
            "regulated_style": regulated,
            "raw_deviation": deviations,
            "max_allowed_deviation": self._max_deviation,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset personality regulator.
        """
        self._last_update = time.time()


