from typing import Dict, Any
import numpy as np
import time


class MultiUserPreferenceArbitrationLayer:
    """
    Multi-user preference arbitration layer.
    Balances multiple human preference vectors with AI identity,
    mission safety, and learned style using weighted authority,
    decay, and contextual relevance.
    """

    __slots__ = (
        "_weights",
        "_last_update",
    )

    def __init__(self):
        self._weights = {
            "pilot": 0.35,
            "owner": 0.30,
            "director": 0.20,
            "safety": 0.15,
        }
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Arbitration logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        preferences: Dict[str, Dict[str, float]],
        ai_style: Dict[str, float],
        mission_risk: float,
    ) -> Dict[str, Any]:
        """
        Arbitrate between user preferences and AI style.
        """
        now = time.time()
        risk = float(np.clip(mission_risk, 0.0, 1.0))

        blended = dict(ai_style)

        for role, prefs in preferences.items():
            weight = self._weights.get(role, 0.0)

            # Safety influence increases with risk
            if role == "safety":
                weight *= (1.0 + risk)

            for k, v in prefs.items():
                blended[k] = blended.get(k, 0.5) + weight * (v - blended.get(k, 0.5))

        # Normalize
        for k in blended:
            blended[k] = float(np.clip(blended[k], 0.0, 1.0))

        self._last_update = now

        return {
            "arbitrated_style": blended,
            "weights": dict(self._weights),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset arbitration layer.
        """
        self._last_update = time.time()


