from typing import Dict, Any, Optional
import time
import hashlib
import json


class CloudEdgeMemorySynchronizationBus:
    """
    Cloud ↔ Edge memory synchronization bus.
    Maintains bidirectional, versioned synchronization of cognitive
    memory and style state across heterogeneous compute nodes while
    preventing overwrite storms, stale regressions, and split-brain.
    """

    __slots__ = (
        "_last_hash",
        "_last_version",
        "_last_update",
    )

    def __init__(self):
        self._last_hash: Optional[str] = None
        self._last_version: int = 0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Hashing & versioning
    # --------------------------------------------------------------------------

    def _hash_state(self, state: Dict[str, Any]) -> str:
        payload = json.dumps(state, sort_keys=True).encode("utf-8")
        return hashlib.sha256(payload).hexdigest()


    # --------------------------------------------------------------------------
    # Synchronization logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        local_state: Dict[str, Any],
        remote_state: Optional[Dict[str, Any]],
        remote_version: Optional[int],
    ) -> Dict[str, Any]:
        """
        Synchronize local and remote cognitive state.
        """
        now = time.time()

        local_hash = self._hash_state(local_state)

        # No remote data — publish local
        if remote_state is None or remote_version is None:
            self._last_hash = local_hash
            self._last_version += 1
            self._last_update = now
            return {
                "action": "publish_local",
                "state": local_state,
                "version": self._last_version,
                "timestamp": now,
            }

        # Remote newer — accept remote
        if remote_version > self._last_version:
            self._last_version = remote_version
            self._last_hash = self._hash_state(remote_state)
            self._last_update = now
            return {
                "action": "accept_remote",
                "state": remote_state,
                "version": remote_version,
                "timestamp": now,
            }

        # Local changed — push update
        if local_hash != self._last_hash:
            self._last_hash = local_hash
            self._last_version += 1
            self._last_update = now
            return {
                "action": "push_update",
                "state": local_state,
                "version": self._last_version,
                "timestamp": now,
            }

        # No-op
        self._last_update = now
        return {
            "action": "noop",
            "version": self._last_version,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset synchronization bus.
        """
        self._last_hash = None
        self._last_version = 0
        self._last_update = time.time()


