from typing import Dict, Any
import time
import numpy as np


class HumanOverrideAuthorityResolver:
    """
    Human override authority resolver.
    Arbitrates control authority between human and AI based on
    confidence, mission risk, communication latency, and explicit
    override intent — preventing abrupt or unsafe transitions.
    """

    __slots__ = (
        "_authority",
        "_blend_factor",
        "_last_update",
    )

    def __init__(self):
        self._authority: str = "ai"
        self._blend_factor: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Authority resolution
    # --------------------------------------------------------------------------

    def apply(
        self,
        human_override: bool,
        confidence: float,
        mission_risk: float,
        link_latency: float,
    ) -> Dict[str, Any]:
        """
        Resolve authority between human and AI.
        """
        now = time.time()

        confidence = float(np.clip(confidence, 0.0, 1.0))
        risk = float(np.clip(mission_risk, 0.0, 1.0))
        latency = float(max(link_latency, 0.0))

        # Latency penalizes human takeover reliability
        latency_factor = np.clip(1.0 - latency, 0.0, 1.0)

        # Compute human authority pressure
        human_pressure = (
            (1.0 if human_override else 0.0)
            * latency_factor
            * (1.0 - confidence)
        )

        # AI authority pressure
        ai_pressure = confidence * (1.0 - risk)

        # Blend authority smoothly
        delta = human_pressure - ai_pressure
        self._blend_factor = float(np.clip(
            self._blend_factor + 0.1 * delta,
            0.0,
            1.0,
        ))

        self._authority = "human" if self._blend_factor > 0.5 else "ai"
        self._last_update = now

        return {
            "authority": self._authority,
            "blend_factor": self._blend_factor,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset authority resolver.
        """
        self._authority = "ai"
        self._blend_factor = 0.0
        self._last_update = time.time()


