from typing import Dict, Any
import numpy as np
import time


class AIAutonomyEscalationGovernor:
    """
    AI autonomy escalation governor.
    Dynamically adjusts autonomy level based on estimator confidence,
    mission risk, environmental stress, communication latency, and
    human authority state — preventing runaway autonomy while allowing
    full AI control when conditions truly permit it.
    """

    __slots__ = (
        "_autonomy_level",
        "_last_update",
    )

    def __init__(self):
        # 0.0 = full human control, 1.0 = full AI autonomy
        self._autonomy_level: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Escalation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        confidence: float,
        mission_risk: float,
        environment_stress: float,
        link_latency: float,
        authority: str,
    ) -> Dict[str, Any]:
        """
        Update autonomy level.
        """
        now = time.time()

        confidence = float(np.clip(confidence, 0.0, 1.0))
        risk = float(np.clip(mission_risk, 0.0, 1.0))
        env = float(np.clip(environment_stress, 0.0, 1.0))
        latency = float(max(link_latency, 0.0))

        # Base autonomy potential
        potential = (
            0.5 * confidence
            + 0.3 * (1.0 - risk)
            + 0.2 * (1.0 - env)
        )

        # Penalize latency and human authority
        if authority == "human":
            potential *= 0.3

        potential *= np.clip(1.0 - latency, 0.0, 1.0)

        # Smooth escalation/de-escalation
        self._autonomy_level = float(np.clip(
            0.9 * self._autonomy_level + 0.1 * potential,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "autonomy_level": self._autonomy_level,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset autonomy governor.
        """
        self._autonomy_level = 0.0
        self._last_update = time.time()


