from typing import Dict, Any
import time
import numpy as np


class EdgeCloudLatencyCompensationLayer:
    """
    Edge ↔ cloud latency compensation layer.
    Tracks latency distribution over time and applies predictive
    temporal alignment so decisions reflect *when* state existed,
    not merely when it arrived.
    """

    __slots__ = (
        "_latency_mean",
        "_latency_var",
        "_last_update",
    )

    def __init__(self):
        self._latency_mean: float = 0.0
        self._latency_var: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Update latency statistics
    # --------------------------------------------------------------------------

    def observe(self, measured_latency: float) -> None:
        """
        Observe a new latency sample.
        """
        l = float(max(measured_latency, 0.0))

        # Exponential moving statistics
        self._latency_mean = 0.9 * self._latency_mean + 0.1 * l
        self._latency_var = 0.9 * self._latency_var + 0.1 * (l - self._latency_mean) ** 2
        self._last_update = time.time()


    # --------------------------------------------------------------------------
    # Compensation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        state: Dict[str, Any],
        state_timestamp: float,
    ) -> Dict[str, Any]:
        """
        Apply temporal compensation to incoming state.
        """
        now = time.time()

        expected_latency = self._latency_mean + np.sqrt(self._latency_var)
        compensated_time = state_timestamp + expected_latency

        freshness = float(np.clip(
            1.0 - (now - compensated_time),
            0.0,
            1.0,
        ))

        return {
            "state": state,
            "compensated_timestamp": compensated_time,
            "freshness": freshness,
            "latency_mean": self._latency_mean,
            "latency_std": float(np.sqrt(self._latency_var)),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset latency compensation.
        """
        self._latency_mean = 0.0
        self._latency_var = 0.0
        self._last_update = time.time()


