from typing import Dict, Any
import time
import numpy as np


class DistributedSafetyConsensusEngine:
    """
    Distributed safety consensus engine.
    Aggregates safety assessments from multiple authoritative sources
    using trust-weighted consensus, preventing single-node hallucination
    or partial failure from triggering unsafe actions.
    """

    __slots__ = (
        "_trust_weights",
        "_last_consensus",
        "_last_update",
    )

    def __init__(self):
        self._trust_weights = {
            "flight_controller": 0.45,
            "edge_ai": 0.35,
            "cloud_ai": 0.20,
        }
        self._last_consensus: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Consensus logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        safety_reports: Dict[str, Dict[str, Any]],
    ) -> Dict[str, Any]:
        """
        Compute distributed safety consensus.
        """
        now = time.time()

        weighted_safe = 0.0
        weight_sum = 0.0

        for source, report in safety_reports.items():
            weight = self._trust_weights.get(source, 0.0)
            safe = float(report.get("safe", 1.0))
            weighted_safe += weight * safe
            weight_sum += weight

        consensus = (
            weighted_safe / weight_sum if weight_sum > 0.0 else 0.0
        )

        # Temporal smoothing prevents flip-flop
        self._last_consensus = float(np.clip(
            0.8 * self._last_consensus + 0.2 * consensus,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "safety_consensus": self._last_consensus,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset safety consensus engine.
        """
        self._last_consensus = 1.0
        self._last_update = time.time()


