from typing import Dict, Any, List
import time
import uuid


class MissionAuthorityAuditExplainabilityLog:
    """
    Mission authority audit & explainability log.
    Records causally-linked decision events with sufficient semantic
    context to reconstruct *why* an action occurred — not merely
    *what* happened — enabling compliance, debugging, and trust.
    """

    __slots__ = (
        "_events",
        "_session_id",
        "_last_update",
    )

    def __init__(self):
        self._events: List[Dict[str, Any]] = []
        self._session_id: str = str(uuid.uuid4())
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Logging primitives
    # --------------------------------------------------------------------------

    def record(
        self,
        event_type: str,
        data: Dict[str, Any],
        causal_refs: List[str] = None,
    ) -> Dict[str, Any]:
        """
        Record an explainable authority-related event.
        """
        now = time.time()

        event_id = str(uuid.uuid4())
        entry = {
            "event_id": event_id,
            "session_id": self._session_id,
            "timestamp": now,
            "type": event_type,
            "data": dict(data),
            "causal_refs": list(causal_refs or []),
        }

        self._events.append(entry)
        self._last_update = now

        return {
            "recorded_event": event_id,
            "timestamp": now,
        }


    # --------------------------------------------------------------------------
    # Query
    # --------------------------------------------------------------------------

    def export(self) -> Dict[str, Any]:
        """
        Export full audit log for review or persistence.
        """
        return {
            "session_id": self._session_id,
            "events": list(self._events),
            "count": len(self._events),
        }


    def reset(self) -> None:
        """
        Reset audit log (new session).
        """
        self._events.clear()
        self._session_id = str(uuid.uuid4())
        self._last_update = time.time()


