from typing import Dict, Any, List
import time
import numpy as np


class RegulatoryGeofenceComplianceCore:
    """
    Regulatory & geofence compliance core.
    Evaluates current and planned motion against hard constraints
    including altitude ceilings, no-fly zones, buffer corridors,
    and jurisdiction-specific operational limits.
    """

    __slots__ = (
        "_active_geofences",
        "_limits",
        "_last_update",
    )

    def __init__(
        self,
        geofences: List[Dict[str, Any]],
        limits: Dict[str, float],
    ):
        self._active_geofences = list(geofences)
        self._limits = dict(limits)
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Constraint evaluation
    # --------------------------------------------------------------------------

    def _check_altitude(self, altitude: float) -> bool:
        return altitude <= self._limits.get("max_altitude", float("inf"))


    def _check_geofence(self, position: Dict[str, float]) -> bool:
        """
        Check if position violates any active geofence.
        """
        for fence in self._active_geofences:
            if fence.get("type") == "circular":
                dx = position["lat"] - fence["lat"]
                dy = position["lon"] - fence["lon"]
                dist = np.sqrt(dx * dx + dy * dy)
                if dist <= fence.get("radius", 0.0):
                    return False
        return True


    # --------------------------------------------------------------------------
    # Update
    # --------------------------------------------------------------------------

    def apply(
        self,
        position: Dict[str, float],
        altitude: float,
        planned_motion: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Evaluate regulatory compliance.
        """
        now = time.time()

        altitude_ok = self._check_altitude(float(altitude))
        geofence_ok = self._check_geofence(position)

        compliant = altitude_ok and geofence_ok

        self._last_update = now

        return {
            "compliant": compliant,
            "altitude_ok": altitude_ok,
            "geofence_ok": geofence_ok,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset compliance core.
        """
        self._last_update = time.time()


