from typing import Dict, Any
import time
import numpy as np


class PreFlightReadinessArmingGate:
    """
    Pre-flight readiness & arming gate.
    Aggregates readiness signals across hardware, software, cognition,
    and regulatory domains to produce a single authoritative
    arm/deny decision with traceable reasons.
    """

    __slots__ = (
        "_ready",
        "_last_update",
    )

    def __init__(self):
        self._ready: bool = False
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Readiness evaluation
    # --------------------------------------------------------------------------

    def apply(
        self,
        sensor_health: Dict[str, bool],
        estimator_confidence: float,
        power_state: Dict[str, Any],
        link_state: Dict[str, Any],
        compliance_ok: bool,
        safety_consensus: float,
    ) -> Dict[str, Any]:
        """
        Evaluate pre-flight readiness.
        """
        now = time.time()

        sensors_ok = all(sensor_health.values())
        estimator_ok = estimator_confidence >= 0.7
        power_ok = power_state.get("battery_ok", False)
        link_ok = link_state.get("connected", False)
        safety_ok = safety_consensus >= 0.9

        self._ready = all([
            sensors_ok,
            estimator_ok,
            power_ok,
            link_ok,
            compliance_ok,
            safety_ok,
        ])

        self._last_update = now

        return {
            "ready_to_arm": self._ready,
            "checks": {
                "sensors": sensors_ok,
                "estimator": estimator_ok,
                "power": power_ok,
                "link": link_ok,
                "compliance": compliance_ok,
                "safety": safety_ok,
            },
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset readiness gate.
        """
        self._ready = False
        self._last_update = time.time()


