# CHUNK 86 BF 01 — DYNAMIC MISSION CONSTRAINT INJECTOR
# ==============================================================================
#
# Purpose:
#   Inject dynamic, context-aware constraints into mission planning
#   and execution based on environment, RF conditions, crowd density,
#   weather, and operational intent — before and during flight.
#
# Backbone truth:
#   A mission without context is a liability.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class DynamicMissionConstraintInjector:
    """
    Dynamic mission constraint injector.
    Continuously refines operational limits (speed, altitude, radius,
    aggressiveness) using real-world context signals so the Director
    AI operates inside a living envelope, not static assumptions.
    """

    __slots__ = (
        "_constraints",
        "_last_update",
    )

    def __init__(self):
        self._constraints: Dict[str, float] = {
            "max_speed": 1.0,
            "max_altitude": 1.0,
            "max_radius": 1.0,
            "motion_aggression": 1.0,
        }
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Constraint synthesis
    # --------------------------------------------------------------------------

    def apply(
        self,
        weather: Dict[str, float],
        rf_quality: float,
        crowd_density: float,
        mission_risk: float,
    ) -> Dict[str, Any]:
        """
        Update mission constraints from context.
        """
        now = time.time()

        wind = float(np.clip(weather.get("wind", 0.0), 0.0, 1.0))
        visibility = float(np.clip(weather.get("visibility", 1.0), 0.0, 1.0))
        rf = float(np.clip(rf_quality, 0.0, 1.0))
        crowd = float(np.clip(crowd_density, 0.0, 1.0))
        risk = float(np.clip(mission_risk, 0.0, 1.0))

        # Speed limited by wind, RF, and crowd
        self._constraints["max_speed"] = float(np.clip(
            1.0
            - 0.4 * wind
            - 0.3 * (1.0 - rf)
            - 0.3 * crowd,
            0.2,
            1.0,
        ))

        # Altitude limited by visibility and risk
        self._constraints["max_altitude"] = float(np.clip(
            0.5 + 0.5 * visibility - 0.4 * risk,
            0.2,
            1.0,
        ))

        # Radius limited by RF quality
        self._constraints["max_radius"] = float(np.clip(
            rf,
            0.3,
            1.0,
        ))

        # Motion aggression softened by crowd and risk
        self._constraints["motion_aggression"] = float(np.clip(
            1.0 - 0.5 * crowd - 0.4 * risk,
            0.1,
            1.0,
        ))

        self._last_update = now

        return {
            "constraints": dict(self._constraints),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset dynamic constraints.
        """
        self._constraints = {
            "max_speed": 1.0,
            "max_altitude": 1.0,
            "max_radius": 1.0,
            "motion_aggression": 1.0,
        }
        self._last_update = time.time()


