# CHUNK 86 BG 01 — LAUNCH AUTHORIZATION & COUNTDOWN CONTROLLER
# ==============================================================================
#
# Purpose:
#   Coordinate final launch authorization and countdown sequencing,
#   ensuring synchronized readiness, late-fault abort capability,
#   and disciplined transition from idle to flight.
#
# Backbone truth:
#   Takeoff is a protocol, not an impulse.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class LaunchAuthorizationCountdownController:
    """
    Launch authorization & countdown controller.
    Manages the final pre-launch window with explicit states,
    synchronized timing, and continuous abort evaluation so
    no unsafe transition is ever forced.
    """

    __slots__ = (
        "_authorized",
        "_countdown",
        "_state",
        "_last_update",
    )

    def __init__(self, countdown_seconds: float = 5.0):
        self._authorized: bool = False
        self._countdown: float = float(max(countdown_seconds, 2.0))
        self._state: str = "idle"   # idle | armed | counting | launched | aborted
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Countdown logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        ready_to_arm: bool,
        safety_consensus: float,
        abort_signal: bool,
    ) -> Dict[str, Any]:
        """
        Evaluate launch authorization and manage countdown.
        """
        now = time.time()

        # Abort overrides everything
        if abort_signal or safety_consensus < 0.8:
            self._state = "aborted"
            self._authorized = False
            self._countdown = 0.0
            self._last_update = now
            return {
                "state": self._state,
                "authorized": False,
                "countdown": 0.0,
                "timestamp": now,
            }

        # Idle → Armed
        if self._state == "idle" and ready_to_arm:
            self._state = "armed"
            self._authorized = True

        # Armed → Counting
        if self._state == "armed":
            self._state = "counting"

        # Countdown progression
        if self._state == "counting":
            self._countdown = max(self._countdown - 0.1, 0.0)
            if self._countdown <= 0.0:
                self._state = "launched"

        self._last_update = now

        return {
            "state": self._state,
            "authorized": self._authorized,
            "countdown": self._countdown,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset launch controller.
        """
        self._authorized = False
        self._countdown = 0.0
        self._state = "idle"
        self._last_update = time.time()


