# CHUNK 86 BH 01 — TAKEOFF TRAJECTORY & INITIAL STABILIZATION DIRECTOR
# ==============================================================================
#
# Purpose:
#   Shape the first seconds of flight by coordinating thrust ramp,
#   vertical trajectory, attitude damping, and camera stabilization
#   so takeoff is safe, smooth, and cinematographically intentional.
#
# Backbone truth:
#   The first 3 seconds define perceived aircraft quality.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class TakeoffTrajectoryInitialStabilizationDirector:
    """
    Takeoff trajectory & initial stabilization director.
    Coordinates thrust ramp, climb profile, and early attitude
    damping while synchronizing camera stabilization so ascent
    feels controlled, premium, and intention-driven.
    """

    __slots__ = (
        "_phase",
        "_thrust_level",
        "_start_time",
        "_last_update",
    )

    def __init__(self):
        self._phase: str = "idle"   # idle | ramp | lift | stabilize
        self._thrust_level: float = 0.0
        self._start_time: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Takeoff shaping logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        altitude: float,
        vertical_velocity: float,
        attitude_error: Dict[str, float],
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Direct takeoff trajectory and stabilization.
        """
        now = time.time()

        if self._phase == "idle":
            self._phase = "ramp"
            self._start_time = now

        elapsed = now - self._start_time

        # Phase transitions
        if self._phase == "ramp" and elapsed > 0.8:
            self._phase = "lift"

        if self._phase == "lift" and altitude > 1.2:
            self._phase = "stabilize"

        # Thrust shaping
        if self._phase == "ramp":
            self._thrust_level = float(np.clip(
                self._thrust_level + 0.05 * autonomy_level,
                0.0,
                0.6,
            ))

        elif self._phase == "lift":
            self._thrust_level = float(np.clip(
                0.6 + 0.2 * (1.0 - np.clip(abs(vertical_velocity), 0.0, 1.0)),
                0.6,
                0.85,
            ))

        elif self._phase == "stabilize":
            self._thrust_level = float(np.clip(
                0.7 - 0.1 * np.linalg.norm(list(attitude_error.values())),
                0.5,
                0.75,
            ))

        self._last_update = now

        return {
            "phase": self._phase,
            "thrust": self._thrust_level,
            "stabilization_gain": float(np.clip(
                1.0 - 0.5 * autonomy_level,
                0.4,
                1.0,
            )),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset takeoff director.
        """
        self._phase = "idle"
        self._thrust_level = 0.0
        self._start_time = 0.0
        self._last_update = time.time()


