# ==============================================================================
# CHUNK 86 BI 01 — EARLY-FLIGHT ANOMALY DETECTION CORE
# ==============================================================================
#
# Purpose:
#   Detect subtle but dangerous anomalies during the first seconds
#   of flight (sensor drift, thrust imbalance, wind shear, estimator
#   divergence) before they escalate into instability or visible error.
#
# Backbone truth:
#   Early anomalies whisper before they scream.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class EarlyFlightAnomalyDetectionCore:
    """
    Early-flight anomaly detection core.
    Fuses IMU consistency, motor symmetry, velocity residuals,
    and estimator confidence to produce a graded anomaly score
    with semantic classification.
    """

    __slots__ = (
        "_baseline",
        "_anomaly_score",
        "_last_update",
    )

    def __init__(self):
        self._baseline: Dict[str, float] = {}
        self._anomaly_score: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Baseline initialization
    # --------------------------------------------------------------------------

    def initialize_baseline(
        self,
        imu_stats: Dict[str, float],
        motor_stats: Dict[str, float],
    ) -> None:
        """
        Capture baseline statistics during stable hover.
        """
        self._baseline = {
            "imu_var": imu_stats.get("variance", 0.0),
            "motor_balance": motor_stats.get("balance", 0.0),
        }
        self._anomaly_score = 0.0
        self._last_update = time.time()


    # --------------------------------------------------------------------------
    # Detection logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        imu_stats: Dict[str, float],
        motor_stats: Dict[str, float],
        velocity_residual: float,
        estimator_confidence: float,
    ) -> Dict[str, Any]:
        """
        Evaluate early-flight anomalies.
        """
        now = time.time()

        imu_var = float(imu_stats.get("variance", 0.0))
        motor_balance = float(motor_stats.get("balance", 0.0))
        vel_res = float(abs(velocity_residual))
        conf = float(np.clip(estimator_confidence, 0.0, 1.0))

        imu_dev = abs(imu_var - self._baseline.get("imu_var", imu_var))
        motor_dev = abs(motor_balance - self._baseline.get("motor_balance", motor_balance))

        # Weighted anomaly synthesis
        score = (
            0.35 * np.clip(imu_dev, 0.0, 1.0)
            + 0.35 * np.clip(motor_dev, 0.0, 1.0)
            + 0.20 * np.clip(vel_res, 0.0, 1.0)
            + 0.10 * (1.0 - conf)
        )

        # Temporal smoothing
        self._anomaly_score = float(np.clip(
            0.85 * self._anomaly_score + 0.15 * score,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "anomaly_score": self._anomaly_score,
            "severity": (
                "none" if self._anomaly_score < 0.2 else
                "minor" if self._anomaly_score < 0.4 else
                "moderate" if self._anomaly_score < 0.7 else
                "critical"
            ),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset anomaly detector.
        """
        self._baseline.clear()
        self._anomaly_score = 0.0
        self._last_update = time.time()


