# END OF CHUNK 86 BI 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 BJ 01 — CLIMB PHASE ENERGY & EXPOSURE HARMONIZER
# ==============================================================================
#
# Purpose:
#   Harmonize mechanical climb energy with camera exposure, tone,
#   and contrast so ascent appears powerful yet controlled, avoiding
#   highlight blowout, contrast pumping, or visual harshness.
#
# Backbone truth:
#   Power without restraint reads as chaos on camera.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class ClimbPhaseEnergyExposureHarmonizer:
    """
    Climb phase energy & exposure harmonizer.
    Couples thrust energy, vertical acceleration, and scene luminance
    to shape exposure, contrast, and tone curves dynamically during
    climb — preserving cinematic smoothness under rising power.
    """

    __slots__ = (
        "_energy_memory",
        "_last_update",
    )

    def __init__(self):
        self._energy_memory: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Harmonization logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        thrust_level: float,
        vertical_accel: float,
        avg_luma: float,
        scene_contrast: float,
    ) -> Dict[str, Any]:
        """
        Harmonize climb energy with exposure and tone.
        """
        now = time.time()

        thrust = float(np.clip(thrust_level, 0.0, 1.0))
        accel = float(np.clip(abs(vertical_accel), 0.0, 1.0))
        luma = float(np.clip(avg_luma, 0.0, 1.0))
        contrast = float(np.clip(scene_contrast, 0.0, 1.0))

        # Energy synthesis (mechanical intensity)
        energy = 0.6 * thrust + 0.4 * accel

        # Temporal smoothing prevents exposure jitter
        self._energy_memory = float(np.clip(
            0.85 * self._energy_memory + 0.15 * energy,
            0.0,
            1.0,
        ))

        # Exposure dampening under high energy
        exposure_bias = float(np.clip(
            -0.3 * self._energy_memory * (1.0 - luma),
            -0.4,
            0.0,
        ))

        # Contrast shaping to preserve highlight rolloff
        contrast_scale = float(np.clip(
            1.0 - 0.25 * self._energy_memory * contrast,
            0.75,
            1.0,
        ))

        self._last_update = now

        return {
            "energy_level": self._energy_memory,
            "exposure_bias": exposure_bias,
            "contrast_scale": contrast_scale,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset harmonizer.
        """
        self._energy_memory = 0.0
        self._last_update = time.time()


