# ==============================================================================
# ==============================================================================
# CHUNK 86 BK 01 — CAMERA–MOTION COUPLING DURING ASCENT
# ==============================================================================
#
# Purpose:
#   Couple camera orientation, stabilization strength, and framing
#   directly to ascent motion vectors so camera behavior leads motion
#   perceptually instead of lagging behind physics.
#
# Backbone truth:
#   Great camera work anticipates motion — it does not chase it.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class CameraMotionCouplingDuringAscent:
    """
    Camera–motion coupling during ascent.
    Maps vertical velocity, acceleration, and attitude change into
    camera pitch bias, stabilization damping, and framing offset so
    ascent feels intentional, smooth, and premium.
    """

    __slots__ = (
        "_pitch_bias",
        "_stabilization_gain",
        "_last_update",
    )

    def __init__(self):
        self._pitch_bias: float = 0.0
        self._stabilization_gain: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Coupling logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        vertical_velocity: float,
        vertical_accel: float,
        attitude_rate: Dict[str, float],
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Compute camera coupling parameters during ascent.
        """
        now = time.time()

        vel = float(np.clip(vertical_velocity, -1.0, 1.0))
        accel = float(np.clip(vertical_accel, -1.0, 1.0))
        pitch_rate = float(attitude_rate.get("pitch", 0.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Predictive pitch bias (camera leads ascent)
        target_pitch = float(np.clip(
            0.25 * vel + 0.15 * accel,
            -0.3,
            0.3,
        ))

        self._pitch_bias = float(
            0.8 * self._pitch_bias + 0.2 * target_pitch
        )

        # Stabilization relaxes slightly with confident autonomy
        base_stab = float(np.clip(
            1.0 - 0.3 * abs(pitch_rate),
            0.5,
            1.0,
        ))

        self._stabilization_gain = float(np.clip(
            0.9 * self._stabilization_gain
            + 0.1 * (base_stab * (0.7 + 0.3 * auto)),
            0.4,
            1.0,
        ))

        self._last_update = now

        return {
            "camera_pitch_bias": self._pitch_bias,
            "stabilization_gain": self._stabilization_gain,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset camera–motion coupling.
        """
        self._pitch_bias = 0.0
        self._stabilization_gain = 1.0
        self._last_update = time.time()


