# CHUNK 86 BL 01 — EARLY-FLIGHT ABORT & RECOVERY DIRECTOR
# ==============================================================================
#
# Purpose:
#   Orchestrate graceful abort and recovery during early flight,
#   prioritizing aircraft stability, camera continuity, and
#   perceptual smoothness instead of abrupt termination.
#
# Backbone truth:
#   Aborting well is harder than taking off.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class EarlyFlightAbortRecoveryDirector:
    """
    Early-flight abort & recovery director.
    Converts anomaly severity and safety consensus into a staged
    recovery plan (soft arrest, hover recovery, controlled descent)
    while maintaining camera stabilization and exposure continuity.
    """

    __slots__ = (
        "_mode",
        "_recovery_gain",
        "_camera_hold",
        "_last_update",
    )

    def __init__(self):
        self._mode: str = "none"   # none | arrest | hover | descend | land
        self._recovery_gain: float = 0.0
        self._camera_hold: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Abort & recovery logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        anomaly_score: float,
        safety_consensus: float,
        altitude: float,
        vertical_velocity: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Determine abort/recovery behavior during early flight.
        """
        now = time.time()

        a = float(np.clip(anomaly_score, 0.0, 1.0))
        safety = float(np.clip(safety_consensus, 0.0, 1.0))
        alt = float(max(altitude, 0.0))
        vel = float(np.clip(vertical_velocity, -2.0, 2.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Mode selection (graded, not binary)
        if safety < 0.4 or a > 0.85:
            self._mode = "land"
        elif a > 0.65:
            self._mode = "descend"
        elif a > 0.4:
            self._mode = "hover"
        elif a > 0.25:
            self._mode = "arrest"
        else:
            self._mode = "none"

        # Recovery gain scales with severity and autonomy
        target_gain = float(np.clip(
            a * (0.6 + 0.4 * auto),
            0.0,
            1.0,
        ))

        self._recovery_gain = float(
            0.85 * self._recovery_gain + 0.15 * target_gain
        )

        # Camera hold prevents visual shock during abort
        self._camera_hold = float(np.clip(
            1.0 - 0.5 * self._recovery_gain,
            0.5,
            1.0,
        ))

        self._last_update = now

        return {
            "mode": self._mode,
            "recovery_gain": self._recovery_gain,
            "camera_hold": self._camera_hold,
            "recommended_vertical_command": float(np.clip(
                -self._recovery_gain * (1.0 + alt * 0.1),
                -1.0,
                0.0,
            )),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset abort & recovery director.
        """
        self._mode = "none"
        self._recovery_gain = 0.0
        self._camera_hold = 1.0
        self._last_update = time.time()


