from typing import Dict, Any
import time
import numpy as np


class TransitionToCruisePhaseCoordinator:
    """
    Transition-to-cruise phase coordinator.
    Blends out climb dynamics, re-centers stabilization, and hands off
    authority to cruise controllers while preserving camera continuity
    and emotional momentum.
    """

    __slots__ = (
        "_blend",
        "_cruise_ready",
        "_last_update",
    )

    def __init__(self):
        self._blend: float = 0.0
        self._cruise_ready: bool = False
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Transition logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        altitude: float,
        vertical_velocity: float,
        anomaly_score: float,
        energy_level: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Blend climb into cruise.
        """
        now = time.time()

        alt = float(max(altitude, 0.0))
        vel = float(abs(vertical_velocity))
        anomaly = float(np.clip(anomaly_score, 0.0, 1.0))
        energy = float(np.clip(energy_level, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Conditions for cruise eligibility
        eligible = (
            alt > 3.0
            and vel < 0.3
            and anomaly < 0.3
        )

        # Blend rate depends on stability and autonomy
        rate = 0.05 + 0.1 * auto

        if eligible:
            self._blend = float(np.clip(
                self._blend + rate * (1.0 - energy),
                0.0,
                1.0,
            ))
        else:
            self._blend = float(np.clip(
                self._blend - 0.1,
                0.0,
                1.0,
            ))

        self._cruise_ready = self._blend >= 0.95
        self._last_update = now

        return {
            "transition_blend": self._blend,
            "cruise_ready": self._cruise_ready,
            "control_softening": float(np.clip(
                1.0 - 0.6 * self._blend,
                0.4,
                1.0,
            )),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cruise transition coordinator.
        """
        self._blend = 0.0
        self._cruise_ready = False
        self._last_update = time.time()


