from typing import Dict, Any
import time
import numpy as np


class CruiseEntryCinematicRecomposition:
    """
    Cruise entry cinematic recomposition.
    Expands framing, rebalances exposure and tone, and resets
    camera–motion relationships to stabilize visual flow after
    climb, while maintaining emotional continuity.
    """

    __slots__ = (
        "_framing_bias",
        "_exposure_rebalance",
        "_color_tone_shift",
        "_motion_damp",
        "_last_update",
    )

    def __init__(self):
        self._framing_bias: float = 0.0
        self._exposure_rebalance: float = 0.0
        self._color_tone_shift: float = 0.0
        self._motion_damp: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Recomposition logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        transition_blend: float,
        energy_level: float,
        emotional_momentum: float,
        avg_luma: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Recompose cinematic parameters upon entering cruise.
        """
        now = time.time()

        blend = float(np.clip(transition_blend, 0.0, 1.0))
        energy = float(np.clip(energy_level, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        luma = float(np.clip(avg_luma, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Framing expands gradually as tension dissipates
        self._framing_bias = float(
            0.9 * self._framing_bias + 0.1 * (0.3 * blend - 0.2 * energy)
        )

        # Exposure rebalances to neutral tone
        self._exposure_rebalance = float(
            0.85 * self._exposure_rebalance + 0.15 * (0.4 * (1.0 - luma))
        )

        # Emotional tone tinting (subtle)
        self._color_tone_shift = float(
            0.9 * self._color_tone_shift + 0.1 * (0.2 * emotion - 0.1 * blend)
        )

        # Motion damping relaxes proportional to stability
        self._motion_damp = float(np.clip(
            1.0 - 0.3 * blend * auto,
            0.6,
            1.0,
        ))

        self._last_update = now

        return {
            "framing_bias": self._framing_bias,
            "exposure_rebalance": self._exposure_rebalance,
            "color_tone_shift": self._color_tone_shift,
            "motion_damp": self._motion_damp,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cinematic recomposition.
        """
        self._framing_bias = 0.0
        self._exposure_rebalance = 0.0
        self._color_tone_shift = 0.0
        self._motion_damp = 1.0
        self._last_update = time.time()


