from typing import Dict, Any
import time
import numpy as np


class CruiseStabilityEnergyOptimizer:
    """
    Cruise stability & energy optimizer.
    Minimizes unnecessary control activity, damps micro-oscillations,
    and adapts cruise aggressiveness to battery state, wind load, and
    narrative pacing so flight feels calm, efficient, and premium.
    """

    __slots__ = (
        "_stability_bias",
        "_energy_bias",
        "_last_update",
    )

    def __init__(self):
        self._stability_bias: float = 1.0
        self._energy_bias: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Optimization logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        attitude_error: Dict[str, float],
        wind_load: float,
        battery_level: float,
        emotional_momentum: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Optimize cruise stability and energy usage.
        """
        now = time.time()

        err = float(np.linalg.norm(list(attitude_error.values())))
        wind = float(np.clip(wind_load, 0.0, 1.0))
        battery = float(np.clip(battery_level, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Stability bias increases when attitude error or wind rises
        target_stability = float(np.clip(
            1.0 + 0.6 * err + 0.4 * wind,
            1.0,
            2.0,
        ))

        self._stability_bias = float(
            0.9 * self._stability_bias + 0.1 * target_stability
        )

        # Energy bias tightens with low battery and low narrative urgency
        target_energy = float(np.clip(
            0.5 + 0.5 * battery - 0.3 * (1.0 - emotion),
            0.3,
            1.0,
        ))

        self._energy_bias = float(
            0.9 * self._energy_bias + 0.1 * target_energy
        )

        self._last_update = now

        return {
            "stability_gain": self._stability_bias * (0.7 + 0.3 * auto),
            "energy_conservation": self._energy_bias,
            "control_softening": float(np.clip(
                1.0 - 0.4 * (1.0 - self._energy_bias),
                0.6,
                1.0,
            )),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cruise optimizer.
        """
        self._stability_bias = 1.0
        self._energy_bias = 1.0
        self._last_update = time.time()


