# Purpose:
#   Plan motion across extended temporal horizons (tens of seconds
#   to minutes), shaping velocity, curvature, altitude, and pacing
#   as a coherent cinematic arc rather than reactive frame-to-frame
#   corrections.
#
# Backbone truth:
#   Cinema happens over time, not ticks.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import numpy as np


class LongArcMotionPlanningCore:
    """
    Long-arc motion planning core.
    Synthesizes future-aware motion envelopes using narrative intent,
    energy budgets, environmental constraints, and subject dynamics
    so flight evolves with purpose instead of reacting to noise.
    """

    __slots__ = (
        "_horizon",
        "_arc_state",
        "_last_update",
    )

    def __init__(self, horizon_seconds: float = 30.0):
        self._horizon: float = float(np.clip(horizon_seconds, 10.0, 120.0))
        self._arc_state: Dict[str, float] = {
            "speed_bias": 0.5,
            "curvature_bias": 0.0,
            "altitude_bias": 0.0,
            "pacing": 0.5,
        }
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Planning logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        narrative_phase: str,
        emotional_momentum: float,
        subject_dynamics: Dict[str, float],
        environment: Dict[str, float],
        energy_constraints: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Plan long-arc motion parameters.
        """
        now = time.time()

        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        subject_speed = float(np.clip(subject_dynamics.get("speed", 0.0), 0.0, 1.0))
        subject_turn = float(np.clip(subject_dynamics.get("turn_rate", 0.0), 0.0, 1.0))
        wind = float(np.clip(environment.get("wind", 0.0), 0.0, 1.0))
        battery = float(np.clip(energy_constraints.get("battery", 1.0), 0.0, 1.0))

        # Narrative pacing map
        phase_pacing = {
            "setup": 0.4,
            "development": 0.6,
            "climax": 0.8,
            "resolution": 0.3,
        }.get(narrative_phase, 0.5)

        # Speed bias considers emotion, subject, and energy
        target_speed = float(np.clip(
            0.3 * phase_pacing
            + 0.3 * emotion
            + 0.2 * subject_speed
            - 0.2 * (1.0 - battery),
            0.2,
            1.0,
        ))

        # Curvature bias reflects subject turning and wind
        target_curvature = float(np.clip(
            0.6 * subject_turn - 0.4 * wind,
            -1.0,
            1.0,
        ))

        # Altitude bias drifts with emotional openness
        target_altitude = float(np.clip(
            0.4 * emotion - 0.2 * wind,
            -0.5,
            0.5,
        ))

        # Temporal smoothing (long horizon)
        self._arc_state["speed_bias"] = float(
            0.9 * self._arc_state["speed_bias"] + 0.1 * target_speed
        )
        self._arc_state["curvature_bias"] = float(
            0.9 * self._arc_state["curvature_bias"] + 0.1 * target_curvature
        )
        self._arc_state["altitude_bias"] = float(
            0.9 * self._arc_state["altitude_bias"] + 0.1 * target_altitude
        )
        self._arc_state["pacing"] = float(
            0.85 * self._arc_state["pacing"] + 0.15 * phase_pacing
        )

        self._last_update = now

        return {
            "arc": dict(self._arc_state),
            "horizon_seconds": self._horizon,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset long-arc planner.
        """
        self._arc_state = {
            "speed_bias": 0.5,
            "curvature_bias": 0.0,
            "altitude_bias": 0.0,
            "pacing": 0.5,
        }
        self._last_update = time.time()


