# CHUNK 86 BQ 01 — CRUISE CINEMATIC ADAPTATION TO LIGHT AND SCENE
# ==============================================================================
#
# Purpose:
#   Adapt cinematic tone, exposure, contrast, and color response
#   dynamically during cruise based on evolving light conditions,
#   cloud cover, sun angle, terrain reflectance, and narrative beat.
#
# Backbone truth:
#   Light is a moving character, not a constant.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class CruiseCinematicAdaptationToLightAndScene:
    """
    Cruise cinematic adaptation to light and scene.
    Modulates exposure bias, highlight rolloff, contrast curve,
    and color temperature during cruise so imagery breathes
    with natural light transitions without perceptual pumping.
    """

    __slots__ = (
        "_exposure_bias",
        "_contrast_curve",
        "_color_temp_shift",
        "_highlight_softness",
        "_last_update",
    )

    def __init__(self):
        self._exposure_bias: float = 0.0
        self._contrast_curve: float = 1.0
        self._color_temp_shift: float = 0.0
        self._highlight_softness: float = 0.5
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Adaptation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        sun_angle: float,
        cloud_cover: float,
        terrain_albedo: float,
        avg_luma: float,
        emotional_momentum: float,
    ) -> Dict[str, Any]:
        """
        Adapt cinematic parameters to light and scene.
        """
        now = time.time()

        sun = float(np.clip(sun_angle, 0.0, 1.0))
        cloud = float(np.clip(cloud_cover, 0.0, 1.0))
        albedo = float(np.clip(terrain_albedo, 0.0, 1.0))
        luma = float(np.clip(avg_luma, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))

        # Exposure bias compensates for clouds and reflective terrain
        target_exposure = (
            -0.2 * cloud
            + 0.2 * (albedo - 0.5)
            - 0.1 * (luma - 0.5)
        )

        self._exposure_bias = float(
            0.9 * self._exposure_bias + 0.1 * target_exposure
        )

        # Contrast softens under cloud cover, firms with emotional intensity
        target_contrast = float(np.clip(
            1.0 - 0.3 * cloud + 0.2 * emotion,
            0.7,
            1.2,
        ))

        self._contrast_curve = float(
            0.9 * self._contrast_curve + 0.1 * target_contrast
        )

        # Color temperature drifts warmer near horizon, cooler under clouds
        target_temp = float(
            0.3 * (1.0 - sun) - 0.2 * cloud
        )

        self._color_temp_shift = float(
            0.95 * self._color_temp_shift + 0.05 * target_temp
        )

        # Highlight softness increases with cloud and low sun
        target_softness = float(np.clip(
            0.4 + 0.4 * cloud + 0.2 * (1.0 - sun),
            0.3,
            0.9,
        ))

        self._highlight_softness = float(
            0.9 * self._highlight_softness + 0.1 * target_softness
        )

        self._last_update = now

        return {
            "exposure_bias": self._exposure_bias,
            "contrast_curve": self._contrast_curve,
            "color_temp_shift": self._color_temp_shift,
            "highlight_softness": self._highlight_softness,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset light & scene adaptation.
        """
        self._exposure_bias = 0.0
        self._contrast_curve = 1.0
        self._color_temp_shift = 0.0
        self._highlight_softness = 0.5
        self._last_update = time.time()


