# CHUNK 86 BR 01 — SUBJECT-ORIENTED FRAMING INTELLIGENCE (CRUISE)
# ==============================================================================
#
# Purpose:
#   Maintain cinematic dominance of primary subjects during cruise
#   by dynamically biasing framing, crop, and camera orientation
#   based on subject salience, motion intent, and narrative priority.
#
# Backbone truth:
#   Composition is a decision — not a default.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class SubjectOrientedFramingIntelligence:
    """
    Subject-oriented framing intelligence (cruise).
    Preserves subject prominence through adaptive framing bias,
    anticipatory crop offsets, and motion-aligned composition so
    subjects feel intentionally filmed, not merely tracked.
    """

    __slots__ = (
        "_framing_offset",
        "_crop_bias",
        "_lead_bias",
        "_last_update",
    )

    def __init__(self):
        self._framing_offset: np.ndarray = np.zeros(2)
        self._crop_bias: float = 0.0
        self._lead_bias: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Framing logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        subject_state: Dict[str, float],
        scene_salience: float,
        emotional_momentum: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Compute subject-oriented framing adjustments.
        """
        now = time.time()

        # Subject metrics
        subj_x = float(np.clip(subject_state.get("x", 0.0), -1.0, 1.0))
        subj_y = float(np.clip(subject_state.get("y", 0.0), -1.0, 1.0))
        subj_vel = float(np.clip(subject_state.get("velocity", 0.0), 0.0, 1.0))
        subj_priority = float(np.clip(subject_state.get("priority", 0.5), 0.0, 1.0))

        salience = float(np.clip(scene_salience, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Anticipatory lead based on subject motion
        target_lead = float(np.clip(
            0.4 * subj_vel * subj_priority,
            0.0,
            0.4,
        ))

        self._lead_bias = float(
            0.85 * self._lead_bias + 0.15 * target_lead
        )

        # Framing offset favors subject + narrative salience
        target_offset = np.array([
            subj_x + self._lead_bias * np.sign(subj_x),
            subj_y * (0.7 + 0.3 * emotion),
        ])

        self._framing_offset = (
            0.85 * self._framing_offset + 0.15 * target_offset
        )

        # Crop bias tightens with subject importance and emotional focus
        target_crop = float(np.clip(
            0.2 * subj_priority + 0.2 * salience + 0.2 * emotion,
            0.0,
            0.6,
        ))

        self._crop_bias = float(
            0.9 * self._crop_bias + 0.1 * target_crop
        )

        self._last_update = now

        return {
            "framing_offset": self._framing_offset.tolist(),
            "crop_bias": self._crop_bias * (0.7 + 0.3 * auto),
            "lead_bias": self._lead_bias,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset subject framing intelligence.
        """
        self._framing_offset = np.zeros(2)
        self._crop_bias = 0.0
        self._lead_bias = 0.0
        self._last_update = time.time()


