from typing import Dict, Any, List
import time
import numpy as np


class PredictiveObstacleCorridorAnticipation:
    """
    Predictive obstacle & corridor anticipation.
    Fuses depth sensing, optical flow divergence, map hints,
    and motion prediction to estimate future spatial risk
    and corridor tightness across a short temporal horizon.
    """

    __slots__ = (
        "_risk_memory",
        "_corridor_width",
        "_last_update",
    )

    def __init__(self):
        self._risk_memory: float = 0.0
        self._corridor_width: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Anticipation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        depth_min: float,
        optical_flow_divergence: float,
        predicted_path_curvature: float,
        map_corridor_hint: float,
        velocity: float,
    ) -> Dict[str, Any]:
        """
        Anticipate obstacles and spatial corridors.
        """
        now = time.time()

        depth = float(np.clip(depth_min, 0.0, 1.0))
        flow = float(np.clip(optical_flow_divergence, 0.0, 1.0))
        curvature = float(np.clip(abs(predicted_path_curvature), 0.0, 1.0))
        map_hint = float(np.clip(map_corridor_hint, 0.0, 1.0))
        vel = float(np.clip(velocity, 0.0, 1.0))

        # Risk rises with low depth, high flow divergence, tight curvature
        instantaneous_risk = float(np.clip(
            0.4 * (1.0 - depth)
            + 0.3 * flow
            + 0.2 * curvature
            + 0.1 * vel,
            0.0,
            1.0,
        ))

        # Temporal risk accumulation (anticipatory, not reactive)
        self._risk_memory = float(np.clip(
            0.8 * self._risk_memory + 0.2 * instantaneous_risk,
            0.0,
            1.0,
        ))

        # Corridor width estimation blends perception and map hints
        target_corridor = float(np.clip(
            0.6 * depth + 0.4 * map_hint - 0.3 * curvature,
            0.1,
            1.0,
        ))

        self._corridor_width = float(
            0.85 * self._corridor_width + 0.15 * target_corridor
        )

        self._last_update = now

        return {
            "spatial_risk": self._risk_memory,
            "corridor_width": self._corridor_width,
            "recommended_speed_scale": float(np.clip(
                1.0 - 0.6 * self._risk_memory,
                0.4,
                1.0,
            )),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset obstacle & corridor anticipation.
        """
        self._risk_memory = 0.0
        self._corridor_width = 1.0
        self._last_update = time.time()


