# CHUNK 86 BU 01 — MULTI-SUBJECT PRIORITY ARBITRATION
# ==============================================================================
#
# Purpose:
#   Decide, at every moment, which subject deserves cinematic
#   priority when multiple subjects compete for attention,
#   using narrative relevance, motion intent, emotional context,
#   and spatial composition — not just detection confidence.
#
# Backbone truth:
#   Attention is a choice, not a coincidence.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import numpy as np


class MultiSubjectPriorityArbitration:
    """
    Multi-subject priority arbitration.
    Scores and ranks detected subjects based on narrative intent,
    emotional salience, motion dominance, and compositional value,
    allowing the Director AI to shift focus deliberately.
    """

    __slots__ = (
        "_active_subject_id",
        "_priority_memory",
        "_last_update",
    )

    def __init__(self):
        self._active_subject_id: Any = None
        self._priority_memory: Dict[Any, float] = {}
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Arbitration logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        subjects: List[Dict[str, Any]],
        narrative_phase: str,
        emotional_momentum: float,
        framing_context: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Select primary subject.
        """
        now = time.time()

        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        center_bias = float(np.clip(framing_context.get("center_bias", 0.0), 0.0, 1.0))

        phase_weight = {
            "setup": 0.3,
            "development": 0.5,
            "climax": 0.8,
            "resolution": 0.2,
        }.get(narrative_phase, 0.4)

        scores: Dict[Any, float] = {}

        for subj in subjects:
            sid = subj.get("id")
            priority = float(np.clip(subj.get("priority", 0.5), 0.0, 1.0))
            motion = float(np.clip(subj.get("motion", 0.0), 0.0, 1.0))
            salience = float(np.clip(subj.get("salience", 0.0), 0.0, 1.0))
            distance = float(np.clip(subj.get("distance", 1.0), 0.0, 1.0))

            score = (
                0.35 * priority
                + 0.25 * salience
                + 0.2 * motion
                + 0.1 * emotion
                + 0.1 * (1.0 - distance)
            ) * (0.6 + 0.4 * phase_weight)

            # Temporal inertia prevents flicker
            prev = self._priority_memory.get(sid, score)
            score = 0.8 * prev + 0.2 * score

            scores[sid] = score
            self._priority_memory[sid] = score

        # Select subject with highest score
        if scores:
            self._active_subject_id = max(scores, key=scores.get)

        self._last_update = now

        return {
            "active_subject_id": self._active_subject_id,
            "subject_scores": scores,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset subject arbitration.
        """
        self._active_subject_id = None
        self._priority_memory.clear()
        self._last_update = time.time()


