# ==============================================================================
#
# Purpose:
#   Refine motion, curvature, and pacing when flying through
#   spatially constrained corridors so tight environments feel
#   intentional, fluid, and cinematic rather than cautious or robotic.
#
# Backbone truth:
#   Constraint reveals style.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class CorridorAwareMotionRefinement:
    """
    Corridor-aware motion refinement.
    Shapes velocity scaling, turn anticipation, and micro-trajectory
    smoothing based on predicted corridor width and spatial risk,
    preserving visual confidence in tight spaces.
    """

    __slots__ = (
        "_speed_scale",
        "_curvature_softening",
        "_lateral_bias",
        "_last_update",
    )

    def __init__(self):
        self._speed_scale: float = 1.0
        self._curvature_softening: float = 1.0
        self._lateral_bias: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Refinement logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        corridor_width: float,
        spatial_risk: float,
        path_curvature: float,
        emotional_momentum: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Refine motion parameters inside corridors.
        """
        now = time.time()

        width = float(np.clip(corridor_width, 0.0, 1.0))
        risk = float(np.clip(spatial_risk, 0.0, 1.0))
        curvature = float(np.clip(abs(path_curvature), 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Speed scales down with narrowing corridors, but emotion resists slowdown
        target_speed = float(np.clip(
            0.6 * width + 0.3 * (1.0 - risk) + 0.2 * emotion,
            0.3,
            1.0,
        ))

        self._speed_scale = float(
            0.85 * self._speed_scale + 0.15 * target_speed
        )

        # Curvature softening prevents twitchy steering in tight spaces
        target_softening = float(np.clip(
            1.0 - 0.6 * curvature * (1.0 - width),
            0.4,
            1.0,
        ))

        self._curvature_softening = float(
            0.9 * self._curvature_softening + 0.1 * target_softening
        )

        # Lateral bias recenters aircraft visually in corridor
        target_lateral = float(np.clip(
            (0.5 - width) * 0.4 * auto,
            -0.2,
            0.2,
        ))

        self._lateral_bias = float(
            0.9 * self._lateral_bias + 0.1 * target_lateral
        )

        self._last_update = now

        return {
            "speed_scale": self._speed_scale,
            "curvature_softening": self._curvature_softening,
            "lateral_bias": self._lateral_bias,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset corridor-aware refinement.
        """
        self._speed_scale = 1.0
        self._curvature_softening = 1.0
        self._lateral_bias = 0.0
        self._last_update = time.time()


