from typing import Dict, Any
import time
import numpy as np


class CruiseToEngagementTransitionLogic:
    """
    Cruise-to-engagement transition logic.
    Detects rising narrative relevance and subject convergence,
    then preconditions camera, motion cadence, and framing so
    engagement feels intentional instead of reactive.
    """

    __slots__ = (
        "_engage_blend",
        "_compression_bias",
        "_anticipation_level",
        "_last_update",
    )

    def __init__(self):
        self._engage_blend: float = 0.0
        self._compression_bias: float = 0.0
        self._anticipation_level: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Transition logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        subject_relevance: float,
        subject_distance: float,
        emotional_momentum: float,
        cruise_stability: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Prepare transition from cruise to engagement.
        """
        now = time.time()

        relevance = float(np.clip(subject_relevance, 0.0, 1.0))
        distance = float(np.clip(subject_distance, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        stability = float(np.clip(cruise_stability, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Anticipation rises with relevance and proximity
        target_anticipation = float(np.clip(
            0.5 * relevance + 0.3 * (1.0 - distance) + 0.2 * emotion,
            0.0,
            1.0,
        ))

        self._anticipation_level = float(
            0.9 * self._anticipation_level + 0.1 * target_anticipation
        )

        # Engagement blend ramps only when cruise stability is high
        if stability > 0.6:
            self._engage_blend = float(np.clip(
                self._engage_blend + 0.08 * self._anticipation_level,
                0.0,
                1.0,
            ))
        else:
            self._engage_blend = float(np.clip(
                self._engage_blend - 0.1,
                0.0,
                1.0,
            ))

        # Emotional compression tightens as engagement nears
        target_compression = float(np.clip(
            0.4 * self._engage_blend * (0.6 + 0.4 * auto),
            0.0,
            0.6,
        ))

        self._compression_bias = float(
            0.85 * self._compression_bias + 0.15 * target_compression
        )

        self._last_update = now

        return {
            "engagement_blend": self._engage_blend,
            "anticipation_level": self._anticipation_level,
            "emotional_compression": self._compression_bias,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cruise-to-engagement transition.
        """
        self._engage_blend = 0.0
        self._compression_bias = 0.0
        self._anticipation_level = 0.0
        self._last_update = time.time()


