# CHUNK 86 BX 01 — ANTICIPATORY REFRAMING BEFORE SUBJECT SWITCH
# ==============================================================================
#
# Purpose:
#   Shift framing, lead space, and camera orientation *before*
#   the active subject changes so attention transfer feels
#   intentional, invisible, and continuous.
#
# Backbone truth:
#   The eye should arrive before the mind notices the change.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class AnticipatoryReframingBeforeSubjectSwitch:
    """
    Anticipatory reframing before subject switch.
    Gradually biases framing toward the *next* likely subject
    while the current subject is still dominant, preventing
    perceptual discontinuities during focus transfer.
    """

    __slots__ = (
        "_anticipation_bias",
        "_pre_offset",
        "_pre_lead",
        "_last_update",
    )

    def __init__(self):
        self._anticipation_bias: float = 0.0
        self._pre_offset: np.ndarray = np.zeros(2)
        self._pre_lead: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Reframing logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        active_subject: Dict[str, float],
        candidate_subject: Dict[str, float],
        switch_probability: float,
        emotional_momentum: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Compute anticipatory reframing parameters.
        """
        now = time.time()

        p_switch = float(np.clip(switch_probability, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Candidate subject spatial hint
        cand_x = float(np.clip(candidate_subject.get("x", 0.0), -1.0, 1.0))
        cand_y = float(np.clip(candidate_subject.get("y", 0.0), -1.0, 1.0))
        cand_vel = float(np.clip(candidate_subject.get("velocity", 0.0), 0.0, 1.0))

        # Anticipation bias grows slowly — never jumps
        target_bias = float(np.clip(
            p_switch * (0.5 + 0.5 * emotion),
            0.0,
            1.0,
        ))

        self._anticipation_bias = float(
            0.9 * self._anticipation_bias + 0.1 * target_bias
        )

        # Pre-offset nudges framing toward future subject
        target_offset = np.array([
            cand_x * 0.4 * self._anticipation_bias,
            cand_y * 0.3 * self._anticipation_bias,
        ])

        self._pre_offset = (
            0.85 * self._pre_offset + 0.15 * target_offset
        )

        # Lead bias prepares motion continuity
        target_lead = float(np.clip(
            cand_vel * 0.5 * self._anticipation_bias,
            0.0,
            0.4,
        ))

        self._pre_lead = float(
            0.85 * self._pre_lead + 0.15 * target_lead
        )

        self._last_update = now

        return {
            "anticipation_bias": self._anticipation_bias,
            "pre_framing_offset": self._pre_offset.tolist(),
            "pre_lead_bias": self._pre_lead * (0.7 + 0.3 * auto),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset anticipatory reframing.
        """
        self._anticipation_bias = 0.0
        self._pre_offset = np.zeros(2)
        self._pre_lead = 0.0
        self._last_update = time.time()


