from typing import Dict, Any
import time
import numpy as np


class EngagementEntryEmotionalCompression:
    """
    Engagement entry emotional compression.
    Narrows tonal spread, firms motion cadence, and tightens framing
    as engagement begins, creating perceptual density and narrative
    gravity without overt visual aggression.
    """

    __slots__ = (
        "_compression_level",
        "_contrast_focus",
        "_cadence_lock",
        "_framing_tightness",
        "_last_update",
    )

    def __init__(self):
        self._compression_level: float = 0.0
        self._contrast_focus: float = 1.0
        self._cadence_lock: float = 0.5
        self._framing_tightness: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Compression logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        engagement_blend: float,
        emotional_momentum: float,
        subject_importance: float,
        scene_complexity: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Apply emotional compression at engagement entry.
        """
        now = time.time()

        blend = float(np.clip(engagement_blend, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        importance = float(np.clip(subject_importance, 0.0, 1.0))
        complexity = float(np.clip(scene_complexity, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Compression increases with engagement certainty and importance
        target_compression = float(np.clip(
            blend * (0.4 + 0.4 * importance + 0.2 * emotion),
            0.0,
            1.0,
        ))

        self._compression_level = float(
            0.85 * self._compression_level + 0.15 * target_compression
        )

        # Contrast focuses inward, avoiding highlight aggression
        target_contrast = float(np.clip(
            1.0 + 0.3 * self._compression_level - 0.2 * complexity,
            0.9,
            1.3,
        ))

        self._contrast_focus = float(
            0.9 * self._contrast_focus + 0.1 * target_contrast
        )

        # Motion cadence firms but does not spike
        target_cadence = float(np.clip(
            0.5 + 0.3 * self._compression_level * (0.7 + 0.3 * auto),
            0.5,
            0.8,
        ))

        self._cadence_lock = float(
            0.9 * self._cadence_lock + 0.1 * target_cadence
        )

        # Framing tightness increases selectively
        target_framing = float(np.clip(
            0.5 * self._compression_level * importance,
            0.0,
            0.6,
        ))

        self._framing_tightness = float(
            0.9 * self._framing_tightness + 0.1 * target_framing
        )

        self._last_update = now

        return {
            "compression_level": self._compression_level,
            "contrast_focus": self._contrast_focus,
            "motion_cadence": self._cadence_lock,
            "framing_tightness": self._framing_tightness,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset engagement emotional compression.
        """
        self._compression_level = 0.0
        self._contrast_focus = 1.0
        self._cadence_lock = 0.5
        self._framing_tightness = 0.0
        self._last_update = time.time()


