from typing import Dict, Any
import time
import numpy as np


class EngagementMotionCommitmentLogic:
    """
    Engagement motion commitment logic.
    Resolves motion ambiguity once engagement is inevitable,
    selecting a dominant trajectory, acceleration envelope,
    and camera lead behavior that communicates confidence
    without shock or overshoot.
    """

    __slots__ = (
        "_commitment_level",
        "_trajectory_bias",
        "_accel_envelope",
        "_camera_lead_gain",
        "_last_update",
    )

    def __init__(self):
        self._commitment_level: float = 0.0
        self._trajectory_bias: float = 0.0
        self._accel_envelope: float = 0.0
        self._camera_lead_gain: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Commitment logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        engagement_blend: float,
        anticipation_level: float,
        spatial_risk: float,
        emotional_momentum: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Commit motion during engagement.
        """
        now = time.time()

        blend = float(np.clip(engagement_blend, 0.0, 1.0))
        anticipate = float(np.clip(anticipation_level, 0.0, 1.0))
        risk = float(np.clip(spatial_risk, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Commitment grows decisively but not abruptly
        target_commitment = float(np.clip(
            blend * (0.6 + 0.4 * anticipate),
            0.0,
            1.0,
        ))

        self._commitment_level = float(
            0.85 * self._commitment_level + 0.15 * target_commitment
        )

        # Trajectory bias selects dominant direction
        target_trajectory = float(np.clip(
            self._commitment_level * (1.0 - 0.5 * risk),
            0.0,
            1.0,
        ))

        self._trajectory_bias = float(
            0.9 * self._trajectory_bias + 0.1 * target_trajectory
        )

        # Acceleration envelope firms with commitment but respects risk
        target_accel = float(np.clip(
            0.4 + 0.4 * self._commitment_level - 0.3 * risk,
            0.2,
            0.8,
        ))

        self._accel_envelope = float(
            0.9 * self._accel_envelope + 0.1 * target_accel
        )

        # Camera lead increases to reinforce decisiveness
        target_lead = float(np.clip(
            0.3 * self._commitment_level * (0.7 + 0.3 * emotion),
            0.0,
            0.5,
        ))

        self._camera_lead_gain = float(
            0.85 * self._camera_lead_gain + 0.15 * target_lead
        )

        self._last_update = now

        return {
            "commitment_level": self._commitment_level,
            "trajectory_bias": self._trajectory_bias,
            "acceleration_envelope": self._accel_envelope,
            "camera_lead_gain": self._camera_lead_gain * (0.7 + 0.3 * auto),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset engagement motion commitment.
        """
        self._commitment_level = 0.0
        self._trajectory_bias = 0.0
        self._accel_envelope = 0.0
        self._camera_lead_gain = 0.0
        self._last_update = time.time()


