# ==============================================================================
# CHUNK 86 CA 01 — SUBJECT LOCK-IN & FRAMING STABILIZATION
# ==============================================================================
#
# Purpose:
#   Lock onto the engaged subject with perceptual authority while
#   stabilizing framing, suppressing micro-hunting, and preserving
#   compositional intent under active motion.
#
# Backbone truth:
#   Once committed, the camera must *own the frame*.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class SubjectLockInFramingStabilization:
    """
    Subject lock-in & framing stabilization.
    Applies hysteresis-based locking, intent-preserving damping,
    and salience-weighted stabilization so framing feels calm,
    deliberate, and confident once engagement begins.
    """

    __slots__ = (
        "_lock_strength",
        "_stable_offset",
        "_damping_gain",
        "_last_update",
    )

    def __init__(self):
        self._lock_strength: float = 0.0
        self._stable_offset: np.ndarray = np.zeros(2)
        self._damping_gain: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Lock-in logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        subject_position: Dict[str, float],
        engagement_level: float,
        subject_salience: float,
        motion_energy: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Lock subject and stabilize framing.
        """
        now = time.time()

        engage = float(np.clip(engagement_level, 0.0, 1.0))
        salience = float(np.clip(subject_salience, 0.0, 1.0))
        motion = float(np.clip(motion_energy, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Subject coordinates
        sx = float(np.clip(subject_position.get("x", 0.0), -1.0, 1.0))
        sy = float(np.clip(subject_position.get("y", 0.0), -1.0, 1.0))
        target_offset = np.array([sx, sy])

        # Lock strength grows with engagement & salience
        target_lock = float(np.clip(
            engage * (0.6 + 0.4 * salience),
            0.0,
            1.0,
        ))

        self._lock_strength = float(
            0.85 * self._lock_strength + 0.15 * target_lock
        )

        # Stable offset resists micro jitter as lock increases
        stability_mix = float(np.clip(
            0.2 + 0.6 * self._lock_strength,
            0.2,
            0.8,
        ))

        self._stable_offset = (
            (1.0 - stability_mix) * self._stable_offset
            + stability_mix * target_offset
        )

        # Damping increases with motion and lock confidence
        target_damping = float(np.clip(
            1.0 + 0.8 * self._lock_strength + 0.5 * motion,
            1.0,
            2.5,
        ))

        self._damping_gain = float(
            0.9 * self._damping_gain + 0.1 * target_damping
        )

        self._last_update = now

        return {
            "lock_strength": self._lock_strength,
            "stable_framing_offset": self._stable_offset.tolist(),
            "damping_gain": self._damping_gain * (0.7 + 0.3 * auto),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset subject lock-in & stabilization.
        """
        self._lock_strength = 0.0
        self._stable_offset = np.zeros(2)
        self._damping_gain = 1.0
        self._last_update = time.time()


