# ==============================================================================
# CHUNK 86 CB 01 — ENGAGEMENT CAMERA AUTHORITY ESCALATION
# ==============================================================================
#
# Purpose:
#   Dynamically escalate camera authority during engagement,
#   deciding *how much control* the Director AI should assert
#   over framing, exposure, cadence, and motion leadership
#   while still allowing graceful human influence when desired.
#
# Backbone truth:
#   Authority is earned gradually, not seized.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class EngagementCameraAuthorityEscalation:
    """
    Engagement camera authority escalation.
    Blends AI authority against user influence based on engagement
    certainty, subject criticality, motion risk, and narrative phase,
    ensuring leadership feels confident but never hostile.
    """

    __slots__ = (
        "_authority_level",
        "_user_override_tolerance",
        "_leadership_bias",
        "_last_update",
    )

    def __init__(self):
        self._authority_level: float = 0.0
        self._user_override_tolerance: float = 1.0
        self._leadership_bias: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Authority escalation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        engagement_level: float,
        subject_importance: float,
        spatial_risk: float,
        narrative_phase: str,
        user_input_strength: float,
    ) -> Dict[str, Any]:
        """
        Escalate or relax camera authority.
        """
        now = time.time()

        engage = float(np.clip(engagement_level, 0.0, 1.0))
        importance = float(np.clip(subject_importance, 0.0, 1.0))
        risk = float(np.clip(spatial_risk, 0.0, 1.0))
        user = float(np.clip(user_input_strength, 0.0, 1.0))

        phase_gain = {
            "setup": 0.3,
            "development": 0.5,
            "climax": 0.8,
            "resolution": 0.2,
        }.get(narrative_phase, 0.4)

        # Authority grows with engagement certainty and importance
        target_authority = float(np.clip(
            engage * (0.4 + 0.4 * importance + 0.2 * phase_gain),
            0.0,
            1.0,
        ))

        self._authority_level = float(
            0.85 * self._authority_level + 0.15 * target_authority
        )

        # User override tolerance decreases as authority increases
        target_tolerance = float(np.clip(
            1.0 - 0.7 * self._authority_level + 0.3 * user,
            0.2,
            1.0,
        ))

        self._user_override_tolerance = float(
            0.9 * self._user_override_tolerance + 0.1 * target_tolerance
        )

        # Leadership bias favors AI when risk is high
        target_leadership = float(np.clip(
            self._authority_level * (0.6 + 0.4 * risk),
            0.0,
            1.0,
        ))

        self._leadership_bias = float(
            0.9 * self._leadership_bias + 0.1 * target_leadership
        )

        self._last_update = now

        return {
            "authority_level": self._authority_level,
            "user_override_tolerance": self._user_override_tolerance,
            "ai_leadership_bias": self._leadership_bias,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset camera authority escalation.
        """
        self._authority_level = 0.0
        self._user_override_tolerance = 1.0
        self._leadership_bias = 0.0
        self._last_update = time.time()


