# ==============================================================================
# CHUNK 86 CC 01 — DYNAMIC REFRAMING UNDER ACTIVE MOTION
# ==============================================================================
#
# Purpose:
#   Maintain cinematic composition while both camera platform
#   and subject are in active motion, dynamically redistributing
#   lead space, framing offset, and compositional tension.
#
# Backbone truth:
#   Motion does not break composition — it reshapes it.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class DynamicReframingUnderActiveMotion:
    """
    Dynamic reframing under active motion.
    Continuously reallocates lead space and framing bias based on
    subject velocity, acceleration, and camera motion so shots
    remain intentional and readable even at high energy.
    """

    __slots__ = (
        "_lead_vector",
        "_framing_bias",
        "_tension_gain",
        "_last_update",
    )

    def __init__(self):
        self._lead_vector: np.ndarray = np.zeros(2)
        self._framing_bias: np.ndarray = np.zeros(2)
        self._tension_gain: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Reframing logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        subject_velocity: Dict[str, float],
        subject_acceleration: Dict[str, float],
        camera_motion: Dict[str, float],
        engagement_level: float,
        emotional_momentum: float,
    ) -> Dict[str, Any]:
        """
        Dynamically reframe during active motion.
        """
        now = time.time()

        vx = float(np.clip(subject_velocity.get("x", 0.0), -1.0, 1.0))
        vy = float(np.clip(subject_velocity.get("y", 0.0), -1.0, 1.0))
        ax = float(np.clip(subject_acceleration.get("x", 0.0), -1.0, 1.0))
        ay = float(np.clip(subject_acceleration.get("y", 0.0), -1.0, 1.0))

        cam_pan = float(np.clip(camera_motion.get("pan", 0.0), -1.0, 1.0))
        cam_tilt = float(np.clip(camera_motion.get("tilt", 0.0), -1.0, 1.0))

        engage = float(np.clip(engagement_level, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))

        # Lead vector anticipates where subject is going, not where it is
        target_lead = np.array([
            0.6 * vx + 0.3 * ax,
            0.6 * vy + 0.3 * ay,
        ])

        self._lead_vector = (
            0.85 * self._lead_vector + 0.15 * target_lead
        )

        # Framing bias counteracts excessive camera motion
        target_bias = np.array([
            -0.4 * cam_pan,
            -0.4 * cam_tilt,
        ])

        self._framing_bias = (
            0.9 * self._framing_bias + 0.1 * target_bias
        )

        # Tension gain increases compositional asymmetry under emotion
        target_tension = float(np.clip(
            engage * (0.5 + 0.5 * emotion),
            0.0,
            1.0,
        ))

        self._tension_gain = float(
            0.9 * self._tension_gain + 0.1 * target_tension
        )

        self._last_update = now

        return {
            "lead_vector": self._lead_vector.tolist(),
            "framing_bias": self._framing_bias.tolist(),
            "tension_gain": self._tension_gain,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset dynamic reframing.
        """
        self._lead_vector = np.zeros(2)
        self._framing_bias = np.zeros(2)
        self._tension_gain = 0.0
        self._last_update = time.time()


