# CHUNK 86 CD 01 — ENGAGEMENT EXPOSURE & CONTRAST COMMAND
# ==============================================================================
#
# Purpose:
#   Assert tonal authority during engagement by commanding
#   exposure bias, contrast shaping, and highlight discipline
#   so visual hierarchy remains legible under emotional pressure.
#
# Backbone truth:
#   Exposure is storytelling, not brightness control.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class EngagementExposureContrastCommand:
    """
    Engagement exposure & contrast command.
    Shapes exposure bias, contrast pivot, and highlight roll-off
    based on engagement certainty, emotional momentum, and scene
    complexity — preserving tonal intent during high-pressure shots.
    """

    __slots__ = (
        "_exposure_bias",
        "_contrast_pivot",
        "_highlight_protection",
        "_shadow_floor",
        "_last_update",
    )

    def __init__(self):
        self._exposure_bias: float = 0.0
        self._contrast_pivot: float = 0.5
        self._highlight_protection: float = 0.5
        self._shadow_floor: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Tonal command logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        engagement_level: float,
        emotional_momentum: float,
        scene_dynamic_range: float,
        subject_luma: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Command exposure & contrast during engagement.
        """
        now = time.time()

        engage = float(np.clip(engagement_level, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        dr = float(np.clip(scene_dynamic_range, 0.0, 1.0))
        subj_luma = float(np.clip(subject_luma, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Exposure bias prioritizes subject without flattening scene
        target_exposure = float(np.clip(
            0.2 * engage * (0.6 + 0.4 * emotion) - 0.15 * dr,
            -0.3,
            0.3,
        ))

        self._exposure_bias = float(
            0.9 * self._exposure_bias + 0.1 * target_exposure
        )

        # Contrast pivot centers near subject luminance
        target_pivot = float(np.clip(
            0.4 + 0.3 * subj_luma,
            0.35,
            0.65,
        ))

        self._contrast_pivot = float(
            0.9 * self._contrast_pivot + 0.1 * target_pivot
        )

        # Highlight protection increases with engagement & DR
        target_highlight = float(np.clip(
            0.4 + 0.4 * engage + 0.2 * dr,
            0.4,
            0.9,
        ))

        self._highlight_protection = float(
            0.85 * self._highlight_protection + 0.15 * target_highlight
        )

        # Shadow floor lifts only slightly to preserve contrast
        target_shadow = float(np.clip(
            0.05 + 0.1 * engage * (1.0 - emotion),
            0.0,
            0.2,
        ))

        self._shadow_floor = float(
            0.9 * self._shadow_floor + 0.1 * target_shadow
        )

        self._last_update = now

        return {
            "exposure_bias": self._exposure_bias * (0.7 + 0.3 * auto),
            "contrast_pivot": self._contrast_pivot,
            "highlight_protection": self._highlight_protection,
            "shadow_floor": self._shadow_floor,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset engagement exposure & contrast command.
        """
        self._exposure_bias = 0.0
        self._contrast_pivot = 0.5
        self._highlight_protection = 0.5
        self._shadow_floor = 0.0
        self._last_update = time.time()


