# ==============================================================================
# CHUNK 86 CE 01 — SUBJECT MOTION PREDICTION & LEAD OPTIMIZATION
# ==============================================================================
#
# Purpose:
#   Predict subject motion beyond instantaneous velocity by
#   modeling intent, inertia, and behavioral continuity, then
#   optimize camera lead so interception feels deliberate,
#   not reactive.
#
# Backbone truth:
#   Great tracking arrives before the subject does.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class SubjectMotionPredictionLeadOptimization:
    """
    Subject motion prediction & lead optimization.
    Builds a short-horizon motion intent model using velocity,
    acceleration, curvature persistence, and engagement context,
    producing a stable lead vector for cinematic interception.
    """

    __slots__ = (
        "_predicted_velocity",
        "_intent_bias",
        "_lead_vector",
        "_confidence",
        "_last_update",
    )

    def __init__(self):
        self._predicted_velocity: np.ndarray = np.zeros(2)
        self._intent_bias: np.ndarray = np.zeros(2)
        self._lead_vector: np.ndarray = np.zeros(2)
        self._confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Prediction logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        subject_velocity: Dict[str, float],
        subject_acceleration: Dict[str, float],
        path_curvature: float,
        engagement_level: float,
        emotional_momentum: float,
    ) -> Dict[str, Any]:
        """
        Predict subject motion and compute optimized lead.
        """
        now = time.time()

        vx = float(np.clip(subject_velocity.get("x", 0.0), -1.0, 1.0))
        vy = float(np.clip(subject_velocity.get("y", 0.0), -1.0, 1.0))
        ax = float(np.clip(subject_acceleration.get("x", 0.0), -1.0, 1.0))
        ay = float(np.clip(subject_acceleration.get("y", 0.0), -1.0, 1.0))

        curvature = float(np.clip(abs(path_curvature), 0.0, 1.0))
        engage = float(np.clip(engagement_level, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))

        # Predict near-future velocity with inertia
        target_velocity = np.array([
            vx + 0.4 * ax * (1.0 - curvature),
            vy + 0.4 * ay * (1.0 - curvature),
        ])

        self._predicted_velocity = (
            0.85 * self._predicted_velocity + 0.15 * target_velocity
        )

        # Intent bias reflects sustained directionality
        self._intent_bias = (
            0.9 * self._intent_bias + 0.1 * self._predicted_velocity
        )

        # Confidence rises with engagement and motion coherence
        coherence = float(
            1.0 - min(1.0, np.linalg.norm(target_velocity - self._predicted_velocity))
        )

        self._confidence = float(np.clip(
            0.6 * self._confidence
            + 0.2 * engage
            + 0.2 * coherence,
            0.0,
            1.0,
        ))

        # Lead vector blends velocity and intent under emotional drive
        target_lead = (
            0.6 * self._predicted_velocity
            + 0.4 * self._intent_bias
        ) * (0.7 + 0.3 * emotion)

        self._lead_vector = (
            0.85 * self._lead_vector + 0.15 * target_lead
        )

        self._last_update = now

        return {
            "predicted_velocity": self._predicted_velocity.tolist(),
            "lead_vector": self._lead_vector.tolist(),
            "prediction_confidence": self._confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset motion prediction & lead optimization.
        """
        self._predicted_velocity = np.zeros(2)
        self._intent_bias = np.zeros(2)
        self._lead_vector = np.zeros(2)
        self._confidence = 0.0
        self._last_update = time.time()


