# ==============================================================================
# CHUNK 86 CF 01 — ENGAGEMENT SHOT SCALE MODULATION
# ==============================================================================
#
# Purpose:
#   Modulate shot scale (wide ↔ medium ↔ close) during engagement
#   so distance itself becomes narrative language — revealing,
#   withholding, or intensifying emotional information with intent.
#
# Backbone truth:
#   How close we are is what we are allowed to feel.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class EngagementShotScaleModulation:
    """
    Engagement shot scale modulation.
    Controls virtual distance, zoom intent, and framing density
    based on engagement certainty, emotional pressure, subject
    stability, and narrative restraint.
    """

    __slots__ = (
        "_scale_level",
        "_zoom_velocity",
        "_scale_inertia",
        "_last_update",
    )

    def __init__(self):
        self._scale_level: float = 0.5   # 0 = wide, 1 = close
        self._zoom_velocity: float = 0.0
        self._scale_inertia: float = 0.5
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Shot scale logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        engagement_level: float,
        emotional_momentum: float,
        subject_stability: float,
        narrative_phase: str,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Modulate shot scale during engagement.
        """
        now = time.time()

        engage = float(np.clip(engagement_level, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        stability = float(np.clip(subject_stability, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        phase_bias = {
            "setup": 0.2,
            "development": 0.45,
            "climax": 0.75,
            "resolution": 0.3,
        }.get(narrative_phase, 0.5)

        # Desired closeness grows with engagement & emotion,
        # but resists instability and early narrative phases
        target_scale = float(np.clip(
            phase_bias
            + 0.35 * engage
            + 0.25 * emotion
            - 0.3 * (1.0 - stability),
            0.15,
            0.9,
        ))

        # Scale inertia prevents aggressive push-ins
        inertia = float(np.clip(
            0.6 + 0.3 * stability,
            0.6,
            0.9,
        ))

        self._scale_inertia = inertia

        self._scale_level = float(
            inertia * self._scale_level + (1.0 - inertia) * target_scale
        )

        # Zoom velocity communicates intent, not speed
        self._zoom_velocity = float(np.clip(
            (target_scale - self._scale_level) * (0.4 + 0.3 * auto),
            -0.15,
            0.15,
        ))

        self._last_update = now

        return {
            "shot_scale": self._scale_level,
            "zoom_velocity": self._zoom_velocity,
            "scale_inertia": self._scale_inertia,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset engagement shot scale modulation.
        """
        self._scale_level = 0.5
        self._zoom_velocity = 0.0
        self._scale_inertia = 0.5
        self._last_update = time.time()


