# ==============================================================================
# CHUNK 86 CG 01 — GIMBAL AUTHORITY & HORIZON DISCIPLINE
# ==============================================================================
#
# Purpose:
#   Establish authoritative control over gimbal orientation,
#   horizon discipline, and roll permission so camera attitude
#   reinforces emotional gravity instead of distracting from it.
#
# Backbone truth:
#   A level horizon is not neutrality — it is a choice.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class GimbalAuthorityHorizonDiscipline:
    """
    Gimbal authority & horizon discipline.
    Controls horizon stiffness, roll allowance, and pitch authority
    based on emotional state, engagement certainty, and narrative
    phase — allowing intentional tilt without instability.
    """

    __slots__ = (
        "_horizon_lock_strength",
        "_roll_permission",
        "_pitch_authority",
        "_damping",
        "_last_update",
    )

    def __init__(self):
        self._horizon_lock_strength: float = 1.0
        self._roll_permission: float = 0.0
        self._pitch_authority: float = 0.5
        self._damping: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Gimbal authority logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        engagement_level: float,
        emotional_momentum: float,
        narrative_phase: str,
        platform_roll_rate: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Command gimbal authority & horizon discipline.
        """
        now = time.time()

        engage = float(np.clip(engagement_level, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        roll_rate = float(np.clip(abs(platform_roll_rate), 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        phase_roll_bias = {
            "setup": 0.0,
            "development": 0.1,
            "climax": 0.3,
            "resolution": 0.05,
        }.get(narrative_phase, 0.1)

        # Horizon lock relaxes slightly under emotional pressure
        target_horizon = float(np.clip(
            1.0 - 0.4 * engage - 0.3 * emotion,
            0.4,
            1.0,
        ))

        self._horizon_lock_strength = float(
            0.9 * self._horizon_lock_strength + 0.1 * target_horizon
        )

        # Roll permission allows intentional tilt
        target_roll = float(np.clip(
            phase_roll_bias + 0.4 * engage * emotion,
            0.0,
            0.5,
        ))

        self._roll_permission = float(
            0.85 * self._roll_permission + 0.15 * target_roll
        )

        # Pitch authority increases with engagement
        target_pitch = float(np.clip(
            0.4 + 0.4 * engage,
            0.3,
            0.9,
        ))

        self._pitch_authority = float(
            0.9 * self._pitch_authority + 0.1 * target_pitch
        )

        # Damping absorbs platform disturbance
        target_damping = float(np.clip(
            1.0 + 0.6 * roll_rate * (1.0 - self._roll_permission),
            1.0,
            2.0,
        ))

        self._damping = float(
            0.9 * self._damping + 0.1 * target_damping
        )

        self._last_update = now

        return {
            "horizon_lock_strength": self._horizon_lock_strength,
            "roll_permission": self._roll_permission * (0.7 + 0.3 * auto),
            "pitch_authority": self._pitch_authority,
            "gimbal_damping": self._damping,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset gimbal authority & horizon discipline.
        """
        self._horizon_lock_strength = 1.0
        self._roll_permission = 0.0
        self._pitch_authority = 0.5
        self._damping = 1.0
        self._last_update = time.time()


