# CHUNK 86 CH 01 — ENGAGEMENT CAMERA PATH SCULPTING
# ==============================================================================
#
# Purpose:
#   Sculpt the camera’s spatial path during engagement so movement
#   follows authored curves, arcs, and approach vectors that convey
#   intention, emotion, and spatial storytelling — not raw navigation.
#
# Backbone truth:
#   Where the camera goes matters as much as what it sees.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class EngagementCameraPathSculpting:
    """
    Engagement camera path sculpting.
    Shapes camera trajectory curvature, lateral drift, and vertical
    bias based on emotional momentum, engagement certainty, spatial
    context, and narrative restraint.
    """

    __slots__ = (
        "_path_curvature",
        "_lateral_arc",
        "_vertical_bias",
        "_path_confidence",
        "_last_update",
    )

    def __init__(self):
        self._path_curvature: float = 0.0
        self._lateral_arc: float = 0.0
        self._vertical_bias: float = 0.0
        self._path_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Path sculpting logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        engagement_level: float,
        emotional_momentum: float,
        spatial_risk: float,
        subject_distance: float,
        narrative_phase: str,
    ) -> Dict[str, Any]:
        """
        Sculpt camera path during engagement.
        """
        now = time.time()

        engage = float(np.clip(engagement_level, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        risk = float(np.clip(spatial_risk, 0.0, 1.0))
        dist = float(np.clip(subject_distance, 0.0, 1.0))

        phase_curve_bias = {
            "setup": 0.1,
            "development": 0.3,
            "climax": 0.6,
            "resolution": 0.2,
        }.get(narrative_phase, 0.3)

        # Path curvature increases with emotion but respects risk
        target_curvature = float(np.clip(
            phase_curve_bias
            + 0.5 * engage * emotion
            - 0.4 * risk,
            0.0,
            1.0,
        ))

        self._path_curvature = float(
            0.9 * self._path_curvature + 0.1 * target_curvature
        )

        # Lateral arc creates cinematic parallax during approach
        target_lateral = float(np.clip(
            (0.6 - dist) * self._path_curvature,
            -0.4,
            0.4,
        ))

        self._lateral_arc = float(
            0.85 * self._lateral_arc + 0.15 * target_lateral
        )

        # Vertical bias adds emotional lift or pressure
        target_vertical = float(np.clip(
            (emotion - 0.5) * 0.4 * engage,
            -0.3,
            0.3,
        ))

        self._vertical_bias = float(
            0.9 * self._vertical_bias + 0.1 * target_vertical
        )

        # Confidence reflects stability of sculpted path
        self._path_confidence = float(np.clip(
            0.7 * self._path_confidence
            + 0.2 * engage
            + 0.1 * (1.0 - risk),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "path_curvature": self._path_curvature,
            "lateral_arc": self._lateral_arc,
            "vertical_bias": self._vertical_bias,
            "path_confidence": self._path_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset camera path sculpting.
        """
        self._path_curvature = 0.0
        self._lateral_arc = 0.0
        self._vertical_bias = 0.0
        self._path_confidence = 0.0
        self._last_update = time.time()


