# CHUNK 86 CI 01 — SUBJECT OCCLUSION ANTICIPATION
# ==============================================================================
#
# Purpose:
#   Anticipate imminent subject occlusion (temporary or sustained)
#   and reshape camera motion, framing bias, and emotional pacing
#   *before* line-of-sight breaks, preserving continuity and tension.
#
# Backbone truth:
#   Losing sight of a subject is a narrative event — not a failure.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class SubjectOcclusionAnticipation:
    """
    Subject occlusion anticipation.
    Predicts near-future occlusion using depth gradients,
    relative motion vectors, and path intersection likelihood,
    enabling proactive cinematic responses instead of reactive cuts.
    """

    __slots__ = (
        "_occlusion_probability",
        "_occlusion_confidence",
        "_pre_occlusion_bias",
        "_last_update",
    )

    def __init__(self):
        self._occlusion_probability: float = 0.0
        self._occlusion_confidence: float = 0.0
        self._pre_occlusion_bias: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Occlusion anticipation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        subject_depth: float,
        background_depth: float,
        relative_motion: Dict[str, float],
        path_intersection_risk: float,
        engagement_level: float,
        emotional_momentum: float,
    ) -> Dict[str, Any]:
        """
        Anticipate subject occlusion.
        """
        now = time.time()

        subj_d = float(np.clip(subject_depth, 0.0, 1.0))
        bg_d = float(np.clip(background_depth, 0.0, 1.0))
        rx = float(np.clip(relative_motion.get("x", 0.0), -1.0, 1.0))
        ry = float(np.clip(relative_motion.get("y", 0.0), -1.0, 1.0))
        path_risk = float(np.clip(path_intersection_risk, 0.0, 1.0))
        engage = float(np.clip(engagement_level, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))

        # Depth convergence indicates looming occlusion
        depth_pressure = float(np.clip(
            1.0 - abs(subj_d - bg_d),
            0.0,
            1.0,
        ))

        # Motion convergence toward background
        motion_pressure = float(np.clip(
            0.5 * abs(rx) + 0.5 * abs(ry),
            0.0,
            1.0,
        ))

        # Instantaneous occlusion likelihood
        instant_occlusion = float(np.clip(
            0.4 * depth_pressure
            + 0.3 * motion_pressure
            + 0.3 * path_risk,
            0.0,
            1.0,
        ))

        # Temporal smoothing builds anticipation
        self._occlusion_probability = float(np.clip(
            0.85 * self._occlusion_probability + 0.15 * instant_occlusion,
            0.0,
            1.0,
        ))

        # Confidence rises when engagement & emotion are high
        self._occlusion_confidence = float(np.clip(
            0.6 * self._occlusion_confidence
            + 0.2 * engage
            + 0.2 * emotion,
            0.0,
            1.0,
        ))

        # Pre-occlusion bias prepares framing & motion
        self._pre_occlusion_bias = float(np.clip(
            self._occlusion_probability * (0.5 + 0.5 * self._occlusion_confidence),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "occlusion_probability": self._occlusion_probability,
            "occlusion_confidence": self._occlusion_confidence,
            "pre_occlusion_bias": self._pre_occlusion_bias,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset occlusion anticipation.
        """
        self._occlusion_probability = 0.0
        self._occlusion_confidence = 0.0
        self._pre_occlusion_bias = 0.0
        self._last_update = time.time()


