# CHUNK 86 CJ 01 — MULTI-LAYER PARALLAX COMPOSITION
# ==============================================================================
#
# Purpose:
#   Construct and maintain multi-layer parallax separation between
#   foreground, subject, and background so depth, scale, and motion
#   differentials become an active cinematic language.
#
# Backbone truth:
#   Depth is emotion with geometry.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class MultiLayerParallaxComposition:
    """
    Multi-layer parallax composition.
    Separates motion and framing into foreground, subject, and
    background layers, dynamically weighting their relative motion
    and scale to reinforce depth perception and narrative focus.
    """

    __slots__ = (
        "_foreground_gain",
        "_subject_gain",
        "_background_gain",
        "_depth_confidence",
        "_last_update",
    )

    def __init__(self):
        self._foreground_gain: float = 0.0
        self._subject_gain: float = 1.0
        self._background_gain: float = 0.5
        self._depth_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Parallax composition logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        foreground_motion: Dict[str, float],
        subject_motion: Dict[str, float],
        background_motion: Dict[str, float],
        engagement_level: float,
        emotional_momentum: float,
        scene_depth_complexity: float,
    ) -> Dict[str, Any]:
        """
        Compose multi-layer parallax.
        """
        now = time.time()

        fg = float(np.clip(abs(foreground_motion.get("magnitude", 0.0)), 0.0, 1.0))
        subj = float(np.clip(abs(subject_motion.get("magnitude", 0.0)), 0.0, 1.0))
        bg = float(np.clip(abs(background_motion.get("magnitude", 0.0)), 0.0, 1.0))

        engage = float(np.clip(engagement_level, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        depth_complexity = float(np.clip(scene_depth_complexity, 0.0, 1.0))

        # Foreground exaggerates parallax under engagement
        target_fg = float(np.clip(
            0.3 + 0.6 * engage * (0.5 + 0.5 * emotion),
            0.2,
            1.0,
        ))

        self._foreground_gain = float(
            0.85 * self._foreground_gain + 0.15 * target_fg
        )

        # Subject remains dominant anchor
        target_subj = float(np.clip(
            1.0 - 0.2 * depth_complexity,
            0.6,
            1.0,
        ))

        self._subject_gain = float(
            0.9 * self._subject_gain + 0.1 * target_subj
        )

        # Background motion compresses under emotional focus
        target_bg = float(np.clip(
            0.4 + 0.3 * (1.0 - engage),
            0.2,
            0.7,
        ))

        self._background_gain = float(
            0.9 * self._background_gain + 0.1 * target_bg
        )

        # Depth confidence reflects stability of layer separation
        separation_quality = float(
            abs(self._foreground_gain - self._subject_gain)
            + abs(self._subject_gain - self._background_gain)
        )

        self._depth_confidence = float(np.clip(
            0.7 * self._depth_confidence
            + 0.2 * separation_quality
            + 0.1 * (1.0 - depth_complexity),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "foreground_gain": self._foreground_gain,
            "subject_gain": self._subject_gain,
            "background_gain": self._background_gain,
            "depth_confidence": self._depth_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset multi-layer parallax composition.
        """
        self._foreground_gain = 0.0
        self._subject_gain = 1.0
        self._background_gain = 0.5
        self._depth_confidence = 0.0
        self._last_update = time.time()


