from typing import Dict, Any
import time
import numpy as np


class EngagementExitEmotionalRelease:
    """
    Engagement exit & emotional release logic.
    Shapes post-engagement emotional decay, linger duration,
    and perceptual softening so intensity resolves with
    psychological truth rather than numerical decay.
    """

    __slots__ = (
        "_release_velocity",
        "_linger_factor",
        "_aftertaste_weight",
        "_release_confidence",
        "_last_update",
    )

    def __init__(self):
        self._release_velocity: float = 0.0
        self._linger_factor: float = 0.0
        self._aftertaste_weight: float = 0.0
        self._release_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Emotional release logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        peak_intensity: float,
        emotional_momentum: float,
        engagement_duration: float,
        peak_type: str,
        narrative_phase: str,
    ) -> Dict[str, Any]:
        """
        Resolve engagement into emotional release.
        """
        now = time.time()

        peak = float(np.clip(peak_intensity, 0.0, 1.0))
        momentum = float(np.clip(emotional_momentum, 0.0, 1.0))
        duration = float(np.clip(engagement_duration, 0.0, 1.0))

        # Peak-type dependent release behavior
        peak_release_profiles = {
            "awe": {"velocity": 0.25, "linger": 0.8},
            "triumph": {"velocity": 0.4, "linger": 0.6},
            "tension": {"velocity": 0.55, "linger": 0.3},
            "loss": {"velocity": 0.15, "linger": 0.9},
            "relief": {"velocity": 0.35, "linger": 0.5},
        }

        profile = peak_release_profiles.get(
            peak_type,
            {"velocity": 0.4, "linger": 0.5},
        )

        # Narrative phase tempers release speed
        phase_modifier = {
            "setup": 0.7,
            "development": 0.9,
            "climax": 1.1,
            "resolution": 0.6,
        }.get(narrative_phase, 1.0)

        target_velocity = float(np.clip(
            profile["velocity"] * phase_modifier * (0.6 + 0.4 * peak),
            0.1,
            0.8,
        ))

        self._release_velocity = float(
            0.85 * self._release_velocity + 0.15 * target_velocity
        )

        # Linger increases with momentum and duration
        target_linger = float(np.clip(
            profile["linger"] * (0.5 + 0.5 * momentum) * (0.6 + 0.4 * duration),
            0.0,
            1.0,
        ))

        self._linger_factor = float(
            0.9 * self._linger_factor + 0.1 * target_linger
        )

        # Aftertaste preserves emotional residue
        self._aftertaste_weight = float(np.clip(
            0.7 * self._aftertaste_weight
            + 0.3 * self._linger_factor * peak,
            0.0,
            1.0,
        ))

        # Confidence reflects coherence of resolution
        self._release_confidence = float(np.clip(
            0.6 * self._release_confidence
            + 0.2 * (1.0 - self._release_velocity)
            + 0.2 * self._linger_factor,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "release_velocity": self._release_velocity,
            "linger_factor": self._linger_factor,
            "aftertaste_weight": self._aftertaste_weight,
            "release_confidence": self._release_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset engagement exit & emotional release logic.
        """
        self._release_velocity = 0.0
        self._linger_factor = 0.0
        self._aftertaste_weight = 0.0
        self._release_confidence = 0.0
        self._last_update = time.time()


