from typing import Dict, Any
import time
import numpy as np


class PostEngagementStabilizationDecompression:
    """
    Post-engagement stabilization & decompression.
    Applies tiered damping and perceptual softening across motion,
    framing, exposure, and gimbal authority so the system settles
    naturally without emotional amnesia.
    """

    __slots__ = (
        "_motion_damping",
        "_framing_softness",
        "_exposure_relaxation",
        "_gimbal_relaxation",
        "_decompression_confidence",
        "_last_update",
    )

    def __init__(self):
        self._motion_damping: float = 1.0
        self._framing_softness: float = 0.0
        self._exposure_relaxation: float = 0.0
        self._gimbal_relaxation: float = 0.0
        self._decompression_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Stabilization & decompression logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        emotional_momentum: float,
        aftertaste_weight: float,
        engagement_confidence: float,
        system_stress: float,
        narrative_phase: str,
    ) -> Dict[str, Any]:
        """
        Stabilize and decompress after engagement.
        """
        now = time.time()

        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        aftertaste = float(np.clip(aftertaste_weight, 0.0, 1.0))
        engage_conf = float(np.clip(engagement_confidence, 0.0, 1.0))
        stress = float(np.clip(system_stress, 0.0, 1.0))

        phase_relax_bias = {
            "resolution": 0.8,
            "development": 0.5,
            "climax": 0.3,
            "setup": 0.6,
        }.get(narrative_phase, 0.5)

        # Motion damping eases first
        target_motion_damping = float(np.clip(
            1.0 + 0.8 * emotion * (1.0 - aftertaste),
            1.0,
            2.0,
        ))

        self._motion_damping = float(
            0.85 * self._motion_damping + 0.15 * target_motion_damping
        )

        # Framing softness restores perceptual calm
        target_softness = float(np.clip(
            0.3 * aftertaste + 0.2 * phase_relax_bias,
            0.0,
            0.6,
        ))

        self._framing_softness = float(
            0.9 * self._framing_softness + 0.1 * target_softness
        )

        # Exposure relaxes last to avoid tonal snap
        target_exposure_relax = float(np.clip(
            0.2 * engage_conf * phase_relax_bias,
            0.0,
            0.4,
        ))

        self._exposure_relaxation = float(
            0.92 * self._exposure_relaxation + 0.08 * target_exposure_relax
        )

        # Gimbal relaxation follows motion stability
        target_gimbal_relax = float(np.clip(
            0.3 * (1.0 - stress),
            0.0,
            0.5,
        ))

        self._gimbal_relaxation = float(
            0.9 * self._gimbal_relaxation + 0.1 * target_gimbal_relax
        )

        # Confidence reflects decompression coherence
        self._decompression_confidence = float(np.clip(
            0.7 * self._decompression_confidence
            + 0.2 * (1.0 - stress)
            + 0.1 * phase_relax_bias,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "motion_damping": self._motion_damping,
            "framing_softness": self._framing_softness,
            "exposure_relaxation": self._exposure_relaxation,
            "gimbal_relaxation": self._gimbal_relaxation,
            "decompression_confidence": self._decompression_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset post-engagement stabilization & decompression.
        """
        self._motion_damping = 1.0
        self._framing_softness = 0.0
        self._exposure_relaxation = 0.0
        self._gimbal_relaxation = 0.0
        self._decompression_confidence = 0.0
        self._last_update = time.time()


