class NarrativeBeatTransitionHarmonizer:
    """
    Narrative beat transition harmonizer.
    Aligns outgoing and incoming beat characteristics by blending
    emotional residue, motion intent, and tonal posture so narrative
    transitions resolve psychologically before they occur visually.
    """

    __slots__ = (
        "_transition_bias",
        "_temporal_blend",
        "_beat_confidence",
        "_last_update",
    )

    def __init__(self):
        self._transition_bias: float = 0.0
        self._temporal_blend: float = 0.0
        self._beat_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Beat transition logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        outgoing_emotion: float,
        incoming_intent: float,
        aftertaste_weight: float,
        temporal_pressure: float,
        narrative_phase: str,
    ) -> Dict[str, Any]:
        """
        Harmonize narrative beat transition.
        """
        now = time.time()

        out_e = float(np.clip(outgoing_emotion, 0.0, 1.0))
        in_i = float(np.clip(incoming_intent, 0.0, 1.0))
        aftertaste = float(np.clip(aftertaste_weight, 0.0, 1.0))
        pressure = float(np.clip(temporal_pressure, 0.0, 1.0))

        phase_blend_bias = {
            "setup": 0.4,
            "development": 0.6,
            "climax": 0.8,
            "resolution": 0.5,
        }.get(narrative_phase, 0.6)

        # Transition bias balances past emotion with future intent
        target_bias = float(np.clip(
            0.6 * out_e * aftertaste + 0.4 * in_i,
            0.0,
            1.0,
        ))

        self._transition_bias = float(
            0.85 * self._transition_bias + 0.15 * target_bias
        )

        # Temporal blend stretches or compresses the handoff
        target_blend = float(np.clip(
            phase_blend_bias * (0.6 + 0.4 * pressure),
            0.3,
            0.9,
        ))

        self._temporal_blend = float(
            0.9 * self._temporal_blend + 0.1 * target_blend
        )

        # Confidence reflects coherence of narrative handoff
        self._beat_confidence = float(np.clip(
            0.7 * self._beat_confidence
            + 0.2 * self._transition_bias
            + 0.1 * self._temporal_blend,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "transition_bias": self._transition_bias,
            "temporal_blend": self._temporal_blend,
            "beat_confidence": self._beat_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset narrative beat transition harmonizer.
        """
        self._transition_bias = 0.0
        self._temporal_blend = 0.0
        self._beat_confidence = 0.0
        self._last_update = time.time()


