    __slots__ = (
        "_memory",
        "_memory_window",
        "_adaptation_bias",
        "_fatigue_estimate",
        "_last_update",
    )

    def __init__(self, memory_window: int = 5):
        self._memory: List[Dict[str, float]] = []
        self._memory_window: int = int(np.clip(memory_window, 3, 7))
        self._adaptation_bias: float = 0.0
        self._fatigue_estimate: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Memory encoding logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        peak_intensity: float,
        linger_factor: float,
        aftertaste_weight: float,
        release_velocity: float,
    ) -> Dict[str, Any]:
        """
        Encode short-horizon emotional memory.
        """
        now = time.time()

        peak = float(np.clip(peak_intensity, 0.0, 1.0))
        linger = float(np.clip(linger_factor, 0.0, 1.0))
        aftertaste = float(np.clip(aftertaste_weight, 0.0, 1.0))
        release = float(np.clip(release_velocity, 0.0, 1.0))

        entry = {
            "peak": peak,
            "linger": linger,
            "aftertaste": aftertaste,
            "release": release,
        }

        self._memory.append(entry)

        if len(self._memory) > self._memory_window:
            self._memory.pop(0)

        # Adaptation bias grows if peaks repeat without sufficient decay
        avg_peak = float(np.mean([m["peak"] for m in self._memory]))
        avg_linger = float(np.mean([m["linger"] for m in self._memory]))

        self._adaptation_bias = float(np.clip(
            0.7 * self._adaptation_bias
            + 0.2 * avg_peak
            + 0.1 * avg_linger,
            0.0,
            1.0,
        ))

        # Fatigue increases when release is fast but peaks stay high
        self._fatigue_estimate = float(np.clip(
            0.75 * self._fatigue_estimate
            + 0.25 * avg_peak * (1.0 - release),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "adaptation_bias": self._adaptation_bias,
            "fatigue_estimate": self._fatigue_estimate,
            "memory_depth": len(self._memory),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset short-horizon emotional memory.
        """
        self._memory.clear()
        self._adaptation_bias = 0.0
        self._fatigue_estimate = 0.0
        self._last_update = time.time()


