from typing import Dict, Any
import time
import numpy as np


class AudienceFatigueSaturationGuard:
    """
    Audience fatigue & saturation guard.
    Monitors cumulative intensity, repetition pressure, and emotional
    adaptation to softly constrain saturation, contrast, and motion
    before perceptual burnout occurs.
    """

    __slots__ = (
        "_fatigue_level",
        "_saturation_guard",
        "_contrast_guard",
        "_motion_guard",
        "_guard_confidence",
        "_last_update",
    )

    def __init__(self):
        self._fatigue_level: float = 0.0
        self._saturation_guard: float = 1.0
        self._contrast_guard: float = 1.0
        self._motion_guard: float = 1.0
        self._guard_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Fatigue & saturation guard logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        fatigue_estimate: float,
        adaptation_bias: float,
        emotional_momentum: float,
        engagement_level: float,
        narrative_phase: str,
    ) -> Dict[str, Any]:
        """
        Guard against audience fatigue and saturation overload.
        """
        now = time.time()

        fatigue = float(np.clip(fatigue_estimate, 0.0, 1.0))
        adapt = float(np.clip(adaptation_bias, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))
        engage = float(np.clip(engagement_level, 0.0, 1.0))

        phase_restraint = {
            "setup": 0.6,
            "development": 0.8,
            "climax": 1.0,
            "resolution": 0.5,
        }.get(narrative_phase, 0.8)

        # Composite fatigue level
        self._fatigue_level = float(np.clip(
            0.6 * self._fatigue_level
            + 0.25 * fatigue
            + 0.15 * adapt,
            0.0,
            1.0,
        ))

        # Saturation guard tightens first
        target_sat_guard = float(np.clip(
            1.0 - 0.5 * self._fatigue_level * phase_restraint,
            0.6,
            1.0,
        ))

        self._saturation_guard = float(
            0.9 * self._saturation_guard + 0.1 * target_sat_guard
        )

        # Contrast guard follows saturation
        target_contrast_guard = float(np.clip(
            1.0 - 0.4 * self._fatigue_level * (0.5 + 0.5 * emotion),
            0.7,
            1.0,
        ))

        self._contrast_guard = float(
            0.9 * self._contrast_guard + 0.1 * target_contrast_guard
        )

        # Motion guard applies last to preserve energy
        target_motion_guard = float(np.clip(
            1.0 - 0.3 * self._fatigue_level * (1.0 - engage),
            0.75,
            1.0,
        ))

        self._motion_guard = float(
            0.92 * self._motion_guard + 0.08 * target_motion_guard
        )

        # Confidence reflects smoothness of restraint
        self._guard_confidence = float(np.clip(
            0.7 * self._guard_confidence
            + 0.2 * (1.0 - self._fatigue_level)
            + 0.1 * phase_restraint,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "saturation_guard": self._saturation_guard,
            "contrast_guard": self._contrast_guard,
            "motion_guard": self._motion_guard,
            "fatigue_level": self._fatigue_level,
            "guard_confidence": self._guard_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset audience fatigue & saturation guard.
        """
        self._fatigue_level = 0.0
        self._saturation_guard = 1.0
        self._contrast_guard = 1.0
        self._motion_guard = 1.0
        self._guard_confidence = 0.0
        self._last_update = time.time()


