#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class DirectorOverrideArbitration:
    """
    Director override arbitration layer.
    Blends AI intent, human override, and safety constraints into
    a single authoritative command stream using confidence-weighted,
    hysteresis-stabilized arbitration.
    """

    __slots__ = (
        "_ai_authority",
        "_human_authority",
        "_safety_authority",
        "_active_controller",
        "_handoff_inertia",
        "_arbitration_confidence",
        "_last_update",
    )

    def __init__(self):
        self._ai_authority: float = 1.0
        self._human_authority: float = 0.0
        self._safety_authority: float = 0.0
        self._active_controller: str = "ai"
        self._handoff_inertia: float = 0.8
        self._arbitration_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Arbitration logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        ai_confidence: float,
        human_input_strength: float,
        safety_pressure: float,
        autonomy_level: float,
    ) -> Dict[str, Any]:
        """
        Arbitrate control authority between AI, human, and safety.
        """
        now = time.time()

        ai_c = float(np.clip(ai_confidence, 0.0, 1.0))
        human = float(np.clip(human_input_strength, 0.0, 1.0))
        safety = float(np.clip(safety_pressure, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        # Safety always asserts first but ramps smoothly
        target_safety = float(np.clip(
            safety * (0.8 + 0.2 * auto),
            0.0,
            1.0,
        ))

        self._safety_authority = float(
            0.9 * self._safety_authority + 0.1 * target_safety
        )

        # Human authority increases with sustained input
        target_human = float(np.clip(
            human * (1.0 - self._safety_authority),
            0.0,
            1.0,
        ))

        self._human_authority = float(
            0.85 * self._human_authority + 0.15 * target_human
        )

        # AI authority fills remaining control space
        target_ai = float(np.clip(
            ai_c * (1.0 - self._human_authority) * (1.0 - self._safety_authority),
            0.0,
            1.0,
        ))

        self._ai_authority = float(
            0.85 * self._ai_authority + 0.15 * target_ai
        )

        # Normalize
        total = self._ai_authority + self._human_authority + self._safety_authority
        if total > 0.0:
            self._ai_authority /= total
            self._human_authority /= total
            self._safety_authority /= total

        # Active controller with hysteresis
        previous = self._active_controller

        if self._safety_authority > 0.4:
            self._active_controller = "safety"
        elif self._human_authority > 0.45:
            self._active_controller = "human"
        else:
            self._active_controller = "ai"

        if previous != self._active_controller:
            self._handoff_inertia = 0.9
        else:
            self._handoff_inertia = float(np.clip(
                self._handoff_inertia * 0.98,
                0.6,
                0.9,
            ))

        # Arbitration confidence reflects stability
        self._arbitration_confidence = float(np.clip(
            0.7 * self._arbitration_confidence
            + 0.2 * (1.0 - abs(self._human_authority - self._ai_authority))
            + 0.1 * (1.0 - self._safety_authority),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "active_controller": self._active_controller,
            "ai_authority": self._ai_authority,
            "human_authority": self._human_authority,
            "safety_authority": self._safety_authority,
            "handoff_inertia": self._handoff_inertia,
            "arbitration_confidence": self._arbitration_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset director override arbitration.
        """
        self._ai_authority = 1.0
        self._human_authority = 0.0
        self._safety_authority = 0.0
        self._active_controller = "ai"
        self._handoff_inertia = 0.8
        self._arbitration_confidence = 0.0
        self._last_update = time.time()


