from typing import Dict, Any
import time
import numpy as np


class HumanAICoControlBlending:
    """
    Human–AI co-control blending.
    Fuses human command vectors and AI intent vectors using
    authority weighting, temporal smoothing, and semantic alignment
    so transitions preserve cinematic continuity and responsiveness.
    """

    __slots__ = (
        "_blend_weight",
        "_alignment_factor",
        "_temporal_smooth",
        "_coherence_confidence",
        "_last_update",
    )

    def __init__(self):
        self._blend_weight: float = 0.5
        self._alignment_factor: float = 1.0
        self._temporal_smooth: float = 0.8
        self._coherence_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Co-control blending logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        ai_command: Dict[str, float],
        human_command: Dict[str, float],
        ai_authority: float,
        human_authority: float,
        latency_estimate: float,
    ) -> Dict[str, Any]:
        """
        Blend human and AI control intents.
        """
        now = time.time()

        ai_w = float(np.clip(ai_authority, 0.0, 1.0))
        human_w = float(np.clip(human_authority, 0.0, 1.0))
        latency = float(np.clip(latency_estimate, 0.0, 1.0))

        total = ai_w + human_w
        if total > 0.0:
            ai_w /= total
            human_w /= total

        # Alignment factor penalizes opposing vectors
        alignment = 1.0
        for k in ai_command.keys():
            if k in human_command:
                alignment -= 0.25 * abs(
                    ai_command[k] - human_command[k]
                )

        self._alignment_factor = float(np.clip(
            0.85 * self._alignment_factor + 0.15 * alignment,
            0.0,
            1.0,
        ))

        # Blend weight adapts with authority and alignment
        target_blend = float(np.clip(
            human_w * self._alignment_factor,
            0.0,
            1.0,
        ))

        self._blend_weight = float(
            0.85 * self._blend_weight + 0.15 * target_blend
        )

        # Temporal smoothing increases with latency
        self._temporal_smooth = float(np.clip(
            0.6 + 0.3 * latency,
            0.6,
            0.9,
        ))

        blended_command: Dict[str, float] = {}

        for k in ai_command.keys():
            ai_v = ai_command.get(k, 0.0)
            human_v = human_command.get(k, ai_v)
            blended = (
                (1.0 - self._blend_weight) * ai_v
                + self._blend_weight * human_v
            )
            blended_command[k] = float(blended)

        # Coherence confidence reflects harmony
        self._coherence_confidence = float(np.clip(
            0.7 * self._coherence_confidence
            + 0.2 * self._alignment_factor
            + 0.1 * (1.0 - latency),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "blended_command": blended_command,
            "blend_weight": self._blend_weight,
            "alignment_factor": self._alignment_factor,
            "temporal_smooth": self._temporal_smooth,
            "coherence_confidence": self._coherence_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset human–AI co-control blending.
        """
        self._blend_weight = 0.5
        self._alignment_factor = 1.0
        self._temporal_smooth = 0.8
        self._coherence_confidence = 0.0
        self._last_update = time.time()


