from typing import Dict, Any
import time
import numpy as np


class SafetyEnvelopeNarrativeDegradation:
    """
    Safety envelope & failsafe narrative degradation.
    Gradually constrains motion, framing, and authority as safety
    pressure rises, translating technical intervention into
    perceptually motivated cinematic simplification.
    """

    __slots__ = (
        "_safety_level",
        "_motion_constraint",
        "_framing_constraint",
        "_authority_clamp",
        "_degradation_confidence",
        "_last_update",
    )

    def __init__(self):
        self._safety_level: float = 0.0
        self._motion_constraint: float = 1.0
        self._framing_constraint: float = 1.0
        self._authority_clamp: float = 1.0
        self._degradation_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Safety envelope logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        raw_safety_pressure: float,
        system_margin: float,
        environmental_risk: float,
        autonomy_level: float,
        narrative_phase: str,
    ) -> Dict[str, Any]:
        """
        Apply safety envelope with narrative degradation.
        """
        now = time.time()

        pressure = float(np.clip(raw_safety_pressure, 0.0, 1.0))
        margin = float(np.clip(system_margin, 0.0, 1.0))
        risk = float(np.clip(environmental_risk, 0.0, 1.0))
        auto = float(np.clip(autonomy_level, 0.0, 1.0))

        phase_safety_bias = {
            "setup": 0.6,
            "development": 0.8,
            "climax": 1.0,
            "resolution": 0.7,
        }.get(narrative_phase, 0.8)

        # Composite safety level
        target_safety = float(np.clip(
            0.5 * pressure
            + 0.3 * risk
            + 0.2 * (1.0 - margin),
            0.0,
            1.0,
        ))

        self._safety_level = float(
            0.85 * self._safety_level + 0.15 * target_safety
        )

        # Motion is constrained first
        target_motion_constraint = float(np.clip(
            1.0 - 0.7 * self._safety_level * phase_safety_bias,
            0.3,
            1.0,
        ))

        self._motion_constraint = float(
            0.9 * self._motion_constraint + 0.1 * target_motion_constraint
        )

        # Framing simplifies next
        target_framing_constraint = float(np.clip(
            1.0 - 0.6 * self._safety_level,
            0.4,
            1.0,
        ))

        self._framing_constraint = float(
            0.9 * self._framing_constraint + 0.1 * target_framing_constraint
        )

        # Authority clamps last (AI yields gracefully)
        target_authority_clamp = float(np.clip(
            1.0 - 0.8 * self._safety_level * auto,
            0.2,
            1.0,
        ))

        self._authority_clamp = float(
            0.92 * self._authority_clamp + 0.08 * target_authority_clamp
        )

        # Confidence reflects smoothness of degradation
        self._degradation_confidence = float(np.clip(
            0.7 * self._degradation_confidence
            + 0.2 * (1.0 - self._safety_level)
            + 0.1 * phase_safety_bias,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "safety_level": self._safety_level,
            "motion_constraint": self._motion_constraint,
            "framing_constraint": self._framing_constraint,
            "authority_clamp": self._authority_clamp,
            "degradation_confidence": self._degradation_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset safety envelope & degradation state.
        """
        self._safety_level = 0.0
        self._motion_constraint = 1.0
        self._framing_constraint = 1.0
        self._authority_clamp = 1.0
        self._degradation_confidence = 0.0
        self._last_update = time.time()


