# CHUNK 86 CS 01 — CONTROL INTENT TEMPORAL SMOOTHING
# ==============================================================================
#
# Purpose:
#   Smooth control intent over time so motion, framing, and camera
#   responses feel continuous, deliberate, and physically plausible
#   under jitter, latency, and authority transitions.
#
# Backbone truth:
#   Continuity is felt more than precision.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class ControlIntentTemporalSmoothing:
    """
    Control intent temporal smoothing.
    Applies adaptive, latency-aware smoothing to control vectors,
    preserving responsiveness while preventing jitter, snap,
    and perceptual discontinuity.
    """

    __slots__ = (
        "_smoothed_command",
        "_velocity_state",
        "_smooth_factor",
        "_responsiveness_bias",
        "_stability_confidence",
        "_last_update",
    )

    def __init__(self):
        self._smoothed_command: Dict[str, float] = {}
        self._velocity_state: Dict[str, float] = {}
        self._smooth_factor: float = 0.7
        self._responsiveness_bias: float = 0.5
        self._stability_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Temporal smoothing logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        raw_command: Dict[str, float],
        latency_estimate: float,
        authority_stability: float,
        safety_level: float,
    ) -> Dict[str, Any]:
        """
        Smooth control intent temporally.
        """
        now = time.time()

        latency = float(np.clip(latency_estimate, 0.0, 1.0))
        authority = float(np.clip(authority_stability, 0.0, 1.0))
        safety = float(np.clip(safety_level, 0.0, 1.0))

        # Adaptive smoothing factor
        target_smooth = float(np.clip(
            0.55
            + 0.25 * latency
            + 0.15 * (1.0 - authority)
            + 0.05 * safety,
            0.5,
            0.9,
        ))

        self._smooth_factor = float(
            0.9 * self._smooth_factor + 0.1 * target_smooth
        )

        # Responsiveness bias counterbalances smoothing
        self._responsiveness_bias = float(np.clip(
            0.6 * self._responsiveness_bias
            + 0.4 * authority * (1.0 - safety),
            0.2,
            0.8,
        ))

        smoothed: Dict[str, float] = {}

        for k, v in raw_command.items():
            prev = self._smoothed_command.get(k, v)
            vel = self._velocity_state.get(k, 0.0)

            # Critically damped smoothing with velocity memory
            delta = v - prev
            vel = (
                0.85 * vel
                + 0.15 * delta * (1.0 - self._smooth_factor)
            )

            value = (
                prev
                + self._responsiveness_bias * vel
                + (1.0 - self._smooth_factor) * delta
            )

            smoothed[k] = float(value)
            self._velocity_state[k] = float(vel)

        self._smoothed_command = smoothed

        # Stability confidence reflects smoothness vs responsiveness balance
        self._stability_confidence = float(np.clip(
            0.7 * self._stability_confidence
            + 0.2 * (1.0 - abs(self._smooth_factor - 0.7))
            + 0.1 * authority,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "smoothed_command": smoothed,
            "smooth_factor": self._smooth_factor,
            "responsiveness_bias": self._responsiveness_bias,
            "stability_confidence": self._stability_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset temporal smoothing state.
        """
        self._smoothed_command.clear()
        self._velocity_state.clear()
        self._smooth_factor = 0.7
        self._responsiveness_bias = 0.5
        self._stability_confidence = 0.0
        self._last_update = time.time()


