from typing import Dict, Any
import time
import numpy as np


class CommandSemanticValidation:
    """
    Command semantic validation layer.
    Ensures that command vectors are meaningful, non-contradictory,
    within physical and narrative bounds, and aligned with the
    current cinematic and safety context.
    """

    __slots__ = (
        "_validity_score",
        "_coherence_score",
        "_safety_score",
        "_validation_confidence",
        "_last_update",
    )

    def __init__(self):
        self._validity_score: float = 1.0
        self._coherence_score: float = 1.0
        self._safety_score: float = 1.0
        self._validation_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Semantic validation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        command: Dict[str, float],
        safety_level: float,
        narrative_phase: str,
        authority_context: str,
    ) -> Dict[str, Any]:
        """
        Validate semantic correctness of command intent.
        """
        now = time.time()

        safety = float(np.clip(safety_level, 0.0, 1.0))

        # Basic physical plausibility
        magnitude = float(
            np.sqrt(sum(v * v for v in command.values()))
        )

        self._validity_score = float(np.clip(
            1.0 - 0.4 * max(0.0, magnitude - 1.0),
            0.0,
            1.0,
        ))

        # Narrative coherence weighting
        phase_coherence_bias = {
            "setup": 0.9,
            "development": 1.0,
            "climax": 0.8,
            "resolution": 0.85,
        }.get(narrative_phase, 1.0)

        self._coherence_score = float(np.clip(
            phase_coherence_bias * self._validity_score,
            0.0,
            1.0,
        ))

        # Safety semantics tighten under elevated risk
        self._safety_score = float(np.clip(
            1.0 - 0.7 * safety,
            0.0,
            1.0,
        ))

        # Authority-aware tolerance
        authority_bias = {
            "ai": 1.0,
            "human": 0.95,
            "safety": 0.7,
        }.get(authority_context, 1.0)

        combined = (
            0.4 * self._validity_score
            + 0.35 * self._coherence_score
            + 0.25 * self._safety_score
        ) * authority_bias

        self._validation_confidence = float(np.clip(
            0.7 * self._validation_confidence + 0.3 * combined,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "validity_score": self._validity_score,
            "coherence_score": self._coherence_score,
            "safety_score": self._safety_score,
            "validation_confidence": self._validation_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset semantic validation state.
        """
        self._validity_score = 1.0
        self._coherence_score = 1.0
        self._safety_score = 1.0
        self._validation_confidence = 0.0
        self._last_update = time.time()


