# CHUNK 86 CU 01 — LATENCY-AWARE CONTROL PREDICTION
# ==============================================================================
#
# Purpose:
#   Predict near-future control intent to compensate for transport,
#   inference, and actuation latency so motion, framing, and response
#   feel immediate even when the system is delayed.
#
# Backbone truth:
#   Perceived immediacy matters more than real-time accuracy.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class LatencyAwareControlPrediction:
    """
    Latency-aware control prediction.
    Uses short-horizon kinematic prediction with confidence-weighted
    extrapolation to offset latency while avoiding overshoot,
    oscillation, or cinematic discontinuity.
    """

    __slots__ = (
        "_last_command",
        "_last_velocity",
        "_prediction_gain",
        "_confidence",
        "_last_update",
    )

    def __init__(self):
        self._last_command: Dict[str, float] = {}
        self._last_velocity: Dict[str, float] = {}
        self._prediction_gain: float = 0.0
        self._confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Prediction logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        current_command: Dict[str, float],
        latency_estimate: float,
        stability_confidence: float,
        safety_level: float,
    ) -> Dict[str, Any]:
        """
        Predict near-future control intent.
        """
        now = time.time()

        latency = float(np.clip(latency_estimate, 0.0, 1.0))
        stability = float(np.clip(stability_confidence, 0.0, 1.0))
        safety = float(np.clip(safety_level, 0.0, 1.0))

        # Prediction gain increases with latency but shrinks under risk
        target_gain = float(np.clip(
            0.6 * latency * stability * (1.0 - safety),
            0.0,
            0.6,
        ))

        self._prediction_gain = float(
            0.85 * self._prediction_gain + 0.15 * target_gain
        )

        predicted: Dict[str, float] = {}

        for k, v in current_command.items():
            prev = self._last_command.get(k, v)
            vel = self._last_velocity.get(k, 0.0)

            # Estimate velocity
            vel = 0.8 * vel + 0.2 * (v - prev)

            # Predict forward
            pred = v + self._prediction_gain * vel

            predicted[k] = float(pred)
            self._last_velocity[k] = float(vel)

        self._last_command = dict(current_command)

        # Prediction confidence
        self._confidence = float(np.clip(
            0.7 * self._confidence
            + 0.2 * stability
            + 0.1 * (1.0 - safety),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "predicted_command": predicted,
            "prediction_gain": self._prediction_gain,
            "prediction_confidence": self._confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset latency-aware prediction state.
        """
        self._last_command.clear()
        self._last_velocity.clear()
        self._prediction_gain = 0.0
        self._confidence = 0.0
        self._last_update = time.time()


