# ==============================================================================
#
# Purpose:
#   Broadcast unified control and cinematic intent across flight,
#   gimbal, camera, and cloud subsystems so all actors operate from
#   the same narrative and physical command state.
#
# Backbone truth:
#   One intent — many executors.
#
# ==============================================================================

from typing import Dict, Any
import time
import uuid
import numpy as np


class CrossSubsystemIntentBroadcasting:
    """
    Cross-subsystem intent broadcasting.
    Packages validated, smoothed, and predicted intent into a
    canonical broadcast frame that is consumed consistently by
    flight control, gimbal control, camera logic, and cloud agents.
    """

    __slots__ = (
        "_intent_id",
        "_broadcast_confidence",
        "_last_broadcast",
    )

    def __init__(self):
        self._intent_id: str = ""
        self._broadcast_confidence: float = 0.0
        self._last_broadcast: float = 0.0


    # --------------------------------------------------------------------------
    # Broadcast logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        command: Dict[str, float],
        authority_context: str,
        validation_confidence: float,
        prediction_confidence: float,
    ) -> Dict[str, Any]:
        """
        Broadcast unified intent to all subsystems.
        """
        now = time.time()

        val_conf = float(np.clip(validation_confidence, 0.0, 1.0))
        pred_conf = float(np.clip(prediction_confidence, 0.0, 1.0))

        # Generate new intent ID when authority or confidence changes meaningfully
        if (
            not self._intent_id
            or abs(val_conf - self._broadcast_confidence) > 0.2
        ):
            self._intent_id = str(uuid.uuid4())

        # Broadcast confidence aggregates trust in intent
        self._broadcast_confidence = float(np.clip(
            0.6 * self._broadcast_confidence
            + 0.25 * val_conf
            + 0.15 * pred_conf,
            0.0,
            1.0,
        ))

        payload = {
            "intent_id": self._intent_id,
            "authority": authority_context,
            "command": dict(command),
            "confidence": self._broadcast_confidence,
            "timestamp": now,
        }

        self._last_broadcast = now

        return payload


    def reset(self) -> None:
        """
        Reset broadcast state.
        """
        self._intent_id = ""
        self._broadcast_confidence = 0.0
        self._last_broadcast = time.time()


