# ==============================================================================
#
# Purpose:
#   Mediate between cinematic camera intent and physical flight
#   dynamics so framing, motion, and aircraft behavior cooperate
#   rather than fight — preserving both safety and composition.
#
# Backbone truth:
#   The camera suggests; the aircraft negotiates.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class CameraFlightCouplingMediator:
    """
    Camera–flight coupling mediator.
    Translates cinematic camera intent into flight-compatible
    adjustments while feeding back aircraft constraints so
    framing adapts gracefully instead of demanding impossibilities.
    """

    __slots__ = (
        "_coupling_strength",
        "_flight_compliance",
        "_camera_yield",
        "_mediation_confidence",
        "_last_update",
    )

    def __init__(self):
        self._coupling_strength: float = 0.7
        self._flight_compliance: float = 1.0
        self._camera_yield: float = 0.0
        self._mediation_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Coupling mediation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        camera_intent: Dict[str, float],
        flight_state: Dict[str, float],
        safety_level: float,
        narrative_phase: str,
    ) -> Dict[str, Any]:
        """
        Mediate camera and flight intent.
        """
        now = time.time()

        safety = float(np.clip(safety_level, 0.0, 1.0))

        # Flight compliance drops under high stress or safety pressure
        stress = float(np.clip(
            flight_state.get("dynamic_stress", 0.0),
            0.0,
            1.0,
        ))

        phase_coupling_bias = {
            "setup": 0.6,
            "development": 0.8,
            "climax": 1.0,
            "resolution": 0.7,
        }.get(narrative_phase, 0.8)

        self._flight_compliance = float(np.clip(
            1.0 - 0.6 * stress - 0.5 * safety,
            0.2,
            1.0,
        ))

        # Camera yields when flight cannot comply
        self._camera_yield = float(np.clip(
            1.0 - self._flight_compliance,
            0.0,
            0.8,
        ))

        # Coupling strength balances both sides
        target_coupling = float(np.clip(
            phase_coupling_bias * self._flight_compliance,
            0.3,
            1.0,
        ))

        self._coupling_strength = float(
            0.85 * self._coupling_strength + 0.15 * target_coupling
        )

        mediated_camera: Dict[str, float] = {}

        for k, v in camera_intent.items():
            mediated_camera[k] = float(
                v * self._coupling_strength * (1.0 - self._camera_yield)
            )

        # Confidence reflects harmony between camera & flight
        self._mediation_confidence = float(np.clip(
            0.7 * self._mediation_confidence
            + 0.2 * self._flight_compliance
            + 0.1 * phase_coupling_bias,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "mediated_camera_intent": mediated_camera,
            "coupling_strength": self._coupling_strength,
            "flight_compliance": self._flight_compliance,
            "camera_yield": self._camera_yield,
            "mediation_confidence": self._mediation_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset camera–flight coupling mediator.
        """
        self._coupling_strength = 0.7
        self._flight_compliance = 1.0
        self._camera_yield = 0.0
        self._mediation_confidence = 0.0
        self._last_update = time.time()


