#   onboard compute (Radxa), and mobile clients without split-brain
#   behavior — preserving authority, continuity, and safety under
#   variable latency and partial connectivity.
#
# Backbone truth:
#   Authority follows confidence, not location.
#
# ==============================================================================

from typing import Dict, Any
import time
import uuid
import numpy as np


class CloudOnboardIntentSynchronization:
    """
    Cloud ↔ onboard intent synchronization.
    Maintains a convergent intent state across distributed agents
    using confidence-weighted reconciliation and authority leasing
    to prevent divergence under network variability.
    """

    __slots__ = (
        "_current_intent_id",
        "_authority_lease",
        "_sync_confidence",
        "_last_sync",
    )

    def __init__(self):
        self._current_intent_id: str = ""
        self._authority_lease: Dict[str, float] = {
            "cloud": 0.0,
            "onboard": 1.0,
        }
        self._sync_confidence: float = 0.0
        self._last_sync: float = 0.0


    # --------------------------------------------------------------------------
    # Synchronization logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        local_intent: Dict[str, Any],
        remote_intent: Dict[str, Any],
        link_quality: float,
        safety_level: float,
    ) -> Dict[str, Any]:
        """
        Synchronize cloud and onboard intent states.
        """
        now = time.time()

        link = float(np.clip(link_quality, 0.0, 1.0))
        safety = float(np.clip(safety_level, 0.0, 1.0))

        local_conf = float(local_intent.get("confidence", 0.0))
        remote_conf = float(remote_intent.get("confidence", 0.0))

        # Authority lease favors stability and proximity under risk
        self._authority_lease["onboard"] = float(np.clip(
            0.6
            + 0.3 * (1.0 - link)
            + 0.1 * safety,
            0.0,
            1.0,
        ))

        self._authority_lease["cloud"] = float(
            1.0 - self._authority_lease["onboard"]
        )

        # Choose dominant intent
        weighted_local = local_conf * self._authority_lease["onboard"]
        weighted_remote = remote_conf * self._authority_lease["cloud"]

        if weighted_remote > weighted_local:
            chosen = dict(remote_intent)
        else:
            chosen = dict(local_intent)

        # Generate new intent ID if divergence detected
        if chosen.get("intent_id") != self._current_intent_id:
            self._current_intent_id = chosen.get(
                "intent_id", str(uuid.uuid4())
            )

        # Synchronization confidence
        self._sync_confidence = float(np.clip(
            0.7 * self._sync_confidence
            + 0.2 * max(local_conf, remote_conf)
            + 0.1 * link,
            0.0,
            1.0,
        ))

        self._last_sync = now

        return {
            "intent_id": self._current_intent_id,
            "chosen_intent": chosen,
            "authority_lease": dict(self._authority_lease),
            "sync_confidence": self._sync_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cloud–onboard synchronization state.
        """
        self._current_intent_id = ""
        self._authority_lease = {"cloud": 0.0, "onboard": 1.0}
        self._sync_confidence = 0.0
        self._last_sync = time.time()


