# ==============================================================================
# CHUNK 86 CY 01 — DISTRIBUTED STATE RECONCILIATION
# ==============================================================================
#
# Purpose:
#   Reconcile distributed state across camera, flight, cloud,
#   and mobile UI so all agents converge on a coherent operational
#   reality even after packet loss, delay, or partial failure.
#
# Backbone truth:
#   Consistency is negotiated, not imposed.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class DistributedStateReconciliation:
    """
    Distributed state reconciliation.
    Maintains a convergent system state using confidence-weighted,
    recency-aware reconciliation instead of brittle authoritative
    overrides — preserving continuity across distributed agents.
    """

    __slots__ = (
        "_state_cache",
        "_confidence_cache",
        "_last_update",
    )

    def __init__(self):
        self._state_cache: Dict[str, Any] = {}
        self._confidence_cache: Dict[str, float] = {}
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Reconciliation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        local_state: Dict[str, Any],
        remote_state: Dict[str, Any],
        local_confidence: float,
        remote_confidence: float,
        link_quality: float,
    ) -> Dict[str, Any]:
        """
        Reconcile distributed state.
        """
        now = time.time()

        lc = float(np.clip(local_confidence, 0.0, 1.0))
        rc = float(np.clip(remote_confidence, 0.0, 1.0))
        link = float(np.clip(link_quality, 0.0, 1.0))

        reconciled: Dict[str, Any] = {}

        # Confidence weighting favors stability under weak links
        local_weight = float(np.clip(
            0.6 + 0.3 * (1.0 - link),
            0.0,
            1.0,
        ))

        remote_weight = float(1.0 - local_weight)

        for key in set(local_state.keys()) | set(remote_state.keys()):
            lv = local_state.get(key)
            rv = remote_state.get(key)

            if lv is None:
                reconciled[key] = rv
                continue
            if rv is None:
                reconciled[key] = lv
                continue

            # Numeric values are blended; others resolved by confidence
            if isinstance(lv, (int, float)) and isinstance(rv, (int, float)):
                reconciled[key] = float(
                    local_weight * lv + remote_weight * rv
                )
            else:
                reconciled[key] = lv if lc >= rc else rv

        # Cache reconciled state
        self._state_cache = reconciled
        self._confidence_cache = {
            "local": lc,
            "remote": rc,
        }

        self._last_update = now

        return {
            "reconciled_state": reconciled,
            "local_weight": local_weight,
            "remote_weight": remote_weight,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset distributed state reconciliation.
        """
        self._state_cache.clear()
        self._confidence_cache.clear()
        self._last_update = time.time()


