# ==============================================================================
# CHUNK 86 CZ 01 — MULTI-AGENT DIRECTOR CONSENSUS
# ==============================================================================
#
# Purpose:
#   Form a unified “director mind” across multiple agents
#   (cloud AI, onboard AI, fallback logic) so decisions emerge
#   as consensus rather than competition.
#
# Backbone truth:
#   Great direction is agreement, not dominance.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import numpy as np


class MultiAgentDirectorConsensus:
    """
    Multi-agent director consensus.
    Aggregates intent proposals from distributed director agents
    using confidence-weighted agreement, dissent damping, and
    narrative alignment scoring.
    """

    __slots__ = (
        "_consensus_confidence",
        "_agent_weights",
        "_last_update",
    )

    def __init__(self, agent_ids: List[str]):
        self._agent_weights: Dict[str, float] = {
            agent_id: 1.0 / max(len(agent_ids), 1)
            for agent_id in agent_ids
        }
        self._consensus_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Consensus logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        agent_intents: Dict[str, Dict[str, Any]],
        narrative_phase: str,
        safety_level: float,
    ) -> Dict[str, Any]:
        """
        Form consensus across director agents.
        """
        now = time.time()

        safety = float(np.clip(safety_level, 0.0, 1.0))

        phase_alignment_bias = {
            "setup": 0.9,
            "development": 1.0,
            "climax": 0.85,
            "resolution": 0.9,
        }.get(narrative_phase, 1.0)

        consensus_command: Dict[str, float] = {}
        total_weight = 0.0

        # Aggregate commands by weighted agreement
        for agent_id, intent in agent_intents.items():
            weight = self._agent_weights.get(agent_id, 0.0)
            conf = float(intent.get("confidence", 0.0))

            effective_weight = weight * conf * phase_alignment_bias * (1.0 - safety)
            total_weight += effective_weight

            for k, v in intent.get("command", {}).items():
                consensus_command[k] = (
                    consensus_command.get(k, 0.0)
                    + effective_weight * v
                )

        if total_weight > 0.0:
            for k in consensus_command:
                consensus_command[k] /= total_weight

        # Update agent weights based on agreement with consensus
        for agent_id, intent in agent_intents.items():
            agreement = 0.0
            cmd = intent.get("command", {})
            for k, v in consensus_command.items():
                agreement += 1.0 - abs(cmd.get(k, v) - v)
            agreement /= max(len(consensus_command), 1)

            self._agent_weights[agent_id] = float(np.clip(
                0.8 * self._agent_weights.get(agent_id, 0.0)
                + 0.2 * agreement,
                0.05,
                0.7,
            ))

        # Normalize weights
        norm = sum(self._agent_weights.values())
        if norm > 0.0:
            for k in self._agent_weights:
                self._agent_weights[k] /= norm

        # Consensus confidence
        self._consensus_confidence = float(np.clip(
            0.7 * self._consensus_confidence
            + 0.2 * phase_alignment_bias
            + 0.1 * (1.0 - safety),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "consensus_command": consensus_command,
            "agent_weights": dict(self._agent_weights),
            "consensus_confidence": self._consensus_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset multi-agent director consensus.
        """
        for k in self._agent_weights:
            self._agent_weights[k] = 1.0 / max(len(self._agent_weights), 1)
        self._consensus_confidence = 0.0
        self._last_update = time.time()


