# CHUNK 86 DA 01 — INTENT PERSISTENCE & RECOVERY
# ==============================================================================
#
# Purpose:
#   Persist cinematic and control intent across transient failures,
#   restarts, and reconnections so the system resumes with memory,
#   not amnesia — preserving narrative continuity and operator trust.
#
# Backbone truth:
#   Recovery should feel like continuation.
#
# ==============================================================================

from typing import Dict, Any, Optional
import time
import json
import os
import numpy as np


class IntentPersistenceRecovery:
    """
    Intent persistence & recovery.
    Stores a compact, narratively meaningful intent snapshot and
    restores it progressively after failures, avoiding sudden jumps
    or unsafe resumption.
    """

    __slots__ = (
        "_snapshot_path",
        "_last_snapshot",
        "_recovery_confidence",
        "_last_update",
    )

    def __init__(self, snapshot_path: str = "/tmp/intent_snapshot.json"):
        self._snapshot_path = snapshot_path
        self._last_snapshot: Optional[Dict[str, Any]] = None
        self._recovery_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Persistence logic
    # --------------------------------------------------------------------------

    def persist(
        self,
        intent: Dict[str, Any],
        confidence: float,
        narrative_phase: str,
    ) -> None:
        """
        Persist current intent snapshot.
        """
        snapshot = {
            "intent": intent,
            "confidence": float(np.clip(confidence, 0.0, 1.0)),
            "narrative_phase": narrative_phase,
            "timestamp": time.time(),
        }

        try:
            with open(self._snapshot_path, "w") as f:
                json.dump(snapshot, f)
            self._last_snapshot = snapshot
        except Exception:
            pass


    # --------------------------------------------------------------------------
    # Recovery logic
    # --------------------------------------------------------------------------

    def recover(self) -> Optional[Dict[str, Any]]:
        """
        Recover last persisted intent snapshot.
        """
        if not os.path.exists(self._snapshot_path):
            return None

        try:
            with open(self._snapshot_path, "r") as f:
                snapshot = json.load(f)
        except Exception:
            return None

        age = time.time() - snapshot.get("timestamp", 0.0)

        # Confidence decays with age
        self._recovery_confidence = float(np.clip(
            snapshot.get("confidence", 0.0) * np.exp(-0.1 * age),
            0.0,
            1.0,
        ))

        self._last_update = time.time()

        return {
            "intent": snapshot.get("intent"),
            "narrative_phase": snapshot.get("narrative_phase"),
            "recovery_confidence": self._recovery_confidence,
            "age_seconds": age,
        }


    def reset(self) -> None:
        """
        Reset intent persistence state.
        """
        self._last_snapshot = None
        self._recovery_confidence = 0.0
        self._last_update = time.time()


