from typing import Dict, Any
import time
import numpy as np


class FailureAwareNarrativeContinuity:
    """
    Failure-aware narrative continuity.
    Converts technical degradation into perceptually motivated
    cinematic simplification — slowing motion, widening framing,
    reducing complexity — while maintaining emotional intent.
    """

    __slots__ = (
        "_failure_level",
        "_continuity_strength",
        "_simplification_bias",
        "_confidence",
        "_last_update",
    )

    def __init__(self):
        self._failure_level: float = 0.0
        self._continuity_strength: float = 1.0
        self._simplification_bias: float = 0.0
        self._confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Failure-aware continuity logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        subsystem_health: Dict[str, float],
        safety_level: float,
        narrative_phase: str,
        emotional_momentum: float,
    ) -> Dict[str, Any]:
        """
        Maintain narrative continuity under failure.
        """
        now = time.time()

        safety = float(np.clip(safety_level, 0.0, 1.0))
        emotion = float(np.clip(emotional_momentum, 0.0, 1.0))

        # Aggregate failure level (lowest health dominates)
        if subsystem_health:
            min_health = min(
                float(np.clip(v, 0.0, 1.0))
                for v in subsystem_health.values()
            )
            target_failure = 1.0 - min_health
        else:
            target_failure = 0.0

        self._failure_level = float(
            0.85 * self._failure_level + 0.15 * target_failure
        )

        phase_continuity_bias = {
            "setup": 0.9,
            "development": 0.8,
            "climax": 0.6,
            "resolution": 0.85,
        }.get(narrative_phase, 0.8)

        # Continuity strength weakens gracefully
        self._continuity_strength = float(np.clip(
            1.0
            - 0.6 * self._failure_level
            - 0.4 * safety,
            0.3,
            1.0,
        ))

        # Simplification bias rises with failure
        self._simplification_bias = float(np.clip(
            0.7 * self._simplification_bias
            + 0.3 * self._failure_level * phase_continuity_bias,
            0.0,
            1.0,
        ))

        # Confidence reflects coherence under stress
        self._confidence = float(np.clip(
            0.7 * self._confidence
            + 0.2 * self._continuity_strength
            + 0.1 * (1.0 - self._failure_level),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "failure_level": self._failure_level,
            "continuity_strength": self._continuity_strength,
            "simplification_bias": self._simplification_bias,
            "confidence": self._confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset failure-aware narrative continuity.
        """
        self._failure_level = 0.0
        self._continuity_strength = 1.0
        self._simplification_bias = 0.0
        self._confidence = 0.0
        self._last_update = time.time()


