from typing import Dict, Any
import time
import numpy as np


class SystemSelfAssessment:
    """
    System self-assessment & confidence broadcasting.
    Aggregates internal performance signals into a perceptually
    meaningful confidence metric that reflects not just safety,
    but cinematic quality and narrative coherence.
    """

    __slots__ = (
        "_stability_score",
        "_coherence_score",
        "_safety_score",
        "_cinematic_score",
        "_overall_confidence",
        "_last_update",
    )

    def __init__(self):
        self._stability_score: float = 1.0
        self._coherence_score: float = 1.0
        self._safety_score: float = 1.0
        self._cinematic_score: float = 1.0
        self._overall_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Self-assessment logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        flight_stability: float,
        narrative_coherence: float,
        safety_level: float,
        cinematic_quality: float,
    ) -> Dict[str, Any]:
        """
        Compute and broadcast system confidence.
        """
        now = time.time()

        self._stability_score = float(np.clip(flight_stability, 0.0, 1.0))
        self._coherence_score = float(np.clip(narrative_coherence, 0.0, 1.0))
        self._safety_score = float(np.clip(1.0 - safety_level, 0.0, 1.0))
        self._cinematic_score = float(np.clip(cinematic_quality, 0.0, 1.0))

        # Weighted confidence favors safety and coherence
        target_confidence = (
            0.35 * self._safety_score
            + 0.25 * self._stability_score
            + 0.25 * self._coherence_score
            + 0.15 * self._cinematic_score
        )

        self._overall_confidence = float(np.clip(
            0.7 * self._overall_confidence + 0.3 * target_confidence,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "stability": self._stability_score,
            "coherence": self._coherence_score,
            "safety": self._safety_score,
            "cinematic": self._cinematic_score,
            "overall_confidence": self._overall_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset self-assessment state.
        """
        self._stability_score = 1.0
        self._coherence_score = 1.0
        self._safety_score = 1.0
        self._cinematic_score = 1.0
        self._overall_confidence = 0.0
        self._last_update = time.time()


