from typing import Dict, Any
import time
import numpy as np


class OperatorTrustTransparency:
    """
    Operator trust & transparency layer.
    Converts internal director state into concise, semantically
    meaningful signals for UI, logging, and human oversight.
    """

    __slots__ = (
        "_exposed_confidence",
        "_intent_clarity",
        "_risk_disclosure",
        "_operator_load",
        "_last_update",
    )

    def __init__(self):
        self._exposed_confidence: float = 0.0
        self._intent_clarity: float = 0.0
        self._risk_disclosure: float = 0.0
        self._operator_load: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Transparency logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        system_confidence: float,
        intent_confidence: float,
        safety_level: float,
        failure_level: float,
    ) -> Dict[str, Any]:
        """
        Generate operator-facing transparency signals.
        """
        now = time.time()

        sys_conf = float(np.clip(system_confidence, 0.0, 1.0))
        intent_conf = float(np.clip(intent_confidence, 0.0, 1.0))
        safety = float(np.clip(safety_level, 0.0, 1.0))
        failure = float(np.clip(failure_level, 0.0, 1.0))

        # Exposed confidence is conservative
        self._exposed_confidence = float(np.clip(
            0.6 * sys_conf + 0.4 * intent_conf,
            0.0,
            1.0,
        ))

        # Intent clarity drops with disagreement or degradation
        self._intent_clarity = float(np.clip(
            intent_conf * (1.0 - failure),
            0.0,
            1.0,
        ))

        # Risk disclosure rises early, not late
        self._risk_disclosure = float(np.clip(
            0.5 * safety + 0.5 * failure,
            0.0,
            1.0,
        ))

        # Operator cognitive load estimation
        self._operator_load = float(np.clip(
            0.4 * self._risk_disclosure
            + 0.3 * (1.0 - self._intent_clarity)
            + 0.3 * (1.0 - self._exposed_confidence),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "confidence": self._exposed_confidence,
            "intent_clarity": self._intent_clarity,
            "risk_level": self._risk_disclosure,
            "operator_load": self._operator_load,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset operator transparency state.
        """
        self._exposed_confidence = 0.0
        self._intent_clarity = 0.0
        self._risk_disclosure = 0.0
        self._operator_load = 0.0
        self._last_update = time.time()


