# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class NarrativeShutdownHandoff:
    """
    Narrative shutdown & handoff logic.
    Shapes mission termination, control transfer, and landing
    behavior so transitions feel deliberate, safe, and narratively
    resolved — even under degraded conditions.
    """

    __slots__ = (
        "_shutdown_progress",
        "_handoff_confidence",
        "_authority_target",
        "_closure_strength",
        "_last_update",
    )

    def __init__(self):
        self._shutdown_progress: float = 0.0
        self._handoff_confidence: float = 0.0
        self._authority_target: str = "onboard"
        self._closure_strength: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Shutdown & handoff logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        shutdown_request: bool,
        handoff_target: str,
        safety_level: float,
        system_confidence: float,
        narrative_phase: str,
    ) -> Dict[str, Any]:
        """
        Execute narrative shutdown and authority handoff.
        """
        now = time.time()

        safety = float(np.clip(safety_level, 0.0, 1.0))
        sys_conf = float(np.clip(system_confidence, 0.0, 1.0))

        # Closure bias depends on narrative phase
        phase_closure_bias = {
            "setup": 0.4,
            "development": 0.6,
            "climax": 1.0,
            "resolution": 0.9,
        }.get(narrative_phase, 0.7)

        if shutdown_request:
            # Progress shutdown gradually unless safety demands urgency
            target_progress = float(np.clip(
                0.3 + 0.7 * phase_closure_bias + 0.4 * safety,
                0.0,
                1.0,
            ))
        else:
            target_progress = 0.0

        self._shutdown_progress = float(np.clip(
            0.8 * self._shutdown_progress + 0.2 * target_progress,
            0.0,
            1.0,
        ))

        # Authority handoff confidence
        self._handoff_confidence = float(np.clip(
            0.7 * self._handoff_confidence
            + 0.2 * sys_conf
            + 0.1 * (1.0 - safety),
            0.0,
            1.0,
        ))

        if self._handoff_confidence > 0.6:
            self._authority_target = handoff_target

        # Closure strength defines how “complete” the ending feels
        self._closure_strength = float(np.clip(
            0.6 * self._closure_strength
            + 0.4 * self._shutdown_progress * phase_closure_bias,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "shutdown_progress": self._shutdown_progress,
            "handoff_target": self._authority_target,
            "handoff_confidence": self._handoff_confidence,
            "closure_strength": self._closure_strength,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset narrative shutdown & handoff state.
        """
        self._shutdown_progress = 0.0
        self._handoff_confidence = 0.0
        self._authority_target = "onboard"
        self._closure_strength = 0.0
        self._last_update = time.time()


