from typing import Dict, Any
import time
import numpy as np


class PostFlightNarrativeReflection:
    """
    Post-flight narrative reflection memory.
    Distills mission-wide signals — emotional arcs, pacing stability,
    safety tension, and cinematic payoff — into a reusable narrative
    memory suitable for cross-mission learning.
    """

    __slots__ = (
        "_reflection",
        "_reflection_confidence",
        "_last_update",
    )

    def __init__(self):
        self._reflection: Dict[str, Any] = {}
        self._reflection_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Reflection logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        emotional_arc: Dict[str, float],
        narrative_stability: float,
        safety_pressure: float,
        cinematic_payoff: float,
        operator_interventions: int,
    ) -> Dict[str, Any]:
        """
        Generate post-flight narrative reflection.
        """
        now = time.time()

        stability = float(np.clip(narrative_stability, 0.0, 1.0))
        safety = float(np.clip(safety_pressure, 0.0, 1.0))
        payoff = float(np.clip(cinematic_payoff, 0.0, 1.0))

        intervention_penalty = float(np.clip(
            1.0 - 0.15 * operator_interventions,
            0.0,
            1.0,
        ))

        # Reflection captures *shape*, not frame data
        self._reflection = {
            "emotional_arc": dict(emotional_arc),
            "stability": stability,
            "safety_pressure": safety,
            "cinematic_payoff": payoff,
            "operator_interventions": operator_interventions,
        }

        # Confidence reflects clarity of outcome
        self._reflection_confidence = float(np.clip(
            0.4 * payoff
            + 0.3 * stability
            + 0.2 * intervention_penalty
            + 0.1 * (1.0 - safety),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "reflection": self._reflection,
            "confidence": self._reflection_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset post-flight narrative reflection.
        """
        self._reflection.clear()
        self._reflection_confidence = 0.0
        self._last_update = time.time()


