from typing import Dict, Any
import time
import json
import os
import numpy as np


class CrossMissionStylePersistence:
    """
    Cross-mission identity & style persistence.
    Maintains a slowly adapting style vector that influences framing,
    motion, exposure bias, color preference, and pacing across
    flights — without locking the system into rigidity.
    """

    __slots__ = (
        "_style_vector",
        "_adaptation_rate",
        "_confidence",
        "_storage_path",
        "_last_update",
    )

    def __init__(
        self,
        storage_path: str = "/tmp/director_style.json",
        adaptation_rate: float = 0.05,
    ):
        self._storage_path = storage_path
        self._adaptation_rate = float(np.clip(adaptation_rate, 0.01, 0.2))
        self._style_vector: Dict[str, float] = {
            "motion_preference": 0.5,
            "contrast_bias": 0.5,
            "luma_bias": 0.5,
            "shot_linger": 0.5,
            "risk_tolerance": 0.5,
        }
        self._confidence: float = 0.0
        self._last_update: float = 0.0

        self._load()


    # --------------------------------------------------------------------------
    # Persistence logic
    # --------------------------------------------------------------------------

    def _load(self) -> None:
        if not os.path.exists(self._storage_path):
            return
        try:
            with open(self._storage_path, "r") as f:
                data = json.load(f)
            if isinstance(data, dict):
                self._style_vector.update(
                    {k: float(np.clip(v, 0.0, 1.0)) for k, v in data.items()}
                )
        except Exception:
            pass


    def _save(self) -> None:
        try:
            with open(self._storage_path, "w") as f:
                json.dump(self._style_vector, f)
        except Exception:
            pass


    # --------------------------------------------------------------------------
    # Style adaptation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        reflection: Dict[str, Any],
        reflection_confidence: float,
    ) -> Dict[str, Any]:
        """
        Update and expose cross-mission style.
        """
        now = time.time()

        conf = float(np.clip(reflection_confidence, 0.0, 1.0))
        rate = self._adaptation_rate * conf

        # Adapt style based on narrative outcome
        payoff = float(reflection.get("cinematic_payoff", 0.5))
        safety = float(reflection.get("safety_pressure", 0.5))

        self._style_vector["motion_preference"] += rate * (payoff - 0.5)
        self._style_vector["contrast_bias"] += rate * (payoff - safety)
        self._style_vector["luma_bias"] += rate * (0.5 - safety)
        self._style_vector["shot_linger"] += rate * (payoff - 0.5)
        self._style_vector["risk_tolerance"] += rate * (0.5 - safety)

        # Clamp style vector
        for k in self._style_vector:
            self._style_vector[k] = float(
                np.clip(self._style_vector[k], 0.0, 1.0)
            )

        self._confidence = float(np.clip(
            0.8 * self._confidence + 0.2 * conf,
            0.0,
            1.0,
        ))

        self._last_update = now
        self._save()

        return {
            "style_vector": dict(self._style_vector),
            "confidence": self._confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset director style to neutral baseline.
        """
        for k in self._style_vector:
            self._style_vector[k] = 0.5
        self._confidence = 0.0
        self._last_update = time.time()
        self._save()


