from typing import Dict, Any
import time
import numpy as np
import json


class DirectorLearningSignalExport:
    """
    Director learning signal export.
    Packages distilled narrative, cinematic, and safety outcomes into
    low-dimensional learning vectors suitable for offline training,
    analytics, and cross-fleet improvement — without leaking raw
    footage or executable control data.
    """

    __slots__ = (
        "_last_export",
        "_export_confidence",
    )

    def __init__(self):
        self._last_export: float = 0.0
        self._export_confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Export logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        reflection: Dict[str, Any],
        style_vector: Dict[str, float],
        system_confidence: float,
        export_target: str = "cloud",
    ) -> Dict[str, Any]:
        """
        Generate director learning signal.
        """
        now = time.time()

        sys_conf = float(np.clip(system_confidence, 0.0, 1.0))

        # Learning signal is intentionally low-bandwidth
        learning_signal = {
            "timestamp": now,
            "emotional_arc": reflection.get("emotional_arc", {}),
            "cinematic_payoff": reflection.get("cinematic_payoff", 0.0),
            "safety_pressure": reflection.get("safety_pressure", 0.0),
            "operator_interventions": reflection.get(
                "operator_interventions", 0
            ),
            "style_vector": dict(style_vector),
        }

        # Export confidence reflects system reliability
        self._export_confidence = float(np.clip(
            0.7 * self._export_confidence + 0.3 * sys_conf,
            0.0,
            1.0,
        ))

        self._last_export = now

        return {
            "export_target": export_target,
            "learning_signal": learning_signal,
            "confidence": self._export_confidence,
            "timestamp": now,
        }


    def serialize(self, payload: Dict[str, Any]) -> str:
        """
        Serialize learning signal for transport or storage.
        """
        try:
            return json.dumps(payload)
        except Exception:
            return "{}"


    def reset(self) -> None:
        """
        Reset learning signal export state.
        """
        self._last_export = 0.0
        self._export_confidence = 0.0


