# ==============================================================================
#
# Purpose:
#   Bind the Camera Director AI into the drone backbone through a
#   clean, explicit, testable interface so cinematic intelligence
#   becomes a live participant in mission execution — without
#   violating safety or modularity.
#
# Backbone truth:
#   Intelligence plugs in; it does not sprawl.
#
# ==============================================================================

from typing import Dict, Any, Callable
import time


class CameraDirectorBackboneBinding:
    """
    Camera Director ↔ Backbone binding interface.
    Provides a narrow, explicit contract between the director
    intelligence and the drone backbone, enabling deterministic
    integration, supervision, and controlled authority transfer.
    """

    __slots__ = (
        "_director",
        "_emit_command",
        "_emit_camera",
        "_emit_status",
        "_last_tick",
    )

    def __init__(
        self,
        director: Any,
        emit_command: Callable[[Dict[str, float]], None],
        emit_camera: Callable[[Dict[str, float]], None],
        emit_status: Callable[[Dict[str, Any]], None],
    ):
        self._director = director
        self._emit_command = emit_command
        self._emit_camera = emit_camera
        self._emit_status = emit_status
        self._last_tick = 0.0


    # --------------------------------------------------------------------------
    # Execution binding
    # --------------------------------------------------------------------------

    def tick(
        self,
        sensor_state: Dict[str, Any],
        operator_input: Dict[str, Any],
        system_state: Dict[str, Any],
    ) -> None:
        """
        Execute one director tick inside backbone.
        """
        now = time.time()

        output = self._director.step(
            sensor_state=sensor_state,
            operator_input=operator_input,
            system_state=system_state,
        )

        # Explicit emission paths
        if "flight_command" in output:
            self._emit_command(output["flight_command"])

        if "camera_command" in output:
            self._emit_camera(output["camera_command"])

        # Status is always emitted
        self._emit_status({
            "director_confidence": output.get("confidence", 0.0),
            "narrative_phase": output.get("narrative_phase"),
            "timestamp": now,
        })

        self._last_tick = now


    def reset(self) -> None:
        """
        Reset binding state.
        """
        self._last_tick = time.time()


