# CHUNK 86 G 01 — REAL-TIME CAMERA DIRECTOR EXECUTION LOOP
# ==============================================================================
#
# Purpose:
#   Execute the Camera Director AI as a deterministic, real-time loop
#   that integrates perception, narrative state, safety constraints,
#   and control emission at a stable cadence suitable for flight.
#
# Backbone truth:
#   Intelligence must run on time — every time.
#
# ==============================================================================

from typing import Dict, Any, Optional
import time


class CameraDirectorExecutionLoop:
    """
    Real-time camera director execution loop.
    Coordinates perception ingestion, narrative evaluation,
    intent synthesis, safety gating, and command emission at
    a bounded, predictable rate.
    """

    __slots__ = (
        "_tick_hz",
        "_dt",
        "_last_tick",
        "_running",
    )

    def __init__(self, tick_hz: float = 30.0):
        self._tick_hz = float(max(5.0, min(tick_hz, 60.0)))
        self._dt = 1.0 / self._tick_hz
        self._last_tick: float = 0.0
        self._running: bool = False


    # --------------------------------------------------------------------------
    # Loop control
    # --------------------------------------------------------------------------

    def start(self) -> None:
        """
        Start execution loop.
        """
        self._running = True
        self._last_tick = time.time()


    def stop(self) -> None:
        """
        Stop execution loop.
        """
        self._running = False


    # --------------------------------------------------------------------------
    # Execution step
    # --------------------------------------------------------------------------

    def tick(
        self,
        director_binding,
        sensor_state: Dict[str, Any],
        operator_input: Dict[str, Any],
        system_state: Dict[str, Any],
    ) -> Optional[Dict[str, Any]]:
        """
        Execute one bounded director tick.
        """
        if not self._running:
            return None

        now = time.time()
        elapsed = now - self._last_tick

        if elapsed < self._dt:
            return None

        # Advance clock deterministically
        self._last_tick = now

        # Execute director via binding
        director_binding.tick(
            sensor_state=sensor_state,
            operator_input=operator_input,
            system_state=system_state,
        )

        return {
            "tick_time": now,
            "dt": elapsed,
        }


    def status(self) -> Dict[str, Any]:
        """
        Execution loop status.
        """
        return {
            "running": self._running,
            "tick_hz": self._tick_hz,
            "last_tick": self._last_tick,
        }


