# ==============================================================================
# CHUNK 86 H 01 — AI ↔ MAVLINK SAFETY INTERLOCK LAYER
# ==============================================================================
#
# Purpose:
#   Enforce a hard, non-bypassable safety interlock between AI-driven
#   cinematic intent and MAVLink flight control so no AI command can
#   violate flight-critical constraints, envelopes, or failsafes.
#
# Backbone truth:
#   The AI may suggest — the flight controller decides.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class AIMAVLinkSafetyInterlock:
    """
    AI ↔ MAVLink safety interlock layer.
    Gates AI-generated control commands against hard flight safety
    constraints enforced by MAVLink/FC logic. This layer may reduce,
    reshape, or fully block commands — but never amplify them.
    """

    __slots__ = (
        "_interlock_confidence",
        "_last_block_reason",
        "_last_update",
    )

    def __init__(self):
        self._interlock_confidence: float = 1.0
        self._last_block_reason: str = ""
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Safety gating logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        ai_command: Dict[str, float],
        mavlink_limits: Dict[str, float],
        failsafe_state: Dict[str, bool],
        safety_level: float,
    ) -> Dict[str, Any]:
        """
        Gate AI command through MAVLink safety constraints.
        """
        now = time.time()

        safety = float(np.clip(safety_level, 0.0, 1.0))
        gated_command: Dict[str, float] = {}
        blocked = False

        # Immediate block if any failsafe is active
        if any(bool(v) for v in failsafe_state.values()):
            blocked = True
            self._last_block_reason = "failsafe_active"
        else:
            for axis, value in ai_command.items():
                limit = float(mavlink_limits.get(axis, 1.0))
                # Safety margin tightens as safety_level rises
                margin = limit * (1.0 - 0.5 * safety)
                gated_value = float(np.clip(value, -margin, margin))
                gated_command[axis] = gated_value
                if abs(gated_value) < abs(value):
                    blocked = True
                    self._last_block_reason = "envelope_limit"

        # Interlock confidence drops when intervention is required
        self._interlock_confidence = float(np.clip(
            0.8 * self._interlock_confidence
            + 0.2 * (0.0 if blocked else 1.0),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "allowed": not blocked,
            "command": {} if blocked else gated_command,
            "interlock_confidence": self._interlock_confidence,
            "block_reason": self._last_block_reason,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset safety interlock state.
        """
        self._interlock_confidence = 1.0
        self._last_block_reason = ""
        self._last_update = time.time()


# ==============================================================================
# END OF CHUNK 86 H 01
# ==============================================================================
# ==============================================================================
# CHUNK 86 I 01 — CLOUD COMMAND ARBITRATION SPINE
# ==============================================================================
#
# Purpose:
#   Arbitrate commands originating from cloud AI, mobile clients,
#   and onboard autonomy into a single coherent command stream,
#   preventing oscillation, authority leakage, or unsafe overrides.
#
# Backbone truth:
#   Authority is contextual, not absolute.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class CloudCommandArbitrationSpine:
    """
    Cloud command arbitration spine.
    Resolves multi-origin command intent using confidence,
    freshness, authority lease, and safety context so only
    one executable command stream reaches flight control.
    """

    __slots__ = (
        "_authority_weights",
        "_last_command_time",
        "_arbitration_confidence",
        "_last_update",
    )

    def __init__(self):
        self._authority_weights: Dict[str, float] = {
            "onboard": 0.6,
            "cloud": 0.3,
            "operator": 0.1,
        }
        self._last_command_time: Dict[str, float] = {}
        self._arbitration_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Arbitration logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        command_sources: Dict[str, Dict[str, Any]],
        safety_level: float,
        link_quality: float,
    ) -> Dict[str, Any]:
        """
        Arbitrate between multiple command sources.
        """
        now = time.time()

        safety = float(np.clip(safety_level, 0.0, 1.0))
        link = float(np.clip(link_quality, 0.0, 1.0))

        best_score = -1.0
        chosen_source = None
        chosen_command: Dict[str, float] = {}

        for source, payload in command_sources.items():
            command = payload.get("command", {})
            confidence = float(payload.get("confidence", 0.0))
            timestamp = float(payload.get("timestamp", 0.0))

            freshness = float(np.exp(-0.5 * (now - timestamp)))
            authority = float(self._authority_weights.get(source, 0.0))

            # Authority shifts toward onboard under poor link or high risk
            if source == "cloud":
                authority *= link * (1.0 - safety)
            if source == "onboard":
                authority *= 1.0 + 0.5 * (1.0 - link)

            score = confidence * freshness * authority

            if score > best_score:
                best_score = score
                chosen_source = source
                chosen_command = dict(command)

        self._arbitration_confidence = float(np.clip(
            0.7 * self._arbitration_confidence
            + 0.3 * max(best_score, 0.0),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "chosen_source": chosen_source,
            "command": chosen_command,
            "arbitration_confidence": self._arbitration_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cloud command arbitration state.
        """
        self._arbitration_confidence = 0.0
        self._last_update = time.time()


