# ==============================================================================
# CHUNK 86 J 01 — OPERATOR OVERRIDE INJECTION LAYER
# ==============================================================================
#
# Purpose:
#   Inject human operator control inputs into the autonomous
#   execution pipeline in a graded, reversible, and narratively
#   coherent manner — without destabilizing AI state or flight safety.
#
# Backbone truth:
#   Human intent should bend autonomy, not shatter it.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class OperatorOverrideInjection:
    """
    Operator override injection layer.
    Allows real-time operator input to modulate, bias, or temporarily
    supersede AI-generated commands while preserving continuity,
    recoverability, and safety guarantees.
    """

    __slots__ = (
        "_override_strength",
        "_override_decay",
        "_last_operator_input",
        "_override_active",
        "_last_update",
    )

    def __init__(self, override_decay: float = 0.85):
        self._override_strength: float = 0.0
        self._override_decay = float(np.clip(override_decay, 0.7, 0.98))
        self._last_operator_input: Dict[str, float] = {}
        self._override_active: bool = False
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Override logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        ai_command: Dict[str, float],
        operator_input: Dict[str, float],
        operator_intent_strength: float,
    ) -> Dict[str, Any]:
        """
        Blend operator override into AI command stream.
        """
        now = time.time()

        intent = float(np.clip(operator_intent_strength, 0.0, 1.0))

        # Update override strength
        if operator_input:
            self._override_strength = float(np.clip(
                0.7 * self._override_strength + 0.3 * intent,
                0.0,
                1.0,
            ))
            self._override_active = True
            self._last_operator_input = dict(operator_input)
        else:
            self._override_strength *= self._override_decay
            if self._override_strength < 0.05:
                self._override_strength = 0.0
                self._override_active = False

        blended_command: Dict[str, float] = {}

        for axis in set(ai_command.keys()) | set(self._last_operator_input.keys()):
            ai_val = float(ai_command.get(axis, 0.0))
            op_val = float(self._last_operator_input.get(axis, ai_val))

            # Operator influence scales smoothly
            blended = (
                (1.0 - self._override_strength) * ai_val
                + self._override_strength * op_val
            )
            blended_command[axis] = blended

        self._last_update = now

        return {
            "command": blended_command,
            "override_strength": self._override_strength,
            "override_active": self._override_active,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset operator override state.
        """
        self._override_strength = 0.0
        self._override_active = False
        self._last_operator_input.clear()
        self._last_update = time.time()


