# CHUNK 86 K 01 — MISSION TERMINATION & POST-AUTHORITY CLEANUP
# ==============================================================================
#
# Purpose:
#   Execute a controlled, narratively complete mission termination
#   sequence that cleanly releases authority, flushes memory,
#   finalizes logs, and leaves the system in a stable, resumable state.
#
# Backbone truth:
#   A mission is not finished until nothing unsafe remains.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class MissionTerminationCleanup:
    """
    Mission termination & post-authority cleanup.
    Ensures that all autonomous authority is relinquished safely,
    all narrative and learning memory is finalized, and all control
    pathways are returned to a known, benign baseline.
    """

    __slots__ = (
        "_termination_progress",
        "_authority_released",
        "_memory_flushed",
        "_cleanup_complete",
        "_last_update",
    )

    def __init__(self):
        self._termination_progress: float = 0.0
        self._authority_released: bool = False
        self._memory_flushed: bool = False
        self._cleanup_complete: bool = False
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Termination logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        termination_requested: bool,
        vehicle_disarmed: bool,
        memory_ready: bool,
        log_flush_ready: bool,
    ) -> Dict[str, Any]:
        """
        Advance mission termination state machine.
        """
        now = time.time()

        if termination_requested:
            self._termination_progress = float(np.clip(
                self._termination_progress + 0.15,
                0.0,
                1.0,
            ))

        # Authority release occurs early but only once
        if self._termination_progress > 0.3 and not self._authority_released:
            self._authority_released = True

        # Memory flush waits for safe vehicle state
        if vehicle_disarmed and memory_ready:
            self._memory_flushed = True

        # Cleanup completes only when everything is safe
        if (
            self._termination_progress >= 1.0
            and self._authority_released
            and self._memory_flushed
            and log_flush_ready
        ):
            self._cleanup_complete = True

        self._last_update = now

        return {
            "termination_progress": self._termination_progress,
            "authority_released": self._authority_released,
            "memory_flushed": self._memory_flushed,
            "cleanup_complete": self._cleanup_complete,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset termination state.
        """
        self._termination_progress = 0.0
        self._authority_released = False
        self._memory_flushed = False
        self._cleanup_complete = False
        self._last_update = time.time()


