from typing import Dict, Any
import time
import numpy as np


class DirectorAppTelemetryBridge:
    """
    Camera Director AI → App telemetry bridge.
    Translates internal director state into compact, human-readable,
    UI-safe telemetry that communicates what the AI is doing and why,
    without exposing control pathways or raw flight data.
    """

    __slots__ = (
        "_last_publish",
        "_publish_rate_hz",
        "_confidence_smooth",
    )

    def __init__(self, publish_rate_hz: float = 5.0):
        self._publish_rate_hz = float(np.clip(publish_rate_hz, 1.0, 15.0))
        self._last_publish: float = 0.0
        self._confidence_smooth: float = 0.0


    # --------------------------------------------------------------------------
    # Telemetry publish logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        director_state: Dict[str, Any],
        mission_state: Dict[str, Any],
        link_quality: float,
    ) -> Dict[str, Any]:
        """
        Produce UI-safe director telemetry payload.
        """
        now = time.time()
        dt = now - self._last_publish

        if dt < (1.0 / self._publish_rate_hz):
            return {}

        self._last_publish = now

        link = float(np.clip(link_quality, 0.0, 1.0))
        confidence = float(np.clip(
            director_state.get("confidence", 0.0), 0.0, 1.0
        ))

        # Smooth confidence to avoid UI jitter
        self._confidence_smooth = float(np.clip(
            0.7 * self._confidence_smooth + 0.3 * confidence,
            0.0,
            1.0,
        ))

        return {
            "timestamp": now,
            "mission_id": mission_state.get("mission_id"),
            "narrative_phase": director_state.get("narrative_phase"),
            "emotional_momentum": director_state.get(
                "emotional_momentum", 0.0
            ),
            "active_intent": director_state.get("active_intent"),
            "director_confidence": self._confidence_smooth,
            "authority_mode": mission_state.get("authority_mode"),
            "link_quality": link,
        }


    def reset(self) -> None:
        """
        Reset telemetry bridge state.
        """
        self._last_publish = 0.0
        self._confidence_smooth = 0.0


