from typing import Dict, Any, Optional
import time
import numpy as np


class VideoMetadataStreamingSpine:
    """
    Real-time video & metadata streaming spine.
    Couples encoded video frames with low-latency cinematic metadata
    packets, ensuring temporal alignment between what the user sees
    and what the Camera Director AI intended at that moment.
    """

    __slots__ = (
        "_last_frame_ts",
        "_metadata_rate_hz",
        "_sync_tolerance",
    )

    def __init__(
        self,
        metadata_rate_hz: float = 15.0,
        sync_tolerance: float = 0.050,
    ):
        self._metadata_rate_hz = float(np.clip(metadata_rate_hz, 5.0, 30.0))
        self._sync_tolerance = float(max(sync_tolerance, 0.01))
        self._last_frame_ts: float = 0.0


    # --------------------------------------------------------------------------
    # Streaming logic
    # --------------------------------------------------------------------------

    def attach_metadata(
        self,
        frame_timestamp: float,
        director_state: Dict[str, Any],
        mission_state: Dict[str, Any],
    ) -> Optional[Dict[str, Any]]:
        """
        Attach cinematic metadata to a video frame timestamp.
        """
        now = time.time()

        # Rate-limit metadata emission
        if (now - self._last_frame_ts) < (1.0 / self._metadata_rate_hz):
            return None

        # Ensure temporal coherence
        if abs(frame_timestamp - now) > self._sync_tolerance:
            return None

        self._last_frame_ts = now

        return {
            "ts": frame_timestamp,
            "narrative_phase": director_state.get("narrative_phase"),
            "emotional_momentum": director_state.get(
                "emotional_momentum", 0.0
            ),
            "active_intent": director_state.get("active_intent"),
            "shot_type": director_state.get("shot_type"),
            "director_confidence": director_state.get("confidence", 0.0),
            "authority_mode": mission_state.get("authority_mode"),
        }


    def reset(self) -> None:
        """
        Reset streaming spine state.
        """
        self._last_frame_ts = 0.0


