from typing import Dict, Any, Optional
import time
import numpy as np


class AppCloudAICommandChannel:
    """
    App ↔ Cloud AI command channel.
    Carries user-originated, high-level intent requests to cloud AI
    services and returns structured, confidence-scored intent frames
    suitable for downstream mission-safe interpretation.
    """

    __slots__ = (
        "_last_send",
        "_last_receive",
        "_round_trip_latency",
        "_link_health",
    )

    def __init__(self):
        self._last_send: float = 0.0
        self._last_receive: float = 0.0
        self._round_trip_latency: float = 0.0
        self._link_health: float = 1.0


    # --------------------------------------------------------------------------
    # Channel logic
    # --------------------------------------------------------------------------

    def send_intent(
        self,
        intent_text: str,
        session_id: str,
    ) -> Dict[str, Any]:
        """
        Package app-originated intent for cloud AI.
        """
        now = time.time()
        self._last_send = now

        return {
            "session_id": session_id,
            "intent_text": intent_text,
            "timestamp": now,
        }


    def receive_intent(
        self,
        cloud_response: Dict[str, Any],
    ) -> Optional[Dict[str, Any]]:
        """
        Receive and validate cloud AI intent response.
        """
        now = time.time()
        self._last_receive = now

        sent_ts = float(cloud_response.get("request_ts", now))
        self._round_trip_latency = max(now - sent_ts, 0.0)

        # Degrade link health under latency or malformed payloads
        latency_penalty = float(np.clip(
            self._round_trip_latency / 2.0, 0.0, 1.0
        ))

        confidence = float(np.clip(
            cloud_response.get("confidence", 0.0), 0.0, 1.0
        ))

        self._link_health = float(np.clip(
            0.7 * self._link_health
            + 0.2 * (1.0 - latency_penalty)
            + 0.1 * confidence,
            0.0,
            1.0,
        ))

        if "intent_frame" not in cloud_response:
            return None

        return {
            "intent_frame": cloud_response.get("intent_frame"),
            "confidence": confidence,
            "latency": self._round_trip_latency,
            "link_health": self._link_health,
            "timestamp": now,
        }


    def status(self) -> Dict[str, Any]:
        """
        Channel health status.
        """
        return {
            "link_health": self._link_health,
            "round_trip_latency": self._round_trip_latency,
            "last_send": self._last_send,
            "last_receive": self._last_receive,
        }


    def reset(self) -> None:
        """
        Reset channel state.
        """
        self._last_send = 0.0
        self._last_receive = 0.0
        self._round_trip_latency = 0.0
        self._link_health = 1.0


