# CHUNK 87 D 01 — MOBILE AI CHAT → DIRECTOR INTENT PARSER
# ==============================================================================
#
# Purpose:
#   Convert free-form human language from the mobile AI chat interface
#   into a structured, cinematic-director-level intent representation.
#
# Core principle:
#   Humans speak in feelings, outcomes, and metaphors —
#   directors think in intent, constraints, and emotional vectors.
#
# This layer performs:
#   • Semantic intent extraction
#   • Emotional vector inference (multi-axis, not scalar)
#   • Shot-language hints (not commands)
#   • Confidence & ambiguity estimation
#
# ==============================================================================

from typing import Dict, Any
import numpy as np


class DirectorIntentParser:
    """
    Translates conversational AI input into director-grade intent frames.
    Output is explicitly NON-ACTIONABLE.
    It describes *what is desired*, never *how to fly*.
    """

    __slots__ = (
        "_last_intent_confidence",
    )

    def __init__(self):
        self._last_intent_confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Core parsing
    # --------------------------------------------------------------------------

    def parse(
        self,
        text: str,
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Parse human language into a director intent frame.
        """

        text_l = text.lower().strip()

        # --- Emotional vector inference (heuristic baseline) ---
        emotional_vector = {
            "tension": self._score_keywords(
                text_l, ["chase", "fast", "danger", "close", "intense"]
            ),
            "awe": self._score_keywords(
                text_l, ["vast", "wide", "sunset", "cinematic", "epic"]
            ),
            "grief": self._score_keywords(
                text_l, ["alone", "loss", "slow", "empty", "quiet"]
            ),
            "triumph": self._score_keywords(
                text_l, ["victory", "win", "rise", "power", "hero"]
            ),
            "relief": self._score_keywords(
                text_l, ["calm", "safe", "rest", "soft", "breathe"]
            ),
        }

        # Normalize emotional vector
        total = sum(emotional_vector.values()) + 1e-6
        for k in emotional_vector:
            emotional_vector[k] = float(
                np.clip(emotional_vector[k] / total, 0.0, 1.0)
            )

        # --- Shot language hints ---
        shot_language = {
            "desired_scale": self._infer_scale(text_l),
            "motion_bias": self._infer_motion_bias(text_l),
            "framing_bias": self._infer_framing_bias(text_l),
        }

        # --- Confidence estimation ---
        clarity = min(len(text_l.split()) / 12.0, 1.0)
        emotion_strength = max(emotional_vector.values())
        confidence = float(
            np.clip(0.6 * clarity + 0.4 * emotion_strength, 0.0, 1.0)
        )

        self._last_intent_confidence = confidence

        return {
            "intent_type": "cinematic_direction",
            "raw_text": text,
            "emotional_vector": emotional_vector,
            "shot_language": shot_language,
            "confidence": confidence,
            "context_hint": context.get("mode", "unknown"),
        }


    # --------------------------------------------------------------------------
    # Helpers
    # --------------------------------------------------------------------------

    def _score_keywords(self, text: str, keywords) -> float:
        return float(sum(1.0 for k in keywords if k in text))

    def _infer_scale(self, text: str) -> str:
        if any(k in text for k in ["close", "face", "detail"]):
            return "close"
        if any(k in text for k in ["wide", "vast", "landscape"]):
            return "wide"
        return "medium"

    def _infer_motion_bias(self, text: str) -> float:
        if any(k in text for k in ["fast", "chase", "follow"]):
            return 0.8
        if any(k in text for k in ["slow", "float", "drift"]):
            return 0.2
        return 0.5

    def _infer_framing_bias(self, text: str) -> float:
        if any(k in text for k in ["center", "lock", "focus"]):
            return 0.7
        if any(k in text for k in ["off", "edge", "background"]):
            return 0.3
        return 0.5


