# ==============================================================================
# CHUNK 87 E 01 — CLOUD LLM → MISSION-SAFE INTENT TRANSLATOR
# ==============================================================================
#
# Purpose:
#   Translate cloud LLM outputs into a mission-safe, bounded intent
#   representation that can be consumed by the Camera Director AI
#   without exposing flight control, unsafe abstractions, or ambiguity.
#
# Core principle:
#   LLMs describe meaning; this layer enforces physics, mission context,
#   and safety envelopes before intent is allowed downstream.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class MissionSafeIntentTranslator:
    """
    Cloud LLM → mission-safe intent translator.
    Converts high-level semantic intent frames produced by cloud AI
    into bounded, typed, confidence-scored intent objects suitable
    for cinematic reasoning — never direct execution.
    """

    __slots__ = (
        "_last_translation_confidence",
        "_ambiguity_score",
    )

    def __init__(self):
        self._last_translation_confidence: float = 0.0
        self._ambiguity_score: float = 0.0


    # --------------------------------------------------------------------------
    # Translation logic
    # --------------------------------------------------------------------------

    def translate(
        self,
        llm_intent_frame: Dict[str, Any],
        mission_context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Translate LLM intent into mission-safe director intent.
        """
        now = time.time()

        raw_emotion = llm_intent_frame.get("emotional_vector", {})
        raw_shot = llm_intent_frame.get("shot_language", {})
        raw_conf = float(llm_intent_frame.get("confidence", 0.0))

        # Bound emotional vector
        emotional_vector = {
            k: float(np.clip(v, 0.0, 1.0))
            for k, v in raw_emotion.items()
        }

        # Normalize again defensively
        s = sum(emotional_vector.values()) + 1e-6
        for k in emotional_vector:
            emotional_vector[k] /= s

        # Enforce mission context constraints
        if mission_context.get("authority_mode") != "autonomous":
            # Reduce aggressive emotions when not autonomous
            for k in ("tension", "triumph"):
                if k in emotional_vector:
                    emotional_vector[k] *= 0.5

        # Ambiguity estimation
        entropy = -sum(
            v * np.log(v + 1e-6) for v in emotional_vector.values()
        )
        self._ambiguity_score = float(np.clip(entropy / 1.5, 0.0, 1.0))

        # Translation confidence penalized by ambiguity
        translation_confidence = float(np.clip(
            0.7 * raw_conf + 0.3 * (1.0 - self._ambiguity_score),
            0.0,
            1.0,
        ))

        self._last_translation_confidence = translation_confidence

        return {
            "intent_type": "mission_safe_cinematic_intent",
            "emotional_vector": emotional_vector,
            "shot_language": {
                "scale": raw_shot.get("desired_scale", "medium"),
                "motion_bias": float(np.clip(
                    raw_shot.get("motion_bias", 0.5), 0.0, 1.0
                )),
                "framing_bias": float(np.clip(
                    raw_shot.get("framing_bias", 0.5), 0.0, 1.0
                )),
            },
            "ambiguity": self._ambiguity_score,
            "confidence": translation_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset translation state.
        """
        self._last_translation_confidence = 0.0
        self._ambiguity_score = 0.0


