# ==============================================================================
# CHUNK 87 F 01 — INTENT CONFIDENCE & RISK ENVELOPE BUILDER
# ==============================================================================
#
# Purpose:
#   Wrap translated cinematic intent inside a dynamic, multi-axis
#   risk envelope that accounts for confidence, ambiguity, mission
#   phase, vehicle state, and operator presence.
#
# Core principle:
#   Intent is allowed only to the extent that risk is understood.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class IntentRiskEnvelopeBuilder:
    """
    Intent confidence & risk envelope builder.
    Produces a bounded intent envelope that downstream director logic
    can safely reason about without ever exceeding physical, safety,
    or narrative limits.
    """

    __slots__ = (
        "_smoothed_confidence",
        "_risk_pressure",
        "_last_update",
    )

    def __init__(self):
        self._smoothed_confidence: float = 0.0
        self._risk_pressure: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Envelope construction
    # --------------------------------------------------------------------------

    def build(
        self,
        mission_safe_intent: Dict[str, Any],
        vehicle_state: Dict[str, Any],
        mission_state: Dict[str, Any],
        operator_presence: float,
    ) -> Dict[str, Any]:
        """
        Build a dynamic risk envelope around intent.
        """
        now = time.time()

        conf = float(np.clip(
            mission_safe_intent.get("confidence", 0.0), 0.0, 1.0
        ))
        ambiguity = float(np.clip(
            mission_safe_intent.get("ambiguity", 0.0), 0.0, 1.0
        ))

        # Smooth confidence temporally
        self._smoothed_confidence = float(np.clip(
            0.8 * self._smoothed_confidence + 0.2 * conf,
            0.0,
            1.0,
        ))

        # Base risk from ambiguity and vehicle dynamics
        speed = float(vehicle_state.get("speed", 0.0))
        altitude = float(vehicle_state.get("altitude", 0.0))
        dynamic_risk = np.tanh(0.02 * speed + 0.01 * altitude)

        # Operator presence reduces acceptable risk
        operator_factor = float(np.clip(1.0 - operator_presence, 0.2, 1.0))

        # Mission authority scaling
        authority = mission_state.get("authority_mode", "manual")
        authority_factor = 1.0 if authority == "autonomous" else 0.6

        self._risk_pressure = float(np.clip(
            0.5 * ambiguity
            + 0.3 * dynamic_risk
            + 0.2 * (1.0 - self._smoothed_confidence),
            0.0,
            1.0,
        ))

        # Final allowable intent strength
        allowable_strength = float(np.clip(
            (1.0 - self._risk_pressure)
            * operator_factor
            * authority_factor,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "intent": mission_safe_intent,
            "allowable_strength": allowable_strength,
            "risk_pressure": self._risk_pressure,
            "smoothed_confidence": self._smoothed_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset envelope builder state.
        """
        self._smoothed_confidence = 0.0
        self._risk_pressure = 0.0
        self._last_update = time.time()


