# CHUNK 87 G 01 — DIRECTOR INTENT → CAMERA DIRECTOR AI BRIDGE
# ==============================================================================
#
# Purpose:
#   Inject mission-safe, risk-bounded cinematic intent into the
#   Camera Director AI cognitive core in a temporally stable,
#   narrative-consistent manner.
#
# Core principle:
#   Intent influences direction gradually — never as a hard switch.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class DirectorIntentBridge:
    """
    Director intent → Camera Director AI bridge.
    Blends external cinematic intent into the internal director
    state while preserving emotional momentum, narrative phase,
    and system safety constraints.
    """

    __slots__ = (
        "_intent_blend",
        "_last_intent",
        "_last_update",
    )

    def __init__(self):
        self._intent_blend: float = 0.0
        self._last_intent: Dict[str, Any] = {}
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Intent injection
    # --------------------------------------------------------------------------

    def apply(
        self,
        director_state: Dict[str, Any],
        intent_envelope: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Blend intent into director cognitive state.
        """
        now = time.time()

        allowable = float(np.clip(
            intent_envelope.get("allowable_strength", 0.0), 0.0, 1.0
        ))
        intent = intent_envelope.get("intent", {})

        # Smooth blending to avoid narrative discontinuity
        self._intent_blend = float(np.clip(
            0.85 * self._intent_blend + 0.15 * allowable,
            0.0,
            1.0,
        ))

        blended_emotion = dict(director_state.get("emotional_vector", {}))
        for k, v in intent.get("emotional_vector", {}).items():
            base = blended_emotion.get(k, 0.0)
            blended_emotion[k] = float(
                (1.0 - self._intent_blend) * base
                + self._intent_blend * float(v)
            )

        # Shot language biasing (non-destructive)
        shot_lang = director_state.get("shot_language", {}).copy()
        intent_shot = intent.get("shot_language", {})

        for k in ("scale", "motion_bias", "framing_bias"):
            if k in intent_shot:
                shot_lang[k] = float(
                    0.7 * shot_lang.get(k, 0.5)
                    + 0.3 * float(intent_shot[k])
                )

        self._last_intent = intent
        self._last_update = now

        return {
            "emotional_vector": blended_emotion,
            "shot_language": shot_lang,
            "intent_blend": self._intent_blend,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset intent bridge state.
        """
        self._intent_blend = 0.0
        self._last_intent.clear()
        self._last_update = time.time()


