# ==============================================================================
# CHUNK 87 H 01 — INTENT DECAY & REINTERPRETATION ENGINE
# ==============================================================================
#
# Purpose:
#   Allow injected cinematic intent to naturally decay, soften,
#   or be reinterpreted over time based on narrative evolution,
#   environmental feedback, and mission dynamics.
#
# Core principle:
#   Intent is temporal — it should fade, bend, or transform,
#   never persist rigidly beyond its narrative usefulness.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class IntentDecayReinterpretationEngine:
    """
    Intent decay & reinterpretation engine.
    Manages the temporal lifecycle of cinematic intent, preventing
    stale commands while preserving emotional continuity through
    gradual decay and context-aware reinterpretation.
    """

    __slots__ = (
        "_decay_state",
        "_reinterpret_pressure",
        "_last_update",
    )

    def __init__(self):
        self._decay_state: float = 1.0
        self._reinterpret_pressure: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Decay & reinterpretation
    # --------------------------------------------------------------------------

    def apply(
        self,
        intent_state: Dict[str, Any],
        director_state: Dict[str, Any],
        environment_feedback: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Apply decay and potential reinterpretation to intent.
        """
        now = time.time()

        # Temporal decay based on narrative phase progression
        phase = director_state.get("narrative_phase", "development")
        phase_decay = {
            "setup": 0.995,
            "development": 0.990,
            "climax": 0.985,
            "resolution": 0.980,
        }.get(phase, 0.990)

        self._decay_state *= phase_decay

        # Environmental mismatch increases reinterpret pressure
        motion_mismatch = abs(
            director_state.get("motion_energy", 0.0)
            - environment_feedback.get("observed_motion", 0.0)
        )

        lighting_mismatch = abs(
            director_state.get("avg_luma", 0.5)
            - environment_feedback.get("observed_luma", 0.5)
        )

        self._reinterpret_pressure = float(np.clip(
            0.6 * motion_mismatch + 0.4 * lighting_mismatch,
            0.0,
            1.0,
        ))

        # Intent strength after decay
        effective_strength = float(np.clip(
            self._decay_state * (1.0 - 0.5 * self._reinterpret_pressure),
            0.0,
            1.0,
        ))

        # Soft reinterpretation: dampen dominant emotions under pressure
        emotional_vector = dict(intent_state.get("emotional_vector", {}))
        if self._reinterpret_pressure > 0.4:
            for k in emotional_vector:
                emotional_vector[k] *= (1.0 - 0.3 * self._reinterpret_pressure)

        self._last_update = now

        return {
            "emotional_vector": emotional_vector,
            "effective_strength": effective_strength,
            "decay_state": self._decay_state,
            "reinterpret_pressure": self._reinterpret_pressure,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset decay and reinterpretation state.
        """
        self._decay_state = 1.0
        self._reinterpret_pressure = 0.0
        self._last_update = time.time()


