# ==============================================================================
# CHUNK 87 I 01 — MULTI-TURN CONVERSATIONAL INTENT MEMORY
# ==============================================================================
#
# Purpose:
#   Maintain a bounded, emotionally-aware conversational memory
#   across multiple user interactions so cinematic intent evolves
#   coherently over dialogue rather than resetting per message.
#
# Core principle:
#   Directors remember what was *meant*, not just what was said.
#
# ==============================================================================

from typing import Dict, Any, List
import numpy as np
import time


class ConversationalIntentMemory:
    """
    Multi-turn conversational intent memory.
    Stores recent intent frames with emotional and narrative context,
    enabling continuity, refinement, and escalation across dialogue.
    """

    __slots__ = (
        "_memory",
        "_max_turns",
        "_decay_rate",
        "_last_update",
    )

    def __init__(
        self,
        max_turns: int = 5,
        decay_rate: float = 0.85,
    ):
        self._memory: List[Dict[str, Any]] = []
        self._max_turns = int(np.clip(max_turns, 3, 10))
        self._decay_rate = float(np.clip(decay_rate, 0.7, 0.95))
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Memory management
    # --------------------------------------------------------------------------

    def push(
        self,
        intent_frame: Dict[str, Any],
    ) -> None:
        """
        Add a new conversational intent frame to memory.
        """
        now = time.time()

        # Apply decay to existing memory
        for m in self._memory:
            m["weight"] *= self._decay_rate

        # Insert new frame with full weight
        frame = dict(intent_frame)
        frame["weight"] = 1.0
        frame["timestamp"] = now

        self._memory.append(frame)

        # Enforce bounded memory
        if len(self._memory) > self._max_turns:
            self._memory = self._memory[-self._max_turns :]

        self._last_update = now


    def aggregate(self) -> Dict[str, Any]:
        """
        Aggregate conversational memory into a unified intent bias.
        """
        if not self._memory:
            return {}

        agg_emotion: Dict[str, float] = {}
        agg_weight = 0.0

        for frame in self._memory:
            w = frame.get("weight", 0.0)
            agg_weight += w

            for k, v in frame.get("emotional_vector", {}).items():
                agg_emotion[k] = agg_emotion.get(k, 0.0) + w * float(v)

        if agg_weight > 0.0:
            for k in agg_emotion:
                agg_emotion[k] /= agg_weight

        # Aggregate shot language with bias toward recent frames
        last = self._memory[-1]
        shot_language = last.get("shot_language", {}).copy()

        return {
            "emotional_vector": agg_emotion,
            "shot_language": shot_language,
            "turns": len(self._memory),
            "timestamp": time.time(),
        }


    def reset(self) -> None:
        """
        Clear conversational intent memory.
        """
        self._memory.clear()
        self._last_update = time.time()


