# ==============================================================================
# CHUNK 87 J 01 — INTENT → NARRATIVE PHASE BIASING
# ==============================================================================
#
# Purpose:
#   Subtly bias the Camera Director AI’s internal narrative phase
#   progression based on accumulated cinematic intent, without
#   forcing hard transitions or breaking emotional continuity.
#
# Core principle:
#   Intent nudges the story forward — it never teleports it.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class IntentNarrativePhaseBias:
    """
    Intent → narrative phase biasing.
    Uses emotional composition and conversational momentum to
    gently influence narrative phase velocity and dwell time,
    preserving cinematic pacing and act structure.
    """

    __slots__ = (
        "_phase_bias",
        "_phase_velocity",
        "_last_update",
    )

    def __init__(self):
        self._phase_bias: float = 0.0
        self._phase_velocity: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Phase bias logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        narrative_phase: str,
        emotional_vector: Dict[str, float],
        conversational_turns: int,
    ) -> Dict[str, Any]:
        """
        Compute narrative phase bias from intent.
        """
        now = time.time()

        # Emotional drivers for phase movement
        tension = emotional_vector.get("tension", 0.0)
        triumph = emotional_vector.get("triumph", 0.0)
        grief = emotional_vector.get("grief", 0.0)
        awe = emotional_vector.get("awe", 0.0)

        # Phase bias accumulation
        drive_forward = 0.6 * tension + 0.4 * triumph
        hold_back = 0.7 * grief + 0.3 * awe

        conversational_factor = float(
            np.clip(conversational_turns / 5.0, 0.0, 1.0)
        )

        raw_bias = drive_forward - hold_back
        self._phase_bias = float(np.clip(
            0.8 * self._phase_bias
            + 0.2 * raw_bias * conversational_factor,
            -1.0,
            1.0,
        ))

        # Phase velocity scaling (never negative)
        self._phase_velocity = float(np.clip(
            0.5 + 0.5 * self._phase_bias,
            0.2,
            1.0,
        ))

        self._last_update = now

        return {
            "narrative_phase": narrative_phase,
            "phase_bias": self._phase_bias,
            "phase_velocity": self._phase_velocity,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset narrative phase bias state.
        """
        self._phase_bias = 0.0
        self._phase_velocity = 0.5
        self._last_update = time.time()


