# ==============================================================================
# CHUNK 87 K 01 — INTENT SATISFACTION & CLOSURE DETECTION
# ==============================================================================
#
# Purpose:
#   Detect when a cinematic intent has been sufficiently fulfilled
#   so the Camera Director AI can transition toward release,
#   resolution, or request further direction instead of endlessly
#   escalating or looping the same behavior.
#
# Core principle:
#   Cinema ends emotionally, not numerically.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class IntentSatisfactionDetector:
    """
    Intent satisfaction & closure detector.
    Evaluates emotional convergence, narrative phase alignment,
    and diminishing returns to determine when intent has reached
    a natural point of closure.
    """

    __slots__ = (
        "_satisfaction_level",
        "_closure_confidence",
        "_last_update",
    )

    def __init__(self):
        self._satisfaction_level: float = 0.0
        self._closure_confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Satisfaction detection
    # --------------------------------------------------------------------------

    def evaluate(
        self,
        intent_state: Dict[str, Any],
        director_state: Dict[str, Any],
        narrative_phase: str,
    ) -> Dict[str, Any]:
        """
        Evaluate intent satisfaction and closure readiness.
        """
        now = time.time()

        emotional_vector = intent_state.get("emotional_vector", {})
        strength = float(np.clip(
            intent_state.get("effective_strength", 0.0), 0.0, 1.0
        ))

        # Emotional convergence: dominance without escalation
        dominant = max(emotional_vector.values(), default=0.0)
        dispersion = np.std(list(emotional_vector.values())) if emotional_vector else 0.0

        convergence = float(np.clip(
            dominant * (1.0 - dispersion),
            0.0,
            1.0,
        ))

        # Narrative alignment boosts closure likelihood
        phase_alignment = {
            "setup": 0.2,
            "development": 0.4,
            "climax": 0.9,
            "resolution": 1.0,
        }.get(narrative_phase, 0.5)

        # Satisfaction accumulation (slow, irreversible)
        self._satisfaction_level = float(np.clip(
            0.85 * self._satisfaction_level
            + 0.15 * convergence * phase_alignment,
            0.0,
            1.0,
        ))

        # Closure confidence penalized by lingering strength
        self._closure_confidence = float(np.clip(
            self._satisfaction_level * (1.0 - 0.6 * strength),
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "satisfaction_level": self._satisfaction_level,
            "closure_confidence": self._closure_confidence,
            "ready_for_release": self._closure_confidence > 0.7,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset satisfaction detector.
        """
        self._satisfaction_level = 0.0
        self._closure_confidence = 0.0
        self._last_update = time.time()


