# ==============================================================================
# ==============================================================================
# CHUNK 88 A 01 — DIRECTOR AI → CAMERA CONTROL ABSTRACTION LAYER
# ==============================================================================
#
# Purpose:
#   Translate high-level cinematic decisions made by the Camera
#   Director AI into a hardware-agnostic camera control abstraction.
#
# This layer does NOT:
#   • Talk to motors
#   • Talk to servos
#   • Know about PWM, I2C, or UART
#
# It ONLY:
#   • Express camera intent in cinematic terms
#   • Remain physically plausible
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CameraControlAbstraction:
    """
    Director AI → Camera control abstraction layer.
    Converts narrative, emotional, and shot-level decisions into
    camera-safe intent primitives such as framing pressure,
    motion smoothness, zoom bias, and stabilization demand.
    """

    __slots__ = (
        "_last_output",
        "_temporal_smooth",
        "_last_update",
    )

    def __init__(self, temporal_smooth: float = 0.85):
        self._temporal_smooth = float(np.clip(temporal_smooth, 0.7, 0.95))
        self._last_output: Dict[str, float] = {}
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Core abstraction
    # --------------------------------------------------------------------------

    def build(
        self,
        director_state: Dict[str, Any],
        intent_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Build camera control abstraction from director cognition.
        """
        now = time.time()

        emotional = director_state.get("emotional_vector", {})
        shot = director_state.get("shot_language", {})

        # Core camera primitives (0–1 normalized)
        framing_pressure = float(np.clip(
            0.5
            + 0.3 * emotional.get("tension", 0.0)
            - 0.2 * emotional.get("awe", 0.0),
            0.0,
            1.0,
        ))

        motion_smoothness = float(np.clip(
            1.0
            - 0.6 * emotional.get("tension", 0.0)
            - 0.3 * emotional.get("triumph", 0.0),
            0.0,
            1.0,
        ))

        zoom_bias = float(np.clip(
            shot.get("motion_bias", 0.5)
            * (1.0 + 0.4 * emotional.get("triumph", 0.0)),
            0.0,
            1.0,
        ))

        stabilization_demand = float(np.clip(
            0.4
            + 0.4 * emotional.get("grief", 0.0)
            + 0.3 * emotional.get("awe", 0.0),
            0.0,
            1.0,
        ))

        raw_output = {
            "framing_pressure": framing_pressure,
            "motion_smoothness": motion_smoothness,
            "zoom_bias": zoom_bias,
            "stabilization_demand": stabilization_demand,
        }

        # Temporal smoothing (camera comfort)
        output: Dict[str, float] = {}
        for k, v in raw_output.items():
            prev = self._last_output.get(k, v)
            output[k] = float(
                self._temporal_smooth * prev
                + (1.0 - self._temporal_smooth) * v
            )

        self._last_output = output
        self._last_update = now

        return {
            "camera_primitives": output,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset camera abstraction state.
        """
        self._last_output.clear()
        self._last_update = time.time()


