# ==============================================================================
# CHUNK 88 B 01 — SHOT-SCALE → GIMBAL & LENS MAPPING
# ==============================================================================
#
# Purpose:
#   Map abstract cinematic shot scale (wide / medium / close)
#   into continuous gimbal intent and lens-domain behavior while
#   preserving smoothness, depth perception, and cinematic comfort.
#
# Core principle:
#   Shot scale is spatial storytelling, not a zoom switch.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class ShotScaleGimbalLensMapper:
    """
    Shot-scale → gimbal & lens mapping.
    Converts shot scale and framing pressure into continuous,
    hardware-agnostic intents for gimbal orientation, zoom domain,
    and parallax sensitivity.
    """

    __slots__ = (
        "_scale_continuum",
        "_last_output",
        "_temporal_smooth",
        "_last_update",
    )

    def __init__(self, temporal_smooth: float = 0.88):
        self._temporal_smooth = float(np.clip(temporal_smooth, 0.75, 0.95))
        self._scale_continuum: float = 0.5
        self._last_output: Dict[str, float] = {}
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Mapping logic
    # --------------------------------------------------------------------------

    def map(
        self,
        shot_language: Dict[str, Any],
        camera_primitives: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Map shot-scale intent to gimbal & lens abstraction.
        """
        now = time.time()

        scale = shot_language.get("scale", "medium")
        framing_pressure = float(camera_primitives.get("framing_pressure", 0.5))

        # Convert discrete scale to continuum target
        scale_target = {
            "wide": 0.2,
            "medium": 0.5,
            "close": 0.8,
        }.get(scale, 0.5)

        # Blend scale with framing pressure
        scale_target = float(np.clip(
            0.7 * scale_target + 0.3 * framing_pressure,
            0.0,
            1.0,
        ))

        # Temporal smoothing
        self._scale_continuum = float(
            self._temporal_smooth * self._scale_continuum
            + (1.0 - self._temporal_smooth) * scale_target
        )

        # Gimbal intent (normalized, non-hardware)
        gimbal_pitch_bias = float(np.clip(
            0.5 + 0.3 * (self._scale_continuum - 0.5),
            0.0,
            1.0,
        ))

        gimbal_yaw_stability = float(np.clip(
            1.0 - 0.6 * abs(self._scale_continuum - 0.5),
            0.2,
            1.0,
        ))

        # Lens-domain intent
        zoom_domain = float(np.clip(
            self._scale_continuum,
            0.0,
            1.0,
        ))

        parallax_sensitivity = float(np.clip(
            0.2 + 0.6 * self._scale_continuum,
            0.0,
            1.0,
        ))

        raw_output = {
            "scale_continuum": self._scale_continuum,
            "gimbal_pitch_bias": gimbal_pitch_bias,
            "gimbal_yaw_stability": gimbal_yaw_stability,
            "zoom_domain": zoom_domain,
            "parallax_sensitivity": parallax_sensitivity,
        }

        # Final smoothing
        output: Dict[str, float] = {}
        for k, v in raw_output.items():
            prev = self._last_output.get(k, v)
            output[k] = float(
                self._temporal_smooth * prev
                + (1.0 - self._temporal_smooth) * v
            )

        self._last_output = output
        self._last_update = now

        return {
            "shot_mapping": output,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset shot-scale mapping state.
        """
        self._scale_continuum = 0.5
        self._last_output.clear()
        self._last_update = time.time()


