# CHUNK 88 C 01 — EMOTIONAL VECTOR → CAMERA MOTION DYNAMICS
# ==============================================================================
#
# Purpose:
#   Translate emotional vectors into physically plausible camera
#   motion dynamics — acceleration, damping, inertia, and trajectory
#   feel — without binding to any specific hardware or motor logic.
#
# Core principle:
#   Emotion is expressed through motion *character*, not speed alone.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class EmotionalCameraMotionDynamics:
    """
    Emotional vector → camera motion dynamics.
    Converts emotional intent into motion physics parameters
    that define how the camera starts, moves, and settles.
    """

    __slots__ = (
        "_velocity_bias",
        "_accel_bias",
        "_damping",
        "_inertia",
        "_last_update",
    )

    def __init__(self):
        self._velocity_bias: float = 0.5
        self._accel_bias: float = 0.5
        self._damping: float = 0.5
        self._inertia: float = 0.5
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Dynamics mapping
    # --------------------------------------------------------------------------

    def map(
        self,
        emotional_vector: Dict[str, float],
        camera_primitives: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Map emotional vector to camera motion dynamics.
        """
        now = time.time()

        tension = emotional_vector.get("tension", 0.0)
        awe = emotional_vector.get("awe", 0.0)
        grief = emotional_vector.get("grief", 0.0)
        triumph = emotional_vector.get("triumph", 0.0)
        relief = emotional_vector.get("relief", 0.0)

        # Velocity character
        vel_target = float(np.clip(
            0.4
            + 0.4 * tension
            + 0.3 * triumph
            - 0.3 * grief,
            0.0,
            1.0,
        ))

        # Acceleration sharpness
        accel_target = float(np.clip(
            0.3
            + 0.5 * tension
            + 0.2 * triumph
            - 0.4 * awe,
            0.0,
            1.0,
        ))

        # Damping (settle smoothness)
        damping_target = float(np.clip(
            0.4
            + 0.5 * awe
            + 0.4 * grief
            - 0.3 * tension,
            0.0,
            1.0,
        ))

        # Inertia (resistance to change)
        inertia_target = float(np.clip(
            0.3
            + 0.5 * awe
            + 0.4 * relief
            - 0.3 * triumph,
            0.0,
            1.0,
        ))

        # Temporal smoothing for comfort
        smooth = 0.85

        self._velocity_bias = smooth * self._velocity_bias + (1.0 - smooth) * vel_target
        self._accel_bias = smooth * self._accel_bias + (1.0 - smooth) * accel_target
        self._damping = smooth * self._damping + (1.0 - smooth) * damping_target
        self._inertia = smooth * self._inertia + (1.0 - smooth) * inertia_target

        self._last_update = now

        return {
            "motion_dynamics": {
                "velocity_bias": self._velocity_bias,
                "acceleration_bias": self._accel_bias,
                "damping": self._damping,
                "inertia": self._inertia,
            },
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset motion dynamics state.
        """
        self._velocity_bias = 0.5
        self._accel_bias = 0.5
        self._damping = 0.5
        self._inertia = 0.5
        self._last_update = time.time()


