# ==============================================================================
# CHUNK 88 D 01 — CAMERA CONTROL → HARDWARE ADAPTER INTERFACE
# ==============================================================================
#
# Purpose:
#   Terminate camera-control abstraction into a strict, pluggable
#   hardware-adapter interface that can target multiple camera
#   stacks (internal CSI, USB, action cam) without leaking hardware
#   details upward or safety concerns downward.
#
# Core principle:
#   Adapters translate intent — never invent it.
#
# ==============================================================================

from typing import Dict, Any, Protocol, runtime_checkable
import time


@runtime_checkable
class CameraHardwareAdapter(Protocol):
    """
    Camera hardware adapter protocol.
    Implementations MUST be:
    - Non-blocking
    - Idempotent per tick
    - Bounded in output
    """
    def apply(self, camera_intent: Dict[str, Any]) -> Dict[str, Any]:
        ...


class CameraHardwareAdapterInterface:
    """
    Camera control → hardware adapter interface.
    Dispatches camera intent primitives to the active hardware adapter
    while enforcing rate limits, bounds, and observability.
    """

    __slots__ = (
        "_adapter",
        "_rate_limit_hz",
        "_last_dispatch",
    )

    def __init__(
        self,
        adapter: CameraHardwareAdapter,
        rate_limit_hz: float = 30.0,
    ):
        self._adapter = adapter
        self._rate_limit_hz = max(5.0, min(rate_limit_hz, 60.0))
        self._last_dispatch: float = 0.0


    # --------------------------------------------------------------------------
    # Dispatch logic
    # --------------------------------------------------------------------------

    def dispatch(
        self,
        camera_primitives: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Dispatch camera primitives to hardware adapter.
        """
        now = time.time()

        if (now - self._last_dispatch) < (1.0 / self._rate_limit_hz):
            return {
                "dispatched": False,
                "reason": "rate_limited",
                "timestamp": now,
            }

        self._last_dispatch = now

        # Defensive copy + bounds check (0–1 normalized)
        bounded_intent = {}
        for k, v in camera_primitives.items():
            try:
                bounded_intent[k] = float(min(max(v, 0.0), 1.0))
            except Exception:
                continue

        # Adapter application (must be non-blocking)
        result = self._adapter.apply(bounded_intent)

        return {
            "dispatched": True,
            "adapter": self._adapter.__class__.__name__,
            "result": result,
            "timestamp": now,
        }


    def swap_adapter(self, adapter: CameraHardwareAdapter) -> None:
        """
        Hot-swap camera hardware adapter.
        """
        self._adapter = adapter
        self._last_dispatch = 0.0


