# CHUNK 88 E 01 — MULTI-CAMERA ARBITRATION (INTERNAL vs EXTERNAL)
# ==============================================================================
#
# Purpose:
#   Decide which camera should lead, follow, or standby when multiple
#   cameras are available (internal CSI + external USB/action cam),
#   ensuring cinematic continuity, safety, and intent preservation.
#
# Core principle:
#   The best camera is the one that serves the moment — not the spec.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class MultiCameraArbitrator:
    """
    Multi-camera arbitration engine.
    Selects and blends camera roles based on intent strength,
    quality confidence, stabilization needs, and safety envelope.
    """

    __slots__ = (
        "_active_camera",
        "_confidence",
        "_last_switch",
    )

    def __init__(self):
        self._active_camera: str = "internal"
        self._confidence: float = 1.0
        self._last_switch: float = 0.0


    # --------------------------------------------------------------------------
    # Arbitration logic
    # --------------------------------------------------------------------------

    def arbitrate(
        self,
        intent_state: Dict[str, Any],
        camera_status: Dict[str, Dict[str, Any]],
    ) -> Dict[str, Any]:
        """
        Determine active camera and role assignment.
        """
        now = time.time()

        # Intent-driven priorities
        stabilization_need = intent_state.get("stabilization_demand", 0.5)
        strength = intent_state.get("effective_strength", 0.5)

        # Extract camera metrics
        internal = camera_status.get("internal", {})
        external = camera_status.get("external", {})

        internal_score = (
            0.5 * internal.get("stability", 0.5)
            + 0.3 * internal.get("latency", 0.5)
            + 0.2 * internal.get("availability", 0.5)
        )

        external_score = (
            0.6 * external.get("image_quality", 0.5)
            + 0.2 * external.get("stability", 0.5)
            + 0.2 * external.get("availability", 0.5)
        )

        # Bias selection
        bias = (
            stabilization_need * (internal_score - external_score)
            + strength * (external_score - internal_score)
        )

        target_camera = "internal" if bias >= 0 else "external"

        # Hysteresis to prevent oscillation
        if target_camera != self._active_camera:
            if (now - self._last_switch) > 2.0:
                self._active_camera = target_camera
                self._last_switch = now
                self._confidence = 0.8
        else:
            self._confidence = float(np.clip(self._confidence + 0.05, 0.0, 1.0))

        return {
            "active_camera": self._active_camera,
            "confidence": self._confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset arbitration state.
        """
        self._active_camera = "internal"
        self._confidence = 1.0
        self._last_switch = time.time()


