# ==============================================================================
# CHUNK 88 F 01 — CAMERA SAFETY ENVELOPE & MECHANICAL LIMITS
# ==============================================================================
#
# Purpose:
#   Enforce a dynamic safety envelope over all camera and gimbal
#   intents so that cinematic decisions remain mechanically safe,
#   fatigue-aware, and non-destructive across long flight sessions.
#
# Core principle:
#   Safety must feel invisible — never abrupt.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CameraSafetyEnvelope:
    """
    Camera safety envelope & mechanical limits.
    Applies soft constraints, fatigue modeling, and context-aware
    damping to camera and gimbal intent primitives.
    """

    __slots__ = (
        "_fatigue",
        "_thermal_load",
        "_last_update",
    )

    def __init__(self):
        self._fatigue: float = 0.0
        self._thermal_load: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Safety application
    # --------------------------------------------------------------------------

    def apply(
        self,
        camera_primitives: Dict[str, float],
        motion_dynamics: Dict[str, float],
        hardware_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Apply safety envelope to camera intent.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # Fatigue accumulation (slow, persistent)
        motion_load = (
            0.4 * motion_dynamics.get("velocity_bias", 0.5)
            + 0.3 * motion_dynamics.get("acceleration_bias", 0.5)
            + 0.3 * (1.0 - motion_dynamics.get("damping", 0.5))
        )

        self._fatigue = float(np.clip(
            self._fatigue + dt * 0.02 * motion_load,
            0.0,
            1.0,
        ))

        # Thermal load proxy
        self._thermal_load = float(np.clip(
            0.9 * self._thermal_load
            + 0.1 * hardware_state.get("temperature_norm", 0.5),
            0.0,
            1.0,
        ))

        # Safety attenuation factor
        safety_factor = float(np.clip(
            1.0
            - 0.4 * self._fatigue
            - 0.3 * self._thermal_load,
            0.4,
            1.0,
        ))

        safe_output: Dict[str, float] = {}

        for k, v in camera_primitives.items():
            try:
                safe_output[k] = float(np.clip(
                    v * safety_factor,
                    0.0,
                    1.0,
                ))
            except Exception:
                continue

        return {
            "camera_primitives_safe": safe_output,
            "safety_factor": safety_factor,
            "fatigue": self._fatigue,
            "thermal_load": self._thermal_load,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset safety envelope state.
        """
        self._fatigue = 0.0
        self._thermal_load = 0.0
        self._last_update = time.time()


