# END OF CHUNK 88 F 01
# ==============================================================================
# ==============================================================================
# CHUNK 88 G 01 — GIMBAL SERVO DYNAMICS ADAPTER
# ==============================================================================
#
# Purpose:
#   Convert safe, abstract camera intent into gimbal servo–ready
#   motion dynamics while preserving smoothness, rate limits,
#   and mechanical comfort — without emitting hardware signals.
#
# Core principle:
#   Servos express motion — they never decide it.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class GimbalServoDynamicsAdapter:
    """
    Gimbal servo dynamics adapter.
    Shapes camera intent into servo-domain dynamics such as
    angular velocity bias, acceleration softness, and settle rate.
    """

    __slots__ = (
        "_pitch_state",
        "_yaw_state",
        "_roll_state",
        "_last_update",
    )

    def __init__(self):
        self._pitch_state: float = 0.5
        self._yaw_state: float = 0.5
        self._roll_state: float = 0.5
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Servo dynamics shaping
    # --------------------------------------------------------------------------

    def adapt(
        self,
        camera_primitives_safe: Dict[str, float],
        motion_dynamics: Dict[str, float],
        shot_mapping: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Adapt camera intent into gimbal servo dynamics.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # Extract dynamics
        velocity = motion_dynamics.get("velocity_bias", 0.5)
        accel = motion_dynamics.get("acceleration_bias", 0.5)
        damping = motion_dynamics.get("damping", 0.5)
        inertia = motion_dynamics.get("inertia", 0.5)

        framing = camera_primitives_safe.get("framing_pressure", 0.5)
        pitch_bias = shot_mapping.get("gimbal_pitch_bias", 0.5)
        yaw_stability = shot_mapping.get("gimbal_yaw_stability", 0.5)

        # Target deltas (normalized, symmetric around 0.5)
        pitch_target = 0.5 + (pitch_bias - 0.5) * framing
        yaw_target = 0.5
        roll_target = 0.5

        # Dynamic rate limits
        rate = float(np.clip(
            0.5 * velocity * (1.0 - inertia),
            0.05,
            0.5,
        ))

        # State integration with damping
        def integrate(current, target):
            delta = np.clip(target - current, -rate * dt, rate * dt)
            return current + delta * (1.0 - damping)

        self._pitch_state = integrate(self._pitch_state, pitch_target)
        self._yaw_state = integrate(self._yaw_state, yaw_target)
        self._roll_state = integrate(self._roll_state, roll_target)

        return {
            "gimbal_dynamics": {
                "pitch": float(np.clip(self._pitch_state, 0.0, 1.0)),
                "yaw": float(np.clip(self._yaw_state, 0.0, 1.0)),
                "roll": float(np.clip(self._roll_state, 0.0, 1.0)),
                "rate": rate,
                "damping": damping,
            },
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset gimbal servo dynamics state.
        """
        self._pitch_state = 0.5
        self._yaw_state = 0.5
        self._roll_state = 0.5
        self._last_update = time.time()


