# ==============================================================================
# CHUNK 88 H 01 — CAMERA FAILURE DETECTION & FALLBACK
# ==============================================================================
#
# Purpose:
#   Detect partial or full camera failure early using perceptual,
#   temporal, and signal-consistency cues, then execute a graceful,
#   cinematic fallback without hard cuts or intent collapse.
#
# Core principle:
#   Failure should feel like intention — not interruption.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CameraFailureDetectionFallback:
    """
    Camera failure detection & fallback engine.
    Identifies degradation trends (latency, stability, signal loss)
    and orchestrates soft fallback across cameras or modes while
    preserving narrative and emotional continuity.
    """

    __slots__ = (
        "_health_score",
        "_degradation_trend",
        "_last_ok",
        "_last_update",
    )

    def __init__(self):
        self._health_score: float = 1.0
        self._degradation_trend: float = 0.0
        self._last_ok: float = time.time()
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Detection & fallback logic
    # --------------------------------------------------------------------------

    def evaluate(
        self,
        camera_metrics: Dict[str, Any],
        active_camera: str,
    ) -> Dict[str, Any]:
        """
        Evaluate camera health and determine fallback need.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # Extract perceptual metrics (normalized 0–1, higher is better)
        stability = camera_metrics.get("stability", 0.5)
        latency = camera_metrics.get("latency", 0.5)
        availability = camera_metrics.get("availability", 0.5)
        signal_quality = camera_metrics.get("signal_quality", 0.5)

        # Health composition
        health = float(np.clip(
            0.35 * stability
            + 0.25 * (1.0 - latency)
            + 0.20 * availability
            + 0.20 * signal_quality,
            0.0,
            1.0,
        ))

        # Degradation trend (slow memory)
        delta = health - self._health_score
        self._degradation_trend = float(np.clip(
            0.9 * self._degradation_trend + 0.1 * delta,
            -1.0,
            1.0,
        ))

        self._health_score = health

        # Update last OK timestamp
        if health > 0.6:
            self._last_ok = now

        # Failure likelihood (anticipatory, not binary)
        failure_likelihood = float(np.clip(
            0.6 * (1.0 - self._health_score)
            + 0.4 * max(-self._degradation_trend, 0.0),
            0.0,
            1.0,
        ))

        # Fallback recommendation
        recommend_fallback = (
            failure_likelihood > 0.7
            or (now - self._last_ok) > 1.5
        )

        return {
            "active_camera": active_camera,
            "health_score": self._health_score,
            "degradation_trend": self._degradation_trend,
            "failure_likelihood": failure_likelihood,
            "recommend_fallback": recommend_fallback,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset failure detection state.
        """
        self._health_score = 1.0
        self._degradation_trend = 0.0
        self._last_ok = time.time()
        self._last_update = time.time()


