# CHUNK 88 I 01 — CAMERA INTENT → TELEMETRY & LOGGING
# ==============================================================================
#
# Purpose:
#   Convert camera and director intent into structured telemetry
#   and logs that preserve causality — enabling cloud analysis,
#   flight replay, learning, and post-mission critique.
#
# Core principle:
#   Logs must explain *why*, not just *what*.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import uuid


class CameraIntentTelemetryLogger:
    """
    Camera intent → telemetry & logging.
    Emits structured, causality-preserving telemetry packets
    describing intent, abstraction, safety, and execution layers.
    """

    __slots__ = (
        "_session_id",
        "_sequence",
        "_buffer",
    )

    def __init__(self):
        self._session_id: str = str(uuid.uuid4())
        self._sequence: int = 0
        self._buffer: List[Dict[str, Any]] = []


    # --------------------------------------------------------------------------
    # Telemetry emission
    # --------------------------------------------------------------------------

    def emit(
        self,
        director_state: Dict[str, Any],
        intent_state: Dict[str, Any],
        camera_primitives: Dict[str, Any],
        safety_state: Dict[str, Any],
        execution_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Emit a structured telemetry frame.
        """
        now = time.time()
        self._sequence += 1

        frame = {
            "session_id": self._session_id,
            "seq": self._sequence,
            "timestamp": now,
            "director": {
                "narrative_phase": director_state.get("narrative_phase"),
                "emotional_vector": director_state.get("emotional_vector"),
                "shot_language": director_state.get("shot_language"),
            },
            "intent": {
                "effective_strength": intent_state.get("effective_strength"),
                "reinterpret_pressure": intent_state.get("reinterpret_pressure"),
                "satisfaction_level": intent_state.get("satisfaction_level"),
            },
            "camera": {
                "primitives": camera_primitives,
            },
            "safety": {
                "factor": safety_state.get("safety_factor"),
                "fatigue": safety_state.get("fatigue"),
                "thermal": safety_state.get("thermal_load"),
            },
            "execution": execution_state,
        }

        self._buffer.append(frame)

        return frame


    def flush(self) -> List[Dict[str, Any]]:
        """
        Flush buffered telemetry frames.
        """
        out = list(self._buffer)
        self._buffer.clear()
        return out


    def reset(self) -> None:
        """
        Reset telemetry session.
        """
        self._session_id = str(uuid.uuid4())
        self._sequence = 0
        self._buffer.clear()


