# ==============================================================================
# CHUNK 89 A 01 — DIRECTOR AI → FLIGHT INTENT INTERFACE (BRIDGE)
# ==============================================================================
#
# Purpose:
#   Bridge high-level cinematic intent into flight-level intent
#   suggestions that can bias, but never override, the flight
#   controller’s authority, autonomy, or safety logic.
#
# Core principle:
#   The director suggests — the pilot (autopilot) decides.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class DirectorFlightIntentBridge:
    """
    Director AI → flight intent interface.
    Translates cinematic priorities into soft flight biases
    such as path curvature preference, altitude comfort,
    and yaw continuity — without issuing control commands.
    """

    __slots__ = (
        "_path_bias",
        "_altitude_bias",
        "_yaw_bias",
        "_last_update",
    )

    def __init__(self):
        self._path_bias: float = 0.0
        self._altitude_bias: float = 0.0
        self._yaw_bias: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Flight intent biasing
    # --------------------------------------------------------------------------

    def compute(
        self,
        director_state: Dict[str, Any],
        camera_state: Dict[str, Any],
        safety_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Compute flight intent biases from director cognition.
        """
        now = time.time()

        emotional = director_state.get("emotional_vector", {})
        shot = director_state.get("shot_language", {})

        # Curvature preference (wide vs tight motion)
        self._path_bias = float(np.clip(
            0.4 * emotional.get("awe", 0.0)
            - 0.6 * emotional.get("tension", 0.0),
            -1.0,
            1.0,
        ))

        # Altitude comfort bias (never absolute)
        self._altitude_bias = float(np.clip(
            0.3 * shot.get("scale_bias", 0.0)
            - 0.4 * emotional.get("grief", 0.0),
            -1.0,
            1.0,
        ))

        # Yaw continuity bias (smooth pans vs aggressive turns)
        self._yaw_bias = float(np.clip(
            0.5 * emotional.get("awe", 0.0)
            + 0.3 * emotional.get("relief", 0.0)
            - 0.5 * emotional.get("tension", 0.0),
            -1.0,
            1.0,
        ))

        # Safety attenuation (flight always wins)
        safety_factor = safety_state.get("safety_factor", 1.0)
        self._path_bias *= safety_factor
        self._altitude_bias *= safety_factor
        self._yaw_bias *= safety_factor

        self._last_update = now

        return {
            "flight_intent_bias": {
                "path_curvature": self._path_bias,
                "altitude_preference": self._altitude_bias,
                "yaw_continuity": self._yaw_bias,
            },
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset flight intent bias state.
        """
        self._path_bias = 0.0
        self._altitude_bias = 0.0
        self._yaw_bias = 0.0
        self._last_update = time.time()


