# ==============================================================================
# CHUNK 89 B 01 — CINEMATIC INTENT → PATH BIASING
# ==============================================================================
#
# Purpose:
#   Translate cinematic intent into spatial path preferences
#   that bias how the drone moves through space — curvature,
#   arc length, lateral offset — without issuing control commands.
#
# Core principle:
#   The path tells the story before the camera does.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CinematicPathBiasing:
    """
    Cinematic intent → path biasing.
    Shapes preferred spatial trajectories based on emotion,
    shot language, and narrative phase, while remaining advisory
    to the flight controller.
    """

    __slots__ = (
        "_curvature_bias",
        "_lateral_offset_bias",
        "_vertical_arc_bias",
        "_temporal_coherence",
        "_last_update",
    )

    def __init__(self):
        self._curvature_bias: float = 0.0
        self._lateral_offset_bias: float = 0.0
        self._vertical_arc_bias: float = 0.0
        self._temporal_coherence: float = 0.5
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Path bias computation
    # --------------------------------------------------------------------------

    def compute(
        self,
        director_state: Dict[str, Any],
        flight_context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Compute cinematic path biases.
        """
        now = time.time()

        emotional = director_state.get("emotional_vector", {})
        shot = director_state.get("shot_language", {})
        phase = director_state.get("narrative_phase", "development")

        # Curvature bias: arcs vs direct lines
        curvature_target = float(np.clip(
            0.6 * emotional.get("awe", 0.0)
            + 0.4 * emotional.get("relief", 0.0)
            - 0.7 * emotional.get("tension", 0.0),
            -1.0,
            1.0,
        ))

        # Lateral offset bias (parallax storytelling)
        lateral_target = float(np.clip(
            0.5 * shot.get("parallax_preference", 0.0)
            + 0.3 * emotional.get("triumph", 0.0)
            - 0.4 * emotional.get("grief", 0.0),
            -1.0,
            1.0,
        ))

        # Vertical arc bias (rise / descend feeling)
        vertical_target = float(np.clip(
            0.5 * emotional.get("triumph", 0.0)
            - 0.5 * emotional.get("grief", 0.0)
            + (0.2 if phase == "climax" else 0.0),
            -1.0,
            1.0,
        ))

        # Temporal coherence (how stubborn the path preference is)
        coherence_target = float(np.clip(
            0.6
            + 0.3 * emotional.get("awe", 0.0)
            - 0.4 * emotional.get("tension", 0.0),
            0.2,
            0.9,
        ))

        # Smooth integration
        smooth = 0.85
        self._curvature_bias = smooth * self._curvature_bias + (1.0 - smooth) * curvature_target
        self._lateral_offset_bias = smooth * self._lateral_offset_bias + (1.0 - smooth) * lateral_target
        self._vertical_arc_bias = smooth * self._vertical_arc_bias + (1.0 - smooth) * vertical_target
        self._temporal_coherence = smooth * self._temporal_coherence + (1.0 - smooth) * coherence_target

        self._last_update = now

        return {
            "path_bias": {
                "curvature": self._curvature_bias,
                "lateral_offset": self._lateral_offset_bias,
                "vertical_arc": self._vertical_arc_bias,
                "coherence": self._temporal_coherence,
            },
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset path bias state.
        """
        self._curvature_bias = 0.0
        self._lateral_offset_bias = 0.0
        self._vertical_arc_bias = 0.0
        self._temporal_coherence = 0.5
        self._last_update = time.time()


