# ==============================================================================
# CHUNK 89 C 01 — OBSTACLE AWARENESS → SHOT PRESERVATION
# ==============================================================================
#
# Purpose:
#   Integrate obstacle awareness into cinematic decision-making
#   so avoidance maneuvers preserve shot intent, framing, and
#   emotional continuity instead of feeling evasive or panicked.
#
# Core principle:
#   Safety moves must still look like choices.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class ObstacleAwareShotPreservation:
    """
    Obstacle awareness → shot preservation.
    Modulates cinematic path and camera intent in response to
    obstacle proximity while maintaining narrative coherence.
    """

    __slots__ = (
        "_avoidance_bias",
        "_shot_integrity",
        "_last_update",
    )

    def __init__(self):
        self._avoidance_bias: float = 0.0
        self._shot_integrity: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Preservation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        obstacle_state: Dict[str, Any],
        path_bias: Dict[str, float],
        camera_primitives: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Apply obstacle-aware modulation to path & camera intent.
        """
        now = time.time()

        proximity = float(np.clip(
            obstacle_state.get("proximity_norm", 0.0),
            0.0,
            1.0,
        ))

        closing_rate = float(np.clip(
            obstacle_state.get("closing_rate_norm", 0.0),
            0.0,
            1.0,
        ))

        # Avoidance pressure (anticipatory)
        avoidance_target = float(np.clip(
            0.7 * proximity + 0.3 * closing_rate,
            0.0,
            1.0,
        ))

        # Smooth integration
        smooth = 0.9
        self._avoidance_bias = (
            smooth * self._avoidance_bias
            + (1.0 - smooth) * avoidance_target
        )

        # Shot integrity decays only under sustained pressure
        integrity_target = float(np.clip(
            1.0 - 0.6 * self._avoidance_bias,
            0.3,
            1.0,
        ))

        self._shot_integrity = (
            smooth * self._shot_integrity
            + (1.0 - smooth) * integrity_target
        )

        # Modulate path bias (soft, never flip sign abruptly)
        preserved_path = {
            "curvature": path_bias.get("curvature", 0.0)
            * (1.0 - 0.5 * self._avoidance_bias),
            "lateral_offset": path_bias.get("lateral_offset", 0.0)
            * (1.0 - 0.4 * self._avoidance_bias),
            "vertical_arc": path_bias.get("vertical_arc", 0.0)
            * (1.0 - 0.6 * self._avoidance_bias),
            "coherence": max(
                0.2,
                path_bias.get("coherence", 0.5)
                * self._shot_integrity,
            ),
        }

        # Modulate camera intent to hide avoidance
        preserved_camera = dict(camera_primitives)
        preserved_camera["motion_smoothness"] = float(np.clip(
            preserved_camera.get("motion_smoothness", 0.5)
            + 0.3 * self._avoidance_bias,
            0.0,
            1.0,
        ))

        self._last_update = now

        return {
            "path_bias_preserved": preserved_path,
            "camera_primitives_preserved": preserved_camera,
            "avoidance_bias": self._avoidance_bias,
            "shot_integrity": self._shot_integrity,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset obstacle preservation state.
        """
        self._avoidance_bias = 0.0
        self._shot_integrity = 1.0
        self._last_update = time.time()


