# ==============================================================================
# CHUNK 89 D 01 — SUBJECT TRACKING → FLIGHT FRAMING COUPLING
# ==============================================================================
#
# Purpose:
#   Couple subject tracking with flight motion and camera framing
#   so that the subject remains compositionally locked while the
#   drone moves — preserving cinematic intent under real dynamics.
#
# Core principle:
#   Subjects are framed by motion, not pixels.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class SubjectTrackingFlightFramingCoupler:
    """
    Subject tracking → flight framing coupling.
    Integrates subject position, camera framing intent, and
    flight bias so the drone moves to protect composition,
    not just chase a target.
    """

    __slots__ = (
        "_framing_error",
        "_tracking_confidence",
        "_last_update",
    )

    def __init__(self):
        self._framing_error: float = 0.0
        self._tracking_confidence: float = 1.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Coupling logic
    # --------------------------------------------------------------------------

    def couple(
        self,
        subject_state: Dict[str, Any],
        framing_intent: Dict[str, float],
        path_bias: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Couple subject tracking into flight framing bias.
        """
        now = time.time()

        # Subject metrics (normalized)
        offset_x = float(np.clip(
            subject_state.get("offset_x_norm", 0.0),
            -1.0,
            1.0,
        ))

        offset_y = float(np.clip(
            subject_state.get("offset_y_norm", 0.0),
            -1.0,
            1.0,
        ))

        confidence = float(np.clip(
            subject_state.get("confidence", 1.0),
            0.0,
            1.0,
        ))

        # Desired framing offsets (rule-of-thirds aware)
        desired_x = framing_intent.get("horizontal_bias", 0.0)
        desired_y = framing_intent.get("vertical_bias", 0.0)

        # Framing error (perceptual)
        error = float(np.sqrt(
            (offset_x - desired_x) ** 2
            + (offset_y - desired_y) ** 2
        ))

        # Smooth confidence integration
        smooth = 0.85
        self._tracking_confidence = (
            smooth * self._tracking_confidence
            + (1.0 - smooth) * confidence
        )

        # Framing error memory (short-term)
        self._framing_error = (
            smooth * self._framing_error
            + (1.0 - smooth) * error
        )

        # Convert framing error into flight bias deltas
        lateral_adjust = float(np.clip(
            (offset_x - desired_x)
            * self._tracking_confidence
            * 0.6,
            -1.0,
            1.0,
        ))

        vertical_adjust = float(np.clip(
            (offset_y - desired_y)
            * self._tracking_confidence
            * 0.6,
            -1.0,
            1.0,
        ))

        # Preserve original path bias shape
        coupled_path = {
            "curvature": path_bias.get("curvature", 0.0),
            "lateral_offset": path_bias.get("lateral_offset", 0.0)
            - lateral_adjust,
            "vertical_arc": path_bias.get("vertical_arc", 0.0)
            - vertical_adjust,
            "coherence": path_bias.get("coherence", 0.5)
            * (0.8 + 0.2 * self._tracking_confidence),
        }

        self._last_update = now

        return {
            "path_bias_coupled": coupled_path,
            "framing_error": self._framing_error,
            "tracking_confidence": self._tracking_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset subject–flight coupling state.
        """
        self._framing_error = 0.0
        self._tracking_confidence = 1.0
        self._last_update = time.time()


