# ==============================================================================
# CHUNK 89 E 01 — SAFETY-FIRST CINEMATIC DEGRADATION
# ==============================================================================
#
# Purpose:
#   Gracefully degrade cinematic ambition under increasing risk
#   while preserving narrative intent, visual continuity, and
#   audience comfort — instead of hard aborts or sudden mode shifts.
#
# Core principle:
#   When risk rises, simplify the shot — don’t end the story.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class SafetyFirstCinematicDegradation:
    """
    Safety-first cinematic degradation engine.
    Reduces shot complexity, motion ambition, and framing aggression
    proportionally to risk while preserving emotional coherence.
    """

    __slots__ = (
        "_risk_memory",
        "_degradation_level",
        "_last_update",
    )

    def __init__(self):
        self._risk_memory: float = 0.0
        self._degradation_level: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Degradation logic
    # --------------------------------------------------------------------------

    def apply(
        self,
        safety_state: Dict[str, Any],
        path_bias: Dict[str, float],
        camera_primitives: Dict[str, float],
        motion_dynamics: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Apply safety-first cinematic degradation.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # Aggregate risk (normalized)
        risk = float(np.clip(
            0.5 * (1.0 - safety_state.get("safety_factor", 1.0))
            + 0.3 * safety_state.get("fatigue", 0.0)
            + 0.2 * safety_state.get("thermal", 0.0),
            0.0,
            1.0,
        ))

        # Risk memory (prevents oscillation)
        self._risk_memory = float(np.clip(
            0.9 * self._risk_memory + 0.1 * risk,
            0.0,
            1.0,
        ))

        # Degradation level rises slowly, falls very slowly
        if risk > self._degradation_level:
            self._degradation_level = float(np.clip(
                self._degradation_level + dt * 0.4 * risk,
                0.0,
                1.0,
            ))
        else:
            self._degradation_level = float(np.clip(
                self._degradation_level - dt * 0.1,
                0.0,
                1.0,
            ))

        d = self._degradation_level

        # Simplify path (reduce curvature & offsets)
        degraded_path = {
            "curvature": path_bias.get("curvature", 0.0) * (1.0 - 0.7 * d),
            "lateral_offset": path_bias.get("lateral_offset", 0.0) * (1.0 - 0.6 * d),
            "vertical_arc": path_bias.get("vertical_arc", 0.0) * (1.0 - 0.8 * d),
            "coherence": max(
                0.3,
                path_bias.get("coherence", 0.5) * (1.0 - 0.5 * d),
            ),
        }

        # Calm camera motion
        degraded_camera = dict(camera_primitives)
        degraded_camera["motion_smoothness"] = float(np.clip(
            degraded_camera.get("motion_smoothness", 0.5)
            + 0.4 * d,
            0.0,
            1.0,
        ))
        degraded_camera["framing_pressure"] = float(np.clip(
            degraded_camera.get("framing_pressure", 0.5)
            * (1.0 - 0.5 * d),
            0.0,
            1.0,
        ))

        # Reduce motion aggression
        degraded_motion = {
            "velocity_bias": motion_dynamics.get("velocity_bias", 0.5) * (1.0 - 0.6 * d),
            "acceleration_bias": motion_dynamics.get("acceleration_bias", 0.5) * (1.0 - 0.7 * d),
            "damping": float(np.clip(
                motion_dynamics.get("damping", 0.5) + 0.4 * d,
                0.0,
                1.0,
            )),
            "inertia": float(np.clip(
                motion_dynamics.get("inertia", 0.5) + 0.3 * d,
                0.0,
                1.0,
            )),
        }

        return {
            "degraded_path_bias": degraded_path,
            "degraded_camera_primitives": degraded_camera,
            "degraded_motion_dynamics": degraded_motion,
            "degradation_level": self._degradation_level,
            "risk_memory": self._risk_memory,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cinematic degradation state.
        """
        self._risk_memory = 0.0
        self._degradation_level = 0.0
        self._last_update = time.time()


