# ==============================================================================
# CHUNK 89 F 01 — DIRECTOR AI → MISSION PLANNER HINTS
# ==============================================================================
#
# Purpose:
#   Provide the mission planner with cinematic preference hints
#   that influence waypoint shaping, timing, and traversal style
#   without rewriting or invalidating mission structure.
#
# Core principle:
#   Missions define *where* — the director suggests *how*.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class DirectorMissionPlannerHints:
    """
    Director AI → mission planner hint generator.
    Emits advisory hints describing preferred pacing,
    waypoint softness, loiter tendencies, and transition mood.
    """

    __slots__ = (
        "_pacing_bias",
        "_loiter_bias",
        "_transition_softness",
        "_last_update",
    )

    def __init__(self):
        self._pacing_bias: float = 0.5
        self._loiter_bias: float = 0.0
        self._transition_softness: float = 0.5
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Hint synthesis
    # --------------------------------------------------------------------------

    def compute(
        self,
        director_state: Dict[str, Any],
        narrative_memory: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Compute mission planner hints.
        """
        now = time.time()

        emotional = director_state.get("emotional_vector", {})
        phase = director_state.get("narrative_phase", "development")

        # Pacing bias (slow dwell vs forward momentum)
        pacing_target = float(np.clip(
            0.6
            - 0.4 * emotional.get("tension", 0.0)
            + 0.3 * emotional.get("awe", 0.0)
            + (0.2 if phase == "resolution" else 0.0),
            0.2,
            0.9,
        ))

        # Loiter preference (linger when emotion benefits)
        loiter_target = float(np.clip(
            0.5 * emotional.get("awe", 0.0)
            + 0.4 * emotional.get("grief", 0.0)
            - 0.5 * emotional.get("tension", 0.0),
            0.0,
            1.0,
        ))

        # Transition softness (between waypoints)
        softness_target = float(np.clip(
            0.6
            + 0.3 * emotional.get("relief", 0.0)
            - 0.4 * emotional.get("tension", 0.0),
            0.3,
            1.0,
        ))

        # Smooth integration
        smooth = 0.85
        self._pacing_bias = smooth * self._pacing_bias + (1.0 - smooth) * pacing_target
        self._loiter_bias = smooth * self._loiter_bias + (1.0 - smooth) * loiter_target
        self._transition_softness = (
            smooth * self._transition_softness
            + (1.0 - smooth) * softness_target
        )

        self._last_update = now

        return {
            "mission_hints": {
                "pacing": self._pacing_bias,
                "loiter": self._loiter_bias,
                "transition_softness": self._transition_softness,
            },
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset mission hint state.
        """
        self._pacing_bias = 0.5
        self._loiter_bias = 0.0
        self._transition_softness = 0.5
        self._last_update = time.time()


