from typing import Dict, Any, Optional
import time
import uuid


class DirectorCloudSynchronizer:
    """
    Director ↔ cloud AI synchronization layer.
    Manages low-frequency, high-semantic exchanges between
    on-drone cognition and cloud-based intelligence.
    """

    __slots__ = (
        "_node_id",
        "_last_push",
        "_last_pull",
        "_cloud_latency_est",
        "_sync_quality",
    )

    def __init__(self):
        self._node_id: str = str(uuid.uuid4())
        self._last_push: float = 0.0
        self._last_pull: float = 0.0
        self._cloud_latency_est: float = 0.0
        self._sync_quality: float = 1.0


    # --------------------------------------------------------------------------
    # Synchronization logic
    # --------------------------------------------------------------------------

    def prepare_push_payload(
        self,
        director_state: Dict[str, Any],
        telemetry_summary: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Prepare a cloud-bound synchronization payload.
        """
        now = time.time()
        self._last_push = now

        payload = {
            "node_id": self._node_id,
            "timestamp": now,
            "director_state": {
                "narrative_phase": director_state.get("narrative_phase"),
                "emotional_vector": director_state.get("emotional_vector"),
                "shot_language": director_state.get("shot_language"),
            },
            "telemetry_summary": telemetry_summary,
        }

        return payload


    def ingest_cloud_response(
        self,
        cloud_packet: Optional[Dict[str, Any]],
    ) -> Dict[str, Any]:
        """
        Ingest advisory response from cloud AI.
        """
        now = time.time()
        self._last_pull = now

        if not cloud_packet:
            self._sync_quality *= 0.98
            return {
                "cloud_advice": None,
                "sync_quality": self._sync_quality,
                "timestamp": now,
            }

        latency = float(np.clip(
            now - cloud_packet.get("timestamp", now),
            0.0,
            5.0,
        ))

        # Update latency estimate
        self._cloud_latency_est = (
            0.8 * self._cloud_latency_est + 0.2 * latency
        )

        # Sync quality decays with latency
        self._sync_quality = float(np.clip(
            1.0 - 0.2 * self._cloud_latency_est,
            0.3,
            1.0,
        ))

        return {
            "cloud_advice": cloud_packet.get("advice"),
            "cloud_latency": self._cloud_latency_est,
            "sync_quality": self._sync_quality,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cloud synchronization state.
        """
        self._last_push = 0.0
        self._last_pull = 0.0
        self._cloud_latency_est = 0.0
        self._sync_quality = 1.0


