#   as *advisory influence*, shaping long-horizon decisions,
#   emotional calibration, and strategy refinement — without
#   compromising real-time autonomy or safety.
#
# Core principle:
#   Cloud feedback adjusts *tendencies*, never actions.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CloudDirectorFeedbackLoop:
    """
    Cloud AI → Director feedback loop.
    Consumes high-level cloud advice and converts it into
    slow-changing internal biases that gently steer the
    Director AI over time.
    """

    __slots__ = (
        "_emotional_bias",
        "_strategy_bias",
        "_confidence_bias",
        "_last_update",
    )

    def __init__(self):
        self._emotional_bias: Dict[str, float] = {}
        self._strategy_bias: Dict[str, float] = {}
        self._confidence_bias: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Feedback assimilation
    # --------------------------------------------------------------------------

    def assimilate(
        self,
        cloud_advice: Dict[str, Any],
        sync_quality: float,
    ) -> Dict[str, Any]:
        """
        Assimilate cloud advisory feedback.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        if not cloud_advice or sync_quality < 0.4:
            # Degrade influence gracefully
            self._confidence_bias *= 0.95
            return {
                "emotional_bias": self._emotional_bias,
                "strategy_bias": self._strategy_bias,
                "confidence_bias": self._confidence_bias,
                "timestamp": now,
            }

        # Extract advisory vectors
        emotional_hint = cloud_advice.get("emotional_adjustment", {})
        strategy_hint = cloud_advice.get("strategy_adjustment", {})
        confidence_hint = float(
            np.clip(cloud_advice.get("confidence", 0.0), -1.0, 1.0)
        )

        # Slow assimilation rates (cinematic inertia)
        rate = 0.1 * sync_quality

        # Update emotional bias vector
        for k, v in emotional_hint.items():
            prev = self._emotional_bias.get(k, 0.0)
            self._emotional_bias[k] = float(
                np.clip(prev + rate * (v - prev), -1.0, 1.0)
            )

        # Update strategy bias vector
        for k, v in strategy_hint.items():
            prev = self._strategy_bias.get(k, 0.0)
            self._strategy_bias[k] = float(
                np.clip(prev + rate * (v - prev), -1.0, 1.0)
            )

        # Confidence bias (trust in own decisions)
        self._confidence_bias = float(np.clip(
            self._confidence_bias + rate * confidence_hint,
            -1.0,
            1.0,
        ))

        return {
            "emotional_bias": dict(self._emotional_bias),
            "strategy_bias": dict(self._strategy_bias),
            "confidence_bias": self._confidence_bias,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cloud feedback influence.
        """
        self._emotional_bias.clear()
        self._strategy_bias.clear()
        self._confidence_bias = 0.0
        self._last_update = time.time()


