#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class MultiAgentDirectorConsensus:
    """
    Multi-agent Director consensus engine.
    Combines advisory signals from heterogeneous Director agents
    using authority, confidence, and temporal validity weighting.
    """

    __slots__ = (
        "_agent_memory",
        "_last_update",
    )

    def __init__(self):
        self._agent_memory: Dict[str, Dict[str, Any]] = {}
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Consensus synthesis
    # --------------------------------------------------------------------------

    def ingest_agent_signal(
        self,
        agent_id: str,
        agent_signal: Dict[str, Any],
    ) -> None:
        """
        Ingest a director-level advisory signal from an agent.
        """
        now = time.time()

        self._agent_memory[agent_id] = {
            "signal": agent_signal,
            "timestamp": now,
            "authority": float(np.clip(
                agent_signal.get("authority", 0.5),
                0.0,
                1.0,
            )),
            "confidence": float(np.clip(
                agent_signal.get("confidence", 0.5),
                0.0,
                1.0,
            )),
        }


    def synthesize(self) -> Dict[str, Any]:
        """
        Synthesize a weighted consensus from all active agents.
        """
        now = time.time()

        emotional_accumulator: Dict[str, float] = {}
        strategy_accumulator: Dict[str, float] = {}
        total_weight = 0.0

        for agent in self._agent_memory.values():
            age = max(now - agent["timestamp"], 1e-3)
            freshness = float(np.exp(-age / 5.0))  # seconds-scale decay

            weight = (
                agent["authority"]
                * agent["confidence"]
                * freshness
            )

            signal = agent["signal"]

            # Emotional vector aggregation
            for k, v in signal.get("emotional_vector", {}).items():
                emotional_accumulator[k] = (
                    emotional_accumulator.get(k, 0.0) + weight * v
                )

            # Strategy vector aggregation
            for k, v in signal.get("strategy_vector", {}).items():
                strategy_accumulator[k] = (
                    strategy_accumulator.get(k, 0.0) + weight * v
                )

            total_weight += weight

        if total_weight < 1e-3:
            return {
                "emotional_vector": {},
                "strategy_vector": {},
                "confidence": 0.0,
                "timestamp": now,
            }

        # Normalize accumulators
        emotional_consensus = {
            k: float(np.clip(v / total_weight, -1.0, 1.0))
            for k, v in emotional_accumulator.items()
        }

        strategy_consensus = {
            k: float(np.clip(v / total_weight, -1.0, 1.0))
            for k, v in strategy_accumulator.items()
        }

        self._last_update = now

        return {
            "emotional_vector": emotional_consensus,
            "strategy_vector": strategy_consensus,
            "confidence": float(np.clip(total_weight, 0.0, 1.0)),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset multi-agent consensus state.
        """
        self._agent_memory.clear()
        self._last_update = time.time()


