from typing import Dict, Any
import numpy as np
import time


class AppDirectorIntentInjector:
    """
    App control → Director intent injection.
    Converts explicit user inputs into soft intent pressures
    that bias Director cognition without hijacking control.
    """

    __slots__ = (
        "_intent_pressure",
        "_confidence_pressure",
        "_last_injection",
    )

    def __init__(self):
        self._intent_pressure: Dict[str, float] = {}
        self._confidence_pressure: float = 0.0
        self._last_injection: float = 0.0


    # --------------------------------------------------------------------------
    # Intent injection logic
    # --------------------------------------------------------------------------

    def inject(
        self,
        user_intent: Dict[str, Any],
        trust_level: float,
    ) -> Dict[str, Any]:
        """
        Inject interpreted user intent into Director cognition.
        """
        now = time.time()

        # Rate-limit injection
        if now - self._last_injection < 0.3:
            return {
                "intent_pressure": self._intent_pressure,
                "confidence_pressure": self._confidence_pressure,
                "timestamp": now,
            }

        self._last_injection = now

        trust = float(np.clip(trust_level, 0.0, 1.0))
        influence = 0.2 + 0.6 * trust  # bounded influence

        # Interpret intent vectors (semantic, not literal)
        interpreted = {}
        for k, v in user_intent.items():
            interpreted[k] = float(np.clip(v, -1.0, 1.0))

        # Assimilate slowly (prevents whiplash)
        for k, v in interpreted.items():
            prev = self._intent_pressure.get(k, 0.0)
            self._intent_pressure[k] = float(
                np.clip(prev + influence * 0.15 * (v - prev), -1.0, 1.0)
            )

        # Confidence pressure (user confidence vs system confidence)
        self._confidence_pressure = float(np.clip(
            self._confidence_pressure + influence * 0.1 * (trust - self._confidence_pressure),
            -1.0,
            1.0,
        ))

        return {
            "intent_pressure": dict(self._intent_pressure),
            "confidence_pressure": self._confidence_pressure,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset injected intent state.
        """
        self._intent_pressure.clear()
        self._confidence_pressure = 0.0
        self._last_injection = time.time()


