from typing import Dict, Any
import numpy as np
import time


class LiveOperatorOverrideArbitration:
    """
    Live operator override arbitration engine.
    Governs authority blending between human input and
    autonomous Director control using graded, time-bound influence.
    """

    __slots__ = (
        "_override_level",
        "_override_confidence",
        "_last_operator_input",
        "_cooldown",
    )

    def __init__(self):
        self._override_level: float = 0.0
        self._override_confidence: float = 0.0
        self._last_operator_input: float = 0.0
        self._cooldown: float = 0.0


    # --------------------------------------------------------------------------
    # Arbitration logic
    # --------------------------------------------------------------------------

    def arbitrate(
        self,
        operator_input: Dict[str, Any],
        director_confidence: float,
        safety_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Arbitrate operator override influence.
        """
        now = time.time()
        dt = max(now - self._last_operator_input, 1e-3)

        safety_factor = float(np.clip(
            safety_state.get("safety_factor", 1.0),
            0.0,
            1.0,
        ))

        operator_strength = float(np.clip(
            operator_input.get("strength", 0.0),
            0.0,
            1.0,
        ))

        operator_urgency = float(np.clip(
            operator_input.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        # Override request pressure
        request = operator_strength * (0.5 + 0.5 * operator_urgency)

        # Safety-gated maximum override
        max_override = 0.8 * safety_factor

        # Director resistance (confidence dampens override)
        resistance = float(np.clip(
            director_confidence,
            0.0,
            1.0,
        ))

        # Integrate override level
        target = request * (1.0 - 0.6 * resistance)
        target = min(target, max_override)

        # Smooth rise / slow decay
        rise_rate = 0.6
        decay_rate = 0.15

        if target > self._override_level:
            self._override_level = float(np.clip(
                self._override_level + rise_rate * dt * (target - self._override_level),
                0.0,
                max_override,
            ))
        else:
            self._override_level = float(np.clip(
                self._override_level - decay_rate * dt,
                0.0,
                max_override,
            ))

        # Confidence in override (stability of operator intent)
        self._override_confidence = float(np.clip(
            0.9 * self._override_confidence + 0.1 * operator_strength,
            0.0,
            1.0,
        ))

        self._last_operator_input = now

        return {
            "override_level": self._override_level,
            "override_confidence": self._override_confidence,
            "authority_blend": {
                "operator": self._override_level,
                "director": 1.0 - self._override_level,
            },
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset operator override state.
        """
        self._override_level = 0.0
        self._override_confidence = 0.0
        self._last_operator_input = time.time()
        self._cooldown = 0.0


