from typing import Dict, Any
import time
import json
import copy


class DirectorStatePersistence:
    """
    Director AI state persistence engine.
    Serializes and restores slow-changing cognitive tendencies
    while intentionally excluding volatile, real-time signals.
    """

    __slots__ = (
        "_schema_version",
        "_last_persist",
    )

    def __init__(self, schema_version: str = "92A01"):
        self._schema_version: str = schema_version
        self._last_persist: float = 0.0


    # --------------------------------------------------------------------------
    # Persistence logic
    # --------------------------------------------------------------------------

    def serialize(
        self,
        director_state: Dict[str, Any],
        cinematic_biases: Dict[str, Any],
        learning_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Serialize Director cognitive state into a persistence-safe form.
        """
        now = time.time()
        self._last_persist = now

        payload = {
            "schema_version": self._schema_version,
            "timestamp": now,
            "director": {
                "narrative_phase": director_state.get("narrative_phase"),
                "emotional_bias": director_state.get("emotional_bias"),
                "strategy_bias": director_state.get("strategy_bias"),
                "confidence_bias": director_state.get("confidence"),
            },
            "cinematic_biases": {
                "path_preferences": cinematic_biases.get("path_preferences"),
                "framing_preferences": cinematic_biases.get("framing_preferences"),
                "pacing_preferences": cinematic_biases.get("pacing_preferences"),
            },
            "learning_state": learning_state,
        }

        # Deep-copy to ensure immutability after emit
        return copy.deepcopy(payload)


    def deserialize(
        self,
        payload: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Restore Director cognitive state from persisted payload.
        """
        if not payload:
            return {}

        if payload.get("schema_version") != self._schema_version:
            # Version mismatch — degrade gracefully
            return {}

        restored = {
            "director": {
                "narrative_phase": payload.get("director", {}).get("narrative_phase"),
                "emotional_bias": payload.get("director", {}).get("emotional_bias", {}),
                "strategy_bias": payload.get("director", {}).get("strategy_bias", {}),
                "confidence_bias": payload.get("director", {}).get("confidence_bias", 0.0),
            },
            "cinematic_biases": payload.get("cinematic_biases", {}),
            "learning_state": payload.get("learning_state", {}),
        }

        return restored


    def encode_json(self, payload: Dict[str, Any]) -> str:
        """
        Encode persistence payload to JSON string.
        """
        return json.dumps(payload, separators=(",", ":"), ensure_ascii=False)


    def decode_json(self, blob: str) -> Dict[str, Any]:
        """
        Decode persistence payload from JSON string.
        """
        try:
            return json.loads(blob)
        except Exception:
            return {}


    def reset(self) -> None:
        """
        Reset persistence timing state.
        """
        self._last_persist = time.time()


