from typing import Dict, Any
import numpy as np
import time


class DirectorColdStartReconstruction:
    """
    Director AI cold-start reconstruction engine.
    Gradually restores persisted cognitive tendencies while
    respecting live sensor reality and safety context.
    """

    __slots__ = (
        "_rehydration_level",
        "_confidence",
        "_last_update",
    )

    def __init__(self):
        self._rehydration_level: float = 0.0
        self._confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Reconstruction logic
    # --------------------------------------------------------------------------

    def reconstruct(
        self,
        persisted_state: Dict[str, Any],
        live_context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Reconstruct Director cognition from persisted state.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # Gradual rehydration (time-based)
        self._rehydration_level = float(np.clip(
            self._rehydration_level + dt * 0.15,
            0.0,
            1.0,
        ))

        # Safety-aware confidence ramp
        safety_factor = float(np.clip(
            live_context.get("safety_factor", 1.0),
            0.0,
            1.0,
        ))

        self._confidence = float(np.clip(
            self._confidence + dt * 0.2 * safety_factor,
            0.0,
            1.0,
        ))

        # Restore emotional & strategy biases proportionally
        restored_emotional = {}
        for k, v in persisted_state.get("director", {}).get("emotional_bias", {}).items():
            restored_emotional[k] = float(
                np.clip(v * self._rehydration_level, -1.0, 1.0)
            )

        restored_strategy = {}
        for k, v in persisted_state.get("director", {}).get("strategy_bias", {}).items():
            restored_strategy[k] = float(
                np.clip(v * self._rehydration_level, -1.0, 1.0)
            )

        return {
            "rehydration_level": self._rehydration_level,
            "confidence": self._confidence,
            "director_state": {
                "narrative_phase": persisted_state.get("director", {}).get("narrative_phase"),
                "emotional_bias": restored_emotional,
                "strategy_bias": restored_strategy,
            },
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cold-start reconstruction state.
        """
        self._rehydration_level = 0.0
        self._confidence = 0.0
        self._last_update = time.time()


