class MissionReplayDirectorLearning:
    """
    Mission replay → Director learning hooks.
    Aggregates post-mission signals into slow-changing
    preference adjustments for future flights.
    """

    __slots__ = (
        "_learning_memory",
        "_last_update",
    )

    def __init__(self):
        self._learning_memory: Dict[str, float] = {}
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Learning extraction
    # --------------------------------------------------------------------------

    def ingest_replay(
        self,
        mission_summary: Dict[str, Any],
        audience_feedback: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Ingest mission replay summary and feedback.
        """
        now = time.time()
        self._last_update = now

        # Outcome signals (normalized)
        stability_score = float(np.clip(
            mission_summary.get("stability_score", 0.5),
            0.0,
            1.0,
        ))

        cinematic_score = float(np.clip(
            mission_summary.get("cinematic_score", 0.5),
            0.0,
            1.0,
        ))

        safety_score = float(np.clip(
            mission_summary.get("safety_score", 0.5),
            0.0,
            1.0,
        ))

        engagement = float(np.clip(
            audience_feedback.get("engagement", 0.5),
            0.0,
            1.0,
        ))

        # Learning deltas (small, bounded)
        adjustments = {
            "motion_smoothness": 0.05 * (stability_score - 0.5),
            "path_curvature": 0.05 * (cinematic_score - 0.5),
            "risk_tolerance": 0.05 * (engagement - safety_score),
        }

        # Assimilate slowly
        for k, delta in adjustments.items():
            prev = self._learning_memory.get(k, 0.0)
            self._learning_memory[k] = float(
                np.clip(prev + delta, -1.0, 1.0)
            )

        return {
            "learning_adjustments": dict(self._learning_memory),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset learning memory.
        """
        self._learning_memory.clear()
        self._last_update = time.time()


