# CHUNK 93 B 01 — BACKBONE → FLIGHT CONTROLLER MEDIATION LAYER
# ==============================================================================
#
# Purpose:
#   Mediate backbone-level cinematic intent into flight-controller-
#   compatible control envelopes while preserving:
#     • Aerodynamic safety
#     • Autopilot authority
#     • Predictable vehicle dynamics
#
# Core principle:
#   The Backbone suggests tendencies —
#   the Flight Controller enforces physics.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class BackboneFlightMediationLayer:
    """
    Backbone → Flight Controller mediation layer.
    Converts cinematic intent into bounded, rate-limited
    flight guidance modifiers suitable for FC consumption.
    """

    __slots__ = (
        "_last_emit",
        "_emit_interval",
    )

    def __init__(self, emit_hz: float = 20.0):
        self._emit_interval: float = 1.0 / max(emit_hz, 5.0)
        self._last_emit: float = 0.0


    # --------------------------------------------------------------------------
    # Mediation logic
    # --------------------------------------------------------------------------

    def mediate(
        self,
        backbone_intent: Dict[str, Any],
        flight_state: Dict[str, Any],
        envelope: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Mediate backbone intent into flight-safe guidance deltas.
        """
        now = time.time()

        if now - self._last_emit < self._emit_interval:
            return {}

        self._last_emit = now

        # Extract intent profiles
        motion = backbone_intent.get("motion_profile", {})
        pacing = backbone_intent.get("pacing_profile", {})
        confidence = float(np.clip(
            backbone_intent.get("confidence", 0.5),
            0.0,
            1.0,
        ))

        # Flight envelope constraints
        max_tilt = float(envelope.get("max_tilt_deg", 25.0))
        max_yaw_rate = float(envelope.get("max_yaw_rate_dps", 90.0))
        max_vel = float(envelope.get("max_velocity_mps", 10.0))

        # Cinematic modulation factors (bounded)
        aggression = float(np.clip(motion.get("aggression", 0.0), -1.0, 1.0))
        smoothness = float(np.clip(motion.get("smoothness", 0.5), 0.0, 1.0))
        linger = float(np.clip(pacing.get("linger_factor", 0.0), 0.0, 1.0))

        # Convert to safe deltas
        tilt_bias = aggression * max_tilt * 0.25
        yaw_rate_bias = aggression * max_yaw_rate * 0.3
        velocity_bias = aggression * max_vel * 0.2

        # Smoothness dampening
        tilt_bias *= smoothness
        yaw_rate_bias *= smoothness
        velocity_bias *= (1.0 - 0.5 * linger)

        # Confidence gating
        tilt_bias *= confidence
        yaw_rate_bias *= confidence
        velocity_bias *= confidence

        # Final bounded guidance deltas
        guidance = {
            "tilt_bias_deg": float(np.clip(
                tilt_bias,
                -max_tilt * 0.3,
                max_tilt * 0.3,
            )),
            "yaw_rate_bias_dps": float(np.clip(
                yaw_rate_bias,
                -max_yaw_rate * 0.4,
                max_yaw_rate * 0.4,
            )),
            "velocity_bias_mps": float(np.clip(
                velocity_bias,
                -max_vel * 0.3,
                max_vel * 0.3,
            )),
        }

        return {
            "flight_guidance_bias": guidance,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset mediation timing state.
        """
        self._last_emit = 0.0


