# CHUNK 93 C 01 — BACKBONE → ESP32 / GIMBAL / CAMERA BUS
# ==============================================================================
#
# Purpose:
#   Distribute backbone-level cinematic intent to embedded
#   subsystems (ESP32, gimbal controllers, camera modules)
#   in a synchronized, rate-limited, actuator-safe manner.
#
# Core principle:
#   One intent — many actuators — zero desynchronization.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class BackbonePeripheralBus:
    """
    Backbone → ESP32 / Gimbal / Camera bus dispatcher.
    Fans out cinematic intent into device-specific control
    envelopes while preserving temporal coherence.
    """

    __slots__ = (
        "_last_emit",
        "_emit_interval",
    )

    def __init__(self, emit_hz: float = 30.0):
        self._emit_interval: float = 1.0 / max(emit_hz, 10.0)
        self._last_emit: float = 0.0


    # --------------------------------------------------------------------------
    # Bus dispatch logic
    # --------------------------------------------------------------------------

    def dispatch(
        self,
        backbone_intent: Dict[str, Any],
        peripheral_state: Dict[str, Any],
        constraints: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Dispatch backbone intent to peripheral subsystems.
        """
        now = time.time()

        if now - self._last_emit < self._emit_interval:
            return {}

        self._last_emit = now

        framing = backbone_intent.get("framing_profile", {})
        pacing = backbone_intent.get("pacing_profile", {})
        confidence = float(np.clip(
            backbone_intent.get("confidence", 0.5),
            0.0,
            1.0,
        ))

        # -------------------------
        # Gimbal control envelope
        # -------------------------
        max_gimbal_rate = float(constraints.get("max_gimbal_rate_dps", 120.0))
        subject_priority = float(np.clip(
            framing.get("subject_priority", 0.5),
            0.0,
            1.0,
        ))

        gimbal_command = {
            "pan_rate_dps": float(np.clip(
                (subject_priority - 0.5) * max_gimbal_rate * confidence,
                -max_gimbal_rate,
                max_gimbal_rate,
            )),
            "tilt_rate_dps": float(np.clip(
                (pacing.get("linger_factor", 0.0) - 0.5)
                * max_gimbal_rate
                * confidence,
                -max_gimbal_rate,
                max_gimbal_rate,
            )),
        }

        # -------------------------
        # Camera control envelope
        # -------------------------
        camera_command = {
            "exposure_bias": float(np.clip(
                framing.get("subject_priority", 0.0) * 0.4,
                -1.0,
                1.0,
            )),
            "stabilization_strength": float(np.clip(
                0.5 + 0.5 * confidence,
                0.0,
                1.0,
            )),
        }

        # -------------------------
        # ESP32 auxiliary envelope
        # -------------------------
        esp32_command = {
            "led_intensity": float(np.clip(
                confidence,
                0.0,
                1.0,
            )),
            "aux_smoothing": float(np.clip(
                pacing.get("linger_factor", 0.0),
                0.0,
                1.0,
            )),
        }

        return {
            "gimbal": gimbal_command,
            "camera": camera_command,
            "esp32": esp32_command,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset peripheral bus timing state.
        """
        self._last_emit = 0.0


