# ==============================================================================

from typing import Dict, Any
import time
import json
import zlib


class BackboneCloudSyncBridge:
    """
    Backbone → Cloud sync & telemetry bridge.
    Emits compact, semantically meaningful telemetry frames
    suitable for cloud ingestion, analytics, and AI advisory loops.
    """

    __slots__ = (
        "_last_emit",
        "_emit_interval",
    )

    def __init__(self, emit_hz: float = 2.0):
        self._emit_interval: float = 1.0 / max(emit_hz, 0.2)
        self._last_emit: float = 0.0


    # --------------------------------------------------------------------------
    # Cloud sync logic
    # --------------------------------------------------------------------------

    def package(
        self,
        director_summary: Dict[str, Any],
        backbone_state: Dict[str, Any],
        flight_summary: Dict[str, Any],
        health_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Package system state into a cloud-safe telemetry frame.
        """
        now = time.time()

        if now - self._last_emit < self._emit_interval:
            return {}

        self._last_emit = now

        payload = {
            "timestamp": now,
            "director": {
                "narrative_phase": director_summary.get("narrative_phase"),
                "emotional_vector": director_summary.get("emotional_vector"),
                "confidence": director_summary.get("confidence"),
            },
            "backbone": {
                "intent_hash": backbone_state.get("intent_hash"),
                "mode": backbone_state.get("mode"),
            },
            "flight": {
                "position": flight_summary.get("position"),
                "velocity": flight_summary.get("velocity"),
                "battery": flight_summary.get("battery"),
            },
            "health": {
                "link_quality": health_state.get("link_quality"),
                "thermal_margin": health_state.get("thermal_margin"),
            },
        }

        # Compact encoding for transport
        encoded = json.dumps(payload, separators=(",", ":"), ensure_ascii=False)
        compressed = zlib.compress(encoded.encode("utf-8"), level=6)

        return {
            "blob": compressed,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cloud sync timing state.
        """
        self._last_emit = 0.0


