from typing import Dict, Any
import time
import numpy as np


class CloudMissionGuidanceBridge:
    """
    Cloud AI ↔ mission-level guidance bridge.
    Assimilates high-level cloud mission suggestions into
    bounded, interpretable mission intent for the onboard system.
    """

    __slots__ = (
        "_last_update",
        "_assimilation_level",
    )

    def __init__(self):
        self._last_update: float = 0.0
        self._assimilation_level: float = 0.0


    # --------------------------------------------------------------------------
    # Mission guidance assimilation
    # --------------------------------------------------------------------------

    def assimilate(
        self,
        cloud_guidance: Dict[str, Any],
        mission_context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Assimilate cloud mission guidance into onboard intent.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # Gradual assimilation (prevents goal whiplash)
        self._assimilation_level = float(np.clip(
            self._assimilation_level + dt * 0.1,
            0.0,
            1.0,
        ))

        # Extract cloud-level intent
        objective = cloud_guidance.get("objective", {})
        constraints = cloud_guidance.get("constraints", {})
        narrative_hint = cloud_guidance.get("narrative_hint", {})

        # Contextual gating (battery, link, airspace)
        context_gate = float(np.clip(
            mission_context.get("context_gate", 1.0),
            0.0,
            1.0,
        ))

        # Construct mission intent
        mission_intent = {
            "objective": objective,
            "constraints": constraints,
            "narrative_bias": narrative_hint,
            "confidence": float(np.clip(
                cloud_guidance.get("confidence", 0.5)
                * self._assimilation_level
                * context_gate,
                0.0,
                1.0,
            )),
        }

        return {
            "mission_intent": mission_intent,
            "assimilation_level": self._assimilation_level,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cloud mission guidance state.
        """
        self._last_update = time.time()
        self._assimilation_level = 0.0


