# ==============================================================================
# CHUNK 95 A 01 — AI MISSION PLANNER (SEMANTIC → PATH)
# ==============================================================================
#
# Purpose:
#   Convert high-level semantic mission intent (from cloud AI,
#   user language, or Director narrative goals) into a structured,
#   executable spatial plan — without collapsing cinematic meaning.
#
# Core principle:
#   A mission is not a route — it is a spatial story.
#
# ==============================================================================

from typing import Dict, Any, List, Tuple
import numpy as np
import time
import math


class SemanticMissionPlanner:
    """
    AI Mission Planner (Semantic → Path).
    Translates semantic objectives like:
        "orbit the subject slowly at sunset"
        "reveal the landscape, then approach the target"
    into structured path primitives consumable by the backbone.
    """

    __slots__ = (
        "_last_plan_time",
        "_cooldown",
    )

    def __init__(self, replanning_cooldown: float = 2.0):
        self._last_plan_time: float = 0.0
        self._cooldown: float = replanning_cooldown


    # --------------------------------------------------------------------------
    # Semantic → spatial planning
    # --------------------------------------------------------------------------

    def plan(
        self,
        mission_intent: Dict[str, Any],
        world_state: Dict[str, Any],
        subject_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Generate a spatial mission plan from semantic intent.
        """
        now = time.time()

        if now - self._last_plan_time < self._cooldown:
            return {}

        self._last_plan_time = now

        objective = mission_intent.get("objective", {})
        narrative_bias = mission_intent.get("narrative_bias", {})
        confidence = float(np.clip(
            mission_intent.get("confidence", 0.5),
            0.0,
            1.0,
        ))

        subject_pos = subject_state.get("position")
        drone_pos = world_state.get("position")

        if subject_pos is None or drone_pos is None:
            return {}

        # -------------------------
        # Interpret semantic intent
        # -------------------------
        mode = objective.get("mode", "observe")
        desired_radius = float(objective.get("radius", 8.0))
        altitude_bias = float(objective.get("altitude_bias", 0.0))
        direction = objective.get("direction", "cw")

        # Narrative modifiers
        reveal_factor = float(np.clip(
            narrative_bias.get("reveal", 0.0),
            0.0,
            1.0,
        ))

        intimacy = float(np.clip(
            narrative_bias.get("intimacy", 0.0),
            -1.0,
            1.0,
        ))

        # -------------------------
        # Build path primitives
        # -------------------------
        path_primitives: List[Dict[str, Any]] = []

        # Approach / reveal phase
        if reveal_factor > 0.2:
            path_primitives.append({
                "type": "approach",
                "from": drone_pos,
                "to": subject_pos,
                "stand_off": desired_radius * (1.0 + reveal_factor),
                "speed_bias": 0.3 * confidence,
            })

        # Orbit / follow phase
        if mode in ("orbit", "follow"):
            path_primitives.append({
                "type": "orbit" if mode == "orbit" else "follow",
                "center": subject_pos,
                "radius": max(2.0, desired_radius * (1.0 - 0.3 * intimacy)),
                "angular_speed": 0.2 * confidence,
                "direction": direction,
                "altitude_offset": altitude_bias,
            })

        # Hold / linger phase
        if narrative_bias.get("linger", 0.0) > 0.3:
            path_primitives.append({
                "type": "hold",
                "duration": 3.0 + 4.0 * narrative_bias.get("linger", 0.0),
            })

        return {
            "mission_path": path_primitives,
            "confidence": confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset mission planner timing state.
        """
        self._last_plan_time = 0.0


