# ==============================================================================

from typing import Dict, Any, List
import numpy as np
import time
import math


class DynamicWaypointReconciliation:
    """
    Dynamic waypoint reconciliation engine.
    Adjusts mission waypoints in real time to reflect
    subject movement, wind drift, and execution variance
    while maintaining cinematic structure.
    """

    __slots__ = (
        "_last_update",
        "_reconciliation_strength",
    )

    def __init__(self):
        self._last_update: float = 0.0
        self._reconciliation_strength: float = 0.0


    # --------------------------------------------------------------------------
    # Waypoint reconciliation
    # --------------------------------------------------------------------------

    def reconcile(
        self,
        mission_path: List[Dict[str, Any]],
        live_subject_state: Dict[str, Any],
        live_drone_state: Dict[str, Any],
        envelope: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Reconcile mission waypoints against live state.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # Strength ramps slowly to avoid oscillation
        self._reconciliation_strength = float(np.clip(
            self._reconciliation_strength + dt * 0.2,
            0.0,
            1.0,
        ))

        subject_pos = live_subject_state.get("position")
        drone_pos = live_drone_state.get("position")

        if subject_pos is None or drone_pos is None:
            return {}

        reconciled_path: List[Dict[str, Any]] = []

        max_shift = float(envelope.get("motion", {}).get("max_speed_mps", 5.0)) * 0.5

        for segment in mission_path:
            seg = dict(segment)

            if seg.get("type") in ("orbit", "follow"):
                # Re-anchor center toward live subject
                center = seg.get("center", subject_pos)
                shift_vec = np.array(subject_pos) - np.array(center)

                shift_mag = float(np.linalg.norm(shift_vec))
                if shift_mag > 1e-3:
                    shift_dir = shift_vec / shift_mag
                else:
                    shift_dir = shift_vec

                allowed_shift = min(shift_mag, max_shift * self._reconciliation_strength)
                new_center = (
                    np.array(center) + shift_dir * allowed_shift
                )

                seg["center"] = tuple(new_center.tolist())

            elif seg.get("type") == "approach":
                # Adjust target position gently
                target = np.array(seg.get("to", subject_pos))
                shift_vec = np.array(subject_pos) - target
                seg["to"] = tuple(
                    (target + shift_vec * self._reconciliation_strength).tolist()
                )

            reconciled_path.append(seg)

        return {
            "reconciled_path": reconciled_path,
            "reconciliation_strength": self._reconciliation_strength,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset reconciliation state.
        """
        self._last_update = time.time()
        self._reconciliation_strength = 0.0


