# CHUNK 96 A 01 — MISSION EXECUTION STATE MACHINE
# ==============================================================================
#
# Purpose:
#   Execute reconciled mission paths through a robust, interruptible,
#   safety-aware state machine that coordinates flight, camera,
#   and Director intent in real time.
#
# Core principle:
#   Missions evolve — execution must adapt, not assume.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import numpy as np
from enum import Enum, auto


class MissionState(Enum):
    IDLE = auto()
    INIT = auto()
    APPROACH = auto()
    ORBIT = auto()
    FOLLOW = auto()
    HOLD = auto()
    TRANSITION = auto()
    COMPLETE = auto()
    ABORT = auto()


class MissionExecutionStateMachine:
    """
    Mission execution state machine.
    Drives mission execution across cinematic phases while
    remaining interruptible, observable, and safety-aware.
    """

    __slots__ = (
        "_state",
        "_current_segment",
        "_segment_start_time",
        "_last_update",
    )

    def __init__(self):
        self._state: MissionState = MissionState.IDLE
        self._current_segment: Dict[str, Any] | None = None
        self._segment_start_time: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # State machine update
    # --------------------------------------------------------------------------

    def update(
        self,
        reconciled_path: List[Dict[str, Any]],
        live_state: Dict[str, Any],
        envelope: Dict[str, Any],
        abort_signal: bool = False,
    ) -> Dict[str, Any]:
        """
        Advance mission execution state.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        if abort_signal:
            self._state = MissionState.ABORT

        # -------------------------
        # State transitions
        # -------------------------
        if self._state == MissionState.IDLE:
            if reconciled_path:
                self._state = MissionState.INIT

        elif self._state == MissionState.INIT:
            self._current_segment = reconciled_path[0]
            self._segment_start_time = now
            self._state = self._infer_state(self._current_segment)

        elif self._state in (
            MissionState.APPROACH,
            MissionState.ORBIT,
            MissionState.FOLLOW,
            MissionState.HOLD,
        ):
            if self._segment_complete(now):
                next_index = reconciled_path.index(self._current_segment) + 1
                if next_index < len(reconciled_path):
                    self._current_segment = reconciled_path[next_index]
                    self._segment_start_time = now
                    self._state = self._infer_state(self._current_segment)
                else:
                    self._state = MissionState.COMPLETE

        elif self._state == MissionState.ABORT:
            return {
                "state": self._state.name,
                "action": "abort",
                "timestamp": now,
            }

        # -------------------------
        # Output execution intent
        # -------------------------
        return {
            "state": self._state.name,
            "current_segment": self._current_segment,
            "time_in_state": now - self._segment_start_time,
            "timestamp": now,
        }


    # --------------------------------------------------------------------------
    # Helpers
    # --------------------------------------------------------------------------

    def _infer_state(self, segment: Dict[str, Any]) -> MissionState:
        t = segment.get("type")
        if t == "approach":
            return MissionState.APPROACH
        if t == "orbit":
            return MissionState.ORBIT
        if t == "follow":
            return MissionState.FOLLOW
        if t == "hold":
            return MissionState.HOLD
        return MissionState.TRANSITION


    def _segment_complete(self, now: float) -> bool:
        if self._current_segment is None:
            return True
        duration = self._current_segment.get("duration")
        if duration is not None:
            return (now - self._segment_start_time) >= duration
        return False


    def reset(self) -> None:
        """
        Reset mission execution state.
        """
        self._state = MissionState.IDLE
        self._current_segment = None
        self._segment_start_time = 0.0
        self._last_update = time.time()


