# ==============================================================================
# CHUNK 97 B 01 — OCCLUSION-AWARE TRACKING CONTINUITY
# ==============================================================================
#
# Purpose:
#   Maintain subject tracking continuity through partial or full
#   occlusions by blending perceptual prediction, motion memory,
#   and narrative intent — avoiding visual discontinuities.
#
# Core principle:
#   When the subject disappears, the camera should remember.
#
# ==============================================================================

from typing import Dict, Any, Tuple
import numpy as np
import time


class OcclusionAwareTrackingContinuity:
    """
    Occlusion-aware tracking continuity engine.
    Preserves perceived subject presence across occlusion events
    by predicting motion and modulating confidence decay.
    """

    __slots__ = (
        "_predicted_position",
        "_velocity_memory",
        "_confidence",
        "_last_update",
    )

    def __init__(self):
        self._predicted_position: Tuple[float, float, float] | None = None
        self._velocity_memory: Tuple[float, float, float] = (0.0, 0.0, 0.0)
        self._confidence: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Continuity update
    # --------------------------------------------------------------------------

    def update(
        self,
        perception_state: Dict[str, Any],
        narrative_context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update tracking continuity across occlusion.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        visibility = float(np.clip(
            perception_state.get("subject_visibility", 1.0),
            0.0,
            1.0,
        ))

        subject_pos = perception_state.get("subject_position")
        subject_vel = perception_state.get("subject_velocity", self._velocity_memory)

        # -------------------------
        # Visible subject update
        # -------------------------
        if visibility > 0.6 and subject_pos is not None:
            self._predicted_position = tuple(subject_pos)
            self._velocity_memory = tuple(subject_vel)

            self._confidence = float(np.clip(
                0.8 * self._confidence + 0.2 * visibility,
                0.0,
                1.0,
            ))

            return {
                "mode": "tracking",
                "predicted_position": self._predicted_position,
                "confidence": self._confidence,
                "timestamp": now,
            }

        # -------------------------
        # Occluded subject prediction
        # -------------------------
        linger_bias = float(np.clip(
            narrative_context.get("linger", 0.5),
            0.0,
            1.0,
        ))

        decay_rate = 0.4 * (1.0 - linger_bias)
        self._confidence = float(np.clip(
            self._confidence - decay_rate * dt,
            0.0,
            1.0,
        ))

        if self._predicted_position is not None:
            px, py, pz = self._predicted_position
            vx, vy, vz = self._velocity_memory

            predicted = (
                px + vx * dt,
                py + vy * dt,
                pz + vz * dt,
            )

            self._predicted_position = predicted

        return {
            "mode": "occluded",
            "predicted_position": self._predicted_position,
            "confidence": self._confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset occlusion tracking continuity state.
        """
        self._predicted_position = None
        self._velocity_memory = (0.0, 0.0, 0.0)
        self._confidence = 0.0
        self._last_update = time.time()


