# ==============================================================================
# CHUNK 98 A 01 — CINEMATIC FAILURE RECOVERY & GRACEFUL EXIT
# ==============================================================================
#
# Purpose:
#   Transform unavoidable mission failures into controlled,
#   narratively coherent exits — preserving safety, dignity,
#   and cinematic intent instead of abrupt termination.
#
# Core principle:
#   How a shot ends matters as much as how it begins.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CinematicFailureRecovery:
    """
    Cinematic failure recovery & graceful exit engine.
    Orchestrates expressive, safe termination behaviors
    when missions cannot continue as intended.
    """

    __slots__ = (
        "_active",
        "_exit_start_time",
        "_exit_mode",
    )

    def __init__(self):
        self._active: bool = False
        self._exit_start_time: float = 0.0
        self._exit_mode: str | None = None


    # --------------------------------------------------------------------------
    # Failure recovery orchestration
    # --------------------------------------------------------------------------

    def initiate(
        self,
        failure_context: Dict[str, Any],
        narrative_context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Initiate a graceful cinematic exit.
        """
        now = time.time()
        self._active = True
        self._exit_start_time = now

        severity = float(np.clip(
            failure_context.get("severity", 0.5),
            0.0,
            1.0,
        ))

        linger_bias = float(np.clip(
            narrative_context.get("linger", 0.5),
            0.0,
            1.0,
        ))

        # -------------------------
        # Exit mode selection
        # -------------------------
        if severity > 0.7:
            self._exit_mode = "safety_return"
        elif linger_bias > 0.6:
            self._exit_mode = "slow_pullback"
        else:
            self._exit_mode = "hold_then_exit"

        return {
            "exit_mode": self._exit_mode,
            "severity": severity,
            "timestamp": now,
        }


    def update(self) -> Dict[str, Any]:
        """
        Advance graceful exit behavior.
        """
        if not self._active or self._exit_mode is None:
            return {}

        now = time.time()
        elapsed = now - self._exit_start_time

        # -------------------------
        # Mode-specific progression
        # -------------------------
        if self._exit_mode == "slow_pullback":
            progress = float(np.clip(elapsed / 4.0, 0.0, 1.0))
            action = {
                "camera_zoom": -0.3 * progress,
                "motion_slowdown": 0.5 * progress,
            }

        elif self._exit_mode == "hold_then_exit":
            if elapsed < 2.0:
                action = {
                    "camera_hold": True,
                    "motion": "minimal",
                }
            else:
                action = {
                    "transition": "exit",
                    "motion_slowdown": 0.6,
                }

        else:  # safety_return
            action = {
                "return_home": True,
                "motion_slowdown": 0.8,
            }

        return {
            "exit_mode": self._exit_mode,
            "action": action,
            "elapsed": elapsed,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset failure recovery state.
        """
        self._active = False
        self._exit_start_time = 0.0
        self._exit_mode = None


