# ==============================================================================
# CHUNK 99 A 01 — DIRECTOR CONFIDENCE FEEDBACK LOOP
# ==============================================================================
#
# Purpose:
#   Close the cognitive loop by feeding execution outcomes,
#   safety pressures, and perceptual stability back into the
#   Director’s confidence model — regulating future autonomy.
#
# Core principle:
#   Confidence is earned continuously, not assumed.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class DirectorConfidenceFeedbackLoop:
    """
    Director confidence feedback loop.
    Adjusts Director autonomy confidence based on how well
    intent survived contact with reality.
    """

    __slots__ = (
        "_confidence",
        "_stability_memory",
        "_last_update",
    )

    def __init__(self, initial_confidence: float = 0.6):
        self._confidence: float = float(np.clip(initial_confidence, 0.0, 1.0))
        self._stability_memory: float = 0.0
        self._last_update: float = 0.0


    # --------------------------------------------------------------------------
    # Feedback update
    # --------------------------------------------------------------------------

    def update(
        self,
        execution_report: Dict[str, Any],
        safety_report: Dict[str, Any],
        perception_report: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update Director confidence from system outcomes.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Outcome signals
        # -------------------------
        completion = float(np.clip(
            execution_report.get("completion_ratio", 1.0),
            0.0,
            1.0,
        ))

        aborts = float(execution_report.get("abort_count", 0.0))
        stability = float(np.clip(
            perception_report.get("tracking_stability", 1.0),
            0.0,
            1.0,
        ))

        safety_factor = float(np.clip(
            safety_report.get("safety_factor", 1.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Stability memory
        # -------------------------
        self._stability_memory = float(np.clip(
            0.9 * self._stability_memory + 0.1 * stability,
            0.0,
            1.0,
        ))

        # -------------------------
        # Confidence adjustment
        # -------------------------
        penalty = 0.15 * aborts + 0.3 * (1.0 - safety_factor)
        reward = 0.4 * completion + 0.3 * self._stability_memory

        delta = (reward - penalty) * dt * 0.5

        self._confidence = float(np.clip(
            self._confidence + delta,
            0.0,
            1.0,
        ))

        return {
            "director_confidence": self._confidence,
            "stability_memory": self._stability_memory,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset confidence feedback state.
        """
        self._confidence = 0.5
        self._stability_memory = 0.0
        self._last_update = time.time()


