# ==============================================================================
# CHUNK 100 A 01 — HUMAN OVERRIDE ARBITRATION LAYER
# ==============================================================================
#
# Purpose:
#   Allow human operators to intervene in flight and camera control
#   without collapsing Director cognition, mission structure,
#   or safety envelopes.
#
# Core principle:
#   Humans bend intent — they do not erase it.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class HumanOverrideArbitration:
    """
    Human override arbitration layer.
    Blends human inputs with AI intent using confidence-weighted,
    time-coherent arbitration rather than hard control switching.
    """

    __slots__ = (
        "_override_strength",
        "_last_input_time",
    )

    def __init__(self):
        self._override_strength: float = 0.0
        self._last_input_time: float = 0.0


    # --------------------------------------------------------------------------
    # Arbitration logic
    # --------------------------------------------------------------------------

    def arbitrate(
        self,
        ai_intent: Dict[str, Any],
        human_input: Dict[str, Any],
        director_confidence: float,
        safety_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Arbitrate between AI intent and human input.
        """
        now = time.time()

        # Detect active human input
        human_active = bool(human_input.get("active", False))
        input_strength = float(np.clip(
            human_input.get("strength", 0.0),
            0.0,
            1.0,
        ))

        if human_active:
            self._last_input_time = now
            self._override_strength = float(np.clip(
                self._override_strength + 0.4 * input_strength,
                0.0,
                1.0,
            ))
        else:
            # Decay override slowly to avoid snap-back
            self._override_strength = float(np.clip(
                self._override_strength - 0.1,
                0.0,
                1.0,
            ))

        safety_factor = float(np.clip(
            safety_state.get("safety_factor", 1.0),
            0.0,
            1.0,
        ))

        # AI authority dampened by human intent and safety pressure
        ai_weight = (1.0 - self._override_strength) * director_confidence * safety_factor
        human_weight = 1.0 - ai_weight

        # -------------------------
        # Blend intents
        # -------------------------
        blended_intent = {}

        for key in set(ai_intent.keys()).union(human_input.keys()):
            ai_val = ai_intent.get(key)
            human_val = human_input.get(key)

            if isinstance(ai_val, (int, float)) and isinstance(human_val, (int, float)):
                blended_intent[key] = (
                    ai_weight * ai_val + human_weight * human_val
                )
            else:
                # Non-numeric: prefer human when override is strong
                blended_intent[key] = (
                    human_val if self._override_strength > 0.5 else ai_val
                )

        return {
            "blended_intent": blended_intent,
            "override_strength": self._override_strength,
            "ai_weight": ai_weight,
            "human_weight": human_weight,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset human override state.
        """
        self._override_strength = 0.0
        self._last_input_time = time.time()


