# ==============================================================================
# CHUNK 101 A 01 — MULTI-AGENT AUTHORITY RESOLUTION (AI ↔ HUMAN ↔ SAFETY)
# ==============================================================================
#
# Purpose:
#   Resolve control authority between AI Director, human operator,
#   and safety systems in a deterministic, context-aware manner —
#   eliminating ambiguity, oscillation, and unsafe contention.
#
# Core principle:
#   Authority is negotiated continuously, not seized.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class MultiAgentAuthorityResolution:
    """
    Multi-agent authority resolution engine.
    Arbitrates final control authority across AI, human, and
    safety subsystems using confidence, urgency, and stability.
    """

    __slots__ = (
        "_last_resolution",
        "_authority_memory",
    )

    def __init__(self):
        self._last_resolution: float = 0.0
        self._authority_memory: Dict[str, float] = {
            "ai": 0.5,
            "human": 0.3,
            "safety": 0.2,
        }


    # --------------------------------------------------------------------------
    # Authority resolution
    # --------------------------------------------------------------------------

    def resolve(
        self,
        ai_signal: Dict[str, Any],
        human_signal: Dict[str, Any],
        safety_signal: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Resolve final authority weights.
        """
        now = time.time()

        # -------------------------
        # Extract pressures
        # -------------------------
        ai_conf = float(np.clip(ai_signal.get("confidence", 0.5), 0.0, 1.0))
        human_intent = float(np.clip(human_signal.get("intent_strength", 0.0), 0.0, 1.0))
        safety_urgency = float(np.clip(safety_signal.get("urgency", 0.0), 0.0, 1.0))

        # -------------------------
        # Raw authority proposal
        # -------------------------
        proposal = {
            "ai": ai_conf * (1.0 - safety_urgency),
            "human": human_intent * (1.0 - safety_urgency),
            "safety": safety_urgency,
        }

        total = sum(proposal.values()) + 1e-6
        for k in proposal:
            proposal[k] /= total

        # -------------------------
        # Temporal smoothing
        # -------------------------
        for k in self._authority_memory:
            self._authority_memory[k] = float(np.clip(
                0.8 * self._authority_memory[k] + 0.2 * proposal.get(k, 0.0),
                0.0,
                1.0,
            ))

        # Renormalize after smoothing
        norm = sum(self._authority_memory.values()) + 1e-6
        for k in self._authority_memory:
            self._authority_memory[k] /= norm

        self._last_resolution = now

        return {
            "authority_weights": dict(self._authority_memory),
            "dominant": max(self._authority_memory, key=self._authority_memory.get),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset authority resolution memory.
        """
        self._authority_memory = {
            "ai": 0.5,
            "human": 0.3,
            "safety": 0.2,
        }
        self._last_resolution = time.time()


