# ==============================================================================
# CHUNK 102 A 01 — CLOUD ↔ ONBOARD AUTHORITY HANDOFF
# ==============================================================================
#
# Purpose:
#   Coordinate authority handoff between cloud advisory systems
#   and onboard Director logic without violating latency, safety,
#   or autonomy constraints.
#
# Core principle:
#   The cloud advises — the drone decides.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CloudOnboardAuthorityHandoff:
    """
    Cloud ↔ onboard authority handoff coordinator.
    Manages when cloud guidance may influence onboard decisions,
    and how that influence is bounded, delayed, or ignored.
    """

    __slots__ = (
        "_last_cloud_contact",
        "_cloud_trust",
    )

    def __init__(self):
        self._last_cloud_contact: float = 0.0
        self._cloud_trust: float = 0.5


    # --------------------------------------------------------------------------
    # Authority handoff logic
    # --------------------------------------------------------------------------

    def evaluate(
        self,
        cloud_signal: Dict[str, Any],
        onboard_state: Dict[str, Any],
        safety_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Evaluate cloud influence on onboard authority.
        """
        now = time.time()
        self._last_cloud_contact = now

        cloud_confidence = float(np.clip(
            cloud_signal.get("confidence", 0.5),
            0.0,
            1.0,
        ))

        latency = float(np.clip(
            cloud_signal.get("latency", 0.0),
            0.0,
            5.0,
        ))

        safety_factor = float(np.clip(
            safety_state.get("safety_factor", 1.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Trust update
        # -------------------------
        trust_delta = cloud_confidence * (1.0 - latency * 0.2)
        self._cloud_trust = float(np.clip(
            0.9 * self._cloud_trust + 0.1 * trust_delta,
            0.0,
            1.0,
        ))

        # -------------------------
        # Influence gating
        # -------------------------
        influence = self._cloud_trust * safety_factor
        influence *= float(np.clip(1.0 - latency * 0.15, 0.0, 1.0))

        return {
            "cloud_influence": influence,
            "cloud_trust": self._cloud_trust,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cloud authority handoff state.
        """
        self._last_cloud_contact = time.time()
        self._cloud_trust = 0.5


