# ==============================================================================
# ==============================================================================
# CHUNK 103 A 01 — PERSISTENT MISSION MEMORY (CROSS-FLIGHT LEARNING)
# ==============================================================================
#
# Purpose:
#   Accumulate mission-level experience across flights to
#   refine Director intuition, planning confidence, and
#   recovery strategies — without contaminating real-time control.
#
# Core principle:
#   Memory informs intent; it never drives actuators directly.
#
# ==============================================================================

from typing import Dict, Any, List
import numpy as np
import time


class PersistentMissionMemory:
    """
    Persistent mission memory engine.
    Stores compact, outcome-focused summaries of past missions
    and distills them into bias adjustments for future planning.
    """

    __slots__ = (
        "_experience_buffer",
        "_max_entries",
    )

    def __init__(self, max_entries: int = 128):
        self._experience_buffer: List[Dict[str, Any]] = []
        self._max_entries: int = max_entries


    # --------------------------------------------------------------------------
    # Memory ingestion
    # --------------------------------------------------------------------------

    def record(
        self,
        mission_summary: Dict[str, Any],
        execution_outcome: Dict[str, Any],
        safety_outcome: Dict[str, Any],
    ) -> None:
        """
        Record a completed mission into persistent memory.
        """
        entry = {
            "timestamp": time.time(),
            "mission_type": mission_summary.get("type"),
            "completion": execution_outcome.get("completion_ratio", 0.0),
            "aborted": execution_outcome.get("aborted", False),
            "safety_margin": safety_outcome.get("safety_factor", 1.0),
        }

        self._experience_buffer.append(entry)

        if len(self._experience_buffer) > self._max_entries:
            self._experience_buffer.pop(0)


    # --------------------------------------------------------------------------
    # Bias synthesis
    # --------------------------------------------------------------------------

    def synthesize_bias(self) -> Dict[str, float]:
        """
        Synthesize planning biases from accumulated experience.
        """
        if not self._experience_buffer:
            return {}

        completions = np.array([e["completion"] for e in self._experience_buffer])
        safety = np.array([e["safety_margin"] for e in self._experience_buffer])

        avg_completion = float(np.mean(completions))
        avg_safety = float(np.mean(safety))

        return {
            "confidence_bias": float(np.clip(avg_completion * 0.5, 0.0, 0.5)),
            "risk_aversion_bias": float(np.clip(1.0 - avg_safety, 0.0, 0.5)),
        }


    def reset(self) -> None:
        """
        Clear persistent mission memory.
        """
        self._experience_buffer.clear()


