# ==============================================================================
# CHUNK 104 A 01 — DISTRIBUTED SYSTEM HEARTBEAT & LIVENESS
# ==============================================================================
#
# Purpose:
#   Maintain continuous liveness awareness across all system nodes
#   (Drone, App, Cloud, Peripheral Controllers) to detect degradation,
#   partitioning, or failure — without triggering spurious aborts.
#
# Core principle:
#   Silence is a signal, but not every pause is a failure.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class DistributedHeartbeatLiveness:
    """
    Distributed heartbeat & liveness monitor.
    Tracks heartbeat freshness, jitter tolerance, and degradation
    patterns across multiple system nodes.
    """

    __slots__ = (
        "_nodes",
        "_last_global_update",
    )

    def __init__(self):
        self._nodes: Dict[str, Dict[str, float]] = {}
        self._last_global_update: float = 0.0


    # --------------------------------------------------------------------------
    # Heartbeat ingestion
    # --------------------------------------------------------------------------

    def update(
        self,
        node_id: str,
        timestamp: float | None = None,
        expected_interval: float = 1.0,
    ) -> None:
        """
        Register a heartbeat from a system node.
        """
        now = time.time() if timestamp is None else timestamp

        state = self._nodes.get(node_id)
        if state is None:
            self._nodes[node_id] = {
                "last_seen": now,
                "expected_interval": expected_interval,
                "jitter": 0.0,
            }
            return

        dt = now - state["last_seen"]
        jitter = abs(dt - state["expected_interval"])

        state["jitter"] = float(np.clip(
            0.8 * state["jitter"] + 0.2 * jitter,
            0.0,
            5.0,
        ))
        state["last_seen"] = now
        state["expected_interval"] = expected_interval


    # --------------------------------------------------------------------------
    # Liveness evaluation
    # --------------------------------------------------------------------------

    def evaluate(self) -> Dict[str, Any]:
        """
        Evaluate liveness state of all nodes.
        """
        now = time.time()
        self._last_global_update = now

        report: Dict[str, Any] = {}
        overall_health = 1.0

        for node_id, state in self._nodes.items():
            silence = now - state["last_seen"]
            tolerance = state["expected_interval"] * (1.5 + state["jitter"])

            if silence <= tolerance:
                status = "alive"
                health = 1.0
            elif silence <= tolerance * 2.0:
                status = "degraded"
                health = 0.6
            else:
                status = "lost"
                health = 0.0

            report[node_id] = {
                "status": status,
                "health": health,
                "silence": silence,
            }

            overall_health *= health

        return {
            "nodes": report,
            "overall_health": overall_health,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset heartbeat tracking.
        """
        self._nodes.clear()
        self._last_global_update = time.time()


