# ==============================================================================
# ==============================================================================
# CHUNK 105 A 01 — APP ↔ DRONE SESSION INTEGRITY LAYER
# ==============================================================================
#
# Purpose:
#   Establish and maintain a cryptographically bound, temporally
#   coherent session between the mobile app and the drone —
#   preventing ghost commands, stale control, or session hijack.
#
# Core principle:
#   Control exists only inside a living session.
#
# ==============================================================================

from typing import Dict, Any
import time
import hashlib
import secrets
import numpy as np


class AppDroneSessionIntegrity:
    """
    App ↔ Drone session integrity layer.
    Maintains session identity, freshness, and continuity
    for all app-originated commands.
    """

    __slots__ = (
        "_session_id",
        "_session_key",
        "_last_heartbeat",
        "_ttl",
    )

    def __init__(self, ttl: float = 5.0):
        self._session_id: str | None = None
        self._session_key: bytes | None = None
        self._last_heartbeat: float = 0.0
        self._ttl: float = ttl


    # --------------------------------------------------------------------------
    # Session lifecycle
    # --------------------------------------------------------------------------

    def establish(self, app_id: str) -> Dict[str, Any]:
        """
        Establish a new control session.
        """
        now = time.time()

        self._session_id = secrets.token_hex(8)
        self._session_key = secrets.token_bytes(32)
        self._last_heartbeat = now

        digest = hashlib.sha256(
            (app_id + self._session_id).encode("utf-8")
        ).hexdigest()

        return {
            "session_id": self._session_id,
            "session_digest": digest,
            "expires_in": self._ttl,
            "timestamp": now,
        }


    # --------------------------------------------------------------------------
    # Session validation
    # --------------------------------------------------------------------------

    def validate(
        self,
        session_id: str,
        signature: str,
    ) -> bool:
        """
        Validate an incoming command session.
        """
        now = time.time()

        if self._session_id is None or self._session_key is None:
            return False

        if session_id != self._session_id:
            return False

        if now - self._last_heartbeat > self._ttl:
            return False

        expected = hashlib.sha256(
            self._session_key + session_id.encode("utf-8")
        ).hexdigest()

        return secrets.compare_digest(signature, expected)


    # --------------------------------------------------------------------------
    # Heartbeat maintenance
    # --------------------------------------------------------------------------

    def heartbeat(self) -> None:
        """
        Refresh session heartbeat.
        """
        self._last_heartbeat = time.time()


    def expired(self) -> bool:
        """
        Check if session expired.
        """
        if self._session_id is None:
            return True
        return (time.time() - self._last_heartbeat) > self._ttl


    def reset(self) -> None:
        """
        Terminate session immediately.
        """
        self._session_id = None
        self._session_key = None
        self._last_heartbeat = 0.0


