# END OF CHUNK 105 A 01
# ==============================================================================
# ==============================================================================
# CHUNK 106 A 01 — SECURE COMMAND CHANNEL & REPLAY PROTECTION
# ==============================================================================
#
# Purpose:
#   Secure all control commands against replay, reordering,
#   injection, and delayed execution — even over lossy links.
#
# Core principle:
#   A valid command is authenticated, ordered, and timely.
#
# ==============================================================================

from typing import Dict, Any
import time
import hmac
import hashlib
import secrets


class SecureCommandChannel:
    """
    Secure command channel with replay protection.
    Provides authenticated, sequence-bound command envelopes
    suitable for unreliable transport layers (UDP / radio).
    """

    __slots__ = (
        "_shared_key",
        "_tx_seq",
        "_rx_seq",
        "_max_skew",
    )

    def __init__(self, shared_key: bytes, max_skew: float = 1.5):
        self._shared_key: bytes = shared_key
        self._tx_seq: int = 0
        self._rx_seq: int = 0
        self._max_skew: float = max_skew


    # --------------------------------------------------------------------------
    # Command sealing (sender)
    # --------------------------------------------------------------------------

    def seal(self, command: Dict[str, Any]) -> Dict[str, Any]:
        """
        Seal a command into a secure envelope.
        """
        now = time.time()
        self._tx_seq += 1

        envelope = {
            "seq": self._tx_seq,
            "ts": now,
            "cmd": command,
        }

        mac = hmac.new(
            self._shared_key,
            repr(envelope).encode("utf-8"),
            hashlib.sha256,
        ).hexdigest()

        envelope["mac"] = mac
        return envelope


    # --------------------------------------------------------------------------
    # Command verification (receiver)
    # --------------------------------------------------------------------------

    def verify(self, envelope: Dict[str, Any]) -> Dict[str, Any]:
        """
        Verify and unwrap a secure command envelope.
        """
        now = time.time()

        seq = int(envelope.get("seq", 0))
        ts = float(envelope.get("ts", 0.0))
        mac = envelope.get("mac", "")
        cmd = envelope.get("cmd")

        # Time validity
        if abs(now - ts) > self._max_skew:
            return {"valid": False, "reason": "timestamp_skew"}

        # Sequence ordering
        if seq <= self._rx_seq:
            return {"valid": False, "reason": "replay_or_reorder"}

        # MAC verification
        expected = hmac.new(
            self._shared_key,
            repr({"seq": seq, "ts": ts, "cmd": cmd}).encode("utf-8"),
            hashlib.sha256,
        ).hexdigest()

        if not secrets.compare_digest(mac, expected):
            return {"valid": False, "reason": "bad_mac"}

        # Accept
        self._rx_seq = seq
        return {
            "valid": True,
            "command": cmd,
            "seq": seq,
            "timestamp": ts,
        }


    def reset(self) -> None:
        """
        Reset channel sequence state.
        """
        self._tx_seq = 0
        self._rx_seq = 0


