# ==============================================================================
# CHUNK 107 A 01 — TELEMETRY INTEGRITY & TAMPER DETECTION
# ==============================================================================
#
# Purpose:
#   Detect telemetry corruption, tampering, spoofing, or silent
#   degradation before poisoned data influences control, AI,
#   or safety logic.
#
# Core principle:
#   Trust telemetry only after it proves consistency over time.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time
import hashlib
import secrets


class TelemetryIntegrityMonitor:
    """
    Telemetry integrity & tamper detection engine.
    Verifies telemetry freshness, continuity, entropy,
    and signature stability to detect manipulation.
    """

    __slots__ = (
        "_last_hash",
        "_last_timestamp",
        "_entropy_memory",
    )

    def __init__(self):
        self._last_hash: str | None = None
        self._last_timestamp: float = 0.0
        self._entropy_memory: float = 0.0


    # --------------------------------------------------------------------------
    # Telemetry evaluation
    # --------------------------------------------------------------------------

    def evaluate(self, telemetry: Dict[str, Any]) -> Dict[str, Any]:
        """
        Evaluate telemetry integrity.
        """
        now = time.time()

        payload = repr(sorted(telemetry.items())).encode("utf-8")
        current_hash = hashlib.sha256(payload).hexdigest()

        # -------------------------
        # Freshness
        # -------------------------
        ts = float(telemetry.get("timestamp", now))
        freshness = float(np.clip(1.0 - abs(now - ts), 0.0, 1.0))

        # -------------------------
        # Continuity
        # -------------------------
        continuity = 1.0
        if self._last_hash is not None:
            continuity = 0.0 if current_hash == self._last_hash else 1.0

        self._last_hash = current_hash
        self._last_timestamp = now

        # -------------------------
        # Entropy consistency
        # -------------------------
        values = np.array(
            [v for v in telemetry.values() if isinstance(v, (int, float))],
            dtype=float,
        )

        if values.size > 1:
            entropy = float(np.std(values))
        else:
            entropy = 0.0

        self._entropy_memory = float(np.clip(
            0.9 * self._entropy_memory + 0.1 * entropy,
            0.0,
            10.0,
        ))

        # -------------------------
        # Integrity score
        # -------------------------
        integrity = float(np.clip(
            0.4 * freshness + 0.3 * continuity + 0.3 * (1.0 - abs(entropy - self._entropy_memory)),
            0.0,
            1.0,
        ))

        return {
            "integrity": integrity,
            "freshness": freshness,
            "continuity": continuity,
            "entropy": entropy,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset telemetry integrity state.
        """
        self._last_hash = None
        self._last_timestamp = 0.0
        self._entropy_memory = 0.0


