# END OF CHUNK 107 A 01
# ==============================================================================
# ==============================================================================
# CHUNK 108 A 01 — TIMEBASE SYNCHRONIZATION (APP ↔ DRONE ↔ CLOUD)
# ==============================================================================
#
# Purpose:
#   Maintain a coherent, drift-resilient shared timebase across
#   app, drone, and cloud — enabling correct ordering of commands,
#   telemetry, logs, learning, and cinematic intent.
#
# Core principle:
#   Time is inferred collaboratively, not imposed.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class DistributedTimebase:
    """
    Distributed timebase synchronization engine.
    Infers a stable logical clock by fusing local time with
    peer observations, latency estimates, and drift smoothing.
    """

    __slots__ = (
        "_offset",
        "_drift",
        "_confidence",
        "_last_update",
    )

    def __init__(self):
        self._offset: float = 0.0
        self._drift: float = 0.0
        self._confidence: float = 0.5
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Time observation ingestion
    # --------------------------------------------------------------------------

    def observe(
        self,
        remote_ts: float,
        rtt: float,
    ) -> Dict[str, Any]:
        """
        Observe a remote timestamp with round-trip delay.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # Estimate one-way latency
        latency = max(rtt * 0.5, 0.0)

        # Proposed offset
        proposed_offset = (remote_ts + latency) - now

        # Drift estimation
        drift_estimate = (proposed_offset - self._offset) / dt

        # Smooth updates
        self._drift = float(np.clip(
            0.95 * self._drift + 0.05 * drift_estimate,
            -0.01,
            0.01,
        ))

        self._offset = float(np.clip(
            0.9 * self._offset + 0.1 * proposed_offset,
            -5.0,
            5.0,
        ))

        # Confidence increases with low RTT and stability
        stability = float(np.clip(1.0 - abs(drift_estimate), 0.0, 1.0))
        latency_quality = float(np.clip(1.0 - rtt, 0.0, 1.0))

        self._confidence = float(np.clip(
            0.8 * self._confidence + 0.2 * (0.6 * stability + 0.4 * latency_quality),
            0.0,
            1.0,
        ))

        return {
            "offset": self._offset,
            "drift": self._drift,
            "confidence": self._confidence,
            "timestamp": now,
        }


    # --------------------------------------------------------------------------
    # Logical time query
    # --------------------------------------------------------------------------

    def now(self) -> Dict[str, Any]:
        """
        Get current synchronized logical time.
        """
        local = time.time()
        logical = local + self._offset

        return {
            "logical_time": logical,
            "local_time": local,
            "confidence": self._confidence,
        }


    def reset(self) -> None:
        """
        Reset timebase synchronization.
        """
        self._offset = 0.0
        self._drift = 0.0
        self._confidence = 0.5
        self._last_update = time.time()


