# END OF CHUNK 108 A 01
# ==============================================================================
# ==============================================================================
# CHUNK 109 A 01 — BANDWIDTH-ADAPTIVE TELEMETRY THROTTLING
# ==============================================================================
#
# Purpose:
#   Dynamically adapt telemetry emission rates to available
#   bandwidth, motion intensity, and control criticality —
#   without starving safety, control, or learning.
#
# Core principle:
#   Telemetry priority follows consequence, not curiosity.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class AdaptiveTelemetryThrottler:
    """
    Bandwidth-adaptive telemetry throttler.
    Shapes telemetry rates based on link quality, maneuvering
    intensity, and subsystem criticality.
    """

    __slots__ = (
        "_base_rates",
        "_min_rates",
        "_max_rates",
        "_last_update",
    )

    def __init__(self):
        # Hz targets
        self._base_rates: Dict[str, float] = {
            "control": 20.0,
            "safety": 10.0,
            "nav": 5.0,
            "vision_meta": 5.0,
            "learning": 1.0,
        }
        self._min_rates: Dict[str, float] = {
            "control": 10.0,
            "safety": 5.0,
            "nav": 2.0,
            "vision_meta": 1.0,
            "learning": 0.2,
        }
        self._max_rates: Dict[str, float] = {
            "control": 40.0,
            "safety": 20.0,
            "nav": 10.0,
            "vision_meta": 10.0,
            "learning": 2.0,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Rate computation
    # --------------------------------------------------------------------------

    def compute(
        self,
        link_state: Dict[str, Any],
        motion_state: Dict[str, Any],
        safety_state: Dict[str, Any],
    ) -> Dict[str, float]:
        """
        Compute per-channel telemetry rates (Hz).
        """
        now = time.time()
        self._last_update = now

        bandwidth = float(np.clip(
            link_state.get("bandwidth_norm", 1.0),
            0.0,
            1.0,
        ))

        jitter = float(np.clip(
            link_state.get("jitter", 0.0),
            0.0,
            1.0,
        ))

        motion = float(np.clip(
            motion_state.get("intensity", 0.0),
            0.0,
            1.0,
        ))

        safety_urgency = float(np.clip(
            safety_state.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        # Global pressure factor
        pressure = float(np.clip(
            0.5 * bandwidth + 0.3 * (1.0 - jitter) + 0.2 * (1.0 - motion),
            0.0,
            1.0,
        ))

        rates: Dict[str, float] = {}

        for ch, base in self._base_rates.items():
            importance = 1.0
            if ch == "control":
                importance += 0.5 * motion + 0.5 * safety_urgency
            elif ch == "safety":
                importance += safety_urgency
            elif ch == "vision_meta":
                importance += 0.3 * motion
            elif ch == "learning":
                importance -= 0.5 * motion

            scaled = base * pressure * importance
            rates[ch] = float(np.clip(
                scaled,
                self._min_rates[ch],
                self._max_rates[ch],
            ))

        return rates


    def reset(self) -> None:
        """
        Reset throttler state.
        """
        self._last_update = time.time()


