# ==============================================================================
# CHUNK 111 A 01 — CLOUD-ASSISTED VISION INDEXING & RETRIEVAL
# ==============================================================================
#
# Purpose:
#   Extend onboard perception by selectively indexing visual
#   context to the cloud, enabling long-horizon recall,
#   semantic reinforcement, and cross-mission visual memory —
#   without inserting cloud latency into real-time control.
#
# Core principle:
#   The cloud remembers; the drone perceives.
#
# ==============================================================================

from typing import Dict, Any, List
import numpy as np
import time
import hashlib


class CloudVisionIndex:
    """
    Cloud-assisted vision indexing & retrieval engine.
    Builds compact semantic fingerprints of visual context,
    suitable for cloud indexing and later retrieval.
    """

    __slots__ = (
        "_last_index_time",
        "_index_interval",
        "_local_cache",
    )

    def __init__(self, index_interval: float = 2.0):
        self._last_index_time: float = 0.0
        self._index_interval: float = index_interval
        self._local_cache: List[Dict[str, Any]] = []


    # --------------------------------------------------------------------------
    # Indexing decision
    # --------------------------------------------------------------------------

    def should_index(self, vision_meta: Dict[str, Any]) -> bool:
        """
        Decide whether current visual context should be indexed.
        """
        now = time.time()

        if now - self._last_index_time < self._index_interval:
            return False

        saliency = float(np.clip(
            vision_meta.get("scene_saliency", 0.0),
            0.0,
            1.0,
        ))

        novelty = float(np.clip(
            vision_meta.get("novelty_score", 0.0),
            0.0,
            1.0,
        ))

        return (saliency + novelty) > 0.9


    # --------------------------------------------------------------------------
    # Index creation
    # --------------------------------------------------------------------------

    def create_index(
        self,
        vision_meta: Dict[str, Any],
        semantic_tags: List[str],
    ) -> Dict[str, Any]:
        """
        Create a compact cloud-indexable vision entry.
        """
        now = time.time()
        self._last_index_time = now

        fingerprint_payload = repr({
            "tags": semantic_tags,
            "luma": vision_meta.get("avg_luma"),
            "motion": vision_meta.get("optical_flow_energy"),
            "scene": vision_meta.get("scene_type"),
        }).encode("utf-8")

        fingerprint = hashlib.sha256(fingerprint_payload).hexdigest()

        entry = {
            "fingerprint": fingerprint,
            "semantic_tags": semantic_tags,
            "scene_type": vision_meta.get("scene_type"),
            "timestamp": now,
        }

        self._local_cache.append(entry)
        if len(self._local_cache) > 64:
            self._local_cache.pop(0)

        return entry


    # --------------------------------------------------------------------------
    # Retrieval assistance
    # --------------------------------------------------------------------------

    def retrieve_hint(
        self,
        fingerprint: str,
    ) -> Dict[str, Any] | None:
        """
        Retrieve locally cached hints for a given fingerprint.
        """
        for entry in reversed(self._local_cache):
            if entry["fingerprint"] == fingerprint:
                return entry
        return None


    def reset(self) -> None:
        """
        Reset vision index state.
        """
        self._last_index_time = 0.0
        self._local_cache.clear()


