# ==============================================================================
# CHUNK 112 A 01 — ONBOARD VISION FALLBACK & DEGRADATION MODES
# ==============================================================================
#
# Purpose:
#   Gracefully degrade onboard vision capability under partial
#   failure, maintaining situational awareness, safety margins,
#   and cinematic continuity instead of binary vision loss.
#
# Core principle:
#   Vision degrades in layers — perception never goes dark.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class VisionFallbackController:
    """
    Onboard vision fallback & degradation controller.
    Selects and blends fallback perception modes based on
    integrity, confidence, and operational context.
    """

    __slots__ = (
        "_mode",
        "_last_switch",
        "_confidence",
    )

    def __init__(self):
        self._mode: str = "full"
        self._last_switch: float = 0.0
        self._confidence: float = 1.0


    # --------------------------------------------------------------------------
    # Degradation evaluation
    # --------------------------------------------------------------------------

    def update(
        self,
        vision_integrity: float,
        nav_confidence: float,
        motion_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update fallback mode based on integrity signals.
        """
        now = time.time()

        motion = float(np.clip(
            motion_state.get("intensity", 0.0),
            0.0,
            1.0,
        ))

        # Confidence synthesis
        self._confidence = float(np.clip(
            0.6 * vision_integrity + 0.4 * nav_confidence,
            0.0,
            1.0,
        ))

        # Hysteresis to prevent oscillation
        can_switch = (now - self._last_switch) > 1.0

        # -------------------------
        # Mode selection
        # -------------------------
        new_mode = self._mode

        if self._confidence < 0.3 and can_switch:
            new_mode = "minimal"
        elif self._confidence < 0.6 and can_switch:
            new_mode = "reduced"
        elif self._confidence >= 0.8 and can_switch:
            new_mode = "full"

        if new_mode != self._mode:
            self._mode = new_mode
            self._last_switch = now

        # -------------------------
        # Mode characteristics
        # -------------------------
        if self._mode == "full":
            characteristics = {
                "vision_weight": 1.0,
                "nav_weight": 0.8,
                "cinematic_allowed": True,
            }
        elif self._mode == "reduced":
            characteristics = {
                "vision_weight": 0.6,
                "nav_weight": 1.0,
                "cinematic_allowed": motion < 0.5,
            }
        else:  # minimal
            characteristics = {
                "vision_weight": 0.3,
                "nav_weight": 1.0,
                "cinematic_allowed": False,
            }

        return {
            "mode": self._mode,
            "confidence": self._confidence,
            "characteristics": characteristics,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset vision fallback state.
        """
        self._mode = "full"
        self._last_switch = time.time()
        self._confidence = 1.0


