# ==============================================================================
# CHUNK 113 A 01 — DUAL-CAMERA FUSION & AUTHORITY ARBITRATION
# ==============================================================================
#
# Purpose:
#   Fuse internal AI camera and external gimbal camera streams
#   into a single coherent perceptual authority — preserving
#   cinematic intent while respecting latency, integrity,
#   and mission context.
#
# Core principle:
#   Cameras collaborate; they do not compete.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class DualCameraAuthority:
    """
    Dual-camera fusion & authority arbitration engine.
    Determines per-frame authority weights between
    internal AI camera and external gimbal camera.
    """

    __slots__ = (
        "_weights",
        "_last_update",
    )

    def __init__(self):
        self._weights: Dict[str, float] = {
            "internal": 0.6,
            "external": 0.4,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Authority arbitration
    # --------------------------------------------------------------------------

    def arbitrate(
        self,
        internal_state: Dict[str, Any],
        external_state: Dict[str, Any],
        mission_context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Arbitrate authority between cameras.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Signal extraction
        # -------------------------
        internal_integrity = float(np.clip(
            internal_state.get("integrity", 1.0),
            0.0,
            1.0,
        ))
        external_integrity = float(np.clip(
            external_state.get("integrity", 1.0),
            0.0,
            1.0,
        ))

        internal_latency = float(np.clip(
            internal_state.get("latency", 0.0),
            0.0,
            1.0,
        ))
        external_latency = float(np.clip(
            external_state.get("latency", 0.0),
            0.0,
            1.0,
        ))

        cinematic_priority = float(np.clip(
            mission_context.get("cinematic_priority", 0.5),
            0.0,
            1.0,
        ))

        # -------------------------
        # Raw authority proposal
        # -------------------------
        internal_score = (
            0.5 * internal_integrity
            + 0.3 * (1.0 - internal_latency)
            + 0.2 * cinematic_priority
        )

        external_score = (
            0.5 * external_integrity
            + 0.3 * (1.0 - external_latency)
            + 0.2 * (1.0 - cinematic_priority)
        )

        total = internal_score + external_score + 1e-6
        proposal = {
            "internal": internal_score / total,
            "external": external_score / total,
        }

        # -------------------------
        # Temporal smoothing
        # -------------------------
        for k in self._weights:
            self._weights[k] = float(np.clip(
                0.85 * self._weights[k] + 0.15 * proposal[k],
                0.0,
                1.0,
            ))

        # Renormalize
        norm = sum(self._weights.values()) + 1e-6
        for k in self._weights:
            self._weights[k] /= norm

        return {
            "camera_weights": dict(self._weights),
            "dominant_camera": max(self._weights, key=self._weights.get),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset camera authority state.
        """
        self._weights = {"internal": 0.6, "external": 0.4}
        self._last_update = time.time()


