# ==============================================================================
# CHUNK 114 A 01 — VISION-GUIDED SAFETY ENVELOPE SHAPING
# ==============================================================================
#
# Purpose:
#   Dynamically shape flight safety envelopes using real-time
#   visual perception — tightening margins in cluttered scenes
#   and relaxing them in open, well-understood environments.
#
# Core principle:
#   Safety margins should reflect what the drone actually sees.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class VisionGuidedSafetyEnvelope:
    """
    Vision-guided safety envelope shaping engine.
    Adjusts spatial, velocity, and acceleration limits
    based on visual density, motion uncertainty, and confidence.
    """

    __slots__ = (
        "_envelope_scale",
        "_last_update",
    )

    def __init__(self):
        self._envelope_scale: float = 1.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Envelope computation
    # --------------------------------------------------------------------------

    def update(
        self,
        vision_state: Dict[str, Any],
        nav_state: Dict[str, Any],
        safety_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update safety envelope scaling factors.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Vision-derived signals
        # -------------------------
        obstacle_density = float(np.clip(
            vision_state.get("obstacle_density", 0.0),
            0.0,
            1.0,
        ))

        depth_uncertainty = float(np.clip(
            vision_state.get("depth_uncertainty", 0.0),
            0.0,
            1.0,
        ))

        vision_confidence = float(np.clip(
            vision_state.get("confidence", 1.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Navigation & safety context
        # -------------------------
        speed = float(np.clip(
            nav_state.get("speed_norm", 0.0),
            0.0,
            1.0,
        ))

        safety_urgency = float(np.clip(
            safety_state.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Envelope pressure synthesis
        # -------------------------
        pressure = (
            0.35 * obstacle_density
            + 0.25 * depth_uncertainty
            + 0.20 * speed
            + 0.20 * safety_urgency
        )

        confidence_relief = 0.4 * vision_confidence

        target_scale = float(np.clip(
            1.0 - pressure + confidence_relief,
            0.3,
            1.2,
        ))

        # -------------------------
        # Temporal smoothing
        # -------------------------
        self._envelope_scale = float(np.clip(
            0.85 * self._envelope_scale + 0.15 * target_scale,
            0.3,
            1.2,
        ))

        return {
            "envelope_scale": self._envelope_scale,
            "pressure": pressure,
            "vision_confidence": vision_confidence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset safety envelope shaping.
        """
        self._envelope_scale = 1.0
        self._last_update = time.time()


