# ==============================================================================
# CHUNK 115 A 01 — CINEMATIC SUBJECT PERSISTENCE ACROSS OCCLUSION
# ==============================================================================
#
# Purpose:
#   Maintain cinematic subject continuity across partial or full
#   occlusion, exits, and re-entries — preserving narrative focus
#   and preventing abrupt subject abandonment.
#
# Core principle:
#   A subject does not cease to matter because it is unseen.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CinematicSubjectPersistence:
    """
    Cinematic subject persistence engine.
    Tracks subjects through occlusion using temporal memory,
    motion prediction, and confidence decay rather than hard loss.
    """

    __slots__ = (
        "_subject_state",
        "_last_seen",
        "_confidence",
    )

    def __init__(self):
        self._subject_state: Dict[str, Any] | None = None
        self._last_seen: float = 0.0
        self._confidence: float = 0.0


    # --------------------------------------------------------------------------
    # Subject update
    # --------------------------------------------------------------------------

    def update(
        self,
        detection: Dict[str, Any] | None,
        motion_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update subject persistence state.
        """
        now = time.time()

        if detection is not None:
            # Fresh detection reinforces subject
            self._subject_state = detection
            self._last_seen = now
            self._confidence = float(np.clip(
                self._confidence + 0.4,
                0.0,
                1.0,
            ))
        else:
            # Occlusion handling
            dt = now - self._last_seen
            decay = float(np.clip(dt * 0.15, 0.0, 1.0))
            self._confidence = float(np.clip(
                self._confidence - decay,
                0.0,
                1.0,
            ))

            # Predict motion if confidence remains
            if self._subject_state is not None and self._confidence > 0.2:
                velocity = motion_state.get("subject_velocity", (0.0, 0.0))
                if isinstance(velocity, (list, tuple)) and len(velocity) == 2:
                    self._subject_state = dict(self._subject_state)
                    self._subject_state["predicted_offset"] = (
        velocity[0] * dt,
        velocity[1] * dt,
                    )

        active = self._subject_state is not None and self._confidence > 0.1

        return {
            "active": active,
            "confidence": self._confidence,
            "subject": self._subject_state if active else None,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset subject persistence state.
        """
        self._subject_state = None
        self._last_seen = 0.0
        self._confidence = 0.0


