# ==============================================================================
# CHUNK 116 A 01 — INTENT-AWARE GIMBAL TRAJECTORY SYNTHESIS
# ==============================================================================
#
# Purpose:
#   Generate gimbal motion trajectories that reflect cinematic
#   intent, emotional momentum, and subject dynamics — producing
#   camera movement that feels directed rather than stabilized.
#
# Core principle:
#   Camera motion is narrative motion.
#
# ==============================================================================

from typing import Dict, Any, Tuple
import numpy as np
import time


class IntentAwareGimbalTrajectory:
    """
    Intent-aware gimbal trajectory synthesis engine.
    Translates cinematic intent, subject persistence, and
    emotional momentum into smooth, motivated gimbal motion.
    """

    __slots__ = (
        "_last_angles",
        "_last_update",
    )

    def __init__(self):
        self._last_angles: Tuple[float, float] = (0.0, 0.0)  # pitch, yaw
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Trajectory synthesis
    # --------------------------------------------------------------------------

    def synthesize(
        self,
        subject_state: Dict[str, Any] | None,
        emotional_state: Dict[str, Any],
        intent_state: Dict[str, Any],
        limits: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Synthesize next gimbal target angles.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Base target from subject
        # -------------------------
        if subject_state is not None:
            target_pitch = float(subject_state.get("pitch", 0.0))
            target_yaw = float(subject_state.get("yaw", 0.0))
        else:
            target_pitch, target_yaw = self._last_angles

        # -------------------------
        # Emotional modulation
        # -------------------------
        momentum = float(np.clip(
            emotional_state.get("emotional_momentum", 0.0),
            0.0,
            1.0,
        ))

        tension = float(np.clip(
            emotional_state.get("tension", 0.0),
            0.0,
            1.0,
        ))

        # High tension tightens motion; high momentum allows sweep
        responsiveness = 0.5 + 0.5 * momentum - 0.3 * tension
        responsiveness = float(np.clip(responsiveness, 0.2, 1.0))

        # -------------------------
        # Intent bias
        # -------------------------
        framing_bias = float(np.clip(
            intent_state.get("framing_bias", 0.0),
            -1.0,
            1.0,
        ))

        target_yaw += framing_bias * 5.0  # degrees bias

        # -------------------------
        # Smooth trajectory
        # -------------------------
        last_pitch, last_yaw = self._last_angles

        max_rate = float(np.clip(
            limits.get("max_rate_deg_s", 90.0),
            10.0,
            180.0,
        ))

        alpha = float(np.clip(responsiveness * dt * 3.0, 0.0, 1.0))

        next_pitch = last_pitch + alpha * (target_pitch - last_pitch)
        next_yaw = last_yaw + alpha * (target_yaw - last_yaw)

        # Rate limiting
        dp = np.clip(next_pitch - last_pitch, -max_rate * dt, max_rate * dt)
        dy = np.clip(next_yaw - last_yaw, -max_rate * dt, max_rate * dt)

        next_pitch = last_pitch + dp
        next_yaw = last_yaw + dy

        self._last_angles = (next_pitch, next_yaw)

        return {
            "pitch": next_pitch,
            "yaw": next_yaw,
            "responsiveness": responsiveness,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset gimbal trajectory state.
        """
        self._last_angles = (0.0, 0.0)
        self._last_update = time.time()


