# ==============================================================================
# CHUNK 117 A 01 — MULTI-TARGET CINEMATIC PRIORITIZATION
# ==============================================================================
#
# Purpose:
#   Dynamically prioritize multiple detected subjects based on
#   cinematic importance, narrative role, emotional contribution,
#   and temporal continuity — without visual thrashing.
#
# Core principle:
#   Cinema chooses who matters — and commits.
#
# ==============================================================================

from typing import Dict, Any, List
import numpy as np
import time


class MultiTargetCinematicPrioritizer:
    """
    Multi-target cinematic prioritization engine.
    Scores and selects subjects using emotional, narrative,
    and temporal coherence rather than raw confidence alone.
    """

    __slots__ = (
        "_active_id",
        "_commit_until",
    )

    def __init__(self):
        self._active_id: str | None = None
        self._commit_until: float = 0.0


    # --------------------------------------------------------------------------
    # Prioritization
    # --------------------------------------------------------------------------

    def select(
        self,
        subjects: List[Dict[str, Any]],
        emotional_state: Dict[str, Any],
        narrative_state: Dict[str, Any],
    ) -> Dict[str, Any] | None:
        """
        Select the most cinematically important subject.
        """
        if not subjects:
            self._active_id = None
            return None

        now = time.time()

        # -------------------------
        # Commitment enforcement
        # -------------------------
        if self._active_id is not None and now < self._commit_until:
            for s in subjects:
                if s.get("id") == self._active_id:
                    return s

        # -------------------------
        # Scoring
        # -------------------------
        momentum = float(np.clip(
            emotional_state.get("emotional_momentum", 0.0),
            0.0,
            1.0,
        ))

        phase_weight = float(np.clip(
            narrative_state.get("focus_weight", 0.5),
            0.0,
            1.0,
        ))

        best = None
        best_score = -1.0

        for s in subjects:
            confidence = float(np.clip(s.get("confidence", 0.0), 0.0, 1.0))
            continuity = float(np.clip(s.get("continuity", 0.0), 0.0, 1.0))
            role = float(np.clip(s.get("narrative_role", 0.5), 0.0, 1.0))

            score = (
                0.35 * confidence
                + 0.30 * continuity
                + 0.20 * role
                + 0.15 * momentum * phase_weight
            )

            if score > best_score:
                best = s
                best_score = score

        # -------------------------
        # Commit selection
        # -------------------------
        if best is not None:
            self._active_id = best.get("id")
            self._commit_until = now + float(
                np.clip(1.0 + 2.0 * momentum, 1.0, 3.0)
            )

        return best


    def reset(self) -> None:
        """
        Reset prioritization state.
        """
        self._active_id = None
        self._commit_until = 0.0


