# ==============================================================================
# CHUNK 118 A 01 — EMOTIONAL FRAMING BIAS CONTROLLER
# ==============================================================================
#
# Purpose:
#   Apply subtle, continuous framing biases driven by emotional
#   state — shaping composition in ways that feel intentional,
#   expressive, and cinematic rather than mechanically centered.
#
# Core principle:
#   Emotion bends the frame before it moves the camera.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class EmotionalFramingBias:
    """
    Emotional framing bias controller.
    Produces compositional offsets (rule-of-thirds drift,
    headroom bias, lateral imbalance) driven by emotional vectors.
    """

    __slots__ = (
        "_bias",
        "_last_update",
    )

    def __init__(self):
        self._bias: Dict[str, float] = {
            "x": 0.0,
            "y": 0.0,
            "headroom": 0.0,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Bias synthesis
    # --------------------------------------------------------------------------

    def update(
        self,
        emotional_state: Dict[str, Any],
        narrative_state: Dict[str, Any],
    ) -> Dict[str, float]:
        """
        Update emotional framing bias.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Emotional axes
        # -------------------------
        tension = float(np.clip(emotional_state.get("tension", 0.0), 0.0, 1.0))
        awe = float(np.clip(emotional_state.get("awe", 0.0), 0.0, 1.0))
        intimacy = float(np.clip(emotional_state.get("intimacy", 0.0), 0.0, 1.0))
        instability = float(np.clip(emotional_state.get("instability", 0.0), 0.0, 1.0))

        phase = float(np.clip(narrative_state.get("phase_norm", 0.5), 0.0, 1.0))

        # -------------------------
        # Target bias computation
        # -------------------------
        target_x = (
            0.25 * instability
            + 0.15 * tension
            - 0.20 * intimacy
        )

        target_y = (
            -0.20 * awe
            + 0.10 * tension
        )

        target_headroom = (
            0.30 * awe
            + 0.20 * phase
            - 0.25 * intimacy
        )

        # Clamp targets
        target_x = float(np.clip(target_x, -0.4, 0.4))
        target_y = float(np.clip(target_y, -0.3, 0.3))
        target_headroom = float(np.clip(target_headroom, -0.4, 0.4))

        # -------------------------
        # Temporal smoothing
        # -------------------------
        alpha = float(np.clip(dt * 1.5, 0.0, 1.0))

        self._bias["x"] += alpha * (target_x - self._bias["x"])
        self._bias["y"] += alpha * (target_y - self._bias["y"])
        self._bias["headroom"] += alpha * (target_headroom - self._bias["headroom"])

        return dict(self._bias)


    def reset(self) -> None:
        """
        Reset framing bias.
        """
        self._bias = {"x": 0.0, "y": 0.0, "headroom": 0.0}
        self._last_update = time.time()


