# ==============================================================================
# CHUNK 119 A 01 — SHOT-SCALE EVOLUTION ENGINE
# ==============================================================================
#
# Purpose:
#   Evolve shot scale (wide ↔ medium ↔ close) continuously over
#   time in response to emotional pressure, narrative phase,
#   subject distance, and motion — avoiding abrupt zoom events.
#
# Core principle:
#   Shot scale breathes with story and emotion.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class ShotScaleEvolution:
    """
    Shot-scale evolution engine.
    Produces a continuous shot-scale scalar rather than
    discrete zoom states, enabling organic transitions.
    """

    __slots__ = (
        "_scale",
        "_last_update",
    )

    def __init__(self):
        # 0.0 = ultra-wide, 1.0 = extreme close
        self._scale: float = 0.3
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Scale evolution
    # --------------------------------------------------------------------------

    def update(
        self,
        emotional_state: Dict[str, Any],
        narrative_state: Dict[str, Any],
        subject_state: Dict[str, Any] | None,
        motion_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update shot-scale scalar.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Emotional drivers
        # -------------------------
        intimacy = float(np.clip(emotional_state.get("intimacy", 0.0), 0.0, 1.0))
        awe = float(np.clip(emotional_state.get("awe", 0.0), 0.0, 1.0))
        tension = float(np.clip(emotional_state.get("tension", 0.0), 0.0, 1.0))

        phase = float(np.clip(narrative_state.get("phase_norm", 0.5), 0.0, 1.0))

        # -------------------------
        # Spatial context
        # -------------------------
        subject_distance = 0.5
        if subject_state is not None:
            subject_distance = float(np.clip(
                subject_state.get("distance_norm", 0.5),
                0.0,
                1.0,
            ))

        motion = float(np.clip(
            motion_state.get("intensity", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Target scale synthesis
        # -------------------------
        emotional_pull = (
            0.5 * intimacy
            - 0.4 * awe
            + 0.2 * tension
        )

        narrative_pull = 0.3 * phase

        spatial_pull = (
            0.5 * (1.0 - subject_distance)
            - 0.3 * motion
        )

        target_scale = (
            0.4 * self._scale
            + 0.6 * np.clip(
                0.5 + emotional_pull + narrative_pull + spatial_pull,
                0.0,
                1.0,
            )
        )

        # -------------------------
        # Temporal smoothing
        # -------------------------
        responsiveness = float(np.clip(
            0.5 + 0.5 * tension,
            0.2,
            1.0,
        ))

        alpha = float(np.clip(dt * responsiveness, 0.0, 1.0))
        self._scale += alpha * (target_scale - self._scale)
        self._scale = float(np.clip(self._scale, 0.0, 1.0))

        return {
            "shot_scale": self._scale,
            "target_scale": target_scale,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset shot-scale evolution.
        """
        self._scale = 0.3
        self._last_update = time.time()


