# ==============================================================================
# CHUNK 120 A 01 — CAMERA–FLIGHT INTENT COUPLING
# ==============================================================================
#
# Purpose:
#   Couple camera intent and flight intent into a single
#   coordinated decision layer — ensuring aircraft motion,
#   framing, and camera dynamics express the same narrative
#   and emotional objective.
#
# Core principle:
#   The camera does not ride the drone; the drone performs the shot.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CameraFlightIntentCoupler:
    """
    Camera–flight intent coupling engine.
    Aligns aircraft motion vectors with cinematic intent so that
    flight dynamics reinforce framing, scale, and emotional tone.
    """

    __slots__ = (
        "_coupling_strength",
        "_last_update",
    )

    def __init__(self):
        self._coupling_strength: float = 0.5
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Intent coupling
    # --------------------------------------------------------------------------

    def couple(
        self,
        camera_intent: Dict[str, Any],
        flight_state: Dict[str, Any],
        emotional_state: Dict[str, Any],
        safety_envelope: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Couple camera and flight intent into motion modifiers.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Emotional weighting
        # -------------------------
        momentum = float(np.clip(
            emotional_state.get("emotional_momentum", 0.0),
            0.0,
            1.0,
        ))

        tension = float(np.clip(
            emotional_state.get("tension", 0.0),
            0.0,
            1.0,
        ))

        envelope_scale = float(np.clip(
            safety_envelope.get("envelope_scale", 1.0),
            0.3,
            1.2,
        ))

        # -------------------------
        # Camera intent signals
        # -------------------------
        desired_scale = float(np.clip(
            camera_intent.get("shot_scale", 0.5),
            0.0,
            1.0,
        ))

        framing_bias_x = float(np.clip(
            camera_intent.get("framing_bias_x", 0.0),
            -1.0,
            1.0,
        ))

        # -------------------------
        # Base flight context
        # -------------------------
        speed_norm = float(np.clip(
            flight_state.get("speed_norm", 0.0),
            0.0,
            1.0,
        ))

        heading_rate = float(np.clip(
            flight_state.get("heading_rate", 0.0),
            -1.0,
            1.0,
        ))

        # -------------------------
        # Coupling synthesis
        # -------------------------
        target_strength = (
            0.3
            + 0.4 * momentum
            - 0.3 * tension
        )

        self._coupling_strength = float(np.clip(
            0.9 * self._coupling_strength + 0.1 * target_strength,
            0.2,
            0.9,
        ))

        # Forward/back motion modulates shot scale
        forward_bias = (
            (desired_scale - 0.5)
            * self._coupling_strength
            * envelope_scale
        )

        # Lateral motion supports framing bias
        lateral_bias = (
            framing_bias_x
            * self._coupling_strength
            * (1.0 - tension)
        )

        # Heading rate smoothing to avoid camera–flight conflict
        heading_damping = float(np.clip(
            1.0 - 0.5 * tension,
            0.4,
            1.0,
        ))

        coupled = {
            "forward_velocity_bias": forward_bias,
            "lateral_velocity_bias": lateral_bias,
            "heading_rate_scale": heading_damping,
            "coupling_strength": self._coupling_strength,
            "timestamp": now,
        }

        return coupled


    def reset(self) -> None:
        """
        Reset intent coupling state.
        """
        self._coupling_strength = 0.5
        self._last_update = time.time()


