# CHUNK 121 A 01 — EMOTIONAL BEAT BOUNDARY DETECTION
# ==============================================================================
#
# Purpose:
#   Detect emotional beat boundaries — moments where a scene
#   resolves, turns, escalates, or demands release — enabling
#   authored pacing rather than continuous modulation.
#
# Core principle:
#   Cinema is shaped by beats, not frames.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class EmotionalBeatDetector:
    """
    Emotional beat boundary detection engine.
    Identifies transitions in emotional trajectory using
    momentum curvature, tension inflection, and stability decay.
    """

    __slots__ = (
        "_last_momentum",
        "_last_tension",
        "_beat_cooldown_until",
    )

    def __init__(self):
        self._last_momentum: float = 0.0
        self._last_tension: float = 0.0
        self._beat_cooldown_until: float = 0.0


    # --------------------------------------------------------------------------
    # Beat detection
    # --------------------------------------------------------------------------

    def update(
        self,
        emotional_state: Dict[str, Any],
        stability_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Detect emotional beat boundaries.
        """
        now = time.time()

        momentum = float(np.clip(
            emotional_state.get("emotional_momentum", 0.0),
            0.0,
            1.0,
        ))

        tension = float(np.clip(
            emotional_state.get("tension", 0.0),
            0.0,
            1.0,
        ))

        stability = float(np.clip(
            stability_state.get("stability", 1.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Derivatives
        # -------------------------
        d_momentum = momentum - self._last_momentum
        d_tension = tension - self._last_tension

        self._last_momentum = momentum
        self._last_tension = tension

        # -------------------------
        # Beat likelihood
        # -------------------------
        curvature = abs(d_momentum) + abs(d_tension)
        instability = 1.0 - stability

        raw_likelihood = (
            0.5 * curvature
            + 0.3 * instability
            + 0.2 * abs(d_tension)
        )

        likelihood = float(np.clip(raw_likelihood, 0.0, 1.0))

        # -------------------------
        # Cooldown enforcement
        # -------------------------
        is_beat = False
        if now >= self._beat_cooldown_until and likelihood > 0.65:
            is_beat = True
            self._beat_cooldown_until = now + 1.5 + 2.0 * momentum

        return {
            "is_beat": is_beat,
            "likelihood": likelihood,
            "curvature": curvature,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset beat detection state.
        """
        self._last_momentum = 0.0
        self._last_tension = 0.0
        self._beat_cooldown_until = 0.0


