# CHUNK 122 A 01 — CINEMATIC AUTONOMY OVERRIDE LOGIC
# ==============================================================================
#
# Purpose:
#   Govern when cinematic autonomy yields to safety, human input,
#   or system degradation — and how it resumes — without abrupt
#   behavioral discontinuities or narrative collapse.
#
# Core principle:
#   Autonomy is negotiated, not revoked.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CinematicAutonomyOverride:
    """
    Cinematic autonomy override logic.
    Arbitrates control authority between AI director, human pilot,
    and safety systems using graded dominance rather than hard cuts.
    """

    __slots__ = (
        "_authority",
        "_last_transition",
    )

    def __init__(self):
        # 1.0 = full AI, 0.0 = full human/safety
        self._authority: float = 1.0
        self._last_transition: float = time.time()


    # --------------------------------------------------------------------------
    # Authority arbitration
    # --------------------------------------------------------------------------

    def update(
        self,
        human_input: Dict[str, Any],
        safety_state: Dict[str, Any],
        system_state: Dict[str, Any],
        emotional_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update autonomy authority level.
        """
        now = time.time()
        dt = max(now - self._last_transition, 1e-3)
        self._last_transition = now

        # -------------------------
        # External pressures
        # -------------------------
        human_pressure = float(np.clip(
            human_input.get("override_intent", 0.0),
            0.0,
            1.0,
        ))

        safety_pressure = float(np.clip(
            safety_state.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        degradation = float(np.clip(
            system_state.get("degradation", 0.0),
            0.0,
            1.0,
        ))

        tension = float(np.clip(
            emotional_state.get("tension", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Target authority synthesis
        # -------------------------
        pressure = (
            0.45 * safety_pressure
            + 0.35 * human_pressure
            + 0.20 * degradation
        )

        emotional_resistance = float(np.clip(
            0.3 * (1.0 - tension),
            0.0,
            0.3,
        ))

        target_authority = float(np.clip(
            1.0 - pressure + emotional_resistance,
            0.0,
            1.0,
        ))

        # -------------------------
        # Smooth authority transition
        # -------------------------
        responsiveness = float(np.clip(
            0.5 + 0.5 * safety_pressure,
            0.2,
            1.0,
        ))

        alpha = float(np.clip(dt * responsiveness, 0.0, 1.0))
        self._authority += alpha * (target_authority - self._authority)
        self._authority = float(np.clip(self._authority, 0.0, 1.0))

        return {
            "ai_authority": self._authority,
            "human_authority": 1.0 - self._authority,
            "pressure": pressure,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset autonomy override state.
        """
        self._authority = 1.0
        self._last_transition = time.time()


