# CHUNK 123 A 01 — HUMAN–AI CONTROL BLENDING
# ==============================================================================
#
# Purpose:
#   Blend human and AI control inputs continuously — allowing
#   partial guidance, correction, or takeover without breaking
#   safety, cinematic intent, or control stability.
#
# Core principle:
#   Control is a spectrum, not a switch.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class HumanAIControlBlender:
    """
    Human–AI control blending engine.
    Produces blended control commands by weighting human input
    and AI intent according to authority, confidence, and safety.
    """

    __slots__ = (
        "_last_output",
        "_last_update",
    )

    def __init__(self):
        self._last_output: Dict[str, float] = {
            "roll": 0.0,
            "pitch": 0.0,
            "yaw": 0.0,
            "throttle": 0.0,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Blending logic
    # --------------------------------------------------------------------------

    def blend(
        self,
        human_cmd: Dict[str, float],
        ai_cmd: Dict[str, float],
        authority_state: Dict[str, Any],
        safety_state: Dict[str, Any],
    ) -> Dict[str, float]:
        """
        Blend human and AI control commands.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        ai_weight = float(np.clip(
            authority_state.get("ai_authority", 0.5),
            0.0,
            1.0,
        ))

        safety_urgency = float(np.clip(
            safety_state.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        # Safety always dilutes manual aggression
        human_weight = (1.0 - ai_weight) * (1.0 - 0.7 * safety_urgency)

        blended: Dict[str, float] = {}

        for axis in ("roll", "pitch", "yaw", "throttle"):
            h = float(np.clip(human_cmd.get(axis, 0.0), -1.0, 1.0))
            a = float(np.clip(ai_cmd.get(axis, 0.0), -1.0, 1.0))

            raw = human_weight * h + ai_weight * a

            # Temporal smoothing to avoid twitch
            last = self._last_output.get(axis, 0.0)
            alpha = float(np.clip(dt * 5.0, 0.0, 1.0))
            blended[axis] = last + alpha * (raw - last)

        self._last_output = dict(blended)
        return blended


    def reset(self) -> None:
        """
        Reset blended control state.
        """
        self._last_output = {
            "roll": 0.0,
            "pitch": 0.0,
            "yaw": 0.0,
            "throttle": 0.0,
        }
        self._last_update = time.time()


