#   collaboration across time.
#
# Core principle:
#   The Director reasons in states, but transitions with memory.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class AIDirectorStateMachine:
    """
    AI Director state machine.
    Coordinates cinematic autonomy, safety dominance,
    and collaborative control using emotionally-aware
    state transitions with hysteresis.
    """

    __slots__ = (
        "_state",
        "_state_entered_at",
    )

    def __init__(self):
        self._state: str = "observe"
        self._state_entered_at: float = time.time()


    # --------------------------------------------------------------------------
    # State update
    # --------------------------------------------------------------------------

    def update(
        self,
        emotional_state: Dict[str, Any],
        safety_state: Dict[str, Any],
        authority_state: Dict[str, Any],
        mission_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update director state.
        """
        now = time.time()
        elapsed = now - self._state_entered_at

        tension = float(np.clip(emotional_state.get("tension", 0.0), 0.0, 1.0))
        momentum = float(np.clip(emotional_state.get("emotional_momentum", 0.0), 0.0, 1.0))

        safety_urgency = float(np.clip(safety_state.get("urgency", 0.0), 0.0, 1.0))
        ai_authority = float(np.clip(authority_state.get("ai_authority", 1.0), 0.0, 1.0))

        mission_phase = mission_state.get("phase", "active")

        next_state = self._state

        # -------------------------
        # State logic
        # -------------------------
        if safety_urgency > 0.7:
            next_state = "safety_override"

        elif ai_authority < 0.3:
            next_state = "human_led"

        elif mission_phase == "complete":
            next_state = "resolve"

        elif tension > 0.6 and momentum > 0.6:
            next_state = "direct"

        elif momentum < 0.2 and elapsed > 2.0:
            next_state = "observe"

        # -------------------------
        # Transition commit
        # -------------------------
        if next_state != self._state:
            self._state = next_state
            self._state_entered_at = now

        return {
            "director_state": self._state,
            "state_duration": now - self._state_entered_at,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset director state.
        """
        self._state = "observe"
        self._state_entered_at = time.time()


