from typing import Dict, Any, List
import numpy as np
import time


class MissionIntentResolver:
    """
    Mission-level intent resolution engine.
    Translates abstract goals into weighted operational intent
    vectors spanning safety, cinema, navigation, and autonomy.
    """

    __slots__ = (
        "_active_intents",
        "_last_update",
    )

    def __init__(self):
        self._active_intents: Dict[str, float] = {}
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Intent resolution
    # --------------------------------------------------------------------------

    def resolve(
        self,
        mission_cmd: Dict[str, Any],
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Resolve mission intent into weighted intent space.
        """
        now = time.time()
        self._last_update = now

        # -------------------------
        # Base intent extraction
        # -------------------------
        cinematic = float(np.clip(
            mission_cmd.get("cinematic_priority", 0.5),
            0.0,
            1.0,
        ))

        follow_target = 1.0 if mission_cmd.get("follow_target") else 0.0
        exploration = 1.0 if mission_cmd.get("explore") else 0.0
        inspection = 1.0 if mission_cmd.get("inspect") else 0.0

        safety_bias = float(np.clip(
            context.get("environment_risk", 0.5),
            0.0,
            1.0,
        ))

        # -------------------------
        # Normalize mission modes
        # -------------------------
        mode_sum = follow_target + exploration + inspection + 1e-6
        follow_target /= mode_sum
        exploration /= mode_sum
        inspection /= mode_sum

        # -------------------------
        # Intent vector synthesis
        # -------------------------
        self._active_intents = {
            "cinematic": cinematic,
            "tracking": follow_target,
            "exploration": exploration,
            "inspection": inspection,
            "safety": safety_bias,
        }

        return {
            "intent_vector": dict(self._active_intents),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset mission intent.
        """
        self._active_intents.clear()
        self._last_update = time.time()


