# ==============================================================================
# CHUNK 126 A 01 — CLOUD ↔ ONBOARD AUTHORITY ARBITRATION
# ==============================================================================
#
# Purpose:
#   Dynamically arbitrate decision authority between cloud AI
#   (LLMs, long-horizon reasoning) and onboard AI (real-time,
#   safety-critical control) — preserving intelligence without
#   sacrificing responsiveness or safety.
#
# Core principle:
#   Latency decides authority; trust decides influence.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class CloudOnboardAuthorityArbiter:
    """
    Cloud ↔ onboard authority arbitration engine.
    Produces graded authority weights for cloud-derived intent
    versus onboard decision-making, adapting continuously to
    latency, link quality, confidence, and safety context.
    """

    __slots__ = (
        "_cloud_weight",
        "_last_update",
    )

    def __init__(self):
        # 1.0 = cloud dominates intent, 0.0 = onboard only
        self._cloud_weight: float = 0.5
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Authority arbitration
    # --------------------------------------------------------------------------

    def update(
        self,
        cloud_state: Dict[str, Any],
        onboard_state: Dict[str, Any],
        link_state: Dict[str, Any],
        safety_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update cloud vs onboard authority weights.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Latency & link quality
        # -------------------------
        latency = float(np.clip(
            link_state.get("latency_norm", 0.0),
            0.0,
            1.0,
        ))

        packet_loss = float(np.clip(
            link_state.get("packet_loss", 0.0),
            0.0,
            1.0,
        ))

        link_quality = float(np.clip(
            1.0 - 0.6 * latency - 0.4 * packet_loss,
            0.0,
            1.0,
        ))

        # -------------------------
        # Confidence signals
        # -------------------------
        cloud_confidence = float(np.clip(
            cloud_state.get("confidence", 0.5),
            0.0,
            1.0,
        ))

        onboard_confidence = float(np.clip(
            onboard_state.get("confidence", 0.8),
            0.0,
            1.0,
        ))

        safety_urgency = float(np.clip(
            safety_state.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Target cloud authority
        # -------------------------
        cloud_desire = (
            0.5 * cloud_confidence
            + 0.3 * link_quality
            - 0.4 * safety_urgency
        )

        target_cloud_weight = float(np.clip(
            cloud_desire,
            0.0,
            1.0,
        ))

        # -------------------------
        # Smooth transition
        # -------------------------
        responsiveness = float(np.clip(
            0.6 + 0.4 * safety_urgency,
            0.3,
            1.0,
        ))

        alpha = float(np.clip(dt * responsiveness, 0.0, 1.0))
        self._cloud_weight += alpha * (target_cloud_weight - self._cloud_weight)
        self._cloud_weight = float(np.clip(self._cloud_weight, 0.0, 1.0))

        return {
            "cloud_authority": self._cloud_weight,
            "onboard_authority": 1.0 - self._cloud_weight,
            "link_quality": link_quality,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset authority arbitration state.
        """
        self._cloud_weight = 0.5
        self._last_update = time.time()


