# ==============================================================================

from typing import Dict, Any, List
import time


class NaturalLanguageGrounder:
    """
    Natural-language command grounding engine.
    Converts unstructured language into normalized intent tokens,
    preserving ambiguity, confidence, and narrative framing.
    """

    __slots__ = (
        "_dialog_context",
        "_last_update",
    )

    def __init__(self):
        self._dialog_context: List[Dict[str, Any]] = []
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Grounding logic
    # --------------------------------------------------------------------------

    def ground(
        self,
        utterance: str,
        llm_output: Dict[str, Any],
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Ground natural-language utterance into intent primitives.
        """
        now = time.time()
        self._last_update = now

        # -------------------------
        # Extract semantic frame
        # -------------------------
        frame = llm_output.get("semantic_frame", {})
        confidence = float(llm_output.get("confidence", 0.5))

        intent_type = frame.get("intent", "unknown")
        targets = frame.get("targets", [])
        style = frame.get("style", {})
        constraints = frame.get("constraints", {})

        # -------------------------
        # Normalize primitives
        # -------------------------
        primitives = {
            "intent_type": intent_type,
            "targets": list(targets),
            "style": dict(style),
            "constraints": dict(constraints),
            "confidence": confidence,
        }

        # -------------------------
        # Dialogue continuity
        # -------------------------
        self._dialog_context.append({
            "utterance": utterance,
            "primitives": primitives,
            "timestamp": now,
        })

        # Keep short-term episodic memory
        if len(self._dialog_context) > 5:
            self._dialog_context.pop(0)

        return {
            "grounded_intent": primitives,
            "dialog_context": list(self._dialog_context),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset dialogue grounding context.
        """
        self._dialog_context.clear()
        self._last_update = time.time()


