# ==============================================================================
# CHUNK 128 A 01 — LLM → INTENT GRAPH TRANSLATION
# ==============================================================================
#
# Purpose:
#   Translate grounded natural-language intent primitives into a
#   structured, relational intent graph capable of multi-step
#   reasoning, prioritization, and cinematic planning.
#
# Core principle:
#   Intent is a graph, not a queue.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import uuid


class IntentGraphTranslator:
    """
    Intent graph translation engine.
    Converts grounded intent primitives into a directed graph
    of intent nodes with semantic relationships.
    """

    __slots__ = (
        "_graph",
        "_last_update",
    )

    def __init__(self):
        self._graph: Dict[str, Dict[str, Any]] = {}
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Graph construction
    # --------------------------------------------------------------------------

    def translate(
        self,
        grounded_intent: Dict[str, Any],
        context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Translate grounded intent into intent graph nodes.
        """
        now = time.time()
        self._last_update = now

        node_id = str(uuid.uuid4())

        node = {
            "id": node_id,
            "intent_type": grounded_intent.get("intent_type"),
            "targets": grounded_intent.get("targets", []),
            "style": grounded_intent.get("style", {}),
            "constraints": grounded_intent.get("constraints", {}),
            "confidence": grounded_intent.get("confidence", 0.5),
            "created_at": now,
            "dependencies": [],
            "status": "pending",
        }

        # -------------------------
        # Relational inference
        # -------------------------
        for other_id, other in self._graph.items():
            if self._is_related(node, other):
                node["dependencies"].append(other_id)

        self._graph[node_id] = node

        return {
            "intent_node": dict(node),
            "graph_size": len(self._graph),
            "timestamp": now,
        }


    # --------------------------------------------------------------------------
    # Relationship heuristics
    # --------------------------------------------------------------------------

    def _is_related(self, a: Dict[str, Any], b: Dict[str, Any]) -> bool:
        """
        Determine whether two intent nodes are related.
        """
        if a["intent_type"] == b["intent_type"]:
            return True

        shared_targets = set(a.get("targets", [])) & set(b.get("targets", []))
        if shared_targets:
            return True

        return False


    def reset(self) -> None:
        """
        Reset intent graph.
        """
        self._graph.clear()
        self._last_update = time.time()


