# ==============================================================================
# CHUNK 129 A 01 — INTENT GRAPH TEMPORAL RESOLUTION
# ==============================================================================
#
# Purpose:
#   Resolve temporal relationships between intent graph nodes —
#   ordering, overlap, duration, and pacing — so the AI Director
#   understands WHEN actions should occur, not just WHAT.
#
# Core principle:
#   Timing is meaning.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class IntentGraphTemporalResolver:
    """
    Intent graph temporal resolution engine.
    Assigns temporal windows, priorities, and overlap permissions
    to intent graph nodes based on confidence, dependencies,
    emotional state, and cinematic pacing.
    """

    __slots__ = (
        "_schedule",
        "_last_update",
    )

    def __init__(self):
        self._schedule: Dict[str, Dict[str, Any]] = {}
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Temporal resolution
    # --------------------------------------------------------------------------

    def resolve(
        self,
        intent_graph: Dict[str, Dict[str, Any]],
        emotional_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Resolve temporal properties for intent graph nodes.
        """
        now = time.time()
        self._last_update = now

        momentum = float(np.clip(
            emotional_state.get("emotional_momentum", 0.0),
            0.0,
            1.0,
        ))

        tension = float(np.clip(
            emotional_state.get("tension", 0.0),
            0.0,
            1.0,
        ))

        for node_id, node in intent_graph.items():
            confidence = float(np.clip(node.get("confidence", 0.5), 0.0, 1.0))
            deps = node.get("dependencies", [])

            # -------------------------
            # Duration estimation
            # -------------------------
            base_duration = 1.0 + 3.0 * confidence
            emotional_stretch = 1.0 + 1.5 * momentum - 0.8 * tension
            duration = float(np.clip(
                base_duration * emotional_stretch,
                0.5,
                8.0,
            ))

            # -------------------------
            # Start time logic
            # -------------------------
            earliest_start = now
            if deps:
                dep_end_times = [
                    self._schedule[d]["end"]
                    for d in deps
                    if d in self._schedule
                ]
                if dep_end_times:
                    earliest_start = max(dep_end_times)

            # -------------------------
            # Overlap policy
            # -------------------------
            allow_overlap = confidence < 0.7 and tension < 0.5

            start = earliest_start
            end = start + duration

            self._schedule[node_id] = {
                "start": start,
                "end": end,
                "duration": duration,
                "allow_overlap": allow_overlap,
                "priority": confidence,
            }

        return {
            "temporal_schedule": dict(self._schedule),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset temporal schedule.
        """
        self._schedule.clear()
        self._last_update = time.time()


# ==============================================================================
# END OF CHUNK 129 A 01
# ==============================================================================
# ==============================================================================
# CHUNK 130 A 01 — INTENT SAFETY & FEASIBILITY PROJECTION
# ==============================================================================
#
# Purpose:
#   Project intent graph nodes into real-world feasibility and
#   safety space BEFORE execution — identifying constraints,
#   degradations, and fallback behaviors without collapsing
#   cinematic intent.
#
# Core principle:
#   A good director adapts the shot — not the rules.
#
# ==============================================================================

from typing import Dict, Any
import numpy as np
import time


class IntentSafetyFeasibilityProjector:
    """
    Intent safety & feasibility projection engine.
    Evaluates intent nodes against safety envelopes, physical
    constraints, and system limits, producing graded feasibility
    and recommended adaptations rather than hard rejection.
    """

    __slots__ = (
        "_last_update",
    )

    def __init__(self):
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Projection logic
    # --------------------------------------------------------------------------

    def project(
        self,
        intent_node: Dict[str, Any],
        environment_state: Dict[str, Any],
        platform_state: Dict[str, Any],
        safety_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Project intent into feasibility and safety space.
        """
        now = time.time()
        self._last_update = now

        # -------------------------
        # Constraint signals
        # -------------------------
        obstacle_density = float(np.clip(
            environment_state.get("obstacle_density", 0.0),
            0.0,
            1.0,
        ))

        wind_severity = float(np.clip(
            environment_state.get("wind_severity", 0.0),
            0.0,
            1.0,
        ))

        battery_margin = float(np.clip(
            platform_state.get("battery_margin", 1.0),
            0.0,
            1.0,
        ))

        thermal_margin = float(np.clip(
            platform_state.get("thermal_margin", 1.0),
            0.0,
            1.0,
        ))

        safety_urgency = float(np.clip(
            safety_state.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Feasibility synthesis
        # -------------------------
        environmental_cost = (
            0.5 * obstacle_density
            + 0.3 * wind_severity
        )

        platform_cost = (
            0.6 * (1.0 - battery_margin)
            + 0.4 * (1.0 - thermal_margin)
        )

        raw_feasibility = 1.0 - (
            0.45 * environmental_cost
            + 0.35 * platform_cost
            + 0.20 * safety_urgency
        )

        feasibility = float(np.clip(raw_feasibility, 0.0, 1.0))

        # -------------------------
        # Adaptation suggestions
        # -------------------------
        adaptations = {}

        if obstacle_density > 0.6:
            adaptations["trajectory"] = "widen_orbit"

        if wind_severity > 0.5:
            adaptations["motion"] = "reduce_lateral_motion"

        if battery_margin < 0.4:
            adaptations["duration"] = "shorten"

        if thermal_margin < 0.4:
            adaptations["processing"] = "lower_intensity"

        # -------------------------
        # Safety gating
        # -------------------------
        allow_execution = feasibility > 0.3

        return {
            "feasibility": feasibility,
            "allow_execution": allow_execution,
            "adaptations": adaptations,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset projection state.
        """
        self._last_update = time.time()


