# CHUNK 132 A 01 — CAMERA–FLIGHT MICRO-TASK BINDING
# ==============================================================================
#
# Purpose:
#   Bind cinematic micro-tasks to concrete, synchronized actions
#   across camera, gimbal, and flight subsystems — ensuring intent
#   manifests physically without fragmentation or conflict.
#
# Core principle:
#   No subsystem acts alone during a shot.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import numpy as np


class CameraFlightMicroTaskBinder:
    """
    Camera–flight micro-task binding engine.
    Converts semantic micro-tasks into synchronized actuator-level
    directives while preserving reversibility and authority blending.
    """

    __slots__ = (
        "_last_update",
    )

    def __init__(self):
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Binding logic
    # --------------------------------------------------------------------------

    def bind(
        self,
        micro_tasks: List[Dict[str, Any]],
        authority_state: Dict[str, Any],
        safety_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Bind micro-tasks to subsystem directives.
        """
        now = time.time()
        self._last_update = now

        directives: List[Dict[str, Any]] = []

        ai_authority = float(np.clip(
            authority_state.get("ai_authority", 1.0),
            0.0,
            1.0,
        ))

        safety_urgency = float(np.clip(
            safety_state.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Task binding
        # -------------------------
        for task in micro_tasks:
            name = task.get("task")
            params = task.get("parameters", {})
            phase = task.get("phase", "develop")

            directive = {
                "task": name,
                "phase": phase,
                "camera": {},
                "gimbal": {},
                "flight": {},
            }

            if name == "lock_subject":
                directive["camera"]["tracking"] = {
                    "targets": params.get("targets", []),
                    "authority": ai_authority,
                }
                directive["gimbal"]["stabilize"] = True

            elif name == "configure_camera":
                directive["camera"]["settings"] = params.get("shot_style", {})
                directive["camera"]["constraints"] = params.get("constraints", {})

            elif name == "execute_flight_pattern":
                directive["flight"]["pattern"] = params.get("pattern")
                directive["flight"]["duration"] = params.get("duration")
                directive["flight"]["adaptations"] = params.get("adaptations", {})
                directive["flight"]["authority"] = ai_authority * (1.0 - safety_urgency)

            elif name == "ease_out":
                directive["flight"]["decelerate"] = True
                directive["camera"]["settle"] = True

            directives.append(directive)

        return {
            "directives": directives,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset binding state.
        """
        self._last_update = time.time()


