# CHUNK 133 A 01 — EXECUTION WINDOW ORCHESTRATION
# ==============================================================================
#
# Purpose:
#   Orchestrate execution windows for bound cinematic directives,
#   determining when tasks begin, overlap, yield, or terminate so
#   the shot unfolds with authored temporal structure.
#
# Core principle:
#   Concurrency without choreography is noise.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import numpy as np


class ExecutionWindowOrchestrator:
    """
    Execution window orchestration engine.
    Aligns directive activation across camera, gimbal, and flight
    using temporal weighting, phase awareness, and emotional pacing.
    """

    __slots__ = (
        "_active_windows",
        "_last_update",
    )

    def __init__(self):
        self._active_windows: List[Dict[str, Any]] = []
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Orchestration logic
    # --------------------------------------------------------------------------

    def orchestrate(
        self,
        directives: List[Dict[str, Any]],
        emotional_state: Dict[str, Any],
        temporal_context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Orchestrate execution windows for directives.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        momentum = float(np.clip(
            emotional_state.get("emotional_momentum", 0.0),
            0.0,
            1.0,
        ))

        tension = float(np.clip(
            emotional_state.get("tension", 0.0),
            0.0,
            1.0,
        ))

        base_window = float(np.clip(
            temporal_context.get("base_window", 1.5),
            0.5,
            4.0,
        ))

        windows: List[Dict[str, Any]] = []

        # -------------------------
        # Window synthesis
        # -------------------------
        cursor = now
        for directive in directives:
            phase = directive.get("phase", "develop")

            phase_weight = {
                "setup": 0.8,
                "develop": 1.0,
                "climax": 1.4,
                "resolve": 1.1,
            }.get(phase, 1.0)

            duration = base_window * phase_weight
            duration *= (1.0 + 0.6 * momentum - 0.5 * tension)
            duration = float(np.clip(duration, 0.3, 6.0))

            window = {
                "directive": directive,
                "start": cursor,
                "end": cursor + duration,
                "phase": phase,
            }

            windows.append(window)
            cursor += duration * (0.7 if phase == "climax" else 0.9)

        self._active_windows = windows

        return {
            "execution_windows": list(windows),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset execution windows.
        """
        self._active_windows.clear()
        self._last_update = time.time()


