# CHUNK 134 A 01 — REAL-TIME TASK ADAPTATION LOOP
# ==============================================================================
#
# Purpose:
#   Continuously adapt active cinematic tasks in real time as
#   perception, emotion, safety, and human input evolve mid-shot —
#   without tearing pacing, intent, or control stability.
#
# Core principle:
#   A great shot listens while it moves.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import numpy as np


class RealTimeTaskAdaptationLoop:
    """
    Real-time cinematic task adaptation engine.
    Adjusts parameters of executing directives continuously
    using perceptual feedback, emotional trajectory, and safety
    pressure — without restarting tasks.
    """

    __slots__ = (
        "_last_update",
    )

    def __init__(self):
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Adaptation logic
    # --------------------------------------------------------------------------

    def adapt(
        self,
        active_windows: List[Dict[str, Any]],
        perceptual_state: Dict[str, Any],
        emotional_state: Dict[str, Any],
        safety_state: Dict[str, Any],
        human_input: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Adapt active execution windows in real time.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        motion_noise = float(np.clip(
            perceptual_state.get("motion_noise", 0.0),
            0.0,
            1.0,
        ))

        subject_confidence = float(np.clip(
            perceptual_state.get("subject_confidence", 1.0),
            0.0,
            1.0,
        ))

        momentum = float(np.clip(
            emotional_state.get("emotional_momentum", 0.0),
            0.0,
            1.0,
        ))

        safety_urgency = float(np.clip(
            safety_state.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        human_pressure = float(np.clip(
            human_input.get("override_intent", 0.0),
            0.0,
            1.0,
        ))

        adapted: List[Dict[str, Any]] = []

        for window in active_windows:
            directive = dict(window["directive"])

            # -------------------------
            # Camera adaptation
            # -------------------------
            if "camera" in directive:
                directive["camera"]["stability_gain"] = float(np.clip(
                    1.0 - 0.6 * motion_noise + 0.3 * momentum,
                    0.3,
                    1.5,
                ))

                directive["camera"]["tracking_confidence"] = subject_confidence

            # -------------------------
            # Flight adaptation
            # -------------------------
            if "flight" in directive:
                directive["flight"]["aggressiveness"] = float(np.clip(
                    1.0 - 0.7 * safety_urgency - 0.4 * human_pressure,
                    0.2,
                    1.0,
                ))

            adapted.append({
                **window,
                "directive": directive,
            })

        return {
            "adapted_windows": adapted,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset adaptation loop state.
        """
        self._last_update = time.time()


