# ==============================================================================
#
# Purpose:
#   Fuse visual, motion, depth, and confidence signals into a
#   continuously evolving perceptual state that the AI Director
#   can trust as a single source of situational truth.
#
# Core principle:
#   Perception is a stream, not a snapshot.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class ContinuousPerceptualFeedbackFusion:
    """
    Continuous perceptual feedback fusion engine.
    Aggregates multi-sensor perceptual inputs over time,
    weighting them by reliability and temporal stability.
    """

    __slots__ = (
        "_state",
        "_last_update",
    )

    def __init__(self):
        self._state: Dict[str, float] = {
            "motion_noise": 0.0,
            "depth_confidence": 1.0,
            "visual_confidence": 1.0,
            "subject_confidence": 1.0,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Fusion logic
    # --------------------------------------------------------------------------

    def fuse(
        self,
        vision_state: Dict[str, Any],
        motion_state: Dict[str, Any],
        depth_state: Dict[str, Any],
        tracking_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Fuse perceptual inputs into unified perceptual state.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Extract signals
        # -------------------------
        motion_noise = float(np.clip(
            motion_state.get("noise", 0.0),
            0.0,
            1.0,
        ))

        visual_conf = float(np.clip(
            vision_state.get("confidence", 1.0),
            0.0,
            1.0,
        ))

        depth_conf = float(np.clip(
            depth_state.get("confidence", 1.0),
            0.0,
            1.0,
        ))

        subject_conf = float(np.clip(
            tracking_state.get("subject_confidence", 1.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Reliability weighting
        # -------------------------
        reliability = {
            "motion_noise": 1.0 - motion_noise,
            "visual_confidence": visual_conf,
            "depth_confidence": depth_conf,
            "subject_confidence": subject_conf,
        }

        # -------------------------
        # Temporal fusion
        # -------------------------
        alpha = float(np.clip(dt * 3.0, 0.0, 1.0))

        for key, value in reliability.items():
            prev = self._state.get(key, value)
            self._state[key] = prev + alpha * (value - prev)

        return {
            "perceptual_state": dict(self._state),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset perceptual fusion state.
        """
        self._state = {
            "motion_noise": 0.0,
            "depth_confidence": 1.0,
            "visual_confidence": 1.0,
            "subject_confidence": 1.0,
        }
        self._last_update = time.time()


