#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class ShotIntegrityMonitor:
    """
    Shot integrity monitoring engine.
    Evaluates cinematic coherence as a continuous signal,
    enabling preemptive correction rather than reactive fixes.
    """

    __slots__ = (
        "_integrity",
        "_last_update",
    )

    def __init__(self):
        self._integrity: float = 1.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Integrity evaluation
    # --------------------------------------------------------------------------

    def evaluate(
        self,
        framing_state: Dict[str, Any],
        motion_state: Dict[str, Any],
        emotional_state: Dict[str, Any],
        perceptual_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Evaluate shot integrity.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Framing coherence
        # -------------------------
        framing_error = float(np.clip(
            framing_state.get("error", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Motion coherence
        # -------------------------
        motion_jitter = float(np.clip(
            motion_state.get("jitter", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Emotional coherence
        # -------------------------
        emotional_drift = float(np.clip(
            emotional_state.get("drift", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Perceptual confidence
        # -------------------------
        perceptual_conf = float(np.clip(
            perceptual_state.get("subject_confidence", 1.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Integrity synthesis
        # -------------------------
        raw_integrity = (
            1.0
            - 0.35 * framing_error
            - 0.30 * motion_jitter
            - 0.20 * emotional_drift
            + 0.15 * perceptual_conf
        )

        integrity = float(np.clip(raw_integrity, 0.0, 1.0))

        # Temporal smoothing
        alpha = float(np.clip(dt * 2.0, 0.0, 1.0))
        self._integrity += alpha * (integrity - self._integrity)
        self._integrity = float(np.clip(self._integrity, 0.0, 1.0))

        return {
            "shot_integrity": self._integrity,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset integrity monitor.
        """
        self._integrity = 1.0
        self._last_update = time.time()


