#   with the larger narrative arc — preventing emotionally correct
#   shots that are narratively wrong.
#
# Core principle:
#   A great moment means nothing if it breaks the story.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class NarrativeArcContinuityGuard:
    """
    Narrative arc continuity guard.
    Tracks evolving narrative phase and emotional trajectory,
    gently constraining local decisions to remain story-consistent.
    """

    __slots__ = (
        "_phase_confidence",
        "_last_update",
    )

    def __init__(self):
        self._phase_confidence: Dict[str, float] = {
            "setup": 0.25,
            "develop": 0.25,
            "climax": 0.25,
            "resolve": 0.25,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Continuity logic
    # --------------------------------------------------------------------------

    def evaluate(
        self,
        emotional_state: Dict[str, Any],
        shot_integrity: float,
        temporal_context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Evaluate narrative arc continuity and suggest constraints.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        momentum = float(np.clip(
            emotional_state.get("emotional_momentum", 0.0),
            0.0,
            1.0,
        ))

        tension = float(np.clip(
            emotional_state.get("tension", 0.0),
            0.0,
            1.0,
        ))

        progress = float(np.clip(
            temporal_context.get("narrative_progress", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Phase likelihood update
        # -------------------------
        likelihoods = {
            "setup": (1.0 - progress) * (1.0 - momentum),
            "develop": progress * (1.0 - tension),
            "climax": progress * tension,
            "resolve": momentum * (1.0 - tension),
        }

        alpha = float(np.clip(dt * 1.5, 0.0, 1.0))

        for phase, value in likelihoods.items():
            prev = self._phase_confidence.get(phase, value)
            self._phase_confidence[phase] = prev + alpha * (value - prev)

        # Normalize
        total = sum(self._phase_confidence.values()) + 1e-6
        for phase in self._phase_confidence:
            self._phase_confidence[phase] /= total

        dominant_phase = max(
            self._phase_confidence,
            key=self._phase_confidence.get,
        )

        # -------------------------
        # Continuity constraints
        # -------------------------
        constraints = {}

        if dominant_phase == "setup" and momentum > 0.6:
            constraints["limit_peak_intensity"] = True

        if dominant_phase == "climax" and shot_integrity < 0.5:
            constraints["stabilize_before_escalation"] = True

        if dominant_phase == "resolve" and tension > 0.4:
            constraints["encourage_release"] = True

        return {
            "dominant_phase": dominant_phase,
            "phase_confidence": dict(self._phase_confidence),
            "constraints": constraints,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset narrative arc guard.
        """
        self._phase_confidence = {
            "setup": 0.25,
            "develop": 0.25,
            "climax": 0.25,
            "resolve": 0.25,
        }
        self._last_update = time.time()


