# CHUNK 139 A 01 — CINEMATIC QUALITY SCORING LOOP
# ==============================================================================
#
# Purpose:
#   Continuously score cinematic decision quality — not frames —
#   producing learning-grade feedback on whether intent, execution,
#   emotion, and narrative alignment succeeded perceptually.
#
# Core principle:
#   Cinema quality lives in choices, not pixels.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class CinematicQualityScoringLoop:
    """
    Cinematic quality scoring engine.
    Evaluates decision-level quality using emotional payoff,
    shot integrity, narrative alignment, and perceptual confidence.
    """

    __slots__ = (
        "_quality_score",
        "_last_update",
    )

    def __init__(self):
        self._quality_score: float = 0.5
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Scoring logic
    # --------------------------------------------------------------------------

    def score(
        self,
        intent_node: Dict[str, Any],
        shot_integrity: float,
        narrative_state: Dict[str, Any],
        emotional_state: Dict[str, Any],
        perceptual_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Compute cinematic quality score.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Intent fulfillment
        # -------------------------
        intent_conf = float(np.clip(
            intent_node.get("confidence", 0.5),
            0.0,
            1.0,
        ))

        # -------------------------
        # Emotional payoff
        # -------------------------
        momentum = float(np.clip(
            emotional_state.get("emotional_momentum", 0.0),
            0.0,
            1.0,
        ))

        tension = float(np.clip(
            emotional_state.get("tension", 0.0),
            0.0,
            1.0,
        ))

        emotional_payoff = momentum * (1.0 - abs(tension - 0.5))

        # -------------------------
        # Narrative alignment
        # -------------------------
        narrative_alignment = float(np.clip(
            narrative_state.get("phase_confidence", {}).get(
                narrative_state.get("dominant_phase", "develop"), 0.5
            ),
            0.0,
            1.0,
        ))

        # -------------------------
        # Perceptual trust
        # -------------------------
        perceptual_trust = float(np.clip(
            perceptual_state.get("subject_confidence", 1.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Quality synthesis
        # -------------------------
        raw_score = (
            0.30 * intent_conf
            + 0.25 * shot_integrity
            + 0.20 * emotional_payoff
            + 0.15 * narrative_alignment
            + 0.10 * perceptual_trust
        )

        score = float(np.clip(raw_score, 0.0, 1.0))

        # Temporal smoothing
        alpha = float(np.clip(dt * 1.8, 0.0, 1.0))
        self._quality_score += alpha * (score - self._quality_score)
        self._quality_score = float(np.clip(self._quality_score, 0.0, 1.0))

        return {
            "cinematic_quality": self._quality_score,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset quality scoring.
        """
        self._quality_score = 0.5
        self._last_update = time.time()


