from typing import Dict, Any
import time
import numpy as np


class DirectorSelfCritiqueEngine:
    """
    Director-level self-critique engine.
    Generates introspective evaluations of decision quality,
    stylistic consistency, and emotional truthfulness to guide
    long-term improvement.
    """

    __slots__ = (
        "_critique_state",
        "_last_update",
    )

    def __init__(self):
        self._critique_state: Dict[str, float] = {
            "confidence": 0.5,
            "hesitation": 0.0,
            "overreach": 0.0,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Critique logic
    # --------------------------------------------------------------------------

    def critique(
        self,
        cinematic_quality: float,
        shot_integrity: float,
        narrative_alignment: float,
        emotional_payoff: float,
    ) -> Dict[str, Any]:
        """
        Generate self-critique assessment.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Critique dimensions
        # -------------------------
        confidence = float(np.clip(
            cinematic_quality * narrative_alignment,
            0.0,
            1.0,
        ))

        hesitation = float(np.clip(
            1.0 - emotional_payoff,
            0.0,
            1.0,
        ))

        overreach = float(np.clip(
            max(0.0, emotional_payoff - shot_integrity),
            0.0,
            1.0,
        ))

        # -------------------------
        # Temporal integration
        # -------------------------
        alpha = float(np.clip(dt * 1.2, 0.0, 1.0))

        self._critique_state["confidence"] += alpha * (
            confidence - self._critique_state["confidence"]
        )

        self._critique_state["hesitation"] += alpha * (
            hesitation - self._critique_state["hesitation"]
        )

        self._critique_state["overreach"] += alpha * (
            overreach - self._critique_state["overreach"]
        )

        # Clamp
        for k in self._critique_state:
            self._critique_state[k] = float(
                np.clip(self._critique_state[k], 0.0, 1.0)
            )

        return {
            "self_critique": dict(self._critique_state),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset self-critique state.
        """
        self._critique_state = {
            "confidence": 0.5,
            "hesitation": 0.0,
            "overreach": 0.0,
        }
        self._last_update = time.time()


