from typing import Dict, Any
import time
import numpy as np


class LongHorizonStyleConsistencyMemory:
    """
    Long-horizon style consistency memory.
    Accumulates slow-moving stylistic preferences and constraints
    derived from successful past decisions, forming an evolving
    directorial signature.
    """

    __slots__ = (
        "_style_state",
        "_last_update",
    )

    def __init__(self):
        self._style_state: Dict[str, float] = {
            "motion_restraint": 0.5,
            "contrast_bias": 0.5,
            "linger_tendency": 0.5,
            "risk_tolerance": 0.5,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Style accumulation
    # --------------------------------------------------------------------------

    def update(
        self,
        cinematic_quality: float,
        self_critique: Dict[str, float],
        narrative_phase: str,
    ) -> Dict[str, Any]:
        """
        Update long-horizon style memory.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        confidence = self_critique.get("confidence", 0.5)
        hesitation = self_critique.get("hesitation", 0.0)
        overreach = self_critique.get("overreach", 0.0)

        # -------------------------
        # Phase-weighted learning
        # -------------------------
        phase_weight = {
            "setup": 0.6,
            "develop": 1.0,
            "climax": 1.3,
            "resolve": 0.8,
        }.get(narrative_phase, 1.0)

        learning_rate = float(np.clip(
            dt * 0.15 * phase_weight,
            0.0,
            0.05,
        ))

        # -------------------------
        # Style dimension updates
        # -------------------------
        self._style_state["motion_restraint"] += learning_rate * (
            hesitation - self._style_state["motion_restraint"]
        )

        self._style_state["contrast_bias"] += learning_rate * (
            cinematic_quality - self._style_state["contrast_bias"]
        )

        self._style_state["linger_tendency"] += learning_rate * (
            confidence - self._style_state["linger_tendency"]
        )

        self._style_state["risk_tolerance"] += learning_rate * (
            (1.0 - overreach) - self._style_state["risk_tolerance"]
        )

        # Clamp
        for k in self._style_state:
            self._style_state[k] = float(
                np.clip(self._style_state[k], 0.0, 1.0)
            )

        return {
            "style_memory": dict(self._style_state),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset long-horizon style memory.
        """
        self._style_state = {
            "motion_restraint": 0.5,
            "contrast_bias": 0.5,
            "linger_tendency": 0.5,
            "risk_tolerance": 0.5,
        }
        self._last_update = time.time()


