from typing import Dict, Any, List
import time
import numpy as np


class CrossMissionLearningIntegrator:
    """
    Cross-mission learning integration engine.
    Aggregates mission-level outcomes into stable learning signals,
    balancing recency, diversity, and stylistic continuity.
    """

    __slots__ = (
        "_mission_buffer",
        "_last_update",
    )

    def __init__(self, buffer_size: int = 32):
        self._mission_buffer: List[Dict[str, Any]] = []
        self._buffer_size = int(max(8, buffer_size))
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Integration logic
    # --------------------------------------------------------------------------

    def integrate(
        self,
        mission_summary: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Integrate a completed mission into learning memory.
        """
        now = time.time()
        self._last_update = now

        # -------------------------
        # Append mission
        # -------------------------
        self._mission_buffer.append(mission_summary)

        if len(self._mission_buffer) > self._buffer_size:
            self._mission_buffer.pop(0)

        # -------------------------
        # Weighted aggregation
        # -------------------------
        qualities = np.array([
            m.get("cinematic_quality", 0.5)
            for m in self._mission_buffer
        ])

        styles = [
            m.get("style_memory", {})
            for m in self._mission_buffer
        ]

        avg_quality = float(np.mean(qualities)) if qualities.size else 0.5

        # -------------------------
        # Style consolidation
        # -------------------------
        consolidated_style: Dict[str, float] = {}

        if styles:
            keys = set().union(*styles)
            for k in keys:
                consolidated_style[k] = float(np.mean([
                    s.get(k, 0.5) for s in styles
                ]))

        return {
            "average_quality": avg_quality,
            "consolidated_style": consolidated_style,
            "mission_count": len(self._mission_buffer),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cross-mission integrator.
        """
        self._mission_buffer.clear()
        self._last_update = time.time()


