#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class CloudOnboardPreferenceSync:
    """
    Cloud ↔ onboard preference synchronization engine.
    Reconciles stylistic memory, risk tolerance, and pacing
    preferences across execution layers using trust-weighted
    fusion rather than authority replacement.
    """

    __slots__ = (
        "_last_sync",
        "_trust_state",
    )

    def __init__(self):
        self._last_sync: float = time.time()
        self._trust_state: Dict[str, float] = {
            "cloud": 0.5,
            "onboard": 0.5,
        }


    # --------------------------------------------------------------------------
    # Sync logic
    # --------------------------------------------------------------------------

    def sync(
        self,
        onboard_style: Dict[str, float],
        cloud_style: Dict[str, float],
        connectivity_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Synchronize onboard and cloud preferences.
        """
        now = time.time()
        latency = float(np.clip(
            connectivity_state.get("latency", 0.2),
            0.0,
            2.0,
        ))

        reliability = float(np.clip(
            connectivity_state.get("reliability", 1.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Trust adaptation
        # -------------------------
        cloud_trust = float(np.clip(
            reliability * (1.0 - latency / 2.0),
            0.1,
            0.9,
        ))

        onboard_trust = 1.0 - cloud_trust

        self._trust_state["cloud"] = cloud_trust
        self._trust_state["onboard"] = onboard_trust

        # -------------------------
        # Preference fusion
        # -------------------------
        fused_style: Dict[str, float] = {}
        keys = set(onboard_style) | set(cloud_style)

        for k in keys:
            o = onboard_style.get(k, 0.5)
            c = cloud_style.get(k, 0.5)
            fused_style[k] = float(
                onboard_trust * o + cloud_trust * c
            )

        self._last_sync = now

        return {
            "fused_style": fused_style,
            "trust_state": dict(self._trust_state),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset preference sync state.
        """
        self._trust_state = {
            "cloud": 0.5,
            "onboard": 0.5,
        }
        self._last_sync = time.time()


