from typing import Dict, Any
import time
import numpy as np


class UserDirectorStyleNegotiationLayer:
    """
    User–Director style negotiation engine.
    Fuses explicit user preferences with learned directorial style
    using confidence, consistency, and situational awareness.
    """

    __slots__ = (
        "_agreement_state",
        "_last_update",
    )

    def __init__(self):
        self._agreement_state: Dict[str, float] = {}
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Negotiation logic
    # --------------------------------------------------------------------------

    def negotiate(
        self,
        user_style: Dict[str, float],
        director_style: Dict[str, float],
        context_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Negotiate shared cinematic style.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        user_confidence = float(np.clip(
            context_state.get("user_confidence", 0.5),
            0.0,
            1.0,
        ))

        situation_risk = float(np.clip(
            context_state.get("situation_risk", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Weighting logic
        # -------------------------
        user_weight = float(np.clip(
            user_confidence * (1.0 - situation_risk),
            0.1,
            0.9,
        ))

        director_weight = 1.0 - user_weight

        # -------------------------
        # Style fusion
        # -------------------------
        negotiated: Dict[str, float] = {}
        keys = set(user_style) | set(director_style)

        for k in keys:
            u = user_style.get(k, 0.5)
            d = director_style.get(k, 0.5)
            negotiated[k] = float(
                user_weight * u + director_weight * d
            )

        self._agreement_state = negotiated

        return {
            "negotiated_style": dict(negotiated),
            "weights": {
                "user": user_weight,
                "director": director_weight,
            },
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset negotiation state.
        """
        self._agreement_state.clear()
        self._last_update = time.time()


