# CHUNK 145 A 01 — LONG-TERM DRIFT DETECTION & CORRECTION
# ==============================================================================
#
# Purpose:
#   Detect slow, multi-dimensional drift in directorial behavior
#   over extended operation and correct it gradually — preserving
#   learned style while preventing degeneration or extremization.
#
# Core principle:
#   Drift is not failure — uncorrected drift is.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class LongTermDriftDetectionCorrection:
    """
    Long-term drift detection & correction engine.
    Monitors stylistic, emotional, and risk-related dimensions
    over long horizons, applying gentle corrective forces when
    persistent deviation is detected.
    """

    __slots__ = (
        "_baseline",
        "_drift_state",
        "_last_update",
    )

    def __init__(self):
        self._baseline: Dict[str, float] = {
            "motion_restraint": 0.5,
            "contrast_bias": 0.5,
            "linger_tendency": 0.5,
            "risk_tolerance": 0.5,
        }
        self._drift_state: Dict[str, float] = {
            "motion_restraint": 0.0,
            "contrast_bias": 0.0,
            "linger_tendency": 0.0,
            "risk_tolerance": 0.0,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Drift analysis
    # --------------------------------------------------------------------------

    def update(
        self,
        current_style: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Update drift estimates and apply correction signals.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        corrections: Dict[str, float] = {}

        for k, base in self._baseline.items():
            cur = float(np.clip(current_style.get(k, base), 0.0, 1.0))
            drift = cur - base

            # Low-pass drift accumulation
            alpha = float(np.clip(dt * 0.02, 0.0, 0.05))
            prev = self._drift_state.get(k, 0.0)
            self._drift_state[k] = prev + alpha * (drift - prev)

            # Gentle correction force
            correction = -0.1 * self._drift_state[k]
            corrections[k] = correction

        return {
            "drift_state": dict(self._drift_state),
            "corrections": corrections,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset drift detection.
        """
        self._drift_state = {
            "motion_restraint": 0.0,
            "contrast_bias": 0.0,
            "linger_tendency": 0.0,
            "risk_tolerance": 0.0,
        }
        self._last_update = time.time()


