# CHUNK 146 A 01 — DIRECTOR AUTHORITY ARBITRATION
# ==============================================================================
#
# Purpose:
#   Resolve control authority dynamically between Director AI,
#   human operator, safety systems, and mission governance —
#   without oscillation, deadlock, or narrative collapse.
#
# Core principle:
#   Authority is situational, not hierarchical.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class DirectorAuthorityArbitration:
    """
    Director authority arbitration engine.
    Determines which entity has control over motion, camera,
    and mission intent at any given moment using confidence,
    urgency, and continuity weighting.
    """

    __slots__ = (
        "_authority_state",
        "_last_update",
    )

    def __init__(self):
        self._authority_state: Dict[str, float] = {
            "director": 0.4,
            "human": 0.3,
            "safety": 0.2,
            "mission": 0.1,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Arbitration logic
    # --------------------------------------------------------------------------

    def arbitrate(
        self,
        human_input: Dict[str, Any],
        safety_state: Dict[str, Any],
        mission_state: Dict[str, Any],
        narrative_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Arbitrate control authority.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        human_assertion = float(np.clip(
            human_input.get("assertiveness", 0.0),
            0.0,
            1.0,
        ))

        safety_urgency = float(np.clip(
            safety_state.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        mission_priority = float(np.clip(
            mission_state.get("priority", 0.5),
            0.0,
            1.0,
        ))

        narrative_stability = float(np.clip(
            narrative_state.get("stability", 0.5),
            0.0,
            1.0,
        ))

        # -------------------------
        # Authority signals
        # -------------------------
        signals = {
            "director": narrative_stability * (1.0 - safety_urgency),
            "human": human_assertion,
            "safety": safety_urgency,
            "mission": mission_priority,
        }

        # Normalize
        total = sum(signals.values()) + 1e-6
        for k in signals:
            signals[k] /= total

        # Temporal smoothing
        alpha = float(np.clip(dt * 2.0, 0.0, 1.0))
        for k in self._authority_state:
            prev = self._authority_state[k]
            self._authority_state[k] = prev + alpha * (signals[k] - prev)

        return {
            "authority": dict(self._authority_state),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset authority arbitration.
        """
        self._authority_state = {
            "director": 0.4,
            "human": 0.3,
            "safety": 0.2,
            "mission": 0.1,
        }
        self._last_update = time.time()


