#   that individual shots, adaptations, and overrides remain aligned
#   with the original user intent and evolving mission objectives.
#
# Core principle:
#   A mission is a promise, not a suggestion.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class MissionLevelIntentGovernance:
    """
    Mission-level intent governance engine.
    Maintains a persistent representation of mission intent,
    evaluating local decisions against global objectives and
    issuing corrective guidance when drift emerges.
    """

    __slots__ = (
        "_mission_intent",
        "_consistency_score",
        "_last_update",
    )

    def __init__(self, mission_intent: Dict[str, Any]):
        self._mission_intent = dict(mission_intent)
        self._consistency_score: float = 1.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Governance logic
    # --------------------------------------------------------------------------

    def evaluate(
        self,
        local_decision: Dict[str, Any],
        narrative_state: Dict[str, Any],
        cinematic_quality: float,
    ) -> Dict[str, Any]:
        """
        Evaluate local decision against mission intent.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        intent_priority = float(np.clip(
            self._mission_intent.get("priority", 0.5),
            0.0,
            1.0,
        ))

        narrative_alignment = float(np.clip(
            narrative_state.get("alignment", 0.5),
            0.0,
            1.0,
        ))

        decision_confidence = float(np.clip(
            local_decision.get("confidence", 0.5),
            0.0,
            1.0,
        ))

        # -------------------------
        # Consistency synthesis
        # -------------------------
        raw_consistency = (
            0.40 * narrative_alignment
            + 0.35 * cinematic_quality
            + 0.25 * decision_confidence
        )

        consistency = float(np.clip(raw_consistency, 0.0, 1.0))

        # Temporal smoothing
        alpha = float(np.clip(dt * 1.5, 0.0, 1.0))
        self._consistency_score += alpha * (
            consistency - self._consistency_score
        )

        # -------------------------
        # Guidance generation
        # -------------------------
        guidance: Dict[str, Any] = {}

        if self._consistency_score < 0.6 and intent_priority > 0.6:
            guidance["reinforce_intent"] = True

        if self._consistency_score < 0.4:
            guidance["restrict_deviation"] = True

        return {
            "mission_consistency": self._consistency_score,
            "guidance": guidance,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset mission governance.
        """
        self._consistency_score = 1.0
        self._last_update = time.time()


