# CHUNK 148 A 01 — SAFETY–CINEMATIC PRIORITY RESOLVER
# ==============================================================================
#
# Purpose:
#   Resolve conflicts between safety constraints and cinematic
#   intent using graded priority fusion — preserving emotional
#   continuity while guaranteeing non-negotiable safety margins.
#
# Core principle:
#   Safety bends cinema — never breaks it.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class SafetyCinematicPriorityResolver:
    """
    Safety–cinematic priority resolution engine.
    Blends safety urgency with narrative and cinematic pressure,
    producing constrained directives instead of abrupt overrides.
    """

    __slots__ = (
        "_resolution_state",
        "_last_update",
    )

    def __init__(self):
        self._resolution_state: Dict[str, float] = {
            "safety_weight": 0.5,
            "cinematic_weight": 0.5,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Resolution logic
    # --------------------------------------------------------------------------

    def resolve(
        self,
        safety_state: Dict[str, Any],
        cinematic_pressure: float,
        narrative_criticality: float,
    ) -> Dict[str, Any]:
        """
        Resolve safety vs cinematic priorities.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        safety_urgency = float(np.clip(
            safety_state.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Weight synthesis
        # -------------------------
        raw_safety = safety_urgency ** 1.4
        raw_cinema = (
            cinematic_pressure * (1.0 - safety_urgency)
            + 0.5 * narrative_criticality
        )

        total = raw_safety + raw_cinema + 1e-6

        target_safety_weight = raw_safety / total
        target_cinematic_weight = raw_cinema / total

        # Temporal smoothing
        alpha = float(np.clip(dt * 2.5, 0.0, 1.0))

        self._resolution_state["safety_weight"] += alpha * (
            target_safety_weight - self._resolution_state["safety_weight"]
        )

        self._resolution_state["cinematic_weight"] += alpha * (
            target_cinematic_weight - self._resolution_state["cinematic_weight"]
        )

        # -------------------------
        # Constraint envelope
        # -------------------------
        constraint = float(np.clip(
            1.0 - self._resolution_state["safety_weight"],
            0.0,
            1.0,
        ))

        return {
            "weights": dict(self._resolution_state),
            "cinematic_constraint": constraint,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset priority resolver.
        """
        self._resolution_state = {
            "safety_weight": 0.5,
            "cinematic_weight": 0.5,
        }
        self._last_update = time.time()


