#   Orchestrate a controlled cinematic closure at mission end,
#   ensuring emotional resolution, stylistic tapering, and
#   perceptual calm before system handoff or shutdown.
#
# Core principle:
#   Endings are authored — not triggered.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class FinalActClosureController:
    """
    Final act cinematic closure controller.
    Shapes the emotional, visual, and kinetic decay of a mission
    so that the ending feels intentional, complete, and stable.
    """

    __slots__ = (
        "_closure_progress",
        "_last_update",
    )

    def __init__(self):
        self._closure_progress: float = 0.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Closure logic
    # --------------------------------------------------------------------------

    def step(
        self,
        emotional_momentum: float,
        narrative_state: Dict[str, Any],
        cinematic_pressure: float,
    ) -> Dict[str, Any]:
        """
        Advance final act closure.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        resolution_readiness = float(np.clip(
            narrative_state.get("resolution_readiness", 0.5),
            0.0,
            1.0,
        ))

        # -------------------------
        # Progress synthesis
        # -------------------------
        target_progress = (
            0.50 * resolution_readiness
            + 0.30 * (1.0 - emotional_momentum)
            + 0.20 * (1.0 - cinematic_pressure)
        )

        target_progress = float(np.clip(target_progress, 0.0, 1.0))

        # Smooth progression
        alpha = float(np.clip(dt * 1.2, 0.0, 1.0))
        self._closure_progress += alpha * (
            target_progress - self._closure_progress
        )

        # -------------------------
        # Closure shaping outputs
        # -------------------------
        taper = 1.0 - self._closure_progress

        return {
            "closure_progress": self._closure_progress,
            "motion_taper": taper ** 1.2,
            "contrast_taper": taper ** 0.9,
            "luma_lift": 0.05 * self._closure_progress,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset closure controller.
        """
        self._closure_progress = 0.0
        self._last_update = time.time()


