class MissionOutcomeConsolidation:
    """
    Mission outcome consolidation engine.
    Distills raw telemetry, decisions, and evaluations into a
    compact mission summary suitable for learning, auditing,
    and cross-mission reasoning.
    """

    __slots__ = (
        "_summary",
        "_timestamp",
    )

    def __init__(self):
        self._summary: Dict[str, Any] = {}
        self._timestamp: float = 0.0


    # --------------------------------------------------------------------------
    # Consolidation logic
    # --------------------------------------------------------------------------

    def consolidate(
        self,
        cinematic_quality: float,
        mission_consistency: float,
        safety_record: Dict[str, Any],
        style_memory: Dict[str, float],
        self_critique: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Consolidate mission outcomes.
        """
        now = time.time()

        safety_score = float(np.clip(
            safety_record.get("score", 1.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Outcome synthesis
        # -------------------------
        overall_success = float(np.clip(
            0.35 * cinematic_quality
            + 0.30 * mission_consistency
            + 0.35 * safety_score,
            0.0,
            1.0,
        ))

        self._summary = {
            "overall_success": overall_success,
            "cinematic_quality": cinematic_quality,
            "mission_consistency": mission_consistency,
            "safety_score": safety_score,
            "style_memory": dict(style_memory),
            "self_critique": dict(self_critique),
        }

        self._timestamp = now

        return {
            "mission_summary": dict(self._summary),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset mission outcome summary.
        """
        self._summary.clear()
        self._timestamp = 0.0


