from typing import Dict, Any
import time
import copy


class DirectorStateFreezeArchive:
    """
    Director state freeze & archive engine.
    Captures an immutable snapshot of all director-relevant states,
    preventing post-mission contamination and enabling exact
    restoration or offline inspection.
    """

    __slots__ = (
        "_frozen_state",
        "_timestamp",
    )

    def __init__(self):
        self._frozen_state: Dict[str, Any] = {}
        self._timestamp: float = 0.0


    # --------------------------------------------------------------------------
    # Freeze logic
    # --------------------------------------------------------------------------

    def freeze(
        self,
        director_modules: Dict[str, Any],
        mission_summary: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Freeze director state.
        """
        now = time.time()

        # Deep copy to guarantee immutability
        frozen_modules = {
            name: copy.deepcopy(state)
            for name, state in director_modules.items()
        }

        self._frozen_state = {
            "modules": frozen_modules,
            "mission_summary": copy.deepcopy(mission_summary),
        }

        self._timestamp = now

        return {
            "frozen_state": copy.deepcopy(self._frozen_state),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Clear archived state.
        """
        self._frozen_state.clear()
        self._timestamp = 0.0


