from typing import Dict, Any
import time


class SystemReadinessReinitialization:
    """
    System readiness reinitialization engine.
    Ensures all director subsystems exit a mission cleanly and
    re-enter an operationally sane baseline before accepting
    new objectives or control authority.
    """

    __slots__ = (
        "_ready_state",
        "_last_update",
    )

    def __init__(self):
        self._ready_state: Dict[str, bool] = {
            "emotion": False,
            "style": False,
            "authority": False,
            "learning": False,
            "safety": False,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Reinitialization logic
    # --------------------------------------------------------------------------

    def reinitialize(
        self,
        subsystems: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Reinitialize all subsystems.
        """
        now = time.time()
        self._last_update = now

        for name, subsystem in subsystems.items():
            if hasattr(subsystem, "reset"):
                subsystem.reset()
                self._ready_state[name] = True

        ready = all(self._ready_state.values())

        return {
            "ready": ready,
            "ready_state": dict(self._ready_state),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset readiness flags.
        """
        for k in self._ready_state:
            self._ready_state[k] = False
        self._last_update = time.time()


