# CHUNK 154 A 01 — DIRECTOR CONTINUITY VALIDATION
# ==============================================================================
#
# Purpose:
#   Validate that the Director AI instance resuming operation
#   maintains behavioral, stylistic, and decision-level continuity
#   with the instance that completed the previous mission.
#
# Core principle:
#   Identity is behavior over time, not stored state alone.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class DirectorContinuityValidation:
    """
    Director continuity validation engine.
    Confirms that restored Director state produces decisions,
    preferences, and reactions consistent with the archived
    pre-freeze identity within acceptable tolerance.
    """

    __slots__ = (
        "_continuity_score",
        "_last_update",
    )

    def __init__(self):
        self._continuity_score: float = 1.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Validation logic
    # --------------------------------------------------------------------------

    def validate(
        self,
        archived_state: Dict[str, Any],
        live_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Validate continuity between archived and live Director states.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        archived_style = archived_state.get("style_memory", {})
        live_style = live_state.get("style_memory", {})

        keys = set(archived_style) | set(live_style)
        diffs = []

        for k in keys:
            a = float(archived_style.get(k, 0.5))
            l = float(live_style.get(k, 0.5))
            diffs.append(abs(a - l))

        mean_diff = float(np.mean(diffs)) if diffs else 0.0

        # -------------------------
        # Continuity synthesis
        # -------------------------
        target_score = float(np.clip(
            1.0 - mean_diff * 1.5,
            0.0,
            1.0,
        ))

        # Temporal smoothing
        alpha = float(np.clip(dt * 2.0, 0.0, 1.0))
        self._continuity_score += alpha * (
            target_score - self._continuity_score
        )

        return {
            "continuity_score": self._continuity_score,
            "mean_style_deviation": mean_diff,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset continuity validation.
        """
        self._continuity_score = 1.0
        self._last_update = time.time()


