from typing import Dict, Any
import time
import numpy as np


class CloudLearningIntakeValidator:
    """
    Cloud learning intake validation engine.
    Screens incoming learning payloads for compatibility with
    the Director’s existing style, risk envelope, and behavioral
    identity before acceptance or rejection.
    """

    __slots__ = (
        "_acceptance_score",
        "_last_update",
    )

    def __init__(self):
        self._acceptance_score: float = 1.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Validation logic
    # --------------------------------------------------------------------------

    def validate(
        self,
        incoming_payload: Dict[str, Any],
        current_style: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Validate cloud learning payload.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        incoming_style = incoming_payload.get("style_memory", {})

        # -------------------------
        # Style compatibility
        # -------------------------
        diffs = []
        keys = set(incoming_style) | set(current_style)

        for k in keys:
            i = float(incoming_style.get(k, 0.5))
            c = float(current_style.get(k, 0.5))
            diffs.append(abs(i - c))

        style_mismatch = float(np.mean(diffs)) if diffs else 0.0

        # -------------------------
        # Acceptance synthesis
        # -------------------------
        target_score = float(np.clip(
            1.0 - style_mismatch * 1.8,
            0.0,
            1.0,
        ))

        alpha = float(np.clip(dt * 2.0, 0.0, 1.0))
        self._acceptance_score += alpha * (
            target_score - self._acceptance_score
        )

        accepted = self._acceptance_score > 0.6

        return {
            "accepted": accepted,
            "acceptance_score": self._acceptance_score,
            "style_mismatch": style_mismatch,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset intake validator.
        """
        self._acceptance_score = 1.0
        self._last_update = time.time()


