from typing import Dict, Any
import time
import numpy as np


class MultiPlatformIntelligenceAlignment:
    """
    Multi-platform intelligence alignment engine.
    Ensures that all participating platforms converge on a
    shared understanding of style, intent, authority, and
    safety envelopes without requiring hard centralization.
    """

    __slots__ = (
        "_alignment_score",
        "_last_update",
    )

    def __init__(self):
        self._alignment_score: float = 1.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Alignment logic
    # --------------------------------------------------------------------------

    def align(
        self,
        platform_states: Dict[str, Dict[str, Any]],
    ) -> Dict[str, Any]:
        """
        Align intelligence across platforms.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        style_vectors = []
        authority_vectors = []

        for state in platform_states.values():
            style_vectors.append(state.get("style_memory", {}))
            authority_vectors.append(state.get("authority", {}))

        # -------------------------
        # Style alignment
        # -------------------------
        style_diffs = []

        if style_vectors:
            keys = set().union(*style_vectors)
            for k in keys:
                values = [v.get(k, 0.5) for v in style_vectors]
                style_diffs.append(np.std(values))

        style_divergence = float(np.mean(style_diffs)) if style_diffs else 0.0

        # -------------------------
        # Authority alignment
        # -------------------------
        authority_diffs = []

        if authority_vectors:
            keys = set().union(*authority_vectors)
            for k in keys:
                values = [v.get(k, 0.0) for v in authority_vectors]
                authority_diffs.append(np.std(values))

        authority_divergence = (
            float(np.mean(authority_diffs)) if authority_diffs else 0.0
        )

        # -------------------------
        # Alignment synthesis
        # -------------------------
        target_alignment = float(np.clip(
            1.0 - (0.6 * style_divergence + 0.4 * authority_divergence),
            0.0,
            1.0,
        ))

        alpha = float(np.clip(dt * 1.8, 0.0, 1.0))
        self._alignment_score += alpha * (
            target_alignment - self._alignment_score
        )

        return {
            "alignment_score": self._alignment_score,
            "style_divergence": style_divergence,
            "authority_divergence": authority_divergence,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset alignment state.
        """
        self._alignment_score = 1.0
        self._last_update = time.time()


