from typing import Dict, Any
import time
import numpy as np


class DirectorTrustCalibration:
    """
    Director trust calibration engine.
    Continuously evaluates performance, reliability, and contextual
    relevance to adjust trust weights across all participating
    decision sources.
    """

    __slots__ = (
        "_trust_state",
        "_last_update",
    )

    def __init__(self):
        self._trust_state: Dict[str, float] = {
            "director": 0.5,
            "human": 0.5,
            "cloud": 0.5,
            "safety": 0.8,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Calibration logic
    # --------------------------------------------------------------------------

    def calibrate(
        self,
        performance_metrics: Dict[str, float],
        reliability_metrics: Dict[str, float],
        context_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Calibrate trust weights.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        context_risk = float(np.clip(
            context_state.get("risk", 0.0),
            0.0,
            1.0,
        ))

        # -------------------------
        # Trust signal synthesis
        # -------------------------
        for k in self._trust_state:
            perf = performance_metrics.get(k, 0.5)
            rel = reliability_metrics.get(k, 0.5)

            target = float(np.clip(
                0.6 * perf + 0.4 * rel - 0.3 * context_risk,
                0.0,
                1.0,
            ))

            alpha = float(np.clip(dt * 1.5, 0.0, 1.0))
            self._trust_state[k] += alpha * (
                target - self._trust_state[k]
            )

        return {
            "trust_state": dict(self._trust_state),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset trust calibration.
        """
        self._trust_state = {
            "director": 0.5,
            "human": 0.5,
            "cloud": 0.5,
            "safety": 0.8,
        }
        self._last_update = time.time()


