# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class AdaptiveAuthorityPersistence:
    """
    Adaptive authority persistence engine.
    Applies temporal inertia and confidence hysteresis to authority
    arbitration outputs so control remains stable, predictable,
    and narratively coherent.
    """

    __slots__ = (
        "_persistent_authority",
        "_last_update",
    )

    def __init__(self):
        self._persistent_authority: Dict[str, float] = {
            "director": 0.4,
            "human": 0.3,
            "safety": 0.2,
            "mission": 0.1,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Persistence logic
    # --------------------------------------------------------------------------

    def persist(
        self,
        proposed_authority: Dict[str, float],
        stability_context: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Persist authority distribution over time.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        volatility = float(np.clip(
            stability_context.get("volatility", 0.0),
            0.0,
            1.0,
        ))

        # Inertia increases under volatility
        inertia = float(np.clip(
            1.0 - volatility,
            0.2,
            0.9,
        ))

        for k, target in proposed_authority.items():
            prev = self._persistent_authority.get(k, 0.0)
            self._persistent_authority[k] = float(
                prev * inertia + target * (1.0 - inertia)
            )

        # Normalize
        total = sum(self._persistent_authority.values()) + 1e-6
        for k in self._persistent_authority:
            self._persistent_authority[k] /= total

        return {
            "authority": dict(self._persistent_authority),
            "inertia": inertia,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset authority persistence.
        """
        self._persistent_authority = {
            "director": 0.4,
            "human": 0.3,
            "safety": 0.2,
            "mission": 0.1,
        }
        self._last_update = time.time()


