from typing import Dict, Any
import time
import numpy as np


class CognitiveLoadGovernor:
    """
    Cognitive load governance engine.
    Dynamically adjusts how many decision dimensions, hypotheses,
    and predictive branches the Director may consider based on
    risk, urgency, and narrative criticality.
    """

    __slots__ = (
        "_load_state",
        "_last_update",
    )

    def __init__(self):
        self._load_state: Dict[str, float] = {
            "current_load": 0.0,
            "allowed_load": 1.0,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Load regulation logic
    # --------------------------------------------------------------------------

    def regulate(
        self,
        requested_load: float,
        context_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Regulate cognitive load.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        urgency = float(np.clip(
            context_state.get("urgency", 0.0),
            0.0,
            1.0,
        ))

        risk = float(np.clip(
            context_state.get("risk", 0.0),
            0.0,
            1.0,
        ))

        narrative_weight = float(np.clip(
            context_state.get("narrative_criticality", 0.5),
            0.0,
            1.0,
        ))

        # -------------------------
        # Allowed load synthesis
        # -------------------------
        target_allowed = float(np.clip(
            1.0
            - 0.6 * urgency
            - 0.5 * risk
            + 0.4 * narrative_weight,
            0.2,
            1.0,
        ))

        # Temporal smoothing
        alpha = float(np.clip(dt * 2.0, 0.0, 1.0))
        self._load_state["allowed_load"] += alpha * (
            target_allowed - self._load_state["allowed_load"]
        )

        # Apply cap
        effective_load = min(requested_load, self._load_state["allowed_load"])

        self._load_state["current_load"] = effective_load

        return {
            "allowed_load": self._load_state["allowed_load"],
            "effective_load": effective_load,
            "load_ratio": (
                effective_load / (self._load_state["allowed_load"] + 1e-6)
            ),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset cognitive load governor.
        """
        self._load_state = {
            "current_load": 0.0,
            "allowed_load": 1.0,
        }
        self._last_update = time.time()


