#   and initiate recovery behaviors before decision quality drops.
#
# Core principle:
#   Endurance is managed, not assumed.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class DirectorFatigueSaturationModel:
    """
    Director fatigue & saturation model.
    Tracks accumulated cognitive effort, sustained pressure,
    and recovery windows to maintain stable, high-quality
    decision-making over long missions.
    """

    __slots__ = (
        "_fatigue_level",
        "_saturation_level",
        "_last_update",
    )

    def __init__(self):
        self._fatigue_level: float = 0.0
        self._saturation_level: float = 0.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Fatigue modeling logic
    # --------------------------------------------------------------------------

    def update(
        self,
        cognitive_load: float,
        sustained_pressure: float,
        recovery_opportunity: float,
    ) -> Dict[str, Any]:
        """
        Update fatigue and saturation levels.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # -------------------------
        # Accumulation dynamics
        # -------------------------
        fatigue_increase = (
            0.6 * cognitive_load
            + 0.4 * sustained_pressure
        )

        recovery_effect = float(np.clip(
            recovery_opportunity,
            0.0,
            1.0,
        ))

        # Fatigue integrates slowly
        self._fatigue_level += dt * (
            0.05 * fatigue_increase
            - 0.08 * recovery_effect
        )

        # Saturation responds faster to overload
        overload = max(0.0, cognitive_load - 0.7)
        self._saturation_level += dt * (
            0.15 * overload
            - 0.10 * recovery_effect
        )

        # Clamp
        self._fatigue_level = float(np.clip(self._fatigue_level, 0.0, 1.0))
        self._saturation_level = float(np.clip(self._saturation_level, 0.0, 1.0))

        return {
            "fatigue_level": self._fatigue_level,
            "saturation_level": self._saturation_level,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset fatigue and saturation state.
        """
        self._fatigue_level = 0.0
        self._saturation_level = 0.0
        self._last_update = time.time()


