from typing import Dict, Any
import time
import numpy as np


class EmergencyNarrativeDegradation:
    """
    Emergency narrative degradation engine.
    Selectively suppresses high-cost cinematic behaviors while
    retaining essential emotional signaling and shot intelligibility.
    """

    __slots__ = (
        "_degradation_level",
        "_last_update",
    )

    def __init__(self):
        self._degradation_level: float = 0.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Degradation logic
    # --------------------------------------------------------------------------

    def degrade(
        self,
        emergency_state: Dict[str, Any],
        narrative_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Apply narrative degradation based on emergency severity.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        severity = float(np.clip(
            emergency_state.get("severity", 0.0),
            0.0,
            1.0,
        ))

        # Degradation rises smoothly with severity
        target = float(np.clip(severity ** 0.8, 0.0, 1.0))

        alpha = float(np.clip(dt * 2.5, 0.0, 1.0))
        self._degradation_level += alpha * (
            target - self._degradation_level
        )

        # -------------------------
        # Narrative simplification
        # -------------------------
        degraded = dict(narrative_state)

        # Reduce motion ambition
        degraded["motion_energy"] *= 1.0 - 0.7 * self._degradation_level

        # Reduce stylistic contrast swings
        degraded["contrast"] *= 1.0 - 0.5 * self._degradation_level

        # Preserve emotional signposts
        degraded["emotional_momentum"] *= 1.0 - 0.2 * self._degradation_level

        degraded["degradation_level"] = self._degradation_level

        return degraded


    def reset(self) -> None:
        """
        Reset degradation state.
        """
        self._degradation_level = 0.0
        self._last_update = time.time()


