from typing import Dict, Any
import time
import numpy as np


class CognitiveRecoveryReExpansion:
    """
    Cognitive recovery & re-expansion engine.
    Manages the controlled reintroduction of suppressed reasoning
    dimensions, stylistic degrees of freedom, and narrative
    expressiveness after constrained operation.
    """

    __slots__ = (
        "_recovery_progress",
        "_last_update",
    )

    def __init__(self):
        self._recovery_progress: float = 0.0
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Recovery logic
    # --------------------------------------------------------------------------

    def recover(
        self,
        degradation_level: float,
        fatigue_level: float,
        context_state: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Execute cognitive recovery and re-expansion.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        # Readiness synthesis
        calmness = float(np.clip(
            context_state.get("calmness", 0.5),
            0.0,
            1.0,
        ))

        readiness = float(np.clip(
            calmness
            * (1.0 - degradation_level)
            * (1.0 - fatigue_level),
            0.0,
            1.0,
        ))

        # Recovery progresses slowly unless fully safe
        rate = float(np.clip(
            0.4 * readiness,
            0.02,
            0.25,
        ))

        self._recovery_progress += dt * rate
        self._recovery_progress = float(
            np.clip(self._recovery_progress, 0.0, 1.0)
        )

        return {
            "recovery_progress": self._recovery_progress,
            "readiness": readiness,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset recovery progress.
        """
        self._recovery_progress = 0.0
        self._last_update = time.time()


