from typing import Dict, Any
import time
import numpy as np


class DirectorResilienceEnvelope:
    """
    Director resilience envelope.
    Encapsulates the safe-operating bounds of cognitive load,
    emotional intensity, authority distribution, and narrative
    ambition to prevent catastrophic collapse or identity drift.
    """

    __slots__ = (
        "_envelope_state",
        "_last_update",
    )

    def __init__(self):
        self._envelope_state: Dict[str, float] = {
            "max_cognitive_load": 1.0,
            "max_emotional_momentum": 1.0,
            "max_motion_energy": 1.0,
            "min_safety_authority": 0.2,
        }
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Envelope enforcement logic
    # --------------------------------------------------------------------------

    def enforce(
        self,
        director_state: Dict[str, Any],
        system_health: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Enforce resilience envelope constraints.
        """
        now = time.time()
        dt = max(now - self._last_update, 1e-3)
        self._last_update = now

        health = float(np.clip(
            system_health.get("overall", 1.0),
            0.0,
            1.0,
        ))

        # Envelope tightens as health degrades
        tightening = float(np.clip(1.0 - health, 0.0, 1.0))

        enforced = dict(director_state)

        enforced["cognitive_load"] = min(
            enforced.get("cognitive_load", 0.0),
            self._envelope_state["max_cognitive_load"] * (1.0 - 0.6 * tightening),
        )

        enforced["emotional_momentum"] = min(
            enforced.get("emotional_momentum", 0.0),
            self._envelope_state["max_emotional_momentum"] * (1.0 - 0.4 * tightening),
        )

        enforced["motion_energy"] = min(
            enforced.get("motion_energy", 0.0),
            self._envelope_state["max_motion_energy"] * (1.0 - 0.5 * tightening),
        )

        authority = enforced.get("authority", {})
        if authority:
            authority["safety"] = max(
                authority.get("safety", 0.0),
                self._envelope_state["min_safety_authority"] + 0.3 * tightening,
            )
            enforced["authority"] = authority

        return {
            "enforced_state": enforced,
            "tightening": tightening,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset resilience envelope state.
        """
        self._last_update = time.time()


