from typing import Dict, Any
import time
import copy


class MissionLevelClosureHandoff:
    """
    Mission-level closure & handoff engine.
    Finalizes mission execution by sealing narrative intent,
    authority resolution, and validated system state before
    controlled dissemination to other layers.
    """

    __slots__ = (
        "_sealed_state",
        "_handoff_targets",
        "_last_update",
    )

    def __init__(self):
        self._sealed_state: Dict[str, Any] = {}
        self._handoff_targets = ("cloud", "operator", "archive")
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Closure logic
    # --------------------------------------------------------------------------

    def close(
        self,
        final_director_state: Dict[str, Any],
        mission_outcome: Dict[str, Any],
        health_snapshot: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Close mission and prepare handoff package.
        """
        now = time.time()
        self._last_update = now

        sealed = copy.deepcopy(final_director_state)

        sealed["mission_outcome"] = mission_outcome
        sealed["system_health"] = health_snapshot
        sealed["closed_at"] = now

        # Strip volatile runtime artifacts
        sealed.pop("live_buffers", None)
        sealed.pop("transient_predictions", None)

        self._sealed_state = sealed

        return {
            "sealed_state": copy.deepcopy(self._sealed_state),
            "handoff_targets": self._handoff_targets,
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset closure engine.
        """
        self._sealed_state.clear()
        self._last_update = time.time()


