#   stylistic, and authority continuity before any live decision
#   is allowed to influence the system.
#
# Core principle:
#   Waking up is an identity act, not a load operation.
#
# ==============================================================================

from typing import Dict, Any
import time
import copy
import hashlib
import json


class ColdStartIdentityRehydration:
    """
    Cold-start identity rehydration engine.
    Reconstructs Director state from archived artifacts and
    validates identity integrity before authorizing cognition,
    control, or narrative reasoning.
    """

    __slots__ = (
        "_rehydrated_state",
        "_validated",
        "_last_update",
    )

    def __init__(self):
        self._rehydrated_state: Dict[str, Any] = {}
        self._validated: bool = False
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Rehydration logic
    # --------------------------------------------------------------------------

    def rehydrate(
        self,
        archive_payload: Dict[str, Any],
        expected_identity_signature: str,
    ) -> Dict[str, Any]:
        """
        Rehydrate Director identity from archive.
        """
        now = time.time()
        self._last_update = now

        sealed_state = archive_payload.get("sealed_state", {})
        archived_signature = archive_payload.get("identity_signature", "")

        # -------------------------
        # Identity verification
        # -------------------------
        identity_core = {
            "style_memory": sealed_state.get("style_memory", {}),
            "trust_state": sealed_state.get("trust_state", {}),
            "authority": sealed_state.get("authority", {}),
            "resilience": sealed_state.get("resilience_envelope", {}),
        }

        serialized = json.dumps(
            identity_core,
            sort_keys=True,
            separators=(",", ":"),
        )

        recomputed_signature = hashlib.sha256(
            serialized.encode("utf-8")
        ).hexdigest()

        self._validated = (
            recomputed_signature == archived_signature
            == expected_identity_signature
        )

        if not self._validated:
            return {
                "rehydrated": False,
                "reason": "identity_mismatch",
                "timestamp": now,
            }

        # -------------------------
        # Controlled restore
        # -------------------------
        self._rehydrated_state = copy.deepcopy(sealed_state)

        return {
            "rehydrated": True,
            "state": copy.deepcopy(self._rehydrated_state),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset rehydration state.
        """
        self._rehydrated_state.clear()
        self._validated = False
        self._last_update = time.time()


