# CHUNK 168 A 01 — DISTRIBUTED DIRECTOR CONSENSUS
# ==============================================================================
#
# Purpose:
#   Establish consensus on Director identity, authority distribution,
#   and intent across distributed instances (onboard, cloud, operator)
#   to prevent split-brain behavior and conflicting decisions.
#
# Core principle:
#   One Director, many embodiments.
#
# ==============================================================================

from typing import Dict, Any
import time
import numpy as np


class DistributedDirectorConsensus:
    """
    Distributed Director consensus engine.
    Aggregates identity signatures, authority states, and confidence
    scores from multiple Director embodiments to form a stable,
    majority-consistent operating state.
    """

    __slots__ = (
        "_consensus_state",
        "_last_update",
    )

    def __init__(self):
        self._consensus_state: Dict[str, Any] = {}
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Consensus logic
    # --------------------------------------------------------------------------

    def converge(
        self,
        director_instances: Dict[str, Dict[str, Any]],
    ) -> Dict[str, Any]:
        """
        Converge distributed Director instances into consensus.
        """
        now = time.time()
        self._last_update = now

        identity_votes = {}
        authority_vectors = []

        for inst in director_instances.values():
            sig = inst.get("identity_signature")
            identity_votes[sig] = identity_votes.get(sig, 0) + 1
            authority_vectors.append(inst.get("authority", {}))

        # -------------------------
        # Identity consensus
        # -------------------------
        consensus_identity = max(identity_votes, key=identity_votes.get)

        # -------------------------
        # Authority consensus
        # -------------------------
        authority_consensus: Dict[str, float] = {}
        if authority_vectors:
            keys = set().union(*authority_vectors)
            for k in keys:
                values = [a.get(k, 0.0) for a in authority_vectors]
                authority_consensus[k] = float(np.median(values))

        self._consensus_state = {
            "identity_signature": consensus_identity,
            "authority": authority_consensus,
            "timestamp": now,
        }

        return dict(self._consensus_state)


    def reset(self) -> None:
        """
        Reset consensus state.
        """
        self._consensus_state.clear()
        self._last_update = time.time()


