# CHUNK 169 A 01 — CROSS-MISSION IDENTITY DRIFT MONITOR
# ==============================================================================
#
# Purpose:
#   Detect slow, cumulative identity drift across missions —
#   identifying subtle but dangerous changes in style, trust,
#   authority balance, or narrative behavior before they
#   manifest as visible failures.
#
# Core principle:
#   Drift is a process, not an event.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import numpy as np


class CrossMissionIdentityDriftMonitor:
    """
    Cross-mission identity drift monitoring engine.
    Maintains a rolling history of identity cores and evaluates
    long-term directional change rather than frame-level noise.
    """

    __slots__ = (
        "_history",
        "_last_update",
    )

    def __init__(self, window: int = 5):
        self._history: List[Dict[str, Any]] = []
        self._window = max(3, window)
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Drift monitoring logic
    # --------------------------------------------------------------------------

    def update(
        self,
        identity_core: Dict[str, Any],
    ) -> Dict[str, Any]:
        """
        Update drift monitor with latest identity core.
        """
        now = time.time()
        self._last_update = now

        self._history.append(identity_core)
        if len(self._history) > self._window:
            self._history.pop(0)

        # -------------------------
        # Drift estimation
        # -------------------------
        drift_score = 0.0

        if len(self._history) >= 2:
            diffs = []
            keys = set().union(*self._history)

            for k in keys:
                values = [
                    float(h.get(k, 0.5)) for h in self._history
                ]
                diffs.append(np.std(values))

            drift_score = float(np.mean(diffs)) if diffs else 0.0

        return {
            "drift_score": drift_score,
            "history_depth": len(self._history),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset drift monitor.
        """
        self._history.clear()
        self._last_update = time.time()


