#   over long horizons to ensure internal consistency across
#   time — detecting contradictions that only emerge when
#   reasoning spans missions, contexts, and emotional arcs.
#
# Core principle:
#   Consistency is truth stretched over time.
#
# ==============================================================================

from typing import Dict, Any, List
import time
import numpy as np


class LongHorizonSelfConsistencyAudit:
    """
    Long-horizon self-consistency audit engine.
    Evaluates whether the Director’s decisions and stylistic
    tendencies remain mutually compatible across extended
    operational timelines.
    """

    __slots__ = (
        "_audit_window",
        "_history",
        "_last_update",
    )

    def __init__(self, window: int = 7):
        self._audit_window = max(5, window)
        self._history: List[Dict[str, Any]] = []
        self._last_update: float = time.time()


    # --------------------------------------------------------------------------
    # Audit logic
    # --------------------------------------------------------------------------

    def audit(
        self,
        decision_signature: Dict[str, float],
        style_signature: Dict[str, float],
        authority_signature: Dict[str, float],
    ) -> Dict[str, Any]:
        """
        Perform long-horizon self-consistency audit.
        """
        now = time.time()
        self._last_update = now

        composite = {
            "decision": decision_signature,
            "style": style_signature,
            "authority": authority_signature,
        }

        self._history.append(composite)
        if len(self._history) > self._audit_window:
            self._history.pop(0)

        inconsistency_score = 0.0

        if len(self._history) >= 2:
            axis_scores = []

            for axis in ("decision", "style", "authority"):
                keys = set().union(
                    *[h[axis] for h in self._history]
                )
                axis_diffs = []

                for k in keys:
                    values = [
        float(h[axis].get(k, 0.5))
        for h in self._history
                    ]
                    axis_diffs.append(np.std(values))

                axis_scores.append(
                    float(np.mean(axis_diffs)) if axis_diffs else 0.0
                )

            # Higher variance → lower consistency
            inconsistency_score = float(np.mean(axis_scores))

        return {
            "inconsistency_score": inconsistency_score,
            "audit_depth": len(self._history),
            "timestamp": now,
        }


    def reset(self) -> None:
        """
        Reset self-consistency audit.
        """
        self._history.clear()
        self._last_update = time.time()


